[400201] = {400201, 10002, 2, 2, "0", "0", "Eh?\u{0020}Is\u{0020}this\u{0020}a\u{0020}good\u{0020}idea?\u{0020}I\u{0020}don't\u{0020}know\u{0020}how\u{0020}to\u{0020}handle\u{0020}this\u{0020}kind\u{0020}of\u{0020}situation\u{0020}at\u{0020}all.", "え？本当にいいのか？こういうとき、どうすればいいのか全然わからないんだが。", "欸？這樣真的好嗎，我這種人完全不知道該怎麼處理這種情況欸。", "0", "哎？这样真的好吗，我这种人完全不知道该怎么处理这种情况哎。", "0", "cv_hank_2", "0", "0"},
[400202] = {400202, 10002, 3, 3, "0", "0", "Yo,\u{0020}you're\u{0020}the\u{0020}navigator?\u{0020}Just\u{0020}to\u{0020}be\u{0020}clear,\u{0020}I'm\u{0020}just\u{0020}a\u{0020}mercenary.", "よぉ！あんたがナビゲーターか？言っておくが、私はただの傭兵だ。", "唷，你就是領航嗎？話先說好，我只是個傭兵喔。", "0", "哟，你就是领航吗？话先说好，我只是个佣兵哦。", "0", "cv_hank_1", "0", "0"},
[400203] = {400203, 10002, 4, 4, "0", "idle", "It's\u{0020}not\u{0020}just\u{0020}for\u{0020}my\u{0020}benefit,\u{0020}it's\u{0020}for\u{0020}the\u{0020}benefit\u{0020}of\u{0020}my\u{0020}employer,\u{0020}too.", "私は報酬に応じた仕事をする。自分にとっても雇用主にとっても良いことだと思うんだがな。", "給多少錢辦多少事，不光光是為了我好也是為了雇主好喔。", "0", "给多少钱办多少事，不光光是为了我好也是为了雇主好哦。", "0", "cv_hank_3", "0", "0"},
[400204] = {400204, 10002, 5, 4, "0", "idle", "Kill,\u{0020}Kill,\u{0020}Kill...\u{0020}This\u{0020}is\u{0020}what\u{0020}I've\u{0020}been\u{0020}doing\u{0020}...\u{0020}Long\u{0020}before\u{0020}I\u{0020}became\u{0020}a\u{0020}driver,\u{0020}I\u{0020}was\u{0020}doing\u{0020}similar\u{0020}things.", "殺戮、殺戮、殺戮、殺戮……これが私の仕事だ……ドライバーになる前もずっと似たような事をやっていた。", "殺戮，殺戮，殺戮，殺戮……這就是我一直以來在做的工作……早在成為駕駛員之前，我就在幹類似的事情了。", "0", "杀戮，杀戮，杀戮，杀戮……这就是我一直以来在做的工作……早在成为驾驶员之前，我就在干类似的事情了。", "0", "cv_hank_4", "0", "0"},
[400205] = {400205, 10002, 6, 4, "0", "idle", "Tina\u{0020}is\u{0020}hard\u{0020}to\u{0020}get\u{0020}along\u{0020}with,\u{0020}but\u{0020}to\u{0020}be\u{0020}honest,\u{0020}I\u{0020}prefer\u{0020}someone\u{0020}who\u{0020}means\u{0020}what\u{0020}they\u{0020}say.", "確かにティナは扱いにくいやつだけど、でも正直なところ、口が悪いけど心根が優しいっていう女の子より、彼女みたいな言行一致のやつの方がいい。", "雖然蒂娜是個蠻難相處的傢伙，不過說實話，比起刀子嘴豆腐心的人，我更喜歡像她一樣言行一致的傢伙。", "0", "虽然蒂娜是个蛮难相处的家伙，不过说实话，比起刀子嘴豆腐心的人，我更喜欢像她一样言行一致的家伙。", "0", "cv_hank_28", "0", "0"},
[400206] = {400206, 10002, 7, 5, "1_》_0_0.8", "level1", "The\u{0020}reason\u{0020}for\u{0020}joining\u{0020}AEGIS...\u{0020}Of\u{0020}course\u{0020}it's\u{0020}the\u{0020}fat\u{0020}paycheck.\u{0020}And\u{0020}also\u{0020}those\u{0020}two\u{0020}girls\u{0020}that\u{0020}I\u{0020}care\u{0020}about.\u{0020}I\u{0020}didn't\u{0020}have\u{0020}a\u{0020}good\u{0020}relationship\u{0020}with\u{0020}my\u{0020}sister\u{0020}in\u{0020}the\u{0020}past.", "アイギスに入った理由……うーん……それはもちろん、報酬がいいからに決まってるだろ。まぁ、あの二人の女の子のことが気になるからっていうのもなくはないが……昔、私も姉さんとは仲が悪かったからな。", "加入艾吉斯的理由…嗯……當然是因為雇主給的錢足夠多啊。還有部分原因是因為我很在意那兩個女孩，在過去，我和姐姐的關係也不太好呢。", "0", "加入艾吉斯的理由…嗯……当然是因为雇主给的钱足够多啊。还有部分原因是因为我很在意那两个女孩，在过去，我和姐姐的关系也不太好呢。", "0", "cv_hank_29", "0", "0"},
[400207] = {400207, 10002, 8, 5, "1_》_0_0.8", "level1", "What's\u{0020}going\u{0020}on\u{0020}here?", "ん？どういうことだ？", "欸？這是什麼情況啊？", "0", "哎？这是什么情况啊？", "0", "cv_hank_5", "0", "0"},
[400208] = {400208, 10002, 9, 5, "1_》_100_1.5", "level2", "Well...\u{0020}Weird\u{0020}but,\u{0020}you\u{0020}mean\u{0020}no\u{0020}harm,\u{0020}right?", "うーん……なんかよくわからないけど、悪意はないってことだろ？", "嗯……雖然還有些奇怪，但是你應該是沒有惡意的吧。", "0", "嗯……虽然还有些奇怪，但是你应该是没有恶意的吧。", "0", "cv_hank_6", "0", "0"},
[400209] = {400209, 10002, 10, 5, "1_》_500_2", "level3", "It's\u{0020}rare\u{0020}that\u{0020}someone\u{0020}other\u{0020}than\u{0020}enemy\u{0020}would\u{0020}approach\u{0020}me.\u{0020}You\u{0020}don't\u{0020}hate\u{0020}me,\u{0020}do\u{0020}you?", "珍しい。敵以外に自分から私に近づいてくるやつがいただなんて。ひょっとして、私のこと、嫌じゃないのか？", "還真是少見，除了敵人外，居然還會有主動靠近我的傢伙啊。難道說，你並沒有討厭我嗎？", "0", "还真是少见，除了敌人外，居然还会有主动靠近我的家伙啊。难道说，你并没有讨厌我吗？", "0", "cv_hank_7", "0", "0"},
[400210] = {400210, 10002, 11, 5, "1_》_1000_2.5", "level4", "Although\u{0020}I'm\u{0020}just\u{0020}a\u{0020}mercenary\u{0020}who\u{0020}gets\u{0020}paid\u{0020}to\u{0020}do\u{0020}things,\u{0020}I\u{0020}don't\u{0020}really\u{0020}know\u{0020}how\u{0020}to\u{0020}express\u{0020}my\u{0020}thoughts.\u{0020}But\u{0020}I\u{0020}can't\u{0020}tell\u{0020}you\u{0020}how\u{0020}happy\u{0020}I\u{0020}am\u{0020}to\u{0020}work\u{0020}with\u{0020}you!\u{0020}I'd\u{0020}like\u{0020}to\u{0020}work\u{0020}with\u{0020}you\u{0020}all\u{0020}the\u{0020}time\u{0020}if\u{0020}I\u{0020}could!", "私は報酬に応じた仕事をするだけの傭兵、だから、自分の考えをどうやって伝えればいいのかもよくわからない。でも、なんというか……だから、あれだ――あんたと一緒に仕事をすることができて、本当に嬉しいんだ！出来るなら、あんたとはずっと一緒に仕事をしたい！", "雖然我只是一個拿錢辦事的傭兵，也不是很懂該怎麼表達自己的想法。但是，該怎麼說呢……哈！就是那個啊——能和你一起工作，真的非常開心！如果有機會的話想要一直和你一起工作！", "0", "虽然我只是一个拿钱办事的佣兵，也不是很懂该怎么表达自己的想法。但是，该怎么说呢……哈！就是那个啊——能和你一起工作，真的非常开心！如果有机会的话想要一直和你一起工作！", "0", "cv_hank_8", "0", "0"},
[400211] = {400211, 10002, 12, 6, "0", "0", "Is\u{0020}that\u{0020}all?\u{0020}Ha,\u{0020}just\u{0020}kidding.", "これしかないのか？あはは、冗談だ。", "就只有這點嗎？哈，開玩笑的。", "0", "就只有这点吗？哈，开玩笑的。", "0", "cv_hank_9", "0", "0"},
[400212] = {400212, 10002, 13, 7, "0", "0", "As\u{0020}long\u{0020}as\u{0020}I\u{0020}get\u{0020}paid.\u{0020}Who\u{0020}are\u{0020}we\u{0020}killing\u{0020}today?", "報酬に応じた仕事をするんだ、さて、今日は誰を斬ろうか？", "拿錢辦事～拿錢辦事～今天要去砍誰呢？", "0", "拿钱办事～拿钱办事～今天要去砍谁呢？", "0", "cv_hank_10", "0", "0"},
[400213] = {400213, 10002, 14, 8, "0", "0", "Great\u{0020}deal\u{0020}indeed...\u{0020}just\u{0020}watch,\u{0020}I\u{0020}won't\u{0020}let\u{0020}my\u{0020}employer\u{0020}down!", "へぇー、これはうまい話だ。任せとけ！雇用主をがっかりさせるようなことは絶対しない。", "呼啊——真是一筆好買賣呢～你就好好看著吧，我絕對不會讓雇主失望的！", "0", "呼啊——真是一笔好买卖呢～你就好好看着吧，我绝对不会让雇主失望的！", "0", "cv_hank_11", "0", "0"},
