[400302] = {400302, 10003, 3, 3, "0", "0", "Morimura\u{0020}Kinosuke.\u{0020}It\u{0020}doesn't\u{0020}matter\u{0020}how\u{0020}you\u{0020}address\u{0020}me.\u{0020}Hurry\u{0020}up\u{0020}and\u{0020}assign\u{0020}the\u{0020}task.", "森村鬼之介。好きに呼んでいい。早く指示を。", "森村鬼之介，稱呼的話怎麼樣都好，趕快佈置任務吧。", "0", "森村鬼之介，称呼的话怎么样都好，赶快布置任务吧。", "0", "cv_morimura_1", "0", "0"},
[400303] = {400303, 10003, 4, 4, "0", "idle", "Just\u{0020}standing\u{0020}here\u{0020}won't\u{0020}solve\u{0020}anything.\u{0020}Move\u{0020}around\u{0020}a\u{0020}little\u{0020}bit,\u{0020}Navigator.", "ここに突っ立ってるだけじゃ何の解決にもならない。少し体を動かそう、ナビゲーター。", "只是站在這裡可解決不了任何問題。稍微活動下吧，領航。", "0", "只是站在这里可解决不了任何问题。稍微活动下吧，领航。", "0", "cv_morimura_3", "0", "0"},
[400304] = {400304, 10003, 5, 4, "0", "idle", "No\u{0020}matter\u{0020}who\u{0020}the\u{0020}enemy\u{0020}is,\u{0020}I\u{0020}won't\u{0020}let\u{0020}them\u{0020}hurt\u{0020}you.", "敵が誰であろうと、あなたを傷つけさせない。", "無論敵人是誰，我都不會讓他們傷害到你的。", "0", "无论敌人是谁，我都不会让他们伤害到你的。", "0", "cv_morimura_4", "0", "0"},
[400305] = {400305, 10003, 6, 4, "0", "idle", "Kuriyama\u{0020}Seiran,\u{0020}Shiranui...\u{0020}And\u{0020}that\u{0020}captain,\u{0020}why\u{0020}do\u{0020}they\u{0020}always\u{0020}come\u{0020}over?\u{0020}One\u{0020}by\u{0020}one,\u{0020}they\u{0020}are\u{0020}all\u{0020}troublesome\u{0020}guys.", "栗山青鸞、不知火……あとあの隊長、何故ちょこちょここっちにやってくる？どいつもこいつも面倒くさいやつばっかり。", "栗山青鸞、不知火……還有那個隊長，為什麼總是湊過來。一個兩個，都是些麻煩的傢伙。", "0", "栗山青鸾、不知火……还有那个队长，为什么总是凑过来。一个两个，都是些麻烦的家伙。", "0", "cv_morimura_29", "0", "0"},
[400306] = {400306, 10003, 7, 5, "1_》_0_0.8", "level1", "Since\u{0020}that\u{0020}day,\u{0020}there\u{0020}has\u{0020}only\u{0020}been\u{0020}revenge\u{0020}in\u{0020}my\u{0020}heart.\u{0020}I\u{0020}will\u{0020}completely\u{0020}destroy\u{0020}the\u{0020}Sin\u{0020}no\u{0020}matter\u{0020}what...\u{0020}Even\u{0020}if\u{0020}I\u{0020}turn\u{0020}myself\u{0020}into\u{0020}an\u{0020}Asura...", "……あの日以来、僕の心の中にあるのは復讐だけ。何が何でも、原罪を完全に滅ぼしてやる……たとえ自分が修羅になったとしても……", "……從那一天開始，我的心裡就只剩下了復仇。無論如何，我都要把原罪徹底毀滅……哪怕另己身化為修羅也……", "0", "……从那一天开始，我的心里就只剩下了复仇。无论如何，我都要把原罪彻底毁灭……哪怕另己身化为修罗也……", "0", "cv_morimura_30", "0", "0"},
[400307] = {400307, 10003, 8, 5, "1_》_0_0.8", "level1", "You\u{0020}should\u{0020}have\u{0020}heard\u{0020}the\u{0020}words.\u{0020}I\u{0020}was\u{0020}just\u{0020}got\u{0020}transferred\u{0020}here.", "あなたも聞いただろう。僕は臨時異動でここに来たんだ。", "你應該也聽說了吧，我是被臨時調過來的。", "0", "你应该也听说了吧，我是被临时调过来的。", "0", "cv_morimura_5", "0", "0"},
[400308] = {400308, 10003, 9, 5, "1_》_100_1.5", "level2", "The\u{0020}faces\u{0020}of\u{0020}my\u{0020}past\u{0020}companions\u{0020}that\u{0020}I\u{0020}still\u{0020}can't\u{0020}forget\u{0020}till\u{0020}now...\u{0020}This\u{0020}regret,\u{0020}this\u{0020}longing\u{0020}is\u{0020}probably\u{0020}never-ending.", "昔の仲間たちの顔、今も忘れられない……この悔い、そしてこの思いは永遠に果てないのだろう。", "至今都無法忘記的，過去夥伴們的容顏……這份悔意，這份思念估計永遠不會有盡頭。", "0", "至今都无法忘记的，过去伙伴们的容颜……这份悔意，这份思念估计永远不会有尽头。", "0", "cv_morimura_6", "0", "0"},
[400309] = {400309, 10003, 10, 5, "1_》_500_2", "level3", "Navigator,\u{0020}I\u{0020}recently\u{0020}found\u{0020}that\u{0020}every\u{0020}time\u{0020}I'm\u{0020}alone\u{0020}with\u{0020}you.\u{0020}My\u{0020}heart\u{0020}becomes\u{0020}calm...\u{0020}Is\u{0020}this\u{0020}a\u{0020}good\u{0020}thing?\u{0020}Or\u{0020}a\u{0020}bad\u{0020}thing?", "ナビゲーター、最近、あなたと二人きりになると……何だか落ち着くようになる……これは良い事？それとも悪い事？", "領航，我最近發現每次和你獨處的時候。內心就會變得平靜下來……這到底是好事呢？還是壞事？", "0", "领航，我最近发现每次和你独处的时候。内心就会变得平静下来……这到底是好事呢？还是坏事？", "0", "cv_morimura_7", "0", "0"},
[400310] = {400310, 10003, 11, 5, "1_》_1000_2.5", "level4", "Even\u{0020}if\u{0020}the\u{0020}revenge\u{0020}is\u{0020}over,\u{0020}the\u{0020}torture\u{0020}in\u{0020}my\u{0020}heart\u{0020}won't\u{0020}ease...\u{0020}But\u{0020}as\u{0020}long\u{0020}as\u{0020}you\u{0020}are\u{0020}still\u{0020}by\u{0020}my\u{0020}side...\u{0020}Nightmares\u{0020}or\u{0020}physical\u{0020}pain,\u{0020}I\u{0020}can\u{0020}bear\u{0020}them\u{0020}all.", "たとえ復讐が終わったとしても、心の苦しみは消えない……でも、あなたがそばにいてくれれば……悪い夢も、身体的苦痛も、僕は全部耐えられる。", "哪怕復仇已經結束，內心的折磨也不會停息……但是如果只要你還在我身邊的話……噩夢也好，身體上的痛楚也罷，我都能承受下來。", "0", "哪怕复仇已经结束，内心的折磨也不会停息……但是如果只要你还在我身边的话……噩梦也好，身体上的痛楚也罢，我都能承受下来。", "0", "cv_morimura_8", "0", "0"},
[400311] = {400311, 10003, 12, 6, "0", "0", "Understood.\u{0020}I\u{0020}won't\u{0020}let\u{0020}you\u{0020}down.", "確かに受け取った。絶対にあなたを失望させない。", "收到了，不會讓你失望的。", "0", "收到了，不会让你失望的。", "0", "cv_morimura_9", "0", "0"},
[400312] = {400312, 10003, 13, 7, "0", "0", "Enhance\u{0020}the\u{0020}combat\u{0020}effectiveness\u{0020}is\u{0020}indeed\u{0020}essential.", "戦力を上げる必要があるからな。", "提升戰力，確實有這個必要。", "0", "提升战力，确实有这个必要。", "0", "cv_morimura_10", "0", "0"},
[400313] = {400313, 10003, 14, 8, "0", "0", "Although\u{0020}I'm\u{0020}not\u{0020}quite\u{0020}clear\u{0020}about\u{0020}your\u{0020}plan\u{0020}yet,\u{0020}I\u{0020}will\u{0020}repay\u{0020}you\u{0020}in\u{0020}my\u{0020}way.\u{0020}I\u{0020}will,\u{0020}turn\u{0020}into\u{0020}a\u{0020}fiend\u{0020}on\u{0020}the\u{0020}battlefield...", "あなたが何を考えてるのかは分からないが、僕は僕らしく応える。僕は、戦場の悪鬼になって……", "雖然還不太清楚你的打算，但是我會用我的方式來回報你的。我會，化作戰場的惡鬼……", "0", "虽然还不太清楚你的打算，但是我会用我的方式来回报你的。我会，化作战场的恶鬼……", "0", "cv_morimura_11", "0", "0"},
[400314] = {400314, 10003, 15, 9, "0", "0", "Yes,\u{0020}that's\u{0020}it.\u{0020}Grinding\u{0020}skills\u{0020}is\u{0020}also\u{0020}indispensable.", "そう、これだ。スキルを鍛えることも必要不可欠だ。", "沒錯，就是這樣，鍛煉技藝也是必不可少的。", "0", "没错，就是这样，锻炼技艺也是必不可少的。", "0", "cv_morimura_12", "0", "0"},
[400315] = {400315, 10003, 16, 10, "0", "0", "Don't\u{0020}group\u{0020}me\u{0020}with\u{0020}them.", "彼女たちと一緒にしないでくれ。", "不要把我和她們歸為一類。", "0", "不要把我和她们归为一类。", "0", "cv_morimura_13", "0", "0"},
[400316] = {400316, 10003, 17, 11, "0", "0", "It's\u{0020}been\u{0020}a\u{0020}long\u{0020}time...\u{0020}The\u{0020}urge\u{0020}to\u{0020}continue\u{0020}fighting\u{0020}side\u{0020}by\u{0020}side\u{0020}with\u{0020}others.", "久しぶりに湧いてきたんだ……他の人と一緒に戦いたい気持ちが。", "久違了……想要和他人繼續並肩作戰的衝動。", "0", "久违了……想要和他人继续并肩作战的冲动。", "0", "cv_morimura_14", "0", "0"},
[400317] = {400317, 10003, 18, 12, "0", "0", "Solved.\u{0020}I'm\u{0020}going\u{0020}back.", "解決した。帰る。", "解決了，我要回去了。", "0", "解决了，我要回去了。", "0", "cv_morimura_15", "0", "0"},
