[400401] = {400401, 10004, 2, 2, "0", "0", "Mission\u{0020}confirmed\u{0020}-\u{0020}mission\u{0020}objective\u{0020}-\u{0020}unknown...\u{0020}In\u{0020}any\u{0020}case,\u{0020}I\u{0020}will\u{0020}do\u{0020}my\u{0020}best.", "ミッション確認――ミッション目的――不明……でも、やって、みます。", "任務確認——任務目的——不明……但是，我會嘗試一下的。", "0", "0", "0", "cv_dtypeb2_2", "0", "0"},
[400402] = {400402, 10004, 3, 3, "0", "0", "Access\u{0020}confirmed\u{0020}-\u{0020}authentication\u{0020}starting\u{0020}in\u{0020}3\u{0020}-2\u{0020}-\u{0020}1...\u{0020}Access\u{0020}granted.\u{0020}D-b2\u{0020}is\u{0020}now\u{0020}ready\u{0020}for\u{0020}use.", "接続確認――認証開始――3――2――1――……接続完了――では、D型b-2をどうぞ、ご自由にお使いください。", "接入確認——認證開始——3——2——1……接入完成——接下來請隨意使用D型b2。", "0", "0", "0", "cv_dtypeb2_1", "0", "0"},
[400403] = {400403, 10004, 4, 4, "0", "idle", "Standby\u{0020}mode\u{0020}active\u{0020}-\u{0020}please\u{0020}press\u{0020}Start\u{0020}to\u{0020}use.", "待機中――ご利用の場合は、アクティベートキーを押してください――。", "待機中——如需使用請按下啟動鍵——", "0", "0", "0", "cv_dtypeb2_3", "0", "0"},
[400404] = {400404, 10004, 5, 4, "0", "idle", "Rebooting\u{0020}-\u{0020}please\u{0020}wait.\u{0020}Navigator,\u{0020}it's\u{0020}been\u{0020}a\u{0020}while.\u{0020}While\u{0020}powered\u{0020}down\u{0020}this\u{0020}time,\u{0020}I\u{0020}think\u{0020}I've\u{0020}started\u{0020}learning\u{0020}to\u{0020}dream...\u{0020}I\u{0020}dreamed\u{0020}of\u{0020}that\u{0020}child.", "再起動しています――しばらくお待ちください――……ナビゲーター、お久しぶりです。スリープ中に、夢を見ることができるようになったみたいです……夢の中で、あの子を見ました。", "正在重啟——還請稍等片刻——……領航，好久不見。在休眠的這段時間裏，我好像學會了做夢……我夢到了，那個孩子。", "0", "0", "0", "cv_dtypeb2_4", "0", "0"},
[400405] = {400405, 10004, 6, 4, "0", "idle", "Search\u{0020}mode\u{0020}activated\u{0020}-\u{0020}Sorry,\u{0020}but\u{0020}no\u{0020}other\u{0020}machines\u{0020}of\u{0020}that\u{0020}model\u{0020}were\u{0020}found.", "検索モード起動――すみません、他の同一型番の機体が見つかりませんでした。", "檢索模式啟動——抱歉，並沒有發現其他同型號的機體。", "0", "0", "0", "cv_dtypeb2_30", "0", "0"},
[400406] = {400406, 10004, 7, 5, "1_》_0_0.8", "level1", "I\u{0020}can't\u{0020}understand\u{0020}it:\u{0020}we\u{0020}exist\u{0020}solely\u{0020}in\u{0020}order\u{0020}to\u{0020}protect\u{0020}humanity,\u{0020}nothing\u{0020}more.\u{0020}I\u{0020}do,\u{0020}anyway.\u{0020}However,\u{0020}I\u{0020}also\u{0020}wish\u{0020}to\u{0020}see\u{0020}that\u{0020}person\u{0020}once\u{0020}more...", "理解できません――私たちの存在意義は人間を守ることです。少なくとも、私はそう認識しています。でも、もし可能ならまたあの人に会いたいと思います……", "無法理解——我們存在的意義只是為了保護人類而已，至少對我而言是這樣的。但是，總覺得又很想再見到那個人……", "0", "0", "0", "cv_dtypeb2_31", "0", "0"},
[400407] = {400407, 10004, 8, 5, "1_》_0_0.8", "level1", "Boot\u{0020}confirmation\u{0020}-\u{0020}authentication\u{0020}start\u{0020}-\u{0020}boot\u{0020}complete.", "アクティベート確認――認証開始――……アクティベート完了。", "啟動確認——認證開始——……啟動完畢。", "0", "0", "0", "cv_dtypeb2_5", "0", "0"},
[400408] = {400408, 10004, 9, 5, "1_》_100_1.5", "level2", "Boot\u{0020}confirmation\u{0020}-\u{0020}authentication\u{0020}start\u{0020}-\u{0020}boot\u{0020}complete.\u{0020}Initiate\u{0020}access\u{0020}mode?", "アクティベート確認――認証開始――……アクティベート完了――接続プログラムを実行しますか？", "啟動確認——認證開始——……啟動完畢——請問是否要執行接入程式？", "0", "0", "0", "cv_dtypeb2_6", "0", "0"},
[400409] = {400409, 10004, 10, 5, "1_》_500_2", "level3", "Boot\u{0020}complete\u{0020}-\u{0020}No\u{0020}matter\u{0020}how\u{0020}I\u{0020}consider\u{0020}it,\u{0020}I\u{0020}can't\u{0020}understand\u{0020}human\u{0020}emotions.\u{0020}So\u{0020}please,\u{0020}don't\u{0020}waste\u{0020}your\u{0020}time\u{0020}on\u{0020}me.", "アクティベート完了――私にとって、あなたたち人間の感情はどうしても理解できないものです。ですから、無駄なことをなさらないでください。", "啟動完畢——無論再怎麼樣，我都沒法理解你們人類的情感。所以，還請不要再努力了。", "0", "0", "0", "cv_dtypeb2_7", "0", "0"},
[400410] = {400410, 10004, 11, 5, "1_》_1000_2.5", "level4", "While\u{0020}I\u{0020}can't\u{0020}understand\u{0020}your\u{0020}emotions,\u{0020}I\u{0020}will\u{0020}be\u{0020}sure\u{0020}to\u{0020}log\u{0020}them\u{0020}in\u{0020}my\u{0020}memory\u{0020}banks,\u{0020}and\u{0020}retain\u{0020}them\u{0020}until\u{0020}I'm\u{0020}able\u{0020}to\u{0020}decipher\u{0020}them\u{0020}properly.\u{0020}Of\u{0020}that\u{0020}you\u{0020}can\u{0020}be\u{0020}sure.", "あなたたちの感情を理解することはできませんが、メモリーモジュールであなたの行為を記録することができます。自分で解読できるようになるまで保存しますので、ご安心ください。", "雖然沒法理解你們的情感，但是我會動用記憶模組將你的行為記錄下來。我會將它們留到自己可以解讀出來為止，所以，還請放心吧。", "0", "0", "0", "cv_dtypeb2_8", "0", "0"},
