[400501] = {400501, 10005, 2, 2, "0", "0", "Care\u{0020}so\u{0020}much\u{0020}about\u{0020}me.\u{0020}Could\u{0020}it\u{0020}be\u{0020}that...", "ボクのことがそんなに気になるの？もしかして……", "這麼在意小生，難道說……", "0", "这么在意小生，难道说……", "0", "cv_karenn_2", "0", "0"},
[400502] = {400502, 10005, 3, 3, "0", "0", "My\u{0020}name\u{0020}is\u{0020}Hualian.\u{0020}If\u{0020}you\u{0020}can\u{0020}take\u{0020}this\u{0020}kick\u{0020}of\u{0020}mine,\u{0020}I\u{0020}will\u{0020}follow\u{0020}you.", "ボクの名は華恋。もしボクの蹴りを受け流すことができたなら、結婚してあげるよ！", "小生名為華戀，如果能接下小生這一腳的話小生就跟定你了喔。", "0", "小生名为华恋，如果能接下小生这一脚的话小生就跟定你了哦。", "0", "cv_karenn_1", "0", "0"},
[400503] = {400503, 10005, 4, 4, "0", "idle", "Aren't\u{0020}you\u{0020}a\u{0020}little\u{0020}tired?\u{0020}Just\u{0020}go\u{0020}and\u{0020}rest.\u{0020}It's\u{0020}fine\u{0020}with\u{0020}me\u{0020}here.", "あのね……もしかして、疲れてきた？だったら早く休んで！ここはボクに任せて。", "我說……你是不是已經有點累了啊？如果累了的話就趕快去休息吧，這裡有小生在就好。", "0", "我说……你是不是已经有点累了啊？如果累了的话就赶快去休息吧，这里有小生在就好。", "0", "cv_karenn_3", "0", "0"},
[400504] = {400504, 10005, 5, 4, "0", "idle", "Winning\u{0020}or\u{0020}losing\u{0020}is\u{0020}not\u{0020}important.\u{0020}What's\u{0020}important\u{0020}is\u{0020}the\u{0020}psychological\u{0020}communication\u{0020}during\u{0020}the\u{0020}fight.\u{0020}As\u{0020}the\u{0020}saying\u{0020}goes,\u{0020}friends\u{0020}are\u{0020}made\u{0020}after\u{0020}a\u{0020}fight.\u{0020}Only\u{0020}by\u{0020}having\u{0020}a\u{0020}good\u{0020}fight\u{0020}can\u{0020}you\u{0020}truly\u{0020}understand\u{0020}a\u{0020}person.", "手合わせする時は、勝敗なんかより、心の交流の方が大事だよ。「けんかをしなければ友達になれない」って言うでしょ？人を理解するにはちゃんとした手合わせが必要だってこと。", "輸贏並不是關鍵，重要的是在交手時的心理交流。正所謂不打不相識，只有好好打上一架才能真正瞭解一個人啊。", "0", "输赢并不是关键，重要的是在交手时的心理交流。正所谓不打不相识，只有好好打上一架才能真正了解一个人啊。", "0", "cv_karenn_4", "0", "0"},
[400505] = {400505, 10005, 6, 4, "0", "idle", "Huameng?\u{0020}Ah,\u{0020}she\u{0020}is\u{0020}my\u{0020}elder\u{0020}sister\u{0020}and\u{0020}also\u{0020}my\u{0020}opponent.\u{0020}We\u{0020}have\u{0020}been\u{0020}practicing\u{0020}together\u{0020}since\u{0020}we\u{0020}were\u{0020}very\u{0020}young.", "華夢？ああ、あれはボクの姉で、好敵手だよ。小さい頃からずっと一緒に修行してるし。", "華夢？啊，她是小生的姐姐，也是小生的對手。從很小的時候我們就在一起修行了。", "0", "华梦？啊，她是小生的姐姐，也是小生的对手。从很小的时候我们就在一起修行了。", "0", "cv_karenn_30", "0", "0"},
[400506] = {400506, 10005, 7, 5, "1_》_0_0.8", "level1", "I\u{0020}myself\u{0020}don't\u{0020}have\u{0020}much\u{0020}ambition.\u{0020}Joining\u{0020}AEGIS\u{0020}is\u{0020}just\u{0020}because\u{0020}I\u{0020}think\u{0020}there\u{0020}must\u{0020}be\u{0020}someone\u{0020}strong\u{0020}that\u{0020}I\u{0020}like\u{0020}here.", "ボクには個人的な志なんかない。アイギスに入ったのも、ボクの気に入る強者がいそうだと思ったから。ただそれだけ。", "小生自己倒是沒什麼志向，加入艾吉斯也只是單純覺得這裡一定會有小生中意的強者罷了。", "0", "小生自己倒是没什么志向，加入艾吉斯也只是单纯觉得这里一定会有小生中意的强者罢了。", "0", "cv_karenn_31", "0", "0"},
[400507] = {400507, 10005, 8, 5, "1_》_0_0.8", "level1", "Do\u{0020}you\u{0020}want\u{0020}to\u{0020}have\u{0020}a\u{0020}fight?\u{0020}I'm\u{0020}ready.", "手合わせをやる？ボクはもう、準備出来てるよ。", "要來打上一架嗎？小生已經準備好了喔。", "0", "要来打上一架吗？小生已经准备好了哦。", "0", "cv_karenn_5", "0", "0"},
[400508] = {400508, 10005, 9, 5, "1_》_100_1.5", "level2", "Oh,\u{0020}nice\u{0020}strike.\u{0020}It\u{0020}seems\u{0020}that\u{0020}your\u{0020}body\u{0020}flows\u{0020}the\u{0020}blood\u{0020}of\u{0020}Danube,\u{0020}too.", "おお、なかなか良い攻撃だったね。あんたの体にも九州の血が流れてるようだ。", "喔喔，不錯的一擊嘛，看來你的體內也流淌著多瑙的血啊。", "0", "噢噢，不错的一击嘛，看来你的体内也流淌着九州的血啊。", "0", "cv_karenn_6", "0", "0"},
[400509] = {400509, 10005, 10, 5, "1_》_500_2", "level3", "It's\u{0020}not\u{0020}like\u{0020}this.\u{0020}Such\u{0020}a\u{0020}kick\u{0020}like\u{0020}yours\u{0020}can't\u{0020}convey\u{0020}the\u{0020}emotion\u{0020}to\u{0020}me.\u{0020}Watch\u{0020}carefully.\u{0020}I'll\u{0020}show\u{0020}you\u{0020}again.", "そうじゃなくて……！そんな足蹴りじゃ気持ちをボクに伝えることはできないよ。いい？ボクがもう一回手本をやって見せてあげる。", "不是這樣的啦，像你這樣的踢腿是沒法將情感傳遞給小生的啦。看好了喔，小生再給你演示一遍。", "0", "不是这样的啦，像你这样的踢腿是没法将情感传递给小生的啦。看好了哦，小生再给你演示一遍。", "0", "cv_karenn_7", "0", "0"},
[400510] = {400510, 10005, 11, 5, "1_》_1000_2.5", "level4", "Why...\u{0020}Why\u{0020}can't\u{0020}I\u{0020}use\u{0020}all\u{0020}my\u{0020}strength?\u{0020}As\u{0020}long\u{0020}as\u{0020}my\u{0020}eyes\u{0020}meet\u{0020}yours,\u{0020}all\u{0020}my\u{0020}strength\u{0020}will\u{0020}slip\u{0020}away...\u{0020}That\u{0020}way,\u{0020}I\u{0020}can't\u{0020}convey\u{0020}my\u{0020}mood\u{0020}to\u{0020}you\u{0020}properly.", "なんで……なんで全力を出せないんだろ？あんたと目が合うと、全身の力が抜けちゃうっていうか……こんなんじゃ今の気持ちをちゃんとあんたに伝えられないじゃないか！", "為什麼……為什麼無法使出全力呢？只要與你對視的話，小生全身的力氣都會溜走……這樣的話可沒法將現在的心情好好傳遞給你啊。", "0", "为什么……为什么无法使出全力呢？只要与你对视的话，小生全身的力气都会溜走……这样的话可没法将现在的心情好好传递给你啊。", "0", "cv_karenn_8", "0", "0"},
[400511] = {400511, 10005, 12, 6, "0", "0", "Huhuhu,\u{0020}the\u{0020}calf\u{0020}size\u{0020}has\u{0020}increased~", "ふふ、ふくらはぎの筋肉が増えた！", "呼呼呼，小腿上的肌肉增加了喔~", "0", "呼呼呼，小腿上的肌肉增加了哦~", "0", "cv_karenn_9", "0", "0"},
[400512] = {400512, 10005, 13, 7, "0", "0", "Oh,\u{0020}after\u{0020}receiving\u{0020}your\u{0020}gift,\u{0020}I\u{0020}seem\u{0020}to\u{0020}have\u{0020}become\u{0020}stronger!", "おっ！あんたからのプレゼントをもらったお陰でまた強くなったみたい！", "喔，小生在收下你的禮物後好像又變強了欸！", "0", "哦，小生在收下你的礼物后好像又变强了哎！", "0", "cv_karenn_10", "0", "0"},
[400513] = {400513, 10005, 14, 8, "0", "0", "Full\u{0020}on!\u{0020}Navigator,\u{0020}please\u{0020}be\u{0020}sure\u{0020}to\u{0020}receive\u{0020}this\u{0020}strike\u{0020}that\u{0020}infuses\u{0020}all\u{0020}my\u{0020}emotions!", "完全形態！ナビゲーター、このボクの気持ちが込められた一撃を是非受け取めて！", "完全形態！領航，還請務必要收下這注入了小生所有情感的一擊！", "0", "完全形态！领航，还请务必要收下这注入了小生所有情感的一击！", "0", "cv_karenn_11", "0", "0"},
[400514] = {400514, 10005, 15, 9, "0", "0", "The\u{0020}battle\u{0020}has\u{0020}become\u{0020}easy!", "戦闘が上達したね！", "戰鬥變得得心應手了！", "0", "战斗变得得心应手了！", "0", "cv_karenn_12", "0", "0"},
[400515] = {400515, 10005, 16, 10, "0", "0", "I\u{0020}have\u{0020}no\u{0020}intention\u{0020}of\u{0020}making\u{0020}friends\u{0020}with\u{0020}the\u{0020}Sin.", "原罪なんかと友達になるつもりはないから。", "我可沒打算和原罪交朋友啊。", "0", "我可没打算和原罪交朋友啊。", "0", "cv_karenn_13", "0", "0"},
[400516] = {400516, 10005, 17, 11, "0", "0", "In\u{0020}this\u{0020}world,\u{0020}there\u{0020}is\u{0020}no\u{0020}one\u{0020}that\u{0020}can't\u{0020}be\u{0020}defeated\u{0020}by\u{0020}martial\u{0020}arts!", "武術で倒せない奴なんてこの世界には存在しない！", "這個世界上沒有什麼傢伙是用武術打不倒的！", "0", "这个世界上没有什么家伙是用武术打不倒的！", "0", "cv_karenn_14", "0", "0"},
[400517] = {400517, 10005, 18, 12, "0", "0", "It's\u{0020}a\u{0020}bit\u{0020}strenuous.\u{0020}I'll\u{0020}exercise\u{0020}more\u{0020}after\u{0020}going\u{0020}back.", "ギリだったね。帰ってもっと鍛錬した方がいい。", "稍微有點吃力啊，回去之後再鍛煉下好了。", "0", "稍微有点吃力啊，回去之后再锻炼下好了。", "0", "cv_karenn_15", "0", "0"},
[400518] = {400518, 10005, 19, 13, "0", "0", "Sure\u{0020}enough...\u{0020}They\u{0020}are\u{0020}just\u{0020}monsters\u{0020}without\u{0020}hearts.", "やっぱり……あいつらは心のないモンスターに過ぎない。", "果然……他們只是沒有心的怪物。", "0", "果然……他们只是没有心的怪物。", "0", "cv_karenn_16", "0", "0"},
[400519] = {400519, 10005, 20, 14, "0", "0", "There\u{0020}is\u{0020}a\u{0020}realm\u{0020}that\u{0020}martial\u{0020}arts\u{0020}can't\u{0020}reach...", "武術で到達できない領域もあったんだ……", "原來還有武術達不到的境界……", "0", "原来还有武术达不到的境界……", "0", "cv_karenn_17", "0", "0"},
[400520] = {400520, 10005, 21, 15, "0", "0", "Still\u{0020}not\u{0020}good\u{0020}enough.", "ちょっと足りないかも。", "還差點意思啊。", "0", "还差点意思啊。", "0", "cv_karenn_18", "0", "0"},
[400521] = {400521, 10005, 23, 16, "0", "0", "I'm\u{0020}coming!", "華恋、参る！", "小生來了喔！", "0", "小生来了哦！", "0", "cv_karenn_19", "0", "0"},
[400522] = {400522, 10005, 24, 17, "0", "0", "Come\u{0020}on,\u{0020}attack\u{0020}me.", "さぁ、かかってこい！", "來吧，朝小生攻擊吧。", "0", "来吧，朝小生攻击吧。", "0", "cv_karenn_21", "0", "0"},
[400523] = {400523, 10005, 26, 19, "0", "0", "My\u{0020}determination...\u{0020}Is\u{0020}still\u{0020}far\u{0020}from\u{0020}enough...", "ボクの定力……まだまだだったね……", "小生的定力……還遠遠不夠……", "0", "小生的定力……还远远不够……", "0", "cv_karenn_20", "0", "0"},
[400524] = {400524, 10005, 27, 20, "0", "0", "Taking\u{0020}a\u{0020}bath,\u{0020}is\u{0020}it\u{0020}a\u{0020}battle\u{0020}with\u{0020}water?\u{0020}I\u{0020}understand.", "お風呂？つまり水との戦い？分かった。", "洗澡，也就是與水的戰鬥嗎？小生瞭解了。", "0", "洗澡，也就是与水的战斗吗？小生清楚了。", "0", "cv_karenn_23", "0", "0"},
[400525] = {400525, 10005, 28, 21, "0", "0", "If\u{0020}it's\u{0020}water,\u{0020}it\u{0020}should\u{0020}be\u{0020}able\u{0020}to\u{0020}take\u{0020}my\u{0020}kick.", "水ならボクの足蹴りを受け流せるよね？", "如果是水的話應該能接住小生的一腳吧。", "0", "如果是水的话应该能接住小生的一脚吧。", "0", "cv_karenn_24", "0", "0"},
[400526] = {400526, 10005, 29, 21, "0", "0", "Have\u{0020}you\u{0020}heard?\u{0020}In\u{0020}my\u{0020}hometown,\u{0020}people\u{0020}would\u{0020}practice\u{0020}under\u{0020}waterfalls.", "ボクの故郷には滝を使って鍛錬する人がいるんだ。こんな話、聞いたことある？", "聽說過嗎？在小生的故鄉，有人會使用瀑布進行修行呢。", "0", "听说过吗？在小生的故乡，有人会使用瀑布进行修行呢。", "0", "cv_karenn_25", "0", "0"},
[400527] = {400527, 10005, 30, 22, "0", "0", "Strike\u{0020}with\u{0020}all\u{0020}your\u{0020}heart\u{0020}like\u{0020}me!", "ボクのみたいに、会心の一撃を出そう！", "像小生一樣使出全心全意的一擊吧！", "0", "像小生一样使出全心全意的一击吧！", "0", "cv_karenn_26", "0", "0"},
[400528] = {400528, 10005, 31, 23, "0", "0", "If\u{0020}you\u{0020}guess\u{0020}wrong,\u{0020}be\u{0020}ready\u{0020}to\u{0020}take\u{0020}this\u{0020}kick\u{0020}of\u{0020}mine.", "外れたらボクの足蹴りを食らうことになるからね。", "猜錯了的話就準備接下小生這腳吧。", "0", "猜错了的话就准备接下小生这脚吧。", "0", "cv_karenn_27", "0", "0"},
[400529] = {400529, 10005, 32, 24, "0", "0", "It\u{0020}seems\u{0020}that\u{0020}we\u{0020}have\u{0020}a\u{0020}connection\u{0020}strong\u{0020}enough.", "ボクたちはもう、心が通じ合ってるみたいだね。", "看來我們之間的默契已經足夠了呢。", "0", "看来我们之间的默契已经足够了呢。", "0", "cv_karenn_28", "0", "0"},
[400530] = {400530, 10005, 33, 25, "0", "0", "Hi-yah!\u{0020}Check\u{0020}this!", "はっ！足蹴りを食らえ！", "嘿呀！我踹！", "0", "嘿呀！我踹！", "0", "cv_karenn_29", "0", "0"},
[400531] = {400531, 10005, 34, 26, "0", "0", "Welcome\u{0020}back,\u{0020}Navigator\u{0020}of\u{0020}Danube.\u{0020}I\u{0020}was\u{0020}worrying\u{0020}about\u{0020}having\u{0020}no\u{0020}opponent.", "お帰り、ダニューブのナビゲーター。ボクはちょうど、手合わせの相手がいなくて悩んでたところだ。", "歡迎回來，多瑙的領航，小生正愁沒有對手呢。", "0", "欢迎回来，多瑙的领航，小生正愁没有对手呢。", "0", "cv_karenn_32", "0", "0"},
[400532] = {400532, 10005, 35, 27, "0", "0", "Let\u{0020}me\u{0020}clear\u{0020}the\u{0020}way\u{0020}for\u{0020}you\u{0020}with\u{0020}my\u{0020}fists\u{0020}and\u{0020}kicks.", "ボクが武術で道を切り開いてやる！", "就讓小生用拳腳為你開路吧。", "0", "就让小生用拳脚为你开路吧。", "0", "cv_karenn_34", "0", "0"},
[400533] = {400533, 10005, 36, 28, "0", "0", "The\u{0020}practice\u{0020}is\u{0020}about\u{0020}to\u{0020}start\u{0020}again.", "修行がまた始まるってことだね。", "修行又要開始了啊。", "0", "修行又要开始了啊。", "0", "cv_karenn_35", "0", "0"},
[400534] = {400534, 10005, 37, 29, "0", "0", "The\u{0020}troops\u{0020}have\u{0020}assembled\u{0020}completely.", "部隊はもう、集合済みだ。", "部隊已經集合完畢了喔。", "0", "部队已经集合完毕了哦。", "0", "cv_karenn_36", "0", "0"},
[400535] = {400535, 10005, 38, 30, "0", "0", "Hope\u{0020}to\u{0020}find\u{0020}a\u{0020}good\u{0020}match.", "好敵手が来ると良いな。", "希望能招到個好對手啊。", "0", "希望能招到个好对手啊。", "0", "cv_karenn_37", "0", "0"},
[400536] = {400536, 10005, 39, 31, "0", "0", "I'm\u{0020}still\u{0020}more\u{0020}used\u{0020}to\u{0020}the\u{0020}equipment\u{0020}of\u{0020}Kyushu.", "個人的には九州の装備の方がいい。", "我還是更習慣九州的裝備啊。", "0", "我还是更习惯九州的装备啊。", "0", "cv_karenn_38", "0", "0"},
[400537] = {400537, 10005, 40, 32, "0", "0", "Leave\u{0020}the\u{0020}purchasing\u{0020}to\u{0020}me!", "買いものならボクに任せて！", "採購的事情就交給小生吧！", "0", "采购的事情就交给小生吧！", "0", "cv_karenn_39", "0", "0"},
[400538] = {400538, 10005, 41, 33, "0", "0", "Identity\u{0020}verification.", "身分確認だ。", "身份確認。", "0", "身份确认。", "0", "cv_karenn_40", "0", "0"},
[400539] = {400539, 10005, 42, 34, "0", "0", "Change\u{0020}the\u{0020}settings\u{0020}according\u{0020}to\u{0020}your\u{0020}own\u{0020}preferences.", "自分の好みに合わせて設定を変更しよう。", "按照自己的喜好來變更設定吧。", "0", "按照自己的喜好来变更设置吧。", "0", "cv_karenn_41", "0", "0"},
[400540] = {400540, 10005, 43, 35, "0", "0", "Check\u{0020}if\u{0020}there\u{0020}are\u{0020}any\u{0020}new\u{0020}letters.", "新しいメールが来てるかチェックしよう。", "檢查一下有沒有新的來信吧。", "0", "检查一下有没有新的来信吧。", "0", "cv_karenn_42", "0", "0"},
[400541] = {400541, 10005, 44, 36, "0", "0", "This\u{0020}is\u{0020}the\u{0020}chat\u{0020}room\u{0020}dedicated\u{0020}to\u{0020}the\u{0020}Navigator,\u{0020}right?", "これはナビゲーター専用のチャットルームかな？", "這是領航專用的聊天室吧。", "0", "这是领航专用的聊天室吧。", "0", "cv_karenn_43", "0", "0"},
