[400601] = {400601, 10006, 2, 2, "0", "0", "Will\u{0020}there\u{0020}be\u{0020}any\u{0020}punishment\u{0020}for\u{0020}bad\u{0020}work?\u{0020}I'm\u{0020}so\u{0020}curious~", "仕事で失敗したら、何か罰があるの？あたし、凄く知りたいなぁ。", "工作不好會有什麼懲罰嗎？我很好奇喔~", "0", "工作不好会有什么惩罚吗？我很好奇哦~", "0", "cv_shirinn_2", "0", "0"},
[400602] = {400602, 10006, 3, 3, "0", "0", "I'm\u{0020}Celine\u{0020}Welt.\u{0020}You\u{0020}can\u{0020}call\u{0020}me\u{0020}whatever\u{0020}you\u{0020}want.", "あたし、シリン・ウォルターっていうの。好きに呼んでねぇ。", "我是棲林·瓦爾特，您想叫我什麼都可以喔。", "0", "我是栖林·瓦尔特，您想叫我什么都可以哦。", "0", "cv_shirinn_1", "0", "0"},
[400603] = {400603, 10006, 4, 4, "0", "idle", "Eh~\u{0020}If\u{0020}I\u{0020}make\u{0020}you\u{0020}feel\u{0020}stressed,\u{0020}please\u{0020}punish\u{0020}me~", "ねぇねぇ、もしあたしのことでなにかストレスを感じたら、お仕置きでもなんでも、好きにしていいからねぇ。", "欸~如果我讓您感到壓力的話，就請懲罰我吧~", "0", "哎~如果我让您感到压力的话，就请惩罚我吧~", "0", "cv_shirinn_3", "0", "0"},
[400604] = {400604, 10006, 5, 4, "0", "idle", "Navigator,\u{0020}don't\u{0020}ignore\u{0020}me.\u{0020}Are\u{0020}you\u{0020}just\u{0020}staring\u{0020}at\u{0020}me\u{0020}like\u{0020}this\u{0020}and\u{0020}doing\u{0020}nothing?", "ナビゲーター、もうっ！もうちょっと構ってほしいの！なんであたしを見つめるだけで、何もしないの？", "領航，不要不理人家啦，總是這麼盯著我卻什麼都不做嗎？", "0", "领航，不要不理人家啦，总是这么盯着我却什么都不做吗？", "0", "cv_shirinn_4", "0", "0"},
[400605] = {400605, 10006, 6, 4, "0", "idle", "Navigator,\u{0020}have\u{0020}you\u{0020}seen\u{0020}Julia?\u{0020}Hmm?\u{0020}Why\u{0020}I'm\u{0020}looking\u{0020}for\u{0020}her?\u{0020}Hehe,\u{0020}it's\u{0020}a\u{0020}secret~", "ナビゲーター、ジュリアを見なかった？え？何の用かって？……うふふ、秘密よぉ。", "領航，你見到茱莉亞了嗎？嗯？找她有什麼事……嘿嘿，是秘密喔~", "0", "领航，你见到茱莉亚了吗？嗯？找她有什么事……嘿嘿，是秘密哦~", "0", "cv_shirinn_29", "0", "0"},
[400606] = {400606, 10006, 7, 5, "1_》_0_0.8", "level1", "Navigator,\u{0020}please\u{0020}scold\u{0020}me\u{0020}and\u{0020}punish\u{0020}me.", "ナビゲーター、あたしを叱って。お仕置きしてぇ。", "領航，請責罵我，懲罰我吧。", "0", "领航，请责骂我，惩罚我吧。", "0", "cv_shirinn_30", "0", "0"},
[400607] = {400607, 10006, 8, 5, "1_》_0_0.8", "level1", "Navigator,\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}know\u{0020}my\u{0020}secret?", "ナビゲーター、あたしの秘密、知りたくない？", "領航，你想要知道我的秘密嗎？", "0", "领航，你想要知道我的秘密吗？", "0", "cv_shirinn_5", "0", "0"},
[400608] = {400608, 10006, 9, 5, "1_》_100_1.5", "level2", "The\u{0020}pain\u{0020}in\u{0020}your\u{0020}eyes\u{0020}is\u{0020}pleasure\u{0020}for\u{0020}me.\u{0020}So,\u{0020}Navigator,\u{0020}please\u{0020}scold\u{0020}me~", "あなたにとっての苦しみは、あたしにとっては喜びなの。だからナビゲーター、あたしを責めてぇ～！", "你們眼中的痛苦對我而言就是快樂，所以，領航，請責罵我吧~", "0", "你们眼中的痛苦对我而言就是快乐，所以，领航，请责骂我吧~", "0", "cv_shirinn_6", "0", "0"},
[400609] = {400609, 10006, 10, 5, "1_》_500_2", "level3", "Sure\u{0020}enough...\u{0020}Only\u{0020}pain\u{0020}can\u{0020}bring\u{0020}me\u{0020}true\u{0020}pleasure.\u{0020}This\u{0020}is\u{0020}the\u{0020}real\u{0020}me.", "やっぱり……本当の喜びをもたらしてくれるのは、痛みだけ。今のあたしこそ、本当のあたしなの。", "果然…只有傷痛才能帶給我真正的愉悅呢，這樣的我才是真正的我。", "0", "果然…只有伤痛才能带给我真正的愉悦呢，这样的我才是真正的我。", "0", "cv_shirinn_7", "0", "0"},
[400610] = {400610, 10006, 11, 5, "1_》_1000_2.5", "level4", "I\u{0020}always\u{0020}feel\u{0020}relieved\u{0020}when\u{0020}I'm\u{0020}with\u{0020}you.\u{0020}Different\u{0020}from\u{0020}the\u{0020}physical\u{0020}pleasure...\u{0020}It's\u{0020}that\u{0020}kind\u{0020}of\u{0020}feeling\u{0020}that\u{0020}makes\u{0020}people\u{0020}want\u{0020}to\u{0020}close\u{0020}their\u{0020}eyes\u{0020}and\u{0020}relax.", "あなたと一緒にいると、いつもホッとするの。体に刺激を受けて得られる喜びとは違って、なんか……まどろむような感じ。", "和你在一起的時候總是感到非常安心呢，和肉體受到刺激後所產生的愉悅感不同……是那種，想讓人閉上眼好好休息一下的感覺呢。", "0", "和你在一起的时候总是感到非常安心呢，和肉体受到刺激后所产生的愉悦感不同……是那种，想让人闭上眼好好休息一下的感觉呢。", "0", "cv_shirinn_8", "0", "0"},
[400611] = {400611, 10006, 12, 6, "0", "0", "Not\u{0020}enough\u{0020}at\u{0020}all~", "全然足りないよぉ。", "完全不夠呢~", "0", "完全不够呢~", "0", "cv_shirinn_9", "0", "0"},
