[400701] = {400701, 10007, 2, 2, "0", "0", "Please\u{0020}rest\u{0020}assured\u{0020}that\u{0020}I\u{0020}will\u{0020}always\u{0020}be\u{0020}here\u{0020}to\u{0020}take\u{0020}good\u{0020}care\u{0020}of\u{0020}you.", "ご安心ください。私はずっとあなたの傍でお世話をしますから。", "請放心，我會一直待在這，照顧好您的。", "0", "请放心，我会一直待在这，照顾好您的。", "0", "cv_uki_2", "0", "0"},
[400702] = {400702, 10007, 3, 3, "0", "0", "Nice\u{0020}to\u{0020}meet\u{0020}you.\u{0020}My\u{0020}name\u{0020}is\u{0020}Uki.\u{0020}I'm\u{0020}the\u{0020}bride\u{0020}of\u{0020}the\u{0020}sea\u{0020}god...\u{0020}Just\u{0020}kidding.\u{0020}Your\u{0020}expression\u{0020}is\u{0020}so\u{0020}cute.", "初めまして。私の名は海姫。海神の花嫁です――冗談ですわ。その表情、可愛かったですよ。", "初次見面，我的名字叫做海姬，是海神的新娘……開玩笑的，您的表情真是可愛啊。", "0", "初次见面，我的名字叫做海姬，是海神的新娘……开玩笑的，您的表情真是可爱啊。", "0", "cv_uki_1", "0", "0"},
[400703] = {400703, 10007, 4, 4, "0", "idle", "Navigator,\u{0020}take\u{0020}off\u{0020}your\u{0020}clothes...\u{0020}Why?\u{0020}Oh,\u{0020}because\u{0020}only\u{0020}when\u{0020}you\u{0020}take\u{0020}them\u{0020}off\u{0020}can\u{0020}I\u{0020}sew\u{0020}them\u{0020}up.", "服を脱いでくださいね、ナビゲーター……どうしたのですか？脱がないと繕えないですよ？", "領航，把衣服脫下來吧……為什麼？欸呀，因為脫下來才能縫好它呀。", "0", "领航，把衣服脱下来吧……为什么？诶呀，因为脱下来才能缝好它呀。", "0", "cv_uki_3", "0", "0"},
[400704] = {400704, 10007, 5, 4, "0", "idle", "It's\u{0020}almost\u{0020}time\u{0020}to\u{0020}rest...\u{0020}Navigator,\u{0020}what\u{0020}do\u{0020}you\u{0020}want\u{0020}for\u{0020}lunch?", "そろそろ休憩時間ですね……ナビゲーター、お昼は何がいいですか？", "差不多該到休息的時間了……領航，午飯想吃什麼？", "0", "差不多该到休息的时间了……领航，午饭想吃什么？", "0", "cv_uki_4", "0", "0"},
[400705] = {400705, 10007, 6, 4, "0", "idle", "Momo...\u{0020}always\u{0020}makes\u{0020}people\u{0020}not\u{0020}understand\u{0020}what\u{0020}she\u{0020}is\u{0020}thinking.\u{0020}But\u{0020}that\u{0020}child\u{0020}always\u{0020}looks\u{0020}lonely.\u{0020}Navigator,\u{0020}please\u{0020}pay\u{0020}more\u{0020}attention\u{0020}to\u{0020}her.", "モモ……あのコが何を考えているのか全然分かりません。でも、何だか寂しそうに見えます……優しくしてあげてくださいね、ナビゲーター。", "默默……總是讓人不明白她在想什麼。但是那孩子似乎總是表現出一副很孤單的樣子，領航要多關心下她喔。", "0", "默默……总是让人不明白她在想什么。但是那孩子似乎总是表现出一副很孤单的样子，领航要多关心下她噢。", "0", "cv_uki_28", "0", "0"},
[400706] = {400706, 10007, 7, 5, "1_》_0_0.8", "level1", "After\u{0020}the\u{0020}war\u{0020}is\u{0020}over,\u{0020}Uki\u{0020}wants\u{0020}to\u{0020}go\u{0020}back\u{0020}to\u{0020}her\u{0020}hometown\u{0020}and\u{0020}run\u{0020}an\u{0020}inn.\u{0020}Every\u{0020}day,\u{0020}watching\u{0020}the\u{0020}travelers\u{0020}coming\u{0020}and\u{0020}going,\u{0020}listening\u{0020}to\u{0020}their\u{0020}stories,\u{0020}and\u{0020}curing\u{0020}the\u{0020}their\u{0020}fatigue.", "戦争が終わったら、私は故郷に帰って旅館をやりたいと思っています。毎日行き来する旅人たちを眺めて、彼らの物語を聞いたりして、疲れを癒してあげたいのです。", "戰爭結束之後，海姬想回到故鄉，開一間旅館。每天看著來來往往的旅人，傾聽旅人的故事，治癒旅人的疲憊。", "0", "战争结束之后，海姬想回到故乡，开一间旅馆。每天看着来来往往的旅人，倾听旅人的故事，治愈旅人的疲惫。", "0", "cv_uki_29", "0", "0"},
[400707] = {400707, 10007, 8, 5, "1_》_0_0.8", "level1", "Huh?\u{0020}Navigator,\u{0020}is\u{0020}there\u{0020}something\u{0020}on\u{0020}my\u{0020}face?", "え？私の顔に何かついていますか？ナビゲーター。", "嗯？領航，我的臉上有什麼嗎？", "0", "嗯？领航，我的脸上有什么吗？", "0", "cv_uki_5", "0", "0"},
[400708] = {400708, 10007, 9, 5, "1_》_100_1.5", "level2", "Navigator,\u{0020}unhealthy\u{0020}food\u{0020}is\u{0020}bad\u{0020}for\u{0020}you.\u{0020}Let\u{0020}me\u{0020}cook\u{0020}for\u{0020}you.", "ナビゲーター、不健康な食品ばかり食べていると、体に悪いですよ？私の自慢の手料理を作ってあげましょう。", "領航，總是吃一些不健康的食品對身體不好，讓我給您做些料理吧。", "0", "领航，总是吃一些不健康的食品对身体不好，让我给您做些料理吧。", "0", "cv_uki_6", "0", "0"},
[400709] = {400709, 10007, 10, 5, "1_》_500_2", "level3", "Navigator,\u{0020}when\u{0020}we\u{0020}are\u{0020}on\u{0020}vacation,\u{0020}let's\u{0020}go\u{0020}on\u{0020}a\u{0020}trip\u{0020}together,\u{0020}just\u{0020}you\u{0020}and\u{0020}me~", "ナビゲーター、いつか一緒に旅行に行きましょう！私とあなた、二人きりで。", "領航，等閒暇的時候，我們一起去旅行吧，只有你和我喔~", "0", "领航，等闲暇的时候，我们一起去旅行吧，只有你和我噢~", "0", "cv_uki_7", "0", "0"},
[400710] = {400710, 10007, 11, 5, "1_》_1000_2.5", "level4", "I\u{0020}really\u{0020}hope\u{0020}such\u{0020}times\u{0020}can\u{0020}last\u{0020}forever...\u{0020}Navigator,\u{0020}who\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}marry\u{0020}in\u{0020}the\u{0020}future?", "こんな日が続くといいのにって思います……ナビゲーターは将来、どんな方と結婚したいのですか？", "真希望這樣的時光能一直持續下去啊……領航，您以後想和什麼樣的人結婚呢？", "0", "真希望这样的时光能一直持续下去啊……领航，您以后想和什么样的人结婚呢？", "0", "cv_uki_8", "0", "0"},
[400711] = {400711, 10007, 12, 6, "0", "0", "The\u{0020}cooking\u{0020}has\u{0020}also\u{0020}improved.", "料理の腕が上がったみたいですね。", "料理的水準也提高了呢。", "0", "料理的水平也提高了呢。", "0", "cv_uki_9", "0", "0"},
[400712] = {400712, 10007, 13, 7, "0", "0", "Am\u{0020}I\u{0020}special\u{0020}to\u{0020}Navigator...", "やはり、ナビゲーターにとって、私は特別な存在なのですね……", "果然，我對領航來說是特別的嗎……", "0", "果然，我对领航来说是特别的吗……", "0", "cv_uki_10", "0", "0"},
[400713] = {400713, 10007, 14, 8, "0", "0", "I\u{0020}can\u{0020}feel\u{0020}it,\u{0020}Navigator.\u{0020}Your\u{0020}passionate\u{0020}heart.\u{0020}To\u{0020}respond\u{0020}to\u{0020}that\u{0020}enthusiasm,\u{0020}Uki\u{0020}will\u{0020}do\u{0020}her\u{0020}best.", "感じていますよ、ナビゲーターのその熱い心。私は全てをかけてその情熱に応えます。", "我感受到了，領航您那顆炙熱的心。為了回應那份熱情，海姬會傾盡所有的。", "0", "我感受到了，领航您那颗炙热的心。为了回应那份热情，海姬会倾尽所有的。", "0", "cv_uki_11", "0", "0"},
[400714] = {400714, 10007, 15, 9, "0", "0", "Even\u{0020}the\u{0020}combat\u{0020}skills\u{0020}have\u{0020}improved~", "戦闘スキルが上達しました。", "連戰鬥技能也上升了喔~", "0", "连战斗技能也上升了噢~", "0", "cv_uki_12", "0", "0"},
[400715] = {400715, 10007, 16, 10, "0", "0", "The\u{0020}battlefield...\u{0020}We\u{0020}can't\u{0020}be\u{0020}careless.", "戦場……絶対に気を緩めてはいけません。", "戰場……可不能掉以輕心呢。", "0", "战场……可不能掉以轻心呢。", "0", "cv_uki_13", "0", "0"},
[400716] = {400716, 10007, 17, 11, "0", "0", "The\u{0020}battle\u{0020}is\u{0020}won.\u{0020}Great~\u{0020}Navigator,\u{0020}let's\u{0020}go\u{0020}home\u{0020}together.", "戦闘勝利！よかったですね！一緒に帰りましょう、ナビゲーター。", "戰鬥勝利，太好了~領航，一起回家吧。", "0", "战斗胜利，太好了~领航，一起回家吧。", "0", "cv_uki_14", "0", "0"},
[400717] = {400717, 10007, 18, 12, "0", "0", "There\u{0020}are\u{0020}some\u{0020}regrets.\u{0020}Let's\u{0020}work\u{0020}hard\u{0020}together\u{0020}next\u{0020}time,\u{0020}Navigator.", "惜しかったですね。また今度一緒に頑張りましょう、ナビゲーター。", "有一些遺憾，下次一起努力吧，領航。", "0", "有一些遗憾，下次一起努力吧，领航。", "0", "cv_uki_15", "0", "0"},
[400718] = {400718, 10007, 19, 13, "0", "0", "It's\u{0020}so\u{0020}close,\u{0020}Navigator.\u{0020}Are\u{0020}you\u{0020}okay?", "危ないところでした！ナビゲーター、大丈夫ですか？", "真危險，領航，您沒事吧？", "0", "真危险，领航，您没事吧？", "0", "cv_uki_16", "0", "0"},
[400719] = {400719, 10007, 20, 14, "0", "0", "Navigator,\u{0020}please\u{0020}follow\u{0020}me\u{0020}closely.\u{0020}Time\u{0020}to\u{0020}retreat.", "ナビゲーター、撤退しますから、私について来てください。", "領航，請跟緊我，要撤退了。", "0", "领航，请跟紧我，要撤退了。", "0", "cv_uki_17", "0", "0"},
[400720] = {400720, 10007, 21, 15, "0", "0", "Hey!\u{0020}Got\u{0020}one!", "やっ！一体、片付けましたね！", "嘿咻！消滅一隻了！", "0", "嘿咻！干掉一只了！", "0", "cv_uki_18", "0", "0"},
[400721] = {400721, 10007, 23, 16, "0", "0", "This\u{0020}is...\u{0020}the\u{0020}power\u{0020}of\u{0020}the\u{0020}sea.", "これが……海の力です。", "這是……大海的力量。", "0", "这是……大海的力量。", "0", "cv_uki_19", "0", "0"},
[400722] = {400722, 10007, 26, 19, "0", "0", "Sorry,\u{0020}Navigator...\u{0020}I've\u{0020}caused\u{0020}you\u{0020}trouble...", "申し訳ありません、ナビゲーター……ご迷惑をお掛けしてしまって……", "抱歉，領航……給您添麻煩了……", "0", "抱歉，领航……给您添麻烦了……", "0", "cv_uki_20", "0", "0"},
[400723] = {400723, 10007, 27, 20, "0", "0", "Navigator,\u{0020}aren't\u{0020}you\u{0020}coming\u{0020}in?", "ナビゲーター、入らないのですか？", "領航，您不進來嗎？", "0", "领航，您不进来吗？", "0", "cv_uki_21", "0", "0"},
[400724] = {400724, 10007, 28, 21, "0", "0", "Uki\u{0020}has\u{0020}loved\u{0020}the\u{0020}feeling\u{0020}of\u{0020}soaking\u{0020}in\u{0020}water\u{0020}since\u{0020}she\u{0020}was\u{0020}a\u{0020}child.\u{0020}How\u{0020}about\u{0020}you?", "私は小さい頃から水の中が好きなんです。あなたは？", "海姬從小時候開始，就很喜歡泡在水裡的感覺，您呢？", "0", "海姬从小时候开始，就很喜欢泡在水里的感觉，您呢？", "0", "cv_uki_22", "0", "0"},
[400725] = {400725, 10007, 29, 21, "0", "0", "Let's\u{0020}bathe\u{0020}together.\u{0020}Navigator,\u{0020}you've\u{0020}been\u{0020}tired,\u{0020}haven't\u{0020}you?", "一緒に入りましょう。今日も一日頑張っていましたから、ナビゲーターもお疲れでしょう。", "一起洗吧，領航您也累了一天了，不是嗎？", "0", "一起洗吧，领航您也累了一天了，不是吗？", "0", "cv_uki_23", "0", "0"},
[400726] = {400726, 10007, 30, 22, "0", "0", "You\u{0020}should\u{0020}be\u{0020}careful\u{0020}of\u{0020}the\u{0020}road.", "足元に、お気をつけて。", "您要當心腳下的路面呀。", "0", "您要当心脚下的路面呀。", "0", "cv_uki_24", "0", "0"},
[400727] = {400727, 10007, 31, 23, "0", "0", "If\u{0020}Navigator\u{0020}can\u{0020}guess\u{0020}it's\u{0020}me,\u{0020}I'll\u{0020}be\u{0020}very\u{0020}happy.", "当たったら嬉しいです。", "如果領航能猜中是我的話，我會很高興的。", "0", "如果领航能猜中是我的话，我会很高兴的。", "0", "cv_uki_25", "0", "0"},
[400728] = {400728, 10007, 32, 24, "0", "0", "I\u{0020}knew\u{0020}you\u{0020}could\u{0020}answer\u{0020}correctly.", "正解すると信じていましたよ、最初から。", "我從一開始，就相信您一定能答對的。", "0", "我从一开始，就相信您一定能答对的。", "0", "cv_uki_26", "0", "0"},
[400729] = {400729, 10007, 33, 25, "0", "0", "Um...\u{0020}It's\u{0020}okay.\u{0020}Navigator\u{0020}has\u{0020}done\u{0020}your\u{0020}best,\u{0020}right?", "うーん……大丈夫です。ナビゲーターは全力を尽くしましたから、ね？", "嗯……沒關係，領航已經盡力了，對吧？", "0", "嗯……没关系，领航已经尽力了，对吧？", "0", "cv_uki_27", "0", "0"},
[400730] = {400730, 10007, 34, 26, "0", "0", "Navigator,\u{0020}are\u{0020}you\u{0020}going\u{0020}to\u{0020}work\u{0020}today?\u{0020}Then,\u{0020}I'll\u{0020}always\u{0020}be\u{0020}here\u{0020}with\u{0020}you.", "今日もお仕事ですか、ナビゲーター？では、ここから、ずっとご一緒しますよ。", "領航，今天您也要工作嗎？那麼，我也會一直在這陪您的。", "0", "领航，今天您也要工作吗？那么，我也会一直在这陪您的。", "0", "cv_uki_30", "0", "0"},
[400731] = {400731, 10007, 35, 27, "0", "0", "Navigator,\u{0020}please\u{0020}lead\u{0020}us\u{0020}forward.", "ナビゲーター、私たちを率いて前に進んでください。", "領航，請您帶領著我們前進吧。", "0", "领航，请您带领着我们前进吧。", "0", "cv_uki_32", "0", "0"},
