[400800] = {400800, 10008, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_dororisu_31", "0", "0"},
[400801] = {400801, 10008, 2, 2, "0", "0", "Leave\u{0020}it\u{0020}to\u{0020}me.\u{0020}I\u{0020}will\u{0020}definitely\u{0020}defend\u{0020}this\u{0020}place.", "私に任せてください。この場所は、絶対に守ってみせます。", "交給我吧，我一定會守住這裡的。", "0", "交给我吧，我一定会守住这里的。", "0", "cv_dororisu_2", "0", "0"},
[400802] = {400802, 10008, 3, 3, "0", "0", "My\u{0020}name\u{0020}is\u{0020}Dolores,\u{0020}Dolores\u{0020}from\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad...\u{0020}I'll\u{0020}be\u{0020}of\u{0020}your\u{0020}care\u{0020}from\u{0020}now\u{0020}on.", "私の名はドロリィス、第三研究室防衛班のドロリィスです……今日からお世話になります、よろしくお願いします。", "我的名字叫做多洛莉絲，第三研究室防衛班的多洛莉絲……從今天起就要給您添麻煩了。", "0", "我的名字叫做多洛莉丝，第三研究室防卫班的多洛莉丝……从今天起就要给您添麻烦了。", "0", "cv_dororisu_1", "0", "0"},
[400803] = {400803, 10008, 4, 4, "0", "idle", "I\u{0020}haven't\u{0020}been\u{0020}back\u{0020}to\u{0020}the\u{0020}Ark\u{0020}for\u{0020}a\u{0020}long\u{0020}time.\u{0020}The\u{0020}changes\u{0020}here\u{0020}are\u{0020}significant.", "方舟に帰るのは久しぶりです。ここも、大きく変わりましたね。", "我已經很久沒回方舟了呢，這裡的變化可真不小啊。", "0", "我已经很久没回方舟了呢，这里的变化可真不小啊。", "0", "cv_dororisu_3", "0", "0"},
[400804] = {400804, 10008, 5, 4, "0", "idle", "Navigator,\u{0020}would\u{0020}you\u{0020}like\u{0020}to\u{0020}have\u{0020}some\u{0020}tea?\u{0020}This\u{0020}is\u{0020}sent\u{0020}by\u{0020}my\u{0020}family\u{0020}from\u{0020}our\u{0020}hometown.\u{0020}There\u{0020}is\u{0020}too\u{0020}much,\u{0020}I\u{0020}want\u{0020}to\u{0020}share\u{0020}with\u{0020}everyone.", "ナビゲーターさん、お茶はいかがですか？これ、実家から送ってきて…...たくさんあるので、皆さんにお分けしようかなと思いまして。", "領航，要喝茶嗎？這是我家裡人從老家寄過來的，因為稍微有些多了，所以就想分給大家。", "0", "领航，要喝茶吗？这是我家里人从老家寄过来的，因为稍微有些多了，所以就想分给大家。", "0", "cv_dororisu_4", "0", "0"},
[400805] = {400805, 10008, 6, 4, "0", "idle", "Even\u{0020}if\u{0020}there\u{0020}is\u{0020}only\u{0020}one\u{0020}person\u{0020}left\u{0020}in\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad,\u{0020}we\u{0020}will\u{0020}never\u{0020}forget\u{0020}our\u{0020}mission.", "第三研究室防衛班の私たちは、たとえ一人になったとしても、自分の使命を全うします。", "第三研究室防衛班哪怕只剩下一個人，我們都不會忘記自己的使命。", "0", "第三研究室防卫班哪怕只剩下一个人，我们都不会忘记自己的使命。", "0", "cv_dororisu_28", "0", "0"},
[400806] = {400806, 10008, 7, 5, "1_》_0_0.8", "level1", "I\u{0020}hope\u{0020}that\u{0020}one\u{0020}day,\u{0020}the\u{0020}Defense\u{0020}Squad\u{0020}can\u{0020}regain\u{0020}its\u{0020}former\u{0020}liveliness.", "いつか、昔のように賑やかな防衛班に戻れたらなぁって思います。", "真希望有朝一日，防衛班還能恢復往昔的熱鬧啊。", "0", "真希望有朝一日，防卫班还能恢复往昔的热闹啊。", "0", "cv_dororisu_29", "0", "0"},
[400807] = {400807, 10008, 8, 5, "1_》_0_0.8", "level1", "Something\u{0020}on\u{0020}your\u{0020}mind,\u{0020}Navigator?\u{0020}Got\u{0020}any\u{0020}jobs\u{0020}for\u{0020}me?", "え？私に何かご用ですか、それとも、一緒に行動したい、…...ということでしょうか？", "嗯？領航找我有什麼事嗎？還是說要一起行動？", "0", "嗯？领航找我有什么事吗？还是说要一起行动？", "0", "cv_dororisu_5", "0", "0"},
[400808] = {400808, 10008, 9, 5, "1_》_100_1.5", "level2", "Seagulls,\u{0020}my\u{0020}favorite\u{0020}animals\u{0020}are\u{0020}them.\u{0020}Watching\u{0020}them\u{0020}gliding\u{0020}across\u{0020}the\u{0020}sky,\u{0020}I\u{0020}can't\u{0020}help\u{0020}but\u{0020}think\u{0020}of\u{0020}them...", "カモメは、私の一番好きな動物です。群れで青空を飛んでいく姿を見るたびに、彼女たちのことを思い出すんです……", "海鷗，我最喜歡的動物就是它們。看著它們集群劃過碧空的身影，我就會不由自主地想起她們來……", "0", "海鸥，我最喜欢的动物就是它们。看着它们集群划过碧空的身影，我就会不由自主地想起她们来……", "0", "cv_dororisu_6", "0", "0"},
[400809] = {400809, 10008, 10, 5, "1_》_500_2", "level3", "Navigator,\u{0020}have\u{0020}you\u{0020}heard\u{0020}of\u{0020}the\u{0020}Arctic\u{0020}Tern?\u{0020}They\u{0020}are\u{0020}the\u{0020}migratory\u{0020}birds\u{0020}with\u{0020}the\u{0020}longest\u{0020}migration\u{0020}route\u{0020}in\u{0020}the\u{0020}world.\u{0020}They\u{0020}have\u{0020}to\u{0020}travel\u{0020}40,000\u{0020}kilometers\u{0020}every\u{0020}year,\u{0020}going\u{0020}back\u{0020}and\u{0020}forth\u{0020}between\u{0020}the\u{0020}summers\u{0020}of\u{0020}the\u{0020}two\u{0020}poles.\u{0020}I\u{0020}always\u{0020}feel\u{0020}that\u{0020}you\u{0020}are\u{0020}also\u{0020}a\u{0020}tern\u{0020}traveling\u{0020}over\u{0020}mountains\u{0020}and\u{0020}rivers\u{0020}in\u{0020}pursuit\u{0020}of\u{0020}something.", "キョクアジサシって聞いたことありますか？最も長距離の渡りをする鳥ですよ。この鳥は年間約4万キロを飛んで、夏を追い求め、両極を往復するんです。ナビゲーターさんも、何かを追い求めるために旅をするキョクアジサシのような方なのかなって、何となくそう思ったんです。", "領航，你聽說過北極燕鷗嗎？它們是世界上遷徙路線最長的候鳥。每年都要經歷4萬公里的旅途，往返於兩極的夏日。我總是在隱約中覺得，您也是一隻為了追尋某物而跋山涉水的燕鷗呢。", "0", "领航，你听说过北极燕鸥吗？它们是世界上迁徙路线最长的候鸟。每年都要经历4万公里的旅途，往返于两极的夏日。我总是在隐约中觉得，您也是一只为了追寻某物而跋山涉水的燕鸥呢。", "0", "cv_dororisu_7", "0", "0"},
[400810] = {400810, 10008, 11, 5, "1_》_1000_2.5", "level4", "The\u{0020}sea\u{0020}is\u{0020}really\u{0020}powerful.\u{0020}Even\u{0020}after\u{0020}such\u{0020}a\u{0020}battle,\u{0020}it\u{0020}can\u{0020}restore\u{0020}everything\u{0020}to\u{0020}its\u{0020}original\u{0020}state\u{0020}overnight.\u{0020}There\u{0020}is\u{0020}nothing\u{0020}here\u{0020}that\u{0020}I\u{0020}am\u{0020}reluctant\u{0020}to\u{0020}part\u{0020}with...\u{0020}Navigator,\u{0020}maybe\u{0020}soon\u{0020}I\u{0020}will\u{0020}also\u{0020}set\u{0020}sail\u{0020}like\u{0020}a\u{0020}migratory\u{0020}bird,\u{0020}to\u{0020}retrieve\u{0020}my\u{0020}own\u{0020}short\u{0020}summer.", "海って凄いですね。あんな戦いがあったっていうのに、一晩で元通りに戻りました。ここにはもう、未練はありません……ナビゲーターさん、私ももうすぐ渡り鳥のように、自分の短い夏を取り戻すために旅に出ようかと思うんです。", "大海還真是厲害啊，即便是經歷那樣的戰鬥也能將一切在一夜之間恢復成原樣。這裡已經沒有什麼讓我留戀的了……領航，不久之後也許我也會像候鳥一樣，為了尋回自己那短暫的夏日而啟航吧。", "0", "大海还真是厉害啊，即便是经历那样的战斗也能将一切在一夜之间恢复成原样。这里已经没有什么让我留恋的了……领航，不久之后也许我也会像候鸟一样，为了寻回自己那短暂的夏日而启航吧。", "0", "cv_dororisu_8", "0", "0"},
[400811] = {400811, 10008, 12, 6, "0", "0", "Thank\u{0020}you!", "ありがとうございます！", "謝謝您！", "0", "谢谢您！", "0", "cv_dororisu_9", "0", "0"},
[400812] = {400812, 10008, 13, 7, "0", "0", "I'm\u{0020}sorry\u{0020}to\u{0020}cause\u{0020}you\u{0020}trouble.", "お手数をおかけしました。", "又讓您費心了。", "0", "又让您费心了。", "0", "cv_dororisu_10", "0", "0"},
[400813] = {400813, 10008, 14, 8, "0", "0", "The\u{0020}support\u{0020}and\u{0020}help\u{0020}you\u{0020}gave\u{0020}me,\u{0020}Dolores\u{0020}will\u{0020}never\u{0020}forget.\u{0020}When\u{0020}you\u{0020}need\u{0020}me,\u{0020}I\u{0020}will\u{0020}definitely\u{0020}return\u{0020}this\u{0020}favor.", "ご支援とご協力、ドロリィスは決して忘れません。何か困ったことがありましたら、必ずあなたの力になります。", "您對我的提攜以及幫助，多洛莉絲永遠不會忘記，當您遇到困境之時，這份力量一定會為您所用。", "0", "您对我的提携以及帮助，多洛莉丝永远不会忘记，当您遇到困境之时，这份力量一定会为您所用。", "0", "cv_dororisu_11", "0", "0"},
[400814] = {400814, 10008, 15, 9, "0", "0", "The\u{0020}new\u{0020}function\u{0020}still\u{0020}needs\u{0020}some\u{0020}time\u{0020}to\u{0020}adapt.", "新機能に慣れるまで、もうちょっと時間がかかりそうですね。", "新功能還需要適應一段時間呢。", "0", "新功能还需要适应一段时间呢。", "0", "cv_dororisu_12", "0", "0"},
[400815] = {400815, 10008, 16, 10, "0", "0", "Landing\u{0020}completed.\u{0020}Prepare\u{0020}to\u{0020}engage.", "ログイン完了です。迎撃の準備に入ります。", "登陸完畢，準備開始迎敵。", "0", "登陆完毕，准备开始迎敌。", "0", "cv_dororisu_13", "0", "0"},
[400816] = {400816, 10008, 17, 11, "0", "0", "Great...\u{0020}Did\u{0020}anyone\u{0020}get\u{0020}hurt?", "良かったです……皆さん、無事でしたか？", "太好了……大家都沒有受傷吧。", "0", "太好了……大家都没有受伤吧。", "0", "cv_dororisu_14", "0", "0"},
[400817] = {400817, 10008, 18, 12, "0", "0", "That\u{0020}was\u{0020}close...\u{0020}Almost\u{0020}failed\u{0020}to\u{0020}block\u{0020}it.", "危なかったですね……危うくやられてしまうところでした。", "好險……差點就沒擋下來。", "0", "好险……差点就没挡下来。", "0", "cv_dororisu_15", "0", "0"},
[400818] = {400818, 10008, 19, 13, "0", "0", "Woo...\u{0020}It's\u{0020}all\u{0020}my\u{0020}fault...", "うっ……全部、私のせいです……", "嗚……都是我的錯……", "0", "呜……都是我的错……", "0", "cv_dororisu_16", "0", "0"},
[400819] = {400819, 10008, 20, 14, "0", "0", "Mission\u{0020}failed...\u{0020}Please,\u{0020}evacuate\u{0020}now.", "ミッション失敗……お願いですから、先に撤退してください。", "任務失敗……拜託了，這次你們先撤離吧。", "0", "任务失败……拜托了，这次你们先撤离吧。", "0", "cv_dororisu_17", "0", "0"},
[400820] = {400820, 10008, 21, 15, "0", "0", "Phew-\u{0020}Finally\u{0020}solved...", "ふぅ――やっと解決できました……", "呼啊——終於解決了……", "0", "呼啊——终于解决了……", "0", "cv_dororisu_18", "0", "0"},
