[400822] = {400822, 10008, 26, 19, "0", "0", "So\u{0020}cold...\u{0020}Just\u{0020}like\u{0020}that\u{0020}time...", "寒いです……あの時と、同じ……", "好冷……和那個時候一樣……", "0", "好冷……和那个时候一样……", "0", "cv_dororisu_20", "0", "0"},
[400823] = {400823, 10008, 27, 20, "0", "0", "When\u{0020}we\u{0020}were\u{0020}at\u{0020}sea,\u{0020}we\u{0020}didn't\u{0020}have\u{0020}the\u{0020}chance\u{0020}to\u{0020}take\u{0020}a\u{0020}bath\u{0020}like\u{0020}this.", "海にいた時はこうしてお風呂に入る機会がなかったので……", "在海上的時候我們都沒有像這樣洗澡的機會呢。", "0", "在海上的时候我们都没有像这样洗澡的机会呢。", "0", "cv_dororisu_21", "0", "0"},
[400824] = {400824, 10008, 28, 21, "0", "0", "The\u{0020}water\u{0020}temperature\u{0020}is\u{0020}just\u{0020}right.\u{0020}Um~\u{0020}Ah\u{0020}-", "水温がちょうどいいです。ふぅ～ああ――", "水溫正好呢，嗯~啊——", "0", "水温正好呢，嗯~啊——", "0", "cv_dororisu_22", "0", "0"},
[400825] = {400825, 10008, 29, 21, "0", "0", "Navigator,\u{0020}be\u{0020}careful.", "ナビゲーターさん、お気を付けください。", "領航，要小心些喔。", "0", "领航，要小心些哦。", "0", "cv_dororisu_23", "0", "0"},
[400826] = {400826, 10008, 30, 22, "0", "0", "Has\u{0020}there\u{0020}been\u{0020}another\u{0020}accident?", "やっぱり……何か起きてしまったのでしょうか？", "果然……又發生意外了嗎？", "0", "果然……又发生意外了吗？", "0", "cv_dororisu_24", "0", "0"},
[400827] = {400827, 10008, 31, 23, "0", "0", "Navigator,\u{0020}guess\u{0020}who\u{0020}I\u{0020}am?", "ナビゲーターさん、私が誰なのか、当ててみてください！", "領航，來猜猜我是誰吧？", "0", "领航，来猜猜我是谁吧？", "0", "cv_dororisu_25", "0", "0"},
