[400841] = {400841, 10008, 45, 37, "0", "0", "It\u{0020}needs\u{0020}to\u{0020}be\u{0020}confirmed.", "ちゃんと確認しないといけませんね。", "得好好確認一下呢。", "0", "得好好确认一下呢。", "0", "cv_dororisu_42", "0", "0"},
[400900] = {400900, 10009, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_morgan_33", "0", "0"},
[400901] = {400901, 10009, 2, 2, "0", "0", "Me?\u{0020}Understood.\u{0020}I'll\u{0020}help\u{0020}you\u{0020}get\u{0020}the\u{0020}job\u{0020}done,\u{0020}Navigator.", "0", "我嗎…我明白了，我會好好協助領航您完成工作的。", "0", "0", "0", "cv_morgan_2", "0", "0"},
[400902] = {400902, 10009, 3, 3, "0", "0", "Hello,\u{0020}Navigator.\u{0020}I'm\u{0020}the\u{0020}captain\u{0020}of\u{0020}Moon\u{0020}Corona,\u{0020}Morgan\u{0020}Le\u{0020}Fay.\u{0020}Have\u{0020}Lilith\u{0020}and\u{0020}Skadi\u{0020}caused\u{0020}you\u{0020}any\u{0020}trouble?", "0", "您好，領航。我是月冕的隊長，摩根勒菲，莉莉絲和斯卡蒂有給您添麻煩嗎？", "0", "0", "0", "cv_morgan_1", "0", "0"},
[400903] = {400903, 10009, 4, 4, "0", "idle", "I'm\u{0020}not\u{0020}as\u{0020}sensitive\u{0020}as\u{0020}Lilith...\u{0020}However,\u{0020}I\u{0020}can\u{0020}sense\u{0020}the\u{0020}feelings\u{0020}of\u{0020}the\u{0020}people\u{0020}around\u{0020}me.\u{0020}Good\u{0020}or\u{0020}bad,\u{0020}I\u{0020}can\u{0020}sense\u{0020}all\u{0020}of\u{0020}them.\u{0020}Navigator,\u{0020}can\u{0020}you,\u{0020}too...?", "0", "我不像莉莉絲那孩子那麼敏感…不過，我也能感受到周圍人的感情。好的，壞的，我全部都能感受到。領航，您也是這樣嗎…？", "0", "0", "0", "cv_morgan_3", "0", "0"},
[400904] = {400904, 10009, 5, 4, "0", "idle", "Navigator,\u{0020}you\u{0020}seem\u{0020}very\u{0020}tired...\u{0020}Wouldn't\u{0020}it\u{0020}be\u{0020}better\u{0020}to\u{0020}take\u{0020}a\u{0020}rest?", "0", "領航，您好像很累的樣子…還是休息一下比較好吧？", "0", "0", "0", "cv_morgan_4", "0", "0"},
[400905] = {400905, 10009, 6, 4, "0", "idle", "Skadi...\u{0020}I\u{0020}met\u{0020}her\u{0020}seven\u{0020}years\u{0020}ago.\u{0020}What\u{0020}happened\u{0020}then...\u{0020}No,\u{0020}it's\u{0020}nothing.\u{0020}Please\u{0020}don't\u{0020}mind.", "0", "斯卡蒂…我和她是七年前認識的，那時發生的事情…不，沒什麼，請不要在意。", "0", "0", "0", "cv_morgan_30", "0", "0"},
[400906] = {400906, 10009, 7, 5, "1_》_0_0.8", "level1", "I\u{0020}want\u{0020}to\u{0020}ensure\u{0020}the\u{0020}happiness\u{0020}of\u{0020}everyone...\u{0020}I\u{0020}want\u{0020}all\u{0020}the\u{0020}unfortunate\u{0020}people\u{0020}to\u{0020}live\u{0020}a\u{0020}happy\u{0020}life.\u{0020}This\u{0020}is\u{0020}the\u{0020}reason\u{0020}why\u{0020}I\u{0020}fight...\u{0020}Is\u{0020}it...\u{0020}weird?", "0", "我想守護所有人的幸福…想要所有不幸的人都能過上正常的，幸福的生活。這就是我戰鬥的理由…那個…很…奇怪嗎？", "0", "0", "0", "cv_morgan_31", "0", "0"},
[400907] = {400907, 10009, 8, 5, "1_》_0_0.8", "level1", "There\u{0020}are\u{0020}always\u{0020}lovely\u{0020}children\u{0020}around\u{0020}Navigator.\u{0020}Everyone\u{0020}trusts\u{0020}you\u{0020}a\u{0020}lot,\u{0020}Navigator.", "0", "領航的身邊總是聚集著很多可愛的孩子呢，大家都很信賴您，領航。", "0", "0", "0", "cv_morgan_5", "0", "0"},
[400908] = {400908, 10009, 9, 5, "1_》_100_1.5", "level2", "Navigator,\u{0020}want\u{0020}to\u{0020}see\u{0020}a\u{0020}magic\u{0020}trick?\u{0020}\"Card\u{0020}magic\",\u{0020}\"Top\u{0020}hat\u{0020}magic\"\u{0020}and\u{0020}such,\u{0020}hehehe...", "0", "領航，您想看魔術嗎？“紙牌魔術”啊，“禮帽魔術”之類的，嘿嘿嘿……", "0", "0", "0", "cv_morgan_6", "0", "0"},
[400909] = {400909, 10009, 10, 5, "1_》_500_2", "level3", "My\u{0020}magic\u{0020}was\u{0020}learned\u{0020}from\u{0020}my\u{0020}parents.\u{0020}Before,\u{0020}as\u{0020}long\u{0020}as\u{0020}they\u{0020}performed\u{0020}magic,\u{0020}everyone\u{0020}would\u{0020}be\u{0020}smiling\u{0020}happily.\u{0020}I\u{0020}also\u{0020}want...\u{0020}to\u{0020}make\u{0020}everyone\u{0020}smile.", "0", "我的魔術，是從父母那裏學來的。以前，只要他們表演魔術，大家就會露出幸福的笑容。我也想…讓大家都能綻放笑容。", "0", "0", "0", "cv_morgan_7", "0", "0"},
[400910] = {400910, 10009, 11, 5, "1_》_1000_2.5", "level4", "The\u{0020}reason\u{0020}why\u{0020}everyone\u{0020}trusts\u{0020}Navigator\u{0020}so\u{0020}much...\u{0020}I\u{0020}understand\u{0020}now.\u{0020}I\u{0020}want\u{0020}to\u{0020}rely\u{0020}on\u{0020}Navigator\u{0020}more,\u{0020}and\u{0020}stay\u{0020}by\u{0020}Navigator's\u{0020}side.\u{0020}I\u{0020}am\u{0020}the\u{0020}same\u{0020}as\u{0020}everyone.", "0", "大家如此信賴領航的理由…現在的我已經完全明白了。想要更加依賴領航，想要陪伴在領航身邊，這份心情，我和大家是一樣的。", "0", "0", "0", "cv_morgan_8", "0", "0"},
[400911] = {400911, 10009, 12, 6, "0", "0", "Thank\u{0020}you.\u{0020}Now\u{0020}I\u{0020}have\u{0020}become\u{0020}stronger.", "0", "謝謝，這下變得更強了呢。", "0", "0", "0", "cv_morgan_9", "0", "0"},
[400912] = {400912, 10009, 13, 7, "0", "0", "Thank\u{0020}you...\u{0020}I\u{0020}won't\u{0020}let\u{0020}you\u{0020}down.", "0", "謝謝…我一定不會辜負領航您的期望的。", "0", "0", "0", "cv_morgan_10", "0", "0"},
[400913] = {400913, 10009, 14, 8, "0", "0", "Without\u{0020}realizing\u{0020}it,\u{0020}I've\u{0020}grown\u{0020}so\u{0020}much.\u{0020}I\u{0020}couldn't\u{0020}have\u{0020}done\u{0020}it\u{0020}alone—thank\u{0020}you,\u{0020}Navigator.\u{0020}Together,\u{0020}let's\u{0020}protect\u{0020}everyone\u{0020}from\u{0020}here\u{0020}on\u{0020}out.", "0", "不知不覺我也成長了許多…如果沒有領航的話，我一個人是不可能做到的。謝謝您，領航，今後也和我一起守護大家吧。", "0", "0", "0", "cv_morgan_11", "0", "0"},
[400914] = {400914, 10009, 15, 9, "0", "0", "I'll\u{0020}make\u{0020}good\u{0020}use\u{0020}of\u{0020}this\u{0020}power.", "0", "這份力量，我會好好使用的。", "0", "0", "0", "cv_morgan_12", "0", "0"},
[400915] = {400915, 10009, 16, 10, "0", "0", "The\u{0020}one\u{0020}who\u{0020}hurt\u{0020}my\u{0020}friends...\u{0020}Where\u{0020}are\u{0020}they?", "0", "傷害同伴的人…在哪？", "0", "0", "0", "cv_morgan_13", "0", "0"},
[400916] = {400916, 10009, 17, 11, "0", "0", "All\u{0020}enemies\u{0020}eliminated.\u{0020}We\u{0020}did\u{0020}it,\u{0020}Navigator.", "0", "敵人全滅，我們勝利了，領航。", "0", "0", "0", "cv_morgan_14", "0", "0"},
[400917] = {400917, 10009, 18, 12, "0", "0", "I\u{0020}have\u{0020}to\u{0020}do\u{0020}better...", "0", "我需要得做更好才行…不然……", "0", "0", "0", "cv_morgan_15", "0", "0"},
