[400919] = {400919, 10009, 20, 14, "0", "0", "...\u{0020}Stay\u{0020}strong,\u{0020}Navigator.\u{0020}We're\u{0020}not\u{0020}done\u{0020}yet.", "0", "…振作起來，領航，還沒有結束。", "0", "0", "0", "cv_morgan_17", "0", "0"},
