[400936] = {400936, 10009, 38, 30, "0", "0", "We\u{0020}should\u{0020}prepare\u{0020}gifts\u{0020}for\u{0020}our\u{0020}new\u{0020}companions.", "0", "要為新來的同伴準備禮物才行。", "0", "0", "0", "cv_morgan_37", "0", "0"},
