[401000] = {401000, 10010, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_alaita_32", "0", "0"},
[401001] = {401001, 10010, 2, 2, "0", "0", "Don't\u{0020}get\u{0020}too\u{0020}captivated\u{0020}by\u{0020}me—we've\u{0020}still\u{0020}got\u{0020}work\u{0020}to\u{0020}do.", "あまり見惚れないで。仕事に支障を来すわよ。", "可不要看我看入迷了喔，那樣會耽誤工作的。", "0", "可不要看我看入迷了哦，那样会耽误工作的。", "0", "cv_alaita_2", "0", "0"},
[401002] = {401002, 10010, 3, 3, "0", "0", "Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad,\u{0020}Alaita.\u{0020}Captain\u{0020}Dolores\u{0020}of\u{0020}my\u{0020}family\u{0020}has\u{0020}been\u{0020}taken\u{0020}good\u{0020}care\u{0020}of\u{0020}by\u{0020}you.\u{0020}Thank\u{0020}you~", "第三研究室防衛班、アライタ。うちのドロリィス隊長が世話になったようね。礼を言うわ。", "第三研究室防衛班，阿萊塔。我家的多洛莉絲隊長受你照顧了，謝謝~", "0", "第三研究室防卫班，阿莱塔。我家的多洛莉丝队长受你照顾了，谢谢~", "0", "cv_alaita_1", "0", "0"},
[401003] = {401003, 10010, 4, 4, "0", "idle", "\"Siren\"?\u{0020}Some\u{0020}people\u{0020}do\u{0020}call\u{0020}me\u{0020}that...\u{0020}But,\u{0020}my\u{0020}singing\u{0020}isn't\u{0020}that\u{0020}good,\u{0020}you\u{0020}know?", "セイレーン？私をそう呼ぶ者もいるけど……私の歌はそんなに上手くないわよ？", "“海妖”？的確有人這麼叫我啦…不過，我唱歌並沒有那麼好聽喔？", "0", "“海妖”？的确有人这么叫我啦…不过，我唱歌并没有那么好听噢？", "0", "cv_alaita_3", "0", "0"},
[401004] = {401004, 10010, 5, 4, "0", "idle", "Don't\u{0020}you\u{0020}think\u{0020}those\u{0020}fleeting\u{0020}beauties\u{0020}are\u{0020}always\u{0020}fascinating?\u{0020}Of\u{0020}course,\u{0020}this\u{0020}includes\u{0020}myself.", "一瞬の美しさには、目を奪われてしまうものよ。勿論、私のことも、ね。", "你不覺得那些轉瞬即逝的美麗總是讓人著迷嗎？當然，這其中也包括我自己。", "0", "你不觉得那些转瞬即逝的美丽总是让人着迷吗？当然，这其中也包括我自己。", "0", "cv_alaita_4", "0", "0"},
[401005] = {401005, 10010, 6, 4, "0", "idle", "Captain\u{0020}Dolores~\u{0020}Captain\u{0020}Dolores~\u{0020}Ah...\u{0020}She's\u{0020}not\u{0020}here.\u{0020}Then\u{0020}I'll\u{0020}give\u{0020}these\u{0020}documents\u{0020}to\u{0020}her\u{0020}next\u{0020}time.\u{0020}Slacking\u{0020}off?\u{0020}No\u{0020}no\u{0020}no,\u{0020}there's\u{0020}nothing\u{0020}I\u{0020}can\u{0020}do\u{0020}about\u{0020}it.", "ドロリィス隊長？……ドロリィス隊長？……あら、いないの。じゃあこのファイルを渡すのは今度ね。……サボり？いいえ、これは仕方のないことよ。", "多洛莉絲隊長~多洛莉絲隊長~啊…不在啊，那下次再把這些文檔交給她吧。偷懶？不不不，這是沒辦法的事吧。", "0", "多洛莉丝队长~多洛莉丝队长~啊…不在啊，那下次再把这些文件交给她吧。偷懒？不不不，这是没办法的事吧。", "0", "cv_alaita_29", "0", "0"},
[401006] = {401006, 10010, 7, 5, "1_》_0_0.8", "level1", "Heya,\u{0020}I\u{0020}was\u{0020}just\u{0020}looking\u{0020}for\u{0020}you\u{0020}too.\u{0020}I\u{0020}have\u{0020}a\u{0020}show\u{0020}tomorrow\u{0020}morning.\u{0020}Will\u{0020}you\u{0020}come\u{0020}to\u{0020}watch?\u{0020}After\u{0020}the\u{0020}performance,\u{0020}we\u{0020}can\u{0020}go\u{0020}have\u{0020}a\u{0020}cup\u{0020}of\u{0020}tea\u{0020}together.", "あら、ちょうど探していたのよ。明日、私の舞台があるの。見に来ない？それで終わったら、一緒にお茶でもどうかしら。", "欸呀，我正好也在找您呢。明天早上有我的演出，要來看看嗎？等演出結束之後，我們正好可以一起去喝杯茶。", "0", "哎呀，我正好也在找您呢。明天早上有我的演出，要来看看吗？等演出结束之后，我们正好可以一起去喝杯茶。", "0", "cv_alaita_30", "0", "0"},
[401007] = {401007, 10010, 8, 5, "1_》_0_0.8", "level1", "It's\u{0020}bad\u{0020}to\u{0020}flirt\u{0020}with\u{0020}someone\u{0020}you\u{0020}just\u{0020}met.", "知り合ったばかりの女性に手を出すのは感心しないわ。", "對認識不久的異性出手，可不太好喔。", "0", "对认识不久的异性出手，可不太好噢。", "0", "cv_alaita_5", "0", "0"},
[401008] = {401008, 10010, 9, 5, "1_》_100_1.5", "level2", "It\u{0020}is\u{0020}said\u{0020}that\u{0020}\"sirens\"\u{0020}can\u{0020}bring\u{0020}misfortune\u{0020}on\u{0020}the\u{0020}sea.\u{0020}Then\u{0020}you'd\u{0020}better\u{0020}not\u{0020}be\u{0020}too\u{0020}close\u{0020}to\u{0020}me...\u{0020}You\u{0020}don't\u{0020}care?\u{0020}So\u{0020}be\u{0020}it...\u{0020}Hehe.", "伝説のセイレーンは海で不幸をもたらすもの。あまり私に近づかない方がいいわよ。……そんなの気にしないって？そう……フフ。", "據說，“海妖”在大海上可是會招來不幸的。那你最好不要和我太親近了……你不在乎嗎？是這樣啊…呵呵。", "0", "据说，“海妖”在大海上可是会招来不幸的。那你最好不要和我太亲近了……你不在乎吗？是这样啊…呵呵。", "0", "cv_alaita_6", "0", "0"},
[401009] = {401009, 10010, 10, 5, "1_》_500_2", "level3", "Heh,\u{0020}even\u{0020}you,\u{0020}Navigator,\u{0020}are\u{0020}charmed\u{0020}by\u{0020}my\u{0020}beauty?\u{0020}Then,\u{0020}please\u{0020}protect\u{0020}me\u{0020}well,\u{0020}Navigator~\u{0020}I\u{0020}will\u{0020}also\u{0020}protect\u{0020}you~", "あら。ナビゲーターも私の美しさの虜になったのかしら。それじゃあ、ちゃんと私を守ってちょうだい。私もあなたを守るから。", "呵，連領航你也被我的美色迷惑了嗎？那麼，就請好好守護我吧，領航~我也會保護你的~", "0", "呵，连领航你也被我的美色迷惑了吗？那么，就请好好守护我吧，领航~我也会保护你的~", "0", "cv_alaita_7", "0", "0"},
[401010] = {401010, 10010, 11, 5, "1_》_1000_2.5", "level4", "My\u{0020}life\u{0020}only\u{0020}needs\u{0020}to\u{0020}be\u{0020}like\u{0020}an\u{0020}epiphyllum.\u{0020}After\u{0020}all,\u{0020}eternity\u{0020}will\u{0020}only\u{0020}fade\u{0020}the\u{0020}beauty.\u{0020}Navigator,\u{0020}now,\u{0020}enjoy\u{0020}this\u{0020}short\u{0020}beauty\u{0020}with\u{0020}me.", "私の人生は、花や朝露のように一瞬でいいの。美しさなんて色褪せるだけだもの。さぁナビゲーター。この束の間の美しさを、私と一緒に楽しんでちょうだい。", "我的人生只需如曇花與朝露那樣便好，畢竟，永恆只會讓美麗褪色。領航，現在，就與我一起享受這份短暫的美好吧。", "0", "我的人生只需如昙花与朝露那样便好，毕竟，永恒只会让美丽褪色。领航，现在，就与我一起享受这份短暂的美好吧。", "0", "cv_alaita_8", "0", "0"},
[401011] = {401011, 10010, 12, 6, "0", "0", "Nice\u{0020}feeling.", "いい感じね。", "不錯的感覺。", "0", "不错的感觉。", "0", "cv_alaita_9", "0", "0"},
[401012] = {401012, 10010, 13, 7, "0", "0", "Do\u{0020}you\u{0020}want\u{0020}to\u{0020}see\u{0020}an\u{0020}even\u{0020}grander\u{0020}show?", "もっと煌びやかにしてもいいんじゃない？", "想看更華麗的演出嗎？", "0", "想看更华丽的演出吗？", "0", "cv_alaita_10", "0", "0"},
[401013] = {401013, 10010, 14, 8, "0", "0", "Hehe...\u{0020}Can\u{0020}you\u{0020}hear\u{0020}it?\u{0020}My\u{0020}sword\u{0020}sings\u{0020}not\u{0020}of\u{0020}my\u{0020}beauty\u{0020}but\u{0020}of\u{0020}its\u{0020}excitement—it's\u{0020}thrilled\u{0020}to\u{0020}defend\u{0020}Danube\u{0020}and\u{0020}Saar\u{0020}again.", "ふふ……この剣の喜びが聞こえるかしら？私の美しさはもとより、再びダニューブやサールを守ることができる喜びに違いないわ。", "呵呵……你能感受到嗎，這把劍正在發出喜悅的鳴聲呢。不，並不是在稱讚我的美麗。它一定是因為能夠再一次保護多瑙，保護薩爾而高興吧。", "0", "呵呵……你能感受到吗，这把剑正在发出喜悦的鸣声呢。不，并不是在称赞我的美丽。它一定是因为能够再一次保护多瑙，保护萨尔而高兴吧。", "0", "cv_alaita_11", "0", "0"},
[401014] = {401014, 10010, 15, 9, "0", "0", "Make\u{0020}me\u{0020}even\u{0020}more\u{0020}dazzling.", "もっと美しくしてちょうだい。", "讓我變得更加美麗吧。", "0", "让我变得更加美丽吧。", "0", "cv_alaita_12", "0", "0"},
[401015] = {401015, 10010, 16, 10, "0", "0", "I'll\u{0020}handle\u{0020}the\u{0020}show;\u{0020}you\u{0020}handle\u{0020}the\u{0020}applause!", "私は舞台に。あなたは喝采を！", "我負責表演，你負責喝彩！", "0", "我负责表演，你负责喝彩！", "0", "cv_alaita_13", "0", "0"},
[401016] = {401016, 10010, 17, 11, "0", "0", "Shower\u{0020}me\u{0020}with\u{0020}praise,\u{0020}adoration—and\u{0020}then\u{0020}let\u{0020}yourself\u{0020}fall\u{0020}for\u{0020}me.", "讃えよ、讃えよ。そして私の虜になるのよ。", "誇讚我吧，稱讚我吧，然後迷戀上我吧。", "0", "夸赞我吧，称赞我吧，然后迷恋上我吧。", "0", "cv_alaita_14", "0", "0"},
[401017] = {401017, 10010, 18, 12, "0", "0", "Well,\u{0020}Navigator,\u{0020}enough\u{0020}daydreaming.\u{0020}Let's\u{0020}get\u{0020}back\u{0020}to\u{0020}reality.", "まあまあね。……ナビゲーター、ボーッとしてないで帰るわよ。", "馬馬虎虎…領航，別發呆了，回去了。", "0", "马马虎虎…领航，别发呆了，回去了。", "0", "cv_alaita_15", "0", "0"},
[401018] = {401018, 10010, 19, 13, "0", "0", "...\u{0020}Hmm,\u{0020}well,\u{0020}I\u{0020}guess\u{0020}that\u{0020}counts\u{0020}as\u{0020}getting\u{0020}the\u{0020}job\u{0020}done,\u{0020}right?", "……まあ、とりあえず良しとするわ。", "…嗯，這也算是完成工作了吧？", "0", "…嗯，这也算是完成工作了吧？", "0", "cv_alaita_16", "0", "0"},
[401019] = {401019, 10010, 20, 14, "0", "0", "What\u{0020}a\u{0020}disaster...\u{0020}wouldn't\u{0020}you\u{0020}agree?", "うーん……出来の悪い舞台ね。そう思わない？", "嗯…真是一場失敗的演出，你不這樣認為嗎？", "0", "嗯…真是一场失败的演出，你不这样认为吗？", "0", "cv_alaita_17", "0", "0"},
[401020] = {401020, 10010, 21, 15, "0", "0", "Time\u{0020}for\u{0020}you\u{0020}to\u{0020}leave\u{0020}the\u{0020}stage.", "退場して。", "你該退場了。", "0", "你该退场了。", "0", "cv_alaita_18", "0", "0"},
[401021] = {401021, 10010, 23, 16, "0", "0", "My\u{0020}turn!", "私の番よ！", "到我了！", "0", "到我了！", "0", "cv_alaita_19", "0", "0"},
[401022] = {401022, 10010, 24, 17, "0", "0", "Revel\u{0020}in\u{0020}my\u{0020}performance!", "酔いしれるがいいわ！", "陶醉吧！", "0", "陶醉吧！", "0", "cv_alaita_21", "0", "0"},
[401023] = {401023, 10010, 26, 19, "0", "0", "Is\u{0020}this...\u{0020}The\u{0020}curtain\u{0020}call...", "これで…終幕……", "這是…謝幕嗎……", "0", "这是…谢幕吗……", "0", "cv_alaita_20", "0", "0"},
[401024] = {401024, 10010, 27, 20, "0", "0", "Oh?\u{0020}Didn't\u{0020}see\u{0020}you\u{0020}coming.", "あら、来たの？", "喔？你來了啊。", "0", "噢？你来了啊。", "0", "cv_alaita_22", "0", "0"},
[401025] = {401025, 10010, 28, 21, "0", "0", "Are\u{0020}you\u{0020}entranced?\u{0020}Don't\u{0020}be\u{0020}shy—compliment\u{0020}my\u{0020}beauty.", "見とれてるの？遠慮しないで、私の美しさを存分に讃えてちょうだい。", "看入迷了嗎？不用害羞，稱讚我的美麗吧。", "0", "看入迷了吗？不用害羞，称赞我的美丽吧。", "0", "cv_alaita_23", "0", "0"},
[401026] = {401026, 10010, 29, 21, "0", "0", "I\u{0020}can't\u{0020}help\u{0020}but\u{0020}hum\u{0020}a\u{0020}tune...\u{0020}Have\u{0020}you\u{0020}brought\u{0020}wax\u{0020}to\u{0020}seal\u{0020}your\u{0020}ears?", "なんだか歌いたくなる気分よ。……あなた、耳栓は持ってるかしら？", "情不自禁想哼歌呢…你準備了蠟來封耳朵嗎？", "0", "情不自禁想哼歌呢…你准备了蜡来封耳朵吗？", "0", "cv_alaita_24", "0", "0"},
[401027] = {401027, 10010, 30, 22, "0", "0", "Heh...\u{0020}Always\u{0020}stay\u{0020}sharp,\u{0020}right?", "ふぅん……警戒すればいいのね？", "呵…提高警惕，對嗎？", "0", "呵…提高警惕，对吗？", "0", "cv_alaita_25", "0", "0"},
[401028] = {401028, 10010, 31, 23, "0", "0", "This\u{0020}curtain\u{0020}can't\u{0020}hide\u{0020}my\u{0020}starlight,\u{0020}can\u{0020}it?", "こんなもので私の美しさは隠せないわ。でしょ？", "這點幕布是遮擋不了我的星光的，對吧？", "0", "这点幕布是遮挡不了我的星光的，对吧？", "0", "cv_alaita_26", "0", "0"},
[401029] = {401029, 10010, 32, 24, "0", "0", "Well\u{0020}done,\u{0020}Navigator.\u{0020}Unfortunately,\u{0020}no\u{0020}reward\u{0020}this\u{0020}time.", "悪くないわ。でもご褒美はないの。残念ね。", "不愧是領航~遺憾的是，沒有獎勵喔。", "0", "不愧是领航~遗憾的是，没有奖励噢。", "0", "cv_alaita_27", "0", "0"},
[401030] = {401030, 10010, 33, 25, "0", "0", "Try\u{0020}harder\u{0020}next\u{0020}time.", "次は頑張って…", "下次再努力吧。", "0", "下次再努力吧。", "0", "cv_alaita_28", "0", "0"},
[401031] = {401031, 10010, 34, 26, "0", "0", "Good\u{0020}morning,\u{0020}Navigator.\u{0020}Here's\u{0020}some\u{0020}rose\u{0020}tea\u{0020}for\u{0020}you.\u{0020}Take\u{0020}your\u{0020}time\u{0020}and\u{0020}enjoy\u{0020}it.", "おはよう、ナビゲーター。あなたのためにローズティーを淹れてあげたわ。どうぞ。", "早上好，領航，這是為您準備的玫瑰茶，還請慢用。", "0", "早上好，领航，这是为您准备的玫瑰茶，还请慢用。", "0", "cv_alaita_31", "0", "0"},
[401032] = {401032, 10010, 35, 27, "0", "0", "Is\u{0020}it\u{0020}time\u{0020}for\u{0020}the\u{0020}mission?\u{0020}Understood,\u{0020}let's\u{0020}go.", "ミッション？いいわよ。出発するわ。", "要執行任務了？我明白了，出發吧。", "0", "要执行任务了？我明白了，出发吧。", "0", "cv_alaita_33", "0", "0"},
[401033] = {401033, 10010, 36, 28, "0", "0", "Finish\u{0020}early\u{0020}and\u{0020}rest\u{0020}early.", "さっさと終わらせて、お茶にしましょ。", "早點完成，早點休息~", "0", "早点完成，早点休息~", "0", "cv_alaita_34", "0", "0"},
[401034] = {401034, 10010, 37, 29, "0", "0", "Hello,\u{0020}everyone!", "皆さん、どうぞよろしく。", "嗨，大家好~！", "0", "嗨，大家好~！", "0", "cv_alaita_35", "0", "0"},
[401035] = {401035, 10010, 38, 30, "0", "0", "Are\u{0020}new\u{0020}companions\u{0020}joining\u{0020}us?", "新しい仲間を増やすのかしら？", "要增加新的同伴嗎？", "0", "要增加新的同伴吗？", "0", "cv_alaita_36", "0", "0"},
[401036] = {401036, 10010, 39, 31, "0", "0", "Will\u{0020}we\u{0020}be\u{0020}purchasing\u{0020}new\u{0020}equipment?", "新しい装備を増やすのかしら？", "要採購新裝備了嗎？", "0", "要采购新装备了吗？", "0", "cv_alaita_37", "0", "0"},
[401037] = {401037, 10010, 40, 32, "0", "0", "Need\u{0020}some\u{0020}pocket\u{0020}money?", "お小遣いが欲しいの？", "需要零花錢嗎？", "0", "需要零花钱吗？", "0", "cv_alaita_38", "0", "0"},
[401038] = {401038, 10010, 41, 33, "0", "0", "Smile.", "笑顔になって。", "笑一下？", "0", "笑一下？", "0", "cv_alaita_39", "0", "0"},
[401039] = {401039, 10010, 42, 34, "0", "0", "Doesn't\u{0020}matter.", "好きにして。", "隨便吧。", "0", "随便吧。", "0", "cv_alaita_40", "0", "0"},
[401040] = {401040, 10010, 43, 35, "0", "0", "Is\u{0020}there\u{0020}an\u{0020}invitation\u{0020}letter?", "招待状はあるかしら？", "有邀請函嗎？", "0", "有邀请函吗？", "0", "cv_alaita_41", "0", "0"},
[401041] = {401041, 10010, 44, 36, "0", "0", "Remember\u{0020}to\u{0020}exchange\u{0020}contact\u{0020}info\u{0020}when\u{0020}you\u{0020}meet\u{0020}someone\u{0020}you\u{0020}like.", "気に入った人とは連絡先の交換を忘れずにね。", "遇到喜歡的人記得要聯繫方式喔。", "0", "遇到喜欢的人记得要联系方式哦。", "0", "cv_alaita_42", "0", "0"},
[401042] = {401042, 10010, 45, 37, "0", "0", "Humph.", "ふーん。", "吼~", "0", "嚯~", "0", "cv_alaita_43", "0", "0"},
[401100] = {401100, 10011, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_ruoshui_32", "0", "0"},
[401101] = {401101, 10011, 2, 2, "0", "0", "Yes,\u{0020}I'll\u{0020}always\u{0020}be\u{0020}here,\u{0020}waiting\u{0020}for\u{0020}your\u{0020}next\u{0020}order,\u{0020}Navigator.", "はい、次の命令までここで待ってますね。ナビゲーターのお兄さん。", "是，我會一直站在這等待您下一個命令的，領航哥哥。", "0", "是，我会一直站在这等待您下一个命令的，领航哥哥。", "0", "cv_ruoshui_2", "0", "0"},
[401102] = {401102, 10011, 3, 3, "0", "0", "My\u{0020}name\u{0020}is\u{0020}Jacksui...\u{0020}My\u{0020}eyes?\u{0020}It\u{0020}doesn't\u{0020}matter.\u{0020}As\u{0020}long\u{0020}as\u{0020}I\u{0020}can\u{0020}see\u{0020}you,\u{0020}Brother\u{0020}Navigator.", "私の名前は弱水です。……私の目ですか？大丈夫です。ちゃんと見えてますよ、ナビゲーターのお兄さん。", "我的名字是弱水…眼睛？沒關係，我能看見您的，領航哥哥。", "0", "我的名字是弱水…眼睛？没关系，我能看见您的，领航哥哥。", "0", "cv_ruoshui_1", "0", "0"},
[401103] = {401103, 10011, 4, 4, "0", "idle", "My\u{0020}eyes...\u{0020}even\u{0020}though\u{0020}I\u{0020}can\u{0020}see,\u{0020}it\u{0020}feels\u{0020}like\u{0020}the\u{0020}\"world\"\u{0020}I\u{0020}see\u{0020}is\u{0020}different\u{0020}from\u{0020}everyone\u{0020}else’s…\u{0020}But\u{0020}I\u{0020}guess\u{0020}there's\u{0020}nothing\u{0020}I\u{0020}can\u{0020}do\u{0020}about\u{0020}that.", "見えてはいるのですが、皆さんが見ている世界とは違うのだそうです。……まあ、それも仕方ないですね。", "我的眼睛…雖然看得見，但是好像和大家看到的“世界”不一樣…不過這也是沒辦法的事吧？", "0", "我的眼睛…虽然看得见，但是好像和大家看到的“世界”不一样…不过这也是没办法的事吧？", "0", "cv_ruoshui_3", "0", "0"},
[401104] = {401104, 10011, 5, 4, "0", "idle", "Brother\u{0020}Navigator,\u{0020}did\u{0020}you\u{0020}catch\u{0020}that\u{0020}TV\u{0020}drama\u{0020}yesterday?\u{0020}It\u{0020}wasn’t\u{0020}the\u{0020}best,\u{0020}but\u{0020}their\u{0020}passion\u{0020}to\u{0020}make\u{0020}something\u{0020}good\u{0020}really\u{0020}moved\u{0020}me!\u{0020}Huh?\u{0020}You\u{0020}didn’t\u{0020}watch\u{0020}it?", "ナビゲーターのお兄さん、昨日のテレビドラマは見ましたか？色々な意味で最悪なドラマでしたが、良い作品を作ろうという姿勢にすごく感動したんです！えぇ？見てないんですか！？", "領航哥哥，昨天的電視劇你看了嗎？那部電視劇雖然各種地方都很爛，但他們想要拍好一部作品的決心卻讓我超感動的！欸？沒看嗎？", "0", "领航哥哥，昨天的电视剧你看了吗？那部电视剧虽然各种地方都很烂，但他们想要拍好一部作品的决心却让我超感动的！诶？没看吗？", "0", "cv_ruoshui_4", "0", "0"},
[401105] = {401105, 10011, 6, 4, "0", "idle", "Meika!\u{0020}Meika!\u{0020}Hmm?\u{0020}She's\u{0020}not\u{0020}here...\u{0020}Whenever\u{0020}she\u{0020}doesn’t\u{0020}have\u{0020}a\u{0020}mission,\u{0020}it’s\u{0020}like\u{0020}she\u{0020}vanishes.\u{0020}So\u{0020}mysterious…\u{0020}I\u{0020}wanted\u{0020}to\u{0020}hang\u{0020}out\u{0020}with\u{0020}her!", "冥火ー？冥火ー？あれ？いない……任務がないとすぐいなくなっちゃうんだから。……一緒に遊ぼうって思ってたのに！", "冥火！冥火！嗯？她不在這裡嗎…欸，她只要沒有任務的時候，感覺就跟消失了一樣，真神秘呢…我還想找她玩呢！", "0", "冥火！冥火！嗯？她不在这里吗…诶，她只要没有任务的时候，感觉就跟消失了一样，真神秘呢…我还想找她玩呢！", "0", "cv_ruoshui_29", "0", "0"},
[401106] = {401106, 10011, 7, 5, "1_》_0_0.8", "level1", "In\u{0020}the\u{0020}past...\u{0020}I\u{0020}lost\u{0020}my\u{0020}sight,\u{0020}along\u{0020}with\u{0020}my\u{0020}friends\u{0020}and\u{0020}family.\u{0020}But\u{0020}that’s\u{0020}all\u{0020}behind\u{0020}me\u{0020}now.\u{0020}Now,\u{0020}I\u{0020}just\u{0020}want\u{0020}to\u{0020}do\u{0020}my\u{0020}best\u{0020}to\u{0020}help\u{0020}everyone!", "ここに来る前に……視力も、友達も、家族も失いました。……でも、それはもう過ぎたことです。今はただ、出来る限りみんなの助けになりたいんです！", "以前…因為一些原因，我失去了視力，也因此失去了自己的朋友和家人…不過，一切都過去了，現在的我，只想盡自己所能地幫助大家！", "0", "以前…因为一些原因，我失去了视力，也因此失去了自己的朋友和家人…不过，一切都过去了，现在的我，只想尽自己所能地帮助大家！", "0", "cv_ruoshui_30", "0", "0"},
[401107] = {401107, 10011, 8, 5, "1_》_0_0.8", "level1", "My\u{0020}eye\u{0020}patch\u{0020}is\u{0020}not\u{0020}a\u{0020}play\u{0020}toy,\u{0020}Brother\u{0020}Navigator!", "ちょっと、眼帯に…勝手に触らないでください！", "領航哥哥，眼罩…您別亂碰它呀！", "0", "领航哥哥，眼罩…您别乱碰它呀！", "0", "cv_ruoshui_5", "0", "0"},
[401108] = {401108, 10011, 9, 5, "1_》_100_1.5", "level2", "Brother\u{0020}Navigator!\u{0020}Let's\u{0020}go\u{0020}out\u{0020}and\u{0020}have\u{0020}some\u{0020}fun.\u{0020}I\u{0020}want\u{0020}to\u{0020}go\u{0020}to\u{0020}the\u{0020}amusement\u{0020}park!", "お兄さんお兄さん、一緒に出かけましょう。遊園地がいいです！", "哥哥，哥哥，我們一起出去玩吧，我想去遊樂場玩！", "0", "哥哥，哥哥，我们一起出去玩吧，我想去游乐场玩！", "0", "cv_ruoshui_6", "0", "0"},
[401109] = {401109, 10011, 10, 5, "1_》_500_2", "level3", "Hey,\u{0020}Brother\u{0020}Navigator,\u{0020}let's\u{0020}go\u{0020}to\u{0020}the\u{0020}movies.\u{0020}First,\u{0020}we'll\u{0020}need\u{0020}to\u{0020}get\u{0020}drinks\u{0020}and\u{0020}popcorn...\u{0020}Eh,\u{0020}like\u{0020}a\u{0020}date?\u{0020}A\u{0020}date,\u{0020}huh...\u{0020}that\u{0020}wouldn't\u{0020}be\u{0020}impossible.", "お兄さん、一緒に映画を見に行きましょう。まず飲み物とポップコーンを買って……え、デートみたい？……デ、デートはダメ……じゃないですけど……", "哥哥，我們一起去看電影吧，首先要做的是去買飲料、爆米花…欸，像約會一樣？……約、約會的話，也不是不行啦。", "0", "哥哥，我们一起去看电影吧，首先要做的是去买饮料、爆米花…诶，像约会一样？……约、约会的话，也不是不行啦。", "0", "cv_ruoshui_7", "0", "0"},
[401110] = {401110, 10011, 11, 5, "1_》_1000_2.5", "level4", "Whenever\u{0020}I'm\u{0020}with\u{0020}you,\u{0020}it's\u{0020}like\u{0020}I\u{0020}don’t\u{0020}have\u{0020}to\u{0020}worry\u{0020}about\u{0020}being\u{0020}betrayed\u{0020}or\u{0020}you\u{0020}suddenly\u{0020}disappearing...\u{0020}and\u{0020}that’s\u{0020}enough\u{0020}for\u{0020}me.\u{0020}Please\u{0020}stay\u{0020}with\u{0020}me\u{0020}from\u{0020}forever,\u{0020}I\u{0020}can't\u{0020}stand\u{0020}a\u{0020}moment\u{0020}apart\u{0020}from\u{0020}you.", "お兄さんがナビゲーターなら、私を裏切ったり、ある日突然消えちゃうこともないですよね。……それで十分です。これからもずっと私のそばに居てください。私……お兄さんと離れるのは嫌なんです。", "是領航您的話，我不用擔心被背叛，也不用擔心你會突然消失吧…這樣就足夠了。領航，之後也請您一直陪著我吧，我…不想和您分開。", "0", "是领航您的话，我不用担心被背叛，也不用担心你会突然消失吧…这样就足够了。领航，之后也请您一直陪着我吧，我…不想和您分开。", "0", "cv_ruoshui_8", "0", "0"},
[401111] = {401111, 10011, 12, 6, "0", "0", "I\u{0020}leveled\u{0020}up!", "レベルアップしましたよ！", "我升級了欸！", "0", "我升级了诶！", "0", "cv_ruoshui_9", "0", "0"},
[401112] = {401112, 10011, 13, 7, "0", "0", "The\u{0020}weapon's\u{0020}sharper!", "武器が鋭くなりました！", "武器變鋒利了！", "0", "武器变锋利了！", "0", "cv_ruoshui_10", "0", "0"},
[401113] = {401113, 10011, 14, 8, "0", "0", "This\u{0020}is\u{0020}amazing...\u{0020}Power\u{0020}just\u{0020}keeps\u{0020}surging\u{0020}through\u{0020}me.\u{0020}Hmm,\u{0020}I've\u{0020}decided—this\u{0020}strength\u{0020}is\u{0020}for\u{0020}you,\u{0020}Navigator.\u{0020}From\u{0020}now\u{0020}on,\u{0020}no\u{0020}matter\u{0020}who\u{0020}the\u{0020}enemy\u{0020}is,\u{0020}\"Jacksui\"\u{0020}will\u{0020}take\u{0020}them\u{0020}down\u{0020}for\u{0020}you!", "不思議……力がどんどん湧いてきます。うん、決めました。この力、この強さはお兄さんだけのものです。これからどんな敵が現れようとも、お兄さんのために弱水が倒して見せます！", "真是不可思議呢…力量在源源不斷地湧出。嗯，決定了，這份力量，這份強大，只為領航您而存在。今後，不管是什麼樣的敵人，“弱水”都會為了您，將他擊潰！", "0", "真是不可思议呢…力量在源源不断地涌出。嗯，决定了，这份力量，这份强大，只为领航您而存在。今后，不管是什么样的敌人，“弱水”都会为了您，将他击溃！", "0", "cv_ruoshui_11", "0", "0"},
[401114] = {401114, 10011, 15, 9, "0", "0", "I'm\u{0020}faster\u{0020}now!", "もっと速くなりました！", "速度變快了！", "0", "速度变快了！", "0", "cv_ruoshui_12", "0", "0"},
[401115] = {401115, 10011, 16, 10, "0", "0", "Got\u{0020}it.\u{0020}Let's\u{0020}start\u{0020}the\u{0020}operation.", "了解、作戦開始。", "瞭解，作戰開始。", "0", "了解，作战开始。", "0", "cv_ruoshui_13", "0", "0"},
[401116] = {401116, 10011, 17, 11, "0", "0", "Mission\u{0020}complete—Navigator,\u{0020}let's\u{0020}head\u{0020}back.", "任務完了。……帰りましょう、お兄さん。", "任務完成——領航，我們回去吧。", "0", "任务完成——领航，我们回去吧。", "0", "cv_ruoshui_14", "0", "0"},
[401117] = {401117, 10011, 18, 12, "0", "0", "I'm\u{0020}fine...\u{0020}But\u{0020}there\u{0020}are\u{0020}others\u{0020}who\u{0020}need\u{0020}medical\u{0020}attention,\u{0020}Navigator.", "大丈夫です……私より、負傷者の方を……お兄さん……", "我沒事…但是有傷員需要治療，領航。", "0", "我没事…但是有伤员需要治疗，领航。", "0", "cv_ruoshui_15", "0", "0"},
[401118] = {401118, 10011, 19, 13, "0", "0", "Everyone...\u{0020}Are\u{0020}you\u{0020}all\u{0020}okay?", "みなさん…無事ですか？", "大家…還好嗎？", "0", "大家…还好吗？", "0", "cv_ruoshui_16", "0", "0"},
[401119] = {401119, 10011, 20, 14, "0", "0", "We\u{0020}can’t\u{0020}give\u{0020}up\u{0020}here,\u{0020}Navigator...", "お兄さん、諦めてはいけません……", "不能就這樣放棄，領航……", "0", "不能就这样放弃，领航……", "0", "cv_ruoshui_17", "0", "0"},
[401120] = {401120, 10011, 21, 15, "0", "0", "Enemy\u{0020}eliminated.", "撃破。", "已擊殺。", "0", "已击杀。", "0", "cv_ruoshui_18", "0", "0"},
[401121] = {401121, 10011, 23, 16, "0", "0", "The\u{0020}enemy...\u{0020}Must\u{0020}be\u{0020}destroyed.", "敵は…始末する。", "敵人…要殺死才行。", "0", "敌人…要杀死才行。", "0", "cv_ruoshui_19", "0", "0"},
[401122] = {401122, 10011, 24, 17, "0", "0", "Time\u{0020}to\u{0020}die.", "仕留める！", "解決你。", "0", "解决你。", "0", "cv_ruoshui_21", "0", "0"},
[401123] = {401123, 10011, 26, 19, "0", "0", "No...\u{0020}I\u{0020}can't...\u{0020}See\u{0020}anything.", "いや…何も…見えない……", "不要啊…什麼都…看不見了。", "0", "不要啊…什么都…看不见了。", "0", "cv_ruoshui_20", "0", "0"},
[401124] = {401124, 10011, 27, 20, "0", "0", "Bath\u{0020}time!\u{0020}Bath\u{0020}time!", "おふろ、おふろ～。", "泡澡~泡澡~", "0", "泡澡~泡澡~", "0", "cv_ruoshui_22", "0", "0"},
[401125] = {401125, 10011, 28, 21, "0", "0", "Navigator!\u{0020}There's\u{0020}a\u{0020}big\u{0020}white\u{0020}shark\u{0020}in\u{0020}the\u{0020}water—just\u{0020}kidding!", "お兄さん、お風呂の中に人食いザメが！……冗談ですよー。", "哥哥！水裡面有一條白色的大鯊魚——開玩笑的~", "0", "哥哥！水里面有一条白色的大鲨鱼——开玩笑的~", "0", "cv_ruoshui_23", "0", "0"},
[401126] = {401126, 10011, 29, 21, "0", "0", "Navigator,\u{0020}could\u{0020}you\u{0020}bring\u{0020}me\u{0020}a\u{0020}can\u{0020}of\u{0020}soda?\u{0020}Thanks!", "お兄さん、サイダーを取ってきてくれませんか？……ありがとうございます！", "哥哥，能幫我拿一聽碳酸飲料過來嗎~謝謝~", "0", "哥哥，能帮我拿一听碳酸饮料过来吗~谢谢~", "0", "cv_ruoshui_24", "0", "0"},
[401127] = {401127, 10011, 30, 22, "0", "0", "Is\u{0020}that\u{0020}the\u{0020}enemy?", "敵ですか！？", "是敵人嗎！？", "0", "是敌人吗！？", "0", "cv_ruoshui_25", "0", "0"},
[401128] = {401128, 10011, 31, 23, "0", "0", "Can\u{0020}you\u{0020}see\u{0020}me\u{0020}with\u{0020}your\u{0020}eyes?", "お兄さん、ちゃんと見えてます？", "您的眼睛，能看見我嗎？", "0", "您的眼睛，能看见我吗？", "0", "cv_ruoshui_26", "0", "0"},
[401129] = {401129, 10011, 32, 24, "0", "0", "Yes!\u{0020}You're\u{0020}the\u{0020}best!", "やったあ！お兄さん最高です！", "好耶！哥哥是最棒的！", "0", "好耶！哥哥是最棒的！", "0", "cv_ruoshui_27", "0", "0"},
[401130] = {401130, 10011, 33, 25, "0", "0", "I've\u{0020}been...\u{0020}betrayed...", "うぅ…裏切られました。", "嗚…被背叛了。", "0", "呜…被背叛了。", "0", "cv_ruoshui_28", "0", "0"},
[401131] = {401131, 10011, 34, 26, "0", "0", "Navigator,\u{0020}welcome\u{0020}back.\u{0020}While\u{0020}you\u{0020}were\u{0020}away,\u{0020}I\u{0020}also\u{0020}worked\u{0020}very\u{0020}hard!", "ナビゲーターのお兄さん、おかえりなさい。お兄さんがいない間もちゃんと頑張りましたよ！", "領航，歡迎回來，在你不在的時候，我也有好好努力喔！", "0", "领航，欢迎回来，在你不在的时候，我也有好好努力哦！", "0", "cv_ruoshui_31", "0", "0"},
[401132] = {401132, 10011, 35, 27, "0", "0", "Got\u{0020}a\u{0020}mission\u{0020}for\u{0020}me?\u{0020}Understood!", "任務ですか？……了解。", "要開始任務了嗎——瞭解。", "0", "要开始任务了吗——了解。", "0", "cv_ruoshui_33", "0", "0"},
[401133] = {401133, 10011, 36, 28, "0", "0", "Jacksui,\u{0020}prepare\u{0020}to\u{0020}strike!", "弱水、出撃準備。", "弱水，準備出擊！", "0", "弱水，准备出击！", "0", "cv_ruoshui_34", "0", "0"},
[401134] = {401134, 10011, 37, 29, "0", "0", "Should\u{0020}we\u{0020}all\u{0020}go\u{0020}on\u{0020}a\u{0020}spring\u{0020}outing?", "みんな、一緒に遠足に行きませんかー？", "大家一起去春遊嗎~", "0", "大家一起去春游吗~", "0", "cv_ruoshui_35", "0", "0"},
[401135] = {401135, 10011, 38, 30, "0", "0", "Am\u{0020}I\u{0020}going\u{0020}to\u{0020}become\u{0020}a\u{0020}senior\u{0020}apprentice?", "私も先輩になっちゃうんですか？", "我也要成為前輩了嗎？", "0", "我也要成为前辈了吗？", "0", "cv_ruoshui_36", "0", "0"},
[401136] = {401136, 10011, 39, 31, "0", "0", "I\u{0020}want\u{0020}a\u{0020}cool\u{0020}weapon!", "カッコいい武器が欲しいです！", "想要帥氣的武器！", "0", "想要帅气的武器！", "0", "cv_ruoshui_37", "0", "0"},
[401137] = {401137, 10011, 40, 32, "0", "0", "Two\u{0020}movie\u{0020}tickets!", "映画のチケットを二枚お願いします！", "來兩張電影票~！", "0", "来两张电影票~！", "0", "cv_ruoshui_38", "0", "0"},
[401138] = {401138, 10011, 41, 33, "0", "0", "Navigator,\u{0020}you're\u{0020}so\u{0020}handsome.", "ナビゲーターのお兄さん、カッコいいですねー！", "領航很帥喔~", "0", "领航很帅噢~", "0", "cv_ruoshui_39", "0", "0"},
