[401142] = {401142, 10011, 45, 37, "0", "0", "Phew!", "ポチ！", "噗噠！", "0", "噗哒！", "0", "cv_ruoshui_43", "0", "0"},
[401200] = {401200, 10012, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_guroria_32", "0", "0"},
[401201] = {401201, 10012, 2, 2, "0", "0", "I'll\u{0020}be\u{0020}right\u{0020}here,\u{0020}watching\u{0020}you\u{0020}work.\u{0020}Boring?\u{0020}No\u{0020}need\u{0020}to\u{0020}worry\u{0020}about\u{0020}my\u{0020}feelings.", "ここで貴方を見守りますね。……退屈じゃないか？いえ、私のことはお気になさらず。", "我會站在這，注視著您工作的……無聊？不，您無須在意我的感受。", "0", "我会站在这，注视着您工作的……无聊？不，您无须在意我的感受。", "0", "cv_guroria_2", "0", "0"},
[401202] = {401202, 10012, 3, 3, "0", "0", "Hello,\u{0020}I'm\u{0020}Gloria,\u{0020}a\u{0020}new\u{0020}member\u{0020}of\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad.\u{0020}From\u{0020}today\u{0020}on,\u{0020}you'll\u{0020}be\u{0020}my\u{0020}Navigator.", "はじめまして。第三研究室防衛班の新メンバーで、グロリアと申します。本日から、貴方が私のナビゲーターです。", "您好，我是第三研究室防衛班的新成員，格洛麗亞。從今天開始，您便是我的領航了。", "0", "您好，我是第三研究室防卫班的新成员，格洛丽亚。从今天开始，您便是我的领航了。", "0", "cv_guroria_1", "0", "0"},
[401203] = {401203, 10012, 4, 4, "0", "idle", "Mr.\u{0020}Navigator,\u{0020}I\u{0020}have\u{0020}a\u{0020}question…\u{0020}Are\u{0020}there\u{0020}really\u{0020}so\u{0020}few\u{0020}rules\u{0020}for\u{0020}AEGIS?\u{0020}Oh,\u{0020}I\u{0020}see.\u{0020}Well,\u{0020}that’s\u{0020}good.", "ナビゲーターさん、少しお聞きしたいのですが……アイギスの規則はこれだけでしょうか？そう…ですか。なるほど。いいですね。", "領航先生，我有一個疑惑…艾吉斯的規章制度，只有那一點嗎？是嗎…這樣啊。嗯，真好啊。", "0", "领航先生，我有一个疑惑…艾吉斯的规章制度，只有那一点吗？是吗…这样啊。嗯，真好啊。", "0", "cv_guroria_3", "0", "0"},
[401204] = {401204, 10012, 5, 4, "0", "idle", "Mr.\u{0020}Navigator,\u{0020}have\u{0020}you\u{0020}finished\u{0020}your\u{0020}work\u{0020}for\u{0020}the\u{0020}day?\u{0020}Oh,\u{0020}I\u{0020}see.\u{0020}Please\u{0020}keep\u{0020}up\u{0020}the\u{0020}good\u{0020}work.", "ナビゲーターさん、まだ今日の仕事が終わっていないのですか？……そうですか。頑張ってください。", "領航先生，您今天的工作還沒有結束嗎？是嗎，請加油。", "0", "领航先生，您今天的工作还没有结束吗？是吗，请加油。", "0", "cv_guroria_4", "0", "0"},
[401205] = {401205, 10012, 6, 4, "0", "idle", "Dolores?\u{0020}Ah,\u{0020}she’s\u{0020}a\u{0020}kind\u{0020}person.\u{0020}I’ve\u{0020}learned\u{0020}a\u{0020}lot\u{0020}by\u{0020}spending\u{0020}time\u{0020}with\u{0020}her.\u{0020}I\u{0020}bet\u{0020}you\u{0020}think\u{0020}so\u{0020}too,\u{0020}right,\u{0020}Mr.\u{0020}Navigator?", "ドロリィス先輩ですか？ええ、素晴らしいお方です。一緒にいれば、きっと沢山の学びが得られることでしょう。ナビゲーターさんもそう思ってらっしゃるのでは？", "多洛莉絲學姐？啊…她是一個好人，和她相處久了能學到不少東西。您也是這麼認為的吧，領航先生。", "0", "多洛莉丝学姐？啊…她是一个好人，和她相处久了能学到不少东西。您也是这么认为的吧，领航先生。", "0", "cv_guroria_29", "0", "0"},
[401206] = {401206, 10012, 7, 5, "1_》_0_0.8", "level1", "AEGIS...\u{0020}For\u{0020}me,\u{0020}it's\u{0020}a\u{0020}new\u{0020}beginning.\u{0020}I\u{0020}want\u{0020}to\u{0020}try...\u{0020}to\u{0020}start\u{0020}a\u{0020}new\u{0020}life....\u{0020}Don’t\u{0020}mind\u{0020}me,\u{0020}Mr.\u{0020}Navigator,\u{0020}I’m\u{0020}just\u{0020}mumbling\u{0020}to\u{0020}myself.", "アイギス……私の新たなスタート……新しい生活を、始められる……あ。ナビゲーターさん、お気になさらないでください。ただの独り言ですから。", "艾吉斯…對我而言，是一次新的開始。我想試著…開始新的生活。…領航先生，請不要在意，我只是在自言自語。", "0", "艾吉斯…对我而言，是一次新的开始。我想试着…开始新的生活。…领航先生，请不要在意，我只是在自言自语。", "0", "cv_guroria_30", "0", "0"},
[401207] = {401207, 10012, 8, 5, "1_》_0_0.8", "level1", "Hmm?\u{0020}Something\u{0020}on\u{0020}your\u{0020}mind?", "はい？あの……どうしたのですか？", "嗯？請問，有什麼事嗎？", "0", "嗯？请问，有什么事吗？", "0", "cv_guroria_5", "0", "0"},
[401208] = {401208, 10012, 9, 5, "1_》_100_1.5", "level2", "Mr.\u{0020}Navigator,\u{0020}if\u{0020}you\u{0020}have\u{0020}time,\u{0020}could\u{0020}we\u{0020}talk\u{0020}after\u{0020}work?\u{0020}I\u{0020}have\u{0020}so\u{0020}much\u{0020}to\u{0020}share\u{0020}with\u{0020}you.\u{0020}But\u{0020}if\u{0020}it’s\u{0020}a\u{0020}bother,\u{0020}we\u{0020}can\u{0020}always\u{0020}do\u{0020}it\u{0020}next\u{0020}time.", "ナビゲーターさん……お仕事の後に少しお時間よろしいですか？もしご迷惑でないなら、お話ししたいことが沢山あるのです。", "領航先生…您如果有空的話，工作結束後能和我聊聊嗎？我有很多想對您說的話，不過，如果給您添麻煩了，就算了。", "0", "领航先生…您如果有空的话，工作结束后能和我聊聊吗？我有很多想对您说的话，不过，如果给您添麻烦了，就算了。", "0", "cv_guroria_6", "0", "0"},
[401209] = {401209, 10012, 10, 5, "1_》_500_2", "level3", "Being\u{0020}by\u{0020}your\u{0020}side\u{0020}always\u{0020}puts\u{0020}me\u{0020}at\u{0020}ease.\u{0020}You\u{0020}might\u{0020}just\u{0020}be\u{0020}the\u{0020}only\u{0020}person\u{0020}who\u{0020}can\u{0020}understand\u{0020}me,\u{0020}Mr.\u{0020}Navigator.", "ナビゲーターさん、貴方のそばにいると……心の中にある大きな重いものがすっと消えるような、軽やかな気持ちになるのです。もしかすると、貴方は私の……唯一の理解者になってくださるのでしょうか……？", "領航先生，待在您身邊…有一種輕鬆感，就像是，把什麼沉重的東西卸下來了一樣。您或許能成為我…唯一的“理解者”。", "0", "领航先生，待在您身边…有一种轻松感，就像是，把什么沉重的东西卸下来了一样。您或许能成为我…唯一的“理解者”。", "0", "cv_guroria_7", "0", "0"},
[401210] = {401210, 10012, 11, 5, "1_》_1000_2.5", "level4", "Mr.\u{0020}Navigator...\u{0020},\u{0020}you\u{0020}are\u{0020}the\u{0020}one\u{0020}I've\u{0020}been\u{0020}looking\u{0020}for,\u{0020}the\u{0020}only\u{0020}one\u{0020}who\u{0020}wants\u{0020}to\u{0020}know\u{0020}me,\u{0020}can\u{0020}understand\u{0020}me,\u{0020}and\u{0020}belongs\u{0020}only\u{0020}to\u{0020}me,\u{0020}my\u{0020}\"understander\".", "ナビゲーターさん……いえ、私の理解者である貴方こそ、私が探し続けたただ一人の人。私を理解しようと思ってくださる、そして理解してくださる人。私だけの……理解者。", "領航先生…不，我的“理解者”，你就是我一直在尋找著的，唯一一個想要瞭解我，能夠理解我的，只屬於我的“理解者”。", "0", "领航先生…不，我的“理解者”，你就是我一直在寻找着的，唯一一个想要了解我，能够理解我的，只属于我的“理解者”。", "0", "cv_guroria_8", "0", "0"},
[401211] = {401211, 10012, 12, 6, "0", "0", "Upgrade?\u{0020}Oh,\u{0020}thank\u{0020}you.", "レベルアップですか？ありがとうございます。", "升級？喔，謝謝。", "0", "升级？哦，谢谢。", "0", "cv_guroria_9", "0", "0"},
[401212] = {401212, 10012, 13, 7, "0", "0", "A\u{0020}rank\u{0020}promotion?\u{0020}I\u{0020}appreciate\u{0020}it!", "ランクアップ、ありがとうございます。", "階級提升，謝謝。", "0", "阶级提升，谢谢。", "0", "cv_guroria_10", "0", "0"},
[401213] = {401213, 10012, 14, 8, "0", "0", "Mr.\u{0020}Navigator,\u{0020}I've\u{0020}been\u{0020}so\u{0020}grateful\u{0020}for\u{0020}your\u{0020}support...\u{0020}But\u{0020}this\u{0020}isn't\u{0020}what\u{0020}I\u{0020}truly\u{0020}hoped\u{0020}for.\u{0020}Can\u{0020}you\u{0020}be\u{0020}a\u{0020}bit\u{0020}closer\u{0020}to\u{0020}me?", "ナビゲーターさん…いつも私に良くしてくださって、ありがとうございます。……ですが、私の本当の望みは、違うのです。ナビゲーターさん……もっと近くに来ていただけますか？", "領航先生…一直以來，我十分感謝您對我的幫助…可，這些並不是我所希望的。領航先生…能，離我更近一些嗎？", "0", "领航先生…一直以来，我十分感谢您对我的帮助…可，这些并不是我所希望的。领航先生…能，离我更近一些吗？", "0", "cv_guroria_11", "0", "0"},
[401214] = {401214, 10012, 15, 9, "0", "0", "Thank\u{0020}you,\u{0020}Mr.\u{0020}Navigator.", "ありがとうございます、ナビゲーターさん。", "謝謝您，領航先生。", "0", "谢谢您，领航先生。", "0", "cv_guroria_12", "0", "0"},
[401215] = {401215, 10012, 16, 10, "0", "0", "Let's\u{0020}stop\u{0020}here.", "終わらせます。", "到此為止吧。", "0", "到此为止吧。", "0", "cv_guroria_13", "0", "0"},
[401216] = {401216, 10012, 17, 11, "0", "0", "Did\u{0020}we\u{0020}win?\u{0020}That's\u{0020}great!\u{0020}Thanks\u{0020}to\u{0020}everyone.", "勝利ですか。良かった。皆さんのお陰です。", "勝利了嗎，嗯，那就好，多虧大家了。", "0", "胜利了吗，嗯，那就好，多亏大家了。", "0", "cv_guroria_14", "0", "0"},
[401217] = {401217, 10012, 18, 12, "0", "0", "I'm\u{0020}sorry\u{0020}for\u{0020}causing\u{0020}you\u{0020}trouble.", "ご迷惑をおかけしました。", "給您添麻煩了。", "0", "给您添麻烦了。", "0", "cv_guroria_15", "0", "0"},
[401218] = {401218, 10012, 19, 13, "0", "0", "I\u{0020}should\u{0020}have\u{0020}done\u{0020}better.", "すみません、もう少しうまくできれば……", "抱歉，我應該做得更好的。", "0", "抱歉，我应该做得更好的。", "0", "cv_guroria_16", "0", "0"},
[401219] = {401219, 10012, 20, 14, "0", "0", "Let's\u{0020}retreat.", "ここは撤退しましょう…！", "先撤退吧。", "0", "先撤退吧。", "0", "cv_guroria_17", "0", "0"},
[401220] = {401220, 10012, 21, 15, "0", "0", "Pathetic.", "私の敵ではありません。", "不堪一擊呢。", "0", "不堪一击呢。", "0", "cv_guroria_18", "0", "0"},
[401221] = {401221, 10012, 23, 16, "0", "0", "I'll\u{0020}split\u{0020}you\u{0020}apart!", "切り裂く！", "劈開你！", "0", "劈开你！", "0", "cv_guroria_19", "0", "0"},
[401222] = {401222, 10012, 24, 17, "0", "0", "Heya!", "せやぁっ！", "嘿呀！", "0", "嘿呀！", "0", "cv_guroria_21", "0", "0"},
[401223] = {401223, 10012, 26, 19, "0", "0", "Looks\u{0020}like...\u{0020}this\u{0020}is\u{0020}my\u{0020}stop...", "ここまでのようですね……", "看來只能到此為止……", "0", "看来只能到此为止……", "0", "cv_guroria_20", "0", "0"},
[401224] = {401224, 10012, 27, 20, "0", "0", "Are\u{0020}you\u{0020}coming\u{0020}too?\u{0020}Is\u{0020}that\u{0020}so...\u{0020}Then\u{0020}do\u{0020}as\u{0020}you\u{0020}like.", "貴方もご一緒にいかがですか？ええ…どうぞお好きなように。", "您也要一起過來嗎？是嗎…那按您喜歡的來吧。", "0", "您也要一起过来吗？是吗…那按您喜欢的来吧。", "0", "cv_guroria_22", "0", "0"},
[401225] = {401225, 10012, 28, 21, "0", "0", "Mr.\u{0020}Navigator,\u{0020}if\u{0020}you're\u{0020}tired,\u{0020}don't\u{0020}push\u{0020}yourself\u{0020}too\u{0020}hard.", "ナビゲーターさん、お疲れでしょうか？どうかご無理をなさらないでください。", "領航先生，您累了的話，就別勉強了。", "0", "领航先生，您累了的话，就别勉强了。", "0", "cv_guroria_23", "0", "0"},
[401226] = {401226, 10012, 29, 21, "0", "0", "You've\u{0020}worked\u{0020}hard,\u{0020}Mr.\u{0020}Navigator.\u{0020}Let\u{0020}me\u{0020}take\u{0020}care\u{0020}of\u{0020}the\u{0020}rest...\u{0020}Is\u{0020}that\u{0020}alright?\u{0020}I\u{0020}understand.", "ナビゲーターさん、お疲れさまでした。あとは私が……ダメですか？…承知しました。", "領航先生，辛苦您了。剩下的讓我自己來…不行嗎？…我明白了。", "0", "领航先生，辛苦您了。剩下的让我自己来…不行吗？…我明白了。", "0", "cv_guroria_24", "0", "0"},
[401227] = {401227, 10012, 30, 22, "0", "0", "Oh...\u{0020}it's\u{0020}an\u{0020}event.", "おや…事件ですね。", "喔…是事件。", "0", "哦…是事件。", "0", "cv_guroria_25", "0", "0"},
[401228] = {401228, 10012, 31, 23, "0", "0", "Please,\u{0020}go\u{0020}ahead\u{0020}as\u{0020}you\u{0020}like.", "お気に召すまま、どうぞ。", "請您隨意。", "0", "请您随意。", "0", "cv_guroria_26", "0", "0"},
[401229] = {401229, 10012, 32, 24, "0", "0", "Congratulations!", "おめでとうございます。", "恭喜您。", "0", "恭喜您。", "0", "cv_guroria_27", "0", "0"},
[401230] = {401230, 10012, 33, 25, "0", "0", "Great\u{0020}work.", "お疲れさまでした。", "辛苦了。", "0", "辛苦了。", "0", "cv_guroria_28", "0", "0"},
[401231] = {401231, 10012, 34, 26, "0", "0", "Hello,\u{0020}Navigator.\u{0020}Are\u{0020}you\u{0020}working\u{0020}today\u{0020}as\u{0020}well?\u{0020}It\u{0020}must\u{0020}be\u{0020}tough.", "おはようございます、ナビゲーターさん。今日もお仕事ですか？お疲れ様です。", "您好，領航先生。今天也要工作嗎？真是辛苦呢。", "0", "您好，领航先生。今天也要工作吗？真是辛苦呢。", "0", "cv_guroria_31", "0", "0"},
[401232] = {401232, 10012, 35, 27, "0", "0", "Navigator,\u{0020}let's\u{0020}head\u{0020}out.\u{0020}I'm\u{0020}all\u{0020}set.", "ナビゲーターさん、行きましょう。私に準備は不要です。", "領航先生，出發吧，我沒有需要準備的東西。", "0", "领航先生，出发吧，我没有需要准备的东西。", "0", "cv_guroria_33", "0", "0"},
[401233] = {401233, 10012, 36, 28, "0", "0", "Let's\u{0020}go,\u{0020}Mr.\u{0020}Navigator.", "参りましょう、ナビゲーターさん。", "我們走吧，領航先生。", "0", "我们走吧，领航先生。", "0", "cv_guroria_34", "0", "0"},
[401234] = {401234, 10012, 37, 29, "0", "0", "Good\u{0020}afternoon,\u{0020}everyone!", "こんにちは、皆さん。", "午安，各位。", "0", "午安，各位。", "0", "cv_guroria_35", "0", "0"},
[401235] = {401235, 10012, 38, 30, "0", "0", "Mr.\u{0020}Navigator,\u{0020}are\u{0020}you\u{0020}heading\u{0020}for\u{0020}an\u{0020}interview?", "ナビゲーターさん、面接をしますか？", "領航先生，您是要面試嗎？", "0", "领航先生，您是要面试吗？", "0", "cv_guroria_36", "0", "0"},
[401236] = {401236, 10012, 39, 31, "0", "0", "Equipment...\u{0020}Do\u{0020}we\u{0020}need\u{0020}to\u{0020}switch\u{0020}to\u{0020}new\u{0020}ones?", "新しい装備が必要ですか？", "裝備…要換新的嗎？", "0", "装备…要换新的吗？", "0", "cv_guroria_37", "0", "0"},
[401237] = {401237, 10012, 40, 32, "0", "0", "What\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}buy?", "何を購入しましょうか。", "想買什麼？", "0", "想买什么？", "0", "cv_guroria_38", "0", "0"},
[401238] = {401238, 10012, 41, 33, "0", "0", "Please\u{0020}remember\u{0020}to\u{0020}wash\u{0020}up.", "身だしなみを整えるのをお忘れなく。", "請記得洗漱。", "0", "请记得洗漱。", "0", "cv_guroria_39", "0", "0"},
[401239] = {401239, 10012, 42, 34, "0", "0", "Be\u{0020}careful\u{0020}with\u{0020}the\u{0020}settings.", "慎重に設定してください。", "請小心設定。", "0", "请小心设置。", "0", "cv_guroria_40", "0", "0"},
[401240] = {401240, 10012, 43, 35, "0", "0", "Make\u{0020}sure\u{0020}to\u{0020}read\u{0020}everything\u{0020}carefully.", "確認をお願いします。", "請仔細閱讀。", "0", "请仔细阅读。", "0", "cv_guroria_41", "0", "0"},
[401241] = {401241, 10012, 44, 36, "0", "0", "It's\u{0020}quite\u{0020}lively\u{0020}here.", "賑やかですね。", "很熱鬧呢。", "0", "很热闹呢。", "0", "cv_guroria_42", "0", "0"},
[401242] = {401242, 10012, 45, 37, "0", "0", "Um?", "はい？", "嗯？", "0", "嗯？", "0", "cv_guroria_43", "0", "0"},
[401300] = {401300, 10013, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_lilith_31", "0", "0"},
[401301] = {401301, 10013, 2, 2, "0", "0", "Why\u{0020}do\u{0020}you\u{0020}care\u{0020}so\u{0020}much\u{0020}about\u{0020}me?", "何故そんなに私のことが気になるの？", "為什麼要這麼在意我？", "0", "为什么要这么在意我？", "0", "cv_lilith_2", "0", "0"},
[401302] = {401302, 10013, 3, 3, "0", "0", "Ah,\u{0020}that\u{0020}familiar\u{0020}smell.\u{0020}You\u{0020}must\u{0020}be\u{0020}that\u{0020}real\u{0020}Synesthete.\u{0020}Let\u{0020}me\u{0020}make\u{0020}it\u{0020}clear,\u{0020}I\u{0020}hate\u{0020}all\u{0020}Synesthetes,\u{0020}including\u{0020}myself.", "ああ、懐かしい匂い…...あなたが真の通感覚者なのね。先に言っておくけど、私、通感覚者のことが嫌いなの。もちろん、私自身も含めて。", "啊，熟悉的味道啊。你就是那個真正的通感者吧。話先說在前面，我討厭所有的通感者，當然也包括我自己。", "0", "啊，熟悉的味道啊。你就是那个真正的通感者吧。话先说在前面，我讨厌所有的通感者，当然也包括我自己。", "0", "cv_lilith_1", "0", "0"},
[401303] = {401303, 10013, 4, 4, "0", "idle", "As\u{0020}a\u{0020}true\u{0020}Synesthete,\u{0020}you\u{0020}should\u{0020}be\u{0020}able\u{0020}to\u{0020}hear\u{0020}it\u{0020}too,\u{0020}right?\u{0020}Everyone's\u{0020}fear,\u{0020}hatred,\u{0020}and...\u{0020}despair.", "真の通感覚者のあなたなら、聞こえるんじゃない？みんなの恐怖、憎悪、そして……絶望。", "身為真正的通感者，你應該也能聽得到吧？大家的恐懼，憎恨以及……絕望。", "0", "身为真正的通感者，你应该也能听得到吧？大家的恐惧，憎恨以及……绝望。", "0", "cv_lilith_3", "0", "0"},
[401304] = {401304, 10013, 5, 4, "0", "idle", "Wasting\u{0020}time\u{0020}here\u{0020}is\u{0020}pointless.\u{0020}You\u{0020}know\u{0020}I'm\u{0020}your\u{0020}subordinate,\u{0020}just\u{0020}assign\u{0020}me\u{0020}a\u{0020}task\u{0020}already.", "ここで時間を費やしても意味がない。ここでは私はあなたの部下なのだから、早く指示を出してちょうだい。", "在這裡浪費時間毫無意義，既然我是你的屬下，就趕快給我佈置任務吧。", "0", "在这里浪费时间毫无意义，既然我是你的属下，就赶快给我布置任务吧。", "0", "cv_lilith_4", "0", "0"},
[401305] = {401305, 10013, 6, 4, "0", "idle", "Blueberry\u{0020}cake...\u{0020}Skadi,\u{0020}you\u{0020}secretly\u{0020}ate\u{0020}my\u{0020}blueberry\u{0020}cake\u{0020}again,\u{0020}didn't\u{0020}you?\u{0020}Don't\u{0020}pretend,\u{0020}I\u{0020}know\u{0020}exactly\u{0020}what's\u{0020}on\u{0020}your\u{0020}mind.", "スカディ、また私のブルーベリーケーキをこっそりつまみ食いしたでしょ？知らないふりをしたって無駄よ。何を考えてるのか、私には分かる。", "藍莓蛋糕……斯卡蒂，你又偷偷吃了我的藍莓蛋糕了吧？不要再裝了，你心裡想的我全都知道了。", "0", "蓝莓蛋糕……斯卡蒂，你又偷偷吃了我的蓝莓蛋糕了吧？不要再装了，你心里想的我全都知道了。", "0", "cv_lilith_28", "0", "0"},
[401306] = {401306, 10013, 7, 5, "1_》_0_0.8", "level1", "What's\u{0020}wrong?\u{0020}Is\u{0020}it\u{0020}strange\u{0020}that\u{0020}I\u{0020}like\u{0020}eating\u{0020}sweets?", "どうしたの？私がスイーツ好きなのが、そんなに驚くこと？", "怎麼了？我喜歡吃甜食很奇怪嗎？", "0", "怎么了？我喜欢吃甜食很奇怪吗？", "0", "cv_lilith_29", "0", "0"},
[401307] = {401307, 10013, 8, 5, "1_》_0_0.8", "level1", "If\u{0020}possible,\u{0020}just\u{0020}treat\u{0020}me\u{0020}as\u{0020}a\u{0020}tool.", "私を道具として使っていいよ。", "如果可以的話，將我當作是工具就好了。", "0", "如果可以的话，将我当作是工具就好了。", "0", "cv_lilith_5", "0", "0"},
[401308] = {401308, 10013, 9, 5, "1_》_100_1.5", "level2", "Since\u{0020}you\u{0020}can\u{0020}also\u{0020}receive\u{0020}others'\u{0020}negative\u{0020}emotions,\u{0020}I\u{0020}suppose\u{0020}that\u{0020}makes\u{0020}us\u{0020}the\u{0020}same\u{0020}kind\u{0020}of\u{0020}Synesthete.", "もし、あなたも他人の負の感情を感じられると言うのなら、私たちは、通感覚者の中でも同類であると言えるね。", "既然你也能接受到他人的負面情感的話，那麼我們姑且也能算作是通感者中的同類了吧。", "0", "既然你也能接受到他人的负面情感的话，那么我们姑且也能算作是通感者中的同类了吧。", "0", "cv_lilith_6", "0", "0"},
[401309] = {401309, 10013, 10, 5, "1_》_500_2", "level3", "It\u{0020}must\u{0020}have\u{0020}been\u{0020}tough\u{0020}for\u{0020}you\u{0020}all\u{0020}this\u{0020}time.\u{0020}Even\u{0020}though\u{0020}I\u{0020}don’t\u{0020}understand\u{0020}why\u{0020}you\u{0020}still\u{0020}act\u{0020}indifferent\u{0020}about\u{0020}it.\u{0020}But\u{0020}I\u{0020}do\u{0020}know\u{0020}your\u{0020}pain,\u{0020}your\u{0020}guilt...", "辛いでしょ？あなたが何故そのようにどうでもいいみたいな態度をとってるのかは知らないけど。でも、私は知ってる。あなたの苦しみと自責の念……", "一直以來都很辛苦吧，雖然不清楚為什麼你對此還是一副無所謂的態度。但是我很清楚，你的痛楚，你的自責……", "0", "一直以来都很辛苦吧，虽然不清楚为什么你对此还是一副无所谓的态度。但是我很清楚，你的痛楚，你的自责……", "0", "cv_lilith_7", "0", "0"},
[401310] = {401310, 10013, 11, 5, "1_》_1000_2.5", "level4", "We're...\u{0020}companions?\u{0020}Say\u{0020}whatever\u{0020}you\u{0020}want.\u{0020}I'm\u{0020}just\u{0020}your\u{0020}tool.\u{0020}But\u{0020}during\u{0020}battles,\u{0020}please\u{0020}stop\u{0020}using\u{0020}Synesthesia\u{0020}on\u{0020}me—I\u{0020}don't\u{0020}want\u{0020}your\u{0020}pain\u{0020}to\u{0020}double.", "同類じゃなくて仲間、か……勝手にすれば。私はただの道具だわ。あなたの道具。でも、戦ってる時は私に対して通感覚をしないで。あなたの苦しみを増やしたくないから。", "是同伴而不是同類嗎……隨便你怎麼說吧，我只是你的工具而已。不過在戰鬥的時候還請不要再對我使用通感了，我可不希望你的痛苦翻倍。", "0", "是同伴而不是同类吗……随便你怎么说吧，我只是你的工具而已。不过在战斗的时候还请不要再对我使用通感了，我可不希望你的痛苦翻倍。", "0", "cv_lilith_8", "0", "0"},
[401311] = {401311, 10013, 12, 6, "0", "0", "That's\u{0020}right,\u{0020}just\u{0020}keep\u{0020}going\u{0020}like\u{0020}this.", "そう、こうやって続けて。", "沒錯，就這樣繼續下去吧。", "0", "没错，就这样继续下去吧。", "0", "cv_lilith_9", "0", "0"},
[401312] = {401312, 10013, 13, 7, "0", "0", "Very\u{0020}good...\u{0020}So\u{0020}my\u{0020}illness\u{0020}can\u{0020}be\u{0020}cured\u{0020}this\u{0020}way,\u{0020}right?", "良いわね…...これなら私の病もきっと治るわ……", "很好……這麼一來我的病就能痊癒了吧……", "0", "很好……这么一来我的病就能痊愈了吧……", "0", "cv_lilith_10", "0", "0"},
[401313] = {401313, 10013, 14, 8, "0", "0", "No\u{0020}matter\u{0020}how\u{0020}hard\u{0020}I\u{0020}try,\u{0020}I\u{0020}can't\u{0020}escape\u{0020}my\u{0020}identity\u{0020}as\u{0020}a\u{0020}Synesthete.\u{0020}But\u{0020}those\u{0020}annoying\u{0020}voices\u{0020}seem\u{0020}to\u{0020}have\u{0020}softened...\u{0020}I\u{0020}can\u{0020}hear\u{0020}other\u{0020}sounds\u{0020}now—the\u{0020}blessings,\u{0020}the\u{0020}thanks,\u{0020}and\u{0020}the\u{0020}prayers\u{0020}sung\u{0020}by\u{0020}the\u{0020}children.", "やっぱり、何をやっても通感覚者という身分から逃れられないのね……でも、最近あの嫌な声が柔らかくなった気がする……私、他の声が聞こえるようになったみたいだわ。子供たちの祝福、感謝、そして……祈りの歌声。", "果然，無論怎麼樣都無法擺脫通感者的身份嗎……只是，那些讓人討厭的聲音好像變得柔和了……我好像能聽到其他的聲音了。孩子們的祝福，感謝以及……祈禱的歌聲。", "0", "果然，无论怎么样都无法摆脱通感者的身份吗……只是，那些让人讨厌的声音好像变得柔和了……我好像能听到其他的声音了。孩子们的祝福，感谢以及……祈祷的歌声。", "0", "cv_lilith_11", "0", "0"},
[401314] = {401314, 10013, 15, 9, "0", "0", "The\u{0020}electric\u{0020}current\u{0020}has\u{0020}increased.", "電流の量が上がったわ。", "電流量提升了呢。", "0", "电流量提升了呢。", "0", "cv_lilith_12", "0", "0"},
[401315] = {401315, 10013, 16, 10, "0", "0", "So\u{0020}annoying.", "嫌だわ。", "真討厭啊。", "0", "真讨厌啊。", "0", "cv_lilith_13", "0", "0"},
[401316] = {401316, 10013, 17, 11, "0", "0", "Don't\u{0020}rush\u{0020}to\u{0020}thank\u{0020}me.", "感謝など、要らないわ。", "不用急著感謝我。", "0", "不用急着感谢我。", "0", "cv_lilith_14", "0", "0"},
[401317] = {401317, 10013, 18, 12, "0", "0", "I've\u{0020}already\u{0020}told\u{0020}you,\u{0020}there's\u{0020}no\u{0020}problem.", "だから言ったでしょ？大丈夫だって。", "都和你說過了，沒問題的。", "0", "都和你说过了，没问题的。", "0", "cv_lilith_15", "0", "0"},
[401318] = {401318, 10013, 19, 13, "0", "0", "Um,\u{0020}how\u{0020}should\u{0020}I\u{0020}put\u{0020}this?\u{0020}It\u{0020}was\u{0020}a\u{0020}narrow\u{0020}escape.", "…うん、なんていうか、ギリギリだったのね。", "嗯，怎麼說呢，有驚無險吧。", "0", "嗯，怎么说呢，有惊无险吧。", "0", "cv_lilith_16", "0", "0"},
[401319] = {401319, 10013, 20, 14, "0", "0", "Ah...\u{0020}those\u{0020}hateful\u{0020}voices...\u{0020}are\u{0020}they\u{0020}back\u{0020}again?", "ああ……例の嫌な声がまた……", "啊……那些討厭的聲音…又出現了嗎。", "0", "啊……那些讨厌的声音…又出现了吗。", "0", "cv_lilith_17", "0", "0"},
[401320] = {401320, 10013, 21, 15, "0", "0", "Resent\u{0020}me.", "私を恨みなさい。", "怨恨我吧。", "0", "怨恨我吧。", "0", "cv_lilith_18", "0", "0"},
[401321] = {401321, 10013, 23, 16, "0", "0", "I'll\u{0020}kill\u{0020}you.", "あなたを、殺す。", "殺了你。", "0", "杀了你。", "0", "cv_lilith_19", "0", "0"},
[401322] = {401322, 10013, 26, 19, "0", "0", "Energy\u{0020}reserves\u{0020}depleted...\u{0020}Is\u{0020}it\u{0020}finally\u{0020}over?\u{0020}Someone\u{0020}save\u{0020}me...\u{0020}Where\u{0020}are\u{0020}you...", "エネルギーがもうすぐ切れてしまう……やっと終わるのね……誰か、私を助けて……あなたはどこ……", "能量儲備即將歸零……終於可以結束了嗎……誰來救救我……你在哪裡啊……", "0", "能量储备即将归零……终于可以结束了吗……谁来救救我……你在哪里啊……", "0", "cv_lilith_20", "0", "0"},
[401323] = {401323, 10013, 27, 20, "0", "0", "Ah,\u{0020}it's\u{0020}that\u{0020}familiar\u{0020}smell\u{0020}again...\u{0020}it's\u{0020}you,\u{0020}isn't\u{0020}it?", "あっ、またあの懐かしい匂いが……あなたよね？", "啊，又是那股熟悉的味道呢，是你吧。", "0", "啊，又是那股熟悉的味道呢，是你吧。", "0", "cv_lilith_21", "0", "0"},
[401324] = {401324, 10013, 28, 21, "0", "0", "Being\u{0020}so\u{0020}close\u{0020}to\u{0020}you\u{0020}is\u{0020}irritating...", "あなたがこんな近い所にいるなんて、嫌だわ……", "和你貼得這麼近，真討厭啊……", "0", "和你贴得这么近，真讨厌啊……", "0", "cv_lilith_22", "0", "0"},
[401325] = {401325, 10013, 29, 21, "0", "0", "Be\u{0020}careful.\u{0020}I\u{0020}don't\u{0020}want\u{0020}to\u{0020}hear\u{0020}your\u{0020}wailing\u{0020}when\u{0020}you\u{0020}fall.", "あなた、気を付けてね。落ちる時の叫び声は聞きたくないわ。", "要小心點喔，我可不想聽到你摔下去時發出的哀嚎。", "0", "要小心点哦，我可不想听到你摔下去时发出的哀嚎。", "0", "cv_lilith_23", "0", "0"},
[401326] = {401326, 10013, 30, 22, "0", "0", "Go\u{0020}ahead\u{0020}with\u{0020}confidence.", "安心して行きなさい。", "放心地上吧。", "0", "放心地上吧。", "0", "cv_lilith_24", "0", "0"},
[401327] = {401327, 10013, 31, 23, "0", "0", "If\u{0020}you\u{0020}dare\u{0020}to\u{0020}cheat\u{0020}using\u{0020}Synesthesia,\u{0020}I'll\u{0020}kill\u{0020}you.", "通感覚でカンニングしたら殺すわよ。", "如果敢使用通感作弊就殺了你喔。", "0", "如果敢使用通感作弊就杀了你哦。", "0", "cv_lilith_25", "0", "0"},
[401328] = {401328, 10013, 32, 24, "0", "0", "Great.\u{0020}I'm\u{0020}so\u{0020}happy.", "やった！…...嬉しいわ。", "好棒，我好開心。", "0", "好棒，我好开心。", "0", "cv_lilith_26", "0", "0"},
[401329] = {401329, 10013, 33, 25, "0", "0", "Ah,\u{0020}just\u{0020}as\u{0020}I\u{0020}thought.\u{0020}Let's\u{0020}try\u{0020}harder\u{0020}next\u{0020}time.", "ああ、こうなると思ったわ。また次の機会に頑張って。", "啊，和我想得一樣，下次再努力吧。", "0", "啊，和我想得一样，下次再努力吧。", "0", "cv_lilith_27", "0", "0"},
[401330] = {401330, 10013, 34, 26, "0", "0", "I\u{0020}could\u{0020}smell\u{0020}you\u{0020}from\u{0020}afar.\u{0020}Of\u{0020}course,\u{0020}I’m\u{0020}not\u{0020}talking\u{0020}about\u{0020}body\u{0020}odor.", "遠くからあなたの匂いがしたわ。もちろん、体臭の話じゃないわよ。", "老遠就聞到你的味道了呢。當然，我指的不是體味。", "0", "老远就闻到你的味道了呢。当然，我指的不是体味。", "0", "cv_lilith_30", "0", "0"},
[401331] = {401331, 10013, 35, 27, "0", "0", "What\u{0020}exactly\u{0020}is\u{0020}waiting\u{0020}for\u{0020}us\u{0020}at\u{0020}the\u{0020}end?", "終点で私たちを待っているものは何だろう。", "終點到底有什麼在等著我們呢？", "0", "终点到底有什么在等着我们呢？", "0", "cv_lilith_32", "0", "0"},
[401332] = {401332, 10013, 36, 28, "0", "0", "How\u{0020}long\u{0020}will\u{0020}this\u{0020}last\u{0020}again?", "今回はどのくらい続くの？", "這次又要持續多久呢？", "0", "这次又要持续多久呢？", "0", "cv_lilith_33", "0", "0"},
