[401502] = {401502, 10015, 3, 3, "0", "0", "I'm\u{0020}Zofia,\u{0020}Zofia\u{0020}I.\u{0020}Pogolovsky.\u{0020}So,\u{0020}you’re\u{0020}the\u{0020}Navigator?\u{0020}Hehe,\u{0020}you’re\u{0020}so\u{0020}tiny.", "0", "我是索菲亞，索菲亞·伊·波戈洛夫斯基。嗯，你就是領航嗎？呵呵，真小啊~", "0", "我是索菲亚，索菲亚·伊·波戈洛夫斯基。嗯，你就是领航吗？呵呵，真小啊~", "0", "cv_sofia_1", "0", "0"},
[401503] = {401503, 10015, 4, 4, "0", "idle", "Snowball\u{0020}fights\u{0020}are\u{0020}my\u{0020}favorite\u{0020}pastime\u{0020}in\u{0020}Katya.\u{0020}You\u{0020}can\u{0020}throw\u{0020}as\u{0020}hard\u{0020}as\u{0020}you\u{0020}want\u{0020}and\u{0020}nobody\u{0020}gets\u{0020}hurt—it’s\u{0020}the\u{0020}perfect\u{0020}game!", "0", "打雪仗是我在卡佳最喜歡的娛樂活動了。不管多麼用力地扔出去，都不會傷到人，這不是很好的娛樂活動嗎？", "0", "打雪仗是我在卡佳最喜欢的娱乐活动了。不管多么用力地扔出去，都不会伤到人，这不是很好的娱乐活动吗？", "0", "cv_sofia_3", "0", "0"},
[401504] = {401504, 10015, 5, 4, "0", "idle", "No\u{0020}matter\u{0020}how\u{0020}many\u{0020}Sins\u{0020}I\u{0020}kill,\u{0020}they\u{0020}just\u{0020}keep\u{0020}coming…\u{0020}What\u{0020}beautiful\u{0020}creatures\u{0020}they\u{0020}are.", "0", "不管殺死多少隻原罪，它們都會不停地湧來……怎麼會有如此美麗的生物呢？", "0", "不管杀死多少只原罪，它们都会不停地涌来……怎么会有如此美丽的生物呢？", "0", "cv_sofia_4", "0", "0"},
[401505] = {401505, 10015, 6, 4, "0", "idle", "The\u{0020}captain\u{0020}of\u{0020}Cannonbore,\u{0020}Efgenia…\u{0020}destroying\u{0020}her\u{0020}body\u{0020}and\u{0020}spirit?\u{0020}I\u{0020}don’t\u{0020}think\u{0020}anyone\u{0020}can\u{0020}pull\u{0020}that\u{0020}off\u{0020}just\u{0020}yet—she\u{0020}is\u{0020}my\u{0020}captain,\u{0020}after\u{0020}all.", "0", "“鋼輪戈爾”的隊長，也就是葉夫根尼婭……將她的身體和精神一併摧毀……我想，能做到這件事的人，應該還不存在吧？畢竟，她可是我的隊長呢。", "0", "“钢轮戈尔”的队长，也就是叶夫根尼娅……将她的身体和精神一并摧毁……我想，能做到这件事的人，应该还不存在吧？毕竟，她可是我的队长呢。", "0", "cv_sofia_29", "0", "0"},
[401506] = {401506, 10015, 7, 5, "1_》_0_0.8", "level1", "\"Destruction,\"\u{0020}\"death,\"\u{0020}\"annihilation,\"\u{0020}\"extinction\"…\u{0020}Just\u{0020}saying\u{0020}those\u{0020}words\u{0020}and\u{0020}imagining\u{0020}the\u{0020}scenes\u{0020}makes\u{0020}me\u{0020}excited.\u{0020}Guess\u{0020}I’m\u{0020}not\u{0020}normal,\u{0020}huh?", "0", "“毀壞”、“死亡”、“滅絕”、“消亡”……光是念誦它們，想像畫面，我就會興奮起來。果然，我不正常呢。", "0", "“毁坏”、“死亡”、“灭绝”、“消亡”……光是念诵它们，想象画面，我就会兴奋起来。果然，我不正常呢。", "0", "cv_sofia_30", "0", "0"},
[401507] = {401507, 10015, 8, 5, "1_》_0_0.8", "level1", "Hmm?\u{0020}Did\u{0020}you\u{0020}have\u{0020}something\u{0020}to\u{0020}say\u{0020}to\u{0020}me?", "0", "嗯？有什麼想對我說的話嗎？", "0", "嗯？有什么想对我说的话吗？", "0", "cv_sofia_5", "0", "0"},
[401508] = {401508, 10015, 9, 5, "1_》_100_1.5", "level2", "Navigator,\u{0020}if\u{0020}you\u{0020}keep\u{0020}messing\u{0020}around\u{0020}like\u{0020}this,\u{0020}I\u{0020}might\u{0020}get\u{0020}angry,\u{0020}hehe...", "0", "領航，再這麼胡鬧的話，我可要生氣了，呵呵……", "0", "领航，再这么胡闹的话，我可要生气了，呵呵……", "0", "cv_sofia_6", "0", "0"},
[401509] = {401509, 10015, 10, 5, "1_》_500_2", "level3", "Whenever\u{0020}I\u{0020}see\u{0020}you,\u{0020}I\u{0020}get\u{0020}this\u{0020}strange\u{0020}urge…\u{0020}like\u{0020}I\u{0020}want\u{0020}to\u{0020}make\u{0020}you\u{0020}mine\u{0020}and\u{0020}mine\u{0020}alone,\u{0020}hehe.", "0", "現在看到領航的時候，我的心裡就會萌生出一種奇怪的衝動……想要將你變成只屬於我一個人的東西呢，呵呵。", "0", "现在看到领航的时候，我的心里就会萌生出一种奇怪的冲动……想要将你变成只属于我一个人的东西呢，呵呵。", "0", "cv_sofia_7", "0", "0"},
[401510] = {401510, 10015, 11, 5, "1_》_1000_2.5", "level4", "People\u{0020}can’t\u{0020}fight\u{0020}their\u{0020}nature.\u{0020}And\u{0020}mine\u{0020}is\u{0020}\"destruction.\"\u{0020}I\u{0020}have\u{0020}a\u{0020}feeling\u{0020}that\u{0020}one\u{0020}day,\u{0020}I’ll\u{0020}hurt\u{0020}something\u{0020}besides\u{0020}the\u{0020}Sins…\u{0020}and\u{0020}when\u{0020}that\u{0020}day\u{0020}comes,\u{0020}I\u{0020}hope\u{0020}it’s\u{0020}you,\u{0020}Navigator,\u{0020}who\u{0020}stops\u{0020}me…\u{0020}even\u{0020}if\u{0020}that\u{0020}means\u{0020}killing\u{0020}me.", "0", "人是不可以忤逆她的天性的。而我的天性就是“破壞”。我有一種預感，有一天，我會對原罪以外的生命下手……所以，那一天來臨的時候，我希望會是領航你來阻止我……殺死我……", "0", "人是不可以忤逆她的天性的。而我的天性就是“破坏”。我有一种预感，有一天，我会对原罪以外的生命下手……所以，那一天来临的时候，我希望会是领航你来阻止我……杀死我……", "0", "cv_sofia_8", "0", "0"},
[401511] = {401511, 10015, 12, 6, "0", "0", "Thanks!\u{0020}But\u{0020}honestly,\u{0020}are\u{0020}you\u{0020}looking\u{0020}to\u{0020}die?", "0", "謝謝~\u{0020}雖想這麼說，你難道想自殺嗎？", "0", "谢谢~\u{0020}虽想这么说，你难道想自杀吗？", "0", "cv_sofia_9", "0", "0"},
[401512] = {401512, 10015, 13, 7, "0", "0", "Did\u{0020}you\u{0020}really\u{0020}add\u{0020}extra\u{0020}explosives?\u{0020}It’s\u{0020}weird\u{0020}for\u{0020}me\u{0020}to\u{0020}say\u{0020}this,\u{0020}but\u{0020}you’re\u{0020}crazy,\u{0020}Navigator.", "0", "故意給炸彈加分量麼？這話由我來說雖然有點奇怪，領航你真是瘋了。", "0", "故意给炸弹加分量么？这话由我来说虽然有点奇怪，领航你真是疯了。", "0", "cv_sofia_10", "0", "0"},
[401513] = {401513, 10015, 14, 8, "0", "0", "Hehe,\u{0020}I\u{0020}can\u{0020}feel\u{0020}it…\u{0020}the\u{0020}desire\u{0020}buried\u{0020}deep\u{0020}in\u{0020}me\u{0020}is\u{0020}rising…\u{0020}What\u{0020}happens\u{0020}next,\u{0020}even\u{0020}I\u{0020}don’t\u{0020}know,\u{0020}so\u{0020}be\u{0020}ready,\u{0020}Navigator.", "0", "呵呵，我能感受到，潛藏在我心裡的那副欲望要湧出來了……接下來會發生什麼，連我也不知道呢，要做好心理準備，領航。", "0", "呵呵，我能感受到，潜藏在我心里的那副欲望要涌出来了……接下来会发生什么，连我也不知道呢，要做好心理准备，领航。", "0", "cv_sofia_11", "0", "0"},
[401514] = {401514, 10015, 15, 9, "0", "0", "It’s\u{0020}easier\u{0020}to\u{0020}destroy\u{0020}enemies\u{0020}now.", "0", "能更輕鬆地摧毀敵人了。", "0", "能更轻松地摧毁敌人了。", "0", "cv_sofia_12", "0", "0"},
