[401601] = {401601, 10016, 2, 2, "0", "0", "So,\u{0020}it's\u{0020}guard\u{0020}duty\u{0020}this\u{0020}time?\u{0020}Got\u{0020}it.\u{0020}I'll\u{0020}make\u{0020}sure\u{0020}to\u{0020}get\u{0020}it\u{0020}done\u{0020}right.", "0", "站崗任務…是嗎？好，我會努力完成的。", "0", "站岗任务…是吗？好，我会努力完成的。", "0", "cv_anan_2", "0", "0"},
[401602] = {401602, 10016, 3, 3, "0", "0", "Fledgeling\u{0020}Eagle's\u{0020}Anan\u{0020}reporting.\u{0020}Please\u{0020}give\u{0020}the\u{0020}order,\u{0020}Navigator.", "0", "雛鷹小隊安安前來報導，請領航下達命令。", "0", "雏鹰小队安安前来报道，请领航下达命令。", "0", "cv_anan_1", "0", "0"},
[401603] = {401603, 10016, 4, 4, "0", "idle", "I\u{0020}can’t\u{0020}slack\u{0020}off—this\u{0020}is\u{0020}my\u{0020}chance\u{0020}to\u{0020}become\u{0020}a\u{0020}true\u{0020}Driver.", "0", "絕不能鬆懈，這是成為正式駕駛員的機會。", "0", "绝不能松懈，这是成为正式驾驶员的机会。", "0", "cv_anan_3", "0", "0"},
[401604] = {401604, 10016, 5, 4, "0", "idle", "I\u{0020}can't\u{0020}let\u{0020}Captain\u{0020}Karen\u{0020}down.", "0", "不能讓卡蓮班長失望。", "0", "不能让卡莲班长失望。", "0", "cv_anan_4", "0", "0"},
[401605] = {401605, 10016, 6, 4, "0", "idle", "At\u{0020}the\u{0020}academy,\u{0020}everyone\u{0020}thought\u{0020}I\u{0020}was\u{0020}dumb.\u{0020}Even\u{0020}the\u{0020}teachers\u{0020}called\u{0020}me\u{0020}\"the\u{0020}biggest\u{0020}failure\u{0020}of\u{0020}this\u{0020}decade.\"\u{0020}But\u{0020}only\u{0020}Captain\u{0020}Karen\u{0020}believed\u{0020}in\u{0020}me…\u{0020}so\u{0020}I\u{0020}can’t\u{0020}let\u{0020}her\u{0020}down!", "0", "在學院裡，大家都覺得我是笨蛋，甚至老師都說我是“十年難遇的廢材”。只有卡蓮班長沒有嫌棄我…所以我一定不能讓班長失望！", "0", "在学院里，大家都觉得我是笨蛋，甚至老师都说我是“十年难遇的废材”。只有卡莲班长没有嫌弃我…所以我一定不能让班长失望！", "0", "cv_anan_29", "0", "0"},
[401606] = {401606, 10016, 7, 5, "1_》_0_0.8", "level1", "I’m\u{0020}going\u{0020}to\u{0020}become\u{0020}an\u{0020}official\u{0020}AVG\u{0020}driver,\u{0020}fight\u{0020}the\u{0020}Sins,\u{0020}and\u{0020}show\u{0020}everyone\u{0020}I’m\u{0020}not\u{0020}stupid\u{0020}or\u{0020}useless.", "0", "我要成為正式的avg駕駛員，為對抗原罪出一份力，我要讓大家都看到，我不是笨蛋，不是廢物。", "0", "我要成为正式的avg驾驶员，为对抗原罪出一份力，我要让大家都看到，我不是笨蛋，不是废物。", "0", "cv_anan_30", "0", "0"},
[401607] = {401607, 10016, 8, 5, "1_》_0_0.8", "level1", "Reporting\u{0020}in,\u{0020}Navigator!\u{0020}No\u{0020}enemies\u{0020}in\u{0020}sight!", "0", "報告領航！沒有看到敵人！", "0", "报告领航！没有看到敌人！", "0", "cv_anan_5", "0", "0"},
[401608] = {401608, 10016, 9, 5, "1_》_100_1.5", "level2", "Zzzz…\u{0020}ah!\u{0020}Sorry,\u{0020}Navigator,\u{0020}I\u{0020}was\u{0020}just\u{0020}so\u{0020}tired...", "0", "呼…呼…啊！領航，對不起，我實在是，太困了…呼……", "0", "呼…呼…啊！领航，对不起，我实在是，太困了…呼……", "0", "cv_anan_6", "0", "0"},
[401609] = {401609, 10016, 10, 5, "1_》_500_2", "level3", "Do\u{0020}you\u{0020}need\u{0020}anything\u{0020}moved,\u{0020}Navigator?\u{0020}Don’t\u{0020}worry,\u{0020}I\u{0020}can\u{0020}handle\u{0020}it\u{0020}all\u{0020}by\u{0020}myself.", "0", "領航，有物資需要搬運嗎？請放心，我一個人可以完成。", "0", "领航，有物资需要搬运吗？请放心，我一个人可以完成。", "0", "cv_anan_7", "0", "0"},
[401610] = {401610, 10016, 11, 5, "1_》_1000_2.5", "level4", "Before\u{0020}I\u{0020}came\u{0020}here,\u{0020}I\u{0020}was\u{0020}so\u{0020}scared\u{0020}you’d\u{0020}dislike\u{0020}me…\u{0020}but\u{0020}not\u{0020}only\u{0020}did\u{0020}you\u{0020}not,\u{0020}you\u{0020}trusted\u{0020}me.\u{0020}Being\u{0020}trusted\u{0020}by\u{0020}you\u{0020}makes\u{0020}me\u{0020}so\u{0020}happy.", "0", "在來這裡之前，我害怕過會不會被領航您討厭……但您不僅沒有討厭我，還信任我，相信我……能夠被領航您所信任，真的太好了。", "0", "在来这里之前，我害怕过会不会被领航您讨厌……但您不仅没有讨厌我，还信任我，相信我……能够被领航您所信任，真的太好了。", "0", "cv_anan_8", "0", "0"},
[401611] = {401611, 10016, 12, 6, "0", "0", "I\u{0020}can\u{0020}feel\u{0020}myself\u{0020}getting\u{0020}stronger.", "0", "能感覺到，力量的提升。", "0", "能感觉到，力量的提升。", "0", "cv_anan_9", "0", "0"},
