[401701] = {401701, 10017, 2, 2, "0", "0", "Good\u{0020}choice!\u{0020}I\u{0020}won’t\u{0020}let\u{0020}you\u{0020}down!", "0", "明智之選，本小姐不會讓你失望的！", "0", "明智之选，本小姐不会让你失望的！", "0", "cv_rosalind_2", "0", "0"},
[401702] = {401702, 10017, 3, 3, "0", "0", "Rosalind\u{0020}Rothschild,\u{0020}eldest\u{0020}daughter\u{0020}of\u{0020}the\u{0020}Rothschild\u{0020}family,\u{0020}at\u{0020}your\u{0020}service.\u{0020}So,\u{0020}you’re\u{0020}the\u{0020}Navigator\u{0020}for\u{0020}this\u{0020}mission?", "0", "“羅斯柴德”家族長女——羅莎琳德覲見。您就是這次行動的領航嗎？", "0", "“罗斯柴德”家族长女——罗莎琳德觐见。您就是这次行动的领航吗？", "0", "cv_rosalind_1", "0", "0"},
[401703] = {401703, 10017, 4, 4, "0", "idle", "The\u{0020}decor\u{0020}here\u{0020}isn’t\u{0020}as\u{0020}grand\u{0020}as\u{0020}my\u{0020}family’s\u{0020}estate,\u{0020}but\u{0020}it’s\u{0020}got\u{0020}its\u{0020}own\u{0020}charm.", "0", "這裡的裝潢雖然不及家族內的裝飾，但是也算是別有風格。", "0", "这里的装潢虽然不及家族内的装饰，但是也算是别有风格。", "0", "cv_rosalind_3", "0", "0"},
[401704] = {401704, 10017, 5, 4, "0", "idle", "Don’t\u{0020}underestimate\u{0020}me\u{0020}just\u{0020}because\u{0020}I’m\u{0020}a\u{0020}noble.\u{0020}Next\u{0020}time,\u{0020}I’ll\u{0020}lead\u{0020}the\u{0020}charge.", "0", "不要因為本小姐是貴族就小瞧我的實力，下次任務本小姐來擔任前鋒。", "0", "不要因为本小姐是贵族就小瞧我的实力，下次任务本小姐来担任前锋。", "0", "cv_rosalind_4", "0", "0"},
[401705] = {401705, 10017, 6, 4, "0", "idle", "Of\u{0020}course,\u{0020}fighting\u{0020}the\u{0020}Sins\u{0020}is\u{0020}scary,\u{0020}but\u{0020}my\u{0020}noble\u{0020}blood\u{0020}doesn’t\u{0020}allow\u{0020}me\u{0020}to\u{0020}feel\u{0020}fear.\u{0020}As\u{0020}a\u{0020}member\u{0020}of\u{0020}Frontier,\u{0020}I’ve\u{0020}accepted\u{0020}that\u{0020}every\u{0020}mission\u{0020}is\u{0020}a\u{0020}fight\u{0020}for\u{0020}survival.", "0", "與原罪戰鬥當然會害怕啦，但是本小姐的貴族血統可不允許害怕。作為前線小隊的成員每一次任務都是在用生命進行戰鬥，這點本小姐早就已經有覺悟了。", "0", "与原罪战斗当然会害怕啦，但是本小姐的贵族血统可不允许害怕。作为前线小队的成员每一次任务都是在用生命进行战斗，这点本小姐早就已经有觉悟了。", "0", "cv_rosalind_29", "0", "0"},
[401706] = {401706, 10017, 7, 5, "1_》_0_0.8", "level1", "Joining\u{0020}the\u{0020}Frontier\u{0020}was\u{0020}my\u{0020}decision,\u{0020}and\u{0020}of\u{0020}course,\u{0020}I’ve\u{0020}kept\u{0020}it\u{0020}secret\u{0020}from\u{0020}my\u{0020}family.\u{0020}If\u{0020}my\u{0020}parents\u{0020}knew\u{0020}I\u{0020}was\u{0020}doing\u{0020}something\u{0020}this\u{0020}dangerous…\u{0020}So,\u{0020}make\u{0020}sure\u{0020}to\u{0020}protect\u{0020}me,\u{0020}Navigator!", "0", "參加前線小隊完全是本小姐自己的意願，當然我家族那塊是必須瞞著的，要是被爸媽知道我在做這麼危險的事……所以，一定要保護好本小姐喔，領航！", "0", "参加前线小队完全是本小姐自己的意愿，当然我家族那块是必须瞒着的，要是被爸妈知道我在做这么危险的事……所以，一定要保护好本小姐哦，领航！", "0", "cv_rosalind_30", "0", "0"},
[401707] = {401707, 10017, 8, 5, "1_》_0_0.8", "level1", "I\u{0020}am\u{0020}a\u{0020}noble.\u{0020}Please\u{0020}stop\u{0020}acting\u{0020}inappropriately,\u{0020}even\u{0020}if\u{0020}it's\u{0020}you,\u{0020}Navigator.", "0", "本小姐可是貴族，就算是領航也不可肆意輕薄。", "0", "本小姐可是贵族，就算是领航也不可肆意轻薄。", "0", "cv_rosalind_5", "0", "0"},
[401708] = {401708, 10017, 9, 5, "1_》_100_1.5", "level2", "My\u{0020}family\u{0020}has\u{0020}a\u{0020}thousand-year\u{0020}history.\u{0020}We’re\u{0020}one\u{0020}of\u{0020}the\u{0020}old\u{0020}aristocratic\u{0020}families\u{0020}from\u{0020}the\u{0020}Maya\u{0020}region…\u{0020}Hmm?\u{0020}Can’t\u{0020}find\u{0020}us\u{0020}online?\u{0020}That’s\u{0020}because\u{0020}we\u{0020}have\u{0020}strict\u{0020}rules\u{0020}about\u{0020}appearing\u{0020}in\u{0020}public.", "0", "本小姐的家族有著千年的歷史，是瑪雅地區老牌的貴族之一……嗯？網路上搜索不到？這…這是因為家族內有規矩，不會隨便出現在世人面前。", "0", "本小姐的家族有着千年的历史，是玛雅地区老牌的贵族之一……嗯？网络上搜索不到？这…这是因为家族内有规矩，不会随便出现在世人面前。", "0", "cv_rosalind_6", "0", "0"},
[401709] = {401709, 10017, 10, 5, "1_》_500_2", "level3", "The\u{0020}armor\u{0020}after\u{0020}Gigantification\u{0020}must\u{0020}be\u{0020}worth\u{0020}a\u{0020}fortune.\u{0020}If\u{0020}I\u{0020}sold\u{0020}it—wait,\u{0020}Navigator!\u{0020}How\u{0020}long\u{0020}have\u{0020}you\u{0020}been\u{0020}standing\u{0020}there?\u{0020}I\u{0020}didn’t\u{0020}say\u{0020}anything,\u{0020}and\u{0020}you\u{0020}didn’t\u{0020}hear\u{0020}anything!", "0", "話說駕駛員巨大化後穿著的裝甲值不少錢吧，如果拿去賣了——呃啊啊，領航你怎麼在這？本小姐剛才什麼都沒說！你也什麼都沒聽到！", "0", "话说驾驶员巨大化后穿着的装甲值不少钱吧，如果拿去卖了——呃啊啊，领航你怎么在这？本小姐刚才什么都没说！你也什么都没听到！", "0", "cv_rosalind_7", "0", "0"},
[401710] = {401710, 10017, 11, 5, "1_》_1000_2.5", "level4", "Navigator,\u{0020}even\u{0020}though\u{0020}we’re\u{0020}from\u{0020}different\u{0020}backgrounds…\u{0020}it’s\u{0020}not\u{0020}impossible.\u{0020}If\u{0020}you’re\u{0020}interested,\u{0020}I\u{0020}could\u{0020}ask\u{0020}my\u{0020}parents…\u{0020}huh?\u{0020}Why\u{0020}did\u{0020}you\u{0020}fall\u{0020}asleep\u{0020}now,\u{0020}of\u{0020}all\u{0020}times?", "0", "領航，雖然你與本小姐之間身份懸殊，但是…也並非沒有機會。如果說你願意的話，我回去請示一下父母……欸？領航……怎麼偏偏這時候睡著了啊。", "0", "领航，虽然你与本小姐之间身份悬殊，但是…也并非没有机会。如果说你愿意的话，我回去请示一下父母……诶？领航……怎么偏偏这时候睡着了啊。", "0", "cv_rosalind_8", "0", "0"},
[401711] = {401711, 10017, 12, 6, "0", "0", "I\u{0020}can\u{0020}feel\u{0020}myself\u{0020}getting\u{0020}stronger.", "0", "感覺到實力的增強了。", "0", "感觉到实力的增强了。", "0", "cv_rosalind_9", "0", "0"},
[401712] = {401712, 10017, 13, 7, "0", "0", "That\u{0020}shooting\u{0020}star\u{0020}that\u{0020}just\u{0020}passed…\u{0020}it\u{0020}looked\u{0020}like\u{0020}it'll\u{0020}sell\u{0020}for\u{0020}a\u{0020}fortune.", "0", "剛閃過的星星，好像很值錢的樣子。", "0", "刚闪过的星星，好像很值钱的样子。", "0", "cv_rosalind_10", "0", "0"},
[401713] = {401713, 10017, 14, 8, "0", "0", "With\u{0020}this\u{0020}kind\u{0020}of\u{0020}power,\u{0020}I\u{0020}can\u{0020}restore\u{0020}my\u{0020}family’s\u{0020}glory.", "0", "擁有這樣的力量，我就可以重振家族的榮耀了。", "0", "拥有这样的力量，我就可以重振家族的荣耀了。", "0", "cv_rosalind_11", "0", "0"},
[401714] = {401714, 10017, 15, 9, "0", "0", "So\u{0020}this\u{0020}is\u{0020}what\u{0020}it’s\u{0020}like\u{0020}to\u{0020}be\u{0020}treated\u{0020}like\u{0020}a\u{0020}noble…\u{0020}Ahem,\u{0020}thank\u{0020}you.", "0", "這就是貴族的待遇麼……咳，謝謝。", "0", "这就是贵族的待遇么……咳，谢谢。", "0", "cv_rosalind_12", "0", "0"},
[401715] = {401715, 10017, 16, 10, "0", "0", "Leave\u{0020}it\u{0020}to\u{0020}me,\u{0020}I\u{0020}won’t\u{0020}disappoint\u{0020}you.", "0", "儘管交給本小姐吧，本小姐絕對不會讓期待落空。", "0", "尽管交给本小姐吧，本小姐绝对不会让期待落空。", "0", "cv_rosalind_13", "0", "0"},
[401716] = {401716, 10017, 17, 11, "0", "0", "With\u{0020}me\u{0020}here,\u{0020}this\u{0020}is\u{0020}the\u{0020}expected\u{0020}outcome.", "0", "有本小姐在，這都是理所應當的結果。", "0", "有本小姐在，这都是理所应当的结果。", "0", "cv_rosalind_14", "0", "0"},
[401717] = {401717, 10017, 18, 12, "0", "0", "I\u{0020}just\u{0020}got\u{0020}distracted\u{0020}for\u{0020}a\u{0020}moment,\u{0020}that’s\u{0020}all.", "0", "本小姐不過是分心了而已。", "0", "本小姐不过是分心了而已。", "0", "cv_rosalind_15", "0", "0"},
