[401802] = {401802, 10018, 3, 3, "0", "0", "Lyfa\u{0020}of\u{0020}Team\u{0020}Valkyries\u{0020}reporting\u{0020}in.\u{0020}Navigator…\u{0020}may\u{0020}I\u{0020}call\u{0020}you\u{0020}Master?", "0", "瓦爾基裏小隊的莉法，向您報導。領航……我能稱呼您為主人嗎？", "0", "0", "0", "cv_lyfa_1", "0", "0"},
[401803] = {401803, 10018, 4, 4, "0", "idle", "So\u{0020}many\u{0020}documents,\u{0020}notes,\u{0020}and\u{0020}battle\u{0020}reports!\u{0020}Master,\u{0020}your\u{0020}job\u{0020}must\u{0020}be\u{0020}exhausting.", "0", "資料和筆記…還有這麼多戰鬥報告！主人的工作真是幸苦啊。", "0", "0", "0", "cv_lyfa_3", "0", "0"},
[401804] = {401804, 10018, 5, 4, "0", "idle", "Even\u{0020}though\u{0020}I’m\u{0020}wearing\u{0020}a\u{0020}maid\u{0020}outfit,\u{0020}that\u{0020}doesn't\u{0020}mean\u{0020}I\u{0020}can't\u{0020}handle\u{0020}myself\u{0020}in\u{0020}a\u{0020}fight.", "0", "雖然我穿著女僕裝，但是在戰場上也請相信我的實力。", "0", "0", "0", "cv_lyfa_4", "0", "0"},
[401805] = {401805, 10018, 6, 4, "0", "idle", "The\u{0020}captain\u{0020}is\u{0020}really\u{0020}understanding\u{0020}and\u{0020}let\u{0020}me\u{0020}wear\u{0020}this\u{0020}outfit,\u{0020}so\u{0020}I\u{0020}can’t\u{0020}disappoint\u{0020}her—I\u{0020}won't\u{0020}let\u{0020}her\u{0020}down.", "0", "隊長是個通情達理的人，同意了我穿女僕裝的任性要求…我當然不能讓她失望，所以必須在戰場上好好表現。", "0", "0", "0", "cv_lyfa_29", "0", "0"},
[401806] = {401806, 10018, 7, 5, "1_》_0_0.8", "level1", "A\u{0020}maid’s\u{0020}daily\u{0020}duties\u{0020}include\u{0020}cleaning,\u{0020}laundry,\u{0020}and\u{0020}preparing\u{0020}afternoon\u{0020}tea…\u{0020}But\u{0020}I\u{0020}enjoy\u{0020}it\u{0020}all,\u{0020}so\u{0020}what’s\u{0020}the\u{0020}next\u{0020}task,\u{0020}Master?", "0", "女僕每天要做的工作是很多的，比如打掃衛生啦，清洗衣物啦，準備下午茶啦……其實我也是樂在其中的，所以下一個命令是什麼呢，主人！", "0", "0", "0", "cv_lyfa_30", "0", "0"},
[401807] = {401807, 10018, 8, 5, "1_》_0_0.8", "level1", "Master,\u{0020}do\u{0020}you\u{0020}think\u{0020}this\u{0020}outfit\u{0020}suits\u{0020}me?\u{0020}Hehe,\u{0020}thank\u{0020}you.", "0", "主人，您也覺得這身裝束很適合我嗎？嘿嘿，謝謝~", "0", "0", "0", "cv_lyfa_5", "0", "0"},
[401808] = {401808, 10018, 9, 5, "1_》_100_1.5", "level2", "Master,\u{0020}would\u{0020}you\u{0020}like\u{0020}tea\u{0020}or\u{0020}coffee?\u{0020}The\u{0020}usual\u{0020}black\u{0020}tea?\u{0020}Understood.", "0", "主人，請問需要喝茶還是咖啡？和平時一樣的紅茶，明白了~", "0", "0", "0", "cv_lyfa_6", "0", "0"},
[401809] = {401809, 10018, 10, 5, "1_》_500_2", "level3", "Master,\u{0020}it’s\u{0020}time\u{0020}for\u{0020}your\u{0020}meeting.\u{0020}Safe\u{0020}travels…\u{0020}Huh?\u{0020}I’m\u{0020}going\u{0020}with\u{0020}you?\u{0020}Yes,\u{0020}understood.", "0", "主人，到開會的時間了，祝您一路順風……誒？我也要一起去嗎……是，遵命~", "0", "0", "0", "cv_lyfa_7", "0", "0"},
[401810] = {401810, 10018, 11, 5, "1_》_1000_2.5", "level4", "A\u{0020}gloomy\u{0020}sky\u{0020}can\u{0020}make\u{0020}people\u{0020}feel\u{0020}down,\u{0020}but\u{0020}don’t\u{0020}worry,\u{0020}the\u{0020}sun\u{0020}will\u{0020}shine\u{0020}again\u{0020}someday.\u{0020}When\u{0020}that\u{0020}day\u{0020}comes,\u{0020}Master,\u{0020}will\u{0020}you\u{0020}go\u{0020}on\u{0020}a\u{0020}picnic\u{0020}with\u{0020}me?\u{0020}Hehe.", "0", "陰霾的天空會讓人們的臉蒙上陰翳，心情也會因此而低落沮喪。但是沒關係，總有一天，天空會放晴的。到時候，主人會和我一起出去野餐嗎，嘿嘿~", "0", "0", "0", "cv_lyfa_8", "0", "0"},
[401811] = {401811, 10018, 12, 6, "0", "0", "I\u{0020}can\u{0020}feel\u{0020}my\u{0020}skills\u{0020}improving.", "0", "感覺到能力有提升了。", "0", "0", "0", "cv_lyfa_9", "0", "0"},
