[401841] = {401841, 10018, 44, 36, "0", "0", "Please\u{0020}wait\u{0020}a\u{0020}moment;\u{0020}I'll\u{0020}make\u{0020}tea\u{0020}for\u{0020}everyone\u{0020}right\u{0020}away.", "0", "請稍等，馬上就為大家泡茶。", "0", "0", "0", "cv_lyfa_42", "0", "0"},
