[401900] = {401900, 10019, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響", "0", "0", "0", "cv_nozomi_sw_1", "0", "0"},
[401901] = {401901, 10019, 2, 2, "0", "0", "You\u{0020}found\u{0020}me,\u{0020}Navigator.\u{0020}I've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}you\u{0020}for\u{0020}a\u{0020}long\u{0020}time.", "あたしを見つけてくれたんですね。ナビゲーターさん。", "你找到我啦，領航，我等你好久了。", "0", "0", "0", "cv_nozomi_sw_2", "0", "0"},
[401902] = {401902, 10019, 3, 3, "0", "0", "Huh?\u{0020}What's\u{0020}wrong\u{0020}with\u{0020}my\u{0020}name?\u{0020}It's\u{0020}exactly\u{0020}the\u{0020}same\u{0020}as\u{0020}that\u{0020}legendary\u{0020}idol's\u{0020}name?\u{0020}So,\u{0020}she's\u{0020}already\u{0020}dead,\u{0020}huh?", "あたしの名前が何か……？え、伝説のアイドルと同じ？……そうですか。彼女はもう、いないんですね。", "嗯？我的名字怎麼了嗎？和那位傳說中的偶像名字一模一樣？……是嘛，原來“她”已經死了啊。", "0", "0", "0", "cv_nozomi_sw_3", "0", "0"},
[401903] = {401903, 10019, 4, 4, "0", "idle", "An\u{0020}idol!\u{0020}A\u{0020}performer!\u{0020}A\u{0020}Driver!\u{0020}Hehe,\u{0020}my\u{0020}next\u{0020}goal\u{0020}is\u{0020}to\u{0020}bring\u{0020}true\u{0020}love\u{0020}and\u{0020}peace\u{0020}to\u{0020}everyone!", "アイドル、ヴァイオリニスト、そしてドライバー！えへへ。次の目標は、みんなに愛と平和を届けることです！", "偶像！演奏家！駕駛員！嘿嘿，接下來的目標就是要為大家帶來真正的愛與和平！", "0", "0", "0", "cv_nozomi_sw_5", "0", "0"},
[401904] = {401904, 10019, 5, 4, "0", "idle", "I\u{0020}pulled\u{0020}everyone\u{0020}into\u{0020}the\u{0020}idol\u{0020}world\u{0020}and\u{0020}then\u{0020}just\u{0020}left\u{0020}them...\u{0020}they\u{0020}must\u{0020}be\u{0020}so\u{0020}disappointed\u{0020}in\u{0020}me.", "勝手にアイドルの世界に引き込んで、自分だけ勝手にいなくなって……みんなきっと、あたしのこと怒ってるよね……", "把大家拉進偶像的領域又擅自走掉……她們一定對我很失望吧……", "0", "0", "0", "cv_nozomi_sw_6", "0", "0"},
[401905] = {401905, 10019, 6, 4, "0", "idle", "It's\u{0020}been\u{0020}so\u{0020}long\u{0020}since\u{0020}I\u{0020}last\u{0020}sang!\u{0020}I'm\u{0020}a\u{0020}bit\u{0020}rusty,\u{0020}but\u{0020}I\u{0020}can't\u{0020}help\u{0020}it...\u{0020}I\u{0020}want\u{0020}to\u{0020}get\u{0020}back\u{0020}on\u{0020}stage\u{0020}soon!\u{0020}I've\u{0020}got\u{0020}to\u{0020}work\u{0020}harder!", "すっごく久しぶりに歌いました！だいぶ下手になっちゃったけど……これが今のあたし。またステージに戻るために、もっと頑張らなきゃ！", "好——久——沒有唱歌了！生疏了不少呢，不過這也沒辦法……我想快點重新回到舞臺上！得加把勁了！", "0", "0", "0", "cv_nozomi_sw_7", "0", "0"},
[401906] = {401906, 10019, 7, 5, "1_》_0_0.8", "level1", "When\u{0020}I'm\u{0020}up\u{0020}on\u{0020}stage,\u{0020}struming\u{0020}the\u{0020}strings\u{0020}and\u{0020}singing\u{0020}my\u{0020}heart\u{0020}and\u{0020}soul...\u{0020}it\u{0020}feels\u{0020}so\u{0020}great\u{0020}to\u{0020}be\u{0020}alive.", "ステージに立って、ヴァイオリンを弾いて、歌うことができる……生きるって素晴らしい……", "當我站在舞臺上，還能拉動琴弦，還能繼續歌唱……活著真是太好了。", "0", "0", "0", "cv_nozomi_sw_8", "0", "0"},
[401907] = {401907, 10019, 8, 5, "1_》_0_0.8", "level1", "Ah!\u{0020}Don't\u{0020}sneak\u{0020}up\u{0020}on\u{0020}me\u{0020}while\u{0020}I'm\u{0020}practicing!", "きゃっ！練習してる時に急に近寄らないでください！", "呀！不要在我練習的時候忽然靠過來嘛。", "0", "0", "0", "cv_nozomi_sw_9", "0", "0"},
[401908] = {401908, 10019, 9, 5, "1_》_100_1.5", "level2", "You...\u{0020}want\u{0020}to\u{0020}listen?\u{0020}It's\u{0020}been\u{0020}so\u{0020}long\u{0020}since\u{0020}I've\u{0020}performed\u{0020}for\u{0020}an\u{0020}audience...\u{0020}I\u{0020}feel\u{0020}a\u{0020}little\u{0020}shy.", "演奏を聞かせてほしい、ですか？お客さんの前でするのは久しぶりです……ちょっと照れちゃいますね。", "你……想聽聽嗎？我已經好久沒有面對觀眾了……有點害羞。", "0", "0", "0", "cv_nozomi_sw_10", "0", "0"},
[401909] = {401909, 10019, 10, 5, "1_》_500_2", "level3", "I'm\u{0020}nervous...\u{0020}Do\u{0020}you\u{0020}think\u{0020}I\u{0020}can\u{0020}still\u{0020}move\u{0020}the\u{0020}audience?\u{0020}...It's\u{0020}my\u{0020}first\u{0020}performance,\u{0020}Navigator,\u{0020}you'll\u{0020}be\u{0020}there,\u{0020}right?", "緊張する……今のあたしで、お客さんを満足させられるのかな……ナビゲーターさん。あたしのファーストライブ、来てくれるよね？", "好緊張……現在的我還能調動起觀眾的情緒嗎。……我的首場演出，領航你會來的吧？", "0", "0", "0", "cv_nozomi_sw_11", "0", "0"},
[401910] = {401910, 10019, 11, 5, "1_》_1000_2.5", "level4", "You\u{0020}know,\u{0020}Navigator,\u{0020}music\u{0020}can\u{0020}really\u{0020}convey\u{0020}the\u{0020}performer's\u{0020}feelings.\u{0020}I\u{0020}want\u{0020}to\u{0020}share\u{0020}Nozomi's\u{0020}voice\u{0020}with\u{0020}you.\u{0020}This\u{0020}song\u{0020}is\u{0020}for\u{0020}you.", "ナビゲーターさん。演奏者は音楽にのせて気持ちを伝えることができるんです。だから結束希の音を聞いてください。これは、あなたのために作った曲なんですよ。", "你知道嗎，領航。音樂演出能傳達出演出者的感情，所以，我想向你傳達結束希的聲音。這是我為你譜寫的曲子。", "0", "0", "0", "cv_nozomi_sw_12", "0", "0"},
[401911] = {401911, 10019, 12, 6, "0", "0", "Humph♫", "フンフフーン♪", "哼♫~~", "0", "0", "0", "cv_nozomi_sw_13", "0", "0"},
[401912] = {401912, 10019, 13, 7, "0", "0", "I'm\u{0020}hitting\u{0020}my\u{0020}stride!", "トップを目指します！", "接近頂點了。", "0", "0", "0", "cv_nozomi_sw_14", "0", "0"},
[401913] = {401913, 10019, 14, 8, "0", "0", "Um...\u{0020}Huh?\u{0020}I\u{0020}just\u{0020}seemed\u{0020}to\u{0020}have\u{0020}a\u{0020}bit\u{0020}of\u{0020}inspiration.\u{0020}What\u{0020}was\u{0020}that\u{0020}just\u{0020}now?\u{0020}Awakening?\u{0020}So\u{0020}amazing!\u{0020}Can\u{0020}it\u{0020}happen\u{0020}again?\u{0020}No?\u{0020}What\u{0020}a\u{0020}pity.", "んん……あれ？このインスピレーション……これ、なんですか！？覚醒？すごーい！もう一回お願いできますか？……ダメ？残念です……", "嗯……嗯？剛剛好像有了一點靈感，剛剛那個是什麼？！覺醒？好厲害！可以再來一次嗎！……不可以了？遺憾……", "0", "0", "0", "cv_nozomi_sw_15", "0", "0"},
[401914] = {401914, 10019, 15, 9, "0", "0", "I've\u{0020}regained\u{0020}my\u{0020}former\u{0020}touch.", "昔の感覚が戻ってきました！", "找回曾經的手感了。", "0", "0", "0", "cv_nozomi_sw_16", "0", "0"},
[401915] = {401915, 10019, 16, 10, "0", "0", "Is\u{0020}it\u{0020}my\u{0020}turn\u{0020}to\u{0020}perform?", "私の出番ですか？", "輪到我表演了嗎？", "0", "0", "0", "cv_nozomi_sw_17", "0", "0"},
[401916] = {401916, 10019, 17, 11, "0", "0", "Perfect\u{0020}curtain\u{0020}call!", "カーテンコール！", "完美謝幕！", "0", "0", "0", "cv_nozomi_sw_18", "0", "0"},
[401917] = {401917, 10019, 18, 12, "0", "0", "A\u{0020}slight\u{0020}mistake.\u{0020}Um...\u{0020}There's\u{0020}a\u{0020}bit\u{0020}of\u{0020}noise\u{0020}in\u{0020}the\u{0020}music.", "ちょっと失敗ですね。うーん……ノイズが入っちゃいました。", "略微的失誤，嗯……音樂有點雜音呢。", "0", "0", "0", "cv_nozomi_sw_19", "0", "0"},
[401918] = {401918, 10019, 19, 13, "0", "0", "I\u{0020}haven't\u{0020}fully\u{0020}mastered\u{0020}this\u{0020}part.\u{0020}Let\u{0020}me\u{0020}train\u{0020}myself\u{0020}some\u{0020}more.", "あのパートが上手くいきません……もっと練習しなきゃ。", "還沒完全掌握這一段，再鍛煉一下自己吧。", "0", "0", "0", "cv_nozomi_sw_20", "0", "0"},
[401919] = {401919, 10019, 20, 14, "0", "0", "Big\u{0020}event!\u{0020}A\u{0020}disastrous\u{0020}performance!\u{0020}It's\u{0020}going\u{0020}to\u{0020}cause\u{0020}public\u{0020}outrage!", "やばい、大失敗！炎上しちゃいます！", "大事件！演奏大失敗！要引起公憤了！", "0", "0", "0", "cv_nozomi_sw_21", "0", "0"},
