[401922] = {401922, 10019, 26, 19, "0", "0", "Noise...", "不協和音が……", "噪音……", "0", "0", "0", "cv_nozomi_sw_24", "0", "0"},
[401923] = {401923, 10019, 24, 17, "0", "0", "Interlude\u{0020}rhythm—", "インテルメッツォ！", "間奏律——", "0", "0", "0", "cv_nozomi_sw_26", "0", "0"},
[401924] = {401924, 10019, 25, 18, "0", "0", "Everyone\u{0020}has\u{0020}waited\u{0020}for\u{0020}a\u{0020}long\u{0020}time!\u{0020}The\u{0020}performance\u{0020}of\u{0020}Nozomi\u{0020}returning\u{0020}to\u{0020}the\u{0020}stage\u{0020}is\u{0020}over.\u{0020}Now,\u{0020}the\u{0020}show\u{0020}begins!", "お待たせしました！希ちゃんの復帰ライブ、開演です！", "大家久等了！結束希重回舞臺的演出，此刻，開演！", "0", "0", "0", "cv_nozomi_sw_25", "0", "0"},
[401925] = {401925, 10019, 27, 20, "0", "0", "Aah!\u{0020}Navigator?\u{0020}Why\u{0020}are\u{0020}you\u{0020}here?", "え、えええ！？ナビゲーターさん！？なんでここに？", "——呀！！領航？！你怎麼在這裏？！", "0", "0", "0", "cv_nozomi_sw_27", "0", "0"},
[401926] = {401926, 10019, 28, 21, "0", "0", "...Mmm,\u{0020}I\u{0020}see.\u{0020}The\u{0020}music\u{0020}industry\u{0020}is\u{0020}really\u{0020}different\u{0020}now.", "……なるほど。今の音楽業界はこうなんですね。", "…嗯嗯，原來如此，現在的樂壇真是大不一樣啊。", "0", "0", "0", "cv_nozomi_sw_28", "0", "0"},
[401927] = {401927, 10019, 29, 21, "0", "0", "Music\u{0020}makes\u{0020}people\u{0020}both\u{0020}painful\u{0020}and\u{0020}happy.\u{0020}Other\u{0020}people's\u{0020}performances\u{0020}touch\u{0020}my\u{0020}heart,\u{0020}but\u{0020}also\u{0020}make\u{0020}me\u{0020}jealous\u{0020}and\u{0020}unwilling.\u{0020}When\u{0020}I\u{0020}get\u{0020}out,\u{0020}I'll\u{0020}continue\u{0020}to\u{0020}practice!", "音楽って本当に楽しいけど、辛い時もあるんですよ。他の人のパフォーマンスで感動して泣くこともあれば、嫉妬で悔しくなることも……うん！帰ったらすぐ練習します！", "音樂真是讓人痛苦又快樂……別人的表演會打動我的心，但卻又讓我嫉妒，不甘心。……等出去了，就繼續練習吧！", "0", "0", "0", "cv_nozomi_sw_29", "0", "0"},
[401928] = {401928, 10019, 30, 22, "0", "0", "The\u{0020}secret\u{0020}concert\u{0020}has\u{0020}begun!", "シークレットライブ、開演です！", "秘密演唱會開始了哦~", "0", "0", "0", "cv_nozomi_sw_30", "0", "0"},
[401929] = {401929, 10019, 31, 23, "0", "0", "Is\u{0020}my\u{0020}\"voice\"\u{0020}special\u{0020}to\u{0020}you?", "ナビゲーターさんにとって私の声って、特別ですかねー？", "我的“聲音”對你而言是特殊的嗎？", "0", "0", "0", "cv_nozomi_sw_31", "0", "0"},
[401930] = {401930, 10019, 32, 24, "0", "0", "You\u{0020}remember!\u{0020}Then\u{0020}I\u{0020}unilaterally\u{0020}declare\u{0020}that\u{0020}you\u{0020}are\u{0020}my\u{0020}die-hard\u{0020}fan!", "覚えててくれたんですね！あたしのファンとして合格です！", "你記住了呢！那我單方面宣佈你是我的死忠粉了！", "0", "0", "0", "cv_nozomi_sw_32", "0", "0"},
[401931] = {401931, 10019, 33, 25, "0", "0", "Woo...\u{0020}It\u{0020}seems\u{0020}I'm\u{0020}not\u{0020}mature\u{0020}enough.", "ううう……私もまだまだですね……", "嗚……看來我還不夠成熟……", "0", "0", "0", "cv_nozomi_sw_33", "0", "0"},
[401932] = {401932, 10019, 34, 26, "0", "0", "Welcome\u{0020}back.\u{0020}I\u{0020}was\u{0020}just\u{0020}about\u{0020}to\u{0020}prepare\u{0020}for\u{0020}practice.\u{0020}Navigator,\u{0020}you\u{0020}can\u{0020}listen\u{0020}by\u{0020}the\u{0020}side.", "おかえりなさーい。ちょうど練習をはじめるところだったんですよ。よかったらそこで聞いててくださいね。", "歡迎回來，我正要準備練習了，領航你可以在旁邊聽哦~", "0", "0", "0", "cv_nozomi_sw_34", "0", "0"},
[401933] = {401933, 10019, 35, 27, "0", "0", "The\u{0020}practice\u{0020}of\u{0020}combat\u{0020}hasn't\u{0020}been\u{0020}neglected\u{0020}either!", "戦闘訓練もちゃんとしてますよ！", "戰鬥的練習也沒有落下！", "0", "0", "0", "cv_nozomi_sw_35", "0", "0"},
[401934] = {401934, 10019, 36, 28, "0", "0", "The\u{0020}path\u{0020}of\u{0020}a\u{0020}driver\u{0020}is\u{0020}as\u{0020}cruel\u{0020}as\u{0020}that\u{0020}of\u{0020}an\u{0020}idol.", "ドライバーの世界もアイドルと同じくらい過酷なんですね。", "駕駛員的道路也和偶像一樣殘酷呢。", "0", "0", "0", "cv_nozomi_sw_36", "0", "0"},
[401935] = {401935, 10019, 37, 29, "0", "0", "Let's\u{0020}invite\u{0020}everyone\u{0020}to\u{0020}listen\u{0020}next\u{0020}time!", "みなさんもライブに来てくださいねー！", "下次邀請大家一起來聽吧！", "0", "0", "0", "cv_nozomi_sw_37", "0", "0"},
[401936] = {401936, 10019, 38, 30, "0", "0", "Oh!\u{0020}Are\u{0020}we\u{0020}getting\u{0020}a\u{0020}new\u{0020}member?", "新しいメンバーですか？", "哦！新的成員要來了嗎。", "0", "0", "0", "cv_nozomi_sw_38", "0", "0"},
[401937] = {401937, 10019, 39, 31, "0", "0", "Actually,\u{0020}I\u{0020}can\u{0020}play\u{0020}the\u{0020}piano\u{0020}too.", "実はピアノも弾けちゃいますよ！", "其實鋼琴我也會彈哦。", "0", "0", "0", "cv_nozomi_sw_39", "0", "0"},
[401938] = {401938, 10019, 40, 32, "0", "0", "I\u{0020}want\u{0020}to\u{0020}try\u{0020}new\u{0020}instruments.", "新しい楽器も試してみたいです。", "想試試新的樂器。", "0", "0", "0", "cv_nozomi_sw_40", "0", "0"},
[401939] = {401939, 10019, 41, 33, "0", "0", "The\u{0020}file,\u{0020}right?\u{0020}Please\u{0020}take\u{0020}a\u{0020}look.", "プロフィールですね、どうぞ。", "檔案對吧，請看。", "0", "0", "0", "cv_nozomi_sw_41", "0", "0"},
[401940] = {401940, 10019, 42, 34, "0", "0", "Turn\u{0020}the\u{0020}volume\u{0020}up\u{0020}to\u{0020}the\u{0020}maximum!", "音量を最大にしましょう！", "把音量調到最大吧！", "0", "0", "0", "cv_nozomi_sw_42", "0", "0"},
[401941] = {401941, 10019, 43, 35, "0", "0", "Are\u{0020}there\u{0020}any\u{0020}thank-you\u{0020}letters\u{0020}from\u{0020}fans?", "ファンレターは…ありますか？", "有粉絲的感謝信嗎？", "0", "0", "0", "cv_nozomi_sw_43", "0", "0"},
[401942] = {401942, 10019, 44, 36, "0", "0", "Let's\u{0020}see\u{0020}what\u{0020}everyone\u{0020}thinks.", "みんなの感想を見てみましょう。", "看看大家的想法吧。", "0", "0", "0", "cv_nozomi_sw_44", "0", "0"},
[401943] = {401943, 10019, 45, 37, "0", "0", "Humph.", "へえー。", "哼~", "0", "0", "0", "cv_nozomi_sw_45", "0", "0"},
[402000] = {402000, 10020, 1, 1, "0", "0", "Haze\u{0020}Reverb.", "ハツリバーブ", "0", "0", "0", "0", "cv_weilai_sw_1", "0", "0"},
[402001] = {402001, 10020, 2, 2, "0", "0", "You\u{0020}want\u{0020}to\u{0020}see\u{0020}that\u{0020}badly,\u{0020}Mr.\u{0020}Pervert.\u{0020}How\u{0020}gross.\u{0020}But\u{0020}I'm\u{0020}a\u{0020}mature\u{0020}and\u{0020}gracious\u{0020}lady,\u{0020}so\u{0020}I\u{0020}won't\u{0020}say\u{0020}no.", "変態さん、そんなに私に会いたかったんですか？気持ち悪いです。だけど私も大人のレディですから、お誘いを断ったりはしませんよ。", "0", "0", "0", "0", "cv_weilai_sw_2", "0", "0"},
[402002] = {402002, 10020, 3, 3, "0", "0", "My\u{0020}name\u{0020}is\u{0020}Mirai,\u{0020}the\u{0020}Driver\u{0020}who\u{0020}made\u{0020}an\u{0020}appointment.\u{0020}Huh?...\u{0020}You've\u{0020}seen\u{0020}me\u{0020}in\u{0020}a\u{0020}dream?\u{0020}Geez,\u{0020}Mr.\u{0020}Pervert,\u{0020}that\u{0020}would\u{0020}be\u{0020}a\u{0020}100%\u{0020}harassment\u{0020}if\u{0020}I\u{0020}didn't\u{0020}remember\u{0020}anything.", "私の名前はミライです。約束通り会いに来ました。えっ？夢の中で私に会ったことがある？変態さん、あなた……それ私が何も覚えてなかったら、ただのセクハラですからね？", "0", "0", "0", "0", "cv_weilai_sw_3", "0", "0"},
[402003] = {402003, 10020, 4, 4, "0", "idle", "I-I\u{0020}lose\u{0020}interest\u{0020}in\u{0020}most\u{0020}things\u{0020}after\u{0020}three\u{0020}days...\u{0020}Even\u{0020}becoming\u{0020}a\u{0020}Driver\u{0020}was\u{0020}just\u{0020}a\u{0020}spur-of-the-moment\u{0020}decision...\u{0020}But\u{0020}I'm\u{0020}glad\u{0020}it\u{0020}led\u{0020}me\u{0020}to\u{0020}you,\u{0020}Mr.\u{0020}Pervert.", "わ、私、何事にも三日坊主なところがありまして……ドライバーになったのも、その場の勢いだったんです…。…でも、変態さんと出会えたのは幸運でした。", "0", "0", "0", "0", "cv_weilai_sw_4", "0", "0"},
[402004] = {402004, 10020, 5, 4, "0", "idle", "I\u{0020}never\u{0020}imagined\u{0020}we'd\u{0020}be\u{0020}from\u{0020}the\u{0020}same\u{0020}world...\u{0020}Or\u{0020}that\u{0020}I'd\u{0020}still\u{0020}be\u{0020}alive...\u{0020}This\u{0020}is\u{0020}so\u{0020}awkward...\u{0020}You'll\u{0020}take\u{0020}responsibility,\u{0020}right,\u{0020}Mr.\u{0020}Pervert?", "まさか変態さんと同じ世界にいられるなんて…。…しかも生きたまま…。…これは大変なことですよ。変態さん、責任取ってくれますよね？", "0", "0", "0", "0", "cv_weilai_sw_5", "0", "0"},
[402005] = {402005, 10020, 6, 4, "0", "idle", "Grown-ups\u{0020}are\u{0020}just\u{0020}people\u{0020}who\u{0020}grow\u{0020}bigger.\u{0020}So\u{0020}if\u{0020}I\u{0020}grow\u{0020}giant-sized,\u{0020}that\u{0020}makes\u{0020}me\u{0020}the\u{0020}most\u{0020}grown-up\u{0020}of\u{0020}all,\u{0020}right?", "いわゆる大人なんてものは、子供より大きいってだけです。ということは、巨大化した私は大人の中の大人ということですね。", "0", "0", "0", "0", "cv_weilai_sw_6", "0", "0"},
[402006] = {402006, 10020, 7, 5, "1_》_0_0.8", "level1", "Ah.\u{0020}I'm\u{0020}kinda\u{0020}tired\u{0020}of\u{0020}being\u{0020}a\u{0020}Driver\u{0020}already.\u{0020}When\u{0020}do\u{0020}I\u{0020}get\u{0020}to\u{0020}try\u{0020}another\u{0020}position?", "あ～、そろそろドライバーにも飽きてきました。なんか他の仕事はないんですか？", "0", "0", "0", "0", "cv_weilai_sw_7", "0", "0"},
[402007] = {402007, 10020, 8, 5, "1_》_0_0.8", "level1", "Even\u{0020}I\u{0020}have\u{0020}things\u{0020}I\u{0020}stick\u{0020}with!\u{0020}Like\u{0020}staying\u{0020}curious\u{0020}about\u{0020}everything\u{0020}new\u{0020}and\u{0020}keeping\u{0020}my\u{0020}three-minute\u{0020}passion!\u{0020}Pretty\u{0020}impressive,\u{0020}huh?", "私にだって継続している事くらいありますよ。未知への好奇心を持ち続けることと三日坊主を繰り返すことです。どうですか、凄いでしょう？", "0", "0", "0", "0", "cv_weilai_sw_8", "0", "0"},
[402008] = {402008, 10020, 9, 5, "1_》_100_1.5", "level2", "I\u{0020}even\u{0020}wore\u{0020}a\u{0020}swimsuit\u{0020}for\u{0020}you,\u{0020}and\u{0020}you\u{0020}don't\u{0020}have\u{0020}anything\u{0020}to\u{0020}say,\u{0020}Mr.\u{0020}Pervert?\u{0020}You're\u{0020}so\u{0020}bad\u{0020}with\u{0020}girls!\u{0020}Stop\u{0020}working\u{0020}already!\u{0020}Play\u{0020}with\u{0020}me!", "水着を着て来たのに、まさか少しもリアクションがないなんて…。本当に女の子の気持ちが分かっていませんね。……仕事の手を止めてください！遊びに行きますよ！", "0", "0", "0", "0", "cv_weilai_sw_9", "0", "0"},
[402009] = {402009, 10020, 10, 5, "1_》_500_2", "level3", "Graceful\u{0020}figure,\u{0020}sexy\u{0020}voice,\u{0020}wonderful\u{0020}personality,\u{0020}passionate\u{0020}about\u{0020}everything...\u{0020}The\u{0020}perfect\u{0020}lady!\u{0020}Who\u{0020}am\u{0020}I\u{0020}talking\u{0020}about?\u{0020}Obviously\u{0020}me!\u{0020}Don't\u{0020}I\u{0020}fit\u{0020}the\u{0020}bill?", "ナイスなボディ、セクシーな声、大物の気質、あらゆるものに情熱を持つ淑女の中の淑女。……誰のこと言ってるのかって？私に決まってるじゃないですか！違うって言うんですか？", "0", "0", "0", "0", "cv_weilai_sw_10", "0", "0"},
[402010] = {402010, 10020, 11, 5, "1_》_1000_2.5", "level4", "Mr.\u{0020}Pervert,\u{0020}my\u{0020}mom\u{0020}says\u{0020}she\u{0020}wants\u{0020}to\u{0020}meet\u{0020}my\u{0020}boyfriend...\u{0020}Who?\u{0020}You,\u{0020}of\u{0020}course!\u{0020}If\u{0020}you\u{0020}dare\u{0020}play\u{0020}dumb\u{0020}and\u{0020}ask\u{0020}\"since\u{0020}when\u{0020}were\u{0020}we\u{0020}dating?\"\u{0020}I'll\u{0020}bite\u{0020}you\u{0020}to\u{0020}death!", "変態さん、お母さんが彼氏を紹介しろって言ってるんですけど…。…誰のことかって？あなたに決まってるでしょう！この期に及んで「いつからそんな関係になったんだ？」なんて言う気なら噛み殺しますからね。", "0", "0", "0", "0", "cv_weilai_sw_11", "0", "0"},
[402011] = {402011, 10020, 12, 6, "0", "0", "I'll\u{0020}be\u{0020}stronger\u{0020}just\u{0020}like\u{0020}that?\u{0020}Feels\u{0020}unreal...\u{0020}Wait,\u{0020}more\u{0020}training?\u{0020}Ugh!", "これで強くなったんですね……実感はありませんが。後で特訓がある？え～…。", "0", "0", "0", "0", "cv_weilai_sw_12", "0", "0"},
[402012] = {402012, 10020, 13, 7, "0", "0", "Ahhhhhh!!\u{0020}Something's\u{0020}inside\u{0020}me!\u{0020}It's\u{0020}tingling!\u{0020}So\u{0020}gross!\u{0020}Is\u{0020}this\u{0020}how\u{0020}Mr.\u{0020}Pervert\u{0020}harasses\u{0020}all\u{0020}the\u{0020}Heroines\u{0020}with\u{0020}[Synesthesia]?", "ぎゃああああ！何かが体の中に入って来きます！ムズムズします！気持ち悪い！変態さん、通感覚でヒロイン達にこんなセクハラじみたことしてたんですか！？", "0", "0", "0", "0", "cv_weilai_sw_13", "0", "0"},
[402013] = {402013, 10020, 14, 8, "0", "0", "So\u{0020}tired...\u{0020}I\u{0020}can't\u{0020}take\u{0020}it\u{0020}anymore.\u{0020}Maybe\u{0020}we\u{0020}should\u{0020}just\u{0020}quit\u{0020}training!", "疲れました…もう限界です…！やっぱり特訓はやめておきましょう！", "0", "0", "0", "0", "cv_weilai_sw_14", "0", "0"},
[402014] = {402014, 10020, 15, 9, "0", "0", "Eh?\u{0020}You\u{0020}said\u{0020}you\u{0020}want\u{0020}to\u{0020}protect\u{0020}everyone\u{0020}with\u{0020}me...\u{0020}That's\u{0020}so\u{0020}unfair,\u{0020}saying\u{0020}something\u{0020}like\u{0020}that.\u{0020}I-I'll\u{0020}try\u{0020}to\u{0020}live\u{0020}up\u{0020}to\u{0020}your\u{0020}expectations.", "えっ？……私と一緒にみんなを守りたいって……ほんと言い回しが卑怯ですねあなたって。……わ、私もできるだけ頑張ってみますよ。", "0", "0", "0", "0", "cv_weilai_sw_15", "0", "0"},
[402015] = {402015, 10020, 16, 10, "0", "0", "What...?\u{0020}I\u{0020}have\u{0020}to\u{0020}fight\u{0020}too?", "は？私も戦場に出るんですか？", "0", "0", "0", "0", "cv_weilai_sw_16", "0", "0"},
[402016] = {402016, 10020, 17, 11, "0", "0", "E-easy\u{0020}peasy!\u{0020}Okay,\u{0020}I'm\u{0020}over\u{0020}being\u{0020}a\u{0020}Driver\u{0020}now.", "ら、楽勝でしたね。ふぅ…私、もうドライバーという仕事に飽きちゃったかもです。", "0", "0", "0", "0", "cv_weilai_sw_17", "0", "0"},
