[402024] = {402024, 10020, 25, 18, "0", "0", "If\u{0020}you're\u{0020}going\u{0020}to\u{0020}expect\u{0020}things\u{0020}from\u{0020}me,\u{0020}then\u{0020}keep\u{0020}your\u{0020}eyes\u{0020}on\u{0020}me\u{0020}properly!!!", "私に期待してるんだったら、絶対に目を離さないでくださいよ！！！！", "0", "0", "0", "0", "cv_weilai_sw_25", "0", "0"},
[402025] = {402025, 10020, 27, 20, "0", "0", "Hmm...\u{0020}You\u{0020}want\u{0020}to\u{0020}bathe\u{0020}together?\u{0020}O-Okay,\u{0020}come\u{0020}on\u{0020}in.\u{0020}I'm\u{0020}ready.", "へぇ……私と一緒にお風呂に入りたいんですか？い、いいでしょう。準備はできてますので。", "0", "0", "0", "0", "cv_weilai_sw_27", "0", "0"},
