[402029] = {402029, 10020, 31, 23, "0", "0", "No\u{0020}guarantee\u{0020}what\u{0020}happens\u{0020}if\u{0020}you\u{0020}answer\u{0020}wrong...", "答えを間違えたらどうなるか分かってますよね……", "0", "0", "0", "0", "cv_weilai_sw_31", "0", "0"},
[402030] = {402030, 10020, 32, 24, "0", "0", "I\u{0020}knew\u{0020}you'd\u{0020}recognize\u{0020}me!\u{0020}After\u{0020}all,\u{0020}I'm\u{0020}your\u{0020}Heroine!", "間違うはずがないって思ってましたよ。だって私はあなたのヒロインですもんね！", "0", "0", "0", "0", "cv_weilai_sw_32", "0", "0"},
[402031] = {402031, 10020, 33, 25, "0", "0", "Y-you\u{0020}promised\u{0020}to\u{0020}keep\u{0020}me\u{0020}in\u{0020}your\u{0020}heart...", "わ、私のことを気にかけてるって言ってたくせに……", "0", "0", "0", "0", "cv_weilai_sw_33", "0", "0"},
[402032] = {402032, 10020, 34, 26, "0", "0", "Ah...\u{0020}You're\u{0020}back!\u{0020}I\u{0020}thought\u{0020}you\u{0020}were\u{0020}leaving\u{0020}me\u{0020}behind!\u{0020}Just\u{0020}don't\u{0020}disappear\u{0020}like\u{0020}that!", "あ、やっと戻って来たんですね！置いてきぼりにされたかと思いました！か、勝手にいなくならないでくださいよ……。", "0", "0", "0", "0", "cv_weilai_sw_34", "0", "0"},
