[402036] = {402036, 10020, 38, 30, "0", "0", "Speaking\u{0020}of\u{0020}which,\u{0020}does\u{0020}a\u{0020}swimsuit\u{0020}count\u{0020}as\u{0020}equipment?", "そう言えば……水着も装備品なんですよね……", "0", "0", "0", "0", "cv_weilai_sw_38", "0", "0"},
[402037] = {402037, 10020, 39, 31, "0", "0", "This\u{0020}armor\u{0020}was\u{0020}literally\u{0020}developed\u{0020}to\u{0020}save\u{0020}the\u{0020}world,\u{0020}but\u{0020}they're\u{0020}making\u{0020}Drivers\u{0020}pay\u{0020}for\u{0020}it?\u{0020}That's\u{0020}just\u{0020}so\u{0020}wrong...", "……世界を救うために開発された装甲が、ドライバーにタダで提供されないなんて……なんかおかしいですよね。", "0", "0", "0", "0", "cv_weilai_sw_39", "0", "0"},
[402038] = {402038, 10020, 40, 32, "0", "0", "Mr.\u{0020}Pervert...\u{0020}I-I\u{0020}don't\u{0020}have\u{0020}a\u{0020}job\u{0020}yet...\u{0020}Can\u{0020}I\u{0020}really\u{0020}enter\u{0020}this\u{0020}store?", "変態さん……わ、私、仕事もしてないのに、こんなお店入っていいんですか……？", "0", "0", "0", "0", "cv_weilai_sw_40", "0", "0"},
[402039] = {402039, 10020, 41, 33, "0", "0", "Put\u{0020}my\u{0020}photo\u{0020}in\u{0020}your\u{0020}collection\u{0020}too,\u{0020}Mr.\u{0020}Pervert!", "私の写真も変態さんのところに置いておいてください！", "0", "0", "0", "0", "cv_weilai_sw_41", "0", "0"},
[402040] = {402040, 10020, 42, 34, "0", "0", "Let's\u{0020}mute\u{0020}everybody\u{0020}and\u{0020}see\u{0020}how\u{0020}it\u{0020}goes.", "全員ミュートしてみたらどうですかね。", "0", "0", "0", "0", "cv_weilai_sw_42", "0", "0"},
