[402100] = {402100, 10021, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "0", "0", "cv_xinxiya_33", "0", "0"},
[402101] = {402101, 10021, 2, 2, "0", "0", "Leave\u{0020}it\u{0020}to\u{0020}us.", "私たちに任せてください。", "交給我們吧。", "0", "0", "0", "cv_xinxiya_2", "0", "0"},
[402102] = {402102, 10021, 3, 3, "0", "0", "Nice\u{0020}to\u{0020}meet\u{0020}you,\u{0020}Navigator\u{0020}of\u{0020}Danube.\u{0020}We're\u{0020}Cynthia\u{0020}and\u{0020}Cynemia,\u{0020}the\u{0020}two-in-one\u{0020}Driver.", "はじめまして、ダニューブのナビゲーター。私たちは二つで一つのドライバー、シンシアとシンミアです。", "初次見面，多瑙的領航，我們是兩人一體的駕駛員，辛西婭，辛米亞。", "0", "0", "0", "cv_xinxiya_1", "0", "0"},
[402103] = {402103, 10021, 4, 4, "0", "idle", "Just\u{0020}standing\u{0020}here\u{0020}is\u{0020}a\u{0020}bit\u{0020}boring...\u{0020}\nHow\u{0020}about\u{0020}we\u{0020}go\u{0020}for\u{0020}a\u{0020}walk,\u{0020}Navigator?", "立っているだけでは少し退屈ですから……。みんなでお散歩に行こうよ！ナビゲーター。", "光是站在這裏稍微有些無聊……\n不如一起出去轉轉吧，領航。", "0", "0", "0", "cv_xinxiya_3", "0", "0"},
[402104] = {402104, 10021, 5, 4, "0", "idle", "No\u{0020}enemies\u{0020}around\u{0020}the\u{0020}Ark,\u{0020}so\u{0020}don't\u{0020}worry.\u{0020}\nEven\u{0020}if\u{0020}any\u{0020}appear,\u{0020}we\u{0020}can\u{0020}handle\u{0020}them\u{0020}in\u{0020}no\u{0020}time.", "方舟周辺に敵影、ありません。大丈夫です。もし敵がきても、私たちなら一瞬でやっつけちゃうしね。", "方舟周邊沒有任何敵人，還請不用太過操心。\n即便是出現敵人了，我們也能在瞬間搞定吧。", "0", "0", "0", "cv_xinxiya_4", "0", "0"},
[402105] = {402105, 10021, 6, 4, "0", "idle", "I\u{0020}envy\u{0020}you,\u{0020}being\u{0020}able\u{0020}to\u{0020}travel\u{0020}the\u{0020}world.\u{0020}We're\u{0020}stuck\u{0020}on\u{0020}the\u{0020}Ark\u{0020}most\u{0020}of\u{0020}the\u{0020}time.", "世界中を旅できるナビゲーターが羨ましいなあ。私たちは基本方舟に乗ってるだけだからねー。", "真羡慕你可以全世界到處跑啊，我們基本上就只能在方舟上行動。", "0", "0", "0", "cv_xinxiya_30", "0", "0"},
[402106] = {402106, 10021, 7, 5, "1_》_0_0.8", "level1", "Hey,\u{0020}it's\u{0020}a\u{0020}rare\u{0020}chance!\u{0020}Let's\u{0020}head\u{0020}to\u{0020}the\u{0020}city\u{0020}with\u{0020}Flora\u{0020}this\u{0020}weekend.\u{0020}Will\u{0020}you\u{0020}come\u{0020}too,\u{0020}Navigator?", "せっかくの機会ですから、週末はフローラと一緒に街に行く予定です。……ナビゲーターもご一緒にいかがですか？", "機會難得，週末一起和芙羅拉到城裏逛逛吧，領航也要一起來嗎？", "0", "0", "0", "cv_xinxiya_31", "0", "0"},
[402107] = {402107, 10021, 8, 5, "1_》_0_0.8", "level1", "Huh?\u{0020}Were\u{0020}you\u{0020}calling\u{0020}me,\u{0020}or\u{0020}Cynemia?", "あ……私に何か、ご用でしょうか？それとも、シンミアにですか？", "哎？是在叫我嗎？還是說，辛米亞？", "0", "0", "0", "cv_xinxiya_5", "0", "0"},
[402108] = {402108, 10021, 9, 5, "1_》_100_1.5", "level2", "Want\u{0020}to\u{0020}get\u{0020}closer\u{0020}to\u{0020}Cynthia?\u{0020}I\u{0020}can\u{0020}tell\u{0020}you\u{0020}how...\nCynemia...", "シンシアと仲良くなりたいの？じゃあいい方法を教えるね。シンミア……", "想要和辛西婭處好關係嗎？我能告訴你方法哦。\n辛米亞……", "0", "0", "0", "cv_xinxiya_6", "0", "0"},
[402109] = {402109, 10021, 10, 5, "1_》_500_2", "level3", "Hmm...\u{0020}Sorry,\u{0020}I\u{0020}don't\u{0020}really\u{0020}remember\u{0020}you.\u{0020}But\u{0020}to\u{0020}be\u{0020}fair,\u{0020}I\u{0020}don't\u{0020}really\u{0020}remember\u{0020}anyone\u{0020}except\u{0020}Cynthia.\u{0020}Still,\u{0020}I\u{0020}feel\u{0020}like\u{0020}you're\u{0020}someone\u{0020}important\u{0020}to\u{0020}both\u{0020}of\u{0020}us,\u{0020}deep\u{0020}down.", "えーっと……ごめんね。あなたのこと、覚えてないんだ。っていうより、私はシンシア以外の人のことはあんまり覚えてないの。でもなぜか、私にも、シンシアにも、あなたがとても大切な人だって気がするんだ。", "嗯……抱歉，我對你沒有任何印象。不過話說回來我對除了辛西婭外的所有人都沒有什麼印象。但是潛意識裏，我還是覺得你是個對我還有她而言非常重要的人。", "0", "0", "0", "cv_xinxiya_7", "0", "0"},
[402110] = {402110, 10021, 11, 5, "1_》_1000_2.5", "level4", "As\u{0020}you\u{0020}can\u{0020}see,\u{0020}she's\u{0020}like\u{0020}my\u{0020}shadow.\u{0020}If\u{0020}you\u{0020}don't\u{0020}mind,\u{0020}the\u{0020}three\u{0020}of\u{0020}us\u{0020}can\u{0020}stay\u{0020}like\u{0020}this...", "ご覧の通り、私とシンミアは表裏一体の存在。もしあなたが宜しければ、私達三人、このままで……いたいです……", "正如你所見，她就像是我的影子一樣。如果你不介意的話，我們三個人就像現在這樣相處就好……", "0", "0", "0", "cv_xinxiya_8", "0", "0"},
[402111] = {402111, 10021, 12, 6, "0", "0", "Let's\u{0020}get\u{0020}stronger\u{0020}together,\u{0020}Cynemia.", "一緒に強くなろう。シンミア。", "一起變強吧，辛米亞。", "0", "0", "0", "cv_xinxiya_9", "0", "0"},
[402112] = {402112, 10021, 13, 7, "0", "0", "Great\u{0020}job,\u{0020}Cynthia!\u{0020}We've\u{0020}gotten\u{0020}stronger\u{0020}again!", "やったね、シンシア！これで私たち、もっと強くなれたよ！", "太好了，辛西婭，這樣一來我們就變得更強了！。", "0", "0", "0", "cv_xinxiya_10", "0", "0"},
[402113] = {402113, 10021, 14, 8, "0", "0", "This\u{0020}moment,\u{0020}arriving\u{0020}here\u{0020}with\u{0020}you,\u{0020}is\u{0020}the\u{0020}most\u{0020}precious\u{0020}in\u{0020}my\u{0020}life.", "あなたと一緒にここまで来ることができました。いま私は、人生で一番大切な瞬間を迎えています……", "和你們一起抵達這裏的此刻，是我人生中最寶貴的時刻。", "0", "0", "0", "cv_xinxiya_11", "0", "0"},
[402114] = {402114, 10021, 15, 9, "0", "0", "Cynemia,\u{0020}let's\u{0020}try\u{0020}out\u{0020}the\u{0020}new\u{0020}skill\u{0020}together.", "シンミア、一緒に新しいスキルを試してみよう！", "辛米亞，一起試試新的技能吧。", "0", "0", "0", "cv_xinxiya_12", "0", "0"},
[402115] = {402115, 10021, 16, 10, "0", "0", "Let's\u{0020}do\u{0020}this\u{0020}together,\u{0020}Cynemia.", "シンミア、一緒に行こう。", "一起上吧，辛米亞。", "0", "0", "0", "cv_xinxiya_13", "0", "0"},
[402116] = {402116, 10021, 17, 11, "0", "0", "The\u{0020}battle's\u{0020}over.\u{0020}Next\u{0020}time,\u{0020}let's\u{0020}fight\u{0020}side\u{0020}by\u{0020}side\u{0020}again.", "戦闘終了。次も一緒に戦いましょう。", "戰鬥結束，下次再一起並肩作戰吧。", "0", "0", "0", "cv_xinxiya_14", "0", "0"},
[402117] = {402117, 10021, 18, 12, "0", "0", "Ahehe,\u{0020}don't\u{0020}worry\u{0020}about\u{0020}that\u{0020}tiny\u{0020}mistake.", "えへへ。ちょっとぐらいのミスは気にしない、気にしない！", "哎嘿嘿，稍微有點點小失誤就別在意啦。", "0", "0", "0", "cv_xinxiya_15", "0", "0"},
[402118] = {402118, 10021, 19, 13, "0", "0", "I'm\u{0020}sorry...\u{0020}I\u{0020}could've\u{0020}done\u{0020}better...", "すみません…もっと上手くできたはず……", "對不起…我明明可以做得更好的……", "0", "0", "0", "cv_xinxiya_16", "0", "0"},
[402119] = {402119, 10021, 20, 14, "0", "0", "I\u{0020}can't...\u{0020}let\u{0020}anyone\u{0020}hurt\u{0020}Cynthia...", "絶対に…シンシアを傷つけさせない…！", "絕對…不能讓你們傷害辛西婭……", "0", "0", "0", "cv_xinxiya_17", "0", "0"},
[402120] = {402120, 10021, 21, 15, "0", "0", "This\u{0020}is\u{0020}the\u{0020}end...", "ここまでです…！", "到此為止了……", "0", "0", "0", "cv_xinxiya_19", "0", "0"},
