[402301] = {402301, 10023, 2, 2, "0", "0", "This\u{0020}lively\u{0020}scene…\u{0020}it\u{0020}feels\u{0020}like\u{0020}something\u{0020}I\u{0020}once\u{0020}saw\u{0020}on\u{0020}Etan,\u{0020}mo.", "0", "這副繁榮的景象，曾幾何時在埃塔星上也看見過。", "0", "0", "0", "cv_mo_2", "0", "0"},
[402302] = {402302, 10023, 3, 3, "0", "0", "You're\u{0020}the\u{0020}Navigator?\u{0020}You're\u{0020}much\u{0020}younger\u{0020}than\u{0020}I\u{0020}imagined,\u{0020}mo.\u{0020}I'm\u{0020}Mo,\u{0020}a\u{0020}\"Shepherd\"—basically,\u{0020}someone\u{0020}who\u{0020}takes\u{0020}care\u{0020}of\u{0020}children,\u{0020}mo.", "0", "您就是領航？比我想像要年輕好多嗼。我是摩，是位“牧者”，簡單來說就是照顧小孩子的職業嗼。", "0", "0", "0", "cv_mo_3", "0", "0"},
[402303] = {402303, 10023, 4, 4, "0", "idle", "From\u{0020}up\u{0020}here,\u{0020}Navigator,\u{0020}you\u{0020}really\u{0020}do\u{0020}look\u{0020}so\u{0020}small—like\u{0020}a\u{0020}child…\u{0020}no,\u{0020}more\u{0020}like\u{0020}an\u{0020}embryo,\u{0020}mo.", "0", "這樣看領航真的好小，小得像個孩子……不，應該說更像是胚胎嗼。", "0", "0", "0", "cv_mo_4", "0", "0"},
[402304] = {402304, 10023, 5, 4, "0", "idle", "Do\u{0020}I\u{0020}look\u{0020}scary\u{0020}like\u{0020}this,\u{0020}mo?\u{0020}Maybe\u{0020}I\u{0020}should\u{0020}just\u{0020}stand\u{0020}still\u{0020}and\u{0020}pretend\u{0020}to\u{0020}be\u{0020}a\u{0020}statue,\u{0020}mo.", "0", "我這個樣子不會嚇到別人嗎？我還是一動不動裝成雕像好了嗼。", "0", "0", "0", "cv_mo_5", "0", "0"},
[402305] = {402305, 10023, 6, 4, "0", "idle", "Shirogane\u{0020}and\u{0020}Mizo\u{0020}are\u{0020}always\u{0020}running\u{0020}around,\u{0020}busy\u{0020}with\u{0020}the\u{0020}affairs\u{0020}of\u{0020}our\u{0020}people.\u{0020}Compared\u{0020}to\u{0020}them,\u{0020}I\u{0020}feel\u{0020}like\u{0020}I'm\u{0020}slacking\u{0020}off\u{0020}as\u{0020}the\u{0020}elder,\u{0020}mo.\u{0020}But\u{0020}what\u{0020}can\u{0020}I\u{0020}do?\u{0020}There\u{0020}are\u{0020}no\u{0020}more\u{0020}children\u{0020}left\u{0020}for\u{0020}me\u{0020}to\u{0020}take\u{0020}care\u{0020}of,\u{0020}mo.", "0", "銀和渠每天都在為族人的事情忙東忙西，相比之下我這個年長者是不是悠閒過頭了嗼？這也是沒辦法的事，誰讓現在沒有孩子讓我照顧呢。", "0", "0", "0", "cv_mo_6", "0", "0"},
[402306] = {402306, 10023, 7, 5, "1_》_0_0.8", "level1", "When\u{0020}I\u{0020}was\u{0020}younger,\u{0020}I\u{0020}thought\u{0020}about\u{0020}switching\u{0020}jobs—maybe\u{0020}becoming\u{0020}a\u{0020}singer\u{0020}or\u{0020}an\u{0020}idol,\u{0020}mo.\u{0020}But\u{0020}I\u{0020}just\u{0020}couldn't\u{0020}leave\u{0020}the\u{0020}little\u{0020}ones\u{0020}behind.\u{0020}And\u{0020}before\u{0020}I\u{0020}knew\u{0020}it,\u{0020}here\u{0020}I\u{0020}am.\u{0020}If\u{0020}you\u{0020}convert\u{0020}my\u{0020}age\u{0020}to\u{0020}Earth\u{0020}years,\u{0020}I'd\u{0020}be\u{0020}around...\u{0020}24,\u{0020}mo?", "0", "年輕的時候也想過換個工作，比如“歌手”、“偶像”。但還是放不下那些小崽子們，一轉眼也已經這個年紀了，換算成地球人年齡的話差不多有……24歲？", "0", "0", "0", "cv_mo_7", "0", "0"},
[402307] = {402307, 10023, 8, 5, "1_》_0_0.8", "level1", "Hmmm,\u{0020}don't\u{0020}act\u{0020}so\u{0020}mischievous,\u{0020}like\u{0020}a\u{0020}little\u{0020}kid,\u{0020}mo.", "0", "唔……你就別像孩子一樣調皮了嗼。", "0", "0", "0", "cv_mo_8", "0", "0"},
[402308] = {402308, 10023, 9, 5, "1_》_100_1.5", "level2", "Why\u{0020}did\u{0020}I\u{0020}become\u{0020}a\u{0020}Driver?\u{0020}Because\u{0020}I\u{0020}couldn't\u{0020}find\u{0020}any\u{0020}other\u{0020}work,\u{0020}mo.\u{0020}A\u{0020}\"Shepherd\"\u{0020}takes\u{0020}care\u{0020}of\u{0020}children,\u{0020}but\u{0020}look\u{0020}around—where\u{0020}are\u{0020}the\u{0020}Etan\u{0020}children\u{0020}now,\u{0020}mo?", "0", "為什嗼要做駕駛員？因為找不到其他工作了嗼。“牧者”是負責照顧孩子的職業，可是你看埃塔人居住地哪裡還有埃塔人的孩子嗼。", "0", "0", "0", "cv_mo_9", "0", "0"},
[402309] = {402309, 10023, 10, 5, "1_》_500_2", "level3", "You\u{0020}must\u{0020}have\u{0020}a\u{0020}lot\u{0020}to\u{0020}deal\u{0020}with,\u{0020}Navigator.\u{0020}Don't\u{0020}waste\u{0020}your\u{0020}time\u{0020}on\u{0020}someone\u{0020}like\u{0020}me,\u{0020}mo.\u{0020}Not\u{0020}that\u{0020}I\u{0020}want\u{0020}you\u{0020}to\u{0020}leave…\u{0020}Actually,\u{0020}having\u{0020}you\u{0020}here\u{0020}to\u{0020}keep\u{0020}me\u{0020}company\u{0020}makes\u{0020}me\u{0020}really\u{0020}happy,\u{0020}mo.", "0", "領航應該有很多事要忙吧，不用特地把時間浪費在我一個閒人身上嗼。我不是在趕你走啦……唔……其實你能花時間陪我我也是很開心的嗼。", "0", "0", "0", "cv_mo_10", "0", "0"},
[402310] = {402310, 10023, 11, 5, "1_》_1000_2.5", "level4", "Earth's\u{0020}way\u{0020}of\u{0020}reproduction\u{0020}is\u{0020}so\u{0020}different\u{0020}from\u{0020}Etan's,\u{0020}mo.\u{0020}Maybe\u{0020}it's\u{0020}the\u{0020}answer\u{0020}to\u{0020}our\u{0020}current\u{0020}struggles.\u{0020}Navigator,\u{0020}can\u{0020}you\u{0020}teach\u{0020}me?\u{0020}It's\u{0020}for\u{0020}the\u{0020}survival\u{0020}of\u{0020}the\u{0020}Etan\u{0020}people,\u{0020}mo.", "0", "地球人繁衍的方法和埃塔人完全不一樣嗼。這或許能解決埃塔人目前遇到的難題。領航能不能教教我嗼？就當是為埃塔人種族的延續做貢獻了嗼。", "0", "0", "0", "cv_mo_11", "0", "0"},
