[402602] = {402602, 10026, 3, 3, "0", "0", "Hey\u{0020}there,\u{0020}young\u{0020}Navigator!\u{0020}I\u{0020}was\u{0020}expecting\u{0020}a\u{0020}smelly\u{0020}old\u{0020}dude,\u{0020}like\u{0020}really\u{0020}sweaty.", "0", "吼呀，好年輕的領航呀，還以為會是個滿身汗味的臭大叔呢。", "0", "0", "0", "cv_nasijia_3", "0", "0"},
[402603] = {402603, 10026, 4, 4, "0", "idle", "Why\u{0020}don't\u{0020}you\u{0020}come\u{0020}sit\u{0020}here\u{0020}too?\u{0020}It\u{0020}seems\u{0020}like\u{0020}you\u{0020}have\u{0020}nothing\u{0020}to\u{0020}do\u{0020}anyway.", "0", "你要不也來這坐著吧，反正看你也很閑呢。", "0", "0", "0", "cv_nasijia_4", "0", "0"},
[402604] = {402604, 10026, 5, 4, "0", "idle", "I\u{0020}just\u{0020}thought\u{0020}of\u{0020}something\u{0020}interesting.\u{0020}If\u{0020}you\u{0020}want\u{0020}to\u{0020}know,\u{0020}kneel\u{0020}down\u{0020}and\u{0020}beg\u{0020}me.", "0", "突然想到件有趣的事，想知道的話就跪下來求我吧。", "0", "0", "0", "cv_nasijia_5", "0", "0"},
[402605] = {402605, 10026, 6, 4, "0", "idle", "Of\u{0020}course,\u{0020}I'm\u{0020}different\u{0020}from\u{0020}the\u{0020}other\u{0020}drivers\u{0020}in\u{0020}the\u{0020}team.\u{0020}I'm\u{0020}just\u{0020}affiliated\u{0020}here.\u{0020}Don't\u{0020}you\u{0020}get\u{0020}it,\u{0020}stupid\u{0020}Navigator?", "0", "我和隊伍的其他駕駛員當然不一樣了，只是掛名在這而已，你不會這都弄不清楚吧，笨蛋領航。", "0", "0", "0", "cv_nasijia_6", "0", "0"},
[402606] = {402606, 10026, 7, 5, "1_》_0_0.8", "level1", "I'm\u{0020}calling\u{0020}security.", "0", "我可要呼叫警備了哦。", "0", "0", "0", "cv_nasijia_7", "0", "0"},
[402607] = {402607, 10026, 8, 5, "1_》_0_0.8", "level1", "In\u{0020}public\u{0020}like\u{0020}this,\u{0020}you\u{0020}wouldn't\u{0020}want\u{0020}to\u{0020}do\u{0020}something\u{0020}like\u{0020}that\u{0020}to\u{0020}me,\u{0020}right?", "0", "在這大庭廣眾之下，領航不會想對我做那種事情吧。", "0", "0", "0", "cv_nasijia_8", "0", "0"},
[402608] = {402608, 10026, 9, 5, "1_》_100_1.5", "level2", "Eh?\u{0020}So,\u{0020}you\u{0020}are\u{0020}actually\u{0020}much\u{0020}older\u{0020}than\u{0020}me?\u{0020}I\u{0020}would\u{0020}never\u{0020}have\u{0020}guessed.\u{0020}You\u{0020}grew\u{0020}old\u{0020}on\u{0020}me\u{0020}all\u{0020}of\u{0020}a\u{0020}sudden,\u{0020}heh?", "0", "誒~原來領航比我大這麼多嗎？外表上完全看不出呢。一下子變成大叔了呢，領航大叔。", "0", "0", "0", "cv_nasijia_9", "0", "0"},
[402609] = {402609, 10026, 10, 5, "1_》_500_2", "level3", "I\u{0020}heard\u{0020}you\u{0020}got\u{0020}pranked!\u{0020}Heehee.\u{0020}It\u{0020}was\u{0020}hilarious\u{0020}to\u{0020}see\u{0020}you\u{0020}drink\u{0020}juice\u{0020}with\u{0020}chili\u{0020}sauce\u{0020}in\u{0020}one\u{0020}gulp...\u{0020}But\u{0020}it\u{0020}wasn't\u{0020}me!\u{0020}I've\u{0020}been\u{0020}on\u{0020}guard\u{0020}here\u{0020}the\u{0020}whole\u{0020}time,\u{0020}stupid\u{0020}uncle.", "0", "聽說領航被人惡作劇了呀，嘻嘻。加了辣椒醬的果汁一飲而盡的樣子真是太好笑了……當然不是我做的啦，我可是一直在這站崗呢，笨蛋大叔。", "0", "0", "0", "cv_nasijia_10", "0", "0"},
[402610] = {402610, 10026, 11, 5, "1_》_1000_2.5", "level4", "Are\u{0020}you\u{0020}free\u{0020}tomorrow\u{0020}night?\u{0020}I\u{0020}have\u{0020}something\u{0020}to\u{0020}tell\u{0020}you...\u{0020}Or\u{0020}maybe\u{0020}now...\u{0020}Navigator,\u{0020}I\u{0020}like...\u{0020}like...\u{0020}Ahahaha!\u{0020}You\u{0020}fell\u{0020}for\u{0020}it!\u{0020}Your\u{0020}heart\u{0020}was\u{0020}racing\u{0020}just\u{0020}now.\u{0020}Don't\u{0020}really\u{0020}think\u{0020}I'd\u{0020}confess\u{0020}to\u{0020}you,\u{0020}stupid\u{0020}uncle!", "0", "明天晚上有空嗎?我有些話像對領航說……或者現在……領航，我喜……喜……啊哈哈哈，上當了吧，你的心剛才跳得好快哦。不會真以為我會向你表白吧，笨蛋大叔。", "0", "0", "0", "cv_nasijia_11", "0", "0"},
[402611] = {402611, 10026, 12, 6, "0", "0", "Is\u{0020}this\u{0020}all\u{0020}you\u{0020}can\u{0020}offer\u{0020}to\u{0020}get\u{0020}rid\u{0020}of\u{0020}me?", "0", "才這點就想打發我嗎？", "0", "0", "0", "cv_nasijia_12", "0", "0"},
