[402616] = {402616, 10026, 17, 11, "0", "0", "You\u{0020}went\u{0020}down\u{0020}without\u{0020}much\u{0020}effort.\u{0020}So\u{0020}weak.", "0", "還沒怎麼用力就倒下了，真弱。", "0", "0", "0", "cv_nasijia_17", "0", "0"},
