[402641] = {402641, 10026, 43, 35, "0", "0", "So\u{0020}pitiful.\u{0020}Not\u{0020}a\u{0020}single\u{0020}love\u{0020}letter.", "0", "真可憐啊，一封情書都沒有呢。", "0", "0", "0", "cv_nasijia_43", "0", "0"},
