[402701] = {402701, 10027, 2, 2, "0", "0", "You're\u{0020}my\u{0020}Navigator,\u{0020}and\u{0020}having\u{0020}you\u{0020}handle\u{0020}the\u{0020}boring,\u{0020}mundane\u{0020}tasks\u{0020}would\u{0020}be\u{0020}an\u{0020}insult\u{0020}to\u{0020}me.", "0", "作為我的領航，如果盡做些無趣的事，那會是對我的侮辱。", "0", "0", "0", "cv_alvitr_2", "0", "0"},
[402702] = {402702, 10027, 3, 3, "0", "0", "Are\u{0020}you\u{0020}the\u{0020}one\u{0020}joining\u{0020}forces\u{0020}with\u{0020}me\u{0020}this\u{0020}time?\u{0020}Ha!\u{0020}The\u{0020}Navigator\u{0020}of\u{0020}the\u{0020}Danube,\u{0020}try\u{0020}to\u{0020}keep\u{0020}up\u{0020}with\u{0020}my\u{0020}pace.", "0", "這次與我合作的對象是你嗎？呵，多瑙的領航，竭盡全力跟上我的步伐吧。", "0", "0", "0", "cv_alvitr_3", "0", "0"},
[402703] = {402703, 10027, 4, 4, "0", "idle", "What\u{0020}a\u{0020}shame.\u{0020}Not\u{0020}a\u{0020}single\u{0020}person\u{0020}in\u{0020}AEGIS\u{0020}can\u{0020}fight\u{0020}alongside\u{0020}me.", "0", "真是遺憾，艾吉斯之中能與我並肩而戰的人，一個也沒有呢。", "0", "0", "0", "cv_alvitr_4", "0", "0"},
[402704] = {402704, 10027, 5, 4, "0", "idle", "Weak\u{0020}and\u{0020}powerless\u{0020}humans\u{0020}should\u{0020}just\u{0020}lie\u{0020}down\u{0020}and\u{0020}look\u{0020}up\u{0020}at\u{0020}my\u{0020}greatness.\u{0020}I'll\u{0020}bring\u{0020}victories,\u{0020}not\u{0020}just\u{0020}one,\u{0020}but\u{0020}many,\u{0020}and\u{0020}eventually\u{0020}wipe\u{0020}out\u{0020}all\u{0020}the\u{0020}Sins.", "0", "貧瘠而無力的人類，只需要臥在地上瞻望我偉大的背影即可。我會帶來勝利，帶來不止一次的勝利，最終將原罪盡數屠戮。", "0", "0", "0", "cv_alvitr_5", "0", "0"},
[402705] = {402705, 10027, 6, 4, "0", "idle", "Naive\u{0020}Geiro,\u{0020}putting\u{0020}her\u{0020}hopes\u{0020}in\u{0020}others\u{0020}and\u{0020}being\u{0020}content\u{0020}to\u{0020}be\u{0020}a\u{0020}stepping\u{0020}stone\u{0020}for\u{0020}ordinary\u{0020}people...\u{0020}I\u{0020}won't\u{0020}be\u{0020}that\u{0020}childish.\u{0020}I'll\u{0020}become\u{0020}humanity's\u{0020}leader.\u{0020}And\u{0020}you,\u{0020}Navigator,\u{0020}will\u{0020}assist\u{0020}me.", "0", "天真的潔蘿，將希望寄託在他人身上，甘心成為凡人的基石...不，應該說是墊腳石。我可不會像她那麼幼稚...我將成為人類的領袖。到時候，你就好好輔佐我吧，領航。", "0", "0", "0", "cv_alvitr_6", "0", "0"},
[402706] = {402706, 10027, 7, 5, "1_》_0_0.8", "level1", "Humans\u{0020}are\u{0020}creatures\u{0020}without\u{0020}much\u{0020}tolerance.\u{0020}They\u{0020}fear\u{0020}what\u{0020}they\u{0020}can't\u{0020}understand.\u{0020}But\u{0020}that's\u{0020}okay.\u{0020}Guiding\u{0020}weak\u{0020}humans\u{0020}is\u{0020}part\u{0020}of\u{0020}my\u{0020}mission.", "0", "人類是沒有肚量的生物，對超出常識的事物只會心懷恐懼。無妨，引導無能的人類前進，本就是我的使命。", "0", "0", "0", "cv_alvitr_7", "0", "0"},
[402707] = {402707, 10027, 8, 5, "1_》_0_0.8", "level1", "Are\u{0020}you\u{0020}surprised\u{0020}I'm\u{0020}a\u{0020}science\u{0020}officer?\u{0020}Mastering\u{0020}human\u{0020}knowledge\u{0020}is\u{0020}easy\u{0020}for\u{0020}someone\u{0020}like\u{0020}me.", "0", "怎麼，你很驚訝我是一名科學官嗎？掌握區區人類的淺薄學識，對我來說不是什麼難事。", "0", "0", "0", "cv_alvitr_8", "0", "0"},
[402708] = {402708, 10027, 9, 5, "1_》_100_1.5", "level2", "Why\u{0020}does\u{0020}Stephanie\u{0020}trust\u{0020}you\u{0020}so\u{0020}much?\u{0020}I'm\u{0020}staying\u{0020}by\u{0020}your\u{0020}side\u{0020}only\u{0020}to\u{0020}figure\u{0020}it\u{0020}out.\u{0020}Try\u{0020}to\u{0020}live\u{0020}up\u{0020}to\u{0020}my\u{0020}expectations,\u{0020}human.", "0", "史蒂芬妮為什麼會如此信任你？我是為了弄清楚這件事才沒從你身邊離開的。盡可能滿足我對你的期待吧，人類。", "0", "0", "0", "cv_alvitr_9", "0", "0"},
[402709] = {402709, 10027, 10, 5, "1_》_500_2", "level3", "Stephanie\u{0020}and\u{0020}I\u{0020}talked\u{0020}about\u{0020}humanity's\u{0020}fate\u{0020}in\u{0020}this\u{0020}timeline.\u{0020}I\u{0020}don't\u{0020}have\u{0020}much\u{0020}sympathy\u{0020}for\u{0020}humans...\u{0020}but\u{0020}some\u{0020}are\u{0020}worth\u{0020}saving.\u{0020}For\u{0020}example...\u{0020}well,\u{0020}let's\u{0020}just\u{0020}say\u{0020}it's\u{0020}worth\u{0020}trying\u{0020}if\u{0020}I'm\u{0020}tasked\u{0020}with\u{0020}saving\u{0020}the\u{0020}world.", "0", "史蒂芬妮和我聊過這條世界線上人類的結局。我不會同情人類...不過，人類之中也不盡是些無藥可救的人，比如說...咳，總之，只是讓我擔負起拯救世界的責任，那還是值得一試的。", "0", "0", "0", "cv_alvitr_10", "0", "0"},
[402710] = {402710, 10027, 11, 5, "1_》_1000_2.5", "level4", "I'll\u{0020}stay\u{0020}with\u{0020}you\u{0020}until\u{0020}the\u{0020}end\u{0020}of\u{0020}this\u{0020}world,\u{0020}no\u{0020}matter\u{0020}what\u{0020}it\u{0020}looks\u{0020}like.\u{0020}You\u{0020}want\u{0020}to\u{0020}know\u{0020}why?\u{0020}Hehe,\u{0020}because\u{0020}it's\u{0020}my\u{0020}way\u{0020}of\u{0020}recognizing\u{0020}you,\u{0020}human,\u{0020}and\u{0020}rewarding\u{0020}you\u{0020}for\u{0020}your\u{0020}service.\u{0020}So\u{0020}let's\u{0020}get\u{0020}along,\u{0020}for\u{0020}however\u{0020}long\u{0020}this\u{0020}journey\u{0020}lasts,\u{0020}Navigator.", "0", "我會陪你走到這個世界的結局，無論它最終會是怎樣一副模樣。你問為什麼？呵呵，這當然是我對你這名人類的最大認可，是對你兢兢業業為我服務的獎賞。好了，接下來或短暫或漫長的時光，就讓我們好好相處吧，領航。", "0", "0", "0", "cv_alvitr_11", "0", "0"},
[402711] = {402711, 10027, 12, 6, "0", "0", "Very\u{0020}good.\u{0020}Keep\u{0020}pleasing\u{0020}me.", "0", "很好，繼續取悅我吧。", "0", "0", "0", "cv_alvitr_12", "0", "0"},
[402712] = {402712, 10027, 13, 7, "0", "0", "You've\u{0020}got\u{0020}a\u{0020}long\u{0020}road\u{0020}ahead\u{0020}of\u{0020}you.", "0", "還差得遠呢。", "0", "0", "0", "cv_alvitr_13", "0", "0"},
[402713] = {402713, 10027, 14, 8, "0", "0", "Hehehe...\u{0020}Navigator\u{0020}of\u{0020}the\u{0020}Danube,\u{0020}I\u{0020}acknowledge\u{0020}your\u{0020}effort.\u{0020}Celebrate!\u{0020}Let\u{0020}reason\u{0020}drown\u{0020}in\u{0020}frenzy.\u{0020}This\u{0020}is\u{0020}the\u{0020}greatest\u{0020}honor\u{0020}a\u{0020}mortal\u{0020}could\u{0020}hope\u{0020}for.", "0", "呵呵呵....多瑙的領航，我認可了為我做到這一步的你。放聲大笑吧，理智淹沒在狂熱中吧，這是凡人能夠得到的最大的殊榮。", "0", "0", "0", "cv_alvitr_14", "0", "0"},
[402714] = {402714, 10027, 15, 9, "0", "0", "Keep\u{0020}up\u{0020}the\u{0020}good\u{0020}work.", "0", "繼續努力吧。", "0", "0", "0", "cv_alvitr_15", "0", "0"},
[402715] = {402715, 10027, 16, 10, "0", "0", "Ants,\u{0020}prepare\u{0020}for\u{0020}judgment.", "0", "螻蟻，準備接受審判吧。", "0", "0", "0", "cv_alvitr_16", "0", "0"},
[402716] = {402716, 10027, 17, 11, "0", "0", "Rejoice!\u{0020}This\u{0020}victory\u{0020}belongs\u{0020}to\u{0020}both\u{0020}of\u{0020}us.", "0", "為此歡呼吧，這是你我攜手帶來的勝利。", "0", "0", "0", "cv_alvitr_17", "0", "0"},
[402717] = {402717, 10027, 18, 12, "0", "0", "Boring\u{0020}opponent.", "0", "無聊的對手。", "0", "0", "0", "cv_alvitr_18", "0", "0"},
[402718] = {402718, 10027, 19, 13, "0", "0", "Alright,\u{0020}I\u{0020}admit\u{0020}it...\u{0020}This\u{0020}time,\u{0020}the\u{0020}enemy\u{0020}gave\u{0020}me\u{0020}a\u{0020}bit\u{0020}of\u{0020}trouble.", "0", "姑且承認...這次的敵人給我帶來了點困擾。", "0", "0", "0", "cv_alvitr_19", "0", "0"},
[402719] = {402719, 10027, 20, 14, "0", "0", "Defeated\u{0020}by\u{0020}such\u{0020}a\u{0020}foe...\u{0020}Disgraceful.", "0", "居然被這種對手打敗了...真是丟人。", "0", "0", "0", "cv_alvitr_20", "0", "0"},
[402720] = {402720, 10027, 21, 15, "0", "0", "Begone!\u{0020}You're\u{0020}an\u{0020}annoyance.", "0", "消失吧，真礙眼。", "0", "0", "0", "cv_alvitr_22", "0", "0"},
