[402723] = {402723, 10027, 24, 17, "0", "0", "Feel\u{0020}privileged,\u{0020}for\u{0020}I\u{0020}will\u{0020}grant\u{0020}you\u{0020}eternal\u{0020}death!", "0", "感到榮幸吧，因為我將賜予你們永恆的死亡！", "0", "0", "0", "cv_alvitr_25", "0", "0"},
