[402819] = {402819, 10028, 20, 14, "0", "0", "The\u{0020}mechanism\u{0020}has\u{0020}stopped\u{0020}turning.\u{0020}Time\u{0020}for\u{0020}a\u{0020}careful\u{0020}check.", "0", "機關停轉，該仔細檢查一番了。", "0", "0", "0", "cv_mojun_20", "0", "0"},
[402820] = {402820, 10028, 21, 15, "0", "0", "Break\u{0020}before\u{0020}me!", "0", "崩解吧。", "0", "0", "0", "cv_mojun_21", "0", "0"},
