[402825] = {402825, 10028, 28, 21, "0", "0", "I'm\u{0020}not\u{0020}that\u{0020}rigid.\u{0020}When\u{0020}it's\u{0020}time\u{0020}to\u{0020}enjoy\u{0020}myself,\u{0020}I\u{0020}will\u{0020}fully\u{0020}indulge.", "0", "我心非木石，該享受的時候，自會好好享受的~", "0", "0", "0", "cv_mojun_26", "0", "0"},
[402826] = {402826, 10028, 29, 21, "0", "0", "You're\u{0020}so\u{0020}quiet,\u{0020}Navigator...\u{0020}Could\u{0020}it\u{0020}be\u{0020}you're\u{0020}observing\u{0020}me?\u{0020}Ahem,\u{0020}I\u{0020}hope\u{0020}you\u{0020}use\u{0020}that\u{0020}sharp\u{0020}gaze\u{0020}when\u{0020}you\u{0020}study.", "0", "領航如此沉默……莫非是在觀察我？咳咳，真希望你能將這份銳利的目光用在學習上。", "0", "0", "0", "cv_mojun_27", "0", "0"},
[402827] = {402827, 10028, 30, 22, "0", "0", "Let\u{0020}me\u{0020}witness\u{0020}it\u{0020}firsthand.", "0", "讓我見證一下吧。", "0", "0", "0", "cv_mojun_28", "0", "0"},
