[403001] = {403001, 10030, 2, 2, "0", "0", "My\u{0020}father\u{0020}once\u{0020}intended\u{0020}to\u{0020}mold\u{0020}me\u{0020}into\u{0020}a\u{0020}staff\u{0020}officer.\u{0020}Do\u{0020}you\u{0020}have\u{0020}similar\u{0020}ambitions?", "0", "父親曾計劃將我培養為參謀，您也有此打算嗎？", "0", "0", "0", "cv_faernaisi_2", "0", "0"},
[403002] = {403002, 10030, 3, 3, "0", "0", "I've\u{0020}heard\u{0020}you're\u{0020}a\u{0020}reasonable\u{0020}Navigator.\u{0020}Here,\u{0020}allow\u{0020}me\u{0020}to\u{0020}adhere\u{0020}more\u{0020}to\u{0020}my\u{0020}family's\u{0020}customs\u{0020}than\u{0020}to\u{0020}those\u{0020}of\u{0020}AEGIS.\u{0020}Thus,\u{0020}Captain\u{0020}of\u{0020}\"Astray\u{0020}Blossom,\"\u{0020}Farnese\u{0020}Lante,\u{0020}reports\u{0020}to\u{0020}you.", "0", "我已聽聞您是位通情達理的領航，在此請允許我更多按照家族的規則，而非艾吉斯的規則行事。那麼，“歧花”隊長，法爾奈斯·蘭特向您報道。", "0", "0", "0", "cv_faernaisi_3", "0", "0"},
[403003] = {403003, 10030, 4, 4, "0", "idle", "Ever\u{0020}since\u{0020}I\u{0020}got\u{0020}huge,\u{0020}this\u{0020}high-up\u{0020}view\u{0020}has\u{0020}never\u{0020}bothered\u{0020}me.\u{0020}It's\u{0020}just\u{0020}that\u{0020}the\u{0020}cypress\u{0020}trees\u{0020}in\u{0020}the\u{0020}garden\u{0020}now\u{0020}look\u{0020}like\u{0020}buildings,\u{0020}and\u{0020}the\u{0020}flowers\u{0020}like\u{0020}crowds.", "0", "從首次巨大化起，這種高度的視野就未曾讓我不適過。無非是滿園林立的絲柏變成大廈，低矮密集的花草變成人群。", "0", "0", "0", "cv_faernaisi_4", "0", "0"},
[403004] = {403004, 10030, 5, 4, "0", "idle", "Is\u{0020}the\u{0020}Navigator\u{0020}thinking\u{0020}or\u{0020}resting?\u{0020}When\u{0020}the\u{0020}breeze\u{0020}picks\u{0020}up,\u{0020}I\u{0020}also\u{0020}like\u{0020}to\u{0020}sit\u{0020}quietly\u{0020}in\u{0020}the\u{0020}courtyard.\u{0020}Though,\u{0020}isn't\u{0020}this\u{0020}high-altitude\u{0020}wind\u{0020}a\u{0020}bit\u{0020}too\u{0020}strong\u{0020}for\u{0020}you?", "0", "領航在休息嗎，抑或是在思考？微風徐起時，我也喜歡在庭院裡靜默不語地待著。不過，這高空的風對您難道不會過於強烈了？", "0", "0", "0", "cv_faernaisi_5", "0", "0"},
[403005] = {403005, 10030, 6, 4, "0", "idle", "\"TeleRabbit\"\u{0020}always\u{0020}tests\u{0020}my\u{0020}patience.\u{0020}We\u{0020}don't\u{0020}know\u{0020}who\u{0020}she\u{0020}really\u{0020}is,\u{0020}so\u{0020}there's\u{0020}not\u{0020}much\u{0020}we\u{0020}can\u{0020}do...\u{0020}but\u{0020}she's\u{0020}trustworthy\u{0020}enough\u{0020}to\u{0020}watch\u{0020}my\u{0020}back\u{0020}during\u{0020}battle.", "0", "“蕩漾兔”，那傢伙總是喜歡挑戰我的忍耐力，由於真身不明，拿她也沒什麼辦法……還好倒是值得信賴，讓人願意在戰鬥中託付後背。", "0", "0", "0", "cv_faernaisi_6", "0", "0"},
[403006] = {403006, 10030, 7, 5, "1_》_0_0.8", "level1", "The\u{0020}Lante\u{0020}family\u{0020}runs\u{0020}construction\u{0020}and\u{0020}gardening\u{0020}in\u{0020}northern\u{0020}Sahara.\u{0020}People\u{0020}take\u{0020}pride\u{0020}in\u{0020}their\u{0020}elegant\u{0020}estates\u{0020}and\u{0020}gardens,\u{0020}but\u{0020}they\u{0020}forget\u{0020}that\u{0020}stone\u{0020}can\u{0020}also\u{0020}be\u{0020}a\u{0020}weapon,\u{0020}and\u{0020}flowers\u{0020}can\u{0020}fuel\u{0020}fires.", "0", "蘭特家族掌管了薩哈拉北部的建築與園林產業，人們對那些典雅的宅邸與花園引以為豪，以至於忘了石料也是種武器，花草也能助燃烈焰。", "0", "0", "0", "cv_faernaisi_7", "0", "0"},
[403007] = {403007, 10030, 8, 5, "1_》_0_0.8", "level1", "If\u{0020}this\u{0020}were\u{0020}my\u{0020}hometown\u{0020}and\u{0020}you\u{0020}touched\u{0020}me\u{0020}like\u{0020}that,\u{0020}you\u{0020}might've\u{0020}been\u{0020}shot.\u{0020}But\u{0020}don't\u{0020}worry,\u{0020}that's\u{0020}not\u{0020}a\u{0020}threat,\u{0020}just\u{0020}a\u{0020}note\u{0020}on\u{0020}how\u{0020}different\u{0020}things\u{0020}are\u{0020}here.", "0", "要是在我的家鄉，您這樣冒然肢體接觸，可能會讓腦袋裡被人播種一顆子彈。不過請別誤會，這不是威脅，只是在感慨環境的差異。", "0", "0", "0", "cv_faernaisi_8", "0", "0"},
[403008] = {403008, 10030, 9, 5, "1_》_100_1.5", "level2", "Would\u{0020}you,\u{0020}if\u{0020}needed,\u{0020}abandon\u{0020}your\u{0020}kindness\u{0020}and\u{0020}shoot\u{0020}a\u{0020}flower?\u{0020}Hmm...\u{0020}a\u{0020}gentle\u{0020}person's\u{0020}answer\u{0020}is\u{0020}easy\u{0020}to\u{0020}guess.\u{0020}But\u{0020}I\u{0020}would.", "0", "倘若有此必要，領航您願捨棄良善而去槍殺一朵花嗎？嗯……溫柔之人的答案果然早已註定。但，我會。", "0", "0", "0", "cv_faernaisi_9", "0", "0"},
[403009] = {403009, 10030, 10, 5, "1_》_500_2", "level3", "You\u{0020}asked\u{0020}about\u{0020}my\u{0020}scent?\u{0020}The\u{0020}citrus\u{0020}and\u{0020}bergamot\u{0020}have\u{0020}faded.\u{0020}Now,\u{0020}it's\u{0020}bitter\u{0020}orange\u{0020}leaves,\u{0020}cardamom,\u{0020}and\u{0020}jasmine.\u{0020}The\u{0020}base\u{0020}notes?\u{0020}Wait\u{0020}until\u{0020}tonight\u{0020}to\u{0020}find\u{0020}out.", "0", "我身上的香味？柑橘與香檸檬的前調方才消散，現在正是苦橙葉、小豆蔻和茉莉的中調。而至於後調……就待數小時後今夜裡的芬芳來揭曉吧。", "0", "0", "0", "cv_faernaisi_10", "0", "0"},
[403010] = {403010, 10030, 11, 5, "1_》_1000_2.5", "level4", "Regarding\u{0020}your\u{0020}joining\u{0020}the\u{0020}family,\u{0020}I've\u{0020}already\u{0020}asked\u{0020}my\u{0020}father.\u{0020}You\u{0020}want\u{0020}to\u{0020}know\u{0020}how\u{0020}exactly?\u{0020}Ha,\u{0020}making\u{0020}me\u{0020}say\u{0020}it\u{0020}out\u{0020}loud,\u{0020}huh?\u{0020}Your\u{0020}playful\u{0020}attitude\u{0020}suits\u{0020}us\u{0020}well.", "0", "關於讓您加入家族一事，我已向父親申請了。唔，您問以何種方式加入？這般明知故問，是想讓我親口說出來吧？您的壞心眼果真適合加入我們呢。", "0", "0", "0", "cv_faernaisi_11", "0", "0"},
[403011] = {403011, 10030, 12, 6, "0", "0", "One\u{0020}must\u{0020}learn\u{0020}from\u{0020}every\u{0020}situation.", "0", "何處都得學習啊。", "0", "0", "0", "cv_faernaisi_12", "0", "0"},
[403012] = {403012, 10030, 13, 7, "0", "0", "When\u{0020}the\u{0020}flowers\u{0020}bloom,\u{0020}it's\u{0020}also\u{0020}their\u{0020}moment\u{0020}of\u{0020}nearing\u{0020}withering.", "0", "花開之時，也即瀕臨凋謝之際。", "0", "0", "0", "cv_faernaisi_13", "0", "0"},
[403013] = {403013, 10030, 14, 8, "0", "0", "My\u{0020}father\u{0020}feared\u{0020}my\u{0020}talent\u{0020}and\u{0020}once\u{0020}ceased\u{0020}my\u{0020}training.\u{0020}It\u{0020}seems\u{0020}you\u{0020}won't\u{0020}do\u{0020}the\u{0020}same,\u{0020}Navigator.\u{0020}Please\u{0020}enjoy\u{0020}the\u{0020}fruits\u{0020}of\u{0020}my\u{0020}labor\u{0020}in\u{0020}the\u{0020}future.", "0", "父親畏懼我的才能，一度放棄過對我的栽培，看來領航您不會這樣。那麼，今後就請享受我所結出的碩果吧。", "0", "0", "0", "cv_faernaisi_14", "0", "0"},
[403014] = {403014, 10030, 15, 9, "0", "0", "This\u{0020}\"skill\"\u{0020}can't\u{0020}grow\u{0020}rusty.", "0", "這門“手藝”可不能生疏。", "0", "0", "0", "cv_faernaisi_15", "0", "0"},
