[403030] = {403030, 10030, 32, 24, "0", "0", "I'll\u{0020}make\u{0020}sure\u{0020}to\u{0020}respond\u{0020}to\u{0020}your\u{0020}attention.", "0", "我也會回應您的重視。", "0", "0", "0", "cv_faernaisi_32", "0", "0"},
[403031] = {403031, 10030, 33, 25, "0", "0", "Honestly,\u{0020}I'm\u{0020}a\u{0020}little\u{0020}disappointed.", "0", "不得不說，我有些失望。", "0", "0", "0", "cv_faernaisi_33", "0", "0"},
[403032] = {403032, 10030, 34, 26, "0", "0", "Today's\u{0020}a\u{0020}perfect\u{0020}day—sunny,\u{0020}bright,\u{0020}and\u{0020}warm—for\u{0020}planting,\u{0020}doing\u{0020}business,\u{0020}shooting\u{0020}practice,\u{0020}or\u{0020}tidying\u{0020}up\u{0020}the\u{0020}shadows\u{0020}of\u{0020}the\u{0020}courtyard.", "0", "今天是個好天氣，晴朗、明媚、溫暖，適合蒔花弄草，洽談生意，訓練射擊，以及清理那些庭院陰影裡的東西。", "0", "0", "0", "cv_faernaisi_34", "0", "0"},
[403033] = {403033, 10030, 35, 27, "0", "0", "Let's\u{0020}go.", "0", "出發吧。", "0", "0", "0", "cv_faernaisi_35", "0", "0"},
