[403101] = {403101, 10031, 2, 2, "0", "0", "I-I'll\u{0020}give\u{0020}it\u{0020}my\u{0020}all!", "0", "我、我會努力的！", "0", "0", "0", "cv_aofeiliya_2", "0", "0"},
[403102] = {403102, 10031, 3, 3, "0", "0", "Um...\u{0020}You're\u{0020}that\u{0020}ultra-famous\u{0020}Navigator,\u{0020}right?\u{0020}I'm\u{0020}Ophelia,\u{0020}from\u{0020}the\u{0020}Order\u{0020}of\u{0020}the\u{0020}Spring.\u{0020}I'm\u{0020}from\u{0020}Waterwheel\u{0020}Village.\u{0020}I\u{0020}love\u{0020}playing\u{0020}with\u{0020}animals,\u{0020}and\u{0020}uh...\u{0020}Well,\u{0020}it's\u{0020}nice\u{0020}to\u{0020}meet\u{0020}you!\u{0020}Let's\u{0020}do\u{0020}our\u{0020}best!", "0", "那個……您就是那位大名鼎鼎的領航嗎？我是啟泉會的奧菲莉亞，來自水車村，愛好是和小动物一起玩，然後還有……初次見面，請多多指教！", "0", "0", "0", "cv_aofeiliya_3", "0", "0"},
[403103] = {403103, 10031, 4, 4, "0", "idle", "I\u{0020}never\u{0020}imagined\u{0020}I'd\u{0020}grow\u{0020}bigger\u{0020}than\u{0020}the\u{0020}waterwheels\u{0020}I'd\u{0020}play\u{0020}by\u{0020}as\u{0020}a\u{0020}kid,\u{0020}back\u{0020}home.\u{0020}I\u{0020}certainly\u{0020}didn't\u{0020}think\u{0020}I'd\u{0020}use\u{0020}them\u{0020}as\u{0020}weapons!", "0", "小時候在村子裡的水車旁玩耍時，我從沒想過自己以後會變得比它們更大，甚至還用它作為武器。", "0", "0", "0", "cv_aofeiliya_4", "0", "0"},
[403104] = {403104, 10031, 5, 4, "0", "idle", "Navigator...\u{0020}Are\u{0020}you\u{0020}tired,\u{0020}by\u{0020}any\u{0020}chance?\u{0020}Don't\u{0020}push\u{0020}yourself\u{0020}too\u{0020}hard,\u{0020}if\u{0020}you\u{0020}want\u{0020}to\u{0020}nap\u{0020}I\u{0020}can\u{0020}give\u{0020}you\u{0020}some\u{0020}shade.", "0", "領航……是不是有些困了？想休息的話不用強撐哦，我會在旁邊幫忙遮一遮風。", "0", "0", "0", "cv_aofeiliya_5", "0", "0"},
[403105] = {403105, 10031, 6, 4, "0", "idle", "This\u{0020}dress\u{0020}is\u{0020}kind\u{0020}of\u{0020}thin,\u{0020}and\u{0020}chilly...\u{0020}But\u{0020}it's\u{0020}what\u{0020}Captain\u{0020}Mira\u{0020}says\u{0020}we\u{0020}should\u{0020}wear,\u{0020}so\u{0020}I've\u{0020}got\u{0020}to\u{0020}grit\u{0020}my\u{0020}teeth\u{0020}and\u{0020}bear\u{0020}it.", "0", "感覺這件裙子涼颼颼的……但既然是米菈隊長要求的著裝，再難為情也還是得努力克服呢。", "0", "0", "0", "cv_aofeiliya_6", "0", "0"},
[403106] = {403106, 10031, 7, 5, "1_》_0_0.8", "level1", "My\u{0020}hometown's\u{0020}a\u{0020}picturesque\u{0020}place\u{0020}known\u{0020}for\u{0020}its\u{0020}waterwheels.\u{0020}Each\u{0020}river\u{0020}flowing\u{0020}through\u{0020}the\u{0020}land\u{0020}is\u{0020}fitted\u{0020}with\u{0020}one.\u{0020}If\u{0020}you\u{0020}look\u{0020}down\u{0020}from\u{0020}the\u{0020}mountain\u{0020}slopes\u{0020}you'll\u{0020}see\u{0020}them,\u{0020}turning\u{0020}without\u{0020}rest\u{0020}like\u{0020}great\u{0020}gears,\u{0020}pushing\u{0020}day\u{0020}into\u{0020}night\u{0020}and\u{0020}night\u{0020}into\u{0020}day.", "0", "我的家鄉，是座以水車聞名的美麗村莊，流經土地的每條大河都建有一座水車，從山坡上望去就像許多齒輪在轉動，日復一日拉起晝夜的帷幕。", "0", "0", "0", "cv_aofeiliya_7", "0", "0"},
[403107] = {403107, 10031, 8, 5, "1_》_0_0.8", "level1", "Ah--!\u{0020}Oh...\u{0020}Uh,\u{0020}sorry,\u{0020}that\u{0020}was\u{0020}a\u{0020}bit\u{0020}of\u{0020}an\u{0020}overreaction.\u{0020}I'm\u{0020}from\u{0020}a\u{0020}little\u{0020}village;\u{0020}I'm\u{0020}not\u{0020}used\u{0020}to\u{0020}the\u{0020}rules\u{0020}here,\u{0020}like\u{0020}how\u{0020}a\u{0020}Navigator\u{0020}can\u{0020}reach\u{0020}out\u{0020}and\u{0020}touch\u{0020}us\u{0020}Drivers...\u{0020}Huh?\u{0020}That's\u{0020}not\u{0020}a\u{0020}rule?", "0", "嗚欸！唔……對、對不起我有些反應過度，我是從鄉下來的，還不習慣領航可以隨意摸駕駛員的規定……嗯？沒有這種規定嗎？", "0", "0", "0", "cv_aofeiliya_8", "0", "0"},
[403108] = {403108, 10031, 9, 5, "1_》_100_1.5", "level2", "You\u{0020}say\u{0020}you\u{0020}want\u{0020}to\u{0020}take\u{0020}me\u{0020}shopping?\u{0020}I,\u{0020}I\u{0020}guess...\u{0020}Yeah,\u{0020}that's\u{0020}a\u{0020}good\u{0020}way\u{0020}to\u{0020}familiarize\u{0020}myself\u{0020}with\u{0020}the\u{0020}city.\u{0020}Sure.\u{0020}(Wait,\u{0020}is\u{0020}this\u{0020}a\u{0020}date?\u{0020}These\u{0020}city\u{0020}folk\u{0020}sure\u{0020}are\u{0020}straightforward!)", "0", "您是說，打算抽空帶我去商業街逛逛？我、我想想……嗯，的確是個熟悉城市的辦法，那好吧。（話說這該不會就是約會吧！城裡人還真是開放……）", "0", "0", "0", "cv_aofeiliya_9", "0", "0"},
[403109] = {403109, 10031, 10, 5, "1_》_500_2", "level3", "I\u{0020}plan\u{0020}to\u{0020}bring\u{0020}some\u{0020}gifts\u{0020}back\u{0020}when\u{0020}I\u{0020}next\u{0020}return\u{0020}from\u{0020}my\u{0020}hometown.\u{0020}Is\u{0020}there\u{0020}anything\u{0020}you\u{0020}want,\u{0020}Navigator?\u{0020}Food,\u{0020}handicrafts,\u{0020}scenic\u{0020}postcards...?\u{0020}You\u{0020}want\u{0020}to\u{0020}join\u{0020}me?\u{0020}I...\u{0020}I\u{0020}guess\u{0020}that's\u{0020}fine\u{0020}too...!", "0", "下次回鄉，我想買點禮物帶來，領航有什麼想要的嗎？小點心、手工藝品、帶有風景的明信片。欸，您要直接陪我一起回去？也、也不是不行啦……", "0", "0", "0", "cv_aofeiliya_10", "0", "0"},
[403110] = {403110, 10031, 11, 5, "1_》_1000_2.5", "level4", "N-Navigator...\u{0020}\"You\u{0020}turn\u{0020}ceaselessly\u{0020}in\u{0020}my\u{0020}mind,\u{0020}like\u{0020}the\u{0020}ever-turning\u{0020}waterwheels,\u{0020}day\u{0020}by\u{0020}day...\"\u{0020}What\u{0020}do\u{0020}you\u{0020}think\u{0020}of\u{0020}that\u{0020}line?\u{0020}It's\u{0020}corny?!\u{0020}But,\u{0020}my\u{0020}mother\u{0020}said\u{0020}it\u{0020}was\u{0020}the\u{0020}greatest\u{0020}sweet-talking\u{0020}line\u{0020}back\u{0020}in\u{0020}her\u{0020}day...", "0", "領領領領航……您覺得，“你像永不停轉的水車，日夜灌溉著我的心田”這句話怎麼樣？欸，很土嗎？！我媽說這是她那一代人最新潮的情話了……", "0", "0", "0", "cv_aofeiliya_11", "0", "0"},
