[403330] = {403330, 10033, 32, 24, "0", "0", "Huh?\u{0020}It's\u{0020}always\u{0020}been\u{0020}me.\u{0020}Who\u{0020}else\u{0020}did\u{0020}you\u{0020}think\u{0020}it\u{0020}was?", "0", "嗯？一直都是我啊？不然你以為是誰？", "0", "0", "0", "cv_kelang_32", "0", "0"},
[403331] = {403331, 10033, 33, 25, "0", "0", "...\u{0020}So\u{0020}that's\u{0020}it.\u{0020}You\u{0020}mistook\u{0020}me\u{0020}for\u{0020}someone\u{0020}else.", "0", "……原來如此。你認錯人了。", "0", "0", "0", "cv_kelang_33", "0", "0"},
[403332] = {403332, 10033, 34, 26, "0", "0", "You're\u{0020}back\u{0020}again.\u{0020}Don't\u{0020}worry.\u{0020}I\u{0020}know\u{0020}those\u{0020}tactics\u{0020}don't\u{0020}work\u{0020}on\u{0020}you,\u{0020}so\u{0020}I\u{0020}won't\u{0020}use\u{0020}them.\u{0020}Unless...", "0", "你又來了啊。放心，我知道那些話術對你不起效果，所以不會用在你身上的。除非……", "0", "0", "0", "cv_kelang_34", "0", "0"},
[403333] = {403333, 10033, 35, 27, "0", "0", "War\u{0020}always\u{0020}brings\u{0020}despair.", "0", "戰爭總會與絕望相伴。", "0", "0", "0", "cv_kelang_35", "0", "0"},
[403334] = {403334, 10033, 36, 28, "0", "0", "Practice\u{0020}stopping\u{0020}at\u{0020}just\u{0020}the\u{0020}right\u{0020}moment.", "0", "點到為止的演習。", "0", "0", "0", "cv_kelang_36", "0", "0"},
[403335] = {403335, 10033, 37, 29, "0", "0", "I\u{0020}can\u{0020}help\u{0020}you\u{0020}have\u{0020}heart-to-heart\u{0020}talks\u{0020}with\u{0020}them.", "0", "我可以幫你與她們談談心。", "0", "0", "0", "cv_kelang_37", "0", "0"},
