[403400] = {403400, 10034, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_roki_1", "0", "0"},
[403401] = {403401, 10034, 2, 2, "0", "0", "Let\u{0020}me\u{0020}stay\u{0020}out\u{0020}in\u{0020}the\u{0020}open.\u{0020}I\u{0020}can't\u{0020}quite\u{0020}decide\u{0020}whether\u{0020}you're\u{0020}bold\u{0020}and\u{0020}meticulous\u{0020}or\u{0020}just\u{0020}an\u{0020}overconfident\u{0020}rookie.\u{0020}Either\u{0020}way,\u{0020}your\u{0020}orders\u{0020}outrank\u{0020}the\u{0020}rules,\u{0020}and\u{0020}I'm\u{0020}willing\u{0020}to\u{0020}follow.", "0", "讓我待在明處……不知道該說你是膽大心細，還是初出茅廬氣焰正盛……不過，畢竟你的命令是大於守則的，我很樂意聽從。", "0", "0", "0", "cv_roki_2", "0", "0"},
[403402] = {403402, 10034, 3, 3, "0", "0", "\"Prisoner\"\u{0020}Loki...\u{0020}If\u{0020}you\u{0020}could,\u{0020}I'd\u{0020}prefer\u{0020}you\u{0020}not\u{0020}to\u{0020}call\u{0020}me\u{0020}that.\u{0020}Just\u{0020}\"Hey\"\u{0020}or\u{0020}\"That\u{0020}guy\"\u{0020}will\u{0020}do.\u{0020}I'm\u{0020}cool\u{0020}with\u{0020}it.", "0", "“受刑人”洛基……可以的話，最好別用這個名字叫我……用“喂”或者是“那個誰”，都可以，我能明白的。", "0", "0", "0", "cv_roki_3", "0", "0"},
[403403] = {403403, 10034, 4, 4, "0", "idle1", "You're\u{0020}really\u{0020}Stephanie's\u{0020}adopted\u{0020}son?\u{0020}That\u{0020}surprises\u{0020}me...\u{0020}She\u{0020}still\u{0020}has\u{0020}some\u{0020}humanity\u{0020}left.\u{0020}I\u{0020}guess\u{0020}I\u{0020}need\u{0020}to\u{0020}reassess\u{0020}my\u{0020}opinion\u{0020}of\u{0020}her.", "0", "你真的是那位史蒂芬妮的養子？真是……嚇了我一跳，她居然還保留了這種程度人性，令人刮目相看，我得重新審視一下她在我心中的形象了。", "0", "0", "0", "cv_roki_4", "0", "0"},
[403404] = {403404, 10034, 5, 4, "0", "idle2", "Ugh,\u{0020}what\u{0020}a\u{0020}headache...\u{0020}This\u{0020}is\u{0020}the\u{0020}longest\u{0020}I've\u{0020}spent\u{0020}in\u{0020}one\u{0020}place\u{0020}with\u{0020}someone.\u{0020}Got\u{0020}any\u{0020}ideas\u{0020}on\u{0020}what\u{0020}to\u{0020}talk\u{0020}about?", "0", "頭疼……我還是第一次和人待在一個地方相處這麼久，這種時候該說什麼比較好，你有什麼主意嗎？", "0", "0", "0", "cv_roki_5", "0", "0"},
[403405] = {403405, 10034, 6, 4, "0", "idle3", "Have\u{0020}you\u{0020}met\u{0020}other\u{0020}\"Prisoners\"?\u{0020}If\u{0020}so,\u{0020}then\u{0020}I've\u{0020}got\u{0020}to\u{0020}hand\u{0020}it\u{0020}to\u{0020}you;\u{0020}I\u{0020}haven't\u{0020}seen\u{0020}other\u{0020}\"Prisoners\"\u{0020}in\u{0020}action.\u{0020}Isn't\u{0020}our\u{0020}little\u{0020}\"family\"\u{0020}great?", "0", "你見過其他的“受刑人”？那不得不誇獎你了，因為我可沒見過其他服役的“受刑人”。怎麼，你不會以為“受刑人”是一個氛圍良好的大家庭吧？", "0", "0", "0", "cv_roki_6", "0", "0"},
[403406] = {403406, 10034, 7, 5, "1_》_0_0.8", "level1", "What's\u{0020}next\u{0020}after\u{0020}leaving\u{0020}the\u{0020}\"Prisoners\"?\u{0020}Yeah,\u{0020}I've\u{0020}thought\u{0020}about\u{0020}it...\u{0020}First,\u{0020}I'll\u{0020}head\u{0020}to\u{0020}Kyushu\u{0020}and\u{0020}find\u{0020}Stephanie...\u{0020}and\u{0020}shoot\u{0020}her.\u{0020}Just\u{0020}kidding.\u{0020}I\u{0020}still\u{0020}don't\u{0020}know\u{0020}where\u{0020}she's\u{0020}hiding.", "0", "離開“受刑人”之後要做什麼？是呢，我得好好想想……總之，先去九州找史蒂芬妮，給她的腦袋來上一槍吧……開個玩笑，畢竟我還沒查到她躲在哪呢。", "0", "0", "0", "cv_roki_7", "0", "0"},
[403407] = {403407, 10034, 8, 5, "1_》_0_0.8", "level1", "Life's\u{0020}a\u{0020}mess\u{0020}right\u{0020}now...\u{0020}Can't\u{0020}sleep\u{0020}well.\u{0020}I\u{0020}envy\u{0020}how\u{0020}optimistic\u{0020}you\u{0020}can\u{0020}still\u{0020}be.\u{0020}What's\u{0020}going\u{0020}on\u{0020}in\u{0020}that\u{0020}head\u{0020}of\u{0020}yours?", "0", "最近的生活真是一團糟……睡也睡不安穩，真羨慕你還能保持樂觀，好想知道你的頭蓋骨下面裝著什麼。", "0", "0", "0", "cv_roki_8", "0", "0"},
[403408] = {403408, 10034, 9, 5, "1_》_100_1.5", "level2", "The\u{0020}Danube,\u{0020}Maya...\u{0020}You're\u{0020}always\u{0020}busy\u{0020}with\u{0020}something.\u{0020}Doesn't\u{0020}it\u{0020}wear\u{0020}you\u{0020}out?\u{0020}Don't\u{0020}you\u{0020}ever\u{0020}get\u{0020}tired?", "0", "多瑙的事情……瑪雅的事情，你好像總是在為這些事奔波，你不會覺得累嗎？不會厭倦嗎？", "0", "0", "0", "cv_roki_9", "0", "0"},
[403409] = {403409, 10034, 10, 5, "1_》_500_2", "level3", "I\u{0020}can't\u{0020}deal\u{0020}with\u{0020}someone\u{0020}as\u{0020}flashy\u{0020}as\u{0020}you...\u{0020}Just\u{0020}charging\u{0020}ahead\u{0020}on\u{0020}pure\u{0020}emotion\u{0020}is\u{0020}a\u{0020}bit\u{0020}much.", "0", "我受不了像你這麼耀眼的人……光憑藉內心湧現的情感就能不顧一切地前進，這也太奢侈了。", "0", "0", "0", "cv_roki_10", "0", "0"},
[403410] = {403410, 10034, 11, 5, "1_》_1000_2.5", "level4", "You're\u{0020}on\u{0020}an\u{0020}endless\u{0020}marathon.\u{0020}The\u{0020}moment\u{0020}you\u{0020}run\u{0020}out\u{0020}of\u{0020}energy,\u{0020}it's\u{0020}game\u{0020}over.\u{0020}I\u{0020}really\u{0020}want\u{0020}you\u{0020}to\u{0020}stop,\u{0020}but\u{0020}I\u{0020}know\u{0020}you\u{0020}won't.\u{0020}My\u{0020}name's\u{0020}Alina\u{0020}Hope,\u{0020}just\u{0020}a\u{0020}regular\u{0020}name,\u{0020}and\u{0020}now\u{0020}I'm\u{0020}the\u{0020}one\u{0020}joining\u{0020}you\u{0020}on\u{0020}this\u{0020}never-ending\u{0020}race.", "0", "你是在進行一場看不到盡頭的長跑，體力枯竭時就是你的終點。我真想讓你停下，但你肯定不願意……艾莉娜·霍普，這是我的名字，普普通通的名字，同時也是即將陪伴你進行這場長跑的同伴的名字。", "0", "0", "0", "cv_roki_11", "0", "0"},
[403411] = {403411, 10034, 12, 6, "0", "0", "Enjoy\u{0020}the\u{0020}treatment\u{0020}of\u{0020}the\u{0020}regular\u{0020}army.", "0", "享受到了正規軍的待遇。", "0", "0", "0", "cv_roki_12", "0", "0"},
[403412] = {403412, 10034, 13, 7, "0", "0", "Thank\u{0020}you\u{0020}for\u{0020}the\u{0020}promotion.", "0", "感謝提拔。", "0", "0", "0", "cv_roki_13", "0", "0"},
[403413] = {403413, 10034, 14, 8, "0", "0", "Suddenly,\u{0020}I\u{0020}think\u{0020}maybe\u{0020}being\u{0020}a\u{0020}driver\u{0020}isn't\u{0020}so\u{0020}bad.", "0", "突然覺得……當駕駛員說不定也挺好的。", "0", "0", "0", "cv_roki_14", "0", "0"},
[403414] = {403414, 10034, 15, 9, "0", "0", "Learning\u{0020}more\u{0020}combat\u{0020}skills\u{0020}isn't\u{0020}a\u{0020}bad\u{0020}thing\u{0020}either.", "0", "多學點戰鬥技能也不是壞事。", "0", "0", "0", "cv_roki_15", "0", "0"},
[403415] = {403415, 10034, 16, 10, "0", "0", "I\u{0020}never\u{0020}imagined\u{0020}I\u{0020}would\u{0020}find\u{0020}myself\u{0020}on\u{0020}the\u{0020}front\u{0020}lines.", "0", "我也沒想過自己會出現在正面戰場。", "0", "0", "0", "cv_roki_16", "0", "0"},
[403416] = {403416, 10034, 17, 11, "0", "0", "A\u{0020}perfect\u{0020}victory?\u{0020}Unbelievable.", "0", "完美勝利？難以置信。", "0", "0", "0", "cv_roki_17", "0", "0"},
[403417] = {403417, 10034, 18, 12, "0", "0", "Did\u{0020}we\u{0020}actually\u{0020}win?\u{0020}Incredible.", "0", "居然贏了嗎？不可思議。", "0", "0", "0", "cv_roki_18", "0", "0"},
[403418] = {403418, 10034, 19, 13, "0", "0", "We\u{0020}could\u{0020}win\u{0020}like\u{0020}this?\u{0020}That's\u{0020}worth\u{0020}admiration.", "0", "這也能贏？值得佩服。", "0", "0", "0", "cv_roki_19", "0", "0"},
[403419] = {403419, 10034, 20, 14, "0", "0", "Lost?\u{0020}That\u{0020}shouldn't\u{0020}be\u{0020}my\u{0020}responsibility,\u{0020}right?", "0", "輸了？應該不是我的責任吧。", "0", "0", "0", "cv_roki_20", "0", "0"},
[403420] = {403420, 10034, 21, 15, "0", "0", "Nice\u{0020}touch.", "0", "手感不錯。", "0", "0", "0", "cv_roki_21", "0", "0"},
[403421] = {403421, 10034, 23, 16, "0", "0", "I'll\u{0020}choose\u{0020}you.", "0", "就選你了。", "0", "0", "0", "cv_roki_23", "0", "0"},
[403422] = {403422, 10034, 26, 19, "0", "0", "Well\u{0020}then,\u{0020}I'll\u{0020}retreat\u{0020}first.", "0", "那麼，我就先撤退了。", "0", "0", "0", "cv_roki_26", "0", "0"},
[403423] = {403423, 10034, 24, 17, "0", "0", "Die\u{0020}quickly.", "0", "快嚥氣吧。", "0", "0", "0", "cv_roki_24", "0", "0"},
[403424] = {403424, 10034, 25, 18, "0", "0", "I'll\u{0020}cut\u{0020}off\u{0020}anything\u{0020}you\u{0020}don't\u{0020}need.", "0", "我來斬去你的多餘之物吧。", "0", "0", "0", "cv_roki_25", "0", "0"},
[403425] = {403425, 10034, 27, 20, "0", "0", "And\u{0020}if\u{0020}that\u{0020}sparks\u{0020}any\u{0020}wicked\u{0020}thoughts\u{0020}in\u{0020}your\u{0020}head,\u{0020}I'll\u{0020}kill\u{0020}you—right\u{0020}then\u{0020}and\u{0020}there.", "0", "如果你因此產生了什麼邪念，我就會殺了你，立即，立刻。", "0", "0", "0", "cv_roki_27", "0", "0"},
[403426] = {403426, 10034, 28, 21, "0", "0", "I've\u{0020}only\u{0020}seen\u{0020}this\u{0020}kind\u{0020}of\u{0020}situation\u{0020}in\u{0020}comics\u{0020}and\u{0020}shows\u{0020}before...\u{0020}What?\u{0020}Did\u{0020}you\u{0020}think\u{0020}I\u{0020}wouldn't\u{0020}be\u{0020}into\u{0020}it?", "0", "以前只在動畫和漫畫裡遇過這種事……怎麼，你覺得我對那種東西不感興趣？", "0", "0", "0", "cv_roki_28", "0", "0"},
[403427] = {403427, 10034, 29, 21, "0", "0", "Watching\u{0020}you\u{0020}wander\u{0020}around\u{0020}beside\u{0020}me,\u{0020}I\u{0020}can't\u{0020}help\u{0020}but\u{0020}imagine\u{0020}stepping\u{0020}on\u{0020}you\u{0020}by\u{0020}accident...\u{0020}Just\u{0020}a\u{0020}passing\u{0020}thought,\u{0020}don't\u{0020}worry.", "0", "看著你在旁邊晃悠，就會想到不小心踩到你的畫面……放心，只是想想而已。", "0", "0", "0", "cv_roki_29", "0", "0"},
[403428] = {403428, 10034, 30, 22, "0", "0", "Huh?", "0", "嗯？", "0", "0", "0", "cv_roki_30", "0", "0"},
[403429] = {403429, 10034, 31, 23, "0", "0", "Are\u{0020}you\u{0020}about\u{0020}to\u{0020}call\u{0020}out\u{0020}that\u{0020}name?", "0", "你要叫那個名字了嗎……", "0", "0", "0", "cv_roki_31", "0", "0"},
[403430] = {403430, 10034, 32, 24, "0", "0", "Please,\u{0020}don't\u{0020}call\u{0020}me\u{0020}Loki.\u{0020}I'm\u{0020}asking\u{0020}you\u{0020}nicely.", "0", "別叫我洛基——就當是我在求你吧。", "0", "0", "0", "cv_roki_32", "0", "0"},
[403431] = {403431, 10034, 33, 25, "0", "0", "It's\u{0020}still\u{0020}better\u{0020}than\u{0020}hearing\u{0020}you\u{0020}use\u{0020}that\u{0020}code\u{0020}name,\u{0020}though.", "0", "總好過你用那個代號叫我。", "0", "0", "0", "cv_roki_33", "0", "0"},
[403432] = {403432, 10034, 34, 26, "0", "0", "I\u{0020}actually\u{0020}made\u{0020}a\u{0020}bet\u{0020}that\u{0020}you\u{0020}wouldn't\u{0020}show\u{0020}up\u{0020}again.\u{0020}Guess\u{0020}I\u{0020}lost.", "0", "嗯……我剛剛正在和人打賭你不會回來了。", "0", "0", "0", "cv_roki_34", "0", "0"},
[403433] = {403433, 10034, 35, 27, "0", "0", "I'm\u{0020}still\u{0020}not\u{0020}too\u{0020}keen\u{0020}on\u{0020}these\u{0020}kinds\u{0020}of\u{0020}assignments...\u{0020}but\u{0020}I'll\u{0020}get\u{0020}used\u{0020}to\u{0020}it.", "0", "我還不是很喜歡這種類型的出勤任務……算了，總會習慣的。", "0", "0", "0", "cv_roki_35", "0", "0"},
[403434] = {403434, 10034, 36, 28, "0", "0", "It's\u{0020}something\u{0020}I\u{0020}excel\u{0020}at,\u{0020}after\u{0020}all.", "0", "也算是我擅長的事情吧。", "0", "0", "0", "cv_roki_36", "0", "0"},
[403435] = {403435, 10034, 37, 29, "0", "0", "Now\u{0020}we're\u{0020}the\u{0020}real\u{0020}headquarters.", "0", "這下我們才是真正的總部了。", "0", "0", "0", "cv_roki_37", "0", "0"},
[403436] = {403436, 10034, 38, 30, "0", "0", "Perfect,\u{0020}gather\u{0020}everyone\u{0020}and\u{0020}let's\u{0020}strike\u{0020}back.", "0", "很好，召集人反攻總部吧。", "0", "0", "0", "cv_roki_38", "0", "0"},
[403437] = {403437, 10034, 39, 31, "0", "0", "I'd\u{0020}love\u{0020}to\u{0020}get\u{0020}my\u{0020}hands\u{0020}on\u{0020}some\u{0020}of\u{0020}that\u{0020}powerful-looking\u{0020}gear.", "0", "我也挺想要那種看著很厲害的裝備。", "0", "0", "0", "cv_roki_39", "0", "0"},
[403438] = {403438, 10034, 40, 32, "0", "0", "Let's\u{0020}take\u{0020}a\u{0020}walk.", "0", "一起逛逛吧。", "0", "0", "0", "cv_roki_40", "0", "0"},
[403439] = {403439, 10034, 41, 33, "0", "0", "Looks\u{0020}like\u{0020}you\u{0020}haven't\u{0020}dodged\u{0020}the\u{0020}orders\u{0020}either.", "0", "看來你也沒少被使喚。", "0", "0", "0", "cv_roki_41", "0", "0"},
[403440] = {403440, 10034, 42, 34, "0", "0", "Did\u{0020}you\u{0020}forget\u{0020}something?", "0", "忘帶東西了嗎？", "0", "0", "0", "cv_roki_42", "0", "0"},
[403441] = {403441, 10034, 43, 35, "0", "0", "Oh,\u{0020}remembered\u{0020}it?\u{0020}I\u{0020}was\u{0020}just\u{0020}about\u{0020}to\u{0020}erase\u{0020}it.", "0", "想起來了？我正打算刪了呢。", "0", "0", "0", "cv_roki_43", "0", "0"},
[403442] = {403442, 10034, 44, 36, "0", "0", "Leaving\u{0020}a\u{0020}paper\u{0020}trail\u{0020}isn't\u{0020}always\u{0020}smart.", "0", "留下文字記錄可不是什麼好事。", "0", "0", "0", "cv_roki_44", "0", "0"},
[403443] = {403443, 10034, 45, 37, "0", "0", "What's\u{0020}the\u{0020}matter?", "0", "怎麼了？", "0", "0", "0", "cv_roki_45", "0", "0"},
[403500] = {403500, 10035, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "苍雾残响", "0", "0", "0", "cv_heli_1", "0", "0"},
[403501] = {403501, 10035, 2, 2, "0", "0", "Yeah,\u{0020}I'm\u{0020}pretty\u{0020}good\u{0020}at\u{0020}this\u{0020}stuff.\u{0020}I've\u{0020}been\u{0020}doing\u{0020}odd\u{0020}jobs\u{0020}for\u{0020}six\u{0020}years...\u{0020}Heh.", "0", "OK，這種事我還是挺擅長的，畢竟當了六年打雜的……呵呵……", "0", "0", "0", "cv_heli_2", "0", "0"},
[403502] = {403502, 10035, 3, 3, "0", "0", "You're\u{0020}the\u{0020}Navigator,\u{0020}right?\u{0020}And\u{0020}that\u{0020}makes\u{0020}me\u{0020}the\u{0020}Driver,\u{0020}right?\u{0020}Right?\u{0020}Hey,\u{0020}I'm\u{0020}Hurley\u{0020}Garcia,\u{0020}official\u{0020}Driver!", "0", "你是領航……是吧？那我就是駕駛員了？對吧？沒錯吧？咳咳，我是赫莉·加西亞，是一名正式駕駛員！", "0", "0", "0", "cv_heli_3", "0", "0"},
[403503] = {403503, 10035, 4, 4, "0", "idle", "I\u{0020}used\u{0020}to\u{0020}admire\u{0020}AEGIS,\u{0020}but\u{0020}after\u{0020}getting\u{0020}here,\u{0020}I\u{0020}realized\u{0020}it's\u{0020}full\u{0020}of\u{0020}weirdos.\u{0020}Only\u{0020}the\u{0020}strongest\u{0020}survive.\u{0020}Chesterton's\u{0020}the\u{0020}same...\u{0020}Maybe\u{0020}it's\u{0020}like\u{0020}this\u{0020}everywhere.", "0", "我以前對艾吉斯還挺憧憬的，結果來了之後才發現到處都是些怪人，這就是適者生存吧，普通人早就待不下去了，切斯頓也是這樣，可能哪裡都一樣吧。", "0", "0", "0", "cv_heli_4", "0", "0"},
[403504] = {403504, 10035, 5, 4, "0", "idle", "Drivers\u{0020}get\u{0020}way\u{0020}more\u{0020}vacation\u{0020}than\u{0020}I\u{0020}thought.\u{0020}Now\u{0020}I\u{0020}can\u{0020}go\u{0020}back\u{0020}and\u{0020}mock\u{0020}my\u{0020}old\u{0020}boss\u{0020}who\u{0020}looked\u{0020}down\u{0020}on\u{0020}me.", "0", "駕駛員的假期比想象中要多不少，這樣一來我就可以經常回去嘲笑以前的店老板了，讓她瞧不起我。", "0", "0", "0", "cv_heli_5", "0", "0"},
[403505] = {403505, 10035, 6, 4, "0", "idle", "...Speaking\u{0020}of\u{0020}which,\u{0020}for\u{0020}various\u{0020}reasons,\u{0020}I\u{0020}barely\u{0020}talk\u{0020}to\u{0020}my\u{0020}teammates.\u{0020}Sometimes,\u{0020}I\u{0020}can't\u{0020}even\u{0020}match\u{0020}faces\u{0020}with\u{0020}names.\u{0020}I\u{0020}guess\u{0020}I'm\u{0020}still\u{0020}immature.", "0", "……說起來，因為各種各樣的原因，我幾乎沒有和其他隊友好好聊過，她們的臉和名字我都不一定對得上，真是一點也不成熟啊。", "0", "0", "0", "cv_heli_6", "0", "0"},
[403506] = {403506, 10035, 7, 5, "1_》_0_0.8", "level1", "Everyone\u{0020}chases\u{0020}happiness\u{0020}differently.\u{0020}Some\u{0020}people\u{0020}aim\u{0020}for\u{0020}\"10,\"\u{0020}others\u{0020}for\u{0020}\"100.\"\u{0020}Me...\u{0020}I'm\u{0020}just\u{0020}trying\u{0020}to\u{0020}stay\u{0020}positive.", "0", "不同人追求的幸福是有不同重量的。有的人想要的是“10”，有的人則是“100”。我的話……總之，先以變成正數為目標吧。", "0", "0", "0", "cv_heli_7", "0", "0"},
[403507] = {403507, 10035, 8, 5, "1_》_0_0.8", "level1", "As\u{0020}long\u{0020}as\u{0020}there's\u{0020}no\u{0020}fighting,\u{0020}being\u{0020}a\u{0020}Driver\u{0020}is\u{0020}pretty\u{0020}easy.", "0", "只要不戰鬥的話，駕駛員的工作還蠻輕鬆的。", "0", "0", "0", "cv_heli_8", "0", "0"},
[403508] = {403508, 10035, 9, 5, "1_》_100_1.5", "level2", "I\u{0020}could\u{0020}go\u{0020}for\u{0020}some\u{0020}ribs...\u{0020}maybe\u{0020}a\u{0020}steak...\u{0020}Those\u{0020}ads\u{0020}make\u{0020}the\u{0020}food\u{0020}look\u{0020}amazing.\u{0020}Wanna\u{0020}treat\u{0020}me?", "0", "想吃牛肋骨……想吃牛排……廣告上把它們拍得太美味了啦……你能請我吃嗎？", "0", "0", "0", "cv_heli_9", "0", "0"},
[403509] = {403509, 10035, 10, 5, "1_》_500_2", "level3", "You're\u{0020}swamped\u{0020}with\u{0020}work...\u{0020}Let's\u{0020}sneak\u{0020}out\u{0020}sometime,\u{0020}blow\u{0020}off\u{0020}some\u{0020}steam?\u{0020}I\u{0020}know\u{0020}a\u{0020}place\u{0020}that's\u{0020}perfect\u{0020}for\u{0020}clearing\u{0020}your\u{0020}head.", "0", "你的時間真的是被工作擠得滿滿……喂，找個時間，我們偷偷溜出去玩吧？我知道一個很適合發洩壓力，淨化心靈的地方。", "0", "0", "0", "cv_heli_10", "0", "0"},
[403510] = {403510, 10035, 11, 5, "1_》_1000_2.5", "level4", "Ugh,\u{0020}I'm\u{0020}annoyed.\u{0020}I've\u{0020}never\u{0020}felt\u{0020}this\u{0020}way\u{0020}before.\u{0020}Is\u{0020}it\u{0020}strange\u{0020}that\u{0020}I\u{0020}might\u{0020}have\u{0020}unrealistic\u{0020}thoughts?\u{0020}Hey,\u{0020}Navigator,\u{0020}promise\u{0020}me\u{0020}you\u{0020}won't\u{0020}deceive\u{0020}me\u{0020}or\u{0020}disappear\u{0020}suddenly,\u{0020}okay?\u{0020}No\u{0020}problem,\u{0020}right?", "0", "嗚啊啊……真是心煩，這種心情還是第一次，太奇怪了，我居然也會有這種不切實際的想法嗎？喂，領航，答應我，絕對不要騙我，也絕對不要突然消失，可以吧？沒問題的吧？", "0", "0", "0", "cv_heli_11", "0", "0"},
[403511] = {403511, 10035, 12, 6, "0", "0", "How\u{0020}do\u{0020}I\u{0020}put\u{0020}this...\u{0020}Thanks\u{0020}for\u{0020}the\u{0020}training.", "0", "該怎麼說……感謝培養？", "0", "0", "0", "cv_heli_12", "0", "0"},
[403512] = {403512, 10035, 13, 7, "0", "0", "I've\u{0020}got\u{0020}this\u{0020}weird\u{0020}feeling...", "0", "怪怪的感覺……", "0", "0", "0", "cv_heli_13", "0", "0"},
[403513] = {403513, 10035, 14, 8, "0", "0", "I'm\u{0020}not\u{0020}used\u{0020}to\u{0020}people\u{0020}like\u{0020}you\u{0020}being\u{0020}so\u{0020}nice...\u{0020}At\u{0020}first,\u{0020}I\u{0020}thought\u{0020}you'd\u{0020}leave\u{0020}me\u{0020}out...\u{0020}but\u{0020}thanks.", "0", "我不太習慣你這類好人……一開始還以為會被冷落呢……謝謝啦。", "0", "0", "0", "cv_heli_14", "0", "0"},
[403514] = {403514, 10035, 15, 9, "0", "0", "Thanks,\u{0020}seriously.", "0", "謝、謝謝。", "0", "0", "0", "cv_heli_15", "0", "0"},
[403515] = {403515, 10035, 16, 10, "0", "0", "Finish\u{0020}early\u{0020}and\u{0020}head\u{0020}home\u{0020}early!", "0", "早點結束，早點回家！", "0", "0", "0", "cv_heli_16", "0", "0"},
[403516] = {403516, 10035, 17, 11, "0", "0", "Whoa,\u{0020}I\u{0020}didn't\u{0020}realize\u{0020}I\u{0020}was\u{0020}this\u{0020}strong.", "0", "嚇了我一跳，我原來這麼厲害嗎？", "0", "0", "0", "cv_heli_17", "0", "0"},
[403517] = {403517, 10035, 18, 12, "0", "0", "Be\u{0020}content.\u{0020}We've\u{0020}done\u{0020}more\u{0020}than\u{0020}enough.", "0", "要知足，做到這個程度已經可以了啦。", "0", "0", "0", "cv_heli_18", "0", "0"},
[403518] = {403518, 10035, 19, 13, "0", "0", "It's\u{0020}better\u{0020}than\u{0020}losing,\u{0020}right?", "0", "總比輸掉要好吧？", "0", "0", "0", "cv_heli_19", "0", "0"},
[403519] = {403519, 10035, 20, 14, "0", "0", "I\u{0020}didn't\u{0020}think\u{0020}I'd\u{0020}lose...", "0", "我還真沒想過會輸……", "0", "0", "0", "cv_heli_20", "0", "0"},
[403520] = {403520, 10035, 21, 15, "0", "0", "Next.", "0", "Next。", "0", "0", "0", "cv_heli_21", "0", "0"},
[403521] = {403521, 10035, 23, 16, "0", "0", "Time's\u{0020}up.", "0", "要上了。", "0", "0", "0", "cv_heli_23", "0", "0"},
[403522] = {403522, 10035, 24, 17, "0", "0", "Tsk.", "0", "切。", "0", "0", "0", "cv_heli_24", "0", "0"},
[403523] = {403523, 10035, 26, 19, "0", "0", "No\u{0020}way...", "0", "不是吧……", "0", "0", "0", "cv_heli_25", "0", "0"},
[403524] = {403524, 10035, 27, 20, "0", "0", "My\u{0020}gut\u{0020}says\u{0020}this\u{0020}doesn't\u{0020}make\u{0020}sense.", "0", "我的常識正在告訴我這不合理。", "0", "0", "0", "cv_heli_26", "0", "0"},
[403525] = {403525, 10035, 28, 21, "0", "0", "I'm\u{0020}trying\u{0020}not\u{0020}to\u{0020}lose\u{0020}my\u{0020}mind\u{0020}by\u{0020}ignoring\u{0020}you.", "0", "我正試著通過無視你來保證我的神經不崩壞。", "0", "0", "0", "cv_heli_27", "0", "0"},
[403526] = {403526, 10035, 29, 21, "0", "0", "If\u{0020}you're\u{0020}waiting\u{0020}for\u{0020}me\u{0020}to\u{0020}get\u{0020}embarrassed,\u{0020}give\u{0020}up.\u{0020}I'm\u{0020}not\u{0020}going\u{0020}to\u{0020}make\u{0020}a\u{0020}fool\u{0020}of\u{0020}myself!", "0", "要是你想看到我害羞丟臉的樣子，那就死心吧，我是絕對不會出醜的！", "0", "0", "0", "cv_heli_28", "0", "0"},
[403527] = {403527, 10035, 30, 22, "0", "0", "What's\u{0020}wrong?!", "0", "怎、怎麼了？！", "0", "0", "0", "cv_heli_29", "0", "0"},
[403528] = {403528, 10035, 31, 23, "0", "0", "Interesting...\u{0020}Guess\u{0020}who\u{0020}I\u{0020}am?", "0", "有點意思……猜猜我是誰？", "0", "0", "0", "cv_heli_30", "0", "0"},
[403529] = {403529, 10035, 32, 24, "0", "0", "You\u{0020}guessed\u{0020}right!\u{0020}So\u{0020}far,\u{0020}so\u{0020}good,\u{0020}huh?", "0", "答對啦！姑且是件好事吧？", "0", "0", "0", "cv_heli_31", "0", "0"},
[403530] = {403530, 10035, 33, 25, "0", "0", "You\u{0020}guessed\u{0020}wrong.\u{0020}Seems\u{0020}like\u{0020}you\u{0020}don't\u{0020}know\u{0020}me\u{0020}that\u{0020}well.", "0", "答錯了，看來你真的和我不熟呢。", "0", "0", "0", "cv_heli_32", "0", "0"},
[403531] = {403531, 10035, 34, 26, "0", "0", "Welcome\u{0020}back...\u{0020}Oh,\u{0020}by\u{0020}the\u{0020}way,\u{0020}a\u{0020}girl\u{0020}was\u{0020}looking\u{0020}for\u{0020}you...\u{0020}You're\u{0020}really\u{0020}popular,\u{0020}huh?", "0", "歡迎回來……對了，有女孩子找你……你還真是有夠受歡迎的。", "0", "0", "0", "cv_heli_33", "0", "0"},
[403532] = {403532, 10035, 35, 27, "0", "0", "So,\u{0020}where\u{0020}are\u{0020}we\u{0020}going\u{0020}to\u{0020}stir\u{0020}things\u{0020}up\u{0020}today?", "0", "那麼，今天又要去哪裡鬧騰呢？", "0", "0", "0", "cv_heli_34", "0", "0"},
[403533] = {403533, 10035, 36, 28, "0", "0", "I\u{0020}don't\u{0020}want\u{0020}to\u{0020}fight\u{0020}meaningless\u{0020}battles.", "0", "不想進行無意義的戰鬥呀。", "0", "0", "0", "cv_heli_35", "0", "0"},
[403534] = {403534, 10035, 37, 29, "0", "0", "If\u{0020}everyone\u{0020}had\u{0020}been\u{0020}there\u{0020}earlier,\u{0020}maybe\u{0020}things\u{0020}would've\u{0020}turned\u{0020}out\u{0020}differently.", "0", "要是當時大家都在，可能結果就不一樣了吧。", "0", "0", "0", "cv_heli_36", "0", "0"},
[403535] = {403535, 10035, 38, 30, "0", "0", "Looks\u{0020}like\u{0020}someone's\u{0020}about\u{0020}to\u{0020}be\u{0020}cannon\u{0020}fodder\u{0020}again.", "0", "又要有人被騙來當炮灰咯。", "0", "0", "0", "cv_heli_37", "0", "0"},
[403536] = {403536, 10035, 39, 31, "0", "0", "I'd\u{0020}love\u{0020}it\u{0020}if\u{0020}you\u{0020}could\u{0020}give\u{0020}me\u{0020}that\u{0020}money.", "0", "真希望你能把這些錢交給我。", "0", "0", "0", "cv_heli_38", "0", "0"},
[403537] = {403537, 10035, 40, 32, "0", "0", "Buy\u{0020}whatever\u{0020}you\u{0020}want.\u{0020}It's\u{0020}not\u{0020}like\u{0020}I\u{0020}saved\u{0020}it.", "0", "想買什麼就買什麼吧，反正花的不是我存的錢。", "0", "0", "0", "cv_heli_39", "0", "0"},
[403538] = {403538, 10035, 41, 33, "0", "0", "I\u{0020}thought\u{0020}you\u{0020}were\u{0020}a\u{0020}newbie\u{0020}like\u{0020}me...", "0", "我還以為你和我一樣是新人……", "0", "0", "0", "cv_heli_40", "0", "0"},
