[403601] = {403601, 10036, 2, 2, "0", "0", "How\u{0020}dare\u{0020}you\u{0020}make\u{0020}me\u{0020}wear\u{0020}something\u{0020}like\u{0020}this\u{0020}just\u{0020}to\u{0020}keep\u{0020}you\u{0020}company?", "0", "竟，竟然讓本小姐穿著這樣的衣服陪你……", "0", "0", "0", "cv_chalisha_vd_2", "0", "0"},
[403602] = {403602, 10036, 3, 3, "0", "0", "It's\u{0020}just\u{0020}chocolate...\u{0020}I\u{0020}grabbed\u{0020}it\u{0020}randomly.\u{0020}Don't\u{0020}go\u{0020}acting\u{0020}like\u{0020}it's\u{0020}anything\u{0020}special.", "0", "這是巧克力……我只是順手拿來的，別把它當成什麼特別的東西。", "0", "0", "0", "cv_chalisha_vd_3", "0", "0"},
[403603] = {403603, 10036, 4, 4, "0", "idle", "Valentine's\u{0020}Day?\u{0020}So\u{0020}boring.\u{0020}But\u{0020}since\u{0020}you\u{0020}invited\u{0020}me,\u{0020}fine,\u{0020}I'll\u{0020}spend\u{0020}it\u{0020}with\u{0020}you...", "0", "情人節？真是無聊，不過既然是你邀請了，那，那本小姐也不是不能和你一起過……", "0", "0", "0", "cv_chalisha_vd_4", "0", "0"},
[403604] = {403604, 10036, 5, 4, "0", "idle", "The\u{0020}chocolate\u{0020}is\u{0020}delicious?\u{0020}Of\u{0020}course!\u{0020}I\u{0020}worked\u{0020}so\u{0020}hard\u{0020}on...\u{0020}Uh...\u{0020}Nothing...\u{0020}I\u{0020}didn't\u{0020}say\u{0020}anything...\u{0020}You\u{0020}heard\u{0020}that?", "0", "巧克力很好吃？那當然啦！本小姐可是努力了好久好久……啊……沒什麼……我什麼都沒說……你聽到了？", "0", "0", "0", "cv_chalisha_vd_5", "0", "0"},
[403605] = {403605, 10036, 6, 4, "0", "idle", "This\u{0020}is\u{0020}just\u{0020}a\u{0020}small\u{0020}gift.\u{0020}Don't\u{0020}think\u{0020}too\u{0020}much\u{0020}of\u{0020}it...\u{0020}Delicious?\u{0020}Great!\u{0020}Great!\u{0020}My\u{0020}skills\u{0020}are\u{0020}obviously\u{0020}the\u{0020}best\u{0020}in\u{0020}the\u{0020}world...", "0", "這不過是一點點小禮物，不必太在意……好吃？太好了！太好了！——本小姐的手藝果然是是天下第一……", "0", "0", "0", "cv_chalisha_vd_6", "0", "0"},
[403606] = {403606, 10036, 7, 5, "1_》_0_0.8", "level1", "I'll\u{0020}hold\u{0020}onto\u{0020}the\u{0020}meaning\u{0020}of\u{0020}this\u{0020}day\u{0020}tightly.\u{0020}Just\u{0020}you\u{0020}wait!", "0", "這個日子的意義，我一定會牢牢地抓住的，給我等著吧！", "0", "0", "0", "cv_chalisha_vd_7", "0", "0"},
[403607] = {403607, 10036, 8, 5, "1_》_0_0.8", "level1", "I\u{0020}will\u{0020}only\u{0020}wear\u{0020}this\u{0020}dress\u{0020}once.\u{0020}You\u{0020}better\u{0020}treasure\u{0020}it...\u{0020}If\u{0020}it\u{0020}doesn't\u{0020}go\u{0020}well\u{0020}this\u{0020}time...\u{0020}I'll...\u{0020}I'll...", "0", "這件衣服本小姐只會穿這一次哦，你可要好好珍惜……如果這次不能成功的話……我就……我就……嗚嗚嗚……", "0", "0", "0", "cv_chalisha_vd_8", "0", "0"},
[403608] = {403608, 10036, 9, 5, "1_》_100_1.5", "level2", "Actually,\u{0020}I\u{0020}picked\u{0020}this\u{0020}gift\u{0020}carefully.\u{0020}I\u{0020}hope\u{0020}you\u{0020}like\u{0020}it...\u{0020}After\u{0020}all,\u{0020}Navigator...\u{0020}Navigator,\u{0020}you're\u{0020}the\u{0020}first\u{0020}real\u{0020}friend\u{0020}I've\u{0020}had\u{0020}in\u{0020}my\u{0020}life...", "0", "嗯，其實這點小禮物是我用心挑選的，希望你會喜歡……畢竟領航……領航是本小姐生命中……生命中……第一個遇到的朋友。", "0", "0", "0", "cv_chalisha_vd_9", "0", "0"},
[403609] = {403609, 10036, 10, 5, "1_》_500_2", "level3", "It's\u{0020}my\u{0020}first\u{0020}time\u{0020}being\u{0020}treated\u{0020}this\u{0020}way,\u{0020}my\u{0020}first\u{0020}time\u{0020}choosing\u{0020}clothes\u{0020}with\u{0020}you,\u{0020}my\u{0020}first\u{0020}time\u{0020}arguing\u{0020}with\u{0020}you...\u{0020}Thinking\u{0020}back,\u{0020}those\u{0020}firsts\u{0020}are\u{0020}actually\u{0020}kind\u{0020}of\u{0020}comforting...\u{0020}Navigator...", "0", "第一次被人這麼對待，第一次和你一起挑選衣服，第一次和你吵架……現在回想起來……這些第一次竟然這麼讓人安心……領航……", "0", "0", "0", "cv_chalisha_vd_10", "0", "0"},
[403610] = {403610, 10036, 11, 5, "1_》_1000_2.5", "level4", "I\u{0020}have\u{0020}no\u{0020}regrets.\u{0020}So,\u{0020}keep\u{0020}your\u{0020}feelings\u{0020}for\u{0020}me\u{0020}in\u{0020}your\u{0020}heart\u{0020}forever,\u{0020}you\u{0020}dummy...", "0", "本小姐不會覺得後悔的，所以——要把對我的感情一直記在心裡啊，呆子……", "0", "0", "0", "cv_chalisha_vd_11", "0", "0"},
