[404303] = {404303, 10043, 4, 4, "0", "idle", "I've\u{0020}been\u{0020}in\u{0020}this\u{0020}world\u{0020}so\u{0020}long\u{0020}and\u{0020}still\u{0020}haven't\u{0020}met\u{0020}my\u{0020}mother...\u{0020}Honestly...\u{0020}I\u{0020}didn't\u{0020}see\u{0020}her\u{0020}in\u{0020}my\u{0020}past\u{0020}life\u{0020}either...", "0", "0", "0", "0", "0", "cv_hikari_04", "0", "0"},
[404304] = {404304, 10043, 5, 4, "0", "idle2", "You'll\u{0020}take\u{0020}me\u{0020}to\u{0020}meet\u{0020}Mom?\u{0020}Hmm...\u{0020}I\u{0020}hope\u{0020}she's\u{0020}as\u{0020}nice\u{0020}as\u{0020}you...\u{0020}But\u{0020}she'd\u{0020}better\u{0020}not\u{0020}take\u{0020}up\u{0020}our\u{0020}time.\u{0020}If\u{0020}so,\u{0020}I\u{0020}won't\u{0020}be\u{0020}nice,\u{0020}even\u{0020}if\u{0020}she's\u{0020}Mom.", "0", "0", "0", "0", "0", "cv_hikari_05", "0", "0"},
