[410002] = {410002, 11000, 3, 3, "0", "0", "Seriously,\u{0020}how\u{0020}did\u{0020}I\u{0020}end\u{0020}up\u{0020}stuck\u{0020}in\u{0020}this\u{0020}marginal\u{0020}unit?", "もうっ！何でこんなノンコア部隊に配属されてるのよ。", "嘖，真是的。人家為什麼會被編進這種邊緣部隊啊。", "0", "啧，真是的。人家为什么会被编进这种边缘部队啊。", "0", "cv_chilyarisa_1", "0", "0"},
[410003] = {410003, 11000, 4, 4, "0", "idle", "Hey,\u{0020}you\u{0020}over\u{0020}there!\u{0020}If\u{0020}you\u{0020}need\u{0020}help,\u{0020}just\u{0020}let\u{0020}me\u{0020}know.\u{0020}I\u{0020}won't\u{0020}let\u{0020}you\u{0020}down\u{0020}today.", "ねえ、ちょっと。何かあったらいつでも言いなさい？今日も絶対、あんたの期待を裏切らないから。", "喂，那邊的傢伙。如果有什麼要幫忙的就隨時聯繫人家吧，今天也絕對不會讓你失望的。", "0", "喂，那边的家伙。如果有什么要帮忙的就随时联系人家吧，今天也绝对不会让你失望的。", "0", "cv_chilyarisa_3", "0", "0"},
[410004] = {410004, 11000, 5, 4, "0", "idle", "A\u{0020}runaway\u{0020}rich\u{0020}girl?\u{0020}Where\u{0020}did\u{0020}you\u{0020}even\u{0020}hear\u{0020}that\u{0020}rumor?\u{0020}If\u{0020}you\u{0020}bring\u{0020}it\u{0020}up\u{0020}again,\u{0020}I'm\u{0020}going\u{0020}to\u{0020}beat\u{0020}you\u{0020}up.", "家出したお嬢様？そんな根も葉もないこと、誰から聞いたの？てか、二度と口にしないでよね！今度は絶対許さないから。", "離家出走的千金大小姐？你到底是從哪聽到的謠言啊，下次如果再敢提起這事，人家絕對不會放過你。", "0", "离家出走的千金大小姐？你到底是从哪听到的谣言啊，下次如果再敢提起这事，人家绝对不会放过你。", "0", "cv_chilyarisa_4", "0", "0"},
[410005] = {410005, 11000, 6, 4, "0", "idle", "Wow,\u{0020}Franca\u{0020}is\u{0020}super\u{0020}cute~\u{0020}Honestly,\u{0020}who\u{0020}could\u{0020}refuse\u{0020}such\u{0020}a\u{0020}smart\u{0020}and\u{0020}adorable\u{0020}girl\u{0020}calling\u{0020}them\u{0020}\"senpai\"?", "もう……！フランカーって本当に可愛い～てか、大人しい後輩に先輩って呼ばれるのは、普通に嬉しいんだけど。", "嗚嗚嗚，弗蘭卡真的超級可愛啊～說實話，沒人能拒絕年幼又懂事的後輩叫自己學姐吧。", "0", "呜呜呜，弗兰卡真的超级可爱啊～说实话，没人能拒绝年幼又懂事的后辈叫自己学姐吧。", "0", "cv_chilyarisa_29", "0", "0"},
[410006] = {410006, 11000, 7, 5, "1_》_0_0.8", "level1", "Let\u{0020}me\u{0020}be\u{0020}straightforward:\u{0020}I\u{0020}want\u{0020}to\u{0020}be\u{0020}famous.\u{0020}I\u{0020}want\u{0020}the\u{0020}whole\u{0020}world's\u{0020}attention\u{0020}on\u{0020}me.\u{0020}I\u{0020}want\u{0020}to\u{0020}prove\u{0020}I'm\u{0020}not\u{0020}some\u{0020}useless\u{0020}rich\u{0020}girl\u{0020}who\u{0020}can\u{0020}be\u{0020}pushed\u{0020}around.", "はっきり言わせてもらうけどね。あたし、有名人になりたいの。世界中の注目を集めたいの。自分は何の取り柄もない、人の言いなりになるお嬢様じゃないってことを、証明したいの。", "我就直說了吧，我想要出名，想讓全世界的目光都聚焦到我的身上。想要……證明自己才不是什麼一無是處任人擺佈的千金大小姐。", "0", "我就直说了吧，我想要出名，想让全世界的目光都聚焦到我的身上。想要……证明自己才不是什么一无是处任人摆布的千金大小姐。", "0", "cv_chilyarisa_30", "0", "0"},
[410007] = {410007, 11000, 8, 5, "1_》_0_0.8", "level1", "Get\u{0020}lost.", "どいて。", "滾。", "0", "滚。", "0", "cv_chilyarisa_5", "0", "0"},
[410008] = {410008, 11000, 9, 5, "1_》_100_1.5", "level2", "Huh?\u{0020}Are\u{0020}you\u{0020}charmed\u{0020}by\u{0020}me~\u{0020}What\u{0020}a\u{0020}simple\u{0020}guy.", "へ？あたしに魅了されたってこと？ふ、ふーん、ちょろいヤツね。", "哈？被人家迷住了嗎～真是單純的傢伙啊。", "0", "哈？被人家迷住了吗～真是单纯的家伙啊。", "0", "cv_chilyarisa_6", "0", "0"},
[410009] = {410009, 11000, 10, 5, "1_》_500_2", "level3", "Hey,\u{0020}I\u{0020}told\u{0020}you.\u{0020}Stop\u{0020}staring\u{0020}at\u{0020}me\u{0020}like\u{0020}that...\u{0020}You're\u{0020}so\u{0020}annoying...\u{0020}waaaaaah!!!", "だから、そんなに見つめないでってば……う、鬱陶しいの！！！！！", "喂，都說了，不要再這麼盯著人家了……煩……煩死人了哇啊啊啊啊！！！！！", "0", "喂，都说了，不要再这么盯着人家了……烦……烦死人了哇啊啊啊啊！！！！！", "0", "cv_chilyarisa_7", "0", "0"},
[410010] = {410010, 11000, 11, 5, "1_》_1000_2.5", "level4", "Hmph,\u{0020}I'll\u{0020}let\u{0020}you\u{0020}look\u{0020}for\u{0020}a\u{0020}while...\u{0020}But\u{0020}just\u{0020}for\u{0020}a\u{0020}while...\u{0020}Really,\u{0020}I\u{0020}didn't\u{0020}expect\u{0020}myself\u{0020}to\u{0020}be\u{0020}this\u{0020}attractive...\u{0020}Hahaha!", "ふん。じゃあさ、ちょっとだけなら、見てもいいけど……今回だけだから、ちょっとだけだからね！もうっ……！あんたがあたしにそんなに夢中になるなんてね。あはは、あははは。", "哼，那個什麼。就破例讓你看一會吧，聽好了就一會喔……真……真是的，沒……沒想到人家的魅力這麼大啊，哈，哈哈，哈哈哈哈。", "0", "哼，那个什么。就破例让你看一会吧，听好了就一会哦……真……真是的，没……没想到人家的魅力这么大啊，哈，哈哈，哈哈哈哈。", "0", "cv_chilyarisa_8", "0", "0"},
[410011] = {410011, 11000, 12, 6, "0", "0", "Humph.", "ふーん", "吼～", "0", "吼～", "0", "cv_chilyarisa_9", "0", "0"},
