[410102] = {410102, 11001, 3, 3, "0", "0", "Alice\u{0020}Cretia,\u{0020}eldest\u{0020}daughter\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family.", "アリス・クリティア。クリティア家の長女です。", "愛麗絲·克雷蒂亞，克雷蒂亞家的長女。", "0", "爱丽丝·克雷蒂亚，克雷蒂亚家的长女。", "0", "cv_alice_1", "0", "0"},
[410103] = {410103, 11001, 4, 4, "0", "idle", "Even\u{0020}in\u{0020}a\u{0020}foreign\u{0020}land,\u{0020}I'll\u{0020}never\u{0020}forget\u{0020}who\u{0020}I\u{0020}am.", "異郷の地とて、クリティア家の長女であることを、決して忘れることはありません。", "即便身處異鄉，我也不會忘記自己是克雷蒂亞家的長女。", "0", "即便身处异乡，我也不会忘记自己是克雷蒂亚家的长女。", "0", "cv_alice_3", "0", "0"},
[410104] = {410104, 11001, 5, 4, "0", "idle", "If\u{0020}you're\u{0020}ready,\u{0020}let's\u{0020}strike,\u{0020}Navigator.\u{0020}You'll\u{0020}witness\u{0020}the\u{0020}swordsmanship\u{0020}of\u{0020}the\u{0020}rightful\u{0020}heir\u{0020}to\u{0020}the\u{0020}Cretia\u{0020}family.", "ご用意ができましたら出撃しましょう、ナビゲーター。クリティア家の正統なる後継者の剣術を披露して差し上げます。", "準備好了的話就出擊吧，領航。讓你見識一下克雷蒂亞家正統繼承人的劍藝。", "0", "准备好了的话就出击吧，领航。让你见识一下克雷蒂亚家正统继承人的剑艺。", "0", "cv_alice_4", "0", "0"},
[410105] = {410105, 11001, 6, 4, "0", "idle", "Gin\u{0020}may\u{0020}lack\u{0020}ambition,\u{0020}but\u{0020}for\u{0020}some\u{0020}reason,\u{0020}I\u{0020}like\u{0020}being\u{0020}around\u{0020}her...\u{0020}She\u{0020}feels\u{0020}more\u{0020}like\u{0020}a\u{0020}hamster\u{0020}than\u{0020}a\u{0020}cat.", "ギンは確かに向上心がないコですが、何故か彼女と一緒にいるのが大好きで……彼女って、どちらかというと猫より絹毛鼠の方に似ていますよね……", "靜雖然是個沒有上進心的孩子，但是不知道為什麼我很喜歡和她待在一起……總覺得，她比起貓咪更像是倉鼠呢……", "0", "静虽然是个没有上进心的孩子，但是不知道为什么我很喜欢和她呆在一起……总觉得，她比起猫咪更像是仓鼠呢……", "0", "cv_alice_30", "0", "0"},
[410106] = {410106, 11001, 7, 5, "1_》_0_0.8", "level1", "Before\u{0020}I\u{0020}return\u{0020}to\u{0020}Danube,\u{0020}I\u{0020}have\u{0020}to\u{0020}become\u{0020}stronger.\u{0020}Otherwise,\u{0020}going\u{0020}back\u{0020}won't\u{0020}change\u{0020}a\u{0020}thing.", "ダニューブに帰る前にもっと強くなっておかなければなりません。そうでなければ、帰ったところで何も変えられないでしょう。", "在回到多瑙之前，我必須要足夠強大才行啊，否則的話即便是回去了也改變不了什麼。", "0", "在回到多瑙之前，我必须要足够强大才行啊，否则的话即便是回去了也改变不了什么。", "0", "cv_alice_31", "0", "0"},
[410107] = {410107, 11001, 8, 5, "1_》_0_0.8", "level1", "Gin,\u{0020}stop\u{0020}messing\u{0020}around!\u{0020}Oh...\u{0020}It's\u{0020}just\u{0020}the\u{0020}Navigator.", "ギン、やめ……！あっ……！ナビゲーターだったんですね。", "靜，別鬧！欸……是領航啊。", "0", "静，别闹！哎……是领航啊。", "0", "cv_alice_5", "0", "0"},
[410108] = {410108, 11001, 9, 5, "1_》_100_1.5", "level2", "To\u{0020}escape\u{0020}the\u{0020}family's\u{0020}internal\u{0020}struggles,\u{0020}Jing\u{0020}and\u{0020}I\u{0020}were\u{0020}sent\u{0020}to\u{0020}Maya\u{0020}as\u{0020}kids.\u{0020}Over\u{0020}time,\u{0020}I've\u{0020}almost\u{0020}forgotten\u{0020}what\u{0020}my\u{0020}parents\u{0020}look\u{0020}like.", "一族内の派閥争いに巻き込まれないよう、私たちとギンは幼い頃からマヤに預けられました。気付いたら、いつの間にか両親の姿まで忘れかけていました……", "為了遠離家族內部的派系鬥爭，我和靜從小就被安置在了瑪雅。不知不覺中已經快忘記父母的樣貌了……", "0", "为了远离家族内部的派系斗争，我和静从小就被安置在了玛雅。不知不觉中已经快忘记父母的样貌了……", "0", "cv_alice_6", "0", "0"},
[410109] = {410109, 11001, 10, 5, "1_》_500_2", "level3", "Is\u{0020}this...\u{0020}A\u{0020}puff?\u{0020}How\u{0020}nostalgic.\u{0020}Jing\u{0020}and\u{0020}I\u{0020}used\u{0020}to\u{0020}sneak\u{0020}out\u{0020}to\u{0020}the\u{0020}dessert\u{0020}shop\u{0020}and\u{0020}eat\u{0020}these\u{0020}together.", "これは……シュークリームですか？懐かしい味です……昔、よくギンと一緒に家の向こうにあるデザート屋に行って、こっそり買って食べていたんです。", "這是……泡芙嗎？真是令人懷念的味道啊……以前經常和靜一起去家對面的甜品店偷偷買回來吃呢。", "0", "这是……泡芙吗？真是令人怀念的味道啊……以前经常和静一起去家对面的甜品店偷偷买回来吃呢。", "0", "cv_alice_7", "0", "0"},
[410110] = {410110, 11001, 11, 5, "1_》_1000_2.5", "level4", "For\u{0020}all\u{0020}these\u{0020}years,\u{0020}there's\u{0020}only\u{0020}been\u{0020}one\u{0020}thing\u{0020}in\u{0020}my\u{0020}mind—going\u{0020}home.\u{0020}But\u{0020}Tina,\u{0020}my\u{0020}teacher,\u{0020}and\u{0020}my\u{0020}parents\u{0020}still\u{0020}think\u{0020}I'm\u{0020}not\u{0020}mature\u{0020}enough...", "長い間、私の頭の中をいっぱいにしているのは一つ――それは、家に帰ること。でも、ティナ先生も、両親も、皆私のことをまだ未熟者だと思っていて……", "這麼多年，我的腦海中只有一件事……那就是回家。但是無論是蒂娜老師還是父母都覺得我還不夠成熟……", "0", "这么多年，我的脑海中只有一件事……那就是回家。但是无论是蒂娜老师还是父母都觉得我还不够成熟……", "0", "cv_alice_8", "0", "0"},
[410111] = {410111, 11001, 12, 6, "0", "0", "Wonderful!\u{0020}Make\u{0020}me\u{0020}stronger!", "よし、もっと強くなりますから！", "很好，讓我變得更強吧！", "0", "很好，让我变得更强吧！", "0", "cv_alice_9", "0", "0"},
[410112] = {410112, 11001, 13, 7, "0", "0", "Stronger\u{0020}than\u{0020}anyone\u{0020}else...", "誰よりも……強い存在ですわ。", "比任何人……都要強。", "0", "比任何人……都要强。", "0", "cv_alice_10", "0", "0"},
[410113] = {410113, 11001, 14, 8, "0", "0", "Is\u{0020}this\u{0020}what\u{0020}it\u{0020}feels\u{0020}like\u{0020}to\u{0020}break\u{0020}my\u{0020}own\u{0020}limits?", "これが自分の限界を突破した感覚でしょうか。", "這就是突破自我的感覺嗎？", "0", "这就是突破自我的感觉吗？", "0", "cv_alice_11", "0", "0"},
[410114] = {410114, 11001, 15, 9, "0", "0", "I\u{0020}need\u{0020}more\u{0020}speed,\u{0020}more\u{0020}accuracy,\u{0020}and\u{0020}more\u{0020}power.", "速度、命中率、力強さ。全部精進しないと。", "速度，准度，力度，都需要提升啊。", "0", "速度，准度，力度，都需要提升啊。", "0", "cv_alice_12", "0", "0"},
[410115] = {410115, 11001, 16, 10, "0", "0", "Victory\u{0020}is\u{0020}ours!", "勝利は我らにあり！", "勝利，是屬於我們的！", "0", "胜利，是属于我们的！", "0", "cv_alice_13", "0", "0"},
[410116] = {410116, 11001, 17, 11, "0", "0", "Humph.\u{0020}As\u{0020}expected,\u{0020}I'm\u{0020}the\u{0020}best.", "やはり私が一番優秀なんですよ。", "哼，果然我才是最優秀的吧。", "0", "哼，果然我才是最优秀的吧。", "0", "cv_alice_14", "0", "0"},
[410117] = {410117, 11001, 18, 12, "0", "0", "Well,\u{0020}I\u{0020}guess\u{0020}that's\u{0020}just\u{0020}barely\u{0020}acceptable.", "ふーん、まぁまぁでしたね。", "嗯，勉強算是及格吧。", "0", "嗯，勉强算是及格吧。", "0", "cv_alice_15", "0", "0"},
[410118] = {410118, 11001, 19, 13, "0", "0", "Not\u{0020}enough...\u{0020}This\u{0020}is\u{0020}nowhere\u{0020}near\u{0020}good\u{0020}enough.", "まだまだです……！こんなみっともないパフォーマンスで終われません！", "還不夠……這樣的表現差得也太遠了。", "0", "还不够……这样的表现差得也太远了。", "0", "cv_alice_16", "0", "0"},
[410119] = {410119, 11001, 20, 14, "0", "0", "Impossible...\u{0020}How\u{0020}could\u{0020}this\u{0020}happen?\u{0020}I\u{0020}won't\u{0020}accept\u{0020}it!", "ありえません……こんなの、私は絶対認めません！", "不可能……為什麼會這樣？我不承認！", "0", "不可能……为什么会这样？我不承认！", "0", "cv_alice_17", "0", "0"},
[410120] = {410120, 11001, 21, 15, "0", "0", "It's\u{0020}over.\u{0020}There's\u{0020}no\u{0020}room\u{0020}left\u{0020}for\u{0020}a\u{0020}counterattack.", "お終いです。あなたにはもう、反撃する余地がありません。", "結束了，你已經沒有反擊的機會了。", "0", "结束了，你已经没有反击的机会了。", "0", "cv_alice_18", "0", "0"},
[410121] = {410121, 11001, 23, 16, "0", "0", "Pierce\u{0020}through!", "貫け！", "貫穿吧！", "0", "贯穿吧！", "0", "cv_alice_19", "0", "0"},
[410122] = {410122, 11001, 24, 17, "0", "0", "Watch\u{0020}closely—this\u{0020}is\u{0020}my\u{0020}swordsmanship.", "よく見てください、私の剣術を！", "好好看著吧，我的劍藝。", "0", "好好看着吧，我的剑艺。", "0", "cv_alice_21", "0", "0"},
[410123] = {410123, 11001, 25, 18, "0", "0", "Will\u{0020}I\u{0020}be\u{0020}acknowledged\u{0020}at\u{0020}this\u{0020}level?\u{0020}This\u{0020}is\u{0020}my...\u{0020}True\u{0020}strength!", "たかがこの程度で認められるのですか？これこそ私の……本当の力です！", "只是這種程度就能被認可了嗎？這才是我……真正的實力！", "0", "只是这种程度就能被认可了吗？这才是我……真正的实力！", "0", "cv_alice_22", "0", "0"},
[410124] = {410124, 11001, 26, 19, "0", "0", "So...\u{0020}In\u{0020}the\u{0020}end,\u{0020}you\u{0020}didn't\u{0020}choose\u{0020}me,\u{0020}did\u{0020}you?", "そうですか……結局、私を選んでくれなかったのですね……", "是嗎……最後還是沒有選擇我嗎……", "0", "是吗……最后还是没有选择我吗……", "0", "cv_alice_20", "0", "0"},
[410125] = {410125, 11001, 27, 20, "0", "0", "The\u{0020}filth\u{0020}we\u{0020}collect\u{0020}on\u{0020}the\u{0020}outside\u{0020}might\u{0020}just\u{0020}sink\u{0020}into\u{0020}the\u{0020}soul.", "身体に蓄積されている穢れは、心にまで侵入することもあるのかもしれませんね。", "身體上積攢下的污穢，說不定也會浸入心靈呢。", "0", "身体上积攒下的污秽，说不定也会浸入心灵呢。", "0", "cv_alice_23", "0", "0"},
[410126] = {410126, 11001, 28, 21, "0", "0", "Haaah...\u{0020}Only\u{0020}now\u{0020}can\u{0020}I\u{0020}fully\u{0020}unwind.", "ふぅ――この時だけは、完全にリラックスできますね。", "呼啊——只有在這種時候才能徹底放鬆下來啊。", "0", "呼啊——只有在这种时候才能彻底放松下来啊。", "0", "cv_alice_24", "0", "0"},
