[410131] = {410131, 11001, 33, 25, "0", "0", "It's\u{0020}just\u{0020}a\u{0020}game.\u{0020}I\u{0020}won't\u{0020}let\u{0020}it\u{0020}get\u{0020}to\u{0020}me...", "ただのゲームですから、気にすることないでしょう……", "只是遊戲而已，我並不會放在心上……", "0", "只是游戏而已，我并不会放在心上……", "0", "cv_alice_29", "0", "0"},
[410132] = {410132, 11001, 34, 26, "0", "0", "Today,\u{0020}I'll\u{0020}stand\u{0020}and\u{0020}fight\u{0020}right\u{0020}by\u{0020}your\u{0020}side\u{0020}again.", "今日も、一緒に戦っていきましょう。", "今天我也將和你一起並肩作戰呢。", "0", "今天我也将和你一起并肩作战呢。", "0", "cv_alice_32", "0", "0"},
