[410202] = {410202, 11002, 3, 3, "0", "0", "Navigator\u{0020}of\u{0020}the\u{0020}west...\u{0020}My\u{0020}name\u{0020}is\u{0020}Kokorokami.\u{0020}From\u{0020}now\u{0020}on,\u{0020}I\u{0020}will\u{0020}serve\u{0020}by\u{0020}your\u{0020}side.", "西の方のナビゲーターですね……いいでしょう。吾は心紙と申します。これからあなた様に仕え致します。", "西方的領航嗎……也罷，老身名為心紙，今後就由老身侍您左右吧。", "0", "西方的领航吗……也罢，老身名为心纸，今后就由老身侍您左右吧。", "0", "cv_kokorokami_1", "0", "0"},
[410203] = {410203, 11002, 4, 4, "0", "idle", "Are\u{0020}the\u{0020}gods\u{0020}hypocritical?\u{0020}Huh,\u{0020}after\u{0020}turning\u{0020}delusions\u{0020}into\u{0020}reality\u{0020}and\u{0020}twisting\u{0020}all\u{0020}common\u{0020}sense,\u{0020}would\u{0020}they\u{0020}still\u{0020}care\u{0020}about\u{0020}such\u{0020}things?", "神様は偽りの存在、ですか……ふん、妄想を現実に変え、全ての常識を覆した後だというのに、まだそんなことにこだわっているのですか？", "神明是虛偽的嗎……哼，讓妄想變為現實，顛覆了所有常識之後，您居然還會在意這些嗎？", "0", "神明是虚伪的吗……哼，让妄想变为现实，颠覆了所有常识之后，您居然还会在意这些吗？", "0", "cv_kokorokami_3", "0", "0"},
[410204] = {410204, 11002, 5, 4, "0", "idle", "I\u{0020}enjoy\u{0020}the\u{0020}fragrance\u{0020}of\u{0020}tea\u{0020}and\u{0020}flowers.\u{0020}I\u{0020}didn't\u{0020}expect\u{0020}someone\u{0020}born\u{0020}in\u{0020}Danube\u{0020}to\u{0020}appreciate\u{0020}them\u{0020}too.\u{0020}That's\u{0020}quite\u{0020}rare.", "お茶の香りとお花の香りですか……二つとも、吾の好物です。まさかダニューブ出身のあなた様に見る目があったとは。驚きですね。", "茶味花香嗎……這兩者都是老身所喜好的，沒想到出生在多瑙的您也懂得欣賞這些，真是難得。", "0", "茶味花香吗……这两者都是老身所喜好的，没想到出生在多瑙的您也懂得欣赏这些，真是难得。", "0", "cv_kokorokami_4", "0", "0"},
[410205] = {410205, 11002, 6, 4, "0", "idle", "Hotarugusa...\u{0020}No,\u{0020}it\u{0020}should\u{0020}be\u{0020}Little\u{0020}Hotarugusa.\u{0020}I'd\u{0020}probably\u{0020}get\u{0020}killed\u{0020}if\u{0020}I\u{0020}called\u{0020}her\u{0020}by\u{0020}the\u{0020}wrong\u{0020}name\u{0020}in\u{0020}front\u{0020}of\u{0020}her.", "蛍草姉さま……いえ、蛍草ちゃん、と呼ぶべきでしょう……彼女の前で呼び名を間違えたら殺されかねません。", "瑩草姐……不對，應該是小瑩草才是……如果當著她的面說錯稱呼估計會被殺掉吧。", "0", "莹草姐……不对，应该是小莹草才是……如果当着她的面说错称呼估计会被杀掉吧。", "0", "cv_kokorokami_30", "0", "0"},
[410206] = {410206, 11002, 7, 5, "1_》_0_0.8", "level1", "The\u{0020}gods\u{0020}only\u{0020}hold\u{0020}value\u{0020}when\u{0020}there's\u{0020}chaos.\u{0020}I'm\u{0020}driven\u{0020}by\u{0020}such\u{0020}a\u{0020}mission.", "神様は動乱時にのみ存在価値があります。吾はただ、使命に駆られて前に進んでいるだけです。", "神明只有在動亂時才有存在的價值，老身只不過是被這樣的使命驅使著前行罷了。", "0", "神明只有在动乱时才有存在的价值，老身只不过是被这样的使命驱使着前行罢了。", "0", "cv_kokorokami_31", "0", "0"},
[410207] = {410207, 11002, 8, 5, "1_》_0_0.8", "level1", "Could\u{0020}you\u{0020}please\u{0020}talk\u{0020}privately?\u{0020}I'm\u{0020}not\u{0020}available\u{0020}right\u{0020}now.", "後にしていただけますか？今は忙しいのです。", "可以請您私下再說嗎？現在老身並沒有空。", "0", "可以请您私下再说吗？现在老身并没有空。", "0", "cv_kokorokami_5", "0", "0"},
[410208] = {410208, 11002, 9, 5, "1_》_100_1.5", "level2", "Why?\u{0020}Have\u{0020}you\u{0020}come\u{0020}to\u{0020}find\u{0020}me\u{0020}again?\u{0020}I'm\u{0020}sorry.\u{0020}Next\u{0020}time,\u{0020}I'll\u{0020}let\u{0020}you\u{0020}know\u{0020}in\u{0020}advance\u{0020}when\u{0020}I'm\u{0020}free.", "また吾の所へ来たのですか？申し訳ありません。時間ができた時に、また連絡いたしますので。", "怎麼？又來找老身了嗎？很抱歉，下次有空時會提前告知您的。", "0", "怎么？又来找老身了吗？很抱歉，下次有空时会提前告知您的。", "0", "cv_kokorokami_6", "0", "0"},
[410209] = {410209, 11002, 10, 5, "1_》_500_2", "level3", "What\u{0020}a\u{0020}persistent\u{0020}man!\u{0020}So,\u{0020}what\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}talk\u{0020}about?\u{0020}Don't\u{0020}worry.\u{0020}As\u{0020}a\u{0020}shrine\u{0020}maiden\u{0020}serving\u{0020}the\u{0020}gods,\u{0020}I\u{0020}will\u{0020}patiently\u{0020}answer\u{0020}all\u{0020}your\u{0020}questions.", "しつこい方ですね。では、吾とどんな話をしたいのですか？ご安心ください。神様に仕える巫女として、あなた様の質問全てに、根気よくお答えします。", "真是個執著的男人啊，那麼您想和老身聊些什麼呢？放心好了，身為侍奉神明的巫女，我會耐心回答完您所有的疑問。", "0", "真是个执着的男人啊，那么您想和老身聊些什么呢？放心好了，身为侍奉神明的巫女，我会耐心回答完您所有的疑问。", "0", "cv_kokorokami_7", "0", "0"},
[410210] = {410210, 11002, 11, 5, "1_》_1000_2.5", "level4", "Ah...\u{0020}It\u{0020}seems\u{0020}I've\u{0020}been\u{0020}discovered.\u{0020}The\u{0020}gods\u{0020}I\u{0020}mentioned,\u{0020}my\u{0020}hobbies...\u{0020}Even\u{0020}my\u{0020}name\u{0020}is\u{0020}false.\u{0020}Yes,\u{0020}the\u{0020}girl\u{0020}who\u{0020}has\u{0020}spent\u{0020}time\u{0020}with\u{0020}you\u{0020}is\u{0020}just\u{0020}a\u{0020}false\u{0020}incarnation,\u{0020}a\u{0020}puppet\u{0020}of\u{0020}faith.\u{0020}What?\u{0020}You\u{0020}think\u{0020}both\u{0020}sides\u{0020}of\u{0020}me\u{0020}are\u{0020}real\u{0020}in\u{0020}your\u{0020}eyes...?", "ああ……もうばれてしまったのですね。吾が申し上げた神様、趣味……そして自分の名前は、全て嘘ですそう、今まであなた様とともに過ごしてきた吾は、ただの偽りの存在、信仰の人形にすぎません……えっ？どの吾でも、あなた様にとっては……真の存在である、と…...？", "啊……想必已經被發現了吧，我口中的神明，愛好……甚至我的姓名都是虛假的。沒錯，這段時間與您相處的女孩只不過是虛偽的化身，信仰的人偶罷了……什麼？您說無論哪邊的我在您眼中都是……真實的嗎……", "0", "啊……想必已经被发现了吧，我口中的神明，爱好……甚至我的姓名都是虚假的。没错，这段时间与您相处的女孩只不过是虚伪的化身，信仰的人偶罢了……什么？您说无论哪边的我在您眼中都是……真实的吗……", "0", "cv_kokorokami_8", "0", "0"},
[410211] = {410211, 11002, 12, 6, "0", "0", "Ah...\u{0020}This\u{0020}power\u{0020}is\u{0020}welling\u{0020}up\u{0020}from\u{0020}my\u{0020}heart...", "ああ……この心から湧き上がる力……", "啊……這股從心中湧現出的力量……", "0", "啊……这股从心中涌现出的力量……", "0", "cv_kokorokami_9", "0", "0"},
[410212] = {410212, 11002, 13, 7, "0", "0", "My\u{0020}faith\u{0020}has\u{0020}grown\u{0020}stronger.", "信仰心が向上したようですね。", "信仰的純度，提高了呢。", "0", "信仰的纯度，提高了呢。", "0", "cv_kokorokami_10", "0", "0"},
[410213] = {410213, 11002, 14, 8, "0", "0", "Cherry\u{0020}blossoms\u{0020}are\u{0020}falling,\u{0020}their\u{0020}beauty\u{0020}fading\u{0020}in\u{0020}an\u{0020}instant.\u{0020}What\u{0020}does\u{0020}an\u{0020}illusory\u{0020}shadow\u{0020}mean?\u{0020}It's\u{0020}worth\u{0020}dedicating\u{0020}half\u{0020}a\u{0020}lifetime\u{0020}to\u{0020}understand.\u{0020}Yet,\u{0020}your\u{0020}intentions\u{0020}have\u{0020}come\u{0020}through.", "桜の花びらが舞い上がる、その美しさは一瞬のこと。そんな偽りの景色を求めるために、なぜ人は生涯をかけるのでしょうか……とはいえ、あなた様のお気持ち、しっかりと受け止めさせていただきました。", "落櫻紛飛，刹那芳華，何為虛影，傾此半生。但您的心意，已經傳達到了。", "0", "落樱纷飞，刹那芳华，何为虚影，倾此半生。但您的心意，已经传达到了。", "0", "cv_kokorokami_11", "0", "0"},
[410214] = {410214, 11002, 15, 9, "0", "0", "Has\u{0020}the\u{0020}purity\u{0020}of\u{0020}my\u{0020}skills\u{0020}improved\u{0020}as\u{0020}well?", "技術の練度も、上がりましたでしょうか。", "技藝的純度，也提升了嗎？", "0", "技艺的纯度，也提升了吗？", "0", "cv_kokorokami_12", "0", "0"},
[410215] = {410215, 11002, 16, 10, "0", "0", "Now,\u{0020}let\u{0020}me\u{0020}handle\u{0020}it.", "ここは吾にお任せください。", "下麵就交由老身吧。", "0", "下面就交由老身吧。", "0", "cv_kokorokami_13", "0", "0"},
[410216] = {410216, 11002, 17, 11, "0", "0", "Great\u{0020}job,\u{0020}Navigator!", "お見事です！ナビゲーター！", "做得好啊！領航！", "0", "做得好啊！领航！", "0", "cv_kokorokami_14", "0", "0"},
[410217] = {410217, 11002, 18, 12, "0", "0", "That'll\u{0020}do.", "まぁ、悪くはないでしょう。", "還算可以吧。", "0", "还算可以吧。", "0", "cv_kokorokami_15", "0", "0"},
[410218] = {410218, 11002, 19, 13, "0", "0", "Tsk,\u{0020}why\u{0020}does\u{0020}the\u{0020}sword\u{0020}have\u{0020}to\u{0020}be\u{0020}so\u{0020}cumbersome?", "刀剣は所詮、道具に過ぎません。", "嘖，刀劍豈是如此不便之物！", "0", "啧，刀剑岂是如此不便之物！", "0", "cv_kokorokami_16", "0", "0"},
[410219] = {410219, 11002, 20, 14, "0", "0", "As\u{0020}I\u{0020}suspected,\u{0020}some\u{0020}things\u{0020}can't\u{0020}be\u{0020}achieved\u{0020}with\u{0020}willpower\u{0020}alone.", "やはり……精神力だけでは解決できないこともありますね。", "果然……有些事僅憑精神力是做不到的。", "0", "果然……有些事仅凭精神力是做不到的。", "0", "cv_kokorokami_17", "0", "0"},
