[410223] = {410223, 11002, 25, 18, "0", "0", "Come\u{0020}on,\u{0020}let's\u{0020}watch\u{0020}together...\u{0020}Burn\u{0020}away\u{0020}all\u{0020}the\u{0020}filth!", "さあ、一緒に見届けましょう……全ての穢れを燃やし尽くせ！", "來吧，一同見證吧…燒盡一切污穢之物吧！", "0", "来吧，一同见证吧……烧尽一切污秽之物吧！", "0", "cv_kokorokami_22", "0", "0"},
[410224] = {410224, 11002, 26, 19, "0", "0", "It\u{0020}ends\u{0020}here...\u{0020}even\u{0020}the\u{0020}god\u{0020}I\u{0020}believed\u{0020}in\u{0020}has\u{0020}failed...", "ここまでのようですね……吾が信じている神様さえ……", "到此為止了啊……老身所信仰的神明也沒能……", "0", "到此为止了啊……老身所信仰的神明也没能……", "0", "cv_kokorokami_20", "0", "0"},
