[410227] = {410227, 11002, 29, 21, "0", "0", "If\u{0020}everything\u{0020}is\u{0020}cleared,\u{0020}make\u{0020}sure\u{0020}to\u{0020}inform\u{0020}this\u{0020}old\u{0020}woman.", "全てをきれいにされましたら、吾にご一報ください。", "如果已經清理完畢了，請務必通知老身一聲。", "0", "如果已经清理完毕了，请务必通知老身一声。", "0", "cv_kokorokami_25", "0", "0"},
[410228] = {410228, 11002, 30, 22, "0", "0", "Chop!...\u{0020}Wait,\u{0020}this\u{0020}is\u{0020}your\u{0020}battle.\u{0020}I\u{0020}can't\u{0020}interfere.", "斬ります！……あっ、申し訳ありません。これはあなた様の戦いですから、吾は介入できませんね。", "斬!……等等，這是您的戰鬥，老身無法插手。", "0", "斩!……等等，这是您的战斗，老身无法插手。", "0", "cv_kokorokami_26", "0", "0"},
[410229] = {410229, 11002, 31, 23, "0", "0", "So,\u{0020}how\u{0020}will\u{0020}you\u{0020}decide?", "では、あなた様はどんな選択をされるのでしょう。", "那麼，您會怎麼選呢？", "0", "那么，您会怎么选呢？", "0", "cv_kokorokami_27", "0", "0"},
[410230] = {410230, 11002, 32, 24, "0", "0", "It\u{0020}seems\u{0020}your\u{0020}faith\u{0020}is\u{0020}very\u{0020}strong,\u{0020}Navigator.", "どうやらあなた様の信仰心は厚いようですね、ナビゲーター。", "看來您信仰的純度很高呢，領航。", "0", "看来您信仰的纯度很高呢，领航。", "0", "cv_kokorokami_28", "0", "0"},
[410231] = {410231, 11002, 33, 25, "0", "0", "I\u{0020}don't\u{0020}mind\u{0020}either\u{0020}way.", "吾は別にどちらでも構いませんが。", "老身無所謂。", "0", "老身无所谓。", "0", "cv_kokorokami_29", "0", "0"},
[410232] = {410232, 11002, 34, 26, "0", "0", "Welcome\u{0020}back!\u{0020}I've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}you.", "お帰りなさいませ。お待ちしておりました。", "歡迎回來，老身已經恭候多時了。", "0", "欢迎回来，老身已经恭候多时了。", "0", "cv_kokorokami_32", "0", "0"},
