[410302] = {410302, 11003, 3, 3, "0", "0", "I'm\u{0020}Suzuki\u{0020}Seifung\u{0020}from\u{0020}Fuurinkazan,\u{0020}and\u{0020}by\u{0020}the\u{0020}way,\u{0020}I'm\u{0020}the\u{0020}team\u{0020}captain.", "うちは風林火山の鈴木清風。ちなみに、隊長やで。", "咱是風林火山的鈴木清風，順帶一提，咱可是隊長喔。", "0", "咱是风林火山的铃木清风，顺带一提，咱可是队长哦。", "0", "cv_suzuki_1", "0", "0"},
[410303] = {410303, 11003, 4, 4, "0", "idle", "For\u{0020}me,\u{0020}protecting\u{0020}my\u{0020}companions\u{0020}comes\u{0020}first.", "うちにとって一番大切なことは仲間を守ることや。", "對咱而言，優先保護好同伴才是最重要的。", "0", "对咱而言，优先保护好同伴才是最重要的。", "0", "cv_suzuki_3", "0", "0"},
[410304] = {410304, 11003, 5, 4, "0", "idle", "Navigator,\u{0020}I'm\u{0020}curious—don't\u{0020}you\u{0020}need\u{0020}to\u{0020}rest?", "なあ、ナビゲーター。前から気になってたんやけど…...ナビゲーターは休憩とかせえへんの？", "領航呀，咱很好奇呀，你難道不需要休息嗎？", "0", "领航呀，咱很好奇呀，你难道不需要休息吗？", "0", "cv_suzuki_4", "0", "0"},
[410305] = {410305, 11003, 6, 4, "0", "idle", "Shiranui\u{0020}always\u{0020}looks\u{0020}at\u{0020}me\u{0020}as\u{0020}if\u{0020}I\u{0020}were\u{0020}a\u{0020}child.\u{0020}Huhu,\u{0020}to\u{0020}me,\u{0020}she's\u{0020}the\u{0020}one\u{0020}who\u{0020}needs\u{0020}looking\u{0020}after.\u{0020}After\u{0020}all,\u{0020}I'm\u{0020}the\u{0020}captain\u{0020}of\u{0020}this\u{0020}team.", "不知火はいつも子供を見る目でうちを見とるけど、ふふ、うちにとっては、あいつこそ世話する必要がある子供なんやで。だって、うちがこのチームの隊長やからね！", "不知火那孩子，總是用看小孩的目光看著咱呢。呼呼呼，對於咱來說，她才是需要照顧的孩子呢。因為，咱才是這支隊伍的隊長呀。", "0", "不知火那孩子，总是用看小孩的目光看着咱呢。呼呼呼，对于咱来说，她才是需要照顾的孩子呢。因为，咱才是这支队伍的队长呀。", "0", "cv_suzuki_30", "0", "0"},
[410306] = {410306, 11003, 7, 5, "1_》_0_0.8", "level1", "My\u{0020}dream?\u{0020}Um,\u{0020}I\u{0020}don't\u{0020}have\u{0020}the\u{0020}energy\u{0020}to\u{0020}think\u{0020}about\u{0020}that.\u{0020}Just\u{0020}taking\u{0020}care\u{0020}of\u{0020}my\u{0020}companions\u{0020}has\u{0020}drained\u{0020}a\u{0020}lot\u{0020}of\u{0020}my\u{0020}energy.", "うちの夢？うーん、そんなん考える時間がないなあ。チーム内の仲間たちの世話をすることだけで手いっぱいやもん。", "咱的夢想？嗚，咱可沒有精力去想那些。光是照顧隊伍裡的同伴，就已經耗費咱不少精力了。", "0", "咱的梦想？呜，咱可没有精力去想那些。光是照顾队伍里的同伴，就已经耗费咱不少精力了。", "0", "cv_suzuki_31", "0", "0"},
[410307] = {410307, 11003, 8, 5, "1_》_0_0.8", "level1", "Please\u{0020}don't\u{0020}just\u{0020}stare\u{0020}at\u{0020}me.\u{0020}If\u{0020}you\u{0020}have\u{0020}something\u{0020}to\u{0020}ask,\u{0020}go\u{0020}ahead!", "そ、そんな目で見つめんといて。聞きたいことがあるんやったらはよ聞いてや。", "別……別老是光盯著咱啊，有話快問啦。", "0", "别……别老是光盯着咱啊，有话快问啦。", "0", "cv_suzuki_5", "0", "0"},
[410308] = {410308, 11003, 9, 5, "1_》_100_1.5", "level2", "Eh?\u{0020}You\u{0020}want\u{0020}to\u{0020}know\u{0020}how\u{0020}to\u{0020}communicate\u{0020}with\u{0020}the\u{0020}team\u{0020}members?\u{0020}Well...\u{0020}to\u{0020}be\u{0020}honest,\u{0020}I'm\u{0020}not\u{0020}really\u{0020}sure\u{0020}either.", "え？チームメンバーとどうやって交流すればええかって……？えっと……正直、うちもよくわからんのや……", "欸？想向咱請教該怎麼和隊員交流。嗯嗯……老實說，咱也不是很清楚欸……", "0", "哎？想向咱请教该怎么和队员交流。嗯嗯……老实说，咱也不是很清楚哎……", "0", "cv_suzuki_6", "0", "0"},
[410309] = {410309, 11003, 10, 5, "1_》_500_2", "level3", "What\u{0020}do\u{0020}I\u{0020}like?\u{0020}Hmm...\u{0020}Sukiyaki,\u{0020}I\u{0020}guess.\u{0020}Of\u{0020}course,\u{0020}I\u{0020}mean\u{0020}I\u{0020}enjoy\u{0020}making\u{0020}Sukiyaki,\u{0020}not\u{0020}just\u{0020}eating\u{0020}it.", "え？うちの好きな物？うーん……すき焼きかな。もちろん、食べるのも好きやけど、作るのも好きやしね。", "欸？咱喜歡的東西？嗯嗯……壽喜燒吧。當然，咱指的是喜歡製作壽喜燒，而不是吃啦。", "0", "哎？咱喜欢的东西？嗯嗯……寿喜烧吧。当然，咱指得是喜欢制作寿喜烧，而不是吃啦。", "0", "cv_suzuki_7", "0", "0"},
[410310] = {410310, 11003, 11, 5, "1_》_1000_2.5", "level4", "Really,\u{0020}Navigator,\u{0020}you've\u{0020}been\u{0020}asking\u{0020}so\u{0020}many\u{0020}questions\u{0020}lately.\u{0020}It's\u{0020}like\u{0020}talking\u{0020}to\u{0020}my\u{0020}younger\u{0020}brother\u{0020}who\u{0020}hasn't\u{0020}lost\u{0020}his\u{0020}baby\u{0020}teeth\u{0020}yet!\u{0020}But...\u{0020}I\u{0020}think\u{0020}this\u{0020}kind\u{0020}of\u{0020}relationship\u{0020}is\u{0020}nice\u{0020}too.", "まったく……最近のナビゲーターって、色々質問してくるからまるで歯の生え変わりがまだ始まっとらんうちの弟みたいなんやけど。まぁ……こんな関係でもええけどな。", "真是的，這段時間領航你總是問東問西的，整得就像是咱那個沒換牙的弟弟一樣。不過……咱覺得這種關係也不錯呢。", "0", "真是的，这段时间领航你总是问东问西的，整得就像是咱那个没换牙的弟弟一样。不过……咱觉得这种关系也不错呢。", "0", "cv_suzuki_8", "0", "0"},
[410311] = {410311, 11003, 12, 6, "0", "0", "Amazing!\u{0020}Navigator,\u{0020}I've\u{0020}become\u{0020}stronger!", "大変、ナビゲーター！うち、強くなったんよ！", "不得了啊！領航，咱變強了呀！", "0", "不得了啊！领航，咱变强了呀！", "0", "cv_suzuki_9", "0", "0"},
[410312] = {410312, 11003, 13, 7, "0", "0", "Are\u{0020}you...\u{0020}really\u{0020}that\u{0020}concerned\u{0020}about\u{0020}me?", "そんなに……うちのことが気になる？", "你就……這麼在意咱嗎？", "0", "你就……这么在意咱吗？", "0", "cv_suzuki_10", "0", "0"},
[410313] = {410313, 11003, 14, 8, "0", "0", "Ooh\u{0020}ooh\u{0020}ooh\u{0020}ooh—Navigator,\u{0020}did\u{0020}you\u{0020}see\u{0020}it!\u{0020}The\u{0020}color\u{0020}of\u{0020}the\u{0020}sword...\u{0020}the\u{0020}color\u{0020}of\u{0020}the\u{0020}blade!!!\u{0020}Wait,\u{0020}you\u{0020}say\u{0020}there's\u{0020}no\u{0020}change?!", "おおっ――ナビゲーター！今の見た？刀の色……刃の色！！！えっ？特に変わっとらんって？！", "喔喔喔喔——領航，你看到了嗎！刀的顏色…刀刃的顏色！！！欸，你說沒啥變化？！", "0", "噢噢噢噢——领航，你看到了吗！刀的颜色…刀刃的颜色！！！哎，你说没啥变化？！", "0", "cv_suzuki_11", "0", "0"},
[410314] = {410314, 11003, 15, 9, "0", "0", "Steady!", "ばっちり！", "穩穩的！", "0", "妥妥滴！", "0", "cv_suzuki_12", "0", "0"},
[410315] = {410315, 11003, 16, 10, "0", "0", "Cut\u{0020}down\u{0020}the\u{0020}enemy's\u{0020}flag!", "敵の旗を斬り落とせ！", "斬落敵人的旗幟吧！", "0", "斩落敌人的旗帜吧！", "0", "cv_suzuki_13", "0", "0"},
