[410339] = {410339, 11003, 41, 33, "0", "0", "Make\u{0020}sure\u{0020}you\u{0020}check\u{0020}your\u{0020}situation\u{0020}properly.", "自分の状況をちゃんと確認せんといかんなあ。", "要好好確認自己的狀況才行喔。", "0", "要好好确认自己的状况才行哦。", "0", "cv_suzuki_40", "0", "0"},
[410340] = {410340, 11003, 42, 34, "0", "0", "A\u{0020}great\u{0020}commander\u{0020}knows\u{0020}how\u{0020}to\u{0020}be\u{0020}flexible.", "臨機応変に対応出来るっちゅーことは、優秀な指揮官に要求される才能なんやで。", "適當的變通才是優秀指揮官的體現。", "0", "适当的变通才是优秀指挥官的体现。", "0", "cv_suzuki_41", "0", "0"},
