[410401] = {410401, 11004, 2, 2, "0", "0", "Oh,\u{0020}you\u{0020}mean...\u{0020}Um,\u{0020}sorry\u{0020}if\u{0020}I\u{0020}overthought\u{0020}that.", "つまり……いいえ、失礼しました。私の考え過ぎかもしれません。", "您的意思是……嗯嗯，抱歉，可能是我想多了。", "0", "您的意思是……嗯嗯，抱歉，可能是我想多了。", "0", "cv_kuriyama_2", "0", "0"},
[410402] = {410402, 11004, 3, 3, "0", "0", "Nice\u{0020}to\u{0020}meet\u{0020}you!\u{0020}I'm\u{0020}Kuriyama\u{0020}Seiran\u{0020}from\u{0020}Fuurinkazan.\u{0020}I\u{0020}hope\u{0020}my\u{0020}appearance\u{0020}didn't\u{0020}scare\u{0020}you.", "初めまして。私は風林火山部隊の栗山青鸞です。あの……私の身体、怖くないでしょうか……？", "初次見面，我是來自風林火山部隊的栗山青鸞。那個……我的身體應該沒有嚇到您吧？", "0", "初次见面，我是来自风林火山部队的栗山青鸾。那个……我的身体应该没有吓到您吧？", "0", "cv_kuriyama_1", "0", "0"},
[410403] = {410403, 11004, 4, 4, "0", "idle", "My\u{0020}body...\u{0020}Is\u{0020}it\u{0020}scary?\u{0020}If\u{0020}it\u{0020}bothers\u{0020}you,\u{0020}I'll\u{0020}leave.\u{0020}Eh?\u{0020}You\u{0020}say\u{0020}it's\u{0020}fine?", "私の身体……怖いでしょう？見てて気分が悪くなるとか…...すみません、すぐここを離れますから。え？気にすることはない、ですか？", "我的身體……很嚇人吧？如果讓您感到不舒服的話我馬上就離開這裡。欸？你說不用放在心上？", "0", "我的身体……很吓人吧？如果让您感到不舒服的话我马上就离开这里。哎？你说不用放在心上？", "0", "cv_kuriyama_3", "0", "0"},
[410404] = {410404, 11004, 5, 4, "0", "idle", "This\u{0020}child's\u{0020}name\u{0020}is\u{0020}Taro.\u{0020}I\u{0020}share\u{0020}its\u{0020}vision.\u{0020}It's\u{0020}quite\u{0020}powerful,\u{0020}huh-huh.", "このコは太郎っていいます。視覚を共有しているんですよ。このコ、凄いでしょ？えへへ。", "這個孩子的名字叫做太郎，我和它的視覺是共用的喔。它很厲害吧，嘿嘿。", "0", "这个孩子的名字叫做太郎，我和他的视觉是共享的哦。它很厉害吧，嘿嘿。", "0", "cv_kuriyama_4", "0", "0"},
[410405] = {410405, 11004, 6, 4, "0", "idle", "I\u{0020}still\u{0020}couldn't\u{0020}talk\u{0020}well\u{0020}with\u{0020}Kinosuke\u{0020}today...\u{0020}Even\u{0020}though\u{0020}she\u{0020}always\u{0020}looks\u{0020}angry,\u{0020}I\u{0020}still\u{0020}think\u{0020}she's\u{0020}a\u{0020}good\u{0020}girl.", "今日も、鬼之介とはちゃんと話せなかったですね……いつも怒っているみたいですけど、嫌われているというよりは、ただの子供なんだと、思います。", "今天又沒能好好和鬼之介說上話呢……雖然她總是一副生氣的樣子，但是我還是覺得她其實是個好孩子。", "0", "今天又没能好好和鬼之介说上话呢……虽然她总是一副生气的样子，但是我还是觉得她其实是个好孩子。", "0", "cv_kuriyama_28", "0", "0"},
[410406] = {410406, 11004, 7, 5, "1_》_0_0.8", "level1", "Navigator...\u{0020}After\u{0020}the\u{0020}war,\u{0020}could\u{0020}you\u{0020}go\u{0020}somewhere\u{0020}with\u{0020}me?\u{0020}There's\u{0020}something\u{0020}I\u{0020}can\u{0020}only\u{0020}tell\u{0020}you\u{0020}there.\u{0020}Eh?\u{0020}What\u{0020}words?\u{0020}Um,\u{0020}I\u{0020}can't\u{0020}say\u{0020}them\u{0020}right\u{0020}now!", "ナビゲーター……戦争が終わったら、ある場所に一緒に行っていただけませんか？そこでしか話せないことがあって。え？何の話って……ま、まだ内緒です！", "領航……戰爭結束了之後，您能和我一起去一個地方嗎？有些話，只有在那裡才能告訴領航。欸？什麼話……嗚，現在還不能說！", "0", "领航……战争结束了之后，您能和我一起去一个地方吗？有些话，只有在那里才能告诉领航。诶？什么话……呜，现在还不能说！", "0", "cv_kuriyama_29", "0", "0"},
[410407] = {410407, 11004, 8, 5, "1_》_0_0.8", "level1", "Eh?\u{0020}You\u{0020}want\u{0020}to\u{0020}go\u{0020}out\u{0020}with\u{0020}me\u{0020}this\u{0020}weekend?\u{0020}But...\u{0020}My\u{0020}body...\u{0020}Everyone\u{0020}might\u{0020}be\u{0020}scared...", "え？週末は私と一緒に出掛けたい、ですか？でも……私の身体が…...それに、一緒にいると……あなたまで怖がられてしまいますよ。", "欸？週末想要和我一起出去玩？但是…我的身體……大家會害怕的……", "0", "哎？周末想要和我一起出去玩？但是…我的身体……大家会害怕的……", "0", "cv_kuriyama_5", "0", "0"},
[410408] = {410408, 11004, 9, 5, "1_》_100_1.5", "level2", "This\u{0020}is...\u{0020}a\u{0020}kindergarten?\u{0020}So,\u{0020}we'll\u{0020}be\u{0020}volunteering\u{0020}to\u{0020}play\u{0020}with\u{0020}the\u{0020}children?\u{0020}But\u{0020}won't\u{0020}they\u{0020}be\u{0020}scared\u{0020}of\u{0020}me?", "ここは……幼稚園ですか？なるほど、出掛けるとはボランティアのことだったのですね。でも、私の身体を見たら……子供たちは本当に大丈夫でしょうか？怖くないのでしょうか…...？", "這裡是……幼稚園？原來如此，一起出去玩的意思是做義工啊。但是我的身體真的不會嚇到孩子們嗎？", "0", "这里是……幼儿园？原来如此，一起出去玩的意思是做义工啊。但是我的身体真的不会吓到孩子们吗？", "0", "cv_kuriyama_6", "0", "0"},
[410409] = {410409, 11004, 10, 5, "1_》_500_2", "level3", "Coming...\u{0020}coming\u{0020}right\u{0020}away!\u{0020}My\u{0020}sister\u{0020}can\u{0020}lift\u{0020}3\u{0020}buckets\u{0020}of\u{0020}water\u{0020}at\u{0020}once!\u{0020}Eh?\u{0020}Navigator?!\u{0020}No...\u{0020}I'm\u{0020}sorry.\u{0020}I\u{0020}accidentally\u{0020}bonded\u{0020}with\u{0020}the\u{0020}kids.", "す、すぐに来るから！お姉さんはバケツを三つも持てるのよ！えっ？ナビゲーター？！す、すみません……子供たちがなついてくれて……", "馬……馬上就來！姐姐的手臂一次性能拎起3桶水呢！欸？是領航嗎？！不……不好意思，不經意間就和孩子們打成一片了。", "0", "马……马上就来！姐姐的手臂一次性能拎起3桶水呢！哎？是领航吗？！不……不好意思，不经意间就和孩子们打成一片了。", "0", "cv_kuriyama_7", "0", "0"},
[410410] = {410410, 11004, 11, 5, "1_》_1000_2.5", "level4", "Ugly\u{0020}is\u{0020}ugly.\u{0020}My\u{0020}body\u{0020}can't\u{0020}be\u{0020}called\u{0020}beautiful.\u{0020}I\u{0020}struggled\u{0020}with\u{0020}that\u{0020}for\u{0020}a\u{0020}long\u{0020}time.\u{0020}But\u{0020}because\u{0020}of\u{0020}you,\u{0020}I'm\u{0020}slowly\u{0020}starting\u{0020}to\u{0020}accept\u{0020}myself.", "醜いものは醜いです。私の身体、綺麗とは言い難いでしょう。今まではこの体の事でずっと悩んでいて、落ち込んでいました。でも、あなた様のお陰で、これからはありのままの自分を受け入れられるような気がします。", "醜陋的就是醜陋的，無論如何我的身體都無法被稱之為美麗的。曾經我也因為這種事情而痛苦過，失落過。但是因為您的緣故，我想我也會開始慢慢接受這樣的自己了吧。", "0", "丑陋的就是丑陋的，无论如何我的身体都无法被称之为美丽的。曾经我也因为这种事情而痛苦过，失落过。但是因为您的缘故，我想我也会开始慢慢接受这样的自己了吧。", "0", "cv_kuriyama_8", "0", "0"},
[410411] = {410411, 11004, 12, 6, "0", "0", "Thank\u{0020}you!\u{0020}I\u{0020}will\u{0020}cherish\u{0020}it.", "ありがとうございます。大事にします。", "謝謝，我會好好珍惜的。", "0", "谢谢，我会好好珍惜的。", "0", "cv_kuriyama_9", "0", "0"},
[410412] = {410412, 11004, 13, 7, "0", "0", "Is\u{0020}this\u{0020}a\u{0020}new\u{0020}prosthetic\u{0020}limb?", "新しい義肢ですか？", "是新的義肢嗎？", "0", "是新的义肢吗？", "0", "cv_kuriyama_10", "0", "0"},
[410413] = {410413, 11004, 14, 8, "0", "0", "You're\u{0020}accepting\u{0020}me\u{0020}like\u{0020}this\u{0020}and\u{0020}training\u{0020}me\u{0020}to\u{0020}this\u{0020}extent...\u{0020}Um!\u{0020}Please\u{0020}rest\u{0020}assured,\u{0020}I\u{0020}won't\u{0020}disappoint\u{0020}your\u{0020}expectations!", "こんな私を受け入れて、そしてここまで育ててくれて……はい！ご安心ください。絶対に、あなた様の期待を裏切りません！", "接受這樣的我，將我培養到這種程度……嗯！還請放心吧，我絕對不會辜負您的期待！", "0", "接受这样的我，将我培养到这种程度……嗯！还请放心吧，我绝对不会辜负您的期待！", "0", "cv_kuriyama_11", "0", "0"},
[410414] = {410414, 11004, 15, 9, "0", "0", "Wait!\u{0020}Navigator!\u{0020}My\u{0020}arm\u{0020}is\u{0020}getting\u{0020}hot!", "これは……ナビゲーター！腕が熱くなっています！", "這是……領航！我的手臂在發熱啊！", "0", "这是……领航！我的手臂在发热啊！", "0", "cv_kuriyama_12", "0", "0"},
