[410416] = {410416, 11004, 17, 11, "0", "0", "Great,\u{0020}we\u{0020}made\u{0020}it!", "良かった、やりましたね！", "太好了，我們做到了！", "0", "太好了，我们做到了！", "0", "cv_kuriyama_14", "0", "0"},
[410417] = {410417, 11004, 18, 12, "0", "0", "The\u{0020}battle\u{0020}is\u{0020}over.\u{0020}Are\u{0020}you\u{0020}alright,\u{0020}Navigator?", "戦闘終了です！お怪我はないですか？ナビゲーター。", "戰鬥結束，您沒有受傷吧？領航。", "0", "战斗结束，您没有受伤吧？领航。", "0", "cv_kuriyama_15", "0", "0"},
[410418] = {410418, 11004, 19, 13, "0", "0", "Um...\u{0020}Which\u{0020}component\u{0020}has\u{0020}gone\u{0020}wrong?", "うーん……一体、どの部品に問題があったのでしょう……？", "嗯……究竟是哪個部件出問題了呢？", "0", "嗯……究竟是哪个部件出问题了呢？", "0", "cv_kuriyama_16", "0", "0"},
