[410427] = {410427, 11004, 31, 23, "0", "0", "It\u{0020}shouldn't\u{0020}be\u{0020}misinterpreted.", "間違えたり、しませんよね。", "應該不會認錯吧。", "0", "应该不会认错吧。", "0", "cv_kuriyama_25", "0", "0"},
[410428] = {410428, 11004, 32, 24, "0", "0", "You've\u{0020}worked\u{0020}hard.\u{0020}Can\u{0020}I\u{0020}scrub\u{0020}your\u{0020}back\u{0020}next\u{0020}time?", "お疲れ様です。今度は私が背中を流してあげましょうか？", "辛苦了，下次讓我幫您搓背吧？", "0", "辛苦了，下次让我帮您搓背吧？", "0", "cv_kuriyama_26", "0", "0"},
[410429] = {410429, 11004, 33, 25, "0", "0", "Um...\u{0020}You\u{0020}did\u{0020}that\u{0020}on\u{0020}purpose,\u{0020}didn't\u{0020}you?", "うーん……わざとですか……？", "嗯……您是故意的吧。", "0", "嗯……您是故意的吧。", "0", "cv_kuriyama_27", "0", "0"},
[410430] = {410430, 11004, 34, 26, "0", "0", "Navigator,\u{0020}you're\u{0020}back.\u{0020}Please\u{0020}give\u{0020}the\u{0020}order\u{0020}for\u{0020}today.", "お帰りなさい、ナビゲーター。今日も、ご指示をお願いしますね。", "領航，您回來了，今天也請您下達指示吧。", "0", "领航，您回来了，今天也请您下达指示吧。", "0", "cv_kuriyama_30", "0", "0"},
[410431] = {410431, 11004, 35, 27, "0", "0", "As\u{0020}long\u{0020}as\u{0020}I'm\u{0020}with\u{0020}you,\u{0020}I\u{0020}can\u{0020}handle\u{0020}anything.\u{0020}Please\u{0020}keep\u{0020}leading\u{0020}us\u{0020}forward,\u{0020}Navigator.", "ナビゲーターと一緒なら、私、何だってできます。ナビゲーター、どうか私たちを率いて前に進み続けて下さい。", "只要和領航在一起，我什麼都能做到。領航，請繼續帶領我們前進吧。", "0", "只要和领航在一起，我什么都能做到。领航，请继续带领我们前进吧。", "0", "cv_kuriyama_32", "0", "0"},
[410432] = {410432, 11004, 36, 28, "0", "0", "Today,\u{0020}I'll\u{0020}work\u{0020}hard\u{0020}alongside\u{0020}you.", "今日も、ナビゲーターと一緒に頑張ります。", "今天我也會和領航一起努力的。", "0", "今天我也会和领航一起努力的。", "0", "cv_kuriyama_33", "0", "0"},
[410433] = {410433, 11004, 37, 29, "0", "0", "It's\u{0020}important\u{0020}to\u{0020}communicate\u{0020}more\u{0020}with\u{0020}the\u{0020}rest\u{0020}of\u{0020}the\u{0020}team,\u{0020}Navigator.", "チームの他の人とも交流を深めましょう、ナビゲーター。", "也要多和隊伍裡的其他人交流呢，領航。", "0", "也要多和队伍里的其他人交流呢，领航。", "0", "cv_kuriyama_34", "0", "0"},
[410434] = {410434, 11004, 38, 30, "0", "0", "Are\u{0020}we\u{0020}getting\u{0020}new\u{0020}companions?", "新しい仲間が来るのですか？", "要有新的同伴來了嗎？", "0", "要有新的同伴来了吗？", "0", "cv_kuriyama_35", "0", "0"},
[410435] = {410435, 11004, 39, 31, "0", "0", "Can\u{0020}the\u{0020}equipment\u{0020}be\u{0020}replaced?", "装備を入れ替えられるのですか？", "能夠更換裝備了嗎？", "0", "能够更换装备了吗？", "0", "cv_kuriyama_36", "0", "0"},
[410436] = {410436, 11004, 40, 32, "0", "0", "We\u{0020}need\u{0020}to\u{0020}replenish\u{0020}any\u{0020}lacking\u{0020}supplies\u{0020}in\u{0020}a\u{0020}timely\u{0020}manner,\u{0020}Navigator.", "足りない物資があったら、早めに補充しましょう、ナビゲーター。", "缺少的物資要及時補充，領航。", "0", "缺少的物资要及时补充，领航。", "0", "cv_kuriyama_37", "0", "0"},
[410437] = {410437, 11004, 41, 33, "0", "0", "You\u{0020}should\u{0020}also\u{0020}pay\u{0020}more\u{0020}attention\u{0020}to\u{0020}your\u{0020}own\u{0020}well-being.", "ナビゲーターも、ご自分の状況にはもっと気を配った方がいいですよ。", "領航也要多注意一下自己的狀況才行。", "0", "领航也要多注意一下自己的状况才行。", "0", "cv_kuriyama_38", "0", "0"},
[410438] = {410438, 11004, 42, 34, "0", "0", "Changing\u{0020}the\u{0020}settings\u{0020}can\u{0020}lead\u{0020}to\u{0020}unexpected\u{0020}effects\u{0020}in\u{0020}battles.", "設定を変更すると、戦闘中に予想外の効果をもたらしてくれるかもしれませんよ。", "變更設定，在戰鬥中也會有意想不到的效果。", "0", "变更设置，在战斗中也会有意想不到的效果。", "0", "cv_kuriyama_39", "0", "0"},
[410439] = {410439, 11004, 43, 35, "0", "0", "Have\u{0020}you\u{0020}received\u{0020}any\u{0020}new\u{0020}letters?", "新しいメールは届いていましたか？", "收到新的來信了嗎？", "0", "收到新的来信了吗？", "0", "cv_kuriyama_40", "0", "0"},
[410440] = {410440, 11004, 44, 36, "0", "0", "Communicating\u{0020}and\u{0020}sharing\u{0020}experiences\u{0020}with\u{0020}others\u{0020}is\u{0020}crucial.", "他の人と交流したり、経験談を共有したりすることも大切です。", "和其他人交流分享經驗也是很重要的。", "0", "和其他人交流分享经验也是很重要的。", "0", "cv_kuriyama_41", "0", "0"},
[410441] = {410441, 11004, 45, 37, "0", "0", "Please\u{0020}confirm\u{0020}this.", "確認してみましょう。", "請確認一下吧。", "0", "请确认一下吧。", "0", "cv_kuriyama_42", "0", "0"},
[410600] = {410600, 11006, 1, 1, "0", "0", "Haze\u{0020}reverb.\u{0020}Click~", "蒼霧残響（ハツリバーブ）～カシャッ。", "蒼霧殘響~哢嚓。", "0", "苍雾残响~咔嚓。", "0", "cv_jenny_33", "0", "0"},
[410601] = {410601, 11006, 2, 2, "0", "0", "Oh,\u{0020}this\u{0020}position\u{0020}is\u{0020}pretty\u{0020}good.\u{0020}Looks\u{0020}like\u{0020}I'll\u{0020}have\u{0020}more\u{0020}materials\u{0020}to\u{0020}shoot.\u{0020}It'd\u{0020}be\u{0020}even\u{0020}better\u{0020}if\u{0020}I\u{0020}could\u{0020}stay\u{0020}more\u{0020}concealed.", "おぉ～、ここいいね。撮影できる素材が増えるそうだよ。もうちょっと隠蔽性が高かったらなぁ。", "喔~這個位置不錯啊，看來能拍攝的素材又變多了。就是如果能再隱蔽點就好了。", "0", "噢~这个位置不错啊，看来能拍摄的素材又变多了。就是如果能再隐蔽点就好了。", "0", "cv_jenny_2", "0", "0"},
[410602] = {410602, 11006, 3, 3, "0", "0", "Yo!\u{0020}I\u{0020}heard\u{0020}some\u{0020}big\u{0020}news\u{0020}around\u{0020}here,\u{0020}so\u{0020}I\u{0020}came\u{0020}by.\u{0020}Nice\u{0020}to\u{0020}meet\u{0020}you\u{0020}for\u{0020}the\u{0020}first\u{0020}time!\u{0020}I'm\u{0020}Jenny\u{0020}Rose.", "よぉ！ここにビッグニュースがあるって聞いたんだ。俺はジェニィ・ロス。よろしくおな。", "呦~聽說這邊有大新聞俺就來了，初次見面，俺叫燕妮·羅斯。", "0", "呦~听说这边有大新闻俺就来了，初次见面，俺叫燕妮·罗斯。", "0", "cv_jenny_1", "0", "0"},
[410603] = {410603, 11006, 4, 4, "0", "idle", "Ah?\u{0020}Big\u{0020}news?\u{0020}Where\u{0020}is\u{0020}it!\u{0020}Where\u{0020}is\u{0020}it!\u{0020}The\u{0020}guy\u{0020}in\u{0020}the\u{0020}front\u{0020}who's\u{0020}in\u{0020}the\u{0020}way,\u{0020}hurry\u{0020}up\u{0020}and\u{0020}get\u{0020}out\u{0020}of\u{0020}the\u{0020}way!\u{0020}Eh,\u{0020}it's\u{0020}you?", "え？ビッグニュース？どこどこ？！ちょっと、邪魔なんだけど！退けって！あれ？あんただったんだ！", "啊？大新聞？在哪裡！在哪裡！前面礙事的傢伙，趕快閃開啊！欸，原來是你嗎？", "0", "啊？大新闻？在哪里！在哪里！前面碍事的家伙，赶快闪开啊！哎，原来是你吗？", "0", "cv_jenny_3", "0", "0"},
[410604] = {410604, 11006, 5, 4, "0", "idle", "Don't\u{0020}worry.\u{0020}I\u{0020}will\u{0020}definitely\u{0020}not\u{0020}confuse\u{0020}the\u{0020}weapon\u{0020}with\u{0020}the\u{0020}camera.\u{0020}Come,\u{0020}smile.\u{0020}Let\u{0020}me\u{0020}give\u{0020}you\u{0020}a\u{0020}shot.\u{0020}Just\u{0020}kidding~", "大丈夫、武器とカメラを間違えるはずがないだろー？ほら、笑えよ。一発射撃するから。冗談だよ、冗談。", "別擔心，俺是絕對不會把武器和相機弄混的。來，笑一個，讓俺給你來上一炮吧。開玩笑的~", "0", "别担心，俺是绝对不会把武器和相机弄混的。来，笑一个，让俺给你来上一炮吧。开玩笑的~", "0", "cv_jenny_4", "0", "0"},
[410605] = {410605, 11006, 6, 4, "0", "idle", "I've\u{0020}been\u{0020}secretly\u{0020}investigating\u{0020}Julia's\u{0020}background.\u{0020}The\u{0020}way\u{0020}she\u{0020}spends\u{0020}money\u{0020}doesn't\u{0020}seem\u{0020}like\u{0020}that\u{0020}of\u{0020}an\u{0020}ordinary\u{0020}girl...\u{0020}Of\u{0020}course,\u{0020}all\u{0020}this\u{0020}is\u{0020}done\u{0020}secretly\u{0020}and\u{0020}mustn't\u{0020}be\u{0020}discovered\u{0020}by\u{0020}her...\u{0020}Ah!\u{0020}Ju...\u{0020}Julia?!\u{0020}When\u{0020}did\u{0020}you\u{0020}run\u{0020}behind\u{0020}me?", "俺、ジュリアのバックグラウンドを密かに調査してるんだ。あいつの金の使い方を見る限り、普通の家の娘さんじゃねーんだろうが……まぁ、密かにね、密かに。絶対に気付かれちゃだめだ……あっ！ジ、ジュリア？！いつから俺の後ろに……？！", "我其實一直都在秘密調查茱莉亞的背景，那個傢伙的花錢方式可不像是個普通人家的女兒啊……當然這些都是秘密進行的，絕對不能被她發現……啊！茱……茱莉亞？！你什麼時候跑到我後面的？", "0", "我其实一直都在秘密调查茱莉亚的背景，那个家伙的花钱方式可不像是个普通人家的女儿啊……当然这些都是秘密进行的，绝对不能被她发现……啊！茱……茱莉亚？！你什么时候跑到我后面的？", "0", "cv_jenny_30", "0", "0"},
[410606] = {410606, 11006, 7, 5, "1_》_0_0.8", "level1", "When\u{0020}I\u{0020}can't\u{0020}write\u{0020}a\u{0020}good\u{0020}report,\u{0020}I\u{0020}naturally\u{0020}fall\u{0020}into\u{0020}a\u{0020}negative\u{0020}mood.\u{0020}At\u{0020}that\u{0020}time,\u{0020}I\u{0020}just\u{0020}need\u{0020}to\u{0020}swap\u{0020}the\u{0020}camera\u{0020}for\u{0020}a\u{0020}cannon\u{0020}and\u{0020}cause\u{0020}a\u{0020}commotion\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}to\u{0020}recover.", "良い記事が書けないと、落ち込んじまう。そういう時はカメラを大砲に替えて戦場で暴れれば元通りの自分に戻れるってわけ。", "寫不出好的報導的時候自然就會陷入消極情緒，這個時候只要把相機換成炮筒去戰場上大鬧一番就能緩過來了。", "0", "写不出好的报道的时候自然就会陷入消极情绪，这个时候只要把相机换成炮筒去战场上大闹一番就能缓过来了。", "0", "cv_jenny_31", "0", "0"},
[410607] = {410607, 11006, 8, 5, "1_》_0_0.8", "level1", "Oh\u{0020}ho\u{0020}ho~\u{0020}Could\u{0020}it\u{0020}be\u{0020}that\u{0020}you've\u{0020}become\u{0020}interested\u{0020}in\u{0020}photography?", "あっはは、撮影に興味が湧いてきたか？", "喔吼吼~難道說你對攝影產生興趣了嗎？", "0", "呕吼吼~难道说你对摄影产生兴趣了吗？", "0", "cv_jenny_5", "0", "0"},
[410608] = {410608, 11006, 9, 5, "1_》_100_1.5", "level2", "The\u{0020}original\u{0020}reason\u{0020}for\u{0020}becoming\u{0020}a\u{0020}Driver?\u{0020}Of\u{0020}course,\u{0020}it's\u{0020}to\u{0020}collect\u{0020}materials\u{0020}more\u{0020}conveniently.\u{0020}But...\u{0020}it\u{0020}might\u{0020}also\u{0020}be\u{0020}because\u{0020}I\u{0020}don't\u{0020}want\u{0020}to\u{0020}just\u{0020}stand\u{0020}on\u{0020}the\u{0020}sidelines.", "ドライバーになった理由？それはもちろん、素材が集めやすいからに決まってる。まぁ……ただの傍観者でいたくないっていうのもあったかもしれないな。", "成為駕駛員的初衷？當然是為了能夠更方便地收集素材啊。但是……從另一面來說，也可能是因為不想一直都在當旁觀者吧。", "0", "成为驾驶员的初衷？当然是为了能够更方便地收集素材啊。但是……从另一面来说，也可能是因为不想一直都在当旁观者吧。", "0", "cv_jenny_6", "0", "0"},
[410609] = {410609, 11006, 10, 5, "1_》_500_2", "level3", "Whether\u{0020}it's\u{0020}a\u{0020}happy\u{0020}moment\u{0020}or\u{0020}a\u{0020}sad\u{0020}one,\u{0020}as\u{0020}long\u{0020}as\u{0020}it\u{0020}can\u{0020}inspire\u{0020}others,\u{0020}I'll\u{0020}record\u{0020}it.\u{0020}But\u{0020}for\u{0020}me,\u{0020}the\u{0020}most\u{0020}important\u{0020}thing\u{0020}is\u{0020}still\u{0020}the\u{0020}moments\u{0020}with\u{0020}my\u{0020}partners.", "楽しい瞬間も悲しい瞬間も、人を励ませる素材があれば、俺は全部記録する。でも、俺にとって、一番重要なのはやっぱり仲間たちと一緒にいる瞬間なんだ。", "無論是開心的瞬間，還是悲傷的瞬間，只要是能激勵他人的素材俺都會記錄下來。但是對我而言，最重要的還是和夥伴們在一起的瞬間。", "0", "无论是开心的瞬间，还是悲伤的瞬间，只要是能激励他人的素材俺都会记录下来。但是对我而言，最重要的还是和伙伴们在一起的瞬间。", "0", "cv_jenny_7", "0", "0"},
[410610] = {410610, 11006, 11, 5, "1_》_1000_2.5", "level4", "Well...\u{0020}we've\u{0020}known\u{0020}each\u{0020}other\u{0020}for\u{0020}so\u{0020}long,\u{0020}and\u{0020}it\u{0020}seems\u{0020}I\u{0020}haven't\u{0020}written\u{0020}any\u{0020}reports\u{0020}about\u{0020}you.\u{0020}Actually,\u{0020}I\u{0020}secretly\u{0020}tried\u{0020}to\u{0020}write\u{0020}one.\u{0020}Here,\u{0020}this\u{0020}is\u{0020}the\u{0020}first\u{0020}draft.\u{0020}Open\u{0020}it\u{0020}somewhere\u{0020}private.", "あのさ……あんたと知り合ってから随分経つんだけど、俺、あんたに関する報道は一つもしてない。実はこっそり記事を書いてみたんだが……ほら、これが初稿だ。読むなら人のいない所で！", "那個……和你認識了這麼久俺好像都沒有出過和你有關的報導呢。其實私底下俺也試著寫過啦。喏，這就是初稿，要記得拿到沒人的地方再拆開喔。", "0", "那个……和你认识了这么久俺好像都没有出过和你有关的报道呢。其实私底下俺也试着写过啦。喏，这就是初稿，要记得拿到没人的地方再拆开哦。", "0", "cv_jenny_8", "0", "0"},
[410611] = {410611, 11006, 12, 6, "0", "0", "What\u{0020}fantastic\u{0020}material!", "なかなか良い素材だった。", "真是不錯的素材啊~", "0", "真是不错的素材啊~", "0", "cv_jenny_9", "0", "0"},
[410612] = {410612, 11006, 13, 7, "0", "0", "Wow,\u{0020}wow,\u{0020}wow!\u{0020}With\u{0020}this,\u{0020}I\u{0020}can\u{0020}capture\u{0020}even\u{0020}better\u{0020}photos!", "おぉぉ！これならもっと良い写真が撮れる！", "喔喔喔！這樣一來俺就能拍出更棒的照片了！", "0", "噢噢噢！这样一来俺就能拍出更棒的照片了！", "0", "cv_jenny_10", "0", "0"},
[410613] = {410613, 11006, 14, 8, "0", "0", "Whether\u{0020}it's\u{0020}combat,\u{0020}photography,\u{0020}or\u{0020}writing\u{0020}reports,\u{0020}everything\u{0020}has\u{0020}reached\u{0020}a\u{0020}new\u{0020}height.\u{0020}Thank\u{0020}you\u{0020}so\u{0020}much!", "戦闘も撮影も記事も、新しいレベルに到達できた！マジありがとう！", "無論是戰鬥，攝影，還是撰寫報導的水準都已經到達新的高度了，非常感謝！", "0", "无论是战斗，摄影，还是撰写报道的水平都已经到达新的高度了，非常感谢！", "0", "cv_jenny_11", "0", "0"},
[410614] = {410614, 11006, 15, 9, "0", "0", "Mmm,\u{0020}this\u{0020}moment\u{0020}needs\u{0020}to\u{0020}be\u{0020}captured\u{0020}perfectly.", "うん、この瞬間、ちゃんと記録しとかないと。", "嗯嗯，這個瞬間可要好好地記錄下來呢。", "0", "嗯嗯，这个瞬间可要好好地记录下来呢。", "0", "cv_jenny_12", "0", "0"},
[410615] = {410615, 11006, 16, 10, "0", "0", "Let\u{0020}me\u{0020}record\u{0020}this\u{0020}moment\u{0020}of\u{0020}victory.", "この勝利の瞬間を記録させてもらうよ。", "讓俺記錄下勝利的瞬間吧。", "0", "让俺记录下胜利的瞬间吧。", "0", "cv_jenny_13", "0", "0"},
[410616] = {410616, 11006, 17, 11, "0", "0", "Perfect!\u{0020}This\u{0020}video\u{0020}will\u{0020}surely\u{0020}inspire\u{0020}everyone.", "完璧だ！このビデオはきっと、みんなに希望をもたらすよ。", "完美！這段錄影一定會給大家帶來希望吧。", "0", "完美！这段录像一定会给大家带来希望吧。", "0", "cv_jenny_14", "0", "0"},
[410617] = {410617, 11006, 18, 12, "0", "0", "Wrap\u{0020}it\u{0020}up!\u{0020}It's\u{0020}time\u{0020}to\u{0020}head\u{0020}back\u{0020}and\u{0020}write\u{0020}the\u{0020}report.", "よし、上がり～帰って記事を書こうっと。", "收工~該回去撰寫報導啦。", "0", "收工~该回去撰写报道啦。", "0", "cv_jenny_15", "0", "0"},
