[410636] = {410636, 11006, 38, 30, "0", "0", "Wow,\u{0020}wow,\u{0020}wow!\u{0020}It\u{0020}looks\u{0020}like\u{0020}the\u{0020}protagonist\u{0020}of\u{0020}the\u{0020}new\u{0020}report\u{0020}is\u{0020}about\u{0020}to\u{0020}make\u{0020}an\u{0020}appearance.", "おぉぉ、新しい記事の主人公が現れるみてーだな。", "喔喔喔，看來新報導的主人公要出現了啊。", "0", "哦哦哦，看来新报道的主人公要出现了啊。", "0", "cv_jenny_37", "0", "0"},
[410637] = {410637, 11006, 39, 31, "0", "0", "I\u{0020}hope\u{0020}we\u{0020}can\u{0020}order\u{0020}some\u{0020}new-style\u{0020}equipment.", "新しい装備を購入できるといいな。", "希望能訂到新式的裝備吧。", "0", "希望能订到新式的装备吧。", "0", "cv_jenny_38", "0", "0"},
