[410901] = {410901, 11009, 2, 2, "0", "0", "I\u{0020}don't\u{0020}quite\u{0020}get\u{0020}your\u{0020}meaning...\u{0020}But\u{0020}as\u{0020}long\u{0020}as\u{0020}I\u{0020}stand\u{0020}here,\u{0020}is\u{0020}it\u{0020}okay?", "言ってる意味がよく分からないけど……ここに立てばいいの？", "我不太明白您的意思……不過只要站在這裡就可以了嗎？", "0", "我不太明白您的意思……不过只要站在这里就可以了吗？", "0", "cv_borinna_2", "0", "0"},
[410902] = {410902, 11009, 3, 3, "0", "0", "I'm\u{0020}Bolina...\u{0020}Uh,\u{0020}Bolina\u{0020}I.\u{0020}Rovsky.", "私はボーリンナ……えっと……ボーリンナ・イ・ロフスキー。", "我是波琳娜……呃……波琳娜•伊•羅夫斯基。", "0", "我是波琳娜……呃……波琳娜•伊•罗夫斯基。", "0", "cv_borinna_1", "0", "0"},
[410903] = {410903, 11009, 4, 4, "0", "idle", "Navigator!\u{0020}...Nothing?\u{0020}I\u{0020}just\u{0020}wanted\u{0020}to\u{0020}call\u{0020}out\u{0020}to\u{0020}you...", "……ナビゲーター！……ううん。ただ呼びたくって……", "……領航！……沒什麼？只是想叫叫您了……", "0", "……领航！……没什么？只是想叫叫您了……", "0", "cv_borinna_3", "0", "0"},
[410904] = {410904, 11009, 5, 4, "0", "idle", "On\u{0020}the\u{0020}battlefield,\u{0020}Iliya\u{0020}always\u{0020}told\u{0020}me\u{0020}not\u{0020}to\u{0020}be\u{0020}nervous...\u{0020}But\u{0020}it's\u{0020}really\u{0020}terrifying...", "戦場では、よくイリアから緊張しないでって言われてるけど……でも……本当に凄く、怖い……", "在戰場，伊莉雅經常讓我不要緊張……但是……真的好可怕……", "0", "在战场，伊莉雅经常让我不要紧张……但是……真的好可怕……", "0", "cv_borinna_4", "0", "0"},
[410905] = {410905, 11009, 6, 4, "0", "idle", "Before\u{0020}I\u{0020}met\u{0020}the\u{0020}Navigator,\u{0020}Captain\u{0020}Iliya\u{0020}always\u{0020}took\u{0020}care\u{0020}of\u{0020}me.\u{0020}In\u{0020}my\u{0020}world,\u{0020}Captain\u{0020}Iliya\u{0020}is\u{0020}the\u{0020}best\u{0020}person.", "ナビゲーターに出会うまではずっとイリア隊長が世話をしてくれてたの。この世界で一番よくしてくれる人はイリア隊長なの。", "在和領航相遇前，一直都是伊莉雅隊長在照顧我喔~在這個世界上，對波琳娜最好的人就是伊莉雅隊長了！", "0", "在和领航相遇前，一直都是伊莉雅队长在照顾我哦~在这个世界上，对波琳娜最好的人就是伊莉雅队长了！", "0", "cv_borinna_29", "0", "0"},
[410906] = {410906, 11009, 7, 5, "1_》_0_0.8", "level1", "I\u{0020}want\u{0020}lots\u{0020}of\u{0020}candies~\u{0020}A\u{0020}warm\u{0020}house\u{0020}and\u{0020}a\u{0020}big\u{0020}bed\u{0020}where\u{0020}everyone\u{0020}can\u{0020}sleep\u{0020}together!", "ボーリンナ、沢山のキャンディーが欲しいの。暖かい家と、みんなが一緒に寝れる、大きなベッドも。", "波琳娜想要好多好多的糖~溫暖的房子，能讓大家都睡在一起的大床~", "0", "波琳娜想要好多好多的糖~温暖的房子，能让大家都睡在一起的大床~", "0", "cv_borinna_30", "0", "0"},
[410907] = {410907, 11009, 8, 5, "1_》_0_0.8", "level1", "Is\u{0020}the\u{0020}Navigator\u{0020}going\u{0020}to\u{0020}be\u{0020}our\u{0020}boss\u{0020}now?\u{0020}You\u{0020}won't\u{0020}starve\u{0020}us\u{0020}like\u{0020}those\u{0020}annoying\u{0020}adults,\u{0020}will\u{0020}you?", "これから、ナビゲーターがボーリングたちのボスになるの？…...あの嫌な大人たちみたいに、ご飯を食べさせてくれないの？", "領航以後就是我們的老闆了嗎？會像那些討厭的大人一樣不給我們東西吃嗎？", "0", "领航以后就是我们的老板了吗？会像那些讨厌的大人一样不给我们东西吃吗？", "0", "cv_borinna_5", "0", "0"},
[410908] = {410908, 11009, 9, 5, "1_》_100_1.5", "level2", "Parents?\u{0020}I've\u{0020}never\u{0020}met\u{0020}mine,\u{0020}but\u{0020}Iliya\u{0020}is\u{0020}so\u{0020}kind.\u{0020}She's\u{0020}like\u{0020}a\u{0020}mother!", "両親？ボーリンナ、自分の両親には会ったことないの。でも、イリアには凄く親切にしてもらってる。まるでお母さんみたい。", "父母？波琳娜沒有見過自己的父母喔。不過，伊莉雅對我可好了，就像母親一樣呢！", "0", "父母？波琳娜没有见过自己的父母喔。不过，伊莉雅对我可好了，就像母亲一样呢！", "0", "cv_borinna_6", "0", "0"},
[410909] = {410909, 11009, 10, 5, "1_》_500_2", "level3", "I've\u{0020}been\u{0020}fighting\u{0020}so\u{0020}hard.\u{0020}Why\u{0020}do\u{0020}people\u{0020}always\u{0020}blame\u{0020}us?\u{0020}Wuu,\u{0020}it'd\u{0020}be\u{0020}nice\u{0020}if\u{0020}everyone\u{0020}was\u{0020}as\u{0020}kind\u{0020}as\u{0020}the\u{0020}Navigator.", "ずっと頑張って戦ってるのに、なんでいつもあの人たちに責められなきゃいけないの……うっ……みんな、ナビゲーターみたいにいい人だったらいいのに。", "我明明一直都在努力戰鬥，為什麼那些人總是責怪我們呢……嗚，要是大家都像領航一樣是個大好人就好了！", "0", "我明明一直都在努力战斗，为什么那些人总是责怪我们呢……呜，要是大家都像领航一样是个大好人就好了！", "0", "cv_borinna_7", "0", "0"},
[410910] = {410910, 11009, 11, 5, "1_》_1000_2.5", "level4", "Lately,\u{0020}whenever\u{0020}I\u{0020}see\u{0020}the\u{0020}you,\u{0020}I\u{0020}get\u{0020}this\u{0020}strange\u{0020}feeling...\u{0020}I\u{0020}want\u{0020}to\u{0020}stay\u{0020}by\u{0020}your\u{0020}side\u{0020}all\u{0020}the\u{0020}time.\u{0020}Is\u{0020}that\u{0020}weird?", "ボーリンナは最近、ナビゲーターを見るとなんか変な気持ちになるの……ずっとナビゲーターのそばにいたい…...って気持ち、……変かな？", "波琳娜最近看到領航，都有一種怪怪的感覺……想要一直陪伴在領航身邊，是這樣的感覺……是不是很奇怪？", "0", "波琳娜最近看到领航，都有一种怪怪的感觉……想要一直陪伴在领航身边，是这样的感觉……是不是很奇怪？", "0", "cv_borinna_8", "0", "0"},
[410911] = {410911, 11009, 12, 6, "0", "0", "I\u{0020}need\u{0020}to\u{0020}control\u{0020}my\u{0020}power\u{0020}better.", "ボーリンナ、自分の力をちゃんとコントロールしなきゃ。", "波琳娜要控制好自己的力量~", "0", "波琳娜要控制好自己的力量~", "0", "cv_borinna_9", "0", "0"},
[410912] = {410912, 11009, 13, 7, "0", "0", "Power...\u{0020}has\u{0020}increased.", "力が……増したの。", "力量……增加了。", "0", "力量……增加了。", "0", "cv_borinna_10", "0", "0"},
[410913] = {410913, 11009, 14, 8, "0", "0", "Only\u{0020}the\u{0020}Navigator\u{0020}doesn't\u{0020}mind\u{0020}my\u{0020}power.\u{0020}For\u{0020}you,\u{0020}I'll\u{0020}control\u{0020}it\u{0020}well\u{0020}and\u{0020}not\u{0020}cause\u{0020}trouble\u{0020}for\u{0020}everyone!", "ボーリンナの力のことを気にしないのは、ナビゲーターくらいだよ……ナビゲーターのために、自分の力をちゃんとコントロールできるよう、みんなに迷惑をかけないように、努力する。", "只有領航才會像這樣不介意波琳娜的力量……為了領航，我會好好控制自己的力量，不給大家添麻煩的！", "0", "只有领航才会像这样不介意波琳娜的力量……为了领航，我会好好控制自己的力量，不给大家添麻烦的！", "0", "cv_borinna_11", "0", "0"},
[410914] = {410914, 11009, 15, 9, "0", "0", "Bolina's\u{0020}weapon\u{0020}has\u{0020}become\u{0020}stronger!", "ボーリンナの武器がもっと凄くなった。", "波琳娜的武器變得更厲害了！", "0", "波琳娜的武器变得更厉害了！", "0", "cv_borinna_12", "0", "0"},
[410915] = {410915, 11009, 16, 10, "0", "0", "Fight\u{0020}carefully...\u{0020}Um!", "気を付けながら戦うこと……ふむ……", "要小心翼翼地戰鬥……嗯！", "0", "要小心翼翼地战斗……嗯！", "0", "cv_borinna_13", "0", "0"},
[410916] = {410916, 11009, 17, 11, "0", "0", "The\u{0020}enemies\u{0020}are\u{0020}annihilated,\u{0020}and\u{0020}the\u{0020}civilians\u{0020}and\u{0020}buildings\u{0020}are\u{0020}safe\u{0020}and\u{0020}sound!", "敵はもう、全部殲滅された。人も建物も無事だよ。", "敵人全部殲滅，平民和樓房也平安無事！", "0", "敌人全部歼灭，平民和楼房也平安无事！", "0", "cv_borinna_14", "0", "0"},
