[411001] = {411001, 11010, 2, 2, "0", "0", "Me…?\u{0020}Are\u{0020}you\u{0020}sure?\u{0020}I\u{0020}don't\u{0020}know\u{0020}if\u{0020}I…\u{0020}I'll\u{0020}do\u{0020}my\u{0020}best!", "わ……私？瓏、大丈夫かな？……ろ、瓏、頑張ってみる。", "我……我嗎？瓏真的能行嗎……瓏、瓏會試著努力的。", "0", "我……我吗？珑真的能行吗……珑、珑会试着努力的。", "0", "cv_long_2", "0", "0"},
[411002] = {411002, 11010, 3, 3, "0", "0", "Nice\u{0020}to\u{0020}meet\u{0020}you,\u{0020}Navigator.\u{0020}I\u{0020}will\u{0020}work\u{0020}hard,\u{0020}so\u{0020}please\u{0020}don't\u{0020}scold\u{0020}me...", "は……初めまして、ナビゲーター。瓏、頑張るから、叱らないで……", "初……初次見面，領航。瓏會努力工作的，請不要罵瓏……", "0", "初……初次见面，领航。珑会努力工作的，请不要骂珑……", "0", "cv_long_1", "0", "0"},
[411003] = {411003, 11010, 4, 4, "0", "idle", "I\u{0020}often\u{0020}run\u{0020}away\u{0020}from\u{0020}the\u{0020}battlefield\u{0020}out\u{0020}of\u{0020}fear.\u{0020}Thanks\u{0020}to\u{0020}everyone\u{0020}in\u{0020}the\u{0020}team,\u{0020}I\u{0020}was\u{0020}spared\u{0020}punishment.\u{0020}It's\u{0020}wrong,\u{0020}but\u{0020}I'm\u{0020}just\u{0020}so\u{0020}scared,\u{0020}what\u{0020}should\u{0020}I\u{0020}do?", "瓏は……怖いから戦場から逃げてばかりなの。だけど、チームのみんなのお陰で、ペナルティを免れたの。こんなの、良くない。でも、本当に凄く怖いの。どうすればいいのかな？", "瓏……常常因為害怕而從戰場上逃走。多虧了隊伍裡的大家，瓏才能免受責罰。這樣是不對的，可是瓏真的很怕，該怎麼辦才好呢？", "0", "珑……常常因为害怕而从战场上逃走。多亏了队伍里的大家，珑才能免受责罚。这样是不对的，可是珑真的很怕，该怎么办才好呢？", "0", "cv_long_3", "0", "0"},
[411004] = {411004, 11010, 5, 4, "0", "idle", "I\u{0020}am\u{0020}weak...\u{0020}and\u{0020}very\u{0020}timid.\u{0020}Can\u{0020}someone\u{0020}like\u{0020}me\u{0020}really\u{0020}earn\u{0020}the\u{0020}Navigator's\u{0020}trust?\u{0020}...But,\u{0020}but!\u{0020}I\u{0020}will\u{0020}try\u{0020}my\u{0020}best,\u{0020}please\u{0020}don't\u{0020}leave\u{0020}me\u{0020}by\u{0020}myself...", "瓏は弱くて……臆病なの。こんな瓏でも、本当にナビゲーターに信頼してもらえるの？……で、でも！瓏、頑張るから！だから、一人にしないで……", "瓏很弱……還很膽小，這樣的我，真的能夠得到領航的信任嗎？……但，但是！瓏會加油的，請不要丟下瓏一個人……", "0", "珑很弱……还很胆小，这样的我，真的能够得到领航的信任吗？……但，但是！珑会加油的，请不要丢下珑一个人……", "0", "cv_long_4", "0", "0"},
[411005] = {411005, 11010, 6, 4, "0", "idle", "It's\u{0020}always\u{0020}been\u{0020}Miss\u{0020}Mizo\u{0020}protecting\u{0020}me...\u{0020}I\u{0020}can't\u{0020}run\u{0020}away\u{0020}anymore.\u{0020}I\u{0020}must\u{0020}get\u{0020}stronger\u{0020}for\u{0020}Miss\u{0020}Mizo.", "瓏、今まではずっと渠さんに守られてて……これ以上は逃げちゃだめ。瓏、渠さんのために強くならなきゃ。", "一直以來，都是渠小姐在保護著瓏……瓏不能再逃了，要為了渠小姐變強才行。", "0", "一直以来，都是渠小姐在保护着珑……珑不能再逃了，要为了渠小姐变强才行。", "0", "cv_long_28", "0", "0"},
[411006] = {411006, 11010, 7, 5, "1_》_0_0.8", "level1", "Honestly,\u{0020}I\u{0020}don't\u{0020}want\u{0020}to\u{0020}fight\u{0020}at\u{0020}all.\u{0020}But\u{0020}my\u{0020}homeland\u{0020}is\u{0020}gone,\u{0020}so\u{0020}this\u{0020}is\u{0020}my\u{0020}only\u{0020}home.\u{0020}I\u{0020}don't\u{0020}want\u{0020}to\u{0020}lose\u{0020}it\u{0020}again!", "瓏、本当は戦いたくないの。でも、瓏の故郷はもう、ない。だから、ここが瓏の唯一の居場所なの。瓏、この場所を失いたくない！", "瓏……其實一點也不想戰鬥。但是瓏的家鄉已經沒了，所以，這裡是瓏唯一的歸宿。瓏不想再失去它了！", "0", "珑……其实一点也不想战斗。但是珑的家乡已经没了，所以，这里是珑唯一的归宿。珑不想再失去它了！", "0", "cv_long_29", "0", "0"},
[411007] = {411007, 11010, 8, 5, "1_》_0_0.8", "level1", "Ahh!\u{0020}Navigator,\u{0020}please\u{0020}don't\u{0020}scare\u{0020}me...", "うわぁ！ナビゲーター！驚かさないでよ……", "嗚哇！領航，請不要嚇我呀……", "0", "呜哇！领航，请不要吓我呀……", "0", "cv_long_5", "0", "0"},
[411008] = {411008, 11010, 9, 5, "1_》_100_1.5", "level2", "Navigator...\u{0020}do\u{0020}you\u{0020}like\u{0020}my\u{0020}ears?\u{0020}That's\u{0020}great,\u{0020}hehe.", "ナビゲーター……瓏の耳が好きなの？よかった、えへへ。", "領航……很喜歡瓏的耳朵嗎？太好了，嘻嘻。", "0", "领航……很喜欢珑的耳朵吗？太好了，嘻嘻。", "0", "cv_long_6", "0", "0"},
[411009] = {411009, 11010, 10, 5, "1_》_500_2", "level3", "Why?\u{0020}Why\u{0020}does\u{0020}the\u{0020}Navigator\u{0020}always\u{0020}only\u{0020}sync\u{0020}with\u{0020}Miss\u{0020}Mizo?\u{0020}Is\u{0020}it\u{0020}because\u{0020}I'm\u{0020}too\u{0020}weak?", "なんで？なんで？ナビゲーターさんは渠さんばかりと通感覚して……瓏が弱すぎるから……？", "為什麼？為什麼？領航每次都只會跟渠小姐進行通感，是因為瓏太弱了嗎？", "0", "为什么？为什么？领航每次都只会跟渠小姐进行通感，是因为珑太弱了吗？", "0", "cv_long_7", "0", "0"},
[411010] = {411010, 11010, 11, 5, "1_》_1000_2.5", "level4", "The\u{0020}Navigator's\u{0020}hand\u{0020}is\u{0020}warm...\u{0020}just\u{0020}like\u{0020}my\u{0020}parents'.\u{0020}Navigator,\u{0020}please\u{0020}don't\u{0020}leave\u{0020}me,\u{0020}okay?\u{0020}I\u{0020}will\u{0020}always\u{0020}stay\u{0020}by\u{0020}your\u{0020}side,\u{0020}no\u{0020}matter\u{0020}when\u{0020}or\u{0020}where.", "ナビゲーターの手、とても温かい……何だかお父さんとお母さんみたい……ナビゲーター、瓏を一人にしないで、ね？瓏も、ずっとナビゲーターのそばにいる。いつまでもどこまでも。", "領航的手，很溫暖……就像爸爸和媽媽一樣。領航，請不要丟下瓏一個人，好嗎？瓏也會一直陪在領航身邊的。無論何時，無論何地。", "0", "领航的手，很温暖……就像爸爸和妈妈一样。领航，请不要丢下珑一个人，好吗？珑也会一直陪在领航身边的。无论何时，无论何地。", "0", "cv_long_8", "0", "0"},
[411011] = {411011, 11010, 12, 6, "0", "0", "Have\u{0020}I\u{0020}really\u{0020}gotten\u{0020}stronger...\u{0020}That's\u{0020}great…", "瓏、本当に強くなったの……？よかった……", "瓏真的變強了嗎……太好了……", "0", "珑真的变强了吗……太好了……", "0", "cv_long_9", "0", "0"},
[411012] = {411012, 11010, 13, 7, "0", "0", "I\u{0020}will\u{0020}work\u{0020}hard\u{0020}not\u{0020}to\u{0020}run\u{0020}away!", "瓏、逃げないように頑張るから！", "瓏會努力不逃跑的！", "0", "珑会努力不逃跑的！", "0", "cv_long_10", "0", "0"},
[411013] = {411013, 11010, 14, 8, "0", "0", "Navigator!\u{0020}Recently,\u{0020}I\u{0020}learned\u{0020}the\u{0020}\"Eta\u{0020}Colored\u{0020}Glaze\u{0020}Sword\u{0020}Technique,\"\u{0020}and\u{0020}I\u{0020}want\u{0020}to\u{0020}show\u{0020}you!\u{0020}Ha!\u{0020}...Eh?\u{0020}Where\u{0020}is\u{0020}the\u{0020}Navigator?\u{0020}How\u{0020}did\u{0020}you\u{0020}get\u{0020}on\u{0020}the\u{0020}ceiling?", "ナ……ナビゲーター！最近ね、瓏、「アイター星瑠璃刀法」を習ったの！ちょっとやってみせるね！はっ！……え？ナビゲーター？あっ！なんで天井に……？", "領……領航！最近瓏學習了一套“埃塔星琉璃刀法”，我想示範一下給你看看？喝！……欸？領航呢？咦？你怎麼到天花板上了？", "0", "领……领航！最近珑学习了一套“埃塔星琉璃刀法”，我想示范一下给你看看？喝！……唉？领航呢？咦？你怎么到天花板上了？", "0", "cv_long_11", "0", "0"},
[411014] = {411014, 11010, 15, 9, "0", "0", "Even\u{0020}though\u{0020}I've\u{0020}gotten\u{0020}stronger,\u{0020}it\u{0020}seems\u{0020}I'm\u{0020}still\u{0020}not\u{0020}good\u{0020}enough...", "強くなったけど……やっぱダメだよね……", "雖然變強了，但瓏果然還是不行的吧……", "0", "虽然变强了，但珑果然还是不行的吧……", "0", "cv_long_12", "0", "0"},
[411015] = {411015, 11010, 16, 10, "0", "0", "Please\u{0020}don't\u{0020}let\u{0020}me\u{0020}fight\u{0020}alone,\u{0020}wah!", "出陣、一人にしないで！う……！", "請不要讓我一個人出戰，嗚！", "0", "请不要让我一个人出战，呜！", "0", "cv_long_13", "0", "0"},
[411016] = {411016, 11010, 17, 11, "0", "0", "It\u{0020}was\u{0020}just\u{0020}a\u{0020}coincidence\u{0020}this\u{0020}time...\u{0020}but\u{0020}I\u{0020}will\u{0020}try\u{0020}even\u{0020}harder!", "偶々だよ……でも、瓏、もっと頑張るから！", "這次只是巧合而已……但是，瓏會更加努力的！", "0", "这次只是巧合而已……但是，珑会更加努力的！", "0", "cv_long_14", "0", "0"},
