[411022] = {411022, 11010, 26, 19, "0", "0", "Wah...\u{0020}don't\u{0020}leave\u{0020}me\u{0020}behind...", "ううう……う！一人にしないで……", "嗚……嗚，不要丟下我……", "0", "呜……呜，不要丢下我……", "0", "cv_long_20", "0", "0"},
[411023] = {411023, 11010, 27, 20, "0", "0", "Navigator,\u{0020}wait\u{0020}a\u{0020}moment,\u{0020}I\u{0020}want\u{0020}to\u{0020}bring\u{0020}some\u{0020}toys...\u{0020}Is\u{0020}that\u{0020}not\u{0020}allowed?", "ナビゲーター、ちょっと待って！おもちゃも一緒に……え？ダメなの？", "領航，稍等一下，我想帶點玩具……欸，不行嗎？", "0", "领航，稍等一下，我想带点玩具……诶，不行吗？", "0", "cv_long_21", "0", "0"},
[411024] = {411024, 11010, 28, 21, "0", "0", "Ah,\u{0020}Navigator!\u{0020}I\u{0020}wasn't\u{0020}playing,\u{0020}you\u{0020}must\u{0020}have\u{0020}seen\u{0020}it\u{0020}wrong.", "ぶくぶく――あっ、ナビゲーター！遊んでない！ナビゲーターの見間違いだよ。", "咕咕咕——啊，領航！我沒有在玩，一定是領航看錯了。", "0", "咕咕咕——啊，领航！我没有在玩，一定是领航看错了。", "0", "cv_long_22", "0", "0"},
[411025] = {411025, 11010, 29, 21, "0", "0", "Hot\u{0020}water...\u{0020}It\u{0020}feels\u{0020}so\u{0020}good,\u{0020}I'm\u{0020}about\u{0020}to\u{0020}fall\u{0020}asleep...", "お湯……気持ちいい～眠くなってきた。グー……グー……", "熱水……好舒服，快睡著了，呼……呼……", "0", "热水……好舒服，快睡着了，呼……呼……", "0", "cv_long_23", "0", "0"},
[411026] = {411026, 11010, 30, 22, "0", "0", "Wah?!\u{0020}What\u{0020}happened?", "うわぁ？！何があったの？", "嗚哇？！發生什麼了？", "0", "呜哇？！发生什么了？", "0", "cv_long_24", "0", "0"},
[411027] = {411027, 11010, 31, 23, "0", "0", "It\u{0020}doesn't\u{0020}matter\u{0020}if\u{0020}you\u{0020}guessed\u{0020}it\u{0020}wrong,\u{0020}I'll\u{0020}never\u{0020}leave\u{0020}you.", "外れたとしても大丈夫だよ！瓏だし……", "即使猜錯也沒有關係，因為是瓏呀……", "0", "即使猜错也没有关系，因为是珑呀……", "0", "cv_long_25", "0", "0"},
[411028] = {411028, 11010, 32, 24, "0", "0", "Navigator...\u{0020}you're\u{0020}amazing!\u{0020}You\u{0020}guessed\u{0020}it\u{0020}right!", "ナビゲーター……凄い！瓏のことが分かったなんて！", "領航……太厲害了！居然能猜出來是瓏！", "0", "领航……太厉害了！居然能猜出来是珑！", "0", "cv_long_26", "0", "0"},
[411029] = {411029, 11010, 33, 25, "0", "0", "It's\u{0020}okay,\u{0020}I\u{0020}won't\u{0020}blame\u{0020}you,\u{0020}Navigator...", "だ……大丈夫だよ。ナビゲーターのせいじゃない……う……", "沒……沒關係，瓏是不會怪領航的……嗚……", "0", "没……没关系，珑是不会怪领航的……呜……", "0", "cv_long_27", "0", "0"},
[411030] = {411030, 11010, 34, 26, "0", "0", "Navigator!\u{0020}Welcome\u{0020}back!\u{0020}I\u{0020}wasn't\u{0020}slacking\u{0020}off,\u{0020}I\u{0020}promise!", "ナ、ナビゲーター！お帰り！瓏、サボってないよ！", "領、領航！歡迎回來！瓏沒有在偷懶喔！", "0", "领、领航！欢迎回来！珑没有在偷懒哦！", "0", "cv_long_30", "0", "0"},
[411031] = {411031, 11010, 35, 27, "0", "0", "Is\u{0020}the\u{0020}battle\u{0020}starting\u{0020}again...\u{0020}I\u{0020}will\u{0020}work\u{0020}hard\u{0020}to\u{0020}complete\u{0020}the\u{0020}task!", "戦い、また始まるの？……瓏、頑張ってミッションをやり遂げるから！", "戰鬥，又要開始了嗎……瓏會努力完成任務的！", "0", "战斗，又要开始了吗……珑会努力完成任务的！", "0", "cv_long_32", "0", "0"},
[411032] = {411032, 11010, 36, 28, "0", "0", "It's\u{0020}so\u{0020}scary...\u{0020}but\u{0020}to\u{0020}get\u{0020}stronger,\u{0020}I'll\u{0020}work\u{0020}hard.", "怖い……でも、瓏、強くなるために頑張る！", "好可怕……但是為了變強，瓏會努力的。", "0", "好可怕……但是为了变强，珑会努力的。", "0", "cv_long_33", "0", "0"},
[411033] = {411033, 11010, 37, 29, "0", "0", "Everyone\u{0020}is\u{0020}so\u{0020}outstanding...", "みんな、とても優秀だよね……", "大家都很優秀呢……", "0", "大家都很优秀呢……", "0", "cv_long_34", "0", "0"},
[411034] = {411034, 11010, 38, 30, "0", "0", "Where\u{0020}is\u{0020}Miss\u{0020}Mizo?", "うう……渠さんはどこ？", "嗚嗚……渠小姐在哪？", "0", "呜呜……渠小姐在哪？", "0", "cv_long_35", "0", "0"},
[411035] = {411035, 11010, 39, 31, "0", "0", "I\u{0020}don't\u{0020}need\u{0020}equipment,\u{0020}it's\u{0020}okay...", "瓏、装備がなくてもいいよ……", "瓏不要裝備也可以喔……", "0", "珑不要装备也可以哦……", "0", "cv_long_36", "0", "0"},
[411036] = {411036, 11010, 40, 32, "0", "0", "Oh,\u{0020}so\u{0020}this\u{0020}is\u{0020}how\u{0020}you\u{0020}guys\u{0020}shop~", "うわぁ、これがナビゲーターたちの買い物の仕方なんだ。", "喔喔，這就是你們的採購方式啊~", "0", "哦哦，这就是你们的采购方式啊~", "0", "cv_long_37", "0", "0"},
[411037] = {411037, 11010, 41, 33, "0", "0", "Navigator's\u{0020}body\u{0020}is\u{0020}different\u{0020}from\u{0020}mine,\u{0020}as\u{0020}expected~", "ナビゲーターってやっぱり瓏とは違う体をしてるね。", "領航果然和瓏的身體不一樣呢~", "0", "领航果然和珑的身体不一样呢~", "0", "cv_long_38", "0", "0"},
[411038] = {411038, 11010, 42, 34, "0", "0", "Settings?\u{0020}That's\u{0020}something\u{0020}I\u{0020}don't\u{0020}understand...", "設定？う……瓏、よく分からない。", "設定？嗚……是瓏不明白的東西。", "0", "设置？呜……是珑不明白的东西。", "0", "cv_long_39", "0", "0"},
[411039] = {411039, 11010, 43, 35, "0", "0", "Is\u{0020}there\u{0020}any\u{0020}mail\u{0020}for\u{0020}me?\u{0020}Eh,\u{0020}none?", "瓏宛のメールはある？そっか、ないか……", "有發給瓏的信嗎？欸，沒有嗎……", "0", "有发给珑的信吗？诶，没有吗……", "0", "cv_long_40", "0", "0"},
[411040] = {411040, 11010, 44, 36, "0", "0", "So\u{0020}many\u{0020}people...\u{0020}I\u{0020}want\u{0020}to\u{0020}be\u{0020}brave\u{0020}like\u{0020}you,\u{0020}Navigator.", "沢山の人がいる……瓏も勇気を出して、ナビゲーターみたいになりたい。", "好多人……我也想像領航一樣勇敢呢。", "0", "好多人……我也想像领航一样勇敢呢。", "0", "cv_long_41", "0", "0"},
[411041] = {411041, 11010, 45, 37, "0", "0", "Wah!", "うわぁ！", "嗚哇！", "0", "呜哇！", "0", "cv_long_42", "0", "0"},
[411100] = {411100, 11011, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_honglei_32", "0", "0"},
[411101] = {411101, 11011, 2, 2, "0", "0", "Is\u{0020}this\u{0020}the\u{0020}mission\u{0020}you've\u{0020}given\u{0020}me?\u{0020}Understood,\u{0020}I'll\u{0020}stand\u{0020}here.", "これは貴殿の命令か？承知した。ここから離れぬ。", "這是您下達的任務嗎？瞭解，我會一直站在這裡的。", "0", "这是您下达的任务吗？了解，我会一直站在这里的。", "0", "cv_honglei_2", "0", "0"},
[411102] = {411102, 11011, 3, 3, "0", "0", "Ninja\u{0020}Group,\u{0020}Gourai.\u{0020}Are\u{0020}you\u{0020}the\u{0020}Navigator\u{0020}of\u{0020}this\u{0020}team?\u{0020}I'll\u{0020}follow\u{0020}all\u{0020}your\u{0020}orders.", "忍心社、轟雷。貴殿がこの隊のナビゲーターか？分かった。命令に従う。", "忍心社，轟雷。您就是這支隊伍的領航嗎？我明白了，我會聽從您的所有命令。", "0", "忍心社，轰雷。您就是这支队伍的领航吗？我明白了，我会听从您的所有命令。", "0", "cv_honglei_1", "0", "0"},
[411103] = {411103, 11011, 4, 4, "0", "idle", "Suzuki\u{0020}Seifung\u{0020}isn't\u{0020}here,\u{0020}right?\u{0020}That's\u{0020}good...\u{0020}Navigator,\u{0020}let\u{0020}me\u{0020}give\u{0020}you\u{0020}some\u{0020}advice,\u{0020}it's\u{0020}best\u{0020}not\u{0020}to\u{0020}pair\u{0020}her\u{0020}with\u{0020}me.", "鈴木清風は……ここにはおらぬようだな。よかった。……貴殿に一つ忠告しておく。彼女と我を同じ所に配置せぬことだ。", "鈴木清風…她不在這裡吧？那就好……領航，給您一個提議，最好不要把她和我安排在一起。", "0", "铃木清风…她不在这里吧？那就好……领航，给您一个提议，最好不要把她和我安排在一起。", "0", "cv_honglei_3", "0", "0"},
[411104] = {411104, 11011, 5, 4, "0", "idle", "Cheer\u{0020}up,\u{0020}Navigator,\u{0020}you've\u{0020}got\u{0020}your\u{0020}own\u{0020}mission\u{0020}too.", "ナビゲーター、しっかりしろ。貴殿にも己の任務があるはずだ。", "打起精神，領航，您也有自己的任務吧？", "0", "打起精神，领航，您也有自己的任务吧？", "0", "cv_honglei_4", "0", "0"},
[411105] = {411105, 11011, 6, 4, "0", "idle", "Even\u{0020}though\u{0020}AEGIS\u{0020}isn't\u{0020}perfect...\u{0020}it\u{0020}saved\u{0020}me,\u{0020}and\u{0020}that's\u{0020}a\u{0020}fact.\u{0020}So,\u{0020}I've\u{0020}decided\u{0020}to\u{0020}dedicate\u{0020}my\u{0020}life\u{0020}as\u{0020}Thunder\u{0020}Strike\u{0020}to\u{0020}AEGIS.", "アイギスは……特に素晴らしい組織とも言えぬ。だが我を救い、新たな人生を与えてくれたことも紛れのない事実だ。だから我は轟雷としての人生を、全てアイギスに捧げると決意したのだ。", "儘管艾吉斯並不是一個表面上那樣完美的的組織…但它救了我，讓我重獲新生也是不爭的事實。所以，我決定將作為“轟雷”的人生…全部奉獻給艾吉斯。", "0", "尽管艾吉斯并不是一个表面上那样完美的的组织…但它救了我，让我重获新生也是不争的事实。所以，我决定将作为“轰雷”的人生…全部奉献给艾吉斯。", "0", "cv_honglei_29", "0", "0"},
[411106] = {411106, 11011, 7, 5, "1_》_0_0.8", "level1", "Members\u{0020}of\u{0020}Ninja\u{0020}Group\u{0020}usually\u{0020}disguise\u{0020}themselves\u{0020}to\u{0020}hide\u{0020}their\u{0020}identities.\u{0020}We\u{0020}serve\u{0020}as\u{0020}AEGIS's\u{0020}invisible\u{0020}blade,\u{0020}working\u{0020}in\u{0020}the\u{0020}shadows\u{0020}until\u{0020}death—that's\u{0020}our\u{0020}fate.", "忍心社の者たちは、目立たぬ一般人として生活することで、己の正体を隠している。アイギスの刃として闇の中で己を研ぎすまし、人知れず錆びていく。これが我らの宿命だ。", "忍心社的成員，平常會偽裝成不起眼的人，來隱藏自己的身份。我們作為艾吉斯的無形之刃，在黑暗中為它服務，直到死亡才會停下，這就是我們的宿命。", "0", "忍心社的成员，平常会伪装成不起眼的人，来隐藏自己的身份。我们作为艾吉斯的无形之刃，在黑暗中为它服务，直到死亡才会停下，这就是我们的宿命。", "0", "cv_honglei_30", "0", "0"},
[411107] = {411107, 11011, 8, 5, "1_》_0_0.8", "level1", "Is\u{0020}there\u{0020}a\u{0020}mission?", "任務か？", "有任務嗎？", "0", "有任务吗？", "0", "cv_honglei_5", "0", "0"},
[411108] = {411108, 11011, 9, 5, "1_》_100_1.5", "level2", "No\u{0020}matter\u{0020}how\u{0020}dirty\u{0020}the\u{0020}mission,\u{0020}I\u{0020}will\u{0020}complete\u{0020}it—that's\u{0020}my\u{0020}duty.", "どんな汚い任務でも成し遂げてみせる。これが我が使命だ。", "領航，無論多麼骯髒的任務我都會完成的，這就是我的使命。", "0", "领航，无论多么肮脏的任务我都会完成的，这就是我的使命。", "0", "cv_honglei_6", "0", "0"},
[411109] = {411109, 11011, 10, 5, "1_》_500_2", "level3", "The\u{0020}purpose\u{0020}of\u{0020}founding\u{0020}Ninja\u{0020}Group\u{0020}was\u{0020}to\u{0020}prevent\u{0020}tragedies\u{0020}like\u{0020}\"hers\"\u{0020}from\u{0020}happening\u{0020}again.\u{0020}I\u{0020}won't\u{0020}let\u{0020}anyone\u{0020}hurt\u{0020}you,\u{0020}Navigator...\u{0020}You\u{0020}deserve\u{0020}a\u{0020}happy\u{0020}life.", "忍心社を創設した目的は……彼女のような悲劇を二度と生じさせぬこと。……ナビゲーター、誰にも貴殿を傷付けさせぬ。貴殿には幸せな人生を送って欲しいのだ。", "成立“忍心社”的目的，是為了防止像“她”那樣的悲劇再次出現。領航，我不會讓任何人傷害您的…您理應有一個美滿的人生。", "0", "成立“忍心社”的目的，是为了防止像“她”那样的悲剧再次出现。领航，我不会让任何人伤害您的…您理应有一个美满的人生。", "0", "cv_honglei_7", "0", "0"},
[411110] = {411110, 11011, 11, 5, "1_》_1000_2.5", "level4", "...Navigator,\u{0020}I've\u{0020}always\u{0020}thought\u{0020}that\u{0020}as\u{0020}long\u{0020}as\u{0020}the\u{0020}mission\u{0020}is\u{0020}completed,\u{0020}life—mine\u{0020}or\u{0020}others'—was\u{0020}just\u{0020}a\u{0020}tool.\u{0020}But\u{0020}you...\u{0020}you're\u{0020}different.", "……ナビゲーター。我は任務が達成できるのであれば、人の命や自分の命など、ただの消耗品に過ぎないと思っていた。しかしナビゲーター。貴殿だけは……特別なのだ。", "…領航，我一直認為，只要能夠完成任務，無論是別人的性命，亦或是自己的生命，都不過是消耗品。但，唯有您…只有您，是不同的。", "0", "…领航，我一直认为，只要能够完成任务，无论是别人的性命，亦或是自己的生命，都不过是消耗品。但，唯有您…只有您，是不同的。", "0", "cv_honglei_8", "0", "0"},
[411111] = {411111, 11011, 12, 6, "0", "0", "Yes,\u{0020}I've\u{0020}gotten\u{0020}stronger.", "うむ。強くなった。", "嗯，我變得更強了。", "0", "嗯，我变得更强了。", "0", "cv_honglei_9", "0", "0"},
[411112] = {411112, 11011, 13, 7, "0", "0", "Do\u{0020}you\u{0020}believe\u{0020}in\u{0020}me?", "貴殿は……我を信じるか？", "您相信我嗎？", "0", "您…相信我吗？", "0", "cv_honglei_10", "0", "0"},
[411113] = {411113, 11011, 14, 8, "0", "0", "I\u{0020}will\u{0020}repay\u{0020}your\u{0020}trust\u{0020}with\u{0020}results.\u{0020}Please\u{0020}forgive\u{0020}me\u{0020}for\u{0020}only\u{0020}being\u{0020}able\u{0020}to\u{0020}say\u{0020}\"thank\u{0020}you\"\u{0020}for\u{0020}now...", "貴殿の信頼に、必ずや実績を持って応えよう。今は、感謝の言葉しかない。許してくれ……", "您的這份信任，我會用實績來回報的。請原諒我現在只能用一句簡單的“謝謝”來回應您……", "0", "您的这份信任，我会用实绩来回报的。请原谅我现在只能用一句简单的“谢谢”来回应您……", "0", "cv_honglei_11", "0", "0"},
[411114] = {411114, 11011, 15, 9, "0", "0", "Thanks\u{0020}for\u{0020}that.", "感謝する。", "謝謝。", "0", "谢谢。", "0", "cv_honglei_12", "0", "0"},
[411115] = {411115, 11011, 16, 10, "0", "0", "Operation\u{0020}commencing.", "作戦開始。", "作戰開始。", "0", "作战开始。", "0", "cv_honglei_13", "0", "0"},
[411116] = {411116, 11011, 17, 11, "0", "0", "This\u{0020}outcome\u{0020}is\u{0020}expected,\u{0020}Ninja\u{0020}Group\u{0020}has\u{0020}never\u{0020}failed.", "当然の結果だ。忍心社に失敗はない。", "這是當然的結果，忍心社從未失敗過。", "0", "这是当然的结果，忍心社从未失败过。", "0", "cv_honglei_14", "0", "0"},
[411117] = {411117, 11011, 18, 12, "0", "0", "Next\u{0020}time,\u{0020}we'll\u{0020}do\u{0020}even\u{0020}better.", "次は必ず、もっと上手くやる。", "下一次，我們一定會做得更好的。", "0", "下一次，我们一定会做得更好的。", "0", "cv_honglei_15", "0", "0"},
[411118] = {411118, 11011, 19, 13, "0", "0", "A\u{0020}victory\u{0020}like\u{0020}this...\u{0020}I\u{0020}can't\u{0020}accept\u{0020}it.", "このような勝利……腑に落ちぬ。", "這樣的勝利…我不能接受。", "0", "这样的胜利…我不能接受。", "0", "cv_honglei_16", "0", "0"},
