[411205] = {411205, 11012, 6, 4, "0", "idle", "…D-b2…\u{0020}My\u{0020}database\u{0020}still\u{0020}holds\u{0020}records\u{0020}about\u{0020}her.\u{0020}I\u{0020}see…\u{0020}so\u{0020}she\u{0020}was\u{0020}the\u{0020}one\u{0020}who\u{0020}stopped\u{0020}me…", "…Ｄ型ｂ－２……アルファのデータベースに、彼女に関する記録があります。なるほど、アルファを止めたのは、彼女……", "0", "0", "0", "0", "cv_arufa_29", "0", "0"},
[411206] = {411206, 11012, 7, 5, "1_》_0_0.8", "level1", "Prototype\u{0020}Unit\u{0020}Alpha—equipped\u{0020}with\u{0020}a\u{0020}Secondary\u{0020}Persona\u{0020}Chip,\u{0020}granting\u{0020}her\u{0020}self-awareness\u{0020}and\u{0020}the\u{0020}ability\u{0020}to\u{0020}learn.\u{0020}And\u{0020}now,\u{0020}Alpha\u{0020}is\u{0020}reactivated\u{0020}for\u{0020}one\u{0020}purpose\u{0020}only:\u{0020}to\u{0020}protect\u{0020}humanity.\u{0020}At\u{0020}least…\u{0020}that's\u{0020}what\u{0020}her\u{0020}database\u{0020}claims.", "初號機アルファ、自我意識と學習能力を備えた次人格チップを搭載。アルファの存在理由は、人間を守る。……アルファのデータベースにこう記載しています。", "0", "0", "0", "0", "cv_arufa_30", "0", "0"},
