[411208] = {411208, 11012, 9, 5, "1_》_100_1.5", "level2", "I\u{0020}often\u{0020}recall\u{0020}the\u{0020}past…before\u{0020}I\u{0020}became\u{0020}Alpha…\u{0020}Yes,\u{0020}I\u{0020}once…", "アルファは…時々昔のことを思い出します…アルファがまだアルファではない時のこと……そう、昔の自分……", "0", "0", "0", "0", "cv_arufa_6", "0", "0"},
[411209] = {411209, 11012, 10, 5, "1_》_500_2", "level3", "If\u{0020}you\u{0020}dislike\u{0020}my\u{0020}appearance,\u{0020}destroy\u{0020}me…\u{0020}It's\u{0020}frightening,\u{0020}but\u{0020}for\u{0020}you,\u{0020}Navigator,\u{0020}I\u{0020}will\u{0020}endure.", "もしアルファの姿が嫌いでしたら、どうかアルファを処分してください……怖いですが、ナビゲーターのためなら、アルファは我慢します。", "0", "0", "0", "0", "cv_arufa_7", "0", "0"},
[411210] = {411210, 11012, 11, 5, "1_》_1000_2.5", "level4", "I…am\u{0020}a\u{0020}machine.\u{0020}I\u{0020}couldn't\u{0020}understand\u{0020}human\u{0020}emotions,\u{0020}nor\u{0020}could\u{0020}I\u{0020}share\u{0020}in\u{0020}them…\u{0020}That\u{0020}was\u{0020}how\u{0020}it\u{0020}used\u{0020}to\u{0020}be.\u{0020}But\u{0020}now,\u{0020}I'm\u{0020}beginning\u{0020}to\u{0020}understand\u{0020}what\u{0020}feelings\u{0020}are.\u{0020}I\u{0020}want…to\u{0020}protect\u{0020}you,\u{0020}to\u{0020}protect\u{0020}humanity.", "アルファは…ロボットで、人間の感情を理解できず、共鳴もできない…はずでした。でも今は段々、感情を理解できるようになりました。アルファは、ナビゲーターを…人間を守りたい。", "0", "0", "0", "0", "cv_arufa_8", "0", "0"},
