[411242] = {411242, 11012, 44, 36, "0", "0", "Advertising\u{0020}prohibited.", "広告…禁止。", "0", "0", "0", "0", "cv_arufa_42", "0", "0"},
[411243] = {411243, 11012, 45, 37, "0", "0", "Error~", "エラー。", "0", "0", "0", "0", "cv_arufa_43", "0", "0"},
[411400] = {411400, 11014, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_sikadi_31", "0", "0"},
[411401] = {411401, 11014, 2, 2, "0", "0", "Humph,\u{0020}it's\u{0020}only\u{0020}natural\u{0020}for\u{0020}you\u{0020}to\u{0020}choose\u{0020}me.\u{0020}After\u{0020}all,\u{0020}there's\u{0020}an\u{0020}invisible\u{0020}red\u{0020}thread\u{0020}of\u{0020}fate\u{0020}connecting\u{0020}us...\u{0020}Hey,\u{0020}don't\u{0020}go!\u{0020}I\u{0020}haven't\u{0020}finished\u{0020}yet!", "フン、汝が妾を選ぶのは当然だ。汝と妾は、運命の赤い糸で結ばれておるのだからなぁ……ってこら！行くな、まだ話の途中だぁ！", "哼，你會選擇吾是理所當然的，畢竟吾與汝之間可是存在著不可視的命運紅線在連接著…喂，別走啊，我還沒說完呢！", "0", "哼，你会选择吾是理所当然的，毕竟吾与汝之间可是存在着不可视的命运红线在连接着…喂，别走啊，我还没说完呢！", "0", "cv_sikadi_2", "0", "0"},
[411402] = {411402, 11014, 3, 3, "0", "0", "Finally,\u{0020}I\u{0020}found\u{0020}you.\u{0020}Is\u{0020}this\u{0020}our\u{0020}destiny?\u{0020}I...\u{0020}My\u{0020}name\u{0020}is\u{0020}Skadi,\u{0020}the\u{0020}queen\u{0020}ruling\u{0020}Dunescaith.\u{0020}Should\u{0020}it\u{0020}be\u{0020}called\u{0020}Dunescaith?\u{0020}Never\u{0020}mind\u{0020}that!", "ようやく見つけたぞ。まさにこれが運命。あた…妾の名はスカディ、影の国を統べる女王なり！……え？冬の女神のほうが正しい？……細かいことを気にするなぁ！", "終於，找到你了，這就是我與你的宿命嗎？我…吾的名字是斯卡蒂，統治著暗之國的女王…“應該是影之國吧？”…不要在意那麼多啦！", "0", "终于，找到你了，这就是我与你的宿命吗？我…吾的名字是斯卡蒂，统治着暗之国的女王…“应该是影之国吧？”…不要在意那么多啦！", "0", "cv_sikadi_1", "0", "0"},
[411403] = {411403, 11014, 4, 4, "0", "idle", "Ha—ha—ha,\u{0020}Navigator,\u{0020}I\u{0020}can\u{0020}sense\u{0020}what\u{0020}you're\u{0020}thinking...\u{0020}\"Synesthesia\"?\u{0020}No,\u{0020}this\u{0020}is\u{0020}magic,\u{0020}magic!", "はっはっはー！ナビゲーター、汝の思惑、妾には隠せぬぞ。……通感覚？違う！これは魔法だ、魔法ぉ！", "哈——哈——哈，領航，吾能感覺到汝在想什麼…“通感”？不是啦，這是魔法，魔法！", "0", "哈——哈——哈，领航，吾能感觉到汝在想什么…“通感”？不是啦，这是魔法，魔法！", "0", "cv_sikadi_3", "0", "0"},
[411404] = {411404, 11014, 5, 4, "0", "idle", "Did\u{0020}you\u{0020}see\u{0020}it,\u{0020}Navigator?\u{0020}My\u{0020}eyes\u{0020}are\u{0020}glowing,\u{0020}it's\u{0020}a\u{0020}sign\u{0020}of\u{0020}our\u{0020}resonance!", "見たか、ナビゲーター。妾の目が光っておるぞ。これは汝との共鳴の兆しじゃ！", "看到了嗎，領航，吾的眼睛正在閃閃發光，這是與汝產生共鳴的徵兆！", "0", "看到了吗，领航，吾的眼睛正在闪闪发光，这是与汝产生共鸣的征兆！", "0", "cv_sikadi_4", "0", "0"},
[411405] = {411405, 11014, 6, 4, "0", "idle", "Shh—Navigator,\u{0020}don't\u{0020}tell\u{0020}Lilith\u{0020}I'm\u{0020}here...\u{0020}It's\u{0020}just\u{0020}cake,\u{0020}what's\u{0020}the\u{0020}big\u{0020}deal...", "しーっ……ナビゲーター、妾がここに居ること、リリスに言うでないぞ。……まったく、ケーキのひとつぐらい、別にいいじゃないか……", "噓——領航，不要告訴莉莉絲我在這裡…真是的，只是一個蛋糕而已，有什麼關係嘛……", "0", "嘘——领航，不要告诉莉莉丝我在这里…真是的，只是一个蛋糕而已，有什么关系嘛……", "0", "cv_sikadi_28", "0", "0"},
[411406] = {411406, 11014, 7, 5, "1_》_0_0.8", "level1", "Chuunibyou?\u{0020}No!\u{0020}I'm\u{0020}not\u{0020}chuunibyou!\u{0020}I\u{0020}was\u{0020}chosen\u{0020}by\u{0020}the\u{0020}world,\u{0020}needed\u{0020}by\u{0020}people,\u{0020}that's\u{0020}why\u{0020}I\u{0020}became\u{0020}the\u{0020}Queen\u{0020}of\u{0020}the\u{0020}Dunescaith!\u{0020}I'm\u{0020}not\u{0020}some\u{0020}regular\u{0020}\"chuunibyou\"!", "中二病？違う！妾は中二病などではないっ！よいかっ。妾は世界に選ばれ、民に必要とされたが故、影の国の女王となってここに顕現したのじゃ！決して中二病ではないぞ！", "中二病？不是！吾才不是中二病！聽好了，吾是因為被世界選擇，被人們需要，所以才會成為影之國的女王，出現在這裡的！才不是普通的“中二病”！", "0", "中二病？不是！吾才不是中二病！听好了，吾是因为被世界选择，被人们需要，所以才会成为影之国的女王，出现在这里的！才不是普通的“中二病”！", "0", "cv_sikadi_29", "0", "0"},
[411407] = {411407, 11014, 8, 5, "1_》_0_0.8", "level1", "If\u{0020}you\u{0020}want\u{0020}to\u{0020}approach\u{0020}me,\u{0020}fine,\u{0020}but\u{0020}beware\u{0020}of\u{0020}being\u{0020}swallowed\u{0020}by\u{0020}the\u{0020}shadows,\u{0020}Navigator.", "ナビゲーターよ。妾に近づくのは構わぬが、影に飲み込まれるでないぞ。", "想靠近吾的話，倒也無妨，不過要小心被陰影吞噬喔，領航。", "0", "想靠近吾的话，倒也无妨，不过要小心被阴影吞噬噢，领航。", "0", "cv_sikadi_5", "0", "0"},
[411408] = {411408, 11014, 9, 5, "1_》_100_1.5", "level2", "Ah,\u{0020}Navigator,\u{0020}just\u{0020}in\u{0020}time,\u{0020}help\u{0020}me\u{0020}get\u{0020}a\u{0020}dark\u{0020}power\u{0020}potion...\u{0020}Just\u{0020}get\u{0020}me\u{0020}the\u{0020}soda.", "あっ、ナビゲーターだ。……丁度よい。妾の代理としてダークエネルギーを補充する魔剤を入手するのだ。……えーっと、あれだよ……サイダーのことだよ。", "啊，是領航啊。正好，幫吾去買一份補充黑暗力量的魔力劑吧…就是那個…碳酸飲料啦。", "0", "啊，是领航啊。正好，帮吾去买一份补充黑暗力量的魔力剂吧…就是那个…碳酸饮料啦。", "0", "cv_sikadi_6", "0", "0"},
[411409] = {411409, 11014, 10, 5, "1_》_500_2", "level3", "No,\u{0020}stop\u{0020}patting\u{0020}me!\u{0020}I'm\u{0020}not\u{0020}one\u{0020}of\u{0020}those\u{0020}spoiled\u{0020}kids!\u{0020}I'm\u{0020}the\u{0020}strongest\u{0020}Queen\u{0020}of\u{0020}the\u{0020}Dunescaith!\u{0020}Ahem...\u{0020}but\u{0020}if\u{0020}you\u{0020}really\u{0020}like\u{0020}me,\u{0020}I\u{0020}wouldn't\u{0020}mind.", "な、なぜいつも頭をなでるのだ。妾を甘えん坊な子供と一緒にするなぁ！妾は最強なる影の国の女王じゃぞ！オホン……でもまあ、そんなに妾のことが好きなら……仕方ないのう。", "不，不要老是摸吾啦，別把吾當成那些愛撒嬌的孩子！吾可是最強的影之國女王！咳咳…不過，你真這麼喜歡吾的話，吾也不會在意的。", "0", "不，不要老是摸吾啦，别把吾当成那些爱撒娇的孩子！吾可是最强的影之国女王！咳咳…不过，你真这么喜欢吾的话，吾也不会在意的。", "0", "cv_sikadi_7", "0", "0"},
[411410] = {411410, 11014, 11, 5, "1_》_1000_2.5", "level4", "Those\u{0020}attracted\u{0020}by\u{0020}shadows\u{0020}and\u{0020}death,\u{0020}come\u{0020}form\u{0020}a\u{0020}bond\u{0020}with\u{0020}the\u{0020}Queen\u{0020}of\u{0020}the\u{0020}Dunescaith...\u{0020}Navigator?!\u{0020}When\u{0020}did\u{0020}you\u{0020}get\u{0020}here?", "影と死に魅了された者よ。影の国の女王と……恋の契りを。……ん？ナ、ナビゲーター！？いつからそこにいたのだぁ？", "被陰影與死亡吸引而墮落的人啊，和影之國的女王結下戀…領航！？汝什麼時候在這的？", "0", "被阴影与死亡吸引而堕落的人啊，和影之国的女王结下恋…领航！？汝什么时候在这的？", "0", "cv_sikadi_8", "0", "0"},
[411411] = {411411, 11014, 12, 6, "0", "0", "Oh,\u{0020}I\u{0020}can\u{0020}feel\u{0020}my\u{0020}power\u{0020}rising!", "おおお、感じるぞ！妾の力が漲っておる！", "喔喔喔，吾感受到了，力量正在提升！", "0", "噢噢噢，吾感受到了，力量正在提升！", "0", "cv_sikadi_9", "0", "0"},
[411412] = {411412, 11014, 13, 7, "0", "0", "Oh?\u{0020}You\u{0020}want\u{0020}to\u{0020}witness\u{0020}my\u{0020}strength\u{0020}at\u{0020}its\u{0020}peak?", "なんだ？全盛期の妾の力を、その目に焼き付けたいのだな？", "喔？想要見識下嗎，吾巔峰時期的實力。", "0", "噢？想要见识下吗，吾巅峰时期的实力。", "0", "cv_sikadi_10", "0", "0"},
[411413] = {411413, 11014, 14, 8, "0", "0", "Yes,\u{0020}I'm\u{0020}in\u{0020}my\u{0020}complete\u{0020}form\u{0020}now!\u{0020}Even\u{0020}legendary\u{0020}gods,\u{0020}monsters,\u{0020}or\u{0020}beasts\u{0020}won't\u{0020}stand\u{0020}a\u{0020}chance\u{0020}against\u{0020}me.\u{0020}After\u{0020}all,\u{0020}I'm\u{0020}the\u{0020}queen\u{0020}of\u{0020}the\u{0020}Dunescaith!", "うむ、今の妾はもはや完全体！例え伝説の神霊、魔物、怪獣が現れようとも相手ではない。なにせ影の国の女王は、最強じゃからなぁ！", "嗯嗯，現在的吾，已經是完全體了！就算是傳說中的神靈、魔物，怪獸出現在吾的面前，也不會是吾的對手。畢竟，影之國的女王是最強的！", "0", "嗯嗯，现在的吾，已经是完全体了！就算是传说中的神灵、魔物，怪兽出现在吾的面前，也不会是吾的对手。毕竟，影之国的女王是最强的！", "0", "cv_sikadi_11", "0", "0"},
[411414] = {411414, 11014, 15, 9, "0", "0", "I\u{0020}can't\u{0020}wait\u{0020}to\u{0020}unleash\u{0020}this\u{0020}power!", "早くこの力を試させよ！妾はもう待てぬぞ！", "吾已經迫不及待想展示這份力量了！", "0", "吾已经迫不及待想展示这份力量了！", "0", "cv_sikadi_12", "0", "0"},
[411415] = {411415, 11014, 16, 10, "0", "0", "The\u{0020}shadow\u{0020}descends,\u{0020}the\u{0020}power\u{0020}of\u{0020}the\u{0020}dead!", "影の降臨、亡者の力！", "陰影降臨，亡者的力量！", "0", "阴影降临，亡者的力量！", "0", "cv_sikadi_13", "0", "0"},
[411416] = {411416, 11014, 17, 11, "0", "0", "A\u{0020}perfect\u{0020}victory!\u{0020}Ha-ha-ha!\u{0020}Did\u{0020}you\u{0020}witness\u{0020}the\u{0020}power\u{0020}of\u{0020}the\u{0020}gods?", "完全勝利！はっはっはー！見たか、これぞ神霊の力よ！", "完美的勝利，哈——哈——哈，見識到了嗎，神靈的力量！", "0", "完美的胜利，哈——哈——哈，见识到了吗，神灵的力量！", "0", "cv_sikadi_14", "0", "0"},
[411417] = {411417, 11014, 18, 12, "0", "0", "Huh...\u{0020}It\u{0020}seems\u{0020}I\u{0020}still\u{0020}have\u{0020}a\u{0020}bit\u{0020}of\u{0020}trouble\u{0020}controlling\u{0020}my\u{0020}power.", "うぅむ……どうやらまだ、力の制御が足りぬようじゃな。", "呼…看來，吾對自己力量的控制還有些不足啊。", "0", "呼…看来，吾对自己力量的控制还有些不足啊。", "0", "cv_sikadi_15", "0", "0"},
[411418] = {411418, 11014, 19, 13, "0", "0", "Woo...\u{0020}I\u{0020}messed\u{0020}up.\u{0020}This\u{0020}doesn't\u{0020}count!\u{0020}It\u{0020}doesn't\u{0020}count!", "う…ミスった。今回はなし、なしー！", "嗚…失誤了，這次不算，這次不算！", "0", "呜…失误了，这次不算，这次不算！", "0", "cv_sikadi_16", "0", "0"},
[411419] = {411419, 11014, 20, 14, "0", "0", "Did\u{0020}we\u{0020}fail?...\u{0020}Retreat!\u{0020}I'll\u{0020}cover\u{0020}you.", "し、失敗か……撤退だ。あたしが援護する。", "失、失敗了嗎…撤退，我來掩護。", "0", "失、失败了吗…撤退，我来掩护。", "0", "cv_sikadi_17", "0", "0"},
[411420] = {411420, 11014, 21, 15, "0", "0", "Be\u{0020}consumed\u{0020}by\u{0020}the\u{0020}shadows!", "影に飲まれよ！", "被陰影吞噬吧！", "0", "被阴影吞噬吧！", "0", "cv_sikadi_18", "0", "0"},
[411421] = {411421, 11014, 23, 16, "0", "0", "Skadi\u{0020}Sword\u{0020}X!", "スカディ式、ハヤテブレイドエックス！", "斯卡蒂式迅猛劍X！", "0", "斯卡蒂式迅猛剑X！", "0", "cv_sikadi_19", "0", "0"},
[411422] = {411422, 11014, 26, 19, "0", "0", "My\u{0020}time...\u{0020}has\u{0020}come...", "妾の番が……来た……", "吾的時間…到了……", "0", "吾的时间…到了……", "0", "cv_sikadi_20", "0", "0"},
[411423] = {411423, 11014, 27, 20, "0", "0", "So,\u{0020}what\u{0020}do\u{0020}you\u{0020}think?\u{0020}Are\u{0020}you\u{0020}captivated\u{0020}by\u{0020}my\u{0020}beautiful\u{0020}form?", "なんじゃ。妾の美しい体の虜になったのか？", "如何，被吾美麗的身體吸引了嗎？", "0", "如何，被吾美丽的身体吸引了吗？", "0", "cv_sikadi_21", "0", "0"},
[411424] = {411424, 11014, 28, 21, "0", "0", "I\u{0020}don't\u{0020}mind,\u{0020}but\u{0020}are\u{0020}you\u{0020}really\u{0020}planning\u{0020}to\u{0020}just\u{0020}keep\u{0020}staring\u{0020}like\u{0020}that...?", "べ、別に構わぬのじゃが……そのままずっと見ているつもり……なのか？", "吾雖然不介意，可汝真打算這樣一直盯著嗎……", "0", "吾虽然不介意，可汝真打算这样一直盯着吗……", "0", "cv_sikadi_22", "0", "0"},
[411425] = {411425, 11014, 29, 21, "0", "0", "Taking\u{0020}a\u{0020}bath\u{0020}feels\u{0020}so\u{0020}nice...\u{0020}It\u{0020}brings\u{0020}back\u{0020}memories\u{0020}from\u{0020}my\u{0020}childhood.", "風呂は気持ちがいいのう……あた…妾の幼き頃を思い出すぞ。", "泡澡真舒服啊…讓我…吾想起小時候的事了。", "0", "泡澡真舒服啊…让我…吾想起小时候的事了。", "0", "cv_sikadi_23", "0", "0"},
[411426] = {411426, 11014, 30, 22, "0", "0", "Could\u{0020}it\u{0020}be\u{0020}that\u{0020}those\u{0020}Underworld\u{0020}creatures\u{0020}are\u{0020}chasing\u{0020}us...?", "まさか、冥界の奴らが……", "難道說，是冥界的那些傢伙追來了嗎……", "0", "难道说，是冥界的那些家伙追来了吗……", "0", "cv_sikadi_24", "0", "0"},
[411427] = {411427, 11014, 31, 23, "0", "0", "Navigator,\u{0020}the\u{0020}shadows\u{0020}connect\u{0020}us...\u{0020}I\u{0020}can't\u{0020}be\u{0020}wrong...\u{0020}right?", "ナビゲーター。影が我らを結んでおるのじゃ。……間違いはせぬ…よな？", "領航，陰影將我們連接在一起…不會猜錯…吧？", "0", "领航，阴影将我们连接在一起…不会猜错…吧？", "0", "cv_sikadi_25", "0", "0"},
[411428] = {411428, 11014, 32, 24, "0", "0", "Very\u{0020}good!\u{0020}I\u{0020}might\u{0020}even\u{0020}want\u{0020}to\u{0020}make\u{0020}you\u{0020}a\u{0020}citizen\u{0020}of\u{0020}the\u{0020}Shadow\u{0020}Kingdom!", "でかした！褒美に影の国の住民として迎え入れてやろうぞ！", "很好，吾都想將汝收為影之國的國民了！", "0", "很好，吾都想将汝收为影之国的国民了！", "0", "cv_sikadi_26", "0", "0"},
[411429] = {411429, 11014, 33, 25, "0", "0", "The\u{0020}pitch-black\u{0020}power\u{0020}hidden\u{0020}in\u{0020}the\u{0020}shadows\u{0020}will\u{0020}burn\u{0020}the\u{0020}one\u{0020}before\u{0020}me\u{0020}to\u{0020}ashes!", "影に隠れし漆黒の力よ……目の前のこやつを灰にせよぉ！", "隱藏在影子中的漆黑力量啊，將吾眼前的人燒成灰燼吧！", "0", "隐藏在影子中的漆黑力量啊，将吾眼前的人烧成灰烬吧！", "0", "cv_sikadi_27", "0", "0"},
[411430] = {411430, 11014, 34, 26, "0", "0", "Navigator,\u{0020}you're\u{0020}here.\u{0020}As\u{0020}you\u{0020}can\u{0020}see,\u{0020}I'm\u{0020}practicing\u{0020}a\u{0020}new\u{0020}finishing\u{0020}move—\"The\u{0020}Dark\u{0020}Swift\u{0020}Blade\"...\u{0020}Hey,\u{0020}stop\u{0020}laughing!", "おおナビゲーターよ、しかと見たか？これが妾の新たなる必殺技、名付けて……ダークソニックシャドーブレイク……ってこらぁ、笑うなぁ！", "領航，汝來了啊。就像汝看見的那樣，吾正在練習新的必殺技——“漆黑的迅疾影刃”……喂，不許笑啦！", "0", "领航，汝来了啊。就像汝看见的那样，吾正在练习新的必杀技——“漆黑的迅疾影刃”……喂，不许笑啦！", "0", "cv_sikadi_30", "0", "0"},
[411431] = {411431, 11014, 35, 27, "0", "0", "My\u{0020}magic\u{0020}eye\u{0020}is\u{0020}heating\u{0020}up.\u{0020}Is\u{0020}\"Fate\"\u{0020}drawing\u{0020}near?", "我が魔眼が熱く疼いておる。……来るか。……運命が。", "吾的魔眼正在發熱，要來了嗎，“命運”……", "0", "吾的魔眼正在发热，要来了吗，“命运”……", "0", "cv_sikadi_32", "0", "0"},
[411432] = {411432, 11014, 36, 28, "0", "0", "Just\u{0020}right!\u{0020}You\u{0020}will\u{0020}witness\u{0020}the\u{0020}queen's\u{0020}power.", "丁度よい。女王たる力、汝に見せようぞ。", "正好，讓汝見識一下女王的力量。", "0", "正好，让汝见识一下女王的力量。", "0", "cv_sikadi_33", "0", "0"},
[411433] = {411433, 11014, 37, 29, "0", "0", "Compared\u{0020}to\u{0020}me,\u{0020}everyone\u{0020}else\u{0020}pales\u{0020}in\u{0020}comparison.", "妾に比べれば、とるに足らぬものばかりよの。", "跟吾比起來，其他人還是差了一截呀。", "0", "跟吾比起来，其他人还是差了一截呀。", "0", "cv_sikadi_34", "0", "0"},
[411434] = {411434, 11014, 38, 30, "0", "0", "I\u{0020}sense...\u{0020}someone\u{0020}is\u{0020}calling\u{0020}me.", "感じるぞ…誰かが妾を呼んでいるっ。", "吾感受到了…有人在呼喚吾。", "0", "吾感受到了…有人在呼唤吾。", "0", "cv_sikadi_35", "0", "0"},
[411435] = {411435, 11014, 39, 31, "0", "0", "Is\u{0020}there\u{0020}a\u{0020}sword\u{0020}that\u{0020}can\u{0020}sever\u{0020}the\u{0020}connection\u{0020}between\u{0020}this\u{0020}world\u{0020}and\u{0020}the\u{0020}Shadow\u{0020}Kingdom?", "現世と影の国を断ち切った剣は、ここにあるのか？", "將現世與影之國的聯繫斬斷的劍，這裡有嗎？", "0", "将现世与影之国的联系斩断的剑，这里有吗？", "0", "cv_sikadi_36", "0", "0"},
[411436] = {411436, 11014, 40, 32, "0", "0", "That\u{0020}shiny\u{0020}thing—I'm\u{0020}quite\u{0020}fond\u{0020}of\u{0020}it!", "あのキラキラ光るやつ、妾は気に入ったぞ！", "那個，亮亮的東西，吾很中意！", "0", "那个，亮亮的东西，吾很中意！", "0", "cv_sikadi_37", "0", "0"},
[411437] = {411437, 11014, 41, 33, "0", "0", "There\u{0020}are\u{0020}no\u{0020}others\u{0020}like\u{0020}you\u{0020}in\u{0020}the\u{0020}Shadow\u{0020}Kingdom.", "影の国には、汝のような者はおらぬぞ。", "影之國裡可沒有汝這樣的人呢。", "0", "影之国里可没有汝这样的人呢。", "0", "cv_sikadi_38", "0", "0"},
[411438] = {411438, 11014, 42, 34, "0", "0", "I...\u{0020}don't\u{0020}understand...", "うむ…分からん……", "吾…看不懂……", "0", "吾…看不懂……", "0", "cv_sikadi_39", "0", "0"},
[411439] = {411439, 11014, 43, 35, "0", "0", "Be\u{0020}careful.\u{0020}There\u{0020}may\u{0020}be\u{0020}traps\u{0020}set\u{0020}by\u{0020}\"the\u{0020}authorities.\"", "気をつけよ。「公式」からの罠があるやもしれぬ。", "小心，也許有來自“官方”的陷阱——", "0", "小心，也许有来自“官方”的陷阱——", "0", "cv_sikadi_40", "0", "0"},
[411440] = {411440, 11014, 44, 36, "0", "0", "Let's\u{0020}go\u{0020}directly\u{0020}to\u{0020}their\u{0020}lair!", "そやつらの家に向かうのじゃ！", "直接去他們家吧！", "0", "直接去他们家吧！", "0", "cv_sikadi_41", "0", "0"},
[411441] = {411441, 11014, 45, 37, "0", "0", "Wow,\u{0020}there\u{0020}are\u{0020}so\u{0020}many\u{0020}buttons!", "うーむ……なんじゃこのボタンの数は。", "嗚哇，按鈕真多。", "0", "呜哇，按钮真多。", "0", "cv_sikadi_42", "0", "0"},
[411500] = {411500, 11015, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響ーー（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_lin_32", "0", "0"},
[411501] = {411501, 11015, 2, 2, "0", "0", "Heh,\u{0020}seems\u{0020}like\u{0020}you\u{0020}can't\u{0020}do\u{0020}without\u{0020}me,\u{0020}huh?\u{0020}After\u{0020}all,\u{0020}I\u{0020}am\u{0020}a\u{0020}genius.\u{0020}Huh?\u{0020}Just\u{0020}standing\u{0020}here?\u{0020}That's\u{0020}a\u{0020}waste\u{0020}of\u{0020}my\u{0020}talent!", "やれやれ。ナビゲーターはやっぱりあたしがいないとダメだねー。まあ天才だしー。……え？ここに立ってるだけ？そんなの誰だってできるじゃーん！", "呵，領航果然離不開我呢，誰讓我是天才呢~欸？只是站在這裡嗎，這是大材小用啦！", "0", "呵，领航果然离不开我呢，谁让我是天才呢~诶？只是站在这里吗，这是大材小用啦！", "0", "cv_lin_2", "0", "0"},
[411502] = {411502, 11015, 3, 3, "0", "0", "My\u{0020}name's\u{0020}Suzu,\u{0020}the\u{0020}ace\u{0020}of\u{0020}Tian\u{0020}Hua\u{0020}Pavilion\u{0020}and\u{0020}the\u{0020}rising\u{0020}star\u{0020}of\u{0020}Kyushu!\u{0020}Haha,\u{0020}from\u{0020}today\u{0020}onwards,\u{0020}my\u{0020}era\u{0020}begins—Hey,\u{0020}are\u{0020}you\u{0020}listening?", "あたしは鈴！天華閣のエース、九州の超新星であーる！フッフーン。ナビゲーター、今日からあたしの時代が開幕……って最後まで聞けー！", "我的名字叫做鈴，天華閣的王牌，九州的超新星！呼呼，領航，從今天開始，我的時代開始了——喂，聽我說完啦！", "0", "我的名字叫做铃，天华阁的王牌，九州的超新星！呼呼，领航，从今天开始，我的时代开始了——喂，听我说完啦！", "0", "cv_lin_1", "0", "0"},
[411503] = {411503, 11015, 4, 4, "0", "idle", "\"Never\u{0020}give\u{0020}up,\"\u{0020}that's\u{0020}my\u{0020}motto!\u{0020}Isn't\u{0020}it\u{0020}cool?\u{0020}Hehe.", "あたしのモットー、それは……ネバーギブアップ！どう？カッコいいでしょ？ニシシ。", "“永不放棄”，這就是我的座右銘！怎麼樣，很帥氣吧？嘻嘻。", "0", "“永不放弃”，这就是我的座右铭！怎么样，很帅气吧？嘻嘻。", "0", "cv_lin_3", "0", "0"},
[411504] = {411504, 11015, 5, 4, "0", "idle", "A\u{0020}genius\u{0020}is\u{0020}someone\u{0020}who\u{0020}keeps\u{0020}pushing\u{0020}forward\u{0020}even\u{0020}when\u{0020}everyone\u{0020}else\u{0020}has\u{0020}given\u{0020}up!", "天才はね、他の人が諦めてくじけそうになっていても、いつものように突き進んで、カッコいい背中を見せつけるの！", "所謂“天才”，就是要在其他人都放棄、氣餒的時候，一如既往地露出自己帥氣的背影，奮力向前！", "0", "所谓“天才”，就是要在其他人都放弃、气馁的时候，一如既往地露出自己帅气的背影，奋力向前！", "0", "cv_lin_4", "0", "0"},
[411505] = {411505, 11015, 6, 4, "0", "idle", "Last\u{0020}time,\u{0020}I\u{0020}accidentally\u{0020}broke\u{0020}Captain\u{0020}Caihua's\u{0020}favorite\u{0020}gourd.\u{0020}I\u{0020}thought\u{0020}I\u{0020}was\u{0020}done\u{0020}for,\u{0020}but\u{0020}she\u{0020}just\u{0020}said\u{0020}it\u{0020}was\u{0020}okay.\u{0020}She's\u{0020}really\u{0020}kind~", "こないだね、彩華隊長が大事にしてるひょうたんを壊しちゃったの。「あ、ダメだ。死ぬ……」って思ってたらなんと！大丈夫って言ってくれたのー！隊長やさしー！", "上次，我不小心把彩華隊長喜歡的葫蘆弄壞了，我還以為自己要被殺掉了呢。結果隊長卻對我說沒關係，真是溫柔呢~", "0", "上次，我不小心把彩华队长喜欢的葫芦弄坏了，我还以为自己要被杀掉了呢。结果队长却对我说没关系，真是温柔呢~", "0", "cv_lin_29", "0", "0"},
[411506] = {411506, 11015, 7, 5, "1_》_0_0.8", "level1", "My\u{0020}dream\u{0020}is\u{0020}to\u{0020}be\u{0020}a\u{0020}revered\u{0020}and\u{0020}dependable\u{0020}hero\u{0020}who\u{0020}charges\u{0020}ahead!\u{0020}Because\u{0020}I'm\u{0020}a\u{0020}genius,\u{0020}I\u{0020}know\u{0020}I\u{0020}can\u{0020}achieve\u{0020}it!", "あたしの夢は、みんなが憧れてくれる、頼りにしてくれる、道を切り開くヒーローになること！天才だから、きっと叶えてみせるもんね！", "我的夢想是，成為一個受人景仰，被人依賴，並且，勇往直前的英雄！因為我是天才，所以一定能實現的！", "0", "我的梦想是，成为一个受人景仰，被人依赖，并且，勇往直前的英雄！因为我是天才，所以一定能实现的！", "0", "cv_lin_30", "0", "0"},
[411507] = {411507, 11015, 8, 5, "1_》_0_0.8", "level1", "Got\u{0020}any\u{0020}troubles?\u{0020}Come\u{0020}to\u{0020}me!\u{0020}No\u{0020}need\u{0020}to\u{0020}hesitate~", "何か面倒なことがあったらこの天才に任せなー。遠慮はいらないよー。", "遇上什麼麻煩事就跟本天才說吧，不用客氣的啦~", "0", "遇上什么麻烦事就跟本天才说吧，不用客气的啦~", "0", "cv_lin_5", "0", "0"},
[411508] = {411508, 11015, 9, 5, "1_》_100_1.5", "level2", "Always\u{0020}getting\u{0020}zero\u{0020}on\u{0020}tests?\u{0020}Eh,\u{0020}well,\u{0020}the\u{0020}stuff\u{0020}they\u{0020}teach\u{0020}is\u{0020}too\u{0020}basic,\u{0020}not\u{0020}worth\u{0020}my\u{0020}time!", "テストはいつも０点…？あっ、それは……学校の授業なんか初歩的すぎて、この天才にふさわしくないから！", "考試總是考零分…？啊，這個……學校教的東西太基礎了，根本沒有學的必要啦！", "0", "考试总是考零分…？啊，这个……学校教的东西太基础了，根本没有学的必要啦！", "0", "cv_lin_6", "0", "0"},
[411509] = {411509, 11015, 10, 5, "1_》_500_2", "level3", "Did\u{0020}you\u{0020}know\u{0020}I\u{0020}have\u{0020}two\u{0020}moms?\u{0020}Both\u{0020}of\u{0020}them\u{0020}are\u{0020}amazing,\u{0020}and\u{0020}that's\u{0020}why\u{0020}I\u{0020}turned\u{0020}out\u{0020}to\u{0020}be\u{0020}such\u{0020}a\u{0020}genius!", "ねえねえ知ってる？あたしにはお母さんが二人いるんだよ！二人ともすっごいの！あたしみたいな天才が生まれるのも当然よね！", "領航，你知道嗎，我有兩位母親喔！不管是哪一個，都是十分偉大的母親，所以才會有我這樣的天才誕生！", "0", "领航，你知道吗，我有两位母亲噢！不管是哪一个，都是十分伟大的母亲，所以才会有我这样的天才诞生！", "0", "cv_lin_7", "0", "0"},
[411510] = {411510, 11015, 11, 5, "1_》_1000_2.5", "level4", "Showing\u{0020}your\u{0020}strongest\u{0020}self\u{0020}is\u{0020}a\u{0020}genius's\u{0020}duty!\u{0020}That\u{0020}way,\u{0020}you\u{0020}become\u{0020}reliable\u{0020}and\u{0020}stop\u{0020}others\u{0020}from\u{0020}worrying.\u{0020}You\u{0020}can\u{0020}always\u{0020}rely\u{0020}on\u{0020}me~\u{0020}Hehe~", "天才の資格とは……どんな時でも最強であること！周りに心配をかけず、むしろ誰からも頼りにされる。それが天才よ！ナビゲーター。好きなだけあたしを頼っていいからねー。えっへーん！", "任何時候都要表現出自己最強的一面，這就是天才的天職喔~畢竟，只有這樣，才能成為大家的依靠，才不會讓身邊的人擔心。領航，你可以盡情地依靠我喔~嘿嘿~", "0", "任何时候都要表现出自己最强的一面，这就是天才的天职噢~毕竟，只有这样，才能成为大家的依靠，才不会让身边的人担心。领航，你可以尽情地依靠我噢~嘿嘿~", "0", "cv_lin_8", "0", "0"},
[411511] = {411511, 11015, 12, 6, "0", "0", "Training\u{0020}is\u{0020}so\u{0020}fun!", "訓練おもしろーい！", "訓練真開心啊！", "0", "训练真开心啊！", "0", "cv_lin_9", "0", "0"},
[411512] = {411512, 11015, 13, 7, "0", "0", "I\u{0020}can\u{0020}feel\u{0020}my\u{0020}talent\u{0020}waking\u{0020}up!", "あたしの才能が開花しちゃう！", "我的才能，正在蘇醒~", "0", "我的才能，正在苏醒~", "0", "cv_lin_10", "0", "0"},
[411513] = {411513, 11015, 14, 8, "0", "0", "Surprised?\u{0020}Haha,\u{0020}this\u{0020}is\u{0020}what\u{0020}I\u{0020}look\u{0020}like\u{0020}when\u{0020}I'm\u{0020}at\u{0020}full\u{0020}power!\u{0020}I'm\u{0020}invincible\u{0020}now!", "びっくりしたー？ふっふーん。これがパワー全開のあたしだよ！もはや完全無敵だあ！", "嚇了一跳吧？哼哼，這就是我火力全開後的模樣！我已經，戰無不勝啦！", "0", "吓了一跳吧？哼哼，这就是我火力全开后的模样！我已经，战无不胜啦！", "0", "cv_lin_11", "0", "0"},
[411514] = {411514, 11015, 15, 9, "0", "0", "Eh?!\u{0020}How\u{0020}did\u{0020}I\u{0020}do\u{0020}that?", "え？どうやったの！？", "欸？！怎麼做到的？", "0", "诶？！怎么做到的？", "0", "cv_lin_12", "0", "0"},
[411515] = {411515, 11015, 16, 10, "0", "0", "The\u{0020}invincible\u{0020}genius\u{0020}has\u{0020}arrived!", "無敵の天才さまの登場だ！", "無敵的天才來啦！", "0", "无敌的天才来啦！", "0", "cv_lin_13", "0", "0"},
[411516] = {411516, 11015, 17, 11, "0", "0", "Perfect\u{0020}victory?\u{0020}Did\u{0020}I\u{0020}do\u{0020}that?—Ahem,\u{0020}well,\u{0020}of\u{0020}course,\u{0020}I'm\u{0020}a\u{0020}genius!", "完全勝利…？あたしが…？オホン！当然だよね、天才なんだもん！", "完美勝利…？我做到的…？——咳咳！這是當然的，我可是天才嘛！", "0", "完美胜利…？我做到的…？——咳咳！这是当然的，我可是天才嘛！", "0", "cv_lin_14", "0", "0"},
[411517] = {411517, 11015, 18, 12, "0", "0", "I\u{0020}never\u{0020}thought\u{0020}I'd\u{0020}make\u{0020}a\u{0020}mistake...", "この天才がミスをするなんてー！", "沒想到，我這名天才，也會有失誤的時候啊……", "0", "没想到，我这名天才，也会有失误的时候啊……", "0", "cv_lin_15", "0", "0"},
[411518] = {411518, 11015, 19, 13, "0", "0", "Ugh...\u{0020}a\u{0020}mistake...\u{0020}I-I\u{0020}did\u{0020}it\u{0020}on\u{0020}purpose!", "うぅ…やっちゃった……こ、これはわざとだもん！", "嗚…失誤了…這，這是我故意的！", "0", "呜…失误了…这，这是我故意的！", "0", "cv_lin_16", "0", "0"},
[411519] = {411519, 11015, 20, 14, "0", "0", "I'm\u{0020}not\u{0020}satisfied...\u{0020}I'll\u{0020}win\u{0020}it\u{0020}back\u{0020}next\u{0020}time!", "悔しい……次、次は勝ってみせるから、絶対っ！", "不甘心……下次，下次我會贏回來的，一定！", "0", "不甘心……下次，下次我会赢回来的，一定！", "0", "cv_lin_17", "0", "0"},
