[411601] = {411601, 11016, 2, 2, "0", "0", "Understood,\u{0020}this\u{0020}is\u{0020}part\u{0020}of\u{0020}my\u{0020}duty.\u{0020}No\u{0020}need\u{0020}to\u{0020}be\u{0020}so\u{0020}polite.", "承知しました。もとより私の任務の範疇です。ご遠慮なさらず。", "瞭解，這本就是我的分內之事，您無須客氣。", "0", "了解，这本就是我的分内之事，您无须客气。", "0", "cv_heiyu_2", "0", "0"},
[411602] = {411602, 11016, 3, 3, "0", "0", "Ninja\u{0020}Group,\u{0020}Kurobane.\u{0020}I\u{0020}will\u{0020}be\u{0020}your\u{0020}guard\u{0020}from\u{0020}today\u{0020}onward.\u{0020}I'll\u{0020}stay\u{0020}by\u{0020}your\u{0020}side\u{0020}at\u{0020}all\u{0020}times.", "忍心社、黒羽。今日からナビゲーター殿の護衛として、一歩も離れません。", "忍心社，黑羽，從今天開始擔任您的護衛，我會寸步不離地守候在您周圍的。", "0", "忍心社，黑羽，从今天开始担任您的护卫，我会寸步不离地守候在您周围的。", "0", "cv_heiyu_1", "0", "0"},
[411603] = {411603, 11016, 4, 4, "0", "idle", "My\u{0020}job\u{0020}is\u{0020}not\u{0020}to\u{0020}monitor\u{0020}you\u{0020}but\u{0020}to\u{0020}protect\u{0020}you.\u{0020}Please\u{0020}don't\u{0020}misunderstand\u{0020}that.", "ナビゲーター殿。私の役目は監視ではなく、護衛です。これだけは、誤解しないでいただきたい。", "領航，我的職責並不是監視您，而是保護您。只有這點，請不要弄錯。", "0", "领航，我的职责并不是监视您，而是保护您。只有这点，请不要弄错。", "0", "cv_heiyu_3", "0", "0"},
[411604] = {411604, 11016, 5, 4, "0", "idle", "I\u{0020}don't\u{0020}know\u{0020}any\u{0020}flashy\u{0020}ninjutsu,\u{0020}and\u{0020}my\u{0020}assassination\u{0020}skills\u{0020}are\u{0020}just\u{0020}so-so.\u{0020}But\u{0020}I\u{0020}assure\u{0020}you,\u{0020}while\u{0020}you're\u{0020}in\u{0020}my\u{0020}sight,\u{0020}you\u{0020}won't\u{0020}be\u{0020}in\u{0020}danger.", "奇妙な忍術はできませんし、暗殺の技も未熟ですが、私の目が黒いうちは、ナビゲーター殿を危険を晒すようなことはないと、保証します。", "我不會那些光怪陸離的忍術，至於刺殺的技藝，也只是一知半解。不過，我向您保證，在我的視野範圍內，您不會有任何危險。", "0", "我不会那些光怪陆离的忍术，至于刺杀的技艺，也只是一知半解。不过，我向您保证，在我的视野范围内，您不会有任何危险。", "0", "cv_heiyu_4", "0", "0"},
[411605] = {411605, 11016, 6, 4, "0", "idle", "Is\u{0020}Captain\u{0020}Gourai\u{0020}on\u{0020}a\u{0020}mission?\u{0020}That's\u{0020}a\u{0020}shame;\u{0020}I\u{0020}wanted\u{0020}to\u{0020}learn\u{0020}some\u{0020}combat\u{0020}techniques\u{0020}from\u{0020}her.", "轟雷隊長は、任務でご不在なのですか？戦闘のコツを教えて頂きたかったのですが、残念です。", "轟雷隊長是去外出執行任務了嗎？真遺憾，我本來想向她學習一些戰鬥的技巧呢。", "0", "轰雷队长是去外出执行任务了吗？真遗憾，我本来想向她学习一些战斗的技巧呢。", "0", "cv_heiyu_29", "0", "0"},
[411606] = {411606, 11016, 7, 5, "1_》_0_0.8", "level1", "I'm\u{0020}not\u{0020}loyal\u{0020}to\u{0020}AEGIS...\u{0020}it's\u{0020}just\u{0020}a\u{0020}fair\u{0020}trade.\u{0020}They\u{0020}provide\u{0020}shelter\u{0020}for\u{0020}me,\u{0020}and\u{0020}I\u{0020}serve\u{0020}them\u{0020}in\u{0020}return.", "私はアイギスに忠誠を誓った訳ではなく、取引をしただけです。彼らは黒羽に住処を提供し、その対価として、私は任務を果たすのです。", "我並不是效忠於艾吉斯…只是平等交易罷了。他們為“黑羽”提供了庇佑的住所，而我為他們服務。", "0", "我并不是效忠于艾吉斯…只是平等交易罢了。他们为“黑羽”提供了庇佑的住所，而我为他们服务。", "0", "cv_heiyu_30", "0", "0"},
[411607] = {411607, 11016, 8, 5, "1_》_0_0.8", "level1", "Is\u{0020}there\u{0020}any\u{0020}special\u{0020}meaning\u{0020}behind\u{0020}what\u{0020}you're\u{0020}doing?", "これは、何か特別な意味があるのですか？", "您這樣做，有什麼特別的含義嗎？", "0", "您这样做，有什么特别的含义吗？", "0", "cv_heiyu_5", "0", "0"},
[411608] = {411608, 11016, 9, 5, "1_》_100_1.5", "level2", "I\u{0020}don't\u{0020}get\u{0020}why\u{0020}you\u{0020}want\u{0020}to\u{0020}get\u{0020}closer\u{0020}to\u{0020}me...\u{0020}that's\u{0020}strange.", "主殿の行動が理解できないのですが……私ともっと親しくなりたい？……フフ。変なことをおっしゃいますね。", "我不能理解您的行為…“想和我更加親近一些”？…呵呵，真是奇怪啊。", "0", "我不能理解您的行为…“想和我更加亲近一些”？…呵呵，真是奇怪啊。", "0", "cv_heiyu_6", "0", "0"},
[411609] = {411609, 11016, 10, 5, "1_》_500_2", "level3", "Interested\u{0020}in\u{0020}my\u{0020}past?\u{0020}Well,\u{0020}technically\u{0020}I'm\u{0020}supposed\u{0020}to\u{0020}keep\u{0020}it\u{0020}secret,\u{0020}but\u{0020}if\u{0020}you\u{0020}want\u{0020}to\u{0020}know...\u{0020}I'll\u{0020}tell\u{0020}you\u{0020}everything.", "私の過去に興味があるのですか？掟は秘密にしなければならないのですが……もし主殿が知りたいのであれば……全てお話しします。", "領航，您對我的過去感興趣嗎？雖然按照規定應該是要對您保密的…不過，如果您想知道的話……我會把您想知道的，都告訴您的。", "0", "领航，您对我的过去感兴趣吗？虽然按照规定应该是要对您保密的…不过，如果您想知道的话……我会把您想知道的，都告诉您的。", "0", "cv_heiyu_7", "0", "0"},
[411610] = {411610, 11016, 11, 5, "1_》_1000_2.5", "level4", "It\u{0020}seems\u{0020}I\u{0020}have\u{0020}to\u{0020}admit\u{0020}it.\u{0020}You\u{0020}really\u{0020}are\u{0020}different\u{0020}from\u{0020}the\u{0020}others.\u{0020}You\u{0020}don't\u{0020}treat\u{0020}me\u{0020}like\u{0020}a\u{0020}tool\u{0020}but\u{0020}like\u{0020}a\u{0020}person.", "……認めざるを得ないようですね。主殿は、確かに他の人とは違って、私を偏見の目で見ることがありませんでした。目的達成のための道具ではなく、自分と同じ「人間」として見てくださったのですね。", "…是該承認這一點了。領…領航，您的確和其他人不一樣。從您身上，我感受不到其他人的偏見……您並沒有把我視為達成目的的道具，而是當做同您一樣的“人”對待。", "0", "…是该承认这一点了。领…领航，您的确和其他人不一样。从您身上，我感受不到其他人的偏见……您并没有把我视为达成目的的道具，而是当做同您一样的“人”对待。", "0", "cv_heiyu_8", "0", "0"},
[411611] = {411611, 11016, 12, 6, "0", "0", "Thank\u{0020}you.", "感謝します。", "感謝。", "0", "感谢。", "0", "cv_heiyu_9", "0", "0"},
[411612] = {411612, 11016, 13, 7, "0", "0", "My\u{0020}arrows\u{0020}will\u{0020}pierce\u{0020}through\u{0020}your\u{0020}enemies.", "主殿の敵を貫く矢となります。", "箭矢，將貫穿您的敵人。", "0", "箭矢，将贯穿您的敌人。", "0", "cv_heiyu_10", "0", "0"},
[411613] = {411613, 11016, 14, 8, "0", "0", "You\u{0020}gave\u{0020}me\u{0020}love.\u{0020}Whether\u{0020}it's\u{0020}friendship,\u{0020}family,\u{0020}or\u{0020}even\u{0020}sympathy...\u{0020}I'll\u{0020}repay\u{0020}you\u{0020}with\u{0020}loyalty.\u{0020}That's\u{0020}my\u{0020}code.", "主殿は、私に愛をくださいました。たとえその愛が友情であろうと、愛情であろうと……同情であっても……私は忠誠をもってお応えします。これが黒羽のやり方です。", "您…給予了我愛。無論這份愛是友情、是親情、是愛情，哪怕是同情…我都會用忠誠回報您。這就是“黑羽”的信條。", "0", "您…给予了我爱。无论这份爱是友情、是亲情、是爱情，哪怕是同情…我都会用忠诚回报您。这就是“黑羽”的信条。", "0", "cv_heiyu_11", "0", "0"},
[411614] = {411614, 11016, 15, 9, "0", "0", "I'll\u{0020}make\u{0020}your\u{0020}enemies\u{0020}suffer\u{0020}more.", "我らが敵に、もっと苦痛を与えましょう。", "讓您的敵人，更加痛苦吧。", "0", "让您的敌人，更加痛苦吧。", "0", "cv_heiyu_12", "0", "0"},
[411615] = {411615, 11016, 16, 10, "0", "0", "We've\u{0020}reached\u{0020}the\u{0020}destination.", "目的地到着。", "抵達目的地。", "0", "抵达目的地。", "0", "cv_heiyu_13", "0", "0"},
[411616] = {411616, 11016, 17, 11, "0", "0", "For\u{0020}you,\u{0020}I'll\u{0020}clear\u{0020}every\u{0020}obstacle.", "主殿の前に立ちはだかる全てを排除します。", "為了領航，我會掃清所有的阻礙。", "0", "为了领航，我会扫清所有的阻碍。", "0", "cv_heiyu_14", "0", "0"},
[411617] = {411617, 11016, 18, 12, "0", "0", "Tsk...\u{0020}such\u{0020}a\u{0020}troublesome\u{0020}enemy.", "ふう……しつこい敵でした。", "嘁…真是難纏的敵人。", "0", "嘁…真是难缠的敌人。", "0", "cv_heiyu_15", "0", "0"},
[411618] = {411618, 11016, 19, 13, "0", "0", "As\u{0020}long\u{0020}as\u{0020}you're\u{0020}safe,\u{0020}that's\u{0020}all\u{0020}that\u{0020}matters.", "主殿が無事で何よりです。", "只要您平安無事就好。", "0", "只要您平安无事就好。", "0", "cv_heiyu_16", "0", "0"},
[411619] = {411619, 11016, 20, 14, "0", "0", "I'll\u{0020}make\u{0020}sure\u{0020}you\u{0020}leave\u{0020}the\u{0020}battlefield\u{0020}safely.", "主殿を安全な場所までお連れします……！", "我會讓您安全離開戰場的。", "0", "我会让您安全离开战场的。", "0", "cv_heiyu_17", "0", "0"},
[411620] = {411620, 11016, 21, 15, "0", "0", "Disappear\u{0020}into\u{0020}the\u{0020}night.", "闇夜に散れ。", "消失在黑夜中吧。", "0", "消失在黑夜中吧。", "0", "cv_heiyu_18", "0", "0"},
[411621] = {411621, 11016, 23, 16, "0", "0", "One\u{0020}strike.", "一撃。", "一擊。", "0", "一击。", "0", "cv_heiyu_19", "0", "0"},
[411622] = {411622, 11016, 24, 17, "0", "0", "Behind\u{0020}you!", "隙あり！", "在你的身後！", "0", "在你的身后！", "0", "cv_heiyu_21", "0", "0"},
[411623] = {411623, 11016, 26, 19, "0", "0", "I'm\u{0020}sorry...\u{0020}I\u{0020}can't\u{0020}protect\u{0020}you\u{0020}anymore...", "すみません…もう守れない……", "很抱歉…沒法再保護您了……", "0", "很抱歉…没法再保护您了……", "0", "cv_heiyu_20", "0", "0"},
