[411631] = {411631, 11016, 34, 26, "0", "0", "While\u{0020}you\u{0020}were\u{0020}out,\u{0020}did\u{0020}you\u{0020}run\u{0020}into\u{0020}anything\u{0020}suspicious?", "主殿。外出先で何か変わったことはなかったですか？", "領航，您外出的這段時間，有遇到可疑的事嗎？", "0", "领航，您外出的这段时间，有遇到可疑的事吗？", "0", "cv_heiyu_31", "0", "0"},
[411632] = {411632, 11016, 35, 27, "0", "0", "Let's\u{0020}go,\u{0020}but\u{0020}don't\u{0020}leave\u{0020}my\u{0020}side.", "主殿、参りましょう。くれぐれも私のそばから離れぬように。", "領航，出發吧。不過，請不要離開我的身邊。", "0", "领航，出发吧。不过，请不要离开我的身边。", "0", "cv_heiyu_33", "0", "0"},
[411633] = {411633, 11016, 36, 28, "0", "0", "Sharpen\u{0020}your\u{0020}skills\u{0020}so\u{0020}I\u{0020}can\u{0020}protect\u{0020}you\u{0020}better.", "主殿を守るため、さらに腕前を磨かねば。", "磨煉技藝，才能更好的保護您。", "0", "磨炼技艺，才能更好的保护您。", "0", "cv_heiyu_34", "0", "0"},
