[411700] = {411700, 11017, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_fuluola_32", "0", "0"},
[411701] = {411701, 11017, 2, 2, "0", "0", "Received,\u{0020}I\u{0020}guarantee\u{0020}I\u{0020}won't\u{0020}disappoint\u{0020}you.", "承知いたしました。あなた様のご期待に応えてみせます。", "收到，芙蘿拉保證不會讓您失望的。", "0", "收到，芙萝拉保证不会让您失望的。", "0", "cv_fuluola_2", "0", "0"},
[411702] = {411702, 11017, 3, 3, "0", "0", "Captain\u{0020}of\u{0020}Danube's\u{0020}First\u{0020}Guards\u{0020}Squad,\u{0020}Flora.\u{0020}Eh?\u{0020}You're\u{0020}asking\u{0020}why\u{0020}we\u{0020}wear\u{0020}maid\u{0020}outfits?", "ダニューブ第一親衛班班長、フローラと申します。え？どうして親衛班がメイド服なのか、ですか？", "多瑙第一親衛班隊長，芙蘿拉。欸？您問為什麼親衛隊要穿女僕裝？", "0", "多瑙第一亲卫班队长，芙萝拉。哎？您问为什么亲卫队要穿女仆装？", "0", "cv_fuluola_1", "0", "0"},
[411703] = {411703, 11017, 4, 4, "0", "idle", "The\u{0020}Ark\u{0020}is\u{0020}sailing\u{0020}smoothly.\u{0020}Shall\u{0020}I\u{0020}make\u{0020}you\u{0020}some\u{0020}tea?", "方舟の運航は順調です。暫くゆっくりなさってください。そうだ、お茶を淹れましょうか？", "方舟正在平穩地行駛，看來暫時沒有什麼要忙的，要為您泡杯茶嗎？", "0", "方舟正在平稳地行驶，看来暂时没有什么要忙的，要为您泡杯茶吗？", "0", "cv_fuluola_3", "0", "0"},
[411704] = {411704, 11017, 5, 4, "0", "idle", "Did\u{0020}my\u{0020}weapon\u{0020}scare\u{0020}you?\u{0020}Sorry,\u{0020}I'll\u{0020}put\u{0020}it\u{0020}away\u{0020}right\u{0020}now.", "わたくしの武器で驚かせてしまったでしょうか？申し訳ありません。今すぐ収めます。", "我的武器嚇到您了嗎？很抱歉，現在就收起來。", "0", "我的武器吓到您了吗？很抱歉，现在就收起来。", "0", "cv_fuluola_4", "0", "0"},
[411705] = {411705, 11017, 6, 4, "0", "idle", "As\u{0020}the\u{0020}team\u{0020}leader,\u{0020}I\u{0020}should\u{0020}set\u{0020}an\u{0020}example.\u{0020}If\u{0020}I\u{0020}get\u{0020}the\u{0020}chance,\u{0020}I'd\u{0020}love\u{0020}to\u{0020}learn\u{0020}from\u{0020}Miss\u{0020}Julius.", "わたくしは親衛班の班長として、常に模範とならなければいけません。今度、ユリウスさんにご指導いただこうと思います。", "身為親衛班的隊長，我更應該要起到表率作用。有機會的話，我想要向朱利烏斯小姐請教一下。", "0", "身为亲卫班的队长，我更应该要起到表率作用。有机会的话，我想要向朱利乌斯小姐请教一下。", "0", "cv_fuluola_29", "0", "0"},
[411706] = {411706, 11017, 7, 5, "1_》_0_0.8", "level1", "The\u{0020}First\u{0020}Guard\u{0020}Team's\u{0020}job\u{0020}is\u{0020}to\u{0020}ensure\u{0020}the\u{0020}Ark\u{0020}sails\u{0020}safely.\u{0020}We're\u{0020}also\u{0020}seen\u{0020}as\u{0020}representatives\u{0020}of\u{0020}Danube's\u{0020}Drivers,\u{0020}so\u{0020}it's\u{0020}important\u{0020}to\u{0020}maintain\u{0020}a\u{0020}good\u{0020}image.", "第一親衛班の最も重要な任務はダニューブの象徴、方舟を守ることです。また、わたくしたちはダニューブのドライバーの代表として見られることが多いですから、自身のイメージを維持することも非常に重要です。", "第一親衛班的首要任務是確保多瑙的象徵——方舟能夠安全地行駛。當然，我們本身也常常被當做是多瑙駕駛員的代表，所以維持自身形象是非常有必要的。", "0", "第一亲卫班的首要任务是确保多瑙的象征——方舟能够安全地行驶。当然，我们本身也常常被当做是多瑙驾驶员的代表，所以维持自身形象是非常有必要的。", "0", "cv_fuluola_5", "0", "0"},
[411707] = {411707, 11017, 8, 5, "1_》_0_0.8", "level1", "The\u{0020}patrol\u{0020}mission\u{0020}is\u{0020}complete.\u{0020}I'm\u{0020}ready\u{0020}for\u{0020}your\u{0020}orders.", "はい。本日の巡回は終了しました。何なりとお申しつけください。", "嗯，今天的巡視任務已經結束了，隨時聽從您的調遣。", "0", "嗯，今天的巡视任务已经结束了，随时听从您的调遣。", "0", "cv_fuluola_30", "0", "0"},
[411708] = {411708, 11017, 9, 5, "1_》_100_1.5", "level2", "My\u{0020}parents?\u{0020}They're\u{0020}not\u{0020}just\u{0020}the\u{0020}ones\u{0020}who\u{0020}raised\u{0020}me;\u{0020}they're\u{0020}who\u{0020}I\u{0020}aspire\u{0020}to\u{0020}be.\u{0020}As\u{0020}a\u{0020}child\u{0020}of\u{0020}the\u{0020}guards,\u{0020}I\u{0020}have\u{0020}to\u{0020}do\u{0020}better\u{0020}than\u{0020}anyone.", "わたくしの両親ですか？はい。わたくしを育ててくれただけでなく、わたくしの目標でもあります。親衛班の家系で生まれたわたくしは、他の隊員以上に責務を全うしなければなりません。でなければ、皆様の期待を裏切ることになってしまいます。", "我的父母？嗯，她們不光光是養育我的人，同時還是我努力想要成為的人。作為親衛的後代，我必須要做得比其他隊員更好。只有這樣，才不會辜負大家的期待。", "0", "我的父母？嗯，她们不光光是养育我的人，同时还是我努力想要成为的人。作为亲卫的后代，我必须要做得比其他队员更好。只有这样，才不会辜负大家的期待。", "0", "cv_fuluola_6", "0", "0"},
[411709] = {411709, 11017, 10, 5, "1_》_500_2", "level3", "I\u{0020}really\u{0020}envy\u{0020}Miss\u{0020}Julius\u{0020}and\u{0020}Miss\u{0020}Charlissa.\u{0020}If\u{0020}I\u{0020}weren't\u{0020}a\u{0020}guard,\u{0020}I'd\u{0020}want\u{0020}to\u{0020}fight\u{0020}by\u{0020}your\u{0020}side\u{0020}like\u{0020}them.\u{0020}But\u{0020}for\u{0020}now,\u{0020}my\u{0020}mission\u{0020}is\u{0020}to\u{0020}protect\u{0020}the\u{0020}Ark.", "ユリウスさんとチャリサーさんが羨ましいです。もしわたくしも親衛隊でなければ、彼女たちのようにあなた様と共に戦いたい……。ですがわたくしには為すべきことが、ダニューブの方舟を守るという使命があるのです。", "真是羡慕朱利烏斯和查麗莎小姐啊……如果我不是親衛的話，也想像她們一樣和您並肩作戰。但是，我現在有更重要的東西要去做，守住多瑙的方舟是我的使命……", "0", "真是羡慕朱利乌斯和查丽莎小姐啊……如果我不是亲卫的话，也想像她们一样和您并肩作战。但是，我现在有更重要的东西要去做，守住多瑙的方舟是我的使命……", "0", "cv_fuluola_7", "0", "0"},
[411710] = {411710, 11017, 11, 5, "1_》_1000_2.5", "level4", "Even\u{0020}though\u{0020}I\u{0020}can't\u{0020}join\u{0020}you\u{0020}on\u{0020}expeditions,\u{0020}I'll\u{0020}protect\u{0020}your\u{0020}home\u{0020}and\u{0020}that\u{0020}of\u{0020}your\u{0020}comrades.\u{0020}If\u{0020}you\u{0020}ever\u{0020}feel\u{0020}tired,\u{0020}you\u{0020}can\u{0020}always\u{0020}come\u{0020}back\u{0020}and\u{0020}rest.\u{0020}I'll\u{0020}be\u{0020}here\u{0020}waiting.", "あなたと共に遠征はできませんが、親衛班であるわたくしだからこそ、できることがあります。ご安心ください。あなた様と仲間の皆様の帰る場所は、わたくしが必ずお守りします。もし疲れたら、いつでも帰ってきてください。いつでもここでお待ちしております。", "雖然無法和您一同遠征，但也有身為親衛的我能做的事。無論您身處何方都還請放心，我一定會守住您和您同伴們的歸所。如果有一天您感到疲憊了也隨時都能回來休息一段時間，我會在這裡等著您的。", "0", "虽然无法和您一同远征，但也有身为亲卫的我能做的事。无论您身处何方都还请放心，我一定会守住您和您同伴们的归所。如果有一天您感到疲惫了也随时都能回来休息一段时间，我会在这里等着您的。", "0", "cv_fuluola_8", "0", "0"},
[411711] = {411711, 11017, 12, 6, "0", "0", "I\u{0020}feel\u{0020}stronger\u{0020}now.", "ふぅ……力が増したようです。", "呼~力氣變大了呢。", "0", "呼~力气变大了呢。", "0", "cv_fuluola_9", "0", "0"},
[411712] = {411712, 11017, 13, 7, "0", "0", "Everything\u{0020}is\u{0020}for\u{0020}Danube.", "すべてはダニューブのために。", "一切都是為了多瑙。", "0", "一切都是为了多瑙。", "0", "cv_fuluola_10", "0", "0"},
[411713] = {411713, 11017, 14, 8, "0", "0", "I\u{0020}feel\u{0020}so\u{0020}refreshed...\u{0020}It's\u{0020}like\u{0020}taking\u{0020}a\u{0020}stroll\u{0020}through\u{0020}a\u{0020}spring\u{0020}garden.", "ああ、なんと清らかな……春の庭園にいるかのようです。", "呼啊~神清氣爽……簡直就像是漫步在春天的花園中一樣。", "0", "呼啊~神清气爽……简直就像是漫步在春天的花园中一样。", "0", "cv_fuluola_11", "0", "0"},
[411714] = {411714, 11017, 15, 9, "0", "0", "Good,\u{0020}let's\u{0020}keep\u{0020}it\u{0020}up.", "いいですね。このまま続けましょう。", "很好，就這樣繼續下去吧。", "0", "很好，就这样继续下去吧。", "0", "cv_fuluola_12", "0", "0"},
[411715] = {411715, 11017, 16, 10, "0", "0", "Let's\u{0020}finish\u{0020}them\u{0020}off\u{0020}all\u{0020}at\u{0020}once.", "はい。一気に倒しましょう。", "嗯，一口氣解決它們吧。", "0", "嗯，一口气解决它们吧。", "0", "cv_fuluola_13", "0", "0"},
[411716] = {411716, 11017, 17, 11, "0", "0", "Thanks\u{0020}to\u{0020}everyone's\u{0020}help,\u{0020}the\u{0020}mission\u{0020}was\u{0020}a\u{0020}success.", "素晴らしい結果です。皆様のお陰ですね。", "多虧大家的協助，此次任務圓滿完成了呢。", "0", "多亏大家的协助，此次任务圆满完成了呢。", "0", "cv_fuluola_14", "0", "0"},
[411717] = {411717, 11017, 18, 12, "0", "0", "Mission\u{0020}complete.\u{0020}You're\u{0020}unharmed,\u{0020}right?", "任務完了です。ナビゲーター様、お怪我はありませんか？", "任務完成，領航，您沒有受傷吧？", "0", "任务完成，领航，您没有受伤吧？", "0", "cv_fuluola_15", "0", "0"},
[411718] = {411718, 11017, 19, 13, "0", "0", "Stop\u{0020}pursuing;\u{0020}preserving\u{0020}our\u{0020}forces\u{0020}is\u{0020}more\u{0020}important\u{0020}than\u{0020}wiping\u{0020}out\u{0020}the\u{0020}enemy.", "追撃はやめましょう、敵の殲滅より、戦力の温存が大事です。", "放棄追擊吧，比起殲滅敵人，保全戰力才是重要的。", "0", "放弃追击吧，比起歼灭敌人，保全战力才是重要的。", "0", "cv_fuluola_16", "0", "0"},
[411719] = {411719, 11017, 20, 14, "0", "0", "Did\u{0020}we\u{0020}fail?\u{0020}We\u{0020}can't\u{0020}let\u{0020}them\u{0020}take\u{0020}the\u{0020}Ark...", "失敗、ですか……。方舟は絶対に守ってみせます。", "失敗了嗎？…方舟絕對不能交給它們……", "0", "失败了吗？…方舟绝对不能交给它们……", "0", "cv_fuluola_17", "0", "0"},
