[411802] = {411802, 11018, 3, 3, "0", "0", "Hmph...\u{0020}A\u{0020}Human?\u{0020}Or\u{0020}maybe\u{0020}not?\u{0020}Navigator,\u{0020}your\u{0020}scent\u{0020}is\u{0020}pretty\u{0020}unique.\u{0020}But\u{0020}I\u{0020}don't\u{0020}mind\u{0020}it.", "ん……人間か？いや、そうとも言い切れないか。……ナビゲーターだって？珍しい匂いがするな。嫌じゃないけど。", "哼…人類嗎？不，好像又不完全是。領航，你的氣味還真是少見啊，不過，我並不討厭。", "0", "哼…人类吗？不，好像又不完全是。领航，你的气味还真是少见啊，不过，我并不讨厌。", "0", "cv_yin_1", "0", "0"},
[411803] = {411803, 11018, 4, 4, "0", "idle", "Is\u{0020}it\u{0020}just\u{0020}me,\u{0020}or\u{0020}does\u{0020}it\u{0020}feel\u{0020}like\u{0020}everyone's\u{0020}staring\u{0020}at\u{0020}me...?", "気のせいか？なんだかみんなに見られているような……", "是我的錯覺嗎？總感覺好像大家都在盯著我看……", "0", "是我的错觉吗？总感觉好像大家都在盯着我看……", "0", "cv_yin_3", "0", "0"},
[411804] = {411804, 11018, 5, 4, "0", "idle", "If\u{0020}it\u{0020}weren't\u{0020}for\u{0020}you,\u{0020}I\u{0020}wouldn't\u{0020}want\u{0020}to\u{0020}stay\u{0020}here\u{0020}even\u{0020}for\u{0020}a\u{0020}second...", "お前のためじゃなかったら、もう一秒もここに居たくない……", "如果不是看在你的面子上，我是一秒也不想在這裡待下去了……", "0", "如果不是看在你的面子上，我是一秒也不想在这里待下去了……", "0", "cv_yin_4", "0", "0"},
[411805] = {411805, 11018, 6, 4, "0", "idle", "Mizo\u{0020}is\u{0020}a\u{0020}good\u{0020}companion.\u{0020}If\u{0020}I\u{0020}die\u{0020}in\u{0020}battle\u{0020}one\u{0020}day,\u{0020}I'll\u{0020}entrust\u{0020}her\u{0020}with\u{0020}protecting\u{0020}the\u{0020}tribe.", "渠はいい相棒だ。もし僕が戦死するようなことがあれば、同胞を守る任務は彼女に託すことができる。", "渠是個不錯的夥伴呢。如果有一天我戰死了的話，保護族人的任務就交給她了。", "0", "渠是个不错的伙伴呢。如果有一天我战死了的话，保护族人的任务就交给她了。", "0", "cv_yin_29", "0", "0"},
[411806] = {411806, 11018, 7, 5, "1_》_0_0.8", "level1", "Stop\u{0020}it,\u{0020}I'm\u{0020}not\u{0020}a\u{0020}puppy.", "ふざけるな。僕は子犬じゃないぞ。", "別鬧了，我可不是小狗。", "0", "别闹了，我可不是小狗。", "0", "cv_yin_30", "0", "0"},
[411807] = {411807, 11018, 8, 5, "1_》_0_0.8", "level1", "!\u{0020}-\u{0020}Wuwuwu\u{0020}--", "うわっ！……グルルル。", "！—嗚嗚嗚——", "0", "！—呜呜呜——", "0", "cv_yin_5", "0", "0"},
[411808] = {411808, 11018, 9, 5, "1_》_100_1.5", "level2", "My\u{0020}kin?\u{0020}Yeah,\u{0020}they're\u{0020}all\u{0020}lovely.\u{0020}They're\u{0020}my\u{0020}only\u{0020}emotional\u{0020}support\u{0020}left\u{0020}in\u{0020}this\u{0020}world.\u{0020}But...\u{0020}as\u{0020}a\u{0020}warrior,\u{0020}I\u{0020}can't\u{0020}face\u{0020}living\u{0020}with\u{0020}them\u{0020}anymore.", "僕の同族？ああ、僕が生きる唯一の心の支えになっている、可愛い子たちだ。でも……戦士になってしまった僕は、もうあの子達と一緒に暮らすことはできない。", "我的同族？嗯，她們都是可愛的孩子，是我活在這個世界上唯一的精神寄託。但是……作為戰士的我已經沒有臉面再和她們生活在一起了。", "0", "我的同族？嗯，她们都是可爱的孩子，是我活在这个世界上唯一的精神寄托。但是……作为战士的我已经没有脸面再和她们生活在一起了。", "0", "cv_yin_6", "0", "0"},
[411809] = {411809, 11018, 10, 5, "1_》_500_2", "level3", "Humans?\u{0020}Some\u{0020}might\u{0020}catch\u{0020}my\u{0020}interest,\u{0020}but\u{0020}your\u{0020}lifespans\u{0020}are\u{0020}way\u{0020}too\u{0020}short.\u{0020}...Human\u{0020}Navigator,\u{0020}do\u{0020}you\u{0020}understand?\u{0020}I\u{0020}just\u{0020}don't\u{0020}want\u{0020}to\u{0020}lose\u{0020}someone\u{0020}I\u{0020}love\u{0020}again.", "僕に興味を持ってくれる人間もいるけど、お前たちの寿命はあまりにも短すぎる。……人間のナビゲーター、お前は分かってくれるか？僕はただ二度と、愛しいものと別れたくないだけなんだ。", "人類？雖然也有個別也能讓我提起興趣的傢伙，但你們人類的壽命實在是過於短暫了。……人類的領航啊，你能理解嗎？我只是不想再和心愛的人分開罷了。", "0", "人类？虽然也有个别也能让我提起兴趣的家伙，但你们人类的寿命实在是过于短暂了。……人类的领航啊，你能理解吗？我只是不想再和心爱的人分开罢了。", "0", "cv_yin_7", "0", "0"},
[411810] = {411810, 11018, 11, 5, "1_》_1000_2.5", "level4", "The\u{0020}moon,\u{0020}it's\u{0020}unsettling,\u{0020}isn't\u{0020}it?\u{0020}The\u{0020}Sin\u{0020}that\u{0020}destroyed\u{0020}my\u{0020}homeland\u{0020}is\u{0020}up\u{0020}there,\u{0020}right?\u{0020}I\u{0020}don't\u{0020}get\u{0020}how\u{0020}you\u{0020}humans\u{0020}can\u{0020}admire\u{0020}that\u{0020}thing...\u{0020}But\u{0020}if\u{0020}I'm\u{0020}with\u{0020}you,\u{0020}I\u{0020}guess\u{0020}it's\u{0020}fine.", "月…か。何とも不安を誘う天体だ。僕の故郷を滅ぼした原罪たちがあそこにいるのだろう？全く、お前ら人間は、よくあんなものを見て楽しめるな。……まあ、お前と一緒だったら、少しはマシだが。", "月亮，真是令人不安的天體啊。摧毀了我故鄉的原罪就居住在上面吧？真是搞不懂你們人類怎麼還有閒心去欣賞那種東西……不過，如果是和你在一起的話也無所謂了。", "0", "月亮，真是令人不安的天体啊。摧毁了我故乡的原罪就居住在上面吧？真是搞不懂你们人类怎么还有闲心去欣赏那种东西……不过，如果是和你在一起的话也无所谓了。", "0", "cv_yin_8", "0", "0"},
[411811] = {411811, 11018, 12, 6, "0", "0", "Hmm,\u{0020}I've\u{0020}made\u{0020}some\u{0020}progress.", "よし。少しは精進できたか。", "嗯，稍微進步一些了呢。", "0", "嗯，稍微进步一些了呢。", "0", "cv_yin_9", "0", "0"},
[411812] = {411812, 11018, 13, 7, "0", "0", "I\u{0020}have\u{0020}to\u{0020}become\u{0020}stronger\u{0020}before\u{0020}that\u{0020}thing\u{0020}returns.", "あいつがもう一度くる前にもっと強くならないと。", "必須得在那個傢伙再次襲來前變得更強。", "0", "必须得在那个家伙再次袭来前变得更强。", "0", "cv_yin_10", "0", "0"},
[411813] = {411813, 11018, 14, 8, "0", "0", "Thanks\u{0020}to\u{0020}you,\u{0020}I\u{0020}feel\u{0020}like\u{0020}I've\u{0020}surpassed\u{0020}my\u{0020}limits.\u{0020}Good,\u{0020}let's\u{0020}keep\u{0020}pushing\u{0020}higher.", "お前のおかげで、僕自身の限界を突破することができた。ありがとう。さらなる高みへと邁進しよう。", "借由你的力量，我似乎已經突破自身的極限了呢。很好，接下來繼續向著更高處邁進吧。", "0", "借由你的力量，我似乎已经突破自身的极限了呢。很好，接下来继续向着更高处迈进吧。", "0", "cv_yin_11", "0", "0"},
