[411902] = {411902, 11019, 3, 3, "0", "0", "Ta-da!\u{0020}Tenten\u{0020}from\u{0020}the\u{0020}Fledgeling\u{0020}Eagle\u{0020}Team\u{0020}reporting!\u{0020}Are\u{0020}you\u{0020}the\u{0020}Navigator?\u{0020}Here,\u{0020}have\u{0020}a\u{0020}cake\u{0020}I\u{0020}made!", "0", "鏘鏘！雛鷹小隊成員天天報導！你就是領航嗎？來吃一個我親手做的蛋糕吧！", "0", "锵锵！雏鹰小队成员天天报道！你就是领航吗？来吃一个我亲手做的蛋糕吧！", "0", "cv_tenten_1", "0", "0"},
[411903] = {411903, 11019, 4, 4, "0", "idle", "Navigator!\u{0020}Time\u{0020}to\u{0020}eat!\u{0020}I'll\u{0020}make\u{0020}you\u{0020}some\u{0020}hamburger\u{0020}steak!", "0", "領航！到飯點了，天天給你做漢堡肉吃吧！", "0", "领航！到饭点了，天天给你做汉堡肉吃吧！", "0", "cv_tenten_3", "0", "0"},
[411904] = {411904, 11019, 5, 4, "0", "idle", "Don't\u{0020}like\u{0020}veggies?\u{0020}Picky\u{0020}eaters\u{0020}aren't\u{0020}good\u{0020}kids,\u{0020}Navigator,\u{0020}so\u{0020}finish\u{0020}those\u{0020}greens!", "0", "不喜歡吃蔬菜嗎？挑食的孩子可不是好孩子，領航可要好好吃完這些青菜喔！", "0", "不喜欢吃蔬菜吗？挑食的孩子可不是好孩子，领航可要好好吃完这些青菜哦！", "0", "cv_tenten_4", "0", "0"},
[411905] = {411905, 11019, 6, 4, "0", "idle", "Navigator,\u{0020}you\u{0020}can\u{0020}command\u{0020}us\u{0020}more\u{0020}confidently.\u{0020}Don't\u{0020}worry\u{0020}about\u{0020}me\u{0020}being\u{0020}a\u{0020}Fledgeling\u{0020}Eagle\u{0020}trainee.\u{0020}One\u{0020}day,\u{0020}I'll\u{0020}fight\u{0020}the\u{0020}Sin\u{0020}too.", "0", "領航，請更放心地指揮我們吧，不用顧慮雛鷹小隊實習生的身份。既然成了駕駛員，總有一天要和原罪戰鬥的。", "0", "领航，请更放心地指挥我们吧，不用顾虑雏鹰小队实习生的身份。既然成了驾驶员，总有一天要和原罪战斗的。", "0", "cv_tenten_28", "0", "0"},
[411906] = {411906, 11019, 7, 5, "1_》_0_0.8", "level1", "If\u{0020}we\u{0020}had\u{0020}more\u{0020}ingredients,\u{0020}I\u{0020}could\u{0020}make\u{0020}something\u{0020}new\u{0020}for\u{0020}you\u{0020}every\u{0020}day!", "0", "要是有更多的食材就好了，天天就可以給領航每天都做不同好吃的了！", "0", "要是有更多的食材就好了，天天就可以给领航每天都做不同好吃的了！", "0", "cv_tenten_29", "0", "0"},
