[412000] = {412000, 11020, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_caroline_32", "0", "0"},
[412001] = {412001, 11020, 2, 2, "0", "0", "Eh?\u{0020}Ah!\u{0020}Of\u{0020}course,\u{0020}I'm\u{0020}totally\u{0020}ready\u{0020}for\u{0020}this\u{0020}position!", "0", "誒？啊！嗯！當然沒問題，我完全可以勝任這個位置，我是這麼想的！", "0", "0", "0", "cv_caroline_2", "0", "0"},
[412002] = {412002, 11020, 3, 3, "0", "0", "Greetings,\u{0020}Navigator!\u{0020}I'm\u{0020}Caroline\u{0020}from\u{0020}the\u{0020}Iron\u{0020}Crow!\u{0020}Here's\u{0020}my\u{0020}personal\u{0020}info—don't\u{0020}lose\u{0020}it!", "0", "領航，您好！我是來自鐵鴉小隊的卡洛琳！還有，這是我的個人資料，一定不要弄丟了！", "0", "0", "0", "cv_caroline_1", "0", "0"},
[412003] = {412003, 11020, 4, 4, "0", "idle", "Uh...\u{0020}Growing\u{0020}bigger\u{0020}just\u{0020}to\u{0020}stand\u{0020}here\u{0020}seems\u{0020}weird.\u{0020}\"Everyone\u{0020}does\u{0020}it\u{0020}like\u{0020}this\"?\u{0020}Really?\u{0020}You're\u{0020}not\u{0020}pulling\u{0020}my\u{0020}leg,\u{0020}right?", "0", "呃……巨大化之後卻只是在這裏站著，不會很奇怪嗎？“大家都是這麼做的”……真的？您不會是在騙我吧？", "0", "0", "0", "cv_caroline_3", "0", "0"},
[412004] = {412004, 11020, 5, 4, "0", "idle", "Am\u{0020}I\u{0020}imagining\u{0020}it,\u{0020}or\u{0020}do\u{0020}I\u{0020}feel\u{0020}like\u{0020}I'm\u{0020}becoming\u{0020}invisible\u{0020}the\u{0020}longer\u{0020}I\u{0020}stand\u{0020}here?\u{0020}Must\u{0020}be\u{0020}a\u{0020}trick\u{0020}of\u{0020}the\u{0020}light,\u{0020}right?", "0", "是錯覺嗎……感覺站久了之後，身體在慢慢變透明……一定是錯覺吧，對吧？", "0", "0", "0", "cv_caroline_4", "0", "0"},
[412005] = {412005, 11020, 6, 4, "0", "idle", "Ugh,\u{0020}when\u{0020}will\u{0020}the\u{0020}captain\u{0020}remember\u{0020}anything\u{0020}from\u{0020}the\u{0020}past?\u{0020}So\u{0020}frustrating...", "0", "唉，隊長到底什麼時候才能想起以前的事啊……真是的……", "0", "0", "0", "cv_caroline_29", "0", "0"},
[412006] = {412006, 11020, 7, 5, "1_》_0_0.8", "level1", "Navigator,\u{0020}sometimes\u{0020}I\u{0020}think\u{0020}everyone\u{0020}has\u{0020}a\u{0020}purpose.\u{0020}Even\u{0020}those\u{0020}who\u{0020}seem\u{0020}insignificant\u{0020}belong\u{0020}somewhere.\u{0020}...What?\u{0020}You\u{0020}weren't\u{0020}listening?\u{0020}You\u{0020}missed\u{0020}all\u{0020}that!?", "0", "領航，有時候我會這麼想，誕生於世的人，應該都有他們存在的使命。不管是多麼不起眼的人，也一定能有她能勝任的位置……我是這麼想的…………誒？您沒在聽嗎？難道您從一開始就沒在聽我說話嗎！？", "0", "0", "0", "cv_caroline_30", "0", "0"},
[412007] = {412007, 11020, 8, 5, "1_》_0_0.8", "level1", "Something\u{0020}wrong?", "0", "有什麼事嗎？", "0", "0", "0", "cv_caroline_5", "0", "0"},
[412008] = {412008, 11020, 9, 5, "1_》_100_1.5", "level2", "Danube\u{0020}Drivers\u{0020}are\u{0020}all\u{0020}so\u{0020}unique\u{0020}compared\u{0020}to\u{0020}me...\u{0020}Ah,\u{0020}but\u{0020}that\u{0020}doesn't\u{0020}make\u{0020}me\u{0020}insecure!\u{0020}Being\u{0020}ordinary\u{0020}is\u{0020}the\u{0020}best,\u{0020}that's\u{0020}what\u{0020}I\u{0020}think!", "0", "多瑙支部……應該說艾吉斯的駕駛員，和我不一樣，都有著自己的特色呢……啊，我可不會因此自卑噢！對我而言，普通是最好的了，我是這麼想的！", "0", "0", "0", "cv_caroline_6", "0", "0"},
[412009] = {412009, 11020, 10, 5, "1_》_500_2", "level3", "The\u{0020}captain\u{0020}says\u{0020}I'm\u{0020}perfect\u{0020}for\u{0020}recon\u{0020}because\u{0020}I'm\u{0020}big\u{0020}but\u{0020}don't\u{0020}stand\u{0020}out.\u{0020}Well,\u{0020}she's\u{0020}right...\u{0020}but\u{0020}I\u{0020}wish\u{0020}she'd\u{0020}be\u{0020}more\u{0020}considerate\u{0020}of\u{0020}my\u{0020}feelings.", "0", "隊長說，偵查的時候需要像我這樣巨大化後也沒什麼存在感的駕駛員。雖然是事實……但真希望她說的時候能夠注意下我的個人感受啦。", "0", "0", "0", "cv_caroline_7", "0", "0"},
[412010] = {412010, 11020, 11, 5, "1_》_1000_2.5", "level4", "If\u{0020}it\u{0020}weren't\u{0020}for\u{0020}war,\u{0020}many\u{0020}wouldn't\u{0020}become\u{0020}\"heroes.\"\u{0020}But\u{0020}I\u{0020}believe\u{0020}those\u{0020}heroes\u{0020}just\u{0020}want\u{0020}to\u{0020}return\u{0020}to\u{0020}their\u{0020}ordinary\u{0020}lives.\u{0020}My\u{0020}duty\u{0020}is\u{0020}to\u{0020}help\u{0020}them\u{0020}get\u{0020}back\u{0020}to\u{0020}where\u{0020}they\u{0020}belong...\u{0020}that's\u{0020}what\u{0020}I\u{0020}think.", "0", "如果沒有戰爭，許多人都不會走上“英雄”的道路。但我相信，即使是那些英雄，也一定盼望著“普通”的人生。所以，我的責任一定就是讓那些遠離日常的英雄們，回到她們本該的位置上……我是這麼想的。", "0", "0", "0", "cv_caroline_8", "0", "0"},
[412011] = {412011, 11020, 12, 6, "0", "0", "My\u{0020}sword\u{0020}is\u{0020}getting\u{0020}faster.", "0", "揮劍的速度更快了呢。", "0", "0", "0", "cv_caroline_9", "0", "0"},
[412012] = {412012, 11020, 13, 7, "0", "0", "Oh,\u{0020}another\u{0020}star?", "0", "多、多了一顆星星？", "0", "0", "0", "cv_caroline_10", "0", "0"},
[412013] = {412013, 11020, 14, 8, "0", "0", "Thank\u{0020}you,\u{0020}Navigator...\u{0020}Huh?\u{0020}I\u{0020}won't\u{0020}change,\u{0020}even\u{0020}with\u{0020}this\u{0020}power.\u{0020}I'll\u{0020}stay\u{0020}the\u{0020}same—because\u{0020}I'm\u{0020}me,\u{0020}that's\u{0020}what\u{0020}I\u{0020}believe.", "0", "謝謝您，領航…嗯？我可不會做出什麼特殊反應噢，領航。即使擁有這樣的力量，我也不會有什麼改變啦，因為我就是我嘛，我是這麼想的。", "0", "0", "0", "cv_caroline_11", "0", "0"},
[412014] = {412014, 11020, 15, 9, "0", "0", "Hooray\u{0020}for\u{0020}normalcy!", "0", "普通萬歲！", "0", "0", "0", "cv_caroline_12", "0", "0"},
[412015] = {412015, 11020, 16, 10, "0", "0", "Phew,\u{0020}I'm\u{0020}not\u{0020}late,\u{0020}am\u{0020}I?", "0", "呼，我沒有來遲吧？", "0", "0", "0", "cv_caroline_13", "0", "0"},
