[412028] = {412028, 11020, 31, 23, "0", "0", "Can\u{0020}you\u{0020}guess\u{0020}who\u{0020}it\u{0020}is\u{0020}by\u{0020}the\u{0020}sound\u{0020}of\u{0020}my\u{0020}voice?", "0", "聽聲音就能猜出來是誰了吧？", "0", "0", "0", "cv_caroline_26", "0", "0"},
