[412030] = {412030, 11020, 33, 25, "0", "0", "That\u{0020}was\u{0020}an\u{0020}easy\u{0020}guess,\u{0020}wasn't\u{0020}it?\u{0020}You're\u{0020}messing\u{0020}with\u{0020}me,\u{0020}right?", "0", "正常來說都能猜出來的吧？您是故意猜錯的吧？", "0", "0", "0", "cv_caroline_28", "0", "0"},
[412031] = {412031, 11020, 34, 26, "0", "0", "Navigator,\u{0020}while\u{0020}you\u{0020}were\u{0020}gone,\u{0020}I\u{0020}organized\u{0020}all\u{0020}the\u{0020}files!\u{0020}Let's\u{0020}keep\u{0020}working\u{0020}hard!", "0", "領航，在您不在的時候我已經把文檔整理好了！今天也一起努力吧！", "0", "0", "0", "cv_caroline_31", "0", "0"},
[412032] = {412032, 11020, 35, 27, "0", "0", "Sometimes,\u{0020}I\u{0020}think\u{0020}your\u{0020}story\u{0020}is\u{0020}like\u{0020}a\u{0020}modern\u{0020}epic.", "0", "偶爾也會覺得，您的故事就像現代的史詩呢。", "0", "0", "0", "cv_caroline_33", "0", "0"},
[412033] = {412033, 11020, 36, 28, "0", "0", "I'll\u{0020}give\u{0020}it\u{0020}everything\u{0020}I've\u{0020}got.", "0", "我會全力以赴的。", "0", "0", "0", "cv_caroline_34", "0", "0"},
