[412101] = {412101, 11021, 2, 2, "0", "0", "Hahaha,\u{0020}Navigator,\u{0020}I've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}you\u{0020}for\u{0020}so\u{0020}long.\u{0020}Isn't\u{0020}it\u{0020}obvious\u{0020}that\u{0020}you'd\u{0020}choose\u{0020}me?", "はーっはっはー！ナビゲーター、待っておったぞ。妾を選ぶのに何を迷う！", "哈——哈——哈，領航，吾都等你好久了。選吾不是毋庸置疑的嘛！", "0", "0", "0", "cv_sikadi_sw_2", "0", "0"},
[412102] = {412102, 11021, 3, 3, "0", "0", "I\u{0020}am\u{0020}the\u{0020}Summer\u{0020}Queen\u{0020}of\u{0020}the\u{0020}Dunescaith.\u{0020}This\u{0020}is\u{0020}just\u{0020}one\u{0020}of\u{0020}my\u{0020}many\u{0020}royal\u{0020}forms,\u{0020}which\u{0020}can\u{0020}only\u{0020}be\u{0020}revealed\u{0020}through\u{0020}the\u{0020}power\u{0020}of\u{0020}sun\u{0020}flames!", "妾は影の国……夏の女王！王が持つ百の姿の一。太陽の力によってのみ発現する特別な姿なのじゃ！", "吾乃影之國的夏之女王，這是吾百般王之形態的其中一種，只有借助陽炎的力量才能顯現的特殊形態！", "0", "0", "0", "cv_sikadi_sw_3", "0", "0"},
[412103] = {412103, 11021, 4, 4, "0", "idle", "...You\u{0020}said\u{0020}there\u{0020}were\u{0020}two\u{0020}blurry\u{0020}figures\u{0020}behind\u{0020}me?...\u{0020}Huh!?\u{0020}No,\u{0020}no\u{0020}way!\u{0020}I\u{0020}didn't\u{0020}see\u{0020}anything\u{0020}at\u{0020}all.\u{0020}You're\u{0020}messing\u{0020}with\u{0020}me,\u{0020}right?", "妾の背後に……人影が二つ？……ええっ！？ど、どこにもおらんぞ。嘘じゃよな……ナビゲーター？", "……你說吾背後有兩個模糊的人影？……嗯！？沒、沒有呀。吾、我完全沒看到哦。你在騙我對吧？", "0", "0", "0", "cv_sikadi_sw_4", "0", "0"},
[412104] = {412104, 11021, 5, 4, "0", "idle", "Speaking\u{0020}of\u{0020}which,\u{0020}lately,\u{0020}I've\u{0020}been\u{0020}having\u{0020}lots\u{0020}of\u{0020}dreams\u{0020}while\u{0020}I\u{0020}sleep.\u{0020}When\u{0020}I\u{0020}wake\u{0020}up,\u{0020}it\u{0020}feels\u{0020}like\u{0020}I've\u{0020}learned\u{0020}a\u{0020}new\u{0020}move...\u{0020}Could\u{0020}it\u{0020}be\u{0020}that\u{0020}my\u{0020}sealed\u{0020}memories\u{0020}are\u{0020}awakening?", "そう言えば妾はよく夢を見るんじゃが、起きたら新しい技を覚えてることがあって…………もしかして、妾の封印されし記憶が蘇ったのか！？", "說起來，最近睡覺的時候經常做夢。醒來後又好像學會了新的招式…………難道吾被封印的記憶覺醒了嗎？", "0", "0", "0", "cv_sikadi_sw_5", "0", "0"},
[412105] = {412105, 11021, 6, 4, "0", "idle", "I\u{0020}woke\u{0020}up\u{0020}feeling\u{0020}sore\u{0020}all\u{0020}over,\u{0020}as\u{0020}if\u{0020}I'd\u{0020}been\u{0020}in\u{0020}a\u{0020}ton\u{0020}of\u{0020}battles.\u{0020}Well,\u{0020}I'm\u{0020}fully\u{0020}recovered\u{0020}now.\u{0020}So,\u{0020}let's\u{0020}go\u{0020}to\u{0020}the\u{0020}beach\u{0020}together,\u{0020}Navigator!", "目が覚めたら全身筋肉痛で、なんかいっぱい戦った感じがするんじゃが……でももう全回復したぞ！一緒に海を見に行くぞ、ナビゲーター！", "睡了一覺起來渾身酸痛，像是打了很多場架。嘛，不過，現在已經完全恢復了。所以陪吾一起去看海吧！領航！", "0", "0", "0", "cv_sikadi_sw_6", "0", "0"},
[412106] = {412106, 11021, 7, 5, "1_》_0_0.8", "level1", "The\u{0020}sun\u{0020}flames\u{0020}want\u{0020}to\u{0020}destroy\u{0020}all\u{0020}life\u{0020}on\u{0020}Earth.\u{0020}Even\u{0020}I've\u{0020}been\u{0020}affected\u{0020}by\u{0020}them.\u{0020}But\u{0020}there's\u{0020}an\u{0020}ancient\u{0020}solution\u{0020}buried\u{0020}in\u{0020}the\u{0020}cold\u{0020}of\u{0020}the\u{0020}Abyssal\u{0020}Lands.\u{0020}Navigator...\u{0020}wanna\u{0020}grab\u{0020}some\u{0020}ice\u{0020}cream?", "太陽がこの大地に生きる者すべてを圧倒し、妾ですらその影響を受けておる。だが極寒の地の氷に、この炎熱に対抗する方法が封じられていたのじゃ。つまり、ナビゲーターよ……アイスクリームを食べに行かぬか？", "陽炎想要覆滅大地上的一切生機，即使是吾也受到了它的影響，但是極淵之地的冰寒中篆刻著破解這高懸陽炎的辦法。領航……要去吃霜淇淋嗎。", "0", "0", "0", "cv_sikadi_sw_7", "0", "0"},
[412107] = {412107, 11021, 8, 5, "1_》_0_0.8", "level1", "What\u{0020}I\u{0020}say\u{0020}gives\u{0020}everyone\u{0020}courage?\u{0020}Yeah!\u{0020}Because\u{0020}I'm\u{0020}the\u{0020}queen\u{0020}who\u{0020}protects\u{0020}the\u{0020}people\u{0020}of\u{0020}the\u{0020}Dunescaith!", "妾の言葉はみんなを勇気づける？うむ！妾は影の国の民を守る女王じゃからな！", "吾說的話能讓大家鼓起勇氣？嗯！因為吾是要保護影之國居民的女王嘛！", "0", "0", "0", "cv_sikadi_sw_8", "0", "0"},
[412108] = {412108, 11021, 9, 5, "1_》_100_1.5", "level2", "I\u{0020}visited\u{0020}the\u{0020}orphanage\u{0020}the\u{0020}other\u{0020}day\u{0020}and\u{0020}saw\u{0020}some\u{0020}old\u{0020}friends.\u{0020}Everyone's\u{0020}grown\u{0020}so\u{0020}tall,\u{0020}but\u{0020}I...\u{0020}haven't\u{0020}changed\u{0020}at\u{0020}all...", "この前孤児院に行って昔の友達と会ったのじゃが、みんな背がすっごく伸びていて……妾だけ昔のままで、ううぅ……", "上次回孤兒院，甚至還碰到了以前的朋友，大家都長得好高，只有吾沒什麼變化，唔……", "0", "0", "0", "cv_sikadi_sw_9", "0", "0"},
[412109] = {412109, 11021, 10, 5, "1_》_500_2", "level3", "Navigator,\u{0020}no\u{0020}matter\u{0020}what\u{0020}happens,\u{0020}I'll\u{0020}come\u{0020}to\u{0020}your\u{0020}side\u{0020}and\u{0020}protect\u{0020}you!\u{0020}Past,\u{0020}present,\u{0020}or\u{0020}future,\u{0020}as\u{0020}long\u{0020}as\u{0020}you\u{0020}call\u{0020}out\u{0020}\"Skadi,\"\u{0020}the\u{0020}Queen\u{0020}of\u{0020}the\u{0020}Dunescaith\u{0020}will\u{0020}come\u{0020}to\u{0020}you.", "ナビゲーター。例え何があろうと、妾が守ってやるぞ！過去、現在、そしてこれからも……スカディと呼べば、影の女王がすぐに降臨するのじゃ！", "領航，不管發生什麼事情吾都會來到你身邊保護你的哦！不論是過去，現在，還是未來，只要你高呼著“斯卡蒂”的名字，那麼影之國女王便會來到你身邊。", "0", "0", "0", "cv_sikadi_sw_10", "0", "0"},
[412110] = {412110, 11021, 11, 5, "1_》_1000_2.5", "level4", "I\u{0020}dreamt\u{0020}I\u{0020}fell\u{0020}into\u{0020}the\u{0020}ocean\u{0020}yesterday,\u{0020}and\u{0020}you\u{0020}saved\u{0020}me,\u{0020}Navigator.\u{0020}We\u{0020}ended\u{0020}up\u{0020}on\u{0020}a\u{0020}deserted\u{0020}island\u{0020}and\u{0020}lived\u{0020}there\u{0020}together...\u{0020}Then?\u{0020}...A-And\u{0020}then\u{0020}I,\u{0020}I\u{0020}totally\u{0020}forgot\u{0020}the\u{0020}rest!!\u{0020}", "ゆうべ海に落ちる夢を見て……ナビゲーターが妾を救ってくれたのじゃ。そして妾たちは孤島に流れ着いて、二人で暮らし始めて…………それから？そっ、そそそれからは何も覚えとらーん！", "昨天夢見吾落在了海裏，是領航救了吾。吾和領航流落到了一座荒島上，然後我們就在島上一起生活……之後？……之，之後吾，吾吾吾已經全部忘掉了！！\u{0020}", "0", "0", "0", "cv_sikadi_sw_11", "0", "0"},
[412111] = {412111, 11021, 12, 6, "0", "0", "Another\u{0020}test?\u{0020}Wait\u{0020}for\u{0020}me!\u{0020}I'll\u{0020}be\u{0020}there\u{0020}in\u{0020}a\u{0020}sec!", "またテストか？ちょっと待て。すぐに行くぞ！", "又要測試啊？稍微等我一下，馬上就來嘛！", "0", "0", "0", "cv_sikadi_sw_12", "0", "0"},
[412112] = {412112, 11021, 13, 7, "0", "0", "A\u{0020}flash\u{0020}from\u{0020}the\u{0020}corner\u{0020}of\u{0020}my\u{0020}eye.", "シャイニングエッジ！", "閃光的一角。", "0", "0", "0", "cv_sikadi_sw_13", "0", "0"},
[412113] = {412113, 11021, 14, 8, "0", "0", "I'm\u{0020}still\u{0020}not\u{0020}in\u{0020}my\u{0020}final\u{0020}form.\u{0020}I\u{0020}mean,\u{0020}I'm\u{0020}pretty\u{0020}powerful\u{0020}now,\u{0020}but\u{0020}I\u{0020}can't\u{0020}wait\u{0020}for\u{0020}my\u{0020}ultimate\u{0020}form!!", "妾はまだ完全体ではない。これで十分とも言えるが、究極形態が本当に楽しみじゃ！", "現在的吾還不是完全體。雖然現在已經足夠了，但果然還是很期待啊，吾的究極形態！！", "0", "0", "0", "cv_sikadi_sw_14", "0", "0"},
[412114] = {412114, 11021, 15, 9, "0", "0", "POWER!", "パワー！！", "POWER！", "0", "0", "0", "cv_sikadi_sw_15", "0", "0"},
[412115] = {412115, 11021, 16, 10, "0", "0", "I\u{0020}wore\u{0020}a\u{0020}swimsuit\u{0020}for\u{0020}this...\u{0020}but\u{0020}now\u{0020}I\u{0020}have\u{0020}to\u{0020}fight?!", "せっかく水着を着たのに…戦うのか？", "明明特地穿了泳裝…竟然要戰鬥？！", "0", "0", "0", "cv_sikadi_sw_16", "0", "0"},
[412116] = {412116, 11021, 17, 11, "0", "0", "What's\u{0020}next?\u{0020}How\u{0020}about\u{0020}we\u{0020}go\u{0020}for\u{0020}a\u{0020}swim?", "これからどうするか、じゃと？泳ぎに行くに決まっておろー！", "接下來？該去游泳咯~", "0", "0", "0", "cv_sikadi_sw_17", "0", "0"},
[412117] = {412117, 11021, 18, 12, "0", "0", "Almost\u{0020}had\u{0020}it...\u{0020}Navigator~\u{0020}I'm\u{0020}so\u{0020}tired.", "あとちょっとでパーフェクトだったのに……もう疲れたのじゃー！", "還差一點就成功了……領航~我已經累了。", "0", "0", "0", "cv_sikadi_sw_18", "0", "0"},
[412118] = {412118, 11021, 19, 13, "0", "0", "Huh!\u{0020}We\u{0020}won,\u{0020}but...\u{0020}there's\u{0020}something\u{0020}off\u{0020}about\u{0020}it.", "勝ちはしたが、うむ……うーん…微妙な感じじゃな。", "誒！雖然勝利了，嗯——嗯——但是有種微妙的感覺呢。", "0", "0", "0", "cv_sikadi_sw_19", "0", "0"},
[412119] = {412119, 11021, 20, 14, "0", "0", "Ah—this\u{0020}doesn't\u{0020}count!", "やあぁっ！……い、今のなし！", "呀——這、這一下不算！", "0", "0", "0", "cv_sikadi_sw_20", "0", "0"},
[412120] = {412120, 11021, 21, 15, "0", "0", "This\u{0020}is\u{0020}the\u{0020}limit,\u{0020}you\u{0020}shall\u{0020}not\u{0020}pass!", "ここで終わりじゃ！", "到此為止吧，你們不可再越過此處。", "0", "0", "0", "cv_sikadi_sw_22", "0", "0"},
[412121] = {412121, 11021, 23, 16, "0", "0", "Heya!", "せいや！", "嘿呀！", "0", "0", "0", "cv_sikadi_sw_21", "0", "0"},
[412122] = {412122, 11021, 24, 17, "0", "0", "Skadi-style\u{0020}Imperial\u{0020}Sword\u{0020}α!", "スカディ式キングスラッシュ・アルファ！！", "斯卡蒂式帝王劍α！", "0", "0", "0", "cv_sikadi_sw_24", "0", "0"},
[412123] = {412123, 11021, 26, 19, "0", "0", "Hmm,\u{0020}alright,\u{0020}I'll\u{0020}let\u{0020}you\u{0020}go\u{0020}this\u{0020}time!", "うぐぐ……今回だけは見逃してやる！", "唔嗯、這一次就饒過你們！", "0", "0", "0", "cv_sikadi_sw_23", "0", "0"},
[412124] = {412124, 11021, 27, 20, "0", "0", "Navigator!?\u{0020}...I'll\u{0020}permit\u{0020}you\u{0020}to...\u{0020}to\u{0020}bathe\u{0020}with\u{0020}me!", "ナ、ナビゲーター！？……し、仕方がない。特別に許してやるぞ。", "領航！？……吾就特許你和吾一、一起共浴吧！", "0", "0", "0", "cv_sikadi_sw_25", "0", "0"},
[412125] = {412125, 11021, 28, 21, "0", "0", "Ah,\u{0020}every\u{0020}time\u{0020}I\u{0020}come\u{0020}here,\u{0020}it\u{0020}feels\u{0020}just\u{0020}like\u{0020}being\u{0020}back\u{0020}in\u{0020}the\u{0020}Dunescaith.", "うむ……いつもここに来ると、影の国にいるみたいに安心するのじゃ。", "嗯！吾每次來到這裏，就像回到了影之國一樣安心。", "0", "0", "0", "cv_sikadi_sw_26", "0", "0"},
[412126] = {412126, 11021, 29, 21, "0", "0", "Navigator...?\u{0020}If\u{0020}you're\u{0020}tired,\u{0020}you\u{0020}can\u{0020}rest\u{0020}on\u{0020}my\u{0020}lap.", "ナビゲーター？疲れたならここに座って休むがよい。", "領航……？如果累了的話，可以坐在吾的身上休息一下哦。", "0", "0", "0", "cv_sikadi_sw_27", "0", "0"},
[412127] = {412127, 11021, 30, 22, "0", "0", "I-Is\u{0020}it\u{0020}starting?", "な、なんか始まるのか？", "要、要開始了嗎？", "0", "0", "0", "cv_sikadi_sw_28", "0", "0"},
[412128] = {412128, 11021, 31, 23, "0", "0", "Navigator,\u{0020}Navigator,\u{0020}look!\u{0020}The\u{0020}mark\u{0020}on\u{0020}my\u{0020}back!", "ナビゲーター、見よ！この背に刻まれた紋章を。", "領航，領航，你看你看，吾背上的紋章！", "0", "0", "0", "cv_sikadi_sw_29", "0", "0"},
[412129] = {412129, 11021, 32, 24, "0", "0", "That's\u{0020}right!\u{0020}I\u{0020}never\u{0020}thought\u{0020}you'd\u{0020}guess\u{0020}wrong,\u{0020}Navigator!", "そうこなくっちゃ！汝が外すはずないのじゃ！", "就該這樣嘛！吾從來都沒想過領航會猜錯哦！", "0", "0", "0", "cv_sikadi_sw_30", "0", "0"},
[412130] = {412130, 11021, 33, 25, "0", "0", "You\u{0020}must\u{0020}have\u{0020}picked\u{0020}the\u{0020}wrong\u{0020}one\u{0020}on\u{0020}purpose,\u{0020}right?\u{0020}Didn't\u{0020}you?", "わざと外したんじゃろ……？そうじゃな？な？", "你一定是故意選錯的吧？對不對？是不是？", "0", "0", "0", "cv_sikadi_sw_31", "0", "0"},
[412131] = {412131, 11021, 34, 26, "0", "0", "Navigator,\u{0020}I've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}you\u{0020}for\u{0020}a\u{0020}long\u{0020}time.", "ナビゲーター、待ちくたびれたぞ！！", "領航，吾等你很久了哦。", "0", "0", "0", "cv_sikadi_sw_32", "0", "0"},
[412132] = {412132, 11021, 35, 27, "0", "0", "Navigator,\u{0020}let\u{0020}me\u{0020}show\u{0020}you\u{0020}the\u{0020}awesome\u{0020}technique\u{0020}I\u{0020}learned\u{0020}in\u{0020}my\u{0020}dream!", "ナビゲーターに見せてやろう。妾が夢で修得した、超凄い技をな！", "領航，給你看看吾在夢中學到的，超級厲害的技藝哦。", "0", "0", "0", "cv_sikadi_sw_33", "0", "0"},
[412133] = {412133, 11021, 36, 28, "0", "0", "Hmph,\u{0020}no\u{0020}matter\u{0020}how\u{0020}many\u{0020}times\u{0020}you\u{0020}challenge\u{0020}me,\u{0020}the\u{0020}result\u{0020}won't\u{0020}change.\u{0020}Bring\u{0020}it\u{0020}on!", "フフン、妾に何度挑んでも結果は変わらんぞ？まとめてかかってくるがいい！", "哼哼，無論挑戰吾多少次結果也不會改變哦？你們一起上吧！", "0", "0", "0", "cv_sikadi_sw_34", "0", "0"},
[412134] = {412134, 11021, 37, 29, "0", "0", "...Navigator,\u{0020}you\u{0020}sure\u{0020}are\u{0020}popular.", "……ナビゲーターは本当にモテモテだな。", "……領航真是受歡迎啊。", "0", "0", "0", "cv_sikadi_sw_35", "0", "0"},
[412135] = {412135, 11021, 38, 30, "0", "0", "Did\u{0020}you\u{0020}receive\u{0020}new\u{0020}orders?", "新しい配置書か？", "收到新的調度書了？", "0", "0", "0", "cv_sikadi_sw_36", "0", "0"},
[412136] = {412136, 11021, 39, 31, "0", "0", "Let\u{0020}me\u{0020}see\u{0020}what\u{0020}new\u{0020}weapons\u{0020}the\u{0020}research\u{0020}department\u{0020}has\u{0020}developed.", "どれどれー。開発部門の新兵器はあるかなー？", "讓吾看看，科研部又研發了什麼新武器。", "0", "0", "0", "cv_sikadi_sw_37", "0", "0"},
[412137] = {412137, 11021, 40, 32, "0", "0", "I\u{0020}don't\u{0020}want\u{0020}anything...\u{0020}hmm...", "妾は何もいらぬぞ。……うん。", "我什麼都不要，嗯……", "0", "0", "0", "cv_sikadi_sw_38", "0", "0"},
[412138] = {412138, 11021, 41, 33, "0", "0", "Let's\u{0020}see\u{0020}if\u{0020}there's\u{0020}a\u{0020}portrait\u{0020}of\u{0020}me.", "妾の写真はあるか？", "看看有沒有吾的畫像。", "0", "0", "0", "cv_sikadi_sw_39", "0", "0"},
[412139] = {412139, 11021, 42, 34, "0", "0", "You\u{0020}better\u{0020}not\u{0020}turn\u{0020}my\u{0020}voice\u{0020}off!", "妾の声を消すとか許さんぞ！", "可不許關掉吾的聲音哦！", "0", "0", "0", "cv_sikadi_sw_40", "0", "0"},
[412140] = {412140, 11021, 43, 35, "0", "0", "Let\u{0020}me,\u{0020}the\u{0020}reliable\u{0020}one,\u{0020}take\u{0020}a\u{0020}look!", "頼りになる妾が見てやろう！", "讓可靠的我來看看吧！", "0", "0", "0", "cv_sikadi_sw_41", "0", "0"},
