[412225] = {412225, 11022, 28, 21, "0", "0", "Can't\u{0020}believe\u{0020}my\u{0020}hunch\u{0020}was\u{0020}right.\u{0020}You\u{0020}actually\u{0020}followed\u{0020}me\u{0020}in\u{0020}here!", "まさかあーしの予感が的中するなんて。ほんとにあーしと一緒にお風呂入るんだ……", "0", "0", "0", "0", "cv_wangnv_28", "0", "0"},
