[412229] = {412229, 11022, 32, 24, "0", "0", "Great!\u{0020}Correct!\u{0020}Your\u{0020}reward\u{0020}is\u{0020}some\u{0020}quality\u{0020}one-on-one\u{0020}time\u{0020}with\u{0020}me\u{0020}on\u{0020}the\u{0020}battlefield.", "はい、良くできましたー！　ご褒美に二人きりの時間をあげるね……さ、二人で戦場に行くよー！", "0", "0", "0", "0", "cv_wangnv_32", "0", "0"},
[412230] = {412230, 11022, 33, 25, "0", "0", "Okay!\u{0020}Your\u{0020}punishment\u{0020}is\u{0020}going\u{0020}back\u{0020}into\u{0020}battle\u{0020}with\u{0020}me.\u{0020}Our\u{0020}special\u{0020}alone\u{0020}time!", "オッケー、罰としてもう一回戦場に付き合って貰うよー。ここからはあーしとナビくん、二人の時間だからね。", "0", "0", "0", "0", "cv_wangnv_33", "0", "0"},
[412231] = {412231, 11022, 34, 26, "0", "0", "Finally!\u{0020}I\u{0020}was\u{0020}getting\u{0020}so\u{0020}bored.\u{0020}Let's\u{0020}go\u{0020}find\u{0020}some\u{0020}fun!", "やっと來たー。退屈だったんだよー？　んじゃ早速、どっか遊びに行かない？", "0", "0", "0", "0", "cv_wangnv_34", "0", "0"},
[412232] = {412232, 11022, 35, 27, "0", "0", "Wanna\u{0020}pull\u{0020}some\u{0020}secret\u{0020}overtime\u{0020}together?", "あーし達ふたりでこっそり殘業しない？", "0", "0", "0", "0", "cv_wangnv_35", "0", "0"},
[412233] = {412233, 11022, 36, 28, "0", "0", "Nice,\u{0020}nice!", "いいねいいねぇ！", "0", "0", "0", "0", "cv_wangnv_36", "0", "0"},
[412234] = {412234, 11022, 37, 29, "0", "0", "Taking\u{0020}me\u{0020}to\u{0020}meet\u{0020}the\u{0020}others?\u{0020}Let's\u{0020}go\u{0020}right\u{0020}now!", "あーしを連れて他の人に會いに行くの？いいよ、今から行く？", "0", "0", "0", "0", "cv_wangnv_37", "0", "0"},
[412235] = {412235, 11022, 38, 30, "0", "0", "Whoa,\u{0020}you\u{0020}can\u{0020}just\u{0020}call\u{0020}in\u{0020}other\u{0020}Drivers\u{0020}like\u{0020}it's\u{0020}nothing?\u{0020}Must\u{0020}be\u{0020}nice\u{0020}having\u{0020}that\u{0020}kinda\u{0020}pull.", "ナビくんって結構偉いんだねー。他のドライバーを自由に募集できるなんて。", "0", "0", "0", "0", "cv_wangnv_38", "0", "0"},
[412236] = {412236, 11022, 39, 31, "0", "0", "Pfft,\u{0020}what\u{0020}weird\u{0020}gear.", "ぷっ、変な裝備。", "0", "0", "0", "0", "cv_wangnv_39", "0", "0"},
[412237] = {412237, 11022, 40, 32, "0", "0", "I'll\u{0020}pay\u{0020}this\u{0020}time.", "あーしが奢ったげるよ。", "0", "0", "0", "0", "cv_wangnv_40", "0", "0"},
[412238] = {412238, 11022, 41, 33, "0", "0", "I\u{0020}recognize\u{0020}this!\u{0020}It's\u{0020}your\u{0020}photo,\u{0020}right?", "あ、見覚えあるー。この寫真ってナビくんでしょ？", "0", "0", "0", "0", "cv_wangnv_41", "0", "0"},
[412239] = {412239, 11022, 42, 34, "0", "0", "The\u{0020}device\u{0020}that'll\u{0020}change\u{0020}the\u{0020}world\u{0020}is\u{0020}right\u{0020}here.", "世界を変える仕組みはここにあるよ。", "0", "0", "0", "0", "cv_wangnv_42", "0", "0"},
[412240] = {412240, 11022, 43, 35, "0", "0", "I\u{0020}know\u{0020}this\u{0020}one!\u{0020}This\u{0020}is\u{0020}where\u{0020}we\u{0020}claim\u{0020}rewards,\u{0020}right?\u{0020}Eh...?\u{0020}Wrong?", "分かった！ここってボーナスが入ってる場所でしょ？え……違った？", "0", "0", "0", "0", "cv_wangnv_43", "0", "0"},
[412241] = {412241, 11022, 44, 36, "0", "0", "The\u{0020}chatroom...\u{0020}better\u{0020}watch\u{0020}out\u{0020}for\u{0020}shady\u{0020}people\u{0020}in\u{0020}there.", "チャットかぁ……荒らしには気を付けてよね。", "0", "0", "0", "0", "cv_wangnv_44", "0", "0"},
[412242] = {412242, 11022, 45, 37, "0", "0", "(stares)", "じぃ～", "0", "0", "0", "0", "cv_wangnv_45", "0", "0"},
[412300] = {412300, 11023, 1, 1, "0", "0", "Haze\u{0020}reverb.", "ハツリバーブ。", "蒼霧殘響", "0", "0", "0", "cv_xiaomeng_1", "0", "0"},
[412301] = {412301, 11023, 2, 2, "0", "0", "Is\u{0020}this\u{0020}where\u{0020}you\u{0020}often\u{0020}stay,\u{0020}sir?\u{0020}Hmm…\u{0020}well\u{0020}then,\u{0020}this\u{0020}is\u{0020}where\u{0020}Xiaomeng\u{0020}will\u{0020}stand\u{0020}guard\u{0020}from\u{0020}now\u{0020}on.", "ここが殿がよくいる場所か……うん……うん！では、今からここが暁夢（ぎょうむ）の守備範囲だな！", "這就是閣下經常呆的地方嗎。嗯……嗯！那現在這裏就是曉夢要守護的地方了。", "0", "0", "0", "cv_xiaomeng_2", "0", "0"},
[412302] = {412302, 11023, 3, 3, "0", "0", "Upon\u{0020}hearing\u{0020}your\u{0020}call,\u{0020}Xiaomeng\u{0020}rushed\u{0020}over.\u{0020}What\u{0020}trial\u{0020}are\u{0020}you\u{0020}giving\u{0020}me\u{0020}this\u{0020}time?", "殿の呼びかけに応じ、暁夢、ここに参上！さあ、今回はどのような試練が待っているんだ？", "閣下，聽到你的呼喚，曉夢馬上就來幫忙了。這次又要給予曉夢什麼樣的試煉呢？", "0", "0", "0", "cv_xiaomeng_3", "0", "0"},
[412303] = {412303, 11023, 4, 4, "0", "idle", "What's\u{0020}the\u{0020}meaning\u{0020}of\u{0020}throwing\u{0020}a\u{0020}punch?\u{0020}I\u{0020}don't\u{0020}know,\u{0020}never\u{0020}thought\u{0020}about\u{0020}it.\u{0020}My\u{0020}teacher\u{0020}taught\u{0020}me\u{0020}martial\u{0020}arts,\u{0020}so\u{0020}I\u{0020}practice\u{0020}it.\u{0020}Why\u{0020}I\u{0020}punch\u{0020}and\u{0020}how\u{0020}I\u{0020}punch—those\u{0020}are\u{0020}things\u{0020}for\u{0020}you\u{0020}to\u{0020}figure\u{0020}out,\u{0020}right?\u{0020}Punching\u{0020}and\u{0020}stopping—that's\u{0020}what\u{0020}I\u{0020}do.", "この拳の意味？分からん、考えたこともない。師匠が拳法を教え、暁夢はそれを修める。それだけのことだ。暁夢が何のためにどうやって拳を出すのか。それは殿に任せる。殿が思うところに我が拳あり！それが暁夢の生き様だ！", "出拳的意義？不知道，也沒想過，先生教曉夢拳法，曉夢便習武，練了便是練了。曉夢為何出拳，怎麼出拳，這些都是閣下需要思考的問題吧？拳出拳止，這才是曉夢的意義。", "0", "0", "0", "cv_xiaomeng_4", "0", "0"},
[412304] = {412304, 11023, 5, 4, "0", "idle", "Cheng\u{0020}Lian\u{0020}said\u{0020}I\u{0020}should\u{0020}listen\u{0020}to\u{0020}your\u{0020}teachings,\u{0020}so\u{0020}I'll\u{0020}listen\u{0020}to\u{0020}whatever\u{0020}you\u{0020}say\u{0020}from\u{0020}now\u{0020}on.", "殿が修行をつけてくれると澄練（ちょうれん）から聞いたんだ。今からどんな命令にも従うぞ！", "澄練說閣下可以教導曉夢修行，要聽閣下的話。那麼從現在開始，曉夢便聽閣下的話。", "0", "0", "0", "cv_xiaomeng_5", "0", "0"},
[412305] = {412305, 11023, 6, 4, "0", "idle", "\"Too\u{0020}much\u{0020}but\u{0020}useless\"—after\u{0020}my\u{0020}mom\u{0020}said\u{0020}that,\u{0020}I\u{0020}was\u{0020}kicked\u{0020}out.\u{0020}Do\u{0020}you\u{0020}know\u{0020}what\u{0020}she\u{0020}meant\u{0020}by\u{0020}that?", "その拳に乗せるものを探しなさい……母上はそう言って、暁夢を追い出したんだ。殿。この意味が分かるか？", "大而無當——母親在說完這句後，曉夢就被趕了出來。閣下知道母親說的話……是什麼意思嗎？", "0", "0", "0", "cv_xiaomeng_6", "0", "0"},
[412306] = {412306, 11023, 7, 5, "1_》_0_0.8", "level1", "Na...\u{0020}Navigator!\u{0020}What\u{0020}are\u{0020}you\u{0020}doing?", "と、殿？何をしているんだ？", "閣……閣下！這是在做什麼？", "0", "0", "0", "cv_xiaomeng_7", "0", "0"},
[412307] = {412307, 11023, 8, 5, "1_》_0_0.8", "level1", "Of\u{0020}course,\u{0020}it\u{0020}hurt\u{0020}when\u{0020}I\u{0020}first\u{0020}started\u{0020}practicing.\u{0020}But\u{0020}after\u{0020}the\u{0020}pain,\u{0020}my\u{0020}fists\u{0020}don't\u{0020}hurt\u{0020}anymore.\u{0020}Want\u{0020}to\u{0020}see\u{0020}my\u{0020}hands?", "拳法を始めた時は痛かった拳が、今はもう痛むことはない。暁夢の手を見てみるか？", "最開始練拳的時候當然很痛啊，但是痛過之後，現在曉夢的拳頭已經不會痛了。閣下想要看看曉夢的手嗎？", "0", "0", "0", "cv_xiaomeng_8", "0", "0"},
[412308] = {412308, 11023, 9, 5, "1_》_100_1.5", "level2", "Navigator,\u{0020}give\u{0020}me\u{0020}an\u{0020}order.\u{0020}I\u{0020}want\u{0020}to\u{0020}listen\u{0020}to\u{0020}you!\u{0020}I\u{0020}want...\u{0020}to\u{0020}stay\u{0020}by\u{0020}your\u{0020}side...", "殿。暁夢に命令をくれ。暁夢は殿の言うことを聞きたい。暁夢は……殿の傍にいたい……", "領航對曉夢下命令吧，曉夢想要聽閣下的話！曉夢想……待在閣下身邊……", "0", "0", "0", "cv_xiaomeng_9", "0", "0"},
[412309] = {412309, 11023, 10, 5, "1_》_500_2", "level3", "Navigator,\u{0020}I\u{0020}think\u{0020}I've\u{0020}figured\u{0020}out\u{0020}a\u{0020}bit\u{0020}more...\u{0020}I\u{0020}want\u{0020}to\u{0020}take\u{0020}time\u{0020}to\u{0020}think\u{0020}about\u{0020}it\u{0020}and\u{0020}give\u{0020}you\u{0020}an\u{0020}answer\u{0020}later...\u{0020}So\u{0020}that's\u{0020}how\u{0020}it\u{0020}is...", "殿。暁夢は少し分かってきた気がする……でも、もっと落ち着いて考えてから、話そうと思う。だから今はここまでだ。", "閣下，曉夢好像明白一點了……想靜下心來思考再給閣下答案……原來是這樣啊……", "0", "0", "0", "cv_xiaomeng_10", "0", "0"},
[412310] = {412310, 11023, 11, 5, "1_》_1000_2.5", "level4", "Thinking\u{0020}is\u{0020}important...\u{0020}so\u{0020}is\u{0020}understanding\u{0020}right\u{0020}and\u{0020}wrong!\u{0020}Everyone\u{0020}in\u{0020}the\u{0020}Pingxin\u{0020}is\u{0020}important...\u{0020}and\u{0020}you're\u{0020}important\u{0020}too,\u{0020}Navigator!\u{0020}Sorry...\u{0020}this\u{0020}is\u{0020}all\u{0020}I\u{0020}can\u{0020}think\u{0020}of\u{0020}right\u{0020}now...\u{0020}Let's\u{0020}figure\u{0020}out\u{0020}the\u{0020}rest\u{0020}together.", "考えることは大切だけど……決めることも大切だな！で、暁夢は平心社のみんなが大切で……でも！殿も大切な存在で……うーん……申し訳ない。いまの暁夢は、これぐらいしか分からない。……だからこれから一緒に考えてくれ！", "……思考是很重要的……對錯也是很重要的！平心社的大家是很重要的……閣下也是很重要的……！對不起……閣下……曉夢現在只能想到這些…………今後再和領航一起想吧。", "0", "0", "0", "cv_xiaomeng_11", "0", "0"},
[412311] = {412311, 11023, 12, 6, "0", "0", "Oh,\u{0020}I\u{0020}see\u{0020}now.\u{0020}So,\u{0020}this\u{0020}is\u{0020}a\u{0020}type\u{0020}of\u{0020}training\u{0020}technique?", "このような修行があるとは！", "原來如此，還有這種練習方式。", "0", "0", "0", "cv_xiaomeng_12", "0", "0"},
[412312] = {412312, 11023, 13, 7, "0", "0", "What's\u{0020}the\u{0020}goal\u{0020}of\u{0020}doing\u{0020}this?", "もっと体を鍛えるぞ！", "這樣做的目的是什麼。", "0", "0", "0", "cv_xiaomeng_13", "0", "0"},
[412313] = {412313, 11023, 14, 8, "0", "0", "Time\u{0020}to\u{0020}stretch\u{0020}out\u{0020}my\u{0020}spine…", "うおぉー！こんなにスッキリしたのは久しぶりだ！どうだ！暁夢は殿の望む姿になれたか？", "該練練脊骨了……", "0", "0", "0", "cv_xiaomeng_14", "0", "0"},
[412314] = {412314, 11023, 15, 9, "0", "0", "Not\u{0020}too\u{0020}much,\u{0020}not\u{0020}too\u{0020}little.\u{0020}Adjust\u{0020}as\u{0020}needed—bend\u{0020}when\u{0020}it's\u{0020}time,\u{0020}stand\u{0020}tall\u{0020}when\u{0020}required!", "過ぎること及ばざることなく、曲に随（したが）い伸（しん）に就（つ）く！", "無過不及，隨曲就伸！", "0", "0", "0", "cv_xiaomeng_15", "0", "0"},
[412315] = {412315, 11023, 16, 10, "0", "0", "Xiaomeng,\u{0020}the\u{0020}Warrior\u{0020}of\u{0020}Kyushu\u{0020}Pingxin,\u{0020}awaiting\u{0020}your\u{0020}command.", "九州平心社（きゅうしゅうへいしんしゃ）の武者、暁夢。参る！", "九州平心社，“武夫”曉夢，請指教。", "0", "0", "0", "cv_xiaomeng_16", "0", "0"},
[412316] = {412316, 11023, 17, 11, "0", "0", "Simple\u{0020}enough—task\u{0020}completed\u{0020}without\u{0020}a\u{0020}hitch!", "押忍、一件落着！", "簡單，順利完成了！", "0", "0", "0", "cv_xiaomeng_17", "0", "0"},
[412317] = {412317, 11023, 18, 12, "0", "0", "Now\u{0020}that\u{0020}I've\u{0020}got\u{0020}the\u{0020}hang\u{0020}of\u{0020}it,\u{0020}let's\u{0020}go\u{0020}again!", "経験は積んだ、もう一度！", "積累了經驗，再來一次吧！", "0", "0", "0", "cv_xiaomeng_18", "0", "0"},
[412318] = {412318, 11023, 19, 13, "0", "0", "Just\u{0020}half\u{0020}a\u{0020}step\u{0020}shy.", "一手足りないか……！", "棋差半步啊。", "0", "0", "0", "cv_xiaomeng_19", "0", "0"},
[412319] = {412319, 11023, 20, 14, "0", "0", "Winning\u{0020}or\u{0020}losing\u{0020}doesn't\u{0020}matter.\u{0020}Xiaomeng\u{0020}will\u{0020}stand\u{0020}by\u{0020}your\u{0020}side\u{0020}and\u{0020}start\u{0020}fresh\u{0020}with\u{0020}you.", "勝敗は兵家の常だ。殿が命じてくれるのなら暁夢が再び挑んでやる！", "勝敗乃常事，曉夢陪閣下重新來過吧。", "0", "0", "0", "cv_xiaomeng_20", "0", "0"},
[412320] = {412320, 11023, 21, 15, "0", "0", "If\u{0020}it's\u{0020}a\u{0020}kill,\u{0020}then\u{0020}it's\u{0020}a\u{0020}kill.", "倒す。それだけだ。", "殺了便是殺了。", "0", "0", "0", "cv_xiaomeng_21", "0", "0"},
[412321] = {412321, 11023, 23, 16, "0", "0", "Hit!", "いちっ！", "中！", "0", "0", "0", "cv_xiaomeng_22", "0", "0"},
[412322] = {412322, 11023, 24, 17, "0", "0", "Another\u{0020}hit!", "にっ！", "再中！", "0", "0", "0", "cv_xiaomeng_23", "0", "0"},
[412323] = {412323, 11023, 25, 18, "0", "0", "Tai\u{0020}Chi\u{0020}Chuan!\u{0020}Ha!", "虚領頂勁。はぁーー！", "虛領頂勁。哈——！", "0", "0", "0", "cv_xiaomeng_24", "0", "0"},
[412324] = {412324, 11023, 26, 19, "0", "0", "Xiaomeng...\u{0020}has\u{0020}grown\u{0020}rusty.", "暁夢は……錆びてしまったのか……", "曉夢……腐朽了啊。", "0", "0", "0", "cv_xiaomeng_25", "0", "0"},
[412325] = {412325, 11023, 27, 20, "0", "0", "I've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}so\u{0020}long.\u{0020}Today's\u{0020}the\u{0020}day...\u{0020}for\u{0020}that\u{0020}medicinal\u{0020}bath\u{0020}my\u{0020}mother\u{0020}used\u{0020}to\u{0020}prepare\u{0020}all\u{0020}the\u{0020}time...", "待っていたぞ。今日は…あの…昔、母上がよくやっていた薬湯をするんだな？", "久候多時了，今天是要……那個吧……以前媽媽經常做的……藥浴……", "0", "0", "0", "cv_xiaomeng_26", "0", "0"},
[412326] = {412326, 11023, 28, 21, "0", "0", "Sir,\u{0020}don't\u{0020}you\u{0020}have\u{0020}any\u{0020}requests\u{0020}for\u{0020}Xiaomeng?\u{0020}Whatever\u{0020}you\u{0020}say,\u{0020}Xiaomeng\u{0020}will\u{0020}listen.", "殿……暁夢に命令はないか？……ちゃんと従うぞ。", "閣下……不向曉夢下要求嗎……曉夢會聽閣下的話哦。", "0", "0", "0", "cv_xiaomeng_27", "0", "0"},
[412327] = {412327, 11023, 29, 21, "0", "0", "Is\u{0020}this\u{0020}behaving\u{0020}well?\u{0020}But\u{0020}if\u{0020}I\u{0020}only\u{0020}stay\u{0020}in\u{0020}one\u{0020}position,\u{0020}some\u{0020}spots\u{0020}won't\u{0020}get\u{0020}washed\u{0020}properly...", "これでいいのか？同じ体勢だけだと、すみずみまできれいに洗えないだろ……？", "乖乖這樣就可以了嗎，只是一個姿勢的話，有些地方會洗不乾淨哦……", "0", "0", "0", "cv_xiaomeng_28", "0", "0"},
[412328] = {412328, 11023, 30, 22, "0", "0", "Is\u{0020}it\u{0020}about\u{0020}to\u{0020}begin...?", "やってみるか？", "要開始了嗎……", "0", "0", "0", "cv_xiaomeng_29", "0", "0"},
[412329] = {412329, 11023, 31, 23, "0", "0", "Xiaomeng\u{0020}trusts\u{0020}you\u{0020}completely.", "暁夢は殿を信じるぞ。", "曉夢相信閣下。", "0", "0", "0", "cv_xiaomeng_30", "0", "0"},
[412330] = {412330, 11023, 32, 24, "0", "0", "You're\u{0020}the\u{0020}one\u{0020}who\u{0020}taught\u{0020}me\u{0020}to\u{0020}see\u{0020}what's\u{0020}right\u{0020}and\u{0020}wrong,\u{0020}what's\u{0020}true\u{0020}and\u{0020}false.", "善と悪、正解と不正解を見極める。殿がこの道理を教えてくれたんだ！", "分清楚是和非、正確和錯誤。閣下就是教會曉夢這個道理的人。", "0", "0", "0", "cv_xiaomeng_31", "0", "0"},
[412331] = {412331, 11023, 33, 25, "0", "0", "Navigator!", "殿！", "閣下！", "0", "0", "0", "cv_xiaomeng_32", "0", "0"},
[412332] = {412332, 11023, 34, 26, "0", "0", "Welcome\u{0020}back,\u{0020}Xiaomeng\u{0020}followed\u{0020}your\u{0020}orders\u{0020}and\u{0020}kept\u{0020}watch!", "おかえり、殿！暁夢はちゃんと言いつけ通り留守番をしてたぞ！", "歡迎回來，曉夢有聽閣下的話好好看家哦！", "0", "0", "0", "cv_xiaomeng_33", "0", "0"},
[412333] = {412333, 11023, 35, 27, "0", "0", "Give\u{0020}me\u{0020}your\u{0020}orders.", "命令をくれ！殿！", "下達命令吧，閣下。", "0", "0", "0", "cv_xiaomeng_34", "0", "0"},
[412334] = {412334, 11023, 36, 28, "0", "0", "Are\u{0020}we\u{0020}heading\u{0020}out?", "ピクニックにでも行くのか？", "準備踏青了嗎。", "0", "0", "0", "cv_xiaomeng_35", "0", "0"},
[412335] = {412335, 11023, 37, 29, "0", "0", "Such\u{0020}a\u{0020}powerful\u{0020}aura...", "強者の気配がするぞ……", "好強的氣息……", "0", "0", "0", "cv_xiaomeng_36", "0", "0"},
[412336] = {412336, 11023, 38, 30, "0", "0", "...", "……色々な気配があるな。", "……", "0", "0", "0", "cv_xiaomeng_37", "0", "0"},
[412337] = {412337, 11023, 39, 31, "0", "0", "These\u{0020}things\u{0020}are\u{0020}just\u{0020}on\u{0020}the\u{0020}surface.", "大事なのは己の肉体だ！", "身外之物罷了。", "0", "0", "0", "cv_xiaomeng_38", "0", "0"},
[412338] = {412338, 11023, 40, 32, "0", "0", "Business\u{0020}settled.", "貸し借りなし。だろ？", "銀貨兩訖。", "0", "0", "0", "cv_xiaomeng_39", "0", "0"},
[412339] = {412339, 11023, 41, 33, "0", "0", "Oh,\u{0020}Xiaomeng\u{0020}has\u{0020}a\u{0020}similar\u{0020}file\u{0020}too!", "おぉ。暁夢にもこんなプロフィールがあるぞ。", "哦哦，曉夢也有類似的檔案！", "0", "0", "0", "cv_xiaomeng_40", "0", "0"},
[412340] = {412340, 11023, 42, 34, "0", "0", "Is\u{0020}it\u{0020}ready?", "設定できたか？", "設定好了嗎。", "0", "0", "0", "cv_xiaomeng_41", "0", "0"},
[412341] = {412341, 11023, 43, 35, "0", "0", "Correspondence\u{0020}exchanges.", "手紙は行ったり来たりするものだよな。", "書信來去。", "0", "0", "0", "cv_xiaomeng_42", "0", "0"},
[412342] = {412342, 11023, 44, 36, "0", "0", "So\u{0020}noisy...\u{0020}Xiaomeng\u{0020}only\u{0020}wants\u{0020}to\u{0020}hear\u{0020}your\u{0020}voice,\u{0020}sir.", "うるさいな。暁夢は殿の声だけが聞きたいのだ。", "聒噪，曉夢只想聽閣下的聲音。", "0", "0", "0", "cv_xiaomeng_43", "0", "0"},
[412343] = {412343, 11023, 45, 37, "0", "0", "Oh,\u{0020}oh!", "おおぉ！", "哦哦！", "0", "0", "0", "cv_xiaomeng_44", "0", "0"},
[412400] = {412400, 11024, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_yanyanluo_1", "0", "0"},
[412401] = {412401, 11024, 2, 2, "0", "0", "Doing\u{0020}this\u{0020}dull\u{0020}work...\u{0020}I\u{0020}might\u{0020}zone\u{0020}out\u{0020}and\u{0020}accidentally\u{0020}step\u{0020}on\u{0020}a\u{0020}building.", "0", "做這種乏味的工作……我也許會精神渙散而不小心踩到建築哦。", "0", "0", "0", "cv_yanyanluo_2", "0", "0"},
[412402] = {412402, 11024, 3, 3, "0", "0", "Whale\u{0020}Fall's\u{0020}secret\u{0020}weapon,\u{0020}Yanyanlo,\u{0020}reporting\u{0020}for\u{0020}duty.\u{0020}Let's\u{0020}see\u{0020}what\u{0020}fun\u{0020}I\u{0020}can\u{0020}find\u{0020}with\u{0020}you,\u{0020}Navigator.", "0", "“鯨落”的秘密武器——妍妍蘿參上。在領航身上能尋找到什麼樂趣，就讓我期待一番吧。", "0", "0", "0", "cv_yanyanluo_3", "0", "0"},
[412403] = {412403, 11024, 4, 4, "0", "idle", "The\u{0020}wind's\u{0020}been\u{0020}blowing\u{0020}all\u{0020}day,\u{0020}making\u{0020}my\u{0020}hair\u{0020}feel\u{0020}a\u{0020}bit\u{0020}dry...\u{0020}should\u{0020}I\u{0020}call\u{0020}for\u{0020}some\u{0020}artificial\u{0020}rain?", "0", "今天的風吹個不停，頭髮好像變得有些乾燥，要不要呼叫一場人工降雨呢？", "0", "0", "0", "cv_yanyanluo_4", "0", "0"},
[412404] = {412404, 11024, 5, 4, "0", "idle", "This\u{0020}body\u{0020}of\u{0020}mine\u{0020}can\u{0020}dive\u{0020}deep\u{0020}into\u{0020}the\u{0020}sea\u{0020}or\u{0020}stand\u{0020}tall\u{0020}on\u{0020}land.\u{0020}It's\u{0020}pretty\u{0020}fun\u{0020}watching\u{0020}several\u{0020}blocks\u{0020}at\u{0020}once\u{0020}from\u{0020}up\u{0020}here.", "0", "這副身姿能讓我在海底潛得更深，或是在地上望得更遠。像這樣矗立著，同時觀察好幾片街區的景象倒也挺有意思。", "0", "0", "0", "cv_yanyanluo_5", "0", "0"},
[412405] = {412405, 11024, 6, 4, "0", "idle", "Samghrma's\u{0020}probably\u{0020}going\u{0020}to\u{0020}spend\u{0020}the\u{0020}whole\u{0020}day\u{0020}in\u{0020}the\u{0020}library\u{0020}again.\u{0020}I\u{0020}need\u{0020}to\u{0020}come\u{0020}up\u{0020}with\u{0020}a\u{0020}fun\u{0020}way\u{0020}to\u{0020}mess\u{0020}with\u{0020}her\u{0020}later.", "0", "伽藍見又打算在圖書館裏泡一整天吧，該為今晚如何捉弄她想個新點子了。", "0", "0", "0", "cv_yanyanluo_6", "0", "0"},
[412406] = {412406, 11024, 7, 5, "1_》_0_0.8", "level1", "So,\u{0020}what\u{0020}kind\u{0020}of\u{0020}reaction\u{0020}are\u{0020}you\u{0020}hoping\u{0020}for\u{0020}by\u{0020}doing\u{0020}this?", "0", "謔~這麼做，是在期待著什麼反應呢？", "0", "0", "0", "cv_yanyanluo_7", "0", "0"},
[412407] = {412407, 11024, 8, 5, "1_》_0_0.8", "level1", "No\u{0020}buttons\u{0020}here!\u{0020}No\u{0020}matter\u{0020}how\u{0020}much\u{0020}you\u{0020}press,\u{0020}torpedoes\u{0020}won't\u{0020}fire.", "0", "這種地方可沒有按鈕，再怎麼按也不會發射魚雷的。", "0", "0", "0", "cv_yanyanluo_8", "0", "0"},
[412408] = {412408, 11024, 9, 5, "1_》_100_1.5", "level2", "Just\u{0020}a\u{0020}heads-up,\u{0020}don't\u{0020}touch\u{0020}random\u{0020}stuff\u{0020}while\u{0020}diving.\u{0020}Lots\u{0020}of\u{0020}poisonous\u{0020}creatures\u{0020}in\u{0020}the\u{0020}sea,\u{0020}you\u{0020}know.", "0", "姑且提醒一句，潛水時就不要像這樣亂摸亂碰了，海底的有毒物種很多呢。", "0", "0", "0", "cv_yanyanluo_9", "0", "0"},
[412409] = {412409, 11024, 10, 5, "1_》_500_2", "level3", "They\u{0020}say\u{0020}there's\u{0020}a\u{0020}sunken\u{0020}city\u{0020}in\u{0020}the\u{0020}South\u{0020}Pacific.\u{0020}When\u{0020}we\u{0020}have\u{0020}time,\u{0020}want\u{0020}to\u{0020}join\u{0020}me\u{0020}on\u{0020}an\u{0020}epic\u{0020}adventure\u{0020}there?", "0", "據說，在南太平洋的某片海域下有座沉沒之城，等哪天有空，陪我去進行一場驚心動魄的冒險吧？", "0", "0", "0", "cv_yanyanluo_10", "0", "0"},
[412410] = {412410, 11024, 11, 5, "1_》_1000_2.5", "level4", "What\u{0020}does\u{0020}a\u{0020}Navigator\u{0020}like\u{0020}you\u{0020}think\u{0020}about\u{0020}at\u{0020}times\u{0020}like\u{0020}this?\u{0020}Hmm...\u{0020}maybe\u{0020}you\u{0020}should\u{0020}try\u{0020}growing\u{0020}bigger\u{0020}too.\u{0020}I\u{0020}kinda\u{0020}want\u{0020}to\u{0020}dive\u{0020}into\u{0020}your\u{0020}mind.", "0", "在這種時候，領航的內心到底會思考些什麼呢？唔……要不你也試試讓身體巨大化？我有些想潛入你的心裏一探究竟了。", "0", "0", "0", "cv_yanyanluo_11", "0", "0"},
[412411] = {412411, 11024, 12, 6, "0", "0", "Yes!", "0", "好耶——", "0", "0", "0", "cv_yanyanluo_12", "0", "0"},
[412412] = {412412, 11024, 13, 7, "0", "0", "I've\u{0020}gotten\u{0020}stronger,\u{0020}but\u{0020}how\u{0020}much\u{0020}potential\u{0020}do\u{0020}I\u{0020}have\u{0020}left?", "0", "又變強了，可我的潛力究竟還剩多少呢？", "0", "0", "0", "cv_yanyanluo_13", "0", "0"},
[412413] = {412413, 11024, 14, 8, "0", "0", "When\u{0020}deep\u{0020}diving,\u{0020}it's\u{0020}not\u{0020}the\u{0020}endless\u{0020}darkness\u{0020}that\u{0020}scares\u{0020}me,\u{0020}it's\u{0020}the\u{0020}\"boundary\"\u{0020}that\u{0020}suddenly\u{0020}appears.\u{0020}It\u{0020}means\u{0020}the\u{0020}journey's\u{0020}about\u{0020}to\u{0020}end.\u{0020}But\u{0020}every\u{0020}time\u{0020}I\u{0020}reach\u{0020}the\u{0020}seabed,\u{0020}I'm\u{0020}still\u{0020}moved\u{0020}by\u{0020}the\u{0020}view.\u{0020}Thanks,\u{0020}Navigator,\u{0020}for\u{0020}showing\u{0020}me\u{0020}such\u{0020}sights.", "0", "深潛時，無垠的黑暗並不令我害怕，不期而遇的“邊界”才會，因為它將宣告著這趟旅途到此為止。然而每當抵達海底，我仍會被終點的景色觸動。領航，謝謝你引領我看見這種景色。", "0", "0", "0", "cv_yanyanluo_14", "0", "0"},
[412414] = {412414, 11024, 15, 9, "0", "0", "I\u{0020}can't\u{0020}wait\u{0020}to\u{0020}show\u{0020}off\u{0020}my\u{0020}new\u{0020}power.", "0", "我迫不及待展現新的力量了。", "0", "0", "0", "cv_yanyanluo_15", "0", "0"},
[412415] = {412415, 11024, 16, 10, "0", "0", "Let\u{0020}me\u{0020}take\u{0020}point.", "0", "由我擔任前鋒吧。", "0", "0", "0", "cv_yanyanluo_16", "0", "0"},
[412416] = {412416, 11024, 17, 11, "0", "0", "Is\u{0020}this\u{0020}what\u{0020}a\u{0020}perfect\u{0020}victory\u{0020}feels\u{0020}like?", "0", "這就是完美的勝利嗎？", "0", "0", "0", "cv_yanyanluo_17", "0", "0"},
[412417] = {412417, 11024, 18, 12, "0", "0", "Are\u{0020}you\u{0020}aiming\u{0020}for\u{0020}even\u{0020}greater\u{0020}results?\u{0020}I\u{0020}won't\u{0020}be\u{0020}satisfied\u{0020}with\u{0020}just\u{0020}this.", "0", "你會追求更加完美的結果嗎？反正我不會滿足於此哦。", "0", "0", "0", "cv_yanyanluo_18", "0", "0"},
