[412425] = {412425, 11024, 28, 21, "0", "0", "With\u{0020}this\u{0020}much\u{0020}steam,\u{0020}it's\u{0020}practically\u{0020}a\u{0020}sauna.\u{0020}Let's\u{0020}see\u{0020}who\u{0020}can\u{0020}last\u{0020}the\u{0020}longest.", "0", "雲蒸霧繞的程度都能讓人體驗桑拿了，我們來比比誰能撐更久吧。", "0", "0", "0", "cv_yanyanluo_26", "0", "0"},
[412426] = {412426, 11024, 29, 21, "0", "0", "Wouldn't\u{0020}it\u{0020}be\u{0020}funny\u{0020}if\u{0020}Haze\u{0020}mist\u{0020}drifted\u{0020}into\u{0020}the\u{0020}bath?", "0", "這種時候要是蒼霧侵入浴室就有意思了。", "0", "0", "0", "cv_yanyanluo_27", "0", "0"},
[412427] = {412427, 11024, 30, 22, "0", "0", "Hurry\u{0020}up.", "0", "快點快點。", "0", "0", "0", "cv_yanyanluo_28", "0", "0"},
[412428] = {412428, 11024, 31, 23, "0", "0", "You're\u{0020}smart,\u{0020}I\u{0020}know\u{0020}you\u{0020}won't\u{0020}guess\u{0020}wrong,\u{0020}right?", "0", "聰明如你不會猜錯的吧？", "0", "0", "0", "cv_yanyanluo_29", "0", "0"},
[412429] = {412429, 11024, 32, 24, "0", "0", "So,\u{0020}this\u{0020}is\u{0020}the\u{0020}answer\u{0020}in\u{0020}your\u{0020}heart,\u{0020}huh?\u{0020}I\u{0020}understand\u{0020}now.", "0", "這就是你心中的答案啊，我瞭解了。", "0", "0", "0", "cv_yanyanluo_30", "0", "0"},
[412430] = {412430, 11024, 33, 25, "0", "0", "Instead\u{0020}of\u{0020}just\u{0020}one\u{0020}correct\u{0020}answer,\u{0020}maybe\u{0020}many\u{0020}possibilities\u{0020}are\u{0020}better.", "0", "比起唯一的答案，更多可能性倒也不錯。", "0", "0", "0", "cv_yanyanluo_31", "0", "0"},
[412431] = {412431, 11024, 34, 26, "0", "0", "You're\u{0020}back,\u{0020}time\u{0020}to\u{0020}start\u{0020}work.\u{0020}I\u{0020}want\u{0020}to\u{0020}clock\u{0020}out\u{0020}early\u{0020}today.", "0", "回來了啊，快開始工作吧，我想早點下班。", "0", "0", "0", "cv_yanyanluo_32", "0", "0"},
[412432] = {412432, 11024, 35, 27, "0", "0", "Blow\u{0020}the\u{0020}whistle\u{0020}of\u{0020}fate.", "0", "鳴響命運的汽笛吧。", "0", "0", "0", "cv_yanyanluo_33", "0", "0"},
[412433] = {412433, 11024, 36, 28, "0", "0", "I'm\u{0020}ready\u{0020}for\u{0020}victory\u{0020}after\u{0020}victory.", "0", "我已經做好連戰連勝的準備了哦。", "0", "0", "0", "cv_yanyanluo_34", "0", "0"},
[412434] = {412434, 11024, 37, 29, "0", "0", "Let's\u{0020}see\u{0020}what\u{0020}everyone's\u{0020}up\u{0020}to.", "0", "看看大家都在做什麼。", "0", "0", "0", "cv_yanyanluo_35", "0", "0"},
[412435] = {412435, 11024, 38, 30, "0", "0", "What\u{0020}new\u{0020}fun\u{0020}will\u{0020}I\u{0020}find\u{0020}today?", "0", "又會尋得什麼新樂子呢？", "0", "0", "0", "cv_yanyanluo_36", "0", "0"},
[412436] = {412436, 11024, 39, 31, "0", "0", "The\u{0020}treasures\u{0020}from\u{0020}the\u{0020}underwater\u{0020}temple\u{0020}suit\u{0020}me\u{0020}best.", "0", "還是在海底神殿找到的寶藏更適合我。", "0", "0", "0", "cv_yanyanluo_37", "0", "0"},
[412437] = {412437, 11024, 40, 32, "0", "0", "Human\u{0020}desires\u{0020}run\u{0020}deeper\u{0020}than\u{0020}the\u{0020}sea.", "0", "人的欲望比海還深呢。", "0", "0", "0", "cv_yanyanluo_38", "0", "0"},
[412438] = {412438, 11024, 41, 33, "0", "0", "Take\u{0020}a\u{0020}look.", "0", "看看你的。", "0", "0", "0", "cv_yanyanluo_39", "0", "0"},
