[412440] = {412440, 11024, 43, 35, "0", "0", "Will\u{0020}we\u{0020}get\u{0020}a\u{0020}message\u{0020}in\u{0020}a\u{0020}bottle\u{0020}from\u{0020}the\u{0020}web?", "0", "會收到網路漂流瓶嗎？", "0", "0", "0", "cv_yanyanluo_41", "0", "0"},
[412441] = {412441, 11024, 44, 36, "0", "0", "Only\u{0020}weaklings\u{0020}socialize.", "0", "弱者才社交。", "0", "0", "0", "cv_yanyanluo_42", "0", "0"},
[412442] = {412442, 11024, 45, 37, "0", "0", "Ugh...\u{0020}more\u{0020}stuff\u{0020}to\u{0020}deal\u{0020}with...", "0", "怎麼還有事啊……", "0", "0", "0", "cv_yanyanluo_43", "0", "0"},
[412800] = {412800, 11028, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響", "0", "0", "0", "cv_geiro_1", "0", "0"},
[412801] = {412801, 11028, 2, 2, "0", "0", "Got\u{0020}it.", "了解。", "瞭解。", "0", "0", "0", "cv_geiro_2", "0", "0"},
[412802] = {412802, 11028, 3, 3, "0", "0", "First\u{0020}time\u{0020}meeting...\u{0020}huh?\u{0020}You...\u{0020}oh...\u{0020}excuse\u{0020}me,\u{0020}I\u{0020}am\u{0020}Geiro,\u{0020}one\u{0020}of\u{0020}the\u{0020}Valkyries...\u{0020}and\u{0020}also\u{0020}Katya's\u{0020}strongest\u{0020}Driver.\u{0020}Yes,\u{0020}I\u{0020}can\u{0020}say\u{0020}that\u{0020}with\u{0020}confidence.", "はじめまして…うん？あなたは…あっ、失礼。私はワルキューレが一人、ジェロよ。そしてカティア最強のドライバー。えぇ、その自信があるわ。", "初次見面…嗯？你…啊…失禮了，我是潔蘿，是瓦爾基裏的一員…同時也是卡佳最強的駕駛員。嗯，我有說出這句話的自信。", "0", "0", "0", "cv_geiro_3", "0", "0"},
[412803] = {412803, 11028, 4, 4, "0", "idle", "Navigator...\u{0020}you're\u{0020}not\u{0020}human,\u{0020}are\u{0020}you?\u{0020}At\u{0020}least,\u{0020}part\u{0020}of\u{0020}the\u{0020}blood\u{0020}flowing\u{0020}in\u{0020}your\u{0020}veins\u{0020}isn't\u{0020}human.\u{0020}How\u{0020}do\u{0020}I\u{0020}know\u{0020}your\u{0020}secret?\u{0020}...I\u{0020}don't\u{0020}know,\u{0020}maybe\u{0020}it's\u{0020}just\u{0020}intuition.", "ナビゲーター、あなた人間じゃ…ないわよね。少なくとも、人間じゃない血が混ざってる。どうして知ってるのかって？…私も分からないわ、ただそう感じただけよ。", "領航…你並不是人類吧？至少，你血管裏流淌著的血液中，有一部分不屬於人類。為什麼會知道你的秘密？…我也不知道，或許只是直覺而已吧。", "0", "0", "0", "cv_geiro_4", "0", "0"},
[412804] = {412804, 11028, 5, 4, "0", "idle", "Huh—you\u{0020}seem\u{0020}more\u{0020}relaxed\u{0020}than\u{0020}I\u{0020}imagined.\u{0020}Seeing\u{0020}your\u{0020}carefree\u{0020}attitude,\u{0020}it's\u{0020}a\u{0020}bit\u{0020}unsettling.", "ん～、あなた…想像してたよりものんびりしてるのね。その余裕のある態度、なんかムカつくわ。", "誒——你…比我想像中還要悠閒呢。看到你這份遊刃有餘的態度，真不舒服。", "0", "0", "0", "cv_geiro_5", "0", "0"},
[412805] = {412805, 11028, 6, 4, "0", "idle", "\"Life\u{0020}only\u{0020}happens\u{0020}once,\u{0020}and\u{0020}everyone\u{0020}has\u{0020}a\u{0020}duty\u{0020}to\u{0020}figure\u{0020}out\u{0020}how\u{0020}to\u{0020}spend\u{0020}it\u{0020}before\u{0020}death\u{0020}arrives.\u{0020}You\u{0020}get\u{0020}to\u{0020}decide\u{0020}who\u{0020}you\u{0020}become.\"\u{0020}That's\u{0020}what\u{0020}that\u{0020}doctor\u{0020}once\u{0020}told\u{0020}me.\u{0020}I\u{0020}hope\u{0020}you\u{0020}think\u{0020}it\u{0020}over\u{0020}too,\u{0020}Navigator.", "「人生は一回限り、死が訪れる前に自分の人生をどうやって費やすのを考えなければならない。どんな人になるのか、決めるのは己自身だ。」これはあの医師に言われたこと。ナビゲーターにもその意味をちゃんと考えて欲しいの。", "“生命只有一次，每個人都有義務在死亡到來前想好怎麼揮霍它。想要成為怎樣的人，由你自己決定。”這是那位醫生對我說過的話，我希望領航你也能好好思考它的含義。", "0", "0", "0", "cv_geiro_6", "0", "0"},
[412806] = {412806, 11028, 7, 5, "1_》_0_0.8", "level1", "The\u{0020}world\u{0020}in\u{0020}chaos\u{0020}can\u{0020}only\u{0020}return\u{0020}to\u{0020}peace\u{0020}by\u{0020}eradicating\u{0020}all\u{0020}Sin.\u{0020}For\u{0020}that\u{0020}day\u{0020}to\u{0020}come\u{0020}sooner,\u{0020}I\u{0020}will\u{0020}keep\u{0020}fighting—for\u{0020}myself\u{0020}and\u{0020}for\u{0020}humanity.", "平和を取り戻すには、全ての原罪を駆除しなくちゃならない。そんな日が一日も早く来るよう、私は戦い続ける。私自身のためにも、人類のためにも。", "動亂的世界想要恢復和平，就必須剷除所有的原罪。為了讓那一天儘早到來，我會一直戰鬥下去，為了我自己，為了人類。", "0", "0", "0", "cv_geiro_7", "0", "0"},
[412807] = {412807, 11028, 8, 5, "1_》_0_0.8", "level1", "Please\u{0020}don't\u{0020}touch\u{0020}me\u{0020}so\u{0020}casually...\u{0020}that's\u{0020}just\u{0020}a\u{0020}word\u{0020}of\u{0020}advice\u{0020}for\u{0020}your\u{0020}own\u{0020}safety.", "気安く触らないで…これはあなたための忠告よ。", "請不要隨便觸碰我…這是為了你的安全著想才說的忠告。", "0", "0", "0", "cv_geiro_8", "0", "0"},
[412808] = {412808, 11028, 9, 5, "1_》_100_1.5", "level2", "Seriously,\u{0020}didn't\u{0020}I\u{0020}just\u{0020}say\u{0020}not\u{0020}to\u{0020}touch\u{0020}me?\u{0020}I'm\u{0020}not\u{0020}trying\u{0020}to\u{0020}scare\u{0020}you.\u{0020}It's\u{0020}just\u{0020}that\u{0020}I\u{0020}still\u{0020}can't\u{0020}fully\u{0020}control\u{0020}my\u{0020}strength.\u{0020}What\u{0020}if\u{0020}I\u{0020}accidentally\u{0020}hurt\u{0020}you?", "まったく、触らないでって言ったはずよ…脅しじゃないわ。私はまだ自分の力を完璧にコントロール出来ないの。怪我したらどうすれば？", "真是的，我不是說了不要碰我嗎…我沒有在嚇你啦。我還不能很好地控制自己的力量，要是傷到你了該怎麼辦啊？", "0", "0", "0", "cv_geiro_9", "0", "0"},
[412809] = {412809, 11028, 10, 5, "1_》_500_2", "level3", "I've\u{0020}traveled\u{0020}around\u{0020}Katya\u{0020}for\u{0020}a\u{0020}while,\u{0020}so\u{0020}I\u{0020}understand\u{0020}it\u{0020}well.\u{0020}Without\u{0020}AEGIS,\u{0020}the\u{0020}civilians\u{0020}would\u{0020}be\u{0020}in\u{0020}a\u{0020}much\u{0020}worse\u{0020}state.\u{0020}That\u{0020}journey\u{0020}also\u{0020}made\u{0020}me\u{0020}reevaluate\u{0020}what\u{0020}I\u{0020}have\u{0020}and\u{0020}made\u{0020}me\u{0020}question\u{0020}what\u{0020}kind\u{0020}of\u{0020}person\u{0020}I\u{0020}should\u{0020}become.\u{0020}Why\u{0020}am\u{0020}I\u{0020}telling\u{0020}you\u{0020}this...?\u{0020}How\u{0020}strange.", "カティアを旅してた私には分かるの。アイギスがなかったら、みんなは今よりも酷い生活を送っていただろうって。だから私は自分を見つめ直して、どんな人間になりたいかを考えたの。……どうしてあなたにこんなことを…変ね。", "我在卡佳遊歷過一段時間，所以心裏很清楚。如果沒有艾吉斯，那些平民只會過得比現在更糟。也是這段經歷，讓我審視起自己擁有的東西，去思考自己該成為什麼樣的人。…為什麼我會和你說這些啊…真奇怪。", "0", "0", "0", "cv_geiro_10", "0", "0"},
[412810] = {412810, 11028, 11, 5, "1_》_1000_2.5", "level4", "AEGIS\u{0020}can\u{0020}lead\u{0020}humanity\u{0020}to\u{0020}a\u{0020}better\u{0020}future,\u{0020}but\u{0020}I'm\u{0020}sure\u{0020}there's\u{0020}no\u{0020}place\u{0020}for\u{0020}me\u{0020}there.\u{0020}Navigator,\u{0020}I\u{0020}will\u{0020}protect\u{0020}AEGIS\u{0020}and\u{0020}humanity's\u{0020}present,\u{0020}but\u{0020}their\u{0020}future\u{0020}will\u{0020}be\u{0020}in\u{0020}your\u{0020}hands.\u{0020}Even\u{0020}though\u{0020}you're\u{0020}not\u{0020}always\u{0020}serious...\u{0020}I\u{0020}believe\u{0020}in\u{0020}you,\u{0020}you\u{0020}can\u{0020}do\u{0020}it.", "アイギスは人類を素晴らしい未来へ導いてくれるけど、その未来に私の居場所はないでしょうね。ナビゲーター、私はアイギスの、人類の今を守る。だけど未来はあなたに任せるわ。時々不真面目な所もあるけど…あなたなら出来ると信じてるわ。", "艾吉斯能帶領人類前往美好的未來，但我確信那個地方不會有我的位置。領航，我會守護艾吉斯的，人類的現在，而他們的未來則拜託你了。雖然你有時候挺不正經的…但我相信你，你一定能做到的。", "0", "0", "0", "cv_geiro_11", "0", "0"},
[412811] = {412811, 11028, 12, 6, "0", "0", "Thanks\u{0020}for\u{0020}that.", "ありがとう。", "謝謝。", "0", "0", "0", "cv_geiro_12", "0", "0"},
[412812] = {412812, 11028, 13, 7, "0", "0", "I'll\u{0020}eradicate\u{0020}every\u{0020}Sin,\u{0020}not\u{0020}leaving\u{0020}a\u{0020}single\u{0020}one.", "私は必ず全ての原罪を退治する。一匹も残らさないわ。", "我會消滅所有原罪，一只也不會剩。", "0", "0", "0", "cv_geiro_13", "0", "0"},
[412813] = {412813, 11028, 14, 8, "0", "0", "Power\u{0020}can\u{0020}make\u{0020}one\u{0020}lose\u{0020}themselves,\u{0020}especially\u{0020}when\u{0020}that\u{0020}power\u{0020}surpasses\u{0020}all\u{0020}common\u{0020}sense.\u{0020}So,\u{0020}I've\u{0020}always\u{0020}been\u{0020}questioning\u{0020}my\u{0020}own\u{0020}heart,\u{0020}asking\u{0020}myself\u{0020}how\u{0020}to\u{0020}use\u{0020}this\u{0020}power.\u{0020}Navigator,\u{0020}please\u{0020}help\u{0020}me\u{0020}use\u{0020}it\u{0020}in\u{0020}the\u{0020}right\u{0020}way.\u{0020}Thank\u{0020}you.", "力を持つと人は自分自身を見失いやすくなる、その力が強ければ強いほどね。だから、私はいつも自分の心に問うの、この力の使い方を。ナビゲーター、どうか私と共に、この力を正しく使ってね。", "力量會讓人迷失自我，尤其是當這份力量強大到超越常識的時候。所以，我一直在審問著自己的心，詢問自己該如何使用這份力量。領航，請和我一起將這份力量用在正確的地方上吧，謝謝。", "0", "0", "0", "cv_geiro_14", "0", "0"},
[412814] = {412814, 11028, 15, 9, "0", "0", "I\u{0020}need\u{0020}to\u{0020}learn\u{0020}more\u{0020}skills\u{0020}from\u{0020}my\u{0020}seniors.", "先輩からもっとスキルを学ばないと。", "我需要向前輩們學習更多技能。", "0", "0", "0", "cv_geiro_15", "0", "0"},
[412815] = {412815, 11028, 16, 10, "0", "0", "I'll\u{0020}use\u{0020}my\u{0020}power\u{0020}in\u{0020}the\u{0020}right\u{0020}place.", "この力…正しく使うわ。", "我會將自己的力量…用在正確的地方。", "0", "0", "0", "cv_geiro_16", "0", "0"},
[412816] = {412816, 11028, 17, 11, "0", "0", "Navigator,\u{0020}we\u{0020}need\u{0020}more\u{0020}victories.", "ナビゲーター、私たちにはもっと勝利が必要よ。", "領航，我們還需要更多勝利。", "0", "0", "0", "cv_geiro_17", "0", "0"},
[412817] = {412817, 11028, 18, 12, "0", "0", "First,\u{0020}we\u{0020}should\u{0020}assess\u{0020}the\u{0020}damage\u{0020}to\u{0020}the\u{0020}city.", "まずは街の被害状況を確認しましょう。", "先確認城市的受損情況吧。", "0", "0", "0", "cv_geiro_18", "0", "0"},
[412818] = {412818, 11028, 19, 13, "0", "0", "...Are\u{0020}you\u{0020}okay?\u{0020}You're\u{0020}not\u{0020}hurt,\u{0020}are\u{0020}you?", "…あなたは大丈夫？怪我してない？", "…你沒事吧？沒有受傷吧？", "0", "0", "0", "cv_geiro_19", "0", "0"},
[412819] = {412819, 11028, 20, 14, "0", "0", "Regroup...\u{0020}I\u{0020}can\u{0020}still\u{0020}keep\u{0020}fighting.", "陣形を立て直して…私はまだ戦える。", "重整旗鼓…我還能繼續戰鬥。", "0", "0", "0", "cv_geiro_20", "0", "0"},
[412820] = {412820, 11028, 21, 15, "0", "0", "Keep\u{0020}going.", "次！", "繼續。", "0", "0", "0", "cv_geiro_22", "0", "0"},
[412821] = {412821, 11028, 23, 16, "0", "0", "Die.", "はあーー！", "去死吧。", "0", "0", "0", "cv_geiro_21", "0", "0"},
[412822] = {412822, 11028, 24, 17, "0", "0", "Energy\u{0020}collection\u{0020}rate...\u{0020}increased.", "エネルギー収集率…限界突破！", "能量收集率…提高。", "0", "0", "0", "cv_geiro_24", "0", "0"},
[412823] = {412823, 11028, 26, 19, "0", "0", "Not\u{0020}enough...\u{0020}I\u{0020}can't\u{0020}collapse\u{0020}here.", "まだよ…ここで倒れる訳には…", "還不行…我不能在這裏倒下。", "0", "0", "0", "cv_geiro_23", "0", "0"},
[412824] = {412824, 11028, 27, 20, "0", "0", "...Huh?\u{0020}Wha-why-why\u{0020}are\u{0020}you\u{0020}in\u{0020}here?!\u{0020}Get\u{0020}out\u{0020}now!", "…え？ど…どうしてあなたがここに！早く出ていって！", "…誒？為…為、為什麼你能進來這裏啊！快出去啊！", "0", "0", "0", "cv_geiro_25", "0", "0"},
[412825] = {412825, 11028, 28, 21, "0", "0", "I\u{0020}thought\u{0020}you\u{0020}were\u{0020}a\u{0020}serious\u{0020}person...\u{0020}you\u{0020}pervert!\u{0020}Scoundrel!\u{0020}How\u{0020}long\u{0020}are\u{0020}you\u{0020}planning\u{0020}to\u{0020}stay?!", "まともな奴かと思ってたのに…この変態！スケベ！いつまでここに居るのよ！", "我還以為你是一個正經人…你這變態！色狼！真是的，你到底要待到什麼時候啊！", "0", "0", "0", "cv_geiro_26", "0", "0"},
[412826] = {412826, 11028, 29, 21, "0", "0", "If\u{0020}you\u{0020}see\u{0020}something\u{0020}you\u{0020}shouldn't,\u{0020}you'll\u{0020}regret\u{0020}it!", "もし見ちゃいけないものを見てたら、後悔するわよ！", "如果看到了不該看的東西，你會後悔的！", "0", "0", "0", "cv_geiro_27", "0", "0"},
[412827] = {412827, 11028, 30, 22, "0", "0", "...What's\u{0020}wrong?", "…どうしたの？", "…怎麼了？", "0", "0", "0", "cv_geiro_28", "0", "0"},
[412828] = {412828, 11028, 31, 23, "0", "0", "Hmph,\u{0020}what\u{0020}a\u{0020}boring\u{0020}game.", "ふーん、つまらない遊びね。", "哼，原來是這種無聊的遊戲。", "0", "0", "0", "cv_geiro_29", "0", "0"},
[412829] = {412829, 11028, 32, 24, "0", "0", "If\u{0020}you\u{0020}have\u{0020}time\u{0020}to\u{0020}wait\u{0020}for\u{0020}my\u{0020}praise,\u{0020}you\u{0020}might\u{0020}as\u{0020}well\u{0020}do\u{0020}something\u{0020}more\u{0020}meaningful,\u{0020}you\u{0020}pervert.", "褒め言葉を待ってる時間があるなら、もっと有意義なことに使えば？この変態。", "有時間等我誇獎的話，不如去做更加有意義的事情，你這變態。", "0", "0", "0", "cv_geiro_30", "0", "0"},
[412830] = {412830, 11028, 33, 25, "0", "0", "I\u{0020}didn't\u{0020}expect\u{0020}anything\u{0020}from\u{0020}the\u{0020}start.", "最初から期待してなかったわ。", "我一開始就沒有過期待。", "0", "0", "0", "cv_geiro_31", "0", "0"},
[412831] = {412831, 11028, 34, 26, "0", "0", "You've\u{0020}finally\u{0020}come...\u{0020}It's\u{0020}not\u{0020}that\u{0020}I\u{0020}was\u{0020}lonely,\u{0020}just\u{0020}that\u{0020}you\u{0020}shouldn't\u{0020}stay\u{0020}away\u{0020}from\u{0020}your\u{0020}post\u{0020}for\u{0020}too\u{0020}long.", "やっと来たわね…寂しかったわけじゃないわ、ただ持ち場から長時間離れないで欲しいだけ。", "終於來了嗎…我可沒有寂寞，只是希望你不要離開崗位太久而已。", "0", "0", "0", "cv_geiro_32", "0", "0"},
[412832] = {412832, 11028, 35, 27, "0", "0", "Let's\u{0020}go,\u{0020}sweep\u{0020}away\u{0020}the\u{0020}clouds\u{0020}looming\u{0020}over\u{0020}the\u{0020}world.", "出発しましょう、世界を覆う暗雲を一掃するわよ。", "出發吧，將籠罩在世界上方的烏雲一掃而盡吧。", "0", "0", "0", "cv_geiro_33", "0", "0"},
[412833] = {412833, 11028, 36, 28, "0", "0", "Unnecessary\u{0020}drills...\u{0020}do\u{0020}as\u{0020}you\u{0020}please.", "余計な演習だけど…好きにして。", "多餘的演習…隨你喜歡吧。", "0", "0", "0", "cv_geiro_34", "0", "0"},
[412834] = {412834, 11028, 37, 29, "0", "0", "Let\u{0020}me\u{0020}just\u{0020}say,\u{0020}I\u{0020}am\u{0020}definitely\u{0020}the\u{0020}strongest\u{0020}one\u{0020}here.", "先に言っておくけど、この中で一番強いのはおそらく私よ。", "姑且說一下，我一定是最強的那一個。", "0", "0", "0", "cv_geiro_35", "0", "0"},
[412835] = {412835, 11028, 38, 30, "0", "0", "Are\u{0020}you\u{0020}looking\u{0020}to\u{0020}strengthen\u{0020}the\u{0020}team?", "チームを補強するの？", "要補強隊伍嗎？", "0", "0", "0", "cv_geiro_36", "0", "0"},
[412836] = {412836, 11028, 39, 31, "0", "0", "Arm\u{0020}yourself\u{0020}as\u{0020}much\u{0020}as\u{0020}you\u{0020}can.", "出来る限り装備を整えなさい。", "盡可能的武裝自己吧。", "0", "0", "0", "cv_geiro_37", "0", "0"},
[412837] = {412837, 11028, 40, 32, "0", "0", "It's\u{0020}all\u{0020}luxury\u{0020}items\u{0020}anyway.", "贅沢品ばかりね。", "都是些奢侈品呢。", "0", "0", "0", "cv_geiro_38", "0", "0"},
[412838] = {412838, 11028, 41, 33, "0", "0", "Are\u{0020}you\u{0020}showing\u{0020}off\u{0020}your\u{0020}medals?", "勲章を見せびらかしているの？", "在炫耀勳章嗎？", "0", "0", "0", "cv_geiro_39", "0", "0"},
[412839] = {412839, 11028, 42, 34, "0", "0", "Settings...\u{0020}so\u{0020}boring.", "セッティングね…任せるわ。", "設置…真無聊。", "0", "0", "0", "cv_geiro_40", "0", "0"},
[412840] = {412840, 11028, 43, 35, "0", "0", "I'm\u{0020}not\u{0020}going\u{0020}to\u{0020}peek.", "覗いたりしないわよ。", "我是不會偷看的。", "0", "0", "0", "cv_geiro_41", "0", "0"},
[412841] = {412841, 11028, 44, 36, "0", "0", "How\u{0020}leisurely.", "本当に暇ね。", "真是悠閒呢。", "0", "0", "0", "cv_geiro_42", "0", "0"},
[412842] = {412842, 11028, 45, 37, "0", "0", "What's\u{0020}the\u{0020}matter?", "どうしたの？", "怎麼了？", "0", "0", "0", "cv_geiro_43", "0", "0"},
[412900] = {412900, 11029, 1, 1, "0", "0", "Haze\u{0020}reverb.", "ハツリバーブ", "蒼霧殘響", "0", "0", "0", "cv_qianmo_1", "0", "0"},
[412901] = {412901, 11029, 2, 2, "0", "0", "Even\u{0020}the\u{0020}president\u{0020}of\u{0020}the\u{0020}student\u{0020}council\u{0020}can't\u{0020}escape\u{0020}being\u{0020}on\u{0020}duty.", "生徒会長も例外なく、日直を担当します。", "就算是學生會長也不能逃避值日。", "0", "0", "0", "cv_qianmo_2", "0", "0"},
[412902] = {412902, 11029, 3, 3, "0", "0", "Good\u{0020}morning,\u{0020}Mr.\u{0020}Navigator.\u{0020}Senhaku\u{0020}of\u{0020}the\u{0020}Fledgeling\u{0020}Eagle\u{0020}reporting\u{0020}for\u{0020}duty.\u{0020}I'll\u{0020}be\u{0020}relying\u{0020}on\u{0020}you\u{0020}from\u{0020}now\u{0020}on.", "おはようございます、先生。雛鷹（ひなたか）所属の、千陌（せんはく）です。これからよろしくお願いします。", "早安，領航先生，雛鷹小隊千陌報導，今後就麻煩您了。", "0", "0", "0", "cv_qianmo_3", "0", "0"},
[412903] = {412903, 11029, 4, 4, "0", "idle", "Is\u{0020}it\u{0020}within\u{0020}the\u{0020}regulations\u{0020}to\u{0020}give\u{0020}such\u{0020}advanced\u{0020}equipment\u{0020}to\u{0020}an\u{0020}intern?", "インターン生にこのような高性能の装備を与えて、問題はないのでしょうか？", "給實習生裝備這麼精良的裝備合乎規定嗎？", "0", "0", "0", "cv_qianmo_4", "0", "0"},
[412904] = {412904, 11029, 5, 4, "0", "idle", "According\u{0020}to\u{0020}the\u{0020}break\u{0020}schedule,\u{0020}it's\u{0020}almost\u{0020}break\u{0020}time.", "スケジュールによると、もうすぐ休憩時間です。", "按照休息表上的時間，馬上就是休息時間了。", "0", "0", "0", "cv_qianmo_5", "0", "0"},
[412905] = {412905, 11029, 6, 4, "0", "idle", "Honestly,\u{0020}I've\u{0020}always\u{0020}opposed\u{0020}the\u{0020}\"Fledgeling\u{0020}Eagle\u{0020}Project.\"\u{0020}Sending\u{0020}inexperienced\u{0020}students\u{0020}into\u{0020}battle\u{0020}is\u{0020}just\u{0020}rushing\u{0020}things.\u{0020}As\u{0020}it\u{0020}stands,\u{0020}only\u{0020}I\u{0020}and\u{0020}Karen\u{0020}at\u{0020}the\u{0020}academy\u{0020}are\u{0020}capable\u{0020}of\u{0020}performing\u{0020}real\u{0020}combat\u{0020}missions.", "私は「雛鷹プロジェクト」には反対です。戦闘経験のない学生を戦場に送るなど、助長抜苗（じょちょうばつびょう）でしかありません。現時点で実戦任務を遂行できるのは、私とカリンだけです。", "其實我一直反對“雛鷹計畫”，讓沒有經驗的學生上戰場就是在揠苗助長。目前來看，學院裏有能力執行實戰任務的只有我和卡蓮。", "0", "0", "0", "cv_qianmo_6", "0", "0"},
[412906] = {412906, 11029, 7, 5, "1_》_0_0.8", "level1", "Survival\u{0020}of\u{0020}the\u{0020}fittest\u{0020}may\u{0020}be\u{0020}the\u{0020}law\u{0020}of\u{0020}nature,\u{0020}but\u{0020}it's\u{0020}not\u{0020}the\u{0020}law\u{0020}of\u{0020}human\u{0020}development.\u{0020}So,\u{0020}even\u{0020}if\u{0020}Sin\u{0020}is\u{0020}a\u{0020}thousand\u{0020}times\u{0020}stronger\u{0020}than\u{0020}us,\u{0020}I\u{0020}will\u{0020}never\u{0020}bow\u{0020}my\u{0020}head.", "自然界においては弱肉強食が正しいのかもしれませんが、人類が発展したのは、それだけが理由ではないはずです。だからこそ、原罪が私たちの百倍、いえ、千倍強くとも屈することはありません。", "弱肉強食雖合乎自然生存之法，但並不合乎人類發展之法。所以縱使原罪比我們強上千倍百倍，我也不會低頭。", "0", "0", "0", "cv_qianmo_7", "0", "0"},
[412907] = {412907, 11029, 8, 5, "1_》_0_0.8", "level1", "Harassing\u{0020}students\u{0020}is\u{0020}a\u{0020}serious\u{0020}crime.\u{0020}Please\u{0020}think\u{0020}twice,\u{0020}sir.", "学生への迷惑行為は重大な犯罪です。慎重に考えてください。", "騷擾學生可是重大犯罪，請先生三思。", "0", "0", "0", "cv_qianmo_8", "0", "0"},
[412908] = {412908, 11029, 9, 5, "1_》_100_1.5", "level2", "It's\u{0020}work\u{0020}hours...\u{0020}if\u{0020}you\u{0020}want\u{0020}to\u{0020}complain,\u{0020}you\u{0020}can\u{0020}do\u{0020}it\u{0020}after\u{0020}we're\u{0020}done\u{0020}working,\u{0020}sir.", "仕事中です。愚痴を言いたければ、仕事が終わってからお聞きしましょう。", "現在是工作時間……想發牢騷的話可以在工作結束後說，先生。", "0", "0", "0", "cv_qianmo_9", "0", "0"},
[412909] = {412909, 11029, 10, 5, "1_》_500_2", "level3", "What\u{0020}you\u{0020}said\u{0020}last\u{0020}time\u{0020}about\u{0020}Sin's\u{0020}movement\u{0020}patterns\u{0020}differs\u{0020}from\u{0020}what\u{0020}we\u{0020}learned\u{0020}in\u{0020}school.\u{0020}If\u{0020}we\u{0020}go\u{0020}by\u{0020}the\u{0020}textbook\u{0020}in\u{0020}combat,\u{0020}we'd\u{0020}likely\u{0020}suffer\u{0020}a\u{0020}major\u{0020}defeat.", "先生から教わった原罪の行動パターンは、学校で聞いたものとずいぶん違いますね……もし実戦で教科書通りに動いたら、あっさりと敗北してしまうかもしれません……", "先生上次說到的原罪行動方式，和學校裏老師所教學的有些出入。如果在實戰中按照教材來應對，想必會敗得很慘吧。", "0", "0", "0", "cv_qianmo_10", "0", "0"},
[412910] = {412910, 11029, 11, 5, "1_》_1000_2.5", "level4", "Your\u{0020}knowledge\u{0020}and\u{0020}experience\u{0020}far\u{0020}surpass\u{0020}mine.\u{0020}Unfortunately,\u{0020}as\u{0020}an\u{0020}intern,\u{0020}I\u{0020}can't\u{0020}study\u{0020}under\u{0020}you\u{0020}for\u{0020}long.\u{0020}I\u{0020}hope\u{0020}that\u{0020}after\u{0020}I\u{0020}become\u{0020}a\u{0020}full\u{0020}Driver,\u{0020}we\u{0020}can\u{0020}continue\u{0020}to\u{0020}work\u{0020}together.", "先生の知識と経験は想像以上でした。もっと先生の元で学びたいのですが……インターン生ですから、残された時間は多くありません。将来、一人前のドライバーになって、先生と一緒に仕事をすることが私の目標です。", "先生的學識和見聞超過我太多。遺憾的是作為實習生，不能長久地在先生身邊學習。希望在成為真正的駕駛員之後可以繼續和先生共事。", "0", "0", "0", "cv_qianmo_11", "0", "0"},
[412911] = {412911, 11029, 12, 6, "0", "0", "Thank\u{0020}you\u{0020}for\u{0020}your\u{0020}guidance.", "教えに感謝します。", "感謝教誨。", "0", "0", "0", "cv_qianmo_12", "0", "0"},
[412912] = {412912, 11029, 13, 7, "0", "0", "Talking\u{0020}with\u{0020}you,\u{0020}sir,\u{0020}really\u{0020}opens\u{0020}up\u{0020}my\u{0020}mind.", "先生との会話は、本当に得ることが多いです。", "與先生閒聊真的感悟頗豐。", "0", "0", "0", "cv_qianmo_13", "0", "0"},
[412913] = {412913, 11029, 14, 8, "0", "0", "By\u{0020}the\u{0020}rules,\u{0020}this\u{0020}kind\u{0020}of\u{0020}power\u{0020}shouldn't\u{0020}be\u{0020}given\u{0020}to\u{0020}an\u{0020}intern\u{0020}driver.\u{0020}Does\u{0020}this\u{0020}mean,\u{0020}sir,\u{0020}that\u{0020}you\u{0020}already\u{0020}see\u{0020}me\u{0020}as\u{0020}a\u{0020}full-fledged\u{0020}driver?", "規定では、これはインターン生が持つべき力ではありません。先生の心の中では、私を一人前のドライバーと認めてくださったのですか？", "按規矩這不該是實習駕駛員應該獲得的力量，難道在先生心中，我已經是正式的駕駛員了嗎？", "0", "0", "0", "cv_qianmo_14", "0", "0"},
[412914] = {412914, 11029, 15, 9, "0", "0", "Such\u{0020}a\u{0020}valuable\u{0020}gift,\u{0020}sir,\u{0020}you\u{0020}really\u{0020}didn't\u{0020}need\u{0020}to\u{0020}go\u{0020}all\u{0020}out.", "このように貴重なもの、いただけません。", "如此貴重的禮物，不該讓先生如此破費。", "0", "0", "0", "cv_qianmo_15", "0", "0"},
[412915] = {412915, 11029, 16, 10, "0", "0", "Anyone\u{0020}who\u{0020}destroys\u{0020}the\u{0020}city\u{0020}must\u{0020}face\u{0020}justice.", "都市を破壊する者は、厳しく罰せられるべきです。", "毀壞城市者必須嚴懲。", "0", "0", "0", "cv_qianmo_16", "0", "0"},
[412916] = {412916, 11029, 17, 11, "0", "0", "If\u{0020}we\u{0020}follow\u{0020}orders\u{0020}properly,\u{0020}winning\u{0020}will\u{0020}be\u{0020}as\u{0020}easy\u{0020}as\u{0020}flipping\u{0020}a\u{0020}coin.", "優れた指揮で、こうも簡単に勝利できるとは。", "只要按照指揮行動，勝利如探囊取物。", "0", "0", "0", "cv_qianmo_17", "0", "0"},
[412917] = {412917, 11029, 18, 12, "0", "0", "Just\u{0020}managed\u{0020}to\u{0020}hold\u{0020}the\u{0020}line...", "ひとまず守り切ることができました。", "勉強守住了底線。", "0", "0", "0", "cv_qianmo_18", "0", "0"},
[412918] = {412918, 11029, 19, 13, "0", "0", "Victory...\u{0020}What\u{0020}a\u{0020}challenge...", "なんとか勝ちましたが……手こずりました。", "勝利……如此艱難……", "0", "0", "0", "cv_qianmo_19", "0", "0"},
[412919] = {412919, 11029, 20, 14, "0", "0", "We've\u{0020}tried\u{0020}every\u{0020}tactic\u{0020}in\u{0020}the\u{0020}book...", "万策尽きました……", "萬策盡矣……", "0", "0", "0", "cv_qianmo_20", "0", "0"},
[412920] = {412920, 11029, 21, 15, "0", "0", "This\u{0020}is\u{0020}what\u{0020}happens\u{0020}to\u{0020}those\u{0020}who\u{0020}break\u{0020}the\u{0020}rules.", "ルール違反者の末路です。", "這就是破壞規矩者的下場。", "0", "0", "0", "cv_qianmo_21", "0", "0"},
[412921] = {412921, 11029, 23, 16, "0", "0", "It's\u{0020}my\u{0020}turn\u{0020}now.", "私のターンです。", "輪到我的回合了。", "0", "0", "0", "cv_qianmo_22", "0", "0"},
[412922] = {412922, 11029, 24, 17, "0", "0", "No\u{0020}strategy,\u{0020}full\u{0020}of\u{0020}flaws.", "条理なく隙だらけです。", "毫無章法，全是破綻。", "0", "0", "0", "cv_qianmo_23", "0", "0"},
[412923] = {412923, 11029, 26, 19, "0", "0", "Still\u{0020}not\u{0020}quite\u{0020}there...\u{0020}compared\u{0020}to\u{0020}real\u{0020}Drivers...", "やはり……正式のドライバーには叶わないのでしょうか……", "還是比不上……正式的駕駛員……", "0", "0", "0", "cv_qianmo_24", "0", "0"},
[412924] = {412924, 11029, 27, 20, "0", "0", "This\u{0020}place\u{0020}wasn't\u{0020}exactly\u{0020}mentioned\u{0020}in\u{0020}the\u{0020}rulebook.", "レギュレーションにこの場所はなかったようですが。", "規章上可沒提過這個地方。", "0", "0", "0", "cv_qianmo_25", "0", "0"},
[412925] = {412925, 11029, 28, 21, "0", "0", "It's\u{0020}a\u{0020}rare\u{0020}chance\u{0020}to\u{0020}step\u{0020}away\u{0020}from\u{0020}all\u{0020}the\u{0020}student\u{0020}council\u{0020}duties...", "生徒会長の立場を忘れることができたのは久しぶりです……", "難得可以放下學生會的事……", "0", "0", "0", "cv_qianmo_26", "0", "0"},
[412926] = {412926, 11029, 29, 21, "0", "0", "Wait,\u{0020}isn't\u{0020}this\u{0020}the\u{0020}girls'\u{0020}bathroom?\u{0020}Sir,\u{0020}you...", "ここは女湯ですよ、先生……", "這裏不是女生浴室嗎？先生你……", "0", "0", "0", "cv_qianmo_27", "0", "0"},
[412927] = {412927, 11029, 30, 22, "0", "0", "Huh?", "おや？", "嗯？", "0", "0", "0", "cv_qianmo_28", "0", "0"},
[412928] = {412928, 11029, 31, 23, "0", "0", "Nothing\u{0020}about\u{0020}this\u{0020}is\u{0020}in\u{0020}the\u{0020}guidelines.", "レギュレーションには書かれていませんね。", "規則可沒說有這個。", "0", "0", "0", "cv_qianmo_29", "0", "0"},
[412929] = {412929, 11029, 32, 24, "0", "0", "You\u{0020}never\u{0020}fail\u{0020}to\u{0020}surprise,\u{0020}sir.", "先生はやはり、期待を裏切らないですね。", "先生果然不會讓人失望。", "0", "0", "0", "cv_qianmo_30", "0", "0"},
[412930] = {412930, 11029, 33, 25, "0", "0", "But\u{0020}it's\u{0020}fine.\u{0020}By\u{0020}the\u{0020}rules,\u{0020}we\u{0020}should\u{0020}keep\u{0020}a\u{0020}respectable\u{0020}distance.", "大丈夫です。レギュレーション通り、互いの距離を保ちましょう。", "沒關係，按照規定我們保持距離吧。", "0", "0", "0", "cv_qianmo_31", "0", "0"},
[412931] = {412931, 11029, 34, 26, "0", "0", "You're\u{0020}late\u{0020}again\u{0020}today,\u{0020}need\u{0020}me\u{0020}to\u{0020}report\u{0020}how\u{0020}many\u{0020}minutes\u{0020}you\u{0020}were\u{0020}late,\u{0020}sir?", "今日も遅刻ですね。", "今天又遲到了，需要我向您彙報遲到了多久嗎，先生。", "0", "0", "0", "cv_qianmo_32", "0", "0"},
[412932] = {412932, 11029, 35, 27, "0", "0", "Please\u{0020}follow\u{0020}the\u{0020}instructions\u{0020}when\u{0020}setting\u{0020}up\u{0020}the\u{0020}battlefield.", "指示に従い、戦場に展開します。", "請按照指令部署戰場。", "0", "0", "0", "cv_qianmo_33", "0", "0"},
[412933] = {412933, 11029, 36, 28, "0", "0", "I'll\u{0020}give\u{0020}it\u{0020}everything\u{0020}I've\u{0020}got.", "全力を尽くします。", "我會全力以赴的。", "0", "0", "0", "cv_qianmo_34", "0", "0"},
[412934] = {412934, 11029, 37, 29, "0", "0", "Everyone's\u{0020}lined\u{0020}up\u{0020}perfectly.", "皆さん一列で並んでいます。", "大家都很整齊地站著。", "0", "0", "0", "cv_qianmo_35", "0", "0"},
[412935] = {412935, 11029, 38, 30, "0", "0", "Is\u{0020}the\u{0020}battle\u{0020}getting\u{0020}intense?", "戦況が厳しいのでしょうか。", "戰況吃緊了嗎？", "0", "0", "0", "cv_qianmo_36", "0", "0"},
[412936] = {412936, 11029, 39, 31, "0", "0", "New\u{0020}gear's\u{0020}arrived.", "新しい装備の確保です。", "新的裝備。", "0", "0", "0", "cv_qianmo_37", "0", "0"},
[412937] = {412937, 11029, 40, 32, "0", "0", "The\u{0020}prices\u{0020}here...\u{0020}Way\u{0020}too\u{0020}high.", "ここは……値が張りますね。", "這裏的價格……太貴了。", "0", "0", "0", "cv_qianmo_38", "0", "0"},
[412938] = {412938, 11029, 41, 33, "0", "0", "This\u{0020}isn't\u{0020}something\u{0020}interns\u{0020}should\u{0020}be\u{0020}looking\u{0020}at.", "これはインターン生が見るべきものではありません。", "這不是實習生應該看的。", "0", "0", "0", "cv_qianmo_39", "0", "0"},
[412939] = {412939, 11029, 42, 34, "0", "0", "That's\u{0020}out\u{0020}of\u{0020}my\u{0020}jurisdiction.", "これは私の権限を超えています。", "這超出了我的許可權。", "0", "0", "0", "cv_qianmo_40", "0", "0"},
[412940] = {412940, 11029, 43, 35, "0", "0", "This\u{0020}email\u{0020}doesn't\u{0020}follow\u{0020}the\u{0020}standard\u{0020}format...", "このメールはフォーマットに合致していません。", "這份郵件不符合格式……", "0", "0", "0", "cv_qianmo_41", "0", "0"},
[412941] = {412941, 11029, 44, 36, "0", "0", "The\u{0020}post\u{0020}format\u{0020}should\u{0020}be\u{0020}like\u{0020}this...", "このメッセージの書式は……", "發文的格式是……", "0", "0", "0", "cv_qianmo_42", "0", "0"},
[412942] = {412942, 11029, 45, 37, "0", "0", "Click.", "タップしましょう。", "點。", "0", "0", "0", "cv_qianmo_43", "0", "0"},
[413000] = {413000, 11030, 1, 1, "0", "0", "Haze\u{0020}reverb.", "ハツリバーブ", "蒼霧殘響", "0", "0", "0", "cv_chenglian_1", "0", "0"},
[413001] = {413001, 11030, 2, 2, "0", "0", "Shall\u{0020}I\u{0020}act\u{0020}as\u{0020}your\u{0020}advisor?\u{0020}Wonderful.\u{0020}I've\u{0020}been\u{0020}wanting\u{0020}to\u{0020}have\u{0020}a\u{0020}proper\u{0020}conversation\u{0020}with\u{0020}you,\u{0020}Navigator.", "私が参謀、ですか……わかりました。ちょうどナビゲーターさんにお聞きしたいことがたくさんあったんです。", "由我來擔任參謀嗎……正好，我也有很多話想與領航講。", "0", "0", "0", "cv_chenglian_2", "0", "0"},
[413002] = {413002, 11030, 3, 3, "0", "0", "Are\u{0020}you\u{0020}the\u{0020}Navigator\u{0020}from\u{0020}Danube?\u{0020}I\u{0020}am\u{0020}Chenglian,\u{0020}from\u{0020}Kyushu\u{0020}Pingxin.\u{0020}I've\u{0020}waited\u{0020}a\u{0020}long\u{0020}time\u{0020}for\u{0020}this\u{0020}moment.\u{0020}It\u{0020}looks\u{0020}like\u{0020}we'll\u{0020}be\u{0020}working\u{0020}together\u{0020}for\u{0020}quite\u{0020}a\u{0020}while—please\u{0020}guide\u{0020}me.", "あなたがダニューブのナビゲーターさんですね？九州平心社（きゅうしゅうへいしんしゃ）の澄練（ちょうれん）といいます。お会いできるのを楽しみにしていました。長いお付き合いになると思いますが、どうぞよろしくお願いします。", "閣下就是那位來自多瑙的領航吧？九州平心社，澄練，在此久候多時了。可以預見，接下來我們將會共事很長一段時間，請多多指教。", "0", "0", "0", "cv_chenglian_3", "0", "0"},
[413003] = {413003, 11030, 4, 4, "0", "idle", "Do\u{0020}you\u{0020}need\u{0020}any\u{0020}help,\u{0020}Navigator?\u{0020}As\u{0020}a\u{0020}token\u{0020}of\u{0020}thanks\u{0020}for\u{0020}taking\u{0020}care\u{0020}of\u{0020}us,\u{0020}I\u{0020}will\u{0020}assist\u{0020}you\u{0020}as\u{0020}much\u{0020}as\u{0020}possible.\u{0020}Even\u{0020}if\u{0020}I\u{0020}don't\u{0020}know\u{0020}something,\u{0020}I'll\u{0020}learn\u{0020}alongside\u{0020}you.", "平心社がお世話になったお礼として、できる限りの協力をさせてください。分からない事があっても、勉強してできるようになりますから。", "領航需要幫忙嗎，作為照顧我們的回禮，我會在能力範圍內協助您的工作，即使是不了解的事情，我也會跟著領航學習的。", "0", "0", "0", "cv_chenglian_4", "0", "0"},
[413004] = {413004, 11030, 5, 4, "0", "idle", "We\u{0020}need\u{0020}to\u{0020}understand\u{0020}the\u{0020}world\u{0020}through\u{0020}you,\u{0020}Navigator,\u{0020}so\u{0020}I\u{0020}hope\u{0020}you'll\u{0020}rely\u{0020}on\u{0020}us\u{0020}a\u{0020}bit\u{0020}more.\u{0020}Whether\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}or\u{0020}in\u{0020}life...\u{0020}I\u{0020}will\u{0020}document\u{0020}everything\u{0020}about\u{0020}you.", "平心社は塵世（じんせい）を知るために、ナビゲーターさんのお力を必要としています。ですから、ナビゲーターさんももう少し私たちを頼ってください。戦場でも、日常生活でも、些細なことまできちんと記録しますから。", "我們需要通過領航來瞭解塵世，所以我希望領航也能稍微依靠我們一點。在戰場上也好，在生活中……也一樣……我會負責記錄領航的點點滴滴。", "0", "0", "0", "cv_chenglian_5", "0", "0"},
[413005] = {413005, 11030, 6, 4, "0", "idle", "Humans\u{0020}in\u{0020}history\u{0020}have\u{0020}never\u{0020}been\u{0020}so\u{0020}united\u{0020}as\u{0020}they\u{0020}are\u{0020}now.\u{0020}While\u{0020}conflicts\u{0020}are\u{0020}inevitable,\u{0020}everyone\u{0020}is\u{0020}wholeheartedly\u{0020}working\u{0020}for\u{0020}a\u{0020}better\u{0020}tomorrow.\u{0020}I\u{0020}can\u{0020}die\u{0020}without\u{0020}regrets\u{0020}knowing\u{0020}I\u{0020}recorded\u{0020}this\u{0020}moment\u{0020}in\u{0020}history.", "歴史上、人類がこれほど団結したことはないでしょう。多少の摩擦が生じることがあっても、みんながより良い未来を目指して全力を尽くしています。この歴史を書き記すことができれば、私はもう悔いはありません。", "在史書上的人類，從來沒有像現在這樣團結過，雖然難免有摩擦，但是所有人都為了更好的明天全心全意，能記錄下這段歷史，我已經死而無憾了。", "0", "0", "0", "cv_chenglian_6", "0", "0"},
[413006] = {413006, 11030, 7, 5, "1_》_0_0.8", "level1", "Do\u{0020}our\u{0020}transformed\u{0020}legs\u{0020}look\u{0020}strange\u{0020}to\u{0020}you?", "ダニューブの博物館に行って、昔の人々が作り出した遺物を見てみたいんです。……その持ち主と私の祖先が知り合いかもしれないとか、想像したら楽しくないですか？", "我們幻化之後的腿是不是看起來很奇怪？", "0", "0", "0", "cv_chenglian_7", "0", "0"},
[413007] = {413007, 11030, 8, 5, "1_》_0_0.8", "level1", "Ugh...\u{0020}Navigator,\u{0020}we're\u{0020}only\u{0020}colleagues,\u{0020}please\u{0020}don't\u{0020}get\u{0020}too\u{0020}close.", "ひゃ！……ナ、ナビゲーターさんと平心社はお仕事でのお付き合いなんですから、近づきすぎちゃダメです！", "嗚……領航，我們與您只是相熟共事的關係，請不要靠得太近。", "0", "0", "0", "cv_chenglian_8", "0", "0"},
[413008] = {413008, 11030, 9, 5, "1_》_100_1.5", "level2", "We're\u{0020}at\u{0020}a\u{0020}crucial\u{0020}point\u{0020}in\u{0020}human\u{0020}history,\u{0020}and\u{0020}Navigator,\u{0020}you're\u{0020}undeniably\u{0020}the\u{0020}most\u{0020}unusual\u{0020}person\u{0020}of\u{0020}this\u{0020}era.\u{0020}Please,\u{0020}by\u{0020}all\u{0020}means,\u{0020}stay\u{0020}alive\u{0020}so\u{0020}we\u{0020}can\u{0020}witness\u{0020}how\u{0020}this\u{0020}all\u{0020}ends.", "私たちは現在、人類史上最も重要な時代にいます。そしてナビゲーターさんは間違いなく、この時代でもっとも特別な一人です。どうかこれからも歩みを止めず、その結末を私たちに見届けさせてください。", "我們正處於人類歷史中最特殊的節點，而領航您無疑是這個時代最奇怪的人之一，無論如何請活下去，讓我們見證結局您的吧。", "0", "0", "0", "cv_chenglian_9", "0", "0"},
[413009] = {413009, 11030, 10, 5, "1_》_500_2", "level3", "I\u{0020}always\u{0020}replace\u{0020}\"I\"\u{0020}with\u{0020}\"we,\"\u{0020}as\u{0020}if\u{0020}losing\u{0020}\"them\"\u{0020}means\u{0020}I\u{0020}lose\u{0020}my\u{0020}confidence\u{0020}to\u{0020}face\u{0020}challenges,\u{0020}to\u{0020}communicate\u{0020}or\u{0020}handle\u{0020}things.\u{0020}I\u{0020}guess\u{0020}I'm...\u{0020}pretty\u{0020}cowardly.", "私、いつも自分のことを「平心社」って言ってしまうんです。仲間がいないと、人と話すことも問題に対処することも自信が持てなくなってしまうみたいで……弱虫ですよね……", "我總是用“我們”來替代“我”，仿佛失去了“她們”，我便失去了與人交流、面對難題、處理事情的底氣……我……很膽小吧。", "0", "0", "0", "cv_chenglian_10", "0", "0"},
[413010] = {413010, 11030, 11, 5, "1_》_1000_2.5", "level4", "Your\u{0020}wish...\u{0020}I've\u{0020}already\u{0020}understood\u{0020}it...\u{0020}but...\u{0020}but...\u{0020}I\u{0020}am\u{0020}a\u{0020}\"historian\"...", "あなたの願い……ちゃんと受け取りました……ですが……ですが私は史官なんですよ……まだ、お返事はできません……", "您的心願……我已經知道了……但是……但是……我是“史官”啊……", "0", "0", "0", "cv_chenglian_11", "0", "0"},
[413011] = {413011, 11030, 12, 6, "0", "0", "Support\u{0020}from\u{0020}the\u{0020}Navigator...\u{0020}I've\u{0020}received\u{0020}it.", "ナビゲーターさんのご支援、受け取りました。", "來自領航的支援。我收到了。", "0", "0", "0", "cv_chenglian_12", "0", "0"},
[413012] = {413012, 11030, 13, 7, "0", "0", "Ah,\u{0020}so\u{0020}this\u{0020}is\u{0020}the\u{0020}feeling.\u{0020}I've\u{0020}noted\u{0020}it\u{0020}down.", "こんな感じだったんですね。記録しないと。", "原來是這種感覺。我記錄了。", "0", "0", "0", "cv_chenglian_13", "0", "0"},
[413013] = {413013, 11030, 14, 8, "0", "0", "New\u{0020}knowledge.\u{0020}I\u{0020}understand\u{0020}now.", "時間の積み重ねは、物事に歳月の風味を与えます。私にも、ナビゲーターさんにも。……私、それが好きなんです。", "新的知識。我明白了。", "0", "0", "0", "cv_chenglian_14", "0", "0"},
[413014] = {413014, 11030, 15, 9, "0", "0", "This...\u{0020}This\u{0020}is...!", "こ…これは……！", "這……這是……！", "0", "0", "0", "cv_chenglian_15", "0", "0"},
[413015] = {413015, 11030, 16, 10, "0", "0", "Was\u{0020}the\u{0020}mission\u{0020}objective\u{0020}conveyed\u{0020}correctly?", "任務目標は届きましたか？", "任務目標好好傳達到了嗎？", "0", "0", "0", "cv_chenglian_16", "0", "0"},
[413016] = {413016, 11030, 17, 11, "0", "0", "Not\u{0020}bad...\u{0020}The\u{0020}battle's\u{0020}over.", "戦闘終了。まあまあでしたね。", "馬馬虎虎吧，戰鬥結束了。", "0", "0", "0", "cv_chenglian_17", "0", "0"},
[413017] = {413017, 11030, 18, 12, "0", "0", "There's\u{0020}a\u{0020}glitch.", "問題点が出ましたね。", "出現了紕漏啊。", "0", "0", "0", "cv_chenglian_18", "0", "0"},
[413018] = {413018, 11030, 19, 13, "0", "0", "We'll\u{0020}just\u{0020}record\u{0020}it\u{0020}and\u{0020}fix\u{0020}it\u{0020}later.\u{0020}That's\u{0020}all\u{0020}we\u{0020}can\u{0020}do,\u{0020}right?", "記録し、修正する。これしかありません。", "記錄然後修正，也只能這樣了吧。", "0", "0", "0", "cv_chenglian_19", "0", "0"},
[413019] = {413019, 11030, 20, 14, "0", "0", "Come\u{0020}on,\u{0020}cheer\u{0020}up.\u{0020}We'll\u{0020}find\u{0020}a\u{0020}solution.", "気を取り直してください。何か対策を考えましょう。", "打起精神來，我們來想辦法。", "0", "0", "0", "cv_chenglian_20", "0", "0"},
[413020] = {413020, 11030, 21, 15, "0", "0", "Ink\u{0020}has\u{0020}set.", "墨が乾き、ことを成す。", "墨已成章。", "0", "0", "0", "cv_chenglian_21", "0", "0"},
[413021] = {413021, 11030, 23, 16, "0", "0", "Pen\u{0020}in\u{0020}hand.", "筆をとる。", "提筆。", "0", "0", "0", "cv_chenglian_22", "0", "0"},
[413022] = {413022, 11030, 24, 17, "0", "0", "Dipped\u{0020}in\u{0020}ink.", "墨をつける。", "著墨。", "0", "0", "0", "cv_chenglian_23", "0", "0"},
[413023] = {413023, 11030, 26, 19, "0", "0", "The\u{0020}record\u{0020}of\u{0020}history\u{0020}will\u{0020}not\u{0020}cease...", "歴史の記録は、途絶えません……", "歷史的記錄，並不會中斷……", "0", "0", "0", "cv_chenglian_24", "0", "0"},
[413024] = {413024, 11030, 27, 20, "0", "0", "Feeling\u{0020}a\u{0020}bit\u{0020}warm...", "なんか熱くありませんか……？", "感覺有點熱熱的……", "0", "0", "0", "cv_chenglian_25", "0", "0"},
[413025] = {413025, 11030, 28, 21, "0", "0", "Navigator...\u{0020}just\u{0020}promise\u{0020}me\u{0020}you\u{0020}won't\u{0020}look\u{0020}down...", "ナビゲーターさん……下を見ないでください……約束ですよ？", "領航……答應我不要往下看哦……", "0", "0", "0", "cv_chenglian_26", "0", "0"},
[413026] = {413026, 11030, 29, 21, "0", "0", "Burning\u{0020}incense\u{0020}and\u{0020}taking\u{0020}a\u{0020}bath...\u{0020}Is\u{0020}something\u{0020}big\u{0020}about\u{0020}to\u{0020}happen?", "お香とお風呂……何かが起きる予感がします……", "焚香沐浴……是有什麼大事要發生了？", "0", "0", "0", "cv_chenglian_27", "0", "0"},
[413027] = {413027, 11030, 30, 22, "0", "0", "Um...\u{0020}is\u{0020}there\u{0020}something\u{0020}on\u{0020}my\u{0020}back?", "ん……？私の背中に何かついてますか？", "嗯……我的背上有什麼東西嗎？", "0", "0", "0", "cv_chenglian_28", "0", "0"},
[413028] = {413028, 11030, 31, 23, "0", "0", "Is\u{0020}this\u{0020}a\u{0020}moment\u{0020}worth\u{0020}recording?", "これは記録すべきことでしょうか？", "這算是一件值得記下來的大事嗎？", "0", "0", "0", "cv_chenglian_29", "0", "0"},
[413029] = {413029, 11030, 32, 24, "0", "0", "Huh...\u{0020}Better\u{0020}make\u{0020}a\u{0020}note\u{0020}of\u{0020}it\u{0020}for\u{0020}now.", "ふぅ…一応記録しておきますね……", "呼……權且記下吧。", "0", "0", "0", "cv_chenglian_30", "0", "0"},
[413030] = {413030, 11030, 33, 25, "0", "0", "The\u{0020}incident\u{0020}where\u{0020}the\u{0020}Navigator\u{0020}mistook\u{0020}someone...\u{0020}I've\u{0020}logged\u{0020}it.", "ナビゲーターさんが人を間違えました、と……", "領航認錯了人這件事，我就記下了。", "0", "0", "0", "cv_chenglian_31", "0", "0"},
[413031] = {413031, 11030, 34, 26, "0", "0", "Today's\u{0020}entry,\u{0020}Navigator\u{0020}returned\u{0020}to\u{0020}the\u{0020}Ark.", "今日の記録……ナビゲーターさんが方舟に戻りました、と……", "今日的記錄，領航回到了方舟。", "0", "0", "0", "cv_chenglian_32", "0", "0"},
[413032] = {413032, 11030, 35, 27, "0", "0", "Ready\u{0020}to\u{0020}head\u{0020}out?", "出発の準備はできましたか？", "準備出征了嗎。", "0", "0", "0", "cv_chenglian_33", "0", "0"},
[413033] = {413033, 11030, 36, 28, "0", "0", "Make\u{0020}sure\u{0020}everything's\u{0020}prepared.", "転ばぬ先の杖ですね。", "未雨綢繆。", "0", "0", "0", "cv_chenglian_34", "0", "0"},
[413034] = {413034, 11030, 37, 29, "0", "0", "Today's\u{0020}plan:\u{0020}visiting\u{0020}a\u{0020}friend.", "今日は友人を訪ねるのですね。", "今日，造訪友人。", "0", "0", "0", "cv_chenglian_35", "0", "0"},
[413035] = {413035, 11030, 38, 30, "0", "0", "How\u{0020}many\u{0020}people\u{0020}are\u{0020}you\u{0020}going\u{0020}to\u{0020}meet?", "これから先、いくつの出会いがあるのでしょうか。", "你究竟還會遇見多少人呢。", "0", "0", "0", "cv_chenglian_36", "0", "0"},
[413036] = {413036, 11030, 39, 31, "0", "0", "This\u{0020}is\u{0020}all\u{0020}for\u{0020}us.", "平心社のためでしょうか？", "這都是為了我們啊。", "0", "0", "0", "cv_chenglian_37", "0", "0"},
[413037] = {413037, 11030, 40, 32, "0", "0", "When\u{0020}shopping...", "買い物の時です。", "購易之時。", "0", "0", "0", "cv_chenglian_38", "0", "0"},
[413038] = {413038, 11030, 41, 33, "0", "0", "I'll\u{0020}help\u{0020}organize\u{0020}the\u{0020}files\u{0020}for\u{0020}you,\u{0020}Navigator.", "プロフィールは私が預かりましょうか？", "檔案就由我幫你保存吧，領航。", "0", "0", "0", "cv_chenglian_39", "0", "0"},
[413039] = {413039, 11030, 42, 34, "0", "0", "Everything\u{0020}is\u{0020}in\u{0020}order.", "良く整理されてますね。", "條理清晰呢。", "0", "0", "0", "cv_chenglian_40", "0", "0"},
[413040] = {413040, 11030, 43, 35, "0", "0", "Letters\u{0020}are\u{0020}carriers\u{0020}of\u{0020}time,\u{0020}too.", "手紙もまた、時の経過を記す媒体です。", "書信也是歲月的載體。", "0", "0", "0", "cv_chenglian_41", "0", "0"},
[413041] = {413041, 11030, 44, 36, "0", "0", "I\u{0020}can't\u{0020}miss\u{0020}this.", "これは見逃せません。", "這我可不能錯過。", "0", "0", "0", "cv_chenglian_42", "0", "0"},
[413042] = {413042, 11030, 45, 37, "0", "0", "Rules\u{0020}and\u{0020}regulations.", "枠組みが細かいですね。", "條條框框。", "0", "0", "0", "cv_chenglian_43", "0", "0"},
[413100] = {413100, 11031, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_lailapusi_001", "0", "0"},
[413101] = {413101, 11031, 2, 2, "0", "0", "Is\u{0020}there\u{0020}really\u{0020}no\u{0020}one\u{0020}better\u{0020}suited\u{0020}for\u{0020}this\u{0020}task?\u{0020}This\u{0020}is\u{0020}way\u{0020}too\u{0020}conspicuous.\u{0020}If\u{0020}something\u{0020}goes\u{0020}wrong,\u{0020}don't\u{0020}say\u{0020}I\u{0020}didn't\u{0020}warn\u{0020}you.", "0", "難道沒有其他更合適的人了嗎？這太引人矚目了，要是出了什麼意外，不要怪我沒提醒你。", "0", "0", "0", "cv_lailapusi_002", "0", "0"},
[413102] = {413102, 11031, 3, 3, "0", "0", "Lai...\u{0020}Lailaps...\u{0020}Lailaps\u{0020}of\u{0020}the\u{0020}Hydra...\u{0020}What?\u{0020}It's\u{0020}not\u{0020}like\u{0020}I\u{0020}wanted\u{0020}this\u{0020}name.\u{0020}My\u{0020}taste\u{0020}isn't\u{0020}that\u{0020}low.", "0", "萊……萊拉普斯……“九頭蛇”的萊拉普斯……怎麼了，又不是我想取這個名字，我的品味才沒這麼低級。", "0", "0", "0", "cv_lailapusi_003", "0", "0"},
[413103] = {413103, 11031, 4, 4, "0", "idle", "Freedom...\u{0020}so\u{0020}many\u{0020}people\u{0020}are\u{0020}pursuing\u{0020}it,\u{0020}and\u{0020}we\u{0020}are\u{0020}no\u{0020}different.\u{0020}Right\u{0020}now,\u{0020}we\u{0020}can\u{0020}only\u{0020}hope\u{0020}that\u{0020}the\u{0020}doctor\u{0020}will\u{0020}keep\u{0020}his\u{0020}promise\u{0020}and\u{0020}grant\u{0020}us\u{0020}the\u{0020}freedom\u{0020}we\u{0020}deserve\u{0020}once\u{0020}this\u{0020}is\u{0020}all\u{0020}over.", "0", "自由……許多人都在追尋它，我們也不例外。我們現在只能寄望於那位博士能遵守承諾，在事情結束之後讓我們得到應有的自由。", "0", "0", "0", "cv_lailapusi_004", "0", "0"},
[413104] = {413104, 11031, 5, 4, "0", "idle", "I\u{0020}don't\u{0020}like\u{0020}this\u{0020}place,\u{0020}whether\u{0020}it's\u{0020}this\u{0020}organization\u{0020}or\u{0020}this\u{0020}Ark.\u{0020}But\u{0020}with\u{0020}you\u{0020}all\u{0020}here,\u{0020}I\u{0020}can\u{0020}tolerate\u{0020}the\u{0020}strange\u{0020}environment\u{0020}and\u{0020}stares\u{0020}a\u{0020}little\u{0020}longer.", "0", "我不喜歡這個地方，無論是這個組織還是這個方舟，但有你們在的話，我多少還能忍受這種異樣的環境和目光。", "0", "0", "0", "cv_lailapusi_005", "0", "0"},
[413105] = {413105, 11031, 6, 4, "0", "idle", "About\u{0020}the\u{0020}last\u{0020}time,\u{0020}I\u{0020}haven't\u{0020}had\u{0020}the\u{0020}chance\u{0020}to\u{0020}properly\u{0020}thank\u{0020}you.\u{0020}A\u{0020}simple\u{0020}meal\u{0020}wouldn't\u{0020}be\u{0020}enough\u{0020}to\u{0020}repay\u{0020}the\u{0020}favor...\u{0020}Is\u{0020}there\u{0020}something\u{0020}else\u{0020}you'd\u{0020}like\u{0020}to\u{0020}do?", "0", "上次的事情，我還沒有機會好好答謝你呢。只是請客的話不足以奉還恩情……你還有其他想做的事情嗎？", "0", "0", "0", "cv_lailapusi_006", "0", "0"},
[413106] = {413106, 11031, 7, 5, "1_》_0_0.8", "level1", "As\u{0020}long\u{0020}as\u{0020}Rebecca\u{0020}can\u{0020}live\u{0020}a\u{0020}happy\u{0020}and\u{0020}peaceful\u{0020}life,\u{0020}I'm\u{0020}willing\u{0020}to\u{0020}do\u{0020}anything.", "0", "只要能讓黎貝卡她能過上幸福、和平的生活，無論讓我做什麼，我都願意。", "0", "0", "0", "cv_lailapusi_007", "0", "0"},
[413107] = {413107, 11031, 8, 5, "1_》_0_0.8", "level1", "This\u{0020}body\u{0020}is\u{0020}harder\u{0020}to\u{0020}control\u{0020}than\u{0020}I\u{0020}thought.\u{0020}It\u{0020}feels\u{0020}like\u{0020}it\u{0020}has\u{0020}its\u{0020}own\u{0020}emotions.\u{0020}This\u{0020}burning\u{0020}rage\u{0020}that\u{0020}wants\u{0020}to\u{0020}incinerate\u{0020}everything—it's\u{0020}not\u{0020}coming\u{0020}from\u{0020}my\u{0020}thoughts\u{0020}but\u{0020}from\u{0020}this\u{0020}body...\u{0020}from\u{0020}the\u{0020}thoughts\u{0020}of\u{0020}Sin.", "0", "這具身體比我想像中還難控制，仿佛它有自己的情緒。這種想要將一切燒卻的憤怒，不是來自於我的想法，而是這具身體……是原罪的想法。", "0", "0", "0", "cv_lailapusi_008", "0", "0"},
[413108] = {413108, 11031, 9, 5, "1_》_100_1.5", "level2", "I've\u{0020}thought\u{0020}about\u{0020}it.\u{0020}If\u{0020}Rebecca\u{0020}can\u{0020}never\u{0020}return\u{0020}to\u{0020}a\u{0020}normal\u{0020}human\u{0020}body,\u{0020}then\u{0020}I'll\u{0020}become\u{0020}a\u{0020}monster\u{0020}with\u{0020}her\u{0020}in\u{0020}others'\u{0020}eyes...\u{0020}Would\u{0020}you\u{0020}mind\u{0020}that?", "0", "我有想過，如果黎貝卡再也無法恢復成正常人的身體，那我就和她一起成為別人眼中的怪物……你會介意嗎？", "0", "0", "0", "cv_lailapusi_009", "0", "0"},
[413109] = {413109, 11031, 10, 5, "1_》_500_2", "level3", "Tired...\u{0020}I'm\u{0020}going\u{0020}to\u{0020}sleep...\u{0020}Don't\u{0020}do\u{0020}anything\u{0020}bad\u{0020}to\u{0020}me\u{0020}while\u{0020}I'm\u{0020}asleep...\u{0020}I'll\u{0020}be...\u{0020}angry...", "0", "困……我要睡覺了……別在我睡覺的時候對我做壞事……我會生……生氣的……", "0", "0", "0", "cv_lailapusi_010", "0", "0"},
[413110] = {413110, 11031, 11, 5, "1_》_1000_2.5", "level4", "The\u{0020}life\u{0020}I\u{0020}seek\u{0020}is\u{0020}a\u{0020}simple\u{0020}person's\u{0020}happiness.\u{0020}It's\u{0020}a\u{0020}shame\u{0020}we\u{0020}can't\u{0020}walk\u{0020}that\u{0020}road\u{0020}together,\u{0020}but\u{0020}I'll\u{0020}prepare\u{0020}everything\u{0020}you\u{0020}want\u{0020}at\u{0020}my\u{0020}future\u{0020}home,\u{0020}waiting\u{0020}for\u{0020}your\u{0020}triumphant\u{0020}return.", "0", "我追求的生活是平凡人的幸福，真遺憾，我們註定沒辦法在這條路上同行，但我會在自己將來的住所，為你準備好你想要的一切，等待你的凱旋。", "0", "0", "0", "cv_lailapusi_011", "0", "0"},
[413111] = {413111, 11031, 12, 6, "0", "0", "Thanks\u{0020}for\u{0020}that.", "0", "謝謝。", "0", "0", "0", "cv_lailapusi_012", "0", "0"},
[413112] = {413112, 11031, 13, 7, "0", "0", "Oh...\u{0020}stars...\u{0020}so\u{0020}beautiful.", "0", "噢……是星星啊，真好看。", "0", "0", "0", "cv_lailapusi_013", "0", "0"},
[413113] = {413113, 11031, 14, 8, "0", "0", "In\u{0020}AEGIS,\u{0020}you're\u{0020}the\u{0020}only\u{0020}one\u{0020}I\u{0020}can\u{0020}trust.\u{0020}You\u{0020}may\u{0020}not\u{0020}realize\u{0020}how\u{0020}much\u{0020}you\u{0020}mean\u{0020}to\u{0020}me...\u{0020}Anyway,\u{0020}I\u{0020}want\u{0020}to\u{0020}be\u{0020}someone\u{0020}you\u{0020}can\u{0020}trust.", "0", "在艾吉斯，你是我唯一一個可以相信的人，你可能不清楚你對我來說有什麼樣的意義……總之，我想成為能讓你信任的人。", "0", "0", "0", "cv_lailapusi_014", "0", "0"},
[413114] = {413114, 11031, 15, 9, "0", "0", "Thanks,\u{0020}it\u{0020}doesn't\u{0020}feel\u{0020}bad.", "0", "謝了，感覺不壞。", "0", "0", "0", "cv_lailapusi_015", "0", "0"},
