[413116] = {413116, 11031, 17, 11, "0", "0", "Great,\u{0020}so\u{0020}now\u{0020}we're\u{0020}safe,\u{0020}right?", "0", "很好，這樣一來我們就安全了吧？", "0", "0", "0", "cv_lailapusi_017", "0", "0"},
