[413126] = {413126, 11031, 29, 21, "0", "0", "Maybe\u{0020}it's\u{0020}your\u{0020}ability\u{0020}at\u{0020}work.\u{0020}When\u{0020}you're\u{0020}around,\u{0020}this\u{0020}Sin\u{0020}body\u{0020}becomes\u{0020}calm.", "0", "可能是你的能力在起作用，你在身邊的時候，這具原罪的軀體就會變得平靜。", "0", "0", "0", "cv_lailapusi_028", "0", "0"},
[413127] = {413127, 11031, 30, 22, "0", "0", "Huh?", "0", "嗯？", "0", "0", "0", "cv_lailapusi_029", "0", "0"},
