[413129] = {413129, 11031, 32, 24, "0", "0", "I\u{0020}was\u{0020}worried...\u{0020}never\u{0020}mind,\u{0020}congrats\u{0020}on\u{0020}getting\u{0020}it\u{0020}right.", "0", "我還擔心……沒事，恭喜你答對了。", "0", "0", "0", "cv_lailapusi_031", "0", "0"},
[413130] = {413130, 11031, 33, 25, "0", "0", "You\u{0020}think\u{0020}this\u{0020}is\u{0020}funny?", "0", "你覺得這很幽默嗎？", "0", "0", "0", "cv_lailapusi_032", "0", "0"},
[413131] = {413131, 11031, 34, 26, "0", "0", "You're\u{0020}here?\u{0020}I\u{0020}was\u{0020}wondering\u{0020}if\u{0020}I'd\u{0020}see\u{0020}you\u{0020}today.", "0", "你來了？我還在想今天能不能見到你。", "0", "0", "0", "cv_lailapusi_033", "0", "0"},
