[413133] = {413133, 11031, 36, 28, "0", "0", "I'm\u{0020}not\u{0020}very\u{0020}good\u{0020}at\u{0020}fighting,\u{0020}but\u{0020}with\u{0020}you,\u{0020}I\u{0020}can\u{0020}give\u{0020}it\u{0020}a\u{0020}try.", "0", "我不太擅長戰鬥，但和你的話可以試一試。", "0", "0", "0", "cv_lailapusi_035", "0", "0"},
[413134] = {413134, 11031, 37, 29, "0", "0", "You're\u{0020}quite\u{0020}popular.", "0", "你挺受歡迎的。", "0", "0", "0", "cv_lailapusi_036", "0", "0"},
