[413140] = {413140, 11031, 43, 35, "0", "0", "A\u{0020}love\u{0020}letter...\u{0020}cough,\u{0020}probably\u{0020}not...\u{0020}right?", "0", "情書……咳，應該不可能有……吧？", "0", "0", "0", "cv_lailapusi_042", "0", "0"},
