[413200] = {413200, 11032, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_qianqiu_1", "0", "0"},
[413201] = {413201, 11032, 2, 2, "0", "0", "Can't\u{0020}someone\u{0020}else\u{0020}take\u{0020}care\u{0020}of\u{0020}this?\u{0020}Fine,\u{0020}I'll\u{0020}handle\u{0020}it.", "0", "就不能讓別人來做這件事……好啦好啦，我做就是了。", "0", "0", "0", "cv_qianqiu_2", "0", "0"},
[413202] = {413202, 11032, 3, 3, "0", "0", "Ugh...\u{0020}That\u{0020}Stephanie\u{0020}is\u{0020}so\u{0020}arrogant!\u{0020}Anyway,\u{0020}long\u{0020}time\u{0020}no\u{0020}see!\u{0020}Looks\u{0020}like\u{0020}you've\u{0020}become\u{0020}quite\u{0020}the\u{0020}Navigator.\u{0020}You\u{0020}remember\u{0020}me,\u{0020}right?\u{0020}Chiaki—make\u{0020}sure\u{0020}you\u{0020}remember\u{0020}that\u{0020}name.", "0", "唉……史蒂芬妮那傢伙真是有夠目中無人的……總之——好久不見，看來你已經成為相當出色的領航了……你不會已經忘了我吧？千——秋，好好記住這個名字。", "0", "0", "0", "cv_qianqiu_3", "0", "0"},
[413203] = {413203, 11032, 4, 4, "0", "idle", "\"Serial\u{0020}Killer\"\u{0020}Chiaki—I've\u{0020}always\u{0020}wanted\u{0020}to\u{0020}be\u{0020}called\u{0020}that.\u{0020}But\u{0020}it\u{0020}seems\u{0020}someone\u{0020}in\u{0020}AEGIS\u{0020}already\u{0020}has\u{0020}that\u{0020}nickname...\u{0020}Damn\u{0020}it,\u{0020}no\u{0020}idea\u{0020}which\u{0020}clueless\u{0020}fool\u{0020}stole\u{0020}it\u{0020}first.", "0", "“殺人鬼”千秋——我一直想被人這樣稱呼。不過艾吉斯裏好像已經有人被這麼叫了……可惡，也不知道是被哪個不知好歹的傢伙搶先了。", "0", "0", "0", "cv_qianqiu_4", "0", "0"},
[413204] = {413204, 11032, 5, 4, "0", "idle", "Hmph—didn't\u{0020}expect\u{0020}it,\u{0020}huh?\u{0020}It's\u{0020}been\u{0020}over\u{0020}a\u{0020}year,\u{0020}and\u{0020}now\u{0020}there\u{0020}are\u{0020}so\u{0020}many\u{0020}pretty\u{0020}girls\u{0020}around\u{0020}you\u{0020}again.\u{0020}Typical.\u{0020}So,\u{0020}not\u{0020}planning\u{0020}to\u{0020}introduce\u{0020}them\u{0020}to\u{0020}me?\u{0020}Especially\u{0020}that\u{0020}smug\u{0020}blonde\u{0020}always\u{0020}hanging\u{0020}around\u{0020}you.", "0", "謔——沒想到，一年多不見，你的身邊又多出了這麼多漂亮的女孩，真不愧是你。怎麼，不打算給我介紹下她們嗎，尤其是那個一臉狂妄，總纏著你的金髮妹。", "0", "0", "0", "cv_qianqiu_5", "0", "0"},
[413205] = {413205, 11032, 6, 4, "0", "idle", "Next\u{0020}time,\u{0020}I\u{0020}want\u{0020}to\u{0020}try\u{0020}the\u{0020}crazy\u{0020}combination\u{0020}of\u{0020}ice\u{0020}cream\u{0020}cake\u{0020}and\u{0020}ramen.\u{0020}Now\u{0020}that\u{0020}would\u{0020}be\u{0020}a\u{0020}real\u{0020}challenge!\u{0020}Honestly,\u{0020}though,\u{0020}eating\u{0020}them\u{0020}should\u{0020}be\u{0020}easier\u{0020}than\u{0020}killing\u{0020}someone,\u{0020}right?", "0", "下次有機會的話，我要嘗試一下冰淇淋蛋糕搭配拉麵的吃法。嗯，這會是一次前所未有的挑戰，但不管怎麼說，咽下它們應該比殺人要簡單吧？", "0", "0", "0", "cv_qianqiu_6", "0", "0"},
[413206] = {413206, 11032, 7, 5, "1_》_0_0.8", "level1", "You\u{0020}know,\u{0020}killing\u{0020}someone\u{0020}isn't\u{0020}actually\u{0020}that\u{0020}hard.\u{0020}But\u{0020}if\u{0020}someone\u{0020}can\u{0020}cross\u{0020}that\u{0020}line\u{0020}without\u{0020}feeling\u{0020}anything,\u{0020}they're\u{0020}a\u{0020}true\u{0020}killer.", "0", "你知道嗎？“將某人殺死”，這種事做起來其實沒有多難。可若是一個人能沒有心理負擔地輕易越過殺人之門，那便是殺人鬼。", "0", "0", "0", "cv_qianqiu_7", "0", "0"},
[413207] = {413207, 11032, 8, 5, "1_》_0_0.8", "level1", "If\u{0020}it\u{0020}weren't\u{0020}for\u{0020}Stephanie,\u{0020}I'd\u{0020}never\u{0020}be\u{0020}a\u{0020}Driver...\u{0020}Sigh,\u{0020}that\u{0020}woman\u{0020}must\u{0020}be\u{0020}a\u{0020}sadist,\u{0020}forcing\u{0020}people\u{0020}to\u{0020}do\u{0020}things\u{0020}they\u{0020}don't\u{0020}want\u{0020}to.", "0", "如果不是史蒂芬妮，我是絕對不會當駕駛員的……唉，那傢伙不會是施虐狂吧，一定要強迫別人做不願意做的事情。", "0", "0", "0", "cv_qianqiu_8", "0", "0"},
[413208] = {413208, 11032, 9, 5, "1_》_100_1.5", "level2", "What?\u{0020}You've\u{0020}got\u{0020}nothing\u{0020}to\u{0020}do?\u{0020}In\u{0020}that\u{0020}case,\u{0020}want\u{0020}to\u{0020}take\u{0020}a\u{0020}look\u{0020}at\u{0020}my\u{0020}breasts?\u{0020}You\u{0020}think\u{0020}I'm\u{0020}joking?\u{0020}I'm\u{0020}serious!\u{0020}I'm\u{0020}just\u{0020}really\u{0020}bored\u{0020}right\u{0020}now.\u{0020}Don't\u{0020}worry,\u{0020}I\u{0020}won't\u{0020}kill\u{0020}you.", "0", "怎麼？沒事情做嗎？既然如此，要不要看看我的胸部？“玩笑”？為什麼會這麼想，我是認真的。畢竟現在真的很無聊。放心，我不會殺你的。", "0", "0", "0", "cv_qianqiu_9", "0", "0"},
[413209] = {413209, 11032, 10, 5, "1_》_500_2", "level3", "By\u{0020}the\u{0020}way,\u{0020}Stephanie\u{0020}said\u{0020}your\u{0020}mission\u{0020}is\u{0020}important—do\u{0020}you\u{0020}know\u{0020}what\u{0020}your\u{0020}mission\u{0020}is?\u{0020}...Forget\u{0020}it,\u{0020}it\u{0020}doesn't\u{0020}matter,\u{0020}it's\u{0020}none\u{0020}of\u{0020}my\u{0020}business.\u{0020}As\u{0020}long\u{0020}as\u{0020}I\u{0020}don't\u{0020}die\u{0020}before\u{0020}you\u{0020}do,\u{0020}that's\u{0020}all\u{0020}that\u{0020}matters.", "0", "話說，史蒂芬妮說你的使命很重要——你知道自己的使命是什麼嗎……算了，怎麼樣都好，跟我沒關係，我只要在自己死之前，保證你不會死，這樣就行了。", "0", "0", "0", "cv_qianqiu_10", "0", "0"},
[413210] = {413210, 11032, 11, 5, "1_》_1000_2.5", "level4", "I'm\u{0020}a\u{0020}killer,\u{0020}you\u{0020}know.\u{0020}If\u{0020}I\u{0020}didn't\u{0020}have\u{0020}any\u{0020}use\u{0020}left,\u{0020}I'd\u{0020}probably\u{0020}have\u{0020}been\u{0020}executed\u{0020}by\u{0020}now...\u{0020}As\u{0020}long\u{0020}as\u{0020}I'm\u{0020}alive,\u{0020}something\u{0020}good\u{0020}might\u{0020}happen.\u{0020}Meeting\u{0020}you\u{0020}in\u{0020}this\u{0020}stinking,\u{0020}rotten\u{0020}life\u{0020}of\u{0020}mine\u{0020}wasn't\u{0020}so\u{0020}bad.", "0", "我呢，是殺人鬼，如果不是還有利用價值的話，我大概已經被處死了……只要活著總會有好事發生，能在自己像下水溝裏的屎一般又臭又爛的人生裏能遇到你，也不壞。", "0", "0", "0", "cv_qianqiu_11", "0", "0"},
[413211] = {413211, 11032, 12, 6, "0", "0", "The\u{0020}higher\u{0020}the\u{0020}level,\u{0020}the\u{0020}greater\u{0020}the\u{0020}responsibility,\u{0020}right?", "0", "級別越高，責任越大，我說的對嗎？", "0", "0", "0", "cv_qianqiu_12", "0", "0"},
[413212] = {413212, 11032, 13, 7, "0", "0", "If\u{0020}you\u{0020}want\u{0020}to\u{0020}reward\u{0020}me,\u{0020}how\u{0020}about\u{0020}treating\u{0020}me\u{0020}to\u{0020}ramen\u{0020}next\u{0020}time?", "0", "想獎勵我的話，不如下次請我吃拉麵。", "0", "0", "0", "cv_qianqiu_13", "0", "0"},
[413213] = {413213, 11032, 14, 8, "0", "0", "Do\u{0020}you\u{0020}remember\u{0020}what\u{0020}we\u{0020}said\u{0020}when\u{0020}we\u{0020}first\u{0020}met?\u{0020}Yeah,\u{0020}I\u{0020}really\u{0020}didn't\u{0020}want\u{0020}to\u{0020}be\u{0020}a\u{0020}pilot\u{0020}at\u{0020}all...\u{0020}I\u{0020}never\u{0020}imagined\u{0020}it\u{0020}would\u{0020}turn\u{0020}out\u{0020}like\u{0020}this.\u{0020}You've\u{0020}really\u{0020}done\u{0020}it,\u{0020}Navigator.", "0", "還記得我們第一次見面時說的嗎？對，我一點也不想當駕駛員……唉，我可能怎麼也想不到居然會成這樣，真有你的——領航。", "0", "0", "0", "cv_qianqiu_14", "0", "0"},
[413214] = {413214, 11032, 15, 9, "0", "0", "Make\u{0020}my\u{0020}scissors\u{0020}even\u{0020}sharper!", "0", "讓我的剪刀更加鋒銳吧！", "0", "0", "0", "cv_qianqiu_15", "0", "0"},
