[413230] = {413230, 11032, 32, 24, "0", "0", "Correct\u{0020}answer!\u{0020}It's\u{0020}my\u{0020}turn\u{0020}next.\u{0020}I\u{0020}want\u{0020}to\u{0020}play\u{0020}too.", "0", "回答正確，下一個到我了，我也要玩。", "0", "0", "0", "cv_qianqiu_32", "0", "0"},
