[413232] = {413232, 11032, 34, 26, "0", "0", "Back\u{0020}already?\u{0020}I\u{0020}know\u{0020}you're\u{0020}busy,\u{0020}but\u{0020}since\u{0020}you're\u{0020}here,\u{0020}you\u{0020}should\u{0020}take\u{0020}a\u{0020}break\u{0020}first.", "0", "回來了？知道你很忙，既然回來了就先休息一會吧。", "0", "0", "0", "cv_qianqiu_34", "0", "0"},
[413233] = {413233, 11032, 35, 27, "0", "0", "Um,\u{0020}hoo—alright,\u{0020}let's\u{0020}get\u{0020}going.\u{0020}Let's\u{0020}kill\u{0020}them\u{0020}all.", "0", "嗯——呼——好，出發，讓我們把它們殺個乾淨吧。", "0", "0", "0", "cv_qianqiu_35", "0", "0"},
[413234] = {413234, 11032, 36, 28, "0", "0", "And\u{0020}hey,\u{0020}don't\u{0020}blame\u{0020}me\u{0020}if\u{0020}I\u{0020}accidentally\u{0020}take\u{0020}someone\u{0020}out\u{0020}in\u{0020}the\u{0020}process.", "0", "要是不小心殺人了可別怪我噢？", "0", "0", "0", "cv_qianqiu_36", "0", "0"},
[413235] = {413235, 11032, 37, 29, "0", "0", "This\u{0020}is\u{0020}way\u{0020}more\u{0020}\"gorgeous\"\u{0020}than\u{0020}I\u{0020}expected...", "0", "比我想像中還“華麗”啊……", "0", "0", "0", "cv_qianqiu_37", "0", "0"},
[413236] = {413236, 11032, 38, 30, "0", "0", "How\u{0020}many\u{0020}girls\u{0020}do\u{0020}you\u{0020}have\u{0020}to\u{0020}find\u{0020}before\u{0020}you're\u{0020}satisfied?", "0", "你要找多少女孩子才滿意呢？", "0", "0", "0", "cv_qianqiu_38", "0", "0"},
