[413300] = {413300, 11033, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_starry_1", "0", "0"},
[413301] = {413301, 11033, 2, 2, "0", "0", "Let\u{0020}me\u{0020}stay\u{0020}here;\u{0020}I\u{0020}might\u{0020}just\u{0020}get\u{0020}hit\u{0020}by\u{0020}a\u{0020}falling\u{0020}meteorite—Haha,\u{0020}just\u{0020}a\u{0020}\"movie\u{0020}joke.\"", "0", "讓我待在這的話，說不定會被墜落的隕石命中——哈哈，只是開個“電影玩笑”而已。", "0", "0", "0", "cv_starry_2", "0", "0"},
[413302] = {413302, 11033, 3, 3, "0", "0", "Hi\u{0020}there,\u{0020}Mr.\u{0020}Hentai!\u{0020}Long\u{0020}time\u{0020}no\u{0020}see!\u{0020}You've\u{0020}become\u{0020}an\u{0020}official\u{0020}Navigator?\u{0020}Well,\u{0020}I'm\u{0020}officially\u{0020}a\u{0020}driver\u{0020}now,\u{0020}\"Starry\"\u{0020}of\u{0020}the\u{0020}frontline\u{0020}team.\u{0020}After\u{0020}all\u{0020}the\u{0020}craziness,\u{0020}we\u{0020}finally\u{0020}meet\u{0020}again.", "0", "嗨~色狼先生，好久不見~你已經是正式的領航了？嗯，我也是正式的駕駛員，前線小隊的“星爍”咯……雖然發生了各種各樣的事，但我們總算又見面了。", "0", "0", "0", "cv_starry_3", "0", "0"},
[413303] = {413303, 11033, 4, 4, "0", "idle", "Don't\u{0020}be\u{0020}jealous\u{0020}of\u{0020}my\u{0020}good\u{0020}luck,\u{0020}it's\u{0020}my\u{0020}only\u{0020}advantage.\u{0020}Other\u{0020}than\u{0020}that,\u{0020}I've\u{0020}got\u{0020}nothing.", "0", "請別嫉妒我的強運哦，畢竟這是我僅有的優點了，除了它之外，我一無所有。", "0", "0", "0", "cv_starry_4", "0", "0"},
[413304] = {413304, 11033, 5, 4, "0", "idle", "I\u{0020}love\u{0020}working\u{0020}alone.\u{0020}Isn't\u{0020}it\u{0020}nice\u{0020}being\u{0020}alone?\u{0020}When\u{0020}you\u{0020}compare\u{0020}yourself\u{0020}to\u{0020}others,\u{0020}you\u{0020}start\u{0020}doubting\u{0020}yourself.\u{0020}If\u{0020}everyone's\u{0020}alone,\u{0020}no\u{0020}one\u{0020}gets\u{0020}hurt.", "0", "我很喜歡一個人行動哦，一個人不是挺好的嗎？人與人之間的對比只會產生讓人自我懷疑的落差感。大家都孤身一人的話，誰都不會受傷了。", "0", "0", "0", "cv_starry_5", "0", "0"},
[413305] = {413305, 11033, 6, 4, "0", "idle", "If\u{0020}I\u{0020}go\u{0020}on\u{0020}a\u{0020}trip,\u{0020}I\u{0020}might\u{0020}win\u{0020}a\u{0020}free\u{0020}ticket\u{0020}or\u{0020}a\u{0020}luxury\u{0020}cruise...\u{0020}But\u{0020}what\u{0020}if\u{0020}something\u{0020}bad\u{0020}happens\u{0020}at\u{0020}the\u{0020}destination?\u{0020}When\u{0020}I\u{0020}think\u{0020}of\u{0020}that,\u{0020}I\u{0020}lose\u{0020}the\u{0020}desire\u{0020}to\u{0020}travel.", "0", "如果我想去旅遊的話，說不定就會抽中免費機票或者豪華遊輪船票什麼的……不過說不定旅遊的景點會發生什麼糟糕的事情。這樣一想，就沒什麼心情去旅遊了呀。", "0", "0", "0", "cv_starry_6", "0", "0"},
[413306] = {413306, 11033, 7, 5, "1_》_0_0.8", "level1", "No\u{0020}matter\u{0020}what\u{0020}ridiculous\u{0020}actions\u{0020}I\u{0020}take,\u{0020}the\u{0020}world\u{0020}always\u{0020}seems\u{0020}to\u{0020}respond\u{0020}favorably.\u{0020}Unfair,\u{0020}right?", "0", "不論我採取多麼離譜的舉動，世界都會以好的結果來回應我的期待。如何？很不公平吧？", "0", "0", "0", "cv_starry_7", "0", "0"},
