[413401] = {413401, 11034, 2, 2, "0", "0", "Got\u{0020}it,\u{0020}Navigator!\u{0020}Anyone\u{0020}who\u{0020}tries\u{0020}to\u{0020}hurt\u{0020}you\u{0020}is\u{0020}getting\u{0020}a\u{0020}good\u{0020}beating\u{0020}from\u{0020}me!", "0", "瞭解！我會把所有想傷害領航的傢伙全部打飛的！", "0", "0", "0", "cv_lodonia_2", "0", "0"},
[413402] = {413402, 11034, 3, 3, "0", "0", "Whoa,\u{0020}whoa!\u{0020}You're\u{0020}the\u{0020}Navigator,\u{0020}aren't\u{0020}you?\u{0020}I've\u{0020}heard\u{0020}all\u{0020}about\u{0020}you!\u{0020}I'm\u{0020}Rodnia,\u{0020}from\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad.\u{0020}It's\u{0020}an\u{0020}honor\u{0020}to\u{0020}meet\u{0020}you!", "0", "噢噢噢！我聽說過你！你就是那位很厲害的領航吧！我是第三研究室防衛班的羅德尼亞，請多關照！", "0", "0", "0", "cv_lodonia_1", "0", "0"},
[413403] = {413403, 11034, 4, 4, "0", "idle", "Navigator,\u{0020}people\u{0020}say\u{0020}I'm\u{0020}a\u{0020}\"natural\u{0020}leader.\"\u{0020}Pretty\u{0020}impressive,\u{0020}right?\u{0020}Who\u{0020}said\u{0020}that?\u{0020}Hmph,\u{0020}I\u{0020}did!", "0", "領航，我可是被人評價為“天生的領袖”噢，超——厲害吧！誰說的？哼哼，當然是我自己說的啦。", "0", "0", "0", "cv_lodonia_3", "0", "0"},
[413404] = {413404, 11034, 5, 4, "0", "idle", "If\u{0020}you're\u{0020}bored,\u{0020}I\u{0020}can\u{0020}play\u{0020}the\u{0020}bagpipe\u{0020}for\u{0020}you!\u{0020}What's\u{0020}that\u{0020}look\u{0020}for?\u{0020}You\u{0020}don't\u{0020}think\u{0020}it\u{0020}suits\u{0020}me?\u{0020}How\u{0020}rude!\u{0020}I'm\u{0020}a\u{0020}gentle\u{0020}girl,\u{0020}you\u{0020}know!", "0", "領航要是無聊的話，我可以為你用風笛演奏樂曲噢！……什麼，“不像是我會做的事”？真是失禮啊，我可是溫柔的女孩子噢！", "0", "0", "0", "cv_lodonia_4", "0", "0"},
[413405] = {413405, 11034, 6, 4, "0", "idle", "You\u{0020}know,\u{0020}at\u{0020}first,\u{0020}I\u{0020}thought\u{0020}Captain\u{0020}Dolores\u{0020}was\u{0020}pretty\u{0020}weak.\u{0020}But\u{0020}after\u{0020}working\u{0020}with\u{0020}her,\u{0020}I\u{0020}realized\u{0020}how\u{0020}incredibly\u{0020}strong\u{0020}she\u{0020}is.\u{0020}She\u{0020}totally\u{0020}deserves\u{0020}the\u{0020}title\u{0020}of\u{0020}captain.", "0", "說起來……我一開始以為多洛莉絲隊長很弱呢。接觸之後才發現，她這不是超強的嗎！真不愧是“隊長”啊。", "0", "0", "0", "cv_lodonia_31", "0", "0"},
[413406] = {413406, 11034, 7, 5, "1_》_0_0.8", "level1", "Haha,\u{0020}that\u{0020}tickles!", "0", "好癢啦哈哈哈！", "0", "0", "0", "cv_lodonia_5", "0", "0"},
[413407] = {413407, 11034, 8, 5, "1_》_0_0.8", "level1", "My\u{0020}dream?\u{0020}Promise\u{0020}you\u{0020}won't\u{0020}laugh!\u{0020}I\u{0020}want\u{0020}to\u{0020}be\u{0020}as\u{0020}strong\u{0020}and\u{0020}kind\u{0020}as\u{0020}my\u{0020}sister\u{0020}and\u{0020}Captain\u{0020}Dolores.", "0", "我的夢想？說出來不許笑話我噢！我想成為像我的姐姐，還有多洛莉絲隊長那樣，既強大，又溫柔的人……", "0", "0", "0", "cv_lodonia_32", "0", "0"},
[413408] = {413408, 11034, 9, 5, "1_》_100_1.5", "level2", "Navigator,\u{0020}I'm\u{0020}not\u{0020}really\u{0020}the\u{0020}joking\u{0020}type.\u{0020}If\u{0020}there's\u{0020}something\u{0020}you\u{0020}want\u{0020}to\u{0020}do,\u{0020}don't\u{0020}wait\u{0020}-\u{0020}just\u{0020}go\u{0020}for\u{0020}it!\u{0020}That's\u{0020}how\u{0020}I\u{0020}live\u{0020}my\u{0020}life.", "0", "領航，我基本上是從來不開玩笑的噢。有想要做的事情就現在去做！這是我的人生信條！", "0", "0", "0", "cv_lodonia_6", "0", "0"},
[413409] = {413409, 11034, 10, 5, "1_》_500_2", "level3", "You've\u{0020}been\u{0020}working\u{0020}so\u{0020}hard,\u{0020}Navigator.\u{0020}Make\u{0020}sure\u{0020}you\u{0020}take\u{0020}care\u{0020}of\u{0020}yourself,\u{0020}too!\u{0020}Ugh,\u{0020}that\u{0020}sounded\u{0020}exhausting...\u{0020}How\u{0020}do\u{0020}my\u{0020}sister\u{0020}and\u{0020}Captain\u{0020}Dolores\u{0020}talk\u{0020}like\u{0020}that\u{0020}all\u{0020}the\u{0020}time?\u{0020}Sometimes\u{0020}I\u{0020}wish\u{0020}I\u{0020}could\u{0020}speak\u{0020}gently\u{0020}too,\u{0020}but\u{0020}it's\u{0020}so\u{0020}hard!", "0", "領航，工作辛苦了，也要稍微注重一下身體噢——啊，不行不行，這樣說話超累啊！姐姐和多洛莉絲隊長是怎麼做到的呀？我偶爾也想試著這樣，溫柔的和領航說話啦~", "0", "0", "0", "cv_lodonia_7", "0", "0"},
[413410] = {413410, 11034, 11, 5, "1_》_1000_2.5", "level4", "If\u{0020}something's\u{0020}bothering\u{0020}you\u{0020}-\u{0020}whether\u{0020}it's\u{0020}work\u{0020}or\u{0020}life\u{0020}-\u{0020}just\u{0020}let\u{0020}me\u{0020}know,\u{0020}okay?\u{0020}I'm\u{0020}here\u{0020}to\u{0020}listen!\u{0020}It's\u{0020}one\u{0020}of\u{0020}my\u{0020}goals\u{0020}to\u{0020}be\u{0020}someone\u{0020}you\u{0020}can\u{0020}count\u{0020}on.", "0", "領航，你工作上如果遇到什麼不順心的事，生活上有什麼煩惱，可以跟我說噢。我超願意當你的傾聽者，聽你講述自己的煩心事的！畢竟，這也是我的目標之一啦~", "0", "0", "0", "cv_lodonia_8", "0", "0"},
[413411] = {413411, 11034, 12, 6, "0", "0", "The\u{0020}senpais\u{0020}are\u{0020}so\u{0020}cool\u{0020}when\u{0020}they\u{0020}fight!\u{0020}I\u{0020}can't\u{0020}stop\u{0020}admiring\u{0020}them!", "0", "前輩們的戰鬥方式超帥啊！", "0", "0", "0", "cv_lodonia_9", "0", "0"},
