[413432] = {413432, 11034, 34, 26, "0", "0", "Whew!\u{0020}Phew!\u{0020}Haha,\u{0020}safe!\u{0020}What?\u{0020}Nothing\u{0020}happened!\u{0020}I\u{0020}was\u{0020}waiting\u{0020}for\u{0020}you\u{0020}like\u{0020}a\u{0020}good\u{0020}girl!", "0", "呼！嘿咻！嘿嘿，安全上壘！嗯？什麼都沒發生啦！我有老老實實地在這裏等你回來噢~", "0", "0", "0", "cv_lodonia_33", "0", "0"},
[413433] = {413433, 11034, 35, 27, "0", "0", "Don't\u{0020}you\u{0020}think\u{0020}it's\u{0020}about\u{0020}time\u{0020}you\u{0020}took\u{0020}me\u{0020}to\u{0020}a\u{0020}super-duper\u{0020}big\u{0020}battle,\u{0020}Navigator?", "0", "差不多該帶我去加入超大型戰役了吧~領航！", "0", "0", "0", "cv_lodonia_35", "0", "0"},
