[413600] = {413600, 11036, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_puruixiou_1", "0", "0"},
[413601] = {413601, 11036, 2, 2, "0", "0", "Really?\u{0020}Finally,\u{0020}I\u{0020}get\u{0020}to\u{0020}observe\u{0020}you\u{0020}up\u{0020}close.", "0", "真的？終於能更加近距離地觀察你了呢。", "0", "0", "0", "cv_puruixiou_2", "0", "0"},
[413602] = {413602, 11036, 3, 3, "0", "0", "The\u{0020}probability\u{0020}of\u{0020}us\u{0020}meeting\u{0020}was\u{0020}100%!\u{0020}Just\u{0020}kidding.\u{0020}I'm\u{0020}Precio,\u{0020}the\u{0020}Sin\u{0020}scholar\u{0020}from\u{0020}Sahara~", "0", "經過計算，你和我相遇的概率是……100%！嘿嘿，開個玩笑。這裡是普瑞席歐，薩哈拉的原罪學者哦~", "0", "0", "0", "cv_puruixiou_3", "0", "0"},
[413603] = {413603, 11036, 4, 4, "0", "idle", "It's\u{0020}nice\u{0020}to\u{0020}observe\u{0020}you,\u{0020}but\u{0020}research\u{0020}is\u{0020}so\u{0020}slow.\u{0020}I\u{0020}wish\u{0020}I\u{0020}could\u{0020}fast-forward\u{0020}to\u{0020}the\u{0020}next\u{0020}phase,\u{0020}like...\u{0020}hands-on\u{0020}experiments!", "0", "雖說能在這裡觀察你已經很不錯了，但科研的推進過程果然無比漫長，我真想快進到下一個階段，比如說……直接上手開始研究！", "0", "0", "0", "cv_puruixiou_4", "0", "0"},
[413604] = {413604, 11036, 5, 4, "0", "idle", "While\u{0020}you're\u{0020}observing\u{0020}me,\u{0020}I'm\u{0020}watching\u{0020}you\u{0020}too.\u{0020}It's\u{0020}essential\u{0020}to\u{0020}observe,\u{0020}not\u{0020}just\u{0020}interact.", "0", "當你凝視著我，我也正凝視著你哦。對於研究目標，不僅是接觸交流，單純地觀察也很必要。", "0", "0", "0", "cv_puruixiou_5", "0", "0"},
[413605] = {413605, 11036, 6, 4, "0", "idle", "Maybelle's\u{0020}insight,\u{0020}Stella's\u{0020}precision,\u{0020}and\u{0020}Mojun's\u{0020}knowledge\u{0020}are\u{0020}all\u{0020}key\u{0020}to\u{0020}the\u{0020}Honey\u{0020}Maker\u{0020}squad.\u{0020}But\u{0020}what\u{0020}keeps\u{0020}us\u{0020}together\u{0020}is\u{0020}more\u{0020}than\u{0020}just\u{0020}the\u{0020}convenience\u{0020}while\u{0020}working.", "0", "梅貝爾的席位，斯緹菈的精準，墨君的學識，都對製蜜人不可或缺。不過維繫這支小隊的，也絕不僅僅是工作上的便利呢。", "0", "0", "0", "cv_puruixiou_6", "0", "0"},
[413606] = {413606, 11036, 7, 5, "1_》_0_0.8", "level1", "Is\u{0020}everything\u{0020}measurable\u{0020}and\u{0020}calculable?\u{0020}Can\u{0020}thoughts\u{0020}be\u{0020}analyzed\u{0020}mathematically?\u{0020}Each\u{0020}of\u{0020}the\u{0020}\"Seven\u{0020}Sages\"\u{0020}has\u{0020}their\u{0020}answer.\u{0020}What's\u{0020}yours,\u{0020}Navigator?\u{0020}I'm\u{0020}curious.", "0", "是否萬物皆可測量與計算，連思維也能用數理邏輯加以分析？“七賢”各有答案，而領航你又如何認為呢？對此，我相當感興趣。", "0", "0", "0", "cv_puruixiou_7", "0", "0"},
[413607] = {413607, 11036, 8, 5, "1_》_0_0.8", "level1", "These\u{0020}\"swarms\"?\u{0020}Don't\u{0020}worry,\u{0020}they'll\u{0020}follow\u{0020}my\u{0020}orders\u{0020}like\u{0020}instruments\u{0020}follow\u{0020}a\u{0020}scientist\u{0020}or\u{0020}formulas\u{0020}obey\u{0020}a\u{0020}mathematician.", "0", "這些“蜂群”？請放心，它們會乖乖遵守我的指令，就像物理學家的儀器、數學家的公式，以及女王的僕從一樣聽話。", "0", "0", "0", "cv_puruixiou_8", "0", "0"},
[413608] = {413608, 11036, 9, 5, "1_》_100_1.5", "level2", "Want\u{0020}to\u{0020}help\u{0020}out\u{0020}in\u{0020}my\u{0020}lab?\u{0020}The\u{0020}data\u{0020}and\u{0020}tools\u{0020}are\u{0020}precious,\u{0020}but\u{0020}I\u{0020}trust\u{0020}you.", "0", "要不要來我的實驗室幫忙做點研究？那些數據與儀器是很貴重沒錯，但是你的話，我可以放心。", "0", "0", "0", "cv_puruixiou_9", "0", "0"},
[413609] = {413609, 11036, 10, 5, "1_》_500_2", "level3", "Interested\u{0020}in\u{0020}any\u{0020}Driver's\u{0020}body\u{0020}data?\u{0020}I\u{0020}can\u{0020}tell\u{0020}you\u{0020}how\u{0020}I\u{0020}collect\u{0020}it.\u{0020}Want\u{0020}to\u{0020}know\u{0020}mine?\u{0020}Hmm,\u{0020}that\u{0020}depends\u{0020}if\u{0020}you\u{0020}can\u{0020}get\u{0020}it~", "0", "對哪位駕駛員的身體數據感興趣嗎？我可以將採集方法告訴你哦。欸？想知道我的？唔……那就要看你有沒有本事拿到了呢~", "0", "0", "0", "cv_puruixiou_10", "0", "0"},
[413610] = {413610, 11036, 11, 5, "1_》_1000_2.5", "level4", "At\u{0020}first,\u{0020}I\u{0020}was\u{0020}only\u{0020}curious\u{0020}about\u{0020}your\u{0020}body,\u{0020}but\u{0020}now,\u{0020}your\u{0020}personality,\u{0020}emotions,\u{0020}and\u{0020}thoughts\u{0020}are\u{0020}fascinating\u{0020}me.\u{0020}It's\u{0020}been\u{0020}a\u{0020}while\u{0020}since\u{0020}I've\u{0020}had\u{0020}such\u{0020}a\u{0020}challenging\u{0020}subject.", "0", "最初只是對你的身體感興趣，漸漸的，你人格的構成、情感的運作、思維的奧秘，也開始讓我興致盎然了——這麼難的課題，我已久未遇見過。", "0", "0", "0", "cv_puruixiou_11", "0", "0"},
[413611] = {413611, 11036, 12, 6, "0", "0", "Growth\u{0020}is\u{0020}narrowing\u{0020}possibilities.", "0", "成長，就是逐漸減少可能性的過程。", "0", "0", "0", "cv_puruixiou_12", "0", "0"},
[413612] = {413612, 11036, 13, 7, "0", "0", "Quantitative\u{0020}changes\u{0020}lead\u{0020}to\u{0020}qualitative\u{0020}changes.", "0", "量變引起質變呢。", "0", "0", "0", "cv_puruixiou_13", "0", "0"},
[413613] = {413613, 11036, 14, 8, "0", "0", "I'll\u{0020}credit\u{0020}you\u{0020}when\u{0020}I\u{0020}publish\u{0020}these\u{0020}findings,\u{0020}and\u{0020}there\u{0020}may\u{0020}be\u{0020}other\u{0020}acknowledgments\u{0020}coming\u{0020}too,\u{0020}Navigator.", "0", "我會將自己這一成果，署上你的名字，而除此以外的致謝，領航也敬請期待哦。", "0", "0", "0", "cv_puruixiou_14", "0", "0"},
[413614] = {413614, 11036, 15, 9, "0", "0", "The\u{0020}\"swarm\"\u{0020}is\u{0020}buzzing.", "0", "“蜂群”在嗡鳴。", "0", "0", "0", "cv_puruixiou_15", "0", "0"},
[413615] = {413615, 11036, 16, 10, "0", "0", "Data\u{0020}is\u{0020}like\u{0020}pollen\u{0020}waiting\u{0020}to\u{0020}be\u{0020}collected.", "0", "數據猶如花粉，正待我們採集。", "0", "0", "0", "cv_puruixiou_16", "0", "0"},
[413616] = {413616, 11036, 17, 11, "0", "0", "Perfectly\u{0020}concluded,\u{0020}and\u{0020}the\u{0020}next\u{0020}batch\u{0020}of\u{0020}funding\u{0020}secured.", "0", "完美結束，新一批經費又有著落了。", "0", "0", "0", "cv_puruixiou_17", "0", "0"},
[413617] = {413617, 11036, 18, 12, "0", "0", "Not\u{0020}bad,\u{0020}not\u{0020}great,\u{0020}just\u{0020}like\u{0020}most\u{0020}experiments.", "0", "不好也不壞，就像多數時候的實驗一樣。", "0", "0", "0", "cv_puruixiou_18", "0", "0"},
[413618] = {413618, 11036, 19, 13, "0", "0", "Let's\u{0020}adjust\u{0020}and\u{0020}move\u{0020}forward.", "0", "與其在這裡氣餒，不如趕緊回去調整一番。", "0", "0", "0", "cv_puruixiou_19", "0", "0"},
