[413724] = {413724, 11037, 27, 20, "0", "0", "Finally,\u{0020}we've\u{0020}reached\u{0020}a\u{0020}place\u{0020}of\u{0020}peace.", "0", "終於到了最讓人安心的地方。", "0", "0", "0", "cv_saileixiya_26", "0", "0"},
[413725] = {413725, 11037, 28, 21, "0", "0", "What's\u{0020}wrong?\u{0020}If\u{0020}nothing's\u{0020}the\u{0020}matter,\u{0020}don't\u{0020}stop—there\u{0020}are\u{0020}still\u{0020}places\u{0020}you\u{0020}haven't\u{0020}tended\u{0020}to.", "0", "怎麼了？沒事的話，還請不要停下動作，許多地方都還沒被您顧及。", "0", "0", "0", "cv_saileixiya_27", "0", "0"},
[413726] = {413726, 11037, 29, 21, "0", "0", "In\u{0020}this\u{0020}place\u{0020}meant\u{0020}for\u{0020}cleansing\u{0020}body\u{0020}and\u{0020}soul...\u{0020}Navigator,\u{0020}are\u{0020}you\u{0020}not\u{0020}thinking\u{0020}of\u{0020}impure\u{0020}things,\u{0020}are\u{0020}you?", "0", "在這洗滌身心的場合……領航您不會在思考某些不潔之事吧？", "0", "0", "0", "cv_saileixiya_28", "0", "0"},
[413727] = {413727, 11037, 30, 22, "0", "0", "There's\u{0020}still\u{0020}more.", "0", "還待更多。", "0", "0", "0", "cv_saileixiya_29", "0", "0"},
[413728] = {413728, 11037, 31, 23, "0", "0", "What's\u{0020}the\u{0020}point\u{0020}of\u{0020}this\u{0020}game?", "0", "這種遊戲……有什麼意義嗎？", "0", "0", "0", "cv_saileixiya_30", "0", "0"},
[413729] = {413729, 11037, 32, 24, "0", "0", "If\u{0020}you\u{0020}really\u{0020}want\u{0020}it,\u{0020}I'll\u{0020}compliment\u{0020}you.", "0", "您真的想要的話，我就誇獎你一句吧。", "0", "0", "0", "cv_saileixiya_31", "0", "0"},
