[413824] = {413824, 11038, 27, 20, "0", "0", "Oh,\u{0020}you're\u{0020}here?\u{0020}Another\u{0020}driver\u{0020}came\u{0020}in\u{0020}just\u{0020}now,\u{0020}but\u{0020}she\u{0020}got\u{0020}scared\u{0020}and\u{0020}ran\u{0020}off\u{0020}as\u{0020}soon\u{0020}as\u{0020}I\u{0020}showed\u{0020}up.", "0", "你來了？剛才本來還有個駕駛員，一看我進來就被嚇跑了。", "0", "0", "0", "cv_kafuka_26", "0", "0"},
[413825] = {413825, 11038, 28, 21, "0", "0", "Do\u{0020}you\u{0020}sing\u{0020}in\u{0020}the\u{0020}shower?\u{0020}I\u{0020}do,\u{0020}but\u{0020}I\u{0020}won't\u{0020}if\u{0020}someone\u{0020}else\u{0020}is\u{0020}around.", "0", "你會在浴室裡唱歌嗎？我雖然會，但旁邊有人的話還是算了。", "0", "0", "0", "cv_kafuka_27", "0", "0"},
[413826] = {413826, 11038, 29, 21, "0", "0", "I\u{0020}once\u{0020}got\u{0020}into\u{0020}a\u{0020}fight\u{0020}with\u{0020}some\u{0020}students\u{0020}in\u{0020}the\u{0020}school\u{0020}bathroom,\u{0020}but\u{0020}the\u{0020}floor\u{0020}was\u{0020}so\u{0020}slippery\u{0020}that\u{0020}neither\u{0020}of\u{0020}us\u{0020}could\u{0020}win.", "0", "有次我在學校浴室裡和其他學生打架，但地太滑，誰也沒打贏誰。", "0", "0", "0", "cv_kafuka_28", "0", "0"},
[413827] = {413827, 11038, 30, 22, "0", "0", "What's\u{0020}this?", "0", "這是啥。", "0", "0", "0", "cv_kafuka_29", "0", "0"},
