[413901] = {413901, 11039, 2, 2, "0", "0", "You've\u{0020}chosen\u{0020}me,\u{0020}and\u{0020}I\u{0020}will\u{0020}answer\u{0020}your\u{0020}call.", "0", "你選擇了吾，吾也會回應你的呼喚。", "0", "0", "0", "cv_sikadi_vd_02", "0", "0"},
[413902] = {413902, 11039, 3, 3, "0", "0", "I\u{0020}can\u{0020}feel\u{0020}it.\u{0020}The\u{0020}dark\u{0020}power\u{0020}that\u{0020}could\u{0020}no\u{0020}longer\u{0020}be\u{0020}contained\u{0020}has\u{0020}awakened\u{0020}with\u{0020}the\u{0020}rise\u{0020}of\u{0020}the\u{0020}Miracle\u{0020}Moon.\u{0020}Don't\u{0020}worry.\u{0020}I\u{0020}will\u{0020}protect\u{0020}you\u{0020}in\u{0020}this\u{0020}brand-new\u{0020}form,\u{0020}Navigator.", "0", "吾感受到了，已經抑制不住的黑暗力量，隨著奇跡之月升起而復蘇。別擔心，吾會以全新的姿態保護你的，領航。", "0", "0", "0", "cv_sikadi_vd_03", "0", "0"},
[413903] = {413903, 11039, 4, 4, "0", "idle", "This\u{0020}is\u{0020}the\u{0020}Queen\u{0020}of\u{0020}the\u{0020}Dunescaith'\u{0020}new\u{0020}form.\u{0020}I've\u{0020}decided\u{0020}to\u{0020}call\u{0020}it\u{0020}Royal\u{0020}Form\u{0020}III.\u{0020}Born\u{0020}from\u{0020}everyone's\u{0020}emotions...\u{0020}sounds\u{0020}cool,\u{0020}right?", "0", "這就是影之國女王的新形態，吾決定就叫它王之形態其三。因為受到大家鼓動的情緒而誕生……這樣子說是不是很酷！", "0", "0", "0", "cv_sikadi_vd_04", "0", "0"},
[413904] = {413904, 11039, 5, 4, "0", "idle", "Hahaha—\u{0020}I\u{0020}heard\u{0020}it\u{0020}from\u{0020}the\u{0020}dark\u{0020}depths—\u{0020}Navigator,\u{0020}you're\u{0020}thinking\u{0020}about\u{0020}me\u{0020}right\u{0020}now,\u{0020}aren't\u{0020}you?\u{0020}...Oh?\u{0020}You're\u{0020}not?\u{0020}Then\u{0020}maybe\u{0020}you\u{0020}were\u{0020}before,\u{0020}and\u{0020}I'm\u{0020}just\u{0020}getting\u{0020}it\u{0020}now!", "0", "哈——哈——哈——吾在黑暗的禁區中聽見了，我聽見了——領航你現在在心中想著吾的事情吧！……誒？沒，沒有嗎？……那就是以前想了，吾現在才收到！", "0", "0", "0", "cv_sikadi_vd_05", "0", "0"},
[413905] = {413905, 11039, 6, 4, "0", "idle", "\"Chocolate...\u{0020}all\u{0020}hideous\u{0020}monsters.\"\u{0020}How's\u{0020}that\u{0020}for\u{0020}a\u{0020}line?\u{0020}I'm\u{0020}thinking\u{0020}of\u{0020}using\u{0020}it\u{0020}in\u{0020}The\u{0020}Chronicles\u{0020}of\u{0020}the\u{0020}Dunescaith\u{0020}3,\u{0020}when\u{0020}the\u{0020}knightess\u{0020}says\u{0020}it\u{0020}as\u{0020}she's\u{0020}condemned\u{0020}by\u{0020}the\u{0020}masses.", "0", "“巧克力……都是醜陋的怪物。”你覺得這句臺詞怎麼樣？我打算把它用在《影之國編年史3》裡，當女騎士被千夫所指時說了這句話。", "0", "0", "0", "cv_sikadi_vd_06", "0", "0"},
[413906] = {413906, 11039, 7, 5, "1_》_0_0.8", "level1", "I\u{0020}am\u{0020}the\u{0020}vampire\u{0020}succubus\u{0020}princess\u{0020}who\u{0020}lives\u{0020}off\u{0020}blood,\u{0020}but\u{0020}now\u{0020}I'm\u{0020}satisfied\u{0020}with\u{0020}just\u{0020}chocolate.\u{0020}So,\u{0020}give\u{0020}me\u{0020}chocolate,\u{0020}quick!", "0", "吾乃吸食血液而活的吸血鬼魅魔王女，但是現在只要巧克力就足夠了，快點把巧克力交給吾！", "0", "0", "0", "cv_sikadi_vd_07", "0", "0"},
[413907] = {413907, 11039, 8, 5, "1_》_0_0.8", "level1", "Navigator,\u{0020}look,\u{0020}just\u{0020}like\u{0020}a\u{0020}swimsuit,\u{0020}you\u{0020}can\u{0020}see\u{0020}my\u{0020}belly\u{0020}button...\u{0020}Wait,\u{0020}but\u{0020}it's\u{0020}not\u{0020}quite\u{0020}the\u{0020}same.\u{0020}If\u{0020}you\u{0020}keep\u{0020}staring\u{0020}like\u{0020}that,\u{0020}I'm\u{0020}getting\u{0020}a\u{0020}little...\u{0020}No,\u{0020}stop\u{0020}looking,\u{0020}Navigator!", "0", "領航，你看你看，和泳裝一樣可以看到肚臍眼哦……咦，但是又和穿泳裝的時候不一樣……現在被領航一直盯著看的話，吾有點……不要……領航還是別看了！", "0", "0", "0", "cv_sikadi_vd_08", "0", "0"},
[413908] = {413908, 11039, 9, 5, "1_》_100_1.5", "level2", "Even\u{0020}when\u{0020}fate\u{0020}cruelly\u{0020}plays\u{0020}tricks\u{0020}on\u{0020}me,\u{0020}I'll\u{0020}find\u{0020}you.\u{0020}I'll\u{0020}find\u{0020}you\u{0020}and\u{0020}tell\u{0020}you\u{0020}how\u{0020}boring\u{0020}my\u{0020}days\u{0020}were\u{0020}without\u{0020}you.", "0", "即使被再殘酷的命運所愚弄，吾也會找到你的。吾會找到你向你訴說，在沒有你的日子裡吾是多麼無趣。", "0", "0", "0", "cv_sikadi_vd_09", "0", "0"},
[413909] = {413909, 11039, 10, 5, "1_》_500_2", "level3", "Hmm,\u{0020}I\u{0020}just\u{0020}realized...\u{0020}whether\u{0020}we're\u{0020}laughing\u{0020}and\u{0020}chatting\u{0020}about\u{0020}the\u{0020}future\u{0020}or\u{0020}hiding\u{0020}from\u{0020}Lilith,\u{0020}everything\u{0020}links\u{0020}back\u{0020}to\u{0020}you,\u{0020}Navigator.\u{0020}It's\u{0020}so\u{0020}good\u{0020}to\u{0020}have\u{0020}you\u{0020}here.", "0", "嗯，吾剛剛想到……無論是歡笑著暢聊未來的日子，還是忐忑著躲避莉莉絲的日子，都與領航息息相關呢，你永遠在這裡真是太好了。", "0", "0", "0", "cv_sikadi_vd_10", "0", "0"},
