[414001] = {414001, 11040, 2, 2, "0", "0", "I'll\u{0020}cheer\u{0020}right\u{0020}alongside\u{0020}Navigator\u{0020}here.", "0", "我會在這裡和領航一起加油的。", "0", "0", "0", "cv_dororisu_haani_002", "0", "0"},
[414002] = {414002, 11040, 3, 3, "0", "0", "No\u{0020}matter\u{0020}how\u{0020}many\u{0020}times\u{0020}I\u{0020}wear\u{0020}this\u{0020}AVG\u{0020}suit,\u{0020}I\u{0020}still\u{0020}feel\u{0020}a\u{0020}bit\u{0020}embarrassed...\u{0020}Let's\u{0020}go,\u{0020}Navigator.\u{0020}By\u{0020}the\u{0020}way,\u{0020}should\u{0020}I\u{0020}call\u{0020}you\u{0020}Mr.\u{0020}Producer\u{0020}now?", "0", "……不管多少次，穿上這套AVG還是會有點難為情呢……走吧領航，不過現在是不是稱呼您為製作人先生比較好？", "0", "0", "0", "cv_dororisu_haani_003", "0", "0"},
[414003] = {414003, 11040, 4, 4, "0", "idle", "This\u{0020}AVG\u{0020}is\u{0020}definitely\u{0020}better\u{0020}than\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad's\u{0020}suits,\u{0020}but\u{0020}wearing\u{0020}something\u{0020}like\u{0020}this\u{0020}into\u{0020}battle\u{0020}is\u{0020}a\u{0020}bit\u{0020}embarrassing…", "0", "這件AVG的性能確實比第三研究室防衛班的要好多，但是穿著這樣的衣服上戰場，感覺有些難為情……", "0", "0", "0", "cv_dororisu_haani_004", "0", "0"},
[414004] = {414004, 11040, 5, 4, "0", "idle", "The\u{0020}first\u{0020}time\u{0020}I\u{0020}wore\u{0020}this\u{0020}AVG,\u{0020}I\u{0020}almost\u{0020}charged\u{0020}straight\u{0020}at\u{0020}the\u{0020}enemy.\u{0020}Luckily,\u{0020}Gloria\u{0020}stopped\u{0020}me...\u{0020}I\u{0020}guess\u{0020}I'm\u{0020}just\u{0020}used\u{0020}to\u{0020}leading\u{0020}the\u{0020}charge\u{0020}with\u{0020}my\u{0020}shield\u{0020}now.", "0", "第一次使用這套AVG參與戰鬥的時候，我差點就往原罪的身上沖過去，還好格洛麗亞攔住了我……我已經習慣舉著盾沖在大家前面了。", "0", "0", "0", "cv_dororisu_haani_005", "0", "0"},
[414005] = {414005, 11040, 6, 4, "0", "idle", "I've\u{0020}been\u{0020}lucky,\u{0020}both\u{0020}back\u{0020}then\u{0020}and\u{0020}now.\u{0020}I\u{0020}want\u{0020}to\u{0020}share\u{0020}this\u{0020}luck\u{0020}with\u{0020}more\u{0020}people,\u{0020}along\u{0020}with\u{0020}you,\u{0020}Navigator.", "0", "那一次也是這一次也是……我真的很幸運。我想和領航一起用這份幸運帶給更多人希望。", "0", "0", "0", "cv_dororisu_haani_006", "0", "0"},
[414006] = {414006, 11040, 7, 5, "1_》_0_0.8", "level1", "\"If\u{0020}you\u{0020}don't\u{0020}want\u{0020}to\u{0020}be\u{0020}forgotten,\u{0020}or\u{0020}forget\u{0020}others,\u{0020}add\u{0020}a\u{0020}little\u{0020}color\u{0020}to\u{0020}your\u{0020}memories.\"\u{0020}That's\u{0020}what\u{0020}the\u{0020}Doctor\u{0020}told\u{0020}me.", "0", "“如果不想被忘記，不想忘記其他人，那就讓記憶中染上色彩吧，不管是自己也好，別人也好。”那位博士是這麼跟我說的。", "0", "0", "0", "cv_dororisu_haani_007", "0", "0"},
[414007] = {414007, 11040, 8, 5, "1_》_0_0.8", "level2", "Even\u{0020}if\u{0020}we're\u{0020}doing\u{0020}\"idol\u{0020}activities\"\u{0020}on\u{0020}the\u{0020}Ark,\u{0020}we\u{0020}can\u{0020}jump\u{0020}into\u{0020}emergency\u{0020}missions\u{0020}at\u{0020}any\u{0020}moment.\u{0020}I'll\u{0020}start\u{0020}small,\u{0020}alright?", "0", "只是在方舟內舉行“偶像活動”的話，即使有緊急任務也能馬上出擊，我可以先從最低限度慢慢做起吧。", "0", "0", "0", "cv_dororisu_haani_008", "0", "0"},
[414008] = {414008, 11040, 8, 5, "1_》_0_0.8", "level2", "Hey,\u{0020}did\u{0020}you\u{0020}hear\u{0020}the\u{0020}cheers\u{0020}outside,\u{0020}Navigator?\u{0020}The\u{0020}crowd\u{0020}is\u{0020}so\u{0020}excited,\u{0020}I\u{0020}feel\u{0020}a\u{0020}bit\u{0020}warm,\u{0020}but\u{0020}I\u{0020}know\u{0020}I\u{0020}can\u{0020}do\u{0020}this\u{0020}because\u{0020}you're\u{0020}with\u{0020}me.", "0", "嘿嘿，領航你有聽見外面的歡呼聲嗎，台下的氣氛好熱鬧，不知道為什麼感覺有點熱熱的，不過我一定會成功的，畢竟有領航陪著我嘛。", "0", "0", "0", "cv_dororisu_haani_046", "0", "0"},
[414009] = {414009, 11040, 9, 5, "1_》_100_1.5", "level4", "Danube's\u{0020}holding\u{0020}an\u{0020}event\u{0020}for\u{0020}Drivers,\u{0020}and\u{0020}a\u{0020}lot\u{0020}of\u{0020}famous\u{0020}ones\u{0020}will\u{0020}be\u{0020}there.\u{0020}I...\u{0020}I\u{0020}want\u{0020}to\u{0020}give\u{0020}it\u{0020}a\u{0020}try.\u{0020}Would\u{0020}you\u{0020}come\u{0020}with\u{0020}me,\u{0020}Navigator?", "0", "多瑙舉辦了一場只有駕駛員參與的演出，很多有名的駕駛員都會參加。我……我也想試試……和阿萊塔一起報名，領航能陪我一起去嗎？", "0", "0", "0", "cv_dororisu_haani_009", "0", "0"},
[414010] = {414010, 11040, 9, 5, "1_》_100_1.5", "level5", "Huh?\u{0020}Is\u{0020}there\u{0020}something\u{0020}on\u{0020}my\u{0020}face?\u{0020}Why\u{0020}are\u{0020}you\u{0020}staring\u{0020}at\u{0020}me\u{0020}like\u{0020}that...?", "0", "誒，怎麼了，我的臉上有什麼東西嗎……您為什麼一直盯著我看……？", "0", "0", "0", "cv_dororisu_haani_048", "0", "0"},
[414011] = {414011, 11040, 9, 5, "1_》_100_1.5", "level6", "Navigator...?\u{0020}You've\u{0020}been\u{0020}staring\u{0020}at\u{0020}something\u{0020}for\u{0020}a\u{0020}while\u{0020}now...\u{0020}Is\u{0020}there\u{0020}something\u{0020}wrong\u{0020}with\u{0020}my\u{0020}straps?\u{0020}I\u{0020}checked\u{0020}in\u{0020}the\u{0020}mirror\u{0020}and\u{0020}everything\u{0020}seemed\u{0020}fine.", "0", "領航……？從剛才開始你就一直在盯著什麼看……？……是我的綁帶錯了嗎？我明明已經對著鏡子確認過了才對。", "0", "0", "0", "cv_dororisu_haani_049", "0", "0"},
[414012] = {414012, 11040, 10, 5, "1_》_500_2", "level7", "You've\u{0020}been\u{0020}with\u{0020}me\u{0020}from\u{0020}the\u{0020}beginning,\u{0020}through\u{0020}everything—whether\u{0020}it's\u{0020}idol\u{0020}activities\u{0020}or\u{0020}working\u{0020}with\u{0020}the\u{0020}Third\u{0020}Research\u{0020}Defense\u{0020}Unit.", "0", "領航從一開始就陪在我身邊，我一直都記著，不管是最開始，還是最忙碌的那段時間，不管是偶像活動還是第三研究室防衛班。", "0", "0", "0", "cv_dororisu_haani_010", "0", "0"},
[414013] = {414013, 11040, 10, 5, "1_》_500_2", "level4", "Can\u{0020}you\u{0020}hold\u{0020}my\u{0020}hand\u{0020}for\u{0020}just\u{0020}a\u{0020}moment,\u{0020}Navigator?\u{0020}Deep\u{0020}breaths...\u{0020}Deep\u{0020}breaths...\u{0020}There,\u{0020}that\u{0020}feels\u{0020}much\u{0020}better.\u{0020}I'll\u{0020}give\u{0020}it\u{0020}my\u{0020}best!", "0", "能握住我的手嗎領航，一會兒就好，深呼吸——深呼吸——果然這樣做了之後感覺好很多了……我會加油的。", "0", "0", "0", "cv_dororisu_haani_051", "0", "0"},
[414014] = {414014, 11040, 11, 5, "1_》_1000_2.5", "level8", "I\u{0020}think\u{0020}I've\u{0020}finally\u{0020}found\u{0020}the\u{0020}color\u{0020}I\u{0020}want\u{0020}to\u{0020}paint\u{0020}my\u{0020}life\u{0020}with...\u{0020}I\u{0020}want\u{0020}to\u{0020}share\u{0020}it\u{0020}with\u{0020}you,\u{0020}Navigator.", "0", "我想……我已經找到了自己想要染上的色彩……我想把現在的色彩分享給領航。", "0", "0", "0", "cv_dororisu_haani_011", "0", "0"},
[414015] = {414015, 11040, 11, 5, "1_》_1000_2.5", "level2", "...The\u{0020}lights\u{0020}are\u{0020}a\u{0020}bit\u{0020}too\u{0020}bright,\u{0020}my\u{0020}eyes\u{0020}are\u{0020}starting\u{0020}to\u{0020}water.", "0", "……燈、燈光有點刺眼睛呢，我的眼淚都快流出來。", "0", "0", "0", "cv_dororisu_haani_053", "0", "0"},
[414016] = {414016, 11040, 11, 5, "1_》_1000_2.5", "level2", "...It's\u{0020}nothing,\u{0020}really.\u{0020}My\u{0020}eyes\u{0020}just\u{0020}got\u{0020}a\u{0020}bit\u{0020}tired.\u{0020}I'll\u{0020}close\u{0020}them\u{0020}for\u{0020}a\u{0020}moment.", "0", "……沒、沒什麼，我只是感覺眼睛忽然很累，閉眼休息一會。", "0", "0", "0", "cv_dororisu_haani_054", "0", "0"},
[414017] = {414017, 11040, 12, 6, "0", "0", "I'll\u{0020}keep\u{0020}pushing\u{0020}forward!\u{0020}I\u{0020}want\u{0020}to\u{0020}be\u{0020}the\u{0020}reason\u{0020}everyone\u{0020}fights.", "0", "我會繼續努力的！我要成為大家戰鬥的理由。", "0", "0", "0", "cv_dororisu_haani_012", "0", "0"},
[414018] = {414018, 11040, 13, 7, "0", "0", "I\u{0020}feel\u{0020}like\u{0020}I\u{0020}can\u{0020}do\u{0020}so\u{0020}much\u{0020}more\u{0020}now.", "0", "感覺現在的我可以做得更多。", "0", "0", "0", "cv_dororisu_haani_013", "0", "0"},
[414019] = {414019, 11040, 14, 8, "0", "0", "I\u{0020}want\u{0020}to\u{0020}spread\u{0020}hope\u{0020}and\u{0020}lift\u{0020}everyone's\u{0020}spirits.\u{0020}That's\u{0020}what\u{0020}I\u{0020}aim\u{0020}for.", "0", "傳遞更多希望，帶走大家的悲傷，我要做到這樣的事情。", "0", "0", "0", "cv_dororisu_haani_014", "0", "0"},
[414020] = {414020, 11040, 15, 9, "0", "0", "This\u{0020}suit\u{0020}of\u{0020}armor\u{0020}has\u{0020}a\u{0020}lot\u{0020}of\u{0020}new\u{0020}functions,\u{0020}and\u{0020}I'm\u{0020}still\u{0020}getting\u{0020}used\u{0020}to\u{0020}it.", "0", "這身裝甲，裝載了很多新功能，我還在慢慢熟悉。", "0", "0", "0", "cv_dororisu_haani_015", "0", "0"},
[414021] = {414021, 11040, 16, 10, "0", "0", "The\u{0020}battle\u{0020}has\u{0020}begun.\u{0020}Please\u{0020}give\u{0020}the\u{0020}order,\u{0020}Navigator.", "0", "戰鬥開始了，請下達指令吧，領航。", "0", "0", "0", "cv_dororisu_haani_016", "0", "0"},
[414022] = {414022, 11040, 17, 11, "0", "0", "I\u{0020}want\u{0020}to\u{0020}bring\u{0020}smiles\u{0020}to\u{0020}everyone\u{0020}all\u{0020}the\u{0020}time.\u{0020}Maybe\u{0020}that's\u{0020}why\u{0020}I\u{0020}fight.", "0", "想要一直為大家帶來笑容，可能這就是我戰鬥的理由吧。", "0", "0", "0", "cv_dororisu_haani_017", "0", "0"},
[414023] = {414023, 11040, 18, 12, "0", "0", "I\u{0020}can't\u{0020}stop\u{0020}here;\u{0020}I\u{0020}need\u{0020}to\u{0020}push\u{0020}harder.", "0", "還不夠，我不能在這裡停下。", "0", "0", "0", "cv_dororisu_haani_018", "0", "0"},
[414024] = {414024, 11040, 19, 13, "0", "0", "I\u{0020}can\u{0020}do\u{0020}better...", "0", "我還可以做得更好……", "0", "0", "0", "cv_dororisu_haani_019", "0", "0"},
[414025] = {414025, 11040, 20, 14, "0", "0", "I'll\u{0020}handle\u{0020}the\u{0020}final\u{0020}fire\u{0020}suppression.\u{0020}Everyone,\u{0020}please\u{0020}retreat\u{0020}in\u{0020}an\u{0020}orderly\u{0020}fashion.", "0", "我來做最後的火力壓制，請大家有序撤退。", "0", "0", "0", "cv_dororisu_haani_020", "0", "0"},
[414026] = {414026, 11040, 21, 15, "0", "0", "Smashed!", "0", "擊碎了！", "0", "0", "0", "cv_dororisu_haani_021", "0", "0"},
[414027] = {414027, 11040, 23, 16, "0", "0", "Hey-a—", "0", "誒咿——", "0", "0", "0", "cv_dororisu_haani_022", "0", "0"},
