[414029] = {414029, 11040, 25, 18, "0", "0", "I\u{0020}want\u{0020}to\u{0020}shatter\u{0020}this\u{0020}future\u{0020}devoid\u{0020}of\u{0020}light\u{0020}and\u{0020}darkness.", "0", "我要打破這沒有光芒與黑暗的未來。", "0", "0", "0", "cv_dororisu_haani_024", "0", "0"},
[414030] = {414030, 11040, 26, 19, "0", "0", "I\u{0020}just\u{0020}want\u{0020}to\u{0020}keep\u{0020}cheering\u{0020}everyone\u{0020}on.", "0", "……想要繼續給大家打氣。", "0", "0", "0", "cv_dororisu_haani_025", "0", "0"},
[414031] = {414031, 11040, 27, 20, "0", "0", "I\u{0020}really\u{0020}wish\u{0020}I\u{0020}could\u{0020}come\u{0020}here\u{0020}to\u{0020}relax\u{0020}after\u{0020}my\u{0020}performance.", "0", "真想在登臺完之後也能來這裡放鬆一下呢。", "0", "0", "0", "cv_dororisu_haani_026", "0", "0"},
[414032] = {414032, 11040, 28, 21, "0", "0", "Hurry\u{0020}up\u{0020}and\u{0020}start,\u{0020}Navigator.", "0", "快點開始吧，領航。", "0", "0", "0", "cv_dororisu_haani_027", "0", "0"},
[414033] = {414033, 11040, 29, 21, "0", "0", "Uh...\u{0020}Ah—so\u{0020}comfortable.", "0", "嗯~啊——好舒服呀。", "0", "0", "0", "cv_dororisu_haani_028", "0", "0"},
[414034] = {414034, 11040, 30, 22, "0", "0", "Taking\u{0020}a\u{0020}break\u{0020}for\u{0020}a\u{0020}bit...\u{0020}That\u{0020}should\u{0020}be\u{0020}fine,\u{0020}right?", "0", "偷懶一會會……也沒有關係的吧。", "0", "0", "0", "cv_dororisu_haani_029", "0", "0"},
[414035] = {414035, 11040, 31, 23, "0", "0", "Once\u{0020}it's\u{0020}over,\u{0020}let's\u{0020}get\u{0020}back\u{0020}to\u{0020}training...\u{0020}Especially\u{0020}for\u{0020}the\u{0020}performance\u{0020}rehearsal.", "0", "等結束之後，我們繼續訓練吧……關於演出的彩排。", "0", "0", "0", "cv_dororisu_haani_030", "0", "0"},
[414036] = {414036, 11040, 32, 24, "0", "0", "That's\u{0020}right.\u{0020}You\u{0020}truly\u{0020}are\u{0020}the\u{0020}Navigator.", "0", "答對了，不愧是領航。", "0", "0", "0", "cv_dororisu_haani_031", "0", "0"},
[414037] = {414037, 11040, 33, 25, "0", "0", "Hehe,\u{0020}you\u{0020}guessed\u{0020}wrong.\u{0020}I'm\u{0020}Dolores.", "0", "呵呵，猜錯了，我是多洛莉絲哦。", "0", "0", "0", "cv_dororisu_haani_032", "0", "0"},
[414038] = {414038, 11040, 34, 26, "0", "0", "It's\u{0020}great\u{0020}to\u{0020}see\u{0020}you\u{0020}again!", "0", "終於又見到您了。", "0", "0", "0", "cv_dororisu_haani_033", "0", "0"},
[414039] = {414039, 11040, 35, 27, "0", "0", "Dolores,\u{0020}ready!", "0", "多洛莉絲，準備完畢。", "0", "0", "0", "cv_dororisu_haani_034", "0", "0"},
[414040] = {414040, 11040, 36, 28, "0", "0", "I\u{0020}come\u{0020}here\u{0020}every\u{0020}day.", "0", "我每天都會來這裡呢。", "0", "0", "0", "cv_dororisu_haani_035", "0", "0"},
[414041] = {414041, 11040, 37, 29, "0", "0", "It's\u{0020}wonderful\u{0020}to\u{0020}see\u{0020}everyone\u{0020}so\u{0020}energized.", "0", "看到大家都這麼精神，真是太好了。", "0", "0", "0", "cv_dororisu_haani_036", "0", "0"},
[414042] = {414042, 11040, 38, 30, "0", "0", "Um...\u{0020}Are\u{0020}we\u{0020}getting\u{0020}ready\u{0020}to\u{0020}welcome\u{0020}new\u{0020}drivers?", "0", "嗯……要準備迎接新的駕駛員嗎？", "0", "0", "0", "cv_dororisu_haani_037", "0", "0"},
[414043] = {414043, 11040, 39, 31, "0", "0", "I\u{0020}don't\u{0020}need\u{0020}any\u{0020}equipment.\u{0020}Please\u{0020}set\u{0020}it\u{0020}up\u{0020}for\u{0020}everyone\u{0020}else.", "0", "裝備……我就不用了，請給大家準備吧。", "0", "0", "0", "cv_dororisu_haani_038", "0", "0"},
[414044] = {414044, 11040, 40, 32, "0", "0", "The\u{0020}purchasing\u{0020}center.\u{0020}It's\u{0020}been\u{0020}a\u{0020}while\u{0020}since\u{0020}I\u{0020}visited\u{0020}here.", "0", "採購中心，好久沒有來了。", "0", "0", "0", "cv_dororisu_haani_039", "0", "0"},
[414045] = {414045, 11040, 41, 33, "0", "0", "Do\u{0020}you\u{0020}want\u{0020}me\u{0020}to\u{0020}check\u{0020}the\u{0020}files\u{0020}for\u{0020}you?", "0", "要我幫您核對一下檔案嗎？", "0", "0", "0", "cv_dororisu_haani_040", "0", "0"},
[414046] = {414046, 11040, 42, 34, "0", "0", "Let's\u{0020}confirm\u{0020}the\u{0020}status.", "0", "確認好狀態吧。", "0", "0", "0", "cv_dororisu_haani_041", "0", "0"},
[414047] = {414047, 11040, 43, 35, "0", "0", "Old\u{0020}emails\u{0020}should\u{0020}be\u{0020}properly\u{0020}stored\u{0020}as\u{0020}well.", "0", "舊的郵件也要收納好哦。", "0", "0", "0", "cv_dororisu_haani_042", "0", "0"},
