[414049] = {414049, 11040, 45, 37, "0", "0", "Eh!", "0", "誒咻！", "0", "0", "0", "cv_dororisu_haani_044", "0", "0"},
[414100] = {414100, 11041, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響。", "0", "0", "0", "cv_zhinvxing_1", "0", "0"},
[414101] = {414101, 11041, 2, 2, "0", "0", "I've\u{0020}got\u{0020}some\u{0020}free\u{0020}time\u{0020}while\u{0020}I\u{0020}wait\u{0020}for\u{0020}the\u{0020}investigation\u{0020}results,\u{0020}so\u{0020}I\u{0020}accepted\u{0020}your\u{0020}invitation\u{0020}to\u{0020}experience\u{0020}a\u{0020}day\u{0020}in\u{0020}the\u{0020}life\u{0020}of\u{0020}a\u{0020}Danube\u{0020}Driver.", "0", "正好我現在等調查結果，也沒什麼事可做，就應你邀請，來體驗一下多瑙駕駛員的日常工作吧。", "0", "0", "0", "cv_zhinvxing_2", "0", "0"},
[414102] = {414102, 11041, 3, 3, "0", "0", "Oh?\u{0020}So\u{0020}you're\u{0020}the\u{0020}Navigator\u{0020}Courant\u{0020}keeps\u{0020}praising?\u{0020}Well,\u{0020}let\u{0020}me\u{0020}introduce\u{0020}myself\u{0020}properly.\u{0020}Code\u{0020}name:\u{0020}Vega,\u{0020}from\u{0020}Iskanwaya\u{0020}in\u{0020}Inca\u{0020}region.", "0", "哦？你就是柯朗吹捧的那位領航？那麼重新自我介紹一下。代號織女星，隸屬於伊斯坎瓦亞，來自印加地區。", "0", "0", "0", "cv_zhinvxing_3", "0", "0"},
[414103] = {414103, 11041, 4, 4, "0", "idle", "Danube\u{0020}is\u{0020}a\u{0020}wonderful\u{0020}place.\u{0020}What\u{0020}really\u{0020}stands\u{0020}out\u{0020}is\u{0020}how\u{0020}friendly\u{0020}everyone\u{0020}is.", "0", "多瑙真是個好地方啊。最難能可貴的是，這裏非常有人情味。", "0", "0", "0", "cv_zhinvxing_4", "0", "0"},
[414104] = {414104, 11041, 5, 4, "0", "idle", "Rest\u{0020}is\u{0020}just\u{0020}as\u{0020}important\u{0020}as\u{0020}preparing\u{0020}for\u{0020}battle,\u{0020}and\u{0020}you\u{0020}know\u{0020}it\u{0020}well.", "0", "休息也是備戰的一環。你很懂嘛。", "0", "0", "0", "cv_zhinvxing_5", "0", "0"},
[414105] = {414105, 11041, 6, 4, "0", "idle", "Hey,\u{0020}if\u{0020}you're\u{0020}feeling\u{0020}tired,\u{0020}head\u{0020}back\u{0020}to\u{0020}your\u{0020}room\u{0020}and\u{0020}sleep.\u{0020}No\u{0020}need\u{0020}to\u{0020}force\u{0020}yourself\u{0020}to\u{0020}stay\u{0020}awake.", "0", "嘿。如果覺得困了，就回房間睡覺，別在這裏硬撐。", "0", "0", "0", "cv_zhinvxing_6", "0", "0"},
[414106] = {414106, 11041, 7, 5, "1_》_0_0.8", "level1", "Promise\u{0020}me,\u{0020}if\u{0020}you\u{0020}see\u{0020}a\u{0020}suspicious-looking\u{0020}crate\u{0020}big\u{0020}enough\u{0020}to\u{0020}hold\u{0020}a\u{0020}person,\u{0020}call\u{0020}me\u{0020}immediately.\u{0020}For\u{0020}your\u{0020}own\u{0020}safety,\u{0020}don't\u{0020}open\u{0020}it.", "0", "答應我，如果看到了可疑的、能裝下一個人的貨物箱，一定要在第一時間聯繫我。為了你的人身安全，絕對不要擅自打開。", "0", "0", "0", "cv_zhinvxing_7", "0", "0"},
[414107] = {414107, 11041, 8, 5, "1_》_0_0.8", "level1", "Suana?\u{0020}You\u{0020}can\u{0020}call\u{0020}me\u{0020}by\u{0020}my\u{0020}real\u{0020}name\u{0020}if\u{0020}you\u{0020}want.\u{0020}Just\u{0020}not\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}okay?\u{0020}We\u{0020}have\u{0020}rules\u{0020}for\u{0020}that.", "0", "蘇亞娜？你想叫我本名是無妨，但不要在戰場上這樣稱呼。畢竟我們在這方面是有規章制度需要遵守的。", "0", "0", "0", "cv_zhinvxing_8", "0", "0"},
[414108] = {414108, 11041, 9, 5, "1_》_100_1.5", "level2", "I\u{0020}chose\u{0020}the\u{0020}code\u{0020}name\u{0020}\"Vega\"\u{0020}as\u{0020}a\u{0020}reminder\u{0020}to\u{0020}myself\u{0020}not\u{0020}to\u{0020}trust\u{0020}others\u{0020}too\u{0020}easily.\u{0020}Now?\u{0020}Well,\u{0020}if\u{0020}I\u{0020}could,\u{0020}I'd\u{0020}give\u{0020}it\u{0020}back.\u{0020}But\u{0020}once\u{0020}a\u{0020}code\u{0020}name\u{0020}is\u{0020}set,\u{0020}you're\u{0020}stuck\u{0020}with\u{0020}it.", "0", "當初會起“織女星”這個代號，只是為了借此警示自己，不要再輕信他人。至於現在嘛……如果可以，我想要將它還回去。可惜代號一經確定，就不允許修改了。", "0", "0", "0", "cv_zhinvxing_9", "0", "0"},
[414109] = {414109, 11041, 10, 5, "1_》_500_2", "level3", "I\u{0020}heard\u{0020}your\u{0020}intelligence\u{0020}officer\u{0020}is\u{0020}actually\u{0020}your\u{0020}sister.\u{0020}Having\u{0020}family\u{0020}support...\u{0020}I'm\u{0020}a\u{0020}little\u{0020}jealous\u{0020}of\u{0020}that.", "0", "我聽說你的那位情報官，其實是你妹妹。能得到家人的支持……真令人羡慕啊。", "0", "0", "0", "cv_zhinvxing_10", "0", "0"},
[414110] = {414110, 11041, 11, 5, "1_》_1000_2.5", "level4", "Looking\u{0020}back,\u{0020}if\u{0020}my\u{0020}parents\u{0020}had\u{0020}been\u{0020}half\u{0020}as\u{0020}supportive\u{0020}as\u{0020}yours,\u{0020}things\u{0020}might\u{0020}have\u{0020}turned\u{0020}out\u{0020}differently\u{0020}for\u{0020}me...\u{0020}Oh,\u{0020}I've\u{0020}got\u{0020}an\u{0020}idea.\u{0020}You're\u{0020}not\u{0020}related\u{0020}to\u{0020}your\u{0020}family\u{0020}by\u{0020}blood,\u{0020}right?\u{0020}So\u{0020}why\u{0020}not\u{0020}add\u{0020}me\u{0020}in,\u{0020}too?\u{0020}Think\u{0020}it\u{0020}over,\u{0020}don't\u{0020}be\u{0020}so\u{0020}quick\u{0020}to\u{0020}say\u{0020}no.", "0", "現如今想想，如果那對夫婦能有你的一半好，我也不至於……欸，突然想到了個好主意。反正你與你的家人們都沒有血緣關係，那麼再加我一個也沒問題？別急著拒絕，你再考慮考慮？", "0", "0", "0", "cv_zhinvxing_11", "0", "0"},
[414111] = {414111, 11041, 12, 6, "0", "0", "I'll\u{0020}return\u{0020}the\u{0020}favor,\u{0020}of\u{0020}course.", "0", "我這邊也會奉上誠意回報的。", "0", "0", "0", "cv_zhinvxing_12", "0", "0"},
[414112] = {414112, 11041, 13, 7, "0", "0", "You're\u{0020}using\u{0020}precious\u{0020}resources\u{0020}on\u{0020}a\u{0020}non-core\u{0020}Driver...\u{0020}You\u{0020}really\u{0020}are\u{0020}something\u{0020}else,\u{0020}aren't\u{0020}you?", "0", "居然會把難得的資源用在非嫡系的駕駛員身上……你還真是個怪人。", "0", "0", "0", "cv_zhinvxing_13", "0", "0"},
[414113] = {414113, 11041, 14, 8, "0", "0", "At\u{0020}this\u{0020}point,\u{0020}if\u{0020}I\u{0020}don't\u{0020}reciprocate,\u{0020}I'd\u{0020}look\u{0020}pretty\u{0020}stingy.\u{0020}So\u{0020}how\u{0020}about\u{0020}this:\u{0020}if\u{0020}you\u{0020}ever\u{0020}visit\u{0020}Inca,\u{0020}I\u{0020}can't\u{0020}guarantee\u{0020}you'll\u{0020}have\u{0020}full\u{0020}freedom,\u{0020}but\u{0020}I'll\u{0020}help\u{0020}out\u{0020}wherever\u{0020}I\u{0020}can.", "0", "到這份上，如果再不意思一下，就顯得我這人有些小氣了。所以來約定吧。等以後你來印加了，雖然沒法保證讓你橫著走，但只要是能幫上忙的，我都不會拒絕。", "0", "0", "0", "cv_zhinvxing_14", "0", "0"},
[414114] = {414114, 11041, 15, 9, "0", "0", "An\u{0020}equipment\u{0020}upgrade?\u{0020}Are\u{0020}you\u{0020}covering\u{0020}the\u{0020}costs?\u{0020}The\u{0020}treatment\u{0020}for\u{0020}drivers\u{0020}on\u{0020}the\u{0020}Danube\u{0020}side\u{0020}is\u{0020}too\u{0020}good,\u{0020}isn't\u{0020}it?!", "0", "設備升級？費用還是你來出？多瑙這邊的駕駛員待遇也太好了吧？！", "0", "0", "0", "cv_zhinvxing_15", "0", "0"},
[414115] = {414115, 11041, 16, 10, "0", "0", "How\u{0020}much\u{0020}time\u{0020}do\u{0020}you\u{0020}need\u{0020}me\u{0020}to\u{0020}buy\u{0020}for\u{0020}the\u{0020}retreat?", "0", "說吧，需要我幫忙爭取多少撤退時間？", "0", "0", "0", "cv_zhinvxing_16", "0", "0"},
[414116] = {414116, 11041, 17, 11, "0", "0", "Wow,\u{0020}a\u{0020}total\u{0020}victory?\u{0020}You've\u{0020}got\u{0020}some\u{0020}serious\u{0020}skills,\u{0020}Navigator.", "0", "喲吼，大獲全勝？你這傢伙很行嘛。", "0", "0", "0", "cv_zhinvxing_17", "0", "0"},
[414117] = {414117, 11041, 18, 12, "0", "0", "This\u{0020}little\u{0020}wound?\u{0020}It's\u{0020}nothing.\u{0020}Where's\u{0020}the\u{0020}next\u{0020}battlefield?", "0", "這點小傷不礙事。下一個戰場在哪里？", "0", "0", "0", "cv_zhinvxing_18", "0", "0"},
[414118] = {414118, 11041, 19, 13, "0", "0", "Good\u{0020}thing\u{0020}you\u{0020}warned\u{0020}the\u{0020}others\u{0020}to\u{0020}evacuate\u{0020}the\u{0020}civilians\u{0020}before\u{0020}the\u{0020}battle\u{0020}started.", "0", "幸好你有先見之明，在開戰之前先通知其他隊伍疏散了群眾。", "0", "0", "0", "cv_zhinvxing_19", "0", "0"},
[414119] = {414119, 11041, 20, 14, "0", "0", "Are\u{0020}you\u{0020}trying\u{0020}to\u{0020}cheer\u{0020}me\u{0020}up?\u{0020}Haha,\u{0020}no\u{0020}need—I've\u{0020}grown\u{0020}used\u{0020}to\u{0020}defeats\u{0020}like\u{0020}this.", "0", "你難道是想安慰我？哈哈，不需要，這種失敗我早就習慣了。", "0", "0", "0", "cv_zhinvxing_20", "0", "0"},
[414120] = {414120, 11041, 21, 15, "0", "0", "Hah,\u{0020}not\u{0020}even\u{0020}I\u{0020}could\u{0020}take\u{0020}them\u{0020}down.", "0", "呵，連我都打不過。", "0", "0", "0", "cv_zhinvxing_21", "0", "0"},
[414121] = {414121, 11041, 23, 16, "0", "0", "I'll\u{0020}keep\u{0020}them\u{0020}occupied.", "0", "由我來牽制他們。", "0", "0", "0", "cv_zhinvxing_23", "0", "0"},
[414122] = {414122, 11041, 24, 17, "0", "0", "So,\u{0020}this\u{0020}is\u{0020}your\u{0020}decision?", "0", "這就是你的決斷嗎？", "0", "0", "0", "cv_zhinvxing_24", "0", "0"},
[414123] = {414123, 11041, 26, 19, "0", "0", "I\u{0020}think\u{0020}I've\u{0020}bought\u{0020}enough\u{0020}time...", "0", "應該爭取到足夠的時間了……", "0", "0", "0", "cv_zhinvxing_26", "0", "0"},
[414124] = {414124, 11041, 27, 20, "0", "0", "No\u{0020}matter\u{0020}how\u{0020}many\u{0020}times\u{0020}I\u{0020}come\u{0020}here,\u{0020}I'll\u{0020}never\u{0020}get\u{0020}used\u{0020}to\u{0020}it.\u{0020}Why\u{0020}is\u{0020}the\u{0020}\"maintenance\u{0020}pool\"\u{0020}right\u{0020}under\u{0020}your\u{0020}office?", "0", "不管第幾次來，都接受不了啊……為什麼“維修池”會就在你的辦公室下麵？", "0", "0", "0", "cv_zhinvxing_27", "0", "0"},
[414125] = {414125, 11041, 28, 21, "0", "0", "I\u{0020}never\u{0020}imagined...\u{0020}that\u{0020}I\u{0020}could\u{0020}take\u{0020}a\u{0020}bath\u{0020}here\u{0020}after\u{0020}growing\u{0020}to\u{0020}giant\u{0020}size.\u{0020}This\u{0020}feels\u{0020}so\u{0020}weird.", "0", "沒想到……巨大化之後還能像這樣躺在池子裡泡澡，真不可思議。", "0", "0", "0", "cv_zhinvxing_28", "0", "0"},
[414126] = {414126, 11041, 29, 21, "0", "0", "So,\u{0020}any\u{0020}Driver\u{0020}can\u{0020}use\u{0020}your\u{0020}maintenance\u{0020}pool?\u{0020}Why\u{0020}do\u{0020}you\u{0020}call\u{0020}it\u{0020}yours?\u{0020}It's\u{0020}just\u{0020}you\u{0020}and\u{0020}me\u{0020}here\u{0020}after\u{0020}all.", "0", "……任何駕駛員都可以在這裡使用你的維修池嗎？為什麼說是你的維修池？因為這裡除了你和我外沒有別人了呀。", "0", "0", "0", "cv_zhinvxing_29", "0", "0"},
[414127] = {414127, 11041, 30, 22, "0", "0", "Go\u{0020}ahead,\u{0020}I'm\u{0020}ready.", "0", "動手吧。我已經準備好了。", "0", "0", "0", "cv_zhinvxing_30", "0", "0"},
[414128] = {414128, 11041, 31, 23, "0", "0", "I've\u{0020}heard\u{0020}about\u{0020}this\u{0020}part.", "0", "我聽說過這個環節。", "0", "0", "0", "cv_zhinvxing_31", "0", "0"},
[414129] = {414129, 11041, 32, 24, "0", "0", "As\u{0020}expected,\u{0020}nothing\u{0020}gets\u{0020}past\u{0020}you.", "0", "果然難不倒你。", "0", "0", "0", "cv_zhinvxing_32", "0", "0"},
[414130] = {414130, 11041, 33, 25, "0", "0", "Don't\u{0020}worry,\u{0020}it's\u{0020}totally\u{0020}fine\u{0020}to\u{0020}guess\u{0020}wrong.\u{0020}After\u{0020}all,\u{0020}I'm\u{0020}from\u{0020}out\u{0020}of\u{0020}town.", "0", "別介意，猜不出來也正常。誰讓我是外地人呢。", "0", "0", "0", "cv_zhinvxing_33", "0", "0"},
[414131] = {414131, 11041, 34, 26, "0", "0", "Hey,\u{0020}we\u{0020}meet\u{0020}again.\u{0020}Your\u{0020}eyes\u{0020}look\u{0020}sharp\u{0020}today.\u{0020}I\u{0020}can\u{0020}see\u{0020}that\u{0020}you\u{0020}have\u{0020}the\u{0020}tenacity\u{0020}of\u{0020}a\u{0020}true\u{0020}warrior.", "0", "喲，又見面了。今天你的眼神也很不錯，能看到一名戰士該有的堅韌。", "0", "0", "0", "cv_zhinvxing_34", "0", "0"},
[414132] = {414132, 11041, 35, 27, "0", "0", "Finally,\u{0020}I\u{0020}get\u{0020}to\u{0020}see\u{0020}your\u{0020}special\u{0020}skills\u{0020}in\u{0020}action.", "0", "終於有機會見識一下你的特殊能力了。", "0", "0", "0", "cv_zhinvxing_35", "0", "0"},
[414133] = {414133, 11041, 36, 28, "0", "0", "Drills?\u{0020}So\u{0020}we're\u{0020}going\u{0020}up\u{0020}against\u{0020}each\u{0020}other?\u{0020}This\u{0020}should\u{0020}be\u{0020}fun.", "0", "演習？也就是自己人跟自己人打？有點意思。", "0", "0", "0", "cv_zhinvxing_36", "0", "0"},
[414134] = {414134, 11041, 37, 29, "0", "0", "It's\u{0020}clear\u{0020}the\u{0020}other\u{0020}Drivers\u{0020}really\u{0020}respect\u{0020}you.", "0", "能看出來，那些駕駛員都很仰慕你。", "0", "0", "0", "cv_zhinvxing_37", "0", "0"},
[414135] = {414135, 11041, 38, 30, "0", "0", "What\u{0020}does\u{0020}being\u{0020}a\u{0020}Driver\u{0020}mean\u{0020}to\u{0020}you,\u{0020}Navigator?", "0", "在你眼中，駕駛員究竟是什麼？", "0", "0", "0", "cv_zhinvxing_38", "0", "0"},
[414136] = {414136, 11041, 39, 31, "0", "0", "Can\u{0020}I\u{0020}try\u{0020}out\u{0020}all\u{0020}this\u{0020}equipment?", "0", "這些裝備都可以試用？", "0", "0", "0", "cv_zhinvxing_39", "0", "0"},
[414137] = {414137, 11041, 40, 32, "0", "0", "No\u{0020}wonder\u{0020}it's\u{0020}AEGIS—the\u{0020}employee\u{0020}discounts\u{0020}are\u{0020}incredible.", "0", "不愧是艾吉斯，員工價的折扣就是大。", "0", "0", "0", "cv_zhinvxing_40", "0", "0"},
[414138] = {414138, 11041, 41, 33, "0", "0", "You've\u{0020}got\u{0020}quite\u{0020}the\u{0020}collection\u{0020}of\u{0020}medals.", "0", "獎章不少嘛你。", "0", "0", "0", "cv_zhinvxing_41", "0", "0"},
[414139] = {414139, 11041, 42, 34, "0", "0", "This\u{0020}plugin's\u{0020}silent\u{0020}mode\u{0020}is\u{0020}really\u{0020}something.", "0", "這插件的靜音效果不錯啊。", "0", "0", "0", "cv_zhinvxing_42", "0", "0"},
[414140] = {414140, 11041, 43, 35, "0", "0", "Another\u{0020}official\u{0020}duty?\u{0020}You\u{0020}sure\u{0020}keep\u{0020}busy.", "0", "又是公事？你可真是有夠忙的。", "0", "0", "0", "cv_zhinvxing_43", "0", "0"},
[414141] = {414141, 11041, 44, 36, "0", "0", "Anonymous\u{0020}chats,\u{0020}huh...\u{0020}Just\u{0020}be\u{0020}careful\u{0020}not\u{0020}to\u{0020}give\u{0020}away\u{0020}too\u{0020}much\u{0020}personal\u{0020}info.", "0", "匿名聊天啊……你最好小心一點，別透露自己的個人隱私。", "0", "0", "0", "cv_zhinvxing_44", "0", "0"},
[414142] = {414142, 11041, 45, 37, "0", "0", "What\u{0020}kind\u{0020}of\u{0020}high-tech\u{0020}system\u{0020}is\u{0020}this?", "0", "這是什麼高科技？", "0", "0", "0", "cv_zhinvxing_45", "0", "0"},
[414200] = {414200, 11042, 1, 1, "0", "0", "Haze\u{0020}reverb!", "0", "蒼霧殘響！", "0", "0", "0", "cv_hailuo_1", "0", "0"},
[414201] = {414201, 11042, 2, 2, "0", "0", "I'm\u{0020}here!\u{0020}You\u{0020}can\u{0020}count\u{0020}on\u{0020}me.\u{0020}I\u{0020}won't\u{0020}make\u{0020}any\u{0020}mistakes,\u{0020}hehe.", "0", "我來啦！把事情都交給我吧，絕對不會出錯的，嘿嘿。", "0", "0", "0", "cv_hailuo_2", "0", "0"},
[414202] = {414202, 11042, 3, 3, "0", "0", "I'm\u{0020}Kyla,\u{0020}your\u{0020}frontline\u{0020}fighter!\u{0020}My\u{0020}full\u{0020}name\u{0020}is\u{0020}Kyla\u{0020}Tria@#￥%...\u{0020}Gah,\u{0020}I\u{0020}can't\u{0020}recall\u{0020}it…\u{0020}Just\u{0020}call\u{0020}me\u{0020}Kyla!", "0", "我是前線的海蘿！海蘿·特裡亞@#￥%……記不得啦，總之叫我海蘿就好！", "0", "0", "0", "cv_hailuo_3", "0", "0"},
[414203] = {414203, 11042, 4, 4, "0", "idle", "When\u{0020}feeling\u{0020}down,\u{0020}just\u{0020}go\u{0020}for\u{0020}a\u{0020}run!\u{0020}Sunlight\u{0020}on\u{0020}your\u{0020}body,\u{0020}wind\u{0020}on\u{0020}your\u{0020}face,\u{0020}and\u{0020}you'll\u{0020}forget\u{0020}all\u{0020}your\u{0020}worries!", "0", "不開心的時候只要去跑步就好了！陽光照在身上，風打在臉上，什麼煩惱都會忘了！", "0", "0", "0", "cv_hailuo_4", "0", "0"},
[414204] = {414204, 11042, 5, 4, "0", "idle", "This\u{0020}is\u{0020}what\u{0020}we\u{0020}need\u{0020}to\u{0020}do\u{0020}today...\u{0020}This\u{0020}is\u{0020}what\u{0020}we\u{0020}need\u{0020}to\u{0020}do\u{0020}tomorrow...\u{0020}OK,\u{0020}I've\u{0020}written\u{0020}it\u{0020}all\u{0020}down...\u{0020}Hmm,\u{0020}by\u{0020}the\u{0020}way,\u{0020}what\u{0020}day\u{0020}is\u{0020}it\u{0020}today...\u{0020}Ah!\u{0020}I\u{0020}missed\u{0020}everything!", "0", "這是今天要做的事情……這是明天要做的事情……OK，已經全部記下來了……嗯，話說今天是幾號……啊！這不是全部錯過了嗎！", "0", "0", "0", "cv_hailuo_5", "0", "0"},
[414205] = {414205, 11042, 6, 4, "0", "idle", "Starry...\u{0020}she\u{0020}really\u{0020}worries\u{0020}me...\u{0020}Oh,\u{0020}I'm\u{0020}not\u{0020}talking\u{0020}about\u{0020}her\u{0020}appearance,\u{0020}it's\u{0020}her\u{0020}mental\u{0020}state.\u{0020}It\u{0020}feels\u{0020}like\u{0020}she\u{0020}could\u{0020}explode\u{0020}at\u{0020}any\u{0020}moment...\u{0020}Bang!\u{0020}Splat!\u{0020}I'm\u{0020}really\u{0020}worried\u{0020}about\u{0020}her.", "0", "星爍……她那樣子真讓人擔心……啊，我不是說她的外表，是說她的精神狀態，總感覺她好像隨時都會爆炸一樣……彭！啪嗒！我很擔心她。", "0", "0", "0", "cv_hailuo_6", "0", "0"},
[414206] = {414206, 11042, 7, 5, "1_》_0_0.8", "level1", "I\u{0020}don't\u{0020}have\u{0020}anything\u{0020}I\u{0020}want\u{0020}to\u{0020}achieve.\u{0020}Even\u{0020}if\u{0020}I\u{0020}did,\u{0020}I'd\u{0020}probably\u{0020}forget\u{0020}it\u{0020}soon.\u{0020}But\u{0020}I'll\u{0020}work\u{0020}hard\u{0020}to\u{0020}help\u{0020}others\u{0020}achieve\u{0020}their\u{0020}dreams,\u{0020}and\u{0020}I\u{0020}don't\u{0020}mind\u{0020}fighting\u{0020}for\u{0020}that\u{0020}as\u{0020}long\u{0020}as\u{0020}it\u{0020}takes!", "0", "我沒有想要實現的事情，就算有也肯定很快就忘記吧，但是我會努力幫其他人實現夢想的，為此就算一直戰鬥下去也沒關係！", "0", "0", "0", "cv_hailuo_7", "0", "0"},
[414207] = {414207, 11042, 8, 5, "1_》_0_0.8", "level1", "Navigator,\u{0020}important\u{0020}promises\u{0020}should\u{0020}be\u{0020}written\u{0020}down\u{0020}because\u{0020}human\u{0020}memory\u{0020}is\u{0020}unreliable!", "0", "領航，重要的約定一定要寫在紙上，因為人的記憶是不可靠的！", "0", "0", "0", "cv_hailuo_8", "0", "0"},
[414208] = {414208, 11042, 9, 5, "1_》_100_1.5", "level2", "It\u{0020}doesn't\u{0020}matter\u{0020}if\u{0020}I\u{0020}can't\u{0020}remember\u{0020}the\u{0020}names\u{0020}of\u{0020}important\u{0020}people\u{0020}because\u{0020}the\u{0020}feelings\u{0020}and\u{0020}memories\u{0020}will\u{0020}always\u{0020}remain\u{0020}in\u{0020}our\u{0020}hearts,\u{0020}mine\u{0020}and\u{0020}yours,\u{0020}Navigator!", "0", "即使記不住重要的人的名字也沒關係，因為那份感情和回憶一直會存在我和領航的心裡的！", "0", "0", "0", "cv_hailuo_9", "0", "0"},
[414209] = {414209, 11042, 10, 5, "1_》_500_2", "level3", "Have\u{0020}you\u{0020}ever\u{0020}lost\u{0020}your\u{0020}memory,\u{0020}Navigator?\u{0020}I\u{0020}understand\u{0020}that\u{0020}feeling—it's\u{0020}awful\u{0020}not\u{0020}to\u{0020}remember\u{0020}important\u{0020}things.\u{0020}But\u{0020}as\u{0020}long\u{0020}as\u{0020}we're\u{0020}alive,\u{0020}moving\u{0020}toward\u{0020}the\u{0020}future,\u{0020}we'll\u{0020}eventually\u{0020}recover\u{0020}what\u{0020}we've\u{0020}forgotten!", "0", "領航也失憶過嗎？我懂的我懂的，那種想不起來重要事情的感覺特別難受吧。不過只要我們還活著，還能向著未來前進，我們總能找回當初忘掉的事情的！", "0", "0", "0", "cv_hailuo_10", "0", "0"},
[414210] = {414210, 11042, 11, 5, "1_》_1000_2.5", "level4", "As\u{0020}a\u{0020}fellow\u{0020}forgetful\u{0020}person,\u{0020}Navigator,\u{0020}if\u{0020}you\u{0020}ever\u{0020}have\u{0020}any\u{0020}troubles,\u{0020}feel\u{0020}free\u{0020}to\u{0020}talk\u{0020}to\u{0020}me.\u{0020}I'll\u{0020}always\u{0020}be\u{0020}there\u{0020}for\u{0020}you,\u{0020}even\u{0020}when\u{0020}I'm\u{0020}asleep!\u{0020}Even\u{0020}in\u{0020}the\u{0020}bath...\u{0020}I\u{0020}don't\u{0020}mind!", "0", "哼哼，作為記性不好的病友，領航要是遇到了什麼困擾就儘管和我傾訴吧，我不管什麼時候都會陪伴你在身邊的，就算是睡覺時候也會的！洗澡的時候……我不介意！", "0", "0", "0", "cv_hailuo_11", "0", "0"},
[414211] = {414211, 11042, 12, 6, "0", "0", "That\u{0020}cost\u{0020}a\u{0020}fortune!", "0", "花了好多錢！", "0", "0", "0", "cv_hailuo_12", "0", "0"},
