[414232] = {414232, 11042, 34, 26, "0", "0", "Oh,\u{0020}Navigator,\u{0020}you're\u{0020}here!\u{0020}Want\u{0020}to\u{0020}sunbathe\u{0020}together?\u{0020}The\u{0020}sunlight\u{0020}today\u{0020}is\u{0020}perfect.", "0", "噢，領航，你來啦，要一起曬太陽嗎？今天的太陽光可是完美陽光哦。", "0", "0", "0", "cv_hailuo_34", "0", "0"},
[414233] = {414233, 11042, 35, 27, "0", "0", "Where\u{0020}are\u{0020}we\u{0020}headed\u{0020}today?\u{0020}Uh,\u{0020}what\u{0020}are\u{0020}we\u{0020}doing?", "0", "今天要去的地方是……哪裡來著？對了，我們要做什麼？", "0", "0", "0", "cv_hailuo_35", "0", "0"},
[414234] = {414234, 11042, 36, 28, "0", "0", "As\u{0020}long\u{0020}as\u{0020}I\u{0020}don't\u{0020}have\u{0020}to\u{0020}remember\u{0020}anything,\u{0020}I\u{0020}won't\u{0020}lose\u{0020}to\u{0020}anyone!", "0", "只要不用記東西的話，我誰都不會輸的！", "0", "0", "0", "cv_hailuo_36", "0", "0"},
[414235] = {414235, 11042, 37, 29, "0", "0", "Wah\u{0020}wah\u{0020}wah,\u{0020}there\u{0020}are\u{0020}so\u{0020}many\u{0020}people!\u{0020}I\u{0020}can't\u{0020}keep\u{0020}track\u{0020}of\u{0020}all\u{0020}their\u{0020}names...", "0", "哇哇哇，好多人，我記不住名字的啦……", "0", "0", "0", "cv_hailuo_37", "0", "0"},
[414236] = {414236, 11042, 38, 30, "0", "0", "Newcomer?\u{0020}Does\u{0020}that\u{0020}mean\u{0020}I'll\u{0020}be\u{0020}a\u{0020}senior\u{0020}now?", "0", "新人？我要當前輩了？", "0", "0", "0", "cv_hailuo_38", "0", "0"},
