[414323] = {414323, 11043, 25, 18, "0", "0", "Please\u{0020}listen\u{0020}closely\u{0020}to\u{0020}the\u{0020}voice\u{0020}that\u{0020}resonates\u{0020}with\u{0020}the\u{0020}heavens.", "0", "讓天空也為之共鳴的聲音，還請洗耳恭聽。", "0", "0", "0", "cv_mila_24", "0", "0"},
