[414325] = {414325, 11043, 27, 20, "0", "0", "I'd\u{0020}love\u{0020}to\u{0020}collaborate\u{0020}with\u{0020}AEGIS\u{0020}on\u{0020}a\u{0020}church-themed\u{0020}maintenance\u{0020}pool.", "0", "真想和艾吉斯合作，推出教會主題的維護池啊。", "0", "0", "0", "cv_mila_27", "0", "0"},
[414326] = {414326, 11043, 28, 21, "0", "0", "During\u{0020}baptism,\u{0020}keeping\u{0020}silent—is\u{0020}it\u{0020}for\u{0020}inward\u{0020}prayer?", "0", "洗禮時保持靜默，是在內心進行祈禱嗎？", "0", "0", "0", "cv_mila_28", "0", "0"},
[414327] = {414327, 11043, 29, 21, "0", "0", "Are\u{0020}you\u{0020}tired,\u{0020}Navigator?\u{0020}If\u{0020}you\u{0020}can't\u{0020}handle\u{0020}this\u{0020}level,\u{0020}there's\u{0020}no\u{0020}way\u{0020}you'll\u{0020}overcome\u{0020}the\u{0020}thousands\u{0020}of\u{0020}hardships\u{0020}ahead.", "0", "領航累了嗎？這種程度就不行的話，可沒法跨越萬千苦難哦。", "0", "0", "0", "cv_mila_29", "0", "0"},
[414328] = {414328, 11043, 30, 22, "0", "0", "I'm\u{0020}really\u{0020}looking\u{0020}forward\u{0020}to\u{0020}it.", "0", "真期待呢。", "0", "0", "0", "cv_mila_30", "0", "0"},
