[414332] = {414332, 11043, 34, 26, "0", "0", "\"No\u{0020}one\u{0020}steps\u{0020}into\u{0020}the\u{0020}same\u{0020}river\u{0020}twice,\"\u{0020}but\u{0020}is\u{0020}the\u{0020}Navigator\u{0020}I\u{0020}see\u{0020}now\u{0020}the\u{0020}same\u{0020}as\u{0020}yesterday?\u{0020}Hmm...\u{0020}you\u{0020}seem\u{0020}to\u{0020}be\u{0020}in\u{0020}better\u{0020}shape.\u{0020}Looks\u{0020}like\u{0020}you're\u{0020}different\u{0020}after\u{0020}all.", "0", "“人不會兩次踏入同一條河流”，而我現在所見到的領航是否與昨天一樣？嗯……狀態似乎更好了些，看來的確不同呢。", "0", "0", "0", "cv_mila_34", "0", "0"},
[414333] = {414333, 11043, 35, 27, "0", "0", "Bringing\u{0020}the\u{0020}gospel\u{0020}together.", "0", "一起帶去福音。", "0", "0", "0", "cv_mila_35", "0", "0"},
[414334] = {414334, 11043, 36, 28, "0", "0", "Not\u{0020}a\u{0020}bad\u{0020}choice.", "0", "也是不錯的選擇。", "0", "0", "0", "cv_mila_36", "0", "0"},
