[414337] = {414337, 11043, 39, 31, "0", "0", "I\u{0020}will\u{0020}give\u{0020}them\u{0020}my\u{0020}blessing.", "0", "我會為其賜予祝福。", "0", "0", "0", "cv_mila_39", "0", "0"},
