[414401] = {414401, 11044, 2, 2, "0", "0", "Ugh!\u{0020}My\u{0020}turn\u{0020}already?\u{0020}Hello...", "0", "呃，今天輪到我了嗎？請多指教……", "0", "0", "0", "cv_hein_2", "0", "0"},
[414402] = {414402, 11044, 3, 3, "0", "0", "I'm\u{0020}Heine,\u{0020}a\u{0020}new\u{0020}Driver...\u{0020}Well,\u{0020}I\u{0020}suppose\u{0020}that's\u{0020}enough\u{0020}for\u{0020}introductions.\u{0020}You\u{0020}already\u{0020}know\u{0020}me,\u{0020}don't\u{0020}you,\u{0020}Navigator?\u{0020}I\u{0020}prefer\u{0020}actions\u{0020}and\u{0020}painting\u{0020}over\u{0020}words.", "0", "我是海因，一名新人駕駛員……那麼，自我介紹就到此為止吧，領航早已了解我了不是嗎？我更愛用行動與繪畫代替言語。", "0", "0", "0", "cv_hein_3", "0", "0"},
[414403] = {414403, 11044, 4, 4, "0", "idle", "From\u{0020}this\u{0020}height,\u{0020}I\u{0020}can\u{0020}see\u{0020}different\u{0020}scenery.\u{0020}Since\u{0020}I'm\u{0020}here\u{0020}anyway,\u{0020}I'd\u{0020}really\u{0020}like\u{0020}to\u{0020}do\u{0020}some\u{0020}sketching.", "0", "以這種高度，可以看到與平常不一樣的風景。反正站著也是站著，真想順便寫寫生啊。", "0", "0", "0", "cv_hein_4", "0", "0"},
[414404] = {414404, 11044, 5, 4, "0", "idle2", "At\u{0020}the\u{0020}research\u{0020}institute,\u{0020}I\u{0020}usually\u{0020}spend\u{0020}my\u{0020}time\u{0020}alone\u{0020}in\u{0020}silence.\u{0020}However,\u{0020}sharing\u{0020}a\u{0020}comfortable\u{0020}silence\u{0020}like\u{0020}this\u{0020}with\u{0020}you...\u{0020}is\u{0020}rather\u{0020}agreeable.", "0", "在研究所裡，我通常獨自一人靜靜待著。不過像現在這樣兩個人一起相視無言，倒也不錯呢。", "0", "0", "0", "cv_hein_5", "0", "0"},
[414405] = {414405, 11044, 6, 4, "0", "idle3", "Shisha\u{0020}won't\u{0020}stop\u{0020}pestering\u{0020}me\u{0020}to\u{0020}work\u{0020}out\u{0020}with\u{0020}her.\u{0020}She\u{0020}even\u{0020}says\u{0020}it'll\u{0020}\"help\u{0020}me\u{0020}grow.\"\u{0020}This\u{0020}is\u{0020}basically\u{0020}workplace\u{0020}bullying...\u{0020}Are\u{0020}you\u{0020}allowing\u{0020}it,\u{0020}Navigator?\u{0020}...Huh?\u{0020}You\u{0020}agree\u{0020}with\u{0020}her?", "0", "希夏說什麼也要拉我去健身，甚至還表示這有助於發育，完全演變成職場騷擾了吧……領航不管管她嗎？欸？你也讚同她的想法？", "0", "0", "0", "cv_hein_6", "0", "0"},
[414406] = {414406, 11044, 7, 5, "1_》_0_0.8", "level1", "The\u{0020}more\u{0020}I\u{0020}learn,\u{0020}the\u{0020}less\u{0020}I\u{0020}know.\u{0020}What\u{0020}faith\u{0020}cannot\u{0020}secure,\u{0020}ideology\u{0020}cannot\u{0020}alter,\u{0020}and\u{0020}art\u{0020}cannot\u{0020}depict...\u{0020}only\u{0020}actions\u{0020}can\u{0020}address.", "0", "掌握的學識越豐富，我就越是能感到自己的無力。信仰無法換取的、思想無法撼動的、藝術無法觸及的，只有行動。", "0", "0", "0", "cv_hein_7", "0", "0"},
[414407] = {414407, 11044, 8, 5, "1_》_0_0.8", "level1", "This\u{0020}staff?\u{0020}It's\u{0020}the\u{0020}AVG\u{0020}I\u{0020}designed\u{0020}myself.\u{0020}The\u{0020}staff's\u{0020}head\u{0020}is\u{0020}inspired\u{0020}by\u{0020}a\u{0020}painter's\u{0020}palette;\u{0020}it\u{0020}can\u{0020}alter\u{0020}the\u{0020}nature\u{0020}of\u{0020}Nimbus\u{0020}energy\u{0020}through\u{0020}\"color\u{0020}mixing.\"\u{0020}The\u{0020}handle\u{0020}itself\u{0020}functions\u{0020}as\u{0020}a\u{0020}tech-pen.", "0", "這根法杖？是我自己設計的AVG武裝哦。杖頭部分概念為調色盤，可以通過“調色”來改變尼姆比斯能的性質，杖柄則是一根科技筆。", "0", "0", "0", "cv_hein_8", "0", "0"},
[414408] = {414408, 11044, 9, 5, "1_》_100_1.5", "level2", "Hanging\u{0020}out\u{0020}after\u{0020}work?\u{0020}Okay.\u{0020}But\u{0020}I'm\u{0020}remarkably\u{0020}unathletic.\u{0020}Nothing\u{0020}too\u{0020}crazy.\u{0020}Maybe\u{0020}the\u{0020}aquarium?\u{0020}Or\u{0020}the\u{0020}planetarium?", "0", "下班後一起出去玩？可以啊。不過我毫無運動細胞，就別考慮什麼過於刺激的活動了，水族館或天文館之類的怎麼樣？", "0", "0", "0", "cv_hein_9", "0", "0"},
[414409] = {414409, 11044, 10, 5, "1_》_500_2", "level3", "I\u{0020}know\u{0020}you\u{0020}mean\u{0020}no\u{0020}harm,\u{0020}but\u{0020}this\u{0020}physical\u{0020}contact\u{0020}still\u{0020}leaves\u{0020}me\u{0020}feeling...\u{0020}unsettled.\u{0020}I\u{0020}can\u{0020}no\u{0020}longer\u{0020}distinguish\u{0020}if\u{0020}it's\u{0020}pleasant\u{0020}or\u{0020}not...\u{0020}This\u{0020}is\u{0020}probably\u{0020}my\u{0020}fault.\u{0020}What's\u{0020}even\u{0020}in\u{0020}my\u{0020}head?", "0", "明知道你不是壞人，但這種肌膚接觸還是讓我有些……唔，已經分不清是喜歡還是討厭了……雖然可能這是我的問題啦，我腦子裡到底裝著些什麼？", "0", "0", "0", "cv_hein_10", "0", "0"},
[414410] = {414410, 11044, 11, 5, "1_》_1000_2.5", "level4", "I\u{0020}used\u{0020}to\u{0020}only\u{0020}paint\u{0020}scenery.\u{0020}But\u{0020}it's\u{0020}started\u{0020}feeling\u{0020}a\u{0020}little...\u{0020}lonely.\u{0020}If\u{0020}I\u{0020}want\u{0020}to\u{0020}get\u{0020}better,\u{0020}to\u{0020}see\u{0020}new\u{0020}things...\u{0020}Navigator,\u{0020}will\u{0020}you\u{0020}be\u{0020}my\u{0020}model?", "0", "此前我獨愛於畫景，最近卻感到只是這樣總有些寂寞……如果我想抵達新的領域，想見識新的景色，領航，能否請你成為我的模特呢？", "0", "0", "0", "cv_hein_11", "0", "0"},
