[414501] = {414501, 11045, 2, 2, "0", "0", "As\u{0020}long\u{0020}as\u{0020}I\u{0020}stay\u{0020}here...\u{0020}we\u{0020}can\u{0020}stay\u{0020}connected\u{0020}like\u{0020}this?", "0", "只要呆在这里，就能和你保持通感？", "0", "0", "0", "cv_feilier_2", "0", "0"},
[414502] = {414502, 11045, 3, 3, "0", "0", "You're\u{0020}the\u{0020}Navigator\u{0020}from\u{0020}Danube?\u{0020}You're\u{0020}so\u{0020}tiny...\u{0020}Allow\u{0020}me\u{0020}to\u{0020}introduce\u{0020}myself.\u{0020}Daybreak,\u{0020}Verir,\u{0020}B17,\u{0020}the\u{0020}only\u{0020}failed\u{0020}subject\u{0020}from\u{0020}Group\u{0020}B\u{0020}who\u{0020}made\u{0020}it\u{0020}out\u{0020}alive.\u{0020}I'll\u{0020}be\u{0020}counting\u{0020}on\u{0020}you\u{0020}for\u{0020}the\u{0020}Synesthesia\u{0020}therapy.", "0", "你就是多瑙的领航？好小一只啊……先自我介绍一下。晨曦，吠黎尔，B17，是B组唯一幸存下来的失败品。通感治疗，就拜托你了。", "0", "0", "0", "cv_feilier_1", "0", "0"},
[414503] = {414503, 11045, 4, 4, "0", "idle", "Every\u{0020}time\u{0020}we\u{0020}link,\u{0020}I\u{0020}feel...\u{0020}light.\u{0020}Like\u{0020}I'm\u{0020}floating.\u{0020}It's\u{0020}pleasant.", "0", "每次连上通感，感觉整个人都飘飘然的，好舒服……", "0", "0", "0", "cv_feilier_3", "0", "0"},
[414504] = {414504, 11045, 5, 4, "0", "idle", "Uh\u{0020}oh.\u{0020}I\u{0020}think\u{0020}I'm\u{0020}getting\u{0020}addicted\u{0020}to\u{0020}this.", "0", "……糟糕，有点上瘾欸。", "0", "0", "0", "cv_feilier_4", "0", "0"},
[414505] = {414505, 11045, 6, 4, "0", "idle", "Huh?\u{0020}The\u{0020}link\u{0020}got\u{0020}cut\u{0020}off?", "0", "咦？通感怎么断了？", "0", "0", "0", "cv_feilier_5", "0", "0"},
[414506] = {414506, 11045, 7, 5, "1_》_0_0.8", "level1", "When\u{0020}I'm\u{0020}de-gigantified,\u{0020}don't\u{0020}touch\u{0020}me\u{0020}like\u{0020}that\u{0020}again.\u{0020}I\u{0020}can't\u{0020}guarantee\u{0020}I...\u{0020}won't\u{0020}harm\u{0020}you\u{0020}by\u{0020}accident.", "0", "等解除巨大化了，可不要再这么触碰我。我不确定，那时候的自己……会不会伤到你。", "0", "0", "0", "cv_feilier_6", "0", "0"},
[414507] = {414507, 11045, 8, 5, "1_》_0_0.8", "level1", "Don't\u{0020}worry.\u{0020}I\u{0020}can\u{0020}regulate\u{0020}myself\u{0020}now.", "0", "请放心，现在我能控制住自己的。", "0", "0", "0", "cv_feilier_7", "0", "0"},
[414508] = {414508, 11045, 9, 5, "1_》_100_1.5", "level2", "Clothes?\u{0020}It's\u{0020}irrelevant.\u{0020}Just\u{0020}fabric.", "0", "衣服？无所谓，就让它破着吧。反正也不过是层布而已。", "0", "0", "0", "cv_feilier_8", "0", "0"},
[414509] = {414509, 11045, 10, 5, "1_》_500_2", "level3", "Return\u{0020}to\u{0020}Inca?\u{0020}Why?\u{0020}I'm\u{0020}from\u{0020}Danube.\u{0020}If\u{0020}I\u{0020}were\u{0020}to\u{0020}return\u{0020}anywhere...\u{0020}it\u{0020}would\u{0020}be\u{0020}Danube.", "0", "回印加？为什么？我可是知道的，我是多瑙人，要回也是回多瑙才对。", "0", "0", "0", "cv_feilier_9", "0", "0"},
[414510] = {414510, 11045, 11, 5, "1_》_1000_2.5", "level4", "As\u{0020}long\u{0020}as\u{0020}we\u{0020}stay\u{0020}together,\u{0020}we\u{0020}can\u{0020}keep\u{0020}the\u{0020}link\u{0020}going...\u{0020}forever.", "0", "只要一直在一起，就能一直保持通感……永远不断开……", "0", "0", "0", "cv_feilier_10", "0", "0"},
[414511] = {414511, 11045, 12, 6, "0", "0", "I'll\u{0020}follow\u{0020}your\u{0020}lead.", "0", "听你的。", "0", "0", "0", "cv_feilier_11", "0", "0"},
[414512] = {414512, 11045, 13, 7, "0", "0", "Whatever\u{0020}you\u{0020}say.", "0", "都听你的。", "0", "0", "0", "cv_feilier_12", "0", "0"},
[414513] = {414513, 11045, 14, 8, "0", "0", "At\u{0020}this\u{0020}rate,\u{0020}maybe\u{0020}soon\u{0020}I'll\u{0020}be\u{0020}able\u{0020}to\u{0020}maintain\u{0020}awareness\u{0020}and\u{0020}talk\u{0020}to\u{0020}you\u{0020}even\u{0020}without\u{0020}the\u{0020}Transformation\u{0020}Core.\u{0020}I\u{0020}can't\u{0020}wait\u{0020}for\u{0020}that\u{0020}day\u{0020}to\u{0020}come.", "0", "照这个趋势，或许不久后，即便没有连接幻化核心，我也能保持意志，与你正常交流？真期待那一天的到来呀。", "0", "0", "0", "cv_feilier_13", "0", "0"},
[414514] = {414514, 11045, 15, 9, "0", "0", "Careful,\u{0020}these\u{0020}claws\u{0020}are\u{0020}sharper\u{0020}than\u{0020}they\u{0020}look.", "0", "小心，这爪子还挺利的。", "0", "0", "0", "cv_feilier_14", "0", "0"},
[414515] = {414515, 11045, 16, 10, "0", "0", "Don't\u{0020}forget\u{0020}to\u{0020}re-establish\u{0020}the\u{0020}link.", "0", "别忘了搭建通感。", "0", "0", "0", "cv_feilier_15", "0", "0"},
