[414518] = {414518, 11045, 19, 13, "0", "0", "My\u{0020}bandages\u{0020}are\u{0020}clean.\u{0020}Want\u{0020}some?", "0", "手上的绷带，不脏，分你一些？", "0", "0", "0", "cv_feilier_18", "0", "0"},
[414519] = {414519, 11045, 20, 14, "0", "0", "Don't\u{0020}be\u{0020}angry\u{0020}or\u{0020}sad...\u{0020}How\u{0020}about\u{0020}I\u{0020}go\u{0020}beat\u{0020}them\u{0020}up\u{0020}again?\u{0020}Would\u{0020}that\u{0020}cheer\u{0020}you\u{0020}up?", "0", "不要生气，不要沮丧……我再去和它们打一架，你会不会开心些？", "0", "0", "0", "cv_feilier_19", "0", "0"},
