[414529] = {414529, 11045, 31, 23, "0", "0", "Don't\u{0020}ask\u{0020}what\u{0020}you\u{0020}already\u{0020}know.", "0", "不要明知故问呐。", "0", "0", "0", "cv_feilier_29", "0", "0"},
[414530] = {414530, 11045, 32, 24, "0", "0", "Talking\u{0020}to\u{0020}yourself\u{0020}is\u{0020}fun,\u{0020}huh?\u{0020}Then\u{0020}I'll\u{0020}try\u{0020}it\u{0020}too.\u{0020}Guess\u{0020}who\u{0020}I\u{0020}am?", "0", "自问自答很有意思么……那我也要来。猜猜我是谁？", "0", "0", "0", "cv_feilier_30", "0", "0"},
[414531] = {414531, 11045, 33, 25, "0", "0", "Who's\u{0020}that?", "0", "……那个人是谁？", "0", "0", "0", "cv_feilier_31", "0", "0"},
[414532] = {414532, 11045, 34, 26, "0", "0", "Finally,\u{0020}you're\u{0020}back...\u{0020}Never\u{0020}mind\u{0020}everything\u{0020}else.\u{0020}Let's\u{0020}reconnect\u{0020}the\u{0020}link\u{0020}first.\u{0020}Hurry,\u{0020}I'm\u{0020}ready.", "0", "终于回来了……其他的不急，先重新连上通感吧。快点，我已经准备好了。", "0", "0", "0", "cv_feilier_32", "0", "0"},
[414533] = {414533, 11045, 35, 27, "0", "0", "Fine.\u{0020}During\u{0020}the\u{0020}treatment,\u{0020}I'm\u{0020}supposed\u{0020}to\u{0020}keep\u{0020}you\u{0020}safe,\u{0020}after\u{0020}all.", "0", "好吧。治疗期间，我确实得保护你的人身安全呢。", "0", "0", "0", "cv_feilier_34", "0", "0"},
[414534] = {414534, 11045, 36, 28, "0", "0", "Do\u{0020}people\u{0020}here\u{0020}solve\u{0020}things\u{0020}with\u{0020}their\u{0020}fists\u{0020}too?", "0", "这里也是靠拳头说话么。", "0", "0", "0", "cv_feilier_35", "0", "0"},
[414535] = {414535, 11045, 37, 29, "0", "0", "So\u{0020}many\u{0020}people...", "0", "好多的人……", "0", "0", "0", "cv_feilier_36", "0", "0"},
[414536] = {414536, 11045, 38, 30, "0", "0", "With\u{0020}me\u{0020}present,\u{0020}that's\u{0020}sufficient.", "0", "这里有我就够了。", "0", "0", "0", "cv_feilier_37", "0", "0"},
[414537] = {414537, 11045, 39, 31, "0", "0", "Those\u{0020}weapons...\u{0020}they\u{0020}look\u{0020}like\u{0020}they'd\u{0020}really\u{0020}hurt\u{0020}if\u{0020}they\u{0020}hit.", "0", "这些装备……如果被它们打，一定很痛……", "0", "0", "0", "cv_feilier_38", "0", "0"},
[414538] = {414538, 11045, 40, 32, "0", "0", "I\u{0020}can\u{0020}help\u{0020}carry\u{0020}stuff.\u{0020}I'm\u{0020}strong.", "0", "我可以帮忙搬东西。我力气很大的。", "0", "0", "0", "cv_feilier_39", "0", "0"},
[414539] = {414539, 11045, 41, 33, "0", "0", "Even\u{0020}after\u{0020}the\u{0020}therapy\u{0020}ends,\u{0020}I\u{0020}can\u{0020}still\u{0020}stay\u{0020}here...\u{0020}right?", "0", "就算疗程结束，我也是可以继续呆在这里的吧？", "0", "0", "0", "cv_feilier_40", "0", "0"},
[414540] = {414540, 11045, 42, 34, "0", "0", "Need\u{0020}me\u{0020}to\u{0020}speak\u{0020}louder?\u{0020}Or\u{0020}softer?", "0", "需要我更大声说话？还是再小声一点？", "0", "0", "0", "cv_feilier_41", "0", "0"},
