[414700] = {414700, 11047, 1, 1, "0", "0", "Haze\u{0020}Reverb", "0", "蒼霧殘響", "0", "0", "0", "cv_dangyangtu_1", "0", "0"},
[414701] = {414701, 11047, 2, 2, "0", "0", "Huh?\u{0020}This\u{0020}isn't\u{0020}some\u{0020}kind\u{0020}of\u{0020}prank\u{0020}show,\u{0020}is\u{0020}it?", "0", "欸？真的不是什麼整人綜藝節目？", "0", "0", "0", "cv_dangyangtu_2", "0", "0"},
[414702] = {414702, 11047, 3, 3, "0", "0", "This\u{0020}is\u{0020}TeleRabbit,\u{0020}an\u{0020}idol\u{0020}active\u{0020}in\u{0020}the\u{0020}online\u{0020}world~\u{0020}Are\u{0020}you\u{0020}my\u{0020}Producer?\u{0020}Even\u{0020}though\u{0020}this\u{0020}isn't\u{0020}our\u{0020}first\u{0020}meeting,\u{0020}I'll\u{0020}be\u{0020}in\u{0020}your\u{0020}care\u{0020}from\u{0020}now\u{0020}on!", "0", "這裡是蕩漾兔，一名活躍在網絡世界的偶像~你就是我的製作人嗎？雖然並非初次見面，以後請多指教咯！", "0", "0", "0", "cv_dangyangtu_3", "0", "0"},
[414703] = {414703, 11047, 4, 4, "0", "idle", "If\u{0020}the\u{0020}city\u{0020}were\u{0020}a\u{0020}gigantic\u{0020}concert\u{0020}hall,\u{0020}then\u{0020}Danube\u{0020}would\u{0020}be\u{0020}a\u{0020}packed\u{0020}house.\u{0020}It'd\u{0020}be\u{0020}a\u{0020}waste\u{0020}not\u{0020}to\u{0020}sing\u{0020}at\u{0020}the\u{0020}top\u{0020}of\u{0020}my\u{0020}lungs.", "0", "如果將城市視為一座巨大的演唱會場館，那麼多瑙可謂是座無虛席，不放聲唱首歌真有些浪費呢。", "0", "0", "0", "cv_dangyangtu_4", "0", "0"},
[414704] = {414704, 11047, 5, 4, "0", "idle", "What's\u{0020}wrong,\u{0020}what's\u{0020}wrong?\u{0020}You\u{0020}suddenly\u{0020}look\u{0020}so\u{0020}lifeless.\u{0020}As\u{0020}my\u{0020}Producer\u{0020}and\u{0020}my\u{0020}fan,\u{0020}if\u{0020}you\u{0020}don't\u{0020}stay\u{0020}energetic,\u{0020}I'll\u{0020}be\u{0020}really\u{0020}sad!", "0", "怎麼啦怎麼啦？突然間這麼死氣沉沉的，作為我的製作人兼粉絲，不時刻保持活力的話可是會讓我很傷心的！", "0", "0", "0", "cv_dangyangtu_5", "0", "0"},
[414705] = {414705, 11047, 6, 4, "0", "idle", "There\u{0020}are\u{0020}always\u{0020}people\u{0020}in\u{0020}the\u{0020}squad\u{0020}trying\u{0020}to\u{0020}dig\u{0020}up\u{0020}my\u{0020}real\u{0020}identity,\u{0020}it's\u{0020}such\u{0020}a\u{0020}headache.\u{0020}Once\u{0020}you\u{0020}tear\u{0020}away\u{0020}that\u{0020}veil\u{0020}between\u{0020}truth\u{0020}and\u{0020}fiction,\u{0020}a\u{0020}lot\u{0020}of\u{0020}things\u{0020}just\u{0020}won't\u{0020}be\u{0020}fun\u{0020}anymore.", "0", "小隊裡老有人想揪出我的真實身份，實在是傷腦筋啊，戳破了真實與虛假之間的這層面紗，許多事可就會沒有意思了。", "0", "0", "0", "cv_dangyangtu_6", "0", "0"},
[414706] = {414706, 11047, 7, 5, "1_》_0_0.8", "level1", "Using\u{0020}this\u{0020}body\u{0020}manifested\u{0020}through\u{0020}Nimbus\u{0020}is\u{0020}definitely\u{0020}easier\u{0020}to\u{0020}control,\u{0020}but\u{0020}compared\u{0020}to\u{0020}projections,\u{0020}it's\u{0020}a\u{0020}little\u{0020}less\u{0020}fun.\u{0020}For\u{0020}example,\u{0020}I\u{0020}can't\u{0020}pretend\u{0020}to\u{0020}be\u{0020}an\u{0020}electronic\u{0020}ghost\u{0020}to\u{0020}scare\u{0020}people\u{0020}anymore~", "0", "用尼姆比斯能幻化出的這具身體，操控起來的確更輕鬆了，但相比投影也少了些樂趣啊，比如說，不能裝作電子幽靈嚇唬人了~", "0", "0", "0", "cv_dangyangtu_7", "0", "0"},
[414707] = {414707, 11047, 8, 5, "1_》_0_0.8", "level1", "Hey,\u{0020}hey,\u{0020}this\u{0020}isn't\u{0020}a\u{0020}handshake\u{0020}event\u{0020}right\u{0020}now!\u{0020}And\u{0020}besides,\u{0020}as\u{0020}my\u{0020}Producer,\u{0020}don't\u{0020}you\u{0020}get\u{0020}to\u{0020}interact\u{0020}with\u{0020}me\u{0020}every\u{0020}day?", "0", "喂喂現在可不是握手會的時候啊！而且作為我的製作人，你不是每天都有機會和我互動嗎？", "0", "0", "0", "cv_dangyangtu_8", "0", "0"},
[414708] = {414708, 11047, 9, 5, "1_》_100_1.5", "level2", "Want\u{0020}to\u{0020}know\u{0020}my\u{0020}real\u{0020}identity?\u{0020}I've\u{0020}already\u{0020}hidden\u{0020}the\u{0020}key\u{0020}to\u{0020}the\u{0020}secret\u{0020}somewhere\u{0020}in\u{0020}the\u{0020}vast\u{0020}ocean\u{0020}of\u{0020}the\u{0020}net.\u{0020}Please\u{0020}look\u{0020}for\u{0020}it\u{0020}yourself,\u{0020}Producer~\u{0020}Oh,\u{0020}and\u{0020}don't\u{0020}forget\u{0020}the\u{0020}saying:\u{0020}\"A\u{0020}cunning\u{0020}rabbit\u{0020}has\u{0020}three\u{0020}burrows.\"", "0", "想知道我的真實身份嗎？我已經將解開秘密的鑰匙藏在網絡海洋的某一處了，請製作人自行尋找吧~當然，可別忘了有句話叫“狡兔三窟”。", "0", "0", "0", "cv_dangyangtu_9", "0", "0"},
[414709] = {414709, 11047, 10, 5, "1_》_500_2", "level3", "While\u{0020}running\u{0020}my\u{0020}idol\u{0020}persona,\u{0020}I\u{0020}can't\u{0020}just\u{0020}neglect\u{0020}my\u{0020}studies,\u{0020}and\u{0020}on\u{0020}top\u{0020}of\u{0020}that,\u{0020}I\u{0020}still\u{0020}have\u{0020}my\u{0020}duties\u{0020}as\u{0020}a\u{0020}Driver.\u{0020}I'm\u{0020}really\u{0020}stretched\u{0020}thin.\u{0020}Looks\u{0020}like\u{0020}I'll\u{0020}have\u{0020}to\u{0020}rely\u{0020}on\u{0020}you\u{0020}even\u{0020}more,\u{0020}Producer~", "0", "運營偶像身份的同時，學業也不能就這麼落下，再加上還有駕駛員的工作要做，我已經分身乏術了，看來，得更加依靠製作人才行啊~", "0", "0", "0", "cv_dangyangtu_10", "0", "0"},
[414710] = {414710, 11047, 11, 5, "1_》_1000_2.5", "level4", "I\u{0020}wasn't\u{0020}very\u{0020}satisfied\u{0020}with\u{0020}this\u{0020}arrangement\u{0020}at\u{0020}first,\u{0020}but\u{0020}having\u{0020}you\u{0020}as\u{0020}my\u{0020}Producer\u{0020}really\u{0020}is\u{0020}the\u{0020}best~\u{0020}Giving\u{0020}everyone\u{0020}freedom\u{0020}and\u{0020}respect,\u{0020}that's\u{0020}exactly\u{0020}the\u{0020}kind\u{0020}of\u{0020}\"idol\"\u{0020}I\u{0020}want\u{0020}to\u{0020}be.", "0", "雖然起初不太滿意這種安排，但能由你成為我的製作人果然最棒了~充分給予每個人自由與尊重，我想成為的正是這樣的“偶像”。", "0", "0", "0", "cv_dangyangtu_11", "0", "0"},
[414711] = {414711, 11047, 12, 6, "0", "0", "Thanks\u{0020}for\u{0020}the\u{0020}support!", "0", "感謝應援！", "0", "0", "0", "cv_dangyangtu_12", "0", "0"},
[414712] = {414712, 11047, 13, 7, "0", "0", "I'll\u{0020}make\u{0020}sure\u{0020}to\u{0020}repay\u{0020}all\u{0020}your\u{0020}love~", "0", "得好好回饋你的愛才行了~", "0", "0", "0", "cv_dangyangtu_13", "0", "0"},
[414713] = {414713, 11047, 14, 8, "0", "0", "Both\u{0020}idols\u{0020}and\u{0020}hackers\u{0020}can\u{0020}create\u{0020}miracles.\u{0020}There\u{0020}are\u{0020}still\u{0020}many\u{0020}things\u{0020}that\u{0020}can't\u{0020}be\u{0020}done\u{0020}with\u{0020}just\u{0020}songs\u{0020}or\u{0020}code\u{0020}alone,\u{0020}but…\u{0020}if\u{0020}it's\u{0020}with\u{0020}you,\u{0020}I\u{0020}believe\u{0020}we're\u{0020}still\u{0020}far\u{0020}from\u{0020}our\u{0020}limit.", "0", "偶像與黑客都能創造奇跡，儘管只憑歌聲或代碼無法辦到的事同樣還有許多，但……如果和你一起，我相信現在還遠遠沒到極限。", "0", "0", "0", "cv_dangyangtu_14", "0", "0"},
[414714] = {414714, 11047, 15, 9, "0", "0", "An\u{0020}idol\u{0020}can't\u{0020}afford\u{0020}to\u{0020}slack\u{0020}off.", "0", "身為偶像可不能懈怠。", "0", "0", "0", "cv_dangyangtu_15", "0", "0"},
[414715] = {414715, 11047, 16, 10, "0", "0", "Let\u{0020}me\u{0020}hear\u{0020}it!\u{0020}Whose\u{0020}cheers\u{0020}are\u{0020}the\u{0020}loudest~", "0", "讓我聽聽，哪邊的粉絲呼聲最熱情~", "0", "0", "0", "cv_dangyangtu_16", "0", "0"},
[414716] = {414716, 11047, 17, 11, "0", "0", "I\u{0020}won't\u{0020}forget\u{0020}this\u{0020}performance.", "0", "我不會忘記這場演出的哦。", "0", "0", "0", "cv_dangyangtu_17", "0", "0"},
[414717] = {414717, 11047, 18, 12, "0", "0", "Since\u{0020}we're\u{0020}not\u{0020}perfect\u{0020}yet,\u{0020}let's\u{0020}keep\u{0020}improving\u{0020}together\u{0020}in\u{0020}the\u{0020}future!", "0", "既然還不完美，未來就讓我們共同進步吧！", "0", "0", "0", "cv_dangyangtu_18", "0", "0"},
[414718] = {414718, 11047, 19, 13, "0", "0", "Did\u{0020}I\u{0020}mess\u{0020}around\u{0020}too\u{0020}much?\u{0020}Time\u{0020}to\u{0020}get\u{0020}serious.", "0", "玩鬧過頭了嗎？得認真起來了啊。", "0", "0", "0", "cv_dangyangtu_19", "0", "0"},
[414719] = {414719, 11047, 20, 14, "0", "0", "I\u{0020}need\u{0020}to\u{0020}prepare\u{0020}more\u{0020}thoroughly\u{0020}beforehand.", "0", "事前准備還得更加充足。", "0", "0", "0", "cv_dangyangtu_20", "0", "0"},
[414720] = {414720, 11047, 21, 15, "0", "0", "This\u{0020}fan\u{0020}here,\u{0020}please\u{0020}keep\u{0020}it\u{0020}down~", "0", "請這位粉絲安靜點~", "0", "0", "0", "cv_dangyangtu_21", "0", "0"},
[414721] = {414721, 11047, 23, 16, "0", "0", "This\u{0020}time,\u{0020}it's\u{0020}a\u{0020}brand-new\u{0020}song!", "0", "這次是新的曲子！", "0", "0", "0", "cv_dangyangtu_23", "0", "0"},
[414722] = {414722, 11047, 24, 17, "0", "0", "Lose\u{0020}yourself\u{0020}in\u{0020}it~", "0", "陶醉其中吧~", "0", "0", "0", "cv_dangyangtu_24", "0", "0"},
[414723] = {414723, 11047, 25, 18, "0", "0", "Desire\u{0020}and\u{0020}source\u{0020}code\u{0020}-\u{0020}both\u{0020}will\u{0020}be\u{0020}rewritten\u{0020}by\u{0020}me.", "0", "慾望與源碼，都將由我改寫。", "0", "0", "0", "cv_dangyangtu_25", "0", "0"},
[414724] = {414724, 11047, 26, 19, "0", "0", "Ugh…\u{0020}I'll\u{0020}show\u{0020}up\u{0020}again!", "0", "唔……我還會再出現的！", "0", "0", "0", "cv_dangyangtu_26", "0", "0"},
