[414801] = {414801, 11048, 2, 2, "0", "0", "It's\u{0020}funny?\u{0020}Keep\u{0020}laughing\u{0020}until\u{0020}I\u{0020}tear\u{0020}your\u{0020}face\u{0020}apart.", "そんなにおかしい？　好きなだけ笑っていいのよ。その口を引き裂く前に、ね。", "0", "0", "0", "0", "cv_lilith_sw_2", "0", "0"},
[414802] = {414802, 11048, 3, 3, "0", "0", "That\u{0020}look\u{0020}of\u{0020}surprise...\u{0020}Is\u{0020}it\u{0020}really\u{0020}so\u{0020}shocking\u{0020}to\u{0020}see\u{0020}me\u{0020}in\u{0020}a\u{0020}swimsuit,\u{0020}Synesthete?", "びっくりしたって顔ね。私の水著がそんなに意外だった？通感覚者さん。", "0", "0", "0", "0", "cv_lilith_sw_3", "0", "0"},
[414803] = {414803, 11048, 4, 4, "0", "idle", "Fate\u{0020}is\u{0020}unpredictable,\u{0020}really.\u{0020}I\u{0020}would\u{0020}never\u{0020}have\u{0020}imagined\u{0020}we'd\u{0020}get\u{0020}along\u{0020}like\u{0020}this\u{0020}at\u{0020}that\u{0020}time.", "事実は小説より奇なりってやつね……以前の私なら、あなたと穏やかに過ごす日が來るなんて思いもよらなかったでしょうね。", "0", "0", "0", "0", "cv_lilith_sw_4", "0", "0"},
[414804] = {414804, 11048, 5, 4, "0", "idle", "Ever\u{0020}wonder?\u{0020}All\u{0020}these\u{0020}girls\u{0020}hanging\u{0020}around\u{0020}you...\u{0020}I\u{0020}bet\u{0020}you've\u{0020}got\u{0020}history\u{0020}with\u{0020}every\u{0020}single\u{0020}one.\u{0020}You\u{0020}just\u{0020}don't\u{0020}remember.\u{0020}Forget\u{0020}I\u{0020}said\u{0020}anything.", "考えたことある？　あなたの周りにいるあの子たちが、あなたと男女の仲だったことを忘れてしまっているかも知れないなんて……いいわ、聞かなかったことにして。", "0", "0", "0", "0", "cv_lilith_sw_5", "0", "0"},
[414805] = {414805, 11048, 6, 4, "0", "idle", "I\u{0020}can\u{0020}hear\u{0020}you\u{0020}no\u{0020}matter\u{0020}how\u{0020}far\u{0020}apart\u{0020}we\u{0020}are.\u{0020}Honestly...\u{0020}I'm\u{0020}so\u{0020}tired\u{0020}of\u{0020}it.\u{0020}Synesthesia\u{0020}is\u{0020}troublesome.\u{0020}Now\u{0020}I'm\u{0020}stuck\u{0020}with\u{0020}you\u{0020}forever.", "どれだけ離れてもあなたの聲が聞こえてくるなんて。まったく、うんざりするわ……通感覚って本當に厄介な能力ね。忘れようにも忘れられないじゃない。", "0", "0", "0", "0", "cv_lilith_sw_6", "0", "0"},
[414806] = {414806, 11048, 7, 5, "1_》_0_0.8", "level1", "Your\u{0020}hands\u{0020}are\u{0020}so\u{0020}cold...\u{0020}in\u{0020}this\u{0020}heat.\u{0020}Need\u{0020}me\u{0020}to\u{0020}warm\u{0020}them?", "あなたの手、冷たいのね……こんなに暑い日なのに。溫めてあげましょうか？", "0", "0", "0", "0", "cv_lilith_sw_7", "0", "0"},
[414807] = {414807, 11048, 8, 5, "1_》_0_0.8", "level1", "With\u{0020}every\u{0020}touch,\u{0020}our\u{0020}emotions\u{0020}flow\u{0020}between\u{0020}us.\u{0020}This\u{0020}intimate\u{0020}exchange\u{0020}belongs\u{0020}to\u{0020}us\u{0020}alone,\u{0020}I'm\u{0020}afraid.", "觸れる度に、互いの感情が流れ込んで來る……そんな付き合い方ができるのは、私達だけなのかもね。", "0", "0", "0", "0", "cv_lilith_sw_8", "0", "0"},
[414808] = {414808, 11048, 9, 5, "1_》_100_1.5", "level2", "What\u{0020}will\u{0020}Master\u{0020}eat\u{0020}today?\u{0020}One\u{0020}omurice\u{0020}overflowing\u{0020}with\u{0020}Lilith's\u{0020}love?\u{0020}...Wh-What?\u{0020}That...\u{0020}that\u{0020}was\u{0020}me\u{0020}talking?\u{0020}My\u{0020}body\u{0020}was\u{0020}out\u{0020}of\u{0020}control...", "ご主人様、今日は何をご注文ですか～？　リリスの愛情がたっぷり詰まったオムライ……な、なに今の……私？　私が喋ってたの？　口が勝手に……", "0", "0", "0", "0", "cv_lilith_sw_9", "0", "0"},
[414809] = {414809, 11048, 10, 5, "1_》_500_2", "level3", "What's\u{0020}happening...\u{0020}A\u{0020}summer\u{0020}curse?\u{0020}My\u{0020}body\u{0020}and\u{0020}mouth\u{0020}acting\u{0020}strange...\u{0020}And\u{0020}the\u{0020}feelings...?", "さっきから何なのよ……夏の呪いだとでもいうの？　體も口も、私の意志とは関係なく勝手に……それに、この気持ちは一體……", "0", "0", "0", "0", "cv_lilith_sw_10", "0", "0"},
[414810] = {414810, 11048, 11, 5, "1_》_1000_2.5", "level4", "Synesthete,\u{0020}you\u{0020}may\u{0020}think\u{0020}this\u{0020}power\u{0020}lets\u{0020}you\u{0020}recklessly\u{0020}delve\u{0020}into\u{0020}hearts...\u{0020}but\u{0020}provoking\u{0020}me\u{0020}carries\u{0020}heavy\u{0020}consequences.\u{0020}Master,\u{0020}please\u{0020}stay\u{0020}with\u{0020}me\u{0020}all\u{0020}summer,\u{0020}all\u{0020}right?\u{0020}Ahem!\u{0020}Wh-What\u{0020}was\u{0020}that?", "通感覚者さん。その力で好き勝手に他人の心に入り込めると思っているようだけど、力の代償についてはよく考えた方がいいわよ……ご主人様、この夏を一緒に過ごしてくださいませ……げほっげほっ……な、なに今の？", "0", "0", "0", "0", "cv_lilith_sw_11", "0", "0"},
