[415601] = {415601, 11056, 2, 2, "0", "0", "Looking\u{0020}after\u{0020}someone,\u{0020}is\u{0020}it?\u{0020}Very\u{0020}well,\u{0020}I'll\u{0020}take\u{0020}care\u{0020}of\u{0020}it.\u{0020}Consider\u{0020}it\u{0020}rent.", "0", "0", "0", "0", "0", "cv_huizhang_02", "0", "0"},
[415602] = {415602, 11056, 3, 3, "0", "0", "Ah...\u{0020}I\u{0020}didn't\u{0020}expect\u{0020}things\u{0020}to\u{0020}turn\u{0020}out\u{0020}this\u{0020}way.\u{0020}To\u{0020}think\u{0020}we'd\u{0020}end\u{0020}up\u{0020}in\u{0020}your\u{0020}world...\u{0020}Until\u{0020}we\u{0020}resolve\u{0020}this,\u{0020}we'll\u{0020}be\u{0020}in\u{0020}your\u{0020}care.\u{0020}Let\u{0020}me\u{0020}reintroduce\u{0020}myself.\u{0020}I\u{0020}am\u{0020}one\u{0020}of\u{0020}Skadi's\u{0020}futures.\u{0020}You\u{0020}may\u{0020}call\u{0020}me\u{0020}President.", "0", "0", "0", "0", "0", "cv_huizhang_03", "0", "0"},
[415603] = {415603, 11056, 4, 4, "0", "idle", "Need\u{0020}help\u{0020}with\u{0020}paperwork?\u{0020}It's\u{0020}no\u{0020}trouble.\u{0020}Back\u{0020}when\u{0020}I\u{0020}was\u{0020}student\u{0020}council\u{0020}president,\u{0020}I\u{0020}handled\u{0020}ten\u{0020}times\u{0020}this\u{0020}volume.\u{0020}I'll\u{0020}review\u{0020}them\u{0020}efficiently\u{0020}and\u{0020}discuss\u{0020}them\u{0020}with\u{0020}you.", "0", "0", "0", "0", "0", "cv_huizhang_04", "0", "0"},
[415604] = {415604, 11056, 5, 4, "0", "idle", "Skadi...?\u{0020}Ah...\u{0020}Right,\u{0020}you're\u{0020}referring\u{0020}to\u{0020}the\u{0020}Queen\u{0020}of\u{0020}Dun\u{0020}Scaith...\u{0020}For\u{0020}a\u{0020}moment,\u{0020}I\u{0020}thought\u{0020}you\u{0020}were\u{0020}calling\u{0020}me.\u{0020}Honestly,\u{0020}it's\u{0020}better\u{0020}not\u{0020}to\u{0020}mention\u{0020}that\u{0020}name\u{0020}in\u{0020}front\u{0020}of\u{0020}me.", "0", "0", "0", "0", "0", "cv_huizhang_05", "0", "0"},
[415605] = {415605, 11056, 6, 4, "0", "idle", "So\u{0020}I've\u{0020}finally\u{0020}arrived\u{0020}in\u{0020}your\u{0020}world...\u{0020}But\u{0020}whether\u{0020}it's\u{0020}fortune\u{0020}or\u{0020}misfortune,\u{0020}I\u{0020}find\u{0020}I\u{0020}can't\u{0020}return\u{0020}now.\u{0020}What\u{0020}are\u{0020}your\u{0020}plans...\u{0020}for\u{0020}us?", "0", "0", "0", "0", "0", "cv_huizhang_06", "0", "0"},
