[420024] = {420024, 12000, 27, 20, "0", "0", "You're\u{0020}here,\u{0020}Danube's\u{0020}Navigator.\u{0020}Want\u{0020}to\u{0020}join\u{0020}me\u{0020}for\u{0020}a\u{0020}bath?", "来たんだ？ナビゲーター。あたしと一緒にお風呂に入る？", "你來了啊，多瑙的領航，要和本小姐一起泡澡嗎？", "0", "你来了啊，多瑙的领航，要和本小姐一起泡澡吗？", "0", "cv_kinkura_22", "0", "0"},
[420025] = {420025, 12000, 28, 21, "0", "0", "Oh-ho-ho~\u{0020}I\u{0020}didn't\u{0020}know\u{0020}Danube\u{0020}folks\u{0020}liked\u{0020}baths\u{0020}too.", "おほほ、あんたたちダニューブにもお風呂に入る習慣があったのね。", "喔吼吼~沒想到你們多瑙也有泡澡的習慣啊。", "0", "哦吼吼~没想到你们多瑙也有泡澡的习惯啊。", "0", "cv_kinkura_23", "0", "0"},
[420026] = {420026, 12000, 29, 21, "0", "0", "Speaking\u{0020}of,\u{0020}how\u{0020}about\u{0020}coming\u{0020}to\u{0020}experience\u{0020}Danube's\u{0020}bathhouse\u{0020}next\u{0020}time?\u{0020}Don't\u{0020}worry,\u{0020}it's\u{0020}on\u{0020}me.", "そういえば、今度は九州のお風呂文化を体験してみない？安心して、あたしのおごりだから。", "說起來，領航下次要不要來體驗下多瑙那邊的澡堂文化呢？放心好了，我請客就是了。", "0", "说起来，领航下次要不要来体验下九州那边的澡堂文化呢？放心好了，我请客就是了。", "0", "cv_kinkura_24", "0", "0"},
[420027] = {420027, 12000, 30, 22, "0", "0", "Looks\u{0020}like\u{0020}some\u{0020}thieves\u{0020}are\u{0020}eyeing\u{0020}my\u{0020}treasure\u{0020}here.", "どうやらここにもあたしの財宝を狙ってる泥棒がいるみたい。", "看來這裡也有窺探著我的財寶的小偷呢。", "0", "看来这里也有窥探着我的财宝的小偷呢。", "0", "cv_kinkura_25", "0", "0"},
[420028] = {420028, 12000, 31, 23, "0", "0", "No\u{0020}pressure,\u{0020}take\u{0020}on\u{0020}the\u{0020}challenge.", "自分にプレッシャーをかけないで。リラックスして挑戦しなさい。", "不要有壓力，放鬆挑戰吧。", "0", "不要有压力，放松挑战吧。", "0", "cv_kinkura_26", "0", "0"},
[420029] = {420029, 12000, 32, 24, "0", "0", "Oh-ho-ho~\u{0020}Looks\u{0020}like\u{0020}we're\u{0020}quite\u{0020}connected.", "おほほ、どうやらあたしとは随分縁があるようね。", "喔吼吼~看來你和本小姐還真是有緣啊。", "0", "哦吼吼~看来你和本小姐还真是有缘啊。", "0", "cv_kinkura_27", "0", "0"},
[420030] = {420030, 12000, 33, 25, "0", "0", "You\u{0020}always\u{0020}surprise\u{0020}me,\u{0020}but\u{0020}this\u{0020}time\u{0020}it\u{0020}wasn't\u{0020}a\u{0020}pleasant\u{0020}one~", "あんたっていつも予想のつかないことをやってくれるのね。もちろん、今回のはサプライズでも何でもないけど。", "你總會做出讓本小姐出乎意料的事呢~當然，這次可不算驚喜~", "0", "你总会做出让本小姐出乎意料的事呢~当然，这次可不算惊喜~", "0", "cv_kinkura_28", "0", "0"},
[420031] = {420031, 12000, 34, 26, "0", "0", "Too\u{0020}slow.\u{0020}Do\u{0020}you\u{0020}know\u{0020}how\u{0020}long\u{0020}I've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}you?", "遅すぎ。あたしがどれだけ待ってたと思うの？", "太慢了，你以為本小姐等你多久了啊？", "0", "太慢了，你以为本小姐等你多久了啊？", "0", "cv_kinkura_31", "0", "0"},
[420032] = {420032, 12000, 35, 27, "0", "0", "Danger\u{0020}is\u{0020}everywhere,\u{0020}and\u{0020}so\u{0020}are\u{0020}business\u{0020}opportunities.\u{0020}Let's\u{0020}go,\u{0020}Danube's\u{0020}Navigator!", "危険が多い場所には商機も沢山あるからね。出発しよう。", "危機四伏之地，處處都是商機。我們出發吧，多瑙的領航！", "0", "危机四伏之地，处处都是商机。我们出发吧，多瑙的领航！", "0", "cv_kinkura_33", "0", "0"},
[420033] = {420033, 12000, 36, 28, "0", "0", "A\u{0020}good\u{0020}businessperson\u{0020}finds\u{0020}treasure\u{0020}in\u{0020}the\u{0020}everyday.", "優秀な商人は日常生活の中でも宝を見つけられるの。", "優秀的商人能從日常中發現寶藏。", "0", "优秀的商人能从日常中发现宝藏。", "0", "cv_kinkura_34", "0", "0"},
