[420103] = {420103, 12001, 4, 4, "0", "idle", "Ugh,\u{0020}holding\u{0020}this\u{0020}pose\u{0020}is\u{0020}exhausting...\u{0020}Can\u{0020}you\u{0020}take\u{0020}over\u{0020}for\u{0020}me?", "0", "一直保持這個姿勢好累啊……麻煩可以把我給換下去嗎？", "0", "0", "0", "cv_jing_3", "0", "0"},
[420104] = {420104, 12001, 5, 4, "0", "idle", "My\u{0020}dream?\u{0020}Creating\u{0020}a\u{0020}world\u{0020}where\u{0020}lazybones\u{0020}and\u{0020}slackers\u{0020}like\u{0020}me\u{0020}can\u{0020}be\u{0020}happy!\u{0020}But\u{0020}I'll\u{0020}leave\u{0020}the\u{0020}actual\u{0020}hard\u{0020}work\u{0020}to\u{0020}my\u{0020}sister,\u{0020}of\u{0020}course.", "0", "夢想是創造出讓懶人和廢材能夠快樂生活的世界！當然，這只是夢想而已，真正落實起來還是交給姐姐吧~", "0", "0", "0", "cv_jing_4", "0", "0"},
[420105] = {420105, 12001, 6, 4, "0", "idle", "Hehe,\u{0020}if\u{0020}my\u{0020}sister\u{0020}catches\u{0020}me\u{0020}lounging\u{0020}around\u{0020}like\u{0020}this,\u{0020}she's\u{0020}gonna\u{0020}be\u{0020}mad\u{0020}at\u{0020}me\u{0020}again.", "0", "呼呼呼，如果被姐姐看到我在這裏偷懶估計又會惹她生氣了吧。", "0", "0", "0", "cv_jing_30", "0", "0"},
[420106] = {420106, 12001, 7, 5, "1_》_0_0.8", "level1", "Ah,\u{0020}there\u{0020}you\u{0020}are!\u{0020}Have\u{0020}a\u{0020}seat,\u{0020}have\u{0020}a\u{0020}seat!\u{0020}Just,\u{0020}uh,\u{0020}not\u{0020}on\u{0020}me,\u{0020}okay?", "0", "哦，你來了啊～隨便坐，隨便坐，只要別坐到我身上就好。", "0", "0", "0", "cv_jing_5", "0", "0"},
[420107] = {420107, 12001, 8, 5, "1_》_0_0.8", "level1", "Yeah,\u{0020}yeah,\u{0020}as\u{0020}you\u{0020}guessed,\u{0020}my\u{0020}family\u{0020}forced\u{0020}me\u{0020}to\u{0020}come\u{0020}here—it's\u{0020}not\u{0020}like\u{0020}I\u{0020}wanted\u{0020}to\u{0020}stick\u{0020}with\u{0020}my\u{0020}sister.", "0", "啊啊，和你想得一樣啦，我是被家裏人強制要求來這裏的啦，才不是因為想粘著姐姐。", "0", "0", "0", "cv_jing_31", "0", "0"},
[420108] = {420108, 12001, 9, 5, "1_》_100_1.5", "level2", "Huh?\u{0020}Back\u{0020}again?\u{0020}And\u{0020}you\u{0020}only\u{0020}brought\u{0020}this\u{0020}little\u{0020}bit\u{0020}of\u{0020}food...?", "0", "哎？你又來了啊……什麼嗎，居然只帶了這點吃的……", "0", "0", "0", "cv_jing_6", "0", "0"},
[420109] = {420109, 12001, 10, 5, "1_》_500_2", "level3", "Hey,\u{0020}hey,\u{0020}hey~\u{0020}Why\u{0020}do\u{0020}you\u{0020}keep\u{0020}visiting\u{0020}me?\u{0020}You\u{0020}won't\u{0020}get\u{0020}anything\u{0020}out\u{0020}of\u{0020}investing\u{0020}in\u{0020}me.\u{0020}You\u{0020}should\u{0020}focus\u{0020}on\u{0020}my\u{0020}sister\u{0020}instead.", "0", "喂喂喂～你這麼頻繁地找我到底是看上我哪一點了啊？在我身上投入再多也不會有回報的哦～比起我，你還是去多關照下姐姐吧。", "0", "0", "0", "cv_jing_7", "0", "0"},
[420110] = {420110, 12001, 11, 5, "1_》_1000_2.5", "level4", "You're\u{0020}persistent—kind\u{0020}of\u{0020}touching,\u{0020}actually.\u{0020}It's\u{0020}the\u{0020}first\u{0020}time\u{0020}someone's\u{0020}had\u{0020}such\u{0020}high\u{0020}expectations\u{0020}for\u{0020}me.\u{0020}Maybe\u{0020}I\u{0020}should\u{0020}try\u{0020}a\u{0020}little\u{0020}harder,\u{0020}like\u{0020}making\u{0020}you\u{0020}some\u{0020}instant\u{0020}noodles.", "0", "還真是執著啊，弄得我都有些感動了。我還是第一次被人這麼期待著。嗯……要不要也嘗試努力下呢，比如給你泡包速食麵什麼的。", "0", "0", "0", "cv_jing_8", "0", "0"},
[420111] = {420111, 12001, 12, 6, "0", "0", "Level\u{0020}up!\u{0020}Wait,\u{0020}this\u{0020}isn't\u{0020}a\u{0020}video\u{0020}game?", "0", "level\u{0020}up！哎？不是電子遊戲嗎？", "0", "0", "0", "cv_jing_9", "0", "0"},
[420112] = {420112, 12001, 13, 7, "0", "0", "Is\u{0020}this\u{0020}what\u{0020}they\u{0020}mean\u{0020}by\u{0020}\"gaining\u{0020}weight\u{0020}just\u{0020}by\u{0020}drinking\u{0020}water\"?", "0", "這就是所謂的“喝水也能長胖”嗎？", "0", "0", "0", "cv_jing_10", "0", "0"},
[420113] = {420113, 12001, 14, 8, "0", "0", "Please\u{0020}spare\u{0020}me\u{0020}this\u{0020}one.\u{0020}I'd\u{0020}rather\u{0020}stay\u{0020}at\u{0020}home\u{0020}than\u{0020}fight.\u{0020}But\u{0020}I\u{0020}can't\u{0020}keep\u{0020}eating\u{0020}for\u{0020}free\u{0020}from\u{0020}you\u{0020}for\u{0020}too\u{0020}long—let's\u{0020}get\u{0020}some\u{0020}exercise\u{0020}instead!", "0", "只有這個還請饒了我吧……比起戰鬥我更加喜歡待在家裏……但是也不能白吃你這麼久，還是稍微運動下吧～", "0", "0", "0", "cv_jing_11", "0", "0"},
