[420202] = {420202, 12002, 3, 3, "0", "0", "Hello,\u{0020}I'm\u{0020}Shiranui\u{0020}of\u{0020}Fuurinkazan.\u{0020}I've\u{0020}heard\u{0020}there\u{0020}are\u{0020}many\u{0020}lovely\u{0020}girls\u{0020}here,\u{0020}so\u{0020}let's\u{0020}see\u{0020}for\u{0020}ourselves.", "こんにちは。私は風林火山の不知火よ。ここには沢山の可愛い女の子がいるって聞いたの。さて、さっそく確認させていただきましょ。", "你好，我是風林火山的不知火，聽說這裡有很多可愛的女孩子，就讓我來確認下吧。", "0", "你好，我是风林火山的不知火，听说这里有很多可爱的女孩子，就让我来确认下吧。", "0", "cv_shiranui_1", "0", "0"},
[420203] = {420203, 12002, 4, 4, "0", "idle", "The\u{0020}weak,\u{0020}the\u{0020}cute,\u{0020}and\u{0020}those\u{0020}who\u{0020}stir\u{0020}up\u{0020}compassion—they're\u{0020}the\u{0020}reason\u{0020}the\u{0020}strong\u{0020}can\u{0020}be\u{0020}called\u{0020}strong.\u{0020}Whether\u{0020}we\u{0020}protect\u{0020}or\u{0020}destroy\u{0020}them,\u{0020}the\u{0020}strong\u{0020}can't\u{0020}exist\u{0020}without\u{0020}the\u{0020}weak.", "弱き者、可愛い者。不憫でならないわ。彼女たちが存在するからこそ、強者は強者と呼ばれるの。守るにせよ、滅ぼすにせよ……強者は弱者から離れられないのよ。", "弱小之人，可愛之人，令人心生憐憫之人啊。正是因為有她們的存在，強者才能被稱作強者。無論是保護她們，還是摧毀她們，強者始終都離不開弱者。", "0", "弱小之人，可爱之人，令人心生怜悯之人啊。正是因为有她们的存在，强者才能被称作强者。无论是保护她们，还是摧毁她们，强者始终都离不开弱者。", "0", "cv_shiranui_3", "0", "0"},
[420204] = {420204, 12002, 5, 4, "0", "idle", "What's\u{0020}wrong\u{0020}with\u{0020}liking\u{0020}cute\u{0020}and\u{0020}fragile\u{0020}things?", "可愛くて弱いものが好きで、何が悪いの？", "喜歡可愛而又脆弱的東西又有什麼錯呢？", "0", "喜欢可爱而又脆弱的东西又有什么错呢？", "0", "cv_shiranui_4", "0", "0"},
[420205] = {420205, 12002, 6, 4, "0", "idle", "Don't\u{0020}you\u{0020}think\u{0020}Seifung\u{0020}is\u{0020}just\u{0020}too\u{0020}adorable?\u{0020}She's\u{0020}still\u{0020}a\u{0020}kid,\u{0020}trying\u{0020}so\u{0020}hard\u{0020}to\u{0020}act\u{0020}like\u{0020}an\u{0020}adult.\u{0020}She\u{0020}carries\u{0020}way\u{0020}too\u{0020}much\u{0020}for\u{0020}someone\u{0020}so\u{0020}young.", "清風って本当に可愛いわあ。ナビゲーターもそう思わない？子供なのに大人ぶってて。あの柔らかい肩に重荷を背負いすぎてるのね。", "領航，你不覺得清風那孩子可愛得有些過分了嗎？明明還是個孩子，卻要裝成大人的模樣。那雙柔弱的肩膀上，背負著太多沉重的東西了。", "0", "领航，你不觉得清风那孩子可爱得有些过分了吗？明明还是个孩子，却要装成大人的模样。那双柔弱的肩膀上，背负着太多沉重的东西了。", "0", "cv_shiranui_30", "0", "0"},
[420206] = {420206, 12002, 7, 5, "1_》_0_0.8", "level1", "Why\u{0020}did\u{0020}I\u{0020}become\u{0020}a\u{0020}Driver?\u{0020}Well,\u{0020}there\u{0020}are\u{0020}lots\u{0020}of\u{0020}cute\u{0020}kids\u{0020}around,\u{0020}and\u{0020}if\u{0020}the\u{0020}war\u{0020}doesn't\u{0020}end,\u{0020}they\u{0020}can't\u{0020}live\u{0020}happy\u{0020}lives,\u{0020}right?", "ドライバーになった理由？沢山の可愛いコがいるからに決まってるわ……それに、戦争が終わらないと、あのコたちは幸せに暮らせない。そうでしょ？", "為什麼要當駕駛員，當然是因為有很多可愛的孩子在啦……而且，如果戰爭不結束的話，那些孩子就沒辦法過上幸福的生活，不是嗎？", "0", "为什么要当驾驶员，当然是因为有很多可爱的孩子在啦……而且，如果战争不结束的话，那些孩子就没办法过上幸福的生活，不是吗？", "0", "cv_shiranui_31", "0", "0"},
[420207] = {420207, 12002, 8, 5, "1_》_0_0.8", "level1", "Oh?\u{0020}Are\u{0020}you\u{0020}like\u{0020}me—someone\u{0020}who\u{0020}likes\u{0020}to\u{0020}take\u{0020}the\u{0020}initiative?", "あら、もしかして、あなたも私みたいに自分から攻めるタイプなの？", "欸呀，難道說你和我一樣也是會主動進攻的那類嗎？", "0", "哎呀，难道说你和我一样也是会主动进攻的那类吗？", "0", "cv_shiranui_5", "0", "0"},
[420208] = {420208, 12002, 9, 5, "1_》_100_1.5", "level2", "Hehe,\u{0020}you're\u{0020}so\u{0020}cute\u{0020}but\u{0020}also\u{0020}surprisingly\u{0020}mature.\u{0020}I\u{0020}guess\u{0020}I\u{0020}can't\u{0020}tease\u{0020}you\u{0020}like\u{0020}I\u{0020}normally\u{0020}would.", "うふふ。見た目は可愛いけど、案外大人しいのね。これじゃ手が出せないじゃない。", "呵呵呵，明明長得那麼可愛，但是卻意外得成熟嘛。這樣一來姐姐就沒法對你下手了吧。", "0", "呵呵呵，明明长得那么可爱，但是却意外得成熟嘛。这样一来姐姐就没法对你下手了吧。", "0", "cv_shiranui_6", "0", "0"},
[420209] = {420209, 12002, 10, 5, "1_》_500_2", "level3", "Even\u{0020}the\u{0020}strongest\u{0020}people\u{0020}have\u{0020}weaknesses.\u{0020}Being\u{0020}strong\u{0020}just\u{0020}means\u{0020}you're\u{0020}better\u{0020}at\u{0020}hiding\u{0020}them.\u{0020}I\u{0020}can\u{0020}tell,\u{0020}Navigator,\u{0020}that\u{0020}deep\u{0020}down,\u{0020}your\u{0020}strength\u{0020}is\u{0020}pretty\u{0020}fragile,\u{0020}isn't\u{0020}it?", "どれだけ強い人であっても弱点は必ずあるわ。ただ、強者は自分の弱点を隠すのが上手い。それだけよ。ナビゲーター、私、感じてるわ。あなたの心を支えてる支柱、本当は凄く脆いんでしょ？", "即便是再強大的人都會擁有弱點，強者只不過是善於掩蓋自己弱點的人罷了。領航，我能感覺到，支撐著你內心的那根支柱實際上非常脆弱吧。", "0", "即便是再强大的人都会拥有弱点，强者只不过是善于掩盖自己弱点的人罢了。领航，我能感觉到，支撑着你内心的那根支柱实际上非常脆弱吧。", "0", "cv_shiranui_7", "0", "0"},
[420210] = {420210, 12002, 11, 5, "1_》_1000_2.5", "level4", "Once\u{0020}all\u{0020}this\u{0020}is\u{0020}over,\u{0020}we\u{0020}can\u{0020}both\u{0020}finally\u{0020}drop\u{0020}the\u{0020}act.\u{0020}All\u{0020}I\u{0020}want\u{0020}is\u{0020}to\u{0020}create\u{0020}a\u{0020}world\u{0020}where\u{0020}strength\u{0020}isn't\u{0020}needed.", "全てが終わったら、あなたも私も、偽りの仮面を外すことができるわ。そう。私が創りたいのは、強者を必要としない世界なの。", "等一切都結束過後，你我就都能卸下偽裝了。是啊，我想要創造的，只是一個不需要強者的世界罷了。", "0", "等一切都结束过后，你我就都能卸下伪装了。是啊，我想要创造的，只是一个不需要强者的世界罢了。", "0", "cv_shiranui_8", "0", "0"},
[420211] = {420211, 12002, 12, 6, "0", "0", "Feeling\u{0020}stronger\u{0020}is\u{0020}incredible!", "強くなる感じって、いいわね。", "變強的感覺……真不錯啊。", "0", "变强的感觉……真不错啊。", "0", "cv_shiranui_9", "0", "0"},
[420212] = {420212, 12002, 13, 7, "0", "0", "This\u{0020}way,\u{0020}attracting\u{0020}adorable\u{0020}kids\u{0020}will\u{0020}be\u{0020}even\u{0020}easier,\u{0020}right?", "これでもっと沢山の可愛いコたちを惹きつけられるのかしら？", "這樣一來就更加容易吸引到可愛的孩子了吧？", "0", "这样一来就更加容易吸引到可爱的孩子了吧？", "0", "cv_shiranui_10", "0", "0"},
[420213] = {420213, 12002, 14, 8, "0", "0", "Hehehe,\u{0020}I\u{0020}didn't\u{0020}expect\u{0020}you\u{0020}to\u{0020}care\u{0020}so\u{0020}much\u{0020}about\u{0020}me.\u{0020}How\u{0020}should\u{0020}I\u{0020}spoil\u{0020}you\u{0020}next?", "うふふ。お姉さんのことがそんなに気になるんだ。さて、どう可愛がってあげようかしら？", "呵呵呵，沒想到你這麼在意姐姐啊。那麼接下來該如何疼愛你呢？", "0", "呵呵呵，没想到你这么在意姐姐啊。那么接下来该如何疼爱你呢？", "0", "cv_shiranui_11", "0", "0"},
[420214] = {420214, 12002, 15, 9, "0", "0", "Hiyah!\u{0020}Wow,\u{0020}this\u{0020}bow\u{0020}is\u{0020}amazing!", "はっ！ふーん、なかなか良い弓だわ。", "喝啊！哼，真是一把好弓啊。", "0", "喝啊！哼，真是一把好弓啊。", "0", "cv_shiranui_12", "0", "0"},
[420215] = {420215, 12002, 16, 10, "0", "0", "Burn\u{0020}them\u{0020}all!", "彼らを焼き尽くしなさい。", "燒盡他們吧。", "0", "烧尽他们吧。", "0", "cv_shiranui_13", "0", "0"},
[420216] = {420216, 12002, 17, 11, "0", "0", "So,\u{0020}what\u{0020}do\u{0020}you\u{0020}think?\u{0020}Am\u{0020}I\u{0020}strong?", "どう？私、強いでしょ？", "怎麼樣，我很強吧？", "0", "怎么样，我很强吧？", "0", "cv_shiranui_14", "0", "0"},
[420217] = {420217, 12002, 18, 12, "0", "0", "Did\u{0020}you\u{0020}have\u{0020}a\u{0020}tough\u{0020}time?\u{0020}Well,\u{0020}that's\u{0020}just\u{0020}how\u{0020}it\u{0020}goes.", "それで抵抗したつもり？まぁ、所詮その程度ね。", "稍微掙扎了一下嗎？不過也就這樣了。", "0", "稍微挣扎了一下吗？不过也就这样了。", "0", "cv_shiranui_15", "0", "0"},
[420218] = {420218, 12002, 19, 13, "0", "0", "Hehehe,\u{0020}the\u{0020}enemy\u{0020}is\u{0020}pretty\u{0020}tough\u{0020}too.", "うふふ。敵もなかなか手強かったわね。", "呵呵呵，敵人也不弱啊。", "0", "呵呵呵，敌人也不弱啊。", "0", "cv_shiranui_16", "0", "0"},
[420219] = {420219, 12002, 20, 14, "0", "0", "We\u{0020}both\u{0020}need\u{0020}to\u{0020}step\u{0020}up\u{0020}our\u{0020}game.", "私もあなたも、もっと頑張らないと。", "無論是我還是你，都還需要再努力一些啊。", "0", "无论是我还是你，都还需要再努力一些啊。", "0", "cv_shiranui_17", "0", "0"},
