[420228] = {420228, 12002, 30, 22, "0", "0", "t\u{0020}seems\u{0020}someone\u{0020}wants\u{0020}to\u{0020}interrupt\u{0020}us.", "私たちの邪魔をしてくる者がいるようね。", "看來有人想要打擾我們呢。", "0", "看来有人想要打扰我们呢。", "0", "cv_shiranui_26", "0", "0"},
