[420231] = {420231, 12002, 33, 25, "0", "0", "Navigator,\u{0020}you\u{0020}got\u{0020}it\u{0020}wrong,\u{0020}but\u{0020}you're\u{0020}still\u{0020}so\u{0020}cute!", "外したナビゲーターも可愛いわ。", "猜錯的領航也好可愛啊～", "0", "猜错的领航也好可爱啊～", "0", "cv_shiranui_29", "0", "0"},
[420232] = {420232, 12002, 34, 26, "0", "0", "You're\u{0020}back,\u{0020}Navigator.\u{0020}Ready\u{0020}to\u{0020}go\u{0020}find\u{0020}some\u{0020}cute\u{0020}little\u{0020}ones\u{0020}to\u{0020}play\u{0020}with\u{0020}today?", "お帰りなさい、ナビゲーター。どう？今日も私と一緒に可愛いコたちの所に行く？", "回來了呀，領航。如何，今天也要和我一起去找那些可愛的小傢伙們玩嗎？", "0", "回来了呀，领航。如何，今天也要和我一起去找那些可爱的小家伙们玩吗？", "0", "cv_shiranui_32", "0", "0"},
[420233] = {420233, 12002, 35, 27, "0", "0", "Let's\u{0020}bring\u{0020}this\u{0020}endless\u{0020}story\u{0020}to\u{0020}a\u{0020}close\u{0020}together.", "一緒にこの果てのない物語を終わらせましょ。", "讓我們一起終結這無盡頭的故事吧。", "0", "让我们一起终结这无尽头的故事吧。", "0", "cv_shiranui_34", "0", "0"},
[420234] = {420234, 12002, 36, 28, "0", "0", "To\u{0020}get\u{0020}stronger,\u{0020}daily\u{0020}training\u{0020}is\u{0020}essential.", "強くなるためには日常の鍛錬も必要だわ。", "為了變強，日常的鍛煉也是必須的。", "0", "为了变强，日常的锻炼也是必须的。", "0", "cv_shiranui_35", "0", "0"},
[420235] = {420235, 12002, 37, 29, "0", "0", "Do\u{0020}you\u{0020}need\u{0020}me\u{0020}to\u{0020}recommend\u{0020}a\u{0020}few\u{0020}exercises?", "何人か推薦してあげようかしら？", "需要我推薦幾位嗎？", "0", "需要我推荐几位吗？", "0", "cv_shiranui_36", "0", "0"},
[420236] = {420236, 12002, 38, 30, "0", "0", "Let's\u{0020}find\u{0020}more\u{0020}lovely\u{0020}children!", "可愛いコたちをもっと募集して！", "多找些可愛的孩子吧！", "0", "多找些可爱的孩子吧！", "0", "cv_shiranui_37", "0", "0"},
