[420238] = {420238, 12002, 40, 32, "0", "0", "Buy\u{0020}something\u{0020}casually;\u{0020}it's\u{0020}not\u{0020}that\u{0020}important.", "適当に買えばいいわ。重要な物じゃないし。", "隨便買點什麼吧，不是什麼重要的東西。", "0", "随便买点什么吧，不是什么重要的东西。", "0", "cv_shiranui_39", "0", "0"},
[420239] = {420239, 12002, 41, 33, "0", "0", "If\u{0020}you\u{0020}look\u{0020}closely,\u{0020}Navigator,\u{0020}you're\u{0020}really\u{0020}quite\u{0020}cute.\u{0020}I'm\u{0020}deeply\u{0020}touched.", "よく見たら、ナビゲーターも可愛い～お姉さんの心が、揺さぶられてしまうわ。", "仔細看的話，果然領航也很可愛，姐姐會心動的。", "0", "仔细看的话，果然领航也很可爱，姐姐会心动的。", "0", "cv_shiranui_40", "0", "0"},
[420240] = {420240, 12002, 42, 34, "0", "0", "Navigator,\u{0020}you\u{0020}really\u{0020}enjoy\u{0020}these\u{0020}little\u{0020}things,\u{0020}don't\u{0020}you?", "ナビゲーターって本当に細かい作業が好きね。", "領航，你還真是喜歡這些瑣碎的事情呢。", "0", "领航，你还真是喜欢这些琐碎的事情呢。", "0", "cv_shiranui_41", "0", "0"},
[420241] = {420241, 12002, 43, 35, "0", "0", "Maybe\u{0020}there's\u{0020}a\u{0020}shy,\u{0020}lovely\u{0020}child\u{0020}secretly\u{0020}writing\u{0020}to\u{0020}you?", "可愛い子が照れながらこっそりメールを送ってくれたかもしれないわよ？", "也許會有害羞可愛的孩子悄悄給你寫信喔？", "0", "也许会有害羞可爱的孩子悄悄给你写信哦？", "0", "cv_shiranui_42", "0", "0"},
[420242] = {420242, 12002, 44, 36, "0", "0", "Let's\u{0020}share\u{0020}experiences\u{0020}with\u{0020}everyone!", "みんなと一緒に心得について交流しましょ。", "和大家一起交流心得吧~", "0", "和大家一起交流心得吧~", "0", "cv_shiranui_43", "0", "0"},
[420243] = {420243, 12002, 45, 37, "0", "0", "Let's\u{0020}make\u{0020}the\u{0020}final\u{0020}confirmation.", "最後の確認を行いましょ。", "進行最後的確認吧。", "0", "进行最后的确认吧。", "0", "cv_shiranui_44", "0", "0"},
[420300] = {420300, 12003, 1, 1, "0", "0", "Haze\u{0020}reverb!", "蒼霧残響（ハツリバーブ）！", "蒼霧殘響！", "0", "苍雾残响！", "0", "cv_efugenia_34", "0", "0"},
[420301] = {420301, 12003, 2, 2, "0", "0", "Haha,\u{0020}you've\u{0020}got\u{0020}sharp\u{0020}a\u{0020}sharp\u{0020}eye!", "あはは、見る目があるね、あんた！", "哈哈，你的眼光不錯！", "0", "哈哈，你的眼光不错！", "0", "cv_efugenia_2", "0", "0"},
[420302] = {420302, 12003, 3, 3, "0", "0", "Are\u{0020}you\u{0020}the\u{0020}Navigator?\u{0020}You\u{0020}look\u{0020}a\u{0020}bit\u{0020}delicate.\u{0020}No\u{0020}worries,\u{0020}Efgenia\u{0020}will\u{0020}take\u{0020}care\u{0020}of\u{0020}your\u{0020}enemies\u{0020}for\u{0020}you!", "あんたがナビゲーターなの？何だか弱そうな奴だね。あはははっ、でも大丈夫。あんたの敵はこのあたし、エフゲニアに任せて！", "你這個傢伙就是領航？看起來有些弱不禁風啊。哈哈，沒事，你的敵人就交給我葉芙根尼婭解決吧！", "0", "你这个家伙就是领航？看起来有些弱不禁风啊。哈哈，没事，你的敌人就交给我叶芙根尼娅解决吧！", "0", "cv_efugenia_1", "0", "0"},
[420303] = {420303, 12003, 4, 4, "0", "idle", "Forty-eight,\u{0020}forty-nine,\u{0020}fifty—done!\u{0020}That's\u{0020}the\u{0020}twelfth\u{0020}set\u{0020}today,\u{0020}eight\u{0020}more\u{0020}to\u{0020}go!\u{0020}Want\u{0020}to\u{0020}try\u{0020}some\u{0020}strength\u{0020}training,\u{0020}Navigator?", "四十八――四十九――五十――よし、今日の筋トレはもう12セットすんだから…...あと8セット！ナビゲーターもやってみない？筋トレ。", "四十八——四十九——五十——好了，今天的第十二組力量訓練完成，還剩下八組！領航，要試試鍛煉肌肉嗎？", "0", "四十八——四十九——五十——好了，今天的第十二组力量训练完成，还剩下八组！领航，要试试锻炼肌肉吗？", "0", "cv_efugenia_3", "0", "0"},
[420304] = {420304, 12003, 5, 4, "0", "idle", "The\u{0020}body\u{0020}matters\u{0020}more\u{0020}than\u{0020}the\u{0020}mind.\u{0020}Only\u{0020}a\u{0020}strong\u{0020}body\u{0020}can\u{0020}house\u{0020}a\u{0020}strong\u{0020}spirit.\u{0020}So,\u{0020}Navigator,\u{0020}are\u{0020}you\u{0020}sure\u{0020}you\u{0020}don't\u{0020}want\u{0020}to\u{0020}train\u{0020}more?\u{0020}Haha,\u{0020}don't\u{0020}worry,\u{0020}I'll\u{0020}guide\u{0020}you\u{0020}through\u{0020}it.", "肉体は精神より遥かに重要だ。丈夫な体にこそ強い魂を宿せるんだから。ってワケで、本当にトレーニングしなくていいの？あはは、安心して。根気よく指導してあげるからさ。", "肉體遠比精神重要，只有健碩的軀體才能容下堅毅的靈魂。所以領航，你真的不考慮再鍛煉一下嗎？哈哈，放心好了，我會耐下性子來好好指導你的。", "0", "肉体远比精神重要，只有健硕的躯体才能容下坚毅的灵魂。所以领航，你真的不考虑再锻炼一下吗？哈哈，放心好了，我会耐下性子来好好指导你的。", "0", "cv_efugenia_4", "0", "0"},
[420305] = {420305, 12003, 6, 4, "0", "idle", "As\u{0020}the\u{0020}captain\u{0020}of\u{0020}Cannonbore,\u{0020}I'm\u{0020}responsible\u{0020}for\u{0020}my\u{0020}team.\u{0020}Whenever\u{0020}I\u{0020}get\u{0020}a\u{0020}chance,\u{0020}I\u{0020}put\u{0020}them\u{0020}through\u{0020}emergency\u{0020}strength\u{0020}training.", "コウリンゲールの隊長として、チーム内の皆の世話をする義務があるんだ。だから、時間がある時はいつも皆を対象に緊急強化トレーニングを実施してるのさ。", "作為鋼輪戈爾的隊長，我必須要對自己的隊員負責！因此，只要有空閑的時間，我都會給她們進行緊急強化訓練。", "0", "作为钢轮戈尔的队长，我必须要对自己的队员负责！因此，只要有空闲的时间，我都会给她们进行紧急强化训练。", "0", "cv_efugenia_31", "0", "0"},
[420306] = {420306, 12003, 7, 5, "1_》_0_0.8", "level1", "If\u{0020}I\u{0020}can't\u{0020}protect\u{0020}my\u{0020}comrades,\u{0020}then\u{0020}all\u{0020}the\u{0020}muscle\u{0020}training\u{0020}is\u{0020}pointless.\u{0020}I\u{0020}need\u{0020}to\u{0020}be\u{0020}strong\u{0020}enough\u{0020}to\u{0020}protect\u{0020}the\u{0020}world.", "仲間を守れないなら、ずっと鍛えた筋肉も意味がない。十分強くなってこそ、人間の世界を守ることができるんだ。", "如果不能保護同伴，我一直鍛煉的肌肉就沒有了意義。只有變得足夠強大，我才能守護人類的世界。", "0", "如果不能保护同伴，我一直锻炼的肌肉就没有了意义。只有变得足够强大，我才能守护人类的世界。", "0", "cv_efugenia_32", "0", "0"},
[420307] = {420307, 12003, 8, 5, "1_》_0_0.8", "level1", "It's\u{0020}been\u{0020}a\u{0020}while\u{0020}since\u{0020}I\u{0020}had\u{0020}a\u{0020}real\u{0020}challenge.\u{0020}You're\u{0020}brave,\u{0020}Navigator!\u{0020}Haha!\u{0020}Oh?\u{0020}I\u{0020}wasn't\u{0020}even\u{0020}trying\u{0020}yet...", "人から挑戦を受けるなんて久しぶりだ。やるね、ナビゲーター！はっ！…...え？そんなあ、これからが本番だっていうのに……", "我已經很久沒有收到過其他人的挑戰了，領航你還真是勇敢！哈！欸？我還沒用力……", "0", "我已经很久没有收到过其他人的挑战了，领航你还真是勇敢！哈！诶？我还没用力……", "0", "cv_efugenia_5", "0", "0"},
[420308] = {420308, 12003, 9, 5, "1_》_100_1.5", "level2", "Ready\u{0020}to\u{0020}build\u{0020}some\u{0020}muscle?\u{0020}Haha,\u{0020}I'll\u{0020}set\u{0020}up\u{0020}a\u{0020}training\u{0020}plan\u{0020}for\u{0020}you!\u{0020}Strong\u{0020}bodies\u{0020}look\u{0020}way\u{0020}cooler!", "筋トレ、やりたくなった？あはは、じゃあ、トレーニングプランを練ってやるよ！丈夫な体を持った方がかっこいいしね！", "你想要鍛煉肌肉了嗎？哈哈，那我來給你安排一套訓練方案吧！擁有強健身材的人才更帥氣啊！", "0", "你想要锻炼肌肉了吗？哈哈，那我来给你安排一套训练方案吧！拥有强健身材的人才更帅气啊！", "0", "cv_efugenia_6", "0", "0"},
[420309] = {420309, 12003, 10, 5, "1_》_500_2", "level3", "You've\u{0020}got\u{0020}some\u{0020}real\u{0020}determination!\u{0020}You\u{0020}even\u{0020}want\u{0020}extra\u{0020}training?\u{0020}I'll\u{0020}join\u{0020}you,\u{0020}but\u{0020}no\u{0020}quitting\u{0020}halfway!", "あんた、本当に根気強いね！まだあたしが作ったトレーニングプランを続けてるだなんて！ここまできたら、付き合ってあげるよ。途中で諦めたりしちゃダメだからね！", "你還真是個有毅力的傢伙！居然還要加練！那我陪你一起鍛煉吧，你可不能中途放棄喔！", "0", "你还真是个有毅力的家伙！居然还要加练！那我陪你一起锻炼吧，你可不能中途放弃哦！", "0", "cv_efugenia_7", "0", "0"},
[420310] = {420310, 12003, 11, 5, "1_》_1000_2.5", "level4", "Don't\u{0020}push\u{0020}yourself\u{0020}too\u{0020}hard—my\u{0020}training\u{0020}is\u{0020}intense.\u{0020}I\u{0020}can\u{0020}see\u{0020}your\u{0020}willpower.\u{0020}You're\u{0020}not\u{0020}that\u{0020}strong\u{0020}yet,\u{0020}but\u{0020}you're\u{0020}definitely\u{0020}a\u{0020}warrior.", "無理しないでね。あたしのトレーニングは超ハードだから、普通の人じゃ耐えられないんだ。でも、あんたの意志、確かに感じたよ。体はまだまだだけど、心はもう優秀な戦士に違いないよ。", "不要逞強啊，我的訓練強度可不是其他人能承受的。你的意志我已經感受到了，雖然你現在還沒那麼強壯，但確實是個優秀的戰士。", "0", "不要逞强啊，我的训练强度可不是其他人能承受的。你的意志我已经感受到了，虽然你现在还没那么强壮，但确实是个优秀的战士。", "0", "cv_efugenia_8", "0", "0"},
[420311] = {420311, 12003, 12, 6, "0", "0", "My\u{0020}muscles\u{0020}have\u{0020}grown!", "筋肉が増えた！", "肌肉增加了！", "0", "肌肉增加了！", "0", "cv_efugenia_9", "0", "0"},
