[420401] = {420401, 12004, 2, 2, "0", "0", "Ah...\u{0020}I'm\u{0020}so\u{0020}happy\u{0020}you\u{0020}picked\u{0020}me.\u{0020}Out\u{0020}of\u{0020}everyone...\u{0020}you\u{0020}chose\u{0020}me,\u{0020}the\u{0020}one\u{0020}and\u{0020}only.", "ああ……嬉しいです！沢山の人の中からあたしを……貴方にとって、唯一無二のあたしを選んでくださって。", "啊……好高興，你居然選擇了我。從那麼多人中……選擇了獨一無二的我。", "0", "啊……好高兴，你居然选择了我。从那么多人中……选择了独一无二的我。", "0", "cv_hanago_2", "0", "0"},
[420402] = {420402, 12004, 3, 3, "0", "0", "Hello,\u{0020}Navigator\u{0020}of\u{0020}the\u{0020}West.\u{0020}My\u{0020}name\u{0020}is\u{0020}Hanakotoba.\u{0020}It\u{0020}must\u{0020}be\u{0020}fate\u{0020}that\u{0020}we've\u{0020}met\u{0020}like\u{0020}this.", "はじめまして、西から来たナビゲーター。あたしの名前は花語。こうして貴方と出会えたのは、きっと……運命です。", "你好，來自西方的領航，我的名字叫做花語，能夠像這樣相遇也算是有緣了吧。", "0", "你好，来自西方的领航，我的名字叫做花语，能够像这样相遇也算是有缘了吧。", "0", "cv_hanago_1", "0", "0"},
[420403] = {420403, 12004, 4, 4, "0", "idle", "You\u{0020}don't\u{0020}think\u{0020}I'm\u{0020}scary,\u{0020}do\u{0020}you?", "貴方も……あたしの性格が怖い…ですか……？", "你不會也覺得……我的性格很恐怖吧。", "0", "你不会也觉得……我的性格很恐怖吧。", "0", "cv_hanago_3", "0", "0"},
[420404] = {420404, 12004, 5, 4, "0", "idle", "I\u{0020}love\u{0020}plush\u{0020}toys\u{0020}because\u{0020}they\u{0020}always\u{0020}play\u{0020}with\u{0020}me.\u{0020}If\u{0020}you\u{0020}want\u{0020}to\u{0020}join\u{0020}us,\u{0020}I'll\u{0020}share\u{0020}them\u{0020}with\u{0020}you.\u{0020}But\u{0020}from\u{0020}now\u{0020}on,\u{0020}you\u{0020}can\u{0020}only\u{0020}play\u{0020}with\u{0020}me,\u{0020}okay?", "あたしは昔、よく問題を起こしては真っ暗な部屋に閉じ込められてました。でもいつも、心紙姉さんが助けてくれたんですよ。", "我很喜歡毛絨玩具，因為他們只會和我玩。如果你也想要加入的話，我會把他們都讓給你喔。但是……從今往後，你只能和我一個人玩，如何？", "0", "我很喜欢毛绒玩具，因为他们只会和我玩。如果你也想要加入的话，我会把他们都让给你哦。但是……从今往后，你只能和我一个人玩，如何？", "0", "cv_hanago_4", "0", "0"},
[420405] = {420405, 12004, 6, 4, "0", "idle", "When\u{0020}I\u{0020}got\u{0020}in\u{0020}trouble\u{0020}before,\u{0020}they'd\u{0020}lock\u{0020}me\u{0020}in\u{0020}the\u{0020}dark\u{0020}room,\u{0020}but\u{0020}Sister\u{0020}Kokorokami\u{0020}always\u{0020}saved\u{0020}me...", "昔ね、何かをやらかした時は真っ暗な部屋に閉じ込められちゃって……でもね、心紙姉さんがいつも助けてくれて、あたしを出してくれたんだ。", "以前我闖禍之後就會被關進那個小黑屋裏，不過每次心紙姐姐都會救我出來……", "0", "以前我闯祸之后就会被关进那个小黑屋里，不过每次心纸姐姐都会救我出来……", "0", "cv_hanago_29", "0", "0"},
[420406] = {420406, 12004, 7, 5, "1_》_0_0.8", "level1", "Why\u{0020}do\u{0020}I\u{0020}fight?\u{0020}Maybe\u{0020}it's\u{0020}to\u{0020}meet\u{0020}someone\u{0020}on\u{0020}the\u{0020}battlefield.\u{0020}Someone\u{0020}whose\u{0020}heart\u{0020}will\u{0020}never\u{0020}break,\u{0020}no\u{0020}matter\u{0020}what.", "なぜ戦わなければいけないのでしょうか……？ああっ！もしや、戦場で運命の人に出逢うため…？壊れることのない、最愛の人と！", "為什麼要戰鬥呢……啊，大概是想在戰場邂逅心上人吧，是無論如何都不會壞掉的心上人喔。", "0", "为什么要战斗呢……啊，大概是想在战场邂逅心上人吧，是无论如何都不会坏掉的心上人哦。", "0", "cv_hanago_30", "0", "0"},
[420407] = {420407, 12004, 8, 5, "1_》_0_0.8", "level1", "What\u{0020}does\u{0020}this\u{0020}mean?\u{0020}Should\u{0020}I\u{0020}take\u{0020}this\u{0020}as\u{0020}your\u{0020}way\u{0020}of\u{0020}responding\u{0020}to\u{0020}my\u{0020}love?", "これってどういう意味なの？こういう形であたしの愛に応えてるってこと？", "這是什麼意思？我可以理解為你是在以這種方式回應我的愛嗎？", "0", "这是什么意思？我可以理解为你是在以这种方式回应我的爱吗？", "0", "cv_hanago_5", "0", "0"},
[420408] = {420408, 12004, 9, 5, "1_》_100_1.5", "level2", "Ah...\u{0020}I\u{0020}wasn't\u{0020}wrong,\u{0020}was\u{0020}I?\u{0020}At\u{0020}some\u{0020}point,\u{0020}you\u{0020}wanted\u{0020}to\u{0020}claim\u{0020}me\u{0020}for\u{0020}yourself,\u{0020}didn't\u{0020}you?", "あ……やっぱり！貴方も、あたしを独り占めしようとしてますよね！", "啊……果然，我沒有猜錯的話，你也曾在不經意間想要將我占為己有吧？", "0", "啊……果然，我没有猜错的话，你也曾在不经意间想要将我占为己有吧？", "0", "cv_hanago_6", "0", "0"},
[420409] = {420409, 12004, 10, 5, "1_》_500_2", "level3", "Um...\u{0020}I\u{0020}have\u{0020}a\u{0020}favor\u{0020}to\u{0020}ask.\u{0020}Yesterday\u{0020}at\u{0020}3:02:31\u{0020}PM,\u{0020}I\u{0020}saw\u{0020}you\u{0020}with\u{0020}another\u{0020}girl.\u{0020}Could\u{0020}you\u{0020}let\u{0020}me\u{0020}know\u{0020}next\u{0020}time?\u{0020}Or\u{0020}better\u{0020}yet,\u{0020}just\u{0020}don't\u{0020}talk\u{0020}to\u{0020}other\u{0020}girls,\u{0020}okay?", "えっと……お願いがあるんです。昨日の午後３時２分３１秒、他の女の子と一緒に出掛けていたのを見ました。今度から、そういう時はあらかじめ、あたしに言っておいてくれませんか？もしできないのなら、他の女の子との交流はもうお仕舞いですよ？", "那個……有件事情想要拜託你。就是昨天下午三點零二分三十一秒的時候我看到你和其他女生一起出去了，如果可以的話下次能提前和我打一聲招呼嗎？或者乾脆不要和其他女生交流了吧，好嗎？", "0", "那个……有件事情想要拜托你。就是昨天下午三点零二分三十一秒的时候我看到你和其他女生一起出去了，如果可以的话下次能提前和我打一声招呼吗？或者干脆不要和其他女生交流了吧，好吗？", "0", "cv_hanago_7", "0", "0"},
[420410] = {420410, 12004, 11, 5, "1_》_1000_2.5", "level4", "Before\u{0020}I\u{0020}met\u{0020}you,\u{0020}I\u{0020}thought\u{0020}I\u{0020}was\u{0020}meant\u{0020}to\u{0020}serve\u{0020}only\u{0020}the\u{0020}gods.\u{0020}But\u{0020}after\u{0020}seeing\u{0020}you,\u{0020}how\u{0020}do\u{0020}I\u{0020}explain\u{0020}this\u{0020}burning\u{0020}feeling\u{0020}inside\u{0020}me?\u{0020}Hehe,\u{0020}maybe\u{0020}it's\u{0020}because\u{0020}you\u{0020}are\u{0020}my\u{0020}god.\u{0020}My\u{0020}very\u{0020}own\u{0020}god.", "貴方に出会うまで、あたしは神様に仕えるだけの存在だと思っていました。でも、貴方と過ごす時間はすごく不思議で安心感があって……うふふ。もしかして、貴方が神様そのものなのでしょうか？あたしだけの……神様。", "在遇到您之前我一直認為自己只應侍奉神明。但是，見過您之後，這腹中躁動著的熱潮又該如何解釋呢？呵呵呵，我想，該不會是因為，您就是神明大人吧？只屬於我的……神明大人。", "0", "在遇到您之前我一直认为自己只应侍奉神明。但是，见过您之后，这腹中躁动着的热潮又该如何解释呢？呵呵呵，我想，该不会是因为，您就是神明大人吧？只属于我的……神明大人。", "0", "cv_hanago_8", "0", "0"},
[420411] = {420411, 12004, 12, 6, "0", "0", "Is\u{0020}this\u{0020}the\u{0020}reward\u{0020}you've\u{0020}given\u{0020}me?", "あたしへのご褒美ですか？", "這就是您給予我的獎勵嗎？", "0", "这就是您给予我的奖励吗？", "0", "cv_hanago_9", "0", "0"},
[420412] = {420412, 12004, 13, 7, "0", "0", "Thank\u{0020}you\u{0020}so\u{0020}much!\u{0020}Navigator\u{0020}sir,\u{0020}my\u{0020}love\u{0020}for\u{0020}you\u{0020}has\u{0020}doubled!", "ありがとうございます、ナビゲーター！貴方への愛も倍増しましたよ。", "非常感謝！領航大人，我對您的愛意也翻倍了！", "0", "非常感谢！领航大人，我对您的爱意也翻倍了！", "0", "cv_hanago_10", "0", "0"},
[420413] = {420413, 12004, 14, 8, "0", "0", "Honestly...\u{0020}I'm\u{0020}not\u{0020}sure\u{0020}how\u{0020}to\u{0020}repay\u{0020}you...\u{0020}But\u{0020}first,\u{0020}let\u{0020}me\u{0020}ask.\u{0020}You\u{0020}didn't\u{0020}do\u{0020}this\u{0020}for\u{0020}any\u{0020}other\u{0020}girls,\u{0020}did\u{0020}you?", "ああ……こんなにしていただいて、どのように恩返しをしたらよいのでしょうか。……ですが、一つだけ確認を。……他の女の子に、同じ事をしたりしてませんよね？", "真是……我已經不知道該如何回報您了……不過，姑且確認下，您應該沒有對其他女生這麼做過吧？", "0", "真是……我已经不知道该如何回报您了……不过，姑且确认下，您应该没有对其他女生这么做过吧？", "0", "cv_hanago_11", "0", "0"},
[420414] = {420414, 12004, 15, 9, "0", "0", "If\u{0020}you\u{0020}don't\u{0020}practice\u{0020}your\u{0020}aim,\u{0020}you\u{0020}won't\u{0020}be\u{0020}able\u{0020}to\u{0020}hit\u{0020}my\u{0020}heart\u{0020}properly.", "ちゃんと射法を磨かないと、貴方の心を狙い撃ちできませんから。", "不好好磨練技術的話，可瞄不准你的心臟喔～", "0", "不好好磨练技术的话，可瞄不准你的心脏哦～", "0", "cv_hanago_12", "0", "0"},
[420415] = {420415, 12004, 16, 10, "0", "0", "Get\u{0020}rid\u{0020}of\u{0020}anyone\u{0020}trying\u{0020}to\u{0020}interrupt\u{0020}our\u{0020}time\u{0020}together!", "あたしたち二人の時間を邪魔する奴らは、全て片付けましょう！", "把妨礙我們獨處的傢伙全部都清理掉！", "0", "把妨碍我们独处的家伙全部都清理掉！", "0", "cv_hanago_13", "0", "0"},
[420416] = {420416, 12004, 17, 11, "0", "0", "Now...\u{0020}No\u{0020}one\u{0020}can\u{0020}come\u{0020}between\u{0020}us\u{0020}anymore.", "あたしたちを引き裂くことは、もう、誰にもできませんね。", "已經……沒有任何人能將我們分開了喔。", "0", "已经……没有任何人能将我们分开了哦。", "0", "cv_hanago_14", "0", "0"},
[420417] = {420417, 12004, 18, 12, "0", "0", "Finally,\u{0020}we've\u{0020}dealt\u{0020}with\u{0020}all\u{0020}the\u{0020}annoying\u{0020}people.", "やっと、邪魔者を全て片付けましたね。", "終於把礙事的傢伙全都收拾掉了呢。", "0", "终于把碍事的家伙全都收拾掉了呢。", "0", "cv_hanago_15", "0", "0"},
[420418] = {420418, 12004, 19, 13, "0", "0", "Ah,\u{0020}it's\u{0020}finally\u{0020}over.\u{0020}Every\u{0020}moment\u{0020}away\u{0020}from\u{0020}you\u{0020}feels\u{0020}like\u{0020}torture.", "ああ、やっと終わりました！貴方がそばにいない間、まるで地獄のようでした。", "啊，終於結束了，和你分開的每一秒都好像是在地獄中一般。", "0", "啊，终于结束了，和你分开的每一秒都好像是在地狱中一般。", "0", "cv_hanago_16", "0", "0"},
[420419] = {420419, 12004, 20, 14, "0", "0", "Please,\u{0020}punish\u{0020}me.\u{0020}But...\u{0020}Please\u{0020}don't\u{0020}abandon\u{0020}me.\u{0020}Don't\u{0020}send\u{0020}me\u{0020}back\u{0020}to\u{0020}that\u{0020}dark\u{0020}room...", "罰でも何でも、甘んじて受けます！でも……お願い、あたしを見捨てないでください！あの真っ暗な部屋には、もう戻りたくありません…", "請責罰我吧，但是……拜託了，請千萬不要丟下我，千萬不要讓我再回那個黑洞洞的房間……", "0", "请责罚我吧，但是……拜托了，请千万不要丢下我，千万不要让我再回那个黑洞洞的房间……", "0", "cv_hanago_17", "0", "0"},
[420420] = {420420, 12004, 21, 15, "0", "0", "Become\u{0020}a\u{0020}broken\u{0020}doll!", "壊れたぬいぐるみですね。", "變成壞掉的玩偶吧！", "0", "变成坏掉的玩偶吧！", "0", "cv_hanago_18", "0", "0"},
[420421] = {420421, 12004, 23, 16, "0", "0", "Break!", "壊れて！", "壞掉吧！", "0", "坏掉吧！", "0", "cv_hanago_20", "0", "0"},
[420422] = {420422, 12004, 22, 38, "0", "0", "I've\u{0020}got\u{0020}my\u{0020}eyes\u{0020}on\u{0020}you.", "狙いをつけましたよ。", "已經盯上你了喔。", "0", "已经盯上你了哦。", "0", "cv_hanago_19", "0", "0"},
[420423] = {420423, 12004, 26, 19, "0", "0", "Is\u{0020}that\u{0020}all\u{0020}the\u{0020}love\u{0020}you\u{0020}have\u{0020}for\u{0020}me?", "愛は……ここまでなの……？", "愛意……就到此為止了嗎？", "0", "爱意……就到此为止了吗？", "0", "cv_hanago_21", "0", "0"},
[420424] = {420424, 12004, 27, 20, "0", "0", "I\u{0020}never\u{0020}imagined\u{0020}I'd\u{0020}be\u{0020}alone\u{0020}with\u{0020}you\u{0020}like\u{0020}this.", "まさか、こんな姿で貴方と二人っきりになるなんて。", "沒想到，居然會以這種姿態和你獨處呢。", "0", "没想到，居然会以这种姿态和你独处呢。", "0", "cv_hanago_22", "0", "0"},
[420425] = {420425, 12004, 28, 21, "0", "0", "Huh—Being\u{0020}with\u{0020}you\u{0020}makes\u{0020}me\u{0020}want\u{0020}to\u{0020}do\u{0020}naughty\u{0020}things.", "ふぅ……貴方と一緒にいると、なんだかイケない気持ちになってしまいますね。", "呼——和你在一起，就忍不住想要做些壞壞的事情呢。", "0", "呼——和你在一起，就忍不住想要做些坏坏的事情呢。", "0", "cv_hanago_23", "0", "0"},
[420426] = {420426, 12004, 29, 21, "0", "0", "Are\u{0020}you\u{0020}feeling\u{0020}tired?\u{0020}If\u{0020}you\u{0020}don't\u{0020}mind,\u{0020}you\u{0020}can\u{0020}nap\u{0020}here.\u{0020}I'll\u{0020}take\u{0020}good\u{0020}care\u{0020}of\u{0020}you.", "お疲れですか？よかったらここで一晩、お休みください。あたしも、そばにいますから……", "你已經累了嗎？如果不介意的話就在這裡睡一覺吧，我會好好照顧你的。", "0", "你已经累了吗？如果不介意的话就在这里睡一觉吧，我会好好照顾你的。", "0", "cv_hanago_24", "0", "0"},
[420427] = {420427, 12004, 30, 22, "0", "0", "Please,\u{0020}don't\u{0020}get\u{0020}hurt,\u{0020}or\u{0020}it'll\u{0020}break\u{0020}my\u{0020}heart.", "怪我をしないでくださいね。あたし、泣いてしまいます……", "還請不要受傷，否則我會難過的。", "0", "还请不要受伤，否则我会难过的。", "0", "cv_hanago_25", "0", "0"},
[420428] = {420428, 12004, 31, 23, "0", "0", "Phew,\u{0020}if\u{0020}it's\u{0020}you,\u{0020}I\u{0020}bet\u{0020}you\u{0020}won't\u{0020}guess\u{0020}wrong,\u{0020}right—right?", "うふふ、貴方なら当たりますよね？…そうですよね？", "呼呼呼，如果是你的話應該不會猜錯吧，對——吧——？", "0", "呼呼呼，如果是你的话应该不会猜错吧，对——吧——？", "0", "cv_hanago_26", "0", "0"},
[420429] = {420429, 12004, 32, 24, "0", "0", "There\u{0020}must\u{0020}be\u{0020}some\u{0020}magical\u{0020}bond\u{0020}between\u{0020}us.", "やっぱりあたし達、運命の赤い糸で結ばれているんです！", "果然，你我之間存在著什麼神奇的連接吧。", "0", "果然，你我之间存在着什么神奇的连接吧。", "0", "cv_hanago_27", "0", "0"},
[420430] = {420430, 12004, 33, 25, "0", "0", "Aiya\u{0020}ya,\u{0020}you're\u{0020}doing\u{0020}this\u{0020}on\u{0020}purpose,\u{0020}aren't\u{0020}you?\u{0020}Want\u{0020}to\u{0020}try\u{0020}picking\u{0020}again?", "あら、わざとですよね？次は……間違いませんよね？", "欸呀呀，你一定是故意的吧，要不要再選一次呢？", "0", "哎呀呀，你一定是故意的吧，要不要再选一次呢？", "0", "cv_hanago_28", "0", "0"},
[420431] = {420431, 12004, 34, 26, "0", "0", "Ah,\u{0020}where\u{0020}did\u{0020}you\u{0020}go?\u{0020}I've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}you\u{0020}so,\u{0020}so\u{0020}long.\u{0020}Hehe.", "ああ…！いったいどこに行ってたんですか？ずっと待ってたんですよ。ずっと……ずうぅぅっと。……うふふ。", "啊，你究竟去哪裡了啊，我已經等了你好久好久，好久好久喔。嘿嘿。", "0", "啊，你究竟去哪里了啊，我已经等了你好久好久，好久好久哦。嘿嘿。", "0", "cv_hanago_31", "0", "0"},
[420432] = {420432, 12004, 35, 27, "0", "0", "Hehehe,\u{0020}this\u{0020}is\u{0020}a\u{0020}story\u{0020}you've\u{0020}written.", "うふふ。貴方が書いてくださった物語ですね。", "嘿嘿嘿，是由你譜寫的故事呢。", "0", "嘿嘿嘿，是由你谱写的故事呢。", "0", "cv_hanago_33", "0", "0"},
[420433] = {420433, 12004, 36, 28, "0", "0", "Our\u{0020}love\u{0020}will\u{0020}never\u{0020}lose\u{0020}to\u{0020}anyone.", "あたしたちの愛は、誰にも負けませんよね。", "我們的愛不會輸給任何人。", "0", "我们的爱不会输给任何人。", "0", "cv_hanago_34", "0", "0"},
[420434] = {420434, 12004, 37, 29, "0", "0", "I\u{0020}really\u{0020}don't\u{0020}want\u{0020}to\u{0020}share\u{0020}you\u{0020}with\u{0020}anyone\u{0020}else.", "他の人と貴方をシェアしたくありません。", "真不想和其他人一起分享你呢。", "0", "真不想和其他人一起分享你呢。", "0", "cv_hanago_35", "0", "0"},
[420435] = {420435, 12004, 38, 30, "0", "0", "Isn't\u{0020}having\u{0020}me\u{0020}enough?", "あたしだけじゃ、だめですか？", "難道有我還不夠嗎？", "0", "难道有我还不够吗？", "0", "cv_hanago_36", "0", "0"},
[420436] = {420436, 12004, 39, 31, "0", "0", "This...\u{0020}Is\u{0020}this\u{0020}a\u{0020}gift\u{0020}for\u{0020}me?", "これって……あたしへのプレゼントですか？", "這是……給我的禮物吧？", "0", "这是……给我的礼物吧？", "0", "cv_hanago_37", "0", "0"},
[420437] = {420437, 12004, 40, 32, "0", "0", "Ah,\u{0020}this\u{0020}must\u{0020}be\u{0020}the\u{0020}offering\u{0020}box.", "ああ、奉納箱ですね。", "啊，這是奉納箱吧。", "0", "啊，这是奉纳箱吧。", "0", "cv_hanago_38", "0", "0"},
[420438] = {420438, 12004, 41, 33, "0", "0", "Hehehe,\u{0020}I\u{0020}could\u{0020}look\u{0020}at\u{0020}you\u{0020}forever\u{0020}and\u{0020}never\u{0020}get\u{0020}tired\u{0020}of\u{0020}it.", "うふふふ……何度見ても、飽きません……", "嘿嘿嘿，無論看多少次，都不會膩呢。", "0", "嘿嘿嘿，无论看多少次，都不会腻呢。", "0", "cv_hanago_39", "0", "0"},
[420439] = {420439, 12004, 42, 34, "0", "0", "Let's\u{0020}change\u{0020}the\u{0020}settings.", "設定を変更しますか？", "變更一下設定吧。", "0", "变更一下设置吧。", "0", "cv_hanago_40", "0", "0"},
[420440] = {420440, 12004, 43, 35, "0", "0", "No\u{0020}letters\u{0020}from\u{0020}other\u{0020}girls,\u{0020}right?", "……他の女の子からのメールはないよね？", "沒有其他女孩的信件吧？", "0", "没有其他女孩的邮件吧？", "0", "cv_hanago_41", "0", "0"},
[420441] = {420441, 12004, 44, 36, "0", "0", "The\u{0020}chat\u{0020}room's\u{0020}not\u{0020}for\u{0020}love\u{0020}talk.", "チャットルームは愛を語らう場所じゃないですけどね。", "聊天室可不是談情說愛的地方呢。", "0", "聊天室可不是谈情说爱的地方呢。", "0", "cv_hanago_42", "0", "0"},
[420442] = {420442, 12004, 45, 37, "0", "0", "Just...\u{0020}Confirm\u{0020}this.", "ちょっと……確認しますね。", "稍微……確認一下。", "0", "稍微……确认一下。", "0", "cv_hanago_43", "0", "0"},
[420500] = {420500, 12005, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_iria_34", "0", "0"},
[420501] = {420501, 12005, 2, 2, "0", "0", "Is\u{0020}this...\u{0020}a\u{0020}sign\u{0020}that\u{0020}I'm\u{0020}getting\u{0020}a\u{0020}raise?!", "これって……給料が上がるってこと？！", "這是…要漲工資的意思嗎？！", "0", "这是…要涨工资的意思吗？！", "0", "cv_iria_2", "0", "0"},
[420502] = {420502, 12005, 3, 3, "0", "0", "Boss...\u{0020}oh,\u{0020}wait,\u{0020}I\u{0020}should\u{0020}call\u{0020}you\u{0020}Navigator,\u{0020}right?\u{0020}Sorry,\u{0020}I'm\u{0020}still\u{0020}getting\u{0020}used\u{0020}to\u{0020}that.\u{0020}I'll\u{0020}switch\u{0020}to\u{0020}it\u{0020}from\u{0020}now\u{0020}on.", "ボス……じゃなくて、ナビゲーターだったよね？ごめん、まだ慣れてなくて。これから気を付けるよ。", "老闆…不對，應該是叫領航嗎？抱歉，我還沒習慣這種稱呼，以後我會慢慢改口的。", "0", "老板…不对，应该是叫领航吗？抱歉，我还没习惯这种称呼，以后我会慢慢改口的。", "0", "cv_iria_1", "0", "0"},
[420503] = {420503, 12005, 4, 4, "0", "idle", "Even\u{0020}though\u{0020}Ember\u{0020}isn't\u{0020}an\u{0020}official\u{0020}unit,\u{0020}don't\u{0020}underestimate\u{0020}us.\u{0020}Our\u{0020}ammo's\u{0020}all\u{0020}ready—make\u{0020}sure\u{0020}to\u{0020}take\u{0020}us\u{0020}on\u{0020}the\u{0020}next\u{0020}mission!", "確かに灰燼は正規部隊じゃないけど、見くびってもらっちゃ困るよ。弾薬の準備はＯＫ。今度のミッション、私たちも連れていってね！", "雖然灰燼不是正牌部隊，不過也不要因此就小瞧我們喔。彈藥已經準備完畢，下次任務請務必帶上我們吧！", "0", "虽然灰烬不是正牌部队，不过也不要因此就小瞧我们哦。弹药已经准备完毕，下次任务请务必带上我们吧！", "0", "cv_iria_3", "0", "0"},
[420504] = {420504, 12005, 5, 4, "0", "idle", "The\u{0020}Sin\u{0020}killed\u{0020}my\u{0020}parents.\u{0020}I'll\u{0020}never\u{0020}forgive\u{0020}them.\u{0020}My\u{0020}anger\u{0020}won't\u{0020}fade\u{0020}until\u{0020}they're\u{0020}completely\u{0020}wiped\u{0020}out.", "原罪が私の両親を殺した。絶対に許せない。彼らを全部滅ぼさないと、私の怒りはきっと消えない。", "原罪是殺害了我父母的兇手，無論如何我都沒法原諒他們。直到將他們徹底消滅乾淨為止，我的怒火永遠都不會熄滅。", "0", "原罪是杀害了我父母的凶手，无论如何我都没法原谅他们。直到将他们彻底消灭干净为止，我的怒火永远都不会熄灭。", "0", "cv_iria_4", "0", "0"},
[420505] = {420505, 12005, 6, 4, "0", "idle", "Bolina...\u{0020}she's\u{0020}so\u{0020}mature\u{0020}for\u{0020}her\u{0020}age,\u{0020}it's\u{0020}worrying.\u{0020}What?\u{0020}You\u{0020}think\u{0020}I'm\u{0020}the\u{0020}same?", "ボーリンナのあの年齢にそぐわない性格って心配だよね……え？私と彼女は大して変わらないって……？", "波琳娜，她的那份與年齡完全不相符的性格真是讓人擔心……什麼？你說我也差不多……", "0", "波琳娜，她的那份与年龄完全不相符的性格真是让人担心……什么？你说我也差不多……", "0", "cv_iria_31", "0", "0"},
[420506] = {420506, 12005, 7, 5, "1_》_0_0.8", "level1", "This\u{0020}arm's\u{0020}a\u{0020}prosthetic.\u{0020}I\u{0020}got\u{0020}it\u{0020}to\u{0020}fight\u{0020}Sin\u{0020}more\u{0020}effectively.", "この腕、作り物だよ。原罪に対抗するために付けたんだ。", "這條胳膊是假的喔，是為了更好地對付原罪才換上的。", "0", "这条胳膊是假的哦，是为了更好地对付原罪才换上的。", "0", "cv_iria_5", "0", "0"},
[420507] = {420507, 12005, 8, 5, "1_》_0_0.8", "level1", "Don't\u{0020}look\u{0020}at\u{0020}me\u{0020}like\u{0020}that.\u{0020}It\u{0020}was\u{0020}my\u{0020}choice.\u{0020}Just\u{0020}treat\u{0020}me\u{0020}like\u{0020}any\u{0020}other\u{0020}mercenary.", "そんな目で見つめないで。これは私自身の選択。私のことは、普通の傭兵だって思えばいい。", "請不要用那種眼神看著我，這都是我自己的選擇，你只用將我當作是普通的雇傭兵就好了。", "0", "请不要用那种眼神看着我，这都是我自己的选择，你只用将我当作是普通的雇佣兵就好了。", "0", "cv_iria_32", "0", "0"},
[420508] = {420508, 12005, 9, 5, "1_》_100_1.5", "level2", "Funds\u{0020}have\u{0020}been\u{0020}a\u{0020}bit\u{0020}tight\u{0020}lately.\u{0020}If\u{0020}we\u{0020}had\u{0020}more,\u{0020}we\u{0020}could\u{0020}stock\u{0020}up\u{0020}on\u{0020}more\u{0020}ammo.", "最近、経費が不足してるみたいだけど。もっと増えたりしないかなあ。そしたらもっと沢山弾薬を買えるし。", "最近經費稍微有些不夠啊，如果能再多點就好了，這樣就能買更多的彈藥了。", "0", "最近经费稍微有些不够啊，如果能再多点就好了，这样就能买更多的弹药了。", "0", "cv_iria_6", "0", "0"},
[420509] = {420509, 12005, 10, 5, "1_》_500_2", "level3", "I\u{0020}didn't\u{0020}realize\u{0020}it\u{0020}before,\u{0020}but\u{0020}ever\u{0020}since\u{0020}joining\u{0020}AEGIS,\u{0020}I've\u{0020}noticed\u{0020}my\u{0020}gear's\u{0020}kind\u{0020}of\u{0020}outdated...", "アイギスに来てから初めて気付いたけど、私の装備ってちょっと古い……？", "以前的我似乎沒有注意到，但是自從來到艾吉斯才發現，自己的裝備好像有些落伍了啊……", "0", "以前的我似乎没有注意到，但是自从来到艾吉斯才发现，自己的装备好像有些落伍了啊……", "0", "cv_iria_7", "0", "0"},
[420510] = {420510, 12005, 11, 5, "1_》_1000_2.5", "level4", "You\u{0020}should\u{0020}take\u{0020}better\u{0020}care\u{0020}of\u{0020}yourself...\u{0020}but\u{0020}for\u{0020}me,\u{0020}as\u{0020}long\u{0020}as\u{0020}I\u{0020}can\u{0020}get\u{0020}my\u{0020}revenge,\u{0020}nothing\u{0020}else\u{0020}matters.\u{0020}Still,\u{0020}if\u{0020}that's\u{0020}an\u{0020}order\u{0020}from\u{0020}you,\u{0020}maybe\u{0020}I'll\u{0020}start\u{0020}thinking\u{0020}about\u{0020}life\u{0020}after\u{0020}revenge.", "自分の身体には気を付けた方がいいって？いや、私にとって、復讐さえできれば他のことはどうでもいい。でも、あんたの命令なら、復讐を果たした後のためにも少しは気を使ってみようかな。", "要更加愛惜自己的身體嘛……不，在我眼裏只要能夠完成復仇，其他的都無所謂了。但是，如果這是你的命令的話，那麼我也會試著抽空考慮下復仇之後的事情吧。", "0", "要更加爱惜自己的身体嘛……不，在我眼里只要能够完成复仇，其他的都无所谓了。但是，如果这是你的命令的话，那么我也会试着抽空考虑下复仇之后的事情吧。", "0", "cv_iria_8", "0", "0"},
[420511] = {420511, 12005, 12, 6, "0", "0", "This\u{0020}is\u{0020}the\u{0020}only\u{0020}thing\u{0020}that\u{0020}brings\u{0020}me\u{0020}peace...", "やっぱり、こうしないと安心できない……", "果然只有這樣才能讓我感到安心啊……", "0", "果然只有这样才能让我感到安心啊……", "0", "cv_iria_9", "0", "0"},
[420512] = {420512, 12005, 13, 7, "0", "0", "AEGIS'\u{0020}tech\u{0020}is\u{0020}really\u{0020}convenient,\u{0020}isn't\u{0020}it?", "アイギスのテクノロジーって便利だね。", "艾吉斯的科技還真是方便呢。", "0", "艾吉斯的科技还真是方便呢。", "0", "cv_iria_10", "0", "0"},
[420513] = {420513, 12005, 14, 8, "0", "0", "I\u{0020}used\u{0020}to\u{0020}think\u{0020}my\u{0020}rage\u{0020}would\u{0020}consume\u{0020}me\u{0020}one\u{0020}day,\u{0020}but\u{0020}thanks\u{0020}to\u{0020}you,\u{0020}I've\u{0020}held\u{0020}onto\u{0020}who\u{0020}I\u{0020}am.\u{0020}Now,\u{0020}I'll\u{0020}use\u{0020}this\u{0020}new\u{0020}steel\u{0020}body\u{0020}to\u{0020}meet\u{0020}your\u{0020}expectations.\u{0020}I'll...\u{0020}turn\u{0020}every\u{0020}Sin\u{0020}to\u{0020}ashes.", "いつか私の心も怒りに呑み込まれるんじゃないかって思ってた。でもあんたのお陰で、最後の最後で自分を取り戻すことができた。これからも、この新しい鋼鉄の身であんたの期待に応えるために頑張るよ。ーー全ての原罪を灰燼と帰さん。", "我曾經以為早晚有一天我的心智會被怒火吞沒，但是多虧了你，我才在最後保持了自我。接下來就讓我用這幅嶄新的鋼鐵之軀來回應你的期待吧。我將會……把所有的原罪都化為灰燼。", "0", "我曾经以为早晚有一天我的心智会被怒火吞没，但是多亏了你，我才在最后保持了自我。接下来就让我用这幅崭新的钢铁之躯来回应你的期待吧。我将会……把所有的原罪都化为灰烬。", "0", "cv_iria_11", "0", "0"},
[420514] = {420514, 12005, 15, 9, "0", "0", "Looks\u{0020}like\u{0020}the\u{0020}new\u{0020}ammo\u{0020}shipment\u{0020}arrived.", "新しい弾薬が届いたみたいだね。", "看來新的彈藥已經到貨了啊。", "0", "看来新的弹药已经到货了啊。", "0", "cv_iria_12", "0", "0"},
[420515] = {420515, 12005, 16, 10, "0", "0", "Good,\u{0020}let's\u{0020}burn\u{0020}the\u{0020}enemies\u{0020}to\u{0020}ash.", "敵を灰燼とせんッ！", "很好，將敵人化為灰燼吧。", "0", "很好，将敌人化为灰烬吧。", "0", "cv_iria_13", "0", "0"},
[420516] = {420516, 12005, 17, 11, "0", "0", "See?\u{0020}I\u{0020}told\u{0020}you,\u{0020}don't\u{0020}underestimate\u{0020}the\u{0020}irregulars.", "だから、非正規軍をなめるなって！", "我就說，千萬不要小瞧非正規軍啊。", "0", "我就说，千万不要小瞧非正规军啊。", "0", "cv_iria_14", "0", "0"},
[420517] = {420517, 12005, 18, 12, "0", "0", "Not\u{0020}a\u{0020}single\u{0020}Sin\u{0020}left.", "原罪はもう、全て灰燼に帰した。", "原罪，已經一個都不剩了。", "0", "原罪，已经一个都不剩了。", "0", "cv_iria_15", "0", "0"},
[420518] = {420518, 12005, 19, 13, "0", "0", "No\u{0020}matter\u{0020}what\u{0020}it\u{0020}takes,\u{0020}I\u{0020}won't\u{0020}back\u{0020}down.", "どんな高い代償を払ったとしても、私は絶対に負けを認めない。", "無論付出多大的代價，我都不會認輸的。", "0", "无论付出多大的代价，我都不会认输的。", "0", "cv_iria_16", "0", "0"},
[420519] = {420519, 12005, 20, 14, "0", "0", "Is\u{0020}it\u{0020}still\u{0020}not\u{0020}enough?...\u{0020}Have\u{0020}I\u{0020}not\u{0020}done\u{0020}enough?...", "足りなかったんだね……私の努力が、まだまだ足りなかった……", "還不夠嗎？……我付出的難道還不夠嗎……", "0", "还不够吗？……我付出的难道还不够吗……", "0", "cv_iria_17", "0", "0"},
[420520] = {420520, 12005, 21, 15, "0", "0", "It's\u{0020}not\u{0020}enough...", "まだまだ足りない……", "還不夠……", "0", "还不够……", "0", "cv_iria_18", "0", "0"},
[420521] = {420521, 12005, 23, 16, "0", "0", "Burn\u{0020}to\u{0020}ash!", "灰燼に帰せ！", "化為灰燼吧！", "0", "化为灰烬吧！", "0", "cv_iria_20", "0", "0"},
[420522] = {420522, 12005, 24, 17, "0", "0", "Pierce!", "牙突！", "突刺！", "0", "突刺！", "0", "cv_iria_22", "0", "0"},
[420523] = {420523, 12005, 25, 18, "0", "0", "I'll\u{0020}never\u{0020}forget!", "決して忘れたりしない！", "我絕對不會忘記！", "0", "我绝对不会忘记！", "0", "cv_iria_23", "0", "0"},
[420524] = {420524, 12005, 22, 38, "0", "0", "No\u{0020}mistakes\u{0020}allowed...", "絶対、失敗しないから……", "萬無一失……", "0", "万无一失……", "0", "cv_iria_19", "0", "0"},
[420525] = {420525, 12005, 26, 19, "0", "0", "I\u{0020}never\u{0020}expected\u{0020}my\u{0020}anger\u{0020}to\u{0020}fade\u{0020}this\u{0020}way.", "まさか私の怒りがこんな形で消えてしまうなんて……", "沒想到，我的怒火會以這種方式熄滅啊。", "0", "没想到，我的怒火会以这种方式熄灭啊。", "0", "cv_iria_21", "0", "0"},
[420526] = {420526, 12005, 27, 20, "0", "0", "Boss?\u{0020}Oh\u{0020}no,\u{0020}I\u{0020}mean\u{0020}Navigator.\u{0020}This\u{0020}cleanup's\u{0020}all\u{0020}yours.", "ボス？ああっ、じゃなくて！ナビゲーターだったよね。清掃、頼んだよ。", "老闆？啊不對不對！應該是領航。這次的清潔工作就拜託你了。", "0", "老板？啊不对不对！应该是领航。这次的清洁工作就拜托你了。", "0", "cv_iria_24", "0", "0"},
[420527] = {420527, 12005, 28, 21, "0", "0", "Didn't\u{0020}expect\u{0020}these\u{0020}perks\u{0020}from\u{0020}working\u{0020}at\u{0020}AEGIS.", "アイギスで働くとこんな福利厚生も付くだなんて。", "沒想到在艾吉斯工作還能有這種待遇啊。", "0", "没想到在艾吉斯工作还能有这种待遇啊。", "0", "cv_iria_25", "0", "0"},
[420528] = {420528, 12005, 29, 21, "0", "0", "I'm\u{0020}not\u{0020}one\u{0020}for\u{0020}luxury,\u{0020}but\u{0020}I\u{0020}have\u{0020}to\u{0020}admit,\u{0020}this\u{0020}is\u{0020}pretty\u{0020}nice.", "私、享楽主義者じゃないけど……でもやっぱり、気持ちいいな。", "貪圖享樂雖然不是我的風格，但是不得不說，實在是太舒服了。", "0", "贪图享乐虽然不是我的风格，但是不得不说，实在是太舒服了。", "0", "cv_iria_26", "0", "0"},
[420529] = {420529, 12005, 30, 22, "0", "0", "Watch\u{0020}your\u{0020}step.", "足元に気を付けて。", "請小心腳下。", "0", "请小心脚下。", "0", "cv_iria_27", "0", "0"},
[420530] = {420530, 12005, 31, 23, "0", "0", "If\u{0020}you\u{0020}can't\u{0020}guess,\u{0020}I'll\u{0020}get\u{0020}mad.", "分からなかったら怒るよ？", "猜不出來的話我可是會生氣的喔。", "0", "猜不出来的话我可是会生气的哦。", "0", "cv_iria_28", "0", "0"},
[420531] = {420531, 12005, 32, 24, "0", "0", "It's\u{0020}been\u{0020}so\u{0020}long\u{0020}since\u{0020}someone\u{0020}cared\u{0020}about\u{0020}me\u{0020}like\u{0020}this.", "久しぶりに私のことをこんなに大事にしてくれる人に出会えたって感じ。", "很久都沒有人這麼在乎過我了。", "0", "很久都没有人这么在乎过我了。", "0", "cv_iria_29", "0", "0"},
[420532] = {420532, 12005, 33, 25, "0", "0", "Of\u{0020}course,\u{0020}I\u{0020}wouldn't\u{0020}really\u{0020}get\u{0020}mad—just\u{0020}a\u{0020}little\u{0020}disappointed.", "怒ってないけど、ちょっとがっかりしたかな。", "我當然不會真的生氣，只不過稍微有些失落罷了。", "0", "我当然不会真的生气，只不过稍微有些失落罢了。", "0", "cv_iria_30", "0", "0"},
[420533] = {420533, 12005, 34, 26, "0", "0", "This\u{0020}place\u{0020}is\u{0020}so\u{0020}spacious\u{0020}and\u{0020}warm...\u{0020}It's\u{0020}been\u{0020}a\u{0020}while\u{0020}since\u{0020}I\u{0020}rested\u{0020}somewhere\u{0020}like\u{0020}this.", "ここって広くて温かいよね。こんな所で休憩するなんて久しぶり。", "這裡還真是寬敞溫暖啊，好久都沒有在這種環境中休息了。", "0", "这里还真是宽敞温暖啊，好久都没有在这种环境中休息了。", "0", "cv_iria_33", "0", "0"},
[420534] = {420534, 12005, 35, 27, "0", "0", "Your\u{0020}story\u{0020}must\u{0020}be\u{0020}full\u{0020}of\u{0020}hope,\u{0020}right?", "あんたの物語はきっと、希望に満ちてるよ。", "屬於你的故事，一定充滿了希望吧。", "0", "属于你的故事，一定充满了希望吧。", "0", "cv_iria_35", "0", "0"},
[420535] = {420535, 12005, 36, 28, "0", "0", "Better\u{0020}deal\u{0020}with\u{0020}things\u{0020}before\u{0020}this\u{0020}body\u{0020}starts\u{0020}breaking\u{0020}down.", "この身体が腐り果てる前にさっさと片付けよう。", "在這副軀體腐朽之前趁早解決掉吧。", "0", "在这副躯体腐朽之前趁早解决掉吧。", "0", "cv_iria_36", "0", "0"},
[420536] = {420536, 12005, 37, 29, "0", "0", "So\u{0020}this\u{0020}is\u{0020}what\u{0020}the\u{0020}official\u{0020}army\u{0020}is\u{0020}like,\u{0020}huh?", "これが正規軍なの？", "這就是正規軍嗎？", "0", "这就是正规军吗？", "0", "cv_iria_37", "0", "0"},
[420537] = {420537, 12005, 38, 30, "0", "0", "Expanding\u{0020}the\u{0020}ranks\u{0020}is\u{0020}always\u{0020}a\u{0020}good\u{0020}thing.", "兵力を拡充することは良いことだし。", "擴充兵力總是一件好事。", "0", "扩充兵力总是一件好事。", "0", "cv_iria_38", "0", "0"},
[420538] = {420538, 12005, 39, 31, "0", "0", "Is\u{0020}this\u{0020}AEGIS\u{0020}gear?", "これがアイギスの装備なの？", "這些就是艾吉斯的裝備嗎？", "0", "这些就是艾吉斯的装备吗？", "0", "cv_iria_39", "0", "0"},
