[420543] = {420543, 12005, 44, 36, "0", "0", "There\u{0020}aren't\u{0020}any\u{0020}info\u{0020}brokers\u{0020}here,\u{0020}right?", "情報商人がいたりしないよね？", "這裡應該不會有情報販子吧。", "0", "这里应该不会有情报贩子吧。", "0", "cv_iria_44", "0", "0"},
