[420700] = {420700, 12007, 1, 1, "0", "0", "Haze\u{0020}reverb!", "蒼霧残響（ハツリバーブ）！", "蒼霧殘響！", "0", "苍雾残响！", "0", "cv_kamu_32", "0", "0"},
[420701] = {420701, 12007, 2, 2, "0", "0", "Don't\u{0020}worry,\u{0020}I'll\u{0020}guard\u{0020}the\u{0020}entrance\u{0020}for\u{0020}you!", "安心しろ、この入り口は、オレが守ってやるから！", "放心好了，我會替你守住大門的！", "0", "放心好了，我会替你守住大门的！", "0", "cv_kamu_2", "0", "0"},
[420702] = {420702, 12007, 3, 3, "0", "0", "Hey~\u{0020}Finally,\u{0020}we\u{0020}meet,\u{0020}Danube's\u{0020}Navigator!\u{0020}My\u{0020}name's\u{0020}Huameng—don't\u{0020}forget\u{0020}it!", "ヤッホー。やっと会えたな、ダニューブのナビゲーター。オレの名は華夢。忘れるなよ。", "呀吼~終於見面了呢，多瑙的領航。小生的名字是華夢，可千萬不要忘記啊。", "0", "呀吼~终于见面了呢，多瑙的领航。小生的名字是华梦，可千万不要忘记啊。", "0", "cv_kamu_1", "0", "0"},
[420703] = {420703, 12007, 4, 4, "0", "idle", "Hah—!\u{0020}This\u{0020}place\u{0020}is\u{0020}way\u{0020}too\u{0020}small!\u{0020}I\u{0020}can\u{0020}barely\u{0020}move!", "はっ――やっ――！狭すぎ！ここ、本当に狭すぎる！体、動かせないじゃん！", "喝——啊——！太小了！這裡實在是太過於狹小了！完全施展不開拳腳！", "0", "喝——啊——！太小了！这里实在是太过于狭小了！完全施展不开拳脚！", "0", "cv_kamu_3", "0", "0"},
[420704] = {420704, 12007, 5, 4, "0", "idle", "Today's\u{0020}perfect\u{0020}for\u{0020}a\u{0020}walk.\u{0020}If\u{0020}you're\u{0020}free,\u{0020}let's\u{0020}go\u{0020}for\u{0020}one.\u{0020}They\u{0020}say\u{0020}it's\u{0020}important\u{0020}to\u{0020}balance\u{0020}work\u{0020}and\u{0020}relaxation,\u{0020}after\u{0020}all.", "今日は遠足日和だ。できればお前と一緒に出掛けたいな。まぁ、仕事と休みはバランスよく取るべきだし。たまには他のことをやってみて、リラックスしたらどうだ？", "今天是個適合踏青的好日子呢，如果可以的話真想和你一起出去走走啊。正所謂勞逸結合，偶爾也去做點其他事情放鬆下吧。", "0", "今天是个适合踏青的好日子呢，如果可以的话真想和你一起出去走走啊。正所谓劳逸结合，偶尔也去做点其他事情放松下吧。", "0", "cv_kamu_4", "0", "0"},
[420705] = {420705, 12007, 6, 4, "0", "idle", "Caihua\u{0020}and\u{0020}Hualian\u{0020}aren't\u{0020}easy\u{0020}opponents,\u{0020}but\u{0020}Caihua\u{0020}scares\u{0020}me\u{0020}more—she's\u{0020}always\u{0020}using\u{0020}dangerous\u{0020}weapons.", "彩華も華恋も、見くびっちゃいけない相手だ。まぁ、オレは彩華の方が苦手だな。あいつ、いつも危ない武器を使ってるからさ。", "無論是彩華還是華戀，她們都不是可以輕視的對手啊。不過小生還是更加害怕和彩華交手，那個傢伙總是會使用非常危險的武器呢。", "0", "无论是彩华还是华恋，她们都不是可以轻视的对手啊。不过小生还是更加害怕和彩华交手，那个家伙总是会使用非常危险的武器呢。", "0", "cv_kamu_29", "0", "0"},
[420706] = {420706, 12007, 7, 5, "1_》_0_0.8", "level1", "I'm\u{0020}not\u{0020}interested\u{0020}in\u{0020}anything\u{0020}except\u{0020}training.", "修行以外のことには興味ないな。", "小生對於修行之外的事情沒有興趣。", "0", "小生对于修行之外的事情没有兴趣。", "0", "cv_kamu_30", "0", "0"},
[420707] = {420707, 12007, 8, 5, "1_》_0_0.8", "level1", "Tianhua\u{0020}Pavilion...\u{0020}it's\u{0020}more\u{0020}like\u{0020}a\u{0020}training\u{0020}unit\u{0020}than\u{0020}a\u{0020}combat\u{0020}one.\u{0020}Martial\u{0020}arts\u{0020}is\u{0020}just\u{0020}part\u{0020}of\u{0020}our\u{0020}daily\u{0020}routine.", "天華閣……作戦部隊っていうより、修行部隊って言うべきか。こうして武芸の練習をするのはオレたちの日常だし。", "天華閣…與其說是作戰部隊不如說是修行部隊呢，像這樣習武是我們的日常。", "0", "天华阁…与其说是作战部队不如说是修行部队呢，像这样习武是我们的日常。", "0", "cv_kamu_5", "0", "0"},
[420708] = {420708, 12007, 9, 5, "1_》_100_1.5", "level2", "Pushing\u{0020}our\u{0020}bodies\u{0020}and\u{0020}skills\u{0020}to\u{0020}the\u{0020}limit\u{0020}is\u{0020}the\u{0020}goal,\u{0020}but\u{0020}for\u{0020}me,\u{0020}there's\u{0020}something\u{0020}else\u{0020}I\u{0020}need\u{0020}to\u{0020}train—my\u{0020}\"qi.\"", "体とスキルを限界まで鍛える事は確かにオレたちが求めてることだ。でも、個人的にはもう一つ鍛えなきゃならないものがある。そう、気のことだ。", "將身體與技巧都鍛煉到極致確實是我們的追求。但是，就我個人來說的話，還有需要鍛煉的事物。沒錯，那便是氣。", "0", "将身体与技巧都锻炼到极致确实是我们的追求。但是，就我个人来说的话，还有需要锻炼的事物。没错，那便是气。", "0", "cv_kamu_6", "0", "0"},
[420709] = {420709, 12007, 10, 5, "1_》_500_2", "level3", "The\u{0020}price\u{0020}of\u{0020}being\u{0020}obsessed\u{0020}with\u{0020}training...\u{0020}is\u{0020}realizing\u{0020}I'm\u{0020}this\u{0020}old\u{0020}now.\u{0020}I\u{0020}don't\u{0020}even\u{0020}remember\u{0020}having\u{0020}a\u{0020}childhood.\u{0020}It's...\u{0020}kind\u{0020}of\u{0020}sad.", "修行に夢中になることの代償と言えば……まぁ、気付いたらもうこんな年になっちゃった、ぐらいか。そういえばオレ、いわゆる子供時代ってものの記憶がないんだ。ちょっと……残念だな。", "癡迷修行的代價嘛……估計就是回過神來才發現自己已經到這個歲數了吧。說起來，在我的記憶中似乎並沒有所謂的童年呢。稍微……有點遺憾啊。", "0", "痴迷修行的代价嘛……估计就是回过神来才发现自己已经到这个岁数了吧。说起来，在我的记忆中似乎并没有所谓的童年呢。稍微……有点遗憾啊。", "0", "cv_kamu_7", "0", "0"},
[420710] = {420710, 12007, 11, 5, "1_》_1000_2.5", "level4", "Training\u{0020}cost\u{0020}me\u{0020}a\u{0020}lot,\u{0020}but\u{0020}when\u{0020}I\u{0020}look\u{0020}at\u{0020}who\u{0020}I've\u{0020}become,\u{0020}it\u{0020}was\u{0020}all\u{0020}worth\u{0020}it.\u{0020}And\u{0020}more\u{0020}importantly,\u{0020}it's\u{0020}because\u{0020}of\u{0020}training\u{0020}that\u{0020}I\u{0020}met\u{0020}you.", "確かにオレは修行のせいで沢山のものを失った。でも、今の自分を見たら、全ては意味があることだったと確信できる。修行のお陰でお前に出会えたんだ。", "修行確實讓我失去了很多東西，但是一想到今天的自己，那麼這一切便都有了意義。更加重要的是，正是因為修行，我才認識了你。", "0", "修行确实让我失去了很多东西，但是一想到今天的自己，那么这一切便都有了意义。更加重要的是，正是因为修行，我才认识了你。", "0", "cv_kamu_8", "0", "0"},
[420711] = {420711, 12007, 12, 6, "0", "0", "With\u{0020}this,\u{0020}training\u{0020}will\u{0020}be\u{0020}a\u{0020}lot\u{0020}easier.\u{0020}Thanks!", "助力があれば、修行も多少楽になるよな？ありがとう！", "有了這些的幫助修行也會輕鬆不少吧？多謝了！", "0", "有了这些的帮助修行也会轻松不少吧？多谢了！", "0", "cv_kamu_9", "0", "0"},
[420712] = {420712, 12007, 13, 7, "0", "0", "My\u{0020}body\u{0020}and\u{0020}skills...\u{0020}both\u{0020}improved!", "肉体、スキル……全部精進したんだ！", "肉體，技巧……都得到提升了呢！", "0", "肉体，技巧……都得到提升了呢！", "0", "cv_kamu_10", "0", "0"},
[420713] = {420713, 12007, 14, 8, "0", "0", "So\u{0020}this\u{0020}is\u{0020}the\u{0020}essence\u{0020}of\u{0020}martial\u{0020}arts?\u{0020}Thank\u{0020}you!\u{0020}You've\u{0020}taken\u{0020}me\u{0020}to\u{0020}a\u{0020}whole\u{0020}new\u{0020}level!", "これが武道の真髄なのか？ありがとう！オレを新しい領域へと導いてくれて！", "這就是武學的真髓嗎？非常感謝！謝謝你將我帶到了新的領域！", "0", "这就是武学的真髓吗？非常感谢！谢谢你将我带到了新的领域！", "0", "cv_kamu_11", "0", "0"},
[420714] = {420714, 12007, 15, 9, "0", "0", "My\u{0020}qi\u{0020}has\u{0020}become\u{0020}even\u{0020}purer!", "気の純度が上がったな！", "氣的純度提升了！", "0", "气的纯度提升了！", "0", "cv_kamu_12", "0", "0"},
[420715] = {420715, 12007, 16, 10, "0", "0", "Pitiful\u{0020}creatures,\u{0020}I'll\u{0020}be\u{0020}the\u{0020}one\u{0020}to\u{0020}defeat\u{0020}you.", "悲しい生き物だ。さぁ、オレが倒してやる！", "可悲的生物啊，接下來就由我來打倒你們。", "0", "可悲的生物啊，接下来就由我来打倒你们。", "0", "cv_kamu_13", "0", "0"},
[420716] = {420716, 12007, 17, 11, "0", "0", "All\u{0020}threats\u{0020}are\u{0020}gone,\u{0020}as\u{0020}expected—martial\u{0020}arts\u{0020}are\u{0020}the\u{0020}strongest!", "全部片付けられたな。やっぱり、武術は最強だ！", "全部都解決乾淨了呢，果然，武術是最強的！", "0", "全部都解决干净了呢，果然，武术是最强的！", "0", "cv_kamu_14", "0", "0"},
[420717] = {420717, 12007, 18, 12, "0", "0", "I\u{0020}should\u{0020}have\u{0020}unleashed\u{0020}all\u{0020}my\u{0020}qi\u{0020}from\u{0020}the\u{0020}start...", "こうなると知ってたなら、全ての気を出しとけばよかった……", "早知道如此就將全部的氣都給釋放出來了……", "0", "早知道如此就将全部的气都给释放出来了……", "0", "cv_kamu_15", "0", "0"},
[420718] = {420718, 12007, 19, 13, "0", "0", "Looks\u{0020}like\u{0020}I\u{0020}need\u{0020}more\u{0020}training.", "まだまだ修行が必要みたいだな", "看來我還需要進行修行啊。", "0", "看来我还需要进行修行啊。", "0", "cv_kamu_16", "0", "0"},
[420719] = {420719, 12007, 20, 14, "0", "0", "If\u{0020}possible,\u{0020}may\u{0020}I\u{0020}undergo\u{0020}harsher\u{0020}training?", "よかったら……苦行、してもいいか？", "可以的話……能讓我進行苦修嗎？", "0", "可以的话……能让我进行苦修吗？", "0", "cv_kamu_17", "0", "0"},
[420720] = {420720, 12007, 21, 15, "0", "0", "Creatures\u{0020}that\u{0020}can't\u{0020}train\u{0020}are\u{0020}truly\u{0020}pitiful.", "修行できない生き物だなんて、哀れなヤツだな。", "無法修行的生物，真是可悲啊。", "0", "无法修行的生物，真是可悲啊。", "0", "cv_kamu_18", "0", "0"},
[420721] = {420721, 12007, 23, 16, "0", "0", "Ha!", "はっ！", "哈！", "0", "哈！", "0", "cv_kamu_20", "0", "0"},
[420722] = {420722, 12007, 22, 38, "0", "0", "Heeyah.", "ふう", "嘿咻。", "0", "嘿咻。", "0", "cv_kamu_19", "0", "0"},
[420723] = {420723, 12007, 26, 19, "0", "0", "Looks\u{0020}like\u{0020}my\u{0020}training\u{0020}ends\u{0020}here.", "どうやらオレの修行はここまでのようだ。", "看來我的修行，也到此為止了。", "0", "看来我的修行，也到此为止了。", "0", "cv_kamu_21", "0", "0"},
[420724] = {420724, 12007, 27, 20, "0", "0", "Underwater's\u{0020}the\u{0020}perfect\u{0020}place\u{0020}to\u{0020}train.", "水の中っていうのは修行に最適だ。", "水下可是非常適合修行的場所呢。", "0", "水下可是非常适合修行的场所呢。", "0", "cv_kamu_22", "0", "0"},
[420725] = {420725, 12007, 28, 21, "0", "0", "This\u{0020}is\u{0020}patience\u{0020}training.", "これは定力の修行だぞ。", "這是定力的修行喔。", "0", "这是定力的修行哦。", "0", "cv_kamu_23", "0", "0"},
[420726] = {420726, 12007, 29, 21, "0", "0", "I\u{0020}can't\u{0020}help\u{0020}but\u{0020}relax\u{0020}during\u{0020}a\u{0020}bath~", "お風呂に入ると何だかんだ気が緩むな。", "洗澡的時候總會忍不住放鬆下來啊~", "0", "洗澡的时候总会忍不住放松下来啊~", "0", "cv_kamu_24", "0", "0"},
[420727] = {420727, 12007, 30, 22, "0", "0", "Infuse\u{0020}your\u{0020}weapon\u{0020}with\u{0020}qi!", "気を武器に注ぎ込め！", "將氣注入武器吧！", "0", "将气注入武器吧！", "0", "cv_kamu_25", "0", "0"},
[420728] = {420728, 12007, 31, 23, "0", "0", "Show\u{0020}the\u{0020}results\u{0020}of\u{0020}your\u{0020}training!", "修行の成果を見せてくれ！", "來展示下修行過後的結果吧！", "0", "来展示下修行过后的结果吧！", "0", "cv_kamu_26", "0", "0"},
[420729] = {420729, 12007, 32, 24, "0", "0", "Did\u{0020}you\u{0020}figure\u{0020}it\u{0020}out\u{0020}with\u{0020}qi?\u{0020}Or\u{0020}was\u{0020}it\u{0020}something\u{0020}else...?", "気で分かったのか？それとも……", "是通過氣來分辨出來的嗎？還是說……", "0", "是通过气来分辨出来的吗？还是说……", "0", "cv_kamu_27", "0", "0"},
[420730] = {420730, 12007, 33, 25, "0", "0", "Both\u{0020}of\u{0020}us\u{0020}haven't\u{0020}trained\u{0020}enough\u{0020}yet.", "お前もオレも、まだまだ修行が足りないな。", "無論是你我，修行還都不夠啊。", "0", "无论是你我，修行还都不够啊。", "0", "cv_kamu_28", "0", "0"},
[420731] = {420731, 12007, 34, 26, "0", "0", "Ah,\u{0020}Navigator,\u{0020}you're\u{0020}back?\u{0020}I'll\u{0020}pause\u{0020}my\u{0020}training.", "ああ、お帰り、ナビゲーター！待ってくれ、すぐに修行を終えるから。", "啊，領航你回來了嗎？小生這就中斷修行。", "0", "啊，领航你回来了吗？小生这就中断修行。", "0", "cv_kamu_31", "0", "0"},
[420732] = {420732, 12007, 35, 27, "0", "0", "Let's\u{0020}head\u{0020}to\u{0020}the\u{0020}next\u{0020}battlefield.", "新しい戦場に向かおう。", "前往新的戰場吧。", "0", "前往新的战场吧。", "0", "cv_kamu_33", "0", "0"},
[420733] = {420733, 12007, 36, 28, "0", "0", "Only\u{0020}through\u{0020}harsh\u{0020}training\u{0020}can\u{0020}we\u{0020}sharpen\u{0020}ourselves.", "人は苦行の中でのみ、自分を磨けるからな。", "人只有在苦修中才能磨練自己。", "0", "人只有在苦修中才能磨练自己。", "0", "cv_kamu_34", "0", "0"},
[420734] = {420734, 12007, 37, 29, "0", "0", "Everyone,\u{0020}push\u{0020}yourselves\u{0020}through\u{0020}tough\u{0020}training!", "皆、苦行で自分を磨こう！", "各位，在苦修中磨練自己吧！", "0", "各位，在苦修中磨练自己吧！", "0", "cv_kamu_35", "0", "0"},
