[420736] = {420736, 12007, 39, 31, "0", "0", "Danube's\u{0020}gear\u{0020}is\u{0020}pretty\u{0020}interesting.", "ダニューブの装備って面白いな。", "多瑙的裝備還真是有趣啊。", "0", "多瑙的装备还真是有趣啊。", "0", "cv_kamu_37", "0", "0"},
