[421201] = {421201, 12012, 2, 2, "0", "0", "You've\u{0020}got\u{0020}guts,\u{0020}huh?\u{0020}I\u{0020}hope\u{0020}you're\u{0020}mentally\u{0020}prepared.", "アタシにこんなことをさせるなんて、良い度胸ね。覚悟はできてるのかしら？", "真是有勇氣呢，想必你也做好了相應的心理準備了吧？", "0", "真是有勇气呢，想必你也做好了相应的心理准备了吧？", "0", "cv_jyuria_2", "0", "0"},
[421202] = {421202, 12012, 3, 3, "0", "0", "Heh,\u{0020}so\u{0020}you're\u{0020}the\u{0020}Navigator?\u{0020}Pretty\u{0020}ordinary,\u{0020}aren't\u{0020}you?\u{0020}I'm\u{0020}Julia,\u{0020}Julia\u{0020}Fox,\u{0020}captain\u{0020}of\u{0020}the\u{0020}Hurricane\u{0020}Shock.\u{0020}Let's\u{0020}\"get\u{0020}along,\"\u{0020}shall\u{0020}we?", "ふん、アンタがナビゲーター？……なんか普通ね。アタシはジュリア。ジュリア・フォックス。颶風突撃隊の隊長よ。仲良くしましょうね。", "呵，你就是領航嗎，看起來很普通呢。我是茱莉亞，茱莉亞·福克斯，颶風突擊隊的隊長，讓我們“友好相處”吧~", "0", "呵，你就是领航吗，看起来很普通呢。我是茱莉亚，茱莉亚·福克斯，飓风突击队的队长，让我们“友好相处”吧~", "0", "cv_jyuria_1", "0", "0"},
[421203] = {421203, 12012, 4, 4, "0", "idle", "I'm\u{0020}thirsty...\u{0020}Hey,\u{0020}idiot,\u{0020}yeah,\u{0020}I'm\u{0020}talking\u{0020}to\u{0020}you.\u{0020}Go\u{0020}get\u{0020}me\u{0020}a\u{0020}drink.", "喉が乾いたわ。……ねえ、そこのブタ野郎。そう、アンタのことよ。さっさと飲み物を買ってきて。", "口渴了呢…笨豬，對，就是在說你，快去幫我買喝的過來。", "0", "口渴了呢…笨猪，对，就是在说你，快去帮我买喝的过来。", "0", "cv_jyuria_3", "0", "0"},
[421204] = {421204, 12012, 5, 4, "0", "idle", "Stop\u{0020}making\u{0020}pig-like\u{0020}noises!\u{0020}Can't\u{0020}you\u{0020}show\u{0020}some\u{0020}dignity?", "ブタみたいな声を出さないでくれる？プライドってものがないのかしら？", "不要發出豬一樣的叫聲！就不能矜持一點嗎？", "0", "不要发出猪一样的叫声！就不能矜持一点吗？", "0", "cv_jyuria_4", "0", "0"},
[421205] = {421205, 12012, 6, 4, "0", "idle", "Idiot,\u{0020}did\u{0020}you\u{0020}see\u{0020}Celine\u{0020}today?\u{0020}No?\u{0020}Hmm...\u{0020}then\u{0020}you'll\u{0020}have\u{0020}to\u{0020}do.\u{0020}Don't\u{0020}run\u{0020}away!\u{0020}Ugh,\u{0020}what\u{0020}a\u{0020}scared\u{0020}little\u{0020}pig\u{0020}you\u{0020}are.", "ブタ。シリンを見かけなかった？見てないの？……ふーん。しょうがないわね。代わりにアンタを……あ、ちょっと！何逃げてんのよ！……なんて憶病なブタかしら。", "笨豬，你今天看見棲琳了嗎？沒有嗎？嗯…這樣的話，就拿你來替代吧…喂，別跑啊，真是的，真膽小豬呢。", "0", "笨猪，你今天看见栖琳了吗？没有吗？嗯…这样的话，就拿你来替代吧…喂，别跑啊，真是的，真胆小猪呢。", "0", "cv_jyuria_29", "0", "0"},
[421206] = {421206, 12012, 7, 5, "1_》_0_0.8", "level1", "A\u{0020}rich\u{0020}girl?\u{0020}Is\u{0020}that\u{0020}what\u{0020}Jenny\u{0020}told\u{0020}you?\u{0020}What\u{0020}a\u{0020}dull\u{0020}joke.\u{0020}Money\u{0020}and\u{0020}power\u{0020}mean\u{0020}nothing\u{0020}to\u{0020}me.", "お金持ちのお嬢様？ジェニィからそう聞いたの？ふん、くだらない冗談ね。お金と権力なんてカスみたいなもの、私にとってはなんの意味もないわ。", "有錢人家的大小姐？燕妮是這麼跟你說的嗎？真是無趣的笑話。金錢與權力，這種渣滓一樣東西對我來說一點意義也沒有。", "0", "有钱人家的大小姐？燕妮是这么跟你说的吗？真是无趣的笑话。金钱与权力，这种渣滓一样东西对我来说一点意义也没有。", "0", "cv_jyuria_30", "0", "0"},
[421207] = {421207, 12012, 8, 5, "1_》_0_0.8", "level1", "Don't\u{0020}touch\u{0020}me,\u{0020}idiot.", "なに勝手に触ってるの。ブタ野郎。", "不要隨便碰我，笨豬。", "0", "不要随便碰我，笨猪。", "0", "cv_jyuria_5", "0", "0"},
[421208] = {421208, 12012, 9, 5, "1_》_100_1.5", "level2", "Idiot,\u{0020}you\u{0020}just\u{0020}touched\u{0020}me,\u{0020}didn't\u{0020}you?\u{0020}Was\u{0020}it\u{0020}this\u{0020}hand?\u{0020}Okay,\u{0020}stretch\u{0020}it\u{0020}out.\u{0020}Don't\u{0020}be\u{0020}scared—it'll\u{0020}hurt\u{0020}at\u{0020}first,\u{0020}but\u{0020}you\u{0020}might\u{0020}just\u{0020}end\u{0020}up\u{0020}liking\u{0020}it—hiya!", "このブタ、今アタシに触ったわね。触ったのはこの手かしら？いいわ。大人しくその手を出して。大丈夫、最初は痛いけど、だんだんその痛みも愛しくなるわ。……ヘイヤー！", "笨豬，你剛剛碰我了吧。是這只手嗎？好的，乖乖把手伸出來。別害怕，剛開始會很痛，但之後你一定會喜歡上這種感覺的——嘿呀！", "0", "笨猪，你刚刚碰我了吧。是这只手吗？好的，乖乖把手伸出来。别害怕，刚开始会很痛，但之后你一定会喜欢上这种感觉的——嘿呀！", "0", "cv_jyuria_6", "0", "0"},
[421209] = {421209, 12012, 10, 5, "1_》_500_2", "level3", "You\u{0020}keep\u{0020}coming\u{0020}back\u{0020}to\u{0020}me,\u{0020}even\u{0020}after\u{0020}all\u{0020}the\u{0020}beatings?\u{0020}Heh,\u{0020}you're\u{0020}really\u{0020}starting\u{0020}to\u{0020}intrigue\u{0020}me,\u{0020}idiot.", "何度もムチに叩かれて、まだアタシに近づくつもり？フフフ……ブタ野郎。だんだんお前に興味が出てきたわ。", "不管被鞭打多少次都要接近我嗎？呵呵，笨豬，你讓我感興趣了呢。", "0", "不管被鞭打多少次都要接近我吗？呵呵，笨猪，你让我感兴趣了呢。", "0", "cv_jyuria_7", "0", "0"},
[421210] = {421210, 12012, 11, 5, "1_》_1000_2.5", "level4", "...Hey,\u{0020}idiot,\u{0020}you\u{0020}touched\u{0020}me\u{0020}again,\u{0020}didn't\u{0020}you?\u{0020}I'm\u{0020}done\u{0020}playing\u{0020}nice.\u{0020}After\u{0020}work,\u{0020}come\u{0020}to\u{0020}my\u{0020}room!\u{0020}Hehehe...\u{0020}I'll\u{0020}show\u{0020}you\u{0020}what\u{0020}real\u{0020}hell\u{0020}is.", "……信じられない。このアホブタ、またアタシを触るなんて。……もう我慢できないわ。今日の仕事が終わったらアタシの部屋に来るのよ！フフフ…アンタに本物の地獄を見せてあげるわ。", "…喂，笨豬，你又碰我了是吧……我已經忍無可忍了。今天工作結束之後，到我的房間裡來！呵呵呵呵呵…我要讓你明白，什麼是真正的地獄。", "0", "…喂，笨猪，你又碰我了是吧……我已经忍无可忍了。今天工作结束之后，到我的房间里来！呵呵呵呵呵…我要让你明白，什么是真正的地狱。", "0", "cv_jyuria_8", "0", "0"},
[421211] = {421211, 12012, 12, 6, "0", "0", "Hmm,\u{0020}not\u{0020}bad.", "ふーん。まあまあね。", "嗯，馬馬虎虎吧。", "0", "嗯，马马虎虎吧。", "0", "cv_jyuria_9", "0", "0"},
[421212] = {421212, 12012, 13, 7, "0", "0", "Of\u{0020}course,\u{0020}you\u{0020}should\u{0020}worship\u{0020}me.", "アタシに仕えるのは当然のことよ。", "供奉我是理所當然的。", "0", "供奉我是理所当然的。", "0", "cv_jyuria_10", "0", "0"},
[421213] = {421213, 12012, 14, 8, "0", "0", "You've\u{0020}gone\u{0020}this\u{0020}far...\u{0020}even\u{0020}I\u{0020}want\u{0020}to\u{0020}praise\u{0020}you.\u{0020}But\u{0020}don't\u{0020}get\u{0020}ahead\u{0020}of\u{0020}yourself!\u{0020}Doing\u{0020}all\u{0020}this\u{0020}for\u{0020}me\u{0020}is\u{0020}what\u{0020}you're\u{0020}supposed\u{0020}to\u{0020}do...\u{0020}Ahem,\u{0020}Navigator,\u{0020}don't\u{0020}you\u{0020}have\u{0020}something\u{0020}else\u{0020}to\u{0020}say\u{0020}to\u{0020}me?", "まさかここまでするなんて……こんなの、さすがのアタシも褒めるしか……なによ！あまり調子に乗らないでちょうだい！こんなの、当たり前のことよ……。おい、ブタ。……ナビゲーター！アタシに何か、言いたいことはないの？", "居然做到這一步…連我也忍不住想要誇獎你呢……不過，不要太得意忘形了！為我付出這麼多是你應該做的……咳咳，喂，豬…領航，你就沒有什麼其他想對我說的嗎？", "0", "居然做到这一步…连我也忍不住想要夸奖你呢……不过，不要太得意忘形了！为我付出这么多是你应该做的……咳咳，喂，猪…领航，你就没有什么其他想对我说的吗？", "0", "cv_jyuria_11", "0", "0"},
[421214] = {421214, 12012, 15, 9, "0", "0", "This\u{0020}is\u{0020}your\u{0020}honor.", "光栄に思うことね。", "這是你的榮幸。", "0", "这是你的荣幸。", "0", "cv_jyuria_12", "0", "0"},
[421215] = {421215, 12012, 16, 10, "0", "0", "Servants,\u{0020}serve\u{0020}me\u{0020}well.", "下僕ども。アタシに従うのよ。", "僕從們，為我服務吧。", "0", "仆从们，为我服务吧。", "0", "cv_jyuria_13", "0", "0"},
[421216] = {421216, 12012, 17, 11, "0", "0", "Now\u{0020}this\u{0020}is\u{0020}how\u{0020}a\u{0020}battle\u{0020}should\u{0020}be\u{0020}fought.", "アタシに相応しい戦闘だったわ。", "這才是與我相配的作戰方式。", "0", "这才是与我相配的作战方式。", "0", "cv_jyuria_14", "0", "0"},
[421217] = {421217, 12012, 18, 12, "0", "0", "Can't\u{0020}even\u{0020}handle\u{0020}a\u{0020}simple\u{0020}task?", "こんなことも上手くできないの？", "連這點小事都做不好嗎？", "0", "连这点小事都做不好吗？", "0", "cv_jyuria_15", "0", "0"},
[421218] = {421218, 12012, 19, 13, "0", "0", "Looks\u{0020}like\u{0020}you\u{0020}idiots\u{0020}and\u{0020}servants\u{0020}need\u{0020}some\u{0020}whipping.", "アホブタと下僕どもには、鞭が必要なようね。", "看來，笨豬和僕從們很需要我的鞭打啊。", "0", "看来，笨猪和仆从们很需要我的鞭打啊。", "0", "cv_jyuria_16", "0", "0"},
[421219] = {421219, 12012, 20, 14, "0", "0", "Spineless\u{0020}pig!\u{0020}Giving\u{0020}up\u{0020}over\u{0020}a\u{0020}little\u{0020}setback?\u{0020}Pull\u{0020}yourself\u{0020}together!", "この能無しブタ野郎！こんなことで諦めるなんて許さないわよ！", "沒骨氣的豬！這點挫折你就放棄了嗎，給我振作起來！", "0", "没骨气的猪！这点挫折你就放弃了吗，给我振作起来！", "0", "cv_jyuria_17", "0", "0"},
[421220] = {421220, 12012, 21, 15, "0", "0", "Such\u{0020}sweet\u{0020}screams.", "心地いい悲鳴ね。", "真是動聽的慘叫。", "0", "真是动听的惨叫。", "0", "cv_jyuria_18", "0", "0"},
[421221] = {421221, 12012, 23, 16, "0", "0", "Scream\u{0020}for\u{0020}me,\u{0020}let\u{0020}me\u{0020}hear\u{0020}your\u{0020}cries\u{0020}of\u{0020}pain.", "悲鳴よ。お前たちの悲鳴が聞きたいの。", "悲鳴吧，讓我聽聽你們的悲鳴吧。", "0", "悲鸣吧，让我听听你们的悲鸣吧。", "0", "cv_jyuria_20", "0", "0"},
[421222] = {421222, 12012, 22, 38, "0", "0", "Heh!\u{0020}Get\u{0020}ready.", "ふん！覚悟するのね。", "呵！做好準備吧。", "0", "呵！做好准备吧。", "0", "cv_jyuria_19", "0", "0"},
[421223] = {421223, 12012, 26, 19, "0", "0", "Idiot...\u{0020}keep\u{0020}at\u{0020}it...", "ブタ野郎…しっかりしないと……", "笨豬…繼續加油啊……", "0", "笨猪…继续加油啊……", "0", "cv_jyuria_21", "0", "0"},
[421224] = {421224, 12012, 27, 20, "0", "0", "Wow,\u{0020}you\u{0020}guys\u{0020}are\u{0020}impressive,\u{0020}managing\u{0020}to\u{0020}bathe\u{0020}in\u{0020}a\u{0020}place\u{0020}that\u{0020}feels\u{0020}like\u{0020}a\u{0020}public\u{0020}restroom.", "へぇ、こんな汚いところでお風呂に入れるなんて。褒めてあげるわ。", "欸，你們真了不起呢，居然能在這種公共廁所一樣的地方洗澡。", "0", "诶，你们真了不起呢，居然能在这种公共厕所一样的地方洗澡。", "0", "cv_jyuria_22", "0", "0"},
[421225] = {421225, 12012, 28, 21, "0", "0", "Idiot,\u{0020}don't\u{0020}just\u{0020}stand\u{0020}there!\u{0020}Come\u{0020}over\u{0020}here.", "ブタ野郎。そんなところで突っ立ってないで、アタシの世話をするのよ。", "笨豬，不要在那裡傻站著，快點過來啦。", "0", "笨猪，不要在那里傻站着，快点过来啦。", "0", "cv_jyuria_23", "0", "0"},
[421226] = {421226, 12012, 29, 21, "0", "0", "If\u{0020}you\u{0020}kneel\u{0020}and\u{0020}lick\u{0020}my\u{0020}toes,\u{0020}I\u{0020}might\u{0020}let\u{0020}you\u{0020}see\u{0020}my\u{0020}noble\u{0020}body.", "跪いて足を舐めるなら、アタシの高貴な体を見せてあげようかしら。", "只要笨豬你跪下來舔我的腳趾，我倒不介意讓你看看我高貴的身體。", "0", "只要笨猪你跪下来舔我的脚趾，我倒不介意让你看看我高贵的身体。", "0", "cv_jyuria_24", "0", "0"},
[421227] = {421227, 12012, 30, 22, "0", "0", "Scout\u{0020}pig,\u{0020}go\u{0020}check\u{0020}out\u{0020}what's\u{0020}going\u{0020}on.", "ブタ。先に行って。アンタが偵察してくるのよ。", "探路豬，看看發生什麼了。", "0", "探路猪，看看发生什么了。", "0", "cv_jyuria_25", "0", "0"},
[421228] = {421228, 12012, 31, 23, "0", "0", "Idiot,\u{0020}don't\u{0020}tell\u{0020}me\u{0020}you\u{0020}don't\u{0020}know\u{0020}who\u{0020}I\u{0020}am!?", "まさかこのアタシが分からないはず、ないわよね？", "笨豬，你不會猜不出我是誰吧！？", "0", "笨猪，你不会猜不出我是谁吧！？", "0", "cv_jyuria_26", "0", "0"},
[421229] = {421229, 12012, 32, 24, "0", "0", "Hmm,\u{0020}seems\u{0020}you're\u{0020}smarter\u{0020}than\u{0020}I\u{0020}thought.", "ふうん。どうやら思ったよりはマシな頭みたいね。", "嗯，看來你比我想像中要聰明一些。", "0", "嗯，看来你比我想象中要聪明一些。", "0", "cv_jyuria_27", "0", "0"},
[421230] = {421230, 12012, 33, 25, "0", "0", "Whips,\u{0020}fire,\u{0020}electric\u{0020}shocks,\u{0020}suffocation...\u{0020}pick\u{0020}your\u{0020}poison.", "鞭。火あぶり。感電。窒息。……好きなのを選んでちょうだい。", "皮鞭、火烤、高壓電、窒息……選一個你喜歡的吧。", "0", "皮鞭、火烤、高压电、窒息……选一个你喜欢的吧。", "0", "cv_jyuria_28", "0", "0"},
[421231] = {421231, 12012, 34, 26, "0", "0", "Idiot,\u{0020}I\u{0020}almost\u{0020}thought\u{0020}you\u{0020}weren't\u{0020}going\u{0020}to\u{0020}show\u{0020}up...\u{0020}\"Lonely\"?\u{0020}Don't\u{0020}make\u{0020}me\u{0020}laugh.\u{0020}Know\u{0020}your\u{0020}place,\u{0020}fool!", "このアホブタ。もう来ないのかと思ったわ……寂しかったか……って笑わせないで！身の程も知らないで……バカ！", "笨豬，我還以為你不來了呢…“寂寞”？別惹我發笑了，認清自己位置，笨蛋！", "0", "笨猪，我还以为你不来了呢…“寂寞”？别惹我发笑了，认清自己位置，笨蛋！", "0", "cv_jyuria_31", "0", "0"},
[421232] = {421232, 12012, 35, 27, "0", "0", "Show\u{0020}me\u{0020}your\u{0020}resolve,\u{0020}idiot.\u{0020}Don't\u{0020}bore\u{0020}me.", "ブタ野郎の覚悟を見せてちょうだい。退屈させないでよ。", "笨豬，讓我見識下你的覺悟吧，不要讓我無聊喔。", "0", "笨猪，让我见识下你的觉悟吧，不要让我无聊喔。", "0", "cv_jyuria_33", "0", "0"},
[421233] = {421233, 12012, 36, 28, "0", "0", "If\u{0020}you're\u{0020}happy\u{0020}with\u{0020}the\u{0020}way\u{0020}things\u{0020}are,\u{0020}I'll\u{0020}be\u{0020}disappointed.", "これで満足しているようじゃ、がっかりね。", "如果你只滿足現狀，我會失望的。", "0", "如果你只满足现状，我会失望的。", "0", "cv_jyuria_34", "0", "0"},
[421234] = {421234, 12012, 37, 29, "0", "0", "Hehe...\u{0020}Is\u{0020}Celine\u{0020}here?", "フフフ……シリンはいるかしら？", "呵呵呵…棲琳在這裡嗎？", "0", "呵呵呵…栖琳在这里吗？", "0", "cv_jyuria_35", "0", "0"},
[421235] = {421235, 12012, 38, 30, "0", "0", "Oh?\u{0020}A\u{0020}new\u{0020}toy\u{0020}to\u{0020}play\u{0020}with\u{0020}today?", "あら。また新しいおもちゃをくれるのかしら。", "喔？今天又有新的玩具了嗎？", "0", "哦？今天又有新的玩具了吗？", "0", "cv_jyuria_36", "0", "0"},
[421236] = {421236, 12012, 39, 31, "0", "0", "Give\u{0020}me\u{0020}the\u{0020}best\u{0020}gear\u{0020}you've\u{0020}got.", "最高の装備をさっさとちょうだい。", "快把最好的裝備給我。", "0", "快把最好的装备给我。", "0", "cv_jyuria_37", "0", "0"},
[421237] = {421237, 12012, 40, 32, "0", "0", "You\u{0020}like\u{0020}this\u{0020}stuff?", "こんなのがいいの？", "你喜歡這些？", "0", "你喜欢这些？", "0", "cv_jyuria_38", "0", "0"},
[421238] = {421238, 12012, 41, 33, "0", "0", "You've\u{0020}got\u{0020}such\u{0020}a\u{0020}dumb\u{0020}look\u{0020}on\u{0020}your\u{0020}face.", "本当、アホ面ね。", "真是一張蠢臉呢。", "0", "真是一张蠢脸呢。", "0", "cv_jyuria_39", "0", "0"},
[421239] = {421239, 12012, 42, 34, "0", "0", "Hehe,\u{0020}should\u{0020}I\u{0020}fix\u{0020}it\u{0020}for\u{0020}you?", "ふふふ。アタシに設定させてみない？", "呵呵，我來幫你改吧？", "0", "呵呵，我来帮你改吧？", "0", "cv_jyuria_40", "0", "0"},
[421240] = {421240, 12012, 43, 35, "0", "0", "Show\u{0020}me\u{0020}what\u{0020}you've\u{0020}got\u{0020}first.", "先にアタシに見せて。", "先給我看。", "0", "先给我看。", "0", "cv_jyuria_41", "0", "0"},
[421241] = {421241, 12012, 44, 36, "0", "0", "Heh,\u{0020}a\u{0020}bunch\u{0020}of\u{0020}idiots.", "あら、ブタだらけね。", "謔，一群笨豬呢。", "0", "嚯，一群笨猪呢。", "0", "cv_jyuria_42", "0", "0"},
[421242] = {421242, 12012, 45, 37, "0", "0", "Boring.", "くだらないわ。", "無聊。", "0", "无聊。", "0", "cv_jyuria_43", "0", "0"},
[421300] = {421300, 12013, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_kalian_33", "0", "0"},
[421301] = {421301, 12013, 2, 2, "0", "0", "Are\u{0020}you\u{0020}sure\u{0020}it's\u{0020}okay\u{0020}to\u{0020}leave\u{0020}this\u{0020}to\u{0020}a\u{0020}trainee\u{0020}like\u{0020}me?", "候補生の私が担当しても宜しいのですか？", "交給我這種候補生真的好嗎？", "0", "交给我这种候补生真的好吗？", "0", "cv_kalian_2", "0", "0"},
[421302] = {421302, 12013, 3, 3, "0", "0", "Finally,\u{0020}we\u{0020}meet,\u{0020}Navigator.\u{0020}I'm\u{0020}Karen,\u{0020}a\u{0020}trainee\u{0020}from\u{0020}the\u{0020}Sahara\u{0020}branch.\u{0020}If\u{0020}it's\u{0020}alright,\u{0020}may\u{0020}I\u{0020}accompany\u{0020}you\u{0020}to\u{0020}the\u{0020}battlefield?", "ナビゲーター、やっとお会いできました。サハラ支部の候補生、カレンと申します。ご迷惑でなければ、戦場に同行させていただいても宜しいでしょうか？", "終於見面了，領航。我是薩哈拉支部的候補生，卡蓮。如果不介意的話，可以讓我與您一同前往戰場嗎？", "0", "终于见面了，领航。我是薩哈拉支部的候补生，卡莲。如果不介意的话，可以让我与您一同前往战场吗？", "0", "cv_kalian_1", "0", "0"},
[421303] = {421303, 12013, 4, 4, "0", "idle", "So\u{0020}this\u{0020}is\u{0020}what\u{0020}Drivers\u{0020}do\u{0020}every\u{0020}day...\u{0020}Alright,\u{0020}I'll\u{0020}give\u{0020}it\u{0020}my\u{0020}all!", "ドライバーの通常業務ですか……わかりました。頑張ります。", "這就是駕駛員們平時的工作嗎……好的，我會努力的。", "0", "这就是驾驶员们平时的工作吗……好的，我会努力的。", "0", "cv_kalian_3", "0", "0"},
[421304] = {421304, 12013, 5, 4, "0", "idle", "Wearing\u{0020}this\u{0020}Nimbus-made\u{0020}gear\u{0020}feels\u{0020}incredible...\u{0020}Huh?\u{0020}I\u{0020}can\u{0020}test\u{0020}it\u{0020}out\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}too?!", "なんと言うか、幻化した装備を身に付けるのは本当に不思議な感覚ですね。", "怎麼說呢？將幻化出的裝備穿在身上的感覺真是太奇妙了……欸？還可以去戰場測試一下嗎？！", "0", "怎么说呢？将幻化出的装备穿在身上的感觉真是太奇妙了……哎？还可以去战场测试一下吗？！", "0", "cv_kalian_4", "0", "0"},
[421305] = {421305, 12013, 6, 4, "0", "idle", "There\u{0020}should\u{0020}be\u{0020}other\u{0020}trainees\u{0020}besides\u{0020}me.\u{0020}If\u{0020}you\u{0020}see\u{0020}them,\u{0020}please\u{0020}look\u{0020}out\u{0020}for\u{0020}them.", "私の他にも候補生がいるのですよね。彼女たちの事も、どうぞよろしくお願いします。", "除了我之外應該還有其他候補生吧，如果見到她們的話還請多多關照一下。", "0", "除了我之外应该还有其他候补生吧，如果见到她们的话还请多多关照一下。", "0", "cv_kalian_30", "0", "0"},
[421306] = {421306, 12013, 7, 5, "1_》_0_0.8", "level1", "This\u{0020}uniform\u{0020}looks\u{0020}unfamiliar?\u{0020}Ah,\u{0020}this\u{0020}is\u{0020}the\u{0020}academy\u{0020}uniform\u{0020}that\u{0020}Sahara\u{0020}prepared\u{0020}for\u{0020}the\u{0020}trainees.", "見たことないユニフォーム、ですか？ああ、これはサハラが候補生に用意した制服ですよ。", "這件制服很陌生？啊，這是薩哈拉為候補生們準備的學院服。", "0", "这件制服很陌生？啊，这是薩哈拉为候补生们准备的学院服。", "0", "cv_kalian_31", "0", "0"},
[421307] = {421307, 12013, 8, 5, "1_》_0_0.8", "level1", "Huh?\u{0020}I\u{0020}happen\u{0020}to\u{0020}have\u{0020}something\u{0020}to\u{0020}discuss\u{0020}with\u{0020}you.\u{0020}May\u{0020}I\u{0020}take\u{0020}up\u{0020}some\u{0020}of\u{0020}your\u{0020}time,\u{0020}Navigator?", "あ、ちょうどナビゲーターにお聞きしたい事があったのです。少しお時間を頂いても宜しいですか？", "嗯？正好我有事想要請教您，可以佔有您一些時間嗎？領航。", "0", "嗯？正好我有事想要请教您，可以占有您一些时间吗？领航。", "0", "cv_kalian_5", "0", "0"},
[421308] = {421308, 12013, 9, 5, "1_》_100_1.5", "level2", "Navigator,\u{0020}I've\u{0020}been\u{0020}thinking\u{0020}about\u{0020}a\u{0020}lot\u{0020}of\u{0020}things,\u{0020}but\u{0020}there's\u{0020}still\u{0020}so\u{0020}much\u{0020}I\u{0020}don't\u{0020}understand...\u{0020}I'm\u{0020}sorry,\u{0020}I\u{0020}may\u{0020}need\u{0020}to\u{0020}rely\u{0020}on\u{0020}you\u{0020}in\u{0020}the\u{0020}future\u{0020}as\u{0020}well.\u{0020}May\u{0020}I\u{0020}call\u{0020}you\u{0020}\"teacher\"?", "ナビゲーター。しばらく考えたのですが、私には、まだまだ分からないことが沢山あるようです。お手数をおかけいたしますが、今後とも宜しくお願いします、先生。……ええ、先生とお呼びすることをお許しください。", "領航，我回去思考了一段時間，但還是有很多事情都弄不明白……非常抱歉，可能今後也還要拜託你了，老師。嗯，還請允許我像這樣稱呼您吧。", "0", "领航，我回去思考了一段时间，但还是有很多事情都弄不明白……非常抱歉，可能今后也还要拜托你了，老师。嗯，还请允许我像这样称呼您吧。", "0", "cv_kalian_6", "0", "0"},
[421309] = {421309, 12013, 10, 5, "1_》_500_2", "level3", "Teacher,\u{0020}do\u{0020}you\u{0020}have\u{0020}some\u{0020}time\u{0020}today?\u{0020}I've\u{0020}organized\u{0020}my\u{0020}notes,\u{0020}and\u{0020}I'd\u{0020}love\u{0020}your\u{0020}help\u{0020}reviewing\u{0020}them.\u{0020}If\u{0020}you're\u{0020}busy,\u{0020}we\u{0020}can\u{0020}do\u{0020}it\u{0020}another\u{0020}day.", "先生、今日、少しお時間宜しいでしょうか？今までの記録を整理したのですが、ご覧いただけますか？もちろんお忙しいようでしたら、後日でも結構ですので。", "老師，您今天有空嗎？我整理出了一些自己這段時間收集到的記錄，想讓您幫忙看一下可以嗎？當然，如果您正在忙的話，我們改天也可以。", "0", "老师，您今天有空吗？我整理出了一些自己这段时间收集到的记录，想让您帮忙看一下可以吗？当然，如果您正在忙的话，我们改天也可以。", "0", "cv_kalian_7", "0", "0"},
[421310] = {421310, 12013, 11, 5, "1_》_1000_2.5", "level4", "It's\u{0020}hard\u{0020}to\u{0020}believe\u{0020}I've\u{0020}spent\u{0020}so\u{0020}much\u{0020}time\u{0020}with\u{0020}you,\u{0020}teacher.\u{0020}Thanks\u{0020}to\u{0020}your\u{0020}guidance,\u{0020}I've\u{0020}stayed\u{0020}safe\u{0020}as\u{0020}a\u{0020}Driver.\u{0020}I\u{0020}wish\u{0020}the\u{0020}day\u{0020}we\u{0020}part\u{0020}would\u{0020}come\u{0020}much\u{0020}later...\u{0020}I\u{0020}still\u{0020}have\u{0020}so\u{0020}much\u{0020}to\u{0020}learn\u{0020}from\u{0020}you...", "先生とはじめてお会いしてから、もうこんなに経ったんですね。先生のおかげで、私は生き延びることができたんですよ。……私、先生とお別れしたくありません。まだまだ教えていただきたいことが、沢山あるんです。", "不知不覺已經和你相處了這麼久了啊，老師。在當駕駛員的時間裏，多虧了你的照顧我才沒有受傷。真希望分別的日子可以再晚些……我還有很多想向老師請教的東西……", "0", "不知不觉已经和你相处了这么久了啊，老师。在当驾驶员的时间里，多亏了你的照顾我才没有受伤。真希望分别的日子可以再晚些……我还有很多想向老师请教的东西……", "0", "cv_kalian_8", "0", "0"},
[421311] = {421311, 12013, 12, 6, "0", "0", "Thank\u{0020}you\u{0020}so\u{0020}much!", "これは……本当にありがとうございます！", "這真是……非常感謝！", "0", "这真是……非常感谢！", "0", "cv_kalian_9", "0", "0"},
[421312] = {421312, 12013, 13, 7, "0", "0", "Fighting\u{0020}on\u{0020}the\u{0020}battlefield...\u{0020}feels\u{0020}amazing.", "戦場を駆け抜ける感じ……素晴らしいです。", "馳騁在戰場的感覺……真好。", "0", "驰骋在战场的感觉……真好。", "0", "cv_kalian_10", "0", "0"},
[421313] = {421313, 12013, 14, 8, "0", "0", "Though\u{0020}it\u{0020}may\u{0020}sound\u{0020}a\u{0020}bit\u{0020}arrogant,\u{0020}I\u{0020}feel\u{0020}that\u{0020}with\u{0020}your\u{0020}help,\u{0020}I'm\u{0020}already\u{0020}becoming\u{0020}a\u{0020}qualified\u{0020}driver.", "自惚れに聞こえるかもしれませんが、私が一人前のドライバーになれたのは、先生のお陰です。", "雖然這麼說有些自大，不過我感覺在你的幫助下，自己已經是個合格的駕駛員了呢。", "0", "虽然这么说有些自大，不过我感觉在你的帮助下，自己已经是个合格的驾驶员了呢。", "0", "cv_kalian_11", "0", "0"},
[421314] = {421314, 12013, 15, 9, "0", "0", "Experience\u{0020}gained\u{0020}in\u{0020}real\u{0020}combat\u{0020}is\u{0020}priceless.", "やはり、実戦での経験ほど貴重なものはありません。", "果然，實戰中獲取的經驗才是最寶貴的。", "0", "果然，实战中获取的经验才是最宝贵的。", "0", "cv_kalian_12", "0", "0"},
[421315] = {421315, 12013, 16, 10, "0", "0", "All\u{0020}systems\u{0020}ready\u{0020}for\u{0020}battle.", "デバッグ完了。戦闘態勢に入ります。", "調試完畢，準備戰鬥。", "0", "调试完毕，准备战斗。", "0", "cv_kalian_13", "0", "0"},
[421316] = {421316, 12013, 17, 11, "0", "0", "Victory\u{0020}without\u{0020}casualties\u{0020}is\u{0020}the\u{0020}best\u{0020}outcome.", "完勝です！誰も怪我をせずに勝利できたことは、最高の戦果です。", "完勝，沒有人受傷就是最好的結果。", "0", "完胜，没有人受伤就是最好的结果。", "0", "cv_kalian_14", "0", "0"},
[421317] = {421317, 12013, 18, 12, "0", "0", "Mission\u{0020}complete,\u{0020}let's\u{0020}head\u{0020}back\u{0020}now,\u{0020}Navigator.", "任務完了。直ちに帰還しましょう、ナビゲーター。", "任務完成，現在就返回吧，領航。", "0", "任务完成，现在就返回吧，领航。", "0", "cv_kalian_15", "0", "0"},
[421318] = {421318, 12013, 19, 13, "0", "0", "Feeling\u{0020}a\u{0020}bit\u{0020}disappointed?\u{0020}Well,\u{0020}it's\u{0020}still\u{0020}valuable\u{0020}experience.", "少し残念、ですか？でも、これも貴重な経験ですから。", "略微有些遺憾嗎？不過算了，這也是寶貴的經驗。", "0", "略微有些遗憾吗？不过算了，这也是宝贵的经验。", "0", "cv_kalian_16", "0", "0"},
