[421326] = {421326, 12013, 28, 21, "0", "0", "Danube's\u{0020}bathhouse\u{0020}reminds\u{0020}me\u{0020}of\u{0020}Sahara's—it\u{0020}feels\u{0020}like\u{0020}I'm\u{0020}back\u{0020}at\u{0020}school.", "ダニューブの浴場は、サハラのと随分似ています。なんだか未だに学校にいるような感じですね。", "多瑙的浴場和薩哈拉的浴場還蠻像的嘛，讓我有種還在學校裏的感覺。", "0", "多瑙的浴场和萨哈拉的浴场还蛮像的嘛，让我有种还在学校里的感觉。", "0", "cv_kalian_24", "0", "0"},
[421327] = {421327, 12013, 29, 21, "0", "0", "It\u{0020}feels\u{0020}like\u{0020}when\u{0020}I\u{0020}used\u{0020}to\u{0020}bathe\u{0020}with\u{0020}my\u{0020}sister\u{0020}as\u{0020}a\u{0020}kid.", "子供の頃、お姉ちゃんと一緒にお風呂に入ったのを思い出します……", "好像小時候和姐姐一起洗澡時的感覺一樣呢。", "0", "好像小时候和姐姐一起洗澡时的感觉一样呢。", "0", "cv_kalian_25", "0", "0"},
[421328] = {421328, 12013, 30, 22, "0", "0", "Teacher,\u{0020}please\u{0020}be\u{0020}careful.", "先生、どうかお気をつけて。", "老師，還請小心一些。", "0", "老师，还请小心一些。", "0", "cv_kalian_26", "0", "0"},
[421329] = {421329, 12013, 31, 23, "0", "0", "Let's\u{0020}play\u{0020}a\u{0020}little\u{0020}game.", "ちょっとしたゲームですね。", "稍微玩個小遊戲吧。", "0", "稍微玩个小游戏吧。", "0", "cv_kalian_27", "0", "0"},
[421330] = {421330, 12013, 32, 24, "0", "0", "As\u{0020}expected\u{0020}of\u{0020}my\u{0020}teacher.", "さすが、私の先生です。", "果然，不愧是我的老師。", "0", "果然，不愧是我的老师。", "0", "cv_kalian_28", "0", "0"},
[421331] = {421331, 12013, 33, 25, "0", "0", "So,\u{0020}even\u{0020}you\u{0020}make\u{0020}mistakes,\u{0020}teacher.", "先生もミスをする時があるのですね。", "原來老師也會有出錯的時候啊。", "0", "原来老师也会有出错的时候啊。", "0", "cv_kalian_29", "0", "0"},
[421332] = {421332, 12013, 34, 26, "0", "0", "Finally,\u{0020}you're\u{0020}here!\u{0020}I've\u{0020}got\u{0020}so\u{0020}many\u{0020}questions\u{0020}for\u{0020}you\u{0020}today.", "やっとお会いできました。今日も教えて頂きたいことが沢山あるのです。", "終於等到您了，今天也有一大堆問題想要請教您呢。", "0", "终于等到您了，今天也有一大堆问题想要请教您呢。", "0", "cv_kalian_32", "0", "0"},
[421333] = {421333, 12013, 35, 27, "0", "0", "The\u{0020}battlefield\u{0020}is\u{0020}the\u{0020}best\u{0020}classroom.", "戦場こそ最高の教室です。", "戰場才是最好的教室。", "0", "战场才是最好的教室。", "0", "cv_kalian_34", "0", "0"},
[421334] = {421334, 12013, 36, 28, "0", "0", "Nothing\u{0020}can\u{0020}stump\u{0020}me.", "私にとって難しいことではありません。", "沒有什麼可以難倒我。", "0", "没有什么可以难倒我。", "0", "cv_kalian_35", "0", "0"},
