[421401] = {421401, 12014, 2, 2, "0", "0", "So,\u{0020}this\u{0020}is\u{0020}what\u{0020}work\u{0020}feels\u{0020}like?\u{0020}Alright,\u{0020}I'll\u{0020}give\u{0020}it\u{0020}my\u{0020}best\u{0020}shot!\u{0020}You\u{0020}too,\u{0020}Renie,\u{0020}let's\u{0020}do\u{0020}our\u{0020}best!", "0", "這就是人類所謂的工作嗎？好，我會努力的！芮妮也要加油哦！", "0", "这就是人类所谓的工作吗？好，我会努力的！芮妮也要加油哦！", "0", "cv_shepharith_2", "0", "0"},
[421402] = {421402, 12014, 3, 3, "0", "0", "Finally,\u{0020}we\u{0020}meet\u{0020}again,\u{0020}Navigator.\u{0020}I'm\u{0020}Cephalis,\u{0020}and\u{0020}this\u{0020}is\u{0020}my\u{0020}partner,\u{0020}Renie.\u{0020}Please\u{0020}take\u{0020}care\u{0020}of\u{0020}us\u{0020}from\u{0020}now\u{0020}on.", "0", "終於又見面了，領航，我叫西法麗斯，這是我的夥伴芮妮，今後就請多多關照。", "0", "终于又见面了，领航，我叫西法丽斯，这是我的伙伴芮妮，今后就请多多关照。", "0", "cv_shepharith_1", "0", "0"},
[421403] = {421403, 12014, 4, 4, "0", "idle", "I\u{0020}see\u{0020}you're\u{0020}daydreaming,\u{0020}Navigator,\u{0020}but\u{0020}don't\u{0020}worry—I\u{0020}won't\u{0020}tell\u{0020}anyone~", "0", "我已經看到領航在開小差了，但我不會告訴別人的~", "0", "我已经看到领航在开小差了，但我不会告诉别人的~", "0", "cv_shepharith_3", "0", "0"},
[421404] = {421404, 12014, 5, 4, "0", "idle", "Can\u{0020}you\u{0020}see\u{0020}Midyr\u{0020}from\u{0020}here?\u{0020}No...\u{0020}I\u{0020}guess\u{0020}not.", "0", "從這裏能看到米狄爾嗎？果然看不到了……", "0", "从这里能看到米狄尔吗？果然看不到了......", "0", "cv_shepharith_4", "0", "0"},
[421405] = {421405, 12014, 6, 4, "0", "idle", "It's\u{0020}so\u{0020}nice\u{0020}to\u{0020}be\u{0020}teammates\u{0020}with\u{0020}other\u{0020}Midyrians\u{0020}again!\u{0020}As\u{0020}long\u{0020}as\u{0020}we're\u{0020}together,\u{0020}the\u{0020}Shumia\u{0020}can\u{0020}set\u{0020}sail\u{0020}once\u{0020}more!", "0", "沒想到還能和同為米狄爾族的大家成為隊友，真是太好了！只要大家還能夠在一起，修米婭的航行就能再次啟動！", "0", "没想到还能和同为米狄尔族的大家成为队友，真是太好了！只要大家还能够在一起，修米娅的航行就能再次启动！", "0", "cv_shepharith_29", "0", "0"},
[421406] = {421406, 12014, 7, 5, "1_》_0_0.8", "level1", "This\u{0020}blue\u{0020}planet...\u{0020}has\u{0020}become\u{0020}the\u{0020}last\u{0020}living\u{0020}world\u{0020}in\u{0020}the\u{0020}universe.\u{0020}History...\u{0020}must\u{0020}not\u{0020}repeat\u{0020}itself!", "0", "這顆蔚藍色的行星，不知何時已經成為了宇宙僅存的生命之果。歷史…絕不能重演！", "0", "这颗蔚蓝色的行星，不知何时已经成为了宇宙仅存的生命之果。历史...绝不能重演！", "0", "cv_shepharith_30", "0", "0"},
[421407] = {421407, 12014, 8, 5, "1_》_0_0.8", "level1", "Is\u{0020}this\u{0020}part\u{0020}of\u{0020}your\u{0020}job\u{0020}too,\u{0020}Navigator?", "0", "這也是領航的工作嗎？", "0", "这也是领航的工作吗？", "0", "cv_shepharith_5", "0", "0"},
[421408] = {421408, 12014, 9, 5, "1_》_100_1.5", "level2", "Renie's\u{0020}not\u{0020}fond\u{0020}of\u{0020}strangers,\u{0020}so\u{0020}be\u{0020}careful\u{0020}not\u{0020}to\u{0020}get\u{0020}too\u{0020}close...\u{0020}huh?", "0", "芮妮對陌生人很凶的，請小心不要靠近……誒？", "0", "芮妮对陌生人很凶的，请小心不要靠近......诶？", "0", "cv_shepharith_6", "0", "0"},
[421409] = {421409, 12014, 10, 5, "1_》_500_2", "level3", "No\u{0020}matter\u{0020}how\u{0020}many\u{0020}times\u{0020}I\u{0020}look\u{0020}at\u{0020}the\u{0020}stars,\u{0020}they\u{0020}always\u{0020}shine\u{0020}so\u{0020}brightly,\u{0020}except\u{0020}where\u{0020}Midyr\u{0020}used\u{0020}to\u{0020}be—it's\u{0020}all\u{0020}darkness.", "0", "無論多少次仰望星空，群星都是那麼璀璨，唯獨米狄爾所在是一片漆黑。", "0", "无论多少次仰望星空，群星都是那么璀璨，唯独米狄尔所在是一片漆黑。", "0", "cv_shepharith_7", "0", "0"},
[421410] = {421410, 12014, 11, 5, "1_》_1000_2.5", "level4", "Do\u{0020}you\u{0020}like\u{0020}traveling\u{0020}too,\u{0020}Navigator?\u{0020}Awesome!\u{0020}After\u{0020}we\u{0020}defeat\u{0020}the\u{0020}Sin,\u{0020}let's\u{0020}travel\u{0020}the\u{0020}universe\u{0020}together!\u{0020}I\u{0020}know\u{0020}a\u{0020}planet\u{0020}where\u{0020}the\u{0020}rivers\u{0020}are\u{0020}made\u{0020}of\u{0020}cream,\u{0020}we\u{0020}can\u{0020}feast\u{0020}there,\u{0020}then\u{0020}head\u{0020}to\u{0020}the\u{0020}center\u{0020}of\u{0020}the\u{0020}galaxy...\u{0020}Of\u{0020}course,\u{0020}I'd\u{0020}love\u{0020}to\u{0020}take\u{0020}you\u{0020}to\u{0020}my\u{0020}home\u{0020}planet\u{0020}most\u{0020}of\u{0020}all.\u{0020}But\u{0020}anywhere's\u{0020}fine,\u{0020}as\u{0020}long\u{0020}as\u{0020}we're\u{0020}together...", "0", "領航也喜歡旅行嗎？太好了，等消滅了原罪後我們一起去宇宙旅行吧！我知道一個河流中充滿奶油的星球，我們可以在那裏大吃一頓，然後去宇宙的中心……當然，最想帶領航去的還是我的故鄉。但是能和領航一起的話，不管去哪……", "0", "领航也喜欢旅行吗？太好了，等消灭了原罪后我们一起去宇宙旅行吧！我知道一个河流中充满奶油的星球，我们可以在那里大吃一顿，然后去宇宙的中心......当然，最想带领航去的还是我的故乡。但是能和领航一起的话，不管去哪......", "0", "cv_shepharith_8", "0", "0"},
[421411] = {421411, 12014, 12, 6, "0", "0", "Good\u{0020}girl,\u{0020}Renie\u{0020}is\u{0020}getting\u{0020}stronger\u{0020}too.", "0", "真乖真乖，芮妮也變強了。", "0", "真乖真乖，芮妮也变强了。", "0", "cv_shepharith_9", "0", "0"},
[421412] = {421412, 12014, 13, 7, "0", "0", "Is\u{0020}this...\u{0020}an\u{0020}award?\u{0020}Wow,\u{0020}thank\u{0020}you,\u{0020}Commander\u{0020}Navigator!", "0", "這是…授勳嗎？哇哦，謝謝領航長官！", "0", "这是…授勋吗？哇哦，谢谢领航长官！", "0", "cv_shepharith_10", "0", "0"},
[421413] = {421413, 12014, 14, 8, "0", "0", "Ah...\u{0020}that\u{0020}sound...\u{0020}It's\u{0020}the\u{0020}voice\u{0020}of\u{0020}Midyr.\u{0020}Navigator,\u{0020}I\u{0020}can\u{0020}hear\u{0020}it—it\u{0020}hasn't\u{0020}perished\u{0020}yet,\u{0020}it's\u{0020}still\u{0020}watching\u{0020}us.", "0", "啊…這個聲音，是“米狄爾”的聲音。領航，我聽到了米狄爾的聲音。它還沒有滅亡，它還在…注視著我們。", "0", "啊...这个声音，是“米狄尔”的声音。领航，我听到了米狄尔的声音。它还没有灭亡，它还在...注视着我们。", "0", "cv_shepharith_11", "0", "0"},
[421414] = {421414, 12014, 15, 9, "0", "0", "Our\u{0020}connection,\u{0020}Renie...\u{0020}it's\u{0020}getting\u{0020}stronger.", "0", "與芮妮的默契…加強了。", "0", "与芮妮的默契...加强了。", "0", "cv_shepharith_12", "0", "0"},
[421415] = {421415, 12014, 16, 10, "0", "0", "Renie,\u{0020}battle\u{0020}mode!", "0", "芮妮！進入戰鬥姿態。", "0", "芮妮！进入战斗姿态。", "0", "cv_shepharith_13", "0", "0"},
[421416] = {421416, 12014, 17, 11, "0", "0", "What\u{0020}do\u{0020}you\u{0020}think?\u{0020}Renie\u{0020}and\u{0020}I\u{0020}are\u{0020}the\u{0020}perfect\u{0020}team,\u{0020}right?", "0", "如何，我與芮妮果然是最佳搭檔吧~！", "0", "如何，我与芮妮果然是最佳搭档吧~！", "0", "cv_shepharith_14", "0", "0"},
[421417] = {421417, 12014, 18, 12, "0", "0", "Great\u{0020}job,\u{0020}Renie!", "0", "芮妮辛苦了~", "0", "芮妮辛苦了~", "0", "cv_shepharith_15", "0", "0"},
[421418] = {421418, 12014, 19, 13, "0", "0", "Whew,\u{0020}that\u{0020}was\u{0020}close!", "0", "還好還好，差點就失敗了。", "0", "还好还好，差点就失败了。", "0", "cv_shepharith_16", "0", "0"},
