[421502] = {421502, 12015, 3, 3, "0", "0", "I\u{0020}see,\u{0020}you're\u{0020}the\u{0020}legendary\u{0020}Navigator\u{0020}my\u{0020}father\u{0020}spoke\u{0020}of?\u{0020}I'm\u{0020}Vesper,\u{0020}and\u{0020}it's\u{0020}an\u{0020}honor\u{0020}to\u{0020}meet\u{0020}you.", "0", "原來如此，您就是父親說的那位傳奇領航嗎？我的名字是薇絲帕爾，很高興能夠見到您。", "0", "原来如此，您就是父亲说的那位传奇领航吗？我的名字是薇丝帕尔，很高兴能够见到您。", "0", "cv_vicepearl_1", "0", "0"},
[421503] = {421503, 12015, 4, 4, "0", "idle", "Although\u{0020}my\u{0020}father\u{0020}is\u{0020}the\u{0020}branch\u{0020}leader,\u{0020}Ark\u{0020}is\u{0020}the\u{0020}true\u{0020}symbol\u{0020}of\u{0020}Danube.\u{0020}Our\u{0020}family\u{0020}owes\u{0020}our\u{0020}status\u{0020}to\u{0020}AEGIS.", "0", "父親雖然貴為支部長，但其實方舟才是多瑙地區的象徵，我們家族能有今天的地位還是拜艾吉斯所賜。", "0", "父亲虽然贵为支部长，但其实方舟才是多瑙地区的象征，我们家族能有今天的地位还是拜艾吉斯所赐。", "0", "cv_vicepearl_3", "0", "0"},
[421504] = {421504, 12015, 5, 4, "0", "idle", "Please\u{0020}don't\u{0020}treat\u{0020}me\u{0020}like\u{0020}some\u{0020}kind\u{0020}of\u{0020}princess\u{0020}of\u{0020}Danube.\u{0020}As\u{0020}you\u{0020}can\u{0020}see,\u{0020}I'm\u{0020}just\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}guards.", "0", "還請不要把我當做是多瑙的公主什麼的，如您所見，我現在只是一名親衛隊隊員。", "0", "还请不要把我当做是多瑙的公主什么的，如您所见，我现在只是一名亲卫队队员。", "0", "cv_vicepearl_4", "0", "0"},
[421505] = {421505, 12015, 6, 4, "0", "idle", "Flora\u{0020}is\u{0020}an\u{0020}excellent\u{0020}Driver,\u{0020}but\u{0020}she\u{0020}might\u{0020}not\u{0020}be\u{0020}suited\u{0020}to\u{0020}lead.", "0", "芙蘿拉是位優秀的駕駛員，不過她也許不太適合做領袖？", "0", "芙萝拉是位优秀的驾驶员，不过她也许不太适合做领袖？", "0", "cv_vicepearl_30", "0", "0"},
[421506] = {421506, 12015, 7, 5, "1_》_0_0.8", "level1", "Hehe,\u{0020}do\u{0020}you\u{0020}like\u{0020}my\u{0020}hair?", "0", "嘿嘿嘿，您很喜歡我的頭髮嗎？", "0", "嘿嘿嘿，您很喜欢我的头发吗？", "0", "cv_vicepearl_31", "0", "0"},
[421507] = {421507, 12015, 8, 5, "1_》_0_0.8", "level1", "What's\u{0020}wrong?\u{0020}Feeling\u{0020}nervous?\u{0020}Don't\u{0020}worry,\u{0020}I\u{0020}won't\u{0020}make\u{0020}things\u{0020}hard\u{0020}for\u{0020}you.", "0", "怎麼了？您也有緊張的時候嗎？別擔心，我不會為難您的。", "0", "怎么了？您也有紧张的时候吗？别担心，我不会为难您的。", "0", "cv_vicepearl_5", "0", "0"},
[421508] = {421508, 12015, 9, 5, "1_》_100_1.5", "level2", "Danube's\u{0020}power\u{0020}is\u{0020}quite\u{0020}complex,\u{0020}and\u{0020}everyone\u{0020}is\u{0020}only\u{0020}united\u{0020}now\u{0020}because\u{0020}of\u{0020}Sin.\u{0020}But\u{0020}I\u{0020}believe\u{0020}my\u{0020}father\u{0020}can\u{0020}manage\u{0020}it\u{0020}all,\u{0020}so\u{0020}there's\u{0020}no\u{0020}need\u{0020}to\u{0020}worry—you're\u{0020}always\u{0020}welcome\u{0020}here.", "0", "多瑙的勢力錯綜複雜，現在大家只不過是因為原罪而聯合在了一起。不過我還是相信父親能處理好這一切，所以您大可不必擔心，這裡永遠歡迎您。", "0", "多瑙的势力错综复杂，现在大家只不过是因为原罪而联合在了一起。不过我还是相信父亲能处理好这一切，所以您大可不必担心，这里永远欢迎您。", "0", "cv_vicepearl_6", "0", "0"},
[421509] = {421509, 12015, 10, 5, "1_》_500_2", "level3", "I\u{0020}must\u{0020}prepare\u{0020}for\u{0020}the\u{0020}future.\u{0020}When\u{0020}my\u{0020}father\u{0020}grows\u{0020}old\u{0020}and\u{0020}the\u{0020}Sin\u{0020}is\u{0020}gone,\u{0020}what\u{0020}path\u{0020}will\u{0020}Danube\u{0020}take?\u{0020}A\u{0020}Danubean\u{0020}must\u{0020}rise\u{0020}as\u{0020}a\u{0020}new\u{0020}legend\u{0020}in\u{0020}this\u{0020}war—it's\u{0020}our\u{0020}fate.\u{0020}Navigator...\u{0020}I\u{0020}hope\u{0020}you'll\u{0020}support\u{0020}me.", "0", "我必須要為未來做好準備，當父親老去，當原罪從世界上消失，多瑙又會走向何方？必須得有一個多瑙人得在這場戰爭中成為新的傳奇，這是我們無法規避的命運。領航……我希望您能支持我。", "0", "我必须要为未来做好准备，当父亲老去，当原罪从世界上消失，多瑙又会走向何方？必须得有一个多瑙人得在这场战争中成为新的传奇，这是我们无法规避的命运。领航……我希望您能支持我。", "0", "cv_vicepearl_7", "0", "0"},
[421510] = {421510, 12015, 11, 5, "1_》_1000_2.5", "level4", "The\u{0020}long\u{0020}night\u{0020}will\u{0020}eventually\u{0020}give\u{0020}way\u{0020}to\u{0020}dawn,\u{0020}and\u{0020}it\u{0020}may\u{0020}not\u{0020}be\u{0020}a\u{0020}single\u{0020}person\u{0020}who\u{0020}brings\u{0020}that\u{0020}light\u{0020}to\u{0020}this\u{0020}land.\u{0020}But\u{0020}the\u{0020}people\u{0020}here\u{0020}need\u{0020}a\u{0020}hero,\u{0020}a\u{0020}legend.\u{0020}Navigator,\u{0020}I\u{0020}know\u{0020}you\u{0020}don't\u{0020}belong\u{0020}to\u{0020}Danube,\u{0020}and\u{0020}perhaps\u{0020}someday\u{0020}we'll\u{0020}stand\u{0020}on\u{0020}opposite\u{0020}sides.\u{0020}But\u{0020}whatever\u{0020}happens,\u{0020}your\u{0020}name\u{0020}will\u{0020}be\u{0020}written\u{0020}into\u{0020}my\u{0020}story.", "0", "長夜終會迎來黎明，而為這片土地帶來黎明的也許不會是任何一個個人。但是這片土地的人需要一個偶像，需要一篇傳奇。領航，我能看出您並不屬於多瑙，也許多年之後我們也會站在彼此的對立面吧。但無論結局如何，我的傳奇故事中一定會為您留下筆墨的。", "0", "长夜终会迎来黎明，而为这片土地带来黎明的也许不会是任何一个个人。但是这片土地的人需要一个偶像，需要一篇传奇。领航，我能看出您并不属于多瑙，也许多年之后我们也会站在彼此的对立面吧。但无论结局如何，我的传奇故事中一定会为您留下笔墨的。", "0", "cv_vicepearl_8", "0", "0"},
[421511] = {421511, 12015, 12, 6, "0", "0", "Thank\u{0020}you,\u{0020}sincerely.", "0", "由衷地感謝您。", "0", "由衷地感谢您。", "0", "cv_vicepearl_9", "0", "0"},
[421512] = {421512, 12015, 13, 7, "0", "0", "Today\u{0020}is\u{0020}truly\u{0020}a\u{0020}memorable\u{0020}day.", "0", "真是值得紀念的日子。", "0", "真是值得纪念的日子。", "0", "cv_vicepearl_10", "0", "0"},
[421513] = {421513, 12015, 14, 8, "0", "0", "Before\u{0020}I\u{0020}knew\u{0020}it,\u{0020}it\u{0020}seems\u{0020}we've\u{0020}already\u{0020}begun\u{0020}writing\u{0020}a\u{0020}new\u{0020}legend\u{0020}together.\u{0020}I\u{0020}look\u{0020}forward\u{0020}to\u{0020}the\u{0020}days\u{0020}ahead.", "0", "不知不覺中貌似已經和您一同書寫了一段新的傳奇，接下來的日子就請多多指教了。", "0", "不知不觉中貌似已经和您一同书写了一段新的传奇，接下来的日子就请多多指教了。", "0", "cv_vicepearl_11", "0", "0"},
[421514] = {421514, 12015, 15, 9, "0", "0", "What\u{0020}an\u{0020}exciting\u{0020}moment!", "0", "真是激動人心的時刻呢。", "0", "真是激动人心的时刻呢。", "0", "cv_vicepearl_12", "0", "0"},
