[421517] = {421517, 12015, 18, 12, "0", "0", "That\u{0020}was\u{0020}a\u{0020}thrilling\u{0020}battle,\u{0020}wasn't\u{0020}it?", "0", "真是一場激動人心的戰鬥，不是嗎？", "0", "真是一场激动人心的战斗，不是吗？", "0", "cv_vicepearl_15", "0", "0"},
[421518] = {421518, 12015, 19, 13, "0", "0", "Even\u{0020}though\u{0020}we\u{0020}faced\u{0020}setbacks,\u{0020}didn't\u{0020}we\u{0020}still\u{0020}win\u{0020}in\u{0020}the\u{0020}end?", "0", "哪怕是歷經了挫折，我們不還是贏下來了嗎？", "0", "哪怕是历经了挫折，我们不还是赢下来了吗？", "0", "cv_vicepearl_16", "0", "0"},
[421519] = {421519, 12015, 20, 14, "0", "0", "There\u{0020}are\u{0020}no\u{0020}invincible\u{0020}heroes—this\u{0020}time,\u{0020}let's\u{0020}just\u{0020}treat\u{0020}it\u{0020}as\u{0020}a\u{0020}lesson.", "0", "並沒有常勝的英雄，這次就當做是長個教訓吧。", "0", "并没有常胜的英雄，这次就当做是长个教训吧。", "0", "cv_vicepearl_17", "0", "0"},
[421520] = {421520, 12015, 21, 15, "0", "0", "Hey!", "0", "嘿！", "0", "嘿！", "0", "cv_vicepearl_19", "0", "0"},
[421521] = {421521, 12015, 23, 16, "0", "0", "Good,\u{0020}just\u{0020}as\u{0020}I\u{0020}expected.", "0", "很好，和預想的一樣。", "0", "很好，和预想的一样。", "0", "cv_vicepearl_20", "0", "0"},
[421522] = {421522, 12015, 24, 17, "0", "0", "I\u{0020}won't\u{0020}let\u{0020}you\u{0020}off\u{0020}that\u{0020}easily.", "0", "不會就這樣放過你的。", "0", "不会就这样放过你的。", "0", "cv_vicepearl_22", "0", "0"},
