[421602] = {421602, 12016, 3, 3, "0", "0", "Yohoo,\u{0020}Salati\u{0020}Sony\u{0020}is\u{0020}here!\u{0020}What\u{0020}kind\u{0020}of\u{0020}music\u{0020}do\u{0020}you\u{0020}like,\u{0020}Navigator?", "0", "唷吼，薩拉蒂·索尼參上！不知道領航喜歡哪種風格的音樂呢？", "0", "哟吼，萨拉蒂·索尼参上！不知道领航喜欢哪种风格的音乐呢？", "0", "cv_saraid_1", "0", "0"},
[421603] = {421603, 12016, 4, 4, "0", "idle", "What\u{0020}should\u{0020}we\u{0020}do\u{0020}about\u{0020}band\u{0020}practice\u{0020}today?...\u{0020}Oh,\u{0020}let's\u{0020}just\u{0020}gather\u{0020}everyone!", "0", "今天的樂隊練習怎麼辦呢？…啊，把大家都叫來就好了呀！", "0", "今天的乐队练习怎么办呢？…啊，把大家都叫来就好了呀！", "0", "cv_saraid_3", "0", "0"},
[421604] = {421604, 12016, 5, 4, "0", "idle", "The\u{0020}album\u{0020}we\u{0020}released\u{0020}sold\u{0020}out\u{0020}faster\u{0020}than\u{0020}I\u{0020}expected!\u{0020}I\u{0020}saved\u{0020}a\u{0020}set\u{0020}for\u{0020}you,\u{0020}Navigator,\u{0020}don't\u{0020}forget\u{0020}to\u{0020}listen\u{0020}to\u{0020}it!", "0", "之前發售的專輯比想像中賣得還要快，我特意幫領航留了一套，一定要記得聽喔~", "0", "之前发售的专辑比想象中卖得还要快，我特意帮领航留了一套，一定要记得听哦~", "0", "cv_saraid_4", "0", "0"},
[421605] = {421605, 12016, 6, 4, "0", "idle", "It's\u{0020}thanks\u{0020}to\u{0020}Ashlica\u{0020}giving\u{0020}me\u{0020}hope\u{0020}that\u{0020}I\u{0020}was\u{0020}able\u{0020}to\u{0020}pick\u{0020}up\u{0020}music\u{0020}again.\u{0020}Not\u{0020}everyone\u{0020}understands\u{0020}our\u{0020}sound,\u{0020}but\u{0020}as\u{0020}long\u{0020}as\u{0020}one\u{0020}person\u{0020}likes\u{0020}it...\u{0020}it's\u{0020}worth\u{0020}it!", "0", "多虧了艾希麗卡給了我希望，我才能重新拾起音樂。雖然很多人都不能接受我們的音樂，但是只要有一個人喜歡……那它就有存在的意義！", "0", "多亏了艾希丽卡给了我希望，我才能重新拾起音乐。虽然很多人都不能接受我们的音乐，但是只要有一个人喜欢……那它就有存在的意义！", "0", "cv_saraid_30", "0", "0"},
[421606] = {421606, 12016, 7, 5, "1_》_0_0.8", "level1", "I\u{0020}hope\u{0020}someday\u{0020}our\u{0020}band\u{0020}can\u{0020}go\u{0020}on\u{0020}a\u{0020}world\u{0020}tour,\u{0020}letting\u{0020}everyone\u{0020}hear\u{0020}our\u{0020}music...\u{0020}Navigator?\u{0020}Why\u{0020}do\u{0020}you\u{0020}look\u{0020}like\u{0020}you've\u{0020}seen\u{0020}the\u{0020}end\u{0020}of\u{0020}the\u{0020}world?!", "0", "真希望有一天，我們樂隊能開巡迴演唱會，讓全世界的人聽到我們的音樂……領航？你為什麼是一副看到世界末日的表情！", "0", "真希望有一天，我们乐队能开巡回演唱会，让全世界的人听到我们的音乐……领航？你为什么是一副看到世界末日的表情！", "0", "cv_saraid_31", "0", "0"},
[421607] = {421607, 12016, 8, 5, "1_》_0_0.8", "level1", "Even\u{0020}if\u{0020}you're\u{0020}a\u{0020}fan,\u{0020}Navigator,\u{0020}you\u{0020}still\u{0020}need\u{0020}to\u{0020}respect\u{0020}personal\u{0020}space!", "0", "就算是fan領航，對於skinship也要注意喔。", "0", "就算是fan领航，对于skinship也要注意哦。", "0", "cv_saraid_5", "0", "0"},
[421608] = {421608, 12016, 9, 5, "1_》_100_1.5", "level2", "Navigator,\u{0020}if\u{0020}you\u{0020}have\u{0020}time,\u{0020}want\u{0020}to\u{0020}go\u{0020}shopping\u{0020}with\u{0020}me?\u{0020}My\u{0020}favorite\u{0020}band\u{0020}just\u{0020}released\u{0020}a\u{0020}new\u{0020}song!\u{0020}I'm\u{0020}dying\u{0020}to\u{0020}know\u{0020}what\u{0020}it\u{0020}sounds\u{0020}like!", "0", "領航，要是有空的話要不要一起去商店轉轉？喜歡的樂隊出新曲了！到底是怎樣的曲子呢……好在意啊！", "0", "领航，要是有空的话要不要一起去商店转转？喜欢的乐队出新曲了！到底是怎样的曲子呢……好在意啊！", "0", "cv_saraid_6", "0", "0"},
[421609] = {421609, 12016, 10, 5, "1_》_500_2", "level3", "Ah~\u{0020}Ah~\u{0020}Ah~\u{0020}Ah~—Navigator?!\u{0020}When\u{0020}did\u{0020}you\u{0020}get\u{0020}here!?\u{0020}Oh\u{0020}no...\u{0020}can\u{0020}we\u{0020}pretend\u{0020}you\u{0020}didn't\u{0020}hear\u{0020}that?\u{0020}Please!", "0", "啊~啊~啊~啊~啊！——領航？你什麼時候來的！？糟糕…能不能當做什麼都沒聽見呢？拜託了！", "0", "啊~啊~啊~啊~啊！——领航？你什么时候来的！？糟糕…能不能当做什么都没听见呢？拜托了！", "0", "cv_saraid_7", "0", "0"},
[421610] = {421610, 12016, 11, 5, "1_》_1000_2.5", "level4", "Navigator,\u{0020}here\u{0020}are\u{0020}tickets\u{0020}to\u{0020}our\u{0020}band's\u{0020}concert\u{0020}next\u{0020}week.\u{0020}You\u{0020}have\u{0020}to\u{0020}come!\u{0020}I've\u{0020}prepared\u{0020}a\u{0020}special\u{0020}song\u{0020}just\u{0020}for\u{0020}you...\u{0020}Wait,\u{0020}why\u{0020}are\u{0020}you\u{0020}running\u{0020}away?!", "0", "領航，這是下週樂隊演唱會的門票。請一定要來參加！我為領航準備了特別的樂曲……領航，為什麼要跑啊！", "0", "领航，这是下周乐队演唱会的门票。请一定要来参加！我为领航准备了特别的乐曲……领航，为什么要跑啊！", "0", "cv_saraid_8", "0", "0"},
[421611] = {421611, 12016, 12, 6, "0", "0", "I'm\u{0020}going\u{0020}to\u{0020}create\u{0020}an\u{0020}even\u{0020}more\u{0020}beautiful\u{0020}melody.", "0", "我將獻上更動聽的旋律。", "0", "我将献上更动听的旋律。", "0", "cv_saraid_9", "0", "0"},
[421612] = {421612, 12016, 13, 7, "0", "0", "I\u{0020}want\u{0020}to\u{0020}bring\u{0020}hope\u{0020}to\u{0020}everyone—the\u{0020}stage\u{0020}will\u{0020}always\u{0020}carry\u{0020}my\u{0020}wish!", "0", "我想要給大家帶來希望，而舞臺一直會承載著我的願望！", "0", "我想要给大家带来希望，而舞台一直会承载着我的愿望！", "0", "cv_saraid_10", "0", "0"},
[421613] = {421613, 12016, 14, 8, "0", "0", "Music\u{0020}has\u{0020}endless\u{0020}possibilities,\u{0020}and\u{0020}now\u{0020}I\u{0020}finally\u{0020}feel\u{0020}like\u{0020}I\u{0020}can\u{0020}reach\u{0020}them.\u{0020}Thank\u{0020}you,\u{0020}Navigator.\u{0020}You've\u{0020}helped\u{0020}my\u{0020}music\u{0020}soar\u{0020}further\u{0020}than\u{0020}ever\u{0020}before.", "0", "音樂裏飽含著無限的可能性。我感覺到現在我可以真正地抓住這可能性了。謝謝你，領航。你給我和我的音樂能夠飛向更遠處。", "0", "音乐里饱含着无限的可能性。我感觉到现在我可以真正地抓住这可能性了。谢谢你，领航。你给我和我的音乐能够飞向更远处。", "0", "cv_saraid_11", "0", "0"},
