[421630] = {421630, 12016, 32, 24, "0", "0", "You\u{0020}really\u{0020}are\u{0020}my\u{0020}number\u{0020}one\u{0020}fan,\u{0020}and\u{0020}that\u{0020}makes\u{0020}me\u{0020}so\u{0020}happy!", "0", "領航不愧是我的頭號粉絲，好開心~", "0", "领航不愧是我的头号粉丝，好开心~", "0", "cv_saraid_28", "0", "0"},
[421631] = {421631, 12016, 33, 25, "0", "0", "I'll\u{0020}make\u{0020}sure\u{0020}you\u{0020}remember\u{0020}me—this\u{0020}feeling\u{0020}is\u{0020}woven\u{0020}into\u{0020}the\u{0020}music.", "0", "一定會讓你記住我的！這份心情，融入音樂中。", "0", "一定会让你记住我的！这份心情，融入音乐中。", "0", "cv_saraid_29", "0", "0"},
