[421701] = {421701, 12017, 2, 2, "0", "0", "Sorry\u{0020}to\u{0020}keep\u{0020}you\u{0020}waiting!\u{0020}Suzu's\u{0020}super-genius\u{0020}mode\u{0020}is\u{0020}on!\u{0020}Let's\u{0020}start\u{0020}the\u{0020}experiment...\u{0020}Huh?\u{0020}You\u{0020}want\u{0020}to\u{0020}know\u{0020}my\u{0020}usual\u{0020}mode?\u{0020}Obviously,\u{0020}it's\u{0020}always\u{0020}genius\u{0020}mode!", "お待たせー！鈴、超天才モードの準備オッケー！実験を開始するよー！……え、普段はどんなモード？当然、天才モードだけど？", "久等了！——鈴的超天才模式已經準備就緒了！實驗開始……誒？你問平時是什麼狀態？——那當然是天才模式啦？！", "0", "0", "0", "cv_lin_sw_1", "0", "0"},
[421702] = {421702, 12017, 3, 3, "0", "0", "Wow!\u{0020}Can\u{0020}I\u{0020}bring\u{0020}my\u{0020}sun\u{0020}umbrella\u{0020}here\u{0020}too?\u{0020}Mizunokomaru,\u{0020}come\u{0020}over\u{0020}here!", "うわぁ！ここにパラソル差しちゃっていい？きつね丸たちもこっちにおいでー！", "哇，我把太陽傘一起帶到這裏可以嗎？水之狐丸也過來這邊吧~", "0", "0", "0", "cv_lin_sw_2", "0", "0"},
[421703] = {421703, 12017, 4, 4, "0", "idle", "Navigator,\u{0020}I've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}you\u{0020}here\u{0020}forever!\u{0020}Let's\u{0020}go!\u{0020}Hehe,\u{0020}this\u{0020}summer,\u{0020}I'll\u{0020}make\u{0020}sure\u{0020}to\u{0020}give\u{0020}you\u{0020}unforgettable\u{0020}memories!—What?\u{0020}Did\u{0020}I\u{0020}mess\u{0020}up\u{0020}that\u{0020}saying?\u{0020}No\u{0020}way!", "ナビゲーター、待ってたよー！早く行こー！ふっふーん。この夏は、ゆりかごから墓場までの思い出を天才のあたしが作ってあげるんだから！……言葉の使い方を間違ってる？そ、そんなことないもん！", "領航，我在這裏等了你好久呢！快走吧！呼呼，這個夏天，本天才一定要讓你留下拍案叫絕的回憶的！——你說我成語用錯了？才沒有！", "0", "0", "0", "cv_lin_sw_3", "0", "0"},
[421704] = {421704, 12017, 5, 4, "0", "idle", "Even\u{0020}a\u{0020}super\u{0020}genius\u{0020}faces\u{0020}challenges\u{0020}sometimes!\u{0020}If\u{0020}everything\u{0020}were\u{0020}easy,\u{0020}life\u{0020}would\u{0020}be\u{0020}too\u{0020}boring!", "超天才にだって悩みくらいあるよ。何もかもぜーんぶ分かっちゃったら、つまんないでしょ？", "超天才也會遇到困擾的事情哦！如果全都一下子就看懂的話，豈不是太無聊了！", "0", "0", "0", "cv_lin_sw_4", "0", "0"},
[421705] = {421705, 12017, 6, 4, "0", "idle", "I\u{0020}wish\u{0020}this\u{0020}summer\u{0020}scene\u{0020}could\u{0020}last\u{0020}a\u{0020}little\u{0020}longer...\u{0020}but\u{0020}we\u{0020}can't\u{0020}stand\u{0020}still,\u{0020}Navigator.\u{0020}We\u{0020}have\u{0020}to\u{0020}keep\u{0020}moving\u{0020}forward.", "この夏がもっと続いてくれたらなぁ……。でも、ダメだよね。ナビゲーターもあたしも、前に進まなきゃ。", "真想要讓這夏日的場景再停留一會啊~但是這樣是不行的，領航和我都要向前跑才對。", "0", "0", "0", "cv_lin_sw_30", "0", "0"},
[421706] = {421706, 12017, 7, 5, "1_》_0_0.8", "level1", "\"Am\u{0020}I\u{0020}a\u{0020}hero\u{0020}now?\"\u{0020}\"Have\u{0020}I\u{0020}become\u{0020}a\u{0020}force\u{0020}that\u{0020}protects\u{0020}everyone?\"\u{0020}Sometimes\u{0020}I\u{0020}wonder.\u{0020}Maybe\u{0020}it's\u{0020}thoughts\u{0020}like\u{0020}these\u{0020}that\u{0020}kept\u{0020}me\u{0020}from\u{0020}straying\u{0020}too\u{0020}far.", "ヒーローになれたか……みんなを守れるのか……時々、そんなことを考えちゃうんだ。だからこそ、いまのあたしがあるんだけどね。", "“我成為了一個英雄了嗎”“我成為保護大家的力量了嗎？”我有的時候會這麼想。也許正是因為這樣的想法，我才沒有走太多歪路吧。", "0", "0", "0", "cv_lin_sw_31", "0", "0"},
[421707] = {421707, 12017, 8, 5, "1_》_0_0.8", "level1", "Navigator!\u{0020}Navigator!\u{0020}Look,\u{0020}I\u{0020}got\u{0020}perfect\u{0020}scores\u{0020}on\u{0020}all\u{0020}my\u{0020}exams\u{0020}this\u{0020}time!\u{0020}Praise\u{0020}me,\u{0020}praise\u{0020}me!", "ナビゲーター見て見てー！今回のテスト全部満点だったよ！褒めて褒めてー！", "領航！領航！你看，我這次考試全部都是滿分哦？誇我誇我！", "0", "0", "0", "cv_lin_sw_5", "0", "0"},
[421708] = {421708, 12017, 9, 5, "1_》_100_1.5", "level2", "You're\u{0020}asking\u{0020}if\u{0020}my\u{0020}ears\u{0020}are\u{0020}real?\u{0020}Of\u{0020}course\u{0020}they\u{0020}are!\u{0020}Wanna\u{0020}touch\u{0020}them?—Ah!\u{0020}No\u{0020}touching!\u{0020}They're\u{0020}too\u{0020}sensitive!", "この耳が本物かって？もちろん本物だよー。触ってみたい？……ひゃっ！急に触んないでよ、敏感なんだから！", "你問我頭上的耳朵是不是真的？當然是真的啦！你要摸摸看嗎？——呀！不許摸，太敏感了！", "0", "0", "0", "cv_lin_sw_6", "0", "0"},
[421709] = {421709, 12017, 10, 5, "1_》_500_2", "level3", "Is\u{0020}this\u{0020}a\u{0020}dream\u{0020}world?\u{0020}When\u{0020}all\u{0020}of\u{0020}this\u{0020}ends,\u{0020}will\u{0020}everyone\u{0020}forget\u{0020}this\u{0020}memory?\u{0020}I\u{0020}need\u{0020}to\u{0020}find\u{0020}a\u{0020}way\u{0020}to\u{0020}make\u{0020}sure\u{0020}I\u{0020}remember\u{0020}our\u{0020}time\u{0020}together,\u{0020}Navigator.", "ここってまぼろしの世界だよね？ぜんぶ終わったらみんなここの事、忘れちゃうのかな？じゃあこの天才が、思い出を残す方法を見つけてみせるよ！", "這裏是虛幻的世界呢？是這樣嗎？一切都結束之後，大家都會淡忘這段記憶嗎？那麼本天才就想一想，有沒有辦法保留下我與你的這段回憶了。", "0", "0", "0", "cv_lin_sw_7", "0", "0"},
[421710] = {421710, 12017, 11, 5, "1_》_1000_2.5", "level4", "This\u{0020}is\u{0020}such\u{0020}a\u{0020}sweet\u{0020}dream...\u{0020}But\u{0020}if,\u{0020}and\u{0020}I\u{0020}mean\u{0020}if,\u{0020}I'm\u{0020}no\u{0020}longer\u{0020}a\u{0020}super\u{0020}genius,\u{0020}would\u{0020}you\u{0020}still\u{0020}remember\u{0020}me,\u{0020}Navigator?\u{0020}I\u{0020}promise,\u{0020}I'll\u{0020}never\u{0020}forget!", "この夢、ずーっと見ていたいなぁ。……もし、もしもなんだけどさ……あたしが超天才じゃなくなっても、ナビゲーターは覚えていてくれるかな？あたしは絶対、絶っ対忘れないよ！", "這真是一段讓人能沉溺在其中的美夢……如果，我是說如果，我不再是超天才。領航……你還會記得這樣的我嗎……我絕對，絕對不會忘記的！", "0", "0", "0", "cv_lin_sw_8", "0", "0"},
[421711] = {421711, 12017, 12, 6, "0", "0", "Summer\u{0020}power\u{0020}is\u{0020}on\u{0020}the\u{0020}rise!", "サマーパワーレベルアァァップッ！", "夏日力提升了。", "0", "0", "0", "cv_lin_sw_9", "0", "0"},
[421712] = {421712, 12017, 13, 7, "0", "0", "Oh!\u{0020}The\u{0020}swimming\u{0020}suit\u{0020}power\u{0020}is\u{0020}filling\u{0020}me\u{0020}up!", "おおぉ！水着パワーがみなぎってきたぁ！", "哦！鼓動的泳裝力量充斥著我的全身。", "0", "0", "0", "cv_lin_sw_10", "0", "0"},
[421713] = {421713, 12017, 14, 8, "0", "0", "Is\u{0020}this\u{0020}my\u{0020}limit?\u{0020}Hmph,\u{0020}a\u{0020}genius\u{0020}never\u{0020}halts!\u{0020}Limits\u{0020}are\u{0020}meant\u{0020}to\u{0020}be\u{0020}broken!", "これがあたしの限界？……ふふん、天才に不可能はないんだよ。限界は超えるものだもんね！", "這就是我的極限了？哼哼，天才是不會停下自己的腳步的，極限就是用來超越的！", "0", "0", "0", "cv_lin_sw_11", "0", "0"},
[421714] = {421714, 12017, 15, 9, "0", "0", "Knowledge\u{0020}accumulation\u{0020}is\u{0020}crucial\u{0020}too...\u{0020}But\u{0020}I\u{0020}really\u{0020}hate\u{0020}reading\u{0020}books!!!", "勉強しなくちゃいけないことはいっぱいあるけど……本は嫌いなの！", "知識的積累也很重要呢……但是呢，我討厭看書！！！", "0", "0", "0", "cv_lin_sw_12", "0", "0"},
[421715] = {421715, 12017, 16, 10, "0", "0", "The\u{0020}genius\u{0020}has\u{0020}arrived.\u{0020}Everyone,\u{0020}stay\u{0020}behind\u{0020}me.\u{0020}I'll\u{0020}protect\u{0020}you!", "天才様のお出ましだよー！あたしが守るから、みんな後ろに下がって！", "天才登場，大家就退到我身後吧，我會保護你們的！", "0", "0", "0", "cv_lin_sw_13", "0", "0"},
[421716] = {421716, 12017, 17, 11, "0", "0", "The\u{0020}experiment\u{0020}is\u{0020}a\u{0020}success.\u{0020}The\u{0020}operation\u{0020}executed\u{0020}flawlessly.\u{0020}As\u{0020}expected\u{0020}from\u{0020}the\u{0020}super-genius\u{0020}me!", "実験成功！完璧な作戦だったね。さすがあたし、超天才！", "實驗成功。作戰完美執行。不愧是超天才的我！", "0", "0", "0", "cv_lin_sw_14", "0", "0"},
[421717] = {421717, 12017, 18, 12, "0", "0", "I've\u{0020}accounted\u{0020}for\u{0020}expected\u{0020}losses.\u{0020}I've\u{0020}already\u{0020}plotted\u{0020}the\u{0020}next\u{0020}course\u{0020}of\u{0020}action\u{0020}for\u{0020}you.\u{0020}Get\u{0020}it\u{0020}together!", "これくらい想定内だよ。次の作戦も準備できてるから、切り替えていこー！", "預料之中的損失，我已經幫你把下一次的行動路線規劃好了，重整旗鼓吧！", "0", "0", "0", "cv_lin_sw_15", "0", "0"},
[421718] = {421718, 12017, 19, 13, "0", "0", "Ugh...\u{0020}The\u{0020}situation\u{0020}hasn't\u{0020}slipped\u{0020}from\u{0020}our\u{0020}grasp.\u{0020}Navigator,\u{0020}don't\u{0020}lose\u{0020}hope!", "ぐぬぬ……もっとうまくできるはずだよ。ナビゲーター、がんばろー！", "呃嗯嗯……事態還沒脫離我們的掌控，領航不要放棄啊！", "0", "0", "0", "cv_lin_sw_16", "0", "0"},
[421719] = {421719, 12017, 20, 14, "0", "0", "Huh...\u{0020}It\u{0020}seems\u{0020}the\u{0020}future\u{0020}I\u{0020}envisioned\u{0020}isn't\u{0020}quite\u{0020}enough.", "うぅ……あたしの読みが甘かったかぁ……", "嗚……看來我所預設的未來還不夠充分。", "0", "0", "0", "cv_lin_sw_17", "0", "0"},
[421720] = {421720, 12017, 21, 15, "0", "0", "Aha,\u{0020}one-hit\u{0020}kill!", "えっへん、一撃必殺！", "哎嘿，一擊必殺！", "0", "0", "0", "cv_lin_sw_18", "0", "0"},
[421721] = {421721, 12017, 23, 16, "0", "0", "Hey!", "ほいっ！", "嘿！", "0", "0", "0", "cv_lin_sw_19", "0", "0"},
[421722] = {421722, 12017, 24, 17, "0", "0", "This\u{0020}is\u{0020}the\u{0020}perfect\u{0020}moment\u{0020}to\u{0020}showcase\u{0020}the\u{0020}strength\u{0020}of\u{0020}a\u{0020}genius!", "天才の実力をみせる時だぁー！", "這就是展現天才實力的最佳時機！", "0", "0", "0", "cv_lin_sw_21", "0", "0"},
[421723] = {421723, 12017, 25, 18, "0", "0", "Summer!\u{0020}Swimsuits!\u{0020}The\u{0020}conceptual\u{0020}energy\u{0020}of\u{0020}the\u{0020}super-genius\u{0020}is\u{0020}overflowing\u{0020}right\u{0020}now.\u{0020}There's\u{0020}no\u{0020}backing\u{0020}down\u{0020}in\u{0020}this\u{0020}midsummer\u{0020}experiment\u{0020}zone.\u{0020}This\u{0020}is\u{0020}a\u{0020}water\u{0020}research\u{0020}party\u{0020}meant\u{0020}to\u{0020}be\u{0020}understood\u{0020}through\u{0020}firsthand\u{0020}experience!", "夏！そして水着！超天才のエネルギーが溢れ出ているっ！真夏の実験場に出口なし！これは体験してみないとわからない水の実験パーティーだー！", "夏日！泳裝！超天才的概念能量在此時溢滿而出。盛夏的實驗場沒有退路，這是只有親身體驗才能明白的水之研究派對！", "0", "0", "0", "cv_lin_sw_22", "0", "0"},
[421724] = {421724, 12017, 22, 38, "0", "0", "Found\u{0020}it!", "発見っ！", "找到了！", "0", "0", "0", "cv_lin_sw_45", "0", "0"},
[421725] = {421725, 12017, 26, 19, "0", "0", "Komaru,\u{0020}activate\u{0020}the\u{0020}emergency\u{0020}evacuation\u{0020}device...", "きつね丸、緊急脱出装置を……", "狐丸，啟動緊急撤退裝置……", "0", "0", "0", "cv_lin_sw_20", "0", "0"},
