[421729] = {421729, 12017, 30, 22, "0", "0", "Navigator?!\u{0020}Are\u{0020}you\u{0020}coming\u{0020}too?", "ナビゲーター！い、一緒に行くか？", "領航？！你、你也一起來嗎。", "0", "0", "0", "cv_lin_sw_26", "0", "0"},
[421730] = {421730, 12017, 31, 23, "0", "0", "Argh,\u{0020}I\u{0020}should've\u{0020}put\u{0020}on\u{0020}sunscreen...\u{0020}I'm\u{0020}starting\u{0020}to\u{0020}feel\u{0020}the\u{0020}sting\u{0020}of\u{0020}the\u{0020}sun,\u{0020}that\u{0020}tingling\u{0020}sensation...", "あああ……日焼けしすぎてちょっと痛いぃー。オイル塗るの忘れてたぁ……", "哇嗚嗚，被太陽曬的地方有點痛，應該抹防曬霜的……", "0", "0", "0", "cv_lin_sw_27", "0", "0"},
[421731] = {421731, 12017, 32, 24, "0", "0", "Just\u{0020}hearing\u{0020}the\u{0020}voice,\u{0020}I'm\u{0020}sure\u{0020}you\u{0020}knew\u{0020}it\u{0020}was\u{0020}my\u{0020}great\u{0020}genius\u{0020}all\u{0020}along!", "天才の声を間違えるはずないよねー！", "聽到聲音就知道了吧？就是本天才哦！", "0", "0", "0", "cv_lin_sw_28", "0", "0"},
[421732] = {421732, 12017, 33, 25, "0", "0", "Eh...?\u{0020}You\u{0020}hurt\u{0020}me!\u{0020}Navigator\u{0020}is\u{0020}a\u{0020}fool!", "ちょ、ちょっと、痛いんだけどー！ナビゲーターのバカッ！", "欸……？你把我弄疼啦！領航是笨蛋！", "0", "0", "0", "cv_lin_sw_29", "0", "0"},
[421733] = {421733, 12017, 34, 26, "0", "0", "Welcome\u{0020}back.\u{0020}We're\u{0020}going\u{0020}to\u{0020}have\u{0020}a\u{0020}party\u{0020}soon!\u{0020}Barbecue\u{0020}party!", "おかえりー！もうすぐパーティーがはじまるよー！焼肉パーティー！", "歡迎回來，我們馬上就要開party了！燒烤party！", "0", "0", "0", "cv_lin_sw_32", "0", "0"},
