[421735] = {421735, 12017, 36, 28, "0", "0", "I\u{0020}won't\u{0020}lose\u{0020}if\u{0020}it's\u{0020}a\u{0020}swimming\u{0020}competition!", "泳ぎなら負けないもんね！", "比游泳的話我可不會輸哦！", "0", "0", "0", "cv_lin_sw_35", "0", "0"},
[421736] = {421736, 12017, 37, 29, "0", "0", "I\u{0020}brought\u{0020}you\u{0020}all\u{0020}souvenirs.", "お土産持ってきたよー！", "我給你們帶了伴手禮哦~", "0", "0", "0", "cv_lin_sw_36", "0", "0"},
[421737] = {421737, 12017, 38, 30, "0", "0", "Why\u{0020}doesn't\u{0020}everyone\u{0020}come\u{0020}out\u{0020}to\u{0020}play?", "みんな遊ばないの？", "大家為什麼都不出來玩？", "0", "0", "0", "cv_lin_sw_37", "0", "0"},
[421738] = {421738, 12017, 39, 31, "0", "0", "Equip\u{0020}Komaru\u{0020}with\u{0020}a\u{0020}life\u{0020}buoy\u{0020}too...\u{0020}Ah,\u{0020}it\u{0020}seems\u{0020}to\u{0020}be\u{0020}able\u{0020}to\u{0020}fly?", "きつね丸にも浮き輪を……あ、飛べるからいらないか。", "給狐丸也配個救生圈……啊，好像能飛欸？", "0", "0", "0", "cv_lin_sw_38", "0", "0"},
[421739] = {421739, 12017, 40, 32, "0", "0", "I\u{0020}want\u{0020}sunscreen!\u{0020}Navigator,\u{0020}apply\u{0020}it\u{0020}on\u{0020}my\u{0020}back\u{0020}for\u{0020}me!", "日焼け止め買ったんだー！ナビゲーター、背中に塗って塗ってー！", "我要防曬霜！領航幫我抹背上！", "0", "0", "0", "cv_lin_sw_39", "0", "0"},
