[421800] = {421800, 12018, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_xhixha_1", "0", "0"},
[421801] = {421801, 12018, 2, 2, "0", "0", "Just\u{0020}leave\u{0020}everything\u{0020}to\u{0020}me!", "0", "全部交給我就好~", "0", "0", "0", "cv_xhixha_2", "0", "0"},
[421802] = {421802, 12018, 3, 3, "0", "0", "Poynred's\u{0020}chief\u{0020}bridge\u{0020}designer,\u{0020}Shisha\u{0020}is\u{0020}here!\u{0020}Let\u{0020}the\u{0020}massive\u{0020}body\u{0020}of\u{0020}mine\u{0020}carry\u{0020}your\u{0020}will\u{0020}and\u{0020}raise\u{0020}a\u{0020}bridge\u{0020}to\u{0020}the\u{0020}future,\u{0020}if\u{0020}you\u{0020}don't\u{0020}mind.", "0", "珀因雷德首席橋梁設計師——希夏報道！不介意的話，就讓我用這副巨大身軀承載你的意志，成為架向未來之橋吧~", "0", "0", "0", "cv_xhixha_3", "0", "0"},
[421803] = {421803, 12018, 4, 4, "0", "idle", "I've\u{0020}visited\u{0020}Danube\u{0020}on\u{0020}business\u{0020}before,\u{0020}but\u{0020}the\u{0020}city\u{0020}looks\u{0020}quite\u{0020}different\u{0020}from\u{0020}a\u{0020}Driver's\u{0020}vantage\u{0020}point.\u{0020}Every\u{0020}place\u{0020}holds\u{0020}its\u{0020}own\u{0020}unique\u{0020}vista.", "0", "以前也偶爾因工作來到多瑙，不過以駕駛員的身份俯瞰城市還是會不免感歎，不同地方的風景果然大相徑庭呢。", "0", "0", "0", "cv_xhixha_4", "0", "0"},
[421804] = {421804, 12018, 5, 4, "0", "idle2", "You're\u{0020}so\u{0020}quiet,\u{0020}Navigator.\u{0020}Lost\u{0020}in\u{0020}thought?\u{0020}I\u{0020}often\u{0020}draw\u{0020}a\u{0020}blank\u{0020}during\u{0020}my\u{0020}design\u{0020}work.\u{0020}I\u{0020}find\u{0020}that\u{0020}a\u{0020}small\u{0020}drink\u{0020}can\u{0020}sometimes\u{0020}shake\u{0020}loose\u{0020}a\u{0020}brilliant\u{0020}idea.\u{0020}Perhaps\u{0020}you\u{0020}might\u{0020}try\u{0020}it?", "0", "領航一動不動的，是在沉思什麼嗎？我在設計工作中也常常陷入苦惱，不過小酌一杯的話，偶爾可能會靈感乍現，領航也試試看吧？", "0", "0", "0", "cv_xhixha_5", "0", "0"},
[421805] = {421805, 12018, 6, 4, "0", "idle3", "It\u{0020}was\u{0020}understandable,\u{0020}but\u{0020}now\u{0020}that\u{0020}she's\u{0020}a\u{0020}Driver,\u{0020}Heine\u{0020}still\u{0020}refuses\u{0020}to\u{0020}leave\u{0020}her\u{0020}room\u{0020}for\u{0020}training.\u{0020}Perhaps\u{0020}you\u{0020}could\u{0020}persuade\u{0020}her\u{0020}to\u{0020}join\u{0020}us\u{0020}for\u{0020}our\u{0020}next\u{0020}workout,\u{0020}Navigator?\u{0020}She\u{0020}would\u{0020}never\u{0020}say\u{0020}no\u{0020}to\u{0020}you.", "0", "之前也就算了，成為駕駛員後海因卻還是窩在房裡不肯鍛煉，要不我們下次健身時也叫上她一起？領航你去邀請的話，她肯定不會拒絕的。", "0", "0", "0", "cv_xhixha_6", "0", "0"},
[421806] = {421806, 12018, 7, 5, "1_》_0_0.8", "level1", "The\u{0020}flower\u{0020}on\u{0020}my\u{0020}head?\u{0020}It's\u{0020}an\u{0020}iris.\u{0020}They\u{0020}bloom\u{0020}in\u{0020}profusion\u{0020}across\u{0020}the\u{0020}central\u{0020}valley\u{0020}of\u{0020}Poynred.\u{0020}It's\u{0020}a\u{0020}symbol\u{0020}of\u{0020}the\u{0020}Rainbow\u{0020}Goddess,\u{0020}you\u{0020}know—said\u{0020}to\u{0020}be\u{0020}messengers\u{0020}between\u{0020}the\u{0020}divine\u{0020}and\u{0020}mortal\u{0020}realm.", "0", "我頭上的花？是喲，這是鳶尾花髮飾，在珀因雷德中央峽谷間也盛放著這道色彩，它被譽為彩虹女神的象征，也是連接神界與人間的使者哦。", "0", "0", "0", "cv_xhixha_7", "0", "0"},
[421807] = {421807, 12018, 8, 5, "1_》_0_0.8", "level1", "Shall\u{0020}we\u{0020}hang\u{0020}out\u{0020}after\u{0020}our\u{0020}duties\u{0020}are\u{0020}done?\u{0020}Danube\u{0020}is\u{0020}vast,\u{0020}and\u{0020}I'm\u{0020}sure\u{0020}it\u{0020}holds\u{0020}countless\u{0020}curiosities\u{0020}I've\u{0020}yet\u{0020}to\u{0020}find.\u{0020}What\u{0020}is\u{0020}your\u{0020}favorite\u{0020}restaurant,\u{0020}Navigator?\u{0020}Any\u{0020}park\u{0020}you\u{0020}like?\u{0020}I'd\u{0020}love\u{0020}your\u{0020}recommendations!", "0", "下班後要一起去逛逛嗎？多瑙這麼大，肯定還有很多有趣的地方我沒去過，領航最喜歡哪家餐廳，哪片公園？歡迎向我推薦！", "0", "0", "0", "cv_xhixha_8", "0", "0"},
[421808] = {421808, 12018, 9, 5, "1_》_100_1.5", "level2", "I\u{0020}may\u{0020}have\u{0020}gone\u{0020}on\u{0020}a\u{0020}bit\u{0020}of\u{0020}a\u{0020}shopping\u{0020}spree...\u{0020}model\u{0020}kits,\u{0020}train\u{0020}sets,\u{0020}and\u{0020}a\u{0020}cat\u{0020}tree.\u{0020}I'm\u{0020}thinking\u{0020}of\u{0020}turning\u{0020}my\u{0020}place\u{0020}in\u{0020}Danube\u{0020}into\u{0020}a\u{0020}little\u{0020}theme\u{0020}park.\u{0020}I\u{0020}just\u{0020}love\u{0020}building\u{0020}things.", "0", "最近又買了好多東西，拼裝積木，鐵道模型，還有貓爬架，我想在多瑙這邊的家裡也建一個微縮版遊樂園，這就是工程設計的樂趣~", "0", "0", "0", "cv_xhixha_9", "0", "0"},
[421809] = {421809, 12018, 10, 5, "1_》_500_2", "level3", "A\u{0020}simple\u{0020}touch\u{0020}is\u{0020}nice,\u{0020}but...\u{0020}I'd\u{0020}rather\u{0020}have\u{0020}a\u{0020}real\u{0020}connection.\u{0020}Like\u{0020}that\u{0020}first\u{0020}time\u{0020}we\u{0020}did\u{0020}a\u{0020}Synesthesia.\u{0020}Everything—the\u{0020}city,\u{0020}the\u{0020}mountain,\u{0020}my\u{0020}heart—just\u{0020}felt\u{0020}so\u{0020}clear\u{0020}and\u{0020}peaceful.", "0", "比起單純觸碰，我想要更加親密的接觸，比如……我還記得我們初次進行通感時的那份感受，城市、山巒，以及心靈都變得像天空一樣澄澈透明。", "0", "0", "0", "cv_xhixha_10", "0", "0"},
[421810] = {421810, 12018, 11, 5, "1_》_1000_2.5", "level4", "A\u{0020}bridge\u{0020}is\u{0020}not\u{0020}really\u{0020}the\u{0020}start\u{0020}or\u{0020}the\u{0020}end.\u{0020}It's\u{0020}the\u{0020}journey\u{0020}across,\u{0020}the\u{0020}moment\u{0020}that\u{0020}connects\u{0020}our\u{0020}past\u{0020}and\u{0020}our\u{0020}future.\u{0020}Focus\u{0020}on\u{0020}now,\u{0020}and\u{0020}we'll\u{0020}always\u{0020}know\u{0020}where\u{0020}we're\u{0020}going.", "0", "所謂橋樑，是既不在此岸也不在彼端之物，它只是一種“過程”，就像連通著過去與未來的“此時此刻”。當我們漫步在時間之橋上，只要著眼於當下的每個瞬間，就絕不會迷失方向。", "0", "0", "0", "cv_xhixha_11", "0", "0"},
[421811] = {421811, 12018, 12, 6, "0", "0", "Thanks.", "0", "感謝~", "0", "0", "0", "cv_xhixha_12", "0", "0"},
[421812] = {421812, 12018, 13, 7, "0", "0", "It\u{0020}feels\u{0020}nice\u{0020}getting\u{0020}improved.", "0", "提升的感覺真不錯。", "0", "0", "0", "cv_xhixha_13", "0", "0"},
[421813] = {421813, 12018, 14, 8, "0", "0", "I\u{0020}like\u{0020}to\u{0020}look\u{0020}on\u{0020}the\u{0020}bright\u{0020}side.\u{0020}So\u{0020}I\u{0020}see\u{0020}greater\u{0020}power\u{0020}not\u{0020}as\u{0020}a\u{0020}burden\u{0020}of\u{0020}responsibility\u{0020}or\u{0020}peril.\u{0020}It\u{0020}means\u{0020}I\u{0020}get\u{0020}to\u{0020}do\u{0020}it\u{0020}all\u{0020}with\u{0020}you\u{0020}by\u{0020}my\u{0020}side\u{0020}and\u{0020}that\u{0020}matters\u{0020}more.", "0", "我自認為是個樂觀主義者，所以隨能力增長帶來的更多責任、更大的危險之類都沒什麼好擔憂的，比起那些，更重要的是我今後能與你一起做到更多。", "0", "0", "0", "cv_xhixha_14", "0", "0"},
[421814] = {421814, 12018, 15, 9, "0", "0", "Build\u{0020}it\u{0020}up,\u{0020}make\u{0020}it\u{0020}strong.", "0", "修築，然後鞏固。", "0", "0", "0", "cv_xhixha_15", "0", "0"},
[421815] = {421815, 12018, 16, 10, "0", "0", "I\u{0020}wonder...\u{0020}what\u{0020}destination\u{0020}does\u{0020}a\u{0020}battle\u{0020}lead\u{0020}to?", "0", "戰鬥，會是一座通往何方的橋樑？", "0", "0", "0", "cv_xhixha_16", "0", "0"},
[421816] = {421816, 12018, 17, 11, "0", "0", "Looks\u{0020}like\u{0020}this\u{0020}time,\u{0020}we\u{0020}arrived\u{0020}at\u{0020}victory.", "0", "看來這次，我們通向了勝利~", "0", "0", "0", "cv_xhixha_17", "0", "0"},
