[422001] = {422001, 12020, 2, 2, "0", "0", "Phew!\u{0020}...Wait,\u{0020}I'm\u{0020}just\u{0020}supposed\u{0020}to\u{0020}stay\u{0020}here?\u{0020}Okay,\u{0020}got\u{0020}it.", "0", "嘿咻！…誒？只是待在這裏嗎…我明白了……", "0", "0", "0", "cv_flovilla_2", "0", "0"},
[422002] = {422002, 12020, 3, 3, "0", "0", "Whoa,\u{0020}you're\u{0020}the\u{0020}Navigator?\u{0020}I'm\u{0020}Flovira.\u{0020}Looks\u{0020}like\u{0020}I'll\u{0020}be\u{0020}relying\u{0020}on\u{0020}you\u{0020}to\u{0020}lead\u{0020}the\u{0020}way\u{0020}from\u{0020}now\u{0020}on~", "0", "嗚哇哇，你原來是領航嗎？我是弗洛維拉，之後就麻煩你帶路咯~", "0", "0", "0", "cv_flovilla_1", "0", "0"},
[422003] = {422003, 12020, 4, 4, "0", "idle", "Here...\u{0020}and\u{0020}here...\u{0020}Hmm,\u{0020}I've\u{0020}got\u{0020}it\u{0020}all\u{0020}planned!\u{0020}I've\u{0020}mapped\u{0020}out\u{0020}my\u{0020}holiday\u{0020}spots,\u{0020}Navigator.\u{0020}Want\u{0020}to\u{0020}join\u{0020}me?", "0", "這裏…還有這裏…嗯，決定好了！領航，我已經規劃好節假日要去的地方了，你要來嗎？", "0", "0", "0", "cv_flovilla_3", "0", "0"},
[422004] = {422004, 12020, 5, 4, "0", "idle", "Space\u{0020}travel\u{0020}always\u{0020}throws\u{0020}curveballs—like\u{0020}running\u{0020}low\u{0020}on\u{0020}fuel\u{0020}or\u{0020}the\u{0020}navigation\u{0020}system\u{0020}failing.\u{0020}But\u{0020}don't\u{0020}worry,\u{0020}I\u{0020}always\u{0020}figure\u{0020}it\u{0020}out.\u{0020}Pretty\u{0020}impressive,\u{0020}right?", "0", "宇宙航行時總會遇到各種難題,燃料不足、導航系統失靈之類的；不過我總會有辦法解決它們，我很了不起吧！", "0", "0", "0", "cv_flovilla_4", "0", "0"},
[422005] = {422005, 12020, 6, 4, "0", "idle", "Sigh...\u{0020}Thinking\u{0020}back,\u{0020}it\u{0020}was\u{0020}terrifying.\u{0020}Mittoshiva\u{0020}and\u{0020}the\u{0020}others\u{0020}got\u{0020}knocked\u{0020}out\u{0020}in\u{0020}an\u{0020}instant.\u{0020}That\u{0020}thing\u{0020}was\u{0020}a\u{0020}total\u{0020}monster.", "0", "唉…現在想起來還是很可怕啊，密托希瓦她們一瞬間就被拍飛了。那個大家夥，真是個不折不扣的怪物呀。", "0", "0", "0", "cv_flovilla_31", "0", "0"},
[422006] = {422006, 12020, 7, 5, "1_》_0_0.8", "level1", "Why\u{0020}do\u{0020}I\u{0020}travel?\u{0020}Because\u{0020}space\u{0020}is\u{0020}just\u{0020}sitting\u{0020}there\u{0020}waiting!\u{0020}Cough\u{0020}Okay,\u{0020}I\u{0020}admit\u{0020}it—I\u{0020}just\u{0020}love\u{0020}traveling.\u{0020}I\u{0020}want\u{0020}to\u{0020}keep\u{0020}traveling\u{0020}forever,\u{0020}even\u{0020}die\u{0020}on\u{0020}the\u{0020}road.\u{0020}And\u{0020}after\u{0020}I'm\u{0020}gone,\u{0020}I\u{0020}want\u{0020}to\u{0020}keep\u{0020}going.\u{0020}You\u{0020}get\u{0020}that\u{0020}feeling,\u{0020}right?", "0", "為什麼要旅行？因為宇宙就在那裏！咳咳，當然是因為我喜歡旅行啦，想要一直旅行，死在旅行的路上；死了以後也要繼續我的旅行，我的這份心情，你能明白嗎？", "0", "0", "0", "cv_flovilla_32", "0", "0"},
[422007] = {422007, 12020, 8, 5, "1_》_0_0.8", "level1", "Navigator,\u{0020}even\u{0020}if\u{0020}you\u{0020}keep\u{0020}patting\u{0020}me,\u{0020}I'm\u{0020}still\u{0020}not\u{0020}giving\u{0020}you\u{0020}any\u{0020}snacks.", "0", "領航，就算你不停地摸我，我也不會給你零食的。", "0", "0", "0", "cv_flovilla_5", "0", "0"},
[422008] = {422008, 12020, 9, 5, "1_》_100_1.5", "level2", "There\u{0020}are\u{0020}all\u{0020}kinds\u{0020}of\u{0020}aliens\u{0020}out\u{0020}there,\u{0020}and\u{0020}they're\u{0020}fascinating.\u{0020}Huh,\u{0020}am\u{0020}I\u{0020}an\u{0020}alien\u{0020}too?\u{0020}Well,\u{0020}I\u{0020}guess\u{0020}so...", "0", "宇宙裏存在著各種各樣的外星人呢，真的很有趣。誒，我也是外星人？這個…的確呢……", "0", "0", "0", "cv_flovilla_6", "0", "0"},
[422009] = {422009, 12020, 10, 5, "1_》_500_2", "level3", "Navigator,\u{0020}let's\u{0020}go\u{0020}on\u{0020}a\u{0020}trip!\u{0020}Let's\u{0020}leave\u{0020}all\u{0020}our\u{0020}worries\u{0020}behind\u{0020}and\u{0020}just\u{0020}go,\u{0020}the\u{0020}two\u{0020}of\u{0020}us.\u{0020}What\u{0020}do\u{0020}you\u{0020}say?", "0", "領航，我們去旅行吧！丟下所有煩心的、讓人不快樂的事情，來一場只有你和我的旅行，怎麼樣？", "0", "0", "0", "cv_flovilla_7", "0", "0"},
[422010] = {422010, 12020, 11, 5, "1_》_1000_2.5", "level4", "As\u{0020}you\u{0020}already\u{0020}know...\u{0020}the\u{0020}real\u{0020}me\u{0020}is\u{0020}dead.\u{0020}The\u{0020}me\u{0020}you\u{0020}see\u{0020}now\u{0020}might\u{0020}just\u{0020}be\u{0020}a\u{0020}memory.\u{0020}Even\u{0020}so,\u{0020}would\u{0020}you\u{0020}still\u{0020}travel\u{0020}with\u{0020}me?\u{0020}Maybe\u{0020}that\u{0020}means\u{0020}you're\u{0020}my\u{0020}\"final\u{0020}destination.\"", "0", "如你所瞭解的那樣…真正的我已經死了；現在的我，說不定只是一道思念的幻影。即便如此，你也願意與我踏上旅途嗎？這樣的話…或許你就是我的“終點”呢。", "0", "0", "0", "cv_flovilla_8", "0", "0"},
[422011] = {422011, 12020, 12, 6, "0", "0", "Getting\u{0020}stronger\u{0020}sure\u{0020}makes\u{0020}me\u{0020}hungry~", "0", "變強後肚子餓了呢~", "0", "0", "0", "cv_flovilla_9", "0", "0"},
