[422102] = {422102, 12021, 3, 3, "0", "0", "The\u{0020}name's\u{0020}Shaoyin,\u{0020}and\u{0020}I'm\u{0020}ready\u{0020}to\u{0020}order\u{0020}troops\u{0020}or\u{0020}provide\u{0020}strategies\u{0020}as\u{0020}needed!\u{0020}Pleasure\u{0020}to\u{0020}work\u{0020}with\u{0020}you.", "0", "小女子名為韶音，可輔以排兵佈陣，出謀劃策。願共事愉悅。", "0", "0", "0", "cv_shaoyin_3", "0", "0"},
[422103] = {422103, 12021, 4, 4, "0", "idle", "Maybe\u{0020}if\u{0020}I\u{0020}stay\u{0020}quiet\u{0020}and\u{0020}hold\u{0020}my\u{0020}tongue,\u{0020}the\u{0020}Navigator\u{0020}might\u{0020}just\u{0020}stay\u{0020}with\u{0020}me\u{0020}a\u{0020}little\u{0020}longer...?", "0", "只要我保持安靜、不說話，是不是領航就會再多陪我一會兒呢？", "0", "0", "0", "cv_shaoyin_4", "0", "0"},
[422104] = {422104, 12021, 5, 4, "0", "idle", "Heh\u{0020}heh.\u{0020}Silent\u{0020}or\u{0020}otherwise,\u{0020}I\u{0020}know\u{0020}the\u{0020}Navigator's\u{0020}right\u{0020}there\u{0020}beside\u{0020}me.\u{0020}So\u{0020}I'm\u{0020}happy!", "0", "……嘿嘿，即便什麼話都不說，但領航只是陪在身邊，我就好開心啊。", "0", "0", "0", "cv_shaoyin_5", "0", "0"},
[422105] = {422105, 12021, 6, 4, "0", "idle", "If\u{0020}only\u{0020}time\u{0020}could\u{0020}freeze\u{0020}forever,\u{0020}right\u{0020}at\u{0020}this\u{0020}moment...", "0", "真希望時間能永遠停留在當下……", "0", "0", "0", "cv_shaoyin_6", "0", "0"},
[422106] = {422106, 12021, 7, 5, "1_》_0_0.8", "level1", "To\u{0020}what\u{0020}do\u{0020}I\u{0020}owe\u{0020}the\u{0020}pleasure?", "0", "此番造訪，是為何事？", "0", "0", "0", "cv_shaoyin_7", "0", "0"},
[422107] = {422107, 12021, 8, 5, "1_》_0_0.8", "level1", "Just\u{0020}give\u{0020}me\u{0020}the\u{0020}order,\u{0020}Navigator,\u{0020}and\u{0020}I'll\u{0020}attend\u{0020}to\u{0020}it\u{0020}at\u{0020}once.", "0", "既得領航委命，小女子自會事無巨細，事必躬親。", "0", "0", "0", "cv_shaoyin_8", "0", "0"},
[422108] = {422108, 12021, 9, 5, "1_》_100_1.5", "level2", "There's\u{0020}no\u{0020}need\u{0020}for\u{0020}formalities.\u{0020}If\u{0020}you\u{0020}want\u{0020}to\u{0020}touch,\u{0020}that's\u{0020}fine\u{0020}by\u{0020}me...\u{0020}I'm\u{0020}just\u{0020}happy\u{0020}that\u{0020}these\u{0020}antlers\u{0020}of\u{0020}mine\u{0020}caught\u{0020}your\u{0020}attention!", "0", "無需拘謹。既然好奇，多摸一會兒又何妨？小女子——不，是我。我很開心哦。倒不如說，僅靠一對鹿角就能與領航這般親昵，未免也太走運了吧我？！", "0", "0", "0", "cv_shaoyin_9", "0", "0"},
[422109] = {422109, 12021, 10, 5, "1_》_500_2", "level3", "Here\u{0020}for\u{0020}a\u{0020}chat?\u{0020}Sure!\u{0020}I've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}this.\u{0020}There's\u{0020}so\u{0020}much\u{0020}I\u{0020}have\u{0020}to\u{0020}say\u{0020}to\u{0020}you,\u{0020}Navigator.", "0", "要來聊天嗎？好呀。我等這一刻已經很久了，有很多很多話想跟領航您說呢。", "0", "0", "0", "cv_shaoyin_10", "0", "0"},
[422110] = {422110, 12021, 11, 5, "1_》_1000_2.5", "level4", "So,\u{0020}why\u{0020}not\u{0020}stay\u{0020}with\u{0020}me\u{0020}awhile?\u{0020}I\u{0020}know,\u{0020}you've\u{0020}been\u{0020}out\u{0020}on\u{0020}missions\u{0020}with\u{0020}other\u{0020}Drivers\u{0020}recently.\u{0020}You're\u{0020}always\u{0020}in\u{0020}the\u{0020}Commander's\u{0020}Office\u{0020}and\u{0020}I\u{0020}don't\u{0020}get\u{0020}to\u{0020}see\u{0020}you\u{0020}all\u{0020}that\u{0020}often...\u{0020}I,\u{0020}uh,\u{0020}I\u{0020}get\u{0020}lonely\u{0020}too\u{0020}sometimes.\u{0020}Don't\u{0020}leave\u{0020}me\u{0020}alone...", "0", "所以說，再多陪陪我有什麼不好的？最近領航您不是和其他駕駛員去出任務，就是在指揮室裡待著，一天下來都見不了幾面……我、我也是會寂寞的，不要留我一個人在這裡呐……", "0", "0", "0", "cv_shaoyin_11", "0", "0"},
[422111] = {422111, 12021, 12, 6, "0", "0", "Wonderful.", "0", "善矣。", "0", "0", "0", "cv_shaoyin_12", "0", "0"},
[422112] = {422112, 12021, 13, 7, "0", "0", "In\u{0020}me\u{0020}you\u{0020}have\u{0020}placed\u{0020}your\u{0020}trust,\u{0020}and\u{0020}so\u{0020}I\u{0020}shall\u{0020}not\u{0020}let\u{0020}you\u{0020}down.", "0", "此般垂青，定不辜負。", "0", "0", "0", "cv_shaoyin_13", "0", "0"},
[422113] = {422113, 12021, 14, 8, "0", "0", "Praise\u{0020}me...\u{0020}Won't\u{0020}you,\u{0020}Navigator?", "0", "……領航，誇誇我好嗎？", "0", "0", "0", "cv_shaoyin_14", "0", "0"},
[422114] = {422114, 12021, 15, 9, "0", "0", "Ample\u{0020}preparation\u{0020}is\u{0020}the\u{0020}key\u{0020}to\u{0020}success.", "0", "利器，然工事。", "0", "0", "0", "cv_shaoyin_15", "0", "0"},
[422115] = {422115, 12021, 16, 10, "0", "0", "Got\u{0020}it.", "0", "明瞭。", "0", "0", "0", "cv_shaoyin_16", "0", "0"},
[422116] = {422116, 12021, 17, 11, "0", "0", "May\u{0020}this\u{0020}be\u{0020}but\u{0020}one\u{0020}of\u{0020}your\u{0020}many\u{0020}victories,\u{0020}Navigator.", "0", "敬賀領航大獲全勝。", "0", "0", "0", "cv_shaoyin_17", "0", "0"},
[422117] = {422117, 12021, 18, 12, "0", "0", "Success\u{0020}is\u{0020}ours,\u{0020}although\u{0020}we've\u{0020}room\u{0020}for\u{0020}improvement...", "0", "無需失落，略有瑕疵而已。", "0", "0", "0", "cv_shaoyin_18", "0", "0"},
[422118] = {422118, 12021, 19, 13, "0", "0", "...We\u{0020}work\u{0020}best\u{0020}alongside\u{0020}our\u{0020}Navigator.\u{0020}We\u{0020}should\u{0020}be\u{0020}proud!", "0", "……是以領航更勝一籌，應當高興。", "0", "0", "0", "cv_shaoyin_19", "0", "0"},
[422119] = {422119, 12021, 20, 14, "0", "0", "How\u{0020}could\u{0020}this\u{0020}be?\u{0020}Let\u{0020}me\u{0020}retrace\u{0020}our\u{0020}steps...\u{0020}I\u{0020}must\u{0020}find\u{0020}out\u{0020}where\u{0020}we\u{0020}went\u{0020}wrong...", "0", "怎麼會這樣？等等，先讓我複盤一下，看問題究竟出在那裡……", "0", "0", "0", "cv_shaoyin_20", "0", "0"},
[422120] = {422120, 12021, 21, 15, "0", "0", "May\u{0020}we\u{0020}never\u{0020}meet\u{0020}again.", "0", "後會無期。", "0", "0", "0", "cv_shaoyin_21", "0", "0"},
[422121] = {422121, 12021, 23, 16, "0", "0", "Fall.", "0", "落。", "0", "0", "0", "cv_shaoyin_23", "0", "0"},
