[422123] = {422123, 12021, 25, 18, "0", "0", "We\u{0020}decide\u{0020}how\u{0020}we\u{0020}live...\u{0020}and\u{0020}destiny\u{0020}decides\u{0020}our\u{0020}fate.", "0", "謀事在人，成事在天。", "0", "0", "0", "cv_shaoyin_25", "0", "0"},
[422124] = {422124, 12021, 22, 38, "0", "0", "Just\u{0020}as\u{0020}I\u{0020}expected.", "0", "正如小女子所料。", "0", "0", "0", "cv_shaoyin_22", "0", "0"},
