[422126] = {422126, 12021, 27, 20, "0", "0", "Oh!\u{0020}You're\u{0020}here\u{0020}too.", "0", "連這裡也有您相伴呀。", "0", "0", "0", "cv_shaoyin_27", "0", "0"},
[422127] = {422127, 12021, 28, 21, "0", "0", "Remember,\u{0020}we\u{0020}must\u{0020}walk\u{0020}before\u{0020}we\u{0020}run.", "0", "欲速則不達。", "0", "0", "0", "cv_shaoyin_28", "0", "0"},
[422128] = {422128, 12021, 29, 21, "0", "0", "All\u{0020}things\u{0020}come\u{0020}with\u{0020}time!\u{0020}So,\u{0020}why\u{0020}not\u{0020}spend\u{0020}a\u{0020}little\u{0020}more\u{0020}time\u{0020}with\u{0020}me?", "0", "……所以說慢慢來嘛。和我在這裡多呆一會兒不好嗎？", "0", "0", "0", "cv_shaoyin_29", "0", "0"},
[422129] = {422129, 12021, 30, 22, "0", "0", "Oh,\u{0020}there\u{0020}are\u{0020}even\u{0020}games\u{0020}in\u{0020}here.", "0", "原來這裡還設有小遊戲呀。", "0", "0", "0", "cv_shaoyin_30", "0", "0"},
[422130] = {422130, 12021, 31, 23, "0", "0", "Guess\u{0020}who!\u{0020}You'd\u{0020}better\u{0020}get\u{0020}this\u{0020}one\u{0020}right.", "0", "是小女子哦。可千萬要猜對哦。", "0", "0", "0", "cv_shaoyin_31", "0", "0"},
[422131] = {422131, 12021, 32, 24, "0", "0", "Great!", "0", "太好啦！", "0", "0", "0", "cv_shaoyin_32", "0", "0"},
[422132] = {422132, 12021, 33, 25, "0", "0", "I'm\u{0020}not\u{0020}mad...", "0", "……我沒有生氣。", "0", "0", "0", "cv_shaoyin_33", "0", "0"},
[422133] = {422133, 12021, 34, 26, "0", "0", "Tch,\u{0020}of\u{0020}course\u{0020}I'm\u{0020}the\u{0020}only\u{0020}one\u{0020}here,\u{0020}as\u{0020}always,\u{0020}I\u{0020}-\u{0020}ah!\u{0020}N-Navigator,\u{0020}you're\u{0020}back!\u{0020}Ahem.\u{0020}No\u{0020}I\u{0020}wasn't\u{0020}talking\u{0020}to\u{0020}myself,\u{0020}your\u{0020}ears\u{0020}deceive\u{0020}you.", "0", "什麼嘛，又只剩我一個人——咿呀？！領、領航，您回來呐……咳，小女子方才什麼都沒說，您也什麼都沒聽見。", "0", "0", "0", "cv_shaoyin_34", "0", "0"},
[422134] = {422134, 12021, 35, 27, "0", "0", "I\u{0020}wish\u{0020}you\u{0020}all\u{0020}the\u{0020}best.", "0", "望諸事順遂。", "0", "0", "0", "cv_shaoyin_35", "0", "0"},
[422135] = {422135, 12021, 36, 28, "0", "0", "May\u{0020}victory\u{0020}await\u{0020}you\u{0020}at\u{0020}every\u{0020}turn.", "0", "願旗開得勝。", "0", "0", "0", "cv_shaoyin_36", "0", "0"},
[422136] = {422136, 12021, 37, 29, "0", "0", "You\u{0020}sure\u{0020}know\u{0020}a\u{0020}whole\u{0020}load\u{0020}of\u{0020}Drivers,\u{0020}don't\u{0020}you,\u{0020}Navigator...", "0", "領航認識的駕駛員可真多啊……", "0", "0", "0", "cv_shaoyin_37", "0", "0"},
[422137] = {422137, 12021, 38, 30, "0", "0", "What\u{0020}wondrous\u{0020}figures,\u{0020}indeed...\u{0020}Wait,\u{0020}you're\u{0020}not\u{0020}thinking\u{0020}of\u{0020}replacing\u{0020}me,\u{0020}are\u{0020}you?", "0", "此般仁人志士……等等，該不會是準備把我換掉了吧？", "0", "0", "0", "cv_shaoyin_38", "0", "0"},
[422138] = {422138, 12021, 39, 31, "0", "0", "They\u{0020}call\u{0020}me\u{0020}a\u{0020}lucky\u{0020}charm.\u{0020}But\u{0020}you\u{0020}knew\u{0020}that\u{0020}already,\u{0020}didn't\u{0020}you?", "0", "人形錦鯉的傳言，您已知曉了呀……", "0", "0", "0", "cv_shaoyin_39", "0", "0"},
[422139] = {422139, 12021, 40, 32, "0", "0", "What\u{0020}is\u{0020}it\u{0020}you\u{0020}seek?", "0", "欲易何物？", "0", "0", "0", "cv_shaoyin_40", "0", "0"},
[422140] = {422140, 12021, 41, 33, "0", "0", "Heh\u{0020}heh,\u{0020}I'll\u{0020}be\u{0020}your\u{0020}assistant,\u{0020}Navigator!", "0", "哼哼，領航的助理是我呢~", "0", "0", "0", "cv_shaoyin_41", "0", "0"},
[422141] = {422141, 12021, 42, 34, "0", "0", "Am\u{0020}I\u{0020}talking\u{0020}too\u{0020}much?\u{0020}Are\u{0020}you\u{0020}trying\u{0020}to\u{0020}turn\u{0020}my\u{0020}volume\u{0020}down?", "0", "難道是我話太多了，領航決定要靜我的音？", "0", "0", "0", "cv_shaoyin_42", "0", "0"},
[422142] = {422142, 12021, 43, 35, "0", "0", "Maybe\u{0020}I\u{0020}could\u{0020}send\u{0020}you\u{0020}some\u{0020}letters\u{0020}too,\u{0020}Navigator?", "0", "要不然我也寫封信寄給領航吧？", "0", "0", "0", "cv_shaoyin_43", "0", "0"},
[422143] = {422143, 12021, 44, 36, "0", "0", "Hey,\u{0020}chat\u{0020}with\u{0020}me\u{0020}too\u{0020}sometimes,\u{0020}alright?", "0", "……不要總是和別人聊啦。", "0", "0", "0", "cv_shaoyin_44", "0", "0"},
[422144] = {422144, 12021, 45, 37, "0", "0", "Always\u{0020}think\u{0020}your\u{0020}words\u{0020}through,\u{0020}and\u{0020}-\u{0020}wait,\u{0020}you've\u{0020}sent\u{0020}it\u{0020}out\u{0020}already?!", "0", "凡事皆應謹言慎——您已經按下去了？！", "0", "0", "0", "cv_shaoyin_45", "0", "0"},
[422200] = {422200, 12022, 1, 1, "0", "0", "Haze\u{0020}reverb!", "0", "蒼霧殘響~", "0", "0", "0", "cv_laipani_34", "0", "0"},
[422201] = {422201, 12022, 2, 2, "0", "0", "Navigator,\u{0020}it's\u{0020}time\u{0020}to\u{0020}work\u{0020}now.\u{0020}Just\u{0020}stay\u{0020}here\u{0020}and\u{0020}don't\u{0020}wander\u{0020}off.", "0", "領航，現在可是工作的時間，就在這哪裡都不要去哦。", "0", "0", "0", "cv_laipani_2", "0", "0"},
[422202] = {422202, 12022, 3, 3, "0", "0", "Nice\u{0020}to\u{0020}meet\u{0020}you!\u{0020}I'm\u{0020}Lepani,\u{0020}captain\u{0020}of\u{0020}the\u{0020}reconnaissance\u{0020}team\u{0020}\"Iron\u{0020}Crow.\"\u{0020}I'll\u{0020}be\u{0020}counting\u{0020}on\u{0020}your\u{0020}guidance\u{0020}for\u{0020}a\u{0020}long\u{0020}time,\u{0020}Navigator.", "0", "初次見面，我是萊帕尼，偵查小隊“鐵鴉”的隊長。之後很長一段時間都要請您指教了，領航。", "0", "0", "0", "cv_laipani_1", "0", "0"},
[422203] = {422203, 12022, 4, 4, "0", "idle", "You\u{0020}look\u{0020}a\u{0020}bit\u{0020}sleep-deprived,\u{0020}Navigator.\u{0020}Want\u{0020}to\u{0020}take\u{0020}a\u{0020}break?\u{0020}I\u{0020}can\u{0020}note\u{0020}the\u{0020}penalty\u{0020}for\u{0020}absenteeism\u{0020}in\u{0020}the\u{0020}book\u{0020}later.", "0", "領航，您看上去睡眠不足的樣子，要休息一下嗎？曠工的懲罰可以先記在本子上。", "0", "0", "0", "cv_laipani_3", "0", "0"},
[422204] = {422204, 12022, 5, 4, "0", "idle", "\"Iron\u{0020}Crow\"\u{0020}is\u{0020}a\u{0020}team\u{0020}I'm\u{0020}proud\u{0020}of,\u{0020}and\u{0020}I\u{0020}hope\u{0020}you\u{0020}can\u{0020}trust\u{0020}us\u{0020}with\u{0020}important\u{0020}tasks.", "0", "“鐵鴉”是一隻讓我引以為豪的隊伍。所以，我也希望領航您能夠信任我們，把重要的任務託付給我們。", "0", "0", "0", "cv_laipani_4", "0", "0"},
[422205] = {422205, 12022, 6, 4, "0", "idle", "When\u{0020}we're\u{0020}on\u{0020}a\u{0020}mission,\u{0020}I\u{0020}can't\u{0020}go\u{0020}anywhere\u{0020}without\u{0020}Lolo\u{0020}by\u{0020}my\u{0020}side.\u{0020}I'm\u{0020}really\u{0020}grateful\u{0020}to\u{0020}have\u{0020}her\u{0020}with\u{0020}me.", "0", "執行任務的時候，如果洛洛不在身邊的話，我可能哪裡都去不了。真的多虧有她在了。", "0", "0", "0", "cv_laipani_31", "0", "0"},
[422206] = {422206, 12022, 7, 5, "1_》_0_0.8", "level1", "During\u{0020}the\u{0020}war,\u{0020}there\u{0020}must\u{0020}be\u{0020}many\u{0020}children\u{0020}like\u{0020}me\u{0020}who\u{0020}got\u{0020}separated\u{0020}from\u{0020}their\u{0020}parents.\u{0020}It's\u{0020}just\u{0020}so\u{0020}unfair,\u{0020}don't\u{0020}you\u{0020}think?", "0", "戰爭中，一定有很多像我一樣和父母走散了的孩子……那樣的事實在是太不合理了……您不這麼認為嗎？", "0", "0", "0", "cv_laipani_32", "0", "0"},
[422207] = {422207, 12022, 8, 5, "1_》_0_0.8", "level1", "Navigator,\u{0020}would\u{0020}you\u{0020}like\u{0020}me\u{0020}to\u{0020}hold\u{0020}your\u{0020}hand?\u{0020}Um…\u{0020}is\u{0020}it\u{0020}too\u{0020}small?", "0", "領航，您是想讓我握住您的手嗎？嗯……是不是太小了點？", "0", "0", "0", "cv_laipani_5", "0", "0"},
[422208] = {422208, 12022, 9, 5, "1_》_100_1.5", "level2", "If\u{0020}you've\u{0020}been\u{0020}having\u{0020}trouble\u{0020}sleeping\u{0020}lately,\u{0020}I\u{0020}can\u{0020}help.\u{0020}I\u{0020}have\u{0020}lots\u{0020}of\u{0020}sleeping\u{0020}pills\u{0020}that\u{0020}will\u{0020}ensure\u{0020}you\u{0020}get\u{0020}a\u{0020}good\u{0020}rest.", "0", "領航，您最近如果失眠的話，我可以幫你噢。我這邊有許多類型的安眠藥，一定能讓您睡個好覺的。", "0", "0", "0", "cv_laipani_6", "0", "0"},
[422209] = {422209, 12022, 10, 5, "1_》_500_2", "level3", "Even\u{0020}though\u{0020}I\u{0020}have\u{0020}no\u{0020}sense\u{0020}of\u{0020}direction,\u{0020}I'm\u{0020}the\u{0020}captain\u{0020}of\u{0020}\"Iron\u{0020}Crow!\"\u{0020}No\u{0020}matter\u{0020}where\u{0020}you\u{0020}are,\u{0020}just\u{0020}call\u{0020}for\u{0020}me,\u{0020}and\u{0020}I'll\u{0020}find\u{0020}you!", "0", "領航，雖然我是路癡，但我可是“鐵鴉”的隊長噢！不管您身處何地，只要您呼喚了我，我一定能找到您的！", "0", "0", "0", "cv_laipani_7", "0", "0"},
[422210] = {422210, 12022, 11, 5, "1_》_1000_2.5", "level4", "Navigator,\u{0020}could\u{0020}you\u{0020}wear\u{0020}this\u{0020}chain...\u{0020}\"Bind\"?\u{0020}I\u{0020}just\u{0020}want\u{0020}us\u{0020}to\u{0020}stay\u{0020}together\u{0020}and\u{0020}not\u{0020}lose\u{0020}each\u{0020}other\u{0020}from\u{0020}now\u{0020}on.", "0", "領航，能請您帶上這根鏈子嗎……“捆綁”？啊，不是的。我只是希望我們從此之後都不會分開，不會走散而已……不行……嗎？", "0", "0", "0", "cv_laipani_8", "0", "0"},
