[422316] = {422316, 12023, 17, 11, "0", "0", "The\u{0020}stars\u{0020}always\u{0020}seem\u{0020}brighter\u{0020}after\u{0020}a\u{0020}successful\u{0020}mission.", "0", "任務圓滿完成的當晚，星空總是會比以往更美。", "0", "0", "0", "cv_stella_17", "0", "0"},
[422317] = {422317, 12023, 18, 12, "0", "0", "Glad\u{0020}there\u{0020}wasn't\u{0020}much\u{0020}damage\u{0020}this\u{0020}time.", "0", "還好這次沒出現太大損傷……", "0", "0", "0", "cv_stella_18", "0", "0"},
