[422401] = {422401, 12024, 2, 2, "0", "0", "Hmm...\u{0020}Would\u{0020}it\u{0020}be\u{0020}alright\u{0020}if\u{0020}I\u{0020}sat\u{0020}next\u{0020}to\u{0020}you,\u{0020}Navigator?", "あの……ナビゲーターさんのとなりに座ってもいいですか？", "0", "0", "0", "0", "cv_fulanka_sw_2", "0", "0"},
[422402] = {422402, 12024, 3, 3, "0", "0", "I've\u{0020}waited\u{0020}so\u{0020}long\u{0020}for\u{0020}this\u{0020}moment...\u{0020}Hehe...\u{0020}I'd\u{0020}imagined\u{0020}our\u{0020}reunion\u{0020}countless\u{0020}times,\u{0020}but\u{0020}never\u{0020}dreamed\u{0020}it\u{0020}would\u{0020}be\u{0020}in\u{0020}a\u{0020}dream.", "ずっと待ってたんですよ……えへへ、ナビゲーターさんとまた會える日をいつも想像してたんですが……こんな風に夢で會うとは思いませんでした。", "0", "0", "0", "0", "cv_fulanka_sw_3", "0", "0"},
[422403] = {422403, 12024, 4, 4, "0", "idle", "I\u{0020}believe\u{0020}this\u{0020}day\u{0020}would\u{0020}come...\u{0020}And\u{0020}now\u{0020}my\u{0020}wish\u{0020}has\u{0020}been\u{0020}granted.\u{0020}This\u{0020}is\u{0020}more\u{0020}than\u{0020}I\u{0020}dared\u{0020}hope\u{0020}for.", "ナビゲーターさんとまた會える日が必ず來るって信じてました……願いが葉っちゃいましたね。えへへ。とっても嬉しいです。", "0", "0", "0", "0", "cv_fulanka_sw_4", "0", "0"},
[422404] = {422404, 12024, 5, 4, "0", "idle", "If\u{0020}only\u{0020}you\u{0020}remembered\u{0020}everything...\u{0020}But\u{0020}it's\u{0020}alright.\u{0020}Even\u{0020}if\u{0020}I'm\u{0020}the\u{0020}only\u{0020}one\u{0020}who\u{0020}recalls...", "ナビゲーターさんに以前の記憶があれば良かったんですが……でも構いません。私のことを忘れてしまっていたとしても……", "0", "0", "0", "0", "cv_fulanka_sw_5", "0", "0"},
[422405] = {422405, 12024, 6, 4, "0", "idle", "Every\u{0020}day\u{0020}with\u{0020}you\u{0020}now\u{0020}feels\u{0020}like\u{0020}an\u{0020}encounter\u{0020}with\u{0020}happiness.\u{0020}It\u{0020}must\u{0020}be\u{0020}my\u{0020}reward\u{0020}for\u{0020}never\u{0020}giving\u{0020}up.", "私、ナビゲーターさんと過ごすこの毎日がとても幸せです。きっと、辛抱強く待ち続けたご褒美ですよね。", "0", "0", "0", "0", "cv_fulanka_sw_6", "0", "0"},
[422406] = {422406, 12024, 7, 5, "1_》_0_0.8", "level1", "Shouldn't\u{0020}we\u{0020}celebrate\u{0020}this\u{0020}peaceful\u{0020}evening\u{0020}with\u{0020}something...\u{0020}indulgent?", "平穏な一日を祝って、今晩はちょっとだけ贅沢しちゃいませんか？", "0", "0", "0", "0", "cv_fulanka_sw_7", "0", "0"},
