[422426] = {422426, 12024, 28, 21, "0", "0", "After\u{0020}baths\u{0020}comes\u{0020}bedtime...\u{0020}Though\u{0020}saying\u{0020}goodnight\u{0020}in\u{0020}a\u{0020}dream\u{0020}does\u{0020}feel\u{0020}rather\u{0020}silly.", "お風呂が済んだらおやすみの時間ですね。でも……夢の中でおやすみっていうのもなんか変ですが。", "0", "0", "0", "0", "cv_fulanka_sw_28", "0", "0"},
[422427] = {422427, 12024, 29, 21, "0", "0", "We\u{0020}exist\u{0020}in\u{0020}the\u{0020}Heroine\u{0020}Universe\u{0020}to\u{0020}forge\u{0020}our\u{0020}future.\u{0020}So\u{0020}my\u{0020}being\u{0020}here\u{0020}means...\u{0020}my\u{0020}future\u{0020}still\u{0020}awaits?", "私達がヒロインバースに現れたのは、私達の未來のためです。同じように、私がここに現れたのは私の未來のため……ではないでしょうか？", "0", "0", "0", "0", "cv_fulanka_sw_29", "0", "0"},
[422428] = {422428, 12024, 30, 22, "0", "0", "Haha.\u{0020}Some\u{0020}things\u{0020}never\u{0020}change.\u{0020}Everyone\u{0020}still\u{0020}teases\u{0020}you\u{0020}at\u{0020}bath\u{0020}time.", "ふふ、やっぱりこうなりますよね。みんなお風呂の時にナビゲーターさんをからかうのが好きですから。", "0", "0", "0", "0", "cv_fulanka_sw_30", "0", "0"},
