[422701] = {422701, 12027, 2, 2, "0", "0", "Better\u{0020}not\u{0020}let\u{0020}the\u{0020}kids\u{0020}see\u{0020}that\u{0020}Santa\u{0020}Claus\u{0020}is\u{0020}a\u{0020}little\u{0020}tipsy.", "0", "可不能讓孩子們看到聖誕老人喝醉的樣子。", "0", "0", "0", "cv_kurimu2_2", "0", "0"},
[422702] = {422702, 12027, 3, 3, "0", "0", "Here's\u{0020}Santa,\u{0020}and\u{0020}I've\u{0020}come\u{0020}with\u{0020}loads\u{0020}of...\u{0020}presents!\u{0020}Only\u{0020}for\u{0020}the\u{0020}good\u{0020}kids!", "0", "聖誕老人來咯，我帶了很多……禮物！只有好孩子才能領取哦。", "0", "0", "0", "cv_kurimu2_3", "0", "0"},
[422703] = {422703, 12027, 4, 4, "0", "idle", "Christmas\u{0020}only\u{0020}comes\u{0020}around\u{0020}once\u{0020}a\u{0020}year,\u{0020}won't\u{0020}you\u{0020}join\u{0020}me\u{0020}with\u{0020}a\u{0020}drink\u{0020}to\u{0020}celebrate?", "0", "一年才有一次的聖誕節，領航不喝一點慶祝嗎？", "0", "0", "0", "cv_kurimu2_4", "0", "0"},
[422704] = {422704, 12027, 5, 4, "0", "idle", "I've\u{0020}got\u{0020}more\u{0020}than\u{0020}just\u{0020}alcohol\u{0020}in\u{0020}my\u{0020}sack!\u{0020}There's\u{0020}peanuts,\u{0020}smoked\u{0020}meats,\u{0020}sausages,\u{0020}all\u{0020}kinds\u{0020}of\u{0020}stuff...", "0", "我的袋子裏可不只有酒，還有花生、熏肉、肉腸……", "0", "0", "0", "cv_kurimu2_5", "0", "0"},
[422705] = {422705, 12027, 6, 4, "0", "idle", "I\u{0020}can't\u{0020}bring\u{0020}everyone\u{0020}gifts\u{0020}quite\u{0020}like\u{0020}Santa\u{0020}does.\u{0020}But\u{0020}if\u{0020}I\u{0020}can\u{0020}bring\u{0020}a\u{0020}smile\u{0020}to\u{0020}everyone's\u{0020}faces,\u{0020}well,\u{0020}that's\u{0020}enough\u{0020}for\u{0020}me.", "0", "雖然不能像真的聖誕老人一樣給大家分發禮物，但能讓大家在看到我的時候開心地笑起來，那也就足夠了。", "0", "0", "0", "cv_kurimu2_6", "0", "0"},
[422706] = {422706, 12027, 7, 5, "1_》_0_0.8", "level1", "What\u{0020}do\u{0020}you\u{0020}think\u{0020}Santa\u{0020}Claus\u{0020}does\u{0020}for\u{0020}work\u{0020}usually?\u{0020}Whatever\u{0020}it\u{0020}is,\u{0020}I\u{0020}bet\u{0020}he\u{0020}works\u{0020}hard.\u{0020}How\u{0020}else\u{0020}could\u{0020}he\u{0020}afford\u{0020}all\u{0020}those\u{0020}gifts?", "0", "你說聖誕老人在平時是在做什麼工作呢？無論他做什麼工作，一定是很努力的吧，不然怎麼能有那麼多錢給孩子們買禮物。", "0", "0", "0", "cv_kurimu2_7", "0", "0"},
[422707] = {422707, 12027, 8, 5, "1_》_0_0.8", "level1", "Merry\u{0020}Christmas!", "0", "Merry\u{0020}Christmas！", "0", "0", "0", "cv_kurimu2_8", "0", "0"},
[422708] = {422708, 12027, 9, 5, "1_》_100_1.5", "level2", "Ho\u{0020}ho\u{0020}ho!\u{0020}If\u{0020}you\u{0020}want\u{0020}some\u{0020}of\u{0020}these\u{0020}presents,\u{0020}you'll\u{0020}have\u{0020}to\u{0020}come\u{0020}get\u{0020}'em.", "0", "吼吼吼，想要聖誕老人禮物可以，但是你得自己來拿。", "0", "0", "0", "cv_kurimu2_9", "0", "0"},
[422709] = {422709, 12027, 10, 5, "1_》_500_2", "level3", "How\u{0020}come\u{0020}Santa\u{0020}Claus\u{0020}always\u{0020}knows\u{0020}what\u{0020}you\u{0020}want\u{0020}for\u{0020}Christmas?\u{0020}Do\u{0020}you\u{0020}think\u{0020}he's\u{0020}got\u{0020}Synesthesia\u{0020}like\u{0020}you\u{0020}do,\u{0020}Navigator...?\u{0020}Wait,\u{0020}could\u{0020}you\u{0020}be\u{0020}Santa?!", "0", "為什麼聖誕老人能知道每個孩子心裏想要的禮物？難道他也和領航一樣有通感……等等，難道領航你就是聖誕老人！", "0", "0", "0", "cv_kurimu2_10", "0", "0"},
[422710] = {422710, 12027, 11, 5, "1_》_1000_2.5", "level4", "Eh,\u{0020}we're\u{0020}all\u{0020}out?\u{0020}I\u{0020}was\u{0020}just\u{0020}getting\u{0020}into\u{0020}my\u{0020}stride...\u{0020}See,\u{0020}being\u{0020}a\u{0020}bit\u{0020}tipsy's\u{0020}way\u{0020}easier\u{0020}for\u{0020}me\u{0020}than\u{0020}being\u{0020}sober.\u{0020}Keeps\u{0020}those\u{0020}crazy\u{0020}thoughts\u{0020}at\u{0020}bay...\u{0020}Do\u{0020}you\u{0020}think\u{0020}you\u{0020}could\u{0020}ever\u{0020}like\u{0020}a\u{0020}drunkard\u{0020}like\u{0020}me,\u{0020}Navigator?", "0", "這就喝光了嗎？可我還沒有喝夠……清醒可比醉的時候更難熬。沒有酒精的幫助，我實在沒法抑制自己的胡思亂想……領航，你會喜歡像我這種酒鬼嗎？", "0", "0", "0", "cv_kurimu2_11", "0", "0"},
