[430002] = {430002, 13000, 3, 3, "0", "0", "Whooooaaa—who\u{0020}are\u{0020}you?\u{0020}Oh,\u{0020}it's\u{0020}you,\u{0020}Navigator!\u{0020}I'm\u{0020}Odora.\u{0020}Nice\u{0020}to\u{0020}meet\u{0020}you!\u{0020}Yawn", "ふぁ――あなた、誰？ナビゲーターだったのね。初めまして。あたしはオードラ。ふぁ――", "哇呼——你是誰？原來是領航，你好，我是歐朵啦。呼——", "0", "哇呼——你是谁？原来是领航，你好，我是欧朵啦。呼——", "0", "cv_odora_1", "0", "0"},
[430003] = {430003, 13000, 4, 4, "0", "idle", "I\u{0020}sleep\u{0020}enough,\u{0020}but\u{0020}why\u{0020}am\u{0020}I\u{0020}not\u{0020}getting\u{0020}taller?\u{0020}Navigator,\u{0020}do\u{0020}you\u{0020}have\u{0020}any\u{0020}tips?\u{0020}Milk?\u{0020}That's\u{0020}what\u{0020}Lulula\u{0020}said\u{0020}too...\u{0020}Alright,\u{0020}I'll\u{0020}trust\u{0020}you\u{0020}both.", "たっぷり寝てるのに、背が伸びないんだよね。何でだろう……ナビゲーターって、背を伸ばす秘訣とか何か知らない？ミルクか……ルルラもそう言ってたなあ……よし、あなたたちの言うことを信じようっと……", "明明睡眠很充足，為什麼長不高呢……領航有什麼長高的秘訣嗎？牛奶……露露啦也是這麼說的……好吧，相信你們……", "0", "明明睡眠很充足，为什么长不高呢……领航有什么长高的秘诀吗？牛奶……露露啦也是这么说的……好吧，相信你们……", "0", "cv_odora_3", "0", "0"},
[430004] = {430004, 13000, 5, 4, "0", "idle", "Humming~\u{0020}The\u{0020}sun's\u{0020}out—Navigator,\u{0020}come\u{0020}play\u{0020}with\u{0020}me!\u{0020}Lulula\u{0020}said\u{0020}the\u{0020}more\u{0020}sun\u{0020}I\u{0020}get,\u{0020}the\u{0020}taller\u{0020}I'll\u{0020}grow!", "ふふふん～ふんふん～♪お日様が出てきたよ、あたしと出かけて遊ぼ、ね、ナビゲーター。背を伸ばすにはひなたぼっこを沢山しないといけないってルルラも言ってたの。", "哼哼——哼哼——太陽出來啦～領航和我出去玩吧～露露啦說多曬太陽才能長高哇～", "0", "哼哼——哼哼——太阳出来啦～领航和我出去玩吧～露露啦说多晒太阳才能长高哇～", "0", "cv_odora_4", "0", "0"},
