[430101] = {430101, 13001, 2, 2, "0", "0", "Is\u{0020}this\u{0020}really\u{0020}okay?\u{0020}I'm\u{0020}not\u{0020}questioning\u{0020}your\u{0020}judgment,\u{0020}but\u{0020}I'm\u{0020}truly\u{0020}sorry!", "本当に、いいのですか？いいえ……あなた様の判断を疑っているわけではありません。失礼しました！", "這樣真的好嗎？不……我並不是在質疑您的判斷，非常抱歉！", "0", "这样真的好吗？不……我并不是在质疑您的判断，非常抱歉！", "0", "cv_furanka_2", "0", "0"},
[430102] = {430102, 13001, 3, 3, "0", "0", "Hello!\u{0020}I'm\u{0020}Franca\u{0020}Vinci,\u{0020}I\u{0020}just\u{0020}became\u{0020}a\u{0020}driver\u{0020}this\u{0020}year.\u{0020}It's\u{0020}a\u{0020}pleasure\u{0020}to\u{0020}meet\u{0020}you.", "こんにちは。私はフランカー・ヴィンチ、今年新任のドライバーです。会えて嬉しいです。", "您好，我的名字是弗蘭卡·芬奇，是今年新上任的駕駛員，很高興能夠見到您。", "0", "您好，我的名字是弗兰卡·芬奇，是今年新上任的驾驶员，很高兴能够见到您。", "0", "cv_furanka_1", "0", "0"},
[430103] = {430103, 13001, 4, 4, "0", "idle", "Ugh...\u{0020}I'm\u{0020}so\u{0020}nervous.\u{0020}This\u{0020}is\u{0020}the\u{0020}first\u{0020}time\u{0020}standing\u{0020}here...\u{0020}But\u{0020}don't\u{0020}worry.\u{0020}I'll\u{0020}do\u{0020}my\u{0020}best!", "う……緊張します。ここに立つのは初めてなので……で、でも、安心してください。私、頑張ります！", "嗚……好緊張啊，還是第一次站在這裡……但是放心好了，我會努力做好的！", "0", "呜……好紧张啊，还是第一次站在这里……但是放心好了，我会努力做好的！", "0", "cv_furanka_3", "0", "0"},
[430104] = {430104, 13001, 5, 4, "0", "idle", "The\u{0020}Danube\u{0020}branch's\u{0020}Ark\u{0020}is\u{0020}super\u{0020}close\u{0020}to\u{0020}my\u{0020}house.\u{0020}If\u{0020}you\u{0020}ever\u{0020}have\u{0020}time,\u{0020}you\u{0020}and\u{0020}everyone\u{0020}should\u{0020}come\u{0020}visit!\u{0020}I'll\u{0020}take\u{0020}care\u{0020}of\u{0020}everything.", "ダニューブ支部の方舟は私の家に近いんですよ。時間があったら、みんな一緒にうちに来ませんか？ちゃんとおもてなししますから。", "多瑙支部的方舟離我家很近呢，有空的話要和大家一起來做客嗎？我會招待好大家的。", "0", "多瑙支部的方舟离我家很近呢，有空的话要和大家一起来做客吗？我会招待好大家的。", "0", "cv_furanka_4", "0", "0"},
[430105] = {430105, 13001, 6, 4, "0", "idle", "Julius,\u{0020}Navigator,\u{0020}Chalissa...\u{0020}they're\u{0020}all\u{0020}so\u{0020}amazing.\u{0020}I\u{0020}wish\u{0020}I\u{0020}could\u{0020}be\u{0020}more\u{0020}like\u{0020}them.", "ユリウス先輩、ナビゲーターさん、そしてチャリサー先輩……みなさん、優秀な方です。もっとみなさんに近づいていけたらいいなぁって思います。", "朱利烏斯學姐，領航還有查麗莎學姐……她們都是優秀的人。如果我能再接近你們一些的話，那就好了。", "0", "朱利乌斯学姐，领航还有查丽莎学姐……她们都是优秀的人。如果我能再接近你们一些的话，那就好了。", "0", "cv_furanka_27", "0", "0"},
[430106] = {430106, 13001, 7, 5, "1_》_0_0.8", "level1", "The\u{0020}gentle\u{0020}sea\u{0020}breeze,\u{0020}delicious\u{0020}food,\u{0020}and\u{0020}kind,\u{0020}warm\u{0020}people.\u{0020}That's\u{0020}where\u{0020}I\u{0020}grew\u{0020}up,\u{0020}and\u{0020}that's\u{0020}what\u{0020}I\u{0020}want\u{0020}to\u{0020}protect.", "しなやかな潮風、美味しい食べ物、そして……優しい方々。ここは私の育った場所であり、私の守りたいものでもあるんです。", "柔和的海風，美味的食物，還有……一群善良溫柔的人。這就是我成長的地方，也是我想要守護的東西。", "0", "柔和的海风，美味的食物，还有……一群善良温柔的人。这就是我成长的地方，也是我想要守护的东西。", "0", "cv_furanka_28", "0", "0"},
[430107] = {430107, 13001, 8, 5, "1_》_0_0.8", "level1", "P-please\u{0020}don't\u{0020}joke\u{0020}like\u{0020}that...", "こ、こんな冗談はやめてください……", "請…請不要開這種玩笑……", "0", "请…请不要开这种玩笑……", "0", "cv_furanka_5", "0", "0"},
[430108] = {430108, 13001, 9, 5, "1_》_100_1.5", "level2", "Whoa!\u{0020}—Oh,\u{0020}it's\u{0020}just\u{0020}you,\u{0020}Navigator.", "きゃっ！――ああ……ナビゲーターさんですか。", "呼啊！——原……原來是領航啊。", "0", "呼啊！——原……原来是领航啊。", "0", "cv_furanka_6", "0", "0"},
[430109] = {430109, 13001, 10, 5, "1_》_500_2", "level3", "Hehe,\u{0020}I'm\u{0020}not\u{0020}so\u{0020}easy\u{0020}to\u{0020}scare\u{0020}anymore!", "うふふ、もう驚かされませんよ。", "嘿嘿，已經不會被您嚇到了喔。", "0", "嘿嘿，已经不会被您吓到了哦。", "0", "cv_furanka_7", "0", "0"},
[430110] = {430110, 13001, 11, 5, "1_》_1000_2.5", "level4", "Have\u{0020}we\u{0020}really\u{0020}known\u{0020}each\u{0020}other\u{0020}for\u{0020}this\u{0020}long?\u{0020}If\u{0020}you\u{0020}don't\u{0020}mind,\u{0020}could\u{0020}we\u{0020}have\u{0020}some\u{0020}tea\u{0020}together,\u{0020}Navigator?\u{0020}I've\u{0020}got\u{0020}something\u{0020}I'd\u{0020}like\u{0020}to\u{0020}talk\u{0020}to\u{0020}you\u{0020}about...", "私たち、知り合ってからもうそんなに経つんですね。ナビゲーターさんさえよければ、一緒にお茶を飲みませんか？二人きりで話したいことがあって……", "不知不覺中我們已經認識那麼久了嗎？如果領航您不介意的話，我可以請您喝杯茶嗎？有些話想要私下對您說…", "0", "不知不觉中我们已经认识那么久了吗？如果领航您不介意的话，我可以请您喝杯茶吗？有些话想要私下对您说……", "0", "cv_furanka_8", "0", "0"},
[430111] = {430111, 13001, 12, 6, "0", "0", "Eh?\u{0020}Are\u{0020}these\u{0020}really\u{0020}for\u{0020}me?", "えっ？本当に私にこれを？", "欸？這些真的要給我嗎？", "0", "哎？这些真的要给我吗？", "0", "cv_furanka_9", "0", "0"},
[430112] = {430112, 13001, 13, 7, "0", "0", "You've\u{0020}gone\u{0020}out\u{0020}of\u{0020}your\u{0020}way,\u{0020}Navigator.\u{0020}Thank\u{0020}you!", "お気遣いありがとうございます、ナビゲーターさん！", "讓領航您費心了，謝謝！", "0", "让领航您费心了，谢谢！", "0", "cv_furanka_10", "0", "0"},
[430113] = {430113, 13001, 14, 8, "0", "0", "Waaah—Look,\u{0020}Navigator!\u{0020}I\u{0020}can\u{0020}do\u{0020}it\u{0020}too!", "わぁ――見てください、ナビゲーターさん！私もできるようになりました！", "哇啊——快看啊領航，我也能夠做到了！", "0", "哇啊——快看啊领航，我也能够做到了！", "0", "cv_furanka_11", "0", "0"},
[430114] = {430114, 13001, 15, 9, "0", "0", "I\u{0020}need\u{0020}to\u{0020}work\u{0020}harder...", "もっと頑張らないと……", "還要再努力些……", "0", "还要再努力些……", "0", "cv_furanka_12", "0", "0"},
