[430116] = {430116, 13001, 17, 11, "0", "0", "It's\u{0020}finally\u{0020}over,\u{0020}Navigator.\u{0020}We\u{0020}made\u{0020}it\u{0020}back\u{0020}safely!", "やっと終わりましたね、ナビゲーターさん。無事に帰ってこれました！", "終於結束了，領航，我們平安回來了！", "0", "终于结束了，领航，我们平安回来了！", "0", "cv_furanka_14", "0", "0"},
[430117] = {430117, 13001, 18, 12, "0", "0", "Ahahaha,\u{0020}there\u{0020}were\u{0020}a\u{0020}few\u{0020}mistakes\u{0020}along\u{0020}the\u{0020}way.", "あははは、えっと……ミスがちょっとありましたが、良いでしょう。", "啊哈哈，稍微有些失誤呢。", "0", "啊哈哈，稍微有些失误呢。", "0", "cv_furanka_15", "0", "0"},
[430118] = {430118, 13001, 19, 13, "0", "0", "Finally...\u{0020}it's\u{0020}over,\u{0020}Navigator.\u{0020}We're\u{0020}back...", "やっと……終わりましたね、ナビゲーターさん。なんとか帰ってこれました……", "終於……結束了，領航，我們回來了……", "0", "终于……结束了，领航，我们回来了……", "0", "cv_furanka_16", "0", "0"},
[430119] = {430119, 13001, 20, 14, "0", "0", "Battle...\u{0020}defeat...\u{0020}I'm\u{0020}so\u{0020}sorry,\u{0020}Navigator.\u{0020}Wait,\u{0020}you\u{0020}said\u{0020}as\u{0020}long\u{0020}as\u{0020}we\u{0020}returned\u{0020}safely...", "戦闘……失敗……すみません、ナビゲーターさん。え？無事に帰ってきたことが何より、ですか？でも……", "戰鬥……失敗……非常抱歉領航。欸？您說只要我們平安回來就好，但是……", "0", "战斗……失败……非常抱歉领航。哎？您说只要我们平安回来就好，但是……", "0", "cv_furanka_17", "0", "0"},
