[430121] = {430121, 13001, 26, 19, "0", "0", "Sorry...\u{0020}everyone...\u{0020}hang\u{0020}in\u{0020}there!", "ごめんなさい……みんな……最後まで頑張って……", "抱歉……大家……一定要堅持住啊。", "0", "抱歉……大家……一定要坚持住啊。", "0", "cv_furanka_19", "0", "0"},
[430122] = {430122, 13001, 27, 20, "0", "0", "Oh...\u{0020}how\u{0020}embarrassing...\u{0020}I\u{0020}don't\u{0020}look\u{0020}as\u{0020}good\u{0020}as\u{0020}those\u{0020}other\u{0020}two...", "は、恥ずかしいですが……私のスタイル、先輩たちにはかないません……", "好…好難為情啊……我的身材完全比不上兩位學姐……", "0", "好…好难为情啊……我的身材完全比不上两位学姐……", "0", "cv_furanka_20", "0", "0"},
