[430129] = {430129, 13001, 34, 26, "0", "0", "Welcome\u{0020}back!\u{0020}I\u{0020}made\u{0020}some\u{0020}squid\u{0020}ink\u{0020}pasta.\u{0020}Want\u{0020}to\u{0020}try\u{0020}some,\u{0020}Navigator?", "お帰りなさい。イカのパスタを作ったんです。ナビゲーターさんも食べてみます？", "歡迎回來，我煮了些墨魚面，領航要來嘗嘗嗎？", "0", "欢迎回来，我煮了些墨鱼面，领航要来尝尝吗？", "0", "cv_furanka_29", "0", "0"},
[430130] = {430130, 13001, 35, 27, "0", "0", "Despite\u{0020}the\u{0020}challenges,\u{0020}I'm\u{0020}confident\u{0020}the\u{0020}story\u{0020}will\u{0020}end\u{0020}happily\u{0020}for\u{0020}everyone.", "どんなに大変なことがあったとしても、きっと、みんなが満足できるような結末を迎えられます。", "無論過程是有多艱辛，我相信故事的最後一定會迎來一個讓大家都滿意的結局吧。", "0", "无论过程是有多艰辛，我相信故事的最后一定会迎来一个让大家都满意的结局吧。", "0", "cv_furanka_31", "0", "0"},
[430131] = {430131, 13001, 36, 28, "0", "0", "Make\u{0020}sure\u{0020}to\u{0020}set\u{0020}a\u{0020}daily\u{0020}goal\u{0020}for\u{0020}yourself.", "毎日の目標を作った方がいいですね。", "每天都要給自己定個目標才行呢。", "0", "每天都要给自己定个目标才行呢。", "0", "cv_furanka_32", "0", "0"},
[430132] = {430132, 13001, 37, 29, "0", "0", "I\u{0020}need\u{0020}to\u{0020}step\u{0020}up\u{0020}my\u{0020}game\u{0020}and\u{0020}catch\u{0020}up\u{0020}with\u{0020}everyone.", "私も頑張ってみんなに追いつかないと。", "我也要努力追上大家才行呢。", "0", "我也要努力追上大家才行呢。", "0", "cv_furanka_33", "0", "0"},
[430133] = {430133, 13001, 38, 30, "0", "0", "Am\u{0020}I\u{0020}really\u{0020}going\u{0020}to\u{0020}be\u{0020}a\u{0020}senior?\u{0020}I'm\u{0020}so\u{0020}nervous!", "私も先輩になるのですか？緊張します……", "我也要當前輩了嗎？好緊張……", "0", "我也要当前辈了吗？好紧张……", "0", "cv_furanka_34", "0", "0"},
[430134] = {430134, 13001, 39, 31, "0", "0", "We\u{0020}should\u{0020}order\u{0020}some\u{0020}new\u{0020}equipment.", "新しい装備を発注しますね。", "要訂購一批新裝備了呢。", "0", "要订购一批新装备了呢。", "0", "cv_furanka_35", "0", "0"},
[430135] = {430135, 13001, 40, 32, "0", "0", "Let's\u{0020}see\u{0020}what\u{0020}we\u{0020}need\u{0020}to\u{0020}get.", "何か必要なものがないかどうか、確認してみましょう。", "看看有什麼需要的吧。", "0", "看看有什么需要的吧。", "0", "cv_furanka_36", "0", "0"},
[430136] = {430136, 13001, 41, 33, "0", "0", "You\u{0020}look\u{0020}as\u{0020}handsome\u{0020}as\u{0020}ever\u{0020}today!", "今日もかっこいいですね！", "今天的您也是一樣的帥氣呢！", "0", "今天的您也是一样的帅气呢！", "0", "cv_furanka_37", "0", "0"},
[430137] = {430137, 13001, 42, 34, "0", "0", "Let's\u{0020}adjust\u{0020}the\u{0020}settings.", "設定を変更しましょう。", "來變更一下設定吧～", "0", "来变更一下设置吧～", "0", "cv_furanka_38", "0", "0"},
[430138] = {430138, 13001, 43, 35, "0", "0", "And\u{0020}don't\u{0020}forget\u{0020}to\u{0020}check\u{0020}for\u{0020}new\u{0020}messages!", "新しいメールが来たら確認しましょう。", "有新的來信要注意查收喔～", "0", "有新的来信要注意查收哦～", "0", "cv_furanka_39", "0", "0"},
[430139] = {430139, 13001, 44, 36, "0", "0", "Come\u{0020}on,\u{0020}let's\u{0020}chat\u{0020}with\u{0020}everyone,\u{0020}Navigator!", "みんなとチャットしましょう、ナビゲーターさん。", "來和大家一起聊天吧，領航。", "0", "来和大家一起聊天吧，领航。", "0", "cv_furanka_40", "0", "0"},
[430140] = {430140, 13001, 45, 37, "0", "0", "What's\u{0020}this\u{0020}for?", "何か御用ですか？", "這個是做什麼的呢？", "0", "这个是做什么的呢？", "0", "cv_furanka_41", "0", "0"},
[430200] = {430200, 13002, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_tina_29", "0", "0"},
[430201] = {430201, 13002, 2, 2, "0", "0", "As\u{0020}head\u{0020}maid,\u{0020}it's\u{0020}my\u{0020}duty\u{0020}to\u{0020}lead\u{0020}by\u{0020}example.", "メイド長として、率先して手本を見せて差し上げましょう。", "身為女僕長確實應該起到表率作用。", "0", "身为女仆长确实应该起到表率作用。", "0", "cv_tina_2", "0", "0"},
[430202] = {430202, 13002, 3, 3, "0", "0", "Tina\u{0020}Eisen,\u{0020}the\u{0020}most\u{0020}loyal\u{0020}servant\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family.\u{0020}Have\u{0020}you\u{0020}seen\u{0020}the\u{0020}young\u{0020}lady\u{0020}of\u{0020}the\u{0020}family,\u{0020}Navigator?", "ティナ・アイソン。クリティア家において最も忠実な従者だと思って頂いて構いません。ナビゲーター、うちのお嬢様を見ませんでした？", "蒂娜·愛森，克雷蒂亞家族最忠誠的僕從。領航，你有看到我家小姐嗎？", "0", "蒂娜·爱森，克雷蒂亚家族最忠诚的仆从。领航，你有看到我家小姐吗？", "0", "cv_tina_1", "0", "0"},
[430203] = {430203, 13002, 4, 4, "0", "idle", "Everyone's\u{0020}got\u{0020}different\u{0020}experiences\u{0020}and\u{0020}talents,\u{0020}and\u{0020}the\u{0020}world\u{0020}needs\u{0020}all\u{0020}kinds\u{0020}of\u{0020}people.\u{0020}That's\u{0020}why\u{0020}I\u{0020}guide\u{0020}the\u{0020}two\u{0020}young\u{0020}ladies\u{0020}down\u{0020}different\u{0020}paths.", "人はそれぞれ違う経歴と素質を持っています。そしてこの世界にも、様々な人が必要ですわ。故に、私はお嬢様お二人それぞれにあった接し方と導き方をするように心がけております。", "每個人都有不同的經歷和天賦，而這個世界也需要各種各樣的人。所以我才會區別對待兩位小姐，將她們引向不同的路。", "0", "每个人都有不同的经历和天赋，而这个世界也需要各种各样的人。所以我才会区别对待两位小姐，将她们引向不同的路。", "0", "cv_tina_3", "0", "0"},
[430204] = {430204, 13002, 5, 4, "0", "idle", "Before\u{0020}becoming\u{0020}great,\u{0020}you\u{0020}have\u{0020}to\u{0020}truly\u{0020}become\u{0020}yourself.\u{0020}As\u{0020}for\u{0020}me...\u{0020}no\u{0020}doubt—I\u{0020}was\u{0020}born\u{0020}to\u{0020}serve\u{0020}the\u{0020}Cretia\u{0020}family.", "人材を育てるためには、まずそれにふさわしい自分になる必要があります。私の場合は……言うまでもございません。私は、クリティア家のために生きておりますから。", "想要成為人才之前，得先成為自己。而我自己……毋庸置疑，我生而為了克雷蒂亞家族。", "0", "想要成为人才之前，得先成为自己。而我自己……毋庸置疑，我生而为了克雷蒂亚家族。", "0", "cv_tina_4", "0", "0"},
[430205] = {430205, 13002, 6, 4, "0", "idle", "Hank,\u{0020}this\u{0020}is\u{0020}the\u{0020}last\u{0020}time\u{0020}I'll\u{0020}remind\u{0020}you—don't\u{0020}be\u{0020}rude\u{0020}in\u{0020}front\u{0020}of\u{0020}the\u{0020}young\u{0020}ladies!\u{0020}And\u{0020}hey!\u{0020}Don't\u{0020}get\u{0020}so\u{0020}close!\u{0020}What\u{0020}are\u{0020}you\u{0020}trying\u{0020}to\u{0020}do?!", "ハンク、これが最後の忠告です。お二人の前で無礼な行為をしないでください。さもないと…...ちょっと、いきなり近寄らないで頂けます？何をなさるつもりですか？！", "漢克，我最後再提醒你一遍，請不要在兩位小姐面前做出那樣無禮的行為，否則的話……喂！不要突然靠得那麼近，你這個傢伙到底想要做什麼啊？！", "0", "汉克，我最后再提醒你一遍，请不要在两位小姐面前做出那样无礼的行为，否则的话……喂！不要突然靠得那么近，你这个家伙到底想要做什么啊？！", "0", "cv_tina_41", "0", "0"},
[430206] = {430206, 13002, 7, 5, "1_》_0_0.8", "level1", "Ensuring\u{0020}the\u{0020}safety\u{0020}of\u{0020}the\u{0020}young\u{0020}ladies\u{0020}and\u{0020}yourself\u{0020}is\u{0020}my\u{0020}priority,\u{0020}but\u{0020}don't\u{0020}get\u{0020}it\u{0020}wrong—this\u{0020}is\u{0020}my\u{0020}choice.", "お嬢様二人だけではなくあなたの安全を確保することが、私の最も重要な任務ですわ。ですが、どうか誤解なさらないでください。これは、自分の意志で決めたことですから。", "確保兩位小姐以及你的安全自然是我的首要任務，但是請不要誤解，這是我自己的意願。", "0", "确保两位小姐以及你的安全自然是我的首要任务，但是请不要误解，这是我自己的意愿。", "0", "cv_tina_27", "0", "0"},
[430207] = {430207, 13002, 8, 5, "1_》_0_0.8", "level1", "Mind\u{0020}your\u{0020}manners.", "礼儀正しい振る舞いを、お願い致します。", "請注意禮儀。", "0", "请注意礼仪。", "0", "cv_tina_5", "0", "0"},
[430208] = {430208, 13002, 9, 5, "1_》_100_1.5", "level2", "Don't\u{0020}act\u{0020}like\u{0020}that\u{0020}in\u{0020}public!", "公の場ですし、このような行為は控えて頂きたいのですが。", "請不要在大庭廣眾下做出這種行為。", "0", "请不要在大庭广众下做出这种行为。", "0", "cv_tina_6", "0", "0"},
[430209] = {430209, 13002, 10, 5, "1_》_500_2", "level3", "Are\u{0020}you\u{0020}trying\u{0020}to\u{0020}get\u{0020}my\u{0020}attention?\u{0020}Or\u{0020}are\u{0020}you\u{0020}just\u{0020}asking\u{0020}for\u{0020}trouble?", "このようなことをなさるなんて……余程私の注意を引きつけたいのでしょうか。それとも、殴られたいのでしょうか。", "你這麼做……是為了引起我的注意嗎？還是說？想要討一頓打呢？", "0", "你这么做……是为了引起我的注意吗？还是说？想要讨一顿打呢？", "0", "cv_tina_7", "0", "0"},
[430210] = {430210, 13002, 11, 5, "1_》_1000_2.5", "level4", "My,\u{0020}my,\u{0020}you're\u{0020}a\u{0020}handful.\u{0020}Wasn't\u{0020}the\u{0020}last\u{0020}lesson\u{0020}enough?\u{0020}Hmph,\u{0020}you're\u{0020}the\u{0020}first\u{0020}to\u{0020}push\u{0020}me\u{0020}this\u{0020}far.\u{0020}Now\u{0020}I'll\u{0020}show\u{0020}you\u{0020}a\u{0020}punishment\u{0020}even\u{0020}the\u{0020}young\u{0020}ladies\u{0020}haven't\u{0020}experienced.", "まったく、しつこいコですね。この前の教訓、もうお忘れですか？ふん。この私をここまで追い詰めたのは、あなたが初めてです。では、お望み通りお嬢様たちすら味わったことのない罰を、味わわせてあげるといたしましょう。", "欸呀，還真是一個難纏的孩子，難道說上次的教訓還不夠嗎？哼，你是第一個把我逼到這一步的傢伙呢。接下來就讓你嘗嘗連兩位小姐都沒有嘗過的責罰好了。", "0", "哎呀，还真是一个难缠的孩子，难道说上次的教训还不够吗？哼，你是第一个把我逼到这一步的家伙呢。接下来就让你尝尝连两位小姐都没有尝过的责罚好了。", "0", "cv_tina_8", "0", "0"},
[430211] = {430211, 13002, 12, 6, "0", "0", "Oh,\u{0020}so\u{0020}you\u{0020}expect\u{0020}a\u{0020}lot\u{0020}from\u{0020}me?", "どうやら、私は期待されているようですね。", "欸呀，看來你對我心懷期待呢。", "0", "哎呀，看来你对我心怀期待呢。", "0", "cv_tina_9", "0", "0"},
