[430321] = {430321, 13003, 26, 19, "0", "0", "Sorry…\u{0020}Logistics\u{0020}is\u{0020}falling\u{0020}apart.", "ごめんね……後方支援……できなくなっちゃう……", "抱歉……後勤…要斷掉了啊。", "0", "抱歉……后勤…要断掉了啊。", "0", "cv_kurimu_19", "0", "0"},
[430322] = {430322, 13003, 27, 20, "0", "0", "Hey\u{0020}hey!\u{0020}You're\u{0020}about\u{0020}to\u{0020}see\u{0020}everything!", "ああっ！これじゃ全部見えちゃうじゃん！", "欸嘿嘿~要被你看光啦~", "0", "哎嘿嘿~要被你看光啦~", "0", "cv_kurimu_20", "0", "0"},
[430323] = {430323, 13003, 28, 21, "0", "0", "Wait,\u{0020}what?\u{0020}We\u{0020}can't\u{0020}eat\u{0020}while\u{0020}washing\u{0020}in\u{0020}the\u{0020}AEGIS\u{0020}bathhouse?", "え？アイギスの浴場って食べながら入っちゃダメなの？", "欸？原來艾吉斯的澡堂裡不能邊吃邊洗嗎？", "0", "哎？原来艾吉斯的澡堂里不能边吃边洗吗？", "0", "cv_kurimu_21", "0", "0"},
[430324] = {430324, 13003, 29, 21, "0", "0", "Should\u{0020}we\u{0020}spike\u{0020}the\u{0020}water\u{0020}tank\u{0020}with\u{0020}whiskey\u{0020}next\u{0020}time?", "今度はバスタブの中にウイスキーを入れてみようかな～", "下次要不要往水箱裏參點威士卡呢？", "0", "下次要不要往水箱里参点威士忌呢？", "0", "cv_kurimu_22", "0", "0"},
