[430326] = {430326, 13003, 31, 23, "0", "0", "Come\u{0020}on,\u{0020}as\u{0020}my\u{0020}best\u{0020}friend,\u{0020}you\u{0020}can't\u{0020}mistake\u{0020}me\u{0020}for\u{0020}someone\u{0020}else!", "さぁ、やろう。あたしの親友のあんたなら、間違えるはずないよね？", "來吧，來吧~身為我的摯友你應該不會認錯人吧。", "0", "来吧，来吧~身为我的挚友你应该不会认错人吧。", "0", "cv_kurimu_24", "0", "0"},
[430327] = {430327, 13003, 32, 24, "0", "0", "Hooray!", "ウラー！万歳！", "ура萬歲！", "0", "ура万岁！", "0", "cv_kurimu_25", "0", "0"},
