[430332] = {430332, 13003, 37, 29, "0", "0", "Ooh,\u{0020}ooh!\u{0020}So\u{0020}this\u{0020}is\u{0020}what\u{0020}being\u{0020}a\u{0020}leader\u{0020}feels\u{0020}like.", "おお、これがリーダーになった気分なのかね。", "喔喔喔，這就是當老大的感覺吧。", "0", "噢噢噢，这就是当老大的感觉吧。", "0", "cv_kurimu_33", "0", "0"},
[430333] = {430333, 13003, 38, 30, "0", "0", "Oh\u{0020}wow,\u{0020}new\u{0020}people\u{0020}already?\u{0020}That\u{0020}was\u{0020}fast.", "へぇー、新人が入ってくるんだ。もうそんな時期なの？", "欸呀呀，沒想到這麼快又要來新人了啊。", "0", "哎呀呀，没想到这么快又要来新人了啊。", "0", "cv_kurimu_34", "0", "0"},
[430334] = {430334, 13003, 39, 31, "0", "0", "Any\u{0020}gear\u{0020}will\u{0020}do.", "どんな装備でもいいよ。", "隨便什麼裝備都行喔~", "0", "随便什么装备都行哦~", "0", "cv_kurimu_35", "0", "0"},
[430335] = {430335, 13003, 40, 32, "0", "0", "Oh,\u{0020}and\u{0020}grab\u{0020}some\u{0020}sausages\u{0020}while\u{0020}you're\u{0020}at\u{0020}it!", "ついでにソーセージも買っておこう。", "順便買點香腸吧~", "0", "顺便买点香肠吧~", "0", "cv_kurimu_36", "0", "0"},
[430336] = {430336, 13003, 41, 33, "0", "0", "Wait,\u{0020}is\u{0020}this\u{0020}your\u{0020}dog\u{0020}tag?", "へぇ、これがあんたのドッグタグなの？", "欸呀呀，這是你的狗牌嗎？", "0", "哎呀呀，这是你的狗牌吗？", "0", "cv_kurimu_37", "0", "0"},
[430337] = {430337, 13003, 42, 34, "0", "0", "Just\u{0020}pick\u{0020}whatever\u{0020}works.", "適当に設定すればいいんじゃない？", "隨便設定一下就好了吧。", "0", "随便设置一下就好了吧。", "0", "cv_kurimu_38", "0", "0"},
[430338] = {430338, 13003, 43, 35, "0", "0", "Will\u{0020}someone\u{0020}bring\u{0020}us\u{0020}sausages?", "ソーセージを送ってくれる人はいるのかな？", "會有人給我們寄香腸嗎？", "0", "会有人给我们寄香肠吗？", "0", "cv_kurimu_39", "0", "0"},
[430339] = {430339, 13003, 44, 36, "0", "0", "We'll\u{0020}probably\u{0020}meet\u{0020}a\u{0020}lot\u{0020}of\u{0020}new\u{0020}friends.", "きっと、沢山の仲間に出会えるよ。", "應該能遇到不少夥伴吧。", "0", "应该能遇到不少伙伴吧。", "0", "cv_kurimu_40", "0", "0"},
[430340] = {430340, 13003, 45, 37, "0", "0", "Let\u{0020}me\u{0020}push\u{0020}this\u{0020}button.", "このボタン、押させてー！", "讓我按一下這個按鈕吧~", "0", "让我按一下这个按钮吧~", "0", "cv_kurimu_41", "0", "0"},
[430400] = {430400, 13004, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_ayaka_30", "0", "0"},
[430401] = {430401, 13004, 2, 2, "0", "0", "Got\u{0020}it!\u{0020}I'll\u{0020}stay\u{0020}right\u{0020}here\u{0020}and\u{0020}do\u{0020}my\u{0020}duty!\u{0020}Navigator,\u{0020}don't\u{0020}slack\u{0020}off\u{0020}either!", "了解！拙者、ここに立って使命を果たす！ナビゲーターも気を引き締めてくれ！", "瞭解！在下會一直站在這裡履行職責的！領航也千萬不要偷懶！", "0", "了解！在下会一直站在这里履行职责的！领航也千万不要偷懒！", "0", "cv_ayaka_2", "0", "0"},
[430402] = {430402, 13004, 3, 3, "0", "0", "I'm\u{0020}Caihua,\u{0020}the\u{0020}newly\u{0020}promoted\u{0020}medical\u{0020}officer.\u{0020}Ready\u{0020}for\u{0020}orders,\u{0020}Navigator!", "拙者は新しく就任した医療官、彩華！ミッションの指示を出してくれ、ナビゲーター！", "在下是新晉的醫療官-彩華！請下達任務吧，領航！", "0", "在下是新晋的医疗官-彩华！请下达任务吧，领航！", "0", "cv_ayaka_1", "0", "0"},
[430403] = {430403, 13004, 4, 4, "0", "idle", "Navigator!\u{0020}Does\u{0020}your\u{0020}neck\u{0020}hurt?\u{0020}I'm\u{0020}an\u{0020}expert\u{0020}in\u{0020}acupuncture\u{0020}and\u{0020}massage,\u{0020}I\u{0020}can\u{0020}fix\u{0020}you\u{0020}right\u{0020}up!", "首が痛いのか？拙者、鍼灸や点穴に精通している、無料で矯正してやろう。", "領航！你的脖子酸痛嗎？在下精通針灸點穴，可以免費幫您物理矯正一下！", "0", "领航！你的脖子酸痛吗？在下精通针灸点穴，可以免费帮您物理矫正一下！", "0", "cv_ayaka_3", "0", "0"},
[430404] = {430404, 13004, 5, 4, "0", "idle", "Some\u{0020}of\u{0020}these\u{0020}patients\u{0020}complain\u{0020}about\u{0020}my\u{0020}treatment\u{0020}just\u{0020}because\u{0020}it's\u{0020}a\u{0020}bit…\u{0020}unconventional.\u{0020}Sure,\u{0020}it\u{0020}hurts,\u{0020}but\u{0020}the\u{0020}results\u{0020}are\u{0020}worth\u{0020}it!", "もう……あいつら！治療方法がちょっと独特だからって拙者にクレームをつけるなんて！確かに痛いけど、その分治療効果が高いのだぞ！", "這幫可惡的傷患，就因為治療手段稍微特殊了點，居然私底下投訴在下。雖然很痛，但是效果絕對很好啊！", "0", "这帮可恶的伤员，就因为治疗手段稍微特殊了点，居然私底下投诉在下。虽然很痛，但是效果绝对很好啊！", "0", "cv_ayaka_4", "0", "0"},
[430405] = {430405, 13004, 6, 4, "0", "idle", "Hualian...\u{0020}she's\u{0020}always\u{0020}lost\u{0020}in\u{0020}her\u{0020}own\u{0020}world.\u{0020}One\u{0020}of\u{0020}these\u{0020}days,\u{0020}I'll\u{0020}straighten\u{0020}out\u{0020}those\u{0020}wandering\u{0020}thoughts\u{0020}with\u{0020}a\u{0020}few\u{0020}well-placed\u{0020}needles!", "華恋のやつ……可笑しなことばっかり考えて！いつか、鍼灸であの頭をどうにかしてやる！", "華戀那傢伙……腦子裏整天在想些奇怪的事情。有機會的話，在下一定要用針灸治好她的腦袋！", "0", "华恋那家伙……脑子里整天在想些奇怪的事情。有机会的话，在下一定要用针灸治好她的脑袋！", "0", "cv_ayaka_27", "0", "0"},
[430406] = {430406, 13004, 7, 5, "1_》_0_0.8", "level1", "My\u{0020}medical\u{0020}skills\u{0020}have\u{0020}been\u{0020}passed\u{0020}down\u{0020}through\u{0020}generations.\u{0020}My\u{0020}family's\u{0020}legacy\u{0020}may\u{0020}have\u{0020}faded,\u{0020}but\u{0020}I'll\u{0020}restore\u{0020}its\u{0020}glory!", "拙者の医術は先祖に代々伝わる技術だ。今はもう、没落してしまったが……いつかは必ず、先祖の栄光を取り戻す！", "在下的醫術，是家族歷代傳承的技藝。雖然現在已經落寞了，但是在下一定會重振家族榮光的！", "0", "在下的医术，是家族历代传承的技艺。虽然现在已经落寞了，但是在下一定会重振家族荣光的！", "0", "cv_ayaka_28", "0", "0"},
[430407] = {430407, 13004, 8, 5, "1_》_0_0.8", "level1", "It's\u{0020}work\u{0020}time.\u{0020}No\u{0020}fooling\u{0020}around,\u{0020}Navigator.", "仕事中に感心せんな、ナビゲーター。", "現在是工作時間，請不要胡鬧，領航。", "0", "现在是工作时间，请不要胡闹，领航。", "0", "cv_ayaka_5", "0", "0"},
[430408] = {430408, 13004, 9, 5, "1_》_100_1.5", "level2", "Navigator,\u{0020}care\u{0020}to\u{0020}try\u{0020}some\u{0020}acupressure?", "ひょっとして、点穴に興味あるのか？", "領航……你難道對點穴有興趣嗎？", "0", "领航……你难道对点穴有兴趣吗？", "0", "cv_ayaka_6", "0", "0"},
[430409] = {430409, 13004, 10, 5, "1_》_500_2", "level3", "Let\u{0020}me\u{0020}show\u{0020}you\u{0020}how\u{0020}it's\u{0020}done.\u{0020}The\u{0020}pain\u{0020}lasts\u{0020}just\u{0020}a\u{0020}moment,\u{0020}and\u{0020}it's\u{0020}over\u{0020}before\u{0020}you\u{0020}know\u{0020}it.", "拙者が正しい点穴のやり方の手本をお見せしよう――一瞬だけ痛みが走るが、すぐに終わる。", "領航，請允許在下為你示範正確的點穴方式吧——疼痛只是一瞬間的，馬上就結束了。", "0", "领航，请允许在下为你示范正确的点穴方式吧——疼痛只是一瞬间的，马上就结束了。", "0", "cv_ayaka_7", "0", "0"},
[430410] = {430410, 13004, 11, 5, "1_》_1000_2.5", "level4", "Navigator,\u{0020}mind\u{0020}if\u{0020}I\u{0020}use\u{0020}you\u{0020}for\u{0020}practice?\u{0020}Huh?\u{0020}It's\u{0020}work\u{0020}time…\u{0020}Well,\u{0020}alright,\u{0020}let's\u{0020}do\u{0020}it!", "もしよければ、拙者の練習相手になってくれるか？うえ？いいのか？仕事中なのに……では、失礼する！はっ！", "領航……如果你不介意的話，在下想請你作為在下的練習對象。欸？可以嗎？明明是工作時間……那麼，在下不客氣了！喝！", "0", "领航……如果你不介意的话，在下想请你作为在下的练习对象。诶？可以吗？明明是工作时间……那么，在下不客气了！喝！", "0", "cv_ayaka_8", "0", "0"},
[430411] = {430411, 13004, 12, 6, "0", "0", "Got\u{0020}the\u{0020}acupoints\u{0020}down\u{0020}perfectly!", "ふむ、経穴をもっと正確に把握できるようになった！", "嗯，對於穴道的把握也更加精准了！", "0", "嗯，对于穴道的把握也更加精准了！", "0", "cv_ayaka_9", "0", "0"},
[430412] = {430412, 13004, 13, 7, "0", "0", "My\u{0020}skills\u{0020}as\u{0020}a\u{0020}doctor\u{0020}have\u{0020}improved.", "医師としてのレベルが上がったぞ！", "作為醫師的水準上升了。", "0", "作为医师的水准上升了。", "0", "cv_ayaka_10", "0", "0"},
[430413] = {430413, 13004, 14, 8, "0", "0", "I\u{0020}can\u{0020}feel\u{0020}the\u{0020}power\u{0020}surging\u{0020}through\u{0020}me!\u{0020}You\u{0020}can\u{0020}trust\u{0020}me\u{0020}with\u{0020}all\u{0020}the\u{0020}treatment\u{0020}tasks\u{0020}now,\u{0020}Navigator.", "体の中から力がどんどん湧いてくる……ナビゲーター、これからも安心して治療のことは拙者に任せてくれ。", "力量從身體裡不斷湧出……領航，從今往後請放心地將治療任務交予在下吧。", "0", "力量从身体里不断涌出……领航，从今往后请放心地将治疗任务交予在下吧。", "0", "cv_ayaka_11", "0", "0"},
[430414] = {430414, 13004, 15, 9, "0", "0", "The\u{0020}treatment\u{0020}results\u{0020}have\u{0020}improved.", "治療効果が上がったぞ。", "領航，治療的效果提升了呢。", "0", "领航，治疗的效果提升了呢。", "0", "cv_ayaka_12", "0", "0"},
[430415] = {430415, 13004, 16, 10, "0", "0", "We're\u{0020}starting\u{0020}the\u{0020}operation.\u{0020}Let\u{0020}me\u{0020}know\u{0020}if\u{0020}you're\u{0020}hurt.", "作戦開始。負傷した者は拙者の所へ。", "作戰開始，請受傷的人來在下身邊。", "0", "作战开始，请受伤的人来在下身边。", "0", "cv_ayaka_13", "0", "0"},
[430416] = {430416, 13004, 17, 11, "0", "0", "As\u{0020}expected,\u{0020}no\u{0020}casualties\u{0020}and\u{0020}the\u{0020}enemies\u{0020}are\u{0020}wiped\u{0020}out!", "拙者の予想通り、死傷者ゼロで敵を全滅！", "就像在下預計的那樣，無人傷亡，全殲敵人！", "0", "就像在下预计的那样，无人伤亡，全歼敌人！", "0", "cv_ayaka_14", "0", "0"},
[430417] = {430417, 13004, 18, 12, "0", "0", "Check\u{0020}for\u{0020}any\u{0020}wounded.\u{0020}Treat\u{0020}them\u{0020}immediately.", "死傷者の状況を確認する。負傷した者はすぐ治療を受けるように！", "確認傷亡情況，受傷人員立即接受治療。", "0", "确认伤亡情况，受伤人员立即接受治疗。", "0", "cv_ayaka_15", "0", "0"},
[430418] = {430418, 13004, 19, 13, "0", "0", "A\u{0020}bloody\u{0020}victory…\u{0020}I'll\u{0020}do\u{0020}better\u{0020}next\u{0020}time.", "勝利したが大変だった……次はきっとうまくいく。", "慘烈的勝利……下次在下會做得更好的。", "0", "惨烈的胜利……下次在下会做得更好的。", "0", "cv_ayaka_16", "0", "0"},
[430419] = {430419, 13004, 20, 14, "0", "0", "Regroup,\u{0020}Navigator,\u{0020}we\u{0020}still\u{0020}have\u{0020}a\u{0020}shot.", "気を取り直せ。チャンスはまだある。", "領航，請重整旗鼓，我們還有機會。", "0", "领航，请重整旗鼓，我们还有机会。", "0", "cv_ayaka_17", "0", "0"},
[430420] = {430420, 13004, 23, 16, "0", "0", "Just\u{0020}hang\u{0020}in\u{0020}there\u{0020}for\u{0020}a\u{0020}bit!", "少しの辛抱だ！", "忍一下就好了！", "0", "忍一下就好了！", "0", "cv_ayaka_18", "0", "0"},
[430421] = {430421, 13004, 26, 19, "0", "0", "I\u{0020}guess\u{0020}doctors\u{0020}can't\u{0020}treat\u{0020}themselves…", "やっぱり……医者は自分の病を治せない、か……", "果然……醫者不能自醫嗎……", "0", "果然……医者不能自医吗……", "0", "cv_ayaka_19", "0", "0"},
[430422] = {430422, 13004, 27, 20, "0", "0", "Huh...\u{0020}nothing\u{0020}beats\u{0020}a\u{0020}hot\u{0020}bath\u{0020}after\u{0020}work,\u{0020}right,\u{0020}Navigator?", "ふぅ……仕事上がりの風呂はやっぱり最高だな！ナビゲーター。", "呼……工作後立馬就去泡澡果然是最棒的，對吧，領航？", "0", "呼……工作后立马就去泡澡果然是最棒的，对吧，领航？", "0", "cv_ayaka_20", "0", "0"},
[430423] = {430423, 13004, 28, 21, "0", "0", "One\u{0020}downside\u{0020}to\u{0020}baths—you\u{0020}can't\u{0020}do\u{0020}acupuncture\u{0020}before\u{0020}or\u{0020}after.", "熱い風呂の前後は鍼灸を施せない。これが風呂の唯一の欠点だ。", "熱浴的前後一段時間內都不能夠針灸，這是泡澡的唯一壞處呢。", "0", "热浴的前后一段时间内都不能够针灸，这是泡澡的唯一坏处呢。", "0", "cv_ayaka_21", "0", "0"},
[430424] = {430424, 13004, 29, 21, "0", "0", "You\u{0020}must\u{0020}be\u{0020}tired\u{0020}too,\u{0020}Navigator.\u{0020}I\u{0020}can\u{0020}give\u{0020}you\u{0020}a\u{0020}massage…\u{0020}No,\u{0020}it's\u{0020}not\u{0020}that\u{0020}painful!\u{0020}Don't\u{0020}be\u{0020}scared.", "ナビゲーターも疲れただろう？拙者がマッサージしてやる……？え？そんなに痛くないぞ！怖がらなくていい。", "領航也很累了吧，在下可以給你按摩喔……欸？沒有那麼痛的，不要害怕啦。", "0", "领航也很累了吧，在下可以给你按摩哦……诶？没有那么痛的，不要害怕啦。", "0", "cv_ayaka_22", "0", "0"},
[430425] = {430425, 13004, 30, 22, "0", "0", "Stay\u{0020}sharp,\u{0020}Navigator!", "十分気を付けるのだ！", "領航，請提高警惕！", "0", "领航，请提高警惕！", "0", "cv_ayaka_23", "0", "0"},
[430426] = {430426, 13004, 31, 23, "0", "0", "Alright,\u{0020}if\u{0020}you\u{0020}guess\u{0020}wrong,\u{0020}I'll\u{0020}sharpen\u{0020}your\u{0020}focus\u{0020}with\u{0020}a\u{0020}little\u{0020}acupuncture!", "よし、外れたら鍼でナビゲーターの頭をはっきりさせよう。", "決定了，猜錯的話，就用針讓領航的腦袋清醒過來！", "0", "决定了，猜错的话，就用针让领航的脑袋清醒过来！", "0", "cv_ayaka_24", "0", "0"},
[430427] = {430427, 13004, 32, 24, "0", "0", "Of\u{0020}course!\u{0020}It'd\u{0020}be\u{0020}bad\u{0020}if\u{0020}you\u{0020}got\u{0020}it\u{0020}wrong.", "当たり前の結果だ。外れたら大変なことになっていたぞ。", "這是理所當然的結果，猜錯了的話就糟糕了。", "0", "这是理所当然的结果，猜错了的话就糟糕了。", "0", "cv_ayaka_25", "0", "0"},
[430428] = {430428, 13004, 33, 25, "0", "0", "Be\u{0020}good,\u{0020}Navigator.\u{0020}It's\u{0020}not\u{0020}as\u{0020}painful\u{0020}as\u{0020}you\u{0020}think.", "ナビゲーターはいいコだからな、怖がらなくていい。思っているほど痛くないぞ。", "領航，乖，不要怕，沒有你想像中那麼痛的。", "0", "领航，乖，不要怕，没有你想象中那么痛的。", "0", "cv_ayaka_26", "0", "0"},
[430429] = {430429, 13004, 34, 26, "0", "0", "Welcome\u{0020}back,\u{0020}Navigator.\u{0020}Want\u{0020}to\u{0020}give\u{0020}my\u{0020}acupuncture\u{0020}a\u{0020}try?", "ナビゲーター、お帰り。拙者の鍼灸を体験してみないか？", "領航，歡迎回來，要試一下在下的針灸嗎？", "0", "领航，欢迎回来，要试一下在下的针灸吗？", "0", "cv_ayaka_29", "0", "0"},
[430430] = {430430, 13004, 35, 27, "0", "0", "There\u{0020}are\u{0020}still\u{0020}people\u{0020}waiting\u{0020}for\u{0020}treatment\u{0020}on\u{0020}the\u{0020}battlefield…\u{0020}Let's\u{0020}get\u{0020}to\u{0020}work!", "戦場には治療が必要な負傷者が沢山いるはず……指示を頼む！", "戰場上，一定有很多人在等待著治療……請下達指示吧！", "0", "战场上，一定有很多人在等待着治疗……请下达指示吧！", "0", "cv_ayaka_31", "0", "0"},
[430431] = {430431, 13004, 36, 28, "0", "0", "Only\u{0020}real\u{0020}combat\u{0020}can\u{0020}improve\u{0020}skills!", "技術は実践で鍛えられるものだ！", "只有通過實戰，技藝才能得到鍛煉！", "0", "只有通过实战，技艺才能得到锻炼！", "0", "cv_ayaka_32", "0", "0"},
[430432] = {430432, 13004, 37, 29, "0", "0", "Now,\u{0020}who\u{0020}needs\u{0020}treatment?", "治療が必要なものがいないか、拙者に確認させてくれ。", "讓在下看看，有誰需要治療~", "0", "让在下看看，有谁需要治疗~", "0", "cv_ayaka_33", "0", "0"},
[430433] = {430433, 13004, 38, 30, "0", "0", "Another\u{0020}sparring\u{0020}candidate?", "新しい練習相手が来るということか！", "又有新的陪練人選了！", "0", "又有新的陪练人选了！", "0", "cv_ayaka_34", "0", "0"},
