[430435] = {430435, 13004, 40, 32, "0", "0", "I\u{0020}want\u{0020}to\u{0020}shop\u{0020}too...", "拙者も買い物をしたいが……", "在下也想買點東西……", "0", "在下也想买点东西……", "0", "cv_ayaka_36", "0", "0"},
[430436] = {430436, 13004, 41, 33, "0", "0", "Let\u{0020}me\u{0020}check\u{0020}your\u{0020}neck,\u{0020}Navigator!", "ナビゲーター、拙者にその首をチェックさせよ！", "領航，讓在下檢查下你的脖子吧！", "0", "领航，让在下检查下你的脖子吧！", "0", "cv_ayaka_37", "0", "0"},
[430437] = {430437, 13004, 42, 34, "0", "0", "Configuring\u{0020}one's\u{0020}settings\u{0020}is\u{0020}kinda\u{0020}simimlar\u{0020}to\u{0020}acupressure.", "設定と点穴ってなんか似てるよな。", "設定和點穴，感覺很像呢。", "0", "设置和点穴，感觉很像呢。", "0", "cv_ayaka_38", "0", "0"},
[430438] = {430438, 13004, 43, 35, "0", "0", "Don't\u{0020}forget\u{0020}to\u{0020}read\u{0020}your\u{0020}mail.", "届いたメールをチェックするのを忘れるないよ。", "不要忘了看別人的信喔。", "0", "不要忘了看别人的信哦。", "0", "cv_ayaka_39", "0", "0"},
[430439] = {430439, 13004, 44, 36, "0", "0", "I\u{0020}want\u{0020}to\u{0020}chat\u{0020}with\u{0020}everyone\u{0020}too!", "拙者もこのように沢山の人とチャットしてみたい！", "在下也想和這麼多人聊天呢！", "0", "在下也想和这么多人聊天呢！", "0", "cv_ayaka_40", "0", "0"},
