[430501] = {430501, 13005, 2, 2, "0", "0", "Understood.\u{0020}I'll\u{0020}stand\u{0020}here\u{0020}and\u{0020}keep\u{0020}an\u{0020}eye\u{0020}on\u{0020}your\u{0020}work.", "0", "明白了，我會站在這裏監督您的工作的。", "0", "0", "0", "cv_genia_2", "0", "0"},
[430502] = {430502, 13005, 3, 3, "0", "0", "Genia\u{0020}Lee\u{0020}Zaytsev,\u{0020}a\u{0020}medical\u{0020}officer.\u{0020}Leave\u{0020}the\u{0020}treatments\u{0020}to\u{0020}me.", "0", "熱尼亞·李·紮伊采夫，擔任的職位是醫療官，治療的工作就交給我吧。", "0", "0", "0", "cv_genia_1", "0", "0"},
[430503] = {430503, 13005, 4, 4, "0", "idle", "Lydia…\u{0020}Yeah,\u{0020}I\u{0020}saved\u{0020}her,\u{0020}but\u{0020}that\u{0020}‘miracle'\u{0020}wasn't\u{0020}just\u{0020}because\u{0020}of\u{0020}me.\u{0020}Her\u{0020}will\u{0020}to\u{0020}survive\u{0020}was\u{0020}unbelievably\u{0020}strong.\u{0020}That's\u{0020}what\u{0020}did\u{0020}it.", "0", "莉迪亞…是的，我的確救過她的性命，但那次“奇跡”並不是因為我一個人而發生的。她那強烈到令人目眩，感到不可思議的求生意志才是關鍵。", "0", "0", "0", "cv_genia_29", "0", "0"},
[430504] = {430504, 13005, 5, 4, "0", "idle", "Tired?\u{0020}Compared\u{0020}to\u{0020}my\u{0020}old\u{0020}job,\u{0020}standing\u{0020}here\u{0020}feels\u{0020}like\u{0020}a\u{0020}break.", "0", "您問我累不累…和以前的工作比起來，站在這裏已經是一種休息了。", "0", "0", "0", "cv_genia_3", "0", "0"},
[430505] = {430505, 13005, 6, 4, "0", "idle", "Huh...\u{0020}Sorry,\u{0020}I\u{0020}was\u{0020}too\u{0020}relaxed\u{0020}and\u{0020}dozed\u{0020}off.\u{0020}My\u{0020}bad.", "0", "呼…呼…啊，抱歉，因為太放鬆了，不小心睡著了，失禮了。", "0", "0", "0", "cv_genia_4", "0", "0"},
[430506] = {430506, 13005, 7, 5, "1_》_0_0.8", "level1", "If\u{0020}it\u{0020}weren't\u{0020}for\u{0020}what\u{0020}happened\u{0020}with\u{0020}my\u{0020}grandma…\u{0020}I\u{0020}don't\u{0020}think\u{0020}I'd\u{0020}want\u{0020}to\u{0020}be\u{0020}a\u{0020}doctor.\u{0020}I\u{0020}guess\u{0020}the\u{0020}reason\u{0020}I\u{0020}keep\u{0020}going\u{0020}is\u{0020}because\u{0020}I\u{0020}can't\u{0020}bear\u{0020}to\u{0020}see\u{0020}anyone\u{0020}die\u{0020}in\u{0020}front\u{0020}of\u{0020}me.", "0", "如果不是奶奶的事…我大概不會想要去成為一名醫生吧。而之所以能夠一直堅持下來，大概是因為我不希望有人在自己眼前死去吧……", "0", "0", "0", "cv_genia_30", "0", "0"},
[430507] = {430507, 13005, 8, 5, "1_》_0_0.8", "level1", "What's\u{0020}wrong?\u{0020}Need\u{0020}carpal\u{0020}tunnel\u{0020}surgery?", "0", "怎麼了？需要我給您的腕管做切開手術嗎？", "0", "0", "0", "cv_genia_5", "0", "0"},
[430508] = {430508, 13005, 9, 5, "1_》_100_1.5", "level2", "I'm\u{0020}not\u{0020}just\u{0020}here\u{0020}to\u{0020}protect\u{0020}you,\u{0020}but\u{0020}everyone.\u{0020}That's\u{0020}my\u{0020}duty\u{0020}as\u{0020}a\u{0020}doctor.", "0", "不僅是確保您的生命安全，任何人的生命，我都有責任去守護。這就是醫生的職責。", "0", "0", "0", "cv_genia_6", "0", "0"},
[430509] = {430509, 13005, 10, 5, "1_》_500_2", "level3", "No\u{0020}one\u{0020}can\u{0020}escape\u{0020}death,\u{0020}but\u{0020}I\u{0020}hope\u{0020}people\u{0020}like\u{0020}you\u{0020}can\u{0020}have\u{0020}a\u{0020}peaceful,\u{0020}happy\u{0020}end.", "0", "沒有人能逃過死亡的命運。但——我希望，像您這樣的人，能迎來安詳的，幸福的死。", "0", "0", "0", "cv_genia_7", "0", "0"},
[430510] = {430510, 13005, 11, 5, "1_》_1000_2.5", "level4", "I've\u{0020}seen\u{0020}enough\u{0020}miracles\u{0020}and\u{0020}lives\u{0020}lost.\u{0020}I'll\u{0020}keep\u{0020}fighting\u{0020}as\u{0020}a\u{0020}doctor.\u{0020}Will\u{0020}you\u{0020}join\u{0020}me,\u{0020}Navigator?", "0", "生命的奇跡與凋零，我見證得足夠多了。今後，我也會一直以醫生的身份去戰鬥。領航，能與我同行嗎？", "0", "0", "0", "cv_genia_8", "0", "0"},
[430511] = {430511, 13005, 12, 6, "0", "0", "The\u{0020}treatment's\u{0020}more\u{0020}effective\u{0020}now.", "0", "嗯，治療的效率提高了。", "0", "0", "0", "cv_genia_9", "0", "0"},
[430512] = {430512, 13005, 13, 7, "0", "0", "Wait,\u{0020}is\u{0020}there\u{0020}really\u{0020}a\u{0020}way\u{0020}to\u{0020}improve\u{0020}more?", "0", "嗯？還有這種提升手段嗎？", "0", "0", "0", "cv_genia_10", "0", "0"},
[430513] = {430513, 13005, 14, 8, "0", "0", "Those\u{0020}soldiers\u{0020}risking\u{0020}everything\u{0020}to\u{0020}end\u{0020}this\u{0020}war\u{0020}need\u{0020}protection.\u{0020}Thank\u{0020}you,\u{0020}Navigator,\u{0020}for\u{0020}giving\u{0020}me\u{0020}the\u{0020}power\u{0020}to\u{0020}help\u{0020}them.", "0", "那些為了結束戰爭而在拼命的戰士，需要人去保護他們。謝謝您，領航，給了我這份力量，我會把它用在正確的地方的。", "0", "0", "0", "cv_genia_11", "0", "0"},
[430514] = {430514, 13005, 15, 9, "0", "0", "Medical\u{0020}tech\u{0020}keeps\u{0020}advancing.", "0", "醫療技術還在進步啊。", "0", "0", "0", "cv_genia_12", "0", "0"},
[430515] = {430515, 13005, 16, 10, "0", "0", "I'm\u{0020}here.\u{0020}You\u{0020}can\u{0020}fight\u{0020}with\u{0020}peace\u{0020}of\u{0020}mind.", "0", "我來了，請各位放心戰鬥吧。", "0", "0", "0", "cv_genia_13", "0", "0"},
[430516] = {430516, 13005, 17, 11, "0", "0", "A\u{0020}perfect\u{0020}victory\u{0020}doesn't\u{0020}mean\u{0020}there\u{0020}are\u{0020}no\u{0020}wounded.\u{0020}Let\u{0020}them\u{0020}come\u{0020}to\u{0020}me\u{0020}for\u{0020}treatment.", "0", "完美勝利？這不意味著沒有傷患，讓傷患過來接受治療。", "0", "0", "0", "cv_genia_14", "0", "0"},
[430517] = {430517, 13005, 18, 12, "0", "0", "Wounded?\u{0020}Come\u{0020}over\u{0020}here.", "0", "負傷者，過來。", "0", "0", "0", "cv_genia_15", "0", "0"},
[430518] = {430518, 13005, 19, 13, "0", "0", "Don't\u{0020}feel\u{0020}down.\u{0020}Prioritize\u{0020}the\u{0020}wounded.", "0", "別沮喪了，先轉移傷患。", "0", "0", "0", "cv_genia_16", "0", "0"},
[430519] = {430519, 13005, 20, 14, "0", "0", "Retreat!\u{0020}And\u{0020}don't\u{0020}leave\u{0020}anyone\u{0020}behind!", "0", "撤退！不要落下任何一個傷患！", "0", "0", "0", "cv_genia_17", "0", "0"},
[430520] = {430520, 13005, 23, 16, "0", "0", "It\u{0020}might\u{0020}sting\u{0020}a\u{0020}bit.", "0", "可能會有點痛。", "0", "0", "0", "cv_genia_18", "0", "0"},
[430521] = {430521, 13005, 26, 19, "0", "0", "Tch,\u{0020}looks\u{0020}like\u{0020}it's\u{0020}done\u{0020}here…", "0", "嘁，到此為止了啊……", "0", "0", "0", "cv_genia_19", "0", "0"},
[430522] = {430522, 13005, 24, 17, "0", "0", "Go\u{0020}ahead.\u{0020}Just\u{0020}don't\u{0020}get\u{0020}hurt\u{0020}anymore.", "0", "上吧…別再受傷了。", "0", "0", "0", "cv_genia_20", "0", "0"},
[430523] = {430523, 13005, 25, 18, "0", "0", "I'll\u{0020}save\u{0020}you,\u{0020}even\u{0020}if\u{0020}it\u{0020}costs\u{0020}me\u{0020}my\u{0020}life.", "0", "我會拯救你的……即使代價是我的生命。", "0", "0", "0", "cv_genia_21", "0", "0"},
[430524] = {430524, 13005, 27, 20, "0", "0", "Staying\u{0020}clean\u{0020}helps\u{0020}prevent\u{0020}disease.", "0", "時刻保持身體的清潔，能有效預防疾病。", "0", "0", "0", "cv_genia_22", "0", "0"},
[430525] = {430525, 13005, 28, 21, "0", "0", "This\u{0020}spot?\u{0020}Cut\u{0020}a\u{0020}two-inch\u{0020}incision\u{0020}and\u{0020}you'll\u{0020}see\u{0020}the\u{0020}heart\u{0020}valve.", "0", "這個位置？從這裏切開兩英寸的小口，就能看見心臟瓣膜了噢。", "0", "0", "0", "cv_genia_23", "0", "0"},
[430526] = {430526, 13005, 29, 21, "0", "0", "I've\u{0020}got\u{0020}surgical\u{0020}scars\u{0020}from\u{0020}the\u{0020}battlefield\u{0020}too.\u{0020}Want\u{0020}to\u{0020}see?", "0", "我身上也有以前戰場上自己留下的手術痕跡呢…要摸摸看嗎？", "0", "0", "0", "cv_genia_24", "0", "0"},
[430527] = {430527, 13005, 30, 22, "0", "0", "Stay\u{0020}alert\u{0020}and\u{0020}don't\u{0020}get\u{0020}injured.", "0", "提高警惕，不要受傷。", "0", "0", "0", "cv_genia_25", "0", "0"},
[430528] = {430528, 13005, 31, 23, "0", "0", "Hurry\u{0020}up\u{0020}and\u{0020}finish.\u{0020}I've\u{0020}got\u{0020}medical\u{0020}records\u{0020}to\u{0020}write.", "0", "快點結束吧，我還有病歷要寫。", "0", "0", "0", "cv_genia_26", "0", "0"},
[430529] = {430529, 13005, 32, 24, "0", "0", "Should\u{0020}I\u{0020}give\u{0020}you\u{0020}a\u{0020}kiss\u{0020}for\u{0020}doing\u{0020}well?\u{0020}…\u{0020}Just\u{0020}kidding!", "0", "需要我給你一個獎勵的吻嗎…呵，當然是開玩笑的。", "0", "0", "0", "cv_genia_27", "0", "0"},
[430530] = {430530, 13005, 33, 25, "0", "0", "Well,\u{0020}if\u{0020}that's\u{0020}all,\u{0020}I'll\u{0020}be\u{0020}heading\u{0020}out.", "0", "…沒有其他事的話，我先回去了。", "0", "0", "0", "cv_genia_28", "0", "0"},
[430531] = {430531, 13005, 34, 26, "0", "0", "Navigator,\u{0020}you're\u{0020}finally\u{0020}here.\u{0020}Here's\u{0020}the\u{0020}report\u{0020}on\u{0020}our\u{0020}last\u{0020}mission.", "0", "您終於來了，領航，這是之前的工作總結，您過目一下吧。", "0", "0", "0", "cv_genia_31", "0", "0"},
[430532] = {430532, 13005, 35, 27, "0", "0", "Let's\u{0020}head\u{0020}to\u{0020}the\u{0020}battlefield.\u{0020}There\u{0020}are\u{0020}people\u{0020}counting\u{0020}on\u{0020}us.", "0", "前往戰場吧，那裏有人需要我們。", "0", "0", "0", "cv_genia_33", "0", "0"},
[430533] = {430533, 13005, 36, 28, "0", "0", "Let's\u{0020}aim\u{0020}for\u{0020}a\u{0020}mission\u{0020}with\u{0020}no\u{0020}injuries\u{0020}next\u{0020}time.", "0", "那麼，以全員無傷為挑戰目標吧。", "0", "0", "0", "cv_genia_34", "0", "0"},
[430534] = {430534, 13005, 37, 29, "0", "0", "Is\u{0020}no\u{0020}one\u{0020}sick?", "0", "沒有人生病吧？", "0", "0", "0", "cv_genia_35", "0", "0"},
[430535] = {430535, 13005, 38, 30, "0", "0", "I'll\u{0020}set\u{0020}up\u{0020}medical\u{0020}exams\u{0020}for\u{0020}the\u{0020}newcomers.", "0", "我去給新人安排體檢。", "0", "0", "0", "cv_genia_36", "0", "0"},
[430536] = {430536, 13005, 39, 31, "0", "0", "We\u{0020}need\u{0020}top-tier\u{0020}medical\u{0020}equipment.", "0", "我們需要最先進的醫療器械。", "0", "0", "0", "cv_genia_37", "0", "0"},
[430537] = {430537, 13005, 40, 32, "0", "0", "Make\u{0020}sure\u{0020}to\u{0020}disinfect\u{0020}new\u{0020}supplies.", "0", "剛買的東西要記得消毒。", "0", "0", "0", "cv_genia_38", "0", "0"},
[430538] = {430538, 13005, 41, 33, "0", "0", "Always\u{0020}stay\u{0020}on\u{0020}top\u{0020}of\u{0020}personal\u{0020}hygiene.", "0", "要時刻注意個人衛生。", "0", "0", "0", "cv_genia_39", "0", "0"},
[430539] = {430539, 13005, 42, 34, "0", "0", "Being\u{0020}prepared\u{0020}is\u{0020}part\u{0020}of\u{0020}the\u{0020}job.", "0", "準備是工作的一環。", "0", "0", "0", "cv_genia_40", "0", "0"},
[430540] = {430540, 13005, 43, 35, "0", "0", "Don't\u{0020}forget\u{0020}to\u{0020}sort\u{0020}through\u{0020}your\u{0020}mail.", "0", "別忘了整理郵件。", "0", "0", "0", "cv_genia_41", "0", "0"},
[430541] = {430541, 13005, 44, 36, "0", "0", "Is\u{0020}this\u{0020}the\u{0020}waiting\u{0020}room?", "0", "這裏是等候室嗎？", "0", "0", "0", "cv_genia_42", "0", "0"},
[430542] = {430542, 13005, 45, 37, "0", "0", "Let's\u{0020}just\u{0020}click\u{0020}a\u{0020}bit.", "0", "點點看吧。", "0", "0", "0", "cv_genia_43", "0", "0"},
[430600] = {430600, 13006, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_yincao_31", "0", "0"},
[430601] = {430601, 13006, 2, 2, "0", "0", "Yes!\u{0020}So,\u{0020}what's\u{0020}the\u{0020}hourly\u{0020}wage...\u{0020}What,\u{0020}there\u{0020}isn't\u{0020}one?\u{0020}Tch—", "はぁい！じゃあ時給は……えぇ、でないの？ちぇ。", "是！那麼，時薪是…什麼，沒有嗎？嘁——", "0", "是！那么，时薪是…什么，没有吗？嘁——", "0", "cv_yincao_2", "0", "0"},
[430602] = {430602, 13006, 3, 3, "0", "0", "I'm\u{0020}Hotarugusa,\u{0020}and\u{0020}I'm\u{0020}here\u{0020}reporting\u{0020}in,\u{0020}Navigator!\u{0020}I'm\u{0020}an\u{0020}agent\u{0020}of\u{0020}the\u{0020}Shingyou\u{0020}House...\u{0020}No,\u{0020}a\u{0020}miko\u{0020}of\u{0020}the\u{0020}Heart\u{0020}Sutra\u{0020}House.", "ナビゲーターちゃん、お待たせぇ。心経屋のマネージャー…じゃなかった、心経屋の巫女、蛍草ちゃんよぉ。", "我來了喔~心經屋的經紀人…不，心經屋的巫女，小瑩草，向你報導，領航。", "0", "我来了噢~心经屋的经纪人…不，心经屋的巫女，小莹草，向你报道，领航。", "0", "cv_yincao_1", "0", "0"},
[430603] = {430603, 13006, 4, 4, "0", "idle", "Sister\u{0020}Hotarugusa?\u{0020}I\u{0020}hate\u{0020}that.\u{0020}Call\u{0020}me\u{0020}Little\u{0020}Hotarugusa.\u{0020}If\u{0020}you\u{0020}mess\u{0020}up\u{0020}next\u{0020}time...\u{0020}you'll\u{0020}regret\u{0020}it.", "蛍草姉さん？やあねえ。蛍草ちゃん、だよ。次に呼び間違えたら…死んじゃうかもよぉ？", "瑩草姐？討厭啦，是小瑩草才對。下次再叫錯的話…你會死喔？", "0", "莹草姐？讨厌啦，是小莹草才对。下次再叫错的话…你会死噢？", "0", "cv_yincao_3", "0", "0"},
[430604] = {430604, 13006, 5, 4, "0", "idle", "In\u{0020}today's\u{0020}world,\u{0020}anyone\u{0020}can\u{0020}become\u{0020}a\u{0020}miko\u{0020}with\u{0020}enough\u{0020}training.\u{0020}Navigator,\u{0020}want\u{0020}to\u{0020}give\u{0020}it\u{0020}a\u{0020}try?\u{0020}I\u{0020}even\u{0020}have\u{0020}a\u{0020}miko\u{0020}outfit\u{0020}ready\u{0020}for\u{0020}you.", "今はちょっと研修を受ければ、誰でも巫女になれるの。ナビゲーターちゃんはどう？あなたの分の巫女装束も用意してあるのよぉ。", "在現代社會，只要經受過培訓，任何人都能成為巫女——領航想試試看嗎，我給你備好巫女服了。", "0", "在现代社会，只要经受过培训，任何人都能成为巫女——领航想试试看吗，我给你备好巫女服了。", "0", "cv_yincao_4", "0", "0"},
[430605] = {430605, 13006, 6, 4, "0", "idle", "Navigator,\u{0020}you\u{0020}don't\u{0020}look\u{0020}well.\u{0020}Did\u{0020}Hanakotoba\u{0020}see\u{0020}us?\u{0020}Hmm...\u{0020}If\u{0020}she\u{0020}did,\u{0020}this\u{0020}could\u{0020}get\u{0020}complicated.\u{0020}Maybe\u{0020}we\u{0020}should\u{0020}book\u{0020}a\u{0020}hospital\u{0020}bed\u{0020}in\u{0020}advance?", "ナビゲーターちゃん、顔色が悪いわよ？……私たちが一緒にいるところを花語（はなことば）に見られたの？うーん……今のうちに病院のベッドの予約、しておいたらぁ？", "領航，你的臉色很難看喔——花語剛剛看到我們了？唔嗯…被她看見了的話，就麻煩了，是不是先預定一下床位比較好？", "0", "领航，你的脸色很难看噢——花语刚刚看到我们了？唔嗯…被她看见了的话，就麻烦了，是不是先预定一下床位比较好？", "0", "cv_yincao_28", "0", "0"},
[430606] = {430606, 13006, 7, 5, "1_》_0_0.8", "level1", "Guiding\u{0020}lost\u{0020}souls\u{0020}and\u{0020}lighting\u{0020}the\u{0020}way...\u{0020}I'm\u{0020}not\u{0020}sure\u{0020}I\u{0020}can\u{0020}be\u{0020}that\u{0020}kind\u{0020}of\u{0020}miko.\u{0020}But\u{0020}the\u{0020}girl\u{0020}I'm\u{0020}protecting...\u{0020}she\u{0020}has\u{0020}no\u{0020}other\u{0020}choice.\u{0020}Can\u{0020}you\u{0020}help\u{0020}me,\u{0020}Navigator?", "迷える人をそっと導いて、道を照らす灯りになる。……多分私はそんな巫女にはなれないと思うの。でも、私が守ったあの少女ならきっと……。ナビゲーターちゃん、お願い。力を貸してね。", "溫柔地引領迷茫之人，點亮前進道路的燈……大概，我沒辦法成為這樣的巫女。不過，我所守護那名少女一定…領航，你能幫我嗎？", "0", "温柔地引领迷茫之人，点亮前进道路的灯……大概，我没办法成为这样的巫女。不过，我所守护那名少女一定…领航，你能帮我吗？", "0", "cv_yincao_29", "0", "0"},
[430607] = {430607, 13006, 8, 5, "1_》_0_0.8", "level1", "Huh?\u{0020}Oh,\u{0020}just\u{0020}doing\u{0020}the\u{0020}monthly\u{0020}income\u{0020}and\u{0020}expenses.", "なに？ああ、今月の収支を計算していたところよぉ。", "嗯？喔，我正在算這個月的收支。", "0", "嗯？噢，我正在算这个月的收支。", "0", "cv_yincao_5", "0", "0"},
[430608] = {430608, 13006, 9, 5, "1_》_100_1.5", "level2", "People\u{0020}say\u{0020}a\u{0020}miko\u{0020}just\u{0020}needs\u{0020}to\u{0020}smile\u{0020}and\u{0020}greet\u{0020}guests...\u{0020}Don't\u{0020}belittle\u{0020}the\u{0020}profession!\u{0020}Cleaning,\u{0020}shrine\u{0020}duties,\u{0020}leading\u{0020}ceremonies,\u{0020}practicing\u{0020}dances—it's\u{0020}harder\u{0020}than\u{0020}it\u{0020}looks.", "巫女なんてニコニコしてれば何とかなるって言う人がいるけど……舐めないでほしいわ！神社の掃除に参拝者への対応、祭祀の補助に舞の練習……みんなが思っているほど楽じゃないのよぉ。", "居然有人說巫女只要微笑迎客就行了…別小看巫女這個職業啊！打掃衛生、朝拜神社、主持典禮，還要練習舞蹈…可沒想像中那麼輕鬆。", "0", "居然有人说巫女只要微笑迎客就行了…别小看巫女这个职业啊！打扫卫生、朝拜神社、主持典礼，还要练习舞蹈…可没想象中那么轻松。", "0", "cv_yincao_6", "0", "0"},
[430609] = {430609, 13006, 10, 5, "1_》_500_2", "level3", "You\u{0020}think\u{0020}I'm\u{0020}different\u{0020}from\u{0020}what\u{0020}you'd\u{0020}expect\u{0020}of\u{0020}a\u{0020}typical\u{0020}miko?\u{0020}Well,\u{0020}mikos\u{0020}became\u{0020}more\u{0020}independant\u{0020}after\u{0020}the\u{0020}Heian\u{0020}period.\u{0020}\"Reliable,\"\u{0020}huh?\u{0020}I'll\u{0020}take\u{0020}that\u{0020}as\u{0020}a\u{0020}compliment.", "想像してた巫女とは違う？ナビゲーターちゃん、平安時代と今では、巫女が与えられた役割が違うのよ。……頼もしい？フフ、もったいない言葉だわぁ。", "我和想像中的巫女不一樣？領航，平安年代之後，巫女被賦予沉重意義的時代也就結束了…“可靠”，呵呵，我就當做誇獎收下了。", "0", "我和想象中的巫女不一样？领航，平安年代之后，巫女被赋予沉重意义的时代也就结束了…“可靠”，呵呵，我就当做夸奖收下了。", "0", "cv_yincao_7", "0", "0"},
[430610] = {430610, 13006, 11, 5, "1_》_1000_2.5", "level4", "Words\u{0020}like\u{0020}\"dreams,\"\u{0020}\"ideals,\"\u{0020}and\u{0020}\"wishes\"...\u{0020}I\u{0020}haven't\u{0020}spoken\u{0020}those\u{0020}in\u{0020}a\u{0020}long\u{0020}time.\u{0020}But\u{0020}Kokorokami\u{0020}and\u{0020}you,\u{0020}Navigator—you\u{0020}should\u{0020}keep\u{0020}chasing\u{0020}them.\u{0020}Fly\u{0020}free,\u{0020}with\u{0020}no\u{0020}worries.\u{0020}Leave\u{0020}the\u{0020}rest\u{0020}to\u{0020}me.", "夢とか理想とか願いなんて、私には遠い思い出よ。でも…心紙ちゃんやナビゲーターちゃんには、まだそういったものを追いかけてほしいの。他のことは私に任せて、安心して前に進んでちょうだい。", "“夢想”、“理想”、“願望”之類的，我已經很久沒有說過這種話了。不過…心紙，還有領航，你們卻應該去追逐它們。請放心地翱翔吧，其他的交給我來處理吧。", "0", "“梦想”、“理想”、“愿望”之类的，我已经很久没有说过这种话了。不过…心纸，还有领航，你们却应该去追逐它们。请放心地翱翔吧，其他的交给我来处理吧。", "0", "cv_yincao_8", "0", "0"},
[430611] = {430611, 13006, 12, 6, "0", "0", "Thank\u{0020}you\u{0020}for\u{0020}your\u{0020}patronage!", "毎度ありがとうございまぁす。", "謝謝惠顧~", "0", "谢谢惠顾~", "0", "cv_yincao_9", "0", "0"},
[430612] = {430612, 13006, 13, 7, "0", "0", "I\u{0020}need\u{0020}to\u{0020}do\u{0020}these\u{0020}profit\u{0020}calculations\u{0020}carefully.", "収益はしっかり計算しないとね。", "要好好算下收益呢。", "0", "要好好算下收益呢。", "0", "cv_yincao_10", "0", "0"},
[430613] = {430613, 13006, 14, 8, "0", "0", "I\u{0020}swear\u{0020}I\u{0020}can\u{0020}hear\u{0020}the\u{0020}gods'\u{0020}voices...\u{0020}That's\u{0020}not\u{0020}possible.\u{0020}I'm\u{0020}not\u{0020}a\u{0020}\"true\u{0020}miko,\"\u{0020}after\u{0020}all.\u{0020}But\u{0020}even\u{0020}if\u{0020}I\u{0020}can't\u{0020}hear\u{0020}them,\u{0020}I\u{0020}can\u{0020}hear\u{0020}yours,\u{0020}Navigator.", "今、神様の声が聞こえた気が……なんて、そんな訳ないよね。私は本物の巫女じゃないんだから。でもね、ナビゲーターちゃん。神様の声は聞こえなくても、君の声は聞こえるわよ。", "現在的我，似乎能聽見神明的聲音…那是不可能的啦。畢竟，我並不是“真正的巫女”吧。不過，雖然聽不見神靈的聲音，但我能聽見你的聲音，領航。", "0", "现在的我，似乎能听见神明的声音…那是不可能的啦。毕竟，我并不是“真正的巫女”吧。不过，虽然听不见神灵的声音，但我能听见你的声音，领航。", "0", "cv_yincao_11", "0", "0"},
[430614] = {430614, 13006, 15, 9, "0", "0", "I'll\u{0020}do\u{0020}my\u{0020}best!", "私、頑張るわぁ。", "我會加油的~", "0", "我会加油的~", "0", "cv_yincao_12", "0", "0"},
[430615] = {430615, 13006, 16, 10, "0", "0", "Where's\u{0020}the\u{0020}troublemaker\u{0020}hiding?", "悪い子はどこかなぁ？", "不乖的傢伙在哪裡呢~", "0", "不乖的家伙在哪里呢~", "0", "cv_yincao_13", "0", "0"},
[430616] = {430616, 13006, 17, 11, "0", "0", "Clean\u{0020}up\u{0020}the\u{0020}battlefield\u{0020}and\u{0020}don't\u{0020}forget\u{0020}to\u{0020}recycle\u{0020}anything\u{0020}valuable.", "戦場をきれいにして、貴重品の回収も忘れずにねぇ。", "打掃戰場，記得回收貴重物品。", "0", "打扫战场，记得回收贵重物品。", "0", "cv_yincao_14", "0", "0"},
[430617] = {430617, 13006, 18, 12, "0", "0", "Even\u{0020}regret\u{0020}has\u{0020}its\u{0020}own\u{0020}beauty.\u{0020}Don't\u{0020}fret.", "後悔することも大事な経験よぉ。気にしない気にしない。", "遺憾也是一種美，別在意別在意。", "0", "遗憾也是一种美，别在意别在意。", "0", "cv_yincao_15", "0", "0"},
[430618] = {430618, 13006, 19, 13, "0", "0", "Leave\u{0020}the\u{0020}injured\u{0020}to\u{0020}me.", "ケガした人のお世話は私に任せて。", "傷患就交給我來照顧吧。", "0", "伤员就交给我来照顾吧。", "0", "cv_yincao_16", "0", "0"},
[430619] = {430619, 13006, 20, 14, "0", "0", "It's\u{0020}a\u{0020}mess...\u{0020}I'll\u{0020}figure\u{0020}it\u{0020}out...\u{0020}but\u{0020}for\u{0020}now,\u{0020}we\u{0020}should\u{0020}retreat.", "やっちゃった……なんとかしないと…とりあえず、一旦撤退ね。", "搞砸了…得想辦法彌補…總之，先暫時撤退吧。", "0", "搞砸了…得想办法弥补…总之，先暂时撤退吧。", "0", "cv_yincao_17", "0", "0"},
[430620] = {430620, 13006, 23, 16, "0", "0", "Um...\u{0020}um...\u{0020}I\u{0020}swing!", "よっ…こい…しょっ！", "嗯…嗯…我揮！", "0", "嗯…嗯…我挥！", "0", "cv_yincao_18", "0", "0"},
[430621] = {430621, 13006, 26, 19, "0", "0", "Take\u{0020}a...\u{0020}quick\u{0020}break...", "少し…休むわね……", "稍微…休息一下……", "0", "稍微…休息一下……", "0", "cv_yincao_19", "0", "0"},
[430622] = {430622, 13006, 24, 17, "0", "0", "I'm\u{0020}a\u{0020}professional.", "こう見えてプロなのよぉ！", "我可是專業的。", "0", "我可是专业的。", "0", "cv_yincao_20", "0", "0"},
[430623] = {430623, 13006, 27, 20, "0", "0", "This\u{0020}miko\u{0020}outfit\u{0020}is\u{0020}harder\u{0020}to\u{0020}take\u{0020}off\u{0020}than\u{0020}you\u{0020}might\u{0020}think.", "この巫女装束、君が思ってるより脱ぎにくいのよ。", "這件巫女服，脫下來可能比你想像中要麻煩喔。", "0", "这件巫女服，脱下来可能比你想象中要麻烦噢。", "0", "cv_yincao_21", "0", "0"},
[430624] = {430624, 13006, 28, 21, "0", "0", "Whoo-ha!\u{0020}All\u{0020}the\u{0020}soreness\u{0020}is\u{0020}gone.\u{0020}Navigator,\u{0020}want\u{0020}to\u{0020}give\u{0020}it\u{0020}a\u{0020}try?", "うはぁ……肩や腰がラクになったわぁ。ナビゲーターちゃんも試してみない？", "嗚哈——酸痛感全部消失了，領航，你不來試試嗎？", "0", "呜哈——酸痛感全部消失了，领航，你不来试试吗？", "0", "cv_yincao_22", "0", "0"},
[430625] = {430625, 13006, 29, 21, "0", "0", "It's\u{0020}about\u{0020}time\u{0020}to\u{0020}get\u{0020}back\u{0020}to\u{0020}work.\u{0020}We\u{0020}can't\u{0020}laze\u{0020}around\u{0020}forever.", "そろそろ仕事に戻らなきゃね。ずっとここでサボってるのもマズいしぃ。", "差不多該準備工作了，也不能一直在這裡偷懶吧。", "0", "差不多该准备工作了，也不能一直在这里偷懒吧。", "0", "cv_yincao_23", "0", "0"},
[430626] = {430626, 13006, 30, 22, "0", "0", "Lucky\u{0020}lot\u{0020}or\u{0020}unlucky\u{0020}lot?", "吉かな？それとも凶かなぁ？", "是“吉簽”呢？還是“凶簽”呢？", "0", "是“吉签”呢？还是“凶签”呢？", "0", "cv_yincao_24", "0", "0"},
[430627] = {430627, 13006, 31, 23, "0", "0", "If\u{0020}you\u{0020}guess\u{0020}wrong,\u{0020}I'll\u{0020}pin\u{0020}you\u{0020}to\u{0020}the\u{0020}sacred\u{0020}tree!", "間違えたら、ご神木に磔の刑よぉ。", "猜錯的話，就把你釘在神木上喔~", "0", "猜错的话，就把你钉在神木上哦~", "0", "cv_yincao_25", "0", "0"},
[430628] = {430628, 13006, 32, 24, "0", "0", "Congrats!\u{0020}Here's\u{0020}an\u{0020}amulet\u{0020}I\u{0020}made\u{0020}for\u{0020}you.\u{0020}Take\u{0020}it.", "おめでとう！手作りのお守りよ。受け取ってねぇ。", "恭喜，這是我親手做的禦守，收下吧~", "0", "恭喜，这是我亲手做的御守，收下吧~", "0", "cv_yincao_26", "0", "0"},
[430629] = {430629, 13006, 33, 25, "0", "0", "Ugh,\u{0020}what\u{0020}a\u{0020}pain...\u{0020}If\u{0020}there's\u{0020}no\u{0020}sacred\u{0020}tree,\u{0020}I'll\u{0020}just\u{0020}pin\u{0020}you\u{0020}to\u{0020}the\u{0020}bed\u{0020}instead.", "困ったわねぇ。ご神木がダメなら、ベットに磔の刑かなぁ。", "傷腦筋，沒有神木的話，就釘在床上吧~", "0", "伤脑筋，没有神木的话，就钉在床上吧~", "0", "cv_yincao_27", "0", "0"},
[430630] = {430630, 13006, 34, 26, "0", "0", "Oh,\u{0020}Navigator,\u{0020}you're\u{0020}here.\u{0020}I'm\u{0020}cleaning\u{0020}up.\u{0020}Just\u{0020}a\u{0020}moment.", "ナビゲーターちゃん、いらっしゃい。いま掃除しているから、ちょっと待ってねぇ。", "領航，你來了呀。我正在打掃衛生，稍等一下喔。", "0", "领航，你来了呀。我正在打扫卫生，稍等一下噢。", "0", "cv_yincao_30", "0", "0"},
[430631] = {430631, 13006, 35, 27, "0", "0", "I\u{0020}hear\u{0020}the\u{0020}sound\u{0020}of\u{0020}music...\u{0020}Navigator,\u{0020}your\u{0020}story\u{0020}is\u{0020}about\u{0020}to\u{0020}unfold.", "楽器の音色が聞こえる……ナビゲーターちゃんの物語が始まるのね。", "我聽見了樂器奏出的樂曲…領航，你的故事要開始了呢。", "0", "我听见了乐器奏出的乐曲…领航，你的故事要开始了呢。", "0", "cv_yincao_32", "0", "0"},
[430632] = {430632, 13006, 36, 28, "0", "0", "Extra\u{0020}tasks\u{0020}mean\u{0020}extra\u{0020}pay.", "残業手当が付くのよね？", "額外任務，要多付工資呢。", "0", "额外任务，要多付工资呢。", "0", "cv_yincao_33", "0", "0"},
[430633] = {430633, 13006, 37, 29, "0", "0", "Everyone,\u{0020}get\u{0020}along.\u{0020}No\u{0020}fighting.", "みんなは仲良く、喧嘩しないでねぇ。", "大家要好好相處，不要吵架喔。", "0", "大家要好好相处，不要吵架哦。", "0", "cv_yincao_34", "0", "0"},
[430634] = {430634, 13006, 38, 30, "0", "0", "I'll\u{0020}pray\u{0020}to\u{0020}the\u{0020}gods\u{0020}for\u{0020}good\u{0020}luck\u{0020}on\u{0020}your\u{0020}behalf!", "君の幸運を神様にお祈りするわねぇ。", "我會為你向神明祈禱好運的~", "0", "我会为你向神明祈祷好运的~", "0", "cv_yincao_35", "0", "0"},
[430635] = {430635, 13006, 39, 31, "0", "0", "May\u{0020}you\u{0020}draw\u{0020}the\u{0020}lot\u{0020}you\u{0020}desire.", "良い物が当たりますように。", "願你抽中想要的簽~", "0", "愿你抽中想要的签~", "0", "cv_yincao_36", "0", "0"},
[430636] = {430636, 13006, 40, 32, "0", "0", "Um...\u{0020}the\u{0020}price\u{0020}is\u{0020}just\u{0020}a\u{0020}reference...", "へえぇ。この値段は参考になるわぁ。", "嗯…價格可以作為參考……", "0", "嗯…价格可以作为参考……", "0", "cv_yincao_37", "0", "0"},
[430637] = {430637, 13006, 41, 33, "0", "0", "Have\u{0020}you\u{0020}thought\u{0020}about\u{0020}becoming\u{0020}a\u{0020}miko?", "巫女になってみない？", "有考慮過當巫女嗎？", "0", "有考虑过当巫女吗？", "0", "cv_yincao_38", "0", "0"},
[430638] = {430638, 13006, 42, 34, "0", "0", "Tedious\u{0020}prep\u{0020}work...", "こういうの、結構大変ねぇ。", "繁瑣的準備工作……", "0", "繁琐的准备工作……", "0", "cv_yincao_39", "0", "0"},
[430639] = {430639, 13006, 43, 35, "0", "0", "Got\u{0020}any\u{0020}guests\u{0020}making\u{0020}reservations?", "ご予約のお客様はいらっしゃいますかぁ？", "有客人要預約嗎？", "0", "有客人要预约吗？", "0", "cv_yincao_40", "0", "0"},
