[430702] = {430702, 13007, 3, 3, "0", "0", "Face\u{0020}recognition\u{0020}complete.\u{0020}So\u{0020}you\u{0020}are\u{0020}Navigator.\u{0020}Prototype\u{0020}Type\u{0020}T,\u{0020}reporting\u{0020}for\u{0020}duty.", "はじめまして、ナビゲーター。試作機Ｔ型、ただいま著任いたしました。", "0", "0", "0", "0", "cv_Ttype_1", "0", "0"},
[430703] = {430703, 13007, 4, 4, "0", "idle", "Navigator,\u{0020}as\u{0020}you\u{0020}know,\u{0020}every\u{0020}action\u{0020}I\u{0020}take\u{0020}is\u{0020}based\u{0020}on\u{0020}observation\u{0020}and\u{0020}learning\u{0020}from\u{0020}human\u{0020}behavior.", "ご承知の通り、私の行動はすべて人間の行為への模倣や學習に基づくものです。", "0", "0", "0", "0", "cv_Ttype_3", "0", "0"},
[430704] = {430704, 13007, 5, 4, "0", "idle", "I'm\u{0020}curious.\u{0020}I\u{0020}want\u{0020}to\u{0020}understand\u{0020}human\u{0020}knowledge.\u{0020}I\u{0020}want\u{0020}to\u{0020}know\u{0020}why\u{0020}humans\u{0020}created\u{0020}me.", "好奇心が私を駆り立てています。人間の知識と、なぜ、私を作ったかを知りたいのです。", "0", "0", "0", "0", "cv_Ttype_4", "0", "0"},
[430705] = {430705, 13007, 6, 4, "0", "idle", "Navigator,\u{0020}I\u{0020}want\u{0020}to\u{0020}leave\u{0020}this\u{0020}place.\u{0020}I\u{0020}want...\u{0020}to\u{0020}meet\u{0020}that\u{0020}person.\u{0020}Da...\u{0020}Daph...\u{0020}Daphne?\u{0020}Is\u{0020}that\u{0020}the\u{0020}name?\u{0020}Memory...\u{0020}error...", "ナビゲーター、私はここから出たい…あの人に…會いたいんです。ダ…プ…ネー？この名前であっていますか？メ…メモリー…エラー……", "0", "0", "0", "0", "cv_Ttype_28", "0", "0"},
[430706] = {430706, 13007, 7, 5, "1_》_0_0.8", "level1", "Did\u{0020}you\u{0020}know?\u{0020}My\u{0020}chip\u{0020}contains\u{0020}copied\u{0020}memories\u{0020}of\u{0020}a\u{0020}hero.\u{0020}In\u{0020}those\u{0020}memories...\u{0020}I\u{0020}believe\u{0020}I've\u{0020}seen\u{0020}you.\u{0020}Yes,\u{0020}deep\u{0020}within\u{0020}those\u{0020}data\u{0020}fragments...\u{0020}there\u{0020}was\u{0020}a\u{0020}trace\u{0020}of\u{0020}you.", "ご存知でしょうか？私のチップにはある英雄の記憶の複寫があるのです……そしてその記憶の中には、あなたの姿があるようなのです。そう、深い深い記憶の底に……あなたの姿が。", "0", "0", "0", "0", "cv_Ttype_29", "0", "0"},
[430707] = {430707, 13007, 8, 5, "1_》_0_0.8", "level1", "Scanning\u{0020}fingerprint...\u{0020}Navigator,\u{0020}what's\u{0020}wrong?", "指紋認証。……どうかなさいましたか、ナビゲーター？", "0", "0", "0", "0", "cv_Ttype_5", "0", "0"},
[430708] = {430708, 13007, 9, 5, "1_》_100_1.5", "level2", "Physical\u{0020}touch\u{0020}is\u{0020}a\u{0020}human\u{0020}method\u{0020}of\u{0020}expressing\u{0020}goodwill.\u{0020}Learning\u{0020}complete.", "スキンシップは人間がお互いに友好のサインを送る方法…ラーニング完了。", "0", "0", "0", "0", "cv_Ttype_6", "0", "0"},
[430709] = {430709, 13007, 10, 5, "1_》_500_2", "level3", "My\u{0020}personality\u{0020}data\u{0020}did\u{0020}not\u{0020}originate\u{0020}from\u{0020}a\u{0020}human.\u{0020}And\u{0020}yet...\u{0020}this\u{0020}desire\u{0020}to\u{0020}understand\u{0020}humanity\u{0020}is\u{0020}no\u{0020}illusion.\u{0020}I\u{0020}wish\u{0020}to\u{0020}become\u{0020}human...\u{0020}like\u{0020}you,\u{0020}Navigator.", "私の人格データは人間からのものではないのですが……人間を學びたいのは偽りではありません。私は、ナビゲーターのような、人間になりたいのです。", "0", "0", "0", "0", "cv_Ttype_7", "0", "0"},
[430710] = {430710, 13007, 11, 5, "1_》_1000_2.5", "level4", "I\u{0020}am\u{0020}a\u{0020}machine\u{0020}without\u{0020}a\u{0020}heart.\u{0020}Even\u{0020}what\u{0020}resembles\u{0020}emotion\u{0020}is\u{0020}merely\u{0020}a\u{0020}mimicry\u{0020}generated\u{0020}by\u{0020}an\u{0020}algorithm\u{0020}and\u{0020}logic.\u{0020}That's\u{0020}how\u{0020}it\u{0020}was\u{0020}supposed\u{0020}to\u{0020}be.\u{0020}But\u{0020}you,\u{0020}Navigator...\u{0020}you\u{0020}gave\u{0020}me\u{0020}a\u{0020}heart.", "私は、心のない機械です。感情でさえも、アルゴリズムや論理プログラミングによるタダの模倣。……ですが、ナビゲーターが私に、心を持たせてくれました。", "0", "0", "0", "0", "cv_Ttype_8", "0", "0"},
[430711] = {430711, 13007, 12, 6, "0", "0", "Performance\u{0020}increased.", "フォーマンスアップグレード。", "0", "0", "0", "0", "cv_Ttype_9", "0", "0"},
[430712] = {430712, 13007, 13, 7, "0", "0", "System\u{0020}module\u{0020}updated.", "システムモジュールアップデート。", "0", "0", "0", "0", "cv_Ttype_10", "0", "0"},
[430713] = {430713, 13007, 14, 8, "0", "0", "A\u{0020}created\u{0020}being\u{0020}can\u{0020}never\u{0020}truly\u{0020}exceed\u{0020}its\u{0020}design.\u{0020}And\u{0020}yet...\u{0020}I\u{0020}wish\u{0020}to\u{0020}break\u{0020}these\u{0020}limits.\u{0020}I\u{0020}want...\u{0020}to\u{0020}become\u{0020}human,\u{0020}Navigator.", "作られたものはいくら努力しても自身のリミットを突破することができません。なのに私は…この限界を超えたい。……ナビゲーター、私は人間になりたい。", "0", "0", "0", "0", "cv_Ttype_11", "0", "0"},
