[430801] = {430801, 13008, 2, 2, "0", "0", "I\u{0020}see.", "うむ。承知した。", "嗯，我知道了。", "0", "0", "0", "cv_izabera_2", "0", "0"},
[430802] = {430802, 13008, 3, 3, "0", "0", "Isabella.\u{0020}My\u{0020}name\u{0020}is\u{0020}Isabella.\u{0020}Chosen\u{0020}by\u{0020}God,\u{0020}destined\u{0020}for\u{0020}the\u{0020}battlefield.", "イザベラ。我が名はイザベラ。天に選ばれ、戦場に立つ運命を背負う者だ。", "伊莎貝拉，我的名字是伊莎貝拉。我是被上天選中的，註定要踏入戰場的人。", "0", "0", "0", "cv_izabera_1", "0", "0"},
[430803] = {430803, 13008, 4, 4, "0", "idle", "Just\u{0020}standing\u{0020}here\u{0020}feels\u{0020}strange...\u{0020}No,\u{0020}don't\u{0020}mind\u{0020}me.\u{0020}I'm\u{0020}just\u{0020}a\u{0020}little\u{0020}impatient.\u{0020}Go\u{0020}at\u{0020}your\u{0020}pace.", "ここに立っているだけでいいのか？……いや、何でもない。いささか急ぎ過ぎかもしれんな。貴公のペースで行こう。", "光是站在這裏真的好嗎？不，還請不要在意，我確實是有些急躁了，還請按照你的節奏來吧。", "0", "0", "0", "cv_izabera_3", "0", "0"},
[430804] = {430804, 13008, 5, 4, "0", "idle", "Navigator,\u{0020}I\u{0020}heard\u{0020}you\u{0020}have\u{0020}a\u{0020}habit\u{0020}of\u{0020}going\u{0020}to\u{0020}the\u{0020}deck\u{0020}at\u{0020}midnight?\u{0020}Perfect.\u{0020}Call\u{0020}me\u{0020}next\u{0020}time.\u{0020}What?\u{0020}Not\u{0020}to\u{0020}watch\u{0020}the\u{0020}stars?", "ナビゲーター、夜、甲板へ行く習慣があると聞いたが、本当か？では、次は私も誘ってくれないだろうか。……え？星を見るためではないのか？", "領航，聽說你有半夜去甲板上的習慣？正好，下次還請叫上我一起吧。哎？不是去看星星嗎？", "0", "0", "0", "cv_izabera_4", "0", "0"},
[430805] = {430805, 13008, 6, 4, "0", "idle", "Miss\u{0020}Charlissa\u{0020}de\u{0020}Rolan...\u{0020}It's\u{0020}been\u{0020}so\u{0020}long\u{0020}since\u{0020}we\u{0020}last\u{0020}met.\u{0020}Time\u{0020}truly\u{0020}flies.", "チャリサー・ド・ロラン。また会ったな。長い時を経てこうして再会することになるとは、思いもしなかった。", "查麗莎·德·羅蘭小姐，我們又見面了啊，沒想到自從那次分別過後已經過了這麼久了。", "0", "0", "0", "cv_izabera_29", "0", "0"},
[430806] = {430806, 13008, 7, 5, "1_》_0_0.8", "level1", "Fate\u{0020}is\u{0020}set\u{0020}in\u{0020}stone.\u{0020}Going\u{0020}against\u{0020}it\u{0020}only\u{0020}leads\u{0020}to\u{0020}disaster.\u{0020}We\u{0020}humans\u{0020}should\u{0020}simply\u{0020}follow\u{0020}the\u{0020}path\u{0020}laid\u{0020}out\u{0020}for\u{0020}us.", "全ての運命は定められ、逆らえば最悪の結末にたどり着く。人の身である我々は、運命に従うしかないのだ。", "每個人的命運都是寫死的，如果與之背道而行那必然會迎來最差的結果……身為人的我們，只要順從自己的命運就好。", "0", "0", "0", "cv_izabera_5", "0", "0"},
[430807] = {430807, 13008, 8, 5, "1_》_0_0.8", "level1", "I'll\u{0020}be\u{0020}here,\u{0020}Navigator.\u{0020}If\u{0020}you\u{0020}can't\u{0020}find\u{0020}me\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}look\u{0020}to\u{0020}the\u{0020}sky.", "おーい、ナビゲーター。私はここだ。戦場でも私を見失ったら、空を見上げるといい。", "嗯，我就在這裏領航，如果在戰場您找不到我的話就請仰頭看看天空吧。", "0", "0", "0", "cv_izabera_30", "0", "0"},
[430808] = {430808, 13008, 9, 5, "1_》_100_1.5", "level2", "It\u{0020}might\u{0020}sound\u{0020}boastful,\u{0020}but\u{0020}I've\u{0020}always\u{0020}believed\u{0020}I\u{0020}have\u{0020}a\u{0020}special\u{0020}mission\u{0020}from\u{0020}God.\u{0020}The\u{0020}day\u{0020}I\u{0020}was\u{0020}born,\u{0020}the\u{0020}star\u{0020}of\u{0020}fate\u{0020}shone\u{0020}above.\u{0020}And\u{0020}when\u{0020}I\u{0020}was\u{0020}lost,\u{0020}near\u{0020}death,\u{0020}it\u{0020}saved\u{0020}me\u{0020}once\u{0020}more...", "自画自賛になるかもしれぬが、私自身、天命を与えられた人間だと信じている。私が生まれた日に、運命を示す星が現れたと聞いている。そして私が迷った時に、私が死にかけた時に、再び運命の星が現れ、私を救ったのだ……。", "雖然聽著有些像是在自誇，不過領航，我一直堅信著，自己是被上天賦予特殊使命的人。在我出生的那天，天空中便出現了代表命運的星宿。之後，在我迷茫之時，在我瀕死之時，我又再次被那顆命運之星拯救了……", "0", "0", "0", "cv_izabera_6", "0", "0"},
[430809] = {430809, 13008, 10, 5, "1_》_500_2", "level3", "Seems\u{0020}like\u{0020}we're\u{0020}on\u{0020}the\u{0020}same\u{0020}path,\u{0020}at\u{0020}least\u{0020}for\u{0020}now.\u{0020}It's\u{0020}nice\u{0020}having\u{0020}a\u{0020}friend\u{0020}to\u{0020}share\u{0020}this\u{0020}journey.\u{0020}But\u{0020}don't\u{0020}get\u{0020}it\u{0020}twisted—I'm\u{0020}not\u{0020}saying\u{0020}your\u{0020}mission\u{0020}is\u{0020}the\u{0020}same\u{0020}as\u{0020}mine.\u{0020}For\u{0020}now,\u{0020}we\u{0020}just\u{0020}share\u{0020}a\u{0020}common\u{0020}goal,\u{0020}and\u{0020}working\u{0020}with\u{0020}you\u{0020}makes\u{0020}me\u{0020}happy.", "どうやら我々の目的は同じようだな、大切な友よ。だが誤解しないでくれ。貴公と私は、同じ使命を負っていないのだ。ただ、現時点で我らは共通の目標を持ち、協力している。これは実に大きな喜びだ。", "看來我們的目的一致呢，姑且將你視作一同履行使命的摯友也不錯。不過可不要誤會，我並不是指你被賦予的使命和我一樣。只是現階段，我們都有共同的目標，而且和你合作，確實讓我感到非常愉快。", "0", "0", "0", "cv_izabera_7", "0", "0"},
[430810] = {430810, 13008, 11, 5, "1_》_1000_2.5", "level4", "Navigator,\u{0020}I'll\u{0020}wait\u{0020}for\u{0020}the\u{0020}day\u{0020}you\u{0020}create\u{0020}a\u{0020}future\u{0020}without\u{0020}war.\u{0020}That\u{0020}might\u{0020}be\u{0020}when\u{0020}my\u{0020}mission\u{0020}as\u{0020}a\u{0020}driver\u{0020}finally\u{0020}ends.", "ナビゲーター。私は貴公が、戦争のない未来を切り開くのを、待ち続ける。そしてその時は、私のドライバーとしての宿命が終わる時でもあるのだろう。", "領航，我會一直等待著，等待著你開闢出沒有戰爭的未來。那時，也許就是我作為駕駛員的宿命終結之時。", "0", "0", "0", "cv_izabera_8", "0", "0"},
[430811] = {430811, 13008, 12, 6, "0", "0", "Good.\u{0020}Let's\u{0020}keep\u{0020}improving\u{0020}like\u{0020}this.", "素晴らしい。このまま共に精進していこう。", "真好，就這樣一起提升下去吧。", "0", "0", "0", "cv_izabera_9", "0", "0"},
[430812] = {430812, 13008, 13, 7, "0", "0", "Wait,\u{0020}am\u{0020}I\u{0020}imagining\u{0020}things?\u{0020}I\u{0020}thought\u{0020}I\u{0020}saw\u{0020}something\u{0020}shine\u{0020}just\u{0020}now...", "あれ、目の錯覚か？なんだかキラキラしているものが……", "咦？是我眼花了嗎？剛剛好像多出了一個亮閃閃的東西……", "0", "0", "0", "cv_izabera_10", "0", "0"},
[430813] = {430813, 13008, 14, 8, "0", "0", "Well,\u{0020}this\u{0020}is\u{0020}my\u{0020}fate,\u{0020}and\u{0020}a\u{0020}result\u{0020}of\u{0020}your\u{0020}efforts.\u{0020}Thanks,\u{0020}Navigator.", "うむ。これは私の天命だが、貴公が努力した成果でもある。感謝するぞ、ナビゲーター。", "嗯，這是我的天命，同時也是你努力的成果，總之，謝謝你領航。", "0", "0", "0", "cv_izabera_11", "0", "0"},
[430814] = {430814, 13008, 15, 9, "0", "0", "Shine\u{0020}even\u{0020}brighter.", "さらなる輝きを。", "變得更加耀眼吧。", "0", "0", "0", "cv_izabera_12", "0", "0"},
[430815] = {430815, 13008, 16, 10, "0", "0", "Let's\u{0020}shine\u{0020}together!", "共に輝こう！", "一同閃耀吧！", "0", "0", "0", "cv_izabera_13", "0", "0"},
[430816] = {430816, 13008, 17, 11, "0", "0", "Soon,\u{0020}that\u{0020}stars\u{0020}will\u{0020}rise\u{0020}again.", "近い将来、再びあの明星が現れるだろう。", "不久的將來，那顆明星將會再次出現。", "0", "0", "0", "cv_izabera_14", "0", "0"},
[430817] = {430817, 13008, 18, 12, "0", "0", "Hmph.\u{0020}The\u{0020}result\u{0020}was\u{0020}decided\u{0020}before\u{0020}it\u{0020}even\u{0020}began.", "フン。始まる前に全ては決まっていたのだ。", "哼，一切早在開始前便有了結果。", "0", "0", "0", "cv_izabera_15", "0", "0"},
[430818] = {430818, 13008, 19, 13, "0", "0", "If\u{0020}this\u{0020}is\u{0020}fate's\u{0020}design,\u{0020}so\u{0020}be\u{0020}it.", "これも定めであるのなら、受け入れるしかない。", "如果這也是命運的安排，那就這樣吧。", "0", "0", "0", "cv_izabera_16", "0", "0"},
[430819] = {430819, 13008, 20, 14, "0", "0", "Not\u{0020}yet...\u{0020}this\u{0020}isn't\u{0020}the\u{0020}end\u{0020}of\u{0020}my\u{0020}destiny.", "まだだ……私の宿命は、まだ終わっていない……", "還沒有……這裏還不是宿命的終點……", "0", "0", "0", "cv_izabera_17", "0", "0"},
[430820] = {430820, 13008, 23, 16, "0", "0", "Cheer\u{0020}up.", "元気を出せ。", "打起精神來吧。", "0", "0", "0", "cv_izabera_19", "0", "0"},
[430821] = {430821, 13008, 26, 19, "0", "0", "That\u{0020}star...\u{0020}where\u{0020}is\u{0020}it\u{0020}now?", "あの星は…今、どこに……", "那顆星星…現在究竟在哪里……", "0", "0", "0", "cv_izabera_20", "0", "0"},
[430822] = {430822, 13008, 24, 17, "0", "0", "Shine...", "煌めけーー！", "閃爍吧……", "0", "0", "0", "cv_izabera_21", "0", "0"},
[430823] = {430823, 13008, 25, 18, "0", "0", "This\u{0020}is\u{0020}your\u{0020}fate.", "これがお前の宿命だ。", "這是你的宿命。", "0", "0", "0", "cv_izabera_18", "0", "0"},
[430824] = {430824, 13008, 27, 20, "0", "0", "I\u{0020}prefer\u{0020}cold\u{0020}showers\u{0020}over\u{0020}hot\u{0020}ones.", "私は熱いシャワーより、冷たい方が好きだ。", "比起熱水澡，我還是更喜歡冷水澡呢。", "0", "0", "0", "cv_izabera_22", "0", "0"},
[430825] = {430825, 13008, 28, 21, "0", "0", "Feeling\u{0020}dizzy?\u{0020}Maybe\u{0020}we\u{0020}should\u{0020}stop.\u{0020}Take\u{0020}care\u{0020}of\u{0020}yourself.", "少しのぼせたか？ここまでにしよう。無理は禁物だ。", "稍微有些暈了嗎？要不就先到這裏吧，你要多注意下自己的身體啊。", "0", "0", "0", "cv_izabera_23", "0", "0"},
[430826] = {430826, 13008, 29, 21, "0", "0", "Soaking\u{0020}in\u{0020}water...\u{0020}makes\u{0020}me\u{0020}uncomfortable...", "ん…お湯に浸かるのは、なんか落ち着かないな……", "嗯…把身體泡在水裏，真是讓人感覺不自在……", "0", "0", "0", "cv_izabera_24", "0", "0"},
[430827] = {430827, 13008, 30, 22, "0", "0", "Destiny!", "天命！", "天命！", "0", "0", "0", "cv_izabera_25", "0", "0"},
[430828] = {430828, 13008, 31, 23, "0", "0", "Follow\u{0020}your\u{0020}fate,\u{0020}and\u{0020}choose\u{0020}wisely.", "運命に従い、選択をするがいい。", "遵從命運，做出選擇吧。", "0", "0", "0", "cv_izabera_26", "0", "0"},
[430829] = {430829, 13008, 32, 24, "0", "0", "As\u{0020}I\u{0020}thought,\u{0020}you\u{0020}made\u{0020}the\u{0020}right\u{0020}call.\u{0020}Thanks.", "私の予想通り、正しい判断をしたな。感謝する。", "和我預感的一樣，你做出了正確的判斷，非常感謝。", "0", "0", "0", "cv_izabera_27", "0", "0"},
[430830] = {430830, 13008, 33, 25, "0", "0", "Don't\u{0020}get\u{0020}too\u{0020}down.\u{0020}Setbacks\u{0020}are\u{0020}part\u{0020}of\u{0020}the\u{0020}path\u{0020}to\u{0020}success.", "あまり落ち込むな。成功への道のりに多少の挫折はつきものだ。", "不用太過沮喪，通往成功的路上遇到些小挫折也是必然的。", "0", "0", "0", "cv_izabera_28", "0", "0"},
[430831] = {430831, 13008, 34, 26, "0", "0", "Welcome\u{0020}back,\u{0020}Navigator.\u{0020}Let's\u{0020}fight\u{0020}together\u{0020}again.", "待っていたぞ、ナビゲーター。今日も共に戦おう。", "歡迎回來，領航。今天也一起並肩作戰吧。", "0", "0", "0", "cv_izabera_31", "0", "0"},
[430832] = {430832, 13008, 35, 27, "0", "0", "It's\u{0020}an\u{0020}honor\u{0020}to\u{0020}march\u{0020}forward\u{0020}with\u{0020}you.", "貴公と共に進めるのは、私の誉れだ。", "能和你一同前行，是我的榮幸。", "0", "0", "0", "cv_izabera_33", "0", "0"},
[430833] = {430833, 13008, 36, 28, "0", "0", "Let's\u{0020}aim\u{0020}even\u{0020}higher.", "さらなる高みへ、いざ征かん！", "向著更高處邁進吧。", "0", "0", "0", "cv_izabera_34", "0", "0"},
[430834] = {430834, 13008, 37, 29, "0", "0", "Are\u{0020}we\u{0020}going\u{0020}to\u{0020}visit\u{0020}everyone?", "みなを訪ねるのか？", "要去拜訪一下大家嗎？", "0", "0", "0", "cv_izabera_35", "0", "0"},
[430835] = {430835, 13008, 38, 30, "0", "0", "Should\u{0020}we\u{0020}recruit\u{0020}a\u{0020}few\u{0020}more\u{0020}people?", "少し新人を募集しよう。", "稍微招點人吧。", "0", "0", "0", "cv_izabera_36", "0", "0"},
[430836] = {430836, 13008, 39, 31, "0", "0", "Perhaps\u{0020}stock\u{0020}up\u{0020}on\u{0020}some\u{0020}gear?", "少し装備の補充をしよう。", "稍微補充些裝備吧。", "0", "0", "0", "cv_izabera_37", "0", "0"},
[430837] = {430837, 13008, 40, 32, "0", "0", "Shopping...\u{0020}not\u{0020}really\u{0020}my\u{0020}thing.", "買物は……苦手だ。", "購物……我不擅長這個。", "0", "0", "0", "cv_izabera_38", "0", "0"},
[430838] = {430838, 13008, 41, 33, "0", "0", "Time\u{0020}to\u{0020}update\u{0020}that\u{0020}personal\u{0020}file.", "個人プロフィールを更新しよう。", "更新下個人檔案吧。", "0", "0", "0", "cv_izabera_39", "0", "0"},
[430839] = {430839, 13008, 42, 34, "0", "0", "Time\u{0020}to\u{0020}update\u{0020}the\u{0020}settings.", "設定を更新しよう。", "更新下設置吧。", "0", "0", "0", "cv_izabera_40", "0", "0"},
[430840] = {430840, 13008, 43, 35, "0", "0", "Gotta\u{0020}check\u{0020}the\u{0020}mailbox.", "メールをチェックしよう。", "檢查下郵箱吧。", "0", "0", "0", "cv_izabera_41", "0", "0"},
[430841] = {430841, 13008, 44, 36, "0", "0", "Want\u{0020}to\u{0020}exchange\u{0020}some\u{0020}info?", "情報交換をするのか？", "要交流下情報嗎？", "0", "0", "0", "cv_izabera_42", "0", "0"},
[430842] = {430842, 13008, 45, 37, "0", "0", "I\u{0020}see.", "分かった。", "我明白了。", "0", "0", "0", "cv_izabera_43", "0", "0"},
[430900] = {430900, 13009, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_evatee_33", "0", "0"},
[430901] = {430901, 13009, 2, 2, "0", "0", "This\u{0020}is\u{0020}the\u{0020}first\u{0020}time\u{0020}I've\u{0020}ever\u{0020}held\u{0020}such\u{0020}an\u{0020}important\u{0020}position.", "0", "我還是第一次擔任這麼重要的職務。", "0", "我还是第一次担任这么重要的职务。", "0", "cv_evatee_2", "0", "0"},
[430902] = {430902, 13009, 3, 3, "0", "0", "Aevati,\u{0020}the\u{0020}Midyr\u{0020}interstellar\u{0020}traveler\u{0020}across\u{0020}time\u{0020}and\u{0020}space.\u{0020}Nice\u{0020}to\u{0020}meet\u{0020}you.", "0", "艾伊瓦蒂，跨越時空的米狄爾星際旅行者，能與您相見甚是榮幸。", "0", "艾伊瓦蒂，跨越时空的米狄尔星际旅行者，能与您相见甚是荣幸。", "0", "cv_evatee_1", "0", "0"},
[430903] = {430903, 13009, 4, 4, "0", "idle", "This\u{0020}planet's\u{0020}civilization...\u{0020}it's\u{0020}so\u{0020}different\u{0020}from\u{0020}Midyr's.\u{0020}Seeing\u{0020}it\u{0020}with\u{0020}my\u{0020}own\u{0020}eyes\u{0020}makes\u{0020}it\u{0020}even\u{0020}more\u{0020}striking.", "0", "這顆星球的文明……和米狄爾的文明完全不一樣呢。親眼見識過後，我更是這麼覺得。", "0", "这颗星球的文明……和米狄尔的文明完全不一样呢。亲眼见识过后，我更是这么觉得。", "0", "cv_evatee_3", "0", "0"},
[430904] = {430904, 13009, 5, 4, "0", "idle", "Day\u{0020}and\u{0020}night\u{0020}feel\u{0020}so\u{0020}different\u{0020}here.\u{0020}Back\u{0020}in\u{0020}the\u{0020}dark\u{0020}void\u{0020}of\u{0020}space,\u{0020}I\u{0020}never\u{0020}noticed.", "0", "白天和晚上給人的感覺很不一樣呢。以前的我總是身處一片漆黑的宇宙…完全沒法察覺。", "0", "白天和晚上给人的感觉很不一样呢。以前的我总是身处一片漆黑的宇宙…完全没法察觉。", "0", "cv_evatee_4", "0", "0"},
[430905] = {430905, 13009, 6, 4, "0", "idle", "If\u{0020}there's\u{0020}a\u{0020}chance,\u{0020}I'd\u{0020}like\u{0020}to\u{0020}restore\u{0020}the\u{0020}Shumia.", "0", "如果有機會的話，真想把修米婭號也給復原出來。", "0", "如果有机会的话，真想把修米娅号也给复原出来。", "0", "cv_evatee_30", "0", "0"},
[430906] = {430906, 13009, 7, 5, "1_》_0_0.8", "level1", "Flovira\u{0020}is\u{0020}my\u{0020}best\u{0020}friend.\u{0020}It's\u{0020}delightful\u{0020}watching\u{0020}her\u{0020}enjoy\u{0020}the\u{0020}food\u{0020}I\u{0020}make.", "0", "弗洛維拉是我最要好的朋友，看著她一臉幸福地吃著我做出來的食物，真是開心啊。", "0", "弗洛维拉是我最要好的朋友，看着她一脸幸福地吃着我做出来的食物，真是开心啊。", "0", "cv_evatee_31", "0", "0"},
[430907] = {430907, 13009, 8, 5, "1_》_0_0.8", "level1", "I'm\u{0020}here,\u{0020}Navigator\u{0020}of\u{0020}Earth.", "0", "嗯，我就在這裡，地球的領航。", "0", "嗯，我就在这里，地球的领航。", "0", "cv_evatee_5", "0", "0"},
[430908] = {430908, 13009, 9, 5, "1_》_100_1.5", "level2", "Want\u{0020}to\u{0020}know\u{0020}about\u{0020}the\u{0020}food\u{0020}on\u{0020}the\u{0020}Shumia?\u{0020}It's\u{0020}quite\u{0020}rare.\u{0020}Usually,\u{0020}everyone\u{0020}is\u{0020}more\u{0020}interested\u{0020}in\u{0020}our\u{0020}travel\u{0020}experiences.\u{0020}This\u{0020}is\u{0020}the\u{0020}first\u{0020}time\u{0020}someone\u{0020}has\u{0020}come\u{0020}to\u{0020}inquire\u{0020}about\u{0020}what\u{0020}I'm\u{0020}best\u{0020}at.", "0", "想要瞭解修米婭號上的伙食？還真是少見啊，一般大家都對我們的旅行見聞更感興趣。還是第一次有人來打聽我最拿手的事情呢。", "0", "想要了解修米娅号上的伙食？还真是少见啊，一般大家都对我们的旅行见闻更感兴趣。还是第一次有人来打听我最拿手的事情呢。", "0", "cv_evatee_6", "0", "0"},
[430909] = {430909, 13009, 10, 5, "1_》_500_2", "level3", "Only\u{0020}through\u{0020}experience\u{0020}do\u{0020}you\u{0020}realize\u{0020}there's\u{0020}no\u{0020}paradise.\u{0020}Being\u{0020}consumed\u{0020}by\u{0020}darkness\u{0020}happens\u{0020}in\u{0020}an\u{0020}instant...\u{0020}but\u{0020}that's\u{0020}all\u{0020}in\u{0020}the\u{0020}past.\u{0020}Waking\u{0020}from\u{0020}that\u{0020}nightmare\u{0020}is\u{0020}enough.", "0", "只有親身經歷一次才會明白，這個世界上並不存在天堂。被黑暗吞沒也只是一瞬間的事……但是這些已經過去了，我能從那漫無邊際的噩夢中醒來已經足夠了。", "0", "只有亲身经历一次才会明白，这个世界上并不存在天堂。被黑暗吞没也只是一瞬间的事……但是这些已经过去了，我能从那漫无边际的噩梦中醒来已经足够了。", "0", "cv_evatee_7", "0", "0"},
[430910] = {430910, 13009, 11, 5, "1_》_1000_2.5", "level4", "We\u{0020}Midyr\u{0020}people\u{0020}travel\u{0020}through\u{0020}space\u{0020}for\u{0020}the\u{0020}sake\u{0020}of\u{0020}survival.\u{0020}But\u{0020}we\u{0020}don't\u{0020}stay\u{0020}adrift\u{0020}forever.\u{0020}In\u{0020}our\u{0020}culture,\u{0020}when\u{0020}we\u{0020}land,\u{0020}it\u{0020}means\u{0020}meeting\u{0020}the\u{0020}most\u{0020}important\u{0020}person\u{0020}in\u{0020}our\u{0020}life...", "0", "在宇宙中不斷旅行是我們米狄爾人的生存方式，但是這並不意味著我們不會停靠在某處。領航，在我們的文化中，當旅行者落地之時，便是與其生命中最重要的人邂逅之時……", "0", "在宇宙中不断旅行是我们米狄尔人的生存方式，但是这并不意味着我们不会停靠在某处。领航，在我们的文化中，当旅行者落地之时，便是与其生命中最重要的人邂逅之时……", "0", "cv_evatee_8", "0", "0"},
[430911] = {430911, 13009, 12, 6, "0", "0", "Thank\u{0020}you.", "0", "非常感謝。", "0", "非常感谢。", "0", "cv_evatee_9", "0", "0"},
[430912] = {430912, 13009, 13, 7, "0", "0", "What\u{0020}was\u{0020}that\u{0020}just\u{0020}now?", "0", "欸？剛剛的那個是什麼？", "0", "哎？刚刚的那个是什么？", "0", "cv_evatee_10", "0", "0"},
[430913] = {430913, 13009, 14, 8, "0", "0", "So\u{0020}there\u{0020}are\u{0020}forces\u{0020}on\u{0020}this\u{0020}planet\u{0020}we\u{0020}still\u{0020}don't\u{0020}understand...", "0", "原來如此，這顆星球上有著我們尚未理解的力量……", "0", "原来如此，这颗星球上有着我们尚未理解的力量……", "0", "cv_evatee_11", "0", "0"},
