[430925] = {430925, 13009, 27, 20, "0", "0", "This\u{0020}is\u{0020}the\u{0020}bathhouse?\u{0020}Didn't\u{0020}expect\u{0020}it\u{0020}to\u{0020}be\u{0020}so\u{0020}spacious.", "0", "這裡就是清洗身體的地方嗎？沒想到連這裡都這麼寬敞。", "0", "这里就是清洗身体的地方吗？没想到连这里都这么宽敞。", "0", "cv_evatee_23", "0", "0"},
[430926] = {430926, 13009, 28, 21, "0", "0", "There\u{0020}are\u{0020}showers\u{0020}on\u{0020}the\u{0020}Shumia,\u{0020}but\u{0020}they\u{0020}don't\u{0020}compare\u{0020}to\u{0020}this.", "0", "修米婭號上也有淋浴間，不過遠比不上這裡。", "0", "修米娅号上也有淋浴间，不过远比不上这里。", "0", "cv_evatee_24", "0", "0"},
[430927] = {430927, 13009, 29, 21, "0", "0", "It's\u{0020}been\u{0020}so\u{0020}long\u{0020}since\u{0020}I've\u{0020}had\u{0020}a\u{0020}hot\u{0020}bath...\u{0020}it's\u{0020}been\u{0020}so\u{0020}long...", "0", "好久都沒有洗過熱水澡了……真的是已經過了好久…好久……", "0", "好久都没有洗过热水澡了……真的是已经过了好久…好久……", "0", "cv_evatee_25", "0", "0"},
