[431000] = {431000, 13010, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響", "0", "0", "0", "cv_qu_1", "0", "0"},
[431001] = {431001, 13010, 2, 2, "0", "0", "This\u{0020}is\u{0020}strange...\u{0020}it's\u{0020}not\u{0020}within\u{0020}the\u{0020}scope\u{0020}of\u{0020}my\u{0020}mission,\u{0020}but...\u{0020}Oh\u{0020}well.", "……変ね。私の任務範囲じゃなさそうだけど。まあ、いいわ。", "真是奇怪啊，這可不在我的任務範圍，不過…這樣也好。", "0", "0", "0", "cv_qu_2", "0", "0"},
[431002] = {431002, 13010, 3, 3, "0", "0", "Are\u{0020}you\u{0020}the\u{0020}new\u{0020}Navigator?\u{0020}Please\u{0020}look\u{0020}after\u{0020}me.\u{0020}Whatever\u{0020}it\u{0020}is—battle,\u{0020}or\u{0020}just\u{0020}life—come\u{0020}to\u{0020}me.\u{0020}Oh,\u{0020}and\u{0020}were\u{0020}you\u{0020}shocked\u{0020}when\u{0020}you\u{0020}first\u{0020}saw\u{0020}us?", "新しいナビゲーター？これからよろしくね。戦闘でもそれ以外でも、困ったことがあれば力になるわ。……ねえ。私たちを初めて見て、驚いたかしら？", "新來的領航？今後就請多多關照了，無論是戰鬥還是生活的事都可以找我幫忙。話說，你看到我們時會嚇一跳嗎？", "0", "0", "0", "cv_qu_3", "0", "0"},
[431003] = {431003, 13010, 4, 4, "0", "idle", "The\u{0020}view\u{0020}here\u{0020}is\u{0020}grand.\u{0020}Nothing\u{0020}hiding\u{0020}in\u{0020}the\u{0020}shadows\u{0020}can\u{0020}escape.", "ここはよく見えるわね。影に潜もうと、隠れることはできないわ。", "這裏的視野很寬廣，那些藏在陰影中的事物都無處遁形。", "0", "0", "0", "cv_qu_4", "0", "0"},
[431004] = {431004, 13010, 5, 4, "0", "idle", "Every\u{0020}time\u{0020}I\u{0020}see\u{0020}you,\u{0020}Navigator,\u{0020}it\u{0020}brings\u{0020}a\u{0020}calm\u{0020}to\u{0020}my\u{0020}heart...", "ナビゲーターを見ると、なんだか心がとても落ち着く……", "每次看到領航，總感覺心裏特別平靜……", "0", "0", "0", "cv_qu_5", "0", "0"},
[431005] = {431005, 13010, 6, 4, "0", "idle", "Shirogane\u{0020}acts\u{0020}rashly\u{0020}sometimes,\u{0020}and\u{0020}Rou\u{0020}is\u{0020}still\u{0020}a\u{0020}kid,\u{0020}not\u{0020}suited\u{0020}to\u{0020}the\u{0020}battlefield\u{0020}yet...\u{0020}Until\u{0020}they\u{0020}grow,\u{0020}I'll\u{0020}protect\u{0020}them.", "銀は衝動的になりすぎるところがあるし、瓏は戦場に出るべきではない子供よ……あの子たちが成長するまでは、私が仲間を守る責任を負うわ。", "銀有時會太過衝動，而瓏不過還是個孩子，不能很好地適應戰場……在她們成長起來之前，我得肩負起保護同胞的責任。", "0", "0", "0", "cv_qu_6", "0", "0"},
[431006] = {431006, 13010, 7, 5, "1_》_0_0.8", "level1", "The\u{0020}Eta\u{0020}people\u{0020}are\u{0020}outsiders\u{0020}to\u{0020}humans.\u{0020}It's\u{0020}only\u{0020}because\u{0020}of\u{0020}the\u{0020}Sins\u{0020}we\u{0020}have\u{0020}peace.\u{0020}What\u{0020}happens\u{0020}when\u{0020}the\u{0020}Sins\u{0020}are\u{0020}gone?\u{0020}How\u{0020}will\u{0020}we\u{0020}get\u{0020}along?", "あなた達人間にとってエッタ人はよそ者よ。私たちの間に平和が保たれているのは、原罪に対抗するためだけど……いつか全ての原罪を滅ぼしたら、私たちはどう付き合えばいいの？", "埃塔人對你們人類來說是外來者，只是因為原罪才能保持我們之間的和平。如果有一天原罪被消滅了，我們該以什麼方式相處呢？", "0", "0", "0", "cv_qu_7", "0", "0"},
[431007] = {431007, 13010, 8, 5, "1_》_0_0.8", "level1", "One\u{0020}must\u{0020}hold\u{0020}back\u{0020}a\u{0020}little...\u{0020}I\u{0020}won't\u{0020}act\u{0020}like\u{0020}a\u{0020}puppy.", "やめて。私は犬じゃないのよ。", "請保持克制，我可不會像小狗一樣……", "0", "0", "0", "cv_qu_8", "0", "0"},
[431008] = {431008, 13010, 9, 5, "1_》_100_1.5", "level2", "I\u{0020}only\u{0020}hope\u{0020}my\u{0020}people\u{0020}can\u{0020}live\u{0020}peacefully,\u{0020}free\u{0020}from\u{0020}Sins\u{0020}and\u{0020}out\u{0020}of\u{0020}harm's\u{0020}way.", "私はただ、同胞がこれ以上原罪などに傷つけられることなく、平和に生きてほしいと願っているだけよ。", "我只希望我的同胞們能安穩地活下去，不再被原罪或者其他什麼東西傷害。", "0", "0", "0", "cv_qu_9", "0", "0"},
[431009] = {431009, 13010, 10, 5, "1_》_500_2", "level3", "Are\u{0020}you\u{0020}really\u{0020}that\u{0020}curious\u{0020}about\u{0020}my\u{0020}tail?\u{0020}Go\u{0020}ahead,\u{0020}feel\u{0020}free.\u{0020}It's\u{0020}a\u{0020}privilege\u{0020}only\u{0020}you,\u{0020}the\u{0020}Navigator,\u{0020}get.", "そんなに私のしっぽが気になるの？ふふっ。じゃあご自由にどうぞ。ナビゲーターだけの特権よ。", "這麼在意我的尾巴嗎？請隨意地撫摸吧，這是僅領航擁有的特權。", "0", "0", "0", "cv_qu_10", "0", "0"},
[431010] = {431010, 13010, 11, 5, "1_》_1000_2.5", "level4", "Last\u{0020}sync,\u{0020}I\u{0020}finally\u{0020}understood\u{0020}what\u{0020}you\u{0020}were\u{0020}trying\u{0020}to\u{0020}do,\u{0020}and\u{0020}you\u{0020}learned\u{0020}about\u{0020}my\u{0020}past—the\u{0020}parts\u{0020}I\u{0020}rarely\u{0020}share.\u{0020}So\u{0020}in\u{0020}AEGIS,\u{0020}you're\u{0020}the\u{0020}only\u{0020}one\u{0020}I\u{0020}truly\u{0020}trust.\u{0020}Only\u{0020}with\u{0020}you\u{0020}do\u{0020}I\u{0020}feel\u{0020}any\u{0020}real\u{0020}peace,\u{0020}Navigator.", "この前の通感覚で、私はナビゲーターの心を理解することができた。……そしてナビゲーターも、私の暗い過去を知ったのね。だから、アイギスで信頼できるのはナビゲーターだけ。あなたと一緒にいる時だけ、私は本当に安らげるの。", "在之前的通感中，我明白了領航的心意，領航也瞭解了我黑暗的過去。所以在艾吉斯中我能相信的只有你一個。只有和領航在一起，我才能真正感到安心。", "0", "0", "0", "cv_qu_11", "0", "0"},
[431011] = {431011, 13010, 12, 6, "0", "0", "Thanks\u{0020}for\u{0020}that.", "ありがとう。", "謝謝。", "0", "0", "0", "cv_qu_12", "0", "0"},
[431012] = {431012, 13010, 13, 7, "0", "0", "\u{0020}I'll\u{0020}do\u{0020}whatever\u{0020}it\u{0020}takes\u{0020}to\u{0020}grow\u{0020}stronger\u{0020}for\u{0020}those\u{0020}I\u{0020}care.", "同胞のために、もっと強くなりたい。", "如果是為了同胞們，我願意變強。", "0", "0", "0", "cv_qu_13", "0", "0"},
[431013] = {431013, 13010, 14, 8, "0", "0", "\"Awakening,\"\u{0020}huh?\u{0020}Makes\u{0020}me\u{0020}think\u{0020}of...\u{0020}before.\u{0020}Navigator,\u{0020}I\u{0020}made\u{0020}you\u{0020}a\u{0020}promise.\u{0020}I\u{0020}won't\u{0020}make\u{0020}the\u{0020}same\u{0020}mistake\u{0020}twice.\u{0020}Failing\u{0020}once\u{0020}was\u{0020}more\u{0020}than\u{0020}enough.", "覚醒、ね……昔を思い出すわ……ナビゲーター、約束するわ。私はもう同じ失敗を繰り返さない。苦汁をなめるのは一度で十分よ。", "“覺醒”嗎…這讓我想起了以前的事……領航，我和你約定好了，我不會再重蹈覆轍了。失敗的苦楚，對我來說品嘗一次就足夠了。", "0", "0", "0", "cv_qu_14", "0", "0"},
[431014] = {431014, 13010, 15, 9, "0", "0", "New\u{0020}skills\u{0020}are\u{0020}always\u{0020}worth\u{0020}picking\u{0020}up.", "新技ね。使いこなしてみせるわ。", "全新的技藝，值得學習。", "0", "0", "0", "cv_qu_15", "0", "0"},
[431015] = {431015, 13010, 16, 10, "0", "0", "I'll\u{0020}keep\u{0020}you\u{0020}safe.", "私があなた達を守ってみせる。", "我會保證你們的安全。", "0", "0", "0", "cv_qu_16", "0", "0"},
[431016] = {431016, 13010, 17, 11, "0", "0", "Just\u{0020}put\u{0020}your\u{0020}faith\u{0020}in\u{0020}them.", "信じて……いいのね。", "只要相信她們就好了。", "0", "0", "0", "cv_qu_17", "0", "0"},
[431017] = {431017, 13010, 18, 12, "0", "0", "Let\u{0020}me\u{0020}take\u{0020}care\u{0020}of\u{0020}the\u{0020}wounded.", "負傷者はこっちに！", "由我來治療傷患吧。", "0", "0", "0", "cv_qu_18", "0", "0"},
[431018] = {431018, 13010, 19, 13, "0", "0", "Next\u{0020}time,\u{0020}push\u{0020}harder.\u{0020}Let\u{0020}me\u{0020}check\u{0020}where\u{0020}you're\u{0020}hurt\u{0020}first.", "反省は後よ。早く傷を見せて。", "下一次再努力吧，先讓我看看哪里受傷了。", "0", "0", "0", "cv_qu_19", "0", "0"},
[431019] = {431019, 13010, 20, 14, "0", "0", "We\u{0020}save\u{0020}lives\u{0020}first,\u{0020}then\u{0020}look\u{0020}for\u{0020}our\u{0020}next\u{0020}shot.", "生き延びることが最優先よ。チャンスはまた来るわ。", "先保住性命，等待下一次機會。", "0", "0", "0", "cv_qu_20", "0", "0"},
[431020] = {431020, 13010, 23, 16, "0", "0", "Leave\u{0020}the\u{0020}healing\u{0020}to\u{0020}me.", "治療なら任せてちょうだい。", "治療的事就交給我吧。", "0", "0", "0", "cv_qu_21", "0", "0"},
[431021] = {431021, 13010, 26, 19, "0", "0", "Is\u{0020}this...\u{0020}really\u{0020}the\u{0020}end\u{0020}for\u{0020}me...?", "うう……ここまでなの……", "嗚…我到此為止了嗎……", "0", "0", "0", "cv_qu_22", "0", "0"},
