[431024] = {431024, 13010, 28, 21, "0", "0", "I\u{0020}wonder\u{0020}if\u{0020}this\u{0020}soap\u{0020}will\u{0020}ruin\u{0020}my\u{0020}fur.", "このボディーソープ、毛が痛まないかしら……", "不知道這個沐浴露會不會損傷毛髮。", "0", "0", "0", "cv_qu_25", "0", "0"},
