[431028] = {431028, 13010, 32, 24, "0", "0", "Maybe\u{0020}it\u{0020}was\u{0020}just\u{0020}a\u{0020}lucky\u{0020}guess?", "当てずっぽうだったりして。", "不會是蒙對的吧。", "0", "0", "0", "cv_qu_29", "0", "0"},
