[431033] = {431033, 13010, 37, 29, "0", "0", "Anyone\u{0020}need\u{0020}medical\u{0020}attention?", "ナビゲーターも大変ね。", "有傷員需要治療嗎？", "0", "0", "0", "cv_qu_34", "0", "0"},
[431034] = {431034, 13010, 38, 30, "0", "0", "Do\u{0020}we\u{0020}really\u{0020}need\u{0020}more\u{0020}recruits\u{0020}again?", "人手不足なの？", "又需要新人手了嗎？", "0", "0", "0", "cv_qu_35", "0", "0"},
[431035] = {431035, 13010, 39, 31, "0", "0", "Hope\u{0020}this\u{0020}boosts\u{0020}survival\u{0020}rates.", "これで生存率が上がったら嬉しいわ。", "希望這些能增加存活率。", "0", "0", "0", "cv_qu_36", "0", "0"},
[431036] = {431036, 13010, 40, 32, "0", "0", "Better\u{0020}stock\u{0020}up\u{0020}for\u{0020}next\u{0020}month.", "来月分も仕入れておこうかしら。", "下個月的物資現在就採購吧。", "0", "0", "0", "cv_qu_37", "0", "0"},
[431037] = {431037, 13010, 41, 33, "0", "0", "How\u{0020}do\u{0020}humans\u{0020}not\u{0020}freeze\u{0020}without\u{0020}fur?", "人間には毛皮がないけど、寒くないの？", "人類沒有皮毛不會冷嗎？", "0", "0", "0", "cv_qu_38", "0", "0"},
[431038] = {431038, 13010, 42, 34, "0", "0", "That's\u{0020}a\u{0020}pretty\u{0020}clever\u{0020}way\u{0020}to\u{0020}do\u{0020}it.", "面白いやり方ね。", "非常新奇的方式。", "0", "0", "0", "cv_qu_39", "0", "0"},
[431039] = {431039, 13010, 43, 35, "0", "0", "Take\u{0020}a\u{0020}look.", "メールをチェックして。", "查看一下吧。", "0", "0", "0", "cv_qu_40", "0", "0"},
[431040] = {431040, 13010, 44, 36, "0", "0", "The\u{0020}whole\u{0020}world's\u{0020}tuned\u{0020}in\u{0020}to\u{0020}us\u{0020}now.", "世界中に聞こえるわよ。", "全世界都能聽到。", "0", "0", "0", "cv_qu_41", "0", "0"},
[431041] = {431041, 13010, 45, 37, "0", "0", "Mhm.", "ふふ。", "嗯哼。", "0", "0", "0", "cv_qu_42", "0", "0"},
[431100] = {431100, 13011, 1, 1, "0", "0", "Haze\u{0020}reverb.", "ハツリバーブ", "蒼霧殘響", "0", "0", "0", "cv_meiliya_1", "0", "0"},
[431101] = {431101, 13011, 2, 2, "0", "0", "Putting\u{0020}on\u{0020}an\u{0020}act\u{0020}is\u{0020}child's\u{0020}play,\u{0020}and\u{0020}it's\u{0020}what\u{0020}I\u{0020}do\u{0020}best.", "猫を被るのは、得意ですよ。", "不就是裝模作樣，這種事我再擅長不過。", "0", "0", "0", "cv_meiliya_2", "0", "0"},
[431102] = {431102, 13011, 3, 3, "0", "0", "Greetings.\u{0020}I\u{0020}am\u{0020}Meria,\u{0020}a\u{0020}devout\u{0020}saintess\u{0020}of\u{0020}the\u{0020}Holy\u{0020}Church.\u{0020}May\u{0020}the\u{0020}ever-flowing\u{0020}water\u{0020}bless\u{0020}us...\u{0020}Hehe.\u{0020}Is\u{0020}that\u{0020}what\u{0020}you\u{0020}want\u{0020}to\u{0020}hear\u{0020}from\u{0020}me,\u{0020}Navigator?\u{0020}How\u{0020}perverse.", "初めまして、聖濯教会の敬虔な聖女、メリアです。永遠の水が、私たちに祝福をもたらしますように……ふふっ、ナビゲーターさんは、こういうセリフが聞きたかったのですか？ほんとう、変態ですね。", "您好，我是梅莉雅，聖濯教會的一名虔誠的聖女，願源遠流長之水為我們帶來祝福……呵呵，領航想聽到的就是這種台詞？真是變態呢。", "0", "0", "0", "cv_meiliya_3", "0", "0"},
[431103] = {431103, 13011, 4, 4, "0", "idle", "With\u{0020}this\u{0020}body,\u{0020}a\u{0020}single\u{0020}breath\u{0020}becomes\u{0020}a\u{0020}gust\u{0020}of\u{0020}wind,\u{0020}a\u{0020}sprinkle\u{0020}of\u{0020}water,\u{0020}a\u{0020}downpour.\u{0020}If\u{0020}the\u{0020}gods\u{0020}can\u{0020}manipulate\u{0020}creation\u{0020}so\u{0020}effortlessly,\u{0020}then\u{0020}I\u{0020}want\u{0020}to\u{0020}be\u{0020}one.", "息を吹けば風となり、水を撒けば雨となる。……そんな簡単に万物を扱うことができるのなら、私も神になりたいです。", "以此身軀吹口氣就成一陣風，灑杯水就是一場雨，如果神明如此簡單就能操控萬物，我也想當神。", "0", "0", "0", "cv_meiliya_4", "0", "0"},
[431104] = {431104, 13011, 5, 4, "0", "idle", "Navigator...\u{0020}have\u{0020}you\u{0020}drifted\u{0020}off\u{0020}already?\u{0020}How\u{0020}pathetically\u{0020}adult.\u{0020}While\u{0020}I\u{0020}may\u{0020}slack\u{0020}off\u{0020}on\u{0020}work,\u{0020}I\u{0020}at\u{0020}least\u{0020}have\u{0020}the\u{0020}decency\u{0020}to\u{0020}pretend\u{0020}otherwise.", "ナビゲーターさん……眠ってしまいましたか？まったく、ダメな大人ですね。私も仕事はしたくないですが、してるフリくらいはするというのに。", "領航……這就睡著了？真是個沒用的大人啊，雖然我對工作也漫不經心，但至少還是會裝一下的。", "0", "0", "0", "cv_meiliya_5", "0", "0"},
[431105] = {431105, 13011, 6, 4, "0", "idle", "My\u{0020}act\u{0020}works\u{0020}differently\u{0020}on\u{0020}everyone.\u{0020}Ophelia?\u{0020}Easiest\u{0020}ever.\u{0020}Kosgaard?\u{0020}Sharp\u{0020}as\u{0020}a\u{0020}tack.\u{0020}But\u{0020}Mira...\u{0020}she's\u{0020}the\u{0020}scary\u{0020}one.\u{0020}She\u{0020}sees\u{0020}right\u{0020}through\u{0020}me\u{0020}and\u{0020}just\u{0020}plays\u{0020}along.", "私の変装の効果は、人によって異なります。同じ部隊のメンバーなら、オフィーリアさんが一番騙しやすいですね。コースガードさんは鋭くて、一番怖いのはミーラさんでしょうか。見破っているのに、気付いていないようなフリをするんですよ。", "我的偽裝效果因人而異，就拿隊友來說，奧菲莉亞最易欺騙，珂斯嘉德則嗅覺靈敏，而最可怕的還是米菈，她能輕易看透我卻依舊佯裝無事。", "0", "0", "0", "cv_meiliya_6", "0", "0"},
[431106] = {431106, 13011, 7, 5, "1_》_0_0.8", "level1", "Fidgety,\u{0020}are\u{0020}we?\u{0020}Had\u{0020}anything\u{0020}to\u{0020}talk\u{0020}about\u{0020}with\u{0020}your\u{0020}saintess?\u{0020}Well\u{0020}then,\u{0020}lesson\u{0020}one\u{0020}on\u{0020}being\u{0020}happy:\u{0020}you've\u{0020}got\u{0020}to\u{0020}learn\u{0020}to\u{0020}lie,\u{0020}starting\u{0020}with\u{0020}yourself.", "そのおかしな手つき…さてはこの聖女に悩みを打ち明けたいのですね？では、幸せになる秘訣をお教えしましょう。まずは、自分の本心を隠すことです。", "小手這麼亂動，是有煩惱要向本聖女傾訴？那麼就讓我告訴你快樂的秘訣吧，首先的一步，當然是學會隱瞞本心啦。", "0", "0", "0", "cv_meiliya_7", "0", "0"},
[431107] = {431107, 13011, 8, 5, "1_》_0_0.8", "level1", "What?\u{0020}Your\u{0020}phone?\u{0020}Why\u{0020}are\u{0020}you\u{0020}asking\u{0020}me?\u{0020}I\u{0020}don't\u{0020}have\u{0020}a\u{0020}clue.\u{0020}But...\u{0020}if\u{0020}I\u{0020}just\u{0020}so\u{0020}happen\u{0020}to\u{0020}find\u{0020}it,\u{0020}maybe\u{0020}I'll\u{0020}pay\u{0020}a\u{0020}visit\u{0020}to\u{0020}return\u{0020}it.", "何でしょうか？ナビゲーターさんの携帯電話ですか？なぜ私に聞くのですか？見ていませんよ？まぁ……もし偶然見つけたら、今夜部屋に届けますね。", "幹什麼？你的手機？問我幹嘛，我可沒看見。不過嘛……之後要是碰巧找到了，今晚就去趟你的房間送還失物吧。", "0", "0", "0", "cv_meiliya_8", "0", "0"},
[431108] = {431108, 13011, 9, 5, "1_》_100_1.5", "level2", "I\u{0020}live\u{0020}for\u{0020}myself,\u{0020}while\u{0020}you,\u{0020}Navigator,\u{0020}have\u{0020}some\u{0020}grand\u{0020}purpose,\u{0020}don't\u{0020}you?\u{0020}I'd\u{0020}call\u{0020}you\u{0020}a\u{0020}hopeless\u{0020}idealist,\u{0020}but...\u{0020}if\u{0020}I'm\u{0020}included\u{0020}in\u{0020}your\u{0020}big\u{0020}plan,\u{0020}I\u{0020}might\u{0020}as\u{0020}well\u{0020}offer\u{0020}some\u{0020}encouragement.", "私は自分のためだけに生きているのです。ナビゲーターさんは、何か大きな目標とかあるのですか？理想主義もほどほどにと言いたいところですが、私もその大きな目標に含まれているのなら、応援してあげてもいいですよ。", "我只為自己而活，領航則有著更宏大的目標吧？雖然想說你太理想主義，但如果我也在那宏大目標中佔一部分，就還是為你鼓鼓勁好了~", "0", "0", "0", "cv_meiliya_9", "0", "0"},
[431109] = {431109, 13011, 10, 5, "1_》_500_2", "level3", "Want\u{0020}a\u{0020}sip\u{0020}from\u{0020}the\u{0020}Holy\u{0020}Grail\u{0020}too,\u{0020}Navigator?\u{0020}Don't\u{0020}get\u{0020}excited,\u{0020}it's\u{0020}just\u{0020}liquid\u{0020}Nimbus.\u{0020}Oh?\u{0020}Wait...\u{0020}could\u{0020}it\u{0020}be\u{0020}you're\u{0020}just\u{0020}trying\u{0020}to\u{0020}get\u{0020}an\u{0020}indirect\u{0020}kiss?", "聖杯の水を飲んでみたいのですか？まあ、何の変哲もない、ただの液体ニムビウスですよ。あ、もしかして本当の狙いは……間接キッス？", "領航也想嘗嘗聖杯中的水嗎？但這裡面只是液態尼姆比斯能，沒什麼特殊的。哦對了，難道你的真正目的是間接接吻？", "0", "0", "0", "cv_meiliya_10", "0", "0"},
[431110] = {431110, 13011, 11, 5, "1_》_1000_2.5", "level4", "What's\u{0020}left\u{0020}on\u{0020}you\u{0020}that's\u{0020}worth\u{0020}stealing?\u{0020}Your\u{0020}ideals?\u{0020}Too\u{0020}bright.\u{0020}Your\u{0020}courage?\u{0020}Too\u{0020}hot\u{0020}to\u{0020}handle.\u{0020}Honestly,\u{0020}the\u{0020}only\u{0020}thing\u{0020}that\u{0020}seems\u{0020}appealing\u{0020}is\u{0020}your\u{0020}entire\u{0020}life.", "あなたは盗む価値のあるような物を持っていますか？…信念？それは眩しすぎますね。勇気？それは熱すぎます。…考えてみれば、私が欲しいものは、あなたの人生だけかもしれませんね。", "在你身上還有什麼寶物值得讓我竊取呢？理念？那種東西太過耀眼。勇氣？那又炙熱到難以忍受。想來想去，還是只有你的人生讓我不禁垂涎呢。", "0", "0", "0", "cv_meiliya_11", "0", "0"},
[431111] = {431111, 13011, 12, 6, "0", "0", "Can\u{0020}we\u{0020}just\u{0020}pretend\u{0020}I'm\u{0020}not\u{0020}here?", "私をいないものとして扱ってもらえませんか？", "就不能當沒我這號人？", "0", "0", "0", "cv_meiliya_12", "0", "0"},
[431112] = {431112, 13011, 13, 7, "0", "0", "A\u{0020}raise\u{0020}in\u{0020}my\u{0020}paycheck\u{0020}would\u{0020}be\u{0020}better.", "お給料も上がると良いですね。", "要是薪水也能增加就好了。", "0", "0", "0", "cv_meiliya_13", "0", "0"},
[431113] = {431113, 13011, 14, 8, "0", "0", "They\u{0020}say\u{0020}\"More\u{0020}power,\u{0020}more\u{0020}responsibility.\"\u{0020}Why\u{0020}are\u{0020}you\u{0020}so\u{0020}eager\u{0020}to\u{0020}dump\u{0020}more\u{0020}on\u{0020}me?\u{0020}If\u{0020}I\u{0020}keep\u{0020}slacking,\u{0020}I'll\u{0020}just\u{0020}look\u{0020}like\u{0020}I'm\u{0020}disappointing\u{0020}you.\u{0020}So\u{0020}annoying.", "能力が上がると、責任も重くなるとよく言われますが、なぜ私に大きな責任を背負わせようとするのですか？このまま逃げ続けてしまったら、あなたの期待を裏切ったように見えるではないですか…まったく。", "總說能力增長伴隨責任增加，為什麼一定要我承擔更大的責任才滿意？要是我繼續擺爛下去，不就顯得像辜負了你的期待嗎，真是的。", "0", "0", "0", "cv_meiliya_14", "0", "0"},
[431114] = {431114, 13011, 15, 9, "0", "0", "Studying\u{0020}is\u{0020}the\u{0020}worst.", "勉強はいやです。", "學習好痛苦。", "0", "0", "0", "cv_meiliya_15", "0", "0"},
