[431839] = {431839, 13018, 43, 35, "0", "0", "Such\u{0020}an\u{0020}old-fashioned\u{0020}way\u{0020}to\u{0020}communicate...\u{0020}Sorry,\u{0020}didn't\u{0020}mean\u{0020}it\u{0020}like\u{0020}that.", "0", "好老土的通訊方式……對不起，我不是那個意思。", "0", "0", "0", "cv_mittshiva_40", "0", "0"},
[431840] = {431840, 13018, 44, 36, "0", "0", "I...\u{0020}I...\u{0020}You...\u{0020}You...", "0", "我……我……你……你……", "0", "0", "0", "cv_mittshiva_41", "0", "0"},
[431841] = {431841, 13018, 45, 37, "0", "0", "It's\u{0020}okay\u{0020}to\u{0020}touch\u{0020}it\u{0020}once,\u{0020}right?", "0", "碰一下不要緊吧？", "0", "0", "0", "cv_mittshiva_42", "0", "0"},
[431900] = {431900, 13019, 1, 1, "0", "0", "Haze\u{0020}reverb.", "ハツリバーブ。", "蒼霧殘響", "0", "0", "0", "cv_zhaowu_1", "0", "0"},
[431901] = {431901, 13019, 2, 2, "0", "0", "Is\u{0020}it\u{0020}really\u{0020}okay\u{0020}for\u{0020}a\u{0020}sinner\u{0020}like\u{0020}me\u{0020}to\u{0020}stand\u{0020}here...?", "本当に良いのでしょうか……わたくしのような罪深い者がここにいて……", "這樣真的好嗎……讓我這樣的罪人站在這裏……", "0", "0", "0", "cv_zhaowu_2", "0", "0"},
[431902] = {431902, 13019, 3, 3, "0", "0", "Nice\u{0020}to\u{0020}meet\u{0020}you.\u{0020}I'm\u{0020}from\u{0020}the\u{0020}Academy\u{0020}of\u{0020}Learning...\u{0020}Ah,\u{0020}no,\u{0020}it's\u{0020}called\u{0020}PingXin\u{0020}now.\u{0020}I'm\u{0020}Zhaowu\u{0020}from\u{0020}PingXin.\u{0020}I...\u{0020}I'm\u{0020}not\u{0020}that\u{0020}gifted,\u{0020}but\u{0020}I'll\u{0020}do\u{0020}everything\u{0020}I\u{0020}can\u{0020}to\u{0020}support\u{0020}you,\u{0020}Navigator.", "初めてお目にかかります。学宮（がっきゅう）……あ、いえ。今は平心社（へいしんしゃ）の朝霧（ちょうむ）と申します。ふ、不束者ですが、全身全霊でナビゲーターをお支えします。", "初次見面，我是來自“學宮”的……啊，不，現在應該叫平心社了……我是平心社的朝霧，小……小女子不才，我……我會全心全意支援領航的。", "0", "0", "0", "cv_zhaowu_3", "0", "0"},
[431903] = {431903, 13019, 4, 4, "0", "idle", "The\u{0020}Academy\u{0020}of\u{0020}Learning...\u{0020}It's\u{0020}where\u{0020}I\u{0020}grew\u{0020}up—a\u{0020}place\u{0020}to\u{0020}read\u{0020}and\u{0020}find\u{0020}peace.\u{0020}But\u{0020}I\u{0020}don't\u{0020}need\u{0020}to\u{0020}go\u{0020}back.\u{0020}It's\u{0020}alright...\u{0020}I\u{0020}chose\u{0020}to\u{0020}leave.\u{0020}I\u{0020}came\u{0020}for\u{0020}you,\u{0020}Navigator,\u{0020}and\u{0020}for\u{0020}myself.", "学宮……わたくしが生まれ育ち、心静かに学ぶことができた場所。……でももう帰ることはありません。……わたくし自身のために、そしてナビゲーターのために……自分で決断したのです。", "“學宮”……是我出身、長大的地方，一個能讓人能靜下心來讀書的地方……但是我現在已經不用回去了。沒事的……是我自己決定出來的，我是為了領航，也是為了我自己而來的。", "0", "0", "0", "cv_zhaowu_4", "0", "0"},
[431904] = {431904, 13019, 5, 4, "0", "idle", "I\u{0020}believe\u{0020}you're\u{0020}the\u{0020}one\u{0020}we've\u{0020}been\u{0020}waiting\u{0020}for.\u{0020}My\u{0020}purpose\u{0020}with\u{0020}PingXin\u{0020}was\u{0020}fulfilled\u{0020}the\u{0020}moment\u{0020}I\u{0020}met\u{0020}you.\u{0020}Now,\u{0020}all\u{0020}I\u{0020}want\u{0020}is\u{0020}to\u{0020}stay\u{0020}by\u{0020}your\u{0020}side.", "わたくし達が待ち望んでいたのはきっと……ナビゲーターです。平心社の目的と使命は、あなたと出会った瞬間に達成されました。これからは、あなたの傍にいるだけで良いのです。", "我覺得……領航就是我們一直在等待的人。我們“平心社”的責任，我的目標在遇見領航的時候就已經完成了，接下來只需要陪伴著您就好了。", "0", "0", "0", "cv_zhaowu_5", "0", "0"},
[431905] = {431905, 13019, 6, 4, "0", "idle", "To\u{0020}me,\u{0020}your\u{0020}existence\u{0020}is\u{0020}more\u{0020}important\u{0020}than\u{0020}anyone\u{0020}else's.\u{0020}So,\u{0020}in\u{0020}dangerous\u{0020}times,\u{0020}don't\u{0020}hesitate\u{0020}to\u{0020}use\u{0020}me.\u{0020}After\u{0020}everything\u{0020}I've\u{0020}experienced\u{0020}with\u{0020}you,\u{0020}I'm\u{0020}already\u{0020}content.", "ナビゲーターは誰よりも重要な存在です。危険な時は迷わずわたくしを盾にしてください。あなたと多くの時間を共有することができて、わたくしはもう十分満足です。", "我認為領航的存在比任何人都重要——所以在危險的時候，請毫不留情地使用我吧，能和您經歷過這麼多事情，我已經很滿足了。", "0", "0", "0", "cv_zhaowu_6", "0", "0"},
[431906] = {431906, 13019, 7, 5, "1_》_0_0.8", "level1", "Navigator,\u{0020}please\u{0020}don't...\u{0020}touch\u{0020}a\u{0020}sinner\u{0020}like\u{0020}me.", "ナビゲーター……どうかこの咎人に触れないでください。", "領航，請不要……碰觸我這個戴罪之人。", "0", "0", "0", "cv_zhaowu_7", "0", "0"},
[431907] = {431907, 13019, 8, 5, "1_》_0_0.8", "level1", "There\u{0020}are\u{0020}far\u{0020}more\u{0020}worthy\u{0020}people\u{0020}to\u{0020}support\u{0020}you.\u{0020}So\u{0020}why\u{0020}do\u{0020}you\u{0020}stay\u{0020}by\u{0020}my\u{0020}side...?", "わたくしよりも、傍にいるべきドライバーがいるはずです。なのにどうして……？", "有更值得您去陪伴的駕駛員，領航，為什麼要呆在我身邊呢。", "0", "0", "0", "cv_zhaowu_8", "0", "0"},
[431908] = {431908, 13019, 9, 5, "1_》_100_1.5", "level2", "I\u{0020}was\u{0020}born\u{0020}a\u{0020}sinner,\u{0020}yet\u{0020}you\u{0020}trust\u{0020}me.\u{0020}You\u{0020}let\u{0020}me\u{0020}stand\u{0020}beside\u{0020}you...\u{0020}and\u{0020}somehow,\u{0020}it\u{0020}brings\u{0020}me\u{0020}peace.", "咎人としてこの世に生を受けたわたくしを信じてくださって、ありがとうございます。あなたの隣はなぜか……心が安らぐのです。", "我是作為罪人降生在這個世界上的，但是謝謝您能相信我。您允許我站在您的身邊，不知道為什麼……讓我感到放鬆。", "0", "0", "0", "cv_zhaowu_9", "0", "0"},
[431909] = {431909, 13019, 10, 5, "1_》_500_2", "level3", "What\u{0020}mistakes\u{0020}have\u{0020}I\u{0020}made?\u{0020}Don't\u{0020}worry\u{0020}about\u{0020}that.\u{0020}Every\u{0020}day\u{0020}spent\u{0020}by\u{0020}your\u{0020}side\u{0020}is\u{0020}my\u{0020}way\u{0020}of\u{0020}atoning.\u{0020}But\u{0020}I'm\u{0020}not\u{0020}here\u{0020}for\u{0020}atonement.\u{0020}I'm\u{0020}here\u{0020}because\u{0020}I\u{0020}hope,\u{0020}I\u{0020}want...\u{0020}I\u{0020}long\u{0020}for\u{0020}you.", "わたくしが犯した罪、ですか……どうか、お気になさらないでください。あなたのそばにいる毎日が償いの日々ですが……罪滅ぼしのためにあなたの傍にいるのではありません。わたくしが……わたくしがあなたに憧れているからです。", "我犯下了什麼過錯……您無需擔心，相伴在您身邊的每一天，便是在贖罪的每一天，但是——我希望您知道，我並不是為了贖罪待在您身邊的，而是我希望，我想要……我憧憬著您。", "0", "0", "0", "cv_zhaowu_10", "0", "0"},
[431910] = {431910, 13019, 11, 5, "1_》_1000_2.5", "level4", "Navigator...\u{0020}Navigator...", "ナビゲーター……ナビゲーター……", "領航……領航……", "0", "0", "0", "cv_zhaowu_11", "0", "0"},
[431911] = {431911, 13019, 12, 6, "0", "0", "Huh,\u{0020}is\u{0020}this...\u{0020}for\u{0020}me?", "こ…これをわたくしに……？", "呼，這……這是給我的嗎？", "0", "0", "0", "cv_zhaowu_12", "0", "0"},
[431912] = {431912, 13019, 13, 7, "0", "0", "Even\u{0020}though\u{0020}I've\u{0020}grown\u{0020}used\u{0020}to\u{0020}it,\u{0020}I\u{0020}can\u{0020}still\u{0020}feel\u{0020}the\u{0020}depth\u{0020}of\u{0020}your\u{0020}care.", "あなたにとっては当たり前のことかもしれませんが、わたくしは真心を感じています。", "就算您習以為常，我依然能感受到其中真實的心意。", "0", "0", "0", "cv_zhaowu_13", "0", "0"},
[431913] = {431913, 13019, 14, 8, "0", "0", "Huh...\u{0020}Huh...\u{0020}Huh...\u{0020}I\u{0020}did\u{0020}it.\u{0020}I...\u{0020}feel\u{0020}better\u{0020}now,\u{0020}so\u{0020}relieved.", "はぁ、はぁ……成し遂げました。いま……とっても、ホッとしています。", "呼……呼……呼……我做到了，我……現在感覺很好，很安心。", "0", "0", "0", "cv_zhaowu_14", "0", "0"},
[431914] = {431914, 13019, 15, 9, "0", "0", "All\u{0020}of\u{0020}my\u{0020}strength...\u{0020}it's\u{0020}yours\u{0020}to\u{0020}use.", "わたくしの力すべてを……あなたに捧げます。", "我的力量，全部都……為您所用。", "0", "0", "0", "cv_zhaowu_15", "0", "0"},
[431915] = {431915, 13019, 16, 10, "0", "0", "\"Heavenly\u{0020}Physician\"\u{0020}Zhaowu,\u{0020}from\u{0020}PingXin,\u{0020}arriving\u{0020}on\u{0020}the\u{0020}battlefield.", "平心社の天医（てんい）、朝霧。ここにあり。", "平心社，“天醫”朝霧，抵達戰場。", "0", "0", "0", "cv_zhaowu_16", "0", "0"},
[431916] = {431916, 13019, 17, 11, "0", "0", "It's\u{0020}a\u{0020}success...\u{0020}Did\u{0020}you\u{0020}see\u{0020}that,\u{0020}Navigator!", "やりました……見ていただけましたか、ナビゲーター！", "成功了……你看到了嗎，領航！", "0", "0", "0", "cv_zhaowu_17", "0", "0"},
[431917] = {431917, 13019, 18, 12, "0", "0", "If\u{0020}you're\u{0020}hurt,\u{0020}tell\u{0020}me\u{0020}right\u{0020}away.", "もし怪我をしたらすぐわたくしにおっしゃってください。", "如果有受傷一定要馬上和我講哦。", "0", "0", "0", "cv_zhaowu_18", "0", "0"},
[431918] = {431918, 13019, 19, 13, "0", "0", "If\u{0020}I\u{0020}don't\u{0020}join\u{0020}the\u{0020}battle...\u{0020}you'll\u{0020}probably\u{0020}win\u{0020}even\u{0020}bigger\u{0020}victories.", "わたくしさえいなければ……きっとナビゲーターは完璧な勝利を手にされていたはず……", "如果沒有我參戰……領航一定會獲得更完美的勝利吧。", "0", "0", "0", "cv_zhaowu_19", "0", "0"},
[431919] = {431919, 13019, 20, 14, "0", "0", "Woo...\u{0020}Navigator,\u{0020}you\u{0020}go\u{0020}ahead.\u{0020}I'll\u{0020}catch\u{0020}up\u{0020}soon.", "うぅ……ナビゲーター、早くお逃げください……わたくしが背中をお守りします。", "嗚……領航……您先走，我……隨後就到。", "0", "0", "0", "cv_zhaowu_20", "0", "0"},
[431920] = {431920, 13019, 23, 16, "0", "0", "Are\u{0020}you\u{0020}hurt\u{0020}anywhere?", "どこを怪我されたんですか？", "哪里受傷了嗎？", "0", "0", "0", "cv_zhaowu_21", "0", "0"},
[431921] = {431921, 13019, 26, 19, "0", "0", "Let\u{0020}me...\u{0020}take\u{0020}a\u{0020}look\u{0020}at\u{0020}the\u{0020}wound.", "傷口をお見せください。", "讓我……看看傷口。", "0", "0", "0", "cv_zhaowu_22", "0", "0"},
[431922] = {431922, 13019, 25, 18, "0", "0", "I\u{0020}will\u{0020}repay\u{0020}my\u{0020}sin\u{0020}as\u{0020}a\u{0020}\"Heavenly\u{0020}Physician\"\u{0020}here.\u{0020}I\u{0020}won't\u{0020}let\u{0020}you\u{0020}harm\u{0020}anyone\u{0020}again.", "「天医」即ち「人の罪」。これがその償い。二度と仲間を傷つけさせません。", "我要在這裏償還我身為“天醫”的人之罪，我不會再讓你們傷害到大家的。", "0", "0", "0", "cv_zhaowu_23", "0", "0"},
[431923] = {431923, 13019, 24, 17, "0", "0", "Have\u{0020}I\u{0020}atoned\u{0020}for\u{0020}this\u{0020}sin?", "罪を償えたでしょうか……", "這份罪責，我還清了嗎……？", "0", "0", "0", "cv_zhaowu_24", "0", "0"},
[431924] = {431924, 13019, 27, 20, "0", "0", "Ah...\u{0020}If\u{0020}you\u{0020}don't\u{0020}mind...", "あ……もし……あなたさえ良ければ……", "啊……如果您不嫌棄的話……", "0", "0", "0", "cv_zhaowu_25", "0", "0"},
[431925] = {431925, 13019, 28, 21, "0", "0", "Before\u{0020}we\u{0020}begin,\u{0020}please\u{0020}wear\u{0020}your\u{0020}protective\u{0020}gear.\u{0020}I\u{0020}want\u{0020}to\u{0020}make\u{0020}sure\u{0020}you\u{0020}stay\u{0020}safe.", "最初に防具を着用し、ご自分の体をお守りください……", "在開始之前，請戴好護具，保護好自己……", "0", "0", "0", "cv_zhaowu_26", "0", "0"},
[431926] = {431926, 13019, 29, 21, "0", "0", "Is\u{0020}it\u{0020}not\u{0020}time\u{0020}yet?\u{0020}That's\u{0020}fine.\u{0020}I'll\u{0020}hold\u{0020}out\u{0020}until\u{0020}you're\u{0020}ready.", "まだ始まらないんですね……大丈夫です。準備が整うまでお待ちします。", "還沒有開始嗎……沒關係，在您做好準備之前，我會一直忍耐的。", "0", "0", "0", "cv_zhaowu_27", "0", "0"},
[431927] = {431927, 13019, 30, 22, "0", "0", "Do\u{0020}you\u{0020}need\u{0020}help?\u{0020}I\u{0020}may\u{0020}not\u{0020}be\u{0020}much\u{0020}use,\u{0020}though...", "お手伝いいたしましょうか……何の役にも立たないかもしれませんが……", "需要我來幫您一起嗎……雖然我可能……起不到什麼作用。", "0", "0", "0", "cv_zhaowu_28", "0", "0"},
[431928] = {431928, 13019, 31, 23, "0", "0", "Navigator...\u{0020}you...\u{0020}still\u{0020}remember\u{0020}me?", "ナビゲーター……わたくしのこと、覚えていらっしゃいますよね？", "領航……您……還記得我？", "0", "0", "0", "cv_zhaowu_29", "0", "0"},
[431929] = {431929, 13019, 32, 24, "0", "0", "Huh...\u{0020}Thank\u{0020}you.", "ふぅ……ありがとうございます。", "呼……謝謝您。", "0", "0", "0", "cv_zhaowu_30", "0", "0"},
[431930] = {431930, 13019, 33, 25, "0", "0", "I\u{0020}suppose\u{0020}this\u{0020}was\u{0020}inevitable...\u{0020}After\u{0020}all,\u{0020}it's\u{0020}me.", "当然でしょうね……わたくしですから……", "這也是沒辦法的事情……畢竟是我啊……", "0", "0", "0", "cv_zhaowu_31", "0", "0"},
[431931] = {431931, 13019, 34, 26, "0", "0", "It\u{0020}feels\u{0020}so\u{0020}comforting,\u{0020}like\u{0020}I'm\u{0020}back\u{0020}at\u{0020}the\u{0020}academy.", "なんだか安心します……まるで学宮に帰ったみたいに……", "安心……像是回到了學宮一樣。", "0", "0", "0", "cv_zhaowu_32", "0", "0"},
[431932] = {431932, 13019, 35, 27, "0", "0", "It's\u{0020}time\u{0020}to\u{0020}hit\u{0020}the\u{0020}battlefield...", "戦場ですね……お任せください。", "要上戰場了……", "0", "0", "0", "cv_zhaowu_33", "0", "0"},
[431933] = {431933, 13019, 36, 28, "0", "0", "Even\u{0020}drills\u{0020}can\u{0020}lead\u{0020}to\u{0020}injuries...", "演習でも負傷者が出るかもしれませんね……", "演習也會出現傷患……", "0", "0", "0", "cv_zhaowu_34", "0", "0"},
[431934] = {431934, 13019, 37, 29, "0", "0", "Everyone's\u{0020}okay.\u{0020}That's\u{0020}a\u{0020}relief.", "皆さんお元気で、何よりです。", "大家都好好的，真好呀。", "0", "0", "0", "cv_zhaowu_35", "0", "0"},
[431935] = {431935, 13019, 38, 30, "0", "0", "Are\u{0020}you\u{0020}searching\u{0020}for\u{0020}a\u{0020}new\u{0020}companion?", "新しいパートナーを探しに行くんですか？", "您要去找新的陪伴者了嗎……", "0", "0", "0", "cv_zhaowu_36", "0", "0"},
[431936] = {431936, 13019, 39, 31, "0", "0", "Be\u{0020}sure\u{0020}to\u{0020}dress\u{0020}nicely\u{0020}when\u{0020}you\u{0020}head\u{0020}out.", "外出する際は、身なりを整えないと。", "出門要穿戴整齊哦。", "0", "0", "0", "cv_zhaowu_37", "0", "0"},
[431937] = {431937, 13019, 40, 32, "0", "0", "Can\u{0020}I\u{0020}get\u{0020}a\u{0020}book?", "本を……本を買いたいです……", "……我……我想要買本書可以嗎？", "0", "0", "0", "cv_zhaowu_38", "0", "0"},
[431938] = {431938, 13019, 41, 33, "0", "0", "Your\u{0020}photo's\u{0020}in\u{0020}the\u{0020}file.", "あなたの写真がありますね。", "檔案上有您的照片。", "0", "0", "0", "cv_zhaowu_39", "0", "0"},
[431939] = {431939, 13019, 42, 34, "0", "0", "This\u{0020}is\u{0020}where\u{0020}the\u{0020}settings\u{0020}are\u{0020}adjusted...", "セッティングを調整できます。", "這裏是調整設置的地方。", "0", "0", "0", "cv_zhaowu_40", "0", "0"},
[431940] = {431940, 13019, 43, 35, "0", "0", "Will\u{0020}there\u{0020}be\u{0020}a\u{0020}new\u{0020}letter?", "新しいメールは来ているでしょうか？", "會有新的來信嗎？", "0", "0", "0", "cv_zhaowu_41", "0", "0"},
[431941] = {431941, 13019, 44, 36, "0", "0", "The\u{0020}Navigator's\u{0020}chat...\u{0020}Could\u{0020}I...\u{0020}see\u{0020}it\u{0020}too?", "ナビゲーターのチャット……わ、わたくしも拝見していいでしょうか？", "領航的聊天……我……我也被允許一起看嗎？", "0", "0", "0", "cv_zhaowu_42", "0", "0"},
[431942] = {431942, 13019, 45, 37, "0", "0", "Huh—", "ふぅ……", "呼——", "0", "0", "0", "cv_zhaowu_43", "0", "0"},
[432000] = {432000, 13020, 1, 1, "0", "0", "Haze\u{0020}reverb.", "ハツ…ふぁ～（あくび）…リバーブ", "蒼霧殘響", "0", "0", "0", "cv_mayball_1", "0", "0"},
[432001] = {432001, 13020, 2, 2, "0", "0", "Are\u{0020}you\u{0020}sure\u{0020}it's\u{0020}up\u{0020}to\u{0020}me?\u{0020}Just\u{0020}a\u{0020}heads-up,\u{0020}I\u{0020}can't\u{0020}promise\u{0020}I'll\u{0020}be\u{0020}much\u{0020}help.", "私に任せるの？あんまり、期待しないでね。", "確定交由我嗎？事先說好，不保證能勝任哦。", "0", "0", "0", "cv_mayball_2", "0", "0"},
[432002] = {432002, 13020, 3, 3, "0", "0", "This\u{0020}is\u{0020}Maybelle\u{0020}Ise,\u{0020}philosophy\u{0020}teacher\u{0020}at\u{0020}Sahara\u{0020}Azure\u{0020}Academy,\u{0020}part\u{0020}of\u{0020}the\u{0020}Honey\u{0020}Makers.\u{0020}Um,\u{0020}that's\u{0020}probably\u{0020}all\u{0020}you\u{0020}need\u{0020}to\u{0020}know...", "私はメイベル・イース。サハラの「ファーマメントアカデミー」で哲学の授業担当。ハニーメイカーに所属。これぐらいかな……。", "這裏是梅貝爾·伊司，薩哈拉蒼穹學院的一名哲學教師，隸屬於制蜜人小隊。唔，介紹應該就這些了……", "0", "0", "0", "cv_mayball_3", "0", "0"},
[432003] = {432003, 13020, 4, 4, "0", "idle", "Let's\u{0020}unwind\u{0020}after\u{0020}work.\u{0020}Coffee\u{0020}shop,\u{0020}friends,\u{0020}good\u{0020}vibes—hahuu...\u{0020}the\u{0020}clash\u{0020}of\u{0020}ideas\u{0020}and\u{0020}peace\u{0020}of\u{0020}mind\u{0020}all\u{0020}in\u{0020}one.", "仕事が終わったら、友達とカフェで会って、リラックスして、静かな時間と良い香り、そして…ふぁ～、思想のぶつかり合いを楽しむの。", "等工作完就放鬆下吧，去咖啡館會會朋友，享受靜謐、芬芳，以及……哈嗚~思想的碰撞。", "0", "0", "0", "cv_mayball_4", "0", "0"},
[432004] = {432004, 13020, 5, 4, "0", "idle", "I'm\u{0020}not\u{0020}exactly\u{0020}popular\u{0020}with\u{0020}the\u{0020}students—laid-back\u{0020}and\u{0020}all\u{0020}that.\u{0020}Still,\u{0020}even\u{0020}a\u{0020}bad\u{0020}example\u{0020}can\u{0020}be\u{0020}a\u{0020}lesson,\u{0020}right?", "のんびりしてる私は、一部の生徒からあまり良く思われてないみたい。でも教師としては成功かな…反面教師としてだけど。", "我這悠閒散漫的樣子不太受一些學生歡迎，雖說作為教師有些失敗，但反面教材也算教嘛~", "0", "0", "0", "cv_mayball_5", "0", "0"},
[432005] = {432005, 13020, 6, 4, "0", "idle", "Precio\u{0020}and\u{0020}Mojun\u{0020}are\u{0020}workhorses.\u{0020}I'm\u{0020}lucky\u{0020}to\u{0020}have\u{0020}them\u{0020}around.\u{0020}Stella's\u{0020}like\u{0020}a\u{0020}walking\u{0020}balm.\u{0020}Want\u{0020}to\u{0020}give\u{0020}her\u{0020}style\u{0020}a\u{0020}try,\u{0020}Navigator?", "プレシオと墨君（ぼくくん）は仕事狂いだから、彼女たちがいるとチームはかなり楽になる。ステラは……柔らかくて癒されるの、ナビゲーターくんも試してみない？", "普瑞席歐和墨君都是工作狂，小隊有她們真讓人輕鬆不少。至於斯緹菈，軟乎乎的非常治癒呢，領航同學也要試試嗎？", "0", "0", "0", "cv_mayball_6", "0", "0"},
[432006] = {432006, 13020, 7, 5, "1_》_0_0.8", "level1", "Existence\u{0020}is\u{0020}emptiness,\u{0020}right?\u{0020}So,\u{0020}what's\u{0020}it\u{0020}all\u{0020}about?\u{0020}Can\u{0020}nothingness\u{0020}ever\u{0020}be\u{0020}filled?", "存在は虚無であるが故に、意味を探し続ける。虚無を埋めることは出来るのかな？", "存在即虛無，因此，存在才會不斷探尋意義……但虛無真的能被填滿嗎？", "0", "0", "0", "cv_mayball_7", "0", "0"},
[432007] = {432007, 13020, 8, 5, "1_》_0_0.8", "level1", "Do\u{0020}I\u{0020}seem\u{0020}sleepy?\u{0020}It's\u{0020}cool.\u{0020}Even\u{0020}if\u{0020}I\u{0020}nod\u{0020}off,\u{0020}this\u{0020}book\u{0020}doubles\u{0020}as\u{0020}a\u{0020}great\u{0020}pillow.", "少し疲れているように見える？心配しないで。うっかり寝てしまっても、この本がちょうど枕代わりになるから。", "我看起來有些困？請不用擔心，就算不小心睡著，手上的書正好能作為一個小枕頭。", "0", "0", "0", "cv_mayball_8", "0", "0"},
[432008] = {432008, 13020, 9, 5, "1_》_100_1.5", "level2", "Philosophy\u{0020}books...\u{0020}Some\u{0020}keep\u{0020}you\u{0020}thinking\u{0020}all\u{0020}night,\u{0020}others\u{0020}put\u{0020}you\u{0020}right\u{0020}to\u{0020}sleep.\u{0020}Which\u{0020}type\u{0020}do\u{0020}you\u{0020}go\u{0020}for,\u{0020}Navigator?", "哲学の本は難解で深遠。眠気が飛ぶものもあれば、眠りへ誘うものもある。ナビゲーターくんはどちらがお好み？", "哲學書艱深晦澀，有些能打消困倦，有些能使人安眠。領航同學喜歡哪種呢？", "0", "0", "0", "cv_mayball_9", "0", "0"},
[432009] = {432009, 13020, 10, 5, "1_》_500_2", "level3", "Feeling\u{0020}lost?\u{0020}That's\u{0020}just\u{0020}proof\u{0020}of\u{0020}life.\u{0020}\"Existence\u{0020}precedes\u{0020}essence,\"\u{0020}and\u{0020}that's\u{0020}not\u{0020}something\u{0020}to\u{0020}sweat.", "たまに迷いを感じることはある？心配しないで。迷いを感じることこそ「実存は本質に先立つ」ということの証明。悪いことではないよ。", "偶爾會感到迷茫嗎？沒關係，能夠迷茫正是“存在先於本質”的證明，這不是壞事。", "0", "0", "0", "cv_mayball_10", "0", "0"},
[432010] = {432010, 13020, 11, 5, "1_》_1000_2.5", "level4", "Navigator,\u{0020}think\u{0020}I\u{0020}could\u{0020}lean\u{0020}on\u{0020}you\u{0020}a\u{0020}little\u{0020}more?\u{0020}Like...\u{0020}when\u{0020}my\u{0020}narcolepsy\u{0020}kicks\u{0020}in,\u{0020}you'll\u{0020}be\u{0020}there,\u{0020}yeah?\u{0020}That\u{0020}kind\u{0020}of\u{0020}vibe.", "ナビゲーターくん、もっと君に頼ってもいいかな？…もし過眠症の発作が起きたとき、君が側にいてくれたらいいなって思って。", "領航同學，我可以更加依靠你一些嗎？比如……要是嗜睡症不小心發作，希望正好有你在我身邊……這種感覺？", "0", "0", "0", "cv_mayball_11", "0", "0"},
[432011] = {432011, 13020, 12, 6, "0", "0", "Hahuu...\u{0020}Thanks.", "ふぅ～、ありがとう。", "哈嗚~謝謝。", "0", "0", "0", "cv_mayball_12", "0", "0"},
[432012] = {432012, 13020, 13, 7, "0", "0", "My\u{0020}head's\u{0020}clearer\u{0020}now,\u{0020}like\u{0020}sipping\u{0020}on\u{0020}a\u{0020}chilled\u{0020}coffee.", "頭の中がすっきりしてる。まるでアイスコーヒーを飲んだ後みたい。", "思維更清晰了，像在品一杯冰咖啡。", "0", "0", "0", "cv_mayball_13", "0", "0"},
[432013] = {432013, 13020, 14, 8, "0", "0", "\"Awakening\"\u{0020}isn't\u{0020}really\u{0020}my\u{0020}thing.\u{0020}I\u{0020}could\u{0020}doze\u{0020}off\u{0020}any\u{0020}second,\u{0020}but\u{0020}since\u{0020}you\u{0020}believe\u{0020}in\u{0020}me...\u{0020}guess\u{0020}I'll\u{0020}try\u{0020}to\u{0020}stay\u{0020}awake.", "「覚醒」？私にはあまり似合わないね。もしかしたら、次の瞬間には寝てしまうかもしれないのに。でも、ナビゲーターくんが期待してくれてるなら、頑張ってみようかな。", "“覺醒”嗎？這詞真不適合我呢，說不定我下一秒就會睡著。但領航同學一直對我有所期待，果然我還是拿出十足的幹勁吧~", "0", "0", "0", "cv_mayball_14", "0", "0"},
[432014] = {432014, 13020, 15, 9, "0", "0", "Let's\u{0020}arm\u{0020}ourselves\u{0020}with\u{0020}thoughts.", "思考で武装するよ。", "用思想武裝自己呢。", "0", "0", "0", "cv_mayball_15", "0", "0"},
[432015] = {432015, 13020, 16, 10, "0", "0", "Back\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}after\u{0020}a\u{0020}while...", "久しぶりの戦場だ。", "闊別已久的戰場啊。", "0", "0", "0", "cv_mayball_16", "0", "0"},
[432016] = {432016, 13020, 17, 11, "0", "0", "Oops,\u{0020}I\u{0020}accidentally\u{0020}did\u{0020}a\u{0020}great\u{0020}job.", "おっと、やりすぎちゃったかな。", "哎呀，不小心發揮超常了。", "0", "0", "0", "cv_mayball_17", "0", "0"},
[432017] = {432017, 13020, 18, 12, "0", "0", "Life's\u{0020}imperfect\u{0020}by\u{0020}design.\u{0020}Don't\u{0020}stress\u{0020}it.", "不完全こそ人らしさだよ。心配しないで。", "不完美才是人生的常態，不用在意哦。", "0", "0", "0", "cv_mayball_18", "0", "0"},
[432018] = {432018, 13020, 19, 13, "0", "0", "If\u{0020}I\u{0020}keep\u{0020}this\u{0020}up,\u{0020}I\u{0020}won't\u{0020}set\u{0020}a\u{0020}good\u{0020}example\u{0020}for\u{0020}the\u{0020}kids.", "これじゃあお手本を見せられないね。", "這樣下去沒法給學生們當榜樣了呢。", "0", "0", "0", "cv_mayball_19", "0", "0"},
