[440001] = {440001, 14000, 2, 2, "0", "0", "Did\u{0020}you\u{0020}miss\u{0020}me?\u{0020}I\u{0020}think\u{0020}about\u{0020}you\u{0020}every\u{0020}day,\u{0020}Mr.\u{0020}Hentai.", "0", "有沒有想我？我倒是每天都在想你，色狼先生。", "0", "0", "0", "cv_starry2_2", "0", "0"},
[440002] = {440002, 14000, 3, 3, "0", "0", "Have\u{0020}you\u{0020}been\u{0020}eating\u{0020}well\u{0020}and\u{0020}resting\u{0020}enough?\u{0020}You\u{0020}look\u{0020}like\u{0020}you've\u{0020}lost\u{0020}a\u{0020}lot\u{0020}of\u{0020}weight.\u{0020}Me?\u{0020}Oh,\u{0020}it's\u{0020}nothing.\u{0020}Just\u{0020}a\u{0020}little\u{0020}accident,\u{0020}like\u{0020}choking\u{0020}on\u{0020}water—no\u{0020}big\u{0020}deal.", "0", "色狼先生，這段時間有好好吃飯，好好休息嗎，感覺你消瘦了不少——我？沒事的，只是點小事故，跟喝水被嗆到沒區別。", "0", "0", "0", "cv_starry2_3", "0", "0"},
[440003] = {440003, 14000, 4, 4, "0", "idle", "I\u{0020}feel\u{0020}like\u{0020}we\u{0020}haven't\u{0020}had\u{0020}a\u{0020}proper\u{0020}chat\u{0020}in\u{0020}ages.\u{0020}Let's\u{0020}make\u{0020}up\u{0020}for\u{0020}that\u{0020}today\u{0020}and\u{0020}talk\u{0020}about\u{0020}everything\u{0020}we've\u{0020}been\u{0020}holding\u{0020}back.", "0", "色狼先生，感覺我們那之後就一直沒有機會好好聊聊。這次要好好地——把這段時間欠下的都說出來。", "0", "0", "0", "cv_starry2_4", "0", "0"},
[440004] = {440004, 14000, 5, 4, "0", "idle", "Talent\u{0020}is\u{0020}a\u{0020}gift\u{0020}from\u{0020}the\u{0020}heavens,\u{0020}but\u{0020}it's\u{0020}also\u{0020}a\u{0020}curse\u{0020}we\u{0020}chosen\u{0020}ones\u{0020}have\u{0020}to\u{0020}carry...\u{0020}Everyone\u{0020}has\u{0020}their\u{0020}own\u{0020}curse.\u{0020}Mine?\u{0020}I\u{0020}think\u{0020}it's\u{0020}\"luck.\"", "0", "才能是上天賜予的禮物，也是被選中的人不得不背負的詛咒……每個人都有自己的詛咒，我想……我的詛咒就是“幸運”吧。", "0", "0", "0", "cv_starry2_5", "0", "0"},
[440005] = {440005, 14000, 6, 4, "0", "idle", "Fighting\u{0020}alongside\u{0020}someone\u{0020}wasn't\u{0020}as\u{0020}bad\u{0020}as\u{0020}I\u{0020}thought\u{0020}it'd\u{0020}be...\u{0020}but\u{0020}I\u{0020}still\u{0020}think\u{0020}I'm\u{0020}better\u{0020}off\u{0020}alone.\u{0020}\"Loneliness\u{0020}is\u{0020}the\u{0020}best\u{0020}makeup\u{0020}for\u{0020}a\u{0020}girl!\"\u{0020}Have\u{0020}you\u{0020}heard\u{0020}that\u{0020}one?", "0", "有人並肩作戰的感覺也許沒我預想的那麼糟糕……不過，我果然還是一個人最合適。“孤獨是女孩子最好的化妝品！”有句話是這麼說的，你聽過嗎？", "0", "0", "0", "cv_starry2_6", "0", "0"},
[440006] = {440006, 14000, 7, 5, "1_》_0_0.8", "level1", "I\u{0020}want\u{0020}to\u{0020}stay\u{0020}here\u{0020}forever...\u{0020}never\u{0020}leave.\u{0020}But\u{0020}we\u{0020}both\u{0020}have\u{0020}battlefields\u{0020}waiting\u{0020}for\u{0020}us.\u{0020}If\u{0020}we\u{0020}stop,\u{0020}more\u{0020}innocent\u{0020}lives\u{0020}will\u{0020}be\u{0020}lost.\u{0020}And\u{0020}I\u{0020}know\u{0020}you\u{0020}wouldn't\u{0020}let\u{0020}that\u{0020}happen.", "0", "我好想一直待在這裏……哪都不想去……但是果然不行吧，不管是你，還是我，都有要奔赴的戰場。一旦停下來，說不定就會有更多無辜的人死去，你不會允許這種事發生的。", "0", "0", "0", "cv_starry2_7", "0", "0"},
[440007] = {440007, 14000, 8, 5, "1_》_0_0.8", "level1", "I\u{0020}understand.\u{0020}The\u{0020}matter\u{0020}with\u{0020}Danube,\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad,\u{0020}and\u{0020}Maya...\u{0020}I\u{0020}know.\u{0020}You\u{0020}did\u{0020}well,\u{0020}Mr.\u{0020}Hentai.", "0", "嗯，我知道，多瑙的事，第三研究室防衛班的事，還有瑪雅的事……我都知道，你做的很棒，色狼先生。", "0", "0", "0", "cv_starry2_8", "0", "0"},
[440008] = {440008, 14000, 9, 5, "1_》_100_1.5", "level2", "Do\u{0020}you\u{0020}ever\u{0020}wonder\u{0020}when\u{0020}all\u{0020}of\u{0020}this\u{0020}will\u{0020}end...\u{0020}or\u{0020}if\u{0020}it'll\u{0020}go\u{0020}on\u{0020}forever?\u{0020}No,\u{0020}it's\u{0020}nothing.\u{0020}I'm\u{0020}just\u{0020}a\u{0020}little\u{0020}tired.", "0", "色狼先生，你覺得這一切什麼時候才會結束呢……還是說，永遠無法結束呢？不……沒什麼，我只是有點累了。", "0", "0", "0", "cv_starry2_9", "0", "0"},
[440009] = {440009, 14000, 10, 5, "1_》_500_2", "level3", "Corruption\u{0020}comes\u{0020}from\u{0020}the\u{0020}heart's\u{0020}craving\u{0020}for\u{0020}happiness.\u{0020}The\u{0020}harder\u{0020}people\u{0020}cling\u{0020}to\u{0020}happiness,\u{0020}the\u{0020}easier\u{0020}it\u{0020}slips\u{0020}away.\u{0020}If\u{0020}I'd\u{0020}just\u{0020}accepted\u{0020}from\u{0020}the\u{0020}start\u{0020}that\u{0020}happiness\u{0020}wasn't\u{0020}meant\u{0020}for\u{0020}me,\u{0020}maybe\u{0020}I\u{0020}wouldn't\u{0020}have\u{0020}wavered.", "0", "墮落的源頭是想要追求幸福的心。人越是想用自己的手抓住幸福的繩子，就越容易從空中墜下。從一開始就認定自己無法獲得幸福的話，我大概就不會動搖了吧。", "0", "0", "0", "cv_starry2_10", "0", "0"},
[440010] = {440010, 14000, 11, 5, "1_》_1000_2.5", "level4", "It\u{0020}won't\u{0020}be\u{0020}long...\u{0020}we'll\u{0020}part\u{0020}again,\u{0020}right?\u{0020}But\u{0020}that's\u{0020}okay.\u{0020}You've\u{0020}got\u{0020}amazing\u{0020}people\u{0020}by\u{0020}your\u{0020}side—Charissa,\u{0020}and\u{0020}that\u{0020}kid\u{0020}who\u{0020}can\u{0020}see\u{0020}the\u{0020}future.\u{0020}With\u{0020}them,\u{0020}you'll\u{0020}be\u{0020}just\u{0020}fine.\u{0020}I'll\u{0020}keep\u{0020}hope\u{0020}in\u{0020}my\u{0020}heart\u{0020}and\u{0020}look\u{0020}forward\u{0020}to\u{0020}the\u{0020}day\u{0020}we\u{0020}meet\u{0020}again.", "0", "再過不久……我們又要分別了吧。沒關係的，你身邊有許多優秀的人……查麗莎，還有那個能看到未來的孩子，有她們在，你是不會出事的。我會心揣著希望，期待我們下一次重逢的。", "0", "0", "0", "cv_starry2_11", "0", "0"},
[440011] = {440011, 14000, 12, 6, "0", "0", "Haha...\u{0020}my\u{0020}hand\u{0020}hurts\u{0020}a\u{0020}little...", "0", "哈哈……手有點疼……", "0", "0", "0", "cv_starry2_12", "0", "0"},
[440012] = {440012, 14000, 13, 7, "0", "0", "But\u{0020}it's\u{0020}manageable.", "0", "還算在控制範圍吧。", "0", "0", "0", "cv_starry2_13", "0", "0"},
[440013] = {440013, 14000, 14, 8, "0", "0", "I've\u{0020}got\u{0020}to\u{0020}shine\u{0020}the\u{0020}brightest\u{0020}before\u{0020}I\u{0020}burn\u{0020}out—that's\u{0020}my\u{0020}mission.", "0", "在燃盡之前綻放出最耀眼的光，這就是我要做的事。", "0", "0", "0", "cv_starry2_14", "0", "0"},
[440014] = {440014, 14000, 15, 9, "0", "0", "Sometimes,\u{0020}I\u{0020}wish\u{0020}I\u{0020}could\u{0020}shine\u{0020}a\u{0020}little\u{0020}more.", "0", "偶爾也想變得更耀眼一點。", "0", "0", "0", "cv_starry2_15", "0", "0"},
