[440025] = {440025, 14000, 27, 20, "0", "0", "Haha,\u{0020}this\u{0020}reminds\u{0020}me\u{0020}of\u{0020}when\u{0020}we\u{0020}first\u{0020}met...\u{0020}\"Our\u{0020}first\u{0020}time...\"", "0", "哈哈哈——讓我想起我們第一次見面的時候……“第一次”……", "0", "0", "0", "cv_starry2_27", "0", "0"},
[440026] = {440026, 14000, 28, 21, "0", "0", "Do\u{0020}those\u{0020}memories\u{0020}still\u{0020}scare\u{0020}you\u{0020}a\u{0020}bit?\u{0020}I\u{0020}wonder\u{0020}if\u{0020}a\u{0020}blackhead\u{0020}remover\u{0020}mask\u{0020}could\u{0020}clear\u{0020}them\u{0020}up?", "0", "那些東西……果然還是有點嚇人吧？不知道除黑頭的面膜能不能除去它們呢？", "0", "0", "0", "cv_starry2_28", "0", "0"},
[440027] = {440027, 14000, 29, 21, "0", "0", "Ouch,\u{0020}ouch,\u{0020}ouch...\u{0020}Is\u{0020}this\u{0020}how\u{0020}people\u{0020}with\u{0020}kidney\u{0020}stones\u{0020}feel?", "0", "疼疼疼……不知道那些有腎結石的人是不是也是這種感覺？", "0", "0", "0", "cv_starry2_29", "0", "0"},
