[440030] = {440030, 14000, 32, 24, "0", "0", "This\u{0020}time,\u{0020}I\u{0020}want\u{0020}to\u{0020}say\u{0020}it\u{0020}clearly—I'm\u{0020}really\u{0020}happy,\u{0020}Mr.\u{0020}Hentai.", "0", "這次我想直率的表達——我很高興，色狼先生。", "0", "0", "0", "cv_starry2_32", "0", "0"},
[440031] = {440031, 14000, 33, 25, "0", "0", "Don't\u{0020}worry.\u{0020}Everyone\u{0020}makes\u{0020}mistakes\u{0020}sometimes.", "0", "別在意~總會有錯的時候。", "0", "0", "0", "cv_starry2_33", "0", "0"},
[440032] = {440032, 14000, 34, 26, "0", "0", "We\u{0020}part,\u{0020}we\u{0020}reunite,\u{0020}and\u{0020}we\u{0020}part\u{0020}again...\u{0020}but\u{0020}we'll\u{0020}break\u{0020}this\u{0020}cycle,\u{0020}I'm\u{0020}sure\u{0020}of\u{0020}it.", "0", "分別，然後重逢，接著是分別……我們一定能脫離這個迴圈的。", "0", "0", "0", "cv_starry2_34", "0", "0"},
[440033] = {440033, 14000, 35, 27, "0", "0", "Alright,\u{0020}the\u{0020}battlefield\u{0020}is\u{0020}waiting.\u{0020}Let's\u{0020}go.", "0", "好啦，戰場還在等著我們呢，出發吧。", "0", "0", "0", "cv_starry2_35", "0", "0"},
