[440035] = {440035, 14000, 37, 29, "0", "0", "There\u{0020}are\u{0020}more\u{0020}unfamiliar\u{0020}faces\u{0020}again.", "0", "又多了些不認識的人呢。", "0", "0", "0", "cv_starry2_37", "0", "0"},
