[440100] = {440100, 14001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_korsgaard_1", "0", "0"},
[440101] = {440101, 14001, 2, 2, "0", "0", "I\u{0020}may\u{0020}not\u{0020}be\u{0020}skilled\u{0020}in\u{0020}this,\u{0020}but\u{0020}I\u{0020}trust\u{0020}your\u{0020}judgment.", "0", "雖然不擅長，但我相信你的選擇。", "0", "0", "0", "cv_korsgaard_2", "0", "0"},
[440102] = {440102, 14001, 3, 3, "0", "0", "Didn't\u{0020}think\u{0020}we'd\u{0020}meet\u{0020}again\u{0020}so\u{0020}soon,\u{0020}Navigator.\u{0020}Save\u{0020}the\u{0020}pleasantries\u{0020}for\u{0020}another\u{0020}time.\u{0020}Kosgaard,\u{0020}Commander\u{0020}of\u{0020}the\u{0020}Poynred\u{0020}Church\u{0020}Knights.\u{0020}Looking\u{0020}forward\u{0020}to\u{0020}working\u{0020}with\u{0020}you\u{0020}once\u{0020}more.", "0", "沒想到重逢來得這麼快，領航。多餘的寒暄就留在日後吧，我——珀因雷德教會騎士團長珂斯嘉德，期待與你的再次合作。", "0", "0", "0", "cv_korsgaard_3", "0", "0"},
[440103] = {440103, 14001, 4, 4, "0", "idle", "If\u{0020}just\u{0020}standing\u{0020}here,\u{0020}like\u{0020}a\u{0020}giant\u{0020}statue\u{0020}of\u{0020}a\u{0020}deity,\u{0020}makes\u{0020}people\u{0020}feel\u{0020}safe,\u{0020}then\u{0020}this\u{0020}job\u{0020}has\u{0020}its\u{0020}uses.", "0", "宛如一尊巨大的神像，只是佇立於此就能讓人心安的話，這份工作倒也不算沒有意義。", "0", "0", "0", "cv_korsgaard_4", "0", "0"},
[440104] = {440104, 14001, 5, 4, "0", "idle2", "Are\u{0020}you\u{0020}meditating,\u{0020}Navigator?\u{0020}I\u{0020}often\u{0020}do\u{0020}the\u{0020}same\u{0020}when\u{0020}troubled.\u{0020}Seems\u{0020}like\u{0020}you're\u{0020}not\u{0020}thinking,\u{0020}but\u{0020}it\u{0020}clears\u{0020}your\u{0020}head\u{0020}and\u{0020}improves\u{0020}your\u{0020}performance.\u{0020}Human\u{0020}mind\u{0020}works\u{0020}in\u{0020}strange\u{0020}ways.", "0", "領航是在冥想？我煩惱時也常常如此。分明看似什麼也沒思考，卻反倒有利於之後的行動，人類的精神還真是奇妙啊。", "0", "0", "0", "cv_korsgaard_5", "0", "0"},
[440105] = {440105, 14001, 6, 4, "0", "idle3", "I\u{0020}used\u{0020}to\u{0020}think\u{0020}it\u{0020}was\u{0020}wrong\u{0020}to\u{0020}pry.\u{0020}That's\u{0020}why\u{0020}I\u{0020}never\u{0020}pressed\u{0020}Mira\u{0020}or\u{0020}Meria\u{0020}about\u{0020}the\u{0020}things\u{0020}that\u{0020}didn't\u{0020}add\u{0020}up.\u{0020}But\u{0020}that\u{0020}was\u{0020}just\u{0020}me\u{0020}fearing\u{0020}to\u{0020}face\u{0020}the\u{0020}truth.", "0", "我曾認為不該過分探究別人的本質，因此對於米菈隊長和梅莉雅的一些違和之處並未過問，但現在看來，這只不過是在逃避吧。", "0", "0", "0", "cv_korsgaard_6", "0", "0"},
[440106] = {440106, 14001, 7, 5, "1_》_0_0.8", "level1", "This\u{0020}left\u{0020}arm\u{0020}doesn't\u{0020}work,\u{0020}like\u{0020}I\u{0020}said.\u{0020}But\u{0020}when\u{0020}I'm\u{0020}gigantified,\u{0020}it\u{0020}functions\u{0020}fine.\u{0020}I\u{0020}don't\u{0020}use\u{0020}it\u{0020}now...\u{0020}because\u{0020}a\u{0020}sword\u{0020}is\u{0020}most\u{0020}useful\u{0020}when\u{0020}it's\u{0020}still\u{0020}in\u{0020}the\u{0020}scabbard.", "0", "如之前所說，這支左臂失去了運動機能，但在巨大化狀態卻可以正常使用。而我現在之所以不用……大概是覺得，劍在鞘中時才最具價值。", "0", "0", "0", "cv_korsgaard_7", "0", "0"},
[440107] = {440107, 14001, 8, 5, "1_》_0_0.8", "level1", "Worried\u{0020}about\u{0020}Poynred,\u{0020}all\u{0020}the\u{0020}way\u{0020}out\u{0020}here?\u{0020}Of\u{0020}course.\u{0020}But\u{0020}that\u{0020}city\u{0020}has\u{0020}learned\u{0020}to\u{0020}stand\u{0020}on\u{0020}its\u{0020}own\u{0020}feet.\u{0020}Now,\u{0020}we\u{0020}wait\u{0020}and\u{0020}see.", "0", "要說我遠在外乡，對珀因雷德的狀況是否擔心，答案是毋庸置疑的。但那座城市已有了靠自己飛離舊巢的力量，接下來的，就交給時間吧。", "0", "0", "0", "cv_korsgaard_8", "0", "0"},
[440108] = {440108, 14001, 9, 5, "1_》_100_1.5", "level2", "What\u{0020}is\u{0020}it?\u{0020}Want\u{0020}a\u{0020}thrilling\u{0020}rematch?\u{0020}I'm\u{0020}always\u{0020}ready.\u{0020}Though\u{0020}I'm\u{0020}not\u{0020}at\u{0020}my\u{0020}best...\u{0020}How\u{0020}about\u{0020}a\u{0020}simulated\u{0020}fight\u{0020}through\u{0020}Synesthesia\u{0020}instead?", "0", "怎麼了？想再進行一場痛痛快快的決鬥的話，我很樂意奉陪。只是現在這副狀態不太合適，或者……我們可以先通感，在內心來一場模擬戰？", "0", "0", "0", "cv_korsgaard_9", "0", "0"},
[440109] = {440109, 14001, 10, 5, "1_》_500_2", "level3", "Besides\u{0020}the\u{0020}sword,\u{0020}I\u{0020}have\u{0020}normal\u{0020}hobbies.\u{0020}Hiking,\u{0020}reading,\u{0020}tea...\u{0020}What?\u{0020}Still\u{0020}too\u{0020}traditional?\u{0020}Then\u{0020}you'll\u{0020}have\u{0020}to\u{0020}teach\u{0020}me\u{0020}what's\u{0020}fun\u{0020}these\u{0020}days,\u{0020}Navigator.", "0", "除了劍術，我當然也有其他更為尋常的興趣，例如登山、看書、喝茶之類……唔，還是太古板了嗎？那麼，我就向領航討教些更現代的娛樂方式吧？", "0", "0", "0", "cv_korsgaard_10", "0", "0"},
[440110] = {440110, 14001, 11, 5, "1_》_1000_2.5", "level4", "Purity\u{0020}means\u{0020}being\u{0020}true\u{0020}to\u{0020}yourself.\u{0020}That's\u{0020}what\u{0020}I've\u{0020}always\u{0020}believed.\u{0020}But\u{0020}is\u{0020}that\u{0020}enough\u{0020}to\u{0020}make\u{0020}peace\u{0020}with\u{0020}the\u{0020}world?\u{0020}I'm\u{0020}not\u{0020}sure.\u{0020}The\u{0020}only\u{0020}thing\u{0020}I\u{0020}am\u{0020}sure\u{0020}of\u{0020}is\u{0020}that\u{0020}I\u{0020}feel\u{0020}steadier\u{0020}with\u{0020}you\u{0020}here.", "0", "所謂純粹，就是保持本真，因此我向來以此要求自己。但與世界相處的模式只是這樣就可以了嗎？我不知道……我唯一能確認的，只有在你身邊會更加安心。", "0", "0", "0", "cv_korsgaard_11", "0", "0"},
[440111] = {440111, 14001, 12, 6, "0", "0", "I\u{0020}appreciate\u{0020}it.", "0", "有勞你了。", "0", "0", "0", "cv_korsgaard_12", "0", "0"},
