[440302] = {440302, 14003, 3, 3, "0", "0", "This\u{0020}is\u{0020}a\u{0020}rare\u{0020}reunion,\u{0020}you\u{0020}know.\u{0020}So\u{0020}I'll\u{0020}take\u{0020}this\u{0020}chance\u{0020}to\u{0020}show\u{0020}you\u{0020}how\u{0020}much\u{0020}I've\u{0020}changed,\u{0020}Navigator.", "0", "這次的重逢是難得的機會，我要向領航您展現我的蛻變。", "0", "0", "0", "cv_iria2_3", "0", "0"},
[440303] = {440303, 14003, 4, 4, "0", "idle", "Ember\u{0020}must\u{0020}have\u{0020}drawn\u{0020}the\u{0020}attention\u{0020}of\u{0020}the\u{0020}Katya\u{0020}Branch\u{0020}after\u{0020}Christmas.\u{0020}They\u{0020}gave\u{0020}us\u{0020}much\u{0020}more\u{0020}supplies,\u{0020}and\u{0020}I'd\u{0020}say\u{0020}we\u{0020}have\u{0020}you\u{0020}to\u{0020}thank\u{0020}for\u{0020}that.", "0", "聖誕節過後，灰燼好像受到了卡佳支部上層的關注，給了我們更多的物資配給。我想這都是托了領航的福。", "0", "0", "0", "cv_iria2_4", "0", "0"},
[440304] = {440304, 14003, 5, 4, "0", "idle2", "I\u{0020}won't\u{0020}forget\u{0020}my\u{0020}hatred\u{0020}for\u{0020}the\u{0020}Sins.\u{0020}But\u{0020}I\u{0020}won't\u{0020}let\u{0020}it\u{0020}take\u{0020}over\u{0020}me\u{0020}anymore.\u{0020}My\u{0020}rage\u{0020}still\u{0020}burns,\u{0020}but\u{0020}from\u{0020}now\u{0020}on,\u{0020}it's\u{0020}under\u{0020}my\u{0020}control.", "0", "對原罪的仇恨我不會忘，但我不會再讓仇恨支配我的心。從今往後，我的怒火將在平靜中燃燒。", "0", "0", "0", "cv_iria2_5", "0", "0"},
[440305] = {440305, 14003, 6, 4, "0", "idle3", "I'd\u{0020}assumed\u{0020}Bolina\u{0020}was\u{0020}the\u{0020}one\u{0020}I'd\u{0020}have\u{0020}to\u{0020}worry\u{0020}about.\u{0020}I\u{0020}feared\u{0020}she'd\u{0020}struggle\u{0020}from\u{0020}day\u{0020}to\u{0020}day\u{0020}without\u{0020}me.\u{0020}After\u{0020}we\u{0020}met\u{0020}at\u{0020}Christmas,\u{0020}though,\u{0020}I'd\u{0020}say\u{0020}it\u{0020}was\u{0020}Crim\u{0020}we\u{0020}should\u{0020}be\u{0020}concerned\u{0020}for.", "0", "原本我最擔心的人是波琳娜，害怕她在離開我之後一個人沒有辦法好好生活。不過從聖誕節的表現來看，好像是克裡姆更不讓人省心。", "0", "0", "0", "cv_iria2_6", "0", "0"},
[440306] = {440306, 14003, 7, 5, "1_》_0_0.8", "level", "Ember\u{0020}and\u{0020}I\u{0020}are\u{0020}now\u{0020}walking\u{0020}an\u{0020}entirely\u{0020}different\u{0020}path\u{0020}from\u{0020}before.\u{0020}That\u{0020}said,\u{0020}you'll\u{0020}always\u{0020}be\u{0020}our\u{0020}guiding\u{0020}star,\u{0020}Navigator.\u{0020}No\u{0020}matter\u{0020}where\u{0020}you\u{0020}might\u{0020}be.", "0", "我和灰燼，都已經走上了一條和之前完全不同的道路。但無論在哪，領航您都是唯一指引著我們的北極星。", "0", "0", "0", "cv_iria2_7", "0", "0"},
[440307] = {440307, 14003, 8, 5, "1_》_0_0.8", "level2", "I\u{0020}still\u{0020}hardly\u{0020}dare\u{0020}to\u{0020}believe\u{0020}that\u{0020}my\u{0020}hand\u{0020}might\u{0020}actually\u{0020}heal,\u{0020}and\u{0020}return\u{0020}to\u{0020}normal.", "0", "我還不是不敢相信，我的左手竟然能恢複如初。", "0", "0", "0", "cv_iria2_8", "0", "0"},
[440308] = {440308, 14003, 9, 5, "1_》_100_1.5", "level3", "You\u{0020}pulled\u{0020}me\u{0020}from\u{0020}that\u{0020}abyss\u{0020}of\u{0020}vengeance\u{0020}I'd\u{0020}fallen\u{0020}into.\u{0020}So\u{0020}it's\u{0020}okay,\u{0020}whatever\u{0020}you\u{0020}plan\u{0020}to\u{0020}do.", "0", "是領航將我從複仇的深淵中拉了回來，所以領航想做什麼都沒關系。", "0", "0", "0", "cv_iria2_9", "0", "0"},
[440309] = {440309, 14003, 10, 5, "1_》_500_2", "level4", "\"Take\u{0020}better\u{0020}care\u{0020}of\u{0020}yourself\"—I'm\u{0020}going\u{0020}to\u{0020}make\u{0020}sure\u{0020}I\u{0020}do\u{0020}that,\u{0020}from\u{0020}now\u{0020}on.\u{0020}As\u{0020}I\u{0020}don't\u{0020}want\u{0020}to\u{0020}let\u{0020}you\u{0020}down.\u{0020}And\u{0020}I\u{0020}never\u{0020}want\u{0020}to\u{0020}put\u{0020}you\u{0020}in\u{0020}danger\u{0020}again.", "0", "“更加愛惜自己的身體。”我現在一定會做到的。因為我不想辜負領航的努力，更不想因為我的原因讓領航再次挺身犯險。", "0", "0", "0", "cv_iria2_10", "0", "0"},
[440310] = {440310, 14003, 11, 5, "1_》_1000_2.5", "level5", "My\u{0020}body's\u{0020}back\u{0020}to\u{0020}normal\u{0020}now,\u{0020}left\u{0020}hand\u{0020}aside.Give\u{0020}me\u{0020}your\u{0020}hand...\u{0020}Feel\u{0020}that?\u{0020}It's\u{0020}a\u{0020}real\u{0020}heartbeat.\u{0020}My\u{0020}heartbeat.\u{0020}I've\u{0020}always\u{0020}wanted\u{0020}you\u{0020}to\u{0020}hear\u{0020}it.", "0", "除了左手之外，我的身體其他地方也恢複原樣。請把您的手給我……感受到了嗎？真正的心髒跳動的聲音，這就是我一直希望領航聽到的心聲。", "0", "0", "0", "cv_iria2_11", "0", "0"},
[440311] = {440311, 14003, 12, 6, "0", "0", "I\u{0020}feel\u{0020}power\u{0020}flowing\u{0020}from\u{0020}within\u{0020}me.", "0", "力量從身體裏湧現。", "0", "0", "0", "cv_iria2_12", "0", "0"},
[440312] = {440312, 14003, 13, 7, "0", "0", "Sparks,\u{0020}that\u{0020}burn\u{0020}all\u{0020}to\u{0020}ashes.", "0", "燃燒一切的小火星。", "0", "0", "0", "cv_iria2_13", "0", "0"},
[440313] = {440313, 14003, 14, 8, "0", "0", "Ember\u{0020}will\u{0020}soon\u{0020}be\u{0020}rekindled.\u{0020}I\u{0020}know\u{0020}it'll\u{0020}be\u{0020}hard\u{0020}to\u{0020}regain\u{0020}what\u{0020}was\u{0020}lost,\u{0020}but\u{0020}that's\u{0020}what\u{0020}makes\u{0020}it\u{0020}such\u{0020}a\u{0020}miracle.\u{0020}Something\u{0020}to\u{0020}cherish.", "0", "灰燼即將重燃，我知道取回失去的東西有多麼困難，所以才更珍惜這來之不易的奇跡。", "0", "0", "0", "cv_iria2_14", "0", "0"},
[440314] = {440314, 14003, 15, 9, "0", "0", "I\u{0020}don't\u{0020}need\u{0020}anything\u{0020}else\u{0020}now.\u{0020}Vengeance\u{0020}has\u{0020}already\u{0020}granted\u{0020}me\u{0020}the\u{0020}power\u{0020}I\u{0020}need.", "0", "不再需要外物，我已經獲得了複仇的力量。", "0", "0", "0", "cv_iria2_15", "0", "0"},
[440315] = {440315, 14003, 16, 10, "0", "0", "Sins...\u{0020}It's\u{0020}time\u{0020}they\u{0020}repented.", "0", "原罪，該贖罪了。", "0", "0", "0", "cv_iria2_16", "0", "0"},
[440316] = {440316, 14003, 17, 11, "0", "0", "Calmness,\u{0020}like\u{0020}nothing\u{0020}ever\u{0020}before.", "0", "前所未有的平靜。", "0", "0", "0", "cv_iria2_17", "0", "0"},
[440317] = {440317, 14003, 18, 12, "0", "0", "The\u{0020}road\u{0020}of\u{0020}revenge\u{0020}is\u{0020}not\u{0020}an\u{0020}easy\u{0020}one\u{0020}to\u{0020}walk,\u{0020}by\u{0020}any\u{0020}means.", "0", "複仇之路，還是沒那麼輕松。", "0", "0", "0", "cv_iria2_18", "0", "0"},
[440318] = {440318, 14003, 19, 13, "0", "0", "Just\u{0020}how\u{0020}much\u{0020}did\u{0020}I\u{0020}cast\u{0020}aside...\u{0020}Just\u{0020}what\u{0020}price\u{0020}did\u{0020}I\u{0020}pay\u{0020}for\u{0020}vengeance?", "0", "為了複仇，我之前到底忽視了多少代價。", "0", "0", "0", "cv_iria2_19", "0", "0"},
[440319] = {440319, 14003, 20, 14, "0", "0", "Vengeance\u{0020}doesn't\u{0020}need\u{0020}to\u{0020}be\u{0020}swift.\u{0020}What's\u{0020}important\u{0020}is\u{0020}that\u{0020}everyone's\u{0020}still\u{0020}here,\u{0020}alive...", "0", "複仇不急於一時，重要的是大家都還活著……", "0", "0", "0", "cv_iria2_20", "0", "0"},
[440320] = {440320, 14003, 21, 15, "0", "0", "Next.", "0", "下一個。", "0", "0", "0", "cv_iria2_21", "0", "0"},
[440321] = {440321, 14003, 23, 16, "0", "0", "Finally,\u{0020}all\u{0020}that's\u{0020}left\u{0020}is\u{0020}smoking\u{0020}embers.", "0", "終將化為灰燼。", "0", "0", "0", "cv_iria2_22", "0", "0"},
[440322] = {440322, 14003, 24, 17, "0", "0", "Slowly.\u{0020}Not\u{0020}a\u{0020}single\u{0020}one\u{0020}shall\u{0020}escape.", "0", "慢慢來，一個都逃不掉。", "0", "0", "0", "cv_iria2_24", "0", "0"},
[440323] = {440323, 14003, 25, 18, "0", "0", "I\u{0020}never\u{0020}forgot\u{0020}about\u{0020}my\u{0020}revenge.\u{0020}I\u{0020}let\u{0020}it\u{0020}simmer\u{0020}peacefully,\u{0020}so\u{0020}that\u{0020}it\u{0020}may\u{0020}now\u{0020}burst\u{0020}into\u{0020}blazing\u{0020}flame.", "0", "我從沒有忘記複仇，平靜的憤怒就是為了在這一刻燃燒殆盡。", "0", "0", "0", "cv_iria2_25", "0", "0"},
[440324] = {440324, 14003, 26, 19, "0", "0", "I\u{0020}thought...\u{0020}I\u{0020}thought\u{0020}I\u{0020}had\u{0020}already...", "0", "我以為……我已經……", "0", "0", "0", "cv_iria2_26", "0", "0"},
[440325] = {440325, 14003, 27, 20, "0", "0", "It's\u{0020}certainly\u{0020}not\u{0020}the\u{0020}first\u{0020}time\u{0020}I'm\u{0020}saying\u{0020}this...\u{0020}But...\u{0020}I'm\u{0020}leaving\u{0020}this\u{0020}in\u{0020}your\u{0020}hands,\u{0020}Navigator.", "0", "雖然不是第一次，但還是想說“拜托領航了”。", "0", "0", "0", "cv_iria2_27", "0", "0"},
