[900001] = {900001, 90000, 2, 2, "0", "3", "I\u{0020}wonder\u{0020}if\u{0020}I'll\u{0020}do\u{0020}it\u{0020}right...", "わっ……ちゃんとやれるかな……", "啊哇哇，不知道能不能做好啊……", "0", "啊哇哇，不知道能不能做好啊……", "0", "cv_jiya_4", "0", "0"},
[900002] = {900002, 90000, 4, 4, "0_0_0_0.1", "6", "The\u{0020}sun\u{0020}gives\u{0020}life,\u{0020}but\u{0020}it's\u{0020}blinding.\u{0020}I\u{0020}prefer\u{0020}the\u{0020}moon—gentler,\u{0020}guiding,\u{0020}maintaining\u{0020}order.", "お日さまは皆は万物に命を与えてくれるけど、直視できない。私は柔らかい光のお月さまの方が好き。", "比起給予萬物生命但卻令人無法直視的太陽，我更加喜歡維繫著規則但卻更加柔和的月亮。", "0", "比起给予万物生命但却令人无法直视的太阳，我更加喜欢维系着规则但却更加柔和的月亮。", "0", "cv_jiya_7", "0", "0"},
[900003] = {900003, 90000, 5, 4, "0_0_0_0.1", "7", "When\u{0020}the\u{0020}war\u{0020}ends,\u{0020}I\u{0020}want\u{0020}to\u{0020}visit\u{0020}the\u{0020}seaside...\u{0020}If\u{0020}my\u{0020}illness\u{0020}is\u{0020}cured,\u{0020}I'd\u{0020}love\u{0020}to\u{0020}open\u{0020}a\u{0020}flower\u{0020}shop\u{0020}there.", "戦争が終わったら、海に行ってみたい。あと……もし病気が治ったら、海沿いでお花屋さんをやりたい。", "等戰爭結束，我想親自去海邊看一看。然後…如果我的病能痊癒的話，吉雅想自己在海邊開一間花店。", "0", "等战争结束，我想亲自去海边看一看。然后…如果我的病能痊愈的话，吉雅想自己在海边开一间花店。", "0", "cv_jiya_8", "0", "0"},
[900004] = {900004, 90000, 6, 4, "0_0_0_0.1", "8", "I\u{0020}just\u{0020}wish\u{0020}I\u{0020}could\u{0020}help\u{0020}you\u{0020}more...", "私がお兄ちゃんの力になれればいいのに……", "如果我也能夠幫上哥哥的忙就好了……", "0", "如果我也能够帮上哥哥的忙就好了……", "0", "cv_jiya_9", "0", "0"},
[900005] = {900005, 90000, 46, 4, "0_0_0_0.1", "9", "If\u{0020}I\u{0020}can\u{0020}become\u{0020}an\u{0020}intelligence\u{0020}officer\u{0020}soon,\u{0020}I\u{0020}can\u{0020}support\u{0020}you\u{0020}better.\u{0020}Alright!\u{0020}While\u{0020}I\u{0020}still\u{0020}have\u{0020}energy,\u{0020}I'll\u{0020}push\u{0020}through\u{0020}and\u{0020}study\u{0020}hard\u{0020}today!", "早く情報官になれば、お兄ちゃんの力になれるよね。よし。まだまだいける気がするし…、今日も頑張って勉強する！", "如果能快點當上情報官的話，就能幫上哥哥了吧。好！趁著還有力氣，今天也要打起精神努力學習喔！", "0", "如果能快点当上情报官的话，就能帮上哥哥了吧。好！趁着还有力气，今天也要打起精神努力学习哦！", "0", "cv_jiya_10", "0", "0"},
[900006] = {900006, 90000, 47, 4, "0_0_0_0.1", "10", "Feeling\u{0020}lonely?\u{0020}It's\u{0020}alright.\u{0020}I'll\u{0020}video\u{0020}chat\u{0020}with\u{0020}you\u{0020}every\u{0020}day,\u{0020}so\u{0020}it's\u{0020}not\u{0020}too\u{0020}bad.\u{0020}It'd\u{0020}be\u{0020}better\u{0020}if\u{0020}you\u{0020}came\u{0020}home\u{0020}sooner,\u{0020}though.\u{0020}Miss\u{0020}Dolores\u{0020}has\u{0020}been\u{0020}teaching\u{0020}me\u{0020}new\u{0020}dishes.\u{0020}I\u{0020}can't\u{0020}wait\u{0020}for\u{0020}you\u{0020}to\u{0020}taste\u{0020}them.", "寂しいかって……？私は大丈夫だよ。だって、毎日お兄ちゃんとテレビ電話できるし、寂しくないよ。…でもお兄ちゃんがもうちょっと早く帰ってきてくれればうれしいなぁって。ドロリィスさんに沢山の新しい料理を教えてもらったから、その成果を見せてあげたいの。", "寂寞？沒關係，因為每天都能和哥哥視頻所以也不算太寂寞。當然，如果哥哥能早點回來那就更好了。多洛莉絲小姐教會了我很多新的料理，就等您回來檢驗成果了。", "0", "寂寞？没关系，因为每天都能和哥哥视频所以也不算太寂寞。当然，如果哥哥能早点回来那就更好了。多洛莉丝小姐教会了我很多新的料理，就等您回来检验成果了。", "0", "cv_jiya_11", "0", "0"},
[900007] = {900007, 90000, 48, 4, "0_0_0_0.1", "11", "I\u{0020}never\u{0020}thought\u{0020}I'd\u{0020}be\u{0020}promoted\u{0020}to\u{0020}an\u{0020}intelligence\u{0020}officer\u{0020}this\u{0020}quickly...\u{0020}I'm\u{0020}glad\u{0020}I\u{0020}can\u{0020}help\u{0020}you,\u{0020}but\u{0020}if\u{0020}I\u{0020}mess\u{0020}up,\u{0020}please\u{0020}point\u{0020}it\u{0020}out,\u{0020}brother...\u{0020}I\u{0020}don't\u{0020}want\u{0020}to\u{0020}make\u{0020}your\u{0020}work\u{0020}harder.", "まさか情報官に抜擢されるなんて、思ってもみなかった……やっとお兄ちゃんの力になれるし、嬉しいけど……何か駄目なところがあったら言ってね、お兄ちゃん……これ以上お仕事で…お兄ちゃんに、迷惑かけるわけにはいかないから。", "沒想到會被破格提升成情報官啊……雖然能幫上哥哥的忙很開心，但是如果我有做得不好的地方還請哥哥一定要指出……畢竟我不能再在工作上給您添麻煩了。", "0", "没想到会被破格提升成情报官啊……虽然能帮上哥哥的忙很开心，但是如果我有做得不好的地方还请哥哥一定要指出……毕竟我不能再在工作上给您添麻烦了。", "0", "cv_jiya_12", "0", "0"},
[900008] = {900008, 90000, 49, 5, "1_》_0_0.3", "12", "Heh,\u{0020}you're\u{0020}always\u{0020}so\u{0020}kind...\u{0020}Even\u{0020}if\u{0020}you\u{0020}don't\u{0020}pat\u{0020}my\u{0020}head,\u{0020}just\u{0020}being\u{0020}by\u{0020}your\u{0020}side\u{0020}is\u{0020}enough\u{0020}to\u{0020}make\u{0020}me\u{0020}happy.", "うふふ。お兄ちゃんっていつも優しいね……頭をぽんぽんしてくれるのも嬉しいけど、本当はそばにいてくれるだけで幸せなんだよ。", "呼呼呼，哥哥你總是這麼溫柔啊……哪怕哥哥不摸我的頭，只是陪在我身邊我就很幸福了。", "0", "呼呼呼，哥哥你总是这么温柔啊……哪怕哥哥不摸我的头，只是陪在我身边我就很幸福了。", "0", "cv_jiya_13", "0", "0"},
[900009] = {900009, 90000, 50, 5, "1_》_0_0.3", "13", "Oh\u{0020}no...um,\u{0020}Navigator,\u{0020}everyone's\u{0020}staring...\u{0020}I\u{0020}think\u{0020}I\u{0020}should\u{0020}use\u{0020}the\u{0020}wheelchair...\u{0020}But...\u{0020}I\u{0020}don't\u{0020}mind\u{0020}being\u{0020}carried\u{0020}by\u{0020}you\u{0020}like\u{0020}this...", "えっ――お兄ちゃん……あっ、えっと、ナ……ナビゲーター、みんな見ているから……私、やっぱり車椅子で……うう。……でも、こうやって抱き上げられるのは、本当は嫌じゃないかも……", "哇呼——哥哥……不對…領…領航，這麼多都在看著我們……我還是用輪椅吧……但是…像這樣被您抱著的感覺並不討厭……", "0", "哇呼——哥哥……不对…领…领航，这么多都在看着我们……我还是用轮椅吧……但是…像这样被您抱着的感觉并不讨厌……", "0", "cv_jiya_14", "0", "0"},
[900010] = {900010, 90000, 51, 5, "1_》_0_0.2", "14", "Yes,\u{0020}I've\u{0020}been\u{0020}keeping\u{0020}up\u{0020}with\u{0020}everything,\u{0020}hehe.", "ちゃんといるよ、サボったりしてないよ。ふふ。", "在，吉雅可沒有偷懶喔，哼哼~", "0", "在，吉雅可没有偷懒哦，哼哼~", "0", "cv_jiya_15", "0", "0"},
[900011] = {900011, 90000, 52, 5, "1_》_0_0.2", "15", "\"I\u{0020}want\u{0020}to\u{0020}be\u{0020}recognized...\u{0020}I\u{0020}want\u{0020}to\u{0020}be\u{0020}like\u{0020}everyone\u{0020}else...\u{0020}I\u{0020}want\u{0020}mom\u{0020}to\u{0020}notice\u{0020}me...\"Lately\u{0020}I've\u{0020}been\u{0020}hearing\u{0020}this\u{0020}voice.\u{0020}Who\u{0020}could\u{0020}it\u{0020}be?", "「認めてもらいたい……他の人みたいに……母さんに認めてもらいたい……」お兄ちゃん、最近ね、いつもこんな声が聞こえてくるんだけど……。一体誰だろう……？", "“想要被認同…想要和其他人一樣……被媽媽認同……”哥哥，我最近總是聽到這樣的聲音在耳邊迴響，到底是誰呢？", "0", "“想要被认同…想要和其他人一样……被妈妈认同……”哥哥，我最近总是听到这样的声音在耳边回响，到底是谁呢？", "0", "cv_jiya_16", "0", "0"},
[900012] = {900012, 90000, 53, 5, "1_》_0_0.2", "16", "\"After\u{0020}giving\u{0020}everything\u{0020}up...\u{0020}you\u{0020}can\u{0020}eat\u{0020}without\u{0020}distractions.\u{0020}Eat\u{0020}enough,\u{0020}and\u{0020}soon\u{0020}you'll\u{0020}return\u{0020}to\u{0020}mother...\"\u{0020}Hey,\u{0020}there's\u{0020}another\u{0020}voice!\u{0020}This\u{0020}is...", "「全部捨てたら……遠慮なく食べられるようになる。沢山食べれば、すぐに母さんの所に帰れる……。」お兄ちゃん、また新しい声が……！これって……", "“將一切都捨棄掉之後……就能心無旁騖地進食了，只要進食得足夠多，馬上就能回到母親身邊了……。”哥哥，好像又有新的聲音出現了！這是……", "0", "“将一切都舍弃掉之后……就能心无旁骛地进食了，只要进食得足够多，马上就能回到母亲身边了……。”哥哥，好像又有新的声音出现了！这是……", "0", "cv_jiya_17", "0", "0"},
[900013] = {900013, 90000, 34, 26, "0", "1", "Hiya,\u{0020}welcome\u{0020}back.", "お兄ちゃん、お帰り…。", "哥哥，歡迎回來~", "0", "哥哥，欢迎回来~", "0", "cv_jiya_2", "0", "0"},
[900014] = {900014, 90000, 54, 26, "0", "2", "Welcome\u{0020}back,\u{0020}Navigator.\u{0020}Let's\u{0020}give\u{0020}it\u{0020}our\u{0020}all\u{0020}today!", "お帰り、ナビゲーター。今日も一緒に頑張ろうね。", "歡迎回來，領航，今天也一起努力吧。", "0", "欢迎回来，领航，今天也一起努力吧。", "0", "cv_jiya_3", "0", "0"},
[900015] = {900015, 90000, 35, 27, "0", "17", "Let's\u{0020}continue\u{0020}our\u{0020}story.", "私たちの物語を続けよう。", "繼續我們的故事吧。", "0", "继续我们的故事吧。", "0", "cv_jiya_18", "0", "0"},
[900016] = {900016, 90000, 36, 28, "0", "18", "Safe\u{0020}travels\u{0020}to\u{0020}you.", "万事順調でありますように。", "祝您一帆風順。", "0", "祝您一帆风顺。", "0", "cv_jiya_19", "0", "0"},
[900017] = {900017, 90000, 37, 29, "0", "19", "Be\u{0020}kind\u{0020}to\u{0020}everyone.", "みんなと仲よくしよう。", "和大家好好相處吧。", "0", "和大家好好相处吧。", "0", "cv_jiya_20", "0", "0"},
[900018] = {900018, 90000, 38, 30, "0", "20", "It's\u{0020}time\u{0020}to\u{0020}recruit\u{0020}new\u{0020}people.", "人手を増やさないとね。", "需要補充人手了吧。", "0", "需要补充人手了吧。", "0", "cv_jiya_21", "0", "0"},
[900019] = {900019, 90000, 39, 31, "0", "21", "Come\u{0020}and\u{0020}restock\u{0020}your\u{0020}gear.", "装備を補充しよう。", "來補充裝備吧。", "0", "来补充装备吧。", "0", "cv_jiya_22", "0", "0"},
[900020] = {900020, 90000, 40, 32, "0", "22", "Let's\u{0020}go\u{0020}shopping\u{0020}together.", "一緒におかいものに行こう。", "一起去採購吧。", "0", "一起去采购吧。", "0", "cv_jiya_23", "0", "0"},
