[900022] = {900022, 90000, 42, 34, "0", "24", "Want\u{0020}to\u{0020}change\u{0020}the\u{0020}settings?", "設定を変更するの？", "要變更設定嗎？", "0", "要变更设置吗？", "0", "cv_jiya_25", "0", "0"},
