[900025] = {900025, 90000, 45, 37, "0", "27", "Need\u{0020}confirmation?", "確認するの？", "要確認一下嗎？", "0", "要确认一下吗？", "0", "cv_jiya_28", "0", "0"},
[900026] = {900026, 90000, 55, 4, "13_=_1_0.5", "4", "There's\u{0020}a\u{0020}lot\u{0020}of\u{0020}excitement\u{0020}over\u{0020}there.\u{0020}Is\u{0020}something\u{0020}going\u{0020}on?", "あそこ、凄く賑やかだね。何かイベントでも開催されてるのかな。", "那邊好熱鬧啊，是在舉辦什麼活動嗎？", "0", "那边好热闹啊，是在举办什么活动吗？", "0", "cv_jiya_5", "0", "0"},
[900027] = {900027, 90000, 56, 4, "13_=_1_0.5", "5", "If\u{0020}you're\u{0020}too\u{0020}tired,\u{0020}don't\u{0020}push\u{0020}yourself.", "疲れた時は無理しないでね。", "太累了的話還請不要勉強自己。", "0", "太累了的话还请不要勉强自己。", "0", "cv_jiya_6", "0", "0"},
[900028] = {900028, 90000, 57, 4, "2_《_100_1", "28", "Mmm,\u{0020}you've\u{0020}worked\u{0020}hard\u{0020}today.\u{0020}Thank\u{0020}you.\u{0020}Do\u{0020}you\u{0020}want\u{0020}to\u{0020}take\u{0020}a\u{0020}break?", "わ…！今日のお兄ちゃんいっぱい頑張ってくれたね！お疲れ様、少し休む？", "嗯嗯嗯，今天哥哥也很努力呢，辛苦了，要休息一下嗎？", "0", "嗯嗯嗯，今天哥哥也很努力呢，辛苦了，要休息一下吗？", "0", "cv_jiya_29", "0", "0"},
[900029] = {900029, 90000, 58, 4, "2_《_60_1", "29", "Wow...\u{0020}Did\u{0020}you\u{0020}do\u{0020}all\u{0020}of\u{0020}this\u{0020}in\u{0020}just\u{0020}one\u{0020}day?\u{0020}As\u{0020}expected\u{0020}of\u{0020}you.\u{0020}But\u{0020}are\u{0020}you\u{0020}sure\u{0020}you\u{0020}don't\u{0020}need\u{0020}a\u{0020}break?", "凄い……これ、お兄ちゃんが一日でやったことなの……？さすが！でも、本当に休まなくていいの？", "好厲害…這是哥哥在一天之內做到的嗎……不愧是您啊。不過真的不用休息一下嗎？", "0", "好厉害…这是哥哥在一天之内做到的吗……不愧是您啊。不过真的不用休息一下吗？", "0", "cv_jiya_30", "0", "0"},
[900030] = {900030, 90000, 59, 4, "2_《_20_2", "30", "I'd\u{0020}love\u{0020}to\u{0020}compliment\u{0020}your\u{0020}efficiency\u{0020}today,\u{0020}but\u{0020}please\u{0020}take\u{0020}care\u{0020}of\u{0020}yourself!\u{0020}Even\u{0020}a\u{0020}short\u{0020}rest\u{0020}would\u{0020}help.", "すごく効率的だし、拍手したいところだけど……くれぐれも体に気をつけてね！少し休もう？", "雖然非常想誇獎您這一天的效率，但是……還請您一定要注意自己的身體啊！稍微休息一下吧。", "0", "虽然非常想夸奖您这一天的效率，但是……还请您一定要注意自己的身体啊！稍微休息一下吧。", "0", "cv_jiya_31", "0", "0"},
[900031] = {900031, 90000, 60, 55, "3_=_50_1", "31", "The\u{0020}recording\u{0020}device\u{0020}is\u{0020}down\u{0020}to\u{0020}50%\u{0020}power.\u{0020}Half\u{0020}is\u{0020}used\u{0020}up.", "記録装置のバッテリーがあと５０％くらいしか残ってないの。もう半分使っちゃったよ。", "記錄裝置的電量還剩下50％，已經用掉一半了啊。", "0", "记录装置的电量还剩下50％，已经用掉一半了啊。", "0", "cv_jiya_32", "0", "0"},
[900032] = {900032, 90000, 61, 56, "3_=_30_1", "32", "The\u{0020}recording\u{0020}device\u{0020}is\u{0020}down\u{0020}to\u{0020}30%.\u{0020}Don't\u{0020}forget\u{0020}to\u{0020}recharge\u{0020}it\u{0020}soon.", "記録装置のバッテリーがあと３０％くらいだよ。充電を忘れないでね。", "記錄裝置的電量還剩下30％，要記得補充電量啊。", "0", "记录装置的电量还剩下30％，要记得补充电量啊。", "0", "cv_jiya_33", "0", "0"},
[900033] = {900033, 90000, 62, 57, "3_=_10_1", "33", "The\u{0020}recording\u{0020}device\u{0020}is\u{0020}at\u{0020}10%?!\u{0020}If\u{0020}you\u{0020}can't\u{0020}find\u{0020}a\u{0020}charger,\u{0020}you\u{0020}should\u{0020}pause\u{0020}the\u{0020}recording.\u{0020}It\u{0020}could\u{0020}be\u{0020}risky\u{0020}otherwise.", "記録装置のバッテリーがあと……１０％！？充電装置って手元にある？なかったら一旦記録を中止しよう。緊急事態が起きたら大変なことになっちゃうから。", "記錄裝置的電量還剩下……10％？！如果周圍沒有充電裝置的話，哥哥還是先暫停記錄吧，否則遇上緊急情況就糟糕了。", "0", "记录装置的电量还剩下……10％？！如果周围没有充电装置的话，哥哥还是先暂停记录吧，否则遇上紧急情况就糟糕了。", "0", "cv_jiya_34", "0", "0"},
[900034] = {900034, 90000, 63, 58, "4_=_9_1", "55", "It's\u{0020}9\u{0020}AM.\u{0020}Did\u{0020}you\u{0020}have\u{0020}a\u{0020}good\u{0020}breakfast?", "うふふ、朝９時だよ。お兄ちゃん、朝ご飯はちゃんと食べた？", "呼呼，現在是早上9點喔，哥哥早飯有好好吃過嗎？", "0", "呼呼，现在是早上9点哦，哥哥早饭有好好吃过吗？", "0", "cv_jiya_56", "0", "0"},
[900035] = {900035, 90000, 64, 59, "4_=_12_1", "56", "Wow,\u{0020}it's\u{0020}already\u{0020}noon!\u{0020}Half\u{0020}the\u{0020}day\u{0020}has\u{0020}gone\u{0020}by.", "わっ！もう１２時！今日はもう、半分も終わっちゃったんだ。", "嗚哇，已經到了12點了呢，一天已經過去一半了啊。", "0", "呜哇，已经到了12点了呢，一天已经过去一半了啊。", "0", "cv_jiya_57", "0", "0"},
[900036] = {900036, 90000, 65, 60, "4_=_15_1", "57", "It's\u{0020}3\u{0020}PM.\u{0020}I've\u{0020}made\u{0020}some\u{0020}afternoon\u{0020}tea.\u{0020}Let's\u{0020}enjoy\u{0020}it\u{0020}together.", "15時になったね、アフタヌーンティーを用意したの、一緒に飲もうよ～お兄ちゃん。", "已經到3點啦，我準備了下午茶，一起來喝吧～哥哥。", "0", "已经到3点啦，我准备了下午茶，一起来喝吧～哥哥。", "0", "cv_jiya_61", "0", "0"},
[900037] = {900037, 90000, 66, 61, "4_=_18_1", "58", "It's\u{0020}6\u{0020}PM.\u{0020}The\u{0020}sun\u{0020}has\u{0020}set\u{0020}before\u{0020}we\u{0020}realized\u{0020}it.\u{0020}Shall\u{0020}we\u{0020}have\u{0020}dinner\u{0020}together?", "18時になったよ。もう日が暮れちゃった。お兄ちゃん、一緒に晩御飯を食べる？", "6點鐘，不知不覺太陽已經下山了呢，要一起吃晚飯嗎哥哥。", "0", "6点钟，不知不觉太阳已经下山了呢，要一起吃晚饭吗哥哥。", "0", "cv_jiya_58", "0", "0"},
[900038] = {900038, 90000, 67, 62, "4_=_22_1", "59", "It's\u{0020}10\u{0020}PM.\u{0020}Only\u{0020}two\u{0020}hours\u{0020}left\u{0020}before\u{0020}the\u{0020}day\u{0020}ends.\u{0020}Time\u{0020}sure\u{0020}flies.", "２２時になったよ。今日もあと2時間で終わっちゃう…。時間が経つのって本当にはやいね。", "10點鐘了，還有兩個小時今天就要過去了呢，時間過得真快啊。", "0", "10点钟了，还有两个小时今天就要过去了呢，时间过得真快啊。", "0", "cv_jiya_59", "0", "0"},
[900039] = {900039, 90000, 68, 63, "4_=_24_1", "60", "It's\u{0020}midnight.\u{0020}You've\u{0020}worked\u{0020}hard.\u{0020}Today\u{0020}is\u{0020}over.\u{0020}But\u{0020}if\u{0020}you\u{0020}still\u{0020}have\u{0020}work\u{0020}to\u{0020}finish,\u{0020}Jiya\u{0020}will\u{0020}stay\u{0020}with\u{0020}you.\u{0020}Just...\u{0020}please\u{0020}look\u{0020}after\u{0020}your\u{0020}health.", "もう２４時だよ。お疲れ様。今日はもう、終わっちゃったね。もしまだ終わってないことがあるなら付き合うよ。ずっとお兄ちゃんのそばにいるから。でも……体に気をつけて、無理しないようにね。", "已經12點了，辛苦了，今天已經過去了喔。不過如果哥哥還有沒處理完的事情的話，吉雅也會一直陪著您的。只是…還請您一定要注意自己的身體。", "0", "已经12点了，辛苦了，今天已经过去了哦。不过如果哥哥还有没处理完的事情的话，吉雅也会一直陪着您的。只是…还请您一定要注意自己的身体。", "0", "cv_jiya_60", "0", "0"},
[900040] = {900040, 90000, 69, 39, "0", "34", "We've\u{0020}connected\u{0020}to\u{0020}the\u{0020}purchasing\u{0020}center.\u{0020}Let's\u{0020}pick\u{0020}out\u{0020}supplies\u{0020}together.", "もうショッピングセンターに繋がっているよ。一緒に必要な物資を選ぼう、お兄ちゃん。", "已經連接上採購中心了，一起挑選要買的物資吧，哥哥。", "0", "已经连接上采购中心了，一起挑选要买的物资吧，哥哥。", "0", "cv_jiya_35", "0", "0"},
[900041] = {900041, 90000, 70, 39, "0", "35", "We\u{0020}should\u{0020}check\u{0020}for\u{0020}any\u{0020}new\u{0020}limited\u{0020}items.\u{0020}Some\u{0020}things\u{0020}just\u{0020}fly\u{0020}off\u{0020}the\u{0020}shelves,\u{0020}but\u{0020}we\u{0020}can't\u{0020}just\u{0020}buy\u{0020}everything\u{0020}impulsively.", "えーと、新しい購入制限品が入荷したかどうか、ちゃんと確認しないと。時間になったら撤去される物もあるから。っていっても、なんでもかんでも買うわけにはいかないよね…。", "嗯嗯，得好好確認有沒有新的限購品上架才行啊。有些東西過了時間就會下架，但是也不能就因為這樣就亂買一通。", "0", "嗯嗯，得好好确认有没有新的限购品上架才行啊。有些东西过了时间就会下架，但是也不能就因为这样就乱买一通。", "0", "cv_jiya_36", "0", "0"},
[900042] = {900042, 90000, 71, 39, "0", "36", "Don't\u{0020}worry.\u{0020}Let's\u{0020}choose\u{0020}slowly\u{0020}and\u{0020}wisely.\u{0020}After\u{0020}all,\u{0020}this\u{0020}is\u{0020}all\u{0020}from\u{0020}the\u{0020}hard-earned\u{0020}funds\u{0020}you\u{0020}saved.\u{0020}We\u{0020}can't\u{0020}waste\u{0020}it.", "ゆっくりでいいよ。必要な商品をゆっくり選ぼう。お兄ちゃんが頑張って貯めた資金だから、無駄遣いはしたくないの。", "不用著急喔，我們還是慢慢挑選自己需要的商品吧。畢竟是哥哥辛苦攢下來的資金，絕對不能浪費啊。", "0", "不用着急哦，我们还是慢慢挑选自己需要的商品吧。毕竟是哥哥辛苦攒下来的资金，绝对不能浪费啊。", "0", "cv_jiya_37", "0", "0"},
[900043] = {900043, 90000, 72, 40, "0", "37", "Have\u{0020}you\u{0020}made\u{0020}your\u{0020}decision\u{0020}yet?", "もう選んだ？お兄ちゃん。", "已經選好了嗎？哥哥。", "0", "已经选好了吗？哥哥。", "0", "cv_jiya_38", "0", "0"},
[900044] = {900044, 90000, 73, 40, "0", "38", "Oh...\u{0020}Th...\u{0020}That\u{0020}thing\u{0020}in\u{0020}the\u{0020}shopping\u{0020}cart?\u{0020}I\u{0020}must've\u{0020}added\u{0020}it\u{0020}by\u{0020}accident...\u{0020}I...\u{0020}I\u{0020}wasn't\u{0020}really\u{0020}looking\u{0020}at\u{0020}romance\u{0020}novels...\u{0020}Huh?\u{0020}You\u{0020}say\u{0020}it's\u{0020}normal\u{0020}for\u{0020}girls\u{0020}my\u{0020}age\u{0020}to\u{0020}like\u{0020}these?...\u{0020}N-no,\u{0020}it's\u{0020}not\u{0020}like\u{0020}that...\u{0020}You're\u{0020}so\u{0020}silly...", "あっ……あ、あれは間違ってカートに入れちゃって……わ、私、恋愛小説になんて興味ないもん……！え？年頃の女の子は普通にこういうのを読んでる……？ち、違うよ！お兄ちゃんのばか……！", "啊……那…那個可能是我不小心添加到購物車裡的……我…我才…才沒有對戀愛小說產生興趣……欸？您說我這個年紀的女孩愛看這個是正常的？……才不是啦……笨蛋哥哥……", "0", "啊……那…那个可能是我不小心添加到购物车里的……我…我才…才没有对恋爱小说产生兴趣……哎？您说我这个年纪的女孩爱看这个是正常的？……才不是啦……笨蛋哥哥……", "0", "cv_jiya_39", "0", "0"},
[900045] = {900045, 90000, 74, 40, "0", "39", "I\u{0020}heard\u{0020}there's\u{0020}a\u{0020}job\u{0020}at\u{0020}the\u{0020}mall\u{0020}called\u{0020}\"shopping\u{0020}guide.\"\u{0020}They\u{0020}help\u{0020}guests\u{0020}with\u{0020}their\u{0020}lists\u{0020}and\u{0020}find\u{0020}what\u{0020}they\u{0020}need.", "外のショップにはショッピングアドバイザーって店員さんがいるんだって。お客さんのためにショッピングリストを作ったり、必要な物を探してくれるらしいよ。", "聽說外面的商城中會有導購這個職位。他們會幫助客人規劃購物清單，也能幫助客人們準確找到自己需要的東西。", "0", "听说外面的商城中会有导购这个职位。他们会帮助客人规划购物清单，也能帮助客人们准确找到自己需要的东西。", "0", "cv_jiya_40", "0", "0"},
[900046] = {900046, 90000, 75, 40, "0", "40", "Thanks\u{0020}to\u{0020}e-stores,\u{0020}people\u{0020}don't\u{0020}have\u{0020}to\u{0020}go\u{0020}out.\u{0020}But\u{0020}if\u{0020}I\u{0020}ever\u{0020}get\u{0020}the\u{0020}chance,\u{0020}I'd\u{0020}love\u{0020}to\u{0020}visit\u{0020}a\u{0020}real\u{0020}market.", "オンラインショップのお陰で、出掛けなくても買い物できるもんね。でも、いつか本物の市場にも行ってみたいなぁ。", "多虧了電子商店的普及，大家也就免去出門的麻煩了。不過如果有機會的話，我真想去線下的市場逛一逛啊。", "0", "多亏了电子商店的普及，大家也就免去出门的麻烦了。不过如果有机会的话，我真想去线下的市场逛一逛啊。", "0", "cv_jiya_41", "0", "0"},
[900047] = {900047, 90000, 76, 40, "0", "41", "How\u{0020}about\u{0020}this?\u{0020}It\u{0020}might\u{0020}be\u{0020}helpful\u{0020}in\u{0020}battle.", "お兄ちゃん、これはどうかな？戦いの時に使えるかも。", "哥哥，這個如何呢？我覺得說不定能在戰鬥中榜上忙呢。", "0", "哥哥，这个如何呢？我觉得说不定能在战斗中榜上忙呢。", "0", "cv_jiya_42", "0", "0"},
[900048] = {900048, 90000, 77, 41, "0", "42", "These\u{0020}are\u{0020}all\u{0020}essentials.", "ここにあるのは全部必要な物だね。", "這些都是必需品呢。", "0", "这些都是必需品呢。", "0", "cv_jiya_43", "0", "0"},
[900049] = {900049, 90000, 78, 42, "0", "43", "Let's\u{0020}give\u{0020}it\u{0020}our\u{0020}best\u{0020}in\u{0020}the\u{0020}next\u{0020}battle.\u{0020}No\u{0020}matter\u{0020}the\u{0020}outcome,\u{0020}Jiya\u{0020}will\u{0020}always\u{0020}stay\u{0020}by\u{0020}your\u{0020}side.", "じゃあ、これからも頑張ってね！どんな結果になったとしても、ずっとお兄ちゃんのそばにいるから。", "那麼接下來要加油了喔，不過無論結果如何，吉雅都會一直陪在您身邊的。", "0", "那么接下来要加油了哦，不过无论结果如何，吉雅都会一直陪在您身边的。", "0", "cv_jiya_44", "0", "0"},
[900050] = {900050, 90000, 79, 43, "0", "44", "With\u{0020}this,\u{0020}the\u{0020}next\u{0020}fight\u{0020}will\u{0020}be\u{0020}much\u{0020}easier.", "ふむ…これくらいあれば、これからの戦いも楽になる、かな？", "嗯嗯，有了這些接下來的戰鬥會輕鬆不少吧。", "0", "嗯嗯，有了这些接下来的战斗会轻松不少吧。", "0", "cv_jiya_45", "0", "0"},
[900051] = {900051, 90000, 80, 44, "0", "45", "It's\u{0020}a\u{0020}rare\u{0020}item.\u{0020}Use\u{0020}it\u{0020}wisely.", "貴重品だよ。お買い物はちゃんと計画的に、ね。", "是貴重品呢，要記得理性消費喔。", "0", "是贵重品呢，要记得理性消费哦。", "0", "cv_jiya_46", "0", "0"},
[900052] = {900052, 90000, 81, 45, "0", "46", "Slow\u{0020}and\u{0020}steady\u{0020}wins\u{0020}the\u{0020}race...\u{0020}That's\u{0020}the\u{0020}truth.", "少しずつだけど、長く続いていくんだね。", "細水長流……是這個道理呢。", "0", "细水长流……是这个道理呢。", "0", "cv_jiya_47", "0", "0"},
[900053] = {900053, 90000, 82, 46, "0", "47", "We\u{0020}need\u{0020}to\u{0020}be\u{0020}cautious\u{0020}with\u{0020}our\u{0020}calculations.", "うふふ、ちゃんと細かく計算しないとね。", "呼呼，要精打細算才行啊。", "0", "呼呼，要精打细算才行啊。", "0", "cv_jiya_48", "0", "0"},
[900054] = {900054, 90000, 83, 47, "0", "48", "Let's\u{0020}wrap\u{0020}it\u{0020}up\u{0020}here.\u{0020}We're\u{0020}exiting\u{0020}the\u{0020}purchasing\u{0020}interface.", "とりあえずここまでにしよっか、…お買い物のところから離れるよ。", "暫時就到這裡吧~要退出採購介面了喔。", "0", "暂时就到这里吧~要退出采购界面了哦。", "0", "cv_jiya_49", "0", "0"},
