[900057] = {900057, 90000, 86, 50, "0", "51", "Wow!\u{0020}It's\u{0020}already\u{0020}been\u{0020}a\u{0020}week.\u{0020}What\u{0020}will\u{0020}the\u{0020}reward\u{0020}be\u{0020}this\u{0020}time?", "うふふ…もう一週間だね。今回のご褒美は何かな？", "呼呼！已經一週了喔，這次的獎勵會是什麼呢？", "0", "呼呼！已经一周了哦，这次的奖励会是什么呢？", "0", "cv_jiya_52", "0", "0"},
[900058] = {900058, 90000, 87, 51, "0", "52", "Time\u{0020}flies.\u{0020}Half\u{0020}a\u{0020}month\u{0020}has\u{0020}passed\u{0020}without\u{0020}us\u{0020}noticing.", "すごーい…あっという間に半月経っちゃった。", "真好啊~不知不覺已經過去半個月了呢~", "0", "真好啊~不知不觉已经过去半个月了呢~", "0", "cv_jiya_53", "0", "0"},
[900059] = {900059, 90000, 88, 52, "0", "53", "Huh?\u{0020}It's\u{0020}almost\u{0020}over?\u{0020}Wow,\u{0020}that's\u{0020}amazing!\u{0020}You're\u{0020}about\u{0020}to\u{0020}claim\u{0020}that\u{0020}final\u{0020}reward,\u{0020}right?!", "え？もうすぐ終わるの？凄い！もうちょっとであの最後のご褒美がもらえるんだ。", "欸？已經快結束了嗎？好——厲——害——！馬上就能拿到那個最終獎勵了吧？！", "0", "哎？已经快结束了吗？好——厉——害——！马上就能拿到那个最终奖励了吧？！", "0", "cv_jiya_54", "0", "0"},
[900060] = {900060, 90000, 89, 53, "0", "0", "Ba-da-bing!\u{0020}You've\u{0020}done\u{0020}well.\u{0020}Sign-in\u{0020}for\u{0020}this\u{0020}period\u{0020}is\u{0020}complete.", "じゃじゃじゃじゃーん！お疲れ様、お兄ちゃん。今期のログインイベント、終了！", "當當當當！辛苦啦，這一期的簽到已經結束了喔，哥哥~", "0", "当当当当！辛苦啦，这一期的签到已经结束了哦，哥哥~", "0", "cv_jiya_55", "0", "0"},
