[9000500] = {9000500, 90005, 97, 0, "0", "idle", "If\u{0020}you\u{0020}pick\u{0020}up\u{0020}anything\u{0020}strange\u{0020}along\u{0020}your\u{0020}journey,\u{0020}come\u{0020}find\u{0020}me!\u{0020}I'll\u{0020}trade\u{0020}you\u{0020}something\u{0020}good.\u{0020}We've\u{0020}prepared\u{0020}a\u{0020}lot,\u{0020}and\u{0020}you'll\u{0020}love\u{0020}it!", "旅の途中で変なものを拾ったら、妾のところで補給品を交換しに来るとよい。ふんふん、準備するのにけっこう時間を掛ったから、汝は絶対驚くぞ!", "如果在旅途中有撿到什麼奇怪東西的話，可以到吾這裡來交換補給品哦。哼哼，我們可是準備了很久的，絕對會讓你大吃一驚！", "0", "如果在旅途中有捡到什么奇怪东西的话，可以到吾这里来交换补给品哦。哼哼，我们可是准备了很久的，绝对会让你大吃一惊！", "0", "shop_sikadi_1", "0", "0"},
[9000501] = {9000501, 90005, 97, 0, "0", "idle2", "Welcome,\u{0020}adventurer,\u{0020}to\u{0020}the\u{0020}witch\u{0020}Dorothy's\u{0020}hut!\u{0020}Though\u{0020}Dorothy\u{0020}isn't\u{0020}in\u{0020}right\u{0020}now,\u{0020}tell\u{0020}me\u{0020}what\u{0020}you\u{0020}need.", "ここは魔女ドロシーの小屋、歓迎するぞ、冒険者！ああでも今ドロシーはここにいないから、何か欲しいものがあったら妾に言ってくれよ!", "這裡是魔女桃樂西的小屋，歡迎你遠道而來的冒險者。不過桃樂西現在不在這裡，有什麼需求的話就和吾講吧！", "0", "这里是魔女多萝西的小屋，欢迎你远道而来的冒险者。不过多萝西现在不在这里，有什么需求的话就和吾讲吧！", "0", "shop_sikadi_2", "0", "0"},
[9000502] = {9000502, 90005, 98, 0, "0", "shy1.1", "Oh\u{0020}–\u{0020}since\u{0020}you're\u{0020}a\u{0020}citizen\u{0020}of\u{0020}Dunscaith,\u{0020}there's\u{0020}a\u{0020}special\u{0020}discount\u{0020}just\u{0020}for\u{0020}you!", "うむ、影の国の住人ナビゲーターよ、特別にサービスしてやろう！", "嗯——既然領航是影之國的國民，那就給領航一個特別優惠好了！", "0", "嗯——既然领航是影之国的国民，那就给领航一个特别优惠好了！", "0", "shop_sikadi_3", "0", "0"},
[9000503] = {9000503, 90005, 97, 0, "0", "shy1.2", "The\u{0020}shop's\u{0020}closing\u{0020}soon,\u{0020}Navigator.\u{0020}Once\u{0020}it's\u{0020}shut,\u{0020}how\u{0020}about\u{0020}we\u{0020}take\u{0020}a\u{0020}stroll\u{0020}along\u{0020}the\u{0020}beach?", "このショップももうすぐ閉店だ。ナビゲーター、そのあとは砂浜で散歩しようか？", "小店馬上就要關門了。領航，等關店了之後，陪吾去沙灘上散一步吧？", "0", "小店马上就要关门了。领航，等关店了之后，陪吾去沙滩上散一步吧？", "0", "shop_sikadi_4", "0", "0"},
[9000504] = {9000504, 90005, 97, 0, "0", "happy", "\"The\u{0020}Chronicles\u{0020}Side\u{0020}Story\u{0020}-\u{0020}Records\u{0020}of\u{0020}the\u{0020}Dream\u{0020}World\"\u{0020}was\u{0020}a\u{0020}hit!\u{0020}And\u{0020}I\u{0020}was\u{0020}the\u{0020}hero\u{0020}who\u{0020}saved\u{0020}the\u{0020}world,\u{0020}Navigator.", "「クロニクル外伝ーー夢の見聞録」、公演大成功！妾こそが世界を救った英雄だぞ！", "《編年史外傳——夢世界見聞錄》公演大成功！吾是拯救了世界的英雄哦，領航。", "0", "《编年史外传——梦世界见闻录》公演大成功！吾是拯救了世界的英雄哦，领航。", "0", "shop_sikadi_5", "0", "0"},
[9000505] = {9000505, 90005, 97, 0, "0", "happy2", "I've\u{0020}received\u{0020}many\u{0020}gifts\u{0020}from\u{0020}the\u{0020}sea,\u{0020}Navigator!\u{0020}Xiaoxi\u{0020}and\u{0020}the\u{0020}others\u{0020}are\u{0020}already\u{0020}preparing\u{0020}the\u{0020}ingredients.\u{0020}Let's\u{0020}feast\u{0020}today!", "ナビゲーター、砂浜たっくさん海の贄が貰ったぞ！希ちゃんたちはもう捌いているよ、今日のご飯はそれにしよう！", "領航，吾在沙灘上收到了很多海之祭品哦！小希她們已經在處理食材了，今天就吃這個吧！", "0", "领航，吾在沙滩上收到了很多海之祭品哦！小希她们已经在处理食材了，今天就吃这个吧！", "0", "shop_sikadi_6", "0", "0"},
[9000506] = {9000506, 90005, 98, 0, "0", "jingya", "Need\u{0020}something\u{0020}else,\u{0020}Navigator?\u{0020}I'll\u{0020}check\u{0020}the\u{0020}inventory\u{0020}for\u{0020}you.", "ナビゲーターはほかに何か欲しいものあるか？妾が在庫を見てくるぞ。", "領航還有什麼想要的嗎？吾去看看庫存裡有沒有。", "0", "领航还有什么想要的吗？吾去看看库存里有没有。", "0", "shop_sikadi_7", "0", "0"},
[9000507] = {9000507, 90005, 98, 0, "0", "normal", "I've\u{0020}gathered\u{0020}many\u{0020}treasures,\u{0020}but\u{0020}they're\u{0020}not\u{0020}free\u{0020}–\u{0020}you'll\u{0020}need\u{0020}to\u{0020}earn\u{0020}them,\u{0020}Navigator!\u{0020}Show\u{0020}me\u{0020}what\u{0020}you've\u{0020}got!", "沢山のお宝を用意してるから、ナビゲーターも頑張って交換しよう！ファイトだぞ！", "吾準備了很多珍寶！要用領航的努力來交換哦！加油——領航！", "0", "吾准备了很多珍宝！要用领航的努力来交换哦！加油——领航！", "0", "shop_sikadi_8", "0", "0"},
[9000600] = {9000600, 90006, 97, 0, "0", "idle", "Navigator,\u{0020}why\u{0020}were\u{0020}you\u{0020}looking\u{0020}for\u{0020}me,\u{0020}meow?\u{0020}I'm\u{0020}free\u{0020}now,\u{0020}we\u{0020}can\u{0020}chat\u{0020}all\u{0020}day.", "0", "幹嘛喵，領航你找芙露露有事喵？芙露露現在不忙，可以陪你聊很久很久。", "0", "0", "0", "shop_fururu_1", "0", "0"},
[9000601] = {9000601, 90006, 97, 0, "0", "kaixin", "This\u{0020}morning,\u{0020}someone\u{0020}gave\u{0020}me\u{0020}an\u{0020}extra\u{0020}egg\u{0020}for\u{0020}breakfast,\u{0020}saying\u{0020}it\u{0020}was\u{0020}for\u{0020}me\u{0020}to\u{0020}grow\u{0020}taller.\u{0020}But\u{0020}I\u{0020}was\u{0020}already\u{0020}full,\u{0020}so\u{0020}I\u{0020}saved\u{0020}it\u{0020}for\u{0020}you,\u{0020}meow.\u{0020}Here.", "0", "今天早上打早飯的時候被人多送了一個雞蛋，說是讓芙露露長高些什麼的。不過，芙露露當時已經吃飽了，所以就偷偷留給你了喵，喏。", "0", "0", "0", "shop_fururu_2", "0", "0"},
[9000602] = {9000602, 90006, 98, 0, "0", "kaixin", "Sorry,\u{0020}I'll\u{0020}be\u{0020}right\u{0020}there,\u{0020}meow!", "0", "抱歉，馬上就來喵！", "0", "0", "0", "shop_fururu_3", "0", "0"},
[9000603] = {9000603, 90006, 97, 0, "0", "idle2", "We\u{0020}meet\u{0020}again,\u{0020}meow.\u{0020}What\u{0020}are\u{0020}you\u{0020}starting\u{0020}the\u{0020}day\u{0020}with,\u{0020}Navigator?", "0", "又見面了喵，領航今天要從哪里開始忙起喵？", "0", "0", "0", "shop_fururu_4", "0", "0"},
[9000604] = {9000604, 90006, 98, 0, "0", "kaixin", "Looks\u{0020}like\u{0020}something\u{0020}popped\u{0020}up,\u{0020}meow.", "0", "好像有什麼東西冒出來了喵。", "0", "0", "0", "shop_fururu_5", "0", "0"},
[9000700] = {9000700, 90007, 97, 0, "0", "idle", "Ah,\u{0020}there\u{0020}you\u{0020}are!\u{0020}Have\u{0020}a\u{0020}seat,\u{0020}have\u{0020}a\u{0020}seat!\u{0020}Just,\u{0020}uh,\u{0020}not\u{0020}on\u{0020}me,\u{0020}okay?", "0", "哦，你來了啊～隨便坐，隨便坐，只要別坐到我身上就好。", "0", "0", "0", "shop_jing_1", "0", "0"},
[9000701] = {9000701, 90007, 97, 0, "0", "jingya", "Huh?\u{0020}Back\u{0020}again?\u{0020}And\u{0020}you\u{0020}only\u{0020}brought\u{0020}this\u{0020}little\u{0020}bit\u{0020}of\u{0020}food...?", "0", "哎？你又來了啊……什麼嗎，居然只帶了這點吃的……", "0", "0", "0", "shop_jing_2", "0", "0"},
[9000702] = {9000702, 90007, 98, 0, "0", "tiaopi", "Hehe,\u{0020}if\u{0020}my\u{0020}sister\u{0020}catches\u{0020}me\u{0020}lounging\u{0020}around\u{0020}like\u{0020}this,\u{0020}she's\u{0020}gonna\u{0020}be\u{0020}mad\u{0020}at\u{0020}me\u{0020}again.", "0", "呼呼呼，如果被姐姐看到我在這裏偷懶估計又會惹她生氣了吧。", "0", "0", "0", "shop_jing_3", "0", "0"},
[9000703] = {9000703, 90007, 97, 0, "0", "idle", "Ugh,\u{0020}holding\u{0020}this\u{0020}pose\u{0020}is\u{0020}exhausting...\u{0020}Can\u{0020}you\u{0020}take\u{0020}over\u{0020}for\u{0020}me?", "0", "一直保持這個姿勢好累啊……麻煩可以把我給換下去嗎？", "0", "0", "0", "shop_jing_4", "0", "0"},
[9000704] = {9000704, 90007, 98, 0, "0", "tushe", "My\u{0020}dream?\u{0020}Creating\u{0020}a\u{0020}world\u{0020}where\u{0020}lazybones\u{0020}and\u{0020}slackers\u{0020}like\u{0020}me\u{0020}can\u{0020}be\u{0020}happy!\u{0020}But\u{0020}I'll\u{0020}leave\u{0020}the\u{0020}actual\u{0020}hard\u{0020}work\u{0020}to\u{0020}my\u{0020}sister,\u{0020}of\u{0020}course.", "0", "夢想是創造出讓懶人和廢材能夠快樂生活的世界！當然，這只是夢想而已，真正落實起來還是交給姐姐吧~", "0", "0", "0", "shop_jing_5", "0", "0"},
[9000800] = {9000800, 90008, 2, 0, "0", "idle", "Huh,\u{0020}is\u{0020}it\u{0020}that\u{0020}time\u{0020}already?\u{0020}Well,\u{0020}the\u{0020}real\u{0020}\"showtime\"\u{0020}happens\u{0020}in\u{0020}seven\u{0020}days.", "0", "已經到了這個時間了？那就敬請七天後的“show\u{0020}time”吧。", "0", "0", "0", "side1_starry_001", "0", "0"},
[9000801] = {9000801, 90008, 2, 0, "0", "kaixin", "Hehe,\u{0020}day\u{0020}two\u{0020}now...\u{0020}What's\u{0020}coming\u{0020}next?\u{0020}I\u{0020}can't\u{0020}wait\u{0020}to\u{0020}see!", "0", "哼哼哼~現在是第二天~之後會發生什麼呢？真期待啊。", "0", "0", "0", "side1_starry_002", "0", "0"},
