[9000804] = {9000804, 90008, 2, 0, "0", "kaixin", "Is\u{0020}it\u{0020}not\u{0020}ready\u{0020}yet?\u{0020}Ugh,\u{0020}my\u{0020}patience\u{0020}is\u{0020}wearing\u{0020}thin.", "0", "還沒好嗎？誒——我的耐心都快被消磨殆盡啦。", "0", "0", "0", "side1_starry_005", "0", "0"},
[9000805] = {9000805, 90008, 2, 0, "0", "idle2", "Patience,\u{0020}patience...\u{0020}I\u{0020}can't\u{0020}lose\u{0020}my\u{0020}cool.\u{0020}The\u{0020}day\u{0020}after\u{0020}tomorrow\u{0020}is\u{0020}important.", "0", "忍耐，我要忍耐，可不能失態了，後天可是很重要的日子。", "0", "0", "0", "side1_starry_006", "0", "0"},
[9000806] = {9000806, 90008, 2, 0, "0", "kaixin", "Tomorrow's\u{0020}the\u{0020}big\u{0020}day!\u{0020}I\u{0020}need\u{0020}to\u{0020}sleep\u{0020}early\u{0020}tonight...\u{0020}or\u{0020}I'll\u{0020}be\u{0020}too\u{0020}hyped\u{0020}to\u{0020}sleep\u{0020}at\u{0020}all!", "0", "明天就要出發啦，得早點睡才行……不然就要興奮得睡不著了！", "0", "0", "0", "side1_starry_007", "0", "0"},
[9000807] = {9000807, 90008, 97, 0, "0", "idle", "During\u{0020}past\u{0020}training,\u{0020}there\u{0020}were\u{0020}a\u{0020}few\u{0020}times\u{0020}I\u{0020}shrank\u{0020}down\u{0020}halfway\u{0020}through\u{0020}gigantification...\u{0020}So\u{0020}embarrassing\u{0020}now\u{0020}that\u{0020}I\u{0020}think\u{0020}about\u{0020}it!", "0", "以前訓練的時候，有過好幾次中途就解除巨大化的經歷，現在想起來可真是尷尬啊……", "0", "0", "0", "side1_starry_008", "0", "0"},
[9000808] = {9000808, 90008, 97, 0, "0", "kaixin", "Ugh,\u{0020}I\u{0020}just\u{0020}know\u{0020}things\u{0020}are\u{0020}going\u{0020}to\u{0020}be\u{0020}troublesome\u{0020}later...\u{0020}But\u{0020}whatever,\u{0020}we'll\u{0020}deal\u{0020}with\u{0020}it\u{0020}when\u{0020}we\u{0020}get\u{0020}there.", "0", "感覺之後盡是些麻煩事……算啦，船到橋頭自然，總會有辦法的。", "0", "0", "0", "side1_starry_009", "0", "0"},
[9000809] = {9000809, 90008, 97, 0, "0", "kaixin", "Logan\u{0020}City\u{0020}holds\u{0020}some\u{0020}of\u{0020}my\u{0020}most\u{0020}precious\u{0020}memories.\u{0020}I'm\u{0020}the\u{0020}only\u{0020}one\u{0020}who\u{0020}remembers\u{0020}them\u{0020}now,\u{0020}so\u{0020}I\u{0020}have\u{0020}to\u{0020}protect\u{0020}it.", "0", "洛根市有我重要的回憶，現在只有我還記得它，所以只能讓我去保護它啦。", "0", "0", "0", "side1_starry_010", "0", "0"},
[9000810] = {9000810, 90008, 97, 0, "0", "idle2", "Oh,\u{0020}by\u{0020}the\u{0020}way,\u{0020}I've\u{0020}been\u{0020}brainstorming\u{0020}some\u{0020}cool\u{0020}lines\u{0020}to\u{0020}shout\u{0020}when\u{0020}I\u{0020}gigantify...\u{0020}Got\u{0020}any\u{0020}ideas?", "0", "對了，我最近在想巨大化時要說的台詞……你有什麼好點子嗎？", "0", "0", "0", "side1_starry_011", "0", "0"},
[9000811] = {9000811, 90008, 98, 0, "0", "kaixin", "This\u{0020}is\u{0020}my\u{0020}teacher's\u{0020}masterpiece.\u{0020}It's\u{0020}not\u{0020}perfect\u{0020}yet,\u{0020}but\u{0020}for\u{0020}drivers,\u{0020}it's\u{0020}groundbreaking.", "0", "這東西是我老師的得意作品，雖然還有缺陷，但對駕駛員來說是劃時代的傑作哦。", "0", "0", "0", "side1_starry_012", "0", "0"},
[9000812] = {9000812, 90008, 98, 0, "0", "idle2", "\"StarChange\"\u{0020}is\u{0020}such\u{0020}a\u{0020}cool\u{0020}name!\u{0020}I\u{0020}just\u{0020}came\u{0020}up\u{0020}with\u{0020}it\u{0020}out\u{0020}of\u{0020}nowhere,\u{0020}but\u{0020}I've\u{0020}grown\u{0020}really\u{0020}fond\u{0020}of\u{0020}it.", "0", "“星變”真是個不錯的名字，雖然是隨便取的，但是我很中意。", "0", "0", "0", "side1_starry_013", "0", "0"},
[9000900] = {9000900, 90009, 97, 0, "0", "jixiao", "Huh,\u{0020}so\u{0020}there's\u{0020}something\u{0020}like\u{0020}this\u{0020}here...\u{0020}That's\u{0020}awesome!\u{0020}Go\u{0020}ahead,\u{0020}get\u{0020}hooked\u{0020}and\u{0020}become\u{0020}a\u{0020}total\u{0020}slacker!", "0", "誒——這裡還有這種玩意啊。真不錯啊，快點上癮變成廢人吧。", "0", "0", "0", "side1_qianqiu_1", "0", "0"},
[9000901] = {9000901, 90009, 97, 0, "0", "laugh", "Play\u{0020}all\u{0020}you\u{0020}want!\u{0020}If\u{0020}you\u{0020}end\u{0020}up\u{0020}addicted\u{0020}to\u{0020}gacha,\u{0020}don't\u{0020}worry—I'll\u{0020}help\u{0020}break\u{0020}you\u{0020}out\u{0020}of\u{0020}the\u{0020}habit.\u{0020}Hahaha!", "0", "放縱地玩吧，要是你成了扭蛋廢人，我會負責把你解決掉的，哈哈哈~", "0", "0", "0", "side1_qianqiu_2", "0", "0"},
[9000902] = {9000902, 90009, 98, 0, "0", "lenku", "Oh\u{0020}wow,\u{0020}this\u{0020}machine\u{0020}really\u{0020}does\u{0020}have\u{0020}everything!", "0", "喔，這機器還真是什麼都有啊。", "0", "0", "0", "side1_qianqiu_3", "0", "0"},
[9000903] = {9000903, 90009, 97, 0, "0", "weixiao", "Wait\u{0020}a\u{0020}second...\u{0020}Could\u{0020}this\u{0020}gacha\u{0020}machine\u{0020}actually\u{0020}be\u{0020}some\u{0020}kind\u{0020}of\u{0020}next-gen\u{0020}kitchen\u{0020}gadget\u{0020}from\u{0020}the\u{0020}22nd\u{0020}century?", "0", "……讓我吃驚了，這台扭蛋機難道是某種方便的二十二世紀料理道具嗎？", "0", "0", "0", "side1_qianqiu_4", "0", "0"},
[9000904] = {9000904, 90009, 98, 0, "0", "haixiu", "Uh...\u{0020}hey,\u{0020}give\u{0020}that\u{0020}to\u{0020}me!\u{0020}Can't\u{0020}you\u{0020}tell\u{0020}how\u{0020}badly\u{0020}I\u{0020}want\u{0020}it,\u{0020}you\u{0020}dummy!", "0", "呃……啊……這……快把它交出來，看不出來我很想要嗎，笨蛋！", "0", "0", "0", "side1_qianqiu_5", "0", "0"},
[9001000] = {9001000, 90010, 97, 0, "0", "haixiu2", "Navigator,\u{0020}it's\u{0020}not\u{0020}good\u{0020}to\u{0020}get\u{0020}too\u{0020}hooked\u{0020}on\u{0020}that\u{0020}machine.\u{0020}My\u{0020}sister\u{0020}says\u{0020}it\u{0020}can\u{0020}make\u{0020}people\u{0020}lose\u{0020}their\u{0020}drive\u{0020}to\u{0020}do\u{0020}anything\u{0020}else.", "0", "領航……太沉迷是不好的，姐姐說過，這台機器會讓人玩物喪志的。", "0", "0", "0", "side1_libeika_1", "0", "0"},
[9001001] = {9001001, 90010, 97, 0, "0", "kaixin", "You're\u{0020}always\u{0020}working\u{0020}so\u{0020}hard,\u{0020}Navigator...\u{0020}I\u{0020}wish\u{0020}I\u{0020}could\u{0020}help\u{0020}more,\u{0020}but\u{0020}all\u{0020}I\u{0020}can\u{0020}do\u{0020}is\u{0020}pray\u{0020}that\u{0020}everything\u{0020}goes\u{0020}smoothly\u{0020}for\u{0020}you.", "0", "領航真辛苦……我幫不上什麼忙，只能在這裡為你工作順利做祈禱了。", "0", "0", "0", "side1_libeika_2", "0", "0"},
[9001002] = {9001002, 90010, 98, 0, "0", "qianxiao", "I've\u{0020}heard\u{0020}that\u{0020}everyone\u{0020}who\u{0020}plays\u{0020}the\u{0020}gacha\u{0020}dreams\u{0020}of\u{0020}hitting\u{0020}the\u{0020}jackpot\u{0020}on\u{0020}their\u{0020}first\u{0020}try...\u{0020}Do\u{0020}you\u{0020}feel\u{0020}the\u{0020}same?", "0", "聽說每一個玩扭蛋機的人都有個一發中大獎的夢想……領航也是嗎？", "0", "0", "0", "side1_libeika_3", "0", "0"},
[9001003] = {9001003, 90010, 97, 0, "0", "haixiu", "So...\u{0020}have\u{0020}you\u{0020}decided\u{0020}who\u{0020}you'll\u{0020}give\u{0020}the\u{0020}prize\u{0020}to\u{0020}if\u{0020}you\u{0020}win?\u{0020}If\u{0020}not,\u{0020}maybe...\u{0020}you\u{0020}could\u{0020}ask\u{0020}me\u{0020}for\u{0020}advice.", "0", "那個……領航有想好要把抽到的獎品給誰嗎？如果沒想好的話，可以……可以找我咨詢哦。", "0", "0", "0", "side1_libeika_4", "0", "0"},
[9001004] = {9001004, 90010, 98, 0, "0", "kaixin", "I\u{0020}don't\u{0020}know\u{0020}what\u{0020}the\u{0020}future\u{0020}holds,\u{0020}but\u{0020}as\u{0020}long\u{0020}as\u{0020}my\u{0020}sister\u{0020}and\u{0020}you,\u{0020}Navigator,\u{0020}are\u{0020}with\u{0020}me,\u{0020}I'm\u{0020}not\u{0020}afraid\u{0020}of\u{0020}anything!", "0", "雖然不知道未來會發生什麼……但只要姐姐和領航在身邊，我就什麼都不怕了！", "0", "0", "0", "side1_libeika_5", "0", "0"},
