[9001006] = {9001006, 90010, 98, 0, "0", "qidao", "Huh...\u{0020}I'm\u{0020}not\u{0020}slacking\u{0020}off!\u{0020}I'm\u{0020}just...\u{0020}a\u{0020}little\u{0020}sleepy...\u{0020}yawn...", "0", "呼……我沒有偷懶，只是……有點困……呼……", "0", "0", "0", "side1_libeika_7", "0", "0"},
