[9001906] = {9001906, 90019, 98, 0, "0", "deyi", "Material\u{0020}needs,\u{0020}spiritual\u{0020}needs—as\u{0020}long\u{0020}as\u{0020}it\u{0020}satisfies\u{0020}one\u{0020}of\u{0020}those,\u{0020}don't\u{0020}hesitate\u{0020}to\u{0020}spend.", "0", "物質需求和精神需求，只要商品滿足了其中一點，就請毫不猶豫地消費吧。", "0", "0", "0", "side2_heli_7", "0", "0"},
