[9002502] = {9002502, 90025, 97, 0, "0", "renzhen", "Are\u{0020}there\u{0020}any\u{0020}details\u{0020}of\u{0020}the\u{0020}task\u{0020}you\u{0020}still\u{0020}don't\u{0020}understand?\u{0020}I'll\u{0020}explain\u{0020}in\u{0020}detail.", "0", "有什麼任務細節還不清楚嗎？我會耐心跟你講的哦。", "0", "0", "0", "1ST_xhixha_3", "0", "0"},
[9002503] = {9002503, 90025, 97, 0, "0", "fuza", "If\u{0020}you\u{0020}need\u{0020}my\u{0020}assistance,\u{0020}just\u{0020}let\u{0020}me\u{0020}know!\u{0020}Right\u{0020}now,\u{0020}I'm\u{0020}like\u{0020}your\u{0020}dedicated\u{0020}secretary.", "0", "需要我協力的話就儘管開口吧~現在的我就相當於領航的秘書呢。", "0", "0", "0", "1ST_xhixha_4", "0", "0"},
[9002504] = {9002504, 90025, 98, 0, "0", "xiao", "Congratulations!\u{0020}Treat\u{0020}yourself\u{0020}to\u{0020}a\u{0020}big\u{0020}meal.\u{0020}If\u{0020}you're\u{0020}reluctant,\u{0020}I'll\u{0020}cover\u{0020}it\u{0020}this\u{0020}time!", "0", "恭喜恭喜，用一頓大餐好好犒勞自己吧，不太捨得的話，這次就我請客了~", "0", "0", "0", "1ST_xhixha_5", "0", "0"},
[9002505] = {9002505, 90025, 98, 0, "0", "xinwei", "Being\u{0020}serious\u{0020}is\u{0020}important,\u{0020}but\u{0020}don't\u{0020}forget\u{0020}to\u{0020}balance\u{0020}work\u{0020}and\u{0020}rest.\u{0020}Want\u{0020}to\u{0020}go\u{0020}shopping\u{0020}or\u{0020}watch\u{0020}a\u{0020}movie\u{0020}to\u{0020}relax\u{0020}together\u{0020}later?", "0", "認真是沒錯，但也別忘記勞逸結合，待會要一起去逛街、看電影放鬆下嗎？", "0", "0", "0", "1ST_xhixha_6", "0", "0"},
[9002506] = {9002506, 90025, 98, 0, "0", "jingya", "You've\u{0020}worked\u{0020}hard.\u{0020}Enjoy\u{0020}the\u{0020}satisfaction,\u{0020}the\u{0020}sense\u{0020}of\u{0020}liberation,\u{0020}and\u{0020}the\u{0020}generous\u{0020}rewards\u{0020}that\u{0020}come\u{0020}from\u{0020}your\u{0020}labor.", "0", "辛苦了，請好好享受勞動過後的滿足感、解放感，以及豐厚的物質獎勵吧。", "0", "0", "0", "1ST_xhixha_7", "0", "0"},
[9002600] = {9002600, 90026, 97, 0, "0", "idle", "Failure\u{0020}is\u{0020}merely\u{0020}a\u{0020}rehearsal\u{0020}for\u{0020}victory,\u{0020}and\u{0020}today\u{0020}is\u{0020}just\u{0020}a\u{0020}rehearsal\u{0020}for\u{0020}tomorrow.\u{0020}So\u{0020}even\u{0020}though\u{0020}it's\u{0020}training,\u{0020}don't\u{0020}slack\u{0020}off.", "0", "失敗是對勝利的預演，今日是對明日的預演，所以雖是訓練，也不可輕易懈怠。", "0", "0", "0", "1ST_korsgaard_1", "0", "0"},
[9002601] = {9002601, 90026, 97, 0, "0", "xiao4", "I\u{0020}always\u{0020}remind\u{0020}myself\u{0020}that\u{0020}both\u{0020}the\u{0020}shield\u{0020}and\u{0020}sword\u{0020}are\u{0020}used\u{0020}to\u{0020}protect\u{0020}people.", "0", "我一直提醒自己，用以守護人們的不只是盾，還有劍。", "0", "0", "0", "1ST_korsgaard_2", "0", "0"},
[9002602] = {9002602, 90026, 97, 0, "0", "xiao3", "When\u{0020}confused,\u{0020}use\u{0020}the\u{0020}passionate\u{0020}battle\u{0020}within\u{0020}you,\u{0020}the\u{0020}will\u{0020}that\u{0020}purges\u{0020}distractions,\u{0020}and\u{0020}let\u{0020}the\u{0020}tip\u{0020}of\u{0020}your\u{0020}soul's\u{0020}sword\u{0020}point\u{0020}the\u{0020}way.", "0", "迷茫之時，就用酣暢淋漓的戰鬥、用滌除雜念的意志、用心靈的劍尖去指明方向吧。", "0", "0", "0", "1ST_korsgaard_3", "0", "0"},
[9002603] = {9002603, 90026, 97, 0, "0", "shy2", "What's\u{0020}wrong?\u{0020}Don't\u{0020}worry.\u{0020}This\u{0020}level\u{0020}of\u{0020}training\u{0020}is\u{0020}just\u{0020}routine\u{0020}and\u{0020}won't\u{0020}exceed\u{0020}your\u{0020}limits.", "0", "怎麼了？不用擔心，這種程度的訓練只是日常，不會超過負荷。", "0", "0", "0", "1ST_korsgaard_4", "0", "0"},
[9002604] = {9002604, 90026, 98, 0, "0", "xiao2", "Now,\u{0020}the\u{0020}battle\u{0020}begins.", "0", "那麼，戰鬥開始。", "0", "0", "0", "1ST_korsgaard_5", "0", "0"},
[9002605] = {9002605, 90026, 98, 0, "0", "ganga", "A\u{0020}surging\u{0020}spring\u{0020}results\u{0020}from\u{0020}every\u{0020}drop\u{0020}of\u{0020}sweat\u{0020}accumulated.", "0", "奔湧的泉水，由每一滴汗水積攢所成。", "0", "0", "0", "1ST_korsgaard_6", "0", "0"},
[9002606] = {9002606, 90026, 98, 0, "0", "ganga", "Thanks\u{0020}to\u{0020}you,\u{0020}the\u{0020}results\u{0020}this\u{0020}time\u{0020}are\u{0020}far\u{0020}better\u{0020}than\u{0020}usual.", "0", "多虧了你，這次的效果遠勝往常。", "0", "0", "0", "1ST_korsgaard_7", "0", "0"},
[9002607] = {9002607, 90026, 98, 0, "0", "ganga", "I\u{0020}will\u{0020}turn\u{0020}this\u{0020}training\u{0020}success\u{0020}into\u{0020}reality.", "0", "我會將訓練中的成功轉變為現實。", "0", "0", "0", "1ST_korsgaard_8", "0", "0"},
[9002608] = {9002608, 90026, 98, 0, "0", "ganga", "Don't\u{0020}be\u{0020}discouraged.\u{0020}Grasp\u{0020}your\u{0020}weapon\u{0020}and\u{0020}fight\u{0020}again.", "0", "不必氣餒，握緊武器，再來一戰。", "0", "0", "0", "1ST_korsgaard_9", "0", "0"},
[9002700] = {9002700, 90027, 97, 0, "0", "idle", "Let's\u{0020}stock\u{0020}up\u{0020}on\u{0020}some\u{0020}supplies.", "0", "補充些物資吧。", "0", "0", "0", "shop_kalian_1", "0", "0"},
[9002701] = {9002701, 90027, 97, 0, "0", "angry", "Huh?\u{0020}I\u{0020}happen\u{0020}to\u{0020}have\u{0020}something\u{0020}to\u{0020}discuss\u{0020}with\u{0020}you.\u{0020}May\u{0020}I\u{0020}take\u{0020}up\u{0020}some\u{0020}of\u{0020}your\u{0020}time,\u{0020}Navigator?", "0", "嗯？正好我有事想要請教您，可以佔有您一些時間嗎？領航。", "0", "0", "0", "shop_kalian_2", "0", "0"},
[9002702] = {9002702, 90027, 97, 0, "0", "sad", "This\u{0020}uniform\u{0020}looks\u{0020}unfamiliar?\u{0020}Ah,\u{0020}this\u{0020}is\u{0020}the\u{0020}academy\u{0020}uniform\u{0020}that\u{0020}Sahara\u{0020}prepared\u{0020}for\u{0020}the\u{0020}trainees.", "0", "這件制服很陌生？啊，這是薩哈拉為候補生們準備的學院服。", "0", "0", "0", "shop_kalian_3", "0", "0"},
[9002703] = {9002703, 90027, 98, 0, "0", "happy", "Though\u{0020}it\u{0020}may\u{0020}sound\u{0020}a\u{0020}bit\u{0020}arrogant,\u{0020}I\u{0020}feel\u{0020}that\u{0020}with\u{0020}your\u{0020}help,\u{0020}I'm\u{0020}already\u{0020}becoming\u{0020}a\u{0020}qualified\u{0020}driver.", "0", "雖然這麼說有些自大，不過我感覺在你的幫助下，自己已經是個合格的駕駛員了呢。", "0", "0", "0", "shop_kalian_4", "0", "0"},
[9002704] = {9002704, 90027, 98, 0, "0", "jingya", "There\u{0020}should\u{0020}be\u{0020}other\u{0020}trainees\u{0020}besides\u{0020}me.\u{0020}If\u{0020}you\u{0020}see\u{0020}them,\u{0020}please\u{0020}look\u{0020}out\u{0020}for\u{0020}them.", "0", "除了我之外應該還有其他候補生吧，如果見到她們的話還請多多關照一下。", "0", "0", "0", "shop_kalian_5", "0", "0"},
[9002800] = {9002800, 90028, 97, 0, "0", "idle", "Ding-dong!\u{0020}Lilith,\u{0020}I\u{0020}finally\u{0020}finished\u{0020}writing\u{0020}Dunscaith\u{0020}Chronicles\u{0020}2!", "0", "噔咚——莉莉絲，吾終於把《影之國編年史2》寫完了！", "0", "0", "0", "XH2_countdown_1", "0", "0"},
[9002801] = {9002801, 90028, 97, 0, "0", "angry", "This\u{0020}time,\u{0020}the\u{0020}subtitle\u{0020}is—\"Seaside\u{0020}Paradise\u{0020}Panic\u{0020}in\u{0020}the\u{0020}Heroine\u{0020}Universe!\"\u{0020}And\u{0020}guess\u{0020}what?\u{0020}I\u{0020}put\u{0020}you\u{0020}in\u{0020}a\u{0020}swimsuit!", "0", "這次的副標題是——女主角宇宙的海濱樂園危機！我讓莉莉絲在書裏穿上了泳裝哦！", "0", "0", "0", "XH2_countdown_2", "0", "0"},
[9002802] = {9002802, 90028, 97, 0, "0", "sad", "Eeek—w-why\u{0020}am\u{0020}I\u{0020}wearing\u{0020}such\u{0020}a\u{0020}shameless\u{0020}swimsuit?!", "0", "咿——我、我怎麼穿著這麼不知廉恥的泳裝！", "0", "0", "0", "XH2_countdown_3", "0", "0"},
[9002803] = {9002803, 90028, 97, 0, "0", "happy", "Her\u{0020}Majesty...\u{0020}don't\u{0020}tell\u{0020}me\u{0020}forgot\u{0020}why\u{0020}we\u{0020}came\u{0020}here.", "0", "王女……你不會忘記我們來海濱樂園的任務了吧？", "0", "0", "0", "XH2_countdown_4", "0", "0"},
[9002804] = {9002804, 90028, 97, 0, "0", "jingya", "Franca...\u{0020}we\u{0020}blew\u{0020}through\u{0020}our\u{0020}budget\u{0020}just\u{0020}buying\u{0020}ferry\u{0020}tickets\u{0020}here.\u{0020}How\u{0020}did\u{0020}you\u{0020}still\u{0020}have\u{0020}money\u{0020}for\u{0020}a\u{0020}swimsuit?!", "0", "弗蘭卡……明明在付了來這裏的船票後我們的經費已經見底了，為什麼你還有錢買泳裝！", "0", "0", "0", "XH2_countdown_5", "0", "0"},
[9002900] = {9002900, 90029, 97, 0, "0", "xiao2", "Hmph,\u{0020}if\u{0020}Mr.\u{0020}Pervert\u{0020}stays\u{0020}here\u{0020}with\u{0020}me,\u{0020}you\u{0020}can\u{0020}have\u{0020}as\u{0020}much\u{0020}as\u{0020}you\u{0020}want.", "哼哼，變態先生要是留在這裡陪我的話，這些東西想要多少都有。", "0", "0", "0", "0", "shop_weilai_1", "0", "0"},
[9002901] = {9002901, 90029, 97, 0, "0", "xiao4", "You\u{0020}want\u{0020}the\u{0020}future\u{0020}from\u{0020}me?\u{0020}I-Idiot!\u{0020}There's\u{0020}no\u{0020}such\u{0020}thing!", "想要在我這裡購買“未來”？笨、笨蛋，這種怎麼東西怎麼可能有啊！", "0", "0", "0", "0", "shop_weilai_2", "0", "0"},
[9002902] = {9002902, 90029, 97, 0, "0", "xiao2", "If\u{0020}you\u{0020}become\u{0020}my\u{0020}boyfriend,\u{0020}I\u{0020}can\u{0020}show\u{0020}you\u{0020}off\u{0020}to\u{0020}everyone,\u{0020}hehe...", "如果變態先生當我的男朋友，我就能向大家炫耀你了，嘿嘿……", "0", "0", "0", "0", "shop_weilai_3", "0", "0"},
[9002903] = {9002903, 90029, 97, 0, "0", "xiao4", "So\u{0020}you've\u{0020}even\u{0020}got\u{0020}Mirai's\u{0020}future\u{0020}in\u{0020}your\u{0020}grip.\u{0020}Truly,\u{0020}Mr.\u{0020}Pervert\u{0020}lives\u{0020}up\u{0020}to\u{0020}his\u{0020}name.", "就連未來的未來都能掌握在你的手中，不愧是變態先生，真了不起。", "0", "0", "0", "0", "shop_weilai_4", "0", "0"},
[9002904] = {9002904, 90029, 97, 0, "0", "wuyu", "We've\u{0020}known\u{0020}each\u{0020}other\u{0020}for\u{0020}less\u{0020}than\u{0020}a\u{0020}month,\u{0020}so\u{0020}no\u{0020}discounts...\u{0020}but\u{0020}if\u{0020}you're\u{0020}willing\u{0020}to\u{0020}offer\u{0020}yourself\u{0020}up,\u{0020}then...\u{0020}No,\u{0020}still\u{0020}not\u{0020}happening.", "我與你相熟共事就連一個月都沒有，所以沒有優惠，但是你如果願意犧牲色相的話……那也不行。", "0", "0", "0", "0", "shop_weilai_5", "0", "0"},
[9002905] = {9002905, 90029, 98, 0, "0", "xiao2", "How\u{0020}about\u{0020}buying\u{0020}me?\u{0020}Wh-What's\u{0020}with\u{0020}that\u{0020}face?\u{0020}O-Of\u{0020}course\u{0020}I'm\u{0020}joking!", "要不把我也一起買走吧~誒……你那是什麼表情，我、我當然是開玩笑的！", "0", "0", "0", "0", "shop_weilai_6", "0", "0"},
[9002906] = {9002906, 90029, 98, 0, "0", "xiao4", "With\u{0020}the\u{0020}Truth\u{0020}Tribunal\u{0020}as\u{0020}my\u{0020}witness,\u{0020}my\u{0020}business\u{0020}is\u{0020}completely\u{0020}legal.", "在真理法庭的見證下，我這裡可是合法生意。", "0", "0", "0", "0", "shop_weilai_7", "0", "0"},
[9002907] = {9002907, 90029, 98, 0, "0", "wuyu", "So\u{0020}pervert!", "太變態了。", "0", "0", "0", "0", "shop_weilai_8", "0", "0"},
[9003000] = {9003000, 90030, 97, 0, "0", "xiao2", "Ah,\u{0020}Navigator...\u{0020}It's\u{0020}been\u{0020}so\u{0020}long.\u{0020}Can\u{0020}I\u{0020}sit\u{0020}next\u{0020}to\u{0020}you?", "啊，領航……真是好久不見了呢。我可以坐你的身邊的嗎？", "0", "0", "0", "0", "XH2_mission_fulanka_1", "0", "0"},
[9003001] = {9003001, 90030, 97, 0, "0", "xiao1", "I\u{0020}have\u{0020}so\u{0020}much\u{0020}I\u{0020}want\u{0020}to\u{0020}talk\u{0020}to\u{0020}you\u{0020}about.\u{0020}Let's\u{0020}meet\u{0020}up\u{0020}after\u{0020}my\u{0020}work,\u{0020}okay?", "我有很多話想要和領航講，等我下班了之後約個時間吧？", "0", "0", "0", "0", "XH2_mission_fulanka_2", "0", "0"},
[9003002] = {9003002, 90030, 97, 0, "0", "xiao2", "Even\u{0020}if\u{0020}your\u{0020}identity\u{0020}is\u{0020}exposed\u{0020}and\u{0020}you're\u{0020}wanted,\u{0020}it's\u{0020}fine.\u{0020}Just\u{0020}hide\u{0020}here\u{0020}with\u{0020}me.\u{0020}I'll\u{0020}take\u{0020}care\u{0020}of\u{0020}you\u{0020}until\u{0020}the\u{0020}very\u{0020}end.", "就算暴露了身份而被通緝也沒關係，躲在我這裡吧，我會照顧你直到生命盡頭的。", "0", "0", "0", "0", "XH2_mission_fulanka_3", "0", "0"},
[9003003] = {9003003, 90030, 97, 0, "0", "xiao1", "Even\u{0020}though\u{0020}you'll\u{0020}forget\u{0020}all\u{0020}of\u{0020}this\u{0020}once\u{0020}you\u{0020}leave,\u{0020}do\u{0020}you\u{0020}still\u{0020}want\u{0020}to\u{0020}hear\u{0020}my\u{0020}story?", "……雖然你離開這裡之後還會忘掉這一切，但你想聽我的故事嗎？", "0", "0", "0", "0", "XH2_mission_fulanka_4", "0", "0"},
[9003004] = {9003004, 90030, 98, 0, "0", "xiao1", "Mission\u{0020}complete!\u{0020}That's\u{0020}impressive.\u{0020}Navigator!", "任務完成了，太棒了，不愧是領航。", "0", "0", "0", "0", "XH2_mission_fulanka_5", "0", "0"},
