[4000100101] = {4000100101, 10001001, 2, 2, "0", "0", "I'll\u{0020}never\u{0020}let\u{0020}you\u{0020}down.", "絶対にご期待を裏切りませんわ。", "我絕對不會辜負您的期待。", "0", "我绝对不会辜负您的期待。", "0", "cv_sk_Julius_2", "0", "0"},
[4000100102] = {4000100102, 10001001, 3, 3, "0", "0", "I'm\u{0020}Julius\u{0020}von\u{0020}Nietzsche,\u{0020}your\u{0020}top\u{0020}driver,\u{0020}here\u{0020}to\u{0020}fight\u{0020}for\u{0020}our\u{0020}glory.", "ユリウス・フォン・ニーチェです。これからあなた様の一番の部下として、我らの栄光のため、共に戦いましょう。", "朱利烏斯·馮·尼采，從現在起將作為您最出色的部下，為了我們共同的榮耀而戰鬥。", "0", "朱利乌斯·冯·尼采，从现在起将作为您最出色的部下，为了我们共同的荣耀而战斗。", "0", "cv_sk_Julius_1", "0", "0"},
[4000100103] = {4000100103, 10001001, 4, 4, "0", "idle", "The\u{0020}bright\u{0020}lights\u{0020}and\u{0020}blaring\u{0020}dance\u{0020}music...\u{0020}It's\u{0020}a\u{0020}bit\u{0020}much,\u{0020}right?\u{0020}Everyone\u{0020}here\u{0020}is\u{0020}young,\u{0020}not\u{0020}a\u{0020}lot\u{0020}of\u{0020}formalities\u{0020}or\u{0020}greetings,\u{0020}but\u{0020}I\u{0020}still\u{0020}don't\u{0020}feel\u{0020}at\u{0020}home.\u{0020}Thankfully,\u{0020}I\u{0020}brought\u{0020}you\u{0020}along.", "華やかな照明と楽しい音楽……若いドライバーばかりですから堅苦しい雰囲気はありませんが、こういう場は少し慣れなくて……だから、あなた様に一緒に来ていただいて良かったです。", "耀眼眩目的燈光、過於歡快的舞曲……雖說參與者都是年輕駕駛員，沒有太多寒暄與繁文縟節，但我果然還是不適應這種場合，幸好有邀您一同前來。", "0", "我想要做的，我能做到的，只不过是笨拙地模仿先人罢了。但是，哪怕是如此愚钝的我还是有一点可以向您保证……赌上家族的荣耀，我一定会为您带来光荣的胜利。", "0", "cv_sk_Julius_3", "0", "0"},
[4000100104] = {4000100104, 10001001, 5, 4, "0", "idle", "This\u{0020}banquet\u{0020}is\u{0020}hosted\u{0020}by\u{0020}my\u{0020}family,\u{0020}and\u{0020}as\u{0020}the\u{0020}eldest\u{0020}daughter,\u{0020}I'll\u{0020}be\u{0020}giving\u{0020}a\u{0020}speech\u{0020}soon,\u{0020}reciting\u{0020}our\u{0020}oath,\u{0020}mission,\u{0020}and\u{0020}upholding\u{0020}the\u{0020}family's\u{0020}honor.\u{0020}Will\u{0020}you\u{0020}be\u{0020}by\u{0020}my\u{0020}side\u{0020}when\u{0020}I\u{0020}do?", "私の家族が主催するパーティーですから、私は長女として、家族の誓いと使命、そして栄光を誓うスピーチをしなければなりません。……もしよろしければ、側にいていただけますか？", "這是由我們家族舉辦的宴會，而作為長女，待會我必須為來賓們進行一番演講，宣說家族的誓言、使命與榮耀。屆時……您也會在旁聆聽的吧？", "0", "在这里停留了这么久，难道说领航已经很累了吗？没关系的，您去休息好了，这里交给我就行了。", "0", "cv_sk_Julius_4", "0", "0"},
[4000100105] = {4000100105, 10001001, 6, 4, "0", "idle", "Dancing\u{0020}the\u{0020}waltz\u{0020}in\u{0020}high\u{0020}heels...\u{0020}I'll\u{0020}try\u{0020}not\u{0020}to\u{0020}lose\u{0020}my\u{0020}balance.\u{0020}I\u{0020}hope\u{0020}you'll\u{0020}be\u{0020}patient\u{0020}with\u{0020}me,\u{0020}my\u{0020}dance\u{0020}partner.", "ハイヒールを履いて、ワルツを踊らなければいけないなんて……恥ずかしいところをお見せしないように精一杯頑張りますから、パートナーとして、どうかご協力をお願いいたします。", "穿著高跟鞋，還非得跳華爾滋……在舞會上我會盡力避免失態的，還希望您多多擔待，我的舞伴。", "0", "领航，你有看到查丽莎吗？今天她又没来训练……每次也不请一个假，真是让人担心的家伙……", "0", "cv_sk_Julius_30", "0", "0"},
[4000100106] = {4000100106, 10001001, 7, 5, "1_》_0_0.8", "level1", "I\u{0020}told\u{0020}Mother\u{0020}that\u{0020}I\u{0020}didn't\u{0020}need\u{0020}such\u{0020}fancy\u{0020}clothes,\u{0020}but...\u{0020}do\u{0020}you\u{0020}think\u{0020}it\u{0020}suits\u{0020}me,\u{0020}Navigator?\u{0020}If\u{0020}so,\u{0020}I\u{0020}might\u{0020}wear\u{0020}things\u{0020}like\u{0020}this\u{0020}more\u{0020}often\u{0020}when\u{0020}you're\u{0020}around.", "こんなに豪華なドレスは必要ないと申し上げたのに、母上はまた……え？似合う、ですか？でしたら……まだ慣れませんが、あなた様の前では色々試してみましょうか。", "都說不用這麼奢華的衣服了，可母親大人她還是……誒？領航認為很適合我嗎？那……雖然不太習慣，以後在您面前我就再嘗試一些吧。", "0", "成为驾驶员的理由？啊，一方面是因为我自己本身就非常憧憬这样的生活，另一方面则是因为我的父亲……", "0", "cv_sk_Julius_31", "0", "0"},
[4000100107] = {4000100107, 10001001, 8, 5, "1_》_0_0.8", "level2", "Are\u{0020}you\u{0020}thirsty?\u{0020}There's\u{0020}green\u{0020}tea\u{0020}and\u{0020}red\u{0020}wine,\u{0020}but\u{0020}that's\u{0020}it,\u{0020}I'm\u{0020}afraid.\u{0020}We\u{0020}only\u{0020}have\u{0020}these\u{0020}somewhat\u{0020}bitter\u{0020}drinks\u{0020}at\u{0020}home.\u{0020}It's\u{0020}part\u{0020}of\u{0020}an\u{0020}old\u{0020}family\u{0020}motto:\u{0020}\"Glory\u{0020}tastes\u{0020}bitter.\"", "ナビゲーター、お飲み物はいかがですか？緑茶か、赤ワインか……申し訳ありません。ここでは、やや苦味のある飲み物だけをご用意させていただいております。栄光の味は苦いという、先代から伝わる家訓によるものです。", "領航需要喝點什麼嗎？綠茶，還是紅酒？抱歉……家中僅備有這類略帶苦味的飲品，據長輩說，這種習慣是源於一句古老的家訓：榮耀的味道是苦的。", "0", "谢谢关心，但是还请您注意形象。", "0", "cv_sk_Julius_5", "0", "0"},
[4000100108] = {4000100108, 10001001, 9, 5, "1_》_0_0.8", "level3", "Oh,\u{0020}and\u{0020}by\u{0020}the\u{0020}way,\u{0020}Mother\u{0020}has\u{0020}always\u{0020}wanted\u{0020}to\u{0020}meet\u{0020}you.\u{0020}She's\u{0020}known\u{0020}as\u{0020}a\u{0020}strong,\u{0020}sharp-tongued\u{0020}woman,\u{0020}but\u{0020}it's\u{0020}just\u{0020}her\u{0020}way\u{0020}of\u{0020}testing\u{0020}people.\u{0020}Don't\u{0020}worry\u{0020}too\u{0020}much.", "そういえば、母上がずっとあなた様にお会いしたがっていました。母上は「手ごわい貴婦人」と言われ、言葉にも遠慮のないところがあるのですが、それも一種の……テストのようなものです。あまりご心配されなくても大丈夫ですよ。", "對了，母親大人一直很想親自見見您，她常被評價為手腕強勢的貴婦人，也許會說些較為尖銳的話，但那只是算種……考驗？總之，還請您放心。", "0", "怎么了？我的装备穿错了吗？抱歉，我马上检讨。", "0", "cv_sk_Julius_6", "0", "0"},
[4000100109] = {4000100109, 10001001, 10, 5, "1_》_0_0.8", "level4", "You\u{0020}want\u{0020}to\u{0020}know\u{0020}about\u{0020}my\u{0020}childhood?\u{0020}I\u{0020}had\u{0020}all\u{0020}kinds\u{0020}of\u{0020}lessons\u{0020}back\u{0020}then,\u{0020}and\u{0020}the\u{0020}hardest\u{0020}by\u{0020}far\u{0020}was\u{0020}equestrian\u{0020}training.\u{0020}To\u{0020}cheer\u{0020}me\u{0020}up,\u{0020}Father\u{0020}bought\u{0020}me\u{0020}a\u{0020}big\u{0020}unicorn\u{0020}doll.\u{0020}I\u{0020}still\u{0020}have\u{0020}it.\u{0020}Want\u{0020}to\u{0020}take\u{0020}a\u{0020}look\u{0020}later?", "私の子供の頃ですか？そうですね……色々な習い事をしたのですが、乗馬が一番苦手でしたね。でも頑張れるように、父上が大きなユニコーンのぬいぐるみを買ってくれたんです。とても気に入って、今でも大切にしているんですよ。後で一緒に見に行きませんか？", "關於我小時候？嗯……那時整天都得上各種課，尤其以馬術課最難熬，為了讓我克服，父親特意買了個大型獨角獸玩偶給我。我很喜歡它，至今還妥善保存著，待會要一起試試嗎？", "0", "为什么……会这么在意我。如果我有让您不满意的地方还请直接指出，老用这种眼神看着我，我也会……", "0", "cv_sk_Julius_7", "0", "0"},
[4000100110] = {4000100110, 10001001, 11, 5, "1_》_0_0.8", "level5", "Thank\u{0020}you\u{0020}for\u{0020}coming\u{0020}with\u{0020}me\u{0020}to\u{0020}the\u{0020}banquet.\u{0020}I'd\u{0020}like\u{0020}to\u{0020}visit\u{0020}your\u{0020}home\u{0020}sometime—no,\u{0020}not\u{0020}the\u{0020}AEGIS\u{0020}dorms,\u{0020}your\u{0020}actual\u{0020}hometown...\u{0020}that\u{0020}place\u{0020}locked\u{0020}away\u{0020}in\u{0020}your\u{0020}memories.\u{0020}I\u{0020}want\u{0020}to\u{0020}go\u{0020}there\u{0020}with\u{0020}you.", "今晩はパーティーにお付き合いくださり、ありがとうございました。いつかあなた様のお家にもお邪魔できたら嬉しいですね。ええ、アイギス寮ではなく、あなた様の故郷……記憶から失われた場所を、一緒に探してみたいのです。", "非常感謝您願意陪我出席宴會，改天我也去您家做做客吧？不，不是指艾吉斯宿舍，而是您的故鄉……那個隨著記憶忘卻的地方，我想陪您一起尋找。", "0", "原来如此，最近我已经明白您的感受了。没错，现在的我和您心中想的事情是一样的……但是在没有结束这一切之前，只是这样看着彼此，就足够了。", "0", "cv_sk_Julius_8", "0", "0"},
[4000100111] = {4000100111, 10001001, 12, 6, "0", "0", "Thank\u{0020}you\u{0020}for\u{0020}caring.", "お気遣い、ありがとうございます。", "謝謝關心。", "0", "谢谢关心。", "0", "cv_sk_Julius_9", "0", "0"},
[4000100112] = {4000100112, 10001001, 13, 7, "0", "0", "Thank\u{0020}you\u{0020}for\u{0020}loving\u{0020}me.", "そのお気持ち、ありがたく頂戴します。", "承蒙厚愛。", "0", "承蒙厚爱。", "0", "cv_sk_Julius_10", "0", "0"},
[4000100113] = {4000100113, 10001001, 14, 8, "0", "0", "Did\u{0020}I\u{0020}really\u{0020}do\u{0020}it...?\u{0020}This\u{0020}victory,\u{0020}Navigator,\u{0020}it\u{0020}belongs\u{0020}to\u{0020}both\u{0020}of\u{0020}us.", "やっとここまで辿り着くことができました…...ナビゲーター、この栄光をあなた様と共に！", "終於抵達這個高度了嗎……領航，這份榮耀與您共用！", "0", "终于抵达这个高度了吗……领航，这份荣耀与您共享！", "0", "cv_sk_Julius_11", "0", "0"},
[4000100114] = {4000100114, 10001001, 15, 9, "0", "0", "How\u{0020}many\u{0020}more\u{0020}times\u{0020}do\u{0020}I\u{0020}have\u{0020}to\u{0020}swing\u{0020}this\u{0020}sword\u{0020}before\u{0020}I'm\u{0020}truly\u{0020}worthy?", "あとどれほど剣を振り回せば、あそこにたどり着けるのでしょう。", "到底還要再揮動多少次劍，才能抵達那個高度呢？", "0", "到底还要再挥动多少次剑，才能抵达那个高度呢？", "0", "cv_sk_Julius_12", "0", "0"},
[4000100115] = {4000100115, 10001001, 16, 10, "0", "0", "Let's\u{0020}march\u{0020}toward\u{0020}victory\u{0020}together,\u{0020}everyone!", "皆、勝利に向かって進みましょう！", "大家，向著勝利前進吧！", "0", "大家，向着胜利前进吧！", "0", "cv_sk_Julius_13", "0", "0"},
[4000100116] = {4000100116, 10001001, 17, 11, "0", "0", "Isn't\u{0020}victory\u{0020}glorious?", "勝利とは、輝かしいものです。", "勝利……很光榮吧？", "0", "胜利……很光荣吧？", "0", "cv_sk_Julius_14", "0", "0"},
[4000100117] = {4000100117, 10001001, 18, 12, "0", "0", "Mission\u{0020}complete.\u{0020}Let's\u{0020}head\u{0020}back.", "ミッション完了です。一緒に帰りましょう。", "任務完成，一起回去吧。", "0", "任务完成，一起回去吧。", "0", "cv_sk_Julius_15", "0", "0"},
[4000100118] = {4000100118, 10001001, 19, 13, "0", "0", "I'm\u{0020}sorry\u{0020}to\u{0020}hear\u{0020}that,\u{0020}but\u{0020}congratulations\u{0020}to\u{0020}all.", "至らない点も少々ありましたが、おめでとうございます。", "雖然還有些小遺憾，但是，還是恭喜大家了。", "0", "虽然还有些小遗憾，但是，还是恭喜大家了。", "0", "cv_sk_Julius_16", "0", "0"},
[4000100119] = {4000100119, 10001001, 20, 14, "0", "0", "I'm\u{0020}sorry\u{0020}I\u{0020}couldn't\u{0020}keep\u{0020}my\u{0020}promise\u{0020}to\u{0020}you.", "……あなた様との約束を果たせなくて、申し訳ありません。", "……沒能完成對您的承諾，非常抱歉。", "0", "……没能完成对您的承诺，非常抱歉。", "0", "cv_sk_Julius_17", "0", "0"},
[4000100120] = {4000100120, 10001001, 21, 15, "0", "0", "Please,\u{0020}leave\u{0020}this\u{0020}banquet.", "ご退席願います。", "請離開這場宴會。", "0", "哼，解决了呢。", "0", "cv_sk_Julius_18", "0", "0"},
[4000100121] = {4000100121, 10001001, 23, 16, "0", "0", "Knife\u{0020}and\u{0020}fork.", "ナイフとフォーク。", "刀與叉。", "0", "喝——哈啊!", "0", "cv_sk_Julius_19", "0", "0"},
[4000100122] = {4000100122, 10001001, 26, 19, "0", "0", "Losing\u{0020}composure...", "なんという失態……", "實在是失態……", "0", "让您失望了……", "0", "cv_sk_Julius_20", "0", "0"},
[4000100123] = {4000100123, 10001001, 24, 17, "0", "0", "Wine\u{0020}and\u{0020}candle.", "ワインとキャンドル。", "酒與燭。", "0", "完全不够！", "0", "cv_sk_Julius_21", "0", "0"},
[4000100124] = {4000100124, 10001001, 25, 18, "0", "0", "This\u{0020}is\u{0020}the\u{0020}full\u{0020}might\u{0020}of\u{0020}Julius's\u{0020}pride!", "ユリウスの名をかけた――会心の一撃！！！！！！！！！！", "這就是賭上了朱利烏斯之名的——全力一擊！！！！！！！！！！！", "0", "这就是赌上了朱利乌斯之名的——全力一击！！！！！！！！！！！", "0", "cv_sk_Julius_22", "0", "0"},
[4000100125] = {4000100125, 10001001, 27, 20, "0", "0", "Apologies.", "お願いします。", "麻煩您了。", "0", "麻烦您了。", "0", "cv_sk_Julius_23", "0", "0"},
[4000100126] = {4000100126, 10001001, 28, 21, "0", "0", "What's\u{0020}wrong?\u{0020}Are\u{0020}you\u{0020}feeling\u{0020}tired?", "どうしましたか？疲れましたか？", "怎麼了？您累了嗎？", "0", "怎么了？您累了吗？", "0", "cv_sk_Julius_24", "0", "0"},
[4000100127] = {4000100127, 10001001, 29, 21, "0", "0", "Don't\u{0020}push\u{0020}yourself\u{0020}too\u{0020}hard.\u{0020}I'm\u{0020}happy\u{0020}to\u{0020}serve\u{0020}you,\u{0020}Navigator.", "あまり無理しないでください。ナビゲーターにもてなして頂いて、もう十分幸せです。", "不用太勉強自己，能享受到領航的服務，我已經很滿足了。", "0", "不用太勉强自己，能享受到领航的服务，我已经很满足了。", "0", "cv_sk_Julius_25", "0", "0"},
[4000100128] = {4000100128, 10001001, 30, 22, "0", "0", "Stay\u{0020}safe.", "どうかお気を付けください。", "還請多加小心。", "0", "还请多加小心。", "0", "cv_sk_Julius_26", "0", "0"},
[4000100129] = {4000100129, 10001001, 31, 23, "0", "0", "Don't\u{0020}worry,\u{0020}I\u{0020}won't\u{0020}hold\u{0020}it\u{0020}against\u{0020}you.", "リラックスしてください。どんな結果になったとしても、責めたりはしませんから。", "還請放輕鬆，無論結果如何我都不會責備您的。", "0", "还请放轻松，无论结果如何我都不会责备您的。", "0", "cv_sk_Julius_27", "0", "0"},
[4000100130] = {4000100130, 10001001, 32, 24, "0", "0", "Thank\u{0020}you\u{0020}for\u{0020}always\u{0020}going\u{0020}above\u{0020}and\u{0020}beyond.", "いつも、ありがとうございます。", "謝謝您，每次都讓您費心了。", "0", "谢谢您，每次都让您费心了。", "0", "cv_sk_Julius_28", "0", "0"},
[4000100131] = {4000100131, 10001001, 33, 25, "0", "0", "I\u{0020}don't\u{0020}blame\u{0020}you\u{0020}for\u{0020}any\u{0020}of\u{0020}this.", "わ、私は……あなた様を責める気はないのですが。", "我……我沒有責怪您的意思。", "0", "我……我没有责怪您的意思。", "0", "cv_sk_Julius_29", "0", "0"},
[4000100132] = {4000100132, 10001001, 34, 26, "0", "0", "With\u{0020}the\u{0020}banquet\u{0020}in\u{0020}full\u{0020}swing,\u{0020}isn't\u{0020}it\u{0020}nice\u{0020}for\u{0020}the\u{0020}two\u{0020}of\u{0020}us\u{0020}to\u{0020}slip\u{0020}away\u{0020}and\u{0020}find\u{0020}some\u{0020}quiet?", "パーティーの喧騒から離れて、二人きりで静かに過ごすのも悪くありませんね。", "在宴會進行得正熱烈時，就這樣兩人獨處，靜靜待著也不錯呢。", "0", "欢迎回来，领航。今天也让我们一起为了荣耀而战斗吧。", "0", "cv_sk_Julius_32", "0", "0"},
[4000100133] = {4000100133, 10001001, 35, 27, "0", "0", "Until\u{0020}my\u{0020}journey's\u{0020}end,\u{0020}I'll\u{0020}be\u{0020}both\u{0020}your\u{0020}strongest\u{0020}shield\u{0020}and\u{0020}sharpest\u{0020}sword.", "この旅が終わるまで、あなた様の一番丈夫な盾、そして一番鋭利な剣であり続けると誓いましょう。", "在旅途結束之前，我都將成為您最牢固的盾以及最鋒利的劍。", "0", "在旅途结束之前，我都将成为您最牢固的盾以及最锋利的剑。", "0", "cv_sk_Julius_34", "0", "0"},
[4000100134] = {4000100134, 10001001, 36, 28, "0", "0", "Time\u{0020}to\u{0020}move\u{0020}on\u{0020}to\u{0020}the\u{0020}next\u{0020}level.", "もっと高い目標に向かって進んでいきましょう。", "向著更高點邁進吧。", "0", "向着更高点迈进吧。", "0", "cv_sk_Julius_35", "0", "0"},
[4000100135] = {4000100135, 10001001, 37, 29, "0", "0", "Everyone's\u{0020}waiting\u{0020}for\u{0020}you.", "皆、あなた様を待っていますよ。", "大家都在等著您呢。", "0", "大家都在等着您呢。", "0", "cv_sk_Julius_36", "0", "0"},
[4000100136] = {4000100136, 10001001, 38, 30, "0", "0", "It's\u{0020}great\u{0020}to\u{0020}have\u{0020}a\u{0020}new\u{0020}partner.", "新しい仲間が加わるなんて、嬉しいですね。", "有新的夥伴加入是件令人高興的事呢。", "0", "有新的伙伴加入是件令人高兴的事呢。", "0", "cv_sk_Julius_37", "0", "0"},
