[4000100138] = {4000100138, 10001001, 40, 32, "0", "0", "Let's\u{0020}make\u{0020}sure\u{0020}to\u{0020}restock\u{0020}supplies.", "物資を補充しましょう。", "補充一下物資吧。", "0", "补充一下物资吧。", "0", "cv_sk_Julius_39", "0", "0"},
[4000100139] = {4000100139, 10001001, 41, 33, "0", "0", "It's\u{0020}crucial\u{0020}to\u{0020}check\u{0020}your\u{0020}condition\u{0020}before\u{0020}moving\u{0020}forward.", "自分の状況を確認するというのも大事なことです。", "確認下自己的狀況也很重要呢。", "0", "确认下自己的状况也很重要呢。", "0", "cv_sk_Julius_40", "0", "0"},
[4000100140] = {4000100140, 10001001, 42, 34, "0", "0", "Adjusting\u{0020}the\u{0020}settings\u{0020}could\u{0020}give\u{0020}us\u{0020}an\u{0020}edge\u{0020}in\u{0020}battle.", "設定を変更すると、戦いに役立つかもしれません。", "變更設定，說不定會對戰鬥有利。", "0", "变更设置，说不定会对战斗有利。", "0", "cv_sk_Julius_41", "0", "0"},
