[4000100301] = {4000100301, 10001003, 2, 2, "0", "0", "I'll\u{0020}never\u{0020}let\u{0020}you\u{0020}down.", "0", "我絕對不會辜負您的期待。", "0", "0", "0", "cv_sk2_Julius_2", "0", "0"},
[4000100302] = {4000100302, 10001003, 3, 3, "0", "0", "I'm\u{0020}Julius\u{0020}von\u{0020}Nietzsche,\u{0020}your\u{0020}top\u{0020}driver,\u{0020}here\u{0020}to\u{0020}fight\u{0020}for\u{0020}our\u{0020}glory.", "0", "朱利烏斯·馮·尼采，從現在起將作為您最出色的部下，為了我們共同的榮耀而戰鬥。", "0", "0", "0", "cv_sk2_Julius_1", "0", "0"},
[4000100303] = {4000100303, 10001003, 4, 4, "0", "idle", "Christmas\u{0020}in\u{0020}Danube\u{0020}is\u{0020}all\u{0020}about\u{0020}spending\u{0020}time\u{0020}with\u{0020}family,\u{0020}but\u{0020}here\u{0020}in\u{0020}Kyushu,\u{0020}it\u{0020}seems\u{0020}more\u{0020}about\u{0020}being\u{0020}with\u{0020}someone\u{0020}special...\u{0020}So,\u{0020}which\u{0020}tradition\u{0020}do\u{0020}we\u{0020}follow...?", "ダニューブのクリスマスは、家族で過ごす祝日です。九州では、恋人同士で過ごす人が多いようですが……私たちは、どちらに属するんでしょうか…。", "多瑙的圣诞节是和家人一起过的节日，九州这边好像很多人都是和情侣一起过的……我们，属于哪一种呢……", "0", "0", "0", "cv_sk2_Julius_3", "0", "0"},
[4000100304] = {4000100304, 10001003, 5, 4, "0", "idle", "You\u{0020}look\u{0020}a\u{0020}bit\u{0020}tired.\u{0020}How\u{0020}about\u{0020}we\u{0020}take\u{0020}a\u{0020}short\u{0020}break\u{0020}and\u{0020}grab\u{0020}something\u{0020}warm\u{0020}to\u{0020}drink?", "少しお疲れのようですね。少し休憩して、温かいものでも飲みましょう。", "看起来你好像有点累了，那我们稍微休息一会儿，去喝点热的东西吧。", "0", "0", "0", "cv_sk2_Julius_4", "0", "0"},
[4000100305] = {4000100305, 10001003, 6, 4, "0", "idle", "Everyone\u{0020}was\u{0020}so\u{0020}eager\u{0020}when\u{0020}we\u{0020}first\u{0020}talked\u{0020}about\u{0020}putting\u{0020}up\u{0020}Christmas\u{0020}decorations,\u{0020}but\u{0020}in\u{0020}the\u{0020}end,\u{0020}it's\u{0020}just\u{0020}the\u{0020}two\u{0020}of\u{0020}us\u{0020}finishing\u{0020}the\u{0020}job.\u{0020}They're\u{0020}like\u{0020}a\u{0020}bunch\u{0020}of\u{0020}kids...", "クリスマスの飾りつけ、皆さん最初はやる気満々だったのに、結局最後は私たち二人だけになってしまいましたね。ほんと、皆さん子供みたいですね……", "大家一开始说起圣诞布置的时候都干劲满满，最后还是要我们两个来收尾啊，真像一群小孩子呢……", "0", "0", "0", "cv_sk2_Julius_30", "0", "0"},
[4000100306] = {4000100306, 10001003, 7, 5, "1_》_0_0.8", "level1", "Navigator,\u{0020}if\u{0020}you\u{0020}don't\u{0020}stay\u{0020}focused,\u{0020}we'll\u{0020}never\u{0020}get\u{0020}this\u{0020}done\u{0020}tonight.\u{0020}Decorating\u{0020}for\u{0020}Christmas\u{0020}takes\u{0020}time.", "ナビゲーター、集中しないと今夜中に終わりませんよ。クリスマスの飾り付けは、手間がかかる作業ですから。", "领航，不专心做的话，今天晚上我们可要做不完了。圣诞布置可是很耗时间的工作。", "0", "0", "0", "cv_sk2_Julius_31", "0", "0"},
[4000100307] = {4000100307, 10001003, 8, 5, "1_》_0_0.8", "level1", "It's\u{0020}getting\u{0020}a\u{0020}little\u{0020}chilly...", "少し、寒くなってきましたね……", "好像，有点冷了……", "0", "0", "0", "cv_sk2_Julius_5", "0", "0"},
[4000100308] = {4000100308, 10001003, 9, 5, "1_》_100_1.5", "level1", "Thank\u{0020}you\u{0020}for\u{0020}sticking\u{0020}around\u{0020}so\u{0020}late...", "遅くまで付き合っていただいて、ありがとうございます。", "谢谢你陪我到这么晚……", "0", "0", "0", "cv_sk2_Julius_6", "0", "0"},
[4000100309] = {4000100309, 10001003, 10, 5, "1_》_500_2", "level1", "When\u{0020}most\u{0020}people\u{0020}think\u{0020}of\u{0020}Christmas,\u{0020}it's\u{0020}all\u{0020}about\u{0020}gifts\u{0020}and\u{0020}trees.\u{0020}But\u{0020}for\u{0020}me,\u{0020}none\u{0020}of\u{0020}that\u{0020}matters...\u{0020}A\u{0020}Christmas\u{0020}spent\u{0020}with\u{0020}you\u{0020}is\u{0020}the\u{0020}best\u{0020}kind\u{0020}of\u{0020}Christmas.", "クリスマスといえば、皆さんプレゼントやクリスマスツリーを楽しみにするかと思いますが、私にとっては必ずしも必要なものではありません。……あなたと過ごせるだけで、最高のクリスマスですから。", "大家提到圣诞节就会想起礼物、圣诞树，对我来说，这些都不是必需品……有你在的圣诞节就是最棒的圣诞节了。", "0", "0", "0", "cv_sk2_Julius_7", "0", "0"},
[4000100310] = {4000100310, 10001003, 11, 5, "1_》_1000_2.5", "level1", "Navigator...\u{0020}In\u{0020}my\u{0020}hometown,\u{0020}there's\u{0020}this\u{0020}old\u{0020}legend...\u{0020}They\u{0020}say\u{0020}a\u{0020}kiss\u{0020}under\u{0020}the\u{0020}mistletoe\u{0020}can't\u{0020}be\u{0020}refused...\u{0020}No,\u{0020}never\u{0020}mind...\u{0020}Forget\u{0020}I\u{0020}said\u{0020}anything.", "ナビゲーター、私の故郷には、とある言い伝えがあるのです。……ヤドリギの下は、キスを断ることができないという……いえ……何でもありません。", "领航……在我的家乡……有一个传说……说是槲寄生下的吻是无法拒绝的……不……没什么。", "0", "0", "0", "cv_sk2_Julius_8", "0", "0"},
[4000100311] = {4000100311, 10001003, 12, 6, "0", "0", "Thank\u{0020}you\u{0020}for\u{0020}caring.", "0", "謝謝關心。", "0", "0", "0", "cv_sk2_Julius_9", "0", "0"},
[4000100312] = {4000100312, 10001003, 13, 7, "0", "0", "Thank\u{0020}you\u{0020}for\u{0020}loving\u{0020}me.", "0", "承蒙厚愛。", "0", "0", "0", "cv_sk2_Julius_10", "0", "0"},
[4000100313] = {4000100313, 10001003, 14, 8, "0", "0", "Did\u{0020}I\u{0020}really\u{0020}do\u{0020}it...?\u{0020}This\u{0020}victory,\u{0020}Navigator,\u{0020}it\u{0020}belongs\u{0020}to\u{0020}both\u{0020}of\u{0020}us.", "0", "終於抵達這個高度了嗎……領航，這份榮耀與您共用！", "0", "0", "0", "cv_sk2_Julius_11", "0", "0"},
[4000100314] = {4000100314, 10001003, 15, 9, "0", "0", "How\u{0020}many\u{0020}more\u{0020}times\u{0020}do\u{0020}I\u{0020}have\u{0020}to\u{0020}swing\u{0020}this\u{0020}sword\u{0020}before\u{0020}I'm\u{0020}truly\u{0020}worthy?", "0", "到底還要再揮動多少次劍，才能抵達那個高度呢？", "0", "0", "0", "cv_sk2_Julius_12", "0", "0"},
[4000100315] = {4000100315, 10001003, 16, 10, "0", "0", "Let's\u{0020}march\u{0020}toward\u{0020}victory\u{0020}together,\u{0020}everyone!", "0", "大家，向著勝利前進吧！", "0", "0", "0", "cv_sk2_Julius_13", "0", "0"},
