[4000900100] = {4000900100, 10009001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_sk_morgan_33", "0", "0"},
[4000900101] = {4000900101, 10009001, 2, 2, "0", "0", "Me?\u{0020}Understood.\u{0020}I'll\u{0020}help\u{0020}you\u{0020}get\u{0020}the\u{0020}job\u{0020}done,\u{0020}Navigator.", "0", "我嗎…我明白了，我會好好協助領航您完成工作的。", "0", "0", "0", "cv_sk_morgan_2", "0", "0"},
[4000900102] = {4000900102, 10009001, 3, 3, "0", "0", "Greetings,\u{0020}Navigator.\u{0020}I'm\u{0020}Morgan\u{0020}Le\u{0020}Fay,\u{0020}captain\u{0020}of\u{0020}Moon\u{0020}Corona.\u{0020}Have\u{0020}Lilith\u{0020}and\u{0020}Skadi\u{0020}been\u{0020}giving\u{0020}you\u{0020}any\u{0020}trouble?", "0", "您好，領航。我是月冕的隊長，摩根勒菲，莉莉絲和斯卡蒂有給您添麻煩嗎？", "0", "0", "0", "cv_sk_morgan_1", "0", "0"},
[4000900103] = {4000900103, 10009001, 4, 4, "0", "idle", "There\u{0020}was\u{0020}an\u{0020}error\u{0020}with\u{0020}the\u{0020}latest\u{0020}magic\u{0020}trick...\u{0020}It's\u{0020}the\u{0020}first\u{0020}time\u{0020}I've\u{0020}faced\u{0020}such\u{0020}a\u{0020}serious\u{0020}mistake...", "0", "在創作新魔術的時候出現失誤了……但，但是，這麼嚴重的失誤，還是第一次遇到……", "0", "0", "0", "cv_sk_morgan_3", "0", "0"},
[4000900104] = {4000900104, 10009001, 5, 4, "0", "idle", "Bringing\u{0020}new\u{0020}magic\u{0020}tricks\u{0020}to\u{0020}the\u{0020}audience\u{0020}and\u{0020}seeing\u{0020}their\u{0020}smiles\u{0020}is\u{0020}such\u{0020}a\u{0020}joy.", "0", "不斷地為觀眾帶來新的魔術，讓他們臉上展露笑容，是一件很開心的事情。", "0", "0", "0", "cv_sk_morgan_4", "0", "0"},
[4000900105] = {4000900105, 10009001, 6, 4, "0", "idle", "Come\u{0020}on,\u{0020}Navigator,\u{0020}let's\u{0020}give\u{0020}it\u{0020}our\u{0020}best!", "0", "領航，加油噢。", "0", "0", "0", "cv_sk_morgan_30", "0", "0"},
[4000900106] = {4000900106, 10009001, 7, 5, "15_1_0_0.8", "touch1", "I'm\u{0020}really\u{0020}sorry\u{0020}you\u{0020}had\u{0020}to\u{0020}see\u{0020}me\u{0020}like\u{0020}this.\u{0020}A\u{0020}magician\u{0020}should\u{0020}always\u{0020}be\u{0020}ready\u{0020}to\u{0020}dazzle\u{0020}the\u{0020}crowd!", "0", "嗯……讓您看到我這副樣子，真是不好意思，魔術師應該隨時都準備著魔術滿足觀眾才對！", "0", "0", "0", "cv_sk_morgan_31", "0", "0"},
[4000900107] = {4000900107, 10009001, 8, 5, "15_2_0_0.8", "touch2", "This\u{0020}move\u{0020}is\u{0020}a\u{0020}bit\u{0020}tricky...\u{0020}Let\u{0020}me\u{0020}guide\u{0020}your\u{0020}hand.\u{0020}But\u{0020}first,\u{0020}let's\u{0020}clear\u{0020}away\u{0020}these\u{0020}props.", "0", "嗯……這裡的動作，稍微有點複雜，之後讓我手把手指導您的動作吧，但是首先……我得先擺脫這些道具。", "0", "0", "0", "cv_sk_morgan_5", "0", "0"},
[4000900108] = {4000900108, 10009001, 9, 5, "15_1_0_0.8", "touch1", "Ah—ah!\u{0020}I\u{0020}messed\u{0020}up\u{0020}again...\u{0020}Hehe,\u{0020}but\u{0020}I\u{0020}can\u{0020}already\u{0020}picture\u{0020}everyone's\u{0020}surprise\u{0020}when\u{0020}the\u{0020}trick\u{0020}finally\u{0020}works!\u{0020}Let's\u{0020}keep\u{0020}trying.", "0", "呀——啊！又搞砸了……嘿嘿，但是我能想象得到，這個魔術要是成功的話，大家一定會非常驚訝的，讓我們一起加油吧。", "0", "0", "0", "cv_sk_morgan_6", "0", "0"},
[4000900109] = {4000900109, 10009001, 10, 5, "15_1_0_0.8", "touch1", "...\u{0020}It's\u{0020}all\u{0020}a\u{0020}mess\u{0020}now.\u{0020}Um...\u{0020}Navigator...\u{0020}Can\u{0020}you\u{0020}help\u{0020}me\u{0020}out?", "0", "……完蛋了，好像越來越亂了。那個……領，領航……如果可以的話，能不能幫幫我？", "0", "0", "0", "cv_sk_morgan_7", "0", "0"},
[4000900110] = {4000900110, 10009001, 11, 5, "15_2_0_0.8", "touch2", "Another\u{0020}mistake...\u{0020}Sigh...\u{0020}But\u{0020}mistakes\u{0020}help\u{0020}us\u{0020}improve!\u{0020}Hold\u{0020}my\u{0020}hand,\u{0020}and\u{0020}let's\u{0020}try\u{0020}again.", "0", "又是在這裡出錯……嗚……不過錯誤的經歷經過積累，一定能成為我們成功的魔術。來，請搭著我的手，把我解救出來吧，讓我們再來一次。", "0", "0", "0", "cv_sk_morgan_8", "0", "0"},
[4000900111] = {4000900111, 10009001, 12, 6, "0", "0", "Thank\u{0020}you.\u{0020}I\u{0020}feel\u{0020}stronger\u{0020}already.", "0", "謝謝，這下變得更強了呢。", "0", "0", "0", "cv_sk_morgan_9", "0", "0"},
[4000900112] = {4000900112, 10009001, 13, 7, "0", "0", "Thank\u{0020}you...\u{0020}I\u{0020}won't\u{0020}let\u{0020}you\u{0020}down.", "0", "謝謝…我一定不會辜負領航您的期望的。", "0", "0", "0", "cv_sk_morgan_10", "0", "0"},
[4000900113] = {4000900113, 10009001, 14, 8, "0", "0", "Without\u{0020}realizing\u{0020}it,\u{0020}I've\u{0020}grown\u{0020}so\u{0020}much.\u{0020}I\u{0020}couldn't\u{0020}have\u{0020}done\u{0020}it\u{0020}alone—thank\u{0020}you,\u{0020}Navigator.\u{0020}Together,\u{0020}let's\u{0020}protect\u{0020}everyone\u{0020}from\u{0020}here\u{0020}on\u{0020}out.", "0", "不知不覺我也成長了許多…如果沒有領航的話，我一個人是不可能做到的。謝謝您，領航，今後也和我一起守護大家吧。", "0", "0", "0", "cv_sk_morgan_11", "0", "0"},
[4000900114] = {4000900114, 10009001, 15, 9, "0", "0", "I'll\u{0020}make\u{0020}good\u{0020}use\u{0020}of\u{0020}this\u{0020}power.", "0", "這份力量，我會好好使用的。", "0", "0", "0", "cv_sk_morgan_12", "0", "0"},
[4000900115] = {4000900115, 10009001, 16, 10, "0", "0", "The\u{0020}one\u{0020}who\u{0020}hurt\u{0020}my\u{0020}friends...\u{0020}Where\u{0020}are\u{0020}they?", "0", "傷害同伴的人…在哪？", "0", "0", "0", "cv_sk_morgan_13", "0", "0"},
[4000900116] = {4000900116, 10009001, 17, 11, "0", "0", "All\u{0020}enemies\u{0020}eliminated.\u{0020}We\u{0020}did\u{0020}it,\u{0020}Navigator.", "0", "敵人全滅，我們勝利了，領航。", "0", "0", "0", "cv_sk_morgan_14", "0", "0"},
[4000900117] = {4000900117, 10009001, 18, 12, "0", "0", "I\u{0020}have\u{0020}to\u{0020}do\u{0020}better...", "0", "我需要得做更好才行…不然……", "0", "0", "0", "cv_sk_morgan_15", "0", "0"},
