[4000900124] = {4000900124, 10009001, 25, 18, "0", "0", "Now,\u{0020}watch\u{0020}closely—this\u{0020}is\u{0020}the\u{0020}performance\u{0020}I've\u{0020}prepared\u{0020}just\u{0020}for\u{0020}you.", "0", "請看著吧，這是我為您準備的華麗演出。", "0", "0", "0", "cv_sk_morgan_22", "0", "0"},
[4000900125] = {4000900125, 10009001, 27, 20, "0", "0", "Navigator,\u{0020}I'm\u{0020}sorry\u{0020}for\u{0020}the\u{0020}trouble.", "0", "領航，麻煩您了。", "0", "0", "0", "cv_sk_morgan_23", "0", "0"},
[4000900126] = {4000900126, 10009001, 28, 21, "0", "0", "When\u{0020}I\u{0020}was\u{0020}in\u{0020}exile\u{0020}with\u{0020}my\u{0020}parents,\u{0020}I\u{0020}could\u{0020}never\u{0020}relax\u{0020}like\u{0020}this...", "0", "以前，和父母流亡的時候，都沒辦法像這樣靜下心來放鬆呢……", "0", "0", "0", "cv_sk_morgan_24", "0", "0"},
[4000900127] = {4000900127, 10009001, 29, 21, "0", "0", "Has\u{0020}Lilith\u{0020}come\u{0020}by?\u{0020}Did\u{0020}she\u{0020}scare\u{0020}you?\u{0020}Don't\u{0020}worry,\u{0020}I'll\u{0020}have\u{0020}a\u{0020}word\u{0020}with\u{0020}her\u{0020}later\u{0020}to\u{0020}make\u{0020}sure\u{0020}it\u{0020}doesn't\u{0020}happen\u{0020}again.", "0", "莉莉絲來過了嗎…您被她嚇到了？真是的…之後我會好好跟她溝通的，讓她不要再這麼做了。", "0", "0", "0", "cv_sk_morgan_25", "0", "0"},
[4000900128] = {4000900128, 10009001, 30, 22, "0", "0", "Navigator,\u{0020}please\u{0020}be\u{0020}careful\u{0020}out\u{0020}there.", "0", "領航，請小心。", "0", "0", "0", "cv_sk_morgan_26", "0", "0"},
[4000900129] = {4000900129, 10009001, 31, 23, "0", "0", "If\u{0020}you\u{0020}guess\u{0020}right,\u{0020}I'll\u{0020}perform\u{0020}a\u{0020}magic\u{0020}trick\u{0020}for\u{0020}you!", "0", "猜對了的話…我給您表演一個魔術吧？", "0", "0", "0", "cv_sk_morgan_27", "0", "0"},
[4000900130] = {4000900130, 10009001, 32, 24, "0", "0", "--Hey!\u{0020}Look,\u{0020}a\u{0020}rose!\u{0020}Pretty\u{0020}cool,\u{0020}right?", "0", "——嘿！玫瑰花出現了，如何，厲害吧？", "0", "0", "0", "cv_sk_morgan_28", "0", "0"},
[4000900131] = {4000900131, 10009001, 33, 25, "0", "0", "It's\u{0020}okay.\u{0020}I\u{0020}know\u{0020}Navigator\u{0020}will\u{0020}nail\u{0020}it\u{0020}next\u{0020}time...", "0", "沒關係，我相信領航您下次一定會成功的……", "0", "0", "0", "cv_sk_morgan_29", "0", "0"},
[4000900132] = {4000900132, 10009001, 34, 26, "0", "0", "Oh,\u{0020}Mr.\u{0020}Assistant,\u{0020}you're\u{0020}early\u{0020}today.\u{0020}Let's\u{0020}get\u{0020}ready\u{0020}and\u{0020}begin.", "0", "哦，助手先生今天也很早就來了呢，那麼在準備過後，我們就開始吧。", "0", "0", "0", "cv_sk_morgan_32", "0", "0"},
[4000900133] = {4000900133, 10009001, 35, 27, "0", "0", "If\u{0020}we\u{0020}don't\u{0020}fight...\u{0020}how\u{0020}can\u{0020}we\u{0020}protect\u{0020}everyone?", "0", "不戰鬥的話…就無法保護大家，不是嗎？", "0", "0", "0", "cv_sk_morgan_34", "0", "0"},
