[4001000101] = {4001000101, 10010001, 2, 2, "0", "0", "Don't\u{0020}get\u{0020}too\u{0020}captivated\u{0020}by\u{0020}me—we've\u{0020}still\u{0020}got\u{0020}work\u{0020}to\u{0020}do.", "0", "可不要看我看入迷了喔，那樣會耽誤工作的。", "0", "0", "0", "cv_sk_alaita_2", "0", "0"},
[4001000102] = {4001000102, 10010001, 3, 3, "0", "0", "Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad,\u{0020}Alaita.\u{0020}I\u{0020}hear\u{0020}Captain\u{0020}Dolores\u{0020}is\u{0020}in\u{0020}your\u{0020}good\u{0020}hands.\u{0020}Much\u{0020}appreciated.", "0", "第三研究室防衛班，阿萊塔。我家的多洛莉絲隊長受你照顧了，謝謝~", "0", "0", "0", "cv_sk_alaita_1", "0", "0"},
[4001000103] = {4001000103, 10010001, 4, 4, "0", "idle", "Haven't\u{0020}you\u{0020}seen\u{0020}it\u{0020}yet?\u{0020}The\u{0020}true\u{0020}face\u{0020}of\u{0020}the\u{0020}\"Siren.\"\u{0020}In\u{0020}this\u{0020}state,\u{0020}her\u{0020}singing\u{0020}becomes\u{0020}even\u{0020}more\u{0020}enchanting.", "見たことがないの？セイレーンの本当の姿を。この姿の時は、本当に素晴らしい歌声になるんだから。", "沒見過嗎？“海妖”真正的面目。這個狀態下的歌聲會更好聽噢。", "0", "0", "0", "cv_sk_alaita_3", "0", "0"},
[4001000104] = {4001000104, 10010001, 5, 4, "0", "idle", "I\u{0020}hope\u{0020}you'll\u{0020}never\u{0020}forget\u{0020}this\u{0020}moment.\u{0020}I'll\u{0020}sing\u{0020}for\u{0020}you\u{0020}in\u{0020}my\u{0020}most\u{0020}elegant\u{0020}form.", "この瞬間のことを、永遠に忘れないで。最も美しい姿で、あなたのために歌っている私のことを。", "希望你能永遠記住此刻，我將以最美的姿態來為你演唱。", "0", "0", "0", "cv_sk_alaita_4", "0", "0"},
[4001000105] = {4001000105, 10010001, 6, 4, "0", "idle", "Captain\u{0020}Dolores\u{0020}hasn't\u{0020}seen\u{0020}me\u{0020}like\u{0020}this.\u{0020}Hehe,\u{0020}I\u{0020}wonder\u{0020}how\u{0020}she'd\u{0020}react...", "ドロリィス隊長は、この姿をまだ見たことがないの。ふふ、見たらびっくりするかしら。", "多洛莉絲隊長還沒見過我現在的樣子。呵呵，要是被看到了不知道會不會被嚇一跳呢。", "0", "0", "0", "cv_sk_alaita_29", "0", "0"},
[4001000106] = {4001000106, 10010001, 7, 5, "15_1_0_0.8", "leve2", "The\u{0020}tragedy\u{0020}of\u{0020}the\u{0020}epiphyllum\u{0020}is\u{0020}that\u{0020}no\u{0020}one\u{0020}witnesses\u{0020}its\u{0020}bloom.\u{0020}But\u{0020}you,\u{0020}you're\u{0020}here\u{0020}to\u{0020}savor\u{0020}it\u{0020}with\u{0020}me.", "月下美人が悲しいのは、花咲く瞬間に立ち会ってくれる人がいないこと。でも私には、花咲く瞬間を共に過ごしてくれるあなたがいるの。", "曇花的哀傷在於綻放的刹那無人欣賞，所幸我能有你，來共度這盛放的瞬間。", "0", "0", "0", "cv_sk_alaita_30", "0", "0"},
[4001000107] = {4001000107, 10010001, 8, 5, "15_2_0_0.8", "leve1", "Wait...\u{0020}Hold\u{0020}on.\u{0020}Don't\u{0020}touch\u{0020}there\u{0020}just\u{0020}yet...", "ちょっと……やめて、そこは触らないで……", "等……等一下，先別碰那裏……", "0", "0", "0", "cv_sk_alaita_5", "0", "0"},
[4001000108] = {4001000108, 10010001, 9, 5, "15_3_0_0.8", "leve3", "Even\u{0020}with\u{0020}just\u{0020}the\u{0020}two\u{0020}of\u{0020}us,\u{0020}that's\u{0020}still\u{0020}a\u{0020}forbidden\u{0020}and\u{0020}dangerous\u{0020}area.", "ふたりきりだからって、そこは触れていい場所じゃないわよ。", "就算只有我們兩個人，那裏也是危險的禁區噢。", "0", "0", "0", "cv_sk_alaita_6", "0", "0"},
[4001000109] = {4001000109, 10010001, 10, 5, "15_2_0_0.8", "leve1", "Hah...\u{0020}I'm\u{0020}feeling\u{0020}a\u{0020}bit\u{0020}sleepy.\u{0020}Navigator,\u{0020}care\u{0020}to\u{0020}drift\u{0020}into\u{0020}a\u{0020}dream-filled\u{0020}bay\u{0020}with\u{0020}me?", "（あくび）ふぁ……んん……なんだか眠いわね。ナビゲーター。このまま一緒に夢の海に沈んでいかない？", "呼……呼……感覺有些困了。領航，與我一同沉入夢境的海灣，好嗎？", "0", "0", "0", "cv_sk_alaita_7", "0", "0"},
[4001000110] = {4001000110, 10010001, 11, 5, "15_1_0_0.8", "leve2", "I've\u{0020}planned\u{0020}this\u{0020}rendezvous\u{0020}for\u{0020}quite\u{0020}some\u{0020}time.\u{0020}This\u{0020}dress,\u{0020}worn\u{0020}only\u{0020}for\u{0020}you,\u{0020}Navigator—and\u{0020}only\u{0020}you\u{0020}get\u{0020}to\u{0020}undo\u{0020}my\u{0020}collar.", "今日のために、ずっと準備して来たの。この服、あなたのために着て来たのよ。この服のボタンを外していいのも、あなただけ。", "為了今日的幽約我已經準備許久，這件衣服只為領航你一人而穿著，也只有領航你一人能解開我衣領上的紐扣。", "0", "0", "0", "cv_sk_alaita_8", "0", "0"},
[4001000111] = {4001000111, 10010001, 12, 6, "0", "0", "It\u{0020}feels\u{0020}nice.", "0", "不錯的感覺。", "0", "0", "0", "cv_sk_alaita_9", "0", "0"},
[4001000112] = {4001000112, 10010001, 13, 7, "0", "0", "Do\u{0020}you\u{0020}want\u{0020}to\u{0020}see\u{0020}an\u{0020}even\u{0020}grander\u{0020}show?", "0", "想看更華麗的演出嗎？", "0", "0", "0", "cv_sk_alaita_10", "0", "0"},
[4001000113] = {4001000113, 10010001, 14, 8, "0", "0", "Hehe...\u{0020}Can\u{0020}you\u{0020}hear\u{0020}it?\u{0020}My\u{0020}sword\u{0020}sings\u{0020}not\u{0020}of\u{0020}my\u{0020}beauty\u{0020}but\u{0020}of\u{0020}its\u{0020}excitement—it's\u{0020}thrilled\u{0020}to\u{0020}defend\u{0020}Danube\u{0020}and\u{0020}Saar\u{0020}again.", "0", "呵呵……你能感受到嗎，這把劍正在發出喜悅的鳴聲呢。不，並不是在稱讚我的美麗。它一定是因為能夠再一次保護多瑙，保護薩爾而高興吧。", "0", "0", "0", "cv_sk_alaita_11", "0", "0"},
[4001000114] = {4001000114, 10010001, 15, 9, "0", "0", "Make\u{0020}me\u{0020}even\u{0020}more\u{0020}dazzling.", "0", "讓我變得更加美麗吧。", "0", "0", "0", "cv_sk_alaita_12", "0", "0"},
[4001000115] = {4001000115, 10010001, 16, 10, "0", "0", "I'll\u{0020}handle\u{0020}the\u{0020}show;\u{0020}you\u{0020}handle\u{0020}the\u{0020}applause!", "0", "我負責表演，你負責喝彩！", "0", "0", "0", "cv_sk_alaita_13", "0", "0"},
[4001000116] = {4001000116, 10010001, 17, 11, "0", "0", "Shower\u{0020}me\u{0020}with\u{0020}praise,\u{0020}adoration—and\u{0020}then\u{0020}let\u{0020}yourself\u{0020}fall\u{0020}for\u{0020}me.", "0", "誇讚我吧，稱讚我吧，然後迷戀上我吧。", "0", "0", "0", "cv_sk_alaita_14", "0", "0"},
[4001000117] = {4001000117, 10010001, 18, 12, "0", "0", "Well,\u{0020}Navigator,\u{0020}enough\u{0020}daydreaming.\u{0020}Let's\u{0020}get\u{0020}back\u{0020}to\u{0020}reality.", "0", "馬馬虎虎…領航，別發呆了，回去了。", "0", "0", "0", "cv_sk_alaita_15", "0", "0"},
[4001000118] = {4001000118, 10010001, 19, 13, "0", "0", "...\u{0020}Hmm,\u{0020}well,\u{0020}I\u{0020}guess\u{0020}that\u{0020}counts\u{0020}as\u{0020}getting\u{0020}the\u{0020}job\u{0020}done,\u{0020}right?", "0", "…嗯，這也算是完成工作了吧？", "0", "0", "0", "cv_sk_alaita_16", "0", "0"},
[4001000119] = {4001000119, 10010001, 20, 14, "0", "0", "What\u{0020}a\u{0020}flop\u{0020}of\u{0020}a\u{0020}performance.\u{0020}Wouldn't\u{0020}you\u{0020}agree?", "0", "嗯…真是一場失敗的演出，你不這樣認為嗎？", "0", "0", "0", "cv_sk_alaita_17", "0", "0"},
[4001000120] = {4001000120, 10010001, 21, 15, "0", "0", "Scatter\u{0020}beneath\u{0020}the\u{0020}thorns\u{0020}of\u{0020}the\u{0020}rose.", "バラのトゲに散りなさい。", "在玫瑰的荊條下消散吧。", "0", "0", "0", "cv_sk_alaita_18", "0", "0"},
[4001000121] = {4001000121, 10010001, 23, 16, "0", "0", "Top-secret\u{0020}performance.", "秘密の舞台を見せてあげる。", "絕密的表演。", "0", "0", "0", "cv_sk_alaita_19", "0", "0"},
