[4001000124] = {4001000124, 10010001, 27, 20, "0", "0", "Oh?\u{0020}You're\u{0020}here.", "0", "喔？你來了啊。", "0", "0", "0", "cv_sk_alaita_22", "0", "0"},
[4001000125] = {4001000125, 10010001, 28, 21, "0", "0", "Are\u{0020}you\u{0020}entranced?\u{0020}Don't\u{0020}be\u{0020}shy—compliment\u{0020}my\u{0020}beauty.", "0", "看入迷了嗎？不用害羞，稱讚我的美麗吧。", "0", "0", "0", "cv_sk_alaita_23", "0", "0"},
[4001000126] = {4001000126, 10010001, 29, 21, "0", "0", "I\u{0020}can't\u{0020}help\u{0020}but\u{0020}hum\u{0020}a\u{0020}tune...\u{0020}Have\u{0020}you\u{0020}brought\u{0020}wax\u{0020}to\u{0020}seal\u{0020}your\u{0020}ears?", "0", "情不自禁想哼歌呢…你準備了蠟來封耳朵嗎？", "0", "0", "0", "cv_sk_alaita_24", "0", "0"},
[4001000127] = {4001000127, 10010001, 30, 22, "0", "0", "Heh...\u{0020}Always\u{0020}stay\u{0020}sharp,\u{0020}right?", "0", "呵…提高警惕，對嗎？", "0", "0", "0", "cv_sk_alaita_25", "0", "0"},
[4001000128] = {4001000128, 10010001, 31, 23, "0", "0", "This\u{0020}curtain\u{0020}can't\u{0020}hide\u{0020}my\u{0020}starlight,\u{0020}can\u{0020}it?", "0", "這點幕布是遮擋不了我的星光的，對吧？", "0", "0", "0", "cv_sk_alaita_26", "0", "0"},
[4001000129] = {4001000129, 10010001, 32, 24, "0", "0", "Well\u{0020}done,\u{0020}Navigator.\u{0020}Unfortunately,\u{0020}no\u{0020}reward\u{0020}this\u{0020}time.", "0", "不愧是領航~遺憾的是，沒有獎勵喔。", "0", "0", "0", "cv_sk_alaita_27", "0", "0"},
[4001000130] = {4001000130, 10010001, 33, 25, "0", "0", "Put\u{0020}in\u{0020}more\u{0020}effort\u{0020}next\u{0020}time.", "0", "下次再努力吧。", "0", "0", "0", "cv_sk_alaita_28", "0", "0"},
[4001000131] = {4001000131, 10010001, 34, 26, "0", "0", "Welcome\u{0020}to\u{0020}our\u{0020}private\u{0020}stage.", "あなたと私の秘密の舞台にようこそ。", "歡迎來到你和我兩個人的秘密舞台。", "0", "0", "0", "cv_sk_alaita_31", "0", "0"},
[4001000132] = {4001000132, 10010001, 35, 27, "0", "0", "Is\u{0020}it\u{0020}time\u{0020}for\u{0020}the\u{0020}mission?\u{0020}Understood,\u{0020}let's\u{0020}go.", "0", "要執行任務了？我明白了，出發吧。", "0", "0", "0", "cv_sk_alaita_33", "0", "0"},
[4001000133] = {4001000133, 10010001, 36, 28, "0", "0", "Finish\u{0020}early\u{0020}and\u{0020}rest\u{0020}early.", "0", "早點完成，早點休息~", "0", "0", "0", "cv_sk_alaita_34", "0", "0"},
[4001000134] = {4001000134, 10010001, 37, 29, "0", "0", "Hello,\u{0020}everyone!", "0", "嗨，大家好~！", "0", "0", "0", "cv_sk_alaita_35", "0", "0"},
[4001000135] = {4001000135, 10010001, 38, 30, "0", "0", "Are\u{0020}new\u{0020}companions\u{0020}joining\u{0020}us?", "0", "要增加新的同伴嗎？", "0", "0", "0", "cv_sk_alaita_36", "0", "0"},
