[4001000142] = {4001000142, 10010001, 45, 37, "0", "0", "Humph.", "0", "吼~", "0", "0", "0", "cv_sk_alaita_43", "0", "0"},
[4001100100] = {4001100100, 10011001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響。", "0", "0", "0", "cv_sk_ruoshui_32", "0", "0"},
[4001100101] = {4001100101, 10011001, 2, 2, "0", "0", "Yes,\u{0020}I'll\u{0020}always\u{0020}be\u{0020}here,\u{0020}waiting\u{0020}for\u{0020}your\u{0020}next\u{0020}order,\u{0020}Navigator.", "0", "是，我會一直站在這等待您下一個命令的，領航哥哥。", "0", "0", "0", "cv_sk_ruoshui_2", "0", "0"},
[4001100102] = {4001100102, 10011001, 3, 3, "0", "0", "My\u{0020}name\u{0020}is\u{0020}Jacksui...\u{0020}My\u{0020}eyes?\u{0020}Don't\u{0020}worry\u{0020}about\u{0020}them.\u{0020}I\u{0020}can\u{0020}see\u{0020}you\u{0020}just\u{0020}fine,\u{0020}Navigator.", "0", "我的名字是弱水…眼睛？沒關係，我能看見您的，領航哥哥。", "0", "0", "0", "cv_sk_ruoshui_1", "0", "0"},
[4001100103] = {4001100103, 10011001, 4, 4, "0", "idle", "Can't\u{0020}see\u{0020}me,\u{0020}can't\u{0020}see\u{0020}me,\u{0020}can't\u{0020}see\u{0020}me,\u{0020}can't\u{0020}see\u{0020}me,\u{0020}can't\u{0020}see\u{0020}me...", "見つかりませんように、見つかりませんように……", "看不见我看不见我看不见我看不见我看不见我……", "0", "0", "0", "cv_sk_ruoshui_3", "0", "0"},
[4001100104] = {4001100104, 10011001, 5, 4, "0", "idle", "Navigator!\u{0020}Oh\u{0020}no,\u{0020}wait—this\u{0020}patient,\u{0020}it's\u{0020}dangerous\u{0020}to\u{0020}wander\u{0020}around\u{0020}the\u{0020}hospital\u{0020}like\u{0020}that...\u{0020}Please,\u{0020}go\u{0020}back\u{0020}to\u{0020}your\u{0020}ward.", "ナビゲーターのお兄さん！あ、いえ、患者さん、勝手に病院内を歩き回るのは危険なので……自分の病室に戻ってください。", "领航哥哥！啊不，这位病人，你这样在医院内随意走动是很危险的……请回到自己的病房。", "0", "0", "0", "cv_sk_ruoshui_4", "0", "0"},
[4001100105] = {4001100105, 10011001, 6, 4, "0", "idle", "Meika\u{0020}told\u{0020}me\u{0020}you\u{0020}were\u{0020}seriously\u{0020}ill\u{0020}and\u{0020}hospitalized,\u{0020}and\u{0020}it\u{0020}was\u{0020}risky\u{0020}for\u{0020}you\u{0020}to\u{0020}be\u{0020}alone...\u{0020}So\u{0020}I\u{0020}snuck\u{0020}in\u{0020}to\u{0020}protect\u{0020}you.\u{0020}But\u{0020}it\u{0020}seems\u{0020}you're\u{0020}not\u{0020}as\u{0020}sick\u{0020}as\u{0020}I\u{0020}thought.", "冥火さんが教えてくれたんです。ナビゲーターのお兄さんが重い病気で入院していて、ひとりじゃ危険だって…。…だから、お兄さんを守るために潜入しました。でも、お兄さんの様子からすると、そんなに重い病気でもなさそうですね。", "冥火告诉我，领航哥哥得了重病住院，一个人很危险……所以我才潜伏进来想要保护哥哥。可是看领航哥哥的样子好像病得并不是很重。", "0", "0", "0", "cv_sk_ruoshui_29", "0", "0"},
[4001100106] = {4001100106, 10011001, 7, 5, "15_1_0_0.8", "level1", "I'm\u{0020}here,\u{0020}secretly\u{0020}watching\u{0020}over\u{0020}you!\u{0020}There\u{0020}could\u{0020}be\u{0020}assassins\u{0020}lurking\u{0020}in\u{0020}the\u{0020}hospital,\u{0020}so\u{0020}I'm\u{0020}disguised.\u{0020}Please,\u{0020}treat\u{0020}me\u{0020}like\u{0020}an\u{0020}ordinary\u{0020}nurse,\u{0020}and\u{0020}don't\u{0020}let\u{0020}anyone\u{0020}know\u{0020}about\u{0020}our\u{0020}connection.", "私はお兄さんを守るためにここに来たんです！刺客を見つけ出すためには、変装しなくてはいけません。なので、お兄さんも私に看護師さんとして接してください。他の人に、私たちの関係を知られないように。", "我是来暗中保护哥哥的！为了找出可能存在医院的刺客，我必须伪装自己。请哥哥也把我当作一个普通的护士来对待，千万不要让别人发现我们之间的关系。", "0", "0", "0", "cv_sk_ruoshui_30", "0", "0"},
[4001100107] = {4001100107, 10011001, 8, 5, "15_2_0_0.8", "level2", "No,\u{0020}don't\u{0020}come\u{0020}any\u{0020}closer...\u{0020}Be...\u{0020}Be\u{0020}careful\u{0020}of\u{0020}the\u{0020}knives...", "ち、近づかないでください……ナ、ナイフが危ないので……", "不，不要靠近……小……小心刀子……", "0", "0", "0", "cv_sk_ruoshui_5", "0", "0"},
[4001100108] = {4001100108, 10011001, 9, 5, "15_2_0_0.8", "level2", "This\u{0020}uniform\u{0020}I\u{0020}grabbed\u{0020}from\u{0020}the\u{0020}changing\u{0020}room\u{0020}is\u{0020}too\u{0020}small.\u{0020}TV\u{0020}dramas\u{0020}never\u{0020}prepared\u{0020}me\u{0020}for\u{0020}this\u{0020}kind\u{0020}of\u{0020}situation.", "更衣室から取ってきたナース服、ちょっと小さすぎたかもしれません。こういうときはどうすれば…。ドラマでもやってませんでした。", "从更衣室随手拿的这件衣服太小了，电视剧里可没有讲过遇到这种情况该怎么办。", "0", "0", "0", "cv_sk_ruoshui_6", "0", "0"},
[4001100109] = {4001100109, 10011001, 10, 5, "15_2_0_0.8", "level2", "Rest\u{0020}up,\u{0020}Navigator.\u{0020}I'll\u{0020}stand\u{0020}guard\u{0020}and\u{0020}make\u{0020}sure\u{0020}no\u{0020}suspicious\u{0020}people\u{0020}come\u{0020}near\u{0020}the\u{0020}ward.", "お兄さんは安心して休んでください。弱水がお守りしますし、不審者は病室に近づかせません。", "哥哥放心养病，弱水会保护哥哥，绝不会让任何可疑的人接近病房。", "0", "0", "0", "cv_sk_ruoshui_7", "0", "0"},
[4001100110] = {4001100110, 10011001, 11, 5, "15_1_0_0.8", "level1", "Once\u{0020}you're\u{0020}better,\u{0020}let's\u{0020}go\u{0020}see\u{0020}a\u{0020}movie\u{0020}together.\u{0020}If\u{0020}we\u{0020}time\u{0020}it\u{0020}right,\u{0020}we\u{0020}can\u{0020}catch\u{0020}that\u{0020}premiere...\u{0020}Deal?", "お兄さんが快復したら、映画に行きましょう。日程的には、ちょうどあの映画のプレミア上映に間に合うはずなので……よし、決まりですね！", "等哥哥病好了，一切去看电影吧。算算时间，应该正好可以赶上那部电影的首映……就这样说好了哦！", "0", "0", "0", "cv_sk_ruoshui_8", "0", "0"},
[4001100111] = {4001100111, 10011001, 12, 6, "0", "0", "I've\u{0020}leveled\u{0020}up!", "0", "我升級了欸！", "0", "0", "0", "cv_sk_ruoshui_9", "0", "0"},
[4001100112] = {4001100112, 10011001, 13, 7, "0", "0", "The\u{0020}weapon's\u{0020}sharper!", "0", "武器變鋒利了！", "0", "0", "0", "cv_sk_ruoshui_10", "0", "0"},
[4001100113] = {4001100113, 10011001, 14, 8, "0", "0", "This\u{0020}is\u{0020}amazing...\u{0020}Power\u{0020}just\u{0020}keeps\u{0020}surging\u{0020}through\u{0020}me.\u{0020}Hmm,\u{0020}I've\u{0020}decided—this\u{0020}strength\u{0020}is\u{0020}for\u{0020}you,\u{0020}Navigator.\u{0020}From\u{0020}now\u{0020}on,\u{0020}no\u{0020}matter\u{0020}who\u{0020}the\u{0020}enemy\u{0020}is,\u{0020}\"Jacksui\"\u{0020}will\u{0020}take\u{0020}them\u{0020}down\u{0020}for\u{0020}you!", "0", "真是不可思議呢…力量在源源不斷地湧出。嗯，決定了，這份力量，這份強大，只為領航您而存在。今後，不管是什麼樣的敵人，“弱水”都會為了您，將他擊潰！", "0", "0", "0", "cv_sk_ruoshui_11", "0", "0"},
[4001100114] = {4001100114, 10011001, 15, 9, "0", "0", "I'm\u{0020}faster\u{0020}now!", "0", "速度變快了！", "0", "0", "0", "cv_sk_ruoshui_12", "0", "0"},
