[4001100117] = {4001100117, 10011001, 18, 12, "0", "0", "I'm\u{0020}fine...\u{0020}But\u{0020}there\u{0020}are\u{0020}others\u{0020}who\u{0020}need\u{0020}medical\u{0020}attention,\u{0020}Navigator.", "0", "我沒事…但是有傷員需要治療，領航。", "0", "0", "0", "cv_sk_ruoshui_15", "0", "0"},
