[4001100126] = {4001100126, 10011001, 29, 21, "0", "0", "Navigator,\u{0020}could\u{0020}you\u{0020}bring\u{0020}me\u{0020}a\u{0020}can\u{0020}of\u{0020}soda?\u{0020}Thanks!", "0", "哥哥，能幫我拿一聽碳酸飲料過來嗎~謝謝~", "0", "0", "0", "cv_sk_ruoshui_24", "0", "0"},
