[4001100133] = {4001100133, 10011001, 36, 28, "0", "0", "Jacksui,\u{0020}prepare\u{0020}to\u{0020}strike!", "0", "弱水，準備出擊！", "0", "0", "0", "cv_sk_ruoshui_34", "0", "0"},
