[4001200100] = {4001200100, 10012001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響。", "0", "0", "0", "cv_sk_guroria_32", "0", "0"},
[4001200101] = {4001200101, 10012001, 2, 2, "0", "0", "I'll\u{0020}be\u{0020}right\u{0020}here,\u{0020}watching\u{0020}you\u{0020}work.\u{0020}Boring?\u{0020}No\u{0020}need\u{0020}to\u{0020}worry\u{0020}about\u{0020}my\u{0020}feelings.", "0", "我會站在這，注視著您工作的……無聊？不，您無須在意我的感受。", "0", "0", "0", "cv_sk_guroria_2", "0", "0"},
[4001200102] = {4001200102, 10012001, 3, 3, "0", "0", "Hello!\u{0020}I'm\u{0020}Gloria,\u{0020}the\u{0020}newest\u{0020}member\u{0020}of\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad.\u{0020}From\u{0020}now\u{0020}on,\u{0020}you're\u{0020}my\u{0020}Navigator.", "0", "您好，我是第三研究室防衛班的新成員，格洛麗亞。從今天開始，您便是我的領航了。", "0", "0", "0", "cv_sk_guroria_1", "0", "0"},
[4001200103] = {4001200103, 10012001, 4, 4, "0", "idle", "Tell\u{0020}Charlissa\u{0020}that\u{0020}when\u{0020}people\u{0020}are\u{0020}drunk,\u{0020}they\u{0020}get\u{0020}red\u{0020}faces.\u{0020}I'm\u{0020}not\u{0020}red,\u{0020}so\u{0020}I'm\u{0020}not\u{0020}drunk.\u{0020}Um,\u{0020}just\u{0020}keep\u{0020}drinking!", "0", "告訴查麗莎，喝醉的人都會臉紅的。我沒有臉紅，所以沒有喝醉，嗯，接、接著喝！", "0", "0", "0", "cv_sk_guroria_3", "0", "0"},
[4001200104] = {4001200104, 10012001, 5, 4, "0", "idle", "There\u{0020}are\u{0020}two\u{0020}Navigators\u{0020}flying...\u{0020}Wait,\u{0020}now\u{0020}there\u{0020}are\u{0020}three...", "0", "有兩個領航在飛……呀，變成三個了……", "0", "0", "0", "cv_sk_guroria_4", "0", "0"},
[4001200105] = {4001200105, 10012001, 6, 4, "0", "idle", "Why\u{0020}are\u{0020}you\u{0020}staring\u{0020}at\u{0020}me?\u{0020}Oh,\u{0020}I\u{0020}get\u{0020}it.\u{0020}You\u{0020}want\u{0020}a\u{0020}drink\u{0020}too.\u{0020}Just\u{0020}say\u{0020}the\u{0020}word...\u{0020}Here,\u{0020}take\u{0020}it.\u{0020}Cheers!", "0", "怎麼一直盯著我看？我明白了，您也想來一杯。想喝就直說嘛……來，拿著，幹、乾杯！", "0", "0", "0", "cv_sk_guroria_29", "0", "0"},
[4001200106] = {4001200106, 10012001, 7, 5, "15_1_0_0.8", "level1", "This\u{0020}light\u{0020}and\u{0020}floaty\u{0020}feeling\u{0020}is\u{0020}so\u{0020}amusing...", "0", "這種輕飄飄的感覺，好有趣呀……", "0", "0", "0", "cv_sk_guroria_30", "0", "0"},
[4001200107] = {4001200107, 10012001, 8, 5, "15_2_0_0.8", "level2", "About\u{0020}that\u{0020}\"show\u{0020}hand\"\u{0020}you\u{0020}mentioned—I\u{0020}think\u{0020}I've\u{0020}heard\u{0020}someone\u{0020}talk\u{0020}about\u{0020}it\u{0020}before.\u{0020}Ah,\u{0020}right!\u{0020}I'm\u{0020}the\u{0020}dealer\u{0020}today,\u{0020}responsible\u{0020}for\u{0020}dealing\u{0020}the\u{0020}cards.\u{0020}Just\u{0020}give\u{0020}me\u{0020}a\u{0020}moment...\u{0020}Where\u{0020}did\u{0020}I\u{0020}put\u{0020}the\u{0020}cards?", "0", "您說的那個“梭哈”，好像有聽誰介紹過——啊，想起來了。我今天是荷官，負責發牌的，發牌……請等一下，我把牌放哪去了？", "0", "0", "0", "cv_sk_guroria_5", "0", "0"},
[4001200108] = {4001200108, 10012001, 9, 5, "15_1_0_0.8", "level1", "Sobering\u{0020}soup?\u{0020}No,\u{0020}thank\u{0020}you.\u{0020}I\u{0020}can\u{0020}handle\u{0020}my\u{0020}alcohol.", "0", "醒酒湯？拿、拿走。我酒量超大的。", "0", "0", "0", "cv_sk_guroria_6", "0", "0"},
[4001200109] = {4001200109, 10012001, 10, 5, "15_1_0_0.8", "level1", "Just\u{0020}like\u{0020}Mr.\u{0020}Navigator\u{0020}said,\u{0020}some\u{0020}people\u{0020}don't\u{0020}show\u{0020}signs\u{0020}of\u{0020}being\u{0020}drunk.\u{0020}So\u{0020}maybe\u{0020}I\u{0020}really\u{0020}am\u{0020}tipsy?\u{0020}Hehe.", "0", "……對哦，就像領航先生您所說的那樣，有些人是喝醉了也不上臉的。所以或許我確實是醉了？嘿嘿。", "0", "0", "0", "cv_sk_guroria_7", "0", "0"},
[4001200110] = {4001200110, 10012001, 11, 5, "15_1_0_0.8", "level1", "When\u{0020}I'm\u{0020}drunk,\u{0020}my\u{0020}head\u{0020}feels\u{0020}blissfully\u{0020}empty.\u{0020}I\u{0020}don't\u{0020}have\u{0020}to\u{0020}think\u{0020}or\u{0020}worry\u{0020}about\u{0020}anything...\u{0020}I\u{0020}quite\u{0020}enjoy\u{0020}this\u{0020}sensation.\u{0020}So,\u{0020}Mr.\u{0020}Navigator,\u{0020}can\u{0020}I\u{0020}have\u{0020}one\u{0020}more\u{0020}drink?\u{0020}Please?", "0", "醉了以後，腦袋裡空空的，什麼都不用考慮，也不用去顧慮任何事情……我還挺喜歡這種感覺的……所以領航先生，再讓我多喝一杯吧？好不好嘛~", "0", "0", "0", "cv_sk_guroria_8", "0", "0"},
[4001200111] = {4001200111, 10012001, 12, 6, "0", "0", "An\u{0020}upgrade?\u{0020}Oh,\u{0020}thank\u{0020}you!", "0", "升級？喔，謝謝。", "0", "0", "0", "cv_sk_guroria_9", "0", "0"},
[4001200112] = {4001200112, 10012001, 13, 7, "0", "0", "A\u{0020}rank\u{0020}promotion?\u{0020}I\u{0020}appreciate\u{0020}it!", "0", "階級提升，謝謝。", "0", "0", "0", "cv_sk_guroria_10", "0", "0"},
[4001200113] = {4001200113, 10012001, 14, 8, "0", "0", "Mr.\u{0020}Navigator,\u{0020}I've\u{0020}been\u{0020}so\u{0020}grateful\u{0020}for\u{0020}your\u{0020}support...\u{0020}But\u{0020}this\u{0020}isn't\u{0020}what\u{0020}I\u{0020}truly\u{0020}hoped\u{0020}for.\u{0020}Can\u{0020}you\u{0020}be\u{0020}a\u{0020}bit\u{0020}closer\u{0020}to\u{0020}me?", "0", "領航先生…一直以來，我十分感謝您對我的幫助…可，這些並不是我所希望的。領航先生…能，離我更近一些嗎？", "0", "0", "0", "cv_sk_guroria_11", "0", "0"},
[4001200114] = {4001200114, 10012001, 15, 9, "0", "0", "Thank\u{0020}you,\u{0020}Mr.\u{0020}Navigator.", "0", "謝謝您，領航先生。", "0", "0", "0", "cv_sk_guroria_12", "0", "0"},
