[4001200116] = {4001200116, 10012001, 17, 11, "0", "0", "Did\u{0020}we\u{0020}win?\u{0020}That's\u{0020}great!\u{0020}Thanks\u{0020}to\u{0020}everyone.", "0", "勝利了嗎，嗯，那就好，多虧大家了。", "0", "0", "0", "cv_sk_guroria_14", "0", "0"},
