[4001200124] = {4001200124, 10012001, 27, 20, "0", "0", "Are\u{0020}you\u{0020}coming\u{0020}too?\u{0020}If\u{0020}you\u{0020}are,\u{0020}then\u{0020}do\u{0020}as\u{0020}you\u{0020}wish.", "0", "您也要一起過來嗎？是嗎…那按您喜歡的來吧。", "0", "0", "0", "cv_sk_guroria_22", "0", "0"},
[4001200125] = {4001200125, 10012001, 28, 21, "0", "0", "Mr.\u{0020}Navigator,\u{0020}if\u{0020}you're\u{0020}tired,\u{0020}don't\u{0020}push\u{0020}yourself\u{0020}too\u{0020}hard.", "0", "領航先生，您累了的話，就別勉強了。", "0", "0", "0", "cv_sk_guroria_23", "0", "0"},
[4001200126] = {4001200126, 10012001, 29, 21, "0", "0", "You've\u{0020}worked\u{0020}hard,\u{0020}Mr.\u{0020}Navigator.\u{0020}Let\u{0020}me\u{0020}take\u{0020}care\u{0020}of\u{0020}the\u{0020}rest...\u{0020}Is\u{0020}that\u{0020}alright?\u{0020}I\u{0020}understand.", "0", "領航先生，辛苦您了。剩下的讓我自己來…不行嗎？…我明白了。", "0", "0", "0", "cv_sk_guroria_24", "0", "0"},
[4001200127] = {4001200127, 10012001, 30, 22, "0", "0", "Oh...\u{0020}it's\u{0020}an\u{0020}event.", "0", "喔…是事件。", "0", "0", "0", "cv_sk_guroria_25", "0", "0"},
