[4001200131] = {4001200131, 10012001, 34, 26, "0", "0", "Oh?\u{0020}Mr.\u{0020}Navigator,\u{0020}haven't\u{0020}you\u{0020}finished\u{0020}today's\u{0020}tasks\u{0020}yet?\u{0020}You're\u{0020}really\u{0020}dedicated.\u{0020}Burp.", "0", "哦？領航先生今天的工作還沒有結束嗎？您可真是太辛苦了、嗝。", "0", "0", "0", "cv_sk_guroria_31", "0", "0"},
[4001200132] = {4001200132, 10012001, 35, 27, "0", "0", "Let's\u{0020}go,\u{0020}Mr.\u{0020}Navigator.\u{0020}I\u{0020}don't\u{0020}have\u{0020}anything\u{0020}to\u{0020}prepare.", "0", "領航先生，出發吧，我沒有需要準備的東西。", "0", "0", "0", "cv_sk_guroria_33", "0", "0"},
