[4001300100] = {4001300100, 10013001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響。", "0", "0", "0", "cv_sk_lilith_31", "0", "0"},
[4001300101] = {4001300101, 10013001, 2, 2, "0", "0", "Why\u{0020}do\u{0020}you\u{0020}care\u{0020}so\u{0020}much\u{0020}about\u{0020}me?", "0", "為什麼要這麼在意我？", "0", "0", "0", "cv_sk_lilith_2", "0", "0"},
[4001300102] = {4001300102, 10013001, 3, 3, "0", "0", "Ah,\u{0020}that\u{0020}familiar\u{0020}smell.\u{0020}You\u{0020}must\u{0020}be\u{0020}the\u{0020}true\u{0020}Synesthete.\u{0020}Let\u{0020}me\u{0020}say\u{0020}this\u{0020}first:\u{0020}I\u{0020}hate\u{0020}all\u{0020}Synesthetes,\u{0020}including\u{0020}myself.", "0", "啊，熟悉的味道啊。你就是那個真正的通感者吧。話先說在前面，我討厭所有的通感者，當然也包括我自己。", "0", "0", "0", "cv_sk_lilith_1", "0", "0"},
[4001300103] = {4001300103, 10013001, 4, 4, "0", "idle", "The\u{0020}bell\u{0020}has\u{0020}rung.\u{0020}Can\u{0020}you\u{0020}hear\u{0020}it?\u{0020}It\u{0020}hovers\u{0020}above\u{0020}the\u{0020}suffering\u{0020}of\u{0020}the\u{0020}people,\u{0020}stirring\u{0020}the\u{0020}faith\u{0020}willing\u{0020}to\u{0020}abandon\u{0020}everything.", "鳴り響く鐘の音が聞こえるかしら？苦しむ人々の頭上で、すべての信仰心を投げうつように迫っているの。", "鐘聲已響，你是否能夠聽見？它正於人們苦難的天空盤旋，激蕩出情願揚棄一切的信仰。", "0", "0", "0", "cv_sk_lilith_3", "0", "0"},
[4001300104] = {4001300104, 10013001, 5, 4, "0", "idle", "In\u{0020}the\u{0020}face\u{0020}of\u{0020}meaningless\u{0020}waiting,\u{0020}the\u{0020}candlelight\u{0020}will\u{0020}gradually\u{0020}burn\u{0020}out,\u{0020}yet\u{0020}our\u{0020}sins\u{0020}will\u{0020}remain\u{0020}unalleviated.", "無意味に待っている間にも、ロウソクは燃え続けていく。けれど、それと共に我々の罪が減っていくわけではないわ。", "在無意義的等待面前，燭火會漸漸燃盡，但我們的罪惡並不會隨之減輕分毫。", "0", "0", "0", "cv_sk_lilith_4", "0", "0"},
[4001300105] = {4001300105, 10013001, 6, 4, "0", "idle", "I\u{0020}can't\u{0020}clearly\u{0020}see\u{0020}the\u{0020}miracle\u{0020}shown\u{0020}by\u{0020}Morgan\u{0020}Le\u{0020}Fay...\u{0020}Is\u{0020}this\u{0020}also\u{0020}a\u{0020}result\u{0020}of\u{0020}my\u{0020}deep\u{0020}sin?", "モーガンルフェイ聖座さまの起こす奇跡は、私の目には映らない……これもまた私の罪の深さゆえか……", "摩根勒菲聖座大人所展現出的奇跡，我的眼卻無法清晰看見……這也是由於吾罪之深嗎？", "0", "0", "0", "cv_sk_lilith_28", "0", "0"},
[4001300106] = {4001300106, 10013001, 7, 5, "1_》_0_0.8", "level1", "If\u{0020}human\u{0020}nature\u{0020}is\u{0020}inherently\u{0020}full\u{0020}of\u{0020}Sin,\u{0020}should\u{0020}we\u{0020}embrace\u{0020}it\u{0020}or\u{0020}reject\u{0020}it?", "もし人の本性が……人類の本質が原罪に塗れているのであれば、それを受け入れるべきなのか。それとも拒絶すべきなのか。", "如果人性——人類的性質本身就飽含原罪，那麼究竟該擁抱它，還是拒絕它？", "0", "0", "0", "cv_sk_lilith_29", "0", "0"},
[4001300107] = {4001300107, 10013001, 8, 5, "1_》_0_0.8", "level1", "Please\u{0020}don't\u{0020}touch\u{0020}my\u{0020}body\u{0020}carelessly;\u{0020}it\u{0020}might\u{0020}disrupt\u{0020}the\u{0020}ceremony.", "私の体をみだりに触らないで。儀式が壊れてしまうわ。", "還請不要亂碰我的身體，以免破壞了儀式。", "0", "0", "0", "cv_sk_lilith_5", "0", "0"},
[4001300108] = {4001300108, 10013001, 9, 5, "1_》_0_0.8", "level2", "Even\u{0020}with\u{0020}my\u{0020}eyes\u{0020}covered,\u{0020}in\u{0020}this\u{0020}deep\u{0020}darkness,\u{0020}your\u{0020}existence\u{0020}stands\u{0020}out\u{0020}so\u{0020}clearly...\u{0020}It's\u{0020}impossible\u{0020}to\u{0020}ignore.", "両目が塞がれようと、深い闇の中であなたの存在を感じ取ることができるわ……とても無視できないほどに。", "即使蒙住雙眼，在我所見的深邃黑暗中，你的存在還是如此突兀……讓人完全無法忽視啊。", "0", "0", "0", "cv_sk_lilith_6", "0", "0"},
[4001300109] = {4001300109, 10013001, 10, 5, "1_》_0_0.8", "level3", "I\u{0020}can\u{0020}feel\u{0020}your\u{0020}burning,\u{0020}sunny\u{0020}gaze\u{0020}directly\u{0020}on\u{0020}me,\u{0020}as\u{0020}if\u{0020}it\u{0020}wants\u{0020}to\u{0020}penetrate\u{0020}everything.\u{0020}What\u{0020}do\u{0020}you\u{0020}see\u{0020}in\u{0020}me?\u{0020}Or\u{0020}what\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}see?", "あなたの燃え盛る太陽のような視線を感じるわ。あなたは私に何を見ているの？それとも、何を見ようとしているの？", "我能感覺到，你那熾烈陽光般的視線正直射在我身上，像是要洞穿一切。你從我這看見了什麼？還是想要看見什麼呢？", "0", "0", "0", "cv_sk_lilith_7", "0", "0"},
[4001300110] = {4001300110, 10013001, 11, 5, "1_》_0_0.8", "level4", "The\u{0020}remnants\u{0020}of\u{0020}the\u{0020}church,\u{0020}melted\u{0020}wax,\u{0020}fallen\u{0020}flowers,\u{0020}and\u{0020}my\u{0020}distorted\u{0020}posture\u{0020}all\u{0020}symbolize\u{0020}something\u{0020}in\u{0020}this\u{0020}ceremony.\u{0020}Yet,\u{0020}the\u{0020}meaning\u{0020}of\u{0020}your\u{0020}presence\u{0020}here\u{0020}is\u{0020}completely\u{0020}beyond\u{0020}my\u{0020}understanding.\u{0020}Can\u{0020}you\u{0020}explain\u{0020}it\u{0020}to\u{0020}me?", "教会の残骸。溶けたロウソク。色あせた花。そしてねじれた私の姿。儀式では全てのものが意味を持つけれど、唯一、あなたがここにいる意味が理解できないの。さぁ……私にそれを教えて？", "教堂的殘礫，融化的蠟液，凋落的鮮花，以及我這副扭曲姿態，在儀式中各有其象徵，唯獨你身處於此的含義我完全不懂。接下來……你能告訴我嗎？", "0", "0", "0", "cv_sk_lilith_8", "0", "0"},
[4001300111] = {4001300111, 10013001, 12, 6, "0", "0", "Yes,\u{0020}just\u{0020}continue\u{0020}like\u{0020}this.", "0", "沒錯，就這樣繼續下去吧。", "0", "0", "0", "cv_sk_lilith_9", "0", "0"},
[4001300112] = {4001300112, 10013001, 13, 7, "0", "0", "Very\u{0020}good...\u{0020}So\u{0020}my\u{0020}illness\u{0020}can\u{0020}be\u{0020}cured\u{0020}this\u{0020}way,\u{0020}right?", "0", "很好……這麼一來我的病就能痊癒了吧……", "0", "0", "0", "cv_sk_lilith_10", "0", "0"},
[4001300113] = {4001300113, 10013001, 14, 8, "0", "0", "No\u{0020}matter\u{0020}how\u{0020}hard\u{0020}I\u{0020}try,\u{0020}I\u{0020}can't\u{0020}escape\u{0020}my\u{0020}identity\u{0020}as\u{0020}a\u{0020}Synesthete.\u{0020}But\u{0020}those\u{0020}annoying\u{0020}voices\u{0020}seem\u{0020}to\u{0020}have\u{0020}softened...\u{0020}I\u{0020}can\u{0020}hear\u{0020}other\u{0020}sounds\u{0020}now—the\u{0020}blessings,\u{0020}the\u{0020}thanks,\u{0020}and\u{0020}the\u{0020}prayers\u{0020}sung\u{0020}by\u{0020}the\u{0020}children.", "0", "果然，無論怎麼樣都無法擺脫通感者的身份嗎……只是，那些讓人討厭的聲音好像變得柔和了……我好像能聽到其他的聲音了。孩子們的祝福，感謝以及……祈禱的歌聲。", "0", "0", "0", "cv_sk_lilith_11", "0", "0"},
[4001300114] = {4001300114, 10013001, 15, 9, "0", "0", "The\u{0020}electric\u{0020}current\u{0020}has\u{0020}increased.", "0", "電流量提升了呢。", "0", "0", "0", "cv_sk_lilith_12", "0", "0"},
[4001300115] = {4001300115, 10013001, 16, 10, "0", "0", "So\u{0020}annoying.", "0", "真討厭啊。", "0", "0", "0", "cv_sk_lilith_13", "0", "0"},
[4001300116] = {4001300116, 10013001, 17, 11, "0", "0", "Don't\u{0020}rush\u{0020}to\u{0020}thank\u{0020}me.", "0", "不用急著感謝我。", "0", "0", "0", "cv_sk_lilith_14", "0", "0"},
