[4001600104] = {4001600104, 10016001, 5, 4, "0", "idle", "Once\u{0020}these\u{0020}cups\u{0020}are\u{0020}sorted,\u{0020}I\u{0020}can\u{0020}finally\u{0020}change\u{0020}out\u{0020}of\u{0020}this\u{0020}outfit.", "0", "只要把這些杯子整理完，就能換回原本的衣服了。", "0", "0", "0", "cv_sk_anan_4", "0", "0"},
[4001600105] = {4001600105, 10016001, 6, 4, "0", "idle", "I\u{0020}don't\u{0020}really\u{0020}get\u{0020}why\u{0020}waitresses\u{0020}need\u{0020}to\u{0020}wear\u{0020}something\u{0020}so\u{0020}revealing,\u{0020}but\u{0020}since\u{0020}the\u{0020}customers\u{0020}are\u{0020}all\u{0020}students,\u{0020}there's\u{0020}no\u{0020}need\u{0020}to\u{0020}feel\u{0020}shy...\u{0020}Plus,\u{0020}the\u{0020}class\u{0020}monitor\u{0020}recommended\u{0020}this\u{0020}job.", "0", "雖然不是很理解為什麼服務員要穿這麼暴露的服裝，但光顧的客人都是學院的學生倒也沒什麼好害羞的……而且這裏可是班長推薦的打工地點。", "0", "0", "0", "cv_sk_anan_29", "0", "0"},
[4001600106] = {4001600106, 10016001, 7, 5, "15_1_0_0.8", "level1", "This\u{0020}rabbit\u{0020}costume\u{0020}is\u{0020}such\u{0020}a\u{0020}pain.\u{0020}Why\u{0020}do\u{0020}city\u{0020}folks\u{0020}love\u{0020}dressing\u{0020}up\u{0020}as\u{0020}rabbits?\u{0020}Back\u{0020}home,\u{0020}rabbits\u{0020}are\u{0020}just\u{0020}food...", "0", "這件兔子衣服穿著真不舒服，為什麼城市裏的人會喜歡扮成兔子呢？在我老家，兔子可是用來吃的東西……", "0", "0", "0", "cv_sk_anan_30", "0", "0"},
[4001600107] = {4001600107, 10016001, 8, 5, "15_1_0_0.8", "level1", "Can\u{0020}I\u{0020}get\u{0020}you\u{0020}a\u{0020}drink?", "0", "請問，您想要點什麼飲品嗎？", "0", "0", "0", "cv_sk_anan_5", "0", "0"},
[4001600108] = {4001600108, 10016001, 9, 5, "15_1_0_0.8", "level1", "Should\u{0020}I\u{0020}tell\u{0020}the\u{0020}manager\u{0020}about\u{0020}the\u{0020}suspicious\u{0020}people\u{0020}outside?\u{0020}Wait,\u{0020}it's\u{0020}just\u{0020}the\u{0020}Navigator...", "0", "要不要告訴店長，外面有奇怪的人……但仔細看的話，好像是領航？", "0", "0", "0", "cv_sk_anan_6", "0", "0"},
[4001600109] = {4001600109, 10016001, 10, 5, "15_2_0_0.8", "level2", "Who's\u{0020}watching\u{0020}me?\u{0020}Navigator?...\u{0020}Um,\u{0020}could\u{0020}you\u{0020}please\u{0020}stop\u{0020}staring?\u{0020}It's\u{0020}hard\u{0020}to\u{0020}focus\u{0020}on\u{0020}cleaning\u{0020}when\u{0020}you're\u{0020}looking\u{0020}at\u{0020}me\u{0020}like\u{0020}that...", "0", "誰，誰在偷看？領航？……唔，可以不可以不要這樣盯著我……你看著我的話，我很難繼續清掃的工作……", "0", "0", "0", "cv_sk_anan_7", "0", "0"},
[4001600110] = {4001600110, 10016001, 11, 5, "15_2_0_0.8", "level2", "I\u{0020}wasn't\u{0020}expecting\u{0020}to\u{0020}see\u{0020}you\u{0020}here,\u{0020}Navigator.\u{0020}Unfortunately,\u{0020}we've\u{0020}already\u{0020}closed\u{0020}for\u{0020}the\u{0020}day.\u{0020}Next\u{0020}time,\u{0020}come\u{0020}earlier\u{0020}and\u{0020}I'll\u{0020}make\u{0020}sure\u{0020}to\u{0020}serve\u{0020}you!", "0", "我沒想到會在這裏看到領航，真可惜現在店裏已經打烊了……領航下次早點來，安安會盡全力那個……服，服務好您！", "0", "0", "0", "cv_sk_anan_8", "0", "0"},
