[4001600112] = {4001600112, 10016001, 13, 7, "0", "0", "Finally,\u{0020}I\u{0020}understand\u{0020}this!", "0", "這個知識點，終於理解了。", "0", "0", "0", "cv_sk_anan_10", "0", "0"},
