[4001800101] = {4001800101, 10018001, 2, 2, "0", "0", "Leave\u{0020}it\u{0020}to\u{0020}me.", "0", "交給我吧。", "0", "0", "0", "cv_sk_lyfa_2", "0", "0"},
[4001800102] = {4001800102, 10018001, 3, 3, "0", "0", "Lyfa\u{0020}from\u{0020}the\u{0020}Valkyries\u{0020}Team\u{0020}reporting\u{0020}in.\u{0020}Navigator...\u{0020}Can\u{0020}I\u{0020}call\u{0020}you\u{0020}Master?", "0", "瓦爾基裏小隊的莉法，向您報導。領航……我能稱呼您為主人嗎？", "0", "0", "0", "cv_sk_lyfa_1", "0", "0"},
[4001800103] = {4001800103, 10018001, 4, 4, "0", "idle", "Take\u{0020}a\u{0020}break.\u{0020}Today's\u{0020}training\u{0020}isn't\u{0020}up\u{0020}to\u{0020}standard.", "少し休憩したら再開しましょう。…今日の訓練目標は、まだ達成していませんので。", "休息一下然后继续……今天的训练还远远没有达标。", "0", "0", "0", "cv_sk_lyfa_3", "0", "0"},
[4001800104] = {4001800104, 10018001, 5, 4, "0", "idle", "The\u{0020}night\u{0020}sky\u{0020}glimmers\u{0020}with\u{0020}the\u{0020}Milky\u{0020}Way,\u{0020}leaving\u{0020}behind\u{0020}shining\u{0020}traces.\u{0020}I\u{0020}wonder\u{0020}if\u{0020}my\u{0020}skating\u{0020}posture\u{0020}can\u{0020}even\u{0020}come\u{0020}close\u{0020}to\u{0020}one\u{0020}percent\u{0020}of\u{0020}that\u{0020}beauty.", "遠い夜空の星は、光の跡を残し、銀河を流れて行く。私のスケートは、あの夜空の美しさの１パーセントには及ぶでしょうか。", "远处的夜空在银河间滑行，留下闪光的线痕。不知道我滑冰的舞姿能否比得上百分之一的夜空。", "0", "0", "0", "cv_sk_lyfa_4", "0", "0"},
[4001800105] = {4001800105, 10018001, 6, 4, "0", "idle", "I\u{0020}didn't\u{0020}expect\u{0020}the\u{0020}ice\u{0020}here\u{0020}to\u{0020}support\u{0020}such\u{0020}a\u{0020}massive\u{0020}body;\u{0020}it\u{0020}truly\u{0020}feels\u{0020}like\u{0020}a\u{0020}natural\u{0020}skating\u{0020}rink.\u{0020}I\u{0020}can't\u{0020}waste\u{0020}nature's\u{0020}generosity—I\u{0020}have\u{0020}to\u{0020}train\u{0020}harder.", "これほど巨大な身体の重みに耐えられるなんて、本当に素晴らしい天然のスケートリンクですね。大自然のご厚意に応えるためにも、もっと頑張らなくては。", "没想到这里的冰面能承载这么巨大身体的重量，简直是天然的滑冰场。我可不能辜负大自然好意，要更努力地训练才行。", "0", "0", "0", "cv_sk_lyfa_29", "0", "0"},
[4001800106] = {4001800106, 10018001, 7, 5, "1_》_0_0.8", "level1", "Skating\u{0020}is\u{0020}part\u{0020}of\u{0020}a\u{0020}maid's\u{0020}training;\u{0020}it\u{0020}sharpens\u{0020}balance\u{0020}and\u{0020}strength\u{0020}control.\u{0020}Of\u{0020}course,\u{0020}this\u{0020}is\u{0020}my\u{0020}first\u{0020}time\u{0020}skating\u{0020}after\u{0020}such\u{0020}a\u{0020}dramatic\u{0020}transformation.", "スケートもメイド修行の一環なんですよ。バランス感覚や筋力のコントロールを鍛えることができるんです。巨大化した姿でスケートをするのは初めてですがね……。", "滑冰运动也是女仆修行的一环。这可以锻炼身体的平衡感以及对力量的控制。当然像这样巨大化后滑冰还是第一次。", "0", "0", "0", "cv_sk_lyfa_30", "0", "0"},
[4001800107] = {4001800107, 10018001, 8, 5, "1_》_0_0.8", "level1", "Does\u{0020}Master\u{0020}care\u{0020}about\u{0020}my\u{0020}outfit?\u{0020}This\u{0020}costume\u{0020}is\u{0020}specially\u{0020}designed\u{0020}for\u{0020}skating.", "ご主人様、この服装が気になるんですか？これはスケートのためにデザインされた専用の衣装なんですよ。", "主人很在意我这件衣服吗？这可是专门为了滑冰而设计的服装。", "0", "0", "0", "cv_sk_lyfa_5", "0", "0"},
[4001800108] = {4001800108, 10018001, 9, 5, "1_》_100_1.5", "level1", "It's\u{0020}really\u{0020}cold...\u{0020}I'm\u{0020}sorry,\u{0020}but\u{0020}I\u{0020}can't\u{0020}prepare\u{0020}warm\u{0020}black\u{0020}tea\u{0020}for\u{0020}you\u{0020}right\u{0020}now.", "寒いのですか？……いまはご主人様に温かい紅茶をご用意できず、申し訳ございません。", "很冷吧……抱歉，我现在没法为主人准备暖身的红茶。", "0", "0", "0", "cv_sk_lyfa_6", "0", "0"},
[4001800109] = {4001800109, 10018001, 10, 5, "1_》_500_2", "level1", "Would\u{0020}you\u{0020}like\u{0020}to\u{0020}see\u{0020}my\u{0020}skating\u{0020}posture?\u{0020}Of\u{0020}course,\u{0020}Master!\u{0020}Whenever\u{0020}and\u{0020}wherever\u{0020}you\u{0020}want,\u{0020}I'll\u{0020}dance\u{0020}for\u{0020}you.", "私のスケートを見たいのですか？畏まりました、ご主人様。お望みでしたら、いつでもどこでも、ご主人様のために舞いましょう。", "想要观赏我滑冰时的舞姿？好的，主人。无论何时何地，只要您想，我都会为您起舞。", "0", "0", "0", "cv_sk_lyfa_7", "0", "0"},
[4001800110] = {4001800110, 10018001, 11, 5, "1_》_1000_2.5", "level1", "I\u{0020}would\u{0020}love\u{0020}to\u{0020}invite\u{0020}you\u{0020}to\u{0020}dance\u{0020}with\u{0020}me.\u{0020}Well,\u{0020}not\u{0020}right\u{0020}now.\u{0020}Unless...\u{0020}if\u{0020}I\u{0020}de-transform,\u{0020}can\u{0020}you\u{0020}catch\u{0020}me\u{0020}in\u{0020}the\u{0020}air?\u{0020}I\u{0020}believe\u{0020}you\u{0020}can,\u{0020}but\u{0020}as\u{0020}your\u{0020}maid,\u{0020}I\u{0020}won't\u{0020}let\u{0020}you\u{0020}worry\u{0020}about\u{0020}me.", "ご主人様と一緒に滑ってみたいですね。もちろん、今ということではなく…。…もし、いま私が幻化を解除したら、ご主人様は私を受け止めてくださいますか？もちろん、ご主人様なら受け止めてくれると信じています。ですが、メイドとしてご主人様にご迷惑をおかけわけにはいきませんよね。", "我想邀请主人与我共舞，当然不是现在，除非……如果我现在解除幻化，主人能在空中接住我吗？我相信您可以，但身为女仆我不会让主人为我担心。", "0", "0", "0", "cv_sk_lyfa_8", "0", "0"},
[4001800111] = {4001800111, 10018001, 12, 6, "0", "0", "I\u{0020}can\u{0020}feel\u{0020}my\u{0020}abilities\u{0020}improving.", "0", "感覺到能力有提升了。", "0", "0", "0", "cv_sk_lyfa_9", "0", "0"},
[4001800112] = {4001800112, 10018001, 13, 7, "0", "0", "I'm\u{0020}one\u{0020}step\u{0020}closer\u{0020}to\u{0020}becoming\u{0020}a\u{0020}professional\u{0020}maid.", "0", "離成為專業女僕又進了一步。", "0", "0", "0", "cv_sk_lyfa_10", "0", "0"},
[4001800113] = {4001800113, 10018001, 14, 8, "0", "0", "I\u{0020}appreciate\u{0020}your\u{0020}kindness,\u{0020}Master.\u{0020}Everything\u{0020}I\u{0020}receive\u{0020}from\u{0020}you\u{0020}will\u{0020}be\u{0020}used\u{0020}to\u{0020}serve\u{0020}you\u{0020}better.", "0", "主人的心意，我感受到了。從主人那得到的全部，我都會用來更好地服侍您的。", "0", "0", "0", "cv_sk_lyfa_11", "0", "0"},
[4001800114] = {4001800114, 10018001, 15, 9, "0", "0", "Cleaning\u{0020}skill\u{0020}up!", "0", "清掃技能up！", "0", "0", "0", "cv_sk_lyfa_12", "0", "0"},
[4001800115] = {4001800115, 10018001, 16, 10, "0", "0", "Is\u{0020}this\u{0020}the\u{0020}area\u{0020}that\u{0020}needs\u{0020}cleaning?", "0", "是這裏需要清掃嗎？", "0", "0", "0", "cv_sk_lyfa_13", "0", "0"},
[4001800116] = {4001800116, 10018001, 17, 11, "0", "0", "Don't\u{0020}underestimate\u{0020}the\u{0020}power\u{0020}of\u{0020}a\u{0020}maid.", "0", "可不要小瞧女僕的厲害之處哦。", "0", "0", "0", "cv_sk_lyfa_14", "0", "0"},
[4001800117] = {4001800117, 10018001, 18, 12, "0", "0", "I'm\u{0020}very\u{0020}sorry;\u{0020}I'll\u{0020}replace\u{0020}the\u{0020}spilled\u{0020}coffee\u{0020}immediately.", "0", "十分抱歉，撒掉的咖啡，馬上就幫你換一杯。", "0", "0", "0", "cv_sk_lyfa_15", "0", "0"},
[4001800118] = {4001800118, 10018001, 19, 13, "0", "0", "Woo—this\u{0020}is\u{0020}the\u{0020}first\u{0020}time\u{0020}I've\u{0020}faced\u{0020}such\u{0020}a\u{0020}situation.\u{0020}What\u{0020}should\u{0020}I\u{0020}do...?", "0", "嗚——這種情況第一次遇到，該怎麼辦呢……", "0", "0", "0", "cv_sk_lyfa_16", "0", "0"},
[4001800119] = {4001800119, 10018001, 20, 14, "0", "0", "Sure\u{0020}enough...\u{0020}I'm\u{0020}still\u{0020}far\u{0020}from\u{0020}being\u{0020}a\u{0020}professional\u{0020}maid...\u{0020}Sobs...", "0", "果然…我離專業的女僕還差得遠呢…嗚嗚……", "0", "0", "0", "cv_sk_lyfa_17", "0", "0"},
[4001800120] = {4001800120, 10018001, 21, 15, "0", "0", "Clearance\u{0020}time.", "お掃除の時間です。", "清场时间。", "0", "0", "0", "cv_sk_lyfa_18", "0", "0"},
[4001800121] = {4001800121, 10018001, 23, 16, "0", "0", "Can\u{0020}you\u{0020}keep\u{0020}up\u{0020}with\u{0020}my\u{0020}dance\u{0020}steps?", "私の舞いについてこられますか？", "跟得上我的舞步吗？", "0", "0", "0", "cv_sk_lyfa_19", "0", "0"},
