[4001800123] = {4001800123, 10018001, 26, 19, "0", "0", "Haven't\u{0020}I\u{0020}worked\u{0020}hard\u{0020}enough...?", "まだ、努力が足りないのでしょうか……", "我还不够努力吗……", "0", "0", "0", "cv_sk_lyfa_20", "0", "0"},
[4001800124] = {4001800124, 10018001, 27, 20, "0", "0", "I\u{0020}never\u{0020}imagined\u{0020}there\u{0020}would\u{0020}come\u{0020}a\u{0020}day\u{0020}when\u{0020}you\u{0020}would\u{0020}serve\u{0020}me...", "0", "沒想到會有讓主人服侍我的一天……", "0", "0", "0", "cv_sk_lyfa_22", "0", "0"},
[4001800125] = {4001800125, 10018001, 28, 21, "0", "0", "The\u{0020}water\u{0020}temperature\u{0020}here\u{0020}is\u{0020}so\u{0020}comfortable...", "0", "這裏的水溫好舒服…", "0", "0", "0", "cv_sk_lyfa_23", "0", "0"},
[4001800126] = {4001800126, 10018001, 29, 21, "0", "0", "Is\u{0020}this\u{0020}what\u{0020}it\u{0020}feels\u{0020}like\u{0020}to\u{0020}be\u{0020}pampered\u{0020}by\u{0020}others?\u{0020}So\u{0020}nice.", "0", "這就是被別人服侍的感覺嗎？真舒服啊。", "0", "0", "0", "cv_sk_lyfa_24", "0", "0"},
[4001800127] = {4001800127, 10018001, 30, 22, "0", "0", "This\u{0020}is\u{0020}an\u{0020}unexpected\u{0020}situation.", "0", "真是意想不到的狀況。", "0", "0", "0", "cv_sk_lyfa_25", "0", "0"},
[4001800128] = {4001800128, 10018001, 31, 23, "0", "0", "It\u{0020}shouldn't\u{0020}be\u{0020}misinterpreted!", "0", "應該不會猜錯吧！", "0", "0", "0", "cv_sk_lyfa_26", "0", "0"},
[4001800129] = {4001800129, 10018001, 32, 24, "0", "0", "Do\u{0020}you\u{0020}care\u{0020}about\u{0020}me\u{0020}that\u{0020}much?!", "0", "原來領航這麼在意我的嗎！", "0", "0", "0", "cv_sk_lyfa_27", "0", "0"},
[4001800130] = {4001800130, 10018001, 33, 25, "0", "0", "I\u{0020}know—you\u{0020}can\u{0020}do\u{0020}it\u{0020}alone,\u{0020}Master.", "0", "我知道了，主人一個人也可以的。", "0", "0", "0", "cv_sk_lyfa_28", "0", "0"},
[4001800131] = {4001800131, 10018001, 34, 26, "0", "0", "Welcome\u{0020}back!\u{0020}With\u{0020}you\u{0020}by\u{0020}my\u{0020}side,\u{0020}I\u{0020}can\u{0020}perform\u{0020}even\u{0020}better\u{0020}next\u{0020}time.", "おかえりなさいませ。ご主人様が傍にいてくれるなら、次はもっと上手に舞える気がします。", "欢迎归来，有主人陪在身边，接下来我能有更好的表现。", "0", "0", "0", "cv_sk_lyfa_31", "0", "0"},
[4001800132] = {4001800132, 10018001, 35, 27, "0", "0", "Do\u{0020}you\u{0020}need\u{0020}me\u{0020}to\u{0020}clean?", "0", "需要莉法去清掃嗎？", "0", "0", "0", "cv_sk_lyfa_33", "0", "0"},
[4001800133] = {4001800133, 10018001, 36, 28, "0", "0", "Even\u{0020}though\u{0020}it's\u{0020}challenging,\u{0020}please\u{0020}trust\u{0020}me\u{0020}to\u{0020}handle\u{0020}it.", "0", "雖然很棘手但是放心交給我吧。", "0", "0", "0", "cv_sk_lyfa_34", "0", "0"},
[4001800134] = {4001800134, 10018001, 37, 29, "0", "0", "I\u{0020}wonder\u{0020}if\u{0020}we\u{0020}have\u{0020}enough\u{0020}tea\u{0020}snacks?", "0", "不知道茶點夠不夠呢？", "0", "0", "0", "cv_sk_lyfa_35", "0", "0"},
