[4001800136] = {4001800136, 10018001, 39, 31, "0", "0", "The\u{0020}Japanese-style\u{0020}maid\u{0020}outfit\u{0020}is\u{0020}lovely...\u{0020}Ah,\u{0020}no,\u{0020}that's\u{0020}nothing.", "0", "和風女僕裝也好好看……啊，沒沒什麼。", "0", "0", "0", "cv_sk_lyfa_37", "0", "0"},
