[4001800138] = {4001800138, 10018001, 41, 33, "0", "0", "Here's\u{0020}your\u{0020}file,\u{0020}Master.\u{0020}Please\u{0020}take\u{0020}a\u{0020}look.", "0", "這是主人的檔案，請過目。", "0", "0", "0", "cv_sk_lyfa_39", "0", "0"},
