[4001900100] = {4001900100, 10019001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響", "0", "0", "0", "cv_sk_nozomi_sw_1", "0", "0"},
[4001900101] = {4001900101, 10019001, 2, 2, "0", "0", "You\u{0020}found\u{0020}me,\u{0020}Navigator.\u{0020}I've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}you\u{0020}for\u{0020}a\u{0020}long\u{0020}time.", "あたしを見つけてくれたんですね。ナビゲーターさん。", "你找到我啦，領航，我等你好久了。", "0", "0", "0", "cv_sk_nozomi_sw_2", "0", "0"},
[4001900102] = {4001900102, 10019001, 3, 3, "0", "0", "Huh?\u{0020}What's\u{0020}wrong\u{0020}with\u{0020}my\u{0020}name?\u{0020}It's\u{0020}exactly\u{0020}the\u{0020}same\u{0020}as\u{0020}that\u{0020}legendary\u{0020}idol's\u{0020}name?\u{0020}So,\u{0020}she's\u{0020}already\u{0020}dead,\u{0020}huh?", "あたしの名前が何か……？え、伝説のアイドルと同じ？……そうですか。彼女はもう、いないんですね。", "嗯？我的名字怎麼了嗎？和那位傳說中的偶像名字一模一樣？……是嘛，原來“她”已經死了啊。", "0", "0", "0", "cv_sk_nozomi_sw_3", "0", "0"},
[4001900103] = {4001900103, 10019001, 91, 4, "0", "idle", "Even\u{0020}if\u{0020}I'm\u{0020}not\u{0020}by\u{0020}your\u{0020}side\u{0020}anymore,\u{0020}I\u{0020}will\u{0020}watch\u{0020}over\u{0020}you\u{0020}through\u{0020}the\u{0020}breeze,\u{0020}the\u{0020}stars,\u{0020}and\u{0020}the\u{0020}sea.\u{0020}What?\u{0020}It's\u{0020}my\u{0020}previous\u{0020}song.", "もしあたしがあなたから離れることがあっても、風と星と海を通して、見守り続ける。……今のですか？昔つくった歌ですよ。", "即使我不在你的身邊了，但是我會通過微風、星辰與大海守望你的。……是什麼？是我以前的歌啦。", "0", "0", "0", "cv_sk_nozomi_sw_5", "0", "0"},
[4001900104] = {4001900104, 10019001, 91, 4, "0", "idle", "Our\u{0020}story\u{0020}hasn't\u{0020}reached\u{0020}the\u{0020}last\u{0020}page\u{0020}yet.\u{0020}Don't\u{0020}rush\u{0020}to\u{0020}end\u{0020}it.", "あたし達の物語はまだ最後のページではありません。そんなに急がなくてもいいですよ。", "我們的故事還沒翻到最後一頁呢，不要太著急結束哦。", "0", "0", "0", "cv_sk_nozomi_sw_6", "0", "0"},
[4001900105] = {4001900105, 10019001, 94, 4, "0", "idle2", "The\u{0020}summer\u{0020}wind\u{0020}sounds\u{0020}like\u{0020}it's\u{0020}mixed\u{0020}with\u{0020}voices\u{0020}cheering\u{0020}for\u{0020}me.\u{0020}They\u{0020}are\u{0020}cheering\u{0020}me\u{0020}on.", "夏のそよ風があたしを元気にしてくれるんです。頑張れって言われてるみたいに……", "夏風聽起來、略微夾雜著為我喝彩的聲音。它們在為我加油鼓勁哦。", "0", "0", "0", "cv_sk_nozomi_sw_7", "0", "0"},
[4001900106] = {4001900106, 10019001, 94, 5, "0", "idle2", "The\u{0020}sunshade\u{0020}is\u{0020}like\u{0020}my\u{0020}stage.\u{0020}Let's\u{0020}hide\u{0020}here\u{0020}together.\u{0020}I\u{0020}have\u{0020}a\u{0020}melody\u{0020}I\u{0020}just\u{0020}thought\u{0020}of\u{0020}that\u{0020}I\u{0020}want\u{0020}you\u{0020}to\u{0020}hear.", "このビーチパラソルの下、まるであたしのステージみたいですね。ここで一緒に少し休みませんか？新しいメロディを思いついたので、ナビゲーターさんに聞いて欲しいんです。", "遮陽傘、就好像是我的舞臺一樣。我們一起躲在這裏吧，我有一段剛想到的旋律、想給領航聽。", "0", "0", "0", "cv_sk_nozomi_sw_8", "0", "0"},
[4001900107] = {4001900107, 10019001, 93, 5, "14_》_0_0.8", "touch_s1", "It's\u{0020}so\u{0020}cool.\u{0020}It's\u{0020}more\u{0020}comfortable\u{0020}like\u{0020}this.", "涼しい……やっぱりこの方が楽ですね。", "真涼快呢……還是這樣更自在。", "0", "0", "0", "cv_sk_nozomi_sw_9", "0", "0"},
[4001900108] = {4001900108, 10019001, 96, 5, "14_》_0_0.8", "touch_s2", "...The\u{0020}president\u{0020}asked\u{0020}me\u{0020}to\u{0020}put\u{0020}on\u{0020}this\u{0020}dress.\u{0020}I'll\u{0020}wear\u{0020}it\u{0020}like\u{0020}this\u{0020}when\u{0020}I'm\u{0020}in\u{0020}her\u{0020}sight.", "この服を着るように、会長に言われてるんです。……少なくとも会長がいる間は、着てた方がいいですよね？", "……被會長要求披上這件衣服。在她視線裏的時候還是先這樣穿著吧。", "0", "0", "0", "cv_sk_nozomi_sw_10", "0", "0"},
[4001900109] = {4001900109, 10019001, 92, 5, "14_》_0_0.8", "touch1", "I\u{0020}can\u{0020}grasp\u{0020}luck\u{0020}and\u{0020}change\u{0020}it,\u{0020}but\u{0020}there's\u{0020}a\u{0020}price.\u{0020}I\u{0020}took\u{0020}a\u{0020}gamble\u{0020}on\u{0020}you.\u{0020}Please,\u{0020}you\u{0020}must\u{0020}find\u{0020}me.", "あたしは幸運をつかむことができます。運命を変えることができます。……でもそれには代償が必要なんです。ナビゲーターさん、お願い……絶対にあたしのことを見つけてくださいね。", "我能抓住幸運、改變運氣，但是這是有代價的……我在你的身上賭了一把，拜託了……一定要找到我啊。", "0", "0", "0", "cv_sk_nozomi_sw_11", "0", "0"},
[4001900110] = {4001900110, 10019001, 92, 5, "14_》_0_0.8", "touch3", "Can\u{0020}you\u{0020}guess\u{0020}what\u{0020}I'm\u{0020}thinking\u{0020}right\u{0020}now?\u{0020}One\u{0020}day,\u{0020}I\u{0020}will\u{0020}step\u{0020}onto\u{0020}the\u{0020}biggest\u{0020}stage\u{0020}in\u{0020}this\u{0020}world.\u{0020}If\u{0020}my\u{0020}wish\u{0020}comes\u{0020}true,\u{0020}will\u{0020}you\u{0020}come\u{0020}to\u{0020}see\u{0020}me\u{0020}that\u{0020}day?", "あたしが今何を考えているのか、分かりますか？……あたしはいつか、この世界で一番大きなステージに立ちたいと思っています。もしあたしの願いが実現したら、見に来てくれますか？", "你能猜到我現在正在想什麼嗎？……總有一天，我會登上這個世界最大的舞臺。如果我的願望實現的話，那一天你能來看我嗎？", "0", "0", "0", "cv_sk_nozomi_sw_12", "0", "0"},
[4001900111] = {4001900111, 10019001, 95, 5, "14_》_0_0.8", "touch2", "...I\u{0020}want\u{0020}to\u{0020}remember\u{0020}you\u{0020}well.\u{0020}Stay\u{0020}around\u{0020}me\u{0020}for\u{0020}a\u{0020}while.", "……ナビゲーターさんのことをちゃんと覚えていたくて……だから、もう少しあたしの側にいてくれませんか？", "……我要把領航好好地記住……在我的周圍多呆一會吧。", "0", "0", "0", "cv_sk_nozomi_sw_46", "0", "0"},
[4001900112] = {4001900112, 10019001, 95, 5, "14_》_0_0.8", "touch2", "It's\u{0020}really\u{0020}a\u{0020}long\u{0020}and\u{0020}short\u{0020}adventure.\u{0020}Thank\u{0020}you\u{0020}for\u{0020}responding\u{0020}to\u{0020}my\u{0020}voice.", "長くて短い冒険でしたね。あたしの声に応えてくれて、ありがとうございます。", "真是一場漫長而又短暫的冒險、謝謝你能回應我的聲音。", "0", "0", "0", "cv_sk_nozomi_sw_47", "0", "0"},
[4001900113] = {4001900113, 10019001, 12, 6, "0", "0", "Humph♫", "フンフフーン♪", "哼♫~~", "0", "0", "0", "cv_sk_nozomi_sw_13", "0", "0"},
[4001900114] = {4001900114, 10019001, 13, 7, "0", "0", "The\u{0020}goal\u{0020}is\u{0020}the\u{0020}peak!", "トップを目指します！", "目標是頂點！", "0", "0", "0", "cv_sk_nozomi_sw_14", "0", "0"},
[4001900115] = {4001900115, 10019001, 14, 8, "0", "0", "Um...\u{0020}Huh?\u{0020}I\u{0020}just\u{0020}seemed\u{0020}to\u{0020}have\u{0020}a\u{0020}bit\u{0020}of\u{0020}inspiration.\u{0020}What\u{0020}was\u{0020}that\u{0020}just\u{0020}now?\u{0020}Awakening?\u{0020}So\u{0020}amazing!\u{0020}Can\u{0020}it\u{0020}happen\u{0020}again?\u{0020}No?\u{0020}What\u{0020}a\u{0020}pity.", "んん……あれ？このインスピレーション……これ、なんですか！？覚醒？すごーい！もう一回お願いできますか？……ダメ？残念です……", "嗯……嗯？剛剛好像有了一點靈感，剛剛那個是什麼？！覺醒？好厲害！可以再來一次嗎！……不可以了？遺憾……", "0", "0", "0", "cv_sk_nozomi_sw_15", "0", "0"},
[4001900116] = {4001900116, 10019001, 15, 9, "0", "0", "I've\u{0020}regained\u{0020}my\u{0020}former\u{0020}touch.", "昔の感覚が戻ってきました！", "找回曾經的手感了。", "0", "0", "0", "cv_sk_nozomi_sw_16", "0", "0"},
[4001900117] = {4001900117, 10019001, 16, 10, "0", "0", "Is\u{0020}it\u{0020}my\u{0020}turn\u{0020}to\u{0020}perform?", "私の出番ですか？", "輪到我表演了嗎？", "0", "0", "0", "cv_sk_nozomi_sw_17", "0", "0"},
[4001900118] = {4001900118, 10019001, 17, 11, "0", "0", "Perfect\u{0020}curtain\u{0020}call!", "カーテンコール！", "完美謝幕！", "0", "0", "0", "cv_sk_nozomi_sw_18", "0", "0"},
[4001900119] = {4001900119, 10019001, 18, 12, "0", "0", "A\u{0020}slight\u{0020}mistake.\u{0020}Um...\u{0020}There's\u{0020}a\u{0020}bit\u{0020}of\u{0020}noise\u{0020}in\u{0020}the\u{0020}music.", "ちょっと失敗ですね。うーん……ノイズが入っちゃいました。", "略微的失誤，嗯……音樂有點雜音呢。", "0", "0", "0", "cv_sk_nozomi_sw_19", "0", "0"},
[4001900120] = {4001900120, 10019001, 19, 13, "0", "0", "I\u{0020}haven't\u{0020}fully\u{0020}mastered\u{0020}this\u{0020}part.\u{0020}Let\u{0020}me\u{0020}train\u{0020}myself\u{0020}some\u{0020}more.", "あのパートが上手くいきません……もっと練習しなきゃ。", "還沒完全掌握這一段，再鍛煉一下自己吧。", "0", "0", "0", "cv_sk_nozomi_sw_20", "0", "0"},
[4001900121] = {4001900121, 10019001, 20, 14, "0", "0", "Big\u{0020}event!\u{0020}A\u{0020}disastrous\u{0020}performance!\u{0020}It's\u{0020}going\u{0020}to\u{0020}cause\u{0020}public\u{0020}outrage!", "やばい、大失敗！炎上しちゃいます！", "大事件！演奏大失敗！要引起公憤了！", "0", "0", "0", "cv_sk_nozomi_sw_21", "0", "0"},
[4001900122] = {4001900122, 10019001, 21, 15, "0", "0", "The\u{0020}curtain\u{0020}falls.", "これでラスト！", "大幕落下。", "0", "0", "0", "cv_sk_nozomi_sw_23", "0", "0"},
[4001900123] = {4001900123, 10019001, 23, 16, "0", "0", "Please\u{0020}listen!", "聞いてください！", "請聆聽！", "0", "0", "0", "cv_sk_nozomi_sw_22", "0", "0"},
[4001900124] = {4001900124, 10019001, 26, 19, "0", "0", "Noise...", "不協和音が……", "噪音……", "0", "0", "0", "cv_sk_nozomi_sw_24", "0", "0"},
[4001900125] = {4001900125, 10019001, 24, 17, "0", "0", "Interlude\u{0020}rhythm—", "インテルメッツォ！", "間奏律——", "0", "0", "0", "cv_sk_nozomi_sw_26", "0", "0"},
[4001900126] = {4001900126, 10019001, 25, 18, "0", "0", "Everyone\u{0020}has\u{0020}waited\u{0020}for\u{0020}a\u{0020}long\u{0020}time!\u{0020}The\u{0020}performance\u{0020}of\u{0020}Nozomi\u{0020}returning\u{0020}to\u{0020}the\u{0020}stage\u{0020}is\u{0020}over.\u{0020}Now,\u{0020}the\u{0020}show\u{0020}begins!", "お待たせしました！希ちゃんの復帰ライブ、開演です！", "大家久等了！結束希重回舞臺的演出，此刻，開演！", "0", "0", "0", "cv_sk_nozomi_sw_25", "0", "0"},
[4001900127] = {4001900127, 10019001, 27, 20, "0", "0", "Aah!\u{0020}Navigator?\u{0020}Why\u{0020}are\u{0020}you\u{0020}here?", "え、えええ！？ナビゲーターさん！？なんでここに？", "——呀！！領航？！你怎麼在這裏？！", "0", "0", "0", "cv_sk_nozomi_sw_27", "0", "0"},
[4001900128] = {4001900128, 10019001, 28, 21, "0", "0", "...Mmm,\u{0020}I\u{0020}see.\u{0020}The\u{0020}music\u{0020}industry\u{0020}is\u{0020}really\u{0020}different\u{0020}now.", "……なるほど。今の音楽業界はこうなんですね。", "…嗯嗯，原來如此，現在的樂壇真是大不一樣啊。", "0", "0", "0", "cv_sk_nozomi_sw_28", "0", "0"},
[4001900129] = {4001900129, 10019001, 29, 21, "0", "0", "Music\u{0020}makes\u{0020}people\u{0020}both\u{0020}painful\u{0020}and\u{0020}happy.\u{0020}Other\u{0020}people's\u{0020}performances\u{0020}touch\u{0020}my\u{0020}heart,\u{0020}but\u{0020}also\u{0020}make\u{0020}me\u{0020}jealous\u{0020}and\u{0020}unwilling.\u{0020}When\u{0020}I\u{0020}get\u{0020}out,\u{0020}I'll\u{0020}continue\u{0020}to\u{0020}practice!", "音楽って本当に楽しいけど、辛い時もあるんですよ。他の人のパフォーマンスで感動して泣くこともあれば、嫉妬で悔しくなることも……うん！帰ったらすぐ練習します！", "音樂真是讓人痛苦又快樂……別人的表演會打動我的心，但卻又讓我嫉妒，不甘心。……等出去了，就繼續練習吧！", "0", "0", "0", "cv_sk_nozomi_sw_29", "0", "0"},
[4001900130] = {4001900130, 10019001, 30, 22, "0", "0", "The\u{0020}secret\u{0020}concert\u{0020}has\u{0020}begun!", "シークレットライブ、開演です！", "秘密演唱會開始了哦~", "0", "0", "0", "cv_sk_nozomi_sw_30", "0", "0"},
[4001900131] = {4001900131, 10019001, 31, 23, "0", "0", "Is\u{0020}my\u{0020}\"voice\"\u{0020}special\u{0020}to\u{0020}you?", "ナビゲーターさんにとって私の声って、特別ですかねー？", "我的“聲音”對你而言是特殊的嗎？", "0", "0", "0", "cv_sk_nozomi_sw_31", "0", "0"},
[4001900132] = {4001900132, 10019001, 32, 24, "0", "0", "You\u{0020}remember!\u{0020}Then\u{0020}I\u{0020}unilaterally\u{0020}declare\u{0020}that\u{0020}you\u{0020}are\u{0020}my\u{0020}die-hard\u{0020}fan!", "覚えててくれたんですね！あたしのファンとして合格です！", "你記住了呢！那我單方面宣佈你是我的死忠粉了！", "0", "0", "0", "cv_sk_nozomi_sw_32", "0", "0"},
[4001900133] = {4001900133, 10019001, 33, 25, "0", "0", "Woo...\u{0020}It\u{0020}seems\u{0020}I'm\u{0020}not\u{0020}mature\u{0020}enough.", "ううう……私もまだまだですね……", "嗚……看來我還不夠成熟……", "0", "0", "0", "cv_sk_nozomi_sw_33", "0", "0"},
[4001900134] = {4001900134, 10019001, 34, 26, "0", "0", "Welcome\u{0020}back.\u{0020}I\u{0020}was\u{0020}just\u{0020}about\u{0020}to\u{0020}prepare\u{0020}for\u{0020}practice.\u{0020}Navigator,\u{0020}you\u{0020}can\u{0020}listen\u{0020}by\u{0020}the\u{0020}side.", "おかえりなさーい。ちょうど練習をはじめるところだったんですよ。よかったらそこで聞いててくださいね。", "歡迎回來，我正要準備練習了，領航你可以在旁邊聽哦~", "0", "0", "0", "cv_sk_nozomi_sw_34", "0", "0"},
[4001900135] = {4001900135, 10019001, 35, 27, "0", "0", "The\u{0020}practice\u{0020}of\u{0020}combat\u{0020}hasn't\u{0020}been\u{0020}neglected\u{0020}either!", "戦闘訓練もちゃんとしてますよ！", "戰鬥的練習也沒有落下！", "0", "0", "0", "cv_sk_nozomi_sw_35", "0", "0"},
[4001900136] = {4001900136, 10019001, 36, 28, "0", "0", "The\u{0020}path\u{0020}of\u{0020}a\u{0020}driver\u{0020}is\u{0020}as\u{0020}cruel\u{0020}as\u{0020}that\u{0020}of\u{0020}an\u{0020}idol.", "ドライバーの世界もアイドルと同じくらい過酷なんですね。", "駕駛員的道路也和偶像一樣殘酷呢。", "0", "0", "0", "cv_sk_nozomi_sw_36", "0", "0"},
[4001900137] = {4001900137, 10019001, 37, 29, "0", "0", "Let's\u{0020}invite\u{0020}everyone\u{0020}to\u{0020}listen\u{0020}next\u{0020}time!", "みなさんもライブに来てくださいねー！", "下次邀請大家一起來聽吧！", "0", "0", "0", "cv_sk_nozomi_sw_37", "0", "0"},
[4001900138] = {4001900138, 10019001, 38, 30, "0", "0", "Oh!\u{0020}Are\u{0020}we\u{0020}getting\u{0020}a\u{0020}new\u{0020}member?", "新しいメンバーですか？", "哦！新的成員要來了嗎。", "0", "0", "0", "cv_sk_nozomi_sw_38", "0", "0"},
[4001900139] = {4001900139, 10019001, 39, 31, "0", "0", "Actually,\u{0020}I\u{0020}can\u{0020}play\u{0020}the\u{0020}piano\u{0020}too.", "実はピアノも弾けちゃいますよ！", "其實鋼琴我也會彈哦。", "0", "0", "0", "cv_sk_nozomi_sw_39", "0", "0"},
[4001900140] = {4001900140, 10019001, 40, 32, "0", "0", "I\u{0020}want\u{0020}to\u{0020}try\u{0020}new\u{0020}instruments.", "新しい楽器も試してみたいです。", "想試試新的樂器。", "0", "0", "0", "cv_sk_nozomi_sw_40", "0", "0"},
[4001900141] = {4001900141, 10019001, 41, 33, "0", "0", "The\u{0020}file,\u{0020}right?\u{0020}Please\u{0020}take\u{0020}a\u{0020}look.", "プロフィールですね、どうぞ。", "檔案對吧，請看。", "0", "0", "0", "cv_sk_nozomi_sw_41", "0", "0"},
[4001900142] = {4001900142, 10019001, 42, 34, "0", "0", "Turn\u{0020}the\u{0020}volume\u{0020}up\u{0020}to\u{0020}the\u{0020}maximum!", "音量を最大にしましょう！", "把音量調到最大吧！", "0", "0", "0", "cv_sk_nozomi_sw_42", "0", "0"},
[4001900143] = {4001900143, 10019001, 43, 35, "0", "0", "Are\u{0020}there\u{0020}any\u{0020}thank-you\u{0020}letters\u{0020}from\u{0020}fans?", "ファンレターは…ありますか？", "有粉絲的感謝信嗎？", "0", "0", "0", "cv_sk_nozomi_sw_43", "0", "0"},
[4001900144] = {4001900144, 10019001, 44, 36, "0", "0", "Let's\u{0020}see\u{0020}what\u{0020}everyone\u{0020}thinks.", "みんなの感想を見てみましょう。", "看看大家的想法吧。", "0", "0", "0", "cv_sk_nozomi_sw_44", "0", "0"},
[4001900145] = {4001900145, 10019001, 45, 37, "0", "0", "Humph.", "へえー。", "哼~", "0", "0", "0", "cv_sk_nozomi_sw_45", "0", "0"},
[4002000100] = {4002000100, 10020001, 1, 1, "0", "0", "Haze\u{0020}Reverb.", "ハツリバーブ", "0", "0", "0", "0", "cv_sk_weilai_sw_1", "0", "0"},
[4002000101] = {4002000101, 10020001, 2, 2, "0", "0", "You want to see that badly, Mr. Pervert. How gross. But I'm a mature and gracious lady, so I won't say no.", "変態さん、そんなに私に会いたかったんですか？気持ち悪いです。だけど私も大人のレディですから、お誘いを断ったりはしませんよ。", "0", "0", "0", "0", "cv_sk_weilai_sw_2", "0", "0"},
[4002000102] = {4002000102, 10020001, 3, 3, "0", "0", "My name is Mirai, the Driver who made an appointment. Huh?... You've seen me in a dream? Geez, Mr. Pervert, that would be a 100% harassment if I didn't remember anything.", "私の名前はミライです。約束通り会いに来ました。えっ？夢の中で私に会ったことがある？変態さん、あなた……それ私が何も覚えてなかったら、ただのセクハラですからね？", "0", "0", "0", "0", "cv_sk_weilai_sw_3", "0", "0"},
[4002000103] = {4002000103, 10020001, 91, 4, "0", "idle", "Ha, I haven't slept this well in ages. Don't tell me you've been watching over me this whole time, Mr. Pervert? You are more of a gentleman than I expected.", "はぁ～こんなにぐっすり眠れたのは久しぶりでした。あれっ、もしかして変態さん、ずっと傍で見守ってくれてたんですか？紳士的なところもあるんですね。", "0", "0", "0", "0", "cv_sk_weilai_sw_4", "0", "0"},
[4002000104] = {4002000104, 10020001, 91, 4, "0", "idle", "I took off my own clothes while sleeping? I'm not an idiot! Ah! Unless this is your pathetic excuse for peeping!", "私が寝てる間に服を脱いでるって？バカじゃないんですから、そんなわけが……あ！あなたが脱がしてるんじゃないですよね！", "0", "0", "0", "0", "cv_sk_weilai_sw_5", "0", "0"},
[4002000105] = {4002000105, 10020001, 91, 4, "0", "idle", "Attracted by my body, aren't you? Not surprising since I'm so gorgeous... Hey! What's with that look? Are you actually... disgusted by this perfect body I'm so proud of?", "私の体に見惚れちゃいましたか。まぁ美少女ですからね。……なんですか？その目は。ま、まさかこの美少女ボディが気に入らないって言うんですか！", "0", "0", "0", "0", "cv_sk_weilai_sw_6", "0", "0"},
[4002000106] = {4002000106, 10020001, 94, 4, "0", "idle2", "Dad... Mom... Sis...", "お父さん……お母さん……お姉ちゃん……", "0", "0", "0", "0", "cv_sk_weilai_sw_7", "0", "0"},
[4002000107] = {4002000107, 10020001, 94, 4, "0", "idle2", "S-Sorry, I let you down. It's all my fault.", "ご、ごめんなさい……みんなをガッカリさせてしまって…。…私のせいです。", "0", "0", "0", "0", "cv_sk_weilai_sw_8", "0", "0"},
[4002000108] = {4002000108, 10020001, 94, 4, "0", "idle2", "I-It's all my fault... If only I could've held out longer...", "わ、私のせいですよね…。…私が頑張っていれば……うう……。", "0", "0", "0", "0", "cv_sk_weilai_sw_9", "0", "0"},
[4002000109] = {4002000109, 10020001, 92, 5, "14_1_0_0.8", "touch1", "I talked in my sleep?! Wh-What did I say? You won't tell me? You big meanie!", "え！？私、寝てる時に寝言言ってるんですか！？な、なんて言ってるんですか？教えない？いじわる過ぎます！", "0", "0", "0", "0", "cv_sk_weilai_sw_10", "0", "0"},
[4002000110] = {4002000110, 10020001, 92, 5, "14_1_0_0.8", "touch1", "Cat got your tongue from my adorable sleeping face? D-Drool!? Where!?", "私の寝顔に心打たれて言葉も出ませんか？……よ、ヨダレが付いてる！？ど、どこですか？", "0", "0", "0", "0", "cv_sk_weilai_sw_11", "0", "0"},
[4002000111] = {4002000111, 10020001, 93, 5, "14_2_0_0.8", "touch_s1", "Yaaawn. So sleepy.", "はぁ～眠いです～。", "0", "0", "0", "0", "cv_sk_weilai_sw_46", "0", "0"},
[4002000112] = {4002000112, 10020001, 95, 5, "14_1_0_0.8", "touch2", "Navigator... Save me...", "ナビゲーターさん……助けてください…。…うう……。", "0", "0", "0", "0", "cv_sk_weilai_sw_47", "0", "0"},
[4002000113] = {4002000113, 10020001, 95, 5, "14_1_0_0.8", "touch2", "N-Next time I'll do better... S-So please believe in me just once more...", "つ、次はちゃんとやるので……も、もう一度信用して貰えませんか……。", "0", "0", "0", "0", "cv_sk_weilai_sw_48", "0", "0"},
[4002000114] = {4002000114, 10020001, 96, 5, "14_2_0_0.8", "touch_s2", "Mmm...", "むむ…。", "0", "0", "0", "0", "cv_sk_weilai_sw_49", "0", "0"},
[4002000115] = {4002000115, 10020001, 12, 6, "0", "0", "I'll be stronger just like that? Feels unreal... Wait, more training? Ugh!", "これで強くなったんですね……実感はありませんが。後で特訓がある？え～…。", "0", "0", "0", "0", "cv_sk_weilai_sw_12", "0", "0"},
[4002000116] = {4002000116, 10020001, 13, 7, "0", "0", "Ahhhhhh!! Something's inside me! It's tingling! So gross! Is this how Mr. Pervert harasses all the Heroines with [Synesthesia]?", "ぎゃああああ！何かが体の中に入って来きます！ムズムズします！気持ち悪い！変態さん、通感覚でヒロイン達にこんなセクハラじみたことしてたんですか！？", "0", "0", "0", "0", "cv_sk_weilai_sw_13", "0", "0"},
[4002000117] = {4002000117, 10020001, 14, 8, "0", "0", "So tired... I can't take it anymore. Maybe we should just quit training!", "疲れました…もう限界です…！やっぱり特訓はやめておきましょう！", "0", "0", "0", "0", "cv_sk_weilai_sw_14", "0", "0"},
[4002000118] = {4002000118, 10020001, 15, 9, "0", "0", "Eh? You said you want to protect everyone with me... That's so unfair, saying something like that. I-I'll try to live up to your expectations.", "えっ？……私と一緒にみんなを守りたいって……ほんと言い回しが卑怯ですねあなたって。……わ、私もできるだけ頑張ってみますよ。", "0", "0", "0", "0", "cv_sk_weilai_sw_15", "0", "0"},
[4002000119] = {4002000119, 10020001, 16, 10, "0", "0", "What...? I have to fight too?", "は？私も戦場に出るんですか？", "0", "0", "0", "0", "cv_sk_weilai_sw_16", "0", "0"},
[4002000120] = {4002000120, 10020001, 17, 11, "0", "0", "E-easy peasy! Okay, I'm over being a Driver now.", "ら、楽勝でしたね。ふぅ…私、もうドライバーという仕事に飽きちゃったかもです。", "0", "0", "0", "0", "cv_sk_weilai_sw_17", "0", "0"},
[4002000121] = {4002000121, 10020001, 18, 12, "0", "0", "Let's go home!", "早く家に帰りましょう！", "0", "0", "0", "0", "cv_sk_weilai_sw_18", "0", "0"},
[4002000122] = {4002000122, 10020001, 19, 13, "0", "0", "Huh! That laser almost grazed my forehead!", "わっ！いま、光線が私のおでこを掠めていきましたよ！", "0", "0", "0", "0", "cv_sk_weilai_sw_19", "0", "0"},
[4002000123] = {4002000123, 10020001, 20, 14, "0", "0", "Um... What do we do here? M-Maybe we should both desert, Navigator!", "あ、ああ……この状況、一体どうすれば…。な、ナビゲーターさん、一緒に逃げましょう！", "0", "0", "0", "0", "cv_sk_weilai_sw_20", "0", "0"},
[4002000124] = {4002000124, 10020001, 21, 15, "0", "0", "Amazing!", "やった！", "0", "0", "0", "0", "cv_sk_weilai_sw_21", "0", "0"},
[4002000125] = {4002000125, 10020001, 23, 16, "0", "0", "Such a hassle...", "め、めんどくさい…。", "0", "0", "0", "0", "cv_sk_weilai_sw_22", "0", "0"},
[4002000126] = {4002000126, 10020001, 26, 19, "0", "0", "Somebody, help me please...", "うぅ……誰か助けてください……", "0", "0", "0", "0", "cv_sk_weilai_sw_23", "0", "0"},
[4002000127] = {4002000127, 10020001, 24, 17, "0", "0", "Disappear!", "消えてください！", "0", "0", "0", "0", "cv_sk_weilai_sw_24", "0", "0"},
[4002000128] = {4002000128, 10020001, 25, 18, "0", "0", "Seaside Paradise Manager, deploying!", "シーサイドパラダイス管理人、出撃です！", "0", "0", "0", "0", "cv_sk_weilai_sw_25", "0", "0"},
[4002000129] = {4002000129, 10020001, 27, 20, "0", "0", "Hmm... You want to bathe together? O-Okay, come on in. I'm ready.", "へぇ……私と一緒にお風呂に入りたいんですか？い、いいでしょう。準備はできてますので。", "0", "0", "0", "0", "cv_sk_weilai_sw_27", "0", "0"},
[4002000130] = {4002000130, 10020001, 28, 21, "0", "0", "W-Wait, you actually just want to bathe?! That's so weird!", "お、お風呂に入るってほんとにお風呂に入るだけって意味だったんですか！？おかしくないですか！？", "0", "0", "0", "0", "cv_sk_weilai_sw_28", "0", "0"},
[4002000131] = {4002000131, 10020001, 29, 21, "0", "0", "Bathing together while giantified?! To come up with this idea... Calling you pervert feels just right. What a weird fetish...!", "巨大化した私と一緒にお風呂に入りたい！？そんなやり方が……さすがは変態さんですね！あなたの性癖には驚かされてばかりですよ……！", "0", "0", "0", "0", "cv_sk_weilai_sw_29", "0", "0"},
[4002000132] = {4002000132, 10020001, 30, 22, "0", "0", "Is this... a game for punishment?", "これって罰ゲームですか…？", "0", "0", "0", "0", "cv_sk_weilai_sw_30", "0", "0"},
[4002000133] = {4002000133, 10020001, 31, 23, "0", "0", "No guarantee what happens if you answer wrong...", "答えを間違えたらどうなるか分かってますよね……", "0", "0", "0", "0", "cv_sk_weilai_sw_31", "0", "0"},
[4002000134] = {4002000134, 10020001, 32, 24, "0", "0", "I knew you'd recognize me! After all, I'm your Heroine!", "間違うはずがないって思ってましたよ。だって私はあなたのヒロインですもんね！", "0", "0", "0", "0", "cv_sk_weilai_sw_32", "0", "0"},
[4002000135] = {4002000135, 10020001, 33, 25, "0", "0", "Y-you promised to keep me in your heart...", "わ、私のことを気にかけてるって言ってたくせに……", "0", "0", "0", "0", "cv_sk_weilai_sw_33", "0", "0"},
[4002000136] = {4002000136, 10020001, 34, 26, "0", "0", "Ah. You fell asleep too, Navigator! Good thing I was here; those little crabs were about to nibble your toes, hehe.", "あ、ナビゲーターさん、今寝てましたよね？私が見てあげてなかったら、足をカニに挟まれるところでしたよ。えへへ。", "0", "0", "0", "0", "cv_sk_weilai_sw_34", "0", "0"},
[4002000137] = {4002000137, 10020001, 35, 27, "0", "0", "No way!! I don't wanna fight!! It's too dangerous!!", "いやです！戦いたくありませんっ！危な過ぎます！", "0", "0", "0", "0", "cv_sk_weilai_sw_35", "0", "0"},
[4002000138] = {4002000138, 10020001, 36, 28, "0", "0", "Drills...? Maybe we can have a try...", "え、演習ですか？……やってみてもいいですけど……。", "0", "0", "0", "0", "cv_sk_weilai_sw_36", "0", "0"},
[4002000139] = {4002000139, 10020001, 37, 29, "0", "0", "Everyone's so reliable...", "みんな頼もしいです……", "0", "0", "0", "0", "cv_sk_weilai_sw_37", "0", "0"},
[4002000140] = {4002000140, 10020001, 38, 30, "0", "0", "Speaking of which, does a swimsuit count as equipment?", "そう言えば……水着も装備品なんですよね……", "0", "0", "0", "0", "cv_sk_weilai_sw_38", "0", "0"},
[4002000141] = {4002000141, 10020001, 39, 31, "0", "0", "This armor was literally developed to save the world, but they're making Drivers pay for it? That's just so wrong...", "……世界を救うために開発された装甲が、ドライバーにタダで提供されないなんて……なんかおかしいですよね。", "0", "0", "0", "0", "cv_sk_weilai_sw_39", "0", "0"},
[4002000142] = {4002000142, 10020001, 40, 32, "0", "0", "Mr. Pervert... I-I don't have a job yet... Can I really enter this store?", "変態さん……わ、私、仕事もしてないのに、こんなお店入っていいんですか……？", "0", "0", "0", "0", "cv_sk_weilai_sw_40", "0", "0"},
[4002000143] = {4002000143, 10020001, 41, 33, "0", "0", "Put my photo in your collection too, Mr. Pervert!", "私の写真も変態さんのところに置いておいてください！", "0", "0", "0", "0", "cv_sk_weilai_sw_41", "0", "0"},
[4002000144] = {4002000144, 10020001, 42, 34, "0", "0", "Let's mute everybody and see how it goes.", "全員ミュートしてみたらどうですかね。", "0", "0", "0", "0", "cv_sk_weilai_sw_42", "0", "0"},
[4002000145] = {4002000145, 10020001, 43, 35, "0", "0", "Mr. Pervert's house still has a mailbox? So old-fashioned.", "変態さんの家ってポストが置いてあるんですか。レトロですね。", "0", "0", "0", "0", "cv_sk_weilai_sw_43", "0", "0"},
[4002000146] = {4002000146, 10020001, 44, 36, "0", "0", "Hey, Mr. Pervert! Can you hear the echo?", "ちょっと、変態さん、返信来てませんか？", "0", "0", "0", "0", "cv_sk_weilai_sw_44", "0", "0"},
[4002000147] = {4002000147, 10020001, 45, 37, "0", "0", "What is it?", "これなんですか？", "0", "0", "0", "0", "cv_sk_weilai_sw_45", "0", "0"},
[4002600100] = {4002600100, 10026001, 1, 1, "0", "0", "Haze.\u{0020}Reverb.", "は・つ・り・ば・あ・ぶ～。", "蒼~霧~殘~響", "0", "0", "0", "cv_sk_nasijia_1", "0", "0"},
[4002600101] = {4002600101, 10026001, 2, 2, "0", "0", "I\u{0020}can't\u{0020}guarantee\u{0020}what\u{0020}will\u{0020}happen.", "何が起こっても知らないよ～。", "我可不保證會發生什麼事哦~", "0", "0", "0", "cv_sk_nasijia_2", "0", "0"},
[4002600102] = {4002600102, 10026001, 3, 3, "0", "0", "Hey\u{0020}there,\u{0020}young\u{0020}Navigator!\u{0020}I\u{0020}was\u{0020}expecting\u{0020}a\u{0020}smelly\u{0020}old\u{0020}dude,\u{0020}like\u{0020}really\u{0020}sweaty.", "へぇ、ナビゲーターなのに若いのね。汗臭い中年おやじだと思ってたのに。", "吼呀，好年輕的領航呀，還以為會是個滿身汗味的臭大叔呢。", "0", "0", "0", "cv_sk_nasijia_3", "0", "0"},
[4002600103] = {4002600103, 10026001, 91, 4, "0", "idle", "Why\u{0020}don't\u{0020}you\u{0020}come\u{0020}sit\u{0020}here\u{0020}too?\u{0020}It\u{0020}seems\u{0020}like\u{0020}you\u{0020}have\u{0020}nothing\u{0020}to\u{0020}do\u{0020}anyway.", "あんたもこっちに座ったら？どうせヒマなんでしょ。", "你要不也來這坐著吧，反正看你也很閑呢。", "0", "0", "0", "cv_sk_nasijia_4", "0", "0"},
[4002600104] = {4002600104, 10026001, 94, 4, "0", "idle2", "I\u{0020}just\u{0020}thought\u{0020}of\u{0020}something\u{0020}interesting.\u{0020}If\u{0020}you\u{0020}want\u{0020}to\u{0020}know,\u{0020}kneel\u{0020}down\u{0020}and\u{0020}beg\u{0020}me.", "面白いこと思い付いちゃった。知りたい？じゃあそこで四つん這いになって。", "突然想到件有趣的事，想知道的話就跪下來求我吧。", "0", "0", "0", "cv_sk_nasijia_5", "0", "0"},
[4002600105] = {4002600105, 10026001, 94, 4, "0", "idle2", "Of\u{0020}course,\u{0020}I'm\u{0020}different\u{0020}from\u{0020}the\u{0020}other\u{0020}drivers\u{0020}in\u{0020}the\u{0020}team.\u{0020}I'm\u{0020}just\u{0020}affiliated\u{0020}here.\u{0020}Don't\u{0020}you\u{0020}get\u{0020}it,\u{0020}stupid\u{0020}Navigator?", "あたしはあの娘たちとは全然違うの。ただ所属してるだけ。その辺、勘違いしないでよね。バカナビゲーター。", "我和隊伍的其他駕駛員當然不一樣了，只是掛名在這而已，你不會這都弄不清楚吧，笨蛋領航。", "0", "0", "0", "cv_sk_nasijia_6", "0", "0"},
[4002600106] = {4002600106, 10026001, 92, 5, "14_1_0_0.8", "touch1", "I'm\u{0020}calling\u{0020}security.", "大人のひと呼んじゃおっかな～。", "我可要呼叫警備了哦。", "0", "0", "0", "cv_sk_nasijia_7", "0", "0"},
[4002600107] = {4002600107, 10026001, 93, 5, "14_2_0_0.8", "touch_s1", "In\u{0020}public\u{0020}like\u{0020}this,\u{0020}you\u{0020}wouldn't\u{0020}want\u{0020}to\u{0020}do\u{0020}something\u{0020}like\u{0020}that\u{0020}to\u{0020}me,\u{0020}right?", "こんな人目につくところで、まさか何もするわけないよね。", "在這大庭廣眾之下，領航不會想對我做那種事情吧。", "0", "0", "0", "cv_sk_nasijia_8", "0", "0"},
[4002600108] = {4002600108, 10026001, 95, 5, "14_1_0_0.8", "touch2", "Eh?\u{0020}So,\u{0020}you\u{0020}are\u{0020}actually\u{0020}much\u{0020}older\u{0020}than\u{0020}me?\u{0020}I\u{0020}would\u{0020}never\u{0020}have\u{0020}guessed.\u{0020}You\u{0020}grew\u{0020}old\u{0020}on\u{0020}me\u{0020}all\u{0020}of\u{0020}a\u{0020}sudden,\u{0020}heh?", "え～ナビゲーターってあたしよりそんなに年上なの？見た目じゃ分かんないもんね。もうおじさんじゃん。おじさんナビゲーター。", "誒~原來領航比我大這麼多嗎？外表上完全看不出呢。一下子變成大叔了呢，領航大叔。", "0", "0", "0", "cv_sk_nasijia_9", "0", "0"},
[4002600109] = {4002600109, 10026001, 96, 5, "14_2_0_0.8", "touch_s2", "I\u{0020}heard\u{0020}you\u{0020}got\u{0020}pranked!\u{0020}Heehee.\u{0020}It\u{0020}was\u{0020}hilarious\u{0020}to\u{0020}see\u{0020}you\u{0020}drink\u{0020}juice\u{0020}with\u{0020}chili\u{0020}sauce\u{0020}in\u{0020}one\u{0020}gulp...\u{0020}But\u{0020}it\u{0020}wasn't\u{0020}me!\u{0020}I've\u{0020}been\u{0020}on\u{0020}guard\u{0020}here\u{0020}the\u{0020}whole\u{0020}time,\u{0020}stupid\u{0020}uncle.", "ナビゲーター、イタズラされたんだって？ふふ。ホットソース入りのジュースを一気飲みした時の顔ったら、ホンット最高……ん？あたしじゃないってば。ずっとここにいたじゃない。バカおじ。", "聽說領航被人惡作劇了呀，嘻嘻。加了辣椒醬的果汁一飲而盡的樣子真是太好笑了……當然不是我做的啦，我可是一直在這站崗呢，笨蛋大叔。", "0", "0", "0", "cv_sk_nasijia_10", "0", "0"},
[4002600110] = {4002600110, 10026001, 95, 5, "14_1_0_0.8", "touch2", "Are\u{0020}you\u{0020}free\u{0020}tomorrow\u{0020}night?\u{0020}I\u{0020}have\u{0020}something\u{0020}to\u{0020}tell\u{0020}you...\u{0020}Or\u{0020}maybe\u{0020}now...\u{0020}Navigator,\u{0020}I\u{0020}like...\u{0020}like...\u{0020}Ahahaha!\u{0020}You\u{0020}fell\u{0020}for\u{0020}it!\u{0020}Your\u{0020}heart\u{0020}was\u{0020}racing\u{0020}just\u{0020}now.\u{0020}Don't\u{0020}really\u{0020}think\u{0020}I'd\u{0020}confess\u{0020}to\u{0020}you,\u{0020}stupid\u{0020}uncle!", "明日の夜、空いてる？ナビゲーターにちょっと話があって……い、今でもいいんだけどさ……ナビゲーター、す……す……あはは！引っかかったー！心臓ばくばくだったでしょ。あたしが告白するって本気で思ったの？チョロおじー。", "明天晚上有空嗎?我有些話像對領航說……或者現在……領航，我喜……喜……啊哈哈哈，上當了吧，你的心剛才跳得好快哦。不會真以為我會向你表白吧，笨蛋大叔。", "0", "0", "0", "cv_sk_nasijia_11", "0", "0"},
