[4003000101] = {4003000101, 10030001, 2, 2, "0", "0", "My\u{0020}father\u{0020}once\u{0020}intended\u{0020}to\u{0020}mold\u{0020}me\u{0020}into\u{0020}a\u{0020}staff\u{0020}officer.\u{0020}Do\u{0020}you\u{0020}have\u{0020}similar\u{0020}ambitions?", "0", "父親曾計劃將我培養為參謀，您也有此打算嗎？", "0", "0", "0", "cv_sk_faernaisi_2", "0", "0"},
[4003000102] = {4003000102, 10030001, 3, 3, "0", "0", "I've\u{0020}heard\u{0020}you're\u{0020}a\u{0020}reasonable\u{0020}Navigator.\u{0020}Here,\u{0020}allow\u{0020}me\u{0020}to\u{0020}adhere\u{0020}more\u{0020}to\u{0020}my\u{0020}family's\u{0020}customs\u{0020}than\u{0020}to\u{0020}those\u{0020}of\u{0020}AEGIS.\u{0020}Thus,\u{0020}Captain\u{0020}of\u{0020}\"Astray\u{0020}Blossom,\"\u{0020}Farnese\u{0020}Lante,\u{0020}reports\u{0020}to\u{0020}you.", "0", "我已聽聞您是位通情達理的領航，在此請允許我更多按照家族的規則，而非艾吉斯的規則行事。那麼，“歧花”隊長，法爾奈斯·蘭特向您報道。", "0", "0", "0", "cv_sk_faernaisi_3", "0", "0"},
[4003000103] = {4003000103, 10030001, 4, 4, "0", "idle", "After\u{0020}a\u{0020}rose\u{0020}bath,\u{0020}I\u{0020}let\u{0020}my\u{0020}skin\u{0020}soak\u{0020}in\u{0020}the\u{0020}fresh\u{0020}air\u{0020}and\u{0020}bask\u{0020}in\u{0020}the\u{0020}sunlight\u{0020}filtering\u{0020}through\u{0020}the\u{0020}velvet\u{0020}curtains.\u{0020}There's\u{0020}nothing\u{0020}more\u{0020}suited\u{0020}for\u{0020}relaxation.", "0", "玫瑰花浴之後，讓肌膚充分接觸清新的空氣，享受從天鵝絨窗簾透入的陽光……沒有比這更適合放鬆的了。", "0", "0", "0", "cv_sk_faernaisi_4", "0", "0"},
[4003000104] = {4003000104, 10030001, 5, 4, "0", "idle", "Are\u{0020}you\u{0020}still\u{0020}lost\u{0020}in\u{0020}thought?\u{0020}Please\u{0020}decide\u{0020}quickly.\u{0020}Regardless\u{0020}of\u{0020}the\u{0020}outcome,\u{0020}I\u{0020}am\u{0020}already\u{0020}well\u{0020}prepared.", "0", "還在兀自沉思嗎？請您盡快翻牌吧，不論會面臨怎樣的結果，我都早已做好準備。", "0", "0", "0", "cv_sk_faernaisi_5", "0", "0"},
[4003000105] = {4003000105, 10030001, 6, 4, "0", "idle", "Call\u{0020}the\u{0020}other\u{0020}members\u{0020}of\u{0020}Astray\u{0020}Blossom\u{0020}another\u{0020}day?\u{0020}With\u{0020}more\u{0020}people,\u{0020}we\u{0020}might\u{0020}indulge\u{0020}in\u{0020}some\u{0020}more\u{0020}thrilling\u{0020}games.", "0", "改天也把歧花的其他幾人叫來吧？人多的話，也許可以玩些更刺激的遊戲。", "0", "0", "0", "cv_sk_faernaisi_6", "0", "0"},
[4003000106] = {4003000106, 10030001, 7, 5, "15_2_0_0.8", "touch1", "Neither\u{0020}victory\u{0020}nor\u{0020}defeat.\u{0020}I\u{0020}faced\u{0020}the\u{0020}least\u{0020}likely\u{0020}outcome.\u{0020}It\u{0020}seems\u{0020}this\u{0020}long\u{0020}game\u{0020}will\u{0020}persist.\u{0020}Is\u{0020}that\u{0020}what\u{0020}you\u{0020}desire?", "0", "既未勝利，也非失敗，我遇上了概率最小的可能啊……看來這場漫長的遊戲還將繼續下去，這是否正如您所願呢？", "0", "0", "0", "cv_sk_faernaisi_7", "0", "0"},
[4003000107] = {4003000107, 10030001, 8, 5, "15_2_0_0.8", "touch2", "The\u{0020}longing\u{0020}for\u{0020}victory\u{0020}is\u{0020}nearly\u{0020}etched\u{0020}on\u{0020}your\u{0020}face,\u{0020}but\u{0020}alas,\u{0020}I\u{0020}won\u{0020}this\u{0020}round.\u{0020}Always\u{0020}conceal\u{0020}your\u{0020}unease\u{0020}and\u{0020}desires\u{0020}well.\u{0020}That's\u{0020}the\u{0020}key\u{0020}to\u{0020}winning\u{0020}at\u{0020}the\u{0020}card\u{0020}table.", "0", "對於勝利的渴望幾乎寫在了您的臉上，但可惜，這一輪是我贏了。時刻隱瞞好自己的忐忑和欲求，這才是牌桌上的製勝之道。", "0", "0", "0", "cv_sk_faernaisi_8", "0", "0"},
[4003000108] = {4003000108, 10030001, 9, 5, "15_2_0_0.8", "touch3", "Oh?\u{0020}I\u{0020}didn't\u{0020}expect\u{0020}to\u{0020}lose.\u{0020}Oh\u{0020}dear,\u{0020}I\u{0020}didn't\u{0020}even\u{0020}realize\u{0020}my\u{0020}chips\u{0020}were\u{0020}nearly\u{0020}gone.\u{0020}How\u{0020}should\u{0020}I\u{0020}repay\u{0020}you?", "0", "哦？沒想到竟然是我輸了……哎呀，我甚至沒注意到籌碼已經所剩無幾，我究竟該用何物來向您償還才好呢？", "0", "0", "0", "cv_sk_faernaisi_9", "0", "0"},
[4003000109] = {4003000109, 10030001, 10, 5, "15_1_0_0.8", "touch4", "Um...\u{0020}Are\u{0020}you\u{0020}checking\u{0020}if\u{0020}I'm\u{0020}hiding\u{0020}any\u{0020}cards?\u{0020}How\u{0020}excessive.\u{0020}Though\u{0020}I\u{0020}don't\u{0020}mind\u{0020}cheating,\u{0020}in\u{0020}this\u{0020}outfit,\u{0020}wherever\u{0020}could\u{0020}I\u{0020}possibly\u{0020}conceal\u{0020}any\u{0020}cards?", "0", "唔……這是在檢查我身上是否藏著牌？真過分啊，雖然我的確不介意出老千，但我這身裝扮，還能往哪裡再藏一張牌呢？", "0", "0", "0", "cv_sk_faernaisi_10", "0", "0"},
[4003000110] = {4003000110, 10030001, 11, 5, "15_1_0_0.8", "touch4", "Interfering\u{0020}with\u{0020}the\u{0020}players...\u{0020}Isn't\u{0020}that\u{0020}against\u{0020}the\u{0020}rules?\u{0020}I\u{0020}admire\u{0020}your\u{0020}boldness,\u{0020}but\u{0020}if\u{0020}this\u{0020}keeps\u{0020}up,\u{0020}I'll\u{0020}have\u{0020}to\u{0020}retaliate.", "0", "對選手進行這種干擾……是違反規則的吧？我倒是不討厭您的這份膽量，但，再這樣下去我可就得以牙還牙了。", "0", "0", "0", "cv_sk_faernaisi_11", "0", "0"},
[4003000111] = {4003000111, 10030001, 12, 6, "0", "0", "One\u{0020}must\u{0020}learn\u{0020}from\u{0020}every\u{0020}situation.", "0", "何處都得學習啊。", "0", "0", "0", "cv_sk_faernaisi_12", "0", "0"},
[4003000112] = {4003000112, 10030001, 13, 7, "0", "0", "When\u{0020}the\u{0020}flowers\u{0020}bloom,\u{0020}it's\u{0020}also\u{0020}their\u{0020}moment\u{0020}of\u{0020}nearing\u{0020}withering.", "0", "花開之時，也即瀕臨凋謝之際。", "0", "0", "0", "cv_sk_faernaisi_13", "0", "0"},
[4003000113] = {4003000113, 10030001, 14, 8, "0", "0", "My\u{0020}father\u{0020}feared\u{0020}my\u{0020}talent\u{0020}and\u{0020}once\u{0020}ceased\u{0020}my\u{0020}training.\u{0020}It\u{0020}seems\u{0020}you\u{0020}won't\u{0020}do\u{0020}the\u{0020}same,\u{0020}Navigator.\u{0020}Please\u{0020}enjoy\u{0020}the\u{0020}fruits\u{0020}of\u{0020}my\u{0020}labor\u{0020}in\u{0020}the\u{0020}future.", "0", "父親畏懼我的才能，一度放棄過對我的栽培，看來領航您不會這樣。那麼，今後就請享受我所結出的碩果吧。", "0", "0", "0", "cv_sk_faernaisi_14", "0", "0"},
[4003000114] = {4003000114, 10030001, 15, 9, "0", "0", "This\u{0020}\"skill\"\u{0020}can't\u{0020}grow\u{0020}rusty.", "0", "這門“手藝”可不能生疏。", "0", "0", "0", "cv_sk_faernaisi_15", "0", "0"},
