[4100200102] = {4100200102, 11002001, 3, 3, "0", "0", "Navigator\u{0020}of\u{0020}the\u{0020}west...\u{0020}My\u{0020}name\u{0020}is\u{0020}Kokorokami.\u{0020}From\u{0020}now\u{0020}on,\u{0020}I\u{0020}will\u{0020}serve\u{0020}by\u{0020}your\u{0020}side.", "0", "西方的領航嗎……也罷，老身名為心紙，今後就由老身侍您左右吧。", "0", "0", "0", "cv_sk_kokorokami_1", "0", "0"},
[4100200103] = {4100200103, 11002001, 4, 4, "0", "idle", "Are\u{0020}the\u{0020}gods\u{0020}hypocritical?\u{0020}Huh,\u{0020}after\u{0020}turning\u{0020}delusions\u{0020}into\u{0020}reality\u{0020}and\u{0020}twisting\u{0020}all\u{0020}common\u{0020}sense,\u{0020}would\u{0020}they\u{0020}still\u{0020}care\u{0020}about\u{0020}such\u{0020}things?", "0", "神明是虛偽的嗎……哼，讓妄想變為現實，顛覆了所有常識之後，您居然還會在意這些嗎？", "0", "0", "0", "cv_sk_kokorokami_3", "0", "0"},
[4100200104] = {4100200104, 11002001, 5, 4, "0", "idle", "I\u{0020}enjoy\u{0020}the\u{0020}fragrance\u{0020}of\u{0020}tea\u{0020}and\u{0020}flowers.\u{0020}I\u{0020}didn't\u{0020}expect\u{0020}someone\u{0020}born\u{0020}in\u{0020}Danube\u{0020}to\u{0020}appreciate\u{0020}them\u{0020}too.\u{0020}That's\u{0020}quite\u{0020}rare.", "0", "茶味花香嗎……這兩者都是老身所喜好的，沒想到出生在多瑙的您也懂得欣賞這些，真是難得。", "0", "0", "0", "cv_sk_kokorokami_4", "0", "0"},
[4100200105] = {4100200105, 11002001, 6, 4, "0", "idle", "Hotarugusa...\u{0020}No,\u{0020}it\u{0020}should\u{0020}be\u{0020}Little\u{0020}Hotarugusa.\u{0020}I'd\u{0020}probably\u{0020}get\u{0020}killed\u{0020}if\u{0020}I\u{0020}called\u{0020}her\u{0020}by\u{0020}the\u{0020}wrong\u{0020}name\u{0020}in\u{0020}front\u{0020}of\u{0020}her.", "0", "瑩草姐……不對，應該是小瑩草才是……如果當著她的面說錯稱呼估計會被殺掉吧。", "0", "0", "0", "cv_sk_kokorokami_30", "0", "0"},
[4100200106] = {4100200106, 11002001, 7, 5, "15_2_0_0.8", "level1", "The\u{0020}gods\u{0020}only\u{0020}hold\u{0020}value\u{0020}when\u{0020}there's\u{0020}chaos.\u{0020}I'm\u{0020}driven\u{0020}by\u{0020}such\u{0020}a\u{0020}mission.", "0", "神明只有在動亂時才有存在的價值，老身只不過是被這樣的使命驅使著前行罷了。", "0", "0", "0", "cv_sk_kokorokami_31", "0", "0"},
[4100200107] = {4100200107, 11002001, 8, 5, "15_1_0_0.8", "level5", "Could\u{0020}you\u{0020}please\u{0020}talk\u{0020}privately?\u{0020}I'm\u{0020}not\u{0020}available\u{0020}right\u{0020}now.", "0", "可以請您私下再說嗎？現在老身並沒有空。", "0", "0", "0", "cv_sk_kokorokami_5", "0", "0"},
[4100200108] = {4100200108, 11002001, 9, 5, "15_2_0_0.8", "level2", "Why?\u{0020}Have\u{0020}you\u{0020}come\u{0020}to\u{0020}find\u{0020}me\u{0020}again?\u{0020}I'm\u{0020}sorry.\u{0020}Next\u{0020}time,\u{0020}I'll\u{0020}let\u{0020}you\u{0020}know\u{0020}in\u{0020}advance\u{0020}when\u{0020}I'm\u{0020}free.", "0", "怎麼？又來找老身了嗎？很抱歉，下次有空時會提前告知您的。", "0", "0", "0", "cv_sk_kokorokami_6", "0", "0"},
[4100200109] = {4100200109, 11002001, 10, 5, "15_2_0_0.8", "level3", "What\u{0020}a\u{0020}persistent\u{0020}man!\u{0020}So,\u{0020}what\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}talk\u{0020}about?\u{0020}Don't\u{0020}worry.\u{0020}As\u{0020}a\u{0020}shrine\u{0020}maiden\u{0020}serving\u{0020}the\u{0020}gods,\u{0020}I\u{0020}will\u{0020}patiently\u{0020}answer\u{0020}all\u{0020}your\u{0020}questions.", "0", "真是個執著的男人啊，那麼您想和老身聊些什麼呢？放心好了，身為侍奉神明的巫女，我會耐心回答完您所有的疑問。", "0", "0", "0", "cv_sk_kokorokami_7", "0", "0"},
[4100200110] = {4100200110, 11002001, 11, 5, "15_2_0_0.8", "level4", "Ah...\u{0020}It\u{0020}seems\u{0020}I've\u{0020}been\u{0020}discovered.\u{0020}The\u{0020}gods\u{0020}I\u{0020}mentioned,\u{0020}my\u{0020}hobbies...\u{0020}Even\u{0020}my\u{0020}name\u{0020}is\u{0020}false.\u{0020}Yes,\u{0020}the\u{0020}girl\u{0020}who\u{0020}has\u{0020}spent\u{0020}time\u{0020}with\u{0020}you\u{0020}is\u{0020}just\u{0020}a\u{0020}false\u{0020}incarnation,\u{0020}a\u{0020}puppet\u{0020}of\u{0020}faith.\u{0020}What?\u{0020}You\u{0020}think\u{0020}both\u{0020}sides\u{0020}of\u{0020}me\u{0020}are\u{0020}real\u{0020}in\u{0020}your\u{0020}eyes...?", "0", "啊……想必已經被發現了吧，我口中的神明，愛好……甚至我的姓名都是虛假的。沒錯，這段時間與您相處的女孩只不過是虛偽的化身，信仰的人偶罷了……什麼？您說無論哪邊的我在您眼中都是……真實的嗎……", "0", "0", "0", "cv_sk_kokorokami_8", "0", "0"},
[4100200111] = {4100200111, 11002001, 12, 6, "0", "0", "Ah...\u{0020}This\u{0020}power\u{0020}is\u{0020}welling\u{0020}up\u{0020}from\u{0020}my\u{0020}heart...", "0", "啊……這股從心中湧現出的力量……", "0", "0", "0", "cv_sk_kokorokami_9", "0", "0"},
[4100200112] = {4100200112, 11002001, 13, 7, "0", "0", "My\u{0020}faith\u{0020}has\u{0020}grown\u{0020}stronger.", "0", "信仰的純度，提高了呢。", "0", "0", "0", "cv_sk_kokorokami_10", "0", "0"},
[4100200113] = {4100200113, 11002001, 14, 8, "0", "0", "Cherry\u{0020}blossoms\u{0020}are\u{0020}falling,\u{0020}their\u{0020}beauty\u{0020}fading\u{0020}in\u{0020}an\u{0020}instant.\u{0020}What\u{0020}does\u{0020}an\u{0020}illusory\u{0020}shadow\u{0020}mean?\u{0020}It's\u{0020}worth\u{0020}dedicating\u{0020}half\u{0020}a\u{0020}lifetime\u{0020}to\u{0020}understand.\u{0020}Yet,\u{0020}your\u{0020}intentions\u{0020}have\u{0020}come\u{0020}through.", "0", "落櫻紛飛，刹那芳華，何為虛影，傾此半生。但您的心意，已經傳達到了。", "0", "0", "0", "cv_sk_kokorokami_11", "0", "0"},
