[4100300101] = {4100300101, 11003001, 2, 2, "0", "0", "Um,\u{0020}I\u{0020}see.", "ふむ、分かった。", "嗚姆，我知道了。", "0", "呜姆，咱知道了。", "0", "cv_sk_suzuki_2", "0", "0"},
[4100300102] = {4100300102, 11003001, 3, 3, "0", "0", "I'm\u{0020}Suzuki\u{0020}Seifung\u{0020}from\u{0020}Fuurinkazan,\u{0020}and\u{0020}by\u{0020}the\u{0020}way,\u{0020}I'm\u{0020}the\u{0020}team\u{0020}captain.", "うちは風林火山の鈴木清風。ちなみに、隊長やで。", "我是風林火山的鈴木清風，順帶一提，我可是隊長喔。", "0", "咱是风林火山的铃木清风，顺带一提，咱可是队长哦。", "0", "cv_sk_suzuki_3", "0", "0"},
[4100300103] = {4100300103, 11003001, 4, 4, "0", "idle", "\"A\u{0020}night's\u{0020}dream\u{0020}is\u{0020}hard\u{0020}to\u{0020}grasp.\u{0020}The\u{0020}mirror\u{0020}flower\u{0020}is\u{0020}tough\u{0020}to\u{0020}pick,\u{0020}and\u{0020}the\u{0020}moon\u{0020}in\u{0020}the\u{0020}water\u{0020}ripples.\u{0020}Only\u{0020}tears\u{0020}and\u{0020}sorrows\u{0020}remain.\"\u{0020}Ah,\u{0020}I've\u{0020}forgotten\u{0020}the\u{0020}rest\u{0020}again.\u{0020}Reciting\u{0020}lines\u{0020}for\u{0020}a\u{0020}play\u{0020}is\u{0020}quite\u{0020}challenging.", "一夜の夢、鏡に映し、ただ憂い……あー、また忘れてもうた。舞台のセリフってホンマ覚えられへんわ。", "“一宵梦黄粱，镜花难折水月荡，徒余泪愁肠。”然后是……啊，又忘了。话剧台词还真是难背呢。", "0", "对咱而言，优先保护好同伴才是最重要的。", "0", "cv_sk_suzuki_4", "0", "0"},
[4100300104] = {4100300104, 11003001, 5, 4, "0", "idle", "Feeling\u{0020}sleepy?\u{0020}If\u{0020}so,\u{0020}take\u{0020}some\u{0020}time\u{0020}to\u{0020}rest.\u{0020}Um...\u{0020}it\u{0020}seems\u{0020}our\u{0020}performance\u{0020}wasn't\u{0020}captivating\u{0020}enough.\u{0020}We\u{0020}need\u{0020}to\u{0020}step\u{0020}up\u{0020}our\u{0020}game!", "眠いんか？とりあえずゆっくり休んどき。うー……、やっぱうちの演技はまだまだやな。もっと頑張らなあかんな！", "困了吗？先好好休息下吧。唔……看来咱的演绎还不够吸引人呢，必须要再加把劲了！", "0", "领航呀，咱很好奇呀，你难道不需要休息吗？", "0", "cv_sk_suzuki_5", "0", "0"},
[4100300105] = {4100300105, 11003001, 6, 4, "0", "idle", "I\u{0020}didn't\u{0020}expect\u{0020}that\u{0020}in\u{0020}this\u{0020}drama,\u{0020}we\u{0020}also\u{0020}have\u{0020}to\u{0020}play\u{0020}the\u{0020}role\u{0020}of\u{0020}a\u{0020}lady,\u{0020}caring\u{0020}for\u{0020}the\u{0020}children\u{0020}just\u{0020}arrived\u{0020}in\u{0020}Sueno\u{0020}Village,\u{0020}played\u{0020}by\u{0020}Shiranui,\u{0020}Kuriyama\u{0020}Seiran,\u{0020}and\u{0020}Morimura\u{0020}Kinosuke.", "栖野庄に新しく来た子らを不知火と青鸞と鬼之介が演じるんや。まさか舞台でも姉さんになって世話することになるとは思わんかったわ。", "没想到在话剧里，咱也要作为“大姐”，照顾不知火、青鸾、鬼之介所扮演的，初来栖野庄的孩子们呢。", "0", "不知火那孩子，总是用看小孩的目光看着咱呢。呼呼呼，对于咱来说，她才是需要照顾的孩子呢。因为，咱才是这支队伍的队长呀。", "0", "cv_sk_suzuki_6", "0", "0"},
[4100300106] = {4100300106, 11003001, 7, 5, "1_》_0_0.8", "level1", "\"Elegy\u{0020}of\u{0020}Sueno\"\u{0020}tells\u{0020}the\u{0020}tale\u{0020}of\u{0020}the\u{0020}oiran,\u{0020}and\u{0020}all\u{0020}the\u{0020}cast\u{0020}members\u{0020}are\u{0020}driver\u{0020}girls.\u{0020}I\u{0020}heard\u{0020}this\u{0020}was\u{0020}done\u{0020}as\u{0020}a\u{0020}tribute\u{0020}to\u{0020}a\u{0020}renowned\u{0020}opera\u{0020}troupe.", "「栖野哀歌」って花魁のお話やねんけど、キャストがドライバーの女の子だけなんは、有名な歌劇団へのオマージュらしいで。", "《栖野哀歌》讲述的是关于花魁的故事，而话剧选角全都是驾驶员少女们，咱听说，这么做是为了致敬某个知名歌剧团哦。", "0", "咱的梦想？呜，咱可没有精力去想那些。光是照顾队伍里的同伴，就已经耗费咱不少精力了。", "0", "cv_sk_suzuki_7", "0", "0"},
[4100300107] = {4100300107, 11003001, 8, 5, "1_》_0_0.8", "level1", "I\u{0020}put\u{0020}a\u{0020}lot\u{0020}of\u{0020}effort\u{0020}into\u{0020}creating\u{0020}this\u{0020}costume,\u{0020}but\u{0020}there\u{0020}are\u{0020}too\u{0020}many\u{0020}layers.\u{0020}It's\u{0020}hard\u{0020}to\u{0020}put\u{0020}them\u{0020}on\u{0020}by\u{0020}myself.\u{0020}Navigator,\u{0020}could\u{0020}you\u{0020}help\u{0020}me\u{0020}out\u{0020}with\u{0020}some\u{0020}of\u{0020}it?", "この衣装、ホンマに心を込めて作ったんやけど、重ね着が大変すぎて一人で着られへんねん。ナビゲーター、手伝ってくれるか？", "对于这戏服，咱可是很用心制作的，结果整套衣物的层数太多，倒是难以只靠自己穿上了。领航能搭把手、帮咱穿上几件吗？", "0", "别……别老是光盯着咱啊，有话快问啦。", "0", "cv_sk_suzuki_8", "0", "0"},
[4100300108] = {4100300108, 11003001, 9, 5, "1_》_0_0.8", "level2", "Costumes,\u{0020}makeup,\u{0020}stage\u{0020}props...\u{0020}Um,\u{0020}everything\u{0020}is\u{0020}pretty\u{0020}much\u{0020}ready.\u{0020}Navigator,\u{0020}what\u{0020}do\u{0020}you\u{0020}think\u{0020}of\u{0020}this\u{0020}scene?\u{0020}It's\u{0020}beautiful,\u{0020}right?\u{0020}Wait,\u{0020}are\u{0020}you\u{0020}really\u{0020}talking\u{0020}about\u{0020}me...?!", "衣装とかメイクとか小道具とか、まあまあ、しっかりと用意したつもりや。ナビゲーター、このシーン、どう思う？……うんうん、キレイやろ？……え？うちのこと言うてんの！？", "服饰、妆容、舞台道具……呜姆，基本算是周全了。领航觉得这幅场景怎么样？嗯嗯，很漂亮对吧？欸？居然是在说咱吗……！", "0", "哎？想向咱请教该怎么和队员交流。嗯嗯……老实说，咱也不是很清楚哎……", "0", "cv_sk_suzuki_9", "0", "0"},
[4100300109] = {4100300109, 11003001, 10, 5, "1_》_0_0.8", "level3", "Drink\u{0020}half\u{0020}a\u{0020}cup\u{0020}of\u{0020}turbid\u{0020}wine\u{0020}again\u{0020}and\u{0020}play\u{0020}a\u{0020}piece\u{0020}of\u{0020}elegant\u{0020}lyrics.\u{0020}And\u{0020}then\u{0020}tonight...\u{0020}Ah,\u{0020}no!\u{0020}Navigator,\u{0020}I'm\u{0020}not\u{0020}drunk\u{0020}at\u{0020}all.\u{0020}I'm\u{0020}just\u{0020}a\u{0020}bit\u{0020}too\u{0020}immersed\u{0020}in\u{0020}the\u{0020}play.\u{0020}If\u{0020}you\u{0020}don't\u{0020}believe\u{0020}me,\u{0020}pinch\u{0020}my\u{0020}face\u{0020}and\u{0020}see?", "にごり酒を一献（いっこん）、無粋はそろそろおさらばえ。今宵は……って、あかん、あかん！ナビゲーター、う、うちは酔ってへんで。ただちょっと役に入り込み過ぎてもうただけや。信じてないなら、ほっぺたつねってみい", "再饮半杯浊酒，抚一曲清词，然后今夜……啊不对！领航，咱、咱才没有醉呢，只是入戏有些深而已，不信的话，你揪一下咱的脸看看？", "0", "哎？咱喜欢的东西？嗯嗯……寿喜烧吧。当然，咱指得是喜欢制作寿喜烧，而不是吃啦。", "0", "cv_sk_suzuki_10", "0", "0"},
[4100300110] = {4100300110, 11003001, 11, 5, "1_》_0_0.8", "level4", "I\u{0020}feel\u{0020}the\u{0020}ending\u{0020}of\u{0020}the\u{0020}drama\u{0020}is\u{0020}a\u{0020}bit\u{0020}sad.\u{0020}After\u{0020}all,\u{0020}the\u{0020}title\u{0020}contains\u{0020}\"elegy.\"\u{0020}However,\u{0020}the\u{0020}story\u{0020}conveys\u{0020}not\u{0020}just\u{0020}sadness\u{0020}but\u{0020}also\u{0020}a\u{0020}determination\u{0020}to\u{0020}fight\u{0020}against\u{0020}fate.\u{0020}For\u{0020}our\u{0020}future,\u{0020}we\u{0020}must\u{0020}work\u{0020}harder\u{0020}outside\u{0020}the\u{0020}play!", "「哀歌」ってタイトルだけあって、ラストはちょっと悲しいねん。せやけど、この物語は悲しみだけやなくて、運命と戦う決意も描いてんねん。うちらの未来のために、舞台の外でももっと頑張らなあかんな！", "感觉话剧的结尾有些悲凉呢，毕竟剧名就带有“哀歌”啊。不过，故事所传递的并不只是悲伤，还有与命运抗争的决心，为了咱们的未来，戏外也得更加努力呢！", "0", "真是的，这段时间领航你总是问东问西的，整得就像是咱那个没换牙的弟弟一样。不过……咱觉得这种关系也不错呢。", "0", "cv_sk_suzuki_11", "0", "0"},
[4100300111] = {4100300111, 11003001, 12, 6, "0", "0", "Amazing!\u{0020}Navigator,\u{0020}I've\u{0020}become\u{0020}stronger!", "大変、ナビゲーター！うち、強くなったんよ！", "不得了啊！領航，我變強了呀！", "0", "不得了啊！领航，咱变强了呀！", "0", "cv_sk_suzuki_12", "0", "0"},
[4100300112] = {4100300112, 11003001, 13, 7, "0", "0", "Are\u{0020}you...\u{0020}really\u{0020}that\u{0020}concerned\u{0020}about\u{0020}me?", "そんなに……うちのことが気になる？", "你就……這麼在意我嗎？", "0", "你就……这么在意咱吗？", "0", "cv_sk_suzuki_13", "0", "0"},
[4100300113] = {4100300113, 11003001, 14, 8, "0", "0", "Ooh\u{0020}ooh\u{0020}ooh\u{0020}ooh—Navigator,\u{0020}did\u{0020}you\u{0020}see\u{0020}it!\u{0020}The\u{0020}color\u{0020}of\u{0020}the\u{0020}sword...\u{0020}the\u{0020}color\u{0020}of\u{0020}the\u{0020}blade!!!\u{0020}Wait,\u{0020}you\u{0020}say\u{0020}there's\u{0020}no\u{0020}change?!", "おおっ――ナビゲーター！今の見た？刀の色……刃の色！！！えっ？特に変わっとらんって？！", "喔喔喔喔——領航，你看到了嗎！刀的顏色…刀刃的顏色！！！欸，你說沒啥變化？！", "0", "噢噢噢噢——领航，你看到了吗！刀的颜色…刀刃的颜色！！！哎，你说没啥变化？！", "0", "cv_sk_suzuki_14", "0", "0"},
[4100300114] = {4100300114, 11003001, 15, 9, "0", "0", "Steady!", "ばっちり！", "穩穩滴！", "0", "妥妥滴！", "0", "cv_sk_suzuki_15", "0", "0"},
[4100300115] = {4100300115, 11003001, 16, 10, "0", "0", "Cut\u{0020}down\u{0020}the\u{0020}enemy's\u{0020}flag!", "敵の旗を斬り落とせ！", "斬落敵人的旗幟吧！", "0", "斩落敌人的旗帜吧！", "0", "cv_sk_suzuki_16", "0", "0"},
[4100300116] = {4100300116, 11003001, 17, 11, "0", "0", "Um,\u{0020}this\u{0020}is\u{0020}truly\u{0020}a\u{0020}refreshing\u{0020}battle.", "ふぅ、爽快な戦いやったわぁ。", "嗚姆，真是一場爽快的戰鬥。", "0", "呜姆，真是一场爽快的战斗。", "0", "cv_sk_suzuki_17", "0", "0"},
[4100300117] = {4100300117, 11003001, 18, 12, "0", "0", "Alright,\u{0020}it's\u{0020}time\u{0020}to\u{0020}head\u{0020}back.", "よし、帰ろ。", "好了，該回去啦。", "0", "妥了，该回去啦。", "0", "cv_sk_suzuki_18", "0", "0"},
[4100300118] = {4100300118, 11003001, 19, 13, "0", "0", "Um,\u{0020}it's\u{0020}good\u{0020}that\u{0020}everyone\u{0020}can\u{0020}return\u{0020}safely.", "ふむ、みんな無事に帰ってこれてよかったわ。", "嗚姆，大家能平安回來就好。", "0", "呜姆，大家能平安回来就好。", "0", "cv_sk_suzuki_19", "0", "0"},
