[4100300232] = {4100300232, 11003002, 34, 26, "0", "0", "Oh,\u{0020}you're\u{0020}back!\u{0020}I'm\u{0020}a\u{0020}bit\u{0020}confused\u{0020}about\u{0020}a\u{0020}part\u{0020}of\u{0020}the\u{0020}script.\u{0020}Can\u{0020}you\u{0020}help\u{0020}me\u{0020}rehearse?", "うちはここでずっと待ってたで、ナビゲーター！", "咱在這裡恭候多時了，領航！", "0", "咱在这里恭候多时了，领航！", "0", "cv_sk1_suzuki_32", "0", "0"},
[4100300233] = {4100300233, 11003002, 0, 27, "0", "0", "Let\u{0020}the\u{0020}show\u{0020}begin!", "おもろいことが始まるらしいで。", "讓好戲上演吧！", "0", "让好戏上演吧！", "0", "cv_sk1_suzuki_34", "0", "0"},
