[4100300239] = {4100300239, 11003002, 41, 33, "0", "0", "Make\u{0020}sure\u{0020}you\u{0020}check\u{0020}your\u{0020}situation\u{0020}properly.", "自分の状況をちゃんと確認せんといかんなあ。", "要好好確認自己的狀況才行喔。", "0", "要好好确认自己的状况才行哦。", "0", "cv_sk1_suzuki_40", "0", "0"},
[4100300240] = {4100300240, 11003002, 42, 34, "0", "0", "A\u{0020}great\u{0020}commander\u{0020}knows\u{0020}how\u{0020}to\u{0020}be\u{0020}flexible.", "臨機応変に対応出来るっちゅーことは、優秀な指揮官に要求される才能なんやで。", "適當的變通才是優秀指揮官的體現。", "0", "适当的变通才是优秀指挥官的体现。", "0", "cv_sk1_suzuki_41", "0", "0"},
[4100300241] = {4100300241, 11003002, 43, 35, "0", "0", "Let\u{0020}me\u{0020}see\u{0020}who\u{0020}the\u{0020}letter\u{0020}is\u{0020}from!", "誰からのメールなんか、先にうちに見せてーやー。", "讓咱先看看是誰的信！", "0", "让咱先看看是谁的信！", "0", "cv_sk1_suzuki_42", "0", "0"},
[4100300242] = {4100300242, 11003002, 44, 36, "0", "0", "It's\u{0020}incredible\u{0020}how\u{0020}everyone\u{0020}is\u{0020}connected\u{0020}through\u{0020}this!", "不思議やな！みんな、こんなんで繋がってる！", "真是不可思議呢，大家通過這個東西聯繫在一起！", "0", "真是不可思议呢，大家通过这个东西联系在一起！", "0", "cv_sk1_suzuki_43", "0", "0"},
[4100300243] = {4100300243, 11003002, 45, 37, "0", "0", "Let's\u{0020}confirm\u{0020}it\u{0020}together!", "うちと一緒に確認しよう。", "和咱一起好好確認下吧。", "0", "和咱一起好好确认下吧。", "0", "cv_sk1_suzuki_44", "0", "0"},
[4100400100] = {4100400100, 11004001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_sk_kuriyama_31", "0", "0"},
[4100400101] = {4100400101, 11004001, 2, 2, "0", "0", "Oh,\u{0020}you\u{0020}mean...\u{0020}Um,\u{0020}sorry\u{0020}if\u{0020}I\u{0020}overthought\u{0020}that.", "0", "您的意思是……嗯嗯，抱歉，可能是我想多了。", "0", "您的意思是……嗯嗯，抱歉，可能是我想多了。", "0", "cv_sk_kuriyama_2", "0", "0"},
[4100400102] = {4100400102, 11004001, 3, 3, "0", "0", "Nice\u{0020}to\u{0020}meet\u{0020}you!\u{0020}I'm\u{0020}Kuriyama\u{0020}Seiran\u{0020}from\u{0020}Fuurinkazan.\u{0020}I\u{0020}hope\u{0020}my\u{0020}appearance\u{0020}didn't\u{0020}scare\u{0020}you.", "0", "初次見面，我是來自風林火山部隊的栗山青鸞。那個……我的身體應該沒有嚇到您吧？", "0", "初次见面，我是来自风林火山部队的栗山青鸾。那个……我的身体应该没有吓到您吧？", "0", "cv_sk_kuriyama_1", "0", "0"},
[4100400103] = {4100400103, 11004001, 4, 4, "0", "idle", "Isn't\u{0020}my\u{0020}prosthetic\u{0020}limb\u{0020}beautiful?\u{0020}It\u{0020}was\u{0020}specially\u{0020}modified\u{0020}for\u{0020}this\u{0020}stage.\u{0020}But\u{0020}while\u{0020}it\u{0020}looks\u{0020}lovely,\u{0020}it's\u{0020}not\u{0020}a\u{0020}normal\u{0020}arm.\u{0020}Um,\u{0020}would\u{0020}you\u{0020}like\u{0020}to\u{0020}touch\u{0020}it?\u{0020}Please,\u{0020}feel\u{0020}free!", "この義肢、綺麗じゃないですか？この舞台のための特注品です。でもどんなに綺麗でも普通の腕じゃ……え、触ってみたい、ですか？はい…ど、どうぞ。", "義肢很漂亮吧，是特地為了這次的舞臺改裝的。不過再漂亮也不是正常的手臂……唔，您想摸摸看？請……請吧。", "0", "我的身体……很吓人吧？如果让您感到不舒服的话我马上就离开这里。哎？你说不用放在心上？", "0", "cv_sk_kuriyama_3", "0", "0"},
[4100400104] = {4100400104, 11004001, 5, 4, "0", "idle", "Taro\u{0020}also\u{0020}has\u{0020}a\u{0020}role\u{0020}in\u{0020}this\u{0020}performance.\u{0020}I\u{0020}play\u{0020}the\u{0020}oiran,\u{0020}and\u{0020}Taro\u{0020}portrays\u{0020}the\u{0020}fox\u{0020}that\u{0020}lives\u{0020}in\u{0020}the\u{0020}oiran's\u{0020}mask.", "舞台劇には太郎にも役があるんですよ。私は花魁役で、太郎の役はお面に宿りし妖怪ーー「こん」です。", "這場演出也有屬於太郎的角色。我扮演花魁，太郎扮演寄宿在花魁面具中的妖異之力——狐。", "0", "这个孩子的名字叫做太郎，我和他的视觉是共享的哦。它很厉害吧，嘿嘿。", "0", "cv_sk_kuriyama_4", "0", "0"},
[4100400105] = {4100400105, 11004001, 6, 4, "0", "idle", "Where\u{0020}is\u{0020}Suzuki\u{0020}Seifung?\u{0020}Navigator,\u{0020}have\u{0020}you\u{0020}seen\u{0020}Sister\u{0020}Suzuki,\u{0020}the\u{0020}captain?\u{0020}It's\u{0020}almost\u{0020}time\u{0020}for\u{0020}my\u{0020}rival\u{0020}scene\u{0020}with\u{0020}her,\u{0020}but\u{0020}we\u{0020}haven't\u{0020}practiced\u{0020}the\u{0020}lines\u{0020}yet!", "\u{0020}鈴木姉、どこ？ナビゲーター、鈴木姉……隊長を見かけましたか？もうすぐ私達のシーンが始まりまるんですが、まだ合わせてないんです。", "鈴木姐，鈴木清風姐你在哪？領航您有看到鈴木姐……隊長嗎？馬上就是我和她的對手戲了，但我們還沒有對過臺詞。", "0", "今天又没能好好和鬼之介说上话呢……虽然她总是一副生气的样子，但是我还是觉得她其实是个好孩子。", "0", "cv_sk_kuriyama_28", "0", "0"},
[4100400106] = {4100400106, 11004001, 7, 5, "15_2_0_0.8", "level2", "I\u{0020}don't\u{0020}really\u{0020}understand\u{0020}\"tragedy.\"\u{0020}The\u{0020}oiran\u{0020}I\u{0020}portray\u{0020}fights\u{0020}evil\u{0020}spirits\u{0020}every\u{0020}day,\u{0020}but\u{0020}she\u{0020}has\u{0020}the\u{0020}fox\u{0020}and\u{0020}her\u{0020}companions\u{0020}with\u{0020}her.\u{0020}I\u{0020}don't\u{0020}see\u{0020}anything\u{0020}sad\u{0020}about\u{0020}that.", "「悲劇」なのかよくわからないんです。例えば私が演じてる花魁さんは毎日妖怪と戦っていますが、こんが隣にいてくれたら、そんなに悲しくはないと思うんです。", "我不太理解“悲劇”的含義。例如我所扮演的花魁，雖然每天都與妖邪戰鬥，但是有狐和同伴陪伴在身邊。我並沒發現哪里值得悲哀。", "0", "领航……战争结束了之后，您能和我一起去一个地方吗？有些话，只有在那里才能告诉领航。诶？什么话……呜，现在还不能说！", "0", "cv_sk_kuriyama_29", "0", "0"},
[4100400107] = {4100400107, 11004001, 8, 5, "15_2_0_0.8", "level2", "This\u{0020}dress\u{0020}was\u{0020}made\u{0020}by\u{0020}Sister\u{0020}Suzuki\u{0020}herself,\u{0020}and\u{0020}I\u{0020}love\u{0020}how\u{0020}smooth\u{0020}the\u{0020}fabric\u{0020}feels.\u{0020}However,\u{0020}it\u{0020}can\u{0020}get\u{0020}a\u{0020}bit\u{0020}chilly\u{0020}when\u{0020}the\u{0020}wind\u{0020}blows.", "この衣装は鈴木姉のお手製で、生地のなめらな触感が特に好きなんですが、風にあたるとちょっとすーすーしますね。", "這件衣服是鈴木姐親手製作的，我很喜歡布料絲滑的觸感，只是風來吹的時候感覺有些涼颼颼。", "0", "哎？周末想要和我一起出去玩？但是…我的身体……大家会害怕的……", "0", "cv_sk_kuriyama_5", "0", "0"},
[4100400108] = {4100400108, 11004001, 9, 5, "15_1_0_0.8", "level1", "Wine?\u{0020}It's\u{0020}actually\u{0020}just\u{0020}water.\u{0020}After\u{0020}Suzuki\u{0020}Seifung\u{0020}got\u{0020}drunk\u{0020}and\u{0020}embarrassed\u{0020}herself\u{0020}on\u{0020}stage,\u{0020}they\u{0020}switched\u{0020}all\u{0020}the\u{0020}wine\u{0020}in\u{0020}the\u{0020}theater\u{0020}to\u{0020}water.\u{0020}I\u{0020}remember\u{0020}you\u{0020}were\u{0020}there,\u{0020}Navigator...", "お酒？いえ、これはただのお水ですよ。前回、鈴木姉が舞台で酔っ払ってからは、全部入れ替えられました。えっと、あの時ナビゲーターもいましたっけ……", "酒？只是清水而已。自從經歷鈴木姐喝醉了上臺的失態之後，她們就把劇場中的酒都用清水代替了。誒，我記得當時領航您也在場吧……", "0", "这里是……幼儿园？原来如此，一起出去玩的意思是做义工啊。但是我的身体真的不会吓到孩子们吗？", "0", "cv_sk_kuriyama_6", "0", "0"},
[4100400109] = {4100400109, 11004001, 10, 5, "15_1_0_0.8", "level1", "Even\u{0020}though\u{0020}my\u{0020}left\u{0020}hand\u{0020}is\u{0020}a\u{0020}prosthetic\u{0020}limb,\u{0020}it\u{0020}has\u{0020}a\u{0020}tactile\u{0020}feedback\u{0020}device,\u{0020}so\u{0020}it\u{0020}feels\u{0020}like\u{0020}a\u{0020}normal\u{0020}arm.\u{0020}I\u{0020}can\u{0020}even\u{0020}sense\u{0020}the\u{0020}strength\u{0020}and\u{0020}warmth\u{0020}of\u{0020}your\u{0020}palm...", "これは義肢ですが、普通の腕と同じように感じるために、触覚センサーが埋め込んであります…。…感じます、あなたの力と、温もりを……", "我的左手雖然是義肢，但是安裝了觸覺回饋器，所以擁有正常手臂那樣的接觸感受……我能感受到您手掌的力度，溫度……", "0", "马……马上就来！姐姐的手臂一次性能拎起3桶水呢！哎？是领航吗？！不……不好意思，不经意间就和孩子们打成一片了。", "0", "cv_sk_kuriyama_7", "0", "0"},
[4100400110] = {4100400110, 11004001, 11, 5, "15_2_0_0.8", "level2", "What\u{0020}do\u{0020}you\u{0020}think\u{0020}of\u{0020}the\u{0020}performance?\u{0020}Before\u{0020}I\u{0020}went\u{0020}on\u{0020}stage,\u{0020}I\u{0020}was\u{0020}really\u{0020}nervous,\u{0020}but\u{0020}when\u{0020}I\u{0020}spotted\u{0020}you\u{0020}in\u{0020}the\u{0020}audience,\u{0020}I\u{0020}felt\u{0020}so\u{0020}much\u{0020}calmer...\u{0020}Will\u{0020}you\u{0020}come\u{0020}to\u{0020}see\u{0020}the\u{0020}next\u{0020}performance\u{0020}too?", "今回の舞台、いかかでしたか？最初は緊張してドキドキしていましたが、観客席にいるあなたを見つけたら、なぜか気持ちが穏やかになりました。……次の部も、観に来てくれませんか？", "這次的演出您覺得如何？本來在上臺前還緊張得心砰砰亂跳，但是一看到您坐在觀眾席上，我就不知覺地平靜了下來……下次的演出，您也會來觀賞嗎？", "0", "丑陋的就是丑陋的，无论如何我的身体都无法被称之为美丽的。曾经我也因为这种事情而痛苦过，失落过。但是因为您的缘故，我想我也会开始慢慢接受这样的自己了吧。", "0", "cv_sk_kuriyama_8", "0", "0"},
[4100400111] = {4100400111, 11004001, 12, 6, "0", "0", "Thank\u{0020}you!\u{0020}I\u{0020}will\u{0020}cherish\u{0020}it.", "0", "謝謝，我會好好珍惜的。", "0", "谢谢，我会好好珍惜的。", "0", "cv_sk_kuriyama_9", "0", "0"},
[4100400112] = {4100400112, 11004001, 13, 7, "0", "0", "Is\u{0020}this\u{0020}a\u{0020}new\u{0020}prosthetic\u{0020}limb?", "0", "是新的義肢嗎？", "0", "是新的义肢吗？", "0", "cv_sk_kuriyama_10", "0", "0"},
[4100400113] = {4100400113, 11004001, 14, 8, "0", "0", "You're\u{0020}accepting\u{0020}me\u{0020}like\u{0020}this\u{0020}and\u{0020}training\u{0020}me\u{0020}to\u{0020}this\u{0020}extent...\u{0020}Um!\u{0020}Please\u{0020}rest\u{0020}assured,\u{0020}I\u{0020}won't\u{0020}disappoint\u{0020}your\u{0020}expectations!", "0", "接受這樣的我，將我培養到這種程度……嗯！還請放心吧，我絕對不會辜負您的期待！", "0", "接受这样的我，将我培养到这种程度……嗯！还请放心吧，我绝对不会辜负您的期待！", "0", "cv_sk_kuriyama_11", "0", "0"},
