[4100600100] = {4100600100, 11006001, 1, 1, "0", "0", "Hazereverb,\u{0020}baka!", "0", "蒼霧殘響~哢嚓。", "0", "0", "0", "cv_sk_jenny_33", "0", "0"},
[4100600101] = {4100600101, 11006001, 2, 2, "0", "0", "Oh,\u{0020}this\u{0020}position\u{0020}is\u{0020}pretty\u{0020}good.\u{0020}Looks\u{0020}like\u{0020}I'll\u{0020}have\u{0020}more\u{0020}materials\u{0020}to\u{0020}shoot.\u{0020}It'd\u{0020}be\u{0020}even\u{0020}better\u{0020}if\u{0020}I\u{0020}could\u{0020}stay\u{0020}more\u{0020}concealed.", "0", "喔~這個位置不錯啊，看來能拍攝的素材又變多了。就是如果能再隱蔽點就好了。", "0", "0", "0", "cv_sk_jenny_2", "0", "0"},
[4100600102] = {4100600102, 11006001, 3, 3, "0", "0", "Yo!\u{0020}I\u{0020}heard\u{0020}some\u{0020}big\u{0020}news\u{0020}around\u{0020}here,\u{0020}so\u{0020}I\u{0020}came\u{0020}by.\u{0020}Nice\u{0020}to\u{0020}meet\u{0020}you\u{0020}for\u{0020}the\u{0020}first\u{0020}time!\u{0020}I'm\u{0020}Jenny\u{0020}Rose.", "0", "呦~聽說這邊有大新聞俺就來了，初次見面，俺叫燕妮·羅斯。", "0", "0", "0", "cv_sk_jenny_1", "0", "0"},
[4100600103] = {4100600103, 11006001, 4, 4, "0", "idle", "Jingle\u{0020}bells,\u{0020}jingle\u{0020}bells,\u{0020}Santa\u{0020}Claus\u{0020}is\u{0020}coming.\u{0020}Ho!\u{0020}Ho!\u{0020}Ho!\u{0020}Guess\u{0020}what\u{0020}goodies\u{0020}I\u{0020}brought\u{0020}you\u{0020}as\u{0020}a\u{0020}Christmas\u{0020}present!", "ジングルベル、ジングルベル、鈴が鳴る～。ほーほっほっほー、サンタクロースが来たぜ。クリスマスプレゼントは何だか分かるか？", "叮铃咚，叮铃咚，圣诞老人来了哦。吼~吼~吼~猜猜我给你带了什么好东西，作为圣诞礼物。", "0", "0", "0", "cv_sk_jenny_3", "0", "0"},
[4100600104] = {4100600104, 11006001, 5, 4, "0", "idle", "A\u{0020}present?\u{0020}Of\u{0020}course,\u{0020}it's\u{0020}free!\u{0020}If\u{0020}you\u{0020}feel\u{0020}guilty\u{0020}about\u{0020}it,\u{0020}just\u{0020}share\u{0020}some\u{0020}secrets\u{0020}with\u{0020}me.\u{0020}For\u{0020}instance,\u{0020}how\u{0020}many\u{0020}drivers\u{0020}have\u{0020}synced\u{0020}with\u{0020}you…", "プレゼント？もちろん無料だ。もし気持ちに応えたいなら、あんたの秘密をいくつか教えてくれよ。たとえば、何人のドライバーと通感覚を接続したかとかさ……", "礼物？当然是免费的啦。如果觉得良心不安的话，就给俺讲些不为人知的秘密吧，比如有多少驾驶员与你通感过了呢……", "0", "0", "0", "cv_sk_jenny_4", "0", "0"},
[4100600105] = {4100600105, 11006001, 6, 4, "0", "idle", "\"Shocking!\u{0020}The\u{0020}Navigator\u{0020}were\u{0020}in\u{0020}the\u{0020}same\u{0020}room\u{0020}with\u{0020}multiple\u{0020}girls\u{0020}on\u{0020}Christmas\u{0020}Eve!\"\u{0020}I\u{0020}really\u{0020}don't\u{0020}get\u{0020}why\u{0020}readers\u{0020}today\u{0020}are\u{0020}drawn\u{0020}to\u{0020}such\u{0020}sensational\u{0020}headlines.\u{0020}But\u{0020}I\u{0020}won't\u{0020}compromise!", "「驚愕！ナビゲーター、クリスマスイブに複数の女の子と同じ部屋で！」…なんで最近の読者は、みんなこんな感じの見出しが好きなんだ？わからねーな。でも、だからといって妥協はしねーぞ！", "“震惊，平安夜领航竟与多名少女同处一室！”真搞不懂为什么现在的读者都喜欢这种掐头去尾的新闻标题。但是，俺是绝对不会向他们妥协的！", "0", "0", "0", "cv_sk_jenny_30", "0", "0"},
[4100600106] = {4100600106, 11006001, 7, 5, "15_2_0_0.8", "level2", "At\u{0020}Christmas,\u{0020}besides\u{0020}exchanging\u{0020}gifts,\u{0020}people\u{0020}also\u{0020}share\u{0020}wild\u{0020}gossip\u{0020}and\u{0020}funny\u{0020}stories.\u{0020}The\u{0020}best\u{0020}news\u{0020}is\u{0020}hidden\u{0020}among\u{0020}phrases\u{0020}like\u{0020}\"I\u{0020}heard\u{0020}someone…\"\u{0020}or\u{0020}\"Recently,\u{0020}it\u{0020}seems…\"\u{0020}and\u{0020}\"Do\u{0020}you\u{0020}know?\"", "クリスマスは、プレゼントの他に根も葉もない噂話も飛び交うんだ。「噂によれば……」「最近誰々が……」「ねえねえ、知ってる？」ってな。そういうところに、ニュースが隠れてるんだよ。", "在圣诞节人们会互相交换的除了圣诞礼物还有一些空穴来风的八卦趣事，而新闻就在“听说那谁……”、“最近好像……”和“你知道吗？”之间藏匿着。", "0", "0", "0", "cv_sk_jenny_31", "0", "0"},
[4100600107] = {4100600107, 11006001, 8, 5, "15_2_0_0.8", "level2", "Merry\u{0020}Christmas!", "メリークリスマス！", "MerryChristmas", "0", "0", "0", "cv_sk_jenny_5", "0", "0"},
[4100600108] = {4100600108, 11006001, 9, 5, "15_1_0_0.8", "level1", "Looking\u{0020}down\u{0020}from\u{0020}above,\u{0020}the\u{0020}chimney\u{0020}that\u{0020}usually\u{0020}seems\u{0020}big\u{0020}looks\u{0020}so\u{0020}small.\u{0020}Will\u{0020}Santa\u{0020}Claus\u{0020}really\u{0020}fit\u{0020}through\u{0020}here?", "普段は大きく見える煙突も、上から見るとこんなに小さいなんてな。…サンタクロースって、本当にここから入れるのか？", "平常看着挺大的烟囱，从上面看下去好小啊。圣诞老人……真的会从这里钻进去吗？", "0", "0", "0", "cv_sk_jenny_6", "0", "0"},
[4100600109] = {4100600109, 11006001, 10, 5, "15_1_0_0.8", "level1", "Pinhole\u{0020}camera!\u{0020}Ready!\u{0020}Bug!\u{0020}Ready!\u{0020}I\u{0020}wonder\u{0020}if\u{0020}Navigator\u{0020}will\u{0020}like\u{0020}this…\u{0020}a\u{0020}Christmas\u{0020}present\u{0020}all\u{0020}wrapped\u{0020}up.", "隠しカメラ、準備ＯＫ～。盗聴器、準備ＯＫ～。ナビゲーターが好きなもの……うーん、気に入ってくれるかどうかわからねーけど……クリスマスプレゼント、準備ＯＫだ。", "针孔摄像头~准备ok，监听器~准备ok，领航喜欢的东西……也不知道领航喜不喜欢这个……圣诞礼物打包完毕。", "0", "0", "0", "cv_sk_jenny_7", "0", "0"},
[4100600110] = {4100600110, 11006001, 11, 5, "15_2_0_0.8", "level2", "Catch\u{0020}my\u{0020}Christmas\u{0020}present,\u{0020}and\u{0020}then\u{0020}spill\u{0020}all\u{0020}your\u{0020}secrets.\u{0020}\"Navigator's\u{0020}Christmas\u{0020}Eve\u{0020}Special\"…\u{0020}This\u{0020}report\u{0020}is\u{0020}definitely\u{0020}going\u{0020}to\u{0020}make\u{0020}the\u{0020}front\u{0020}page\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}Driver\u{0020}News!", "クリスマスプレゼントを受け取ったら、あんたのことを全部部聞かせてくれ。「ナビゲーターのクリスマスイブ特集」……これなら、アイギスドライバー新聞のトップ記事になること間違いなしだ！", "接住我的圣诞礼物，然后将你的一切都向我和盘托出吧。《领航的平安夜特辑》……这篇报道一定能上艾吉斯驾驶员报头条！", "0", "0", "0", "cv_sk_jenny_8", "0", "0"},
