[4100700131] = {4100700131, 11007001, 34, 26, "0", "0", "Welcome\u{0020}back,\u{0020}Navigator\u{0020}of\u{0020}Danube!\u{0020}I've\u{0020}already\u{0020}brewed\u{0020}some\u{0020}tea.", "0", "你回來了啊，多瑙的領航，姐姐已經把茶水泡好了喔。", "0", "0", "0", "cv_sk_ridelia_31", "0", "0"},
[4100700132] = {4100700132, 11007001, 35, 27, "0", "0", "Neither\u{0020}the\u{0020}blizzard\u{0020}nor\u{0020}the\u{0020}Haze\u{0020}can\u{0020}stop\u{0020}your\u{0020}forward\u{0020}march.", "0", "無論是暴風雪還是蒼霧，都無法阻擋您前進的步伐。", "0", "0", "0", "cv_sk_ridelia_33", "0", "0"},
[4100700133] = {4100700133, 11007001, 36, 28, "0", "0", "The\u{0020}worse\u{0020}the\u{0020}environment\u{0020}gets,\u{0020}the\u{0020}more\u{0020}it\u{0020}fuels\u{0020}my\u{0020}fighting\u{0020}spirit.", "0", "越是惡劣的環境，越是能激發我的戰鬥欲望。", "0", "0", "0", "cv_sk_ridelia_34", "0", "0"},
