[4100700135] = {4100700135, 11007001, 38, 30, "0", "0", "Hehehe,\u{0020}I\u{0020}wonder\u{0020}if\u{0020}I'll\u{0020}get\u{0020}to\u{0020}meet\u{0020}the\u{0020}children\u{0020}from\u{0020}Katya?", "0", "嘿嘿嘿，不知道能不能遇到卡佳的孩子呢？", "0", "0", "0", "cv_sk_ridelia_36", "0", "0"},
[4100700136] = {4100700136, 11007001, 39, 31, "0", "0", "I'll\u{0020}send\u{0020}you\u{0020}a\u{0020}batch\u{0020}of\u{0020}equipment\u{0020}from\u{0020}Katya\u{0020}next\u{0020}time.", "0", "下次送你一批卡佳的裝備吧。", "0", "0", "0", "cv_sk_ridelia_37", "0", "0"},
