[4100700142] = {4100700142, 11007001, 45, 37, "0", "0", "Let's\u{0020}click\u{0020}and\u{0020}take\u{0020}a\u{0020}look.", "0", "來點一下看看吧。", "0", "0", "0", "cv_sk_ridelia_43", "0", "0"},
[4100800100] = {4100800100, 11008001, 1, 1, "0", "0", "Haze\u{0020}reverb!", "蒼霧残響（ハツリバーブ）！", "蒼霧殘響！", "0", "苍雾残响！", "0", "cv_sk_aishirika_33", "0", "0"},
[4100800101] = {4100800101, 11008001, 2, 2, "0", "0", "Is\u{0020}this\u{0020}the\u{0020}new\u{0020}stage?\u{0020}Awesome!\u{0020}Let's\u{0020}play\u{0020}a\u{0020}song\u{0020}first\u{0020}and\u{0020}check\u{0020}it\u{0020}out.", "ここが新しい舞台なのね。じゃあ、一曲演奏してみようかしら。", "這就是新舞臺嗎，很好先來演奏一首看看吧。", "0", "这就是新舞台吗，很好先来演奏一首看看吧。", "0", "cv_sk_aishirika_2", "0", "0"},
[4100800102] = {4100800102, 11008001, 3, 3, "0", "0", "What\u{0020}brought\u{0020}us\u{0020}together?\u{0020}Was\u{0020}it\u{0020}an\u{0020}order?\u{0020}Or\u{0020}was\u{0020}it\u{0020}the\u{0020}music?\u{0020}Regardless,\u{0020}our\u{0020}fates\u{0020}are\u{0020}now\u{0020}intertwined\u{0020}from\u{0020}this\u{0020}moment\u{0020}on.", "私たちの出会ったきっかけは、命令？それとも音楽？どちらにしても、あなたと私の運命はもう繋がっているのよ。", "是什麼讓你我相遇呢？是命令？還是音樂？無論如何，從現在開始你我的命運已經連接在一起了。", "0", "是什么让你我相遇呢？是命令？还是音乐？无论如何，从现在开始你我的命运已经连接在一起了。", "0", "cv_sk_aishirika_1", "0", "0"},
[4100800103] = {4100800103, 11008001, 4, 4, "0", "idle", "Yahoooooooo!\u{0020}The\u{0020}sea\u{0020}breeze\u{0020}feels\u{0020}amazing,\u{0020}doesn't\u{0020}it,\u{0020}Navigator?", "Yahoooooooooooo！海風は気持ちいいわね！ナビゲーターも、そう思わない？", "Yahoooooooooooo——海邊的風真是太舒服了，領航，你不這麼覺得嗎？", "0", "无论是带领部队还是乐队，我都是超一流的。", "0", "cv_sk_aishirika_3", "0", "0"},
[4100800104] = {4100800104, 11008001, 5, 4, "0", "idle", "Come\u{0020}sit\u{0020}beside\u{0020}me.\u{0020}Oh,\u{0020}look!\u{0020}I've\u{0020}blocked\u{0020}the\u{0020}sun\u{0020}for\u{0020}us,\u{0020}so\u{0020}no\u{0020}need\u{0020}for\u{0020}a\u{0020}sun\u{0020}umbrella.", "ナビゲーターは、私の隣に座っていればいいのよ。ほら、私が日差しを遮れるから、日傘も必要ないでしょ。", "領航就坐在我的身邊吧，哦——你看，我剛好擋住了身邊的太陽，這樣就不用遮陽傘了。", "0", "真希望能有机会在这里办场音乐会啊。毕竟，这里可是汇聚了一批不得了的听众呢。", "0", "cv_sk_aishirika_4", "0", "0"},
[4100800105] = {4100800105, 11008001, 6, 4, "0", "idle", "My\u{0020}shoes\u{0020}are\u{0020}even\u{0020}bigger\u{0020}than\u{0020}yours!\u{0020}Want\u{0020}to\u{0020}try\u{0020}on\u{0020}my\u{0020}high\u{0020}heels\u{0020}for\u{0020}a\u{0020}bit?\u{0020}They're\u{0020}like\u{0020}a\u{0020}slide!\u{0020}Don't\u{0020}worry;\u{0020}I'll\u{0020}keep\u{0020}a\u{0020}close\u{0020}eye\u{0020}on\u{0020}you.", "私の靴、ナビゲーターより大きいわね。この滑り台みたいなハイヒールで遊んでみる？心配しないで、ちゃんと見守っててあげるから。", "我的鞋子都比現在的領航大了，你要在我的高跟鞋裡玩一會嗎？嗯，就像是滑滑梯一樣，放心我會小心地看著你。", "0", "瓦答娜和萨拉蒂，她们两个总是让我不放心。但是，我又担心自己对她们是不是太严厉了一点。该怎么办才好呢……", "0", "cv_sk_aishirika_30", "0", "0"},
[4100800106] = {4100800106, 11008001, 7, 5, "15_1_0_0.8", "touch1", "Don't\u{0020}be\u{0020}shy!\u{0020}Sit\u{0020}wherever\u{0020}you\u{0020}like.\u{0020}We've\u{0020}worked\u{0020}so\u{0020}hard—taking\u{0020}down\u{0020}the\u{0020}Sin\u{0020}and\u{0020}rebuilding\u{0020}the\u{0020}defenses.\u{0020}Isn't\u{0020}it\u{0020}all\u{0020}for\u{0020}days\u{0020}like\u{0020}this?\u{0020}Let's\u{0020}enjoy\u{0020}this\u{0020}moment\u{0020}of\u{0020}peace.", "恥ずかしがらないで、好きなところに座っていいのよ。原罪を討伐したり、防衛線を再建したり、今まで頑張ってきたのは、この日のためなんだから！さあ、このひと時の平和を、存分に楽しみましょう。", "來吧，不要害羞了。你想坐在哪就坐在哪。我們努力了這麼久——清剿原罪，重建防禦，不就是為了這一天嗎！就讓我們好好享受這短暫的安寧吧。", "0", "如果不成为驾驶员，不终结这场战争，大家都没办法静下心聆听我的音乐了。所以，我必须要战斗才行。不过，领航，你不觉得让原罪成为自己的听众，是件很有趣的事吗！", "0", "cv_sk_aishirika_31", "0", "0"},
[4100800107] = {4100800107, 11008001, 8, 5, "15_1_0_0.8", "touch1", "Humph,\u{0020}humph!\u{0020}Humph...\u{0020}Humph.", "ふんふんふん～ふんふん〜ふん〜♪", "哼哼哼~哼哼~哼~", "0", "舞蹈和音乐有着奇妙的力量，你也是这么觉得吧？", "0", "cv_sk_aishirika_5", "0", "0"},
[4100800108] = {4100800108, 11008001, 9, 5, "15_1_0_0.8", "touch1", "I've\u{0020}posed!\u{0020}Quick,\u{0020}record\u{0020}this\u{0020}moment!\u{0020}Navigator,\u{0020}join\u{0020}in\u{0020}too.\u{0020}One\u{0020}day,\u{0020}when\u{0020}we\u{0020}look\u{0020}back\u{0020}at\u{0020}these\u{0020}photos,\u{0020}we\u{0020}might\u{0020}feel\u{0020}something\u{0020}new.", "このポーズで撮ってちょうだい。ほら、ナビゲーターも一緒に。いつかこの写真を見返したとき、今とは違う気持ちが生まれるかもしれないわよ。", "我擺好姿勢了，快把這一幕記錄下來吧，領航也一起來吧，或許等哪天翻閱這些照片的時候還會有新的感情誕生呢。", "0", "我曾经有过这样的幻想。既然原罪能够受到我的音乐的影响，那么是不是意味着他们也能听懂我的演奏呢？既然这样的话……说不定我们之间还有交流的可能性。", "0", "cv_sk_aishirika_6", "0", "0"},
[4100800109] = {4100800109, 11008001, 10, 5, "15_2_0_0.8", "touch2", "Wow,\u{0020}this\u{0020}wind\u{0020}is\u{0020}so\u{0020}strong!\u{0020}It's\u{0020}really\u{0020}messing\u{0020}up\u{0020}my\u{0020}clothes.\u{0020}Are\u{0020}you\u{0020}okay,\u{0020}Navigator?", "あら、風のせいで服がめちゃくちゃだわ……ナビゲーターは大丈夫？", "哇啊——好大的風——真是的，把我的衣服都弄亂了。你沒事吧領航？", "0", "真是少见啊，你突然提出想要听我的弹奏吗？好吧，哪怕听众只有你一个人我也不会拒绝的。毕竟，你是我最好的朋友嘛。", "0", "cv_sk_aishirika_7", "0", "0"},
[4100800110] = {4100800110, 11008001, 11, 5, "15_2_0_0.8", "touch2", "Um...\u{0020}Today's\u{0020}wind\u{0020}is\u{0020}so\u{0020}loud,\u{0020}just\u{0020}like\u{0020}my\u{0020}mood.\u{0020}What\u{0020}mood,\u{0020}you\u{0020}ask?\u{0020}Humph!\u{0020}Let's\u{0020}sing\u{0020}together\u{0020}later...\u{0020}You'll\u{0020}surely\u{0020}understand.\u{0020}This\u{0020}feeling...\u{0020}It's\u{0020}such\u{0020}a\u{0020}luxury.", "んっ……今日は風が騒がしいわね。……まるで今の私の気持ちみたい。…どんな気持ちかって？ふふ、後で一緒に歌いましょう。きっと分かるわ。……とても贅沢な気持ちよ。", "唔……今天的風真是喧囂呢……就像我現在的心情一樣。是什麼樣的心情？哼哼，等一下我們一起唱歌吧……你一定會明白的……這份心情……真是奢侈的感情呢。", "0", "越是短暂的生命就越是要高声歌唱，这只是蝉的哲学罢了。无论生命长短，我们都有放声歌唱的权利。如果我能亲眼见证这场战争的胜利，那么我一定会将与你一同经历过故事写进歌中。", "0", "cv_sk_aishirika_8", "0", "0"},
[4100800111] = {4100800111, 11008001, 12, 6, "0", "0", "Thanks\u{0020}to\u{0020}you,\u{0020}I've\u{0020}found\u{0020}fresh\u{0020}inspiration!", "お陰で新しいインスピレーションを得たわ。", "托你的福，又有新的創作靈感了。", "0", "托你的福，又有新的创作灵感了。", "0", "cv_sk_aishirika_9", "0", "0"},
[4100800112] = {4100800112, 11008001, 13, 7, "0", "0", "The\u{0020}concert\u{0020}is\u{0020}about\u{0020}to\u{0020}begin,\u{0020}Navigator.\u{0020}Let's\u{0020}hit\u{0020}the\u{0020}stage\u{0020}together!", "コンサートの準備ができたみたいね。ナビゲーター、一緒に出ましょ！", "看來音樂會已經準備就緒了呢，領航，一起登場吧！", "0", "看来音乐会已经准备就绪了呢，领航，一起登场吧！", "0", "cv_sk_aishirika_10", "0", "0"},
[4100800113] = {4100800113, 11008001, 14, 8, "0", "0", "Ah...\u{0020}I'm\u{0020}so\u{0020}sorry!\u{0020}I\u{0020}get\u{0020}a\u{0020}little\u{0020}carried\u{0020}away\u{0020}in\u{0020}moments\u{0020}like\u{0020}this...\u{0020}Finally,\u{0020}we\u{0020}can\u{0020}play\u{0020}the\u{0020}melody\u{0020}that\u{0020}truly\u{0020}belongs\u{0020}to\u{0020}us.", "ああっ……ごめんなさい。こういう時いつも自分の感情をコントロールできなくて……やっと……やっと、私たちの真のメロディーを奏でることができるのね。", "啊……非常抱歉，每次到這種時候我都會控制不住自己……終於…終於可以奏出真正屬於我們的旋律了。", "0", "啊……非常抱歉，每次到这种时候我都会控制不住自己……终于…终于可以奏出真正属于我们的旋律了。", "0", "cv_sk_aishirika_11", "0", "0"},
[4100800114] = {4100800114, 11008001, 15, 9, "0", "0", "My\u{0020}music\u{0020}will\u{0020}tear\u{0020}our\u{0020}enemies\u{0020}apart!", "私の音楽で、敵を引き裂くわ。", "我的音樂，將會把敵人撕碎。", "0", "我的音乐，将会把敌人撕碎。", "0", "cv_sk_aishirika_12", "0", "0"},
[4100800115] = {4100800115, 11008001, 16, 10, "0", "0", "Everything\u{0020}is\u{0020}set!\u{0020}Let's\u{0020}perform\u{0020}to\u{0020}our\u{0020}hearts'\u{0020}content!", "準備ができたわ。思う存分演奏するわよ！", "一切都已經準備就緒，接下來就盡情演奏吧！", "0", "一切都已经准备就绪，接下来就尽情演奏吧！", "0", "cv_sk_aishirika_13", "0", "0"},
[4100800116] = {4100800116, 11008001, 17, 11, "0", "0", "Wow,\u{0020}time\u{0020}really\u{0020}flies!\u{0020}Has\u{0020}the\u{0020}curtain\u{0020}call\u{0020}come\u{0020}already?", "時間が経つのが早いわね。もうカーテンコールの時間なの？", "時間過得真快啊，不知不覺已經到了謝幕環節了嗎？", "0", "时间过得真快啊，不知不觉已经到了谢幕环节了吗？", "0", "cv_sk_aishirika_14", "0", "0"},
[4100800117] = {4100800117, 11008001, 18, 12, "0", "0", "The\u{0020}performance\u{0020}is\u{0020}over.\u{0020}Let's\u{0020}head\u{0020}back\u{0020}together.", "演奏が終わったわね。一緒に帰りましょ。", "演奏已經結束了，一起回去吧。", "0", "演奏已经结束了，一起回去吧。", "0", "cv_sk_aishirika_15", "0", "0"},
[4100800118] = {4100800118, 11008001, 19, 13, "0", "0", "Even\u{0020}if\u{0020}I\u{0020}scream\u{0020}until\u{0020}I'm\u{0020}hoarse,\u{0020}the\u{0020}Sin\u{0020}still\u{0020}can't\u{0020}understand\u{0020}my\u{0020}singing?", "声がかすれるまで歌っても、原罪に理解してもらうことはできないの？", "即便是把嗓子都喊啞了原罪都沒法聽懂我的歌聲嗎？", "0", "即便是把嗓子都喊哑了原罪都没法听懂我的歌声吗？", "0", "cv_sk_aishirika_16", "0", "0"},
[4100800119] = {4100800119, 11008001, 20, 14, "0", "0", "They\u{0020}interrupted\u{0020}us...\u{0020}I\u{0020}won't\u{0020}forgive\u{0020}them\u{0020}for\u{0020}that!", "中断された……絶対許さない……", "被打斷了啊……絕對不能原諒他們……", "0", "被打断了啊……绝对不能原谅他们……", "0", "cv_sk_aishirika_17", "0", "0"},
[4100800120] = {4100800120, 11008001, 21, 15, "0", "0", "Rage!", "盛り上がりなさい！", "躁動吧！", "0", "退场吧！", "0", "cv_sk_aishirika_18", "0", "0"},
[4100800121] = {4100800121, 11008001, 23, 16, "0", "0", "Follow\u{0020}my\u{0020}music!", "私のリズムについてきなさい！", "跟上我的音樂吧！", "0", "将我的愤怒传递过去吧！", "0", "cv_sk_aishirika_19", "0", "0"},
[4100800122] = {4100800122, 11008001, 24, 17, "0", "0", "One\u{0020}more\u{0020}song!", "もう一曲！", "再來一首！", "0", "终曲了！", "0", "cv_sk_aishirika_21", "0", "0"},
[4100800123] = {4100800123, 11008001, 25, 18, "0", "0", "Encore?\u{0020}Your\u{0020}voices\u{0020}are\u{0020}too\u{0020}soft!\u{0020}If\u{0020}you\u{0020}want\u{0020}me\u{0020}back\u{0020}on\u{0020}stage,\u{0020}ignite\u{0020}me\u{0020}with\u{0020}your\u{0020}passion!", "アンコール？声が小さすぎるわよ！さあ、その熱意で私を照らしてちょうだい！", "安可？声音太轻了！想让我返场的话，就用声音点燃我吧！", "0", "各位，演唱会要开始了哦。现在退票的话已经来不及了，你们就好好享受吧！", "0", "cv_sk_aishirika_22", "0", "0"},
[4100800124] = {4100800124, 11008001, 26, 19, "0", "0", "I...\u{0020}I\u{0020}still\u{0020}want\u{0020}to\u{0020}play\u{0020}with\u{0020}you,\u{0020}Navigator...", "ナビゲーターと一緒に……演奏したかった……", "我……還想和領航一起演奏……", "0", "只要我的歌声还回荡在战场上……", "0", "cv_sk_aishirika_20", "0", "0"},
[4100800125] = {4100800125, 11008001, 27, 20, "0", "0", "This\u{0020}is\u{0020}the\u{0020}perfect\u{0020}place\u{0020}to\u{0020}spark\u{0020}new\u{0020}inspirations\u{0020}while\u{0020}taking\u{0020}a\u{0020}bath.", "お風呂の時間はインスピレーションを得るのに最適ね。", "洗澡的時候確實非常適合整理靈感呢。", "0", "洗澡的时候确实非常适合整理灵感呢。", "0", "cv_sk_aishirika_23", "0", "0"},
[4100800126] = {4100800126, 11008001, 28, 21, "0", "0", "Navigator,\u{0020}do\u{0020}you\u{0020}mind\u{0020}if\u{0020}I\u{0020}sing\u{0020}here?", "ナビゲーター、ここで歌ってもいいかしら？", "領航，你不介意我在這邊唱歌吧。", "0", "领航，你不介意我在这边唱歌吧。", "0", "cv_sk_aishirika_24", "0", "0"},
[4100800127] = {4100800127, 11008001, 29, 21, "0", "0", "Bathing\u{0020}really\u{0020}unleashes\u{0020}a\u{0020}wave\u{0020}of\u{0020}creativity.", "お風呂に入るとインスピレーションを得やすいのよ。", "洗澡的時候可是靈感的爆發期喔。", "0", "洗澡的时候可是灵感的爆发期哦。", "0", "cv_sk_aishirika_25", "0", "0"},
[4100800128] = {4100800128, 11008001, 30, 22, "0", "0", "It's\u{0020}too\u{0020}bad\u{0020}I\u{0020}don't\u{0020}have\u{0020}a\u{0020}guitar\u{0020}with\u{0020}me.", "ギターがあればいいのに。", "可惜我的手邊沒有吉他啊。", "0", "可惜我的手边没有吉他啊。", "0", "cv_sk_aishirika_26", "0", "0"},
[4100800129] = {4100800129, 11008001, 31, 23, "0", "0", "My\u{0020}melody\u{0020}shouldn't\u{0020}be\u{0020}so\u{0020}easy\u{0020}to\u{0020}forget,\u{0020}right?", "私のメロディー、そう簡単には忘れられない…...でしょ？", "我的旋律，應該不會那麼容易就忘記了吧。", "0", "我的旋律，应该不会那么容易就忘记了吧。", "0", "cv_sk_aishirika_27", "0", "0"},
[4100800130] = {4100800130, 11008001, 32, 24, "0", "0", "It's\u{0020}an\u{0020}honor\u{0020}to\u{0020}have\u{0020}such\u{0020}an\u{0020}audience\u{0020}like\u{0020}you.", "あなたのようなリスナーがいてくれて光栄だわ。", "能有像你一樣的聽眾，是我的榮幸。", "0", "能有像你一样的听众，是我的荣幸。", "0", "cv_sk_aishirika_28", "0", "0"},
[4100800131] = {4100800131, 11008001, 33, 25, "0", "0", "Alas,\u{0020}my\u{0020}music\u{0020}still\u{0020}isn't\u{0020}moving\u{0020}enough?", "私の音楽じゃ人の心を動かせなかったのかしら……？", "果然，我的音樂還不夠深入人心嗎？", "0", "果然，我的音乐还不够深入人心吗？", "0", "cv_sk_aishirika_29", "0", "0"},
[4100800132] = {4100800132, 11008001, 34, 26, "0", "0", "Not\u{0020}ready\u{0020}yet?\u{0020}Hurry\u{0020}up\u{0020}and\u{0020}change\u{0020}your\u{0020}clothes.", "まだ準備できていないの？早く着替えてきて。", "還沒準備好？趕緊換衣服去。", "0", "嗯？领航！你来的正好，我正在准备今晚的演出呢！", "0", "cv_sk_aishirika_32", "0", "0"},
[4100800133] = {4100800133, 11008001, 35, 27, "0", "0", "Let's\u{0020}go,\u{0020}Navigator!\u{0020}Let\u{0020}our\u{0020}story\u{0020}resonate\u{0020}through\u{0020}every\u{0020}corner\u{0020}of\u{0020}the\u{0020}world\u{0020}with\u{0020}music.", "出発しよ、ナビゲーター。私とあなたの物語を音楽で世界の隅々まで伝えましょ。", "出發吧，領航，讓我與你的故事通過音樂傳達至世界的每個角落。", "0", "出发吧，领航，让我与你的故事通过音乐传达至世界的每个角落。", "0", "cv_sk_aishirika_34", "0", "0"},
[4100800134] = {4100800134, 11008001, 36, 28, "0", "0", "If\u{0020}you\u{0020}slack\u{0020}off,\u{0020}you'll\u{0020}grow\u{0020}weaker.", "気を緩めたら弱くなるわ。", "懈怠了就會變弱。", "0", "懈怠了就会变弱。", "0", "cv_sk_aishirika_35", "0", "0"},
[4100800135] = {4100800135, 11008001, 37, 29, "0", "0", "Everyone\u{0020}in\u{0020}the\u{0020}troop\u{0020}is\u{0020}here.", "部隊の皆がここにいるのね。", "部隊裡的大家都在這了呢。", "0", "部队里的大家都在这了呢。", "0", "cv_sk_aishirika_36", "0", "0"},
[4100800136] = {4100800136, 11008001, 38, 30, "0", "0", "Are\u{0020}there\u{0020}any\u{0020}new\u{0020}audience\u{0020}members?", "新しいリスナーが来るのかしら？", "有新的聽眾了嗎！", "0", "有新的听众了吗！", "0", "cv_sk_aishirika_37", "0", "0"},
[4100800137] = {4100800137, 11008001, 39, 31, "0", "0", "I\u{0020}want\u{0020}a\u{0020}guitar!", "ギターが欲しいわね", "想要把吉他呢~", "0", "想要把吉他呢~", "0", "cv_sk_aishirika_38", "0", "0"},
[4100800138] = {4100800138, 11008001, 40, 32, "0", "0", "Do\u{0020}we\u{0020}need\u{0020}to\u{0020}restock\u{0020}supplies?", "物資を補充するのかしら？", "需要補充物資嗎？", "0", "需要补充物资吗？", "0", "cv_sk_aishirika_39", "0", "0"},
[4100800139] = {4100800139, 11008001, 41, 33, "0", "0", "Don't\u{0020}forget\u{0020}to\u{0020}check\u{0020}on\u{0020}yourself.", "自分の状況の確認を忘れないようにね。", "別忘了確認自己的狀況。", "0", "别忘了确认自己的状况。", "0", "cv_sk_aishirika_40", "0", "0"},
[4100800140] = {4100800140, 11008001, 42, 34, "0", "0", "Is\u{0020}there\u{0020}a\u{0020}need\u{0020}for\u{0020}any\u{0020}detailed\u{0020}adjustments?", "細かな調整を行うのかしら？", "是要進行細節上的調整嗎？", "0", "是要进行细节上的调整吗？", "0", "cv_sk_aishirika_41", "0", "0"},
[4100800141] = {4100800141, 11008001, 43, 35, "0", "0", "Make\u{0020}sure\u{0020}to\u{0020}check\u{0020}the\u{0020}letters\u{0020}in\u{0020}time.", "こまめにメールをチェックするようにね。", "要及時查看信件。", "0", "要及时查看邮件。", "0", "cv_sk_aishirika_42", "0", "0"},
[4100800142] = {4100800142, 11008001, 44, 36, "0", "0", "If\u{0020}I\u{0020}sing\u{0020}here...", "ここで歌うのなら……", "如果在這裡演唱的話……", "0", "如果在这里演唱的话……", "0", "cv_sk_aishirika_43", "0", "0"},
[4100800143] = {4100800143, 11008001, 45, 37, "0", "0", "There\u{0020}are\u{0020}still\u{0020}things\u{0020}we\u{0020}need\u{0020}to\u{0020}confirm.", "他にも確認しないといけないことがあるわよ。", "還有需要確認的事。", "0", "还有需要确认的事。", "0", "cv_sk_aishirika_44", "0", "0"},
[4101400100] = {4101400100, 11014001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響。", "0", "苍雾残响。", "0", "cv_sk_sikadi_31", "0", "0"},
[4101400101] = {4101400101, 11014001, 2, 2, "0", "0", "Humph,\u{0020}it's\u{0020}only\u{0020}natural\u{0020}for\u{0020}you\u{0020}to\u{0020}choose\u{0020}me.\u{0020}After\u{0020}all,\u{0020}there's\u{0020}an\u{0020}invisible\u{0020}red\u{0020}thread\u{0020}of\u{0020}fate\u{0020}connecting\u{0020}us...\u{0020}Hey,\u{0020}don't\u{0020}go!\u{0020}I\u{0020}haven't\u{0020}finished\u{0020}yet!", "フン、汝が妾を選ぶのは当然だ。汝と妾は、運命の赤い糸で結ばれておるのだからなぁ……ってこら！行くな、まだ話の途中だぁ！", "哼，你會選擇吾是理所當然的，畢竟吾與汝之間可是存在著不可視的命運紅線在連接著…喂，別走啊，我還沒說完呢！", "0", "哼，你会选择吾是理所当然的，毕竟吾与汝之间可是存在着不可视的命运红线在连接着…喂，别走啊，我还没说完呢！", "0", "cv_sk_sikadi_2", "0", "0"},
[4101400102] = {4101400102, 11014001, 3, 3, "0", "0", "Finally,\u{0020}I\u{0020}found\u{0020}you.\u{0020}Is\u{0020}this\u{0020}our\u{0020}destiny?\u{0020}I...\u{0020}My\u{0020}name\u{0020}is\u{0020}Skadi,\u{0020}the\u{0020}queen\u{0020}ruling\u{0020}Dunescaith.\u{0020}Should\u{0020}it\u{0020}be\u{0020}called\u{0020}Dunescaith?\u{0020}Never\u{0020}mind\u{0020}that!", "ようやく見つけたぞ。まさにこれが運命。あた…妾の名はスカディ、影の国を統べる女王なり！……え？冬の女神のほうが正しい？……細かいことを気にするなぁ！", "終於，找到你了，這就是我與你的宿命嗎？我…吾的名字是斯卡蒂，統治著暗之國的女王…“應該是影之國吧？”…不要在意那麼多啦！", "0", "终于，找到你了，这就是我与你的宿命吗？我…吾的名字是斯卡蒂，统治着暗之国的女王…“应该是影之国吧？”…不要在意那么多啦！", "0", "cv_sk_sikadi_1", "0", "0"},
[4101400103] = {4101400103, 11014001, 4, 4, "0", "idle", "Humph,\u{0020}I\u{0020}dreamed\u{0020}of\u{0020}the\u{0020}incredible\u{0020}possibilities\u{0020}that\u{0020}await\u{0020}me.\u{0020}After\u{0020}breaking\u{0020}the\u{0020}curse,\u{0020}I\u{0020}won't\u{0020}stop\u{0020}here,\u{0020}will\u{0020}I?", "ふふん。妾は夢で予見したのじゃ。未来の妾が驚異的な可能性を持つことを！呪いを破ったスカディは、ここで立ち止まることはない！", "哼，吾在夢中預見到了，未來的吾所擁有的驚人可能性。破除詛咒後的斯卡蒂可不會止步於此哦？", "0", "哈——哈——哈，领航，吾能感觉到汝在想什么…“通感”？不是啦，这是魔法，魔法！", "0", "cv_sk_sikadi_3", "0", "0"},
[4101400104] = {4101400104, 11014001, 5, 4, "0", "idle", "When\u{0020}the\u{0020}Navigator\u{0020}isn't\u{0020}around,\u{0020}can't\u{0020}I\u{0020}take\u{0020}his\u{0020}place?\u{0020}Surely,\u{0020}only\u{0020}the\u{0020}middle\u{0020}position\u{0020}can\u{0020}highlight\u{0020}my\u{0020}greatness…\u{0020}Nav...\u{0020}Navigator...\u{0020}When\u{0020}did\u{0020}you\u{0020}arrive?", "ナビゲーターがおらぬのなら、その席をいただこう……やはり、最も中央の席こそ偉大なる妾に相応しい。……ナ、ナビゲーター……いつからいたの？", "領航不在的時候，吾不就能霸佔他的位置了嗎……果然，只有最中間的位置才能凸顯吾的偉大。……領、領航……什麼時候在的？", "0", "看到了吗，领航，吾的眼睛正在闪闪发光，这是与汝产生共鸣的征兆！", "0", "cv_sk_sikadi_4", "0", "0"},
[4101400105] = {4101400105, 11014001, 6, 4, "0", "idle", "The\u{0020}companions\u{0020}from\u{0020}the\u{0020}orphanage?\u{0020}I\u{0020}did\u{0020}ask\u{0020}the\u{0020}Intelligence\u{0020}Department\u{0020}to\u{0020}keep\u{0020}an\u{0020}eye\u{0020}on\u{0020}them.\u{0020}Why\u{0020}do\u{0020}you\u{0020}bring\u{0020}them\u{0020}up?\u{0020}What's\u{0020}wrong?\u{0020}Are\u{0020}you\u{0020}concerned\u{0020}about\u{0020}my\u{0020}past?\u{0020}HaHaHa,\u{0020}Navigator,\u{0020}you've\u{0020}finally\u{0020}reached\u{0020}for\u{0020}the\u{0020}untouchable...\u{0020}Alright,\u{0020}I'll\u{0020}tell\u{0020}you\u{0020}everything...", "孤児院に居た時の仲間か？情報部に頼んで見守るようしているが、どうしたのじゃ？さては……妾の過去が気になると見える。ははは！ナビゲーターよ……とうとう探ってはならぬことに手を……分かった。教える。教えるから……", "以前孤兒院的夥伴麼？吾是有拜託情報部的人一直關注他們的啦……你提他們做什麼……怎麼了，對吾的過去如此在意嗎？哈~哈~哈，領航，終於將手伸向那不可被觸及的……好，告訴你，吾全告訴你……", "0", "嘘——领航，不要告诉莉莉丝我在这里…真是的，只是一个蛋糕而已，有什么关系嘛……", "0", "cv_sk_sikadi_28", "0", "0"},
[4101400106] = {4101400106, 11014001, 7, 5, "1_》_0_0.8", "level1", "I\u{0020}tried\u{0020}on\u{0020}these\u{0020}clothes...\u{0020}How\u{0020}do\u{0020}they\u{0020}look?\u{0020}What\u{0020}do\u{0020}you\u{0020}think?", "これ、試しに着てみたんじゃが……ど、どうじゃ？", "我試著穿了這樣的衣服……感覺、感覺怎麼樣？", "0", "中二病？不是！吾才不是中二病！听好了，吾是因为被世界选择，被人们需要，所以才会成为影之国的女王，出现在这里的！才不是普通的“中二病”！", "0", "cv_sk_sikadi_29", "0", "0"},
[4101400107] = {4101400107, 11014001, 8, 5, "1_》_0_0.8", "level1", "Ah!\u{0020}While\u{0020}I\u{0020}allowed\u{0020}you\u{0020}to\u{0020}get\u{0020}close,\u{0020}it's\u{0020}not\u{0020}nice\u{0020}to\u{0020}scare\u{0020}me\u{0020}like\u{0020}that!", "ぎゃー！わ、妾に近づくことは許したが、お、驚かせてるでない！", "呀——！雖、雖然吾特許你能親近吾，但、但是嚇到我可不好哦。", "0", "想靠近吾的话，倒也无妨，不过要小心被阴影吞噬噢，领航。", "0", "cv_sk_sikadi_5", "0", "0"},
[4101400108] = {4101400108, 11014001, 9, 5, "1_》_0_0.8", "level2", "Um...\u{0020}It's\u{0020}a\u{0020}bit\u{0020}chilly\u{0020}down\u{0020}here.\u{0020}Wouldn't\u{0020}it\u{0020}be\u{0020}better\u{0020}to\u{0020}lengthen\u{0020}the\u{0020}skirt?\u{0020}What\u{0020}do\u{0020}you\u{0020}think,\u{0020}Navigator?", "うーむ……下がスースーするな。スカートを長くしてはどうじゃろうか……ナビゲーターはどう思う？", "嗯……下面涼颼颼的，是不是加長一下裙子比較好……領航覺得呢？", "0", "啊，是领航啊。正好，帮吾去买一份补充黑暗力量的魔力剂吧…就是那个…碳酸饮料啦。", "0", "cv_sk_sikadi_6", "0", "0"},
[4101400109] = {4101400109, 11014001, 10, 5, "1_》_0_0.8", "level3", "Rejoice!\u{0020}In\u{0020}this\u{0020}eternal\u{0020}polar\u{0020}night,\u{0020}the\u{0020}king\u{0020}of\u{0020}the\u{0020}Shadow\u{0020}Kingdom\u{0020}is\u{0020}ready\u{0020}to\u{0020}stand\u{0020}by\u{0020}your\u{0020}side.", "祝うがよい。古の極夜、影の国の王が汝の声に応じ、ここに君臨したのじゃ。", "慶賀吧，在亙古的極夜中，影之國的王答應了你，來到了你身旁。", "0", "不，不要老是摸吾啦，别把吾当成那些爱撒娇的孩子！吾可是最强的影之国女王！咳咳…不过，你真这么喜欢吾的话，吾也不会在意的。", "0", "cv_sk_sikadi_7", "0", "0"},
[4101400110] = {4101400110, 11014001, 11, 5, "1_》_0_0.8", "level4", "Have\u{0020}you\u{0020}heard\u{0020}of\u{0020}\"YeHai\u{0020}Pearl\"?\u{0020}It's\u{0020}not\u{0020}jewelry;\u{0020}it's\u{0020}a\u{0020}super\u{0020}rare\u{0020}kind\u{0020}of\u{0020}caviar.\u{0020}If\u{0020}we\u{0020}get\u{0020}the\u{0020}chance,\u{0020}let's\u{0020}try\u{0020}it\u{0020}together!", "ナビゲーターは「アリスト海の真珠」って聞いたことはあるか？宝石のことじゃないぞ。とっても珍しいキャビアの名前なんじゃ。今度一緒に食べてみようではないか。", "領航聽過“葉海珍珠”嗎？不是珠寶哦？那是一種超稀有的魚子醬的稱呼哦，如果有機會的話，我們一起嘗嘗看吧。", "0", "被阴影与死亡吸引而堕落的人啊，和影之国的女王结下恋…领航！？汝什么时候在这的？", "0", "cv_sk_sikadi_8", "0", "0"},
[4101400111] = {4101400111, 11014001, 12, 6, "0", "0", "Oh,\u{0020}I\u{0020}can\u{0020}feel\u{0020}my\u{0020}power\u{0020}rising!", "おおお、感じるぞ！妾の力が漲っておる！", "喔喔喔，吾感受到了，力量正在提升！", "0", "噢噢噢，吾感受到了，力量正在提升！", "0", "cv_sk_sikadi_9", "0", "0"},
[4101400112] = {4101400112, 11014001, 13, 7, "0", "0", "Oh?\u{0020}You\u{0020}want\u{0020}to\u{0020}witness\u{0020}my\u{0020}strength\u{0020}at\u{0020}its\u{0020}peak?", "なんだ？全盛期の妾の力を、その目に焼き付けたいのだな？", "喔？想要見識下嗎，吾巔峰時期的實力。", "0", "噢？想要见识下吗，吾巅峰时期的实力。", "0", "cv_sk_sikadi_10", "0", "0"},
[4101400113] = {4101400113, 11014001, 14, 8, "0", "0", "Yes,\u{0020}I'm\u{0020}in\u{0020}my\u{0020}complete\u{0020}form\u{0020}now!\u{0020}Even\u{0020}legendary\u{0020}gods,\u{0020}monsters,\u{0020}or\u{0020}beasts\u{0020}won't\u{0020}stand\u{0020}a\u{0020}chance\u{0020}against\u{0020}me.\u{0020}After\u{0020}all,\u{0020}I'm\u{0020}the\u{0020}queen\u{0020}of\u{0020}the\u{0020}Dunescaith!", "うむ、今の妾はもはや完全体！例え伝説の神霊、魔物、怪獣が現れようとも相手ではない。なにせ影の国の女王は、最強じゃからなぁ！", "嗯嗯，現在的吾，已經是完全體了！就算是傳說中的神靈、魔物，怪獸出現在吾的面前，也不會是吾的對手。畢竟，影之國的女王是最強的！", "0", "嗯嗯，现在的吾，已经是完全体了！就算是传说中的神灵、魔物，怪兽出现在吾的面前，也不会是吾的对手。毕竟，影之国的女王是最强的！", "0", "cv_sk_sikadi_11", "0", "0"},
[4101400114] = {4101400114, 11014001, 15, 9, "0", "0", "I\u{0020}can't\u{0020}wait\u{0020}to\u{0020}unleash\u{0020}this\u{0020}power!", "早くこの力を試させよ！妾はもう待てぬぞ！", "吾已經迫不及待想展示這份力量了！", "0", "吾已经迫不及待想展示这份力量了！", "0", "cv_sk_sikadi_12", "0", "0"},
[4101400115] = {4101400115, 11014001, 16, 10, "0", "0", "The\u{0020}shadow\u{0020}descends,\u{0020}the\u{0020}power\u{0020}of\u{0020}the\u{0020}dead!", "影の降臨、亡者の力！", "陰影降臨，亡者的力量！", "0", "阴影降临，亡者的力量！", "0", "cv_sk_sikadi_13", "0", "0"},
[4101400116] = {4101400116, 11014001, 17, 11, "0", "0", "A\u{0020}perfect\u{0020}victory!\u{0020}Ha-ha-ha!\u{0020}Did\u{0020}you\u{0020}witness\u{0020}the\u{0020}power\u{0020}of\u{0020}the\u{0020}gods?", "完全勝利！はっはっはー！見たか、これぞ神霊の力よ！", "完美的勝利，哈——哈——哈，見識到了嗎，神靈的力量！", "0", "完美的胜利，哈——哈——哈，见识到了吗，神灵的力量！", "0", "cv_sk_sikadi_14", "0", "0"},
[4101400117] = {4101400117, 11014001, 18, 12, "0", "0", "Huh...\u{0020}It\u{0020}seems\u{0020}I\u{0020}still\u{0020}have\u{0020}a\u{0020}bit\u{0020}of\u{0020}trouble\u{0020}controlling\u{0020}my\u{0020}power.", "うぅむ……どうやらまだ、力の制御が足りぬようじゃな。", "呼…看來，吾對自己力量的控制還有些不足啊。", "0", "呼…看来，吾对自己力量的控制还有些不足啊。", "0", "cv_sk_sikadi_15", "0", "0"},
[4101400118] = {4101400118, 11014001, 19, 13, "0", "0", "Woo...\u{0020}I\u{0020}messed\u{0020}up.\u{0020}This\u{0020}doesn't\u{0020}count!\u{0020}It\u{0020}doesn't\u{0020}count!", "う…ミスった。今回はなし、なしー！", "嗚…失誤了，這次不算，這次不算！", "0", "呜…失误了，这次不算，这次不算！", "0", "cv_sk_sikadi_16", "0", "0"},
[4101400119] = {4101400119, 11014001, 20, 14, "0", "0", "Did\u{0020}we\u{0020}fail?...\u{0020}Retreat!\u{0020}I'll\u{0020}cover\u{0020}you.", "し、失敗か……撤退だ。あたしが援護する。", "失、失敗了嗎…撤退，我來掩護。", "0", "失、失败了吗…撤退，我来掩护。", "0", "cv_sk_sikadi_17", "0", "0"},
[4101400120] = {4101400120, 11014001, 21, 15, "0", "0", "Come\u{0020}on,\u{0020}become\u{0020}my\u{0020}strength!", "来い。妾の力になれ！", "來吧，成為我的力量！", "0", "被阴影吞噬吧！", "0", "cv_sk_sikadi_18", "0", "0"},
[4101400121] = {4101400121, 11014001, 23, 16, "0", "0", "The\u{0020}final\u{0020}strike!", "とどめだぁー！", "最後一擊了！", "0", "斯卡蒂式迅猛剑X！", "0", "cv_sk_sikadi_19", "0", "0"},
[4101400122] = {4101400122, 11014001, 26, 19, "0", "0", "...\u{0020}I\u{0020}never\u{0020}expected\u{0020}I,\u{0020}the\u{0020}queen\u{0020}of\u{0020}the\u{0020}Shadow\u{0020}Kingdom,\u{0020}would\u{0020}face\u{0020}defeat\u{0020}here.", "……よもや影の国の女王たる妾が恨みをのむことしかできぬとは。", "……沒想到影之國的女王要在這裡恨飲。", "0", "吾的时间…到了……", "0", "cv_sk_sikadi_20", "0", "0"},
[4101400123] = {4101400123, 11014001, 27, 20, "0", "0", "So,\u{0020}what\u{0020}do\u{0020}you\u{0020}think?\u{0020}Are\u{0020}you\u{0020}captivated\u{0020}by\u{0020}my\u{0020}beautiful\u{0020}form?", "なんじゃ。妾の美しい体の虜になったのか？", "如何，被吾美麗的身體吸引了嗎？", "0", "如何，被吾美丽的身体吸引了吗？", "0", "cv_sk_sikadi_21", "0", "0"},
[4101400124] = {4101400124, 11014001, 28, 21, "0", "0", "I\u{0020}don't\u{0020}mind,\u{0020}but\u{0020}are\u{0020}you\u{0020}really\u{0020}planning\u{0020}to\u{0020}just\u{0020}keep\u{0020}staring\u{0020}like\u{0020}that...?", "べ、別に構わぬのじゃが……そのままずっと見ているつもり……なのか？", "吾雖然不介意，可汝真打算這樣一直盯著嗎……", "0", "吾虽然不介意，可汝真打算这样一直盯着吗……", "0", "cv_sk_sikadi_22", "0", "0"},
[4101400125] = {4101400125, 11014001, 29, 21, "0", "0", "Taking\u{0020}a\u{0020}bath\u{0020}feels\u{0020}so\u{0020}nice...\u{0020}It\u{0020}brings\u{0020}back\u{0020}memories\u{0020}from\u{0020}my\u{0020}childhood.", "風呂は気持ちがいいのう……あた…妾の幼き頃を思い出すぞ。", "泡澡真舒服啊…讓我…吾想起小時候的事了。", "0", "泡澡真舒服啊…让我…吾想起小时候的事了。", "0", "cv_sk_sikadi_23", "0", "0"},
[4101400126] = {4101400126, 11014001, 30, 22, "0", "0", "Could\u{0020}it\u{0020}be\u{0020}that\u{0020}those\u{0020}Underworld\u{0020}creatures\u{0020}are\u{0020}chasing\u{0020}us...?", "まさか、冥界の奴らが……", "難道說，是冥界的那些傢伙追來了嗎……", "0", "难道说，是冥界的那些家伙追来了吗……", "0", "cv_sk_sikadi_24", "0", "0"},
[4101400127] = {4101400127, 11014001, 31, 23, "0", "0", "Navigator,\u{0020}the\u{0020}shadows\u{0020}connect\u{0020}us...\u{0020}I\u{0020}can't\u{0020}be\u{0020}wrong...\u{0020}right?", "ナビゲーター。影が我らを結んでおるのじゃ。……間違いはせぬ…よな？", "領航，陰影將我們連接在一起…不會猜錯…吧？", "0", "领航，阴影将我们连接在一起…不会猜错…吧？", "0", "cv_sk_sikadi_25", "0", "0"},
[4101400128] = {4101400128, 11014001, 32, 24, "0", "0", "Very\u{0020}good!\u{0020}I\u{0020}might\u{0020}even\u{0020}want\u{0020}to\u{0020}make\u{0020}you\u{0020}a\u{0020}citizen\u{0020}of\u{0020}the\u{0020}Shadow\u{0020}Kingdom!", "でかした！褒美に影の国の住民として迎え入れてやろうぞ！", "很好，吾都想將汝收為影之國的國民了！", "0", "很好，吾都想将汝收为影之国的国民了！", "0", "cv_sk_sikadi_26", "0", "0"},
[4101400129] = {4101400129, 11014001, 33, 25, "0", "0", "The\u{0020}pitch-black\u{0020}power\u{0020}hidden\u{0020}in\u{0020}the\u{0020}shadows\u{0020}will\u{0020}burn\u{0020}the\u{0020}one\u{0020}before\u{0020}me\u{0020}to\u{0020}ashes!", "影に隠れし漆黒の力よ……目の前のこやつを灰にせよぉ！", "隱藏在影子中的漆黑力量啊，將吾眼前的人燒成灰燼吧！", "0", "隐藏在影子中的漆黑力量啊，将吾眼前的人烧成灰烬吧！", "0", "cv_sk_sikadi_27", "0", "0"},
[4101400130] = {4101400130, 11014001, 34, 26, "0", "0", "Our\u{0020}encounter,\u{0020}Navigator,\u{0020}is\u{0020}both\u{0020}inevitable\u{0020}and\u{0020}predestined.", "汝と妾の出会いは、逃れられない運命なのじゃ。", "領航與吾的相遇，是必然的，是早已被定好的命運。", "0", "领航，汝来了啊。就像汝看见的那样，吾正在练习新的必杀技——“漆黑的迅疾影刃”……喂，不许笑啦！", "0", "cv_sk_sikadi_30", "0", "0"},
[4101400131] = {4101400131, 11014001, 35, 27, "0", "0", "My\u{0020}magic\u{0020}eye\u{0020}is\u{0020}heating\u{0020}up.\u{0020}Is\u{0020}\"Fate\"\u{0020}drawing\u{0020}near?", "我が魔眼が熱く疼いておる。……来るか。……運命が。", "吾的魔眼正在發熱，要來了嗎，“命運”……", "0", "吾的魔眼正在发热，要来了吗，“命运”……", "0", "cv_sk_sikadi_32", "0", "0"},
[4101400132] = {4101400132, 11014001, 36, 28, "0", "0", "Just\u{0020}right!\u{0020}You\u{0020}will\u{0020}witness\u{0020}the\u{0020}queen's\u{0020}power.", "丁度よい。女王たる力、汝に見せようぞ。", "正好，讓汝見識一下女王的力量。", "0", "正好，让汝见识一下女王的力量。", "0", "cv_sk_sikadi_33", "0", "0"},
[4101400133] = {4101400133, 11014001, 37, 29, "0", "0", "Compared\u{0020}to\u{0020}me,\u{0020}everyone\u{0020}else\u{0020}pales\u{0020}in\u{0020}comparison.", "妾に比べれば、とるに足らぬものばかりよの。", "跟吾比起來，其他人還是差了一截呀。", "0", "跟吾比起来，其他人还是差了一截呀。", "0", "cv_sk_sikadi_34", "0", "0"},
