[4102200101] = {4102200101, 11022001, 2, 2, "0", "0", "Pfft...\u{0020}From\u{0020}this\u{0020}angle,\u{0020}Navigator\u{0020}looks\u{0020}like\u{0020}a\u{0020}little\u{0020}bug!\u{0020}So\u{0020}adorable.", "おっかし～。こっから見るとナビくん、蟲みたいで可愛いじゃん。", "0", "0", "0", "0", "cv_sk_wangnv_2", "0", "0"},
[4102200102] = {4102200102, 11022001, 3, 3, "0", "0", "Oh\u{0020}hey.\u{0020}Long\u{0020}time\u{0020}no\u{0020}see.\u{0020}I'm\u{0020}Her\u{0020}Majesty.\u{0020}What?\u{0020}Why\u{0020}am\u{0020}I\u{0020}here?\u{0020}Don't\u{0020}sweat\u{0020}the\u{0020}small\u{0020}details!", "おっひさー、王女だよー。え……？　なんでここにいるのかって？　細かいことはどうでもいいじゃん！", "0", "0", "0", "0", "cv_sk_wangnv_3", "0", "0"},
[4102200103] = {4102200103, 11022001, 4, 4, "0", "idle", "Ahhh.\u{0020}Nothing\u{0020}says\u{0020}summer\u{0020}like\u{0020}wearing\u{0020}a\u{0020}swimsuit...\u{0020}I\u{0020}guess\u{0020}my\u{0020}hidden\u{0020}assets\u{0020}were\u{0020}bound\u{0020}to\u{0020}be\u{0020}revealed\u{0020}eventually!", "はぁ～夏といえばやっぱり水著だよね……あーしが巨乳なのを隠してきたけど、ついにみんなにバレちゃうー！", "0", "0", "0", "0", "cv_sk_wangnv_4", "0", "0"},
[4102200104] = {4102200104, 11022001, 5, 4, "0", "idle", "The\u{0020}President\u{0020}said\u{0020}she\u{0020}had\u{0020}business\u{0020}today?\u{0020}That's\u{0020}just\u{0020}an\u{0020}excuse...\u{0020}She's\u{0020}actually\u{0020}super\u{0020}shy...\u{0020}Probably\u{0020}just\u{0020}doesn't\u{0020}know\u{0020}how\u{0020}to\u{0020}face\u{0020}you\u{0020}like\u{0020}this...", "會長は用事で來れないって？　ウソウソ。むっつりだから、どんな顔してナビくんと會えばいいのか分からないだけじゃん？", "0", "0", "0", "0", "cv_sk_wangnv_5", "0", "0"},
[4102200105] = {4102200105, 11022001, 6, 4, "0", "idle", "Hey\u{0020}Navigator,\u{0020}do\u{0020}those\u{0020}other\u{0020}Drivers\u{0020}who\u{0020}like\u{0020}you\u{0020}know\u{0020}you're\u{0020}out\u{0020}alone\u{0020}with\u{0020}me\u{0020}today?...\u{0020}Hahaha,\u{0020}that\u{0020}sounded\u{0020}so\u{0020}villainous!\u{0020}Forget\u{0020}I\u{0020}said\u{0020}that...\u{0020}I\u{0020}sound\u{0020}like\u{0020}such\u{0020}a\u{0020}bad\u{0020}girl,\u{0020}how\u{0020}funny!", "ナビくん。あーしと二人きりで會ってるって、他のドライバーの子は知ってるの？　……はは、あーし何言ってんだろ。忘れてくれていいよ……なんかあーしが悪役みたいじゃん。ヤバ。", "0", "0", "0", "0", "cv_sk_wangnv_6", "0", "0"},
[4102200106] = {4102200106, 11022001, 7, 5, "15_2_0_0.8", "level2", "Navigator,\u{0020}why\u{0020}are\u{0020}you\u{0020}looking\u{0020}away?\u{0020}No\u{0020}way...\u{0020}Are\u{0020}you\u{0020}embarrassed?\u{0020}Don't\u{0020}worry.\u{0020}Embrace\u{0020}your\u{0020}desires!\u{0020}Just\u{0020}open\u{0020}your\u{0020}eyes\u{0020}wide\u{0020}and\u{0020}take\u{0020}a\u{0020}good\u{0020}look!", "……ナビくん、なんで目を逸らしちゃうのかなー？……恥ずかしがることないっしょ！へーきへーき！　自分に正直になってさ。見たいなら堂々と見ればいーじゃん！", "0", "0", "0", "0", "cv_sk_wangnv_7", "0", "0"},
[4102200107] = {4102200107, 11022001, 8, 5, "15_2_0_0.8", "level2", "Let's\u{0020}do\u{0020}something\u{0020}you\u{0020}can\u{0020}only\u{0020}do\u{0020}when\u{0020}wearing\u{0020}swimsuits.", "水著を著てる時しかできないこと、しない？", "0", "0", "0", "0", "cv_sk_wangnv_8", "0", "0"},
[4102200108] = {4102200108, 11022001, 9, 5, "15_1_0_0.8", "level1", "It's\u{0020}time\u{0020}to\u{0020}prepare\u{0020}for\u{0020}battle.\u{0020}This\u{0020}summer,\u{0020}I'm\u{0020}going\u{0020}to\u{0020}dominate\u{0020}the\u{0020}hunting\u{0020}grounds...\u{0020}Join\u{0020}my\u{0020}team,\u{0020}Navigator.\u{0020}I'll\u{0020}give\u{0020}you\u{0020}special\u{0020}member\u{0020}privileges.", "もはや戦いは避けられないね。この夏の狩場は、あーしが優勝するからさ、ナビくんはあーしのチームに入りなよ。特別隊員にしてあげるよ！", "0", "0", "0", "0", "cv_sk_wangnv_9", "0", "0"},
[4102200109] = {4102200109, 11022001, 10, 5, "15_1_0_0.8", "level1", "Don't\u{0020}be\u{0020}scared.\u{0020}You\u{0020}must\u{0020}be\u{0020}prepared,\u{0020}right?\u{0020}Summer\u{0020}makes\u{0020}you\u{0020}think\u{0020}of\u{0020}swimsuits,\u{0020}swimsuits\u{0020}make\u{0020}you\u{0020}think\u{0020}of\u{0020}me\u{0020}in\u{0020}a\u{0020}swimsuit,\u{0020}and\u{0020}that\u{0020}brings\u{0020}you\u{0020}to\u{0020}this\u{0020}very\u{0020}moment!\u{0020}So\u{0020}enjoy\u{0020}it\u{0020}properly!", "ビビッてんの？　とっくに覚悟はできてるんでしょ？夏といえば水著、水著といえば水著姿のあーし、あーしといえばこの絵面っしょ？　しっかり楽しんでよね。", "0", "0", "0", "0", "cv_sk_wangnv_10", "0", "0"},
[4102200110] = {4102200110, 11022001, 11, 5, "15_2_0_0.8", "level2", "It's\u{0020}so\u{0020}nice...\u{0020}Being\u{0020}with\u{0020}Navigator\u{0020}is\u{0020}never\u{0020}boring.\u{0020}How\u{0020}about\u{0020}entrusting\u{0020}your\u{0020}whole\u{0020}life\u{0020}to\u{0020}me?", "いいね……ナビくんの傍にいると退屈しないよ。このまま一生あーしの橫にいてくんない？", "0", "0", "0", "0", "cv_sk_wangnv_11", "0", "0"},
