[4102200134] = {4102200134, 11022001, 37, 29, "0", "0", "Taking\u{0020}me\u{0020}to\u{0020}meet\u{0020}the\u{0020}others?\u{0020}Let's\u{0020}go\u{0020}right\u{0020}now!", "あーしを連れて他の人に會いに行くの？いいよ、今から行く？", "0", "0", "0", "0", "cv_sk_wangnv_37", "0", "0"},
[4102200135] = {4102200135, 11022001, 38, 30, "0", "0", "Whoa,\u{0020}you\u{0020}can\u{0020}just\u{0020}call\u{0020}in\u{0020}other\u{0020}Drivers\u{0020}like\u{0020}it's\u{0020}nothing?\u{0020}Must\u{0020}be\u{0020}nice\u{0020}having\u{0020}that\u{0020}kinda\u{0020}pull.", "ナビくんって結構偉いんだねー。他のドライバーを自由に募集できるなんて。", "0", "0", "0", "0", "cv_sk_wangnv_38", "0", "0"},
