[4102200138] = {4102200138, 11022001, 41, 33, "0", "0", "I\u{0020}recognize\u{0020}this!\u{0020}It's\u{0020}your\u{0020}photo,\u{0020}right?", "あ、見覚えあるー。この寫真ってナビくんでしょ？", "0", "0", "0", "0", "cv_sk_wangnv_41", "0", "0"},
[4102200139] = {4102200139, 11022001, 42, 34, "0", "0", "The\u{0020}device\u{0020}that'll\u{0020}change\u{0020}the\u{0020}world\u{0020}is\u{0020}right\u{0020}here.", "世界を変える仕組みはここにあるよ。", "0", "0", "0", "0", "cv_sk_wangnv_42", "0", "0"},
[4102200140] = {4102200140, 11022001, 43, 35, "0", "0", "I\u{0020}know\u{0020}this\u{0020}one!\u{0020}This\u{0020}is\u{0020}where\u{0020}we\u{0020}claim\u{0020}rewards,\u{0020}right?\u{0020}Eh...?\u{0020}Wrong?", "分かった！ここってボーナスが入ってる場所でしょ？え……違った？", "0", "0", "0", "0", "cv_sk_wangnv_43", "0", "0"},
[4102200141] = {4102200141, 11022001, 44, 36, "0", "0", "The\u{0020}chatroom...\u{0020}better\u{0020}watch\u{0020}out\u{0020}for\u{0020}shady\u{0020}people\u{0020}in\u{0020}there.", "チャットかぁ……荒らしには気を付けてよね。", "0", "0", "0", "0", "cv_sk_wangnv_44", "0", "0"},
