[4102300100] = {4102300100, 11023001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_sk_xiaomeng_1", "0", "0"},
[4102300101] = {4102300101, 11023001, 2, 2, "0", "0", "Is\u{0020}this\u{0020}where\u{0020}you\u{0020}often\u{0020}stay,\u{0020}sir?\u{0020}Hmm…\u{0020}well\u{0020}then,\u{0020}this\u{0020}is\u{0020}where\u{0020}Xiaomeng\u{0020}will\u{0020}stand\u{0020}guard\u{0020}from\u{0020}now\u{0020}on.", "0", "這就是閣下經常呆的地方嗎。嗯……嗯！那現在這裏就是曉夢要守護的地方了。", "0", "0", "0", "cv_sk_xiaomeng_2", "0", "0"},
[4102300102] = {4102300102, 11023001, 3, 3, "0", "0", "Upon\u{0020}hearing\u{0020}your\u{0020}call,\u{0020}Xiaomeng\u{0020}rushed\u{0020}over.\u{0020}What\u{0020}trial\u{0020}are\u{0020}you\u{0020}giving\u{0020}me\u{0020}this\u{0020}time?", "0", "閣下，聽到你的呼喚，曉夢馬上就來幫忙了。這次又要給予曉夢什麼樣的試煉呢？", "0", "0", "0", "cv_sk_xiaomeng_3", "0", "0"},
[4102300103] = {4102300103, 11023001, 4, 4, "0", "idle", "May\u{0020}I\u{0020}ask,\u{0020}how\u{0020}many\u{0020}hours\u{0020}until\u{0020}sunrise?\u{0020}Hmm,\u{0020}seems\u{0020}like\u{0020}it's\u{0020}going\u{0020}to\u{0020}be\u{0020}another\u{0020}long\u{0020}night.", "殿、日の出まで、あとどれくらいだ？……ふむ、長い夜になりそうだな。", "請問閣下現在離日出還有幾個時辰？……嗯，看來今晚又是一個漫漫長夜。", "0", "0", "0", "cv_sk_xiaomeng_4", "0", "0"},
[4102300104] = {4102300104, 11023001, 5, 4, "0", "idle", "You've\u{0020}been\u{0020}here\u{0020}for\u{0020}quite\u{0020}a\u{0020}while.\u{0020}Everyone's\u{0020}waiting\u{0020}for\u{0020}you\u{0020}to\u{0020}take\u{0020}your\u{0020}seat…\u{0020}But\u{0020}don't\u{0020}worry,\u{0020}Xiaomeng\u{0020}can\u{0020}handle\u{0020}things\u{0020}just\u{0020}fine.", "殿、もう長い間ここに留まっているが、みんな殿が戻ってくるのを待っているぞ。……暁夢のことなら、心配は無用だ。", "閣下已在此停留多時了，大家都在等著閣下入席呢……閣下不用擔心曉夢的。", "0", "0", "0", "cv_sk_xiaomeng_5", "0", "0"},
[4102300105] = {4102300105, 11023001, 6, 4, "0", "idle", "This\u{0020}posture?\u{0020}Oh,\u{0020}Xiaomeng\u{0020}didn't\u{0020}mean\u{0020}to\u{0020}stand\u{0020}like\u{0020}this!\u{0020}Chenglian\u{0020}asked\u{0020}me\u{0020}to\u{0020}greet\u{0020}you\u{0020}here,\u{0020}but\u{0020}after\u{0020}standing\u{0020}for\u{0020}so\u{0020}long,\u{0020}I\u{0020}tried\u{0020}to\u{0020}stretch.\u{0020}Didn't\u{0020}expect\u{0020}my\u{0020}leg\u{0020}to\u{0020}cramp,\u{0020}and\u{0020}now\u{0020}it's\u{0020}stuck\u{0020}mid-air!", "この姿勢は……暁夢が好きでやっているものではない。澄練に、ここで殿を迎えるようにと言われたんだけど、長く立っていたから、身体を伸ばしてみたら、太ももをつってしまったんだ。", "這姿勢……當然不是曉夢故意為之。澄練讓曉夢站在這裏迎接閣下，站久了便活動活動筋骨，可不想大腿抽筋，一抬腿就放不下來了……", "0", "0", "0", "cv_sk_xiaomeng_6", "0", "0"},
[4102300106] = {4102300106, 11023001, 7, 5, "15_1_0_0.8", "level1", "How\u{0020}could\u{0020}you\u{0020}even\u{0020}do\u{0020}something\u{0020}like\u{0020}that?", "と、殿、他人のピンチにつけ込むのか！？", "閣……閣下豈能趁人之危！", "0", "0", "0", "cv_sk_xiaomeng_7", "0", "0"},
[4102300107] = {4102300107, 11023001, 8, 5, "15_1_0_0.8", "level1", "As\u{0020}a\u{0020}warrior,\u{0020}mastering\u{0020}both\u{0020}fists\u{0020}and\u{0020}kicks\u{0020}is\u{0020}essential.\u{0020}You've\u{0020}seen\u{0020}Xiaomeng's\u{0020}fists\u{0020}in\u{0020}action\u{0020}many\u{0020}times,\u{0020}but\u{0020}I\u{0020}haven't\u{0020}shown\u{0020}my\u{0020}leg\u{0020}techniques\u{0020}yet.\u{0020}Maybe\u{0020}you\u{0020}could\u{0020}offer\u{0020}some\u{0020}guidance?", "武闘家として、拳と蹴りは基本だ。暁夢の拳術は何度か見せたと思うが、蹴りはまだ披露していないな。……殿、何かアドバイスをくれないか？", "身為武夫，拳腳功夫是基礎。曉夢的拳術想必閣下已經見過多次，但腿法還未曾展示過……不知閣下能否指教指教？", "0", "0", "0", "cv_sk_xiaomeng_8", "0", "0"},
[4102300108] = {4102300108, 11023001, 9, 5, "15_2_0_0.8", "level2", "Chenglian\u{0020}picked\u{0020}this\u{0020}outfit\u{0020}for\u{0020}Xiaomeng.\u{0020}She\u{0020}said\u{0020}you\u{0020}have\u{0020}a\u{0020}liking\u{0020}for\u{0020}these\u{0020}unusual\u{0020}clothes…\u{0020}Maybe\u{0020}that's\u{0020}why\u{0020}you've\u{0020}been\u{0020}so\u{0020}curious\u{0020}and\u{0020}touching\u{0020}my\u{0020}outfit?", "この服装は澄練が選んでくれたものだ。殿がこういった変な服装を好むと……殿が先ほどから暁夢の身体を触っているのは、好奇心からか？", "這身衣服是澄練替曉夢選擇的，說是閣下喜歡這些怪異的服飾……想必閣下也是因為好奇才一直觸碰曉夢的身體的吧。", "0", "0", "0", "cv_sk_xiaomeng_9", "0", "0"},
[4102300109] = {4102300109, 11023001, 10, 5, "15_2_0_0.8", "level2", "What's\u{0020}this?\u{0020}Ah,\u{0020}I\u{0020}get\u{0020}it—more\u{0020}talisman\u{0020}papers\u{0020}mean\u{0020}a\u{0020}stronger\u{0020}sealed\u{0020}zombie,\u{0020}right?\u{0020}That's\u{0020}how\u{0020}it\u{0020}always\u{0020}works\u{0020}in\u{0020}the\u{0020}movies.\u{0020}But\u{0020}I'm\u{0020}curious,\u{0020}where\u{0020}did\u{0020}you\u{0020}even\u{0020}get\u{0020}these\u{0020}talisman\u{0020}papers\u{0020}from?", "殿、これは？いや、暁夢は知っているぞ。「身体に貼られた札が多ければ多いほど、封印されているキョンシーも強い」ということは。映画でよくある設定だな。だけど、暁夢が気になっているのは、殿がこの札をどこで手に入れたのかだ。", "閣下這是？曉夢明白了——“身上的符紙越多表示封印的僵屍越強”—這是電影裏常有的設定。不過曉夢好奇的是閣下是從哪里拿出這些符紙？", "0", "0", "0", "cv_sk_xiaomeng_10", "0", "0"},
[4102300110] = {4102300110, 11023001, 11, 5, "15_1_0_0.8", "level1", "Xiaomeng\u{0020}isn't\u{0020}a\u{0020}real\u{0020}zombie.\u{0020}Your\u{0020}talisman\u{0020}papers\u{0020}won't\u{0020}work\u{0020}on\u{0020}me.\u{0020}If\u{0020}you\u{0020}need\u{0020}something\u{0020}done,\u{0020}just\u{0020}give\u{0020}the\u{0020}order…\u{0020}Whatever\u{0020}it\u{0020}is,\u{0020}Xiaomeng\u{0020}will\u{0020}give\u{0020}her\u{0020}all.", "暁夢は本物のキョンシーではないから、殿の札も暁夢には効かないぞ。暁夢に何かして欲しいなら、そのまま命じればいい。…いかなる時でも、暁夢は殿のためには力を尽くすぞ。", "曉夢不是真的僵屍，閣下的符紙對曉夢是沒用的。如果閣下想要曉夢做什麼事，只需下命令就好了……無論何事，曉夢都將傾力而為……", "0", "0", "0", "cv_sk_xiaomeng_11", "0", "0"},
[4102300111] = {4102300111, 11023001, 12, 6, "0", "0", "Oh,\u{0020}I\u{0020}see\u{0020}now.\u{0020}So,\u{0020}this\u{0020}is\u{0020}a\u{0020}type\u{0020}of\u{0020}training\u{0020}technique?", "0", "原來如此，還有這種練習方式。", "0", "0", "0", "cv_sk_xiaomeng_12", "0", "0"},
[4102300112] = {4102300112, 11023001, 13, 7, "0", "0", "What's\u{0020}the\u{0020}goal\u{0020}of\u{0020}doing\u{0020}this?", "0", "這樣做的目的是什麼。", "0", "0", "0", "cv_sk_xiaomeng_13", "0", "0"},
[4102300113] = {4102300113, 11023001, 14, 8, "0", "0", "Time\u{0020}to\u{0020}stretch\u{0020}out\u{0020}my\u{0020}spine…", "0", "該練練脊骨了……", "0", "0", "0", "cv_sk_xiaomeng_14", "0", "0"},
[4102300114] = {4102300114, 11023001, 15, 9, "0", "0", "Not\u{0020}too\u{0020}much,\u{0020}not\u{0020}too\u{0020}little.\u{0020}Adjust\u{0020}as\u{0020}needed—bend\u{0020}when\u{0020}it's\u{0020}time,\u{0020}stand\u{0020}tall\u{0020}when\u{0020}required!", "0", "無過不及，隨曲就伸！", "0", "0", "0", "cv_sk_xiaomeng_15", "0", "0"},
[4102300115] = {4102300115, 11023001, 16, 10, "0", "0", "Xiaomeng,\u{0020}the\u{0020}Warrior\u{0020}of\u{0020}Kyushu\u{0020}Pingxin,\u{0020}awaiting\u{0020}your\u{0020}command.", "0", "九州平心社，“武夫”曉夢，請指教。", "0", "0", "0", "cv_sk_xiaomeng_16", "0", "0"},
[4102300116] = {4102300116, 11023001, 17, 11, "0", "0", "Simple\u{0020}enough—task\u{0020}completed\u{0020}without\u{0020}a\u{0020}hitch!", "0", "簡單，順利完成了！", "0", "0", "0", "cv_sk_xiaomeng_17", "0", "0"},
[4102300117] = {4102300117, 11023001, 18, 12, "0", "0", "Now\u{0020}that\u{0020}I've\u{0020}got\u{0020}the\u{0020}hang\u{0020}of\u{0020}it,\u{0020}let's\u{0020}go\u{0020}again!", "0", "積累了經驗，再來一次吧！", "0", "0", "0", "cv_sk_xiaomeng_18", "0", "0"},
[4102300118] = {4102300118, 11023001, 19, 13, "0", "0", "Just\u{0020}half\u{0020}a\u{0020}step\u{0020}shy.", "0", "棋差半步啊。", "0", "0", "0", "cv_sk_xiaomeng_19", "0", "0"},
[4102300119] = {4102300119, 11023001, 20, 14, "0", "0", "Winning\u{0020}or\u{0020}losing\u{0020}doesn't\u{0020}matter.\u{0020}Xiaomeng\u{0020}will\u{0020}stand\u{0020}by\u{0020}your\u{0020}side\u{0020}and\u{0020}start\u{0020}fresh\u{0020}with\u{0020}you.", "0", "勝敗乃常事，曉夢陪閣下重新來過吧。", "0", "0", "0", "cv_sk_xiaomeng_20", "0", "0"},
[4102300120] = {4102300120, 11023001, 21, 15, "0", "0", "Too\u{0020}weak.", "弱すぎる。", "太嬴弱了。", "0", "0", "0", "cv_sk_xiaomeng_21", "0", "0"},
[4102300121] = {4102300121, 11023001, 23, 16, "0", "0", "Your\u{0020}life\u{0020}belongs\u{0020}to\u{0020}me!", "お命ちょうだい！", "拿命來！", "0", "0", "0", "cv_sk_xiaomeng_22", "0", "0"},
[4102300122] = {4102300122, 11023001, 24, 17, "0", "0", "Did\u{0020}you\u{0020}really\u{0020}think\u{0020}you\u{0020}could\u{0020}escape?", "本当に逃げられると思っているのか？", "真當你可以逃走嗎？", "0", "0", "0", "cv_sk_xiaomeng_23", "0", "0"},
[4102300123] = {4102300123, 11023001, 25, 18, "0", "0", "Tai\u{0020}Chi\u{0020}Chuan!\u{0020}Ha!", "0", "虛領頂勁。哈——！", "0", "0", "0", "cv_sk_xiaomeng_24", "0", "0"},
[4102300124] = {4102300124, 11023001, 26, 19, "0", "0", "This\u{0020}time,\u{0020}I'll\u{0020}really\u{0020}turn\u{0020}into\u{0020}a\u{0020}zombie.", "本当にキョンシーになってしまうのか。", "這下真要變僵屍了。", "0", "0", "0", "cv_sk_xiaomeng_25", "0", "0"},
[4102300125] = {4102300125, 11023001, 27, 20, "0", "0", "I've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}so\u{0020}long.\u{0020}Today's\u{0020}the\u{0020}day...\u{0020}for\u{0020}that\u{0020}medicinal\u{0020}bath\u{0020}my\u{0020}mother\u{0020}used\u{0020}to\u{0020}prepare\u{0020}all\u{0020}the\u{0020}time...", "0", "久候多時了，今天是要……那個吧……以前媽媽經常做的……藥浴……", "0", "0", "0", "cv_sk_xiaomeng_26", "0", "0"},
[4102300126] = {4102300126, 11023001, 28, 21, "0", "0", "Sir,\u{0020}don't\u{0020}you\u{0020}have\u{0020}any\u{0020}requests\u{0020}for\u{0020}Xiaomeng?\u{0020}Whatever\u{0020}you\u{0020}say,\u{0020}Xiaomeng\u{0020}will\u{0020}listen.", "0", "閣下……不向曉夢下要求嗎……曉夢會聽閣下的話哦。", "0", "0", "0", "cv_sk_xiaomeng_27", "0", "0"},
[4102300127] = {4102300127, 11023001, 29, 21, "0", "0", "Is\u{0020}this\u{0020}behaving\u{0020}well?\u{0020}But\u{0020}if\u{0020}I\u{0020}only\u{0020}stay\u{0020}in\u{0020}one\u{0020}position,\u{0020}some\u{0020}spots\u{0020}won't\u{0020}get\u{0020}washed\u{0020}properly...", "0", "乖乖這樣就可以了嗎，只是一個姿勢的話，有些地方會洗不乾淨哦……", "0", "0", "0", "cv_sk_xiaomeng_28", "0", "0"},
[4102300128] = {4102300128, 11023001, 30, 22, "0", "0", "Is\u{0020}it\u{0020}about\u{0020}to\u{0020}begin...?", "0", "要開始了嗎……", "0", "0", "0", "cv_sk_xiaomeng_29", "0", "0"},
[4102300129] = {4102300129, 11023001, 31, 23, "0", "0", "Xiaomeng\u{0020}trusts\u{0020}you\u{0020}completely.", "0", "曉夢相信閣下。", "0", "0", "0", "cv_sk_xiaomeng_30", "0", "0"},
[4102300130] = {4102300130, 11023001, 32, 24, "0", "0", "You're\u{0020}the\u{0020}one\u{0020}who\u{0020}taught\u{0020}me\u{0020}to\u{0020}see\u{0020}what's\u{0020}right\u{0020}and\u{0020}wrong,\u{0020}what's\u{0020}true\u{0020}and\u{0020}false.", "0", "分清楚是和非、正確和錯誤。閣下就是教會曉夢這個道理的人。", "0", "0", "0", "cv_sk_xiaomeng_31", "0", "0"},
[4102300131] = {4102300131, 11023001, 33, 25, "0", "0", "Navigator!", "0", "閣下！", "0", "0", "0", "cv_sk_xiaomeng_32", "0", "0"},
[4102300132] = {4102300132, 11023001, 34, 26, "0", "0", "We\u{0020}meet\u{0020}again.\u{0020}Xiaomeng's\u{0020}just\u{0020}practicing\u{0020}leg\u{0020}techniques...\u{0020}Ha,\u{0020}ha,\u{0020}ha.", "また会ったな、殿。……暁夢はただ、蹴りの練習をしていただけだ……ハッ、ハッ、ハッ。", "又見面了閣下……曉夢只是在練習腿法而已……哈，哈，哈。", "0", "0", "0", "cv_sk_xiaomeng_33", "0", "0"},
