[4102800102] = {4102800102, 11028001, 3, 3, "0", "0", "First\u{0020}time\u{0020}meeting...\u{0020}huh?\u{0020}You...\u{0020}oh...\u{0020}excuse\u{0020}me,\u{0020}I\u{0020}am\u{0020}Geiro,\u{0020}one\u{0020}of\u{0020}the\u{0020}Valkyries...\u{0020}and\u{0020}also\u{0020}Katya's\u{0020}strongest\u{0020}Driver.\u{0020}Yes,\u{0020}I\u{0020}can\u{0020}say\u{0020}that\u{0020}with\u{0020}confidence.", "はじめまして…うん？あなたは…あっ、失禮。私はワルキューレが一人、ジェロよ。そしてカティア最強のドライバー。えぇ、その自信があるわ。", "0", "0", "0", "0", "cv_sk_geiro_3", "0", "0"},
[4102800103] = {4102800103, 11028001, 4, 4, "0", "idle", "In\u{0020}quiet\u{0020}moments,\u{0020}I\u{0020}browse\u{0020}the\u{0020}things\u{0020}I\u{0020}like\u{0020}online.\u{0020}What\u{0020}kind\u{0020}of\u{0020}things?\u{0020}…Why\u{0020}do\u{0020}you\u{0020}care?\u{0020}It’s\u{0020}not\u{0020}something\u{0020}someone\u{0020}like\u{0020}you\u{0020}would\u{0020}understand\u{0020}anyway.", "0", "0", "0", "0", "0", "cv_sk_geiro_4", "0", "0"},
[4102800104] = {4102800104, 11028001, 4, 4, "0", "idle", "Sometimes\u{0020}I\u{0020}envy\u{0020}those\u{0020}who\u{0020}can\u{0020}draw—able\u{0020}to\u{0020}paint\u{0020}what\u{0020}only\u{0020}lives\u{0020}in\u{0020}the\u{0020}mind.\u{0020}Sigh...\u{0020}Wish\u{0020}I\u{0020}could\u{0020}do\u{0020}that\u{0020}too.\u{0020}\u{0020}", "0", "0", "0", "0", "0", "cv_sk_geiro_5", "0", "0"},
[4102800105] = {4102800105, 11028001, 4, 4, "0", "idle2", "You're\u{0020}strange.\u{0020}Why\u{0020}would\u{0020}you\u{0020}want\u{0020}to\u{0020}pat\u{0020}my\u{0020}head?\u{0020}Does\u{0020}that\u{0020}amuse\u{0020}you\u{0020}somehow?", "0", "0", "0", "0", "0", "cv_sk_geiro_6", "0", "0"},
