[4103000100] = {4103000100, 11030001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_sk_chenglian_1", "0", "0"},
[4103000101] = {4103000101, 11030001, 2, 2, "0", "0", "Shall\u{0020}I\u{0020}act\u{0020}as\u{0020}your\u{0020}advisor?\u{0020}Wonderful.\u{0020}I've\u{0020}been\u{0020}wanting\u{0020}to\u{0020}have\u{0020}a\u{0020}proper\u{0020}conversation\u{0020}with\u{0020}you,\u{0020}Navigator.", "0", "由我來擔任參謀嗎……正好，我也有很多話想與領航講。", "0", "0", "0", "cv_sk_chenglian_2", "0", "0"},
[4103000102] = {4103000102, 11030001, 3, 3, "0", "0", "Are\u{0020}you\u{0020}the\u{0020}Navigator\u{0020}from\u{0020}Danube?\u{0020}I\u{0020}am\u{0020}Chenglian,\u{0020}from\u{0020}Kyushu\u{0020}Pingxin.\u{0020}I've\u{0020}waited\u{0020}a\u{0020}long\u{0020}time\u{0020}for\u{0020}this\u{0020}moment.\u{0020}It\u{0020}looks\u{0020}like\u{0020}we'll\u{0020}be\u{0020}working\u{0020}together\u{0020}for\u{0020}quite\u{0020}a\u{0020}while—please\u{0020}guide\u{0020}me.", "0", "閣下就是那位來自多瑙的領航吧？九州平心社，澄練，在此久候多時了。可以預見，接下來我們將會共事很長一段時間，請多多指教。", "0", "0", "0", "cv_sk_chenglian_3", "0", "0"},
[4103000103] = {4103000103, 11030001, 4, 4, "0", "idle", "Let's\u{0020}enjoy\u{0020}some\u{0020}wine\u{0020}today\u{0020}while\u{0020}we\u{0020}have\u{0020}the\u{0020}chance...\u{0020}Where's\u{0020}your\u{0020}cup,\u{0020}Navigator?\u{0020}If\u{0020}you\u{0020}don't\u{0020}have\u{0020}one,\u{0020}feel\u{0020}free\u{0020}to\u{0020}drink\u{0020}from\u{0020}mine.", "お酒があるなら、飲まずにはいられないですよね…。…ナビゲーターさん、あなたの杯は？もしないのなら、私のを飲んでください。", "今朝有酒今朝醉……領航你的酒杯呢？沒有的話就喝我的吧。", "0", "0", "0", "cv_sk_chenglian_4", "0", "0"},
[4103000104] = {4103000104, 11030001, 5, 4, "0", "idle", "You've\u{0020}been\u{0020}staring\u{0020}for\u{0020}a\u{0020}while\u{0020}now...\u{0020}Don't\u{0020}worry,\u{0020}I\u{0020}won't\u{0020}write\u{0020}this\u{0020}down.", "さっきからずっとナビゲーターさんの視線を感じるのですが…。…心配しないでください、このことは記録しませんので。", "從剛才開始，領航的眼睛就沒移開過。……放心，這件事我不會記錄下來的。", "0", "0", "0", "cv_sk_chenglian_5", "0", "0"},
[4103000105] = {4103000105, 11030001, 6, 4, "0", "idle", "Happy\u{0020}New\u{0020}Year!\u{0020}Today,\u{0020}we\u{0020}should\u{0020}raise\u{0020}a\u{0020}toast.\u{0020}In\u{0020}times\u{0020}like\u{0020}these,\u{0020}every\u{0020}year\u{0020}we\u{0020}get\u{0020}through\u{0020}is\u{0020}a\u{0020}victory\u{0020}for\u{0020}humanity.", "新春を祝して、今日は杯を交わしましょう。このような時代に無事一年過ごすことができれば、人類にとっては大きな勝利といえるでしょう。", "新年快樂！今天，我們應當舉杯歡慶。在這個危機時代，每度過一年都是人類的一次偉大勝利。", "0", "0", "0", "cv_sk_chenglian_6", "0", "0"},
[4103000106] = {4103000106, 11030001, 7, 5, "1_》_0_0.8", "level1", "This\u{0020}outfit\u{0020}feels\u{0020}a\u{0020}bit\u{0020}daring...\u{0020}I\u{0020}think\u{0020}I\u{0020}need\u{0020}a\u{0020}few\u{0020}more\u{0020}sips\u{0020}to\u{0020}shake\u{0020}off\u{0020}the\u{0020}embarrassment.", "この衣装、少し大胆なような気がするのですが……。…この恥ずかしさを振り払うためにも、もっと飲まなくては。", "這套衣服好像是有些大膽了……我要多喝幾口才能擺脫羞恥的感覺。", "0", "0", "0", "cv_sk_chenglian_7", "0", "0"},
[4103000107] = {4103000107, 11030001, 8, 5, "1_》_0_0.8", "level1", "Are\u{0020}you\u{0020}curious\u{0020}about\u{0020}what's\u{0020}beneath\u{0020}this\u{0020}fabric?", "この布の下がどうなっているのか​​、気になりますか？", "很在意這塊布下麵的東西嗎？", "0", "0", "0", "cv_sk_chenglian_8", "0", "0"},
[4103000108] = {4103000108, 11030001, 9, 5, "1_》_100_1.5", "level2", "Eh—has\u{0020}the\u{0020}Navigator\u{0020}had\u{0020}a\u{0020}bit\u{0020}too\u{0020}much\u{0020}too?", "あら、ナビゲーターさんも、飲み過ぎてしまいましたか？", "咦——領航你也喝多了嗎？", "0", "0", "0", "cv_sk_chenglian_9", "0", "0"},
[4103000109] = {4103000109, 11030001, 10, 5, "1_》_500_2", "level3", "This\u{0020}must\u{0020}be\u{0020}a\u{0020}dream.\u{0020}I'm\u{0020}actually\u{0020}drinking...\u{0020}A\u{0020}historian\u{0020}should\u{0020}stay\u{0020}sober.\u{0020}I'll\u{0020}have\u{0020}to\u{0020}write\u{0020}this\u{0020}down\u{0020}as\u{0020}a\u{0020}reminder...\u{0020}Wait,\u{0020}where's\u{0020}my\u{0020}pen?", "私がお酒を飲むなんて…これはきっと夢ですね。史官は、意識を保たなくてはいけないのに…。…戒めのために、今日のことはちゃんと記録しておかないと……。……あれ、私の筆は…？", "我一定是在做夢，我竟然在喝酒。史官需要保持清醒……我要把今天記錄下來以此為戒。……誒，我的筆去哪了？", "0", "0", "0", "cv_sk_chenglian_10", "0", "0"},
[4103000110] = {4103000110, 11030001, 11, 5, "1_》_1000_2.5", "level4", "Tonight\u{0020}will\u{0020}end\u{0020}soon,\u{0020}and\u{0020}before\u{0020}long,\u{0020}we'll\u{0020}be\u{0020}celebrating\u{0020}again.\u{0020}History\u{0020}repeats\u{0020}itself.\u{0020}I\u{0020}hope\u{0020}the\u{0020}next\u{0020}year\u{0020}brings\u{0020}us\u{0020}the\u{0020}same\u{0020}joys,\u{0020}sorrows,\u{0020}and\u{0020}blessings\u{0020}as\u{0020}the\u{0020}last.", "今宵ももう残りわずかですね…。ですが、次のお祝い事はそう遠くない未來でしょう。歴史とは、このように繰り返してきたことの記録です。来年も、よく笑い、よく泣き、そして幸せに過ごせるといいですね。", "今夜不久後就會結束，而下一次慶祝將在不久的未來。歷史就是這樣不斷重複的記錄。願明年的我們能和去年的我們一樣，快樂悲傷幸福。", "0", "0", "0", "cv_sk_chenglian_11", "0", "0"},
[4103000111] = {4103000111, 11030001, 12, 6, "0", "0", "Support\u{0020}from\u{0020}the\u{0020}Navigator...\u{0020}I've\u{0020}received\u{0020}it.", "0", "來自領航的支援。我收到了。", "0", "0", "0", "cv_sk_chenglian_12", "0", "0"},
