[4103200100] = {4103200100, 11032001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_sk_qianqiu_1", "0", "0"},
[4103200101] = {4103200101, 11032001, 2, 2, "0", "0", "Can't\u{0020}someone\u{0020}else\u{0020}take\u{0020}care\u{0020}of\u{0020}this?\u{0020}Fine,\u{0020}I'll\u{0020}handle\u{0020}it.", "0", "就不能讓別人來做這件事……好啦好啦，我做就是了。", "0", "0", "0", "cv_sk_qianqiu_2", "0", "0"},
[4103200102] = {4103200102, 11032001, 3, 3, "0", "0", "Ugh...\u{0020}That\u{0020}Stephanie\u{0020}is\u{0020}so\u{0020}arrogant!\u{0020}Anyway,\u{0020}long\u{0020}time\u{0020}no\u{0020}see!\u{0020}Looks\u{0020}like\u{0020}you've\u{0020}become\u{0020}quite\u{0020}the\u{0020}Navigator.\u{0020}You\u{0020}remember\u{0020}me,\u{0020}right?\u{0020}Chiaki—make\u{0020}sure\u{0020}you\u{0020}remember\u{0020}that\u{0020}name.", "0", "唉……史蒂芬妮那傢伙真是有夠目中無人的……總之——好久不見，看來你已經成為相當出色的領航了……你不會已經忘了我吧？千——秋，好好記住這個名字。", "0", "0", "0", "cv_sk_qianqiu_3", "0", "0"},
[4103200103] = {4103200103, 11032001, 91, 4, "0", "idle", "Sob...\u{0020}Do\u{0020}you\u{0020}know\u{0020}how\u{0020}I\u{0020}spent\u{0020}the\u{0020}last\u{0020}year?\u{0020}Eating\u{0020}nothing\u{0020}but\u{0020}junk\u{0020}food\u{0020}that\u{0020}wrecks\u{0020}my\u{0020}taste\u{0020}buds\u{0020}every\u{0020}single\u{0020}day!\u{0020}If\u{0020}I\u{0020}ever\u{0020}get\u{0020}the\u{0020}chance,\u{0020}I'm\u{0020}definitely\u{0020}going\u{0020}after\u{0020}that\u{0020}Stephanie!", "0", "呜呜呜，你知道我这一年多来是怎么度过的吗，每天吃的都是什么破坏味觉的垃圾食品吗？史蒂芬妮那家伙，有机会我一定要杀了她！", "0", "0", "0", "cv_sk_qianqiu_4", "0", "0"},
[4103200104] = {4103200104, 11032001, 91, 4, "0", "idle", "Hmph!\u{0020}Do\u{0020}you\u{0020}want\u{0020}me\u{0020}to\u{0020}call\u{0020}you\u{0020}\"Navigator\"\u{0020}like\u{0020}everyone\u{0020}else?\u{0020}Alright,\u{0020}I\u{0020}get\u{0020}it.\u{0020}Navigator.\u{0020}Navigator.\u{0020}Navigator.\u{0020}Haha!\u{0020}That\u{0020}title\u{0020}is\u{0020}just\u{0020}ridiculous.", "0", "哼~你也希望我像她们那样称呼你为“领航”吗？好啦好啦，我知道了，领航~领航~领航~哈哈！这个称呼真的好蠢呀。", "0", "0", "0", "cv_sk_qianqiu_5", "0", "0"},
[4103200105] = {4103200105, 11032001, 94, 4, "0", "idle2", "Next\u{0020}time,\u{0020}I\u{0020}want\u{0020}to\u{0020}try\u{0020}the\u{0020}crazy\u{0020}combination\u{0020}of\u{0020}ice\u{0020}cream\u{0020}cake\u{0020}and\u{0020}ramen.\u{0020}Now\u{0020}that\u{0020}would\u{0020}be\u{0020}a\u{0020}real\u{0020}challenge!\u{0020}Honestly,\u{0020}though,\u{0020}eating\u{0020}them\u{0020}should\u{0020}be\u{0020}easier\u{0020}than\u{0020}killing\u{0020}someone,\u{0020}right?", "0", "下次有機會的話，我要嘗試一下冰淇淋蛋糕搭配拉麵的吃法。嗯，這會是一次前所未有的挑戰，但不管怎麼說，咽下它們應該比殺人要簡單吧？", "0", "0", "0", "cv_sk_qianqiu_6", "0", "0"},
[4103200106] = {4103200106, 11032001, 95, 5, "14_》_0_0.8", "touch2", "You\u{0020}know,\u{0020}killing\u{0020}someone\u{0020}isn't\u{0020}actually\u{0020}that\u{0020}hard.\u{0020}But\u{0020}if\u{0020}someone\u{0020}can\u{0020}cross\u{0020}that\u{0020}line\u{0020}without\u{0020}feeling\u{0020}anything,\u{0020}they're\u{0020}a\u{0020}true\u{0020}killer.", "0", "你知道嗎？“將某人殺死”，這種事做起來其實沒有多難。可若是一個人能沒有心理負擔地輕易越過殺人之門，那便是殺人鬼。", "0", "0", "0", "cv_sk_qianqiu_7", "0", "0"},
[4103200107] = {4103200107, 11032001, 93, 5, "14_》_0_0.8", "touch_s1", "Ice\u{0020}cream\u{0020}burger!", "0", "冰淇淋漢堡！", "0", "0", "0", "cv_sk_qianqiu_8", "0", "0"},
[4103200108] = {4103200108, 11032001, 95, 5, "14_》_0_0.8", "touch2", "What?\u{0020}You've\u{0020}got\u{0020}nothing\u{0020}to\u{0020}do?\u{0020}In\u{0020}that\u{0020}case,\u{0020}want\u{0020}to\u{0020}take\u{0020}a\u{0020}look\u{0020}at\u{0020}my\u{0020}breasts?\u{0020}You\u{0020}think\u{0020}I'm\u{0020}joking?\u{0020}I'm\u{0020}serious!\u{0020}I'm\u{0020}just\u{0020}really\u{0020}bored\u{0020}right\u{0020}now.\u{0020}Don't\u{0020}worry,\u{0020}I\u{0020}won't\u{0020}kill\u{0020}you.", "0", "怎麼？沒事情做嗎？既然如此，要不要看看我的胸部？“玩笑”？為什麼會這麼想，我是認真的。畢竟現在真的很無聊。放心，我不會殺你的。", "0", "0", "0", "cv_sk_qianqiu_9", "0", "0"},
[4103200109] = {4103200109, 11032001, 92, 5, "14_》_0_0.8", "touch1", "Since\u{0020}you're\u{0020}being\u{0020}reasonable,\u{0020}I'll\u{0020}let\u{0020}you\u{0020}touch\u{0020}me\u{0020}today.\u{0020}Usually,\u{0020}that\u{0020}would\u{0020}cost\u{0020}you\u{0020}a\u{0020}life!", "0", "看在你識趣的份上，今天我就允許你隨意摸我啦，要是平常的話，可是會搭上一條人命的。", "0", "0", "0", "cv_sk_qianqiu_10", "0", "0"},
[4103200110] = {4103200110, 11032001, 96, 5, "14_》_0_0.8", "touch_s2", "Will\u{0020}you\u{0020}miss\u{0020}that\u{0020}experience?\u{0020}I\u{0020}know\u{0020}I\u{0020}will.\u{0020}Sometimes,\u{0020}I\u{0020}even\u{0020}dream\u{0020}of\u{0020}your\u{0020}ridiculous\u{0020}face\u{0020}from\u{0020}back\u{0020}then.\u{0020}But\u{0020}honestly,\u{0020}after\u{0020}looking\u{0020}at\u{0020}it\u{0020}for\u{0020}a\u{0020}while,\u{0020}I\u{0020}think\u{0020}it's\u{0020}not\u{0020}so\u{0020}bad—it's\u{0020}kind\u{0020}of\u{0020}handsome.", "0", "你會不會懷念那次經歷？我的話是會的哦，晚上做夢的時候也偶爾會夢到你當時的那副蠢臉——不過嘛，看久了的話也會覺得蠻帥的。", "0", "0", "0", "cv_sk_qianqiu_11", "0", "0"},
[4103200111] = {4103200111, 11032001, 12, 6, "0", "0", "The\u{0020}higher\u{0020}the\u{0020}level,\u{0020}the\u{0020}greater\u{0020}the\u{0020}responsibility,\u{0020}right?", "0", "級別越高，責任越大，我說的對嗎？", "0", "0", "0", "cv_sk_qianqiu_12", "0", "0"},
[4103200112] = {4103200112, 11032001, 13, 7, "0", "0", "If\u{0020}you\u{0020}want\u{0020}to\u{0020}reward\u{0020}me,\u{0020}how\u{0020}about\u{0020}treating\u{0020}me\u{0020}to\u{0020}ramen\u{0020}next\u{0020}time?", "0", "想獎勵我的話，不如下次請我吃拉麵。", "0", "0", "0", "cv_sk_qianqiu_13", "0", "0"},
[4103200113] = {4103200113, 11032001, 14, 8, "0", "0", "Do\u{0020}you\u{0020}remember\u{0020}what\u{0020}we\u{0020}said\u{0020}when\u{0020}we\u{0020}first\u{0020}met?\u{0020}Yeah,\u{0020}I\u{0020}really\u{0020}didn't\u{0020}want\u{0020}to\u{0020}be\u{0020}a\u{0020}pilot\u{0020}at\u{0020}all...\u{0020}I\u{0020}never\u{0020}imagined\u{0020}it\u{0020}would\u{0020}turn\u{0020}out\u{0020}like\u{0020}this.\u{0020}You've\u{0020}really\u{0020}done\u{0020}it,\u{0020}Navigator.", "0", "還記得我們第一次見面時說的嗎？對，我一點也不想當駕駛員……唉，我可能怎麼也想不到居然會成這樣，真有你的——領航。", "0", "0", "0", "cv_sk_qianqiu_14", "0", "0"},
