[4103200132] = {4103200132, 11032001, 34, 26, "0", "0", "Back\u{0020}already?\u{0020}I\u{0020}know\u{0020}you're\u{0020}busy,\u{0020}but\u{0020}since\u{0020}you're\u{0020}here,\u{0020}you\u{0020}should\u{0020}take\u{0020}a\u{0020}break\u{0020}first.", "0", "回來了？知道你很忙，既然回來了就先休息一會吧。", "0", "0", "0", "cv_sk_qianqiu_34", "0", "0"},
[4103200133] = {4103200133, 11032001, 35, 27, "0", "0", "Um,\u{0020}hoo—alright,\u{0020}let's\u{0020}get\u{0020}going.\u{0020}Let's\u{0020}kill\u{0020}them\u{0020}all.", "0", "嗯——呼——好，出發，讓我們把它們殺個乾淨吧。", "0", "0", "0", "cv_sk_qianqiu_35", "0", "0"},
[4103200134] = {4103200134, 11032001, 36, 28, "0", "0", "And\u{0020}hey,\u{0020}don't\u{0020}blame\u{0020}me\u{0020}if\u{0020}I\u{0020}accidentally\u{0020}take\u{0020}someone\u{0020}out\u{0020}in\u{0020}the\u{0020}process.", "0", "要是不小心殺人了可別怪我噢？", "0", "0", "0", "cv_sk_qianqiu_36", "0", "0"},
