[4103300101] = {4103300101, 11033001, 2, 2, "0", "0", "Let\u{0020}me\u{0020}stay\u{0020}here;\u{0020}I\u{0020}might\u{0020}just\u{0020}get\u{0020}hit\u{0020}by\u{0020}a\u{0020}falling\u{0020}meteorite—Haha,\u{0020}just\u{0020}a\u{0020}\"movie\u{0020}joke.\"", "0", "讓我待在這的話，說不定會被墜落的隕石命中——哈哈，只是開個“電影玩笑”而已。", "0", "0", "0", "cv_sk_starry_2", "0", "0"},
[4103300102] = {4103300102, 11033001, 3, 3, "0", "0", "Hi\u{0020}there,\u{0020}Mr.\u{0020}Hentai!\u{0020}Long\u{0020}time\u{0020}no\u{0020}see!\u{0020}You've\u{0020}become\u{0020}an\u{0020}official\u{0020}Navigator?\u{0020}Well,\u{0020}I'm\u{0020}officially\u{0020}a\u{0020}driver\u{0020}now,\u{0020}\"Starry\"\u{0020}of\u{0020}the\u{0020}frontline\u{0020}team.\u{0020}After\u{0020}all\u{0020}the\u{0020}craziness,\u{0020}we\u{0020}finally\u{0020}meet\u{0020}again.", "0", "嗨~色狼先生，好久不見~你已經是正式的領航了？嗯，我也是正式的駕駛員，前線小隊的“星爍”咯……雖然發生了各種各樣的事，但我們總算又見面了。", "0", "0", "0", "cv_sk_starry_3", "0", "0"},
[4103300103] = {4103300103, 11033001, 4, 4, "0", "idle", "The\u{0020}smell\u{0020}of\u{0020}the\u{0020}sea\u{0020}breeze\u{0020}and\u{0020}your\u{0020}scent—it's\u{0020}truly\u{0020}unforgettable.", "0", "海風的氣味……還有你的氣味，真是讓人不想忘懷。", "0", "0", "0", "cv_sk_starry_4", "0", "0"},
[4103300104] = {4103300104, 11033001, 5, 4, "0", "idle", "Thinking\u{0020}about\u{0020}what's\u{0020}next\u{0020}gives\u{0020}me\u{0020}a\u{0020}headache.\u{0020}Forget\u{0020}it;\u{0020}let's\u{0020}not\u{0020}dwell\u{0020}on\u{0020}unhappy\u{0020}thoughts.\u{0020}Let's\u{0020}enjoy\u{0020}the\u{0020}moment!", "0", "一想到之後要做的事情，頭就會開始疼起來。算啦，不想那種不開心的事，我們還是享受當下吧！", "0", "0", "0", "cv_sk_starry_5", "0", "0"},
[4103300105] = {4103300105, 11033001, 6, 4, "0", "idle", "I\u{0020}snuck\u{0020}in\u{0020}here\u{0020}this\u{0020}time.\u{0020}For\u{0020}our\u{0020}safety,\u{0020}it's\u{0020}best\u{0020}not\u{0020}to\u{0020}tell\u{0020}anyone\u{0020}else.\u{0020}This\u{0020}is\u{0020}our\u{0020}secret—oh.", "0", "我這次算是偷偷摸摸過來的，為了你和我的安全著想，最好不要告訴給第三人，這是我和你的秘——密噢。", "0", "0", "0", "cv_sk_starry_6", "0", "0"},
[4103300106] = {4103300106, 11033001, 7, 5, "15_1_0_0.8", "level1", "What's\u{0020}up?\u{0020}Are\u{0020}you\u{0020}drawn\u{0020}to\u{0020}my\u{0020}body?", "0", "怎麼了？對我的身體心動了嗎？", "0", "0", "0", "cv_sk_starry_7", "0", "0"},
[4103300107] = {4103300107, 11033001, 8, 5, "15_1_0_0.8", "level1", "Enjoying\u{0020}the\u{0020}beach\u{0020}and\u{0020}sunshine\u{0020}with\u{0020}you...\u{0020}Haha,\u{0020}seriously,\u{0020}is\u{0020}the\u{0020}world\u{0020}really\u{0020}going\u{0020}to\u{0020}end\u{0020}after\u{0020}this?", "0", "和你一起享受海灘與陽光……哈哈…真是的，難道之後世界就要毀滅了嗎？", "0", "0", "0", "cv_sk_starry_8", "0", "0"},
[4103300108] = {4103300108, 11033001, 9, 5, "15_2_0_0.8", "level2", "Want\u{0020}something\u{0020}to\u{0020}eat?\u{0020}What\u{0020}a\u{0020}shame;\u{0020}I\u{0020}didn't\u{0020}win\u{0020}the\u{0020}second\u{0020}round\u{0020}this\u{0020}time.\u{0020}But\u{0020}if\u{0020}you\u{0020}don't\u{0020}mind,\u{0020}I\u{0020}can\u{0020}share\u{0020}this\u{0020}one\u{0020}with\u{0020}you.\u{0020}\"Ah—\"", "0", "想吃嗎？真遺憾，這一次我沒有抽中第二根——不過你要是不介意的話，我可以把這一根給你哦，“啊——”。", "0", "0", "0", "cv_sk_starry_9", "0", "0"},
[4103300109] = {4103300109, 11033001, 10, 5, "15_1_0_0.8", "level1", "Just\u{0020}lying\u{0020}around\u{0020}is\u{0020}boring.\u{0020}Hey,\u{0020}Mr.\u{0020}Hentai,\u{0020}want\u{0020}to\u{0020}do\u{0020}something\u{0020}more\u{0020}exciting?\u{0020}Anything\u{0020}you\u{0020}want\u{0020}is\u{0020}fine\u{0020}by\u{0020}me.", "0", "光是躺著很沒意思把。喂，色狼先生，我們要不要去做更加刺激的事情？只要你想的話，什麼——都可以噢。", "0", "0", "0", "cv_sk_starry_10", "0", "0"},
[4103300110] = {4103300110, 11033001, 11, 5, "15_1_0_0.8", "level1", "Mr.\u{0020}Hentai,\u{0020}let's\u{0020}make\u{0020}a\u{0020}promise:\u{0020}when\u{0020}I'm\u{0020}in\u{0020}danger,\u{0020}you'll\u{0020}come\u{0020}to\u{0020}save\u{0020}me,\u{0020}and\u{0020}when\u{0020}you're\u{0020}in\u{0020}danger,\u{0020}I'll\u{0020}rush\u{0020}to\u{0020}your\u{0020}side,\u{0020}no\u{0020}matter\u{0020}where\u{0020}I\u{0020}am.\u{0020}I\u{0020}won't\u{0020}break\u{0020}my\u{0020}promise.", "0", "色狼先生，我們來做個約定吧。當我遇到危險時你要來救我——當你遇到危險時，無論我在什麼地方，我都會奔赴到你的身邊，我不會食言的。", "0", "0", "0", "cv_sk_starry_11", "0", "0"},
[4103300111] = {4103300111, 11033001, 12, 6, "0", "0", "Not\u{0020}bad,\u{0020}not\u{0020}bad.", "0", "不錯不錯。", "0", "0", "0", "cv_sk_starry_12", "0", "0"},
[4103300112] = {4103300112, 11033001, 13, 7, "0", "0", "This\u{0020}fits\u{0020}my\u{0020}code\u{0020}name\u{0020}perfectly.", "0", "和我的代號很搭配呢。", "0", "0", "0", "cv_sk_starry_13", "0", "0"},
[4103300113] = {4103300113, 11033001, 14, 8, "0", "0", "Our\u{0020}greedy\u{0020}nature\u{0020}drives\u{0020}us\u{0020}to\u{0020}constantly\u{0020}seek\u{0020}better\u{0020}things,\u{0020}leaving\u{0020}no\u{0020}room\u{0020}for\u{0020}luck\u{0020}to\u{0020}spare\u{0020}us.\u{0020}Mr.\u{0020}Hentai,\u{0020}something\u{0020}bad\u{0020}might\u{0020}happen\u{0020}in\u{0020}the\u{0020}future,\u{0020}but\u{0020}this\u{0020}time,\u{0020}I'll\u{0020}face\u{0020}it\u{0020}with\u{0020}you.", "0", "我們貪婪的本性會讓我們去不斷索取更好的東西，連運氣也不會放過。色狼先生，也許以後會發生不好的事情，但這一次，我會和你共同面對的。", "0", "0", "0", "cv_sk_starry_14", "0", "0"},
[4103300114] = {4103300114, 11033001, 15, 9, "0", "0", "Am\u{0020}I\u{0020}even\u{0020}luckier\u{0020}now?", "0", "我更加幸運了？", "0", "0", "0", "cv_sk_starry_15", "0", "0"},
[4103300115] = {4103300115, 11033001, 16, 10, "0", "0", "What\u{0020}good\u{0020}things\u{0020}await\u{0020}us\u{0020}next?", "0", "接下來會發生什麼好事呢？", "0", "0", "0", "cv_sk_starry_16", "0", "0"},
[4103300116] = {4103300116, 11033001, 17, 11, "0", "0", "Awesome,\u{0020}we\u{0020}won\u{0020}again!", "0", "真好啊，我們又贏了。", "0", "0", "0", "cv_sk_starry_17", "0", "0"},
[4103300117] = {4103300117, 11033001, 18, 12, "0", "0", "Let's\u{0020}confirm\u{0020}the\u{0020}condition\u{0020}of\u{0020}the\u{0020}wounded.", "0", "確認一下傷患狀況吧。", "0", "0", "0", "cv_sk_starry_18", "0", "0"},
