[4103500101] = {4103500101, 11035001, 2, 2, "0", "0", "I\u{0020}never\u{0020}expected\u{0020}we'd\u{0020}have\u{0020}enough\u{0020}freedom\u{0020}for\u{0020}drivers\u{0020}to\u{0020}do\u{0020}things\u{0020}like\u{0020}this!\u{0020}But\u{0020}honestly,\u{0020}I'm\u{0020}loving\u{0020}it!", "0", "真沒想到，如今已經餘裕到可以讓駕駛員做這樣的事了~不過人家並不討厭，倒不如說很中意這份餘裕呢！", "0", "0", "0", "cv_sk_zepar_2", "0", "0"},
[4103500102] = {4103500102, 11035001, 3, 3, "0", "0", "Are\u{0020}you\u{0020}the\u{0020}Navigator\u{0020}Stephanie\u{0020}mentioned?\u{0020}Heehee,\u{0020}I'm\u{0020}Zepar,\u{0020}a\u{0020}proud\u{0020}member\u{0020}of\u{0020}the\u{0020}\"Iron\u{0020}Crow\"\u{0020}team.\u{0020}Just\u{0020}remember\u{0020}to\u{0020}take\u{0020}good\u{0020}care\u{0020}of\u{0020}lovely\u{0020}me!", "0", "你就是史蒂芬妮提過的那位領航嗎？嘻嘻，我是桀派。現在姑且是“鐵鴉”小隊的隊員。之後你可得好好照顧可愛的人家哦。", "0", "0", "0", "cv_sk_zepar_1", "0", "0"},
[4103500103] = {4103500103, 11035001, 4, 4, "0", "idle", "\"Demon\u{0020}of\u{0020}Solomon\"?\u{0020}Ugh,\u{0020}I\u{0020}can't\u{0020}stand\u{0020}that!\u{0020}How\u{0020}could\u{0020}a\u{0020}cute\u{0020}girl\u{0020}like\u{0020}me\u{0020}have\u{0020}such\u{0020}a\u{0020}weird\u{0020}title?\u{0020}You\u{0020}must\u{0020}be\u{0020}mixing\u{0020}me\u{0020}up\u{0020}with\u{0020}someone\u{0020}else!", "0", "“所羅門的魔神”？討厭啦，人家這麼可愛的女孩子，怎麼會有那種奇怪的稱號呢？一定是領航你把人家和不知道的哪個誰弄混了。", "0", "0", "0", "cv_sk_zepar_3", "0", "0"},
[4103500104] = {4103500104, 11035001, 5, 4, "0", "idle", "The\u{0020}changes\u{0020}in\u{0020}AEGIS\u{0020}are\u{0020}incredible...\u{0020}Is\u{0020}this\u{0020}what\u{0020}\"time\"\u{0020}does?\u{0020}I\u{0020}guess\u{0020}I\u{0020}need\u{0020}to\u{0020}step\u{0020}up\u{0020}my\u{0020}game\u{0020}so\u{0020}those\u{0020}juniors\u{0020}don't\u{0020}look\u{0020}down\u{0020}on\u{0020}me!", "0", "艾吉斯的變化真大呢…這就是“時間”嗎？人家是不是也得努力一下，不能讓那些後生小瞧了~", "0", "0", "0", "cv_sk_zepar_4", "0", "0"},
[4103500105] = {4103500105, 11035001, 6, 4, "0", "idle", "\"If\u{0020}you're\u{0020}shy,\u{0020}I'll\u{0020}lead\u{0020}you\u{0020}away\u{0020}with\u{0020}chains.\"\u{0020}Captain\u{0020}Lepani\u{0020}told\u{0020}me\u{0020}that,\u{0020}and\u{0020}even\u{0020}I\u{0020}couldn't\u{0020}say\u{0020}no.\u{0020}But\u{0020}honestly,\u{0020}supporting\u{0020}my\u{0020}teammates\u{0020}like\u{0020}this\u{0020}suits\u{0020}me\u{0020}surprisingly\u{0020}well!", "0", "“您要是害羞的話，我就用鎖鏈領走您了哦？”被萊帕尼隊長這麼說了之後，就算是人家也不好意思拒絕了。不過，像現在這樣為隊友提供支援，意外得很適合人家呢！", "0", "0", "0", "cv_sk_zepar_29", "0", "0"},
[4103500106] = {4103500106, 11035001, 7, 5, "15_2_0_0.8", "level2", "When\u{0020}I'm\u{0020}sleepy,\u{0020}I\u{0020}can\u{0020}sleep\u{0020}as\u{0020}long\u{0020}as\u{0020}I\u{0020}want.\u{0020}When\u{0020}there's\u{0020}food\u{0020}I\u{0020}love,\u{0020}I\u{0020}can\u{0020}eat\u{0020}as\u{0020}much\u{0020}as\u{0020}I\u{0020}want.\u{0020}And\u{0020}when\u{0020}there's\u{0020}someone\u{0020}I\u{0020}want\u{0020}to\u{0020}fall\u{0020}for,\u{0020}I'll\u{0020}go\u{0020}after\u{0020}them\u{0020}boldly.\u{0020}That's\u{0020}my\u{0020}biggest\u{0020}wish\u{0020}right\u{0020}now.\u{0020}Want\u{0020}to\u{0020}know\u{0020}who\u{0020}that\u{0020}special\u{0020}someone\u{0020}is?\u{0020}Hehe,\u{0020}curious,\u{0020}are\u{0020}you?", "0", "困的時候可以想睡多久就睡多久；喜歡的食物想吃多少就可以吃多少；如果有了想要談戀愛的對象，就大膽地去追。這就是人家現在最想做的事情。對方是誰？嘿嘿，這麼想知道麼？", "0", "0", "0", "cv_sk_zepar_30", "0", "0"},
[4103500107] = {4103500107, 11035001, 8, 5, "15_1_0_0.8", "level1", "Hehe.\u{0020}Aren't\u{0020}I\u{0020}adorable?", "0", "呵呵~人家是不是很可愛呀？", "0", "0", "0", "cv_sk_zepar_5", "0", "0"},
[4103500108] = {4103500108, 11035001, 9, 5, "15_1_0_0.8", "level1", "Ahh...\u{0020}This\u{0020}feels\u{0020}amazing.\u{0020}Just\u{0020}chilling\u{0020}and\u{0020}carefree,\u{0020}enjoying\u{0020}our\u{0020}little\u{0020}world\u{0020}together,\u{0020}Navigator.", "0", "哈啊~這種感覺，真好啊。悠悠閑閑的，更別說是和領航一起享受二人世界~", "0", "0", "0", "cv_sk_zepar_6", "0", "0"},
[4103500109] = {4103500109, 11035001, 10, 5, "15_2_0_0.8", "level2", "I'm\u{0020}really\u{0020}worried\u{0020}about\u{0020}your\u{0020}health,\u{0020}Navigator.\u{0020}Remember,\u{0020}nothing\u{0020}matters\u{0020}more\u{0020}than\u{0020}your\u{0020}well-being—honor\u{0020}and\u{0020}money\u{0020}pale\u{0020}in\u{0020}comparison.\u{0020}So\u{0020}when\u{0020}you\u{0020}need\u{0020}to\u{0020}rest,\u{0020}make\u{0020}sure\u{0020}you\u{0020}take\u{0020}the\u{0020}time\u{0020}to\u{0020}do\u{0020}so.", "0", "人家很關心領航你的身體健康哦~跟身體健康比起來，榮譽和金錢都不算什麼了。所以想要休息的時候要好好休息哦。", "0", "0", "0", "cv_sk_zepar_7", "0", "0"},
[4103500110] = {4103500110, 11035001, 11, 5, "15_1_0_0.8", "level1", "\"Zepar\"\u{0020}is\u{0020}both\u{0020}an\u{0020}honor\u{0020}and\u{0020}a\u{0020}burden\u{0020}for\u{0020}me.\u{0020}Even\u{0020}when\u{0020}I\u{0020}try\u{0020}to\u{0020}hide\u{0020}away,\u{0020}it\u{0020}pulls\u{0020}me\u{0020}back\u{0020}to\u{0020}the\u{0020}battlefield.\u{0020}But\u{0020}I\u{0020}have\u{0020}no\u{0020}regrets.\u{0020}It's\u{0020}because\u{0020}everyone\u{0020}needs\u{0020}\"Zepar\"\u{0020}that\u{0020}I\u{0020}got\u{0020}to\u{0020}meet\u{0020}you,\u{0020}Navigator.", "0", "“桀派”……它是我的榮譽，也是我的桎梏。就算我躲到地獄，它也把我拉了回來，趕回戰場上。但是，我並不後悔…至少，正是因為大家需要“桀派”，人家才會和領航相遇呀。", "0", "0", "0", "cv_sk_zepar_8", "0", "0"},
[4103500111] = {4103500111, 11035001, 12, 6, "0", "0", "Thank\u{0020}you\u{0020}so\u{0020}much!\u{0020}", "0", "嘻嘻~謝謝~", "0", "0", "0", "cv_sk_zepar_9", "0", "0"},
[4103500112] = {4103500112, 11035001, 13, 7, "0", "0", "Have\u{0020}I\u{0020}gotten\u{0020}stronger?\u{0020}Is\u{0020}more\u{0020}overtime\u{0020}coming\u{0020}my\u{0020}way?", "0", "變強了嗎…接下來不會要加班吧……", "0", "0", "0", "cv_sk_zepar_10", "0", "0"},
[4103500113] = {4103500113, 11035001, 14, 8, "0", "0", "My\u{0020}feelings\u{0020}are\u{0020}pretty\u{0020}mixed\u{0020}right\u{0020}now.\u{0020}If\u{0020}I'm\u{0020}this\u{0020}valued,\u{0020}I\u{0020}need\u{0020}to\u{0020}perform\u{0020}well\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}right?\u{0020}Okay,\u{0020}I've\u{0020}decided!\u{0020}I'll\u{0020}stay\u{0020}energetic\u{0020}and\u{0020}show\u{0020}you\u{0020}just\u{0020}how\u{0020}powerful\u{0020}the\u{0020}\"Demon\u{0020}of\u{0020}Solomon\"\u{0020}can\u{0020}be!\u{0020}But\u{0020}I\u{0020}can\u{0020}tell\u{0020}you\u{0020}really\u{0020}like\u{0020}me,\u{0020}heehee~♪", "0", "人家現在的心情真的有些複雜，被如此重視的話，不在戰場上好好表現是不行的吧？嗯…好！決定了，人家得拿出幹勁，讓領航你見識一下“所羅門的魔神”有多麼厲害了！……不過領航還真是喜歡人家呢，嘻嘻~♪", "0", "0", "0", "cv_sk_zepar_11", "0", "0"},
[4103500114] = {4103500114, 11035001, 15, 9, "0", "0", "I've\u{0020}got\u{0020}a\u{0020}bad\u{0020}feeling\u{0020}about\u{0020}this...", "0", "我已經有不好的預感啦……", "0", "0", "0", "cv_sk_zepar_12", "0", "0"},
