[4103800101] = {4103800101, 11038001, 2, 2, "0", "0", "Huh?\u{0020}You\u{0020}think\u{0020}I'm\u{0020}suited\u{0020}for\u{0020}this?", "0", "哈？你覺得我適合做這個？", "0", "0", "0", "cv_sk_kafuka_2", "0", "0"},
[4103800102] = {4103800102, 11038001, 3, 3, "0", "0", "I'm\u{0020}Kafka\u{0020}from\u{0020}the\u{0020}\"Astray\u{0020}Blossom\"\u{0020}team.\u{0020}As\u{0020}you\u{0020}can\u{0020}see,\u{0020}I'm\u{0020}a\u{0020}bit\u{0020}of\u{0020}a\u{0020}delinquent.\u{0020}It's\u{0020}not\u{0020}easy\u{0020}to\u{0020}make\u{0020}me\u{0020}obedient,\u{0020}so\u{0020}you\u{0020}should\u{0020}be\u{0020}mentally\u{0020}prepared.", "0", "我是“歧花”小隊的卡芙卡，如你所見是個所謂的不良，想讓我乖乖聽話可不簡單，你應該做好心理準備了吧？", "0", "0", "0", "cv_sk_kafuka_3", "0", "0"},
[4103800103] = {4103800103, 11038001, 4, 4, "0", "idle", "Jelly\u{0020}candies,\u{0020}lollipops,\u{0020}marshmallows...\u{0020}and\u{0020}human\u{0020}essence\u{0020}and\u{0020}souls\u{0020}are\u{0020}the\u{0020}tastiest\u{0020}desserts.", "ゼリーキャンディー、ロリポップ、マシュマロ……あと人間の生気と魂、全部最高に旨いデザートだ。", "啫喱糖、棒棒糖、棉花糖……還有人類的精氣與靈魂，都是最美味的甜點哦。", "0", "0", "0", "cv_sk_kafuka_4", "0", "0"},
[4103800104] = {4103800104, 11038001, 5, 4, "0", "idle", "Another\u{0020}human\u{0020}scared\u{0020}silly\u{0020}by\u{0020}me.\u{0020}The\u{0020}soul\u{0020}just\u{0020}flew\u{0020}away!\u{0020}It's\u{0020}a\u{0020}classic\u{0020}case\u{0020}of\u{0020}being\u{0020}scared\u{0020}out\u{0020}of\u{0020}one's\u{0020}wits.", "またひとり、アタシにビビッて腰を抜かしたやつがいたぜ。魂が目に見えて飛んでたぞ。魂飛魄散ってのは、まさにこのことだな。", "又一個被我嚇傻了的人類啊，靈魂都肉眼可見地飛走了，簡直是字面意思的魂飛魄散。", "0", "0", "0", "cv_sk_kafuka_5", "0", "0"},
[4103800105] = {4103800105, 11038001, 6, 4, "0", "idle", "Believe\u{0020}it\u{0020}or\u{0020}not,\u{0020}I'm\u{0020}the\u{0020}friendliest\u{0020}of\u{0020}the\u{0020}four\u{0020}evil\u{0020}spirits.\u{0020}In\u{0020}the\u{0020}western-style\u{0020}mansion\u{0020}behind\u{0020}us,\u{0020}even\u{0020}more\u{0020}terrifying\u{0020}beings\u{0020}are\u{0020}sleeping.\u{0020}Curious?\u{0020}I\u{0020}suggest\u{0020}you\u{0020}suppress\u{0020}that\u{0020}emotion.", "アタシは四大悪霊の中でも、一番優しい方だぜ。裏の屋敷には、ヤバいヤツが眠ってるからな。…気になるのか？その余計な好奇心、捨てたほうがいいぜ。", "我已經是四大惡靈中最友善的一個了，在後面那棟洋館中還沉睡著更加恐怖的存在。好奇嗎？勸你最好收起這份多餘的情感。", "0", "0", "0", "cv_sk_kafuka_6", "0", "0"},
[4103800106] = {4103800106, 11038001, 7, 5, "15_1_0_0.8", "leve1", "How\u{0020}dare\u{0020}you\u{0020}touch\u{0020}me\u{0020}like\u{0020}that?\u{0020}Aren't\u{0020}you\u{0020}afraid\u{0020}of\u{0020}the\u{0020}curse?\u{0020}What\u{0020}curse?\u{0020}Heh,\u{0020}you'll\u{0020}find\u{0020}out\u{0020}soon\u{0020}enough.", "アタシに触るなんて、呪いが怖くないのか？何の呪いかって？ハッ、すぐにわかるよ。", "竟敢隨便碰我，你不害怕詛咒嗎？什麼詛咒？呵，很快你就會知道了。", "0", "0", "0", "cv_sk_kafuka_7", "0", "0"},
[4103800107] = {4103800107, 11038001, 8, 5, "15_2_0_0.8", "leve2", "Speaking\u{0020}of\u{0020}which,\u{0020}you\u{0020}can\u{0020}actually\u{0020}touch\u{0020}my\u{0020}body.\u{0020}Logically,\u{0020}you\u{0020}should\u{0020}have\u{0020}passed\u{0020}through\u{0020}me.\u{0020}Could\u{0020}it\u{0020}be\u{0020}you\u{0020}possess\u{0020}some\u{0020}sort\u{0020}of\u{0020}special\u{0020}spiritual\u{0020}power?", "そういえば、あんたはアタシの体に触(さわ)れるんだよな。普通なら通り抜けるはずなのに、何か特別な力とか持ってんのか？", "說起來，你居然能觸碰到我的身體，照理來說應該直接從中穿過才對，難道你擁有某種特殊的靈力？", "0", "0", "0", "cv_sk_kafuka_8", "0", "0"},
[4103800108] = {4103800108, 11038001, 9, 5, "15_1_0_0.8", "leve1", "These\u{0020}ghosts\u{0020}around\u{0020}me?\u{0020}They're\u{0020}just\u{0020}people\u{0020}who\u{0020}got\u{0020}lost\u{0020}in\u{0020}this\u{0020}forest\u{0020}and\u{0020}gradually\u{0020}perished...\u{0020}Just\u{0020}kidding!\u{0020}They're\u{0020}actually\u{0020}my\u{0020}summoned\u{0020}familiars.", "アタシの周りにいる幽霊のことか？こいつらは、この森に迷い込んで死んじまった奴らだよ……ってのは冗談で、本当はアタシが召喚した使い魔だ。", "身邊這些幽靈？它們都是曾迷失於這片森林而逐漸死去的人……開個玩笑，其實只是我召喚出的使魔而已。", "0", "0", "0", "cv_sk_kafuka_9", "0", "0"},
[4103800109] = {4103800109, 11038001, 10, 5, "15_2_0_0.8", "leve2", "I'd\u{0020}like\u{0020}to\u{0020}take\u{0020}a\u{0020}look\u{0020}at\u{0020}the\u{0020}items\u{0020}you've\u{0020}brought\u{0020}from\u{0020}the\u{0020}outside\u{0020}world.\u{0020}I've\u{0020}lost\u{0020}track\u{0020}of\u{0020}how\u{0020}long\u{0020}I've\u{0020}been\u{0020}here\u{0020}and\u{0020}how\u{0020}the\u{0020}world\u{0020}outside\u{0020}has\u{0020}changed.", "あんたが持ってる外界の物を見せてくれよ。ずいぶんと長くここにいるから、外の世界がどんな感じになってるのか気になんだよ。", "也把你身上帶著的外界物品給我看看吧，我已經忘了自己在這待了多久，外面的世界又發展成什麼樣了。", "0", "0", "0", "cv_sk_kafuka_10", "0", "0"},
[4103800110] = {4103800110, 11038001, 11, 5, "15_1_0_0.8", "leve1", "Are\u{0020}you\u{0020}still\u{0020}hanging\u{0020}around\u{0020}here?\u{0020}Are\u{0020}you\u{0020}trapped\u{0020}by\u{0020}this\u{0020}forest,\u{0020}or\u{0020}are\u{0020}you\u{0020}enchanted\u{0020}by\u{0020}its\u{0020}tranquility?\u{0020}Either\u{0020}way,\u{0020}feel\u{0020}free\u{0020}to\u{0020}do\u{0020}as\u{0020}you\u{0020}like.\u{0020}I\u{0020}don't\u{0020}mind\u{0020}outsiders\u{0020}like\u{0020}you.", "あんた、まだここにいたのか。この森に囚われたのか？それとも、ここの静かさにハマっちまったのか？まあ、好きにしろよ。あんたみたいなやつは、嫌いじゃないからな。", "你依然徘徊於此，是被這片森林給困住了，還是迷戀上了這份幽靜呢？無論如何，請便吧，我並不討厭你這樣的外來者。", "0", "0", "0", "cv_sk_kafuka_11", "0", "0"},
[4103800111] = {4103800111, 11038001, 12, 6, "0", "0", "Thanks\u{0020}for\u{0020}your\u{0020}help.", "0", "有勞你了。", "0", "0", "0", "cv_sk_kafuka_12", "0", "0"},
[4103800112] = {4103800112, 11038001, 13, 7, "0", "0", "In\u{0020}arcade\u{0020}terms,\u{0020}I\u{0020}just\u{0020}broke\u{0020}the\u{0020}record!", "0", "用街機的說法，就是刷新記錄了。", "0", "0", "0", "cv_sk_kafuka_13", "0", "0"},
[4103800113] = {4103800113, 11038001, 14, 8, "0", "0", "I'm\u{0020}not\u{0020}one\u{0020}to\u{0020}waste\u{0020}words.\u{0020}Besides\u{0020}saying\u{0020}\"thank\u{0020}you,\"\u{0020}I\u{0020}want\u{0020}to\u{0020}repay\u{0020}you\u{0020}practically.", "0", "畢竟我是不愛廢話的性格，除了一聲“謝謝”外，就讓我用更實在的方式回報你吧。", "0", "0", "0", "cv_sk_kafuka_14", "0", "0"},
[4103800114] = {4103800114, 11038001, 15, 9, "0", "0", "Alright,\u{0020}my\u{0020}punch\u{0020}is\u{0020}stronger.", "0", "很好，拳頭更硬了。", "0", "0", "0", "cv_sk_kafuka_15", "0", "0"},
[4103800115] = {4103800115, 11038001, 16, 10, "0", "0", "Let's\u{0020}take\u{0020}out\u{0020}our\u{0020}frustrations\u{0020}on\u{0020}them!", "0", "就拿它們來發洩不滿吧。", "0", "0", "0", "cv_sk_kafuka_16", "0", "0"},
[4103800116] = {4103800116, 11038001, 17, 11, "0", "0", "Humph,\u{0020}that\u{0020}was\u{0020}easy.", "0", "哼，小菜一碟。", "0", "0", "0", "cv_sk_kafuka_17", "0", "0"},
[4103800117] = {4103800117, 11038001, 18, 12, "0", "0", "It's\u{0020}just\u{0020}okay.", "0", "勉勉強強吧。", "0", "0", "0", "cv_sk_kafuka_18", "0", "0"},
[4103800118] = {4103800118, 11038001, 19, 13, "0", "0", "Next\u{0020}time,\u{0020}I'll\u{0020}come\u{0020}back\u{0020}swinging.", "0", "下次得以牙還牙。", "0", "0", "0", "cv_sk_kafuka_19", "0", "0"},
[4103800119] = {4103800119, 11038001, 20, 14, "0", "0", "I\u{0020}won't\u{0020}let\u{0020}even\u{0020}monsters\u{0020}walk\u{0020}all\u{0020}over\u{0020}me.", "0", "可不能連怪物都踩在我頭上。", "0", "0", "0", "cv_sk_kafuka_20", "0", "0"},
[4103800120] = {4103800120, 11038001, 21, 15, "0", "0", "I'm\u{0020}starving.\u{0020}I\u{0020}need\u{0020}to\u{0020}eat.", "因果応報だ！", "餓有餓報。", "0", "0", "0", "cv_sk_kafuka_21", "0", "0"},
[4103800121] = {4103800121, 11038001, 23, 16, "0", "0", "Feel\u{0020}the\u{0020}fear!", "怖がりやがれ！", "感受恐怖吧！", "0", "0", "0", "cv_sk_kafuka_23", "0", "0"},
[4103800122] = {4103800122, 11038001, 24, 17, "0", "0", "You're\u{0020}too\u{0020}loud.", "うるせーな。", "你太吵了。", "0", "0", "0", "cv_sk_kafuka_24", "0", "0"},
[4103800123] = {4103800123, 11038001, 26, 19, "0", "0", "So,\u{0020}have\u{0020}you\u{0020}finally\u{0020}escaped\u{0020}the\u{0020}curse?", "ようやく、呪いから解放されるのか……", "終於從詛咒中解脫了嗎……", "0", "0", "0", "cv_sk_kafuka_25", "0", "0"},
[4103800124] = {4103800124, 11038001, 27, 20, "0", "0", "Oh,\u{0020}you're\u{0020}here?\u{0020}Another\u{0020}driver\u{0020}came\u{0020}in\u{0020}just\u{0020}now,\u{0020}but\u{0020}she\u{0020}got\u{0020}scared\u{0020}and\u{0020}ran\u{0020}off\u{0020}as\u{0020}soon\u{0020}as\u{0020}I\u{0020}showed\u{0020}up.", "0", "你來了？剛才本來還有個駕駛員，一看我進來就被嚇跑了。", "0", "0", "0", "cv_sk_kafuka_26", "0", "0"},
[4103800125] = {4103800125, 11038001, 28, 21, "0", "0", "Do\u{0020}you\u{0020}sing\u{0020}in\u{0020}the\u{0020}shower?\u{0020}I\u{0020}do,\u{0020}but\u{0020}I\u{0020}won't\u{0020}if\u{0020}someone\u{0020}else\u{0020}is\u{0020}around.", "0", "你會在浴室裡唱歌嗎？我雖然會，但旁邊有人的話還是算了。", "0", "0", "0", "cv_sk_kafuka_27", "0", "0"},
[4103800126] = {4103800126, 11038001, 29, 21, "0", "0", "I\u{0020}once\u{0020}got\u{0020}into\u{0020}a\u{0020}fight\u{0020}with\u{0020}some\u{0020}students\u{0020}in\u{0020}the\u{0020}school\u{0020}bathroom,\u{0020}but\u{0020}the\u{0020}floor\u{0020}was\u{0020}so\u{0020}slippery\u{0020}that\u{0020}neither\u{0020}of\u{0020}us\u{0020}could\u{0020}win.", "0", "有次我在學校浴室裡和其他學生打架，但地太滑，誰也沒打贏誰。", "0", "0", "0", "cv_sk_kafuka_28", "0", "0"},
