[4142000131] = {4142000131, 11042001, 31, 23, "0", "0", "Who\u{0020}am\u{0020}I?", "0", "我是……誰？", "0", "0", "0", "cv_sk_hailuo_31", "0", "0"},
[4142000132] = {4142000132, 11042001, 32, 24, "0", "0", "I\u{0020}almost\u{0020}forgot\u{0020}who\u{0020}I\u{0020}was!", "0", "我都差點想不起來我是誰啦！", "0", "0", "0", "cv_sk_hailuo_32", "0", "0"},
[4142000133] = {4142000133, 11042001, 33, 25, "0", "0", "I\u{0020}didn't\u{0020}remember\u{0020}either,\u{0020}haha.", "0", "我也沒想起來，哈哈~", "0", "0", "0", "cv_sk_hailuo_33", "0", "0"},
[4142000134] = {4142000134, 11042001, 34, 26, "0", "0", "Oh,\u{0020}Navigator,\u{0020}you're\u{0020}here!\u{0020}Want\u{0020}to\u{0020}sunbathe\u{0020}together?\u{0020}The\u{0020}sunlight\u{0020}today\u{0020}is\u{0020}perfect.", "0", "噢，領航，你來啦，要一起曬太陽嗎？今天的太陽光可是完美陽光哦。", "0", "0", "0", "cv_sk_hailuo_34", "0", "0"},
[4142000135] = {4142000135, 11042001, 35, 27, "0", "0", "Where\u{0020}are\u{0020}we\u{0020}headed\u{0020}today?\u{0020}Uh,\u{0020}what\u{0020}are\u{0020}we\u{0020}doing?", "0", "今天要去的地方是……哪裡來著？對了，我們要做什麼？", "0", "0", "0", "cv_sk_hailuo_35", "0", "0"},
[4142000136] = {4142000136, 11042001, 36, 28, "0", "0", "As\u{0020}long\u{0020}as\u{0020}I\u{0020}don't\u{0020}have\u{0020}to\u{0020}remember\u{0020}anything,\u{0020}I\u{0020}won't\u{0020}lose\u{0020}to\u{0020}anyone!", "0", "只要不用記東西的話，我誰都不會輸的！", "0", "0", "0", "cv_sk_hailuo_36", "0", "0"},
[4142000137] = {4142000137, 11042001, 37, 29, "0", "0", "Wah\u{0020}wah\u{0020}wah,\u{0020}there\u{0020}are\u{0020}so\u{0020}many\u{0020}people!\u{0020}I\u{0020}can't\u{0020}keep\u{0020}track\u{0020}of\u{0020}all\u{0020}their\u{0020}names...", "0", "哇哇哇，好多人，我記不住名字的啦……", "0", "0", "0", "cv_sk_hailuo_37", "0", "0"},
[4142000138] = {4142000138, 11042001, 38, 30, "0", "0", "Newcomer?\u{0020}Does\u{0020}that\u{0020}mean\u{0020}I'll\u{0020}be\u{0020}a\u{0020}senior\u{0020}now?", "0", "新人？我要當前輩了？", "0", "0", "0", "cv_sk_hailuo_38", "0", "0"},
[4142000139] = {4142000139, 11042001, 39, 31, "0", "0", "I\u{0020}trust\u{0020}my\u{0020}fists\u{0020}more\u{0020}than\u{0020}anything!", "0", "我更加信賴自己的拳頭！", "0", "0", "0", "cv_sk_hailuo_39", "0", "0"},
[4142000140] = {4142000140, 11042001, 40, 32, "0", "0", "My\u{0020}eyes\u{0020}can't\u{0020}keep\u{0020}up!", "0", "眼睛看不過來了！", "0", "0", "0", "cv_sk_hailuo_40", "0", "0"},
