[4142000143] = {4142000143, 11042001, 43, 35, "0", "0", "A\u{0020}bad\u{0020}pen\u{0020}is\u{0020}better\u{0020}than\u{0020}a\u{0020}good\u{0020}memory.", "0", "好記性不如爛筆頭~", "0", "0", "0", "cv_sk_hailuo_43", "0", "0"},
[4142000144] = {4142000144, 11042001, 44, 36, "0", "0", "I'm\u{0020}Kyla\u{0020}from\u{0020}Chesterton!", "0", "我是來自切斯頓的海蘿！", "0", "0", "0", "cv_sk_hailuo_44", "0", "0"},
[4142000145] = {4142000145, 11042001, 45, 37, "0", "0", "What's\u{0020}up?", "0", "咋啦？", "0", "0", "0", "cv_sk_hailuo_45", "0", "0"},
[4143000100] = {4143000100, 11043001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_sk_mila_1", "0", "0"},
[4143000101] = {4143000101, 11043001, 2, 2, "0", "0", "More\u{0020}chances\u{0020}to\u{0020}preach?", "0", "能有更多傳教機會了？", "0", "0", "0", "cv_sk_mila_2", "0", "0"},
[4143000102] = {4143000102, 11043001, 3, 3, "0", "0", "Hello\u{0020}Navigator,\u{0020}I'm\u{0020}Mira,\u{0020}bishop\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Diocese~\u{0020}Haha,\u{0020}does\u{0020}my\u{0020}tone\u{0020}not\u{0020}sound\u{0020}like\u{0020}a\u{0020}clergy?\u{0020}It\u{0020}seems\u{0020}your\u{0020}understanding\u{0020}is\u{0020}a\u{0020}bit\u{0020}outdated;\u{0020}the\u{0020}Saint\u{0020}Wash\u{0020}Church\u{0020}is\u{0020}constantly\u{0020}moving\u{0020}forward\u{0020}like\u{0020}a\u{0020}rushing\u{0020}stream.", "0", "你好啊領航，我是多瑙教區的主教米菈~呵呵，感覺我的語調不太像一名神職？看來你的瞭解有些滯後了，聖濯教會可是如奔流般與時俱進的哦。", "0", "0", "0", "cv_sk_mila_3", "0", "0"},
[4143000103] = {4143000103, 11043001, 4, 4, "0", "idle", "People\u{0020}once\u{0020}imagined\u{0020}the\u{0020}form\u{0020}of\u{0020}God,\u{0020}and\u{0020}some\u{0020}thought\u{0020}He\u{0020}was\u{0020}as\u{0020}massive\u{0020}as\u{0020}I\u{0020}am\u{0020}now.\u{0020}Yet,\u{0020}standing\u{0020}here,\u{0020}overlooking\u{0020}the\u{0020}earth,\u{0020}I\u{0020}can't\u{0020}help\u{0020}but\u{0020}feel\u{0020}how\u{0020}limited\u{0020}human\u{0020}imagination\u{0020}is.", "0", "古人們曾想像神的模樣，有人認為神就如同我現在這般巨大，然而矗立在此俯瞰著大地，我不由得感到人類的想像力是那麼貧弱。", "0", "0", "0", "cv_sk_mila_4", "0", "0"},
[4143000104] = {4143000104, 11043001, 5, 4, "0", "idle", "Preaching\u{0020}with\u{0020}such\u{0020}a\u{0020}huge\u{0020}body\u{0020}here\u{0020}must\u{0020}have\u{0020}quite\u{0020}the\u{0020}effect,\u{0020}don't\u{0020}you\u{0020}think,\u{0020}Navigator?\u{0020}Hmm?\u{0020}Not\u{0020}allowed?\u{0020}Really\u{0020}can't\u{0020}do\u{0020}it?", "0", "在這種地方以巨大化的軀體宣說教義，想必能起到非常不錯的傳教效果，領航覺得呢？唔，不允許嗎？真的不行嗎？", "0", "0", "0", "cv_sk_mila_5", "0", "0"},
[4143000105] = {4143000105, 11043001, 6, 4, "0", "idle", "Ophelia\u{0020}and\u{0020}Celesia\u{0020}are\u{0020}such\u{0020}diligent\u{0020}and\u{0020}pure\u{0020}kids.\u{0020}When\u{0020}you're\u{0020}with\u{0020}them,\u{0020}Navigator,\u{0020}remember\u{0020}not\u{0020}to\u{0020}bully\u{0020}them\u{0020}too\u{0020}much.", "0", "奧菲利亞和塞蕾希婭都是相當努力又單純的孩子，領航跟她們相處時，可要記得不能欺負得太過哦。", "0", "0", "0", "cv_sk_mila_6", "0", "0"},
[4143000106] = {4143000106, 11043001, 7, 5, "15_1_0_0.8", "level1", "Simply\u{0020}reflecting\u{0020}inwardly\u{0020}and\u{0020}praying\u{0020}in\u{0020}silence\u{0020}won't\u{0020}bring\u{0020}miracles.\u{0020}For\u{0020}our\u{0020}respective\u{0020}beliefs,\u{0020}let's\u{0020}march\u{0020}forward\u{0020}more\u{0020}boldly\u{0020}together.", "0", "只是內斂自省、埋頭祈禱的話，奇跡可是不會自己降臨的，為了我們各自的信念，一起更加大膽地昂首向前吧。", "0", "0", "0", "cv_sk_mila_7", "0", "0"},
[4143000107] = {4143000107, 11043001, 8, 5, "15_1_0_0.8", "level1", "The\u{0020}organ's\u{0020}range\u{0020}is\u{0020}vast,\u{0020}and\u{0020}its\u{0020}grandeur,\u{0020}the\u{0020}sound\u{0020}produced\u{0020}by\u{0020}air\u{0020}currents,\u{0020}is\u{0020}like\u{0020}a\u{0020}chorus\u{0020}of\u{0020}the\u{0020}faithful.\u{0020}Navigator,\u{0020}is\u{0020}your\u{0020}synesthesia\u{0020}also\u{0020}like\u{0020}faith,\u{0020}uniting\u{0020}people's\u{0020}hearts\u{0020}from\u{0020}the\u{0020}depths?", "0", "管風琴音域寬廣，規模宏大，氣流振鳴所發出的樂聲猶如信眾們的整齊合唱。領航你的通感，是不是也能和信仰一樣，讓人們發自真心地意念合一呢？", "0", "0", "0", "cv_sk_mila_8", "0", "0"},
[4143000108] = {4143000108, 11043001, 9, 5, "15_2_0_0.8", "level2", "The\u{0020}Holy\u{0020}Church\u{0020}isn't\u{0020}a\u{0020}rigid,\u{0020}old-fashioned\u{0020}group.\u{0020}In\u{0020}fact,\u{0020}our\u{0020}doctrine\u{0020}has\u{0020}always\u{0020}evolved\u{0020}with\u{0020}the\u{0020}times.\u{0020}If\u{0020}you're\u{0020}interested,\u{0020}Navigator,\u{0020}why\u{0020}not\u{0020}visit\u{0020}the\u{0020}church\u{0020}for\u{0020}a\u{0020}good\u{0020}sermon\u{0020}on\u{0020}the\u{0020}next\u{0020}worship\u{0020}day?", "0", "聖濯教會並不是那種頑固的守舊派，我們教義的細節其實一直隨著時代演變、革新，領航若有興趣，禮拜之日不妨來教堂好好傾聽一下。", "0", "0", "0", "cv_sk_mila_9", "0", "0"},
[4143000109] = {4143000109, 11043001, 10, 5, "15_2_0_0.8", "level2", "Just\u{0020}as\u{0020}prophecies\u{0020}tend\u{0020}to\u{0020}fulfill\u{0020}themselves,\u{0020}faith\u{0020}has\u{0020}a\u{0020}miraculous\u{0020}power.\u{0020}If\u{0020}you\u{0020}believe,\u{0020}it\u{0020}will\u{0020}come\u{0020}true.\u{0020}My\u{0020}actions\u{0020}are\u{0020}a\u{0020}result\u{0020}of\u{0020}this\u{0020}steadfast\u{0020}belief;\u{0020}they\u{0020}allow\u{0020}me\u{0020}to\u{0020}help\u{0020}people\u{0020}without\u{0020}hesitation.", "0", "如同預言往往會自我實現，信仰也擁有神奇的力量，只要你相信，它就將成真。而我的行動正是這種篤信的產物，它能讓我心無旁騖地幫助人們。", "0", "0", "0", "cv_sk_mila_10", "0", "0"},
[4143000110] = {4143000110, 11043001, 11, 5, "15_1_0_0.8", "level1", "Oh,\u{0020}does\u{0020}Navigator\u{0020}like\u{0020}communicating\u{0020}through\u{0020}touch?\u{0020}Then\u{0020}lean\u{0020}in\u{0020}a\u{0020}little\u{0020}closer...\u{0020}Now,\u{0020}can\u{0020}you\u{0020}hear\u{0020}clearly?\u{0020}The\u{0020}pulse\u{0020}is\u{0020}the\u{0020}torrent\u{0020}of\u{0020}life,\u{0020}and\u{0020}the\u{0020}heartbeat\u{0020}beats\u{0020}as\u{0020}a\u{0020}drum\u{0020}for\u{0020}you.", "0", "哎呀，領航喜歡經由肌膚與人交流？那麼可以將腦袋再貼近些……現在，能仔細聽見嗎？脈搏是生命的激流，心跳則是為你而鳴響的戰鼓。", "0", "0", "0", "cv_sk_mila_11", "0", "0"},
