[4200100103] = {4200100103, 12001001, 4, 4, "0", "idle", "Um,\u{0020}I'm\u{0020}so\u{0020}sleepy.\u{0020}The\u{0020}side\u{0020}effects\u{0020}of\u{0020}abusing\u{0020}star\u{0020}magic\u{0020}are\u{0020}way\u{0020}too\u{0020}obvious.", "うぅ、眠い……明らかに星空魔法を使い過ぎた副作用だねー、これは。", "唔，好睏……濫用星空魔法的副作用也太明顯了。", "0", "0", "0", "cv_sk_jing_3", "0", "0"},
[4200100104] = {4200100104, 12001001, 5, 4, "0", "idle", "If\u{0020}you're\u{0020}feeling\u{0020}sleepy\u{0020}too,\u{0020}you\u{0020}can\u{0020}lie\u{0020}down\u{0020}and\u{0020}rest\u{0020}here.\u{0020}Don't\u{0020}worry—those\u{0020}monsters\u{0020}won't\u{0020}dare\u{0020}come\u{0020}near\u{0020}me.", "眠かったら、ここで横になってもいいよー。大丈夫。あの魔物たちは私に近づこうとしないから。", "如果你也很睏，在這裡躺下就睡也可以。放心，那些魔物不敢接近我的。", "0", "0", "0", "cv_sk_jing_4", "0", "0"},
[4200100105] = {4200100105, 12001001, 6, 5, "15_1_0_0.8", "level1", "Let\u{0020}me\u{0020}check\u{0020}on\u{0020}my\u{0020}sister.\u{0020}Hasn't\u{0020}she\u{0020}given\u{0020}up\u{0020}on\u{0020}searching\u{0020}for\u{0020}me\u{0020}yet?\u{0020}She\u{0020}can\u{0020}handle\u{0020}reviving\u{0020}star\u{0020}magic\u{0020}on\u{0020}her\u{0020}own.\u{0020}Why\u{0020}does\u{0020}she\u{0020}keep\u{0020}insisting\u{0020}on\u{0020}doing\u{0020}it\u{0020}together?", "（魔法で遠くを見て）姉ちゃんは何してるのかなーっと……あれ、まだ私を探してんの？星空魔法の復興なんて姉ちゃんひとりでいいじゃん。どうして私まで一緒にやんなきゃいけないのー。", "讓我看看姐姐在幹什麼……呃，居然還沒放棄找我嗎？復興星空魔法的事交給她一個人就好了，為什麼非要找我一起。", "0", "0", "0", "cv_sk_jing_30", "0", "0"},
[4200100106] = {4200100106, 12001001, 7, 5, "15_2_0_0.8", "level2", "If\u{0020}there's\u{0020}nothing\u{0020}urgent,\u{0020}please\u{0020}let\u{0020}me\u{0020}rest.\u{0020}If\u{0020}there\u{0020}is\u{0020}something,\u{0020}then\u{0020}you'll\u{0020}need\u{0020}to\u{0020}offer\u{0020}the\u{0020}commission\u{0020}deposit\u{0020}first.", "用事がないなら休憩は邪魔しないでー。用事があるなら前金払いねー。", "沒有事的話，就不要打擾我休息了。如果有事的話，那就先把委託定金獻上吧~", "0", "0", "0", "cv_sk_jing_5", "0", "0"},
[4200100107] = {4200100107, 12001001, 8, 5, "15_1_0_0.8", "level3", "Are\u{0020}you\u{0020}underestimating\u{0020}me?\u{0020}I'm\u{0020}a\u{0020}powerful\u{0020}magician\u{0020}known\u{0020}as\u{0020}\"The\u{0020}Silent\u{0020}Star\u{0020}Summoner,\"\u{0020}and\u{0020}I\u{0020}can\u{0020}cast\u{0020}high-level\u{0020}magic\u{0020}without\u{0020}any\u{0020}incantations.", "私のこと舐めてない？これでも星空魔法をマスターした大魔法使い……人呼んで「静謐なる星呼び」だよー？詠唱なしで高等魔法が使えるんだから。", "你是在小瞧我嗎？我可是掌握著星空魔法的大魔法師，人稱“靜謐的喚星者”，無詠唱就能使用高階魔法哦。", "0", "0", "0", "cv_sk_jing_31", "0", "0"},
[4200100108] = {4200100108, 12001001, 9, 5, "15_2_0_0.8", "level4", "Wondering\u{0020}why\u{0020}I'm\u{0020}in\u{0020}a\u{0020}place\u{0020}like\u{0020}this?\u{0020}It's\u{0020}simple—the\u{0020}ordinary\u{0020}world\u{0020}is\u{0020}just\u{0020}too\u{0020}noisy.\u{0020}If\u{0020}only\u{0020}your\u{0020}voice\u{0020}filled\u{0020}the\u{0020}world,\u{0020}it\u{0020}would\u{0020}be\u{0020}perfect\u{0020}like\u{0020}this.", "どうしてこんな場所にいるのかって？別にいーじゃん。世の中が騒がしすぎるんだよー。今みたいに、世界であんたの声しかしないといいんだけどなー。", "你問我為什麼會在這種地方？別想多了，只是凡間太吵鬧了而已，要是世上只有你一個人的聲音，就像現在這樣倒還算好。", "0", "0", "0", "cv_sk_jing_6", "0", "0"},
[4200100109] = {4200100109, 12001001, 10, 5, "15_1_0_0.8", "level5", "Since\u{0020}you\u{0020}always\u{0020}bring\u{0020}me\u{0020}such\u{0020}valuable\u{0020}treasures,\u{0020}I'll\u{0020}give\u{0020}you\u{0020}a\u{0020}free\u{0020}service\u{0020}today.\u{0020}What\u{0020}monster\u{0020}do\u{0020}you\u{0020}want\u{0020}me\u{0020}to\u{0020}take\u{0020}care\u{0020}of?\u{0020}Or\u{0020}would\u{0020}you\u{0020}like\u{0020}me\u{0020}to\u{0020}be\u{0020}your\u{0020}bodyguard\u{0020}for\u{0020}a\u{0020}day?", "いつもお宝を沢山持って来てくれるから、今日は１回だけタダで動いてあげよー。何がいい？やっつけたい魔物がいる？それとも、１日護衛に着いて欲しい？", "看你總是為我帶來那麼多財寶，今天就免費贈送一次服務好了。說吧，想要我解決什麼魔物？還是想讓我作為護衛陪你一天？", "0", "0", "0", "cv_sk_jing_7", "0", "0"},
[4200100110] = {4200100110, 12001001, 11, 5, "15_2_0_0.8", "level6", "Remember,\u{0020}we're\u{0020}only\u{0020}in\u{0020}a\u{0020}simple\u{0020}cooperative\u{0020}relationship.\u{0020}Don't\u{0020}forget\u{0020}that!\u{0020}But\u{0020}you\u{0020}know,\u{0020}I've\u{0020}changed\u{0020}my\u{0020}mind\u{0020}a\u{0020}bit.\u{0020}Why\u{0020}not\u{0020}just\u{0020}live\u{0020}with\u{0020}me\u{0020}in\u{0020}the\u{0020}eternal\u{0020}starry\u{0020}sky?", "私達の関係はただのビジネス……だったはずだけど、考えが変わっちゃった。いっそのことこのまま私と一緒に、永遠の星空の中で暮らしてみない？", "我們只是單純的合作關係……這點你沒忘吧？不過，雖說我最初是那麼說的，但現在我改變想法了。你乾脆就這樣和我住在永恆的星空中，如何？", "0", "0", "0", "cv_sk_jing_8", "0", "0"},
[4200100111] = {4200100111, 12001001, 12, 6, "0", "0", "Level\u{0020}up!\u{0020}Wait,\u{0020}isn't\u{0020}this\u{0020}a\u{0020}video\u{0020}game?", "0", "leveup！哎？不是電子遊戲嗎？", "0", "0", "0", "cv_sk_jing_9", "0", "0"},
[4200100112] = {4200100112, 12001001, 13, 7, "0", "0", "Is\u{0020}this\u{0020}what\u{0020}they\u{0020}mean\u{0020}by\u{0020}gaining\u{0020}weight\u{0020}just\u{0020}by\u{0020}drinking\u{0020}water?", "0", "這就是所謂喝水也能長胖嗎？", "0", "0", "0", "cv_sk_jing_10", "0", "0"},
[4200100113] = {4200100113, 12001001, 14, 8, "0", "0", "Please\u{0020}spare\u{0020}me\u{0020}this\u{0020}one.\u{0020}I'd\u{0020}rather\u{0020}stay\u{0020}at\u{0020}home\u{0020}than\u{0020}fight.\u{0020}But\u{0020}I\u{0020}can't\u{0020}keep\u{0020}eating\u{0020}for\u{0020}free\u{0020}from\u{0020}you\u{0020}for\u{0020}too\u{0020}long—let's\u{0020}get\u{0020}some\u{0020}exercise\u{0020}instead!", "0", "只有這個還請饒了我吧……比起戰鬥我更加喜歡待在家裏……但是也不能白吃你這麼久，還是稍微運動下吧～", "0", "0", "0", "cv_sk_jing_11", "0", "0"},
[4200100114] = {4200100114, 12001001, 15, 9, "0", "0", "Oh\u{0020}no!\u{0020}My\u{0020}weight\u{0020}has\u{0020}gone\u{0020}up!", "0", "噢——！體重增加了！", "0", "0", "0", "cv_sk_jing_12", "0", "0"},
[4200100115] = {4200100115, 12001001, 16, 10, "0", "0", "So\u{0020}troublesome...", "0", "真麻煩啊……", "0", "0", "0", "cv_sk_jing_13", "0", "0"},
[4200100116] = {4200100116, 12001001, 17, 11, "0", "0", "Everyone\u{0020}except\u{0020}me\u{0020}has\u{0020}been\u{0020}working\u{0020}hard.", "0", "除了我之外的大家辛苦啦～", "0", "0", "0", "cv_sk_jing_14", "0", "0"},
[4200100117] = {4200100117, 12001001, 18, 12, "0", "0", "I'm\u{0020}so\u{0020}tired—I'm\u{0020}about\u{0020}to\u{0020}collapse!", "0", "好累——要死了——", "0", "0", "0", "cv_sk_jing_15", "0", "0"},
[4200100118] = {4200100118, 12001001, 19, 13, "0", "0", "Bed…Get\u{0020}me\u{0020}a\u{0020}bed\u{0020}quickly...", "0", "床……快給我來張床……", "0", "0", "0", "cv_sk_jing_16", "0", "0"},
[4200100119] = {4200100119, 12001001, 20, 14, "0", "0", "I\u{0020}suppose\u{0020}this\u{0020}is\u{0020}inevitable\u{0020}since\u{0020}I'm\u{0020}here...", "0", "這也是必然的吧，畢竟有我在呢……", "0", "0", "0", "cv_sk_jing_17", "0", "0"},
[4200100120] = {4200100120, 12001001, 21, 15, "0", "0", "The\u{0020}commission\u{0020}is\u{0020}complete!", "任務完了ー。", "委託完成~", "0", "0", "0", "cv_sk_jing_18", "0", "0"},
[4200100121] = {4200100121, 12001001, 23, 16, "0", "0", "Look,\u{0020}a\u{0020}star\u{0020}has\u{0020}fallen.", "見て、星が降って来るよ。", "看，星星掉下來了。", "0", "0", "0", "cv_sk_jing_19", "0", "0"},
[4200100122] = {4200100122, 12001001, 22, 38, "0", "0", "Don't\u{0020}worry.", "焦っちゃダメダメ。", "不要著急。", "0", "0", "0", "cv_sk_jing_20", "0", "0"},
