[4200100124] = {4200100124, 12001001, 27, 20, "0", "0", "Ah,\u{0020}what\u{0020}a\u{0020}pity!\u{0020}Now\u{0020}that\u{0020}I'm\u{0020}this\u{0020}size,\u{0020}I\u{0020}can't\u{0020}eat\u{0020}and\u{0020}wash\u{0020}up\u{0020}at\u{0020}the\u{0020}same\u{0020}time.", "0", "啊——好可惜，變成這個大小之後就沒法邊吃邊洗了啊。", "0", "0", "0", "cv_sk_jing_23", "0", "0"},
[4200100125] = {4200100125, 12001001, 28, 21, "0", "0", "Yawn—I'm\u{0020}about\u{0020}to\u{0020}fall\u{0020}asleep.", "0", "呼呼呼——要睡著了哦。", "0", "0", "0", "cv_sk_jing_24", "0", "0"},
