[4200100130] = {4200100130, 12001001, 33, 25, "0", "0", "Aiya,\u{0020}it\u{0020}seems\u{0020}you\u{0020}guessed\u{0020}wrong.\u{0020}As\u{0020}a\u{0020}punishment,\u{0020}I'll\u{0020}eat\u{0020}you!", "0", "哎呀呀，看來你猜錯了呢，作為懲罰就把你吃掉吧～", "0", "0", "0", "cv_sk_jing_29", "0", "0"},
[4200100131] = {4200100131, 12001001, 34, 26, "0", "0", "Have\u{0020}you\u{0020}come\u{0020}to\u{0020}see\u{0020}me\u{0020}again?\u{0020}What's\u{0020}the\u{0020}matter\u{0020}this\u{0020}time,\u{0020}and\u{0020}what\u{0020}reward\u{0020}have\u{0020}you\u{0020}prepared?", "また私に会いに来たの？それで、どんな仕事？いくらぐらい用意して来たのかな～？", "又來見我了嗎？這次所為何事，準備了多少報酬~？", "0", "0", "0", "cv_sk_jing_32", "0", "0"},
[4200100132] = {4200100132, 12001001, 35, 27, "0", "0", "Full\u{0020}of\u{0020}energy!\u{0020}Let's\u{0020}clear\u{0020}this\u{0020}in\u{0020}one\u{0020}go!", "0", "幹勁十足，一口氣通關吧！", "0", "0", "0", "cv_sk_jing_34", "0", "0"},
