[4200100141] = {4200100141, 12001001, 44, 36, "0", "0", "Don't\u{0020}flaunt\u{0020}your\u{0020}cards\u{0020}on\u{0020}the\u{0020}public\u{0020}screen.", "0", "不要在公屏曬卡哦。", "0", "0", "0", "cv_sk_jing_43", "0", "0"},
