[4200200101] = {4200200101, 12002001, 2, 2, "0", "0", "I'm\u{0020}definitely\u{0020}not\u{0020}a\u{0020}good\u{0020}example!", "0", "我可不是什麼好榜樣喔～", "0", "0", "0", "cv_sk_shiranui_2", "0", "0"},
[4200200102] = {4200200102, 12002001, 3, 3, "0", "0", "Hello,\u{0020}I'm\u{0020}Shiranui\u{0020}of\u{0020}Fuurinkazan.\u{0020}I've\u{0020}heard\u{0020}there\u{0020}are\u{0020}many\u{0020}lovely\u{0020}girls\u{0020}here,\u{0020}so\u{0020}let's\u{0020}see\u{0020}for\u{0020}ourselves.", "0", "你好，我是風林火山的不知火，聽說這裡有很多可愛的女孩子，就讓我來確認下吧。", "0", "0", "0", "cv_sk_shiranui_1", "0", "0"},
[4200200103] = {4200200103, 12002001, 4, 4, "0", "idle", "The\u{0020}stronger\u{0020}someone\u{0020}is,\u{0020}the\u{0020}more\u{0020}they\u{0020}tend\u{0020}to\u{0020}fear\u{0020}the\u{0020}existence\u{0020}of\u{0020}those\u{0020}who\u{0020}are\u{0020}even\u{0020}stronger.\u{0020}In\u{0020}contrast,\u{0020}the\u{0020}weak\u{0020}usually\u{0020}don't\u{0020}make\u{0020}a\u{0020}fuss\u{0020}about\u{0020}it.\u{0020}It's\u{0020}quite\u{0020}an\u{0020}interesting\u{0020}phenomenon.", "0", "越是強者，就越會忌憚比自己更強的存在，而弱者往往不會那樣大驚小怪，這真是個有趣的現象。", "0", "0", "0", "cv_sk_shiranui_3", "0", "0"},
[4200200104] = {4200200104, 12002001, 5, 4, "0", "idle", "Standing\u{0020}before\u{0020}my\u{0020}towering\u{0020}form\u{0020}of\u{0020}over\u{0020}a\u{0020}hundred\u{0020}feet,\u{0020}do\u{0020}you\u{0020}feel\u{0020}more\u{0020}scared\u{0020}or\u{0020}excited,\u{0020}Navigator?", "0", "在我這副百尺有餘的身軀面前……領航感到的更多是害怕，還是激動呢？", "0", "0", "0", "cv_sk_shiranui_4", "0", "0"},
[4200200105] = {4200200105, 12002001, 6, 4, "0", "idle", "The\u{0020}miko\u{0020}from\u{0020}the\u{0020}Shingyou\u{0020}House\u{0020}constantly\u{0020}tries\u{0020}to\u{0020}drive\u{0020}me\u{0020}away,\u{0020}claiming\u{0020}it's\u{0020}to\u{0020}exorcise\u{0020}evil\u{0020}spirits.\u{0020}But\u{0020}really,\u{0020}she\u{0020}just\u{0020}wants\u{0020}you\u{0020}all\u{0020}to\u{0020}herself.", "0", "心經屋的巫女小姐總是試圖以驅邪退魔之名將我從你身邊趕走，但在我看來，那孩子分明只是想獨佔你呢。", "0", "0", "0", "cv_sk_shiranui_30", "0", "0"},
[4200200106] = {4200200106, 12002001, 7, 5, "15_2_0_0.8", "level2", "Ah,\u{0020}we've\u{0020}finally\u{0020}found\u{0020}a\u{0020}secluded\u{0020}spot\u{0020}where\u{0020}no\u{0020}one\u{0020}else\u{0020}is\u{0020}around.\u{0020}Here,\u{0020}Navigator,\u{0020}don't\u{0020}even\u{0020}think\u{0020}about\u{0020}calling\u{0020}for\u{0020}help.\u{0020}Just\u{0020}surrender\u{0020}to\u{0020}me,\u{0020}and\u{0020}I'll\u{0020}absorb\u{0020}your\u{0020}yang\u{0020}energy\u{0020}completely!", "0", "呼呼，终于來到了四下無人的僻靜之處，在這裡領航可不要想著向誰呼救哦，乖乖束手就擒，讓我充分吸收你的陽氣吧~", "0", "0", "0", "cv_sk_shiranui_31", "0", "0"},
[4200200107] = {4200200107, 12002001, 8, 5, "15_1_0_0.8", "level1", "Urban\u{0020}legends\u{0020}are\u{0020}often\u{0020}just\u{0020}humans\u{0020}scaring\u{0020}themselves.\u{0020}Look\u{0020}at\u{0020}these\u{0020}little\u{0020}creatures;\u{0020}they're\u{0020}not\u{0020}afraid\u{0020}of\u{0020}me\u{0020}at\u{0020}all,\u{0020}are\u{0020}they?", "0", "所謂都市傳說，很多時候只是人類自己吓自己，你看這些單純的小動物不就絲毫不懼怕我嗎？", "0", "0", "0", "cv_sk_shiranui_5", "0", "0"},
[4200200108] = {4200200108, 12002001, 9, 5, "15_1_0_0.8", "level1", "My\u{0020}heart\u{0020}is\u{0020}racing,\u{0020}sending\u{0020}every\u{0020}throb\u{0020}through\u{0020}my\u{0020}skin.\u{0020}This\u{0020}flimsy\u{0020}clothing\u{0020}can\u{0020}barely\u{0020}contain\u{0020}it.\u{0020}Won't\u{0020}the\u{0020}lovely\u{0020}Navigator\u{0020}come\u{0020}and\u{0020}feel\u{0020}it?", "0", "姐姐我啊，心臟正狂蹦亂跳著，將每一刻悸動傳向肌膚，這身薄薄的衣物都要承受不住了。可愛的領航不來感受下嗎？", "0", "0", "0", "cv_sk_shiranui_6", "0", "0"},
[4200200109] = {4200200109, 12002001, 10, 5, "15_1_0_0.8", "level1", "If\u{0020}you're\u{0020}feeling\u{0020}tired,\u{0020}you\u{0020}can\u{0020}rest\u{0020}on\u{0020}me\u{0020}for\u{0020}a\u{0020}while.\u{0020}Whether\u{0020}it's\u{0020}on\u{0020}my\u{0020}palm,\u{0020}my\u{0020}hat,\u{0020}my\u{0020}waist,\u{0020}or\u{0020}somewhere\u{0020}softer,\u{0020}it's\u{0020}your\u{0020}choice!", "0", "如果感到有些累了，可以坐在我的身上休息一會兒。至於是坐在手心裡、帽子上、腰間，還是更加柔軟舒適的地方，就由你來決定吧~", "0", "0", "0", "cv_sk_shiranui_7", "0", "0"},
[4200200110] = {4200200110, 12002001, 11, 5, "15_1_0_0.8", "level1", "As\u{0020}we\u{0020}stroll\u{0020}through\u{0020}these\u{0020}endless\u{0020}fields,\u{0020}our\u{0020}path\u{0020}seems\u{0020}never-ending.\u{0020}Wouldn't\u{0020}it\u{0020}be\u{0020}wonderful\u{0020}to\u{0020}become\u{0020}a\u{0020}lasting\u{0020}legend\u{0020}together?", "0", "漫步在一望無際的田野間，我們二人的道路好似走不到盡頭。如果能夠就這麼成為悠遠雋永的傳說，是不是也不錯呢？", "0", "0", "0", "cv_sk_shiranui_8", "0", "0"},
[4200200111] = {4200200111, 12002001, 12, 6, "0", "0", "Feeling\u{0020}stronger\u{0020}is\u{0020}incredible!", "0", "變強的感覺……真不錯啊。", "0", "0", "0", "cv_sk_shiranui_9", "0", "0"},
[4200200112] = {4200200112, 12002001, 13, 7, "0", "0", "This\u{0020}way,\u{0020}attracting\u{0020}adorable\u{0020}kids\u{0020}will\u{0020}be\u{0020}even\u{0020}easier,\u{0020}right?", "0", "這樣一來就更加容易吸引到可愛的孩子了吧？", "0", "0", "0", "cv_sk_shiranui_10", "0", "0"},
[4200200113] = {4200200113, 12002001, 14, 8, "0", "0", "Hehehe,\u{0020}I\u{0020}didn't\u{0020}expect\u{0020}you\u{0020}to\u{0020}care\u{0020}so\u{0020}much\u{0020}about\u{0020}me.\u{0020}How\u{0020}should\u{0020}I\u{0020}spoil\u{0020}you\u{0020}next?", "0", "呵呵呵，沒想到你這麼在意姐姐啊。那麼接下來該如何疼愛你呢？", "0", "0", "0", "cv_sk_shiranui_11", "0", "0"},
[4200200114] = {4200200114, 12002001, 15, 9, "0", "0", "Hiyah!\u{0020}Wow,\u{0020}this\u{0020}bow\u{0020}is\u{0020}amazing!", "0", "喝啊！哼，真是一把好弓啊。", "0", "0", "0", "cv_sk_shiranui_12", "0", "0"},
