[4200200131] = {4200200131, 12002001, 33, 25, "0", "0", "Navigator,\u{0020}you\u{0020}got\u{0020}it\u{0020}wrong,\u{0020}but\u{0020}you're\u{0020}still\u{0020}so\u{0020}cute!", "0", "猜錯的領航也好可愛啊～", "0", "0", "0", "cv_sk_shiranui_29", "0", "0"},
[4200200132] = {4200200132, 12002001, 34, 26, "0", "0", "You\u{0020}woke\u{0020}up\u{0020}again!\u{0020}But\u{0020}take\u{0020}a\u{0020}little\u{0020}more\u{0020}time\u{0020}to\u{0020}rest.\u{0020}We\u{0020}still\u{0020}have\u{0020}to\u{0020}continue\u{0020}playing\u{0020}and\u{0020}enjoy\u{0020}this\u{0020}peaceful,\u{0020}leisurely\u{0020}countryside.", "0", "你又醒過來了呀，不過再稍微休息會兒吧，我们還得繼續嬉戏一番、好好享受这恬静悠闲的乡村时光呢。", "0", "0", "0", "cv_sk_shiranui_32", "0", "0"},
[4200200133] = {4200200133, 12002001, 35, 27, "0", "0", "Let's\u{0020}bring\u{0020}this\u{0020}endless\u{0020}story\u{0020}to\u{0020}a\u{0020}close\u{0020}together.", "0", "讓我們一起終結這無盡頭的故事吧。", "0", "0", "0", "cv_sk_shiranui_34", "0", "0"},
