[4200200139] = {4200200139, 12002001, 41, 33, "0", "0", "If\u{0020}you\u{0020}look\u{0020}closely,\u{0020}Navigator,\u{0020}you're\u{0020}really\u{0020}quite\u{0020}cute.\u{0020}I'm\u{0020}deeply\u{0020}touched.", "0", "仔細看的話，果然領航也很可愛，姐姐會心動的。", "0", "0", "0", "cv_sk_shiranui_40", "0", "0"},
[4200200140] = {4200200140, 12002001, 42, 34, "0", "0", "Navigator,\u{0020}you\u{0020}really\u{0020}enjoy\u{0020}these\u{0020}little\u{0020}things,\u{0020}don't\u{0020}you?", "0", "領航，你還真是喜歡這些瑣碎的事情呢。", "0", "0", "0", "cv_sk_shiranui_41", "0", "0"},
