[4200300100] = {4200300100, 12003001, 1, 1, "0", "0", "Haze\u{0020}reverb!", "0", "蒼霧殘響！", "0", "0", "0", "cv_sk_efugenia_34", "0", "0"},
[4200300101] = {4200300101, 12003001, 2, 2, "0", "0", "Haha,\u{0020}you've\u{0020}got\u{0020}sharp\u{0020}a\u{0020}sharp\u{0020}eye!", "0", "哈哈，你的眼光不錯！", "0", "0", "0", "cv_sk_efugenia_2", "0", "0"},
[4200300102] = {4200300102, 12003001, 3, 3, "0", "0", "Are\u{0020}you\u{0020}the\u{0020}Navigator?\u{0020}You\u{0020}look\u{0020}a\u{0020}bit\u{0020}delicate.\u{0020}No\u{0020}worries,\u{0020}Efgenia\u{0020}will\u{0020}take\u{0020}care\u{0020}of\u{0020}your\u{0020}enemies\u{0020}for\u{0020}you!", "0", "你這個傢伙就是領航？看起來有些弱不禁風啊。哈哈，沒事，你的敵人就交給我葉芙根尼婭解決吧！", "0", "0", "0", "cv_sk_efugenia_1", "0", "0"},
[4200300103] = {4200300103, 12003001, 4, 4, "0", "idle", "Let's\u{0020}relax\u{0020}a\u{0020}little\u{0020}longer\u{0020}before\u{0020}starting\u{0020}the\u{0020}next\u{0020}round\u{0020}of\u{0020}training.\u{0020}We've\u{0020}still\u{0020}got\u{0020}ten\u{0020}kilometers\u{0020}left\u{0020}on\u{0020}today's\u{0020}morning\u{0020}run\u{0020}target.", "0", "再泡一會兒就進行接下來的鍛煉吧。今天的晨跑目標還剩十公里。", "0", "0", "0", "cv_sk_efugenia_3", "0", "0"},
[4200300104] = {4200300104, 12003001, 5, 4, "0", "idle", "Mmm...\u{0020}This\u{0020}feels\u{0020}amazing!\u{0020}The\u{0020}cold\u{0020}spring\u{0020}water\u{0020}hitting\u{0020}those\u{0020}tight\u{0020}muscles,\u{0020}it's\u{0020}like\u{0020}all\u{0020}the\u{0020}soreness\u{0020}from\u{0020}earlier\u{0020}just\u{0020}vanished.", "0", "嗯~~~~好舒服~~~冰涼的泉水刺激著緊繃的肌肉，感覺剛才運動的疲憊都煙消雲散了。", "0", "0", "0", "cv_sk_efugenia_4", "0", "0"},
[4200300105] = {4200300105, 12003001, 6, 4, "0", "idle", "Morning\u{0020}exercise\u{0020}is\u{0020}a\u{0020}must.\u{0020}As\u{0020}both\u{0020}a\u{0020}driver\u{0020}and\u{0020}the\u{0020}captain,\u{0020}I've\u{0020}got\u{0020}to\u{0020}keep\u{0020}my\u{0020}body\u{0020}in\u{0020}peak\u{0020}shape.\u{0020}Muscles\u{0020}don't\u{0020}stick\u{0020}around\u{0020}for\u{0020}the\u{0020}lazy!", "0", "晨練是必須的，作為駕駛員，作為隊長，我必須保證自己的身體永遠處在最佳的狀態。肌肉可是很容易就會被懶惰嚇跑的。", "0", "0", "0", "cv_sk_efugenia_31", "0", "0"},
[4200300106] = {4200300106, 12003001, 7, 5, "15_2_0_0.8", "level1", "I'm\u{0020}up\u{0020}by\u{0020}four\u{0020}every\u{0020}day.\u{0020}At\u{0020}four-fifteen,\u{0020}I'm\u{0020}already\u{0020}halfway\u{0020}through\u{0020}a\u{0020}ten-kilometer\u{0020}run\u{0020}around\u{0020}the\u{0020}base.\u{0020}Once\u{0020}that's\u{0020}done,\u{0020}it's\u{0020}straight\u{0020}to\u{0020}twenty\u{0020}sets\u{0020}of\u{0020}strength\u{0020}training,\u{0020}then\u{0020}jogging\u{0020}back\u{0020}for\u{0020}breakfast.\u{0020}After\u{0020}that?\u{0020}Daily\u{0020}training,\u{0020}of\u{0020}course.", "0", "每天四點起床，四點十五從基地出發開始長跑十公里，接著是二十組力量訓練然後再慢跑回基地用早餐。早餐之後？當然是繼續日常訓練啦。", "0", "0", "0", "cv_sk_efugenia_32", "0", "0"},
[4200300107] = {4200300107, 12003001, 8, 5, "15_1_0_0.8", "level2", "Ah,\u{0020}don't\u{0020}touch\u{0020}me…\u{0020}No,\u{0020}wait…\u{0020}My\u{0020}leg…\u{0020}It\u{0020}cramped!", "0", "別碰我……不，不是……我的腿……抽筋了。", "0", "0", "0", "cv_sk_efugenia_5", "0", "0"},
[4200300108] = {4200300108, 12003001, 9, 5, "15_1_0_0.8", "level3", "Oh,\u{0020}is\u{0020}this\u{0020}some\u{0020}kind\u{0020}of\u{0020}special\u{0020}massage\u{0020}technique?\u{0020}The\u{0020}tingling\u{0020}and\u{0020}numbness\u{0020}in\u{0020}the\u{0020}muscles—it's\u{0020}definitely\u{0020}working,\u{0020}but\u{0020}could\u{0020}you\u{0020}use\u{0020}a\u{0020}bit\u{0020}more\u{0020}pressure?", "0", "這是什麼按摩的手法嗎？肌肉麻酥酥的確實很有效呢，不過力道可以再大一些。", "0", "0", "0", "cv_sk_efugenia_6", "0", "0"},
[4200300109] = {4200300109, 12003001, 10, 5, "15_1_0_0.8", "level4", "This\u{0020}place\u{0020}is\u{0020}perfect.\u{0020}We\u{0020}should\u{0020}come\u{0020}back\u{0020}here\u{0020}to\u{0020}recover\u{0020}after\u{0020}training\u{0020}sessions.\u{0020}Do\u{0020}you\u{0020}work\u{0020}out\u{0020}in\u{0020}the\u{0020}mornings\u{0020}too,\u{0020}Navigator?\u{0020}Let's\u{0020}make\u{0020}a\u{0020}plan\u{0020}to\u{0020}meet\u{0020}here\u{0020}every\u{0020}day\u{0020}to\u{0020}keep\u{0020}each\u{0020}other\u{0020}on\u{0020}track!", "0", "這裏可真是個好地方，以後訓練結束就來這裏放鬆身體吧。領航也會晨練嗎？那我們約好每天都在這裏見面吧。我們互相監督對方的鍛煉成果。", "0", "0", "0", "cv_sk_efugenia_7", "0", "0"},
[4200300110] = {4200300110, 12003001, 11, 5, "15_1_0_0.8", "level5", "I\u{0020}knew\u{0020}you've\u{0020}been\u{0020}training\u{0020}hard.\u{0020}With\u{0020}your\u{0020}current\u{0020}fitness\u{0020}level,\u{0020}you\u{0020}can\u{0020}totally\u{0020}keep\u{0020}up\u{0020}with\u{0020}my\u{0020}basic\u{0020}training\u{0020}routine.\u{0020}Come\u{0020}on,\u{0020}let's\u{0020}push\u{0020}our\u{0020}limits\u{0020}and\u{0020}set\u{0020}our\u{0020}bodies\u{0020}on\u{0020}fire!", "0", "果然，領航也有在好好鍛煉呢。以你現在的身體，已經可以承受我最初級的訓練了。來，與我一起燃燒身體吧。", "0", "0", "0", "cv_sk_efugenia_8", "0", "0"},
