[4201300101] = {4201300101, 12013001, 2, 2, "0", "0", "Are\u{0020}you\u{0020}sure\u{0020}it's\u{0020}okay\u{0020}to\u{0020}leave\u{0020}this\u{0020}to\u{0020}a\u{0020}trainee\u{0020}like\u{0020}me?", "交給我這種候補生真的好嗎？", "0", "0", "0", "0", "cv_sk_kalian_2", "0", "0"},
[4201300102] = {4201300102, 12013001, 3, 3, "0", "0", "Finally,\u{0020}we\u{0020}meet,\u{0020}Navigator.\u{0020}I'm\u{0020}Karen,\u{0020}a\u{0020}trainee\u{0020}from\u{0020}the\u{0020}Sahara\u{0020}branch.\u{0020}If\u{0020}it's\u{0020}alright,\u{0020}may\u{0020}I\u{0020}accompany\u{0020}you\u{0020}to\u{0020}the\u{0020}battlefield?", "終於見面了，領航。我是薩哈拉支部的候補生，卡蓮。如果不介意的話，可以讓我與您一同前往戰場嗎？", "0", "0", "0", "0", "cv_sk_kalian_1", "0", "0"},
[4201300103] = {4201300103, 12013001, 4, 4, "0", "idle", "So\u{0020}this\u{0020}is\u{0020}what\u{0020}Drivers\u{0020}do\u{0020}every\u{0020}day...\u{0020}Alright,\u{0020}I'll\u{0020}give\u{0020}it\u{0020}my\u{0020}all!", "這就是駕駛員們平時的工作嗎……好的，我會努力的。", "0", "0", "0", "0", "cv_sk_kalian_3", "0", "0"},
[4201300104] = {4201300104, 12013001, 5, 4, "0", "idle", "Wearing\u{0020}this\u{0020}Nimbus-made\u{0020}gear\u{0020}feels\u{0020}incredible...\u{0020}Huh?\u{0020}I\u{0020}can\u{0020}test\u{0020}it\u{0020}out\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}too?!", "怎麼說呢？將幻化出的裝備穿在身上的感覺真是太奇妙了……欸？還可以去戰場測試一下嗎？！", "0", "0", "0", "0", "cv_sk_kalian_4", "0", "0"},
[4201300105] = {4201300105, 12013001, 6, 4, "0", "idle", "There\u{0020}should\u{0020}be\u{0020}other\u{0020}trainees\u{0020}besides\u{0020}me.\u{0020}If\u{0020}you\u{0020}see\u{0020}them,\u{0020}please\u{0020}look\u{0020}out\u{0020}for\u{0020}them.", "除了我之外應該還有其他候補生吧，如果見到她們的話還請多多關照一下。", "0", "0", "0", "0", "cv_sk_kalian_30", "0", "0"},
[4201300106] = {4201300106, 12013001, 7, 5, "15_1_0_0.8", "level1", "This\u{0020}uniform\u{0020}looks\u{0020}unfamiliar?\u{0020}Ah,\u{0020}this\u{0020}is\u{0020}the\u{0020}academy\u{0020}uniform\u{0020}that\u{0020}Sahara\u{0020}prepared\u{0020}for\u{0020}the\u{0020}trainees.", "這件制服很陌生？啊，這是薩哈拉為候補生們準備的學院服。", "0", "0", "0", "0", "cv_sk_kalian_31", "0", "0"},
[4201300107] = {4201300107, 12013001, 8, 5, "15_2_0_0.8", "level2", "Huh?\u{0020}I\u{0020}happen\u{0020}to\u{0020}have\u{0020}something\u{0020}to\u{0020}discuss\u{0020}with\u{0020}you.\u{0020}May\u{0020}I\u{0020}take\u{0020}up\u{0020}some\u{0020}of\u{0020}your\u{0020}time,\u{0020}Navigator?", "嗯？正好我有事想要請教您，可以佔有您一些時間嗎？領航。", "0", "0", "0", "0", "cv_sk_kalian_5", "0", "0"},
[4201300108] = {4201300108, 12013001, 9, 5, "15_2_0_0.8", "level2", "Navigator,\u{0020}I've\u{0020}been\u{0020}thinking\u{0020}about\u{0020}a\u{0020}lot\u{0020}of\u{0020}things,\u{0020}but\u{0020}there's\u{0020}still\u{0020}so\u{0020}much\u{0020}I\u{0020}don't\u{0020}understand...\u{0020}I'm\u{0020}sorry,\u{0020}I\u{0020}may\u{0020}need\u{0020}to\u{0020}rely\u{0020}on\u{0020}you\u{0020}in\u{0020}the\u{0020}future\u{0020}as\u{0020}well.\u{0020}May\u{0020}I\u{0020}call\u{0020}you\u{0020}\"teacher\"?", "領航，我回去思考了一段時間，但還是有很多事情都弄不明白……非常抱歉，可能今後也還要拜託你了，老師。嗯，還請允許我像這樣稱呼您吧。", "0", "0", "0", "0", "cv_sk_kalian_6", "0", "0"},
[4201300109] = {4201300109, 12013001, 10, 5, "15_1_0_0.8", "level1", "Teacher,\u{0020}do\u{0020}you\u{0020}have\u{0020}some\u{0020}time\u{0020}today?\u{0020}I've\u{0020}organized\u{0020}my\u{0020}notes,\u{0020}and\u{0020}I'd\u{0020}love\u{0020}your\u{0020}help\u{0020}reviewing\u{0020}them.\u{0020}If\u{0020}you're\u{0020}busy,\u{0020}we\u{0020}can\u{0020}do\u{0020}it\u{0020}another\u{0020}day.", "老師，您今天有空嗎？我整理出了一些自己這段時間收集到的記錄，想讓您幫忙看一下可以嗎？當然，如果您正在忙的話，我們改天也可以。", "0", "0", "0", "0", "cv_sk_kalian_7", "0", "0"},
[4201300110] = {4201300110, 12013001, 11, 5, "15_2_0_0.8", "level2", "It's\u{0020}hard\u{0020}to\u{0020}believe\u{0020}I've\u{0020}spent\u{0020}so\u{0020}much\u{0020}time\u{0020}with\u{0020}you,\u{0020}teacher.\u{0020}Thanks\u{0020}to\u{0020}your\u{0020}guidance,\u{0020}I've\u{0020}stayed\u{0020}safe\u{0020}as\u{0020}a\u{0020}Driver.\u{0020}I\u{0020}wish\u{0020}the\u{0020}day\u{0020}we\u{0020}part\u{0020}would\u{0020}come\u{0020}much\u{0020}later...\u{0020}I\u{0020}still\u{0020}have\u{0020}so\u{0020}much\u{0020}to\u{0020}learn\u{0020}from\u{0020}you...", "不知不覺已經和你相處了這麼久了啊，老師。在當駕駛員的時間裏，多虧了你的照顧我才沒有受傷。真希望分別的日子可以再晚些……我還有很多想向老師請教的東西……", "0", "0", "0", "0", "cv_sk_kalian_8", "0", "0"},
[4201300111] = {4201300111, 12013001, 12, 6, "0", "0", "Thank\u{0020}you\u{0020}so\u{0020}much!", "這真是……非常感謝！", "0", "0", "0", "0", "cv_sk_kalian_9", "0", "0"},
