[4201600101] = {4201600101, 12016001, 2, 2, "0", "0", "Ha!\u{0020}This\u{0020}place\u{0020}is\u{0020}perfect\u{0020}for\u{0020}a\u{0020}concert!", "0", "哈！這個地方真不錯，很適合開演唱會！", "0", "0", "0", "cv_sk_saraid_2", "0", "0"},
[4201600102] = {4201600102, 12016001, 3, 3, "0", "0", "Yohoo,\u{0020}Sarati\u{0020}Sony\u{0020}is\u{0020}here!\u{0020}What\u{0020}kind\u{0020}of\u{0020}music\u{0020}do\u{0020}you\u{0020}like,\u{0020}Navigator?", "0", "唷吼，薩拉蒂·索尼參上！不知道領航喜歡哪種風格的音樂呢？", "0", "0", "0", "cv_sk_saraid_1", "0", "0"},
[4201600103] = {4201600103, 12016001, 4, 4, "0", "idle", "Phew,\u{0020}it's\u{0020}finally\u{0020}over.\u{0020}That\u{0020}race\u{0020}was\u{0020}a\u{0020}wild\u{0020}ride!\u{0020}Good\u{0020}thing\u{0020}you\u{0020}were\u{0020}guiding\u{0020}me\u{0020}the\u{0020}whole\u{0020}way,\u{0020}Navigator.", "0", "終於結束了，剛才的比賽驚險萬分，還好有領航你在一旁指導。", "0", "0", "0", "cv_sk_saraid_3", "0", "0"},
[4201600104] = {4201600104, 12016001, 5, 4, "0", "idle", "Crossing\u{0020}the\u{0020}finish\u{0020}line\u{0020}left\u{0020}my\u{0020}spirit\u{0020}pumped\u{0020}but\u{0020}my\u{0020}body\u{0020}exhausted—just\u{0020}like\u{0020}after\u{0020}an\u{0020}epic\u{0020}concert.", "0", "沖過終點的那一刻，我的精神保持著興奮，但身體卻感到疲憊，就像剛結束一場盛大的演唱會。", "0", "0", "0", "cv_sk_saraid_4", "0", "0"},
[4201600105] = {4201600105, 12016001, 6, 4, "0", "idle", "Ashlica\u{0020}was\u{0020}supposed\u{0020}to\u{0020}be\u{0020}my\u{0020}navigator,\u{0020}but\u{0020}she\u{0020}strained\u{0020}her\u{0020}voice\u{0020}from\u{0020}singing\u{0020}too\u{0020}much.\u{0020}Thanks\u{0020}to\u{0020}you,\u{0020}though,\u{0020}Navigator.\u{0020}Maybe\u{0020}you're\u{0020}the\u{0020}one\u{0020}meant\u{0020}to\u{0020}guide\u{0020}me\u{0020}all\u{0020}along.", "0", "本來是艾希麗卡來做我的領航員，可是她的嗓子在演唱上用力過猛變得沙啞。但多虧了領航你在，或許你就是我命中註定是的領航員。", "0", "0", "0", "cv_sk_saraid_30", "0", "0"},
[4201600106] = {4201600106, 12016001, 7, 5, "15_1_0_0.8", "touch1", "The\u{0020}roar\u{0020}of\u{0020}the\u{0020}engine\u{0020}is\u{0020}like\u{0020}a\u{0020}beat\u{0020}that\u{0020}just\u{0020}keeps\u{0020}building.\u{0020}I\u{0020}slammed\u{0020}on\u{0020}the\u{0020}gas\u{0020}and\u{0020}composed\u{0020}a\u{0020}track\u{0020}called\u{0020}Speed.\u{0020}Racing\u{0020}is\u{0020}now\u{0020}the\u{0020}third\u{0020}love\u{0020}of\u{0020}my\u{0020}life.", "0", "賽車引擎的轟鳴就像是緊密的音符節拍，我緊踩油門，演奏出一曲名為【速度】的樂譜。從此之後，賽車將是我生命中第三重要的東西。", "0", "0", "0", "cv_sk_saraid_31", "0", "0"},
[4201600107] = {4201600107, 12016001, 8, 5, "15_2_0_0.8", "touch2", "Want\u{0020}an\u{0020}autograph\u{0020}from\u{0020}the\u{0020}champion?", "0", "想要獲得一張冠軍的簽名照嗎？", "0", "0", "0", "cv_sk_saraid_5", "0", "0"},
[4201600108] = {4201600108, 12016001, 9, 5, "15_1_0_0.8", "touch1", "I\u{0020}thought\u{0020}the\u{0020}race\u{0020}itself\u{0020}would\u{0020}be\u{0020}my\u{0020}limit,\u{0020}but\u{0020}with\u{0020}you\u{0020}by\u{0020}my\u{0020}side,\u{0020}Navigator,\u{0020}I\u{0020}feel\u{0020}like\u{0020}there's\u{0020}no\u{0020}limit!", "0", "本來參加賽車比賽就已經是我的極限了，但因為領航你在，所以今天的我沒有極限！", "0", "0", "0", "cv_sk_saraid_6", "0", "0"},
[4201600109] = {4201600109, 12016001, 10, 5, "15_1_0_0.8", "touch1", "Even\u{0020}though\u{0020}the\u{0020}race\u{0020}is\u{0020}done,\u{0020}I\u{0020}still\u{0020}want\u{0020}to\u{0020}take\u{0020}a\u{0020}spin.\u{0020}Care\u{0020}to\u{0020}join\u{0020}me,\u{0020}Navigator?", "0", "雖然比賽已經結束了，但我還想再去開車兜兜風。領航你願意陪我嗎？", "0", "0", "0", "cv_sk_saraid_7", "0", "0"},
[4201600110] = {4201600110, 12016001, 11, 5, "15_2_0_0.8", "touch2", "Today's\u{0020}win\u{0020}was\u{0020}a\u{0020}miracle—a\u{0020}miracle\u{0020}we\u{0020}made\u{0020}happen\u{0020}together.\u{0020}I\u{0020}didn't\u{0020}even\u{0020}think\u{0020}about\u{0020}winning;\u{0020}I\u{0020}just\u{0020}thought\u{0020}about\u{0020}crossing\u{0020}the\u{0020}finish\u{0020}line\u{0020}with\u{0020}you.", "0", "今天的冠軍是一場奇跡，一場你與我共創的奇跡。在比賽之前，我從沒有想過會不會贏，我想的只是和你一起沖過終點。", "0", "0", "0", "cv_sk_saraid_8", "0", "0"},
[4201600111] = {4201600111, 12016001, 12, 6, "0", "0", "I'm\u{0020}going\u{0020}to\u{0020}create\u{0020}an\u{0020}even\u{0020}more\u{0020}beautiful\u{0020}melody.", "0", "我將獻上更動聽的旋律。", "0", "0", "0", "cv_sk_saraid_9", "0", "0"},
[4201600112] = {4201600112, 12016001, 13, 7, "0", "0", "I\u{0020}want\u{0020}to\u{0020}bring\u{0020}hope\u{0020}to\u{0020}everyone—the\u{0020}stage\u{0020}will\u{0020}always\u{0020}carry\u{0020}my\u{0020}wish!", "0", "我想要給大家帶來希望，而舞臺一直會承載著我的願望！", "0", "0", "0", "cv_sk_saraid_10", "0", "0"},
[4201600113] = {4201600113, 12016001, 14, 8, "0", "0", "Music\u{0020}has\u{0020}endless\u{0020}possibilities,\u{0020}and\u{0020}now\u{0020}I\u{0020}finally\u{0020}feel\u{0020}like\u{0020}I\u{0020}can\u{0020}reach\u{0020}them.\u{0020}Thank\u{0020}you,\u{0020}Navigator.\u{0020}You've\u{0020}helped\u{0020}my\u{0020}music\u{0020}soar\u{0020}further\u{0020}than\u{0020}ever\u{0020}before.", "0", "音樂裏飽含著無限的可能性。我感覺到現在我可以真正地抓住這可能性了。謝謝你，領航。你給我和我的音樂能夠飛向更遠處。", "0", "0", "0", "cv_sk_saraid_11", "0", "0"},
[4201600114] = {4201600114, 12016001, 15, 9, "0", "0", "I've\u{0020}mastered\u{0020}a\u{0020}new\u{0020}arrangement\u{0020}technique.\u{0020}Let's\u{0020}try\u{0020}it\u{0020}out\u{0020}in\u{0020}the\u{0020}next\u{0020}single!", "0", "掌握了新的編曲法，這就加入新的單曲裏試試吧！", "0", "0", "0", "cv_sk_saraid_12", "0", "0"},
