[4201700101] = {4201700101, 12017001, 2, 2, "0", "0", "Sorry\u{0020}to\u{0020}keep\u{0020}you\u{0020}waiting!\u{0020}Suzu's\u{0020}super-genius\u{0020}mode\u{0020}is\u{0020}on!\u{0020}Let's\u{0020}start\u{0020}the\u{0020}experiment...\u{0020}Huh?\u{0020}You\u{0020}want\u{0020}to\u{0020}know\u{0020}my\u{0020}usual\u{0020}mode?\u{0020}Obviously,\u{0020}it's\u{0020}always\u{0020}genius\u{0020}mode!", "お待たせー！鈴、超天才モードの準備オッケー！実験を開始するよー！……え、普段はどんなモード？当然、天才モードだけど？", "久等了！——鈴的超天才模式已經準備就緒了！實驗開始……誒？你問平時是什麼狀態？——那當然是天才模式啦？！", "0", "0", "0", "cv_sk_lin_sw_1", "0", "0"},
[4201700102] = {4201700102, 12017001, 3, 3, "0", "0", "Wow!\u{0020}Can\u{0020}I\u{0020}bring\u{0020}my\u{0020}sun\u{0020}umbrella\u{0020}here\u{0020}too?\u{0020}Mizunokomaru,\u{0020}come\u{0020}over\u{0020}here!", "うわぁ！ここにパラソル差しちゃっていい？きつね丸たちもこっちにおいでー！", "哇，我把太陽傘一起帶到這裏可以嗎？水之狐丸也過來這邊吧~", "0", "0", "0", "cv_sk_lin_sw_2", "0", "0"},
[4201700103] = {4201700103, 12017001, 91, 4, "0", "idle", "I\u{0020}never\u{0020}imagined\u{0020}we'd\u{0020}actually\u{0020}make\u{0020}it\u{0020}here,\u{0020}Navigator.\u{0020}This\u{0020}is\u{0020}truly\u{0020}the\u{0020}perfect\u{0020}ending\u{0020}for\u{0020}me...", "あたしたち、本当にここに来れたんだね、ナビゲーター。あたしにとって、本当に最高の結末だよ……", "沒想到我們真的到達了這裏呢，領航。對我來說這真是最好的結局了……", "0", "0", "0", "cv_sk_lin_sw_3", "0", "0"},
[4201700104] = {4201700104, 12017001, 91, 4, "0", "idle", "The\u{0020}sunlight's\u{0020}pretty\u{0020}harsh...\u{0020}Feeling\u{0020}light-headed.\u{0020}Am\u{0020}I\u{0020}dreaming?...\u{0020}Heatstroke?...\u{0020}Maybe.", "日差しがちょっと眩しいな～。クラクラして、まるで夢を見てるみたい……熱中症？……かもね。", "陽光稍微有點晃眼呢……暈乎乎的、我現在就好像在做夢一樣……中暑？……也許是吧。", "0", "0", "0", "cv_sk_lin_sw_4", "0", "0"},
[4201700105] = {4201700105, 12017001, 94, 4, "0", "idle2", "Huh\u{0020}ah,\u{0020}the\u{0020}sunlight\u{0020}feels\u{0020}so\u{0020}nice.\u{0020}I\u{0020}could\u{0020}easily\u{0020}drift\u{0020}off\u{0020}to\u{0020}sleep\u{0020}on\u{0020}the\u{0020}beach—Sunscreen?\u{0020}Um,\u{0020}um?\u{0020}Just\u{0020}apply\u{0020}it,\u{0020}right!", "ふわー、日差しが気持ちいい～。砂浜でゆっくり寝たいなぁーー。日焼け止め？えーと、うん？塗ればいいの？", "呼啊，陽光真舒服，好想在沙灘上好好睡一覺——防曬霜？嗯、嗯？塗上就好了吧！", "0", "0", "0", "cv_sk_lin_sw_30", "0", "0"},
[4201700106] = {4201700106, 12017001, 94, 5, "0", "idle2", "Let's\u{0020}make\u{0020}this\u{0020}a\u{0020}yearly\u{0020}tradition!", "来年もここに来ようね！", "明年還要來這裏！", "0", "0", "0", "cv_sk_lin_sw_31", "0", "0"},
[4201700107] = {4201700107, 12017001, 93, 5, "14_》_0_0.8", "touch_s1", "Let's\u{0020}hit\u{0020}the\u{0020}water!\u{0020}Navigator,\u{0020}here\u{0020}are\u{0020}your\u{0020}clothes.\u{0020}Can\u{0020}you\u{0020}hold\u{0020}them\u{0020}for\u{0020}me?", "海だよ！ナビゲーター、あたしの服持っててぇ！", "下水咯！領航衣服給你給你，幫我拿一下！", "0", "0", "0", "cv_sk_lin_sw_5", "0", "0"},
[4201700108] = {4201700108, 12017001, 96, 5, "14_》_0_0.8", "touch_s2", "Worried\u{0020}I'll\u{0020}catch\u{0020}a\u{0020}cold?\u{0020}Um...\u{0020}Guess\u{0020}I'll\u{0020}put\u{0020}on\u{0020}the\u{0020}clothes\u{0020}first.\u{0020}But,\u{0020}I\u{0020}promise\u{0020}I\u{0020}won't\u{0020}catch\u{0020}a\u{0020}cold...\u{0020}Never.", "体が冷えるのが心配？うーん……じゃあとりあえず服着よっかな。でもね、あたしは風邪ひかないんだ！今まで一度もひいたことないんだよ！", "擔心我著涼？嗯……那就先穿上衣服吧。不過哦，我是不會感冒的……從來沒有過哦。", "0", "0", "0", "cv_sk_lin_sw_6", "0", "0"},
[4201700109] = {4201700109, 12017001, 92, 5, "14_》_0_0.8", "touch1", "Let's\u{0020}make\u{0020}a\u{0020}pact.\u{0020}Bring\u{0020}me\u{0020}back\u{0020}here\u{0020}next\u{0020}time\u{0020}and\u{0020}stay\u{0020}with\u{0020}me...", "約束、またここに、あたしをつれてきてね……", "做個約定吧，下次也要帶我來這裏、和我一起……", "0", "0", "0", "cv_sk_lin_sw_7", "0", "0"},
[4201700110] = {4201700110, 12017001, 92, 5, "14_》_0_0.8", "touch1", "What's\u{0020}wrong?\u{0020}Why\u{0020}do\u{0020}you\u{0020}keep\u{0020}staring\u{0020}at\u{0020}me?\u{0020}Hmph...\u{0020}Waiting\u{0020}for\u{0020}an\u{0020}invitation?\u{0020}Then\u{0020}let's\u{0020}go\u{0020}together!", "どうしたの？あたしのことじっと見て？えへへ…もしかしてあたしから誘われるのを待ってたの？じゃあ、一緒にいこー！", "怎麼了？一直盯著我看？哼哼……你不會在等我邀請你吧？那就、一起來吧？", "0", "0", "0", "cv_sk_lin_sw_8", "0", "0"},
[4201700111] = {4201700111, 12017001, 95, 5, "14_》_0_0.8", "touch2", "Navigator,\u{0020}listen\u{0020}up.\u{0020}Suzu\u{0020}has\u{0020}two\u{0020}sets\u{0020}of\u{0020}swimsuits\u{0020}ready\u{0020}for\u{0020}this\u{0020}summer...\u{0020}Can\u{0020}you\u{0020}guess\u{0020}what\u{0020}they\u{0020}are?\u{0020}Huh?\u{0020}Why,\u{0020}why?\u{0020}Navigator,\u{0020}you're\u{0020}amazing!", "ナビゲーター、聞いて聞いて、あたしこの夏のために、水着を二着も用意したんだー！……予想通りだって？え？どうしてどうして？ナビゲーターすっごーい！", "領航聽我說，鈴為這個夏天準備了兩套泳裝哦……已經猜到了？誒？為什麼、為什麼？領航好厲害！", "0", "0", "0", "cv_sk_lin_sw_46", "0", "0"},
[4201700112] = {4201700112, 12017001, 95, 5, "14_》_0_0.8", "touch2", "Navigator...\u{0020}Don't\u{0020}just\u{0020}stand\u{0020}there.\u{0020}Come\u{0020}join\u{0020}me!\u{0020}Could\u{0020}it\u{0020}be\u{0020}that\u{0020}you\u{0020}can't\u{0020}swim?\u{0020}Suzu\u{0020}can\u{0020}teach\u{0020}you!", "ナビゲーター！そんなところで見てないで、一緒に行こうよ！あ、もしかしてナビゲーター泳げないの？それならあたしが教えてあげるよ！", "領航~~不要在這裏一個人看著了，一起來吧？難道說！領航不會游泳嗎？鈴可以教你哦！", "0", "0", "0", "cv_sk_lin_sw_47", "0", "0"},
[4201700113] = {4201700113, 12017001, 12, 6, "0", "0", "Summer\u{0020}power\u{0020}is\u{0020}on\u{0020}the\u{0020}rise!", "サマーパワーレベルアァァップッ！", "夏日力提升了。", "0", "0", "0", "cv_sk_lin_sw_9", "0", "0"},
[4201700114] = {4201700114, 12017001, 13, 7, "0", "0", "Oh!\u{0020}The\u{0020}swimming\u{0020}suit\u{0020}power\u{0020}is\u{0020}filling\u{0020}me\u{0020}up!", "おおぉ！水着パワーがみなぎってきたぁ！", "哦！鼓動的泳裝力量充斥著我的全身。", "0", "0", "0", "cv_sk_lin_sw_10", "0", "0"},
[4201700115] = {4201700115, 12017001, 14, 8, "0", "0", "Is\u{0020}this\u{0020}my\u{0020}limit?\u{0020}Hmph,\u{0020}a\u{0020}genius\u{0020}never\u{0020}halts!\u{0020}Limits\u{0020}are\u{0020}meant\u{0020}to\u{0020}be\u{0020}broken!", "これがあたしの限界？……ふふん、天才に不可能はないんだよ。限界は超えるものだもんね！", "這就是我的極限了？哼哼，天才是不會停下自己的腳步的，極限就是用來超越的！", "0", "0", "0", "cv_sk_lin_sw_11", "0", "0"},
[4201700116] = {4201700116, 12017001, 15, 9, "0", "0", "Knowledge\u{0020}accumulation\u{0020}is\u{0020}crucial\u{0020}too...\u{0020}But\u{0020}I\u{0020}really\u{0020}hate\u{0020}reading\u{0020}books!!!", "勉強しなくちゃいけないことはいっぱいあるけど……本は嫌いなの！", "知識的積累也很重要呢……但是呢，我討厭看書！！！", "0", "0", "0", "cv_sk_lin_sw_12", "0", "0"},
