[4202100129] = {4202100129, 12021001, 30, 22, "0", "0", "Oh,\u{0020}there\u{0020}are\u{0020}even\u{0020}games\u{0020}in\u{0020}here.", "0", "原來這裡還設有小遊戲呀。", "0", "0", "0", "cv_sk_shaoyin_30", "0", "0"},
