[4202100133] = {4202100133, 12021001, 34, 26, "0", "0", "Are\u{0020}you\u{0020}here\u{0020}today\u{0020}to\u{0020}improve\u{0020}your\u{0020}calligraphy,\u{0020}Navigator?", "0", "領航今日到訪，是要來精進書法嗎？", "0", "0", "0", "cv_sk_shaoyin_34", "0", "0"},
[4202100134] = {4202100134, 12021001, 35, 27, "0", "0", "I\u{0020}wish\u{0020}you\u{0020}all\u{0020}the\u{0020}best.", "0", "望諸事順遂。", "0", "0", "0", "cv_sk_shaoyin_35", "0", "0"},
