[4202100136] = {4202100136, 12021001, 37, 29, "0", "0", "You\u{0020}sure\u{0020}know\u{0020}a\u{0020}whole\u{0020}load\u{0020}of\u{0020}Drivers,\u{0020}don't\u{0020}you,\u{0020}Navigator...", "0", "領航認識的駕駛員可真多啊……", "0", "0", "0", "cv_sk_shaoyin_37", "0", "0"},
[4202100137] = {4202100137, 12021001, 38, 30, "0", "0", "What\u{0020}wondrous\u{0020}figures,\u{0020}indeed...\u{0020}Wait,\u{0020}you're\u{0020}not\u{0020}thinking\u{0020}of\u{0020}replacing\u{0020}me,\u{0020}are\u{0020}you?", "0", "此般仁人志士……等等，該不會是準備把我換掉了吧？", "0", "0", "0", "cv_sk_shaoyin_38", "0", "0"},
[4202100138] = {4202100138, 12021001, 39, 31, "0", "0", "They\u{0020}call\u{0020}me\u{0020}a\u{0020}lucky\u{0020}charm.\u{0020}But\u{0020}you\u{0020}knew\u{0020}that\u{0020}already,\u{0020}didn't\u{0020}you?", "0", "人形錦鯉的傳言，您已知曉了呀……", "0", "0", "0", "cv_sk_shaoyin_39", "0", "0"},
