[4202100140] = {4202100140, 12021001, 41, 33, "0", "0", "Heh\u{0020}heh,\u{0020}I'll\u{0020}be\u{0020}your\u{0020}assistant,\u{0020}Navigator!", "0", "哼哼，領航的助理是我呢~", "0", "0", "0", "cv_sk_shaoyin_41", "0", "0"},
[4202100141] = {4202100141, 12021001, 42, 34, "0", "0", "Am\u{0020}I\u{0020}talking\u{0020}too\u{0020}much?\u{0020}Are\u{0020}you\u{0020}trying\u{0020}to\u{0020}turn\u{0020}my\u{0020}volume\u{0020}down?", "0", "難道是我話太多了，領航決定要靜我的音？", "0", "0", "0", "cv_sk_shaoyin_42", "0", "0"},
[4202100142] = {4202100142, 12021001, 43, 35, "0", "0", "Maybe\u{0020}I\u{0020}could\u{0020}send\u{0020}you\u{0020}some\u{0020}letters\u{0020}too,\u{0020}Navigator?", "0", "要不然我也寫封信寄給領航吧？", "0", "0", "0", "cv_sk_shaoyin_43", "0", "0"},
[4202100143] = {4202100143, 12021001, 44, 36, "0", "0", "Hey,\u{0020}chat\u{0020}with\u{0020}me\u{0020}too\u{0020}sometimes,\u{0020}alright?", "0", "……不要總是和別人聊啦。", "0", "0", "0", "cv_sk_shaoyin_44", "0", "0"},
[4202100144] = {4202100144, 12021001, 45, 37, "0", "0", "Always\u{0020}think\u{0020}your\u{0020}words\u{0020}through,\u{0020}and\u{0020}-\u{0020}wait,\u{0020}you've\u{0020}sent\u{0020}it\u{0020}out\u{0020}already?!", "0", "凡事皆應謹言慎——您已經按下去了？！", "0", "0", "0", "cv_sk_shaoyin_45", "0", "0"},
[4202200100] = {4202200100, 12022001, 1, 1, "0", "0", "Haze\u{0020}reverb!", "0", "蒼霧殘響~", "0", "0", "0", "cv_sk_laipani_34", "0", "0"},
[4202200101] = {4202200101, 12022001, 2, 2, "0", "0", "Navigator,\u{0020}it's\u{0020}time\u{0020}to\u{0020}work\u{0020}now.\u{0020}Just\u{0020}stay\u{0020}here\u{0020}and\u{0020}don't\u{0020}wander\u{0020}off.", "0", "領航，現在可是工作的時間，就在這哪裡都不要去哦。", "0", "0", "0", "cv_sk_laipani_2", "0", "0"},
[4202200102] = {4202200102, 12022001, 3, 3, "0", "0", "Nice\u{0020}to\u{0020}meet\u{0020}you!\u{0020}I'm\u{0020}Lepani,\u{0020}captain\u{0020}of\u{0020}the\u{0020}reconnaissance\u{0020}team\u{0020}\"Iron\u{0020}Crow.\"\u{0020}I'll\u{0020}be\u{0020}counting\u{0020}on\u{0020}your\u{0020}guidance\u{0020}for\u{0020}a\u{0020}long\u{0020}time,\u{0020}Navigator.", "0", "初次見面，我是萊帕尼，偵查小隊“鐵鴉”的隊長。之後很長一段時間都要請您指教了，領航。", "0", "0", "0", "cv_sk_laipani_1", "0", "0"},
[4202200103] = {4202200103, 12022001, 4, 4, "0", "idle", "You\u{0020}look\u{0020}a\u{0020}bit\u{0020}sleep-deprived,\u{0020}Navigator.\u{0020}Want\u{0020}to\u{0020}take\u{0020}a\u{0020}break?\u{0020}I\u{0020}can\u{0020}note\u{0020}the\u{0020}penalty\u{0020}for\u{0020}absenteeism\u{0020}in\u{0020}the\u{0020}book\u{0020}later.", "0", "領航，您看上去睡眠不足的樣子，要休息一下嗎？曠工的懲罰可以先記在本子上。", "0", "0", "0", "cv_sk_laipani_3", "0", "0"},
[4202200104] = {4202200104, 12022001, 5, 4, "0", "idle", "\"Iron\u{0020}Crow\"\u{0020}is\u{0020}a\u{0020}team\u{0020}I'm\u{0020}proud\u{0020}of,\u{0020}and\u{0020}I\u{0020}hope\u{0020}you\u{0020}can\u{0020}trust\u{0020}us\u{0020}with\u{0020}important\u{0020}tasks.", "0", "“鐵鴉”是一隻讓我引以為豪的隊伍。所以，我也希望領航您能夠信任我們，把重要的任務託付給我們。", "0", "0", "0", "cv_sk_laipani_4", "0", "0"},
[4202200105] = {4202200105, 12022001, 6, 4, "0", "idle", "When\u{0020}we're\u{0020}on\u{0020}a\u{0020}mission,\u{0020}I\u{0020}can't\u{0020}go\u{0020}anywhere\u{0020}without\u{0020}Lolo\u{0020}by\u{0020}my\u{0020}side.\u{0020}I'm\u{0020}really\u{0020}grateful\u{0020}to\u{0020}have\u{0020}her\u{0020}with\u{0020}me.", "0", "執行任務的時候，如果洛洛不在身邊的話，我可能哪裡都去不了。真的多虧有她在了。", "0", "0", "0", "cv_sk_laipani_31", "0", "0"},
[4202200106] = {4202200106, 12022001, 7, 5, "1_》_0_0.8", "level1", "During\u{0020}the\u{0020}war,\u{0020}there\u{0020}must\u{0020}be\u{0020}many\u{0020}children\u{0020}like\u{0020}me\u{0020}who\u{0020}got\u{0020}separated\u{0020}from\u{0020}their\u{0020}parents.\u{0020}It's\u{0020}just\u{0020}so\u{0020}unfair,\u{0020}don't\u{0020}you\u{0020}think?", "0", "戰爭中，一定有很多像我一樣和父母走散了的孩子……那樣的事實在是太不合理了……您不這麼認為嗎？", "0", "0", "0", "cv_sk_laipani_32", "0", "0"},
[4202200107] = {4202200107, 12022001, 8, 5, "1_》_0_0.8", "level1", "Navigator,\u{0020}would\u{0020}you\u{0020}like\u{0020}me\u{0020}to\u{0020}hold\u{0020}your\u{0020}hand?\u{0020}Um…\u{0020}is\u{0020}it\u{0020}too\u{0020}small?", "0", "領航，您是想讓我握住您的手嗎？嗯……是不是太小了點？", "0", "0", "0", "cv_sk_laipani_5", "0", "0"},
[4202200108] = {4202200108, 12022001, 9, 5, "1_》_100_1.5", "level2", "If\u{0020}you've\u{0020}been\u{0020}having\u{0020}trouble\u{0020}sleeping\u{0020}lately,\u{0020}I\u{0020}can\u{0020}help.\u{0020}I\u{0020}have\u{0020}lots\u{0020}of\u{0020}sleeping\u{0020}pills\u{0020}that\u{0020}will\u{0020}ensure\u{0020}you\u{0020}get\u{0020}a\u{0020}good\u{0020}rest.", "0", "領航，您最近如果失眠的話，我可以幫你噢。我這邊有許多類型的安眠藥，一定能讓您睡個好覺的。", "0", "0", "0", "cv_sk_laipani_6", "0", "0"},
[4202200109] = {4202200109, 12022001, 10, 5, "1_》_500_2", "level3", "Even\u{0020}though\u{0020}I\u{0020}have\u{0020}no\u{0020}sense\u{0020}of\u{0020}direction,\u{0020}I'm\u{0020}the\u{0020}captain\u{0020}of\u{0020}\"Iron\u{0020}Crow!\"\u{0020}No\u{0020}matter\u{0020}where\u{0020}you\u{0020}are,\u{0020}just\u{0020}call\u{0020}for\u{0020}me,\u{0020}and\u{0020}I'll\u{0020}find\u{0020}you!", "0", "領航，雖然我是路癡，但我可是“鐵鴉”的隊長噢！不管您身處何地，只要您呼喚了我，我一定能找到您的！", "0", "0", "0", "cv_sk_laipani_7", "0", "0"},
[4202200110] = {4202200110, 12022001, 11, 5, "1_》_1000_2.5", "level4", "Navigator,\u{0020}could\u{0020}you\u{0020}wear\u{0020}this\u{0020}chain...\u{0020}\"Bind\"?\u{0020}I\u{0020}just\u{0020}want\u{0020}us\u{0020}to\u{0020}stay\u{0020}together\u{0020}and\u{0020}not\u{0020}lose\u{0020}each\u{0020}other\u{0020}from\u{0020}now\u{0020}on.", "0", "領航，能請您帶上這根鏈子嗎……“捆綁”？啊，不是的。我只是希望我們從此之後都不會分開，不會走散而已……不行……嗎？", "0", "0", "0", "cv_sk_laipani_8", "0", "0"},
[4202200111] = {4202200111, 12022001, 12, 6, "0", "0", "Thank\u{0020}you.", "0", "謝謝。", "0", "0", "0", "cv_sk_laipani_9", "0", "0"},
[4202200112] = {4202200112, 12022001, 13, 7, "0", "0", "I\u{0020}need\u{0020}to\u{0020}think\u{0020}of\u{0020}a\u{0020}way\u{0020}to\u{0020}repay\u{0020}you!", "0", "要想想該怎麼回報您才行~", "0", "0", "0", "cv_sk_laipani_10", "0", "0"},
[4202200113] = {4202200113, 12022001, 14, 8, "0", "0", "I'm\u{0020}so\u{0020}happy\u{0020}to\u{0020}be\u{0020}valued\u{0020}by\u{0020}you,\u{0020}Navigator.\u{0020}After\u{0020}this,\u{0020}let's\u{0020}stick\u{0020}together\u{0020}all\u{0020}the\u{0020}time.\u{0020}We\u{0020}shouldn't\u{0020}and\u{0020}can't\u{0020}be\u{0020}separated.", "0", "能被您如此重視，我真的感到很幸福，領航。在這之後，我們也要一直在一起，不要，也不能分開噢。", "0", "0", "0", "cv_sk_laipani_11", "0", "0"},
[4202200114] = {4202200114, 12022001, 15, 9, "0", "0", "I\u{0020}want\u{0020}to\u{0020}improve\u{0020}my\u{0020}skills\u{0020}in\u{0020}navigation…", "0", "更想要識路的技能呀……", "0", "0", "0", "cv_sk_laipani_12", "0", "0"},
