[4202200116] = {4202200116, 12022001, 17, 11, "0", "0", "This\u{0020}credit\u{0020}goes\u{0020}to\u{0020}everyone.", "0", "這都是大家的功勞。", "0", "0", "0", "cv_sk_laipani_14", "0", "0"},
