[4202200123] = {4202200123, 12022001, 25, 18, "0", "0", "I\u{0020}declare\u{0020}the\u{0020}hide-and-seek\u{0020}game\u{0020}over.", "0", "我宣佈，捉迷藏遊戲結束了。", "0", "0", "0", "cv_sk_laipani_23", "0", "0"},
