[4202200127] = {4202200127, 12022001, 28, 21, "0", "0", "Whew…\u{0020}that\u{0020}was\u{0020}close.\u{0020}I\u{0020}almost\u{0020}swatted\u{0020}you\u{0020}like\u{0020}a\u{0020}mosquito\u{0020}just\u{0020}now.", "0", "呼……好危險。剛剛差點把領航當做蚊子拍下去了~", "0", "0", "0", "cv_sk_laipani_25", "0", "0"},
