[4202200130] = {4202200130, 12022001, 31, 23, "0", "0", "Don't\u{0020}worry.\u{0020}It's\u{0020}okay\u{0020}if\u{0020}you\u{0020}make\u{0020}mistakes.", "0", "請放心，即使錯了也沒有關係的。", "0", "0", "0", "cv_sk_laipani_28", "0", "0"},
