[4300200101] = {4300200101, 13002001, 2, 2, "0", "0", "As\u{0020}head\u{0020}maid,\u{0020}it's\u{0020}my\u{0020}duty\u{0020}to\u{0020}lead\u{0020}by\u{0020}example.", "0", "身為女僕長確實應該起到表率作用。", "0", "0", "0", "cv_sk_tina_2", "0", "0"},
[4300200102] = {4300200102, 13002001, 3, 3, "0", "0", "Tina\u{0020}Eisen,\u{0020}the\u{0020}most\u{0020}loyal\u{0020}servant\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family.\u{0020}Have\u{0020}you\u{0020}seen\u{0020}the\u{0020}young\u{0020}lady\u{0020}of\u{0020}the\u{0020}family,\u{0020}Navigator?", "0", "蒂娜·愛森，克雷蒂亞家族最忠誠的僕從。領航，你有看到我家小姐嗎？", "0", "0", "0", "cv_sk_tina_1", "0", "0"},
[4300200103] = {4300200103, 13002001, 4, 4, "0", "idle", "Team\u{0020}racing\u{0020}is\u{0020}a\u{0020}battle,\u{0020}and\u{0020}no\u{0020}one\u{0020}wins\u{0020}alone.", "レースは戦闘と同じです。自分のことだけを考えていては、勝つことはできません。", "车队比赛和战斗是一样的，如果心中只有自己，就无法取得胜利。", "0", "0", "0", "cv_sk_tina_3", "0", "0"},
[4300200104] = {4300200104, 13002001, 5, 4, "0", "idle", "Skill\u{0020}matters.\u{0020}Mind\u{0020}matters\u{0020}more.\u{0020}My\u{0020}high\u{0020}standards?\u{0020}They're\u{0020}there\u{0020}to\u{0020}train\u{0020}you\u{0020}to\u{0020}handle\u{0020}the\u{0020}pressure.", "運転のテクニック以外に、メンタルも非常に重要です。私があなたに厳しくしているのも、ストレス耐性を鍛えるためですよ。", "除了驾驶技术，比赛时的心态也非常重要。我对你的高要求也是在训练你的抗压能力。", "0", "0", "0", "cv_sk_tina_4", "0", "0"},
[4300200105] = {4300200105, 13002001, 6, 4, "0", "idle", "Next\u{0020}race,\u{0020}switch\u{0020}from\u{0020}hard\u{0020}to\u{0020}soft\u{0020}tires\u{0020}mid-race.\u{0020}How\u{0020}many\u{0020}times\u{0020}do\u{0020}I\u{0020}have\u{0020}to\u{0020}say\u{0020}it?\u{0020}Honestly,\u{0020}even\u{0020}I'm\u{0020}starting\u{0020}to\u{0020}get\u{0020}a\u{0020}little\u{0020}nervous...\u{0020}But\u{0020}I'll\u{0020}keep\u{0020}my\u{0020}cool.", "次のレースでは、タイヤをハードからソフトに交換するように……既に言っていましたか？どうやら、私も少し緊張しているようですね。メンタルを整えます。", "下次的比赛选择硬胎转软胎的战术……我已经说过很多遍了？看来我也有些紧张了，我会尽量保持克制的。", "0", "0", "0", "cv_sk_tina_41", "0", "0"},
[4300200106] = {4300200106, 13002001, 7, 5, "15_1_0_0.8", "level1", "Off-season\u{0020}doesn't\u{0020}mean\u{0020}off-duty.\u{0020}Training's\u{0020}on\u{0020}schedule,\u{0020}same\u{0020}as\u{0020}always.", "オフシーズンに入りましたが、怠けてはいけませんよ。今日もいつも通りに訓練を行いますわ。", "虽然现在是休赛期，但也不能松懈，今天照常训练。", "0", "0", "0", "cv_sk_tina_27", "0", "0"},
[4300200107] = {4300200107, 13002001, 8, 5, "15_2_0_0.8", "level2", "Focus\u{0020}on\u{0020}your\u{0020}drills.", "訓練に集中してください。", "请专心训练。", "0", "0", "0", "cv_sk_tina_5", "0", "0"},
[4300200108] = {4300200108, 13002001, 9, 5, "15_1_0_0.8", "level1", "Remember,\u{0020}your\u{0020}top\u{0020}priority\u{0020}in\u{0020}the\u{0020}first\u{0020}lap\u{0020}is\u{0020}to\u{0020}stay\u{0020}alive.\u{0020}Keep\u{0020}calm,\u{0020}find\u{0020}your\u{0020}rhythm.", "ちゃんと覚えてくださいね。１周目の目標は、生き残ることです。メンタルを安定させて、自分のリズムを保つようにしましょう。", "记住，第一圈的首要任务永远是“活下来”，一定要稳住心态，保持自己的节奏。", "0", "0", "0", "cv_sk_tina_6", "0", "0"},
[4300200109] = {4300200109, 13002001, 10, 5, "15_1_0_0.8", "level1", "You\u{0020}don't\u{0020}need\u{0020}to\u{0020}be\u{0020}tense\u{0020}every\u{0020}second\u{0020}on\u{0020}track.\u{0020}If\u{0020}you've\u{0020}built\u{0020}enough\u{0020}lead,\u{0020}slow\u{0020}down,\u{0020}save\u{0020}those\u{0020}tires.\u{0020}What's\u{0020}that?\u{0020}You\u{0020}get\u{0020}nervous\u{0020}just\u{0020}thinking\u{0020}about\u{0020}me?\u{0020}Am\u{0020}I\u{0020}really\u{0020}that\u{0020}intimidating?", "レース中、常に気を張る必要はありません。十分にリードしている場合は、タイヤの節約のために速度を落としてもいいでしょう。え、私のことを考えるだけで緊張してしまうですって？私って、そんなに怖いコーチなのででしょうか……", "比赛中你不需要一直都保持紧张，如果你领先得足够多，你可以试着放慢节奏去节省轮胎。什么？只要想起我就会紧张？我是那么可怕的教练么……", "0", "0", "0", "cv_sk_tina_7", "0", "0"},
[4300200110] = {4300200110, 13002001, 11, 5, "15_2_0_0.8", "level2", "Huh?\u{0020}You\u{0020}can't\u{0020}focus\u{0020}when\u{0020}I'm\u{0020}here?\u{0020}What\u{0020}are\u{0020}you\u{0020}staring\u{0020}at?\u{0020}I'm\u{0020}here\u{0020}to\u{0020}supervise,\u{0020}not\u{0020}to\u{0020}be\u{0020}your\u{0020}distraction.\u{0020}Train\u{0020}seriously,\u{0020}or\u{0020}there'll\u{0020}be\u{0020}consequences.", "え、私がここにいたら、訓練に集中できないと？あなた、どこを見ているのですか！私は訓練を監督するために来ているのです。私のことばかり見つめるのはおやめください！訓練に集中しないと、後でお仕置きですからね！", "诶？我在这里就无法认真训练？你……你在看什么地方啊！我是来监督训练的，不要老是看着我啊！不专心训练我可是会惩罚你的！", "0", "0", "0", "cv_sk_tina_8", "0", "0"},
[4300200111] = {4300200111, 13002001, 12, 6, "0", "0", "Oh,\u{0020}so\u{0020}you\u{0020}expect\u{0020}a\u{0020}lot\u{0020}from\u{0020}me?", "0", "欸呀，看來你對我心懷期待呢。", "0", "0", "0", "cv_sk_tina_9", "0", "0"},
[4300200112] = {4300200112, 13002001, 13, 7, "0", "0", "Is\u{0020}this\u{0020}how\u{0020}you\u{0020}teach\u{0020}others?", "0", "喔～這就是你教育人的方式嗎？", "0", "0", "0", "cv_sk_tina_10", "0", "0"},
[4300200113] = {4300200113, 13002001, 14, 8, "0", "0", "Thank\u{0020}you\u{0020}for\u{0020}your\u{0020}trust.\u{0020}From\u{0020}now\u{0020}on,\u{0020}I\u{0020}won't\u{0020}let\u{0020}you\u{0020}down.\u{0020}I'll\u{0020}work\u{0020}hard\u{0020}to\u{0020}forge\u{0020}my\u{0020}own\u{0020}path.", "0", "承蒙厚愛，從今往後我絕不辜負你的期待，努力探求出屬於自己的道路。", "0", "0", "0", "cv_sk_tina_11", "0", "0"},
[4300200114] = {4300200114, 13002001, 15, 9, "0", "0", "Is\u{0020}this...\u{0020}some\u{0020}new\u{0020}advice?", "0", "這是……新的教鞭？", "0", "0", "0", "cv_sk_tina_12", "0", "0"},
