[4300300101] = {4300300101, 13003001, 2, 2, "0", "0", "Woah,\u{0020}I\u{0020}honestly\u{0020}don't\u{0020}think\u{0020}there's\u{0020}anything\u{0020}you\u{0020}can't\u{0020}do!", "0", "喔！這就是所謂的上得廳堂下得廚房吧。", "0", "0", "0", "cv_sk_kurimu_2", "0", "0"},
[4300300102] = {4300300102, 13003001, 3, 3, "0", "0", "Hey\u{0020}hey,\u{0020}hiiiiii!\u{0020}I'm\u{0020}Crimmm\u{0020}KKKKK\u{0020}Tanov!", "0", "欸嘿嘿~李猴牙~我名字是克裏姆木木木木點科點塔諾夫~", "0", "0", "0", "cv_sk_kurimu_1", "0", "0"},
[4300300103] = {4300300103, 13003001, 4, 4, "0", "idle", "Wings?\u{0020}Tail?\u{0020}Are\u{0020}you\u{0020}already\u{0020}tipsy,\u{0020}Navigator?\u{0020}No\u{0020}worries,\u{0020}let's\u{0020}keep\u{0020}drinking.", "羽根？尻尾？ナビゲーター、酔ってるんじゃない？ま、気にしないでじゃんじゃん饮もー！", "翅膀？尾巴？領航你是喝醉了嗎？不過不要緊，我們繼續喝。", "0", "0", "0", "cv_sk_kurimu_3", "0", "0"},
[4300300104] = {4300300104, 13003001, 5, 4, "0", "idle", "Wait...\u{0020}all\u{0020}the\u{0020}smoked\u{0020}sausages\u{0020}are\u{0020}gone?\u{0020}Wine\u{0020}just\u{0020}doesn't\u{0020}hit\u{0020}right\u{0020}without\u{0020}a\u{0020}snack.\u{0020}Got\u{0020}any\u{0020}hidden\u{0020}somewhere,\u{0020}Navigator?", "あれ、ソーセージ、もうないの？つまみがないと寂しいなー……ナビゲーター、どっかにまだソーセージ隠してなーい？", "唔？熏肉腸吃完了嗎？沒有下酒菜的話這酒喝著沒滋味了……領航你那兒還藏著熏肉腸是不是？", "0", "0", "0", "cv_sk_kurimu_4", "0", "0"},
[4300300105] = {4300300105, 13003001, 6, 4, "0", "idle", "If\u{0020}Iliya\u{0020}were\u{0020}here,\u{0020}there's\u{0020}no\u{0020}way\u{0020}you'd\u{0020}walk\u{0020}home.\u{0020}I\u{0020}can't\u{0020}even\u{0020}keep\u{0020}up\u{0020}with\u{0020}her\u{0020}drinking.\u{0020}But\u{0020}don't\u{0020}worry,\u{0020}if\u{0020}it\u{0020}comes\u{0020}to\u{0020}that,\u{0020}I'll\u{0020}handle\u{0020}it\u{0020}for\u{0020}you.", "イリア姉さんがここにいたら、ナビゲーターは帰れなかったよ。姉さんの饮む量はハンパないからね。でも大丈夫！そうなったらあたしが代わりに饮んであげる！", "伊莉雅姐姐在這裏的話，領航今天可就別想走著回去咯。她的酒量就連我都有點扛不住。不過放心，真到了那時候的話，我會幫你喝的。", "0", "0", "0", "cv_sk_kurimu_27", "0", "0"},
[4300300106] = {4300300106, 13003001, 7, 5, "1_》_0_0.8", "level1", "They\u{0020}say\u{0020}alcohol\u{0020}brings\u{0020}out\u{0020}desires,\u{0020}but\u{0020}really,\u{0020}those\u{0020}were\u{0020}already\u{0020}there,\u{0020}right?", "酒は人を狂わせるって言うけど、その人の本质が元々そうってことだよ。", "人們都說酒會勾出人的欲望，那是因為欲望本來就存在於人的心中。", "0", "0", "0", "cv_sk_kurimu_28", "0", "0"},
[4300300107] = {4300300107, 13003001, 8, 5, "1_》_0_0.8", "level1", "Hey,\u{0020}what\u{0020}are\u{0020}you\u{0020}reaching\u{0020}for?\u{0020}That's\u{0020}not\u{0020}the\u{0020}wine\u{0020}bottle!", "どこ触ってんの？それは酒瓶じゃないよ。", "你摸哪里呢？這可不是酒瓶。", "0", "0", "0", "cv_sk_kurimu_5", "0", "0"},
[4300300108] = {4300300108, 13003001, 9, 5, "1_》_0_0.8", "level2", "Cheers!\u{0020}How\u{0020}do\u{0020}you\u{0020}like\u{0020}this\u{0020}new\u{0020}vodka\u{0020}I\u{0020}brought?", "かんぱーい！ウォッカを使った新しいドリンク、気に入った？", "乾杯！喜歡我的新口味“伏特加”嗎？", "0", "0", "0", "cv_sk_kurimu_6", "0", "0"},
[4300300109] = {4300300109, 13003001, 10, 5, "1_》_0_0.8", "level3", "Oh!\u{0020}I\u{0020}just\u{0020}remembered\u{0020}something\u{0020}important.\u{0020}It's\u{0020}something\u{0020}only\u{0020}you\u{0020}and\u{0020}I\u{0020}can\u{0020}do,\u{0020}but\u{0020}let's\u{0020}talk\u{0020}after\u{0020}we\u{0020}finish\u{0020}drinking.", "そうだ。大事な话があるんだった。ナビゲーターと一绪じゃないとできないこと。でもまぁ、お酒を饮み终わってからでいいよね。", "我突然想起件重要的事，一件必須和領航一起才能做的事，不過這件事還是等喝完了酒再說吧。", "0", "0", "0", "cv_sk_kurimu_7", "0", "0"},
[4300300110] = {4300300110, 13003001, 11, 5, "1_》_0_0.8", "level4", "I\u{0020}probably\u{0020}look\u{0020}ridiculous\u{0020}to\u{0020}you\u{0020}right\u{0020}now,\u{0020}huh?\u{0020}No\u{0020}need\u{0020}to\u{0020}hide\u{0020}it.\u{0020}I\u{0020}can\u{0020}see\u{0020}it\u{0020}in\u{0020}your\u{0020}eyes,\u{0020}but\u{0020}that's\u{0020}just\u{0020}the\u{0020}booze\u{0020}talking.\u{0020}Don't\u{0020}worry,\u{0020}the\u{0020}real\u{0020}me\u{0020}is\u{0020}still\u{0020}right\u{0020}here\u{0020}by\u{0020}your\u{0020}side.", "今のあたし、すごく変に见えてるんじゃない？へへ。否定しないくていいよ。ナビゲーターの目を见れば分かるから。でも、これは幻覚。酔ってるんだもん、当たり前だよね。安心していいよ。いつものあたしは、ずっとナビゲーターの傍にいるから。", "現在的我在你眼中一定很奇怪吧。不用否認，領航的眼睛已經告訴我了。但這只是幻覺，是喝醉之後的正常現象。請放心，正常的我一直都陪在領航身邊。", "0", "0", "0", "cv_sk_kurimu_8", "0", "0"},
[4300300111] = {4300300111, 13003001, 12, 6, "0", "0", "Sausage!", "0", "Колбаса！", "0", "0", "0", "cv_sk_kurimu_9", "0", "0"},
