[4300400101] = {4300400101, 13004001, 2, 2, "0", "0", "Got\u{0020}it!\u{0020}I'll\u{0020}stay\u{0020}right\u{0020}here\u{0020}and\u{0020}do\u{0020}my\u{0020}duty!\u{0020}Navigator,\u{0020}don't\u{0020}slack\u{0020}off\u{0020}either!", "了解！拙者、ここに立って使命を果たす！ナビゲーターも気を引き締めてくれ！", "瞭解！在下會一直站在這裡履行職責的！領航也千萬不要偷懶！", "0", "了解！在下会一直站在这里履行职责的！领航也千万不要偷懒！", "0", "cv_sk_ayaka_2", "0", "0"},
[4300400102] = {4300400102, 13004001, 3, 3, "0", "0", "I'm\u{0020}Caihua,\u{0020}the\u{0020}newly\u{0020}promoted\u{0020}medical\u{0020}officer.\u{0020}Ready\u{0020}for\u{0020}orders,\u{0020}Navigator!", "拙者は新しく就任した医療官、彩華！ミッションの指示を出してくれ、ナビゲーター！", "在下是新晉的醫療官-彩華！請下達任務吧，領航！", "0", "在下是新晋的医疗官-彩华！请下达任务吧，领航！", "0", "cv_sk_ayaka_1", "0", "0"},
[4300400103] = {4300400103, 13004001, 4, 4, "0", "idle", "Navigator!\u{0020}Does\u{0020}your\u{0020}neck\u{0020}hurt?\u{0020}I'm\u{0020}an\u{0020}expert\u{0020}in\u{0020}acupuncture\u{0020}and\u{0020}massage,\u{0020}I\u{0020}can\u{0020}fix\u{0020}you\u{0020}right\u{0020}up!", "首が痛いのか？拙者、鍼灸や点穴に精通している、無料で矯正してやろう。", "領航！你的脖子酸痛嗎？在下精通針灸點穴，可以免費幫您物理矯正一下！", "0", "领航！你的脖子酸痛吗？在下精通针灸点穴，可以免费帮您物理矫正一下！", "0", "cv_sk_ayaka_3", "0", "0"},
[4300400104] = {4300400104, 13004001, 5, 4, "0", "idle", "Some\u{0020}of\u{0020}these\u{0020}patients\u{0020}complain\u{0020}about\u{0020}my\u{0020}treatment\u{0020}just\u{0020}because\u{0020}it's\u{0020}a\u{0020}bit…\u{0020}unconventional.\u{0020}Sure,\u{0020}it\u{0020}hurts,\u{0020}but\u{0020}the\u{0020}results\u{0020}are\u{0020}worth\u{0020}it!", "もう……あいつら！治療方法がちょっと独特だからって拙者にクレームをつけるなんて！確かに痛いけど、その分治療効果が高いのだぞ！", "這幫可惡的傷患，就因為治療手段稍微特殊了點，居然私底下投訴在下。雖然很痛，但是效果絕對很好啊！", "0", "这帮可恶的伤员，就因为治疗手段稍微特殊了点，居然私底下投诉在下。虽然很痛，但是效果绝对很好啊！", "0", "cv_sk_ayaka_4", "0", "0"},
[4300400105] = {4300400105, 13004001, 6, 4, "0", "idle", "Hualian...\u{0020}she's\u{0020}always\u{0020}lost\u{0020}in\u{0020}her\u{0020}own\u{0020}world.\u{0020}One\u{0020}of\u{0020}these\u{0020}days,\u{0020}I'll\u{0020}straighten\u{0020}out\u{0020}those\u{0020}wandering\u{0020}thoughts\u{0020}with\u{0020}a\u{0020}few\u{0020}well-placed\u{0020}needles!", "華恋のやつ……可笑しなことばっかり考えて！いつか、鍼灸であの頭をどうにかしてやる！", "華戀那傢伙……腦子裏整天在想些奇怪的事情。有機會的話，在下一定要用針灸治好她的腦袋！", "0", "华恋那家伙……脑子里整天在想些奇怪的事情。有机会的话，在下一定要用针灸治好她的脑袋！", "0", "cv_sk_ayaka_27", "0", "0"},
[4300400106] = {4300400106, 13004001, 7, 5, "15_2_0_0.8", "touch2", "My\u{0020}medical\u{0020}skills\u{0020}have\u{0020}been\u{0020}passed\u{0020}down\u{0020}through\u{0020}generations.\u{0020}My\u{0020}family's\u{0020}legacy\u{0020}may\u{0020}have\u{0020}faded,\u{0020}but\u{0020}I'll\u{0020}restore\u{0020}its\u{0020}glory!", "拙者の医術は先祖に代々伝わる技術だ。今はもう、没落してしまったが……いつかは必ず、先祖の栄光を取り戻す！", "在下的醫術，是家族歷代傳承的技藝。雖然現在已經落寞了，但是在下一定會重振家族榮光的！", "0", "在下的医术，是家族历代传承的技艺。虽然现在已经落寞了，但是在下一定会重振家族荣光的！", "0", "cv_sk_ayaka_28", "0", "0"},
[4300400107] = {4300400107, 13004001, 8, 5, "15_1_0_0.8", "touch1", "It's\u{0020}work\u{0020}time.\u{0020}No\u{0020}fooling\u{0020}around,\u{0020}Navigator.", "仕事中に感心せんな、ナビゲーター。", "現在是工作時間，請不要胡鬧，領航。", "0", "现在是工作时间，请不要胡闹，领航。", "0", "cv_sk_ayaka_5", "0", "0"},
[4300400108] = {4300400108, 13004001, 9, 5, "15_1_0_0.8", "touch1", "Navigator,\u{0020}care\u{0020}to\u{0020}try\u{0020}some\u{0020}acupressure?", "ひょっとして、点穴に興味あるのか？", "領航……你難道對點穴有興趣嗎？", "0", "领航……你难道对点穴有兴趣吗？", "0", "cv_sk_ayaka_6", "0", "0"},
[4300400109] = {4300400109, 13004001, 10, 5, "15_2_0_0.8", "touch2", "Let\u{0020}me\u{0020}show\u{0020}you\u{0020}how\u{0020}it's\u{0020}done.\u{0020}The\u{0020}pain\u{0020}lasts\u{0020}just\u{0020}a\u{0020}moment,\u{0020}and\u{0020}it's\u{0020}over\u{0020}before\u{0020}you\u{0020}know\u{0020}it.", "拙者が正しい点穴のやり方の手本をお見せしよう――一瞬だけ痛みが走るが、すぐに終わる。", "領航，請允許在下為你示範正確的點穴方式吧——疼痛只是一瞬間的，馬上就結束了。", "0", "领航，请允许在下为你示范正确的点穴方式吧——疼痛只是一瞬间的，马上就结束了。", "0", "cv_sk_ayaka_7", "0", "0"},
[4300400110] = {4300400110, 13004001, 11, 5, "15_1_0_0.8", "touch1", "Navigator,\u{0020}mind\u{0020}if\u{0020}I\u{0020}use\u{0020}you\u{0020}for\u{0020}practice?\u{0020}Huh?\u{0020}It's\u{0020}work\u{0020}time…\u{0020}Well,\u{0020}alright,\u{0020}let's\u{0020}do\u{0020}it!", "もしよければ、拙者の練習相手になってくれるか？うえ？いいのか？仕事中なのに……では、失礼する！はっ！", "領航……如果你不介意的話，在下想請你作為在下的練習對象。欸？可以嗎？明明是工作時間……那麼，在下不客氣了！喝！", "0", "领航……如果你不介意的话，在下想请你作为在下的练习对象。诶？可以吗？明明是工作时间……那么，在下不客气了！喝！", "0", "cv_sk_ayaka_8", "0", "0"},
[4300400111] = {4300400111, 13004001, 12, 6, "0", "0", "Got\u{0020}the\u{0020}acupoints\u{0020}down\u{0020}perfectly!", "ふむ、経穴をもっと正確に把握できるようになった！", "嗯，對於穴道的把握也更加精准了！", "0", "嗯，对于穴道的把握也更加精准了！", "0", "cv_sk_ayaka_9", "0", "0"},
[4300400112] = {4300400112, 13004001, 13, 7, "0", "0", "My\u{0020}skills\u{0020}as\u{0020}a\u{0020}doctor\u{0020}have\u{0020}improved.", "医師としてのレベルが上がったぞ！", "作為醫師的水準上升了。", "0", "作为医师的水准上升了。", "0", "cv_sk_ayaka_10", "0", "0"},
[4300400113] = {4300400113, 13004001, 14, 8, "0", "0", "I\u{0020}can\u{0020}feel\u{0020}the\u{0020}power\u{0020}surging\u{0020}through\u{0020}me!\u{0020}You\u{0020}can\u{0020}trust\u{0020}me\u{0020}with\u{0020}all\u{0020}the\u{0020}treatment\u{0020}tasks\u{0020}now,\u{0020}Navigator.", "体の中から力がどんどん湧いてくる……ナビゲーター、これからも安心して治療のことは拙者に任せてくれ。", "力量從身體裡不斷湧出……領航，從今往後請放心地將治療任務交予在下吧。", "0", "力量从身体里不断涌出……领航，从今往后请放心地将治疗任务交予在下吧。", "0", "cv_sk_ayaka_11", "0", "0"},
[4300400114] = {4300400114, 13004001, 15, 9, "0", "0", "The\u{0020}treatment\u{0020}results\u{0020}have\u{0020}improved.", "治療効果が上がったぞ。", "領航，治療的效果提升了呢。", "0", "领航，治疗的效果提升了呢。", "0", "cv_sk_ayaka_12", "0", "0"},
[4300400115] = {4300400115, 13004001, 16, 10, "0", "0", "We're\u{0020}starting\u{0020}the\u{0020}operation.\u{0020}Let\u{0020}me\u{0020}know\u{0020}if\u{0020}you're\u{0020}hurt.", "作戦開始。負傷した者は拙者の所へ。", "作戰開始，請受傷的人來在下身邊。", "0", "作战开始，请受伤的人来在下身边。", "0", "cv_sk_ayaka_13", "0", "0"},
[4300400116] = {4300400116, 13004001, 17, 11, "0", "0", "As\u{0020}expected,\u{0020}no\u{0020}casualties\u{0020}and\u{0020}the\u{0020}enemies\u{0020}are\u{0020}wiped\u{0020}out!", "拙者の予想通り、死傷者ゼロで敵を全滅！", "就像在下預計的那樣，無人傷亡，全殲敵人！", "0", "就像在下预计的那样，无人伤亡，全歼敌人！", "0", "cv_sk_ayaka_14", "0", "0"},
[4300400117] = {4300400117, 13004001, 18, 12, "0", "0", "Check\u{0020}for\u{0020}any\u{0020}wounded.\u{0020}Treat\u{0020}them\u{0020}immediately.", "死傷者の状況を確認する。負傷した者はすぐ治療を受けるように！", "確認傷亡情況，受傷人員立即接受治療。", "0", "确认伤亡情况，受伤人员立即接受治疗。", "0", "cv_sk_ayaka_15", "0", "0"},
[4300400118] = {4300400118, 13004001, 19, 13, "0", "0", "A\u{0020}bloody\u{0020}victory…\u{0020}I'll\u{0020}do\u{0020}better\u{0020}next\u{0020}time.", "勝利したが大変だった……次はきっとうまくいく。", "慘烈的勝利……下次在下會做得更好的。", "0", "惨烈的胜利……下次在下会做得更好的。", "0", "cv_sk_ayaka_16", "0", "0"},
[4300400119] = {4300400119, 13004001, 20, 14, "0", "0", "Regroup,\u{0020}Navigator,\u{0020}we\u{0020}still\u{0020}have\u{0020}a\u{0020}shot.", "気を取り直せ。チャンスはまだある。", "領航，請重整旗鼓，我們還有機會。", "0", "领航，请重整旗鼓，我们还有机会。", "0", "cv_sk_ayaka_17", "0", "0"},
[4300400120] = {4300400120, 13004001, 23, 16, "0", "0", "Just\u{0020}hang\u{0020}in\u{0020}there\u{0020}for\u{0020}a\u{0020}bit!", "少しの辛抱だ！", "忍一下就好了！", "0", "忍一下就好了！", "0", "cv_sk_ayaka_18", "0", "0"},
[4300400121] = {4300400121, 13004001, 26, 19, "0", "0", "I\u{0020}guess\u{0020}doctors\u{0020}can't\u{0020}treat\u{0020}themselves…", "やっぱり……医者は自分の病を治せない、か……", "果然……醫者不能自醫嗎……", "0", "果然……医者不能自医吗……", "0", "cv_sk_ayaka_19", "0", "0"},
[4300400122] = {4300400122, 13004001, 27, 20, "0", "0", "Huh...\u{0020}nothing\u{0020}beats\u{0020}a\u{0020}hot\u{0020}bath\u{0020}after\u{0020}work,\u{0020}right,\u{0020}Navigator?", "ふぅ……仕事上がりの風呂はやっぱり最高だな！ナビゲーター。", "呼……工作後立馬就去泡澡果然是最棒的，對吧，領航？", "0", "呼……工作后立马就去泡澡果然是最棒的，对吧，领航？", "0", "cv_sk_ayaka_20", "0", "0"},
[4300400123] = {4300400123, 13004001, 28, 21, "0", "0", "One\u{0020}downside\u{0020}to\u{0020}baths—you\u{0020}can't\u{0020}do\u{0020}acupuncture\u{0020}before\u{0020}or\u{0020}after.", "熱い風呂の前後は鍼灸を施せない。これが風呂の唯一の欠点だ。", "熱浴的前後一段時間內都不能夠針灸，這是泡澡的唯一壞處呢。", "0", "热浴的前后一段时间内都不能够针灸，这是泡澡的唯一坏处呢。", "0", "cv_sk_ayaka_21", "0", "0"},
[4300400124] = {4300400124, 13004001, 29, 21, "0", "0", "You\u{0020}must\u{0020}be\u{0020}tired\u{0020}too,\u{0020}Navigator.\u{0020}I\u{0020}can\u{0020}give\u{0020}you\u{0020}a\u{0020}massage…\u{0020}No,\u{0020}it's\u{0020}not\u{0020}that\u{0020}painful!\u{0020}Don't\u{0020}be\u{0020}scared.", "ナビゲーターも疲れただろう？拙者がマッサージしてやる……？え？そんなに痛くないぞ！怖がらなくていい。", "領航也很累了吧，在下可以給你按摩喔……欸？沒有那麼痛的，不要害怕啦。", "0", "领航也很累了吧，在下可以给你按摩哦……诶？没有那么痛的，不要害怕啦。", "0", "cv_sk_ayaka_22", "0", "0"},
[4300400125] = {4300400125, 13004001, 30, 22, "0", "0", "Stay\u{0020}sharp,\u{0020}Navigator!", "十分気を付けるのだ！", "領航，請提高警惕！", "0", "领航，请提高警惕！", "0", "cv_sk_ayaka_23", "0", "0"},
[4300400126] = {4300400126, 13004001, 31, 23, "0", "0", "Alright,\u{0020}if\u{0020}you\u{0020}guess\u{0020}wrong,\u{0020}I'll\u{0020}sharpen\u{0020}your\u{0020}focus\u{0020}with\u{0020}a\u{0020}little\u{0020}acupuncture!", "よし、外れたら鍼でナビゲーターの頭をはっきりさせよう。", "決定了，猜錯的話，就用針讓領航的腦袋清醒過來！", "0", "决定了，猜错的话，就用针让领航的脑袋清醒过来！", "0", "cv_sk_ayaka_24", "0", "0"},
[4300400127] = {4300400127, 13004001, 32, 24, "0", "0", "Of\u{0020}course!\u{0020}It'd\u{0020}be\u{0020}bad\u{0020}if\u{0020}you\u{0020}got\u{0020}it\u{0020}wrong.", "当たり前の結果だ。外れたら大変なことになっていたぞ。", "這是理所當然的結果，猜錯了的話就糟糕了。", "0", "这是理所当然的结果，猜错了的话就糟糕了。", "0", "cv_sk_ayaka_25", "0", "0"},
[4300400128] = {4300400128, 13004001, 33, 25, "0", "0", "Be\u{0020}good,\u{0020}Navigator.\u{0020}It's\u{0020}not\u{0020}as\u{0020}painful\u{0020}as\u{0020}you\u{0020}think.", "ナビゲーターはいいコだからな、怖がらなくていい。思っているほど痛くないぞ。", "領航，乖，不要怕，沒有你想像中那麼痛的。", "0", "领航，乖，不要怕，没有你想象中那么痛的。", "0", "cv_sk_ayaka_26", "0", "0"},
[4300400129] = {4300400129, 13004001, 34, 26, "0", "0", "Welcome\u{0020}back,\u{0020}Navigator.\u{0020}Want\u{0020}to\u{0020}give\u{0020}my\u{0020}acupuncture\u{0020}a\u{0020}try?", "ナビゲーター、お帰り。拙者の鍼灸を体験してみないか？", "領航，歡迎回來，要試一下在下的針灸嗎？", "0", "领航，欢迎回来，要试一下在下的针灸吗？", "0", "cv_sk_ayaka_29", "0", "0"},
[4300400130] = {4300400130, 13004001, 35, 27, "0", "0", "There\u{0020}are\u{0020}still\u{0020}people\u{0020}waiting\u{0020}for\u{0020}treatment\u{0020}on\u{0020}the\u{0020}battlefield…\u{0020}Let's\u{0020}get\u{0020}to\u{0020}work!", "戦場には治療が必要な負傷者が沢山いるはず……指示を頼む！", "戰場上，一定有很多人在等待著治療……請下達指示吧！", "0", "战场上，一定有很多人在等待着治疗……请下达指示吧！", "0", "cv_sk_ayaka_31", "0", "0"},
[4300400131] = {4300400131, 13004001, 36, 28, "0", "0", "Only\u{0020}real\u{0020}combat\u{0020}can\u{0020}improve\u{0020}skills!", "技術は実践で鍛えられるものだ！", "只有通過實戰，技藝才能得到鍛煉！", "0", "只有通过实战，技艺才能得到锻炼！", "0", "cv_sk_ayaka_32", "0", "0"},
