[4300500101] = {4300500101, 13005001, 2, 2, "0", "0", "Understood.\u{0020}I'll\u{0020}stand\u{0020}here\u{0020}and\u{0020}keep\u{0020}an\u{0020}eye\u{0020}on\u{0020}your\u{0020}work.", "0", "明白了，我會站在這裏監督您的工作的。", "0", "0", "0", "cv_sk_genia_2", "0", "0"},
[4300500102] = {4300500102, 13005001, 3, 3, "0", "0", "Genia\u{0020}Lee\u{0020}Zaytsev,\u{0020}a\u{0020}medical\u{0020}officer.\u{0020}Leave\u{0020}the\u{0020}treatments\u{0020}to\u{0020}me.", "0", "熱尼亞·李·紮伊采夫，擔任的職位是醫療官，治療的工作就交給我吧。", "0", "0", "0", "cv_sk_genia_1", "0", "0"},
[4300500103] = {4300500103, 13005001, 4, 4, "0", "idle", "Lydia…\u{0020}Yeah,\u{0020}I\u{0020}saved\u{0020}her,\u{0020}but\u{0020}that\u{0020}‘miracle'\u{0020}wasn't\u{0020}just\u{0020}because\u{0020}of\u{0020}me.\u{0020}Her\u{0020}will\u{0020}to\u{0020}survive\u{0020}was\u{0020}unbelievably\u{0020}strong.\u{0020}That's\u{0020}what\u{0020}did\u{0020}it.", "0", "莉迪亞…是的，我的確救過她的性命，但那次“奇跡”並不是因為我一個人而發生的。她那強烈到令人目眩，感到不可思議的求生意志才是關鍵。", "0", "0", "0", "cv_sk_genia_29", "0", "0"},
[4300500104] = {4300500104, 13005001, 5, 4, "0", "idle", "Tired?\u{0020}Compared\u{0020}to\u{0020}my\u{0020}old\u{0020}job,\u{0020}standing\u{0020}here\u{0020}feels\u{0020}like\u{0020}a\u{0020}break.", "0", "您問我累不累…和以前的工作比起來，站在這裏已經是一種休息了。", "0", "0", "0", "cv_sk_genia_3", "0", "0"},
[4300500105] = {4300500105, 13005001, 6, 4, "0", "idle", "Huh...\u{0020}Sorry,\u{0020}I\u{0020}was\u{0020}too\u{0020}relaxed\u{0020}and\u{0020}dozed\u{0020}off.\u{0020}My\u{0020}bad.", "0", "呼…呼…啊，抱歉，因為太放鬆了，不小心睡著了，失禮了。", "0", "0", "0", "cv_sk_genia_4", "0", "0"},
[4300500106] = {4300500106, 13005001, 7, 5, "15_2_0_0.8", "level2", "If\u{0020}it\u{0020}weren't\u{0020}for\u{0020}what\u{0020}happened\u{0020}with\u{0020}my\u{0020}grandma…\u{0020}I\u{0020}don't\u{0020}think\u{0020}I'd\u{0020}want\u{0020}to\u{0020}be\u{0020}a\u{0020}doctor.\u{0020}I\u{0020}guess\u{0020}the\u{0020}reason\u{0020}I\u{0020}keep\u{0020}going\u{0020}is\u{0020}because\u{0020}I\u{0020}can't\u{0020}bear\u{0020}to\u{0020}see\u{0020}anyone\u{0020}die\u{0020}in\u{0020}front\u{0020}of\u{0020}me.", "0", "如果不是奶奶的事…我大概不會想要去成為一名醫生吧。而之所以能夠一直堅持下來，大概是因為我不希望有人在自己眼前死去吧……", "0", "0", "0", "cv_sk_genia_30", "0", "0"},
[4300500107] = {4300500107, 13005001, 8, 5, "15_1_0_0.8", "level1", "What's\u{0020}wrong?\u{0020}Need\u{0020}carpal\u{0020}tunnel\u{0020}surgery?", "0", "怎麼了？需要我給您的腕管做切開手術嗎？", "0", "0", "0", "cv_sk_genia_5", "0", "0"},
[4300500108] = {4300500108, 13005001, 9, 5, "15_1_0_0.8", "level1", "I'm\u{0020}not\u{0020}just\u{0020}here\u{0020}to\u{0020}protect\u{0020}you,\u{0020}but\u{0020}everyone.\u{0020}That's\u{0020}my\u{0020}duty\u{0020}as\u{0020}a\u{0020}doctor.", "0", "不僅是確保您的生命安全，任何人的生命，我都有責任去守護。這就是醫生的職責。", "0", "0", "0", "cv_sk_genia_6", "0", "0"},
[4300500109] = {4300500109, 13005001, 10, 5, "15_1_0_0.8", "level1", "No\u{0020}one\u{0020}can\u{0020}escape\u{0020}death,\u{0020}but\u{0020}I\u{0020}hope\u{0020}people\u{0020}like\u{0020}you\u{0020}can\u{0020}have\u{0020}a\u{0020}peaceful,\u{0020}happy\u{0020}end.", "0", "沒有人能逃過死亡的命運。但——我希望，像您這樣的人，能迎來安詳的，幸福的死。", "0", "0", "0", "cv_sk_genia_7", "0", "0"},
[4300500110] = {4300500110, 13005001, 11, 5, "15_1_0_0.8", "level1", "I've\u{0020}seen\u{0020}enough\u{0020}miracles\u{0020}and\u{0020}lives\u{0020}lost.\u{0020}I'll\u{0020}keep\u{0020}fighting\u{0020}as\u{0020}a\u{0020}doctor.\u{0020}Will\u{0020}you\u{0020}join\u{0020}me,\u{0020}Navigator?", "0", "生命的奇跡與凋零，我見證得足夠多了。今後，我也會一直以醫生的身份去戰鬥。領航，能與我同行嗎？", "0", "0", "0", "cv_sk_genia_8", "0", "0"},
[4300500111] = {4300500111, 13005001, 12, 6, "0", "0", "The\u{0020}treatment's\u{0020}more\u{0020}effective\u{0020}now.", "0", "嗯，治療的效率提高了。", "0", "0", "0", "cv_sk_genia_9", "0", "0"},
[4300500112] = {4300500112, 13005001, 13, 7, "0", "0", "Wait,\u{0020}is\u{0020}there\u{0020}really\u{0020}a\u{0020}way\u{0020}to\u{0020}improve\u{0020}more?", "0", "嗯？還有這種提升手段嗎？", "0", "0", "0", "cv_sk_genia_10", "0", "0"},
[4300500113] = {4300500113, 13005001, 14, 8, "0", "0", "Those\u{0020}soldiers\u{0020}risking\u{0020}everything\u{0020}to\u{0020}end\u{0020}this\u{0020}war\u{0020}need\u{0020}protection.\u{0020}Thank\u{0020}you,\u{0020}Navigator,\u{0020}for\u{0020}giving\u{0020}me\u{0020}the\u{0020}power\u{0020}to\u{0020}help\u{0020}them.", "0", "那些為了結束戰爭而在拼命的戰士，需要人去保護他們。謝謝您，領航，給了我這份力量，我會把它用在正確的地方的。", "0", "0", "0", "cv_sk_genia_11", "0", "0"},
[4300500114] = {4300500114, 13005001, 15, 9, "0", "0", "Medical\u{0020}tech\u{0020}keeps\u{0020}advancing.", "0", "醫療技術還在進步啊。", "0", "0", "0", "cv_sk_genia_12", "0", "0"},
