[4300500131] = {4300500131, 13005001, 34, 26, "0", "0", "Navigator,\u{0020}you're\u{0020}finally\u{0020}here.\u{0020}Here's\u{0020}the\u{0020}report\u{0020}on\u{0020}our\u{0020}last\u{0020}mission.", "0", "您終於來了，領航，這是之前的工作總結，您過目一下吧。", "0", "0", "0", "cv_sk_genia_31", "0", "0"},
[4300500132] = {4300500132, 13005001, 35, 27, "0", "0", "Let's\u{0020}head\u{0020}to\u{0020}the\u{0020}battlefield.\u{0020}There\u{0020}are\u{0020}people\u{0020}counting\u{0020}on\u{0020}us.", "0", "前往戰場吧，那裏有人需要我們。", "0", "0", "0", "cv_sk_genia_33", "0", "0"},
