[4300500139] = {4300500139, 13005001, 42, 34, "0", "0", "Being\u{0020}prepared\u{0020}is\u{0020}part\u{0020}of\u{0020}the\u{0020}job.", "0", "準備是工作的一環。", "0", "0", "0", "cv_sk_genia_40", "0", "0"},
