[4300600101] = {4300600101, 13006001, 2, 2, "0", "0", "Yes!\u{0020}So,\u{0020}what's\u{0020}the\u{0020}hourly\u{0020}wage...\u{0020}What,\u{0020}there\u{0020}isn't\u{0020}one?\u{0020}Tch—", "0", "是！那麼，時薪是…什麼，沒有嗎？嘁——", "0", "0", "0", "cv_sk_yincao_2", "0", "0"},
[4300600102] = {4300600102, 13006001, 3, 3, "0", "0", "I'm\u{0020}Hotarugusa,\u{0020}and\u{0020}I'm\u{0020}here\u{0020}reporting\u{0020}in,\u{0020}Navigator!\u{0020}I'm\u{0020}an\u{0020}agent\u{0020}of\u{0020}the\u{0020}Shingyou\u{0020}House...\u{0020}No,\u{0020}a\u{0020}miko\u{0020}of\u{0020}the\u{0020}Heart\u{0020}Sutra\u{0020}House.", "0", "我來了喔~心經屋的經紀人…不，心經屋的巫女，小瑩草，向你報導，領航。", "0", "0", "0", "cv_sk_yincao_1", "0", "0"},
[4300600103] = {4300600103, 13006001, 4, 4, "0", "idle", "Huh?\u{0020}You're\u{0020}already\u{0020}worn\u{0020}out?\u{0020}You\u{0020}should\u{0020}exercise\u{0020}more—it’s\u{0020}good\u{0020}for\u{0020}you,\u{0020}you\u{0020}know.\u{0020}Or…\u{0020}are\u{0020}you\u{0020}feeling\u{0020}a\u{0020}little\u{0020}low-energy?\u{0020}Need\u{0020}me\u{0020}to\u{0020}keep\u{0020}you\u{0020}company\u{0020}to\u{0020}get\u{0020}you\u{0020}back\u{0020}in\u{0020}the\u{0020}mood?~", "え～？ずっとここでじっとしてるのぉ？健康には適度な運動が欠かせないのにぃ。それとも……私が一緒にやってあげないとダメなのかなぁ？", "唔，這就不動了嗎？多運動運動對身體才好哦。還是說……現在沒什麼精神，需要我陪你一起才有幹勁~？", "0", "0", "0", "cv_sk_yincao_3", "0", "0"},
[4300600104] = {4300600104, 13006001, 5, 4, "0", "idle", "While\u{0020}you\u{0020}weren't\u{0020}looking,\u{0020}I\u{0020}quickly\u{0020}slipped\u{0020}on\u{0020}that\u{0020}adorable\u{0020}little\u{0020}outfit\u{0020}I\u{0020}had\u{0020}prepared\u{0020}for\u{0020}you...\u{0020}Oh?\u{0020}Did\u{0020}you\u{0020}catch\u{0020}me?", "ナビゲーターちゃんが気を取られている間に、準備して来たドール服を着せてっとぉ……あれぇ？気付いちゃったぁ？", "趁領航不注意，趕緊拿出之前準備好的玩偶服給他換上了……咦？被發現了嗎？", "0", "0", "0", "cv_sk_yincao_4", "0", "0"},
[4300600105] = {4300600105, 13006001, 6, 4, "0", "idle", "By\u{0020}the\u{0020}way,\u{0020}doesn't\u{0020}living\u{0020}here\u{0020}all\u{0020}alone\u{0020}feel\u{0020}a\u{0020}bit\u{0020}lonely,\u{0020}Navigator-Chan?\u{0020}Maybe\u{0020}next\u{0020}time\u{0020}I'll\u{0020}invite\u{0020}Kokorokami—or\u{0020}even\u{0020}Hanakotoba\u{0020}and\u{0020}Hoshii—to\u{0020}join\u{0020}us.\u{0020}Just\u{0020}imagine\u{0020}how\u{0020}much\u{0020}fun\u{0020}that\u{0020}would\u{0020}be!", "そういえば、ナビゲーターちゃんだけでここに住むのって、寂しくなぁい？あ、心紙（こころかみ）ちゃんとか、花語（はなことば）ちゃんとか、星井ちゃんたちを捕まえて来よっかぁ。うふふ。考えるだけで面白そぉ。", "說起來，領航一個人住在這裡面會不會有些孤單？要不下次，我把心紙，或者花語、星井她們也抓進來吧，想想就很有意思。", "0", "0", "0", "cv_sk_yincao_28", "0", "0"},
[4300600106] = {4300600106, 13006001, 7, 5, "1_》_0_0.8", "level1", "You're\u{0020}so\u{0020}tiny,\u{0020}just\u{0020}like\u{0020}a\u{0020}little\u{0020}hamster.\u{0020}And\u{0020}oh\u{0020}my,\u{0020}why\u{0020}are\u{0020}those\u{0020}eyes\u{0020}so\u{0020}fixed\u{0020}on\u{0020}my\u{0020}big\u{0020}ear\u{0020}of\u{0020}barley?\u{0020}Teehee,\u{0020}you're\u{0020}absolutely\u{0020}adorable!", "ナビゲーターちゃんたら小さくって、ハムスターみたい。あらら～？どうして私の持ってるムギをじーっと見てるのかなぁ？うふふ。本当に可愛いわねぇ。", "領航這麼小小一隻，簡直就像倉鼠一樣呢。哎呀，眼睛怎麼直勾勾地盯著人家的大麥穗？噗，真是可愛~", "0", "0", "0", "cv_sk_yincao_29", "0", "0"},
[4300600107] = {4300600107, 13006001, 8, 5, "1_》_0_0.8", "level1", "Anything\u{0020}else\u{0020}you’d\u{0020}like\u{0020}for\u{0020}your\u{0020}little\u{0020}house?\u{0020}A\u{0020}climbing\u{0020}ladder,\u{0020}a\u{0020}seesaw,\u{0020}a\u{0020}swing…?\u{0020}As\u{0020}long\u{0020}as\u{0020}it\u{0020}doesn’t\u{0020}go\u{0020}over\u{0020}budget,\u{0020}I’ll\u{0020}do\u{0020}my\u{0020}best\u{0020}to\u{0020}make\u{0020}it\u{0020}happen\u{0020}for\u{0020}you.~", "この家に、あと何か必要なものってある？ハシゴ、シーソー、ブランコ……予算内なら、できるだけ要望に応えるわよぉ。", "對於這間屋子還有什麼需求嗎？爬梯、蹺蹺板、鞦韆……只要不超出預算太多，我都會盡量滿足你哦。", "0", "0", "0", "cv_sk_yincao_5", "0", "0"},
[4300600108] = {4300600108, 13006001, 9, 5, "1_》_0_0.8", "level2", "Even\u{0020}though\u{0020}I'm\u{0020}not\u{0020}a\u{0020}real\u{0020}Miko,\u{0020}I\u{0020}do\u{0020}adore\u{0020}the\u{0020}idea\u{0020}of\u{0020}All\u{0020}the\u{0020}Deities.\u{0020}Living\u{0020}here,\u{0020}surrounded\u{0020}by\u{0020}nature\u{0020}and\u{0020}in\u{0020}harmony\u{0020}with\u{0020}all\u{0020}its\u{0020}creatures,\u{0020}is\u{0020}simply\u{0020}blissful.", "私は本当の巫女じゃないけどぉ、八百万の神って考え方は好きよぉ。この世界で、大自然の霊的存在たちと仲良く暮らすなんて、すっごく素敵じゃない？", "雖然我不是真正的巫女，但對“八百萬神靈”的概念還是挺喜歡的。像這樣身處天地間，與大自然的生靈們和諧共處，在如今也算非常愜意了。", "0", "0", "0", "cv_sk_yincao_6", "0", "0"},
[4300600109] = {4300600109, 13006001, 10, 5, "1_》_0_0.8", "level3", "Besides\u{0020}you,\u{0020}I\u{0020}also\u{0020}have\u{0020}a\u{0020}cat\u{0020}and\u{0020}a\u{0020}parrot\u{0020}at\u{0020}home--watching\u{0020}them\u{0020}is\u{0020}endlessly\u{0020}entertaining.\u{0020}Tell\u{0020}me,\u{0020}Navigator-Chan,\u{0020}if\u{0020}there\u{0020}really\u{0020}are\u{0020}gods\u{0020}out\u{0020}there,\u{0020}do\u{0020}you\u{0020}think\u{0020}they'd\u{0020}be\u{0020}watching\u{0020}us\u{0020}like\u{0020}this?", "ハムスター以外にも、私の家にはネコとオウムがいるんだけどぉ、あの子たちの動きをじーっと見てるのが好きなのぉ。ナビゲーターちゃん。本当に神様がいるとしたら、そんな風に私たちをどこかで観察しているのかなぁ？", "除倉鼠外，我的家裡還養了貓和鸚鵡，靜靜觀賞它們的一舉一動很有意思。領航你說，如果真有神明大人，會不會也像這樣在某處觀察我們呢？", "0", "0", "0", "cv_sk_yincao_7", "0", "0"},
[4300600110] = {4300600110, 13006001, 11, 5, "1_》_0_0.8", "level4", "I\u{0020}know\u{0020}cats\u{0020}have\u{0020}that\u{0020}charming\u{0020}habit\u{0020}of\u{0020}kneading,\u{0020}but\u{0020}I'm\u{0020}not\u{0020}sure\u{0020}if\u{0020}hamsters\u{0020}do\u{0020}that...\u{0020}Hehe,\u{0020}Navigator-Chan,\u{0020}fancy\u{0020}trying\u{0020}out\u{0020}a\u{0020}little\u{0020}kneading\u{0020}session?", "ネコちゃんがふみふみするのは知ってるけど、ハムスターもだっけ？……うふふ。ナビゲーターちゃんは、ハムスターになってみたいのかなぁ？", "我知道貓咪有“踩奶”的習慣，但不太清楚倉鼠是否會這樣……嘿嘿，領航想作為倉鼠體驗一下嗎？", "0", "0", "0", "cv_sk_yincao_8", "0", "0"},
[4300600111] = {4300600111, 13006001, 12, 6, "0", "0", "Thank\u{0020}you\u{0020}for\u{0020}your\u{0020}patronage!", "0", "謝謝惠顧~", "0", "0", "0", "cv_sk_yincao_9", "0", "0"},
[4300600112] = {4300600112, 13006001, 13, 7, "0", "0", "I\u{0020}need\u{0020}to\u{0020}do\u{0020}these\u{0020}profit\u{0020}calculations\u{0020}carefully.", "0", "要好好算下收益呢。", "0", "0", "0", "cv_sk_yincao_10", "0", "0"},
[4300600113] = {4300600113, 13006001, 14, 8, "0", "0", "I\u{0020}swear\u{0020}I\u{0020}can\u{0020}hear\u{0020}the\u{0020}gods'\u{0020}voices...\u{0020}That's\u{0020}not\u{0020}possible.\u{0020}I'm\u{0020}not\u{0020}a\u{0020}\"true\u{0020}miko,\"\u{0020}after\u{0020}all.\u{0020}But\u{0020}even\u{0020}if\u{0020}I\u{0020}can't\u{0020}hear\u{0020}them,\u{0020}I\u{0020}can\u{0020}hear\u{0020}yours,\u{0020}Navigator.", "0", "現在的我，似乎能聽見神明的聲音…那是不可能的啦。畢竟，我並不是“真正的巫女”吧。不過，雖然聽不見神靈的聲音，但我能聽見你的聲音，領航。", "0", "0", "0", "cv_sk_yincao_11", "0", "0"},
