[4300800102] = {4300800102, 13008001, 3, 3, "0", "0", "Isabella.\u{0020}My\u{0020}name\u{0020}is\u{0020}Isabella.\u{0020}Chosen\u{0020}by\u{0020}God,\u{0020}destined\u{0020}for\u{0020}the\u{0020}battlefield.", "伊莎貝拉，我的名字是伊莎貝拉。我是被上天選中的，註定要踏入戰場的人。", "0", "0", "0", "0", "cv_sk_izabera_1", "0", "0"},
[4300800103] = {4300800103, 13008001, 4, 4, "0", "idle", "Even\u{0020}for\u{0020}a\u{0020}swimsuit,\u{0020}it\u{0020}has\u{0020}a\u{0020}quite\u{0020}daring\u{0020}design...\u{0020}But\u{0020}I\u{0020}don't\u{0020}mind\u{0020}if\u{0020}it's\u{0020}for\u{0020}your\u{0020}eyes\u{0020}alone.", "這身泳裝的設計是不是有些太大膽了？不過只是穿給你看的話……也無妨。", "0", "0", "0", "0", "cv_sk_izabera_3", "0", "0"},
[4300800104] = {4300800104, 13008001, 5, 4, "0", "idle", "That\u{0020}Skadi\u{0020}from\u{0020}Moon\u{0020}Corona\u{0020}suddenly\u{0020}said\u{0020}to\u{0020}me\u{0020}aloud,\u{0020}\"Ah,\u{0020}what\u{0020}a\u{0020}perfect\u{0020}villainess\u{0020}look!\"\u{0020}before\u{0020}dashing\u{0020}off\u{0020}again.\u{0020}How\u{0020}absurd.\u{0020}So\u{0020}pissed\u{0020}off!", "那個月冕的斯卡蒂突然跑過來對著我說“啊，好合適的反派角色！”莫名其妙，真讓人火大。", "0", "0", "0", "0", "cv_sk_izabera_4", "0", "0"},
[4300800105] = {4300800105, 13008001, 6, 4, "0", "idle", "On\u{0020}a\u{0020}beach\u{0020}at\u{0020}night...\u{0020}you\u{0020}might\u{0020}see\u{0020}a\u{0020}sky\u{0020}unlike\u{0020}any\u{0020}other.", "如果是夜晚的海灘……或許能看見不同往常的星空。", "0", "0", "0", "0", "cv_sk_izabera_29", "0", "0"},
[4300800106] = {4300800106, 13008001, 7, 5, "15_2_0_0.8", "level2", "How\u{0020}strange.\u{0020}Why\u{0020}does\u{0020}wearing\u{0020}this\u{0020}swimsuit\u{0020}fill\u{0020}me\u{0020}with\u{0020}such\u{0020}satisfaction?\u{0020}As\u{0020}if\u{0020}it\u{0020}has\u{0020}made\u{0020}up\u{0020}for\u{0020}some\u{0020}long-held\u{0020}regret.", "好奇怪，為什麼我穿上泳裝後會有一種滿足感，像是彌補了什麼遺憾……", "0", "0", "0", "0", "cv_sk_izabera_5", "0", "0"},
[4300800107] = {4300800107, 13008001, 8, 5, "15_1_0_0.8", "level1", "Navigator,\u{0020}do\u{0020}I\u{0020}look\u{0020}good\u{0020}in\u{0020}this\u{0020}swimsuit?\u{0020}Hm...\u{0020}Yes?\u{0020}That's\u{0020}good\u{0020}to\u{0020}hear.", "領航，你會不會覺得這泳裝不太適合我？嗯……不會嗎？那就好。", "0", "0", "0", "0", "cv_sk_izabera_30", "0", "0"},
[4300800108] = {4300800108, 13008001, 9, 5, "15_1_0_0.8", "level1", "Coral,\u{0020}seashells,\u{0020}crabs,\u{0020}fish...\u{0020}and\u{0020}you.\u{0020}It\u{0020}seems\u{0020}the\u{0020}ocean's\u{0020}view\u{0020}rivals\u{0020}even\u{0020}the\u{0020}night\u{0020}sky.", "珊瑚、貝殼、螃蟹、魚……還有你，看來海洋的景色，也完全不遜於夜晚的星空。", "0", "0", "0", "0", "cv_sk_izabera_6", "0", "0"},
[4300800109] = {4300800109, 13008001, 10, 5, "15_2_0_0.8", "level2", "When\u{0020}I\u{0020}close\u{0020}my\u{0020}eyes,\u{0020}I\u{0020}can\u{0020}hear\u{0020}the\u{0020}seashells\u{0020}whispering\u{0020}untold\u{0020}stories,\u{0020}with\u{0020}the\u{0020}gentle\u{0020}sound\u{0020}of\u{0020}waves\u{0020}lapping.\u{0020}Just\u{0020}staying\u{0020}here\u{0020}makes\u{0020}it\u{0020}easy\u{0020}to\u{0020}forget\u{0020}everything\u{0020}about\u{0020}war...\u{0020}Yet,\u{0020}that\u{0020}star\u{0020}of\u{0020}fate\u{0020}still\u{0020}shines\u{0020}bright\u{0020}in\u{0020}the\u{0020}sky,\u{0020}serving\u{0020}as\u{0020}a\u{0020}constant\u{0020}reminder\u{0020}of\u{0020}my\u{0020}duty.", "閉上眼睛，仿佛能聽見海灘上的貝殼在敘述不為人知的故事，海浪則在為它伴奏。只是在這裡待著，就能把關於戰爭的事情全部遺忘……只是，那顆命運之星不管何時都會懸掛在天空，提醒著我何為使命。", "0", "0", "0", "0", "cv_sk_izabera_7", "0", "0"},
[4300800110] = {4300800110, 13008001, 11, 5, "15_2_0_0.8", "level2", "I\u{0020}may\u{0020}not\u{0020}be\u{0020}able\u{0020}to\u{0020}rewrite\u{0020}what's\u{0020}set\u{0020}in\u{0020}stone.\u{0020}But\u{0020}before\u{0020}the\u{0020}curtain\u{0020}rises\u{0020}and\u{0020}the\u{0020}final\u{0020}act\u{0020}begins...\u{0020}I'll\u{0020}do\u{0020}whatever\u{0020}it\u{0020}takes\u{0020}to\u{0020}cherish\u{0020}every\u{0020}moment\u{0020}I\u{0020}share\u{0020}with\u{0020}you.\u{0020}Such\u{0020}is\u{0020}my\u{0020}act\u{0020}of\u{0020}defiance.", "我可能沒辦法忤逆自己的宿命，但在那已經知曉結果的答案被揭開前，我會抓緊一切機會去珍惜與你相處的時光，這是我……微不足道的抗爭。", "0", "0", "0", "0", "cv_sk_izabera_8", "0", "0"},
[4300800111] = {4300800111, 13008001, 12, 6, "0", "0", "Good.\u{0020}Let's\u{0020}keep\u{0020}improving\u{0020}like\u{0020}this.", "真好，就這樣一起提升下去吧。", "0", "0", "0", "0", "cv_sk_izabera_9", "0", "0"},
[4300800112] = {4300800112, 13008001, 13, 7, "0", "0", "Wait,\u{0020}am\u{0020}I\u{0020}imagining\u{0020}things?\u{0020}I\u{0020}thought\u{0020}I\u{0020}saw\u{0020}something\u{0020}shine\u{0020}just\u{0020}now...", "咦？是我眼花了嗎？剛剛好像多出了一個亮閃閃的東西……", "0", "0", "0", "0", "cv_sk_izabera_10", "0", "0"},
[4300800113] = {4300800113, 13008001, 14, 8, "0", "0", "Well,\u{0020}this\u{0020}is\u{0020}my\u{0020}fate,\u{0020}and\u{0020}a\u{0020}result\u{0020}of\u{0020}your\u{0020}efforts.\u{0020}Thanks,\u{0020}Navigator.", "嗯，這是我的天命，同時也是你努力的成果，總之，謝謝你領航。", "0", "0", "0", "0", "cv_sk_izabera_11", "0", "0"},
[4300800114] = {4300800114, 13008001, 15, 9, "0", "0", "Shine\u{0020}even\u{0020}brighter.", "變得更加耀眼吧。", "0", "0", "0", "0", "cv_sk_izabera_12", "0", "0"},
[4300800115] = {4300800115, 13008001, 16, 10, "0", "0", "Let's\u{0020}shine\u{0020}together!", "一同閃耀吧！", "0", "0", "0", "0", "cv_sk_izabera_13", "0", "0"},
[4300800116] = {4300800116, 13008001, 17, 11, "0", "0", "Soon,\u{0020}that\u{0020}stars\u{0020}will\u{0020}rise\u{0020}again.", "不久的將來，那顆明星將會再次出現。", "0", "0", "0", "0", "cv_sk_izabera_14", "0", "0"},
[4300800117] = {4300800117, 13008001, 18, 12, "0", "0", "Hmph.\u{0020}The\u{0020}result\u{0020}was\u{0020}decided\u{0020}before\u{0020}it\u{0020}even\u{0020}began.", "哼，一切早在開始前便有了結果。", "0", "0", "0", "0", "cv_sk_izabera_15", "0", "0"},
[4300800118] = {4300800118, 13008001, 19, 13, "0", "0", "If\u{0020}this\u{0020}is\u{0020}fate's\u{0020}design,\u{0020}so\u{0020}be\u{0020}it.", "如果這也是命運的安排，那就這樣吧。", "0", "0", "0", "0", "cv_sk_izabera_16", "0", "0"},
[4300800119] = {4300800119, 13008001, 20, 14, "0", "0", "Not\u{0020}yet...\u{0020}this\u{0020}isn't\u{0020}the\u{0020}end\u{0020}of\u{0020}my\u{0020}destiny.", "還沒有……這裏還不是宿命的終點……", "0", "0", "0", "0", "cv_sk_izabera_17", "0", "0"},
