[4300900101] = {4300900101, 13009001, 2, 2, "0", "0", "This\u{0020}is\u{0020}the\u{0020}first\u{0020}time\u{0020}I've\u{0020}ever\u{0020}held\u{0020}such\u{0020}an\u{0020}important\u{0020}position.", "これほど重要な責務は初めてです。", "我還是第一次擔任這麼重要的職務。", "0", "我还是第一次担任这么重要的职务。", "0", "cv_sk_evatee_2", "0", "0"},
[4300900102] = {4300900102, 13009001, 3, 3, "0", "0", "Aevati,\u{0020}the\u{0020}Midyr\u{0020}interstellar\u{0020}traveler\u{0020}across\u{0020}time\u{0020}and\u{0020}space.\u{0020}Nice\u{0020}to\u{0020}meet\u{0020}you.", "私はエヴァティ。時空を超えて宇宙を旅するミディール人です。お会いできて、光栄です。", "艾伊瓦蒂，跨越時空的米狄爾星際旅行者，能與您相見甚是榮幸。", "0", "艾伊瓦蒂，跨越时空的米狄尔星际旅行者，能与您相见甚是荣幸。", "0", "cv_sk_evatee_1", "0", "0"},
[4300900103] = {4300900103, 13009001, 4, 4, "0", "idle", "This\u{0020}planet's\u{0020}civilization...\u{0020}it's\u{0020}so\u{0020}different\u{0020}from\u{0020}Midyr's.\u{0020}Seeing\u{0020}it\u{0020}with\u{0020}my\u{0020}own\u{0020}eyes\u{0020}makes\u{0020}it\u{0020}even\u{0020}more\u{0020}striking.", "この星の文明は、ミディールと全く違います。自分の目で確かめて、より一層、そう思うようになりました。", "這顆星球的文明……和米狄爾的文明完全不一樣呢。親眼見識過後，我更是這麼覺得。", "0", "这颗星球的文明……和米狄尔的文明完全不一样呢。亲眼见识过后，我更是这么觉得。", "0", "cv_sk_evatee_3", "0", "0"},
[4300900104] = {4300900104, 13009001, 5, 4, "0", "idle", "Day\u{0020}and\u{0020}night\u{0020}feel\u{0020}so\u{0020}different\u{0020}here.\u{0020}Back\u{0020}in\u{0020}the\u{0020}dark\u{0020}void\u{0020}of\u{0020}space,\u{0020}I\u{0020}never\u{0020}noticed.", "昼と夜はこんなに違うのですね。いつも漆黒の宇宙にいたので…気づきませんでした。", "白天和晚上給人的感覺很不一樣呢。以前的我總是身處一片漆黑的宇宙…完全沒法察覺。", "0", "白天和晚上给人的感觉很不一样呢。以前的我总是身处一片漆黑的宇宙…完全没法察觉。", "0", "cv_sk_evatee_4", "0", "0"},
[4300900105] = {4300900105, 13009001, 6, 4, "0", "idle", "If\u{0020}there's\u{0020}a\u{0020}chance,\u{0020}I'd\u{0020}like\u{0020}to\u{0020}restore\u{0020}the\u{0020}Shumia.", "機会があれば、シュミヤを復元したいです。", "如果有機會的話，真想把修米婭號也給復原出來。", "0", "如果有机会的话，真想把修米娅号也给复原出来。", "0", "cv_sk_evatee_30", "0", "0"},
[4300900106] = {4300900106, 13009001, 7, 5, "15_1_0_0.8", "touch1", "Flovira\u{0020}is\u{0020}my\u{0020}best\u{0020}friend.\u{0020}It's\u{0020}delightful\u{0020}watching\u{0020}her\u{0020}enjoy\u{0020}the\u{0020}food\u{0020}I\u{0020}make.", "フロービラは私の親友です。私が作った料理を嬉しそうに食べる彼女を見ると、幸せな気持ちになるのです。", "弗洛維拉是我最要好的朋友，看著她一臉幸福地吃著我做出來的食物，真是開心啊。", "0", "弗洛维拉是我最要好的朋友，看着她一脸幸福地吃着我做出来的食物，真是开心啊。", "0", "cv_sk_evatee_31", "0", "0"},
[4300900107] = {4300900107, 13009001, 8, 5, "15_1_0_0.8", "touch1", "I'm\u{0020}here,\u{0020}Navigator\u{0020}of\u{0020}Earth.", "はい、地球のナビゲーターさん。私はここにいます。", "嗯，我就在這裡，地球的領航。", "0", "嗯，我就在这里，地球的领航。", "0", "cv_sk_evatee_5", "0", "0"},
[4300900108] = {4300900108, 13009001, 9, 5, "15_1_0_0.8", "touch1", "Curious\u{0020}about\u{0020}Shumia's\u{0020}food?\u{0020}It's\u{0020}rare\u{0020}to\u{0020}get\u{0020}asked\u{0020}that.\u{0020}Usually,\u{0020}people\u{0020}are\u{0020}more\u{0020}interested\u{0020}in\u{0020}our\u{0020}travels.\u{0020}This\u{0020}is\u{0020}a\u{0020}first.", "シュミヤで私が作っていた料理のことを知りたいのですか？珍しいですね。私たちが旅先で見てきたものを知りたがる方は多いのですが、私の得意なものに興味を持たれたのは、初めてです。", "想要瞭解修米婭號上的伙食？還真是少見啊，一般大家都對我們的旅行見聞更感興趣。還是第一次有人來打聽我最拿手的事情呢。", "0", "想要了解修米娅号上的伙食？还真是少见啊，一般大家都对我们的旅行见闻更感兴趣。还是第一次有人来打听我最拿手的事情呢。", "0", "cv_sk_evatee_6", "0", "0"},
[4300900109] = {4300900109, 13009001, 10, 5, "15_2_0_0.8", "touch2", "Only\u{0020}through\u{0020}experience\u{0020}do\u{0020}you\u{0020}realize\u{0020}there's\u{0020}no\u{0020}paradise.\u{0020}Being\u{0020}consumed\u{0020}by\u{0020}darkness\u{0020}happens\u{0020}in\u{0020}an\u{0020}instant...\u{0020}but\u{0020}that's\u{0020}all\u{0020}in\u{0020}the\u{0020}past.\u{0020}Waking\u{0020}from\u{0020}that\u{0020}nightmare\u{0020}is\u{0020}enough.", "天国などというものが存在しないことを、この身で体験して初めて理解できました。闇に飲み込まれるのは一瞬で……。ですがそれはもう過去のこと。あの果てしない悪夢から目を覚ますことができただけで、十分です。", "只有親身經歷一次才會明白，這個世界上並不存在天堂。被黑暗吞沒也只是一瞬間的事……但是這些已經過去了，我能從那漫無邊際的噩夢中醒來已經足夠了。", "0", "只有亲身经历一次才会明白，这个世界上并不存在天堂。被黑暗吞没也只是一瞬间的事……但是这些已经过去了，我能从那漫无边际的噩梦中醒来已经足够了。", "0", "cv_sk_evatee_7", "0", "0"},
[4300900110] = {4300900110, 13009001, 11, 5, "15_2_0_0.8", "touch2", "We\u{0020}Midyr\u{0020}people\u{0020}travel\u{0020}through\u{0020}space\u{0020}for\u{0020}the\u{0020}sake\u{0020}of\u{0020}survival.\u{0020}But\u{0020}we\u{0020}don't\u{0020}stay\u{0020}adrift\u{0020}forever.\u{0020}In\u{0020}our\u{0020}culture,\u{0020}when\u{0020}we\u{0020}land,\u{0020}it\u{0020}means\u{0020}meeting\u{0020}the\u{0020}most\u{0020}important\u{0020}person\u{0020}in\u{0020}our\u{0020}life...", "宇宙を旅し続けるのは私たちミディール人の生き方ですが、それはどこにも留まらないということではありません。ナビゲーター。私たちの言い伝えでは、旅人が大地を踏みしめた時に、人生で最も大切な人と出会うと言われているのです。", "在宇宙中不斷旅行是我們米狄爾人的生存方式，但是這並不意味著我們不會停靠在某處。領航，在我們的文化中，當旅行者落地之時，便是與其生命中最重要的人邂逅之時……", "0", "在宇宙中不断旅行是我们米狄尔人的生存方式，但是这并不意味着我们不会停靠在某处。领航，在我们的文化中，当旅行者落地之时，便是与其生命中最重要的人邂逅之时……", "0", "cv_sk_evatee_8", "0", "0"},
[4300900111] = {4300900111, 13009001, 12, 6, "0", "0", "Thank\u{0020}you.", "誠にありがとうございます。", "非常感謝。", "0", "非常感谢。", "0", "cv_sk_evatee_9", "0", "0"},
[4300900112] = {4300900112, 13009001, 13, 7, "0", "0", "What\u{0020}was\u{0020}that\u{0020}just\u{0020}now?", "え？今のは何でしょうか？", "欸？剛剛的那個是什麼？", "0", "哎？刚刚的那个是什么？", "0", "cv_sk_evatee_10", "0", "0"},
[4300900113] = {4300900113, 13009001, 14, 8, "0", "0", "So\u{0020}there\u{0020}are\u{0020}forces\u{0020}on\u{0020}this\u{0020}planet\u{0020}we\u{0020}still\u{0020}don't\u{0020}understand...", "なるほど。この星には、私たちの知らない力があるのですね……", "原來如此，這顆星球上有著我們尚未理解的力量……", "0", "原来如此，这颗星球上有着我们尚未理解的力量……", "0", "cv_sk_evatee_11", "0", "0"},
[4300900114] = {4300900114, 13009001, 15, 9, "0", "0", "I'm\u{0020}sorry.", "お願いします。", "麻煩您了。", "0", "麻烦您了。", "0", "cv_sk_evatee_12", "0", "0"},
[4300900115] = {4300900115, 13009001, 16, 10, "0", "0", "Allow\u{0020}me\u{0020}to\u{0020}help\u{0020}in\u{0020}battle.", "ご尽力させてください。", "請允許我助戰吧。", "0", "请允许我助战吧。", "0", "cv_sk_evatee_13", "0", "0"},
[4300900116] = {4300900116, 13009001, 17, 11, "0", "0", "Success!\u{0020}I\u{0020}didn't\u{0020}mess\u{0020}up,\u{0020}did\u{0020}I,\u{0020}Navigator?", "成功しました。改善点がありましたらご教示ください。", "成功了！我沒有做錯什麼吧，領航。", "0", "成功了！我没有做错什么吧，领航。", "0", "cv_sk_evatee_14", "0", "0"},
[4300900117] = {4300900117, 13009001, 18, 12, "0", "0", "The\u{0020}battle's\u{0020}over.\u{0020}Let\u{0020}me\u{0020}heal\u{0020}everyone's\u{0020}wounds.", "戦闘終了です。負傷者の手当てはお任せください。", "戰鬥已經結束了，就讓我來為大家療傷吧。", "0", "战斗已经结束了，就让我来为大家疗伤吧。", "0", "cv_sk_evatee_15", "0", "0"},
[4300900118] = {4300900118, 13009001, 19, 13, "0", "0", "Still\u{0020}getting\u{0020}used\u{0020}to\u{0020}fighting\u{0020}in\u{0020}this\u{0020}body...", "この姿での戦いにもっと慣れなければ……", "稍微還有些不太習慣用這幅身軀戰鬥……", "0", "稍微还有些不太习惯用这幅身躯战斗……", "0", "cv_sk_evatee_16", "0", "0"},
[4300900119] = {4300900119, 13009001, 20, 14, "0", "0", "Defeated…\u{0020}Again?", "また…敗れてしまったのでしょうか？", "再一次…被擊敗了嗎？", "0", "再一次…被击败了吗？", "0", "cv_sk_evatee_17", "0", "0"},
[4300900120] = {4300900120, 13009001, 23, 16, "0", "0", "Poor\u{0020}soul...", "かわいそうな子……", "可憐的孩子……", "0", "可怜的孩子……", "0", "cv_sk_evatee_18", "0", "0"},
