[4300900123] = {4300900123, 13009001, 25, 18, "0", "0", "Let\u{0020}everything\u{0020}connect,\u{0020}and\u{0020}your\u{0020}wishes\u{0020}will\u{0020}carry\u{0020}on.", "すべては繋がり、願いは絶えず受け継がれていく。", "讓一切都連接起來，你們的願望必會不斷傳遞下去。", "0", "让一切都连接起来，你们的愿望必会不断传递下去。", "0", "cv_sk_evatee_22", "0", "0"},
[4300900124] = {4300900124, 13009001, 21, 15, "0", "0", "Pathetic\u{0020}creature.", "哀れな……", "可悲的傢伙。", "0", "可悲的家伙。", "0", "cv_sk_evatee_19", "0", "0"},
[4300900125] = {4300900125, 13009001, 27, 20, "0", "0", "This\u{0020}is\u{0020}the\u{0020}bathhouse?\u{0020}Didn't\u{0020}expect\u{0020}it\u{0020}to\u{0020}be\u{0020}so\u{0020}spacious.", "ここで体を洗うのですか？このように広い場所だとは思いませんでした。", "這裡就是清洗身體的地方嗎？沒想到連這裡都這麼寬敞。", "0", "这里就是清洗身体的地方吗？没想到连这里都这么宽敞。", "0", "cv_sk_evatee_23", "0", "0"},
[4300900126] = {4300900126, 13009001, 28, 21, "0", "0", "There\u{0020}are\u{0020}showers\u{0020}on\u{0020}the\u{0020}Shumia,\u{0020}but\u{0020}they\u{0020}don't\u{0020}compare\u{0020}to\u{0020}this.", "シュミヤにもシャワールームはありますが、ここと比べては見劣りしてしまいますね。", "修米婭號上也有淋浴間，不過遠比不上這裡。", "0", "修米娅号上也有淋浴间，不过远比不上这里。", "0", "cv_sk_evatee_24", "0", "0"},
[4300900127] = {4300900127, 13009001, 29, 21, "0", "0", "It's\u{0020}been\u{0020}so\u{0020}long\u{0020}since\u{0020}I've\u{0020}had\u{0020}a\u{0020}hot\u{0020}bath...\u{0020}it's\u{0020}been\u{0020}so\u{0020}long...", "久しぶりに温かいお湯に入りました。……本当に、本当に久しぶり……", "好久都沒有洗過熱水澡了……真的是已經過了好久…好久……", "0", "好久都没有洗过热水澡了……真的是已经过了好久…好久……", "0", "cv_sk_evatee_25", "0", "0"},
[4300900128] = {4300900128, 13009001, 30, 22, "0", "0", "Let\u{0020}me\u{0020}help\u{0020}you.", "サポートさせてください。", "還請讓我來支援您吧。", "0", "还请让我来支援您吧。", "0", "cv_sk_evatee_26", "0", "0"},
[4300900129] = {4300900129, 13009001, 31, 23, "0", "0", "Alright,\u{0020}guess\u{0020}who\u{0020}I\u{0020}am?", "では、私を当ててみてください。", "好了，來猜猜看我是誰吧？", "0", "好了，来猜猜看我是谁吧？", "0", "cv_sk_evatee_27", "0", "0"},
[4300900130] = {4300900130, 13009001, 32, 24, "0", "0", "Wait,\u{0020}how\u{0020}did\u{0020}you\u{0020}figure\u{0020}it\u{0020}out?!", "おや。いつお分かりになったのですか？", "欸？是什麼時候猜出來的？！", "0", "哎？是什么时候猜出来的？！", "0", "cv_sk_evatee_28", "0", "0"},
[4300900131] = {4300900131, 13009001, 33, 25, "0", "0", "Heh,\u{0020}don't\u{0020}guess\u{0020}wrong\u{0020}next\u{0020}time.", "あら。次は間違わないでくださいね。", "嘿嘿嘿，下次可不要再猜錯了。", "0", "嘿嘿嘿，下次可不要再猜错了。", "0", "cv_sk_evatee_29", "0", "0"},
[4300900132] = {4300900132, 13009001, 34, 26, "0", "0", "Back\u{0020}again,\u{0020}Navigator?", "ナビゲーターさん、お帰りなさいませ。", "是領航回來了嗎？", "0", "是领航回来了吗？", "0", "cv_sk_evatee_32", "0", "0"},
[4300900133] = {4300900133, 13009001, 35, 27, "0", "0", "Let's\u{0020}continue\u{0020}the\u{0020}journey.", "旅を続けましょう。", "繼續旅行下去吧。", "0", "继续旅行下去吧。", "0", "cv_sk_evatee_34", "0", "0"},
