[4300900135] = {4300900135, 13009001, 37, 29, "0", "0", "A\u{0020}companion\u{0020}worth\u{0020}fighting\u{0020}with.", "共に戦ってくれる仲間たちです。", "這是一同戰鬥的夥伴。", "0", "这是一同战斗的伙伴。", "0", "cv_sk_evatee_36", "0", "0"},
[4300900136] = {4300900136, 13009001, 38, 30, "0", "0", "This\u{0020}is\u{0020}where\u{0020}we\u{0020}recruit\u{0020}others.", "新人募集の入り口です。", "招募新人的入口。", "0", "招募新人的入口。", "0", "cv_sk_evatee_37", "0", "0"},
