[4300900143] = {4300900143, 13009001, 45, 37, "0", "0", "I\u{0020}understand.", "分かりました。", "我明白了。", "0", "我明白了。", "0", "cv_sk_evatee_44", "0", "0"},
[4301000100] = {4301000100, 13010001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧残響（ハツリバーブ）。", "蒼霧殘響", "0", "0", "0", "cv_sk_qu_1", "0", "0"},
[4301000101] = {4301000101, 13010001, 2, 2, "0", "0", "This\u{0020}is\u{0020}strange...\u{0020}it's\u{0020}not\u{0020}within\u{0020}the\u{0020}scope\u{0020}of\u{0020}my\u{0020}mission,\u{0020}but...\u{0020}Oh\u{0020}well.", "……変ね。私の任務範囲じゃなさそうだけど。まあ、いいわ。", "真是奇怪啊，這可不在我的任務範圍，不過…這樣也好。", "0", "0", "0", "cv_sk_qu_2", "0", "0"},
[4301000102] = {4301000102, 13010001, 3, 3, "0", "0", "Are\u{0020}you\u{0020}the\u{0020}new\u{0020}Navigator?\u{0020}Please\u{0020}look\u{0020}after\u{0020}me.\u{0020}Whatever\u{0020}it\u{0020}is—battle,\u{0020}or\u{0020}just\u{0020}life—come\u{0020}to\u{0020}me.\u{0020}Oh,\u{0020}and\u{0020}were\u{0020}you\u{0020}shocked\u{0020}when\u{0020}you\u{0020}first\u{0020}saw\u{0020}us?", "新しいナビゲーター？これからよろしくね。戦闘でもそれ以外でも、困ったことがあれば力になるわ。……ねえ。私たちを初めて見て、驚いたかしら？", "新來的領航？今後就請多多關照了，無論是戰鬥還是生活的事都可以找我幫忙。話說，你看到我們時會嚇一跳嗎？", "0", "0", "0", "cv_sk_qu_3", "0", "0"},
[4301000103] = {4301000103, 13010001, 4, 4, "0", "idle", "...\u{0020}Although\u{0020}it's\u{0020}just\u{0020}a\u{0020}whim\u{0020}for\u{0020}now,\u{0020}I\u{0020}once\u{0020}thought\u{0020}of\u{0020}being\u{0020}a\u{0020}nurse\u{0020}before.\u{0020}Um,\u{0020}when\u{0020}I\u{0020}was\u{0020}a\u{0020}child.", "……ただの気まぐれだったけど、以前ナースになろうと思ったことがあるの。子供の頃だけどね。", "……雖然現在只是一時興起，不過我以前也想過當一名護士哦。嗯，在我還是個孩子的時候。", "0", "0", "0", "cv_sk_qu_4", "0", "0"},
[4301000104] = {4301000104, 13010001, 5, 4, "0", "idle", "If\u{0020}I\u{0020}were\u{0020}a\u{0020}nurse,\u{0020}then\u{0020}Navigator,\u{0020}are\u{0020}you\u{0020}a\u{0020}doctor\u{0020}working\u{0020}with\u{0020}me,\u{0020}or...\u{0020}Are\u{0020}you\u{0020}a\u{0020}patient\u{0020}at\u{0020}my\u{0020}mercy?", "私がナースだったら、ナビゲーターは医者として私の仕事仲間になりたい？それとも……患者としていたずらされたい？", "如果我是護士的話，那麼領航你到底是和我共事的醫生，還是說……是任我擺弄的傷患呢？", "0", "0", "0", "cv_sk_qu_5", "0", "0"},
[4301000105] = {4301000105, 13010001, 6, 4, "0", "idle", "Right,\u{0020}call\u{0020}Shirogane\u{0020}next\u{0020}time\u{0020}-\u{0020}I\u{0020}also\u{0020}want\u{0020}to\u{0020}see\u{0020}that\u{0020}child\u{0020}wearing\u{0020}this\u{0020}outfit\u{0020}and\u{0020}being\u{0020}stared\u{0020}at\u{0020}by\u{0020}the\u{0020}Navigator.\u{0020}It\u{0020}must\u{0020}be\u{0020}very\u{0020}interesting.", "そうだ、今度はギンも呼んでおこうかしら。この衣装を着たあの子が、ナビゲーターに見つめられるところを見てみたいかも。絶対に面白いわ。", "對了，下次叫上銀吧——我也想看那孩子換上這身服裝，被領航盯著看的模樣，一定會很有趣的。", "0", "0", "0", "cv_sk_qu_6", "0", "0"},
[4301000106] = {4301000106, 13010001, 7, 5, "15_1_0_0.8", "level1", "If\u{0020}there's\u{0020}really\u{0020}a\u{0020}day\u{0020}when\u{0020}the\u{0020}war\u{0020}ends,\u{0020}then\u{0020}I\u{0020}might\u{0020}look\u{0020}for\u{0020}a\u{0020}job\u{0020}on\u{0020}Earth...\u{0020}How\u{0020}about\u{0020}being\u{0020}the\u{0020}Navigator's\u{0020}private\u{0020}nurse?", "いつか本当に戦争が終わったら、地球で新しい仕事を見つけないといけないわね。……ナビゲーターの専属ナースになるってのはどうかしら？", "如果戰爭真的有結束的那一天，屆時我可能要在地球上找一份工作……去當領航的私人護士怎麼樣？", "0", "0", "0", "cv_sk_qu_7", "0", "0"},
[4301000107] = {4301000107, 13010001, 8, 5, "15_2_0_0.8", "level2", "What's\u{0020}wrong?\u{0020}Do\u{0020}you\u{0020}want\u{0020}a\u{0020}physical\u{0020}examination?", "どうしたの？健康診断でも受けたい?", "怎麼了，是想來一次身體檢查嗎？", "0", "0", "0", "cv_sk_qu_8", "0", "0"},
[4301000108] = {4301000108, 13010001, 9, 5, "15_1_0_0.8", "level1", "It\u{0020}will\u{0020}hurt\u{0020}when\u{0020}the\u{0020}needle\u{0020}goes\u{0020}in\u{0020}-\u{0020}But\u{0020}the\u{0020}medicine\u{0020}can\u{0020}only\u{0020}enter\u{0020}your\u{0020}body\u{0020}like\u{0020}this\u{0020}to\u{0020}cure\u{0020}your\u{0020}illness.\u{0020}Life\u{0020}is\u{0020}always\u{0020}like\u{0020}this.", "針で刺されるの、痛いでしょう。でも、そうすることで薬が体内に入って、病気を治してくれるわ。人生もそんな感じよ。", "針在刺進去的時候會很痛吧——不過藥物要這樣才能進入你的身體，治愈你的疾病，生活也總是如此。", "0", "0", "0", "cv_sk_qu_9", "0", "0"},
[4301000109] = {4301000109, 13010001, 10, 5, "15_1_0_0.8", "level1", "This\u{0020}nurse\u{0020}outfit\u{0020}wasn't\u{0020}like\u{0020}this\u{0020}when\u{0020}it\u{0020}was\u{0020}initially\u{0020}designed.\u{0020}I\u{0020}analyzed\u{0020}your\u{0020}usual\u{0020}hobbies,\u{0020}Navigator,\u{0020}and\u{0020}specially\u{0020}redesigned\u{0020}it.\u{0020}Now\u{0020}it\u{0020}seems...\u{0020}Hehe,\u{0020}the\u{0020}effort\u{0020}should\u{0020}not\u{0020}have\u{0020}been\u{0020}wasted,\u{0020}right?", "このナース服、最初はこんな感じじゃなかったのよ。ナビゲーターの興味や嗜好を分析して、特別にデザインし直したの。……その苦労は、無駄じゃなかったみたいね、ふふ。", "這身護士服在最初設計的時候可不是這樣的，我分析了領航你平時的興趣愛好，特意進行了再設計。現在看來……呵呵，應該沒有白費功夫吧？", "0", "0", "0", "cv_sk_qu_10", "0", "0"},
[4301000110] = {4301000110, 13010001, 11, 5, "15_2_0_0.8", "level2", "The\u{0020}sense\u{0020}of\u{0020}security\u{0020}isn't\u{0020}given\u{0020}by\u{0020}words\u{0020}but\u{0020}provided\u{0020}by\u{0020}actions.\u{0020}Navigator\u{0020}has\u{0020}given\u{0020}me\u{0020}a\u{0020}peaceful\u{0020}home\u{0020}-\u{0020}And\u{0020}I\u{0020}will\u{0020}do\u{0020}my\u{0020}best\u{0020}to\u{0020}make\u{0020}Navigator\u{0020}feel\u{0020}at\u{0020}ease\u{0020}with\u{0020}me.", "安心感は言葉ではなく、行動によって与えられるものよ。ナビゲーターは、私に安心できる居場所を与えてくれた…。…私も、ナビゲーターがここで安心できるように尽くすわ。", "安全感並不是靠話語施捨的，而是用行動去給予的，領航給了我一個安心的家——而我也會盡可能地，讓領航在我這裡感到心安。", "0", "0", "0", "cv_sk_qu_11", "0", "0"},
[4301000111] = {4301000111, 13010001, 12, 6, "0", "0", "Thanks\u{0020}for\u{0020}that.", "ありがとう。", "謝謝。", "0", "0", "0", "cv_sk_qu_12", "0", "0"},
[4301000112] = {4301000112, 13010001, 13, 7, "0", "0", "\u{0020}I'll\u{0020}do\u{0020}whatever\u{0020}it\u{0020}takes\u{0020}to\u{0020}grow\u{0020}stronger\u{0020}for\u{0020}those\u{0020}I\u{0020}care.", "同胞のために、もっと強くなりたい。", "如果是為了同胞們，我願意變強。", "0", "0", "0", "cv_sk_qu_13", "0", "0"},
[4301000113] = {4301000113, 13010001, 14, 8, "0", "0", "\"Awakening,\"\u{0020}huh?\u{0020}Makes\u{0020}me\u{0020}think\u{0020}of...\u{0020}before.\u{0020}Navigator,\u{0020}I\u{0020}made\u{0020}you\u{0020}a\u{0020}promise.\u{0020}I\u{0020}won't\u{0020}make\u{0020}the\u{0020}same\u{0020}mistake\u{0020}twice.\u{0020}Failing\u{0020}once\u{0020}was\u{0020}more\u{0020}than\u{0020}enough.", "覚醒、ね……昔を思い出すわ……ナビゲーター、約束するわ。私はもう同じ失敗を繰り返さない。苦汁をなめるのは一度で十分よ。", "“覺醒”嗎…這讓我想起了以前的事……領航，我和你約定好了，我不會再重蹈覆轍了。失敗的苦楚，對我來說品嘗一次就足夠了。", "0", "0", "0", "cv_sk_qu_14", "0", "0"},
[4301000114] = {4301000114, 13010001, 15, 9, "0", "0", "New\u{0020}skills\u{0020}are\u{0020}always\u{0020}worth\u{0020}picking\u{0020}up.", "新技ね。使いこなしてみせるわ。", "全新的技藝，值得學習。", "0", "0", "0", "cv_sk_qu_15", "0", "0"},
[4301000115] = {4301000115, 13010001, 16, 10, "0", "0", "I'll\u{0020}keep\u{0020}you\u{0020}safe.", "私があなた達を守ってみせる。", "我會保證你們的安全。", "0", "0", "0", "cv_sk_qu_16", "0", "0"},
[4301000116] = {4301000116, 13010001, 17, 11, "0", "0", "Just\u{0020}put\u{0020}your\u{0020}faith\u{0020}in\u{0020}them.", "信じて……いいのね。", "只要相信她們就好了。", "0", "0", "0", "cv_sk_qu_17", "0", "0"},
[4301000117] = {4301000117, 13010001, 18, 12, "0", "0", "Let\u{0020}me\u{0020}take\u{0020}care\u{0020}of\u{0020}the\u{0020}wounded.", "負傷者はこっちに！", "由我來治療傷患吧。", "0", "0", "0", "cv_sk_qu_18", "0", "0"},
[4301000118] = {4301000118, 13010001, 19, 13, "0", "0", "Next\u{0020}time,\u{0020}push\u{0020}harder.\u{0020}Let\u{0020}me\u{0020}check\u{0020}where\u{0020}you're\u{0020}hurt\u{0020}first.", "反省は後よ。早く傷を見せて。", "下一次再努力吧，先讓我看看哪里受傷了。", "0", "0", "0", "cv_sk_qu_19", "0", "0"},
[4301000119] = {4301000119, 13010001, 20, 14, "0", "0", "We\u{0020}save\u{0020}lives\u{0020}first,\u{0020}then\u{0020}look\u{0020}for\u{0020}our\u{0020}next\u{0020}shot.", "生き延びることが最優先よ。チャンスはまた来るわ。", "先保住性命，等待下一次機會。", "0", "0", "0", "cv_sk_qu_20", "0", "0"},
[4301000120] = {4301000120, 13010001, 23, 16, "0", "0", "I'll\u{0020}be\u{0020}gentler\u{0020}than\u{0020}usual\u{0020}~", "いつもより優しくするわね。", "我會比往常更溫柔的~", "0", "0", "0", "cv_sk_qu_21", "0", "0"},
[4301000121] = {4301000121, 13010001, 26, 19, "0", "0", "Well,\u{0020}that's\u{0020}it\u{0020}for\u{0020}today.", "じゃあ、今日はここまでね。", "那麼，今天就到這裡了。", "0", "0", "0", "cv_sk_qu_22", "0", "0"},
[4301000122] = {4301000122, 13010001, 24, 17, "0", "0", "The\u{0020}pain\u{0020}has\u{0020}flown\u{0020}away\u{0020}~", "痛いの痛いの、飛んでいけ～", "痛痛飛走咯~", "0", "0", "0", "cv_sk_qu_23", "0", "0"},
[4301000123] = {4301000123, 13010001, 27, 20, "0", "0", "It's\u{0020}been\u{0020}ages\u{0020}since\u{0020}I\u{0020}had\u{0020}a\u{0020}quiet\u{0020}bath.", "落ち着いてお風呂に入るのは久しぶりね。", "好久沒有安心地泡澡了。", "0", "0", "0", "cv_sk_qu_24", "0", "0"},
[4301000124] = {4301000124, 13010001, 28, 21, "0", "0", "I\u{0020}wonder\u{0020}if\u{0020}this\u{0020}soap\u{0020}will\u{0020}ruin\u{0020}my\u{0020}fur.", "このボディーソープ、毛が痛まないかしら……", "不知道這個沐浴露會不會損傷毛髮。", "0", "0", "0", "cv_sk_qu_25", "0", "0"},
[4301000125] = {4301000125, 13010001, 29, 21, "0", "0", "This\u{0020}pool\u{0020}feels\u{0020}crowded.", "少し狭いわね。", "水池有點擠呢。", "0", "0", "0", "cv_sk_qu_26", "0", "0"},
[4301000126] = {4301000126, 13010001, 30, 22, "0", "0", "Navigator...\u{0020}Are\u{0020}you\u{0020}ready?", "ナビゲーター、準備はできた？", "領航……準備好了麼？", "0", "0", "0", "cv_sk_qu_27", "0", "0"},
[4301000127] = {4301000127, 13010001, 31, 23, "0", "0", "My\u{0020}fur\u{0020}color...\u{0020}you\u{0020}think\u{0020}it's\u{0020}obvious?", "私の毛色なら……わかるわよね。", "我的毛色……應該很好猜吧。", "0", "0", "0", "cv_sk_qu_28", "0", "0"},
