[4301000137] = {4301000137, 13010001, 41, 33, "0", "0", "How\u{0020}do\u{0020}humans\u{0020}not\u{0020}freeze\u{0020}without\u{0020}fur?", "人間には毛皮がないけど、寒くないの？", "人類沒有皮毛不會冷嗎？", "0", "0", "0", "cv_sk_qu_38", "0", "0"},
[4301000138] = {4301000138, 13010001, 42, 34, "0", "0", "That's\u{0020}a\u{0020}pretty\u{0020}clever\u{0020}way\u{0020}to\u{0020}do\u{0020}it.", "面白いやり方ね。", "非常新奇的方式。", "0", "0", "0", "cv_sk_qu_39", "0", "0"},
[4301000139] = {4301000139, 13010001, 43, 35, "0", "0", "Take\u{0020}a\u{0020}look.", "メールをチェックして。", "查看一下吧。", "0", "0", "0", "cv_sk_qu_40", "0", "0"},
[4301000140] = {4301000140, 13010001, 44, 36, "0", "0", "The\u{0020}whole\u{0020}world's\u{0020}tuned\u{0020}in\u{0020}to\u{0020}us\u{0020}now.", "世界中に聞こえるわよ。", "全世界都能聽到。", "0", "0", "0", "cv_sk_qu_41", "0", "0"},
[4301000141] = {4301000141, 13010001, 45, 37, "0", "0", "Mhm.", "ふふ。", "嗯哼。", "0", "0", "0", "cv_sk_qu_42", "0", "0"},
[4301100100] = {4301100100, 13011001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "ハツリバーブ", "蒼霧殘響", "0", "0", "0", "cv_sk_meiliya_1", "0", "0"},
[4301100101] = {4301100101, 13011001, 2, 2, "0", "0", "Putting\u{0020}on\u{0020}an\u{0020}act\u{0020}is\u{0020}child's\u{0020}play,\u{0020}and\u{0020}it's\u{0020}what\u{0020}I\u{0020}do\u{0020}best.", "猫を被るのは、得意ですよ。", "不就是裝模作樣，這種事我再擅長不過。", "0", "0", "0", "cv_sk_meiliya_2", "0", "0"},
[4301100102] = {4301100102, 13011001, 3, 3, "0", "0", "Greetings.\u{0020}I\u{0020}am\u{0020}Meria,\u{0020}a\u{0020}devout\u{0020}saintess\u{0020}of\u{0020}the\u{0020}Holy\u{0020}Church.\u{0020}May\u{0020}the\u{0020}ever-flowing\u{0020}water\u{0020}bless\u{0020}us...\u{0020}Hehe.\u{0020}Is\u{0020}that\u{0020}what\u{0020}you\u{0020}want\u{0020}to\u{0020}hear\u{0020}from\u{0020}me,\u{0020}Navigator?\u{0020}How\u{0020}perverse.", "初めまして、聖濯教会の敬虔な聖女、メリアです。永遠の水が、私たちに祝福をもたらしますように……ふふっ、ナビゲーターさんは、こういうセリフが聞きたかったのですか？ほんとう、変態ですね。", "您好，我是梅莉雅，聖濯教會的一名虔誠的聖女，願源遠流長之水為我們帶來祝福……呵呵，領航想聽到的就是這種台詞？真是變態呢。", "0", "0", "0", "cv_sk_meiliya_3", "0", "0"},
[4301100103] = {4301100103, 13011001, 91, 4, "0", "idle", "I\u{0020}planted\u{0020}these\u{0020}flowers\u{0020}when\u{0020}I\u{0020}was\u{0020}a\u{0020}child.\u{0020}To\u{0020}see\u{0020}them\u{0020}still\u{0020}blooming,\u{0020}so\u{0020}untouched\u{0020}by\u{0020}time...\u{0020}it\u{0020}stirs\u{0020}a\u{0020}strange,\u{0020}almost\u{0020}maternal\u{0020}sense\u{0020}of\u{0020}pride.", "子供の頃に植えた花が、今も元気に咲いているのを見て、心の中が急に……これが母性というものでしょうか？", "這些花都是我小時候親手种下的，看到它們時至今日也依然健康、無暇地盛開著，心裡忽然產生了一種……欣慰的母親的感覺？", "0", "0", "0", "cv_sk_meiliya_4", "0", "0"},
[4301100104] = {4301100104, 13011001, 91, 4, "0", "idle", "What\u{0020}would\u{0020}happen\u{0020}if\u{0020}I\u{0020}used\u{0020}the\u{0020}Holy\u{0020}Grail\u{0020}to\u{0020}water\u{0020}this\u{0020}parched\u{0020}well?\u{0020}Not\u{0020}that\u{0020}I\u{0020}expect\u{0020}any\u{0020}miracles.\u{0020}Still,\u{0020}I\u{0020}brought\u{0020}it.", "この枯れた井戸に聖杯で水を注いだら、何か奇跡が起きたりするでしょうか？…期待はしていませんが、聖杯を持ってきています。", "用聖杯盛水來澆灌這座早已乾枯的井，是否會發生什麼奇跡呢？儘管對此絲毫不期待，我還是將聖杯帶來了。", "0", "0", "0", "cv_sk_meiliya_5", "0", "0"},
[4301100105] = {4301100105, 13011001, 94, 4, "0", "idle2", "You\u{0020}getting\u{0020}used\u{0020}to\u{0020}the\u{0020}place\u{0020}like\u{0020}this,\u{0020}Navigator?\u{0020}Well,\u{0020}a\u{0020}gilded\u{0020}church\u{0020}or\u{0020}a\u{0020}filthy\u{0020}well.\u{0020}They're\u{0020}all\u{0020}the\u{0020}same\u{0020}to\u{0020}me.\u{0020}Quiet\u{0020}places\u{0020}to\u{0020}reflect.", "この場所には慣れましたか？私は嫌いではないんです。明るい教会も、泥だらけの井戸の底も、一人で何かを考えるのに適した静かな場所ですから。", "領航在這種地方待著還習慣嗎？反正對我來說是沒差啦，光鮮亮麗的教堂，充滿淤泥的井底，都是一種適合沉思的幽靜之處。", "0", "0", "0", "cv_sk_meiliya_6", "0", "0"},
[4301100106] = {4301100106, 13011001, 94, 4, "0", "idle2", "Still\u{0020}staring\u{0020}so\u{0020}intently?\u{0020}You\u{0020}really\u{0020}are\u{0020}a\u{0020}pervert.\u{0020}Fine.\u{0020}Look\u{0020}all\u{0020}you\u{0020}want.\u{0020}Tomorrow,\u{0020}the\u{0020}perfect\u{0020}saintess\u{0020}is\u{0020}back,\u{0020}so\u{0020}enjoy\u{0020}the\u{0020}real\u{0020}me\u{0020}while\u{0020}it\u{0020}lasts\u{0020}and\u{0020}remember\u{0020}it\u{0020}well.", "相変わらず人を見つめるのが好きなのですね、変態さん。ですが、明日からはまたあの華やかな服を着なければいけないので、今の私の姿、しっかりと目に焼き付けてくださいね。", "還是這麼喜歡死死盯著人家看呢，真是變態。不過，畢竟明天我又會披回那身華麗的偽裝，你就趁現在將我最本真的模樣牢牢記在心裡好了。", "0", "0", "0", "cv_sk_meiliya_7", "0", "0"},
[4301100107] = {4301100107, 13011001, 93, 5, "14_》_0_0.8", "touch_s1", "Tch.", "へぇ～", "嚯~", "0", "0", "0", "cv_sk_meiliya_8", "0", "0"},
[4301100108] = {4301100108, 13011001, 96, 5, "14_》_0_0.8", "touch_s2", "Weird\u{0020}one.", "変な方ですね。", "奇怪的傢伙。", "0", "0", "0", "cv_sk_meiliya_9", "0", "0"},
[4301100109] = {4301100109, 13011001, 92, 5, "14_》_0_0.8", "touch1", "You\u{0020}want\u{0020}to\u{0020}lie\u{0020}here\u{0020}with\u{0020}me?\u{0020}Well,\u{0020}I'll\u{0020}allow\u{0020}it.\u{0020}But\u{0020}this\u{0020}is\u{0020}my\u{0020}private\u{0020}place.\u{0020}There's\u{0020}an\u{0020}admission\u{0020}fee,\u{0020}so\u{0020}you're\u{0020}not\u{0020}getting\u{0020}in\u{0020}for\u{0020}free.\u{0020}Pay\u{0020}up.", "ナビゲーターさんもここで一緒に寝たいのですか？うーん、駄目ではないですが、ここは私だけの秘密基地なんです。入場料をください。ケチらないで下さいよ？", "領航也想一起躺在這裡？哼，倒也不是不行，但這可是我私人的秘密基地，入場費就別想省下了，老老實實給我交出來~", "0", "0", "0", "cv_sk_meiliya_10", "0", "0"},
[4301100110] = {4301100110, 13011001, 92, 5, "14_》_0_0.8", "touch2", "You're\u{0020}the\u{0020}only\u{0020}one\u{0020}who's\u{0020}seen\u{0020}me\u{0020}like\u{0020}this.\u{0020}And\u{0020}still,\u{0020}you\u{0020}want\u{0020}more?\u{0020}Then\u{0020}swear\u{0020}you'll\u{0020}never\u{0020}speak\u{0020}a\u{0020}word\u{0020}of\u{0020}it.\u{0020}Hah.\u{0020}Isn't\u{0020}it\u{0020}ironic?\u{0020}A\u{0020}liar\u{0020}like\u{0020}me,\u{0020}asking\u{0020}for\u{0020}a\u{0020}promise.", "こんな私を見たのは、あなただけです。…まだ満足していないのですか？では、内緒にすると誓えますか？ふふ……私のような嘘つきが、他人に何かを誓わせるなんて、なんだか皮肉ですね。", "只有你見過我的這副模樣，可你還不滿足，還想見到更多嗎？那麼你能發誓自己會守口如瓶？唔……我這種謊話連篇的人卻要別人發誓，確實諷刺。", "0", "0", "0", "cv_sk_meiliya_11", "0", "0"},
[4301100111] = {4301100111, 13011001, 95, 5, "14_》_0_0.8", "touch3", "There\u{0020}your\u{0020}restless\u{0020}hand\u{0020}goes\u{0020}again.\u{0020}Is\u{0020}this\u{0020}my\u{0020}punishment?\u{0020}Because\u{0020}I\u{0020}stole\u{0020}from\u{0020}you,\u{0020}now\u{0020}you\u{0020}want\u{0020}to\u{0020}take\u{0020}something\u{0020}of\u{0020}mine?\u{0020}My\u{0020}heart,\u{0020}my\u{0020}body...\u{0020}And\u{0020}more?", "また私に手を伸ばしてきたのは、罰ですか？私があなたの物を盗んだから、私の心と体、全てを盗もうと？", "又伸出了你那不安分的手啊，這是對我的懲罰嗎？因為我偷走過你的物品，所以你也想反過來竊走我的心，我的身體，以及更多？", "0", "0", "0", "cv_sk_meiliya_46", "0", "0"},
[4301100112] = {4301100112, 13011001, 95, 5, "14_》_0_0.8", "touch3", "You\u{0020}should\u{0020}leave\u{0020}something\u{0020}here\u{0020}tonight\u{0020}too,\u{0020}Navigator.\u{0020}How\u{0020}about...\u{0020}we\u{0020}plant\u{0020}some\u{0020}new\u{0020}flowers?\u{0020}We\u{0020}could\u{0020}water\u{0020}them\u{0020}and\u{0020}watch\u{0020}them\u{0020}thrive.", "ここを出る前に、ナビゲーターさんもこの井戸の底に何か残してください。たとえば……一緒に花を植えるとか。これから毎日、水をあげて、お世話しませんか？", "今夜過後，領航也在這處井底留下些什麼吧。就比如說……我們可以一起种些新的花朵，然後每天輪換著為它澆水，照料它茁壯成長。", "0", "0", "0", "cv_sk_meiliya_47", "0", "0"},
[4301100113] = {4301100113, 13011001, 95, 5, "14_》_0_0.8", "touch4", "Phew...", "ふう。", "呼~", "0", "0", "0", "cv_sk_meiliya_48", "0", "0"},
[4301100114] = {4301100114, 13011001, 12, 6, "0", "0", "Can\u{0020}we\u{0020}just\u{0020}pretend\u{0020}I'm\u{0020}not\u{0020}here?", "私をいないものとして扱ってもらえませんか？", "就不能當沒我這號人？", "0", "0", "0", "cv_sk_meiliya_12", "0", "0"},
[4301100115] = {4301100115, 13011001, 13, 7, "0", "0", "A\u{0020}raise\u{0020}in\u{0020}my\u{0020}paycheck\u{0020}would\u{0020}be\u{0020}better.", "お給料も上がると良いですね。", "要是薪水也能增加就好了。", "0", "0", "0", "cv_sk_meiliya_13", "0", "0"},
[4301100116] = {4301100116, 13011001, 14, 8, "0", "0", "They\u{0020}say\u{0020}\"More\u{0020}power,\u{0020}more\u{0020}responsibility.\"\u{0020}Why\u{0020}are\u{0020}you\u{0020}so\u{0020}eager\u{0020}to\u{0020}dump\u{0020}more\u{0020}on\u{0020}me?\u{0020}If\u{0020}I\u{0020}keep\u{0020}slacking,\u{0020}I'll\u{0020}just\u{0020}look\u{0020}like\u{0020}I'm\u{0020}disappointing\u{0020}you.\u{0020}So\u{0020}annoying.", "能力が上がると、責任も重くなるとよく言われますが、なぜ私に大きな責任を背負わせようとするのですか？このまま逃げ続けてしまったら、あなたの期待を裏切ったように見えるではないですか…まったく。", "總說能力增長伴隨責任增加，為什麼一定要我承擔更大的責任才滿意？要是我繼續擺爛下去，不就顯得像辜負了你的期待嗎，真是的。", "0", "0", "0", "cv_sk_meiliya_14", "0", "0"},
[4301100117] = {4301100117, 13011001, 15, 9, "0", "0", "Studying\u{0020}is\u{0020}the\u{0020}worst.", "勉強はいやです。", "學習好痛苦。", "0", "0", "0", "cv_sk_meiliya_15", "0", "0"},
[4301100118] = {4301100118, 13011001, 16, 10, "0", "0", "How\u{0020}mean,\u{0020}making\u{0020}a\u{0020}saintess\u{0020}like\u{0020}me\u{0020}fight.", "私も戦場に行くのですか？なんて残酷なのでしょう。", "連我也得上戰場，真殘酷呢。", "0", "0", "0", "cv_sk_meiliya_16", "0", "0"},
[4301100119] = {4301100119, 13011001, 17, 11, "0", "0", "I\u{0020}definitely\u{0020}get\u{0020}a\u{0020}share\u{0020}of\u{0020}the\u{0020}glory,\u{0020}right?", "私の手柄でもありますよね？", "總得有我一份功勞吧？", "0", "0", "0", "cv_sk_meiliya_17", "0", "0"},
[4301100120] = {4301100120, 13011001, 18, 12, "0", "0", "Meh.\u{0020}It'll\u{0020}do.", "まあまあといった感じですね。", "勉勉強強吧。", "0", "0", "0", "cv_sk_meiliya_18", "0", "0"},
[4301100121] = {4301100121, 13011001, 19, 13, "0", "0", "Time\u{0020}to\u{0020}cook\u{0020}up\u{0020}an\u{0020}excuse\u{0020}for\u{0020}the\u{0020}report.", "言い訳を考えなくては。", "該想想檢討的說辭了。", "0", "0", "0", "cv_sk_meiliya_19", "0", "0"},
[4301100122] = {4301100122, 13011001, 20, 14, "0", "0", "Are\u{0020}you\u{0020}sure\u{0020}the\u{0020}problem\u{0020}wasn't\u{0020}your\u{0020}leadership?", "ナビゲーターさんの指揮の問題ではないでしょうか？", "這次是不是你指揮得有問題？", "0", "0", "0", "cv_sk_meiliya_20", "0", "0"},
[4301100123] = {4301100123, 13011001, 23, 16, "0", "0", "I'll\u{0020}put\u{0020}on\u{0020}a\u{0020}little\u{0020}show.", "適当にやっておきますよ。", "象征性動一動好了。", "0", "0", "0", "cv_sk_meiliya_23", "0", "0"},
[4301100124] = {4301100124, 13011001, 26, 19, "0", "0", "I'm\u{0020}done\u{0020}here.\u{0020}You\u{0020}guys\u{0020}handle\u{0020}the\u{0020}rest.", "力は尽くしました、あとは任せましたよ。", "我盡力了，接下來交給你們吧。", "0", "0", "0", "cv_sk_meiliya_24", "0", "0"},
[4301100125] = {4301100125, 13011001, 24, 17, "0", "0", "Take\u{0020}your\u{0020}reward.", "贈り物を受け取りなさい。", "接受賞賜吧~", "0", "0", "0", "cv_sk_meiliya_25", "0", "0"},
