[4301900101] = {4301900101, 13019001, 2, 2, "0", "0", "Is\u{0020}it\u{0020}really\u{0020}okay\u{0020}for\u{0020}a\u{0020}sinner\u{0020}like\u{0020}me\u{0020}to\u{0020}stand\u{0020}here...?", "本当に良いのでしょうか……わたくしのような罪深い者がここにいて……", "這樣真的好嗎……讓我這樣的罪人站在這裏……", "0", "0", "0", "cv_sk_zhaowu_2", "0", "0"},
[4301900102] = {4301900102, 13019001, 3, 3, "0", "0", "Nice\u{0020}to\u{0020}meet\u{0020}you.\u{0020}I'm\u{0020}from\u{0020}the\u{0020}Academy\u{0020}of\u{0020}Learning...\u{0020}Ah,\u{0020}no,\u{0020}it's\u{0020}called\u{0020}PingXin\u{0020}now.\u{0020}I'm\u{0020}Zhaowu\u{0020}from\u{0020}PingXin.\u{0020}I...\u{0020}I'm\u{0020}not\u{0020}that\u{0020}gifted,\u{0020}but\u{0020}I'll\u{0020}do\u{0020}everything\u{0020}I\u{0020}can\u{0020}to\u{0020}support\u{0020}you,\u{0020}Navigator.", "初めてお目にかかります。学宮（がっきゅう）……あ、いえ。今は平心社（へいしんしゃ）の朝霧（ちょうむ）と申します。ふ、不束者ですが、全身全霊でナビゲーターをお支えします。", "初次見面，我是來自“學宮”的……啊，不，現在應該叫平心社了……我是平心社的朝霧，小……小女子不才，我……我會全心全意支援領航的。", "0", "0", "0", "cv_sk_zhaowu_3", "0", "0"},
[4301900103] = {4301900103, 13019001, 4, 4, "0", "idle", "The\u{0020}Academy\u{0020}of\u{0020}Learning...\u{0020}It's\u{0020}where\u{0020}I\u{0020}grew\u{0020}up—a\u{0020}place\u{0020}to\u{0020}read\u{0020}and\u{0020}find\u{0020}peace.\u{0020}But\u{0020}I\u{0020}don't\u{0020}need\u{0020}to\u{0020}go\u{0020}back.\u{0020}It's\u{0020}alright...\u{0020}I\u{0020}chose\u{0020}to\u{0020}leave.\u{0020}I\u{0020}came\u{0020}for\u{0020}you,\u{0020}Navigator,\u{0020}and\u{0020}for\u{0020}myself.", "学宮……わたくしが生まれ育ち、心静かに学ぶことができた場所。……でももう帰ることはありません。……わたくし自身のために、そしてナビゲーターのために……自分で決断したのです。", "“學宮”……是我出身、長大的地方，一個能讓人能靜下心來讀書的地方……但是我現在已經不用回去了。沒事的……是我自己決定出來的，我是為了領航，也是為了我自己而來的。", "0", "0", "0", "cv_sk_zhaowu_4", "0", "0"},
[4301900104] = {4301900104, 13019001, 5, 4, "0", "idle", "I\u{0020}believe\u{0020}you're\u{0020}the\u{0020}one\u{0020}we've\u{0020}been\u{0020}waiting\u{0020}for.\u{0020}My\u{0020}purpose\u{0020}with\u{0020}PingXin\u{0020}was\u{0020}fulfilled\u{0020}the\u{0020}moment\u{0020}I\u{0020}met\u{0020}you.\u{0020}Now,\u{0020}all\u{0020}I\u{0020}want\u{0020}is\u{0020}to\u{0020}stay\u{0020}by\u{0020}your\u{0020}side.", "わたくし達が待ち望んでいたのはきっと……ナビゲーターです。平心社の目的と使命は、あなたと出会った瞬間に達成されました。これからは、あなたの傍にいるだけで良いのです。", "我覺得……領航就是我們一直在等待的人。我們“平心社”的責任，我的目標在遇見領航的時候就已經完成了，接下來只需要陪伴著您就好了。", "0", "0", "0", "cv_sk_zhaowu_5", "0", "0"},
[4301900105] = {4301900105, 13019001, 6, 4, "0", "idle", "To\u{0020}me,\u{0020}your\u{0020}existence\u{0020}is\u{0020}more\u{0020}important\u{0020}than\u{0020}anyone\u{0020}else's.\u{0020}So,\u{0020}in\u{0020}dangerous\u{0020}times,\u{0020}don't\u{0020}hesitate\u{0020}to\u{0020}use\u{0020}me.\u{0020}After\u{0020}everything\u{0020}I've\u{0020}experienced\u{0020}with\u{0020}you,\u{0020}I'm\u{0020}already\u{0020}content.", "ナビゲーターは誰よりも重要な存在です。危険な時は迷わずわたくしを盾にしてください。あなたと多くの時間を共有することができて、わたくしはもう十分満足です。", "我認為領航的存在比任何人都重要——所以在危險的時候，請毫不留情地使用我吧，能和您經歷過這麼多事情，我已經很滿足了。", "0", "0", "0", "cv_sk_zhaowu_6", "0", "0"},
[4301900106] = {4301900106, 13019001, 7, 5, "15_1_0_0.8", "level1", "Navigator,\u{0020}please\u{0020}don't...\u{0020}touch\u{0020}a\u{0020}sinner\u{0020}like\u{0020}me.", "ナビゲーター……どうかこの咎人に触れないでください。", "領航，請不要……碰觸我這個戴罪之人。", "0", "0", "0", "cv_sk_zhaowu_7", "0", "0"},
[4301900107] = {4301900107, 13019001, 8, 5, "15_2_0_0.8", "level2", "There\u{0020}are\u{0020}far\u{0020}more\u{0020}worthy\u{0020}people\u{0020}to\u{0020}support\u{0020}you.\u{0020}So\u{0020}why\u{0020}do\u{0020}you\u{0020}stay\u{0020}by\u{0020}my\u{0020}side...?", "わたくしよりも、傍にいるべきドライバーがいるはずです。なのにどうして……？", "有更值得您去陪伴的駕駛員，領航，為什麼要呆在我身邊呢。", "0", "0", "0", "cv_sk_zhaowu_8", "0", "0"},
[4301900108] = {4301900108, 13019001, 9, 5, "15_1_0_0.8", "level1", "I\u{0020}was\u{0020}born\u{0020}a\u{0020}sinner,\u{0020}yet\u{0020}you\u{0020}trust\u{0020}me.\u{0020}You\u{0020}let\u{0020}me\u{0020}stand\u{0020}beside\u{0020}you...\u{0020}and\u{0020}somehow,\u{0020}it\u{0020}brings\u{0020}me\u{0020}peace.", "咎人としてこの世に生を受けたわたくしを信じてくださって、ありがとうございます。あなたの隣はなぜか……心が安らぐのです。", "我是作為罪人降生在這個世界上的，但是謝謝您能相信我。您允許我站在您的身邊，不知道為什麼……讓我感到放鬆。", "0", "0", "0", "cv_sk_zhaowu_9", "0", "0"},
[4301900109] = {4301900109, 13019001, 10, 5, "15_2_0_0.8", "level2", "What\u{0020}mistakes\u{0020}have\u{0020}I\u{0020}made?\u{0020}Don't\u{0020}worry\u{0020}about\u{0020}that.\u{0020}Every\u{0020}day\u{0020}spent\u{0020}by\u{0020}your\u{0020}side\u{0020}is\u{0020}my\u{0020}way\u{0020}of\u{0020}atoning.\u{0020}But\u{0020}I'm\u{0020}not\u{0020}here\u{0020}for\u{0020}atonement.\u{0020}I'm\u{0020}here\u{0020}because\u{0020}I\u{0020}hope,\u{0020}I\u{0020}want...\u{0020}I\u{0020}long\u{0020}for\u{0020}you.", "わたくしが犯した罪、ですか……どうか、お気になさらないでください。あなたのそばにいる毎日が償いの日々ですが……罪滅ぼしのためにあなたの傍にいるのではありません。わたくしが……わたくしがあなたに憧れているからです。", "我犯下了什麼過錯……您無需擔心，相伴在您身邊的每一天，便是在贖罪的每一天，但是——我希望您知道，我並不是為了贖罪待在您身邊的，而是我希望，我想要……我憧憬著您。", "0", "0", "0", "cv_sk_zhaowu_10", "0", "0"},
[4301900110] = {4301900110, 13019001, 11, 5, "15_1_0_0.8", "level1", "Navigator...\u{0020}Navigator...", "ナビゲーター……ナビゲーター……", "領航……領航……", "0", "0", "0", "cv_sk_zhaowu_11", "0", "0"},
[4301900111] = {4301900111, 13019001, 12, 6, "0", "0", "Huh,\u{0020}is\u{0020}this...\u{0020}for\u{0020}me?", "こ…これをわたくしに……？", "呼，這……這是給我的嗎？", "0", "0", "0", "cv_sk_zhaowu_12", "0", "0"},
[4301900112] = {4301900112, 13019001, 13, 7, "0", "0", "Even\u{0020}though\u{0020}I've\u{0020}grown\u{0020}used\u{0020}to\u{0020}it,\u{0020}I\u{0020}can\u{0020}still\u{0020}feel\u{0020}the\u{0020}depth\u{0020}of\u{0020}your\u{0020}care.", "あなたにとっては当たり前のことかもしれませんが、わたくしは真心を感じています。", "就算您習以為常，我依然能感受到其中真實的心意。", "0", "0", "0", "cv_sk_zhaowu_13", "0", "0"},
[4301900113] = {4301900113, 13019001, 14, 8, "0", "0", "Huh...\u{0020}Huh...\u{0020}Huh...\u{0020}I\u{0020}did\u{0020}it.\u{0020}I...\u{0020}feel\u{0020}better\u{0020}now,\u{0020}so\u{0020}relieved.", "はぁ、はぁ……成し遂げました。いま……とっても、ホッとしています。", "呼……呼……呼……我做到了，我……現在感覺很好，很安心。", "0", "0", "0", "cv_sk_zhaowu_14", "0", "0"},
[4301900114] = {4301900114, 13019001, 15, 9, "0", "0", "All\u{0020}of\u{0020}my\u{0020}strength...\u{0020}it's\u{0020}yours\u{0020}to\u{0020}use.", "わたくしの力すべてを……あなたに捧げます。", "我的力量，全部都……為您所用。", "0", "0", "0", "cv_sk_zhaowu_15", "0", "0"},
[4301900115] = {4301900115, 13019001, 16, 10, "0", "0", "\"Heavenly\u{0020}Physician\"\u{0020}Zhaowu,\u{0020}from\u{0020}PingXin,\u{0020}arriving\u{0020}on\u{0020}the\u{0020}battlefield.", "平心社の天医（てんい）、朝霧。ここにあり。", "平心社，“天醫”朝霧，抵達戰場。", "0", "0", "0", "cv_sk_zhaowu_16", "0", "0"},
[4301900116] = {4301900116, 13019001, 17, 11, "0", "0", "It's\u{0020}a\u{0020}success...\u{0020}Did\u{0020}you\u{0020}see\u{0020}that,\u{0020}Navigator!", "やりました……見ていただけましたか、ナビゲーター！", "成功了……你看到了嗎，領航！", "0", "0", "0", "cv_sk_zhaowu_17", "0", "0"},
[4301900117] = {4301900117, 13019001, 18, 12, "0", "0", "If\u{0020}you're\u{0020}hurt,\u{0020}tell\u{0020}me\u{0020}right\u{0020}away.", "もし怪我をしたらすぐわたくしにおっしゃってください。", "如果有受傷一定要馬上和我講哦。", "0", "0", "0", "cv_sk_zhaowu_18", "0", "0"},
[4301900118] = {4301900118, 13019001, 19, 13, "0", "0", "If\u{0020}I\u{0020}don't\u{0020}join\u{0020}the\u{0020}battle...\u{0020}you'll\u{0020}probably\u{0020}win\u{0020}even\u{0020}bigger\u{0020}victories.", "わたくしさえいなければ……きっとナビゲーターは完璧な勝利を手にされていたはず……", "如果沒有我參戰……領航一定會獲得更完美的勝利吧。", "0", "0", "0", "cv_sk_zhaowu_19", "0", "0"},
[4301900119] = {4301900119, 13019001, 20, 14, "0", "0", "Woo...\u{0020}Navigator,\u{0020}you\u{0020}go\u{0020}ahead.\u{0020}I'll\u{0020}catch\u{0020}up\u{0020}soon.", "うぅ……ナビゲーター、早くお逃げください……わたくしが背中をお守りします。", "嗚……領航……您先走，我……隨後就到。", "0", "0", "0", "cv_sk_zhaowu_20", "0", "0"},
[4301900120] = {4301900120, 13019001, 23, 16, "0", "0", "Are\u{0020}you\u{0020}hurt\u{0020}anywhere?", "どこを怪我されたんですか？", "哪里受傷了嗎？", "0", "0", "0", "cv_sk_zhaowu_21", "0", "0"},
[4301900121] = {4301900121, 13019001, 26, 19, "0", "0", "Let\u{0020}me...\u{0020}take\u{0020}a\u{0020}look\u{0020}at\u{0020}the\u{0020}wound.", "傷口をお見せください。", "讓我……看看傷口。", "0", "0", "0", "cv_sk_zhaowu_22", "0", "0"},
[4301900122] = {4301900122, 13019001, 25, 18, "0", "0", "I\u{0020}will\u{0020}repay\u{0020}my\u{0020}sin\u{0020}as\u{0020}a\u{0020}\"Heavenly\u{0020}Physician\"\u{0020}here.\u{0020}I\u{0020}won't\u{0020}let\u{0020}you\u{0020}harm\u{0020}anyone\u{0020}again.", "「天医」即ち「人の罪」。これがその償い。二度と仲間を傷つけさせません。", "我要在這裏償還我身為“天醫”的人之罪，我不會再讓你們傷害到大家的。", "0", "0", "0", "cv_sk_zhaowu_23", "0", "0"},
[4301900123] = {4301900123, 13019001, 24, 17, "0", "0", "Have\u{0020}I\u{0020}atoned\u{0020}for\u{0020}this\u{0020}sin?", "罪を償えたでしょうか……", "這份罪責，我還清了嗎……？", "0", "0", "0", "cv_sk_zhaowu_24", "0", "0"},
[4301900124] = {4301900124, 13019001, 27, 20, "0", "0", "Ah...\u{0020}If\u{0020}you\u{0020}don't\u{0020}mind...", "あ……もし……あなたさえ良ければ……", "啊……如果您不嫌棄的話……", "0", "0", "0", "cv_sk_zhaowu_25", "0", "0"},
[4301900125] = {4301900125, 13019001, 28, 21, "0", "0", "Before\u{0020}we\u{0020}begin,\u{0020}please\u{0020}wear\u{0020}your\u{0020}protective\u{0020}gear.\u{0020}I\u{0020}want\u{0020}to\u{0020}make\u{0020}sure\u{0020}you\u{0020}stay\u{0020}safe.", "最初に防具を着用し、ご自分の体をお守りください……", "在開始之前，請戴好護具，保護好自己……", "0", "0", "0", "cv_sk_zhaowu_26", "0", "0"},
[4301900126] = {4301900126, 13019001, 29, 21, "0", "0", "Is\u{0020}it\u{0020}not\u{0020}time\u{0020}yet?\u{0020}That's\u{0020}fine.\u{0020}I'll\u{0020}hold\u{0020}out\u{0020}until\u{0020}you're\u{0020}ready.", "まだ始まらないんですね……大丈夫です。準備が整うまでお待ちします。", "還沒有開始嗎……沒關係，在您做好準備之前，我會一直忍耐的。", "0", "0", "0", "cv_sk_zhaowu_27", "0", "0"},
[4301900127] = {4301900127, 13019001, 30, 22, "0", "0", "Do\u{0020}you\u{0020}need\u{0020}help?\u{0020}I\u{0020}may\u{0020}not\u{0020}be\u{0020}much\u{0020}use,\u{0020}though...", "お手伝いいたしましょうか……何の役にも立たないかもしれませんが……", "需要我來幫您一起嗎……雖然我可能……起不到什麼作用。", "0", "0", "0", "cv_sk_zhaowu_28", "0", "0"},
[4301900128] = {4301900128, 13019001, 31, 23, "0", "0", "Navigator...\u{0020}you...\u{0020}still\u{0020}remember\u{0020}me?", "ナビゲーター……わたくしのこと、覚えていらっしゃいますよね？", "領航……您……還記得我？", "0", "0", "0", "cv_sk_zhaowu_29", "0", "0"},
[4301900129] = {4301900129, 13019001, 32, 24, "0", "0", "Huh...\u{0020}Thank\u{0020}you.", "ふぅ……ありがとうございます。", "呼……謝謝您。", "0", "0", "0", "cv_sk_zhaowu_30", "0", "0"},
[4301900130] = {4301900130, 13019001, 33, 25, "0", "0", "I\u{0020}suppose\u{0020}this\u{0020}was\u{0020}inevitable...\u{0020}After\u{0020}all,\u{0020}it's\u{0020}me.", "当然でしょうね……わたくしですから……", "這也是沒辦法的事情……畢竟是我啊……", "0", "0", "0", "cv_sk_zhaowu_31", "0", "0"},
[4301900131] = {4301900131, 13019001, 34, 26, "0", "0", "Take\u{0020}it\u{0020}easy...\u{0020}It\u{0020}feels\u{0020}just\u{0020}like\u{0020}being\u{0020}back\u{0020}at\u{0020}the\u{0020}Academy\u{0020}of\u{0020}Learning.", "なんだか安心します……まるで学宮に帰ったみたいに……", "安心……像是回到了學宮一樣。", "0", "0", "0", "cv_sk_zhaowu_32", "0", "0"},
[4301900132] = {4301900132, 13019001, 35, 27, "0", "0", "It's\u{0020}time\u{0020}to\u{0020}hit\u{0020}the\u{0020}battlefield...", "戦場ですね……お任せください。", "要上戰場了……", "0", "0", "0", "cv_sk_zhaowu_33", "0", "0"},
[4301900133] = {4301900133, 13019001, 36, 28, "0", "0", "Even\u{0020}drills\u{0020}can\u{0020}lead\u{0020}to\u{0020}injuries...", "演習でも負傷者が出るかもしれませんね……", "演習也會出現傷患……", "0", "0", "0", "cv_sk_zhaowu_34", "0", "0"},
[4301900134] = {4301900134, 13019001, 37, 29, "0", "0", "Everyone's\u{0020}okay.\u{0020}That's\u{0020}a\u{0020}relief.", "皆さんお元気で、何よりです。", "大家都好好的，真好呀。", "0", "0", "0", "cv_sk_zhaowu_35", "0", "0"},
[4301900135] = {4301900135, 13019001, 38, 30, "0", "0", "Are\u{0020}you\u{0020}searching\u{0020}for\u{0020}a\u{0020}new\u{0020}companion?", "新しいパートナーを探しに行くんですか？", "您要去找新的陪伴者了嗎……", "0", "0", "0", "cv_sk_zhaowu_36", "0", "0"},
[4301900136] = {4301900136, 13019001, 39, 31, "0", "0", "Be\u{0020}sure\u{0020}to\u{0020}dress\u{0020}nicely\u{0020}when\u{0020}you\u{0020}head\u{0020}out.", "外出する際は、身なりを整えないと。", "出門要穿戴整齊哦。", "0", "0", "0", "cv_sk_zhaowu_37", "0", "0"},
[4301900137] = {4301900137, 13019001, 40, 32, "0", "0", "Can\u{0020}I\u{0020}get\u{0020}a\u{0020}book?", "本を……本を買いたいです……", "……我……我想要買本書可以嗎？", "0", "0", "0", "cv_sk_zhaowu_38", "0", "0"},
[4301900138] = {4301900138, 13019001, 41, 33, "0", "0", "Your\u{0020}photo's\u{0020}in\u{0020}the\u{0020}file.", "あなたの写真がありますね。", "檔案上有您的照片。", "0", "0", "0", "cv_sk_zhaowu_39", "0", "0"},
[4301900139] = {4301900139, 13019001, 42, 34, "0", "0", "This\u{0020}is\u{0020}where\u{0020}the\u{0020}settings\u{0020}are\u{0020}adjusted...", "セッティングを調整できます。", "這裏是調整設置的地方。", "0", "0", "0", "cv_sk_zhaowu_40", "0", "0"},
[4301900140] = {4301900140, 13019001, 43, 35, "0", "0", "Will\u{0020}there\u{0020}be\u{0020}a\u{0020}new\u{0020}letter?", "新しいメールは来ているでしょうか？", "會有新的來信嗎？", "0", "0", "0", "cv_sk_zhaowu_41", "0", "0"},
[4301900141] = {4301900141, 13019001, 44, 36, "0", "0", "The\u{0020}Navigator's\u{0020}chat...\u{0020}Could\u{0020}I...\u{0020}see\u{0020}it\u{0020}too?", "ナビゲーターのチャット……わ、わたくしも拝見していいでしょうか？", "領航的聊天……我……我也被允許一起看嗎？", "0", "0", "0", "cv_sk_zhaowu_42", "0", "0"},
[4301900142] = {4301900142, 13019001, 45, 37, "0", "0", "Huh—", "ふぅ……", "呼——", "0", "0", "0", "cv_sk_zhaowu_43", "0", "0"},
[4302000100] = {4302000100, 13020001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼霧殘響", "0", "0", "0", "cv_sk_mayball_1", "0", "0"},
[4302000101] = {4302000101, 13020001, 2, 2, "0", "0", "Are\u{0020}you\u{0020}sure\u{0020}it's\u{0020}up\u{0020}to\u{0020}me?\u{0020}Just\u{0020}a\u{0020}heads-up,\u{0020}I\u{0020}can't\u{0020}promise\u{0020}I'll\u{0020}be\u{0020}much\u{0020}help.", "0", "確定交由我嗎？事先說好，不保證能勝任哦。", "0", "0", "0", "cv_sk_mayball_2", "0", "0"},
[4302000102] = {4302000102, 13020001, 3, 3, "0", "0", "This\u{0020}is\u{0020}Maybelle\u{0020}Ise,\u{0020}philosophy\u{0020}teacher\u{0020}at\u{0020}Sahara\u{0020}Azure\u{0020}Academy,\u{0020}part\u{0020}of\u{0020}the\u{0020}Beekeepers\u{0020}Team.\u{0020}Um,\u{0020}that's\u{0020}probably\u{0020}all\u{0020}you\u{0020}need\u{0020}to\u{0020}know...", "0", "這裏是梅貝爾·伊司，薩哈拉蒼穹學院的一名哲學教師，隸屬於制蜜人小隊。唔，介紹應該就這些了……", "0", "0", "0", "cv_sk_mayball_3", "0", "0"},
[4302000103] = {4302000103, 13020001, 4, 4, "0", "idle", "The\u{0020}gentle\u{0020}breeze\u{0020}blows\u{0020}while\u{0020}the\u{0020}blue\u{0020}waves\u{0020}lap\u{0020}against\u{0020}the\u{0020}sand.\u{0020}This\u{0020}is\u{0020}the\u{0020}perfect\u{0020}spot\u{0020}for\u{0020}some\u{0020}philosophical\u{0020}contemplation.", "青い海に白い砂浜、そしてそよ風。哲学に耽るには最適な場所だね。", "這裏微風習習，碧浪疊沙，是個適合哲思的好歸宿。", "0", "0", "0", "cv_sk_mayball_4", "0", "0"},
[4302000104] = {4302000104, 13020001, 5, 4, "0", "idle", "I\u{0020}forgot\u{0020}to\u{0020}submit\u{0020}a\u{0020}leave\u{0020}request\u{0020}to\u{0020}the\u{0020}college\u{0020}before\u{0020}coming\u{0020}here,\u{0020}so\u{0020}I\u{0020}fear\u{0020}all\u{0020}my\u{0020}classes\u{0020}have\u{0020}been\u{0020}suspended.\u{0020}Not\u{0020}that\u{0020}it\u{0020}matters\u{0020}much;\u{0020}I\u{0020}hardly\u{0020}ever\u{0020}show\u{0020}up\u{0020}anyway.\u{0020}My\u{0020}absence\u{0020}probably\u{0020}doesn't\u{0020}make\u{0020}a\u{0020}difference\u{0020}to\u{0020}the\u{0020}students.", "学院に休暇届け出すのを忘れちゃったから、私の授業は全部休講になっちゃうのかな。でも、普段からあまり授業に出ていないし、生徒たちからしたら、私がいてもいなくても変わらないかもしれないね。", "來時忘記向學院遞交請假申請，我負責的課程恐怕都要停擺了。不過平時我也不怎麼去上課，我存在或者不存在，對於學生們來說大概也沒有區別。", "0", "0", "0", "cv_sk_mayball_5", "0", "0"},
[4302000105] = {4302000105, 13020001, 6, 4, "0", "idle", "When\u{0020}I\u{0020}float\u{0020}on\u{0020}the\u{0020}sea,\u{0020}I\u{0020}finally\u{0020}feel\u{0020}free.\u{0020}In\u{0020}contrast,\u{0020}Precio\u{0020}and\u{0020}the\u{0020}others\u{0020}remain\u{0020}trapped\u{0020}in\u{0020}the\u{0020}cage\u{0020}of\u{0020}life.", "海の上に浮かんでるときは、本当の自由を感じることができるね。こんな自由な私とは対照的に、プレシオたちはまだ命の檻に囚われてる。", "只有親身浮於海上，我才能感覺到真正的自由。而與自由的我相比，普瑞席歐她們還被牢牢地拴在生活的牢籠之中。", "0", "0", "0", "cv_sk_mayball_6", "0", "0"},
[4302000106] = {4302000106, 13020001, 7, 5, "15_1_0_0.8", "level2", "I\u{0020}often\u{0020}ponder\u{0020}the\u{0020}difference\u{0020}between\u{0020}my\u{0020}gigantified\u{0020}self\u{0020}and\u{0020}my\u{0020}original\u{0020}form.\u{0020}No\u{0020}matter\u{0020}how\u{0020}my\u{0020}body\u{0020}changes,\u{0020}my\u{0020}thoughts\u{0020}and\u{0020}will\u{0020}remain\u{0020}the\u{0020}same.\u{0020}So,\u{0020}has\u{0020}this\u{0020}larger\u{0020}version\u{0020}truly\u{0020}surpassed\u{0020}the\u{0020}original?", "巨大化した私と元の私はどう違うのか、よく考えるの。体がどんなに変わっても、思考や意志は変わらない。なら、巨大化した私は元の私を超えていると言えるのかな？", "我經常思考，巨大化後的我和本來的我有何不同。因為無論身體如何改變，我的思維意志並不會隨之改變。那巨大後的我是否真的超越了原本的我呢？", "0", "0", "0", "cv_sk_mayball_7", "0", "0"},
[4302000107] = {4302000107, 13020001, 8, 5, "15_2_0_0.8", "level1", "In\u{0020}this\u{0020}comfortable\u{0020}setting,\u{0020}I\u{0020}feel\u{0020}more\u{0020}energized.\u{0020}My\u{0020}thoughts\u{0020}drift\u{0020}like\u{0020}the\u{0020}waves...\u{0020}Haw…", "こんなに快適な環境の中だと、なんだかテンションが上がるね。思考が海のように広がっていくのを感じる…。…ふぅ～", "在這舒適的環境中，反而變得愈加精神，我能清晰地感覺到思緒在大海上漂散……哈嗚~", "0", "0", "0", "cv_sk_mayball_8", "0", "0"},
[4302000108] = {4302000108, 13020001, 9, 5, "15_1_0_0.8", "level2", "The\u{0020}creatures\u{0020}around\u{0020}me\u{0020}are\u{0020}livelier\u{0020}than\u{0020}I\u{0020}expected.\u{0020}But\u{0020}do\u{0020}they\u{0020}even\u{0020}realize\u{0020}their\u{0020}own\u{0020}existence?\u{0020}Are\u{0020}they\u{0020}ever\u{0020}confused\u{0020}by\u{0020}it?\u{0020}What\u{0020}do\u{0020}you\u{0020}think,\u{0020}Navigator?", "ここの生物たちが思っていた以上に活発だけど、私たちの存在を認識しているのかな？そのせいで困惑しているのかも。ナビゲーターくんはどう思う？", "這裏的生物比我預想的更加活潑，可是對它們來說，是否會意識到自己的存在？又是否會因此感到困惑呢？領航同學覺得呢。", "0", "0", "0", "cv_sk_mayball_9", "0", "0"},
[4302000109] = {4302000109, 13020001, 10, 5, "15_2_0_0.8", "level1", "Haw...\u{0020}Drowsiness\u{0020}is\u{0020}creeping\u{0020}in.\u{0020}I'll\u{0020}need\u{0020}your\u{0020}help,\u{0020}Navigator.\u{0020}Just\u{0020}make\u{0020}sure\u{0020}I\u{0020}don't\u{0020}drift\u{0020}away\u{0020}with\u{0020}the\u{0020}waves\u{0020}while\u{0020}I\u{0020}sleep...", "ふぅ～疲れてきちゃった。ナビゲーターくん、あとは頼むね。私が寝てる間、波に流されないようにしてね……", "哈嗚~倦意又湧上來了，領航同學，接下來就只能依靠你了。在我睡著的時候，一定不要讓我被海浪卷走……", "0", "0", "0", "cv_sk_mayball_10", "0", "0"},
[4302000110] = {4302000110, 13020001, 11, 5, "15_1_0_0.8", "level2", "So,\u{0020}have\u{0020}you\u{0020}taken\u{0020}an\u{0020}interest\u{0020}in\u{0020}philosophy?\u{0020}If\u{0020}so,\u{0020}why\u{0020}not\u{0020}rest\u{0020}your\u{0020}head\u{0020}on\u{0020}my\u{0020}chest\u{0020}and\u{0020}read\u{0020}this\u{0020}book\u{0020}with\u{0020}me?\u{0020}It's\u{0020}a\u{0020}rare\u{0020}chance\u{0020}for\u{0020}some\u{0020}personal\u{0020}tutoring.\u{0020}If\u{0020}anything\u{0020}puzzles\u{0020}you,\u{0020}don't\u{0020}hesitate\u{0020}to\u{0020}ask!", "ナビゲーターくん、哲学に興味がわいてきたの？なら、私の胸の上に横になって、この本を一緒に読もう。個別指導の機会なんてなかなか無いから、分からないことがあれば聞いてね。", "領航同學開始對哲學感興趣了嗎？那就請躺在我的胸口上與我一同閱讀這本書籍。難得單獨輔導的機會，有不解的觀點請直接問我吧。", "0", "0", "0", "cv_sk_mayball_11", "0", "0"},
[4302000111] = {4302000111, 13020001, 12, 6, "0", "0", "Hahuu...\u{0020}Thanks.", "0", "哈嗚~謝謝。", "0", "0", "0", "cv_sk_mayball_12", "0", "0"},
[4302000112] = {4302000112, 13020001, 13, 7, "0", "0", "My\u{0020}head's\u{0020}clearer\u{0020}now,\u{0020}like\u{0020}sipping\u{0020}on\u{0020}a\u{0020}chilled\u{0020}coffee.", "0", "思維更清晰了，像在品一杯冰咖啡。", "0", "0", "0", "cv_sk_mayball_13", "0", "0"},
[4302000113] = {4302000113, 13020001, 14, 8, "0", "0", "\"Awakening\"\u{0020}isn't\u{0020}really\u{0020}my\u{0020}thing.\u{0020}I\u{0020}could\u{0020}doze\u{0020}off\u{0020}any\u{0020}second,\u{0020}but\u{0020}since\u{0020}you\u{0020}believe\u{0020}in\u{0020}me...\u{0020}guess\u{0020}I'll\u{0020}try\u{0020}to\u{0020}stay\u{0020}awake.", "0", "“覺醒”嗎？這詞真不適合我呢，說不定我下一秒就會睡著。但領航同學一直對我有所期待，果然我還是拿出十足的幹勁吧~", "0", "0", "0", "cv_sk_mayball_14", "0", "0"},
[4302000114] = {4302000114, 13020001, 15, 9, "0", "0", "Let's\u{0020}arm\u{0020}ourselves\u{0020}with\u{0020}thoughts.", "0", "用思想武裝自己呢。", "0", "0", "0", "cv_sk_mayball_15", "0", "0"},
[4302000115] = {4302000115, 13020001, 16, 10, "0", "0", "Back\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}after\u{0020}a\u{0020}while...", "0", "闊別已久的戰場啊。", "0", "0", "0", "cv_sk_mayball_16", "0", "0"},
[4302000116] = {4302000116, 13020001, 17, 11, "0", "0", "Oops,\u{0020}I\u{0020}accidentally\u{0020}did\u{0020}a\u{0020}great\u{0020}job.", "0", "哎呀，不小心發揮超常了。", "0", "0", "0", "cv_sk_mayball_17", "0", "0"},
[4302000117] = {4302000117, 13020001, 18, 12, "0", "0", "Life's\u{0020}imperfect\u{0020}by\u{0020}design.\u{0020}Don't\u{0020}stress\u{0020}it.", "0", "不完美才是人生的常態，不用在意哦。", "0", "0", "0", "cv_sk_mayball_18", "0", "0"},
[4302000118] = {4302000118, 13020001, 19, 13, "0", "0", "If\u{0020}I\u{0020}keep\u{0020}this\u{0020}up,\u{0020}I\u{0020}won't\u{0020}set\u{0020}a\u{0020}good\u{0020}example\u{0020}for\u{0020}the\u{0020}kids.", "0", "這樣下去沒法給學生們當榜樣了呢。", "0", "0", "0", "cv_sk_mayball_19", "0", "0"},
[4302000119] = {4302000119, 13020001, 20, 14, "0", "0", "Maybe\u{0020}someone\u{0020}else\u{0020}should\u{0020}take\u{0020}the\u{0020}lead\u{0020}next\u{0020}time?", "0", "果然下次作戰把我換掉更好吧~？", "0", "0", "0", "cv_sk_mayball_20", "0", "0"},
[4302000120] = {4302000120, 13020001, 23, 16, "0", "0", "Students,\u{0020}Come\u{0020}on.", "みんな、頑張って。", "同學們，加油。", "0", "0", "0", "cv_sk_mayball_21", "0", "0"},
[4302000121] = {4302000121, 13020001, 26, 19, "0", "0", "You've\u{0020}been\u{0020}very\u{0020}amazing.", "もう十分強いよね。", "已經很厲害了。", "0", "0", "0", "cv_sk_mayball_22", "0", "0"},
[4302000122] = {4302000122, 13020001, 24, 17, "0", "0", "Let\u{0020}me...\u{0020}sleep\u{0020}for\u{0020}a\u{0020}while...", "もうちょっと、寝かせて……", "讓我再……睡一會兒……", "0", "0", "0", "cv_sk_mayball_23", "0", "0"},
[4302000123] = {4302000123, 13020001, 27, 20, "0", "0", "To\u{0020}think\u{0020}clearer,\u{0020}maybe\u{0020}we\u{0020}should\u{0020}just\u{0020}rest.", "0", "為了更好地思考，讓我們洗卻身體的疲憊吧~", "0", "0", "0", "cv_sk_mayball_24", "0", "0"},
[4302000124] = {4302000124, 13020001, 28, 21, "0", "0", "Hahuu...\u{0020}It's\u{0020}way\u{0020}easier\u{0020}to\u{0020}get\u{0020}sleepy\u{0020}in\u{0020}here\u{0020}than\u{0020}out\u{0020}there.\u{0020}Navigator,\u{0020}don't\u{0020}fall\u{0020}asleep\u{0020}before\u{0020}me.", "0", "哈嗚~這裏比外面更容易讓人發困，領航同學可不能比我先睡著哦。", "0", "0", "0", "cv_sk_mayball_25", "0", "0"},
[4302000125] = {4302000125, 13020001, 29, 21, "0", "0", "In\u{0020}Sahara,\u{0020}philosophers\u{0020}have\u{0020}always\u{0020}debated\u{0020}in\u{0020}bathhouses.\u{0020}Got\u{0020}any\u{0020}questions\u{0020}you\u{0020}want\u{0020}to\u{0020}ask\u{0020}me\u{0020}right\u{0020}now?", "0", "古時起，薩哈拉的哲學家們就喜歡在浴場討論問題，領航同學此刻也有想要知曉的問題嗎？", "0", "0", "0", "cv_sk_mayball_26", "0", "0"},
[4302000126] = {4302000126, 13020001, 30, 22, "0", "0", "Game\u{0020}time!", "0", "遊戲時間開始~", "0", "0", "0", "cv_sk_mayball_27", "0", "0"},
[4302000127] = {4302000127, 13020001, 31, 23, "0", "0", "So,\u{0020}what's\u{0020}your\u{0020}answer?", "0", "那麼答案是什麼呢？", "0", "0", "0", "cv_sk_mayball_28", "0", "0"},
[4302000128] = {4302000128, 13020001, 32, 24, "0", "0", "Correct!\u{0020}One\u{0020}hundred\u{0020}points!", "0", "答對了，一百分！", "0", "0", "0", "cv_sk_mayball_29", "0", "0"},
[4302000129] = {4302000129, 13020001, 33, 25, "0", "0", "Oops,\u{0020}that\u{0020}didn't\u{0020}go\u{0020}according\u{0020}to\u{0020}plan.", "0", "很遺憾，不及格呢~", "0", "0", "0", "cv_sk_mayball_30", "0", "0"},
[4302000130] = {4302000130, 13020001, 34, 26, "0", "0", "Where\u{0020}were\u{0020}you\u{0020}just\u{0020}now?\u{0020}Come\u{0020}and\u{0020}lie\u{0020}down\u{0020}here\u{0020}to\u{0020}continue\u{0020}reading\u{0020}the\u{0020}book.", "どこにいってたの？こっちで横になって、一緒に本を読もうよ。", "你剛才去哪了？來我這邊躺下繼續閱讀書籍吧。", "0", "0", "0", "cv_sk_mayball_31", "0", "0"},
[4302000131] = {4302000131, 13020001, 35, 27, "0", "0", "Should\u{0020}I\u{0020}be\u{0020}serious\u{0020}now?", "0", "該認真起來了嗎？", "0", "0", "0", "cv_sk_mayball_32", "0", "0"},
[4302000132] = {4302000132, 13020001, 36, 28, "0", "0", "Take\u{0020}it\u{0020}easy\u{0020}in\u{0020}the\u{0020}sim\u{0020}battle.", "0", "模擬戰就隨意點吧。", "0", "0", "0", "cv_sk_mayball_33", "0", "0"},
[4302000133] = {4302000133, 13020001, 37, 29, "0", "0", "Surprise\u{0020}inspection!\u{0020}Anyone\u{0020}slacking\u{0020}off?", "0", "突擊檢查~有開小差的同學嗎？", "0", "0", "0", "cv_sk_mayball_34", "0", "0"},
[4302000134] = {4302000134, 13020001, 38, 30, "0", "0", "Hee...\u{0020}A\u{0020}mysterious\u{0020}transfer\u{0020}student\u{0020}is\u{0020}on\u{0020}their\u{0020}way.", "0", "謔~要出現神秘轉校生了。", "0", "0", "0", "cv_sk_mayball_35", "0", "0"},
[4302000135] = {4302000135, 13020001, 39, 31, "0", "0", "What\u{0020}do\u{0020}you\u{0020}think\u{0020}we'll\u{0020}get?\u{0020}I'm\u{0020}excited\u{0020}to\u{0020}find\u{0020}out.", "0", "會得到什麼呢？稍微期待下吧。", "0", "0", "0", "cv_sk_mayball_36", "0", "0"},
[4302000136] = {4302000136, 13020001, 40, 32, "0", "0", "Check\u{0020}out\u{0020}the\u{0020}new\u{0020}pajama\u{0020}styles\u{0020}while\u{0020}you're\u{0020}at\u{0020}it.", "0", "幫忙留意下新款睡衣哦。", "0", "0", "0", "cv_sk_mayball_37", "0", "0"},
[4302000137] = {4302000137, 13020001, 41, 33, "0", "0", "So,\u{0020}what's\u{0020}the\u{0020}Navigator's\u{0020}big\u{0020}ambition?", "0", "看看領航同學的志向填了什麼。", "0", "0", "0", "cv_sk_mayball_38", "0", "0"},
