[4302000139] = {4302000139, 13020001, 43, 35, "0", "0", "Writing\u{0020}beats\u{0020}talking\u{0020}every\u{0020}time.\u{0020}Way\u{0020}more\u{0020}convenient.", "0", "比起口頭交流，果然文字更方便呢。", "0", "0", "0", "cv_sk_mayball_40", "0", "0"},
