[4302000141] = {4302000141, 13020001, 45, 37, "0", "0", "Alright,\u{0020}alright.", "0", "好、好。", "0", "0", "0", "cv_sk_mayball_42", "0", "0"},
[4302100100] = {4302100100, 13021001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "0", "蒼~霧~殘~響~", "0", "0", "0", "cv_sk_hoshii_1", "0", "0"},
[4302100101] = {4302100101, 13021001, 2, 2, "0", "0", "According\u{0020}to\u{0020}the\u{0020}mysticism\u{0020}of\u{0020}Kyushu,\u{0020}the\u{0020}feng\u{0020}shui\u{0020}here\u{0020}is\u{0020}exceptional.", "0", "用九州的神秘學理論來說就是——這裏的風水不錯。", "0", "0", "0", "cv_sk_hoshii_2", "0", "0"},
[4302100102] = {4302100102, 13021001, 3, 3, "0", "0", "I'm\u{0020}Hoshii\u{0020}Bernardy,\u{0020}your\u{0020}life\u{0020}guide.\u{0020}Mind\u{0020}if\u{0020}I\u{0020}call\u{0020}you\u{0020}Navigator\u{0020}Brother?", "0", "我是星井伯納蒂，您的人生指引者。我可以稱呼你為“領航哥哥”嗎？", "0", "0", "0", "cv_sk_hoshii_3", "0", "0"},
[4302100103] = {4302100103, 13021001, 4, 4, "0", "idle", "May\u{0020}the\u{0020}supreme\u{0020}light\u{0020}from\u{0020}boundless\u{0020}wisdom\u{0020}illuminate\u{0020}the\u{0020}paths\u{0020}of\u{0020}confused\u{0020}souls.", "0", "來自無邊思緒之上的無上之光，請照亮迷惑靈魂飄蕩的方向。", "0", "0", "0", "cv_sk_hoshii_4", "0", "0"},
[4302100104] = {4302100104, 13021001, 5, 4, "0", "idle", "The\u{0020}result\u{0020}of\u{0020}the\u{0020}divination\u{0020}is...\u{0020}ramen\u{0020}for\u{0020}dinner.", "0", "占卜的結果是……晚飯吃拉麵。", "0", "0", "0", "cv_sk_hoshii_5", "0", "0"},
[4302100105] = {4302100105, 13021001, 6, 4, "0", "idle", "Yesterday,\u{0020}I\u{0020}peeked\u{0020}into\u{0020}some\u{0020}futures.\u{0020}Little\u{0020}Hotarugusa\u{0020}and\u{0020}Hanakotoba\u{0020}are\u{0020}bound\u{0020}for\u{0020}peace,\u{0020}but\u{0020}Sister\u{0020}Kokorokami's...\u{0020}uh,\u{0020}Navigator\u{0020}Brother,\u{0020}you\u{0020}might\u{0020}want\u{0020}to\u{0020}sit\u{0020}that\u{0020}one\u{0020}out.", "0", "我呀，昨天偷偷給其他人占卜了一下未來。小螢草和花語的命運清晰而寧靜，但心紙姐姐她……嗯……領航哥哥還是不要知道比較好。", "0", "0", "0", "cv_sk_hoshii_6", "0", "0"},
[4302100106] = {4302100106, 13021001, 7, 5, "15_1_0_0.8", "touch1", "Honestly,\u{0020}there's\u{0020}not\u{0020}much\u{0020}difference\u{0020}between\u{0020}a\u{0020}miko\u{0020}and\u{0020}a\u{0020}diviner—we\u{0020}both\u{0020}guide\u{0020}lost\u{0020}souls\u{0020}toward\u{0020}hope.\u{0020}But\u{0020}let's\u{0020}face\u{0020}it—mikos\u{0020}have\u{0020}those\u{0020}cute\u{0020}outfits.", "0", "巫女和占卜師的在我看來並沒有區別，都是幫助迷茫的人尋找人生的希望。不過巫女可以穿可愛的巫女服。", "0", "0", "0", "cv_sk_hoshii_7", "0", "0"},
[4302100107] = {4302100107, 13021001, 8, 5, "15_2_0_0.8", "touch1", "Shh...\u{0020}don't\u{0020}disturb\u{0020}my\u{0020}meditation...\u{0020}I'm\u{0020}channeling\u{0020}the\u{0020}wisdom\u{0020}of\u{0020}the\u{0020}sages\u{0020}of\u{0020}the\u{0020}thinking\u{0020}world...\u{0020}Zzzz—(snoring)", "0", "別……別打擾我的冥想……我正在……接受……思維世界先賢的……智慧……呼——（呼嚕聲）", "0", "0", "0", "cv_sk_hoshii_8", "0", "0"},
[4302100108] = {4302100108, 13021001, 9, 5, "15_1_0_0.8", "touch2", "Huh?\u{0020}Another\u{0020}divination,\u{0020}Navigator\u{0020}Brother?\u{0020}Sure,\u{0020}but\u{0020}no\u{0020}matter\u{0020}how\u{0020}many\u{0020}times\u{0020}you\u{0020}ask,\u{0020}the\u{0020}outcome\u{0020}stays\u{0020}the\u{0020}same.\u{0020}The\u{0020}black\u{0020}light\u{0020}swallows\u{0020}the\u{0020}sun\u{0020}and\u{0020}earth\u{0020}from\u{0020}the\u{0020}moon...", "0", "誒？領航哥哥還要再占卜一次嗎？可以是可以啦，不過就算再占卜一千次，結果也不會變的——黑色的光自月亮開始吞沒了太陽與大地……", "0", "0", "0", "cv_sk_hoshii_9", "0", "0"},
[4302100109] = {4302100109, 13021001, 10, 5, "15_2_0_0.8", "touch1", "But\u{0020}don't\u{0020}worry\u{0020}about\u{0020}the\u{0020}\"black\u{0020}light.\"\u{0020}That's\u{0020}just\u{0020}a\u{0020}vision.\u{0020}The\u{0020}future\u{0020}can\u{0020}always\u{0020}be\u{0020}rewritten.\u{0020}Besides,\u{0020}I'll\u{0020}be\u{0020}right\u{0020}here\u{0020}with\u{0020}you.", "0", "不必過於擔心“黑光”，占卜的結果僅僅是未來的推演而已，真正的未來並不一定會發生那樣的事。更何況，還有我在領航哥哥身邊。", "0", "0", "0", "cv_sk_hoshii_10", "0", "0"},
[4302100110] = {4302100110, 13021001, 11, 5, "15_1_0_0.8", "touch2", "My\u{0020}mother's\u{0020}divination\u{0020}said\u{0020}I'd\u{0020}form\u{0020}a\u{0020}deep\u{0020}connection\u{0020}with\u{0020}someone\u{0020}who's\u{0020}lived\u{0020}a\u{0020}thousand\u{0020}lifetimes.\u{0020}You\u{0020}know,\u{0020}I\u{0020}think\u{0020}that\u{0020}someone\u{0020}might\u{0020}be\u{0020}you,\u{0020}Navigator\u{0020}Brother.", "0", "母親的占卜結果說，我將會與一位千轉輪回之人產生超越群體潛意識控制的深度交融。現在我越來越確定，那個千轉輪回之人就是你——領航哥哥。", "0", "0", "0", "cv_sk_hoshii_11", "0", "0"},
[4302100111] = {4302100111, 13021001, 12, 6, "0", "0", "Inspiration's\u{0020}flowing\u{0020}now.", "0", "靈感提升。", "0", "0", "0", "cv_sk_hoshii_12", "0", "0"},
[4302100112] = {4302100112, 13021001, 13, 7, "0", "0", "My\u{0020}link\u{0020}to\u{0020}the\u{0020}thinking\u{0020}world\u{0020}is\u{0020}getting\u{0020}stronger.", "0", "與思維世界的感應更緊密了。", "0", "0", "0", "cv_sk_hoshii_13", "0", "0"},
[4302100113] = {4302100113, 13021001, 14, 8, "0", "0", "I\u{0020}can\u{0020}see\u{0020}the\u{0020}world's\u{0020}branches\u{0020}unfolding—freeze-frames\u{0020}of\u{0020}the\u{0020}future,\u{0020}one\u{0020}by\u{0020}one.\u{0020}Only\u{0020}you,\u{0020}Navigator\u{0020}Brother,\u{0020}can\u{0020}bring\u{0020}light\u{0020}to\u{0020}the\u{0020}darkness.", "0", "世界的枝條在我眼前舒展，未來的定格照正在一張一張覆蓋。唯一的光將消融黑色，那便是領航哥哥你。", "0", "0", "0", "cv_sk_hoshii_14", "0", "0"},
[4302100114] = {4302100114, 13021001, 15, 9, "0", "0", "Keep\u{0020}the\u{0020}crystal\u{0020}ball\u{0020}spotless.", "0", "要保持水晶球的清潔。", "0", "0", "0", "cv_sk_hoshii_15", "0", "0"},
