[4400000101] = {4400000101, 14000001, 2, 2, "0", "0", "Did\u{0020}you\u{0020}miss\u{0020}me?\u{0020}I\u{0020}think\u{0020}about\u{0020}you\u{0020}every\u{0020}day,\u{0020}Mr.\u{0020}Hentai.", "0", "有沒有想我？我到是每天都在想你，色狼先生。", "0", "0", "0", "cv_sk_starry2_2", "0", "0"},
[4400000102] = {4400000102, 14000001, 3, 3, "0", "0", "Have\u{0020}you\u{0020}been\u{0020}eating\u{0020}well\u{0020}and\u{0020}resting\u{0020}enough?\u{0020}You\u{0020}look\u{0020}like\u{0020}you've\u{0020}lost\u{0020}a\u{0020}lot\u{0020}of\u{0020}weight.\u{0020}Me?\u{0020}Oh,\u{0020}it's\u{0020}nothing.\u{0020}Just\u{0020}a\u{0020}little\u{0020}accident,\u{0020}like\u{0020}choking\u{0020}on\u{0020}water—no\u{0020}big\u{0020}deal.", "0", "色狼先生，這段時間有好好吃飯，好好休息嗎，感覺你消瘦了不少——我？沒事的，只是點小事故，跟喝水被嗆到沒區別。", "0", "0", "0", "cv_sk_starry2_3", "0", "0"},
[4400000103] = {4400000103, 14000001, 91, 4, "0", "idle", "Sink\u{0020}my\u{0020}heart\u{0020}into\u{0020}the\u{0020}endless\u{0020}darkness.\u{0020}When\u{0020}I\u{0020}close\u{0020}my\u{0020}eyes,\u{0020}I\u{0020}can\u{0020}feel\u{0020}a\u{0020}power\u{0020}as\u{0020}vast\u{0020}as\u{0020}the\u{0020}ocean\u{0020}within\u{0020}me.\u{0020}With\u{0020}this\u{0020}strength,\u{0020}I\u{0020}might\u{0020}defy\u{0020}fate\u{0020}itself.", "0", "將心沉寂在無邊的黑暗中，閉上雙眼感受到的是近乎海洋般浩瀚的力量。憑借著它，我大概能夠戰勝命運吧。", "0", "0", "0", "cv_sk_starry2_4", "0", "0"},
[4400000104] = {4400000104, 14000001, 91, 4, "0", "idle", "I'm\u{0020}starting\u{0020}to\u{0020}grasp\u{0020}the\u{0020}truth:\u{0020}luck\u{0020}and\u{0020}misfortune\u{0020}are\u{0020}two\u{0020}sides\u{0020}of\u{0020}the\u{0020}same\u{0020}coin.\u{0020}I'm\u{0020}both\u{0020}fortunate\u{0020}and\u{0020}unfortunate.\u{0020}I\u{0020}can't\u{0020}escape\u{0020}my\u{0020}misfortune\u{0020}any\u{0020}more\u{0020}than\u{0020}I\u{0020}can\u{0020}leave\u{0020}behind\u{0020}my\u{0020}luck.", "0", "我漸漸明白了……幸運和不幸是一體兩面的，我既是幸運的，也是不幸的。我無法逃離自己的不幸，就像我離不開我的幸運一樣。", "0", "0", "0", "cv_sk_starry2_5", "0", "0"},
[4400000105] = {4400000105, 14000001, 94, 4, "0", "idle2", "As\u{0020}for\u{0020}my\u{0020}current\u{0020}situation...\u{0020}How\u{0020}should\u{0020}I\u{0020}put\u{0020}it?\u{0020}\"I'm\u{0020}fine\"...\u{0020}No\u{0020}one\u{0020}would\u{0020}believe\u{0020}that,\u{0020}would\u{0020}they?\u{0020}But\u{0020}it\u{0020}doesn't\u{0020}matter.\u{0020}Eventually,\u{0020}things\u{0020}will\u{0020}work\u{0020}themselves\u{0020}out.\u{0020}There's\u{0020}always\u{0020}a\u{0020}way\u{0020}forward.", "0", "我現在的狀況……該怎麼說呢，“我很好”……這樣也不會有人相信吧，但是沒關係，船到橋頭自然直，總會有辦法的。", "0", "0", "0", "cv_sk_starry2_6", "0", "0"},
[4400000106] = {4400000106, 14000001, 94, 4, "0", "idle2", "Now\u{0020}that\u{0020}I've\u{0020}become\u{0020}like\u{0020}this,\u{0020}emotions\u{0020}surge\u{0020}uncontrollably.\u{0020}It's\u{0020}incredible.\u{0020}I\u{0020}feel\u{0020}like\u{0020}I\u{0020}can\u{0020}accomplish\u{0020}anything.", "0", "變成這副模樣之後，情緒會不受控制地高漲起來。真是不可思議，好像自己什麼都可以做到一樣。", "0", "0", "0", "cv_sk_starry2_46", "0", "0"},
[4400000107] = {4400000107, 14000001, 92, 5, "14_1_0_0.8", "touch1", "But\u{0020}that\u{0020}desperate\u{0020}feeling\u{0020}of\u{0020}trying\u{0020}to\u{0020}grasp\u{0020}something\u{0020}only\u{0020}to\u{0020}watch\u{0020}it\u{0020}slip\u{0020}away...\u{0020}It's\u{0020}the\u{0020}worst.\u{0020}Just\u{0020}experiencing\u{0020}it\u{0020}is\u{0020}enough...\u{0020}I\u{0020}won't\u{0020}let\u{0020}you\u{0020}endure\u{0020}the\u{0020}same,\u{0020}Navigator.", "0", "那種努力想要去抓住某種東西，卻只能眼睜睜地看著它從指縫間流失的感覺……真的是最糟了，光是我體驗就已經足夠了……我不會讓你感同身受的，領航。", "0", "0", "0", "cv_sk_starry2_9", "0", "0"},
[4400000108] = {4400000108, 14000001, 92, 5, "14_1_0_0.8", "touch2", "I\u{0020}have\u{0020}this\u{0020}sense\u{0020}that\u{0020}I\u{0020}might\u{0020}end\u{0020}up\u{0020}in\u{0020}hell.\u{0020}If\u{0020}that\u{0020}day\u{0020}comes\u{0020}and\u{0020}I\u{0020}call\u{0020}out\u{0020}for\u{0020}help...\u{0020}Will\u{0020}you\u{0020}come\u{0020}to\u{0020}save\u{0020}me,\u{0020}my\u{0020}Navigator?", "0", "感覺……說不定我會下地獄啊，要是真有那天的話，我要是大聲呼救的話……你會來救我嗎，我的領航。", "0", "0", "0", "cv_sk_starry2_10", "0", "0"},
[4400000109] = {4400000109, 14000001, 92, 5, "14_1_0_0.8", "touch3", "It's\u{0020}eroding\u{0020}my\u{0020}consciousness,\u{0020}dragging\u{0020}me\u{0020}slowly\u{0020}into\u{0020}a\u{0020}nightmare...\u{0020}But\u{0020}as\u{0020}long\u{0020}as\u{0020}you're\u{0020}here,\u{0020}my\u{0020}heart\u{0020}won't\u{0020}get\u{0020}lost.\u{0020}I\u{0020}promise\u{0020}you\u{0020}that.", "0", "它在侵蝕，在奪走我的意識，在把我一點點拽向噩夢……但只要有你在，我的心就不會迷失，這點我可以向你保證。", "0", "0", "0", "cv_sk_starry2_11", "0", "0"},
[4400000110] = {4400000110, 14000001, 93, 5, "14_2_0_0.8", "touch_s1", "...\u{0020}What's\u{0020}wrong?\u{0020}Can't\u{0020}you\u{0020}take\u{0020}it\u{0020}anymore?", "0", "……怎麼了，不行了嗎？", "0", "0", "0", "cv_sk_starry2_49", "0", "0"},
[4400000111] = {4400000111, 14000001, 95, 5, "14_1_0_0.8", "touch4", "Um...\u{0020}Suddenly,\u{0020}I\u{0020}crave\u{0020}the\u{0020}taste\u{0020}of\u{0020}humanity.\u{0020}Let's\u{0020}start\u{0020}with\u{0020}Mr.\u{0020}Hentai—Haha,\u{0020}just\u{0020}kidding.\u{0020}I\u{0020}only\u{0020}wanted\u{0020}to\u{0020}say\u{0020}something\u{0020}silly.\u{0020}After\u{0020}all,\u{0020}a\u{0020}Sin\u{0020}wouldn't\u{0020}eat\u{0020}humans,\u{0020}right?...\u{0020}It\u{0020}shouldn't,\u{0020}right?", "0", "嗯……突然想嘗嘗人類的味道了，就先從色狼先生開始吧——哈哈，開玩笑的，只是想說說這樣的臺詞而已，畢竟原罪也不會吃人類吧？……應該不會吧？", "0", "0", "0", "cv_sk_starry2_47", "0", "0"},
[4400000112] = {4400000112, 14000001, 95, 5, "14_1_0_0.8", "touch5", "If\u{0020}it's\u{0020}you,\u{0020}I\u{0020}believe\u{0020}it\u{0020}can\u{0020}be\u{0020}done.\u{0020}Let's\u{0020}reverse\u{0020}all\u{0020}the\u{0020}\"misfortunes\"\u{0020}for\u{0020}you,\u{0020}for\u{0020}me,\u{0020}and\u{0020}for\u{0020}everyone.", "0", "如果是你的話，我覺得能做到吧，把你身上的，以及我身上的，所有人身上的“不幸”，全部反轉。", "0", "0", "0", "cv_sk_starry2_7", "0", "0"},
[4400000113] = {4400000113, 14000001, 95, 5, "14_1_0_0.8", "touch6", "It\u{0020}would\u{0020}be\u{0020}too\u{0020}tragic\u{0020}to\u{0020}sacrifice\u{0020}everything\u{0020}and\u{0020}still\u{0020}be\u{0020}unable\u{0020}to\u{0020}help\u{0020}the\u{0020}one\u{0020}you\u{0020}love.\u{0020}I'm\u{0020}so\u{0020}lucky.\u{0020}I\u{0020}won't\u{0020}find\u{0020}myself\u{0020}in\u{0020}such\u{0020}a\u{0020}situation.", "0", "如果犧牲自己的全部，卻連喜歡的人都幫不了的話，那也太可悲了。我這麼幸運，絕對不會淪落到那種結局的。", "0", "0", "0", "cv_sk_starry2_8", "0", "0"},
[4400000114] = {4400000114, 14000001, 96, 5, "14_2_0_0.8", "touch_s2", "Running\u{0020}away\u{0020}is\u{0020}not\u{0020}an\u{0020}option.", "0", "逃跑是禁止事項。", "0", "0", "0", "cv_sk_starry2_48", "0", "0"},
[4400000115] = {4400000115, 14000001, 12, 6, "0", "0", "Haha...\u{0020}my\u{0020}hand\u{0020}hurts\u{0020}a\u{0020}little...", "0", "哈哈……手有點疼……", "0", "0", "0", "cv_sk_starry2_12", "0", "0"},
[4400000116] = {4400000116, 14000001, 13, 7, "0", "0", "But\u{0020}it's\u{0020}manageable.", "0", "還算在控制範圍吧。", "0", "0", "0", "cv_sk_starry2_13", "0", "0"},
[4400000117] = {4400000117, 14000001, 14, 8, "0", "0", "I've\u{0020}got\u{0020}to\u{0020}shine\u{0020}the\u{0020}brightest\u{0020}before\u{0020}I\u{0020}burn\u{0020}out—that's\u{0020}my\u{0020}mission.", "0", "在燃盡之前綻放出最耀眼的光，這就是我要做的事。", "0", "0", "0", "cv_sk_starry2_14", "0", "0"},
[4400000118] = {4400000118, 14000001, 15, 9, "0", "0", "Sometimes,\u{0020}I\u{0020}wish\u{0020}I\u{0020}could\u{0020}shine\u{0020}a\u{0020}little\u{0020}more.", "0", "偶爾也想變得更耀眼一點。", "0", "0", "0", "cv_sk_starry2_15", "0", "0"},
