[4001400102] = {4001400102, 10014001, 3, 3, "0", "0", "Korowin\u{0020}K\u{0020}Vella\u{0020}reporting\u{0020}for\u{0020}duty,\u{0020}Navigator.\u{0020}Is\u{0020}there\u{0020}a\u{0020}place\u{0020}to\u{0020}buy\u{0020}some\u{0020}snacks\u{0020}nearby?", "0", "科羅溫·卡·薇拉，向領航報導，請問這裡附近有買零食的地方嗎？", "0", "柯洛溫·卡·薇拉，向領航報導，請問這裡附近有買零食的地方嗎？", "0", "cv_sk_korovin_1", "0", "0"},
[4001400103] = {4001400103, 10014001, 4, 4, "0", "idle", "The\u{0020}snacks\u{0020}are\u{0020}running\u{0020}out.\u{0020}I\u{0020}have\u{0020}to\u{0020}find\u{0020}a\u{0020}way\u{0020}to\u{0020}buy\u{0020}some...\u{0020}Navigator,\u{0020}can\u{0020}you\u{0020}lend\u{0020}me\u{0020}10,000\u{0020}Shield\u{0020}Credits?", "0", "零食要吃完了，得想辦法去買一些…領航，能借我一萬盾幣嗎？", "0", "零食要吃完了，得想辦法去買一些…領航，能借我一萬盾幣嗎？", "0", "cv_sk_korovin_3", "0", "0"},
