[4400300102] = {4400300102, 14003001, 3, 3, "0", "0", "This\u{0020}is\u{0020}a\u{0020}rare\u{0020}reunion,\u{0020}you\u{0020}know.\u{0020}So\u{0020}I'll\u{0020}take\u{0020}this\u{0020}chance\u{0020}to\u{0020}show\u{0020}you\u{0020}how\u{0020}much\u{0020}I've\u{0020}changed,\u{0020}Navigator.", "0", "這次的重逢是難得的機會，我要向領航您展現我的蛻變。", "0", "0", "0", "cv_sk_iria2_3", "0", "0"},
[4400300103] = {4400300103, 14003001, 93, 5, "14_2_0_0.8", "sw12", "This\u{0020}is\u{0020}an\u{0020}old\u{0020}outfit\u{0020}I've\u{0020}kept\u{0020}tucked\u{0020}away—I've\u{0020}never\u{0020}worn\u{0020}it\u{0020}in\u{0020}front\u{0020}of\u{0020}anyone\u{0020}before.", "0", "壓箱底的舊裝，我也是第一次在別人面前穿上。", "0", "0", "0", "cv_sk_iria2_46", "0", "0,sw12"},
