[4400300105] = {4400300105, 14003001, 92, 5, "14_1_0_0.8", "touch1", "I'm\u{0020}not\u{0020}on\u{0020}guard?\u{0020}No,\u{0020}because\u{0020}it's\u{0020}just\u{0020}the\u{0020}two\u{0020}of\u{0020}us\u{0020}here.\u{0020}Wait,\u{0020}don't\u{0020}tell\u{0020}me\u{0020}you're\u{0020}trying\u{0020}to\u{0020}take\u{0020}advantage\u{0020}of\u{0020}that...", "0", "沒有防備？因為現在只有我們兩個人。難道說領航想要趁人之危……", "0", "0", "0", "cv_sk_iria2_48", "0", "0,touch1"},
[4400300106] = {4400300106, 14003001, 92, 5, "14_1_0_0.8", "touch1", "I\u{0020}feel\u{0020}my\u{0020}heartbeat\u{0020}quicken…\u{0020}It's\u{0020}such\u{0020}a\u{0020}wonderful\u{0020}sensation.", "0", "我感覺到心跳加速……很美妙的感覺。", "0", "0", "0", "cv_sk_iria2_49", "0", "0,touch1"},
