[4101600101] = {4101600101, 11016001, 2, 2, "0", "0", "Understood,\u{0020}this\u{0020}is\u{0020}part\u{0020}of\u{0020}my\u{0020}duty.\u{0020}No\u{0020}need\u{0020}to\u{0020}be\u{0020}so\u{0020}polite.", "0", "0", "0", "瞭解，這本就是我的分內之事，您無須客氣。", "0", "cv_sk_heiyu_2", "0", "0"},
[4101600102] = {4101600102, 11016001, 3, 3, "0", "0", "Ninja\u{0020}Group,\u{0020}Kurobane.\u{0020}I\u{0020}will\u{0020}be\u{0020}your\u{0020}guard\u{0020}from\u{0020}today\u{0020}onward.\u{0020}I'll\u{0020}stay\u{0020}by\u{0020}your\u{0020}side\u{0020}at\u{0020}all\u{0020}times.", "0", "0", "0", "忍心社，黑羽，從今天開始擔任您的護衛，我會寸步不離地守候在您周圍的。", "0", "cv_sk_heiyu_1", "0", "0"},
[4101600103] = {4101600103, 11016001, 4, 4, "0", "idle", "My\u{0020}job\u{0020}is\u{0020}not\u{0020}to\u{0020}monitor\u{0020}you\u{0020}but\u{0020}to\u{0020}protect\u{0020}you.\u{0020}Please\u{0020}don't\u{0020}misunderstand\u{0020}that.", "0", "0", "0", "領航，我的職責並不是監視您，而是保護您。只有這點，請不要弄錯。", "0", "cv_sk_heiyu_3", "0", "0"},
[4101600104] = {4101600104, 11016001, 5, 4, "0", "idle", "I\u{0020}don't\u{0020}know\u{0020}any\u{0020}flashy\u{0020}ninjutsu,\u{0020}and\u{0020}my\u{0020}assassination\u{0020}skills\u{0020}are\u{0020}just\u{0020}so-so.\u{0020}But\u{0020}I\u{0020}assure\u{0020}you,\u{0020}while\u{0020}you're\u{0020}in\u{0020}my\u{0020}sight,\u{0020}you\u{0020}won't\u{0020}be\u{0020}in\u{0020}danger.", "0", "0", "0", "我不會那些光怪陸離的忍術，至於刺殺的技藝，也只是一知半解。不過，我向您保證，在我的視野範圍內，您不會有任何危險。", "0", "cv_sk_heiyu_4", "0", "0"},
[4101600105] = {4101600105, 11016001, 6, 4, "0", "idle", "Is\u{0020}Captain\u{0020}Gourai\u{0020}on\u{0020}a\u{0020}mission?\u{0020}That's\u{0020}a\u{0020}shame;\u{0020}I\u{0020}wanted\u{0020}to\u{0020}learn\u{0020}some\u{0020}combat\u{0020}techniques\u{0020}from\u{0020}her.", "0", "0", "0", "轟雷隊長是去外出執行任務了嗎？真遺憾，我本來想向她學習一些戰鬥的技巧呢。", "0", "cv_sk_heiyu_29", "0", "0"},
[4101600106] = {4101600106, 11016001, 7, 5, "15_1_0_0.8", "level1", "I'm\u{0020}not\u{0020}loyal\u{0020}to\u{0020}AEGIS...\u{0020}it's\u{0020}just\u{0020}a\u{0020}fair\u{0020}trade.\u{0020}They\u{0020}provide\u{0020}shelter\u{0020}for\u{0020}me,\u{0020}and\u{0020}I\u{0020}serve\u{0020}them\u{0020}in\u{0020}return.", "0", "0", "0", "我並不是效忠于艾吉斯…只是平等交易罷了。他們為“黑羽”提供了庇佑的住所，而我為他們服務。", "0", "cv_sk_heiyu_30", "0", "0"},
[4101600107] = {4101600107, 11016001, 8, 5, "15_1_0_0.8", "level1", "Is\u{0020}there\u{0020}any\u{0020}special\u{0020}meaning\u{0020}behind\u{0020}what\u{0020}you're\u{0020}doing?", "0", "0", "0", "您這樣做，有什麼特別的含義嗎？", "0", "cv_sk_heiyu_5", "0", "0"},
[4101600108] = {4101600108, 11016001, 9, 5, "15_1_0_0.8", "level1", "I\u{0020}don't\u{0020}get\u{0020}why\u{0020}you\u{0020}want\u{0020}to\u{0020}get\u{0020}closer\u{0020}to\u{0020}me...\u{0020}that's\u{0020}strange.", "0", "0", "0", "我不能理解您的行為…“想和我更加親近一些”？…呵呵，真是奇怪啊。", "0", "cv_sk_heiyu_6", "0", "0"},
[4101600109] = {4101600109, 11016001, 10, 5, "15_2_0_0.8", "level2", "Interested\u{0020}in\u{0020}my\u{0020}past?\u{0020}Well,\u{0020}technically\u{0020}I'm\u{0020}supposed\u{0020}to\u{0020}keep\u{0020}it\u{0020}secret,\u{0020}but\u{0020}if\u{0020}you\u{0020}want\u{0020}to\u{0020}know...\u{0020}I'll\u{0020}tell\u{0020}you\u{0020}everything.", "0", "0", "0", "領航，您對我的過去感興趣嗎？雖然按照規定應該是要對您保密的…不過，如果您想知道的話……我會把您想知道的，都告訴您的。", "0", "cv_sk_heiyu_7", "0", "0"},
[4101600110] = {4101600110, 11016001, 11, 5, "15_2_0_0.8", "level2", "It\u{0020}seems\u{0020}I\u{0020}have\u{0020}to\u{0020}admit\u{0020}it.\u{0020}You\u{0020}really\u{0020}are\u{0020}different\u{0020}from\u{0020}the\u{0020}others.\u{0020}You\u{0020}don't\u{0020}treat\u{0020}me\u{0020}like\u{0020}a\u{0020}tool\u{0020}but\u{0020}like\u{0020}a\u{0020}person.", "0", "0", "0", "…是該承認這一點了。領…領航，您的確和其他人不一樣。從您身上，我感受不到其他人的偏見……您並沒有把我視為達成目的的道具，而是當做同您一樣的“人”對待。", "0", "cv_sk_heiyu_8", "0", "0"},
[4101600111] = {4101600111, 11016001, 12, 6, "0", "0", "Thank\u{0020}you.", "0", "0", "0", "感謝。", "0", "cv_sk_heiyu_9", "0", "0"},
[4101600112] = {4101600112, 11016001, 13, 7, "0", "0", "My\u{0020}arrows\u{0020}will\u{0020}pierce\u{0020}through\u{0020}your\u{0020}enemies.", "0", "0", "0", "箭矢，將貫穿您的敵人。", "0", "cv_sk_heiyu_10", "0", "0"},
[4101600113] = {4101600113, 11016001, 14, 8, "0", "0", "You\u{0020}gave\u{0020}me\u{0020}love.\u{0020}Whether\u{0020}it's\u{0020}friendship,\u{0020}family,\u{0020}or\u{0020}even\u{0020}sympathy...\u{0020}I'll\u{0020}repay\u{0020}you\u{0020}with\u{0020}loyalty.\u{0020}That's\u{0020}my\u{0020}code.", "0", "0", "0", "您…給予了我愛。無論這份愛是友情、是親情、是愛情，哪怕是同情…我都會用忠誠回報您。這就是“黑羽”的信條。", "0", "cv_sk_heiyu_11", "0", "0"},
[4101600114] = {4101600114, 11016001, 15, 9, "0", "0", "I'll\u{0020}make\u{0020}your\u{0020}enemies\u{0020}suffer\u{0020}more.", "0", "0", "0", "讓您的敵人，更加痛苦吧。", "0", "cv_sk_heiyu_12", "0", "0"},
[4101600115] = {4101600115, 11016001, 16, 10, "0", "0", "We've\u{0020}reached\u{0020}the\u{0020}destination.", "0", "0", "0", "抵達目的地。", "0", "cv_sk_heiyu_13", "0", "0"},
[4101600116] = {4101600116, 11016001, 17, 11, "0", "0", "For\u{0020}you,\u{0020}I'll\u{0020}clear\u{0020}every\u{0020}obstacle.", "0", "0", "0", "為了領航，我會掃清所有的阻礙。", "0", "cv_sk_heiyu_14", "0", "0"},
