[4002500102] = {4002500102, 10025001, 3, 3, "0", "0", "I'm\u{0020}Mel.\u{0020}And\u{0020}you're\u{0020}the\u{0020}Navigator\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force?\u{0020}Huh,\u{0020}you're\u{0020}a\u{0020}bit\u{0020}skinnier\u{0020}than\u{0020}I\u{0020}imagined.", "0", "我是梅爾。你就是那個多瑙特別聯合部隊的領航？比我想像中的要瘦弱一點啊。", "0", "0", "0", "cv_melu_1", "0", "0"},
[4002500103] = {4002500103, 10025001, 91, 4, "0", "idle", "Hey,\u{0020}when\u{0020}can\u{0020}we\u{0020}go\u{0020}out\u{0020}and\u{0020}fight?\u{0020}I'm\u{0020}getting\u{0020}a\u{0020}little\u{0020}bored.", "0", "喂，我們什麼時候才能出擊啊，稍微有些無聊了。", "0", "0", "0", "cv_melu_3", "0", "idle,idle"},
[4002500104] = {4002500104, 10025001, 91, 4, "0", "idle", "Huh?\u{0020}Is\u{0020}my\u{0020}voice\u{0020}is\u{0020}too\u{0020}loud?\u{0020}Well,\u{0020}what\u{0020}can\u{0020}I\u{0020}do?\u{0020}Now\u{0020}that\u{0020}I'm\u{0020}this\u{0020}big,\u{0020}it's\u{0020}kind\u{0020}of\u{0020}hard\u{0020}to\u{0020}control\u{0020}it.", "0", "哎？我的聲音太大了？沒辦法，身體變得這麼大之後我也沒辦法啊。", "0", "0", "0", "cv_melu_4", "0", "idle,idle"},
[4002500105] = {4002500105, 10025001, 91, 4, "0", "idle", "Hey,\u{0020}can\u{0020}I\u{0020}complain\u{0020}a\u{0020}little?\u{0020}I\u{0020}didn't\u{0020}expect\u{0020}to\u{0020}get\u{0020}along\u{0020}with\u{0020}everyone,\u{0020}but\u{0020}that\u{0020}Fafnir\u{0020}is\u{0020}pushing\u{0020}it.\u{0020}It's\u{0020}impossible\u{0020}to\u{0020}work\u{0020}with\u{0020}her\u{0020}during\u{0020}a\u{0020}fight...", "0", "喂，可以聽我稍微抱怨下嗎？雖說我並沒有指望能和大家相處得多好，但是法芙娜那個傢夥也太過分了吧。戰鬥的時候完全沒法和她好好配合......", "0", "0", "0", "cv_melu_29", "0", "idle,idle"},
[4002500106] = {4002500106, 10025001, 92, 5, "14_1_0_0.8", "level1", "If\u{0020}I\u{0020}could,\u{0020}I'd\u{0020}like\u{0020}to\u{0020}go\u{0020}back\u{0020}in\u{0020}time...\u{0020}even\u{0020}just\u{0020}to\u{0020}see\u{0020}them\u{0020}again...", "0", "如果有可能的話，我希望能夠回到過去...哪怕只是再見他們一面也好......", "0", "0", "0", "cv_melu_30", "0", "level1,level1"},
[4002500108] = {4002500108, 10025001, 93, 5, "14_2_0_0.8", "switch1", "Huh?\u{0020}You\u{0020}need\u{0020}something?\u{0020}If\u{0020}it's\u{0020}time\u{0020}to\u{0020}go\u{0020}out,\u{0020}I'm\u{0020}ready\u{0020}whenever.", "0", "哈？找我有什麼事嗎？如果要出擊的話我隨時都能奉陪。", "0", "0", "0", "cv_melu_5", "0", "switch1,switch1"},
