[4002100102] = {4002100102, 10021001, 3, 3, "0", "0", "Nice\u{0020}to\u{0020}meet\u{0020}you,\u{0020}Navigator\u{0020}of\u{0020}Danube.\u{0020}We're\u{0020}Cynthia\u{0020}and\u{0020}Cynemia,\u{0020}the\u{0020}two-in-one\u{0020}Driver.", "はじめまして、ダニューブのナビゲーター。私たちは二つで一つのドライバー、シンシアとシンミアです。", "0", "0", "0", "0", "cv_sk_xinxiya_1", "0", "0"},
[4002100103] = {4002100103, 10021001, 4, 4, "0", "idle", "Just\u{0020}standing\u{0020}here\u{0020}is\u{0020}a\u{0020}bit\u{0020}boring...\u{0020}\nHow\u{0020}about\u{0020}we\u{0020}go\u{0020}for\u{0020}a\u{0020}walk,\u{0020}Navigator?", "立っているだけでは少し退屈ですから……。みんなでお散歩に行こうよ！ナビゲーター。", "0", "0", "0", "0", "cv_sk_xinxiya_3", "0", "0"},
[4002100104] = {4002100104, 10021001, 5, 4, "0", "idle", "No\u{0020}enemies\u{0020}around\u{0020}the\u{0020}Ark,\u{0020}so\u{0020}don't\u{0020}worry.\u{0020}\nEven\u{0020}if\u{0020}any\u{0020}appear,\u{0020}we\u{0020}can\u{0020}handle\u{0020}them\u{0020}in\u{0020}no\u{0020}time.", "方舟周辺に敵影、ありません。大丈夫です。もし敵がきても、私たちなら一瞬でやっつけちゃうしね。", "0", "0", "0", "0", "cv_sk_xinxiya_4", "0", "0"},
[4002100105] = {4002100105, 10021001, 6, 4, "0", "idle", "I\u{0020}envy\u{0020}you,\u{0020}being\u{0020}able\u{0020}to\u{0020}travel\u{0020}the\u{0020}world.\u{0020}We're\u{0020}stuck\u{0020}on\u{0020}the\u{0020}Ark\u{0020}most\u{0020}of\u{0020}the\u{0020}time.", "世界中を旅できるナビゲーターが羨ましいなあ。私たちは基本方舟に乗ってるだけだからねー。", "0", "0", "0", "0", "cv_sk_xinxiya_30", "0", "0"},
[4002100106] = {4002100106, 10021001, 7, 5, "15_1_0_0.8", "level1", "Hey,\u{0020}it's\u{0020}a\u{0020}rare\u{0020}chance!\u{0020}Let's\u{0020}head\u{0020}to\u{0020}the\u{0020}city\u{0020}with\u{0020}Flora\u{0020}this\u{0020}weekend.\u{0020}Will\u{0020}you\u{0020}come\u{0020}too,\u{0020}Navigator?", "せっかくの機會ですから、週末はフローラと一緒に街に行く予定です。……ナビゲーターもご一緒にいかがですか？", "0", "0", "0", "0", "cv_sk_xinxiya_31", "0", "0"},
[4002100107] = {4002100107, 10021001, 8, 5, "15_1_0_0.8", "level1", "Huh?\u{0020}Were\u{0020}you\u{0020}calling\u{0020}me,\u{0020}or\u{0020}Cynemia?", "あ……私に何か、ご用でしょうか？それとも、シンミアにですか？", "0", "0", "0", "0", "cv_sk_xinxiya_5", "0", "0"},
[4002100108] = {4002100108, 10021001, 9, 5, "15_1_0_0.8", "level1", "Want\u{0020}to\u{0020}get\u{0020}closer\u{0020}to\u{0020}Cynthia?\u{0020}I\u{0020}can\u{0020}tell\u{0020}you\u{0020}how...\nCynemia...", "シンシアと仲良くなりたいの？じゃあいい方法を教えるね。シンミア……", "0", "0", "0", "0", "cv_sk_xinxiya_6", "0", "0"},
[4002100109] = {4002100109, 10021001, 10, 5, "15_2_0_0.8", "level2", "Hmm...\u{0020}Sorry,\u{0020}I\u{0020}don't\u{0020}really\u{0020}remember\u{0020}you.\u{0020}But\u{0020}to\u{0020}be\u{0020}fair,\u{0020}I\u{0020}don't\u{0020}really\u{0020}remember\u{0020}anyone\u{0020}except\u{0020}Cynthia.\u{0020}Still,\u{0020}I\u{0020}feel\u{0020}like\u{0020}you're\u{0020}someone\u{0020}important\u{0020}to\u{0020}both\u{0020}of\u{0020}us,\u{0020}deep\u{0020}down.", "えーっと……ごめんね。あなたのこと、覚えてないんだ。っていうより、私はシンシア以外の人のことはあんまり覚えてないの。でもなぜか、私にも、シンシアにも、あなたがとても大切な人だって気がするんだ。", "0", "0", "0", "0", "cv_sk_xinxiya_7", "0", "0"},
[4002100110] = {4002100110, 10021001, 11, 5, "15_2_0_0.8", "level2", "As\u{0020}you\u{0020}can\u{0020}see,\u{0020}she's\u{0020}like\u{0020}my\u{0020}shadow.\u{0020}If\u{0020}you\u{0020}don't\u{0020}mind,\u{0020}the\u{0020}three\u{0020}of\u{0020}us\u{0020}can\u{0020}stay\u{0020}like\u{0020}this...", "ご覧の通り、私とシンミアは表裏一體の存在。もしあなたが宜しければ、私達三人、このままで……いたいです……", "0", "0", "0", "0", "cv_sk_xinxiya_8", "0", "0"},
[4002100111] = {4002100111, 10021001, 12, 6, "0", "0", "Let's\u{0020}get\u{0020}stronger\u{0020}together,\u{0020}Cynemia.", "一緒に強くなろう。シンミア。", "0", "0", "0", "0", "cv_sk_xinxiya_9", "0", "0"},
[4002100112] = {4002100112, 10021001, 13, 7, "0", "0", "Great\u{0020}job,\u{0020}Cynthia!\u{0020}We've\u{0020}gotten\u{0020}stronger\u{0020}again!", "やったね、シンシア！これで私たち、もっと強くなれたよ！", "0", "0", "0", "0", "cv_sk_xinxiya_10", "0", "0"},
[4002100113] = {4002100113, 10021001, 14, 8, "0", "0", "This\u{0020}moment,\u{0020}arriving\u{0020}here\u{0020}with\u{0020}you,\u{0020}is\u{0020}the\u{0020}most\u{0020}precious\u{0020}in\u{0020}my\u{0020}life.", "あなたと一緒にここまで來ることができました。いま私は、人生で一番大切な瞬間を迎えています……", "0", "0", "0", "0", "cv_sk_xinxiya_11", "0", "0"},
[4002100114] = {4002100114, 10021001, 15, 9, "0", "0", "Cynemia,\u{0020}let's\u{0020}try\u{0020}out\u{0020}the\u{0020}new\u{0020}skill\u{0020}together.", "シンミア、一緒に新しいスキルを試してみよう！", "0", "0", "0", "0", "cv_sk_xinxiya_12", "0", "0"},
[4002100115] = {4002100115, 10021001, 16, 10, "0", "0", "Let's\u{0020}do\u{0020}this\u{0020}together,\u{0020}Cynemia.", "シンミア、一緒に行こう。", "0", "0", "0", "0", "cv_sk_xinxiya_13", "0", "0"},
[4002100116] = {4002100116, 10021001, 17, 11, "0", "0", "The\u{0020}battle's\u{0020}over.\u{0020}Next\u{0020}time,\u{0020}let's\u{0020}fight\u{0020}side\u{0020}by\u{0020}side\u{0020}again.", "戦闘終了。次も一緒に戦いましょう。", "0", "0", "0", "0", "cv_sk_xinxiya_14", "0", "0"},
