[4102300200] = {4102300200, 11023002, 1, 1, "0", "0", "Haze\u{0020}reverb.", "ハツリバーブ。", "0", "0", "0", "0", "cv_sk2_xiaomeng_1", "0", "0"},
[4102300201] = {4102300201, 11023002, 2, 2, "0", "0", "Is\u{0020}this\u{0020}where\u{0020}you\u{0020}often\u{0020}stay,\u{0020}sir?\u{0020}Hmm…\u{0020}well\u{0020}then,\u{0020}this\u{0020}is\u{0020}where\u{0020}Xiaomeng\u{0020}will\u{0020}stand\u{0020}guard\u{0020}from\u{0020}now\u{0020}on.", "ここが殿がよくいる場所か……うん……うん！では、今からここが暁夢（ぎょうむ）の守備範囲だな！", "0", "0", "0", "0", "cv_sk2_xiaomeng_2", "0", "0"},
[4102300202] = {4102300202, 11023002, 3, 3, "0", "0", "Upon\u{0020}hearing\u{0020}your\u{0020}call,\u{0020}Xiaomeng\u{0020}rushed\u{0020}over.\u{0020}What\u{0020}trial\u{0020}are\u{0020}you\u{0020}giving\u{0020}me\u{0020}this\u{0020}time?", "殿の呼びかけに応じ、暁夢、ここに參上！さあ、今回はどのような試練が待っているんだ？", "0", "0", "0", "0", "cv_sk2_xiaomeng_3", "0", "0"},
[4102300203] = {4102300203, 11023002, 4, 4, "0", "idle", "Eh…?\u{0020}No\u{0020}training\u{0020}in\u{0020}this\u{0020}outfit?\u{0020}Why...?\u{0020}Much\u{0020}as\u{0020}I'm\u{0020}itching\u{0020}for\u{0020}a\u{0020}fight…\u{0020}Xiaomeng\u{0020}will\u{0020}take\u{0020}your\u{0020}order.", "この拳の意味？分からん、考えたこともない。師匠が拳法を教え、暁夢はそれを修める。それだけのことだ。暁夢が何のためにどうやって拳を出すのか。それは殿に任せる。殿が思うところに我が拳あり！それが暁夢の生き様だ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_46", "0", "0"},
[4102300204] = {4102300204, 11023002, 5, 4, "0", "idle", "Tickle\u{0020}attack…?\u{0020}Pfft—Xiaomeng's\u{0020}not\u{0020}afraid\u{0020}of\u{0020}that!\u{0020}Bring\u{0020}it\u{0020}on!", "殿が修行をつけてくれると澄練（ちょうれん）から聞いたんだ。今からどんな命令にも従うぞ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_55", "0", "0"},
[4102300205] = {4102300205, 11023002, 6, 4, "0", "idle", "Won't\u{0020}you\u{0020}try\u{0020}the\u{0020}Valentine's\u{0020}gift\u{0020}I\u{0020}gave\u{0020}you,\u{0020}my\u{0020}lord?", "その拳に乗せるものを探しなさい……母上はそう言って、暁夢を追い出したんだ。殿。この意味が分かるか？", "0", "0", "0", "0", "cv_sk2_xiaomeng_56", "0", "0"},
[4102300206] = {4102300206, 11023002, 7, 5, "1_》_0_0.8", "level", "So\u{0020}today,\u{0020}all\u{0020}I\u{0020}need\u{0020}to\u{0020}do\u{0020}is\u{0020}follow\u{0020}your\u{0020}lead,\u{0020}right?\u{0020}Perfect!", "と、殿？何をしているんだ？", "0", "0", "0", "0", "cv_sk2_xiaomeng_49", "0", "0"},
[4102300207] = {4102300207, 11023002, 8, 5, "1_》_0_0.8", "level", "Wow,\u{0020}plain-cloth\u{0020}officers\u{0020}out\u{0020}on\u{0020}a\u{0020}mission\u{0020}today!\u{0020}Who's\u{0020}the\u{0020}target?\u{0020}Name\u{0020}it,\u{0020}and\u{0020}I'll\u{0020}handle\u{0020}it.", "拳法を始めた時は痛かった拳が、今はもう痛むことはない。暁夢の手を見てみるか？", "0", "0", "0", "0", "cv_sk2_xiaomeng_50", "0", "0"},
[4102300208] = {4102300208, 11023002, 9, 5, "1_》_100_1.5", "level", "Navigator,\u{0020}it's\u{0020}fine.\u{0020}Xiaomeng\u{0020}can\u{0020}dress\u{0020}herself.", "殿。暁夢に命令をくれ。暁夢は殿の言うことを聞きたい。暁夢は……殿の傍にいたい……", "0", "0", "0", "0", "cv_sk2_xiaomeng_52", "0", "0"},
[4102300209] = {4102300209, 11023002, 10, 5, "1_》_500_2", "level", "Ugh…\u{0020}feel\u{0020}like\u{0020}I'm\u{0020}burning\u{0020}up…", "殿。暁夢は少し分かってきた気がする……でも、もっと落ち著いて考えてから、話そうと思う。だから今はここまでだ。", "0", "0", "0", "0", "cv_sk2_xiaomeng_53", "0", "0"},
[4102300210] = {4102300210, 11023002, 11, 5, "1_》_1000_2.5", "level", "I'm\u{0020}blushing,\u{0020}you\u{0020}say?\u{0020}Yeah!\u{0020}Xiaomeng's\u{0020}heart\u{0020}is\u{0020}thumping\u{0020}like\u{0020}crazy!\u{0020}You\u{0020}want\u{0020}me\u{0020}to\u{0020}calm\u{0020}down,\u{0020}my\u{0020}lord?", "考えることは大切だけど……決めることも大切だな！で、暁夢は平心社のみんなが大切で……でも！殿も大切な存在で……うーん……申し訳ない。いまの暁夢は、これぐらいしか分からない。……だからこれから一緒に考えてくれ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_54", "0", "0"},
[4102300211] = {4102300211, 11023002, 12, 6, "0", "0", "Oh,\u{0020}I\u{0020}see\u{0020}now.\u{0020}So,\u{0020}this\u{0020}is\u{0020}a\u{0020}type\u{0020}of\u{0020}training\u{0020}technique?", "このような修行があるとは！", "0", "0", "0", "0", "cv_sk2_xiaomeng_12", "0", "0"},
[4102300212] = {4102300212, 11023002, 13, 7, "0", "0", "What's\u{0020}the\u{0020}goal\u{0020}of\u{0020}doing\u{0020}this?", "もっと體を鍛えるぞ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_13", "0", "0"},
[4102300213] = {4102300213, 11023002, 14, 8, "0", "0", "Time\u{0020}to\u{0020}stretch\u{0020}out\u{0020}my\u{0020}spine…", "うおぉー！こんなにスッキリしたのは久しぶりだ！どうだ！暁夢は殿の望む姿になれたか？", "0", "0", "0", "0", "cv_sk2_xiaomeng_14", "0", "0"},
[4102300214] = {4102300214, 11023002, 15, 9, "0", "0", "Not\u{0020}too\u{0020}much,\u{0020}not\u{0020}too\u{0020}little.\u{0020}Adjust\u{0020}as\u{0020}needed—bend\u{0020}when\u{0020}it's\u{0020}time,\u{0020}stand\u{0020}tall\u{0020}when\u{0020}required!", "過ぎること及ばざることなく、曲に隨（したが）い伸（しん）に就（つ）く！", "0", "0", "0", "0", "cv_sk2_xiaomeng_15", "0", "0"},
[4102300215] = {4102300215, 11023002, 16, 10, "0", "0", "Xiaomeng,\u{0020}the\u{0020}Warrior\u{0020}of\u{0020}Kyushu\u{0020}Pingxin,\u{0020}awaiting\u{0020}your\u{0020}command.", "九州平心社（きゅうしゅうへいしんしゃ）の武者、暁夢。參る！", "0", "0", "0", "0", "cv_sk2_xiaomeng_16", "0", "0"},
[4102300216] = {4102300216, 11023002, 17, 11, "0", "0", "Simple\u{0020}enough—task\u{0020}completed\u{0020}without\u{0020}a\u{0020}hitch!", "押忍、一件落著！", "0", "0", "0", "0", "cv_sk2_xiaomeng_17", "0", "0"},
[4102300217] = {4102300217, 11023002, 18, 12, "0", "0", "Now\u{0020}that\u{0020}I've\u{0020}got\u{0020}the\u{0020}hang\u{0020}of\u{0020}it,\u{0020}let's\u{0020}go\u{0020}again!", "経験は積んだ、もう一度！", "0", "0", "0", "0", "cv_sk2_xiaomeng_18", "0", "0"},
[4102300218] = {4102300218, 11023002, 19, 13, "0", "0", "Just\u{0020}half\u{0020}a\u{0020}step\u{0020}shy.", "一手足りないか……！", "0", "0", "0", "0", "cv_sk2_xiaomeng_19", "0", "0"},
[4102300219] = {4102300219, 11023002, 20, 14, "0", "0", "Winning\u{0020}or\u{0020}losing\u{0020}doesn't\u{0020}matter.\u{0020}Xiaomeng\u{0020}will\u{0020}stand\u{0020}by\u{0020}your\u{0020}side\u{0020}and\u{0020}start\u{0020}fresh\u{0020}with\u{0020}you.", "勝敗は兵家の常だ。殿が命じてくれるのなら暁夢が再び挑んでやる！", "0", "0", "0", "0", "cv_sk2_xiaomeng_20", "0", "0"},
[4102300220] = {4102300220, 11023002, 21, 15, "0", "0", "SOO\u{0020}annoying!!!!", "倒す。それだけだ。", "0", "0", "0", "0", "cv_sk2_xiaomeng_57", "0", "0"},
[4102300221] = {4102300221, 11023002, 23, 16, "0", "0", "I\u{0020}said\u{0020}no\u{0020}fighting!", "いちっ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_58", "0", "0"},
[4102300222] = {4102300222, 11023002, 24, 17, "0", "0", "Ah?", "にっ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_59", "0", "0"},
[4102300223] = {4102300223, 11023002, 25, 18, "0", "0", "Poof,\u{0020}all\u{0020}gone!", "虛領頂勁。はぁーー！", "0", "0", "0", "0", "cv_sk2_xiaomeng_60", "0", "0"},
[4102300224] = {4102300224, 11023002, 26, 19, "0", "0", "Not\u{0020}coming\u{0020}back\u{0020}for\u{0020}dinner\u{0020}tonight!", "暁夢は……錆びてしまったのか……", "0", "0", "0", "0", "cv_sk2_xiaomeng_62", "0", "0"},
[4102300225] = {4102300225, 11023002, 27, 20, "0", "0", "I've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}so\u{0020}long.\u{0020}Today's\u{0020}the\u{0020}day...\u{0020}for\u{0020}that\u{0020}medicinal\u{0020}bath\u{0020}my\u{0020}mother\u{0020}used\u{0020}to\u{0020}prepare\u{0020}all\u{0020}the\u{0020}time...", "待っていたぞ。今日は…あの…昔、母上がよくやっていた薬湯をするんだな？", "0", "0", "0", "0", "cv_sk2_xiaomeng_26", "0", "0"},
[4102300226] = {4102300226, 11023002, 28, 21, "0", "0", "Sir,\u{0020}don't\u{0020}you\u{0020}have\u{0020}any\u{0020}requests\u{0020}for\u{0020}Xiaomeng?\u{0020}Whatever\u{0020}you\u{0020}say,\u{0020}Xiaomeng\u{0020}will\u{0020}listen.", "殿……暁夢に命令はないか？……ちゃんと従うぞ。", "0", "0", "0", "0", "cv_sk2_xiaomeng_27", "0", "0"},
[4102300227] = {4102300227, 11023002, 29, 21, "0", "0", "Is\u{0020}this\u{0020}behaving\u{0020}well?\u{0020}But\u{0020}if\u{0020}I\u{0020}only\u{0020}stay\u{0020}in\u{0020}one\u{0020}position,\u{0020}some\u{0020}spots\u{0020}won't\u{0020}get\u{0020}washed\u{0020}properly...", "これでいいのか？同じ體勢だけだと、すみずみまできれいに洗えないだろ……？", "0", "0", "0", "0", "cv_sk2_xiaomeng_28", "0", "0"},
[4102300228] = {4102300228, 11023002, 30, 22, "0", "0", "Is\u{0020}it\u{0020}about\u{0020}to\u{0020}begin...?", "やってみるか？", "0", "0", "0", "0", "cv_sk2_xiaomeng_29", "0", "0"},
[4102300229] = {4102300229, 11023002, 31, 23, "0", "0", "Xiaomeng\u{0020}trusts\u{0020}you\u{0020}completely.", "暁夢は殿を信じるぞ。", "0", "0", "0", "0", "cv_sk2_xiaomeng_30", "0", "0"},
[4102300230] = {4102300230, 11023002, 32, 24, "0", "0", "You're\u{0020}the\u{0020}one\u{0020}who\u{0020}taught\u{0020}me\u{0020}to\u{0020}see\u{0020}what's\u{0020}right\u{0020}and\u{0020}wrong,\u{0020}what's\u{0020}true\u{0020}and\u{0020}false.", "善と悪、正解と不正解を見極める。殿がこの道理を教えてくれたんだ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_31", "0", "0"},
[4102300231] = {4102300231, 11023002, 33, 25, "0", "0", "Navigator!", "殿！", "0", "0", "0", "0", "cv_sk2_xiaomeng_32", "0", "0"},
[4102300232] = {4102300232, 11023002, 34, 26, "0", "0", "Welcome\u{0020}back,\u{0020}Xiaomeng\u{0020}followed\u{0020}your\u{0020}orders\u{0020}and\u{0020}kept\u{0020}watch!", "おかえり、殿！暁夢はちゃんと言いつけ通り留守番をしてたぞ！", "0", "0", "0", "0", "cv_sk2_xiaomeng_63", "0", "0"},
