[415400] = {415400, 11054, 1, 1, "0", "0", "Haze\u{0020}Reverb", "蒼霧殘響", "0", "0", "0", "0", "cv_iztk_1", "0", "0"},
[415401] = {415401, 11054, 2, 2, "0", "0", "Focus\u{0020}on\u{0020}the\u{0020}battle\u{0020}ahead.\u{0020}I'll\u{0020}protect\u{0020}the\u{0020}rear.", "請放心去作戰，後方的安危就交給我負責吧。", "0", "0", "0", "0", "cv_iztk_2", "0", "0"},
[415402] = {415402, 11054, 3, 3, "0", "0", "I'm\u{0020}Tenka\u{0020}Izumo,\u{0020}Commander\u{0020}of\u{0020}the\u{0020}6th\u{0020}Squad\u{0020}of\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force.\u{0020}Just\u{0020}say\u{0020}the\u{0020}word\u{0020}if\u{0020}you\u{0020}need\u{0020}anything.", "魔防隊第六組組長·出雲天花。有需要的地方請儘管開口。", "0", "0", "0", "0", "cv_iztk_3", "0", "0"},
[415403] = {415403, 11054, 4, 4, "0", "idle", "It's\u{0020}a\u{0020}shame\u{0020}my\u{0020}powers\u{0020}can't\u{0020}allow\u{0020}me\u{0020}to\u{0020}teleport\u{0020}between\u{0020}worlds...", "我的能力無法在兩個世界之間傳送，真是遺憾。", "0", "0", "0", "0", "cv_iztk_4", "0", "0"},
[415404] = {415404, 11054, 5, 4, "0", "idle", "This\u{0020}world\u{0020}suffers\u{0020}just\u{0020}as\u{0020}much\u{0020}pain\u{0020}as\u{0020}ours...", "這個世界，同樣也深陷痛苦和折磨之中呢……", "0", "0", "0", "0", "cv_iztk_5", "0", "0"},
[415405] = {415405, 11054, 6, 4, "0", "idle", "I\u{0020}hope\u{0020}no\u{0020}Mato\u{0020}Mishap\u{0020}happens\u{0020}while\u{0020}we're\u{0020}gone.\u{0020}But\u{0020}I\u{0020}believe\u{0020}even\u{0020}without\u{0020}me,\u{0020}my\u{0020}squad\u{0020}can\u{0020}handle\u{0020}them\u{0020}perfectly!", "希望我們消失的期間，我們的世界不要發生【魔都災害】。不過我相信即使我不在，我的組員們也能夠發揮她們的能力，及時並且完美地解決【災害】問題。", "0", "0", "0", "0", "cv_iztk_6", "0", "0"},
[415406] = {415406, 11054, 7, 5, "1_》_0_0.8", "level1", "I\u{0020}can\u{0020}use\u{0020}my\u{0020}abilities\u{0020}up\u{0020}to\u{0020}666\u{0020}times\u{0020}in\u{0020}a\u{0020}row,\u{0020}which\u{0020}is\u{0020}more\u{0020}than\u{0020}enough\u{0020}for\u{0020}regular\u{0020}fights.\u{0020}But\u{0020}if\u{0020}a\u{0020}nightmare\u{0020}scenario\u{0020}ever\u{0020}happens\u{0020}...\u{0020}I'll\u{0020}save\u{0020}the\u{0020}final\u{0020}teleportation\u{0020}for\u{0020}you.", "我可以連續使用能力的次數上限是666次，應付一般的戰鬥已經足夠了。但如果真的遇到需要超過這個限制的情況……我會將最後的傳送，留給你們。", "0", "0", "0", "0", "cv_iztk_7", "0", "0"},
[415407] = {415407, 11054, 8, 5, "1_》_0_0.8", "level1", "Sin,\u{0020}Shuuki...\u{0020}Neither\u{0020}world\u{0020}can\u{0020}live\u{0020}in\u{0020}peace\u{0020}with\u{0020}them\u{0020}around.", "【原罪】、【醜鬼】，無論哪個世界的人們都得不到平靜的生活。", "0", "0", "0", "0", "cv_iztk_8", "0", "0"},
[415408] = {415408, 11054, 9, 5, "1_》_100_1.5", "level2", "I\u{0020}only\u{0020}manage\u{0020}two\u{0020}team\u{0020}members\u{0020}while\u{0020}you\u{0020}lead\u{0020}dozens.\u{0020}That's\u{0020}no\u{0020}easy\u{0020}feat.", "我身為組長只需要管理兩名組員，而你手下的駕駛員是“2”的幾十倍。真的很了不起呢。", "0", "0", "0", "0", "cv_iztk_9", "0", "0"},
[415409] = {415409, 11054, 10, 5, "1_》_500_2", "level3", "You\u{0020}who\u{0020}have\u{0020}found\u{0020}a\u{0020}way\u{0020}to\u{0020}fight\u{0020}even\u{0020}without\u{0020}Peach's\u{0020}Blessing\u{0020}are\u{0020}strong.", "沒有【桃之恩惠】的你們，很強大。", "0", "0", "0", "0", "cv_iztk_10", "0", "0"},
[415410] = {415410, 11054, 11, 5, "1_》_1000_2.5", "level4", "Seeing\u{0020}the\u{0020}beauty\u{0020}of\u{0020}another\u{0020}world\u{0020}has\u{0020}been\u{0020}wonderful.\u{0020}I\u{0020}wish\u{0020}a\u{0020}chance\u{0020}that\u{0020}you\u{0020}all\u{0020}can\u{0020}share\u{0020}such\u{0020}joy.", "能夠見識到不同世界的美好真的很開心，如果有機會也希望可以請你們去我們的世界做客。", "0", "0", "0", "0", "cv_iztk_11", "0", "0"},
[415411] = {415411, 11054, 12, 6, "0", "0", "That's\u{0020}effortless.", "輕輕鬆松就變強了。", "0", "0", "0", "0", "cv_iztk_12", "0", "0"},
[415412] = {415412, 11054, 13, 7, "0", "0", "It\u{0020}feels\u{0020}so\u{0020}special.", "很特殊的感覺。", "0", "0", "0", "0", "cv_iztk_13", "0", "0"},
[415413] = {415413, 11054, 14, 8, "0", "0", "Thanks\u{0020}for\u{0020}the\u{0020}gift.\u{0020}Look\u{0020}forward\u{0020}to\u{0020}my\u{0020}performance\u{0020}in\u{0020}battle.", "感謝你的禮物，期待我在戰鬥中的表現吧。", "0", "0", "0", "0", "cv_iztk_14", "0", "0"},
[415414] = {415414, 11054, 15, 9, "0", "0", "667\u{0020}teleportations.\u{0020}Can\u{0020}I\u{0020}pull\u{0020}it\u{0020}off?", "667，能做到嗎？", "0", "0", "0", "0", "cv_iztk_15", "0", "0"},
[415415] = {415415, 11054, 16, 10, "0", "0", "If\u{0020}that's\u{0020}all,\u{0020}I\u{0020}can\u{0020}handle\u{0020}them\u{0020}alone.", "只有這些敵人的話，全部交給我也沒有問題的。", "0", "0", "0", "0", "cv_iztk_16", "0", "0"},
[415416] = {415416, 11054, 17, 11, "0", "0", "Come\u{0020}on\u{0020}through\u{0020}my\u{0020}portal.\u{0020}Save\u{0020}your\u{0020}energy\u{0020}for\u{0020}celebrating.", "用傳送門回去吧，大家的精力可要好好用在慶祝上。", "0", "0", "0", "0", "cv_iztk_17", "0", "0"},
[415417] = {415417, 11054, 18, 12, "0", "0", "I'll\u{0020}teleport\u{0020}the\u{0020}wounded\u{0020}back.", "我來把傷患傳送回去。", "0", "0", "0", "0", "cv_iztk_18", "0", "0"},
[415418] = {415418, 11054, 19, 13, "0", "0", "Everyone's\u{0020}hurt...\u{0020}But\u{0020}we\u{0020}won;\u{0020}that's\u{0020}what\u{0020}counts.", "大家都受傷了，不過只要贏了就好。", "0", "0", "0", "0", "cv_iztk_19", "0", "0"},
[415419] = {415419, 11054, 20, 14, "0", "0", "Don't\u{0020}push\u{0020}yourselves.\u{0020}Just\u{0020}go.", "不要逞強，你們先走。", "0", "0", "0", "0", "cv_iztk_20", "0", "0"},
