[404200] = {404200, 10042, 1, 1, "0", "0", "Haze\u{0020}Reverb", "蒼霧殘響", "0", "0", "0", "0", "cv_srss_1", "0", "0"},
[404201] = {404201, 10042, 2, 2, "0", "0", "Nice\u{0020}scenery\u{0020}here.\u{0020}I\u{0020}wish\u{0020}I\u{0020}could\u{0020}grow\u{0020}even\u{0020}bigger!", "這裡風景不錯嘛~好想再變大點~", "0", "0", "0", "0", "cv_srss_2", "0", "0"},
[404202] = {404202, 10042, 3, 3, "0", "0", "Shushu\u{0020}Suruga,\u{0020}ready\u{0020}to\u{0020}turn\u{0020}this\u{0020}world\u{0020}into\u{0020}my\u{0020}personal\u{0020}adventure\u{0020}logbook!", "駿河朱朱，將在異世界開始新的冒險~！", "0", "0", "0", "0", "cv_srss_3", "0", "0"},
[404203] = {404203, 10042, 4, 4, "0", "idle", "The\u{0020}only\u{0020}thing\u{0020}special\u{0020}about\u{0020}me\u{0020}now\u{0020}is\u{0020}that\u{0020}I\u{0020}can\u{0020}shrink...\u{0020}Wait,\u{0020}no.\u{0020}If\u{0020}I\u{0020}wanted,\u{0020}I\u{0020}could\u{0020}grow\u{0020}even\u{0020}bigger\u{0020}than\u{0020}an\u{0020}average\u{0020}Driver!", "我的特殊之處現在就只有能變小了……不對，只要我想的話我也可以變得更大，比一般駕駛員都大！", "0", "0", "0", "0", "cv_srss_4", "0", "0"},
[404204] = {404204, 10042, 5, 4, "0", "idle", "I\u{0020}never\u{0020}thought\u{0020}something\u{0020}straight\u{0020}out\u{0020}of\u{0020}a\u{0020}manga\u{0020}would\u{0020}actually\u{0020}happen.\u{0020}However,\u{0020}somehow\u{0020}I\u{0020}expected\u{0020}a\u{0020}world\u{0020}with\u{0020}more\u{0020}fantasy-adventure\u{0020}vibes.", "沒想到真遇到了漫畫裡面會發生的事情~我還以為會有更有奇幻冒險風格的那種世界呢……", "0", "0", "0", "0", "cv_srss_5", "0", "0"},
[404205] = {404205, 10042, 6, 4, "0", "idle", "Still,\u{0020}this\u{0020}world\u{0020}is\u{0020}subtly\u{0020}different\u{0020}from\u{0020}ours.\u{0020}I'd\u{0020}love\u{0020}to\u{0020}explore\u{0020}inside\u{0020}this\u{0020}Ark!\u{0020}Wanna\u{0020}come\u{0020}with\u{0020}me\u{0020}later,\u{0020}Navigator?", "不過不管怎麼說，這個世界和我們世界還是有著微妙的不同呢，好想去這個方舟的裡面看看，要不等一下領航和我一起去探險怎麼樣？", "0", "0", "0", "0", "cv_srss_6", "0", "0"},
[404206] = {404206, 10042, 7, 5, "1_》_0_0.8", "level1", "Hmm...\u{0020}I\u{0020}wonder\u{0020}how\u{0020}Mom\u{0020}and\u{0020}my\u{0020}sisters\u{0020}are\u{0020}doing.\u{0020}Oh...\u{0020}that's\u{0020}something\u{0020}another\u{0020}world\u{0020}manga\u{0020}rarely\u{0020}covers...\u{0020}Like\u{0020}how\u{0020}the\u{0020}families\u{0020}left\u{0020}behind\u{0020}have\u{0020}to\u{0020}manage\u{0020}well\u{0020}after\u{0020}losing\u{0020}their\u{0020}loved\u{0020}ones.", "嗯……不知道媽媽和姐姐們怎麼樣了，對了……這是異世界轉生漫畫都從不會過度提及的內容呢……轉生者的家人們在失去了親人之後還要堅強地活在世界上之類的事情。", "0", "0", "0", "0", "cv_srss_7", "0", "0"},
[404207] = {404207, 10042, 8, 5, "1_》_0_0.8", "level2", "\"So\u{0020}boring...\"\u{0020}And\u{0020}that's\u{0020}why\u{0020}I've\u{0020}become\u{0020}one\u{0020}of\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force!", "“好無聊啊……”我就這樣想著成為了魔防隊的一員！", "0", "0", "0", "0", "cv_srss_8", "0", "0"},
[404208] = {404208, 10042, 9, 5, "1_》_100_1.5", "level3", "Can\u{0020}I\u{0020}go\u{0020}check\u{0020}out\u{0020}other\u{0020}places?\u{0020}A\u{0020}little\u{0020}stroll\u{0020}won't\u{0020}hurt,\u{0020}right?\u{0020}If\u{0020}I\u{0020}run\u{0020}into\u{0020}a\u{0020}Sin,\u{0020}I'll\u{0020}just\u{0020}knock\u{0020}it\u{0020}out.", "我可以去其他地方看看嗎？隨便逛逛沒事的吧？嗯~如果遇到原罪打飛它們就好了。", "0", "0", "0", "0", "cv_srss_9", "0", "0"},
[404209] = {404209, 10042, 10, 5, "1_》_500_2", "level4", "It's\u{0020}weird\u{0020}how\u{0020}this\u{0020}world\u{0020}is\u{0020}so\u{0020}similar\u{0020}to\u{0020}ours...\u{0020}No\u{0020}language\u{0020}barrier\u{0020}even.\u{0020}Why\u{0020}is\u{0020}that?", "沒想到這個異世界竟然和我們的世界沒什麼太大區別……就連語言之間都沒有溝通障礙……為什麼？", "0", "0", "0", "0", "cv_srss_10", "0", "0"},
[404210] = {404210, 10042, 11, 5, "1_》_1000_2.5", "level5", "Shushu\u{0020}Suruga's\u{0020}Otherworld\u{0020}Adventure\u{0020}Report,\u{0020}a\u{0020}future\u{0020}bestseller!\u{0020}Well,\u{0020}where\u{0020}to\u{0020}today?\u{0020}I\u{0020}need\u{0020}to\u{0020}collect\u{0020}material\u{0020}for\u{0020}my\u{0020}masterpiece!", "《駿河朱朱的異世界冒險體驗報告》，如果回去之後寫這麼一本書的話會不會爆火呢……嘿，為了寫出這本書——今天我們去什麼地方？", "0", "0", "0", "0", "cv_srss_11", "0", "0"},
[404211] = {404211, 10042, 12, 6, "0", "0", "Oh,\u{0020}stats\u{0020}screen!\u{0020}Add\u{0020}points\u{0020}and\u{0020}I'll\u{0020}level\u{0020}up,\u{0020}right?", "哦，我知道這個，加點就能升級對吧。", "0", "0", "0", "0", "cv_srss_12", "0", "0"},
[404212] = {404212, 10042, 13, 7, "0", "0", "As\u{0020}expected\u{0020}of\u{0020}another\u{0020}world.", "果然異世界就是不一樣~", "0", "0", "0", "0", "cv_srss_13", "0", "0"},
[404213] = {404213, 10042, 14, 8, "0", "0", "This\u{0020}is...\u{0020}awakening?\u{0020}Kinda\u{0020}underwhelming...\u{0020}I\u{0020}thought\u{0020}it'd\u{0020}work\u{0020}like\u{0020}the\u{0020}Peach.\u{0020}Where's\u{0020}my\u{0020}protagonist's\u{0020}cheat\u{0020}skill?!", "覺醒……嗯……微妙……我還以會像【桃之果實】一樣會給予我新的能力。可惜了，要是我也能有更主人公一樣的能力就好了。", "0", "0", "0", "0", "cv_srss_14", "0", "0"},
