[4004200101] = {4004200101, 10042001, 2, 2, "0", "0", "Nice\u{0020}scenery\u{0020}here.\u{0020}I\u{0020}wish\u{0020}I\u{0020}could\u{0020}grow\u{0020}even\u{0020}bigger!", "這裡風景不錯嘛~好想再變大點~", "0", "0", "0", "0", "cv_sk_srss_2", "0", "0"},
[4004200102] = {4004200102, 10042001, 3, 3, "0", "0", "Shushu\u{0020}Suruga,\u{0020}ready\u{0020}to\u{0020}turn\u{0020}this\u{0020}world\u{0020}into\u{0020}my\u{0020}personal\u{0020}adventure\u{0020}logbook!", "駿河朱朱，將在異世界開始新的冒險~！", "0", "0", "0", "0", "cv_sk_srss_3", "0", "0"},
[4004200103] = {4004200103, 10042001, 91, 4, "0", "idle", "Yee-haw-!", "呀吼——！", "0", "0", "0", "0", "cv_sk_srss_n1", "0", "idle,idle"},
[4004200104] = {4004200104, 10042001, 91, 4, "0", "idle", "I\u{0020}now\u{0020}equal\u{0020}a\u{0020}skyscraper's\u{0020}height.\u{0020}Much\u{0020}taller\u{0020}than\u{0020}any\u{0020}regular\u{0020}Driver!\u{0020}Hmm...\u{0020}about\u{0020}a\u{0020}hundred\u{0020}meters\u{0020}tall,\u{0020}maybe?", "我現在可是和大樓一樣高了~可比普通的駕駛員都高~我想想~大概有一百多米高吧？", "0", "0", "0", "0", "cv_sk_srss_n2", "0", "idle,idle"},
[4004200105] = {4004200105, 10042001, 91, 4, "0", "idle", "Ah...\u{0020}The\u{0020}fog\u{0020}has\u{0020}faded\u{0020}away\u{0020}with\u{0020}the\u{0020}Sin\u{0020}and\u{0020}I\u{0020}feel\u{0020}so\u{0020}much\u{0020}lighter...\u{0020}The\u{0020}air\u{0020}is\u{0020}fresher,\u{0020}too!\u{0020}What's\u{0020}happening?\u{0020}Did\u{0020}I\u{0020}just\u{0020}level\u{0020}up?", "啊~打倒原罪之後霧氣都消散了，感覺渾身都輕鬆了不少……空氣也清新了……這是什麼……難道說是升級了？", "0", "0", "0", "0", "cv_sk_srss_n3", "0", "idle,idle"},
[4004200106] = {4004200106, 10042001, 92, 5, "14_1_0_0.8", "level1", "I've\u{0020}always\u{0020}wanted\u{0020}to\u{0020}observe\u{0020}a\u{0020}building\u{0020}up\u{0020}close...\u{0020}Though\u{0020}it's\u{0020}an\u{0020}abandoned\u{0020}one\u{0020}and\u{0020}nothing\u{0020}interesting\u{0020}is\u{0020}going\u{0020}on...\u{0020}Wow,\u{0020}a\u{0020}window\u{0020}glass\u{0020}mirror!\u{0020}And\u{0020}my\u{0020}cuteness\u{0020}is\u{0020}still\u{0020}unbeatable!", "我早就想這樣近距離地觀察大樓了……哈哈，雖然是廢棄的大樓就是了……哇，大樓的玻璃裡映出了我的樣子！果然不管什麼角度看我都這麼可愛～", "0", "0", "0", "0", "cv_sk_srss_n4", "0", "level1,level1"},
[4004200107] = {4004200107, 10042001, 92, 5, "14_1_0_0.8", "level1", "How\u{0020}is\u{0020}the\u{0020}outfit?\u{0020}Looking\u{0020}good?", "感覺怎麼樣？我的這身衣服？", "0", "0", "0", "0", "cv_sk_srss_n5", "0", "level1,level1"},
[4004200108] = {4004200108, 10042001, 93, 5, "14_2_0_0.8", "switch1", "Wanna\u{0020}stand\u{0020}on\u{0020}my\u{0020}hand?\u{0020}I\u{0020}can\u{0020}play\u{0020}“throw-and-catch”\u{0020}with\u{0020}you...\u{0020}Wheee...!\u{0020}Just\u{0020}like\u{0020}that.", "要試試站在我的手上嗎，我可以和你玩舉高高的遊戲哦……飛咯飛咯……這樣把你拋起來接住……", "0", "0", "0", "0", "cv_sk_srss_n6", "0", "switch1,switch1"},
[4004200109] = {4004200109, 10042001, 94, 4, "0", "idle2", "Heh\u{0020}heh!", "嘿嘿。", "0", "0", "0", "0", "cv_sk_srss_n7", "0", "idle2,idle2"},
[4004200110] = {4004200110, 10042001, 94, 4, "0", "idle2", "It's\u{0020}hot\u{0020}after\u{0020}battle...\u{0020}The\u{0020}Phantom\u{0020}Device\u{0020}is\u{0020}so\u{0020}handy.\u{0020}With\u{0020}a\u{0020}blueprint,\u{0020}I\u{0020}can\u{0020}change\u{0020}into\u{0020}any\u{0020}outfit\u{0020}I\u{0020}want,\u{0020}right?", "戰鬥過後稍微有點熱呢……幻化裝置竟然這麼方便嗎……有藍圖的話不是什麼樣的衣服我都能換？", "0", "0", "0", "0", "cv_sk_srss_n8", "0", "idle2,idle2"},
[4004200111] = {4004200111, 10042001, 94, 4, "0", "idle2", "Mmm.\u{0020}The\u{0020}breeze\u{0020}feels\u{0020}refreshing\u{0020}after\u{0020}sweating.\u{0020}Ah...!\u{0020}I\u{0020}don't\u{0020}smell,\u{0020}do\u{0020}I?\u{0020}Hiff...\u{0020}hiff.", "嗯~流了汗之後被風拂過~真暢快~啊……！不會有很重的汗味吧！嗅嗅……嗅嗅……", "0", "0", "0", "0", "cv_sk_srss_n9", "0", "idle2,idle2"},
