[4101100101] = {4101100101, 11011001, 2, 2, "0", "0", "Is\u{0020}this\u{0020}the\u{0020}mission\u{0020}you've\u{0020}given\u{0020}me?\u{0020}Understood,\u{0020}I'll\u{0020}stand\u{0020}here.", "這是您下達的任務嗎？瞭解，我會一直站在這裡的。", "0", "0", "0", "0", "cv_honglei_2", "0", "0"},
[4101100102] = {4101100102, 11011001, 3, 3, "0", "0", "Ninja\u{0020}Group,\u{0020}Gourai.\u{0020}Are\u{0020}you\u{0020}the\u{0020}Navigator\u{0020}of\u{0020}this\u{0020}team?\u{0020}I'll\u{0020}follow\u{0020}all\u{0020}your\u{0020}orders.", "忍心社，轟雷。您就是這支隊伍的領航嗎？我明白了，我會聽從您的所有命令。", "0", "0", "0", "0", "cv_honglei_1", "0", "0"},
[4101100103] = {4101100103, 11011001, 91, 4, "0", "idle", "Suzuki\u{0020}Seifung\u{0020}isn't\u{0020}here,\u{0020}right?\u{0020}That's\u{0020}good...\u{0020}Navigator,\u{0020}let\u{0020}me\u{0020}give\u{0020}you\u{0020}some\u{0020}advice,\u{0020}it's\u{0020}best\u{0020}not\u{0020}to\u{0020}pair\u{0020}her\u{0020}with\u{0020}me.", "鈴木清風…她不在這裡吧？那就好……領航，給您一個提議，最好不要把她和我安排在一起。", "0", "0", "0", "0", "cv_honglei_3", "0", "idle,idle"},
[4101100104] = {4101100104, 11011001, 94, 4, "0", "idle2", "Cheer\u{0020}up,\u{0020}Navigator,\u{0020}you've\u{0020}got\u{0020}your\u{0020}own\u{0020}mission\u{0020}too.", "打起精神，領航，您也有自己的任務吧？", "0", "0", "0", "0", "cv_honglei_4", "0", "idle2,idle2"},
[4101100105] = {4101100105, 11011001, 98, 4, "0", "idle3", "Even\u{0020}though\u{0020}AEGIS\u{0020}isn't\u{0020}perfect...\u{0020}it\u{0020}saved\u{0020}me,\u{0020}and\u{0020}that's\u{0020}a\u{0020}fact.\u{0020}So,\u{0020}I've\u{0020}decided\u{0020}to\u{0020}dedicate\u{0020}my\u{0020}life\u{0020}as\u{0020}Thunder\u{0020}Strike\u{0020}to\u{0020}AEGIS.", "儘管艾吉斯並不是一個表面上那樣完美的的組織…但它救了我，讓我重獲新生也是不爭的事實。所以，我決定將作為“轟雷”的人生…全部奉獻給艾吉斯。", "0", "0", "0", "0", "cv_honglei_29", "0", "idle3,idle3"},
[4101100106] = {4101100106, 11011001, 93, 5, "1_》_0_0.8", "switch1", "Members\u{0020}of\u{0020}Ninja\u{0020}Group\u{0020}usually\u{0020}disguise\u{0020}themselves\u{0020}to\u{0020}hide\u{0020}their\u{0020}identities.\u{0020}We\u{0020}serve\u{0020}as\u{0020}AEGIS's\u{0020}invisible\u{0020}blade,\u{0020}working\u{0020}in\u{0020}the\u{0020}shadows\u{0020}until\u{0020}death—that's\u{0020}our\u{0020}fate.", "忍心社的成員，平常會偽裝成不起眼的人，來隱藏自己的身份。我們作為艾吉斯的無形之刃，在黑暗中為它服務，直到死亡才會停下，這就是我們的宿命。", "0", "0", "0", "0", "cv_honglei_30", "0", "switch1,switch1"},
[4101100107] = {4101100107, 11011001, 102, 5, "1_》_0_0.8", "switch2", "Is\u{0020}there\u{0020}a\u{0020}mission?", "有任務嗎？", "0", "0", "0", "0", "cv_honglei_5", "0", "switch2,switch2"},
[4101100108] = {4101100108, 11011001, 96, 5, "1_》_0_0.8", "switch3", "What's\u{0020}the\u{0020}matter?", "怎麼了？", "0", "0", "0", "0", "cv_honglei_43", "0", "switch3,switch3"},
[4101100109] = {4101100109, 11011001, 92, 5, "1_》_0_0.8", "level1", "Members\u{0020}of\u{0020}Ninja\u{0020}Group\u{0020}usually\u{0020}disguise\u{0020}themselves\u{0020}to\u{0020}hide\u{0020}their\u{0020}identities.\u{0020}We\u{0020}serve\u{0020}as\u{0020}AEGIS's\u{0020}invisible\u{0020}blade,\u{0020}working\u{0020}in\u{0020}the\u{0020}shadows\u{0020}until\u{0020}death—that's\u{0020}our\u{0020}fate.", "忍心社的成員，平常會偽裝成不起眼的人，來隱藏自己的身份。我們作為艾吉斯的無形之刃，在黑暗中為它服務，直到死亡才會停下，這就是我們的宿命。", "0", "0", "0", "0", "cv_honglei_30", "0", "level1,level1"},
[4101100110] = {4101100110, 11011001, 95, 5, "1_》_0_0.8", "level2", "No\u{0020}matter\u{0020}how\u{0020}dirty\u{0020}the\u{0020}mission,\u{0020}I\u{0020}will\u{0020}complete\u{0020}it—that's\u{0020}my\u{0020}duty.", "領航，無論多麼骯髒的任務我都會完成的，這就是我的使命。", "0", "0", "0", "0", "cv_honglei_6", "0", "level2,level2"},
[4101100111] = {4101100111, 11011001, 106, 5, "1_》_0_0.8", "level3", "The\u{0020}purpose\u{0020}of\u{0020}founding\u{0020}Ninja\u{0020}Group\u{0020}was\u{0020}to\u{0020}prevent\u{0020}tragedies\u{0020}like\u{0020}\"hers\"\u{0020}from\u{0020}happening\u{0020}again.\u{0020}I\u{0020}won't\u{0020}let\u{0020}anyone\u{0020}hurt\u{0020}you,\u{0020}Navigator...\u{0020}You\u{0020}deserve\u{0020}a\u{0020}happy\u{0020}life.", "成立“忍心社”的目的，是為了防止像“她”那樣的悲劇再次出現。領航，我不會讓任何人傷害您的…您理應有一個美滿的人生。", "0", "0", "0", "0", "cv_honglei_7", "0", "level3,level3"},
[4101100112] = {4101100112, 11011001, 106, 5, "1_》_0_0.8", "level4", "...Navigator,\u{0020}I've\u{0020}always\u{0020}thought\u{0020}that\u{0020}as\u{0020}long\u{0020}as\u{0020}the\u{0020}mission\u{0020}is\u{0020}completed,\u{0020}life—mine\u{0020}or\u{0020}others'—was\u{0020}just\u{0020}a\u{0020}tool.\u{0020}But\u{0020}you...\u{0020}you're\u{0020}different.", "…領航，我一直認為，只要能夠完成任務，無論是別人的性命，亦或是自己的生命，都不過是消耗品。但，唯有您…只有您，是不同的。", "0", "0", "0", "0", "cv_honglei_8", "0", "level4,level4"},
[4101100113] = {4101100113, 11011001, 12, 6, "0", "0", "Yes,\u{0020}I've\u{0020}gotten\u{0020}stronger.", "嗯，我變得更強了。", "0", "0", "0", "0", "cv_honglei_9", "0", "0"},
