[4200000101] = {4200000101, 12000001, 2, 2, "0", "0", "Oh-ho~\u{0020}You've\u{0020}got\u{0020}good\u{0020}taste~", "喔吼~還真是有眼光啊~", "0", "0", "哦吼~还真是有眼光啊~", "0", "cv_kinkura_2", "0", "0"},
[4200000102] = {4200000102, 12000001, 3, 3, "0", "0", "Oh-ho-ho~\u{0020}So,\u{0020}you're\u{0020}Danube's\u{0020}Navigator?\u{0020}Remember\u{0020}my\u{0020}name—it's\u{0020}Kinkura!", "喔吼吼~你就是那個多瑙的領航嗎？聽好了，本小姐的名字是金庫啦，好好記住吧。", "0", "0", "哦吼吼~你就是那个多瑙的领航吗？听好了，本小姐的名字是金库啦，好好记住吧。", "0", "cv_kinkura_1", "0", "0"},
[4200000103] = {4200000103, 12000001, 4, 4, "0", "idle", "The\u{0020}wealthy\u{0020}give\u{0020}money,\u{0020}the\u{0020}strong\u{0020}give\u{0020}strength.\u{0020}For\u{0020}me,\u{0020}money\u{0020}is\u{0020}power!", "富有的人貢獻金錢，強壯的人貢獻力量。當然~對於我來說，金錢就是力量！", "0", "0", "富有的人贡献金钱，强壮的人贡献力量。当然~对于我来说，金钱就是力量！", "0", "cv_kinkura_3", "0", "0"},
[4200000104] = {4200000104, 12000001, 5, 4, "0", "idle", "It's\u{0020}a\u{0020}shame,\u{0020}though.\u{0020}If\u{0020}someone\u{0020}like\u{0020}you\u{0020}joined\u{0020}Danube,\u{0020}we'd\u{0020}bring\u{0020}real\u{0020}change.", "真是可惜啊，像你這樣的人才如果能來九州的話，一定會為我們帶來新的變革吧。", "0", "0", "真是可惜啊，像你这样的人才如果能来九州岛的话，一定会为我们带来新的变革吧。", "0", "cv_kinkura_4", "0", "0"},
[4200000105] = {4200000105, 12000001, 6, 4, "0", "idle", "Danube's\u{0020}Navigator,\u{0020}don't\u{0020}you\u{0020}think\u{0020}Lulula\u{0020}is\u{0020}too\u{0020}naïve?\u{0020}With\u{0020}her\u{0020}kindness,\u{0020}she'll\u{0020}get\u{0020}taken\u{0020}advantage\u{0020}of.\u{0020}Hmm?\u{0020}You\u{0020}think\u{0020}so\u{0020}too?\u{0020}Hey,\u{0020}I\u{0020}called\u{0020}dibs\u{0020}on\u{0020}her\u{0020}first!", "多瑙的領航，你不覺得露露啦太天真了嗎？她那種溫柔的性格，太容易被人利用了。嗯？你也這麼覺得……喂，她可是本小姐先看上的！", "0", "0", "多瑙的领航，你不觉得露露啦太天真了吗？她那种温柔的性格，太容易被人利用了。嗯？你也这么觉得……喂，她可是本小姐先看上的！", "0", "cv_kinkura_29", "0", "0"},
[4200000106] = {4200000106, 12000001, 7, 5, "15_1_0_0.8", "touch1", "Joining\u{0020}this\u{0020}war\u{0020}is\u{0020}just\u{0020}the\u{0020}first\u{0020}step\u{0020}in\u{0020}my\u{0020}plan.\u{0020}Once\u{0020}we're\u{0020}done\u{0020}with\u{0020}Sin,\u{0020}my\u{0020}business\u{0020}empire\u{0020}will\u{0020}be\u{0020}complete,\u{0020}haha!", "加入這場戰爭，不過是本小姐計劃的第一步。與原罪的戰爭結束後，本小姐的商業帝國也就成型了，哼哼哼！", "0", "0", "加入这场战争，不过是本小姐计划的第一步。与原罪的战争结束后，本小姐的商业帝国也就成型了，哼哼哼！", "0", "cv_kinkura_30", "0", "0"},
[4200000107] = {4200000107, 12000001, 8, 5, "15_1_0_0.8", "touch1", "Oh-ho~\u{0020}Are\u{0020}you\u{0020}finally\u{0020}thinking\u{0020}about\u{0020}transferring?\u{0020}Don't\u{0020}worry,\u{0020}with\u{0020}me\u{0020}guiding\u{0020}you,\u{0020}you'll\u{0020}be\u{0020}well\u{0020}taken\u{0020}care\u{0020}of.", "喔吼~難道說你終於打算轉部了嗎？放心好了，只要有本小姐的指示，你的待遇一切從優。", "0", "0", "哦吼~难道说你终于打算转部了吗？放心好了，只要有本小姐的指示，你的待遇一切从优。", "0", "cv_kinkura_5", "0", "0"},
[4200000108] = {4200000108, 12000001, 9, 5, "15_1_0_0.8", "touch1", "Yes,\u{0020}I'm\u{0020}all\u{0020}about\u{0020}results.\u{0020}I'll\u{0020}do\u{0020}whatever\u{0020}it\u{0020}takes\u{0020}to\u{0020}help\u{0020}those\u{0020}in\u{0020}need,\u{0020}whether\u{0020}as\u{0020}a\u{0020}businesswoman\u{0020}or\u{0020}a\u{0020}warrior.", "沒錯，沒錯。本小姐確實是結果主義者，只要能夠幫助到那些有困難的人。我既可以是商人，也可以是戰士。", "0", "0", "没错，没错。本小姐确实是结果主义者，只要能够帮助到那些有困难的人。我既可以是商人，也可以是战士。", "0", "cv_kinkura_6", "0", "0"},
[4200000109] = {4200000109, 12000001, 10, 5, "15_2_0_0.8", "touch2", "My\u{0020}family\u{0020}always\u{0020}said\u{0020}you\u{0020}can't\u{0020}solve\u{0020}everything\u{0020}with\u{0020}money,\u{0020}but\u{0020}I\u{0020}know\u{0020}some\u{0020}problems\u{0020}require\u{0020}it.\u{0020}Like\u{0020}building\u{0020}a\u{0020}shelter\u{0020}for\u{0020}homeless\u{0020}kids—that\u{0020}takes\u{0020}more\u{0020}than\u{0020}strength.", "雖然家裡的長輩曾經教導過我們，不要妄圖使用金錢解決一切問題。但是，我明白，有些事情必須要用金錢來解決……比如說，想要為那些流離失所的孩子們建起一座大廈，光靠力氣是絕對辦不到的。", "0", "0", "虽然家里的长辈曾经教导过我们，不要妄图使用金钱解决一切问题。但是，我明白，有些事情必须要用金钱来解决……比如说，想要为那些流离失所的孩子们建起一座大厦，光靠力气是绝对办不到的。", "0", "cv_kinkura_7", "0", "0"},
[4200000110] = {4200000110, 12000001, 11, 5, "15_2_0_0.8", "touch2", "Priceless\u{0020}things?\u{0020}Sure,\u{0020}there\u{0020}are\u{0020}things\u{0020}money\u{0020}can't\u{0020}buy,\u{0020}like\u{0020}what\u{0020}my\u{0020}grandpa\u{0020}said:\u{0020}trust,\u{0020}love,\u{0020}and\u{0020}connections\u{0020}between\u{0020}people...\u{0020}I\u{0020}think\u{0020}I'm\u{0020}finally\u{0020}starting\u{0020}to\u{0020}get\u{0020}what\u{0020}he\u{0020}meant.", "無價之寶嗎……確實啊，我承認，這個世界上確實存在著無法用金錢衡量的事物。比如爺爺曾經說過的，人和人之間的聯繫，信任，與愛意……究竟從何時起，我好像也能漸漸體會到這其中的含義了。", "0", "0", "无价之宝吗……确实啊，我承认，这个世界上确实存在着无法用金钱衡量的事物。比如爷爷曾经说过的，人和人之间的联系，信任，与爱意……究竟从何时起，我好像也能渐渐体会到这其中的含义了。", "0", "cv_kinkura_8", "0", "0"},
[4200000111] = {4200000111, 12000001, 12, 6, "0", "0", "Looks\u{0020}like\u{0020}my\u{0020}stocks\u{0020}are\u{0020}about\u{0020}to\u{0020}soar.", "看來我的股勢要大漲啦。", "0", "0", "看来我的股势要大涨啦。", "0", "cv_kinkura_9", "0", "0"},
[4200000112] = {4200000112, 12000001, 13, 7, "0", "0", "Oh-ho-ho~\u{0020}That's\u{0020}right,\u{0020}the\u{0020}more\u{0020}you\u{0020}invest,\u{0020}the\u{0020}stronger\u{0020}I\u{0020}become.\u{0020}That's\u{0020}equivalent\u{0020}exchange!", "喔吼吼~沒錯，就是這樣，你投入得越多我的力量也會變得越大。這便是，等價交換！", "0", "0", "哦吼吼~没错，就是这样，你投入得越多我的力量也会变得越大。这便是，等价交换！", "0", "cv_kinkura_10", "0", "0"},
[4200000113] = {4200000113, 12000001, 14, 8, "0", "0", "Did\u{0020}you\u{0020}invest\u{0020}all\u{0020}your\u{0020}savings\u{0020}in\u{0020}me?\u{0020}Are\u{0020}you\u{0020}sure\u{0020}about\u{0020}that?\u{0020}No\u{0020}turning\u{0020}back\u{0020}now!", "將攢到現在的積蓄全部都投在我身上了嗎？這樣真的好嗎？事到如今本小姐可不允許你反悔喔~", "0", "0", "将攒到现在的积蓄全部都投在我身上了吗？这样真的好吗？事到如今本小姐可不允许你反悔哦~", "0", "cv_kinkura_11", "0", "0"},
[4200000114] = {4200000114, 12000001, 15, 9, "0", "0", "Looks\u{0020}like\u{0020}the\u{0020}new\u{0020}shipment's\u{0020}here—just\u{0020}in\u{0020}time\u{0020}for\u{0020}a\u{0020}workout.", "看來新訂的貨到了啊，正好想去活動一下呢。", "0", "0", "看来新订的货到了啊，正好想去活动一下呢。", "0", "cv_kinkura_12", "0", "0"},
