[4200000131] = {4200000131, 12000001, 34, 26, "0", "0", "Too\u{0020}slow.\u{0020}Do\u{0020}you\u{0020}know\u{0020}how\u{0020}long\u{0020}I've\u{0020}been\u{0020}waiting\u{0020}for\u{0020}you?", "太慢了，你以為本小姐等你多久了啊？", "0", "0", "太慢了，你以为本小姐等你多久了啊？", "0", "cv_kinkura_31", "0", "0"},
[4200000132] = {4200000132, 12000001, 35, 27, "0", "0", "Danger\u{0020}is\u{0020}everywhere,\u{0020}and\u{0020}so\u{0020}are\u{0020}business\u{0020}opportunities.\u{0020}Let's\u{0020}go,\u{0020}Danube's\u{0020}Navigator!", "危機四伏之地，處處都是商機。我們出發吧，多瑙的領航！", "0", "0", "危机四伏之地，处处都是商机。我们出发吧，多瑙的领航！", "0", "cv_kinkura_33", "0", "0"},
