[4101700100] = {4101700100, 11017001, 1, 1, "0", "0", "Haze\u{0020}reverb.", "蒼霧殘響（ハツリバーブ）。", "0", "0", "蒼霧殘響。", "0", "cv_sk_fuluola_32", "0", "0"},
[4101700101] = {4101700101, 11017001, 2, 2, "0", "0", "Received,\u{0020}I\u{0020}guarantee\u{0020}I\u{0020}won't\u{0020}disappoint\u{0020}you.", "承知いたしました。あなた様のご期待に応えてみせます。", "0", "0", "收到，芙蘿拉保證不會讓您失望的。", "0", "cv_sk_fuluola_2", "0", "0"},
[4101700102] = {4101700102, 11017001, 3, 3, "0", "0", "Captain\u{0020}of\u{0020}Danube's\u{0020}First\u{0020}Guards\u{0020}Squad,\u{0020}Flora.\u{0020}Eh?\u{0020}You're\u{0020}asking\u{0020}why\u{0020}we\u{0020}wear\u{0020}maid\u{0020}outfits?", "ダニューブ第一親衛班班長、フローラと申します。え？どうして親衛班がメイド服なのか、ですか？", "0", "0", "多瑙第一親衛班隊長，芙蘿拉。哎？您問為什麼親衛隊要穿女僕裝？", "0", "cv_sk_fuluola_1", "0", "0"},
[4101700103] = {4101700103, 11017001, 4, 4, "0", "idle", "Navigator,\u{0020}you've\u{0020}worked\u{0020}so\u{0020}hard\u{0020}all\u{0020}this\u{0020}time.\u{0020}Please\u{0020}have\u{0020}a\u{0020}rest,\u{0020}at\u{0020}least\u{0020}for\u{0020}today.", "方舟の運航は順調です。暫くゆっくりなさってください。そうだ、お茶を淹れましょうか？", "0", "0", "方舟正在平穩地行駛，看來暫時沒有什麼要忙的，要為您泡杯茶嗎？", "0", "cv_sk_fuluola_n1", "0", "0"},
[4101700104] = {4101700104, 11017001, 5, 4, "0", "idle", "Work\u{0020}and\u{0020}missions\u{0020}matter,\u{0020}of\u{0020}course,\u{0020}but\u{0020}you\u{0020}deserve\u{0020}to\u{0020}enjoy\u{0020}your\u{0020}life\u{0020}too,\u{0020}and\u{0020}to\u{0020}make\u{0020}the\u{0020}most\u{0020}of\u{0020}your\u{0020}downtime.", "わたくしの武器で驚かせてしまったでしょうか？申し訳ありません。今すぐ収めます。", "0", "0", "我的武器嚇到您了嗎？很抱歉，現在就收起來。", "0", "cv_sk_fuluola_n2", "0", "0"},
[4101700105] = {4101700105, 11017001, 6, 4, "0", "idle", "I\u{0020}dressed\u{0020}up\u{0020}specially\u{0020}for\u{0020}this\u{0020}occasion,\u{0020}cute\u{0020}enough\u{0020}to\u{0020}rival\u{0020}anyone\u{0020}else,\u{0020}if\u{0020}I\u{0020}may\u{0020}say\u{0020}so.\u{0020}Do\u{0020}you\u{0020}agree?", "わたくしは親衛班の班長として、常に模範とならなければいけません。今度、ユリウスさんにご指導いただこうと思います。", "0", "0", "身為親衛班的隊長，我更應該要起到表率作用。有機會的話，我想要向朱利烏斯小姐請教一下。", "0", "cv_sk_fuluola_n3", "0", "0"},
[4101700106] = {4101700106, 11017001, 7, 5, "15_1_0_0.8", "level1", "Valentine's\u{0020}Day\u{0020}is\u{0020}a\u{0020}day\u{0020}to\u{0020}offer\u{0020}one's\u{0020}pure\u{0020}love,\u{0020}and\u{0020}outshine\u{0020}every\u{0020}rival.\u{0020}As\u{0020}captain\u{0020}of\u{0020}the\u{0020}First\u{0020}Guards\u{0020}Squad,\u{0020}I\u{0020}must\u{0020}be\u{0020}the\u{0020}last\u{0020}one\u{0020}standing.", "第一親衛班の最も重要な任務はダニューブの象徴、方舟を守ることです。また、わたくしたちはダニューブのドライバーの代表として見られることが多いですから、自身のイメージを維持することも非常に重要です。", "0", "0", "第一親衛班的首要任務是確保多瑙的象徵——方舟能夠安全地行駛。當然，我們本身也常常被當做是多瑙駕駛員的代表，所以維持自身形象是非常有必要的。", "0", "cv_sk_fuluola_n4", "0", "0"},
[4101700107] = {4101700107, 11017001, 8, 5, "15_2_0_0.8", "level2", "And\u{0020}it's\u{0020}not\u{0020}just\u{0020}chocolate.\u{0020}I\u{0020}prepared\u{0020}a\u{0020}lot\u{0020}more\u{0020}for\u{0020}this\u{0020}day...\u{0020}candlelight\u{0020}dinner\u{0020}included.\u{0020}Navigator,\u{0020}would\u{0020}you\u{0020}accept\u{0020}my\u{0020}invitation?", "はい。本日の巡迴は終了しました。何なりとお申しつけください。", "0", "0", "嗯，今天的巡視任務已經結束了，隨時聽從您的調遣。", "0", "cv_sk_fuluola_n5", "0", "0"},
[4101700108] = {4101700108, 11017001, 9, 5, "15_1_0_0.8", "level3", "Danube's\u{0020}finest\u{0020}cocoa\u{0020}beans,\u{0020}a\u{0020}filling\u{0020}of\u{0020}seasonal\u{0020}raspberries\u{0020}and\u{0020}black\u{0020}truffle,\u{0020}all\u{0020}made\u{0020}by\u{0020}my\u{0020}own\u{0020}hands.\u{0020}I'm\u{0020}certain\u{0020}this\u{0020}chocolate\u{0020}will\u{0020}conquer\u{0020}your\u{0020}palate...\u{0020}and\u{0020}your\u{0020}heart.", "わたくしの両親ですか？はい。わたくしを育ててくれただけでなく、わたくしの目標でもあります。親衛班の家系で生まれたわたくしは、他の隊員以上に責務を全うしなければなりません。でなければ、皆様の期待を裏切ることになってしまいます。", "0", "0", "我的父母？嗯，她們不光光是養育我的人，同時還是我努力想要成為的人。作為親衛的後代，我必須要做得比其他隊員更好。只有這樣，才不會辜負大家的期待。", "0", "cv_sk_fuluola_n6", "0", "0"},
[4101700109] = {4101700109, 11017001, 10, 5, "15_1_0_0.8", "level4", "Please\u{0020}savor\u{0020}my\u{0020}chocolate\u{0020}carefully,\u{0020}and\u{0020}the\u{0020}time\u{0020}we\u{0020}spend\u{0020}together.", "ユリウスさんとチャリサーさんが羨ましいです。もしわたくしも親衛隊でなければ、彼女たちのようにあなた様と共に戦いたい……。ですがわたくしには為すべきことが、ダニューブの方舟を守るという使命があるのです。", "0", "0", "真是羡慕朱利烏斯和查麗莎小姐啊……如果我不是親衛的話，也想像她們一樣和您並肩作戰。但是，我現在有更重要的東西要去做，守住多瑙的方舟是我的使命……", "0", "cv_sk_fuluola_n7", "0", "0"},
[4101700110] = {4101700110, 11017001, 11, 5, "15_1_0_0.8", "level5", "Just\u{0020}for\u{0020}today,\u{0020}I\u{0020}want\u{0020}to\u{0020}forget\u{0020}I'm\u{0020}a\u{0020}captain,\u{0020}and\u{0020}simply\u{0020}enjoy\u{0020}this\u{0020}special\u{0020}day.", "あなたと共に遠征はできませんが、親衛班であるわたくしだからこそ、できることがあります。ご安心ください。あなた様と仲間の皆様の帰る場所は、わたくしが必ずお守りします。もし疲れたら、いつでも帰ってきてください。いつでもここでお待ちしております。", "0", "0", "雖然無法和您一同遠征，但也有身為親衛的我能做的事。無論您身處何方都還請放心，我一定會守住您和您同伴們的歸所。如果有一天您感到疲憊了也隨時都能回來休息一段時間，我會在這裡等著您的。", "0", "cv_sk_fuluola_n8", "0", "0"},
[4101700111] = {4101700111, 11017001, 11, 5, "15_1_0_0.8", "level6", "Just\u{0020}for\u{0020}today,\u{0020}I\u{0020}want\u{0020}to\u{0020}forget\u{0020}I'm\u{0020}a\u{0020}captain,\u{0020}and\u{0020}simply\u{0020}enjoy\u{0020}this\u{0020}special\u{0020}day.", "あなたと共に遠征はできませんが、親衛班であるわたくしだからこそ、できることがあります。ご安心ください。あなた様と仲間の皆様の帰る場所は、わたくしが必ずお守りします。もし疲れたら、いつでも帰ってきてください。いつでもここでお待ちしております。", "0", "0", "雖然無法和您一同遠征，但也有身為親衛的我能做的事。無論您身處何方都還請放心，我一定會守住您和您同伴們的歸所。如果有一天您感到疲憊了也隨時都能回來休息一段時間，我會在這裡等著您的。", "0", "cv_sk_fuluola_n8", "0", "0"},
[4101700112] = {4101700112, 11017001, 12, 6, "0", "0", "I\u{0020}feel\u{0020}stronger\u{0020}now.", "ふぅ……力が増したようです。", "0", "0", "呼~力氣變大了呢。", "0", "cv_sk_fuluola_9", "0", "0"},
[4101700113] = {4101700113, 11017001, 13, 7, "0", "0", "Everything\u{0020}is\u{0020}for\u{0020}Danube.", "すべてはダニューブのために。", "0", "0", "一切都是為了多瑙。", "0", "cv_sk_fuluola_10", "0", "0"},
[4101700114] = {4101700114, 11017001, 14, 8, "0", "0", "I\u{0020}feel\u{0020}so\u{0020}refreshed...\u{0020}It's\u{0020}like\u{0020}taking\u{0020}a\u{0020}stroll\u{0020}through\u{0020}a\u{0020}spring\u{0020}garden.", "ああ、なんと清らかな……春の庭園にいるかのようです。", "0", "0", "呼啊~神清氣爽……簡直就像是漫步在春天的花園中一樣。", "0", "cv_sk_fuluola_11", "0", "0"},
[4101700115] = {4101700115, 11017001, 15, 9, "0", "0", "Good,\u{0020}let's\u{0020}keep\u{0020}it\u{0020}up.", "いいですね。このまま続けましょう。", "0", "0", "很好，就這樣繼續下去吧。", "0", "cv_sk_fuluola_12", "0", "0"},
[4101700116] = {4101700116, 11017001, 16, 10, "0", "0", "Let's\u{0020}finish\u{0020}them\u{0020}off\u{0020}all\u{0020}at\u{0020}once.", "はい。一気に倒しましょう。", "0", "0", "嗯，一口氣解決它們吧。", "0", "cv_sk_fuluola_13", "0", "0"},
[4101700117] = {4101700117, 11017001, 17, 11, "0", "0", "Thanks\u{0020}to\u{0020}everyone's\u{0020}help,\u{0020}the\u{0020}mission\u{0020}was\u{0020}a\u{0020}success.", "素晴らしい結果です。皆様のお陰ですね。", "0", "0", "多虧大家的協助，此次任務圓滿完成了呢。", "0", "cv_sk_fuluola_14", "0", "0"},
[4101700118] = {4101700118, 11017001, 18, 12, "0", "0", "Mission\u{0020}complete.\u{0020}You're\u{0020}unharmed,\u{0020}right?", "任務完了です。ナビゲーター様、お怪我はありませんか？", "0", "0", "任務完成，領航，您沒有受傷吧？", "0", "cv_sk_fuluola_15", "0", "0"},
[4101700119] = {4101700119, 11017001, 19, 13, "0", "0", "Stop\u{0020}pursuing;\u{0020}preserving\u{0020}our\u{0020}forces\u{0020}is\u{0020}more\u{0020}important\u{0020}than\u{0020}wiping\u{0020}out\u{0020}the\u{0020}enemy.", "追撃はやめましょう、敵の殲滅より、戦力の溫存が大事です。", "0", "0", "放棄追擊吧，比起殲滅敵人，保全戰力才是重要的。", "0", "cv_sk_fuluola_16", "0", "0"},
[4101700120] = {4101700120, 11017001, 20, 14, "0", "0", "Did\u{0020}we\u{0020}fail?\u{0020}We\u{0020}can't\u{0020}let\u{0020}them\u{0020}take\u{0020}the\u{0020}Ark...", "失敗、ですか……。方舟は絶対に守ってみせます。", "0", "0", "失敗了嗎？…方舟絕對不能交給它們……", "0", "cv_sk_fuluola_17", "0", "0"},
[4101700121] = {4101700121, 11017001, 21, 15, "0", "0", "Justice,\u{0020}served.", "ふぅ……", "0", "0", "呼……", "0", "cv_sk_fuluola_n9", "0", "0"},
[4101700122] = {4101700122, 11017001, 23, 16, "0", "0", "Don't\u{0020}you\u{0020}dare\u{0020}ruin\u{0020}this\u{0020}special\u{0020}day.", "一歩たりとも近づけさせません！", "0", "0", "一步，也不會讓你們接近！", "0", "cv_sk_fuluola_n10", "0", "0"},
[4101700123] = {4101700123, 11017001, 24, 17, "0", "0", "Unforgivable.", "ダニューブのために！", "0", "0", "為了多瑙……！", "0", "cv_sk_fuluola_n11", "0", "0"},
[4101700124] = {4101700124, 11017001, 26, 19, "0", "0", "I\u{0020}failed...?", "春の……終わりが……", "0", "0", "春天…已經結束了……", "0", "cv_sk_fuluola_n12", "0", "0"},
[4101700125] = {4101700125, 11017001, 27, 20, "0", "0", "Even\u{0020}though\u{0020}this\u{0020}isn't\u{0020}my\u{0020}first\u{0020}time\u{0020}here,\u{0020}I'm\u{0020}still\u{0020}amazed.\u{0020}The\u{0020}Ark's\u{0020}heat\u{0020}supply\u{0020}system\u{0020}is\u{0020}so\u{0020}advanced.", "何度も來ていますが、やはり感心せざるを得ません。方舟の熱エネルギー供給システムは実に先進的ですね。", "0", "0", "雖然已經不是第一次來這裡了，不過還是不得不令人讚歎啊。方舟上的熱能供給系統，真是先進。", "0", "cv_sk_fuluola_22", "0", "0"},
[4101700126] = {4101700126, 11017001, 28, 21, "0", "0", "Eh?\u{0020}You\u{0020}smelled\u{0020}flowers?\u{0020}Are\u{0020}you\u{0020}joking?", "え？花のような香りがする、って……ご、ご冗談を。", "0", "0", "哎？您聞到了花香？是…是在開玩笑的吧。", "0", "cv_sk_fuluola_23", "0", "0"},
