[403700] = {403700, 10037, 1, 1, "0", "0", "Haze\u{0020}Reverb.", "ハツリバーブ", "0", "0", "0", "0", "cv_zhensusi_01", "0", "0"},
[403701] = {403701, 10037, 2, 2, "0", "0", "You\u{0020}really\u{0020}took\u{0020}me\u{0020}for\u{0020}a\u{0020}guard,\u{0020}huh?", "警備員扱いですか。", "0", "0", "0", "0", "cv_zhensusi_02", "0", "0"},
[403702] = {403702, 10037, 3, 3, "0", "0", "So\u{0020}you\u{0020}are\u{0020}the\u{0020}Navigator?\u{0020}The\u{0020}one\u{0020}who\u{0020}destroyed\u{0020}the\u{0020}universe\u{0020}in\u{0020}your\u{0020}last\u{0020}life?\u{0020}...Just\u{0020}call\u{0020}me\u{0020}Kraz,\u{0020}so\u{0020}you\u{0020}don't\u{0020}confuse\u{0020}me\u{0020}with\u{0020}that\u{0020}redheaded\u{0020}one.", "あなたがナビゲーターですか？あの前世に宇宙を破壊した人……クラズと呼んでください、赤い髪の誰かさんと間違わないようにね。", "0", "0", "0", "0", "cv_zhensusi_03", "0", "0"},
[403703] = {403703, 10037, 4, 4, "0", "idle", "No\u{0020}one\u{0020}expected\u{0020}me\u{0020}to\u{0020}survive,\u{0020}much\u{0020}less\u{0020}stand\u{0020}here\u{0020}today.\u{0020}Honestly,\u{0020}I\u{0020}didn't\u{0020}think\u{0020}I'd\u{0020}ever\u{0020}end\u{0020}up\u{0020}like\u{0020}this\u{0020}either.", "僕が生き延びたことも、ここに立ってることも、彼女たちは想像もしていなかったでしょう……僕もです。", "0", "0", "0", "0", "cv_zhensusi_04", "0", "0"},
[403704] = {403704, 10037, 5, 4, "0", "idle", "Holding\u{0020}up\u{0020}this\u{0020}shield\u{0020}so\u{0020}it\u{0020}doesn't\u{0020}topple\u{0020}is\u{0020}exhausting...\u{0020}Want\u{0020}to\u{0020}give\u{0020}it\u{0020}a\u{0020}try?", "盾を支えるのも結構疲れますよ……なんなら試してみますか？", "0", "0", "0", "0", "cv_zhensusi_05", "0", "0"},
[403705] = {403705, 10037, 6, 4, "0", "idle", "Uh...\u{0020}do\u{0020}you\u{0020}know\u{0020}where\u{0020}I\u{0020}can\u{0020}find\u{0020}a\u{0020}clown?\u{0020}Silver\u{0020}hair,\u{0020}red\u{0020}nose,\u{0020}big\u{0020}painted\u{0020}smile...\u{0020}No\u{0020}red\u{0020}nose\u{0020}or\u{0020}smile?\u{0020}Oh.\u{0020}Maybe\u{0020}I'm\u{0020}mixing\u{0020}them\u{0020}up.", "うーん……ピエロを見かけませんでしたか？白い髪に、赤い鼻、そして大きな笑顔が描かれている人。赤い鼻と笑顔はない？僕が間違えたかもしれません。", "0", "0", "0", "0", "cv_zhensusi_06", "0", "0"},
[403706] = {403706, 10037, 7, 5, "1_》_0_0.8", "level1", "I\u{0020}never\u{0020}planned\u{0020}on\u{0020}revenge,\u{0020}not\u{0020}four\u{0020}years\u{0020}ago,\u{0020}not\u{0020}even\u{0020}earlier.\u{0020}A\u{0020}quiet\u{0020}life\u{0020}was\u{0020}already\u{0020}more\u{0020}than\u{0020}what\u{0020}I\u{0020}asked\u{0020}for.\u{0020}But\u{0020}sometimes\u{0020}something\u{0020}gets\u{0020}stuck\u{0020}in\u{0020}my\u{0020}chest...\u{0020}and\u{0020}I\u{0020}just\u{0020}want\u{0020}to\u{0020}shout\u{0020}into\u{0020}some\u{0020}hollow\u{0020}tree.", "復讐なんて考えたことはありません、四年前も、その前も。穏やかな日々を過ごせたら万々歳です。ただ時には、穴の空いた切り株に胸のモヤモヤを喚き散らしたいです。", "0", "0", "0", "0", "cv_zhensusi_07", "0", "0"},
[403707] = {403707, 10037, 8, 5, "1_》_0_0.8", "level1", "I\u{0020}don't\u{0020}like\u{0020}this\u{0020}hat.\u{0020}Too\u{0020}small,\u{0020}too\u{0020}tight,\u{0020}and\u{0020}it\u{0020}doesn't\u{0020}even\u{0020}hide\u{0020}my\u{0020}face.", "この帽子は好きではありません。小さいしきついし、顔も隠せません。", "0", "0", "0", "0", "cv_zhensusi_08", "0", "0"},
[403708] = {403708, 10037, 9, 5, "1_》_100_1.5", "level2", "After\u{0020}I\u{0020}escaped\u{0020}the\u{0020}research\u{0020}institute,\u{0020}I\u{0020}wanted\u{0020}to\u{0020}leave\u{0020}Inca\u{0020}for\u{0020}good.\u{0020}Yet\u{0020}here\u{0020}I\u{0020}am...\u{0020}standing\u{0020}here\u{0020}as\u{0020}an\u{0020}Inch\u{0020}Branch's\u{0020}Driver.", "研究所から脱出した後、インカという危険な場所から離れたかったのですが、今ここにいられるのはインカに所属するドライバーという肩書きのおかげです。", "0", "0", "0", "0", "cv_zhensusi_09", "0", "0"},
[403709] = {403709, 10037, 10, 5, "1_》_500_2", "level3", "Come\u{0020}swimming\u{0020}with\u{0020}me\u{0020}sometime.\u{0020}I'm\u{0020}a\u{0020}very\u{0020}good\u{0020}swimmer,\u{0020}you\u{0020}know.\u{0020}After\u{0020}all,\u{0020}I\u{0020}learned\u{0020}it\u{0020}with\u{0020}my\u{0020}life\u{0020}on\u{0020}the\u{0020}line.", "時間があるときに一緒に泳ぎに行きませんか？自分の泳ぎには自信があります。命をかけて得た技術ですので。", "0", "0", "0", "0", "cv_zhensusi_10", "0", "0"},
[403710] = {403710, 10037, 11, 5, "1_》_1000_2.5", "level4", "\"Vega,\"\u{0020}\"guard,\"\u{0020}\"Kraz\"...\u{0020}I\u{0020}feel\u{0020}like\u{0020}I've\u{0020}spent\u{0020}my\u{0020}whole\u{0020}life\u{0020}playing\u{0020}roles\u{0020}no\u{0020}one\u{0020}likes.\u{0020}If\u{0020}I\u{0020}could\u{0020}choose\u{0020}for\u{0020}myself...\u{0020}Ah!\u{0020}I\u{0020}want\u{0020}to\u{0020}be\u{0020}your\u{0020}lover.\u{0020}Or\u{0020}your\u{0020}daughter.\u{0020}That\u{0020}works\u{0020}too.", "「ベガ」、「警備員」、「クラズ」、僕はずっと嫌われ役を演じているように感じます。もし僕の好きなように選べるなら……そうですね、あなたの「恋人」になりたいです、もしくは「娘」でも構いません。", "0", "0", "0", "0", "cv_zhensusi_11", "0", "0"},
