[4104200201] = {4104200201, 11042002, 2, 2, "0", "0", "I'm\u{0020}here!\u{0020}You\u{0020}can\u{0020}count\u{0020}on\u{0020}me.\u{0020}I\u{0020}won't\u{0020}make\u{0020}any\u{0020}mistakes,\u{0020}hehe.", "我來啦！把事情都交給我吧，絕對不會出錯的，嘿嘿。", "0", "0", "0", "0", "cv_hailuo_2", "0", "0"},
[4104200202] = {4104200202, 11042002, 3, 3, "0", "0", "I'm\u{0020}Kyla,\u{0020}your\u{0020}frontline\u{0020}fighter!\u{0020}My\u{0020}full\u{0020}name\u{0020}is\u{0020}Kyla\u{0020}Tria@#￥%...\u{0020}Gah,\u{0020}I\u{0020}can't\u{0020}recall\u{0020}it…\u{0020}Just\u{0020}call\u{0020}me\u{0020}Kyla!", "我是前線的海蘿！海蘿·特裡亞@#￥%……記不得啦，總之叫我海蘿就好！", "0", "0", "0", "0", "cv_hailuo_3", "0", "0"},
[4104200203] = {4104200203, 11042002, 91, 4, "0", "idle", "When\u{0020}feeling\u{0020}down,\u{0020}just\u{0020}go\u{0020}for\u{0020}a\u{0020}run!\u{0020}Sunlight\u{0020}on\u{0020}your\u{0020}body,\u{0020}wind\u{0020}on\u{0020}your\u{0020}face,\u{0020}and\u{0020}you'll\u{0020}forget\u{0020}all\u{0020}your\u{0020}worries!", "不開心的時候只要去跑步就好了！陽光照在身上，風打在臉上，什麼煩惱都會忘了！", "0", "0", "0", "0", "cv_hailuo_4", "0", "idle,idle"},
[4104200204] = {4104200204, 11042002, 94, 4, "0", "idle2", "This\u{0020}is\u{0020}what\u{0020}we\u{0020}need\u{0020}to\u{0020}do\u{0020}today...\u{0020}This\u{0020}is\u{0020}what\u{0020}we\u{0020}need\u{0020}to\u{0020}do\u{0020}tomorrow...\u{0020}OK,\u{0020}I've\u{0020}written\u{0020}it\u{0020}all\u{0020}down...\u{0020}Hmm,\u{0020}by\u{0020}the\u{0020}way,\u{0020}what\u{0020}day\u{0020}is\u{0020}it\u{0020}today...\u{0020}Ah!\u{0020}I\u{0020}missed\u{0020}everything!", "這是今天要做的事情……這是明天要做的事情……OK，已經全部記下來了……嗯，話說今天是幾號……啊！這不是全部錯過了嗎！", "0", "0", "0", "0", "cv_hailuo_5", "0", "idle2,idle2"},
[4104200205] = {4104200205, 11042002, 98, 4, "0", "idle3", "Starry...\u{0020}she\u{0020}really\u{0020}worries\u{0020}me...\u{0020}Oh,\u{0020}I'm\u{0020}not\u{0020}talking\u{0020}about\u{0020}her\u{0020}appearance,\u{0020}it's\u{0020}her\u{0020}mental\u{0020}state.\u{0020}It\u{0020}feels\u{0020}like\u{0020}she\u{0020}could\u{0020}explode\u{0020}at\u{0020}any\u{0020}moment...\u{0020}Bang!\u{0020}Splat!\u{0020}I'm\u{0020}really\u{0020}worried\u{0020}about\u{0020}her.", "星爍……她那樣子真讓人擔心……啊，我不是說她的外表，是說她的精神狀態，總感覺她好像隨時都會爆炸一樣……彭！啪嗒！我很擔心她。", "0", "0", "0", "0", "cv_hailuo_6", "0", "idle3,idle3"},
[4104200206] = {4104200206, 11042002, 92, 5, "1_》_0_0.8", "level1", "I\u{0020}don't\u{0020}have\u{0020}anything\u{0020}I\u{0020}want\u{0020}to\u{0020}achieve.\u{0020}Even\u{0020}if\u{0020}I\u{0020}did,\u{0020}I'd\u{0020}probably\u{0020}forget\u{0020}it\u{0020}soon.\u{0020}But\u{0020}I'll\u{0020}work\u{0020}hard\u{0020}to\u{0020}help\u{0020}others\u{0020}achieve\u{0020}their\u{0020}dreams,\u{0020}and\u{0020}I\u{0020}don't\u{0020}mind\u{0020}fighting\u{0020}for\u{0020}that\u{0020}as\u{0020}long\u{0020}as\u{0020}it\u{0020}takes!", "我沒有想要實現的事情，就算有也肯定很快就忘記吧，但是我會努力幫其他人實現夢想的，為此就算一直戰鬥下去也沒關係！", "0", "0", "0", "0", "cv_hailuo_7", "0", "level1,level1"},
[4104200207] = {4104200207, 11042002, 95, 5, "1_》_0_0.8", "level2", "Navigator,\u{0020}important\u{0020}promises\u{0020}should\u{0020}be\u{0020}written\u{0020}down\u{0020}because\u{0020}human\u{0020}memory\u{0020}is\u{0020}unreliable!", "領航，重要的約定一定要寫在紙上，因為人的記憶是不可靠的！", "0", "0", "0", "0", "cv_hailuo_8", "0", "level2,level2"},
[4104200208] = {4104200208, 11042002, 106, 5, "1_》_0_0.8", "level3", "It\u{0020}doesn't\u{0020}matter\u{0020}if\u{0020}I\u{0020}can't\u{0020}remember\u{0020}the\u{0020}names\u{0020}of\u{0020}important\u{0020}people\u{0020}because\u{0020}the\u{0020}feelings\u{0020}and\u{0020}memories\u{0020}will\u{0020}always\u{0020}remain\u{0020}in\u{0020}our\u{0020}hearts,\u{0020}mine\u{0020}and\u{0020}yours,\u{0020}Navigator!", "即使記不住重要的人的名字也沒關係，因為那份感情和回憶一直會存在我和領航的心裡的！", "0", "0", "0", "0", "cv_hailuo_9", "0", "level3,level3"},
[4104200209] = {4104200209, 11042002, 93, 5, "1_》_0_0.8", "switch1", "Have\u{0020}you\u{0020}ever\u{0020}lost\u{0020}your\u{0020}memory,\u{0020}Navigator?\u{0020}I\u{0020}understand\u{0020}that\u{0020}feeling—it's\u{0020}awful\u{0020}not\u{0020}to\u{0020}remember\u{0020}important\u{0020}things.\u{0020}But\u{0020}as\u{0020}long\u{0020}as\u{0020}we're\u{0020}alive,\u{0020}moving\u{0020}toward\u{0020}the\u{0020}future,\u{0020}we'll\u{0020}eventually\u{0020}recover\u{0020}what\u{0020}we've\u{0020}forgotten!", "領航也失憶過嗎？我懂的我懂的，那種想不起來重要事情的感覺特別難受吧。不過只要我們還活著，還能向著未來前進，我們總能找回當初忘掉的事情的！", "0", "0", "0", "0", "cv_hailuo_10", "0", "switch1,switch1"},
[4104200210] = {4104200210, 11042002, 102, 5, "1_》_0_0.8", "switch2", "Have\u{0020}you\u{0020}ever\u{0020}lost\u{0020}your\u{0020}memory,\u{0020}Navigator?\u{0020}I\u{0020}understand\u{0020}that\u{0020}feeling—it's\u{0020}awful\u{0020}not\u{0020}to\u{0020}remember\u{0020}important\u{0020}things.\u{0020}But\u{0020}as\u{0020}long\u{0020}as\u{0020}we're\u{0020}alive,\u{0020}moving\u{0020}toward\u{0020}the\u{0020}future,\u{0020}we'll\u{0020}eventually\u{0020}recover\u{0020}what\u{0020}we've\u{0020}forgotten!", "領航也失憶過嗎？我懂的我懂的，那種想不起來重要事情的感覺特別難受吧。不過只要我們還活著，還能向著未來前進，我們總能找回當初忘掉的事情的！", "0", "0", "0", "0", "cv_hailuo_10", "0", "switch2,switch2"},
[4104200211] = {4104200211, 11042002, 96, 5, "1_》_0_0.8", "switch3", "As\u{0020}a\u{0020}fellow\u{0020}forgetful\u{0020}person,\u{0020}Navigator,\u{0020}if\u{0020}you\u{0020}ever\u{0020}have\u{0020}any\u{0020}troubles,\u{0020}feel\u{0020}free\u{0020}to\u{0020}talk\u{0020}to\u{0020}me.\u{0020}I'll\u{0020}always\u{0020}be\u{0020}there\u{0020}for\u{0020}you,\u{0020}even\u{0020}when\u{0020}I'm\u{0020}asleep!\u{0020}Even\u{0020}in\u{0020}the\u{0020}bath...\u{0020}I\u{0020}don't\u{0020}mind!", "哼哼，作為記性不好的病友，領航要是遇到了什麼困擾就儘管和我傾訴吧，我不管什麼時候都會陪伴你在身邊的，就算是睡覺時候也會的！洗澡的時候……我不介意！", "0", "0", "0", "0", "cv_hailuo_11", "0", "switch3,switch3"},
