[4101900101] = {4101900101, 11019001, 2, 2, "0", "0", "Driver\u{0020}Tenten,\u{0020}ready\u{0020}for\u{0020}duty!\u{0020}Hehe!", "0", "0", "駕駛員天天，保證完成任務！嘻嘻！", "驾驶员天天，保证完成任务！嘻嘻！", "0", "cv_tenten_2", "0", "0"},
[4101900102] = {4101900102, 11019001, 3, 3, "0", "0", "Ta-da!\u{0020}Tenten\u{0020}from\u{0020}the\u{0020}Fledgeling\u{0020}Eagle\u{0020}Team\u{0020}reporting!\u{0020}Are\u{0020}you\u{0020}the\u{0020}Navigator?\u{0020}Here,\u{0020}have\u{0020}a\u{0020}cake\u{0020}I\u{0020}made!", "0", "0", "鏘鏘！雛鷹小隊成員天天報導！你就是領航嗎？來吃一個我親手做的蛋糕吧！", "锵锵！雏鹰小队成员天天报导！你就是领航吗？来吃一个我亲手做的蛋糕吧！", "0", "cv_tenten_1", "0", "0"},
[4101900103] = {4101900103, 11019001, 91, 4, "0", "idle", "Navigator!\u{0020}Time\u{0020}to\u{0020}eat!\u{0020}I'll\u{0020}make\u{0020}you\u{0020}some\u{0020}hamburger\u{0020}steak!", "0", "0", "領航！到飯點了，天天給你做漢堡肉吃吧！", "领航！到饭点了，天天给你做汉堡肉吃吧！", "0", "cv_tenten_3", "0", "idle,idle"},
[4101900104] = {4101900104, 11019001, 91, 4, "0", "idle", "Don't\u{0020}like\u{0020}veggies?\u{0020}Picky\u{0020}eaters\u{0020}aren't\u{0020}good\u{0020}kids,\u{0020}Navigator,\u{0020}so\u{0020}finish\u{0020}those\u{0020}greens!", "0", "0", "不喜歡吃蔬菜嗎？挑食的孩子可不是好孩子，領航可要好好吃完這些青菜喔！", "不喜欢吃蔬菜吗？挑食的孩子可不是好孩子，领航可要好好吃完这些青菜哦！", "0", "cv_tenten_4", "0", "idle,idle"},
[4101900105] = {4101900105, 11019001, 91, 4, "0", "idle", "Navigator,\u{0020}you\u{0020}can\u{0020}command\u{0020}us\u{0020}more\u{0020}confidently.\u{0020}Don't\u{0020}worry\u{0020}about\u{0020}me\u{0020}being\u{0020}a\u{0020}Fledgeling\u{0020}Eagle\u{0020}trainee.\u{0020}One\u{0020}day,\u{0020}I'll\u{0020}fight\u{0020}the\u{0020}Sin\u{0020}too.", "0", "0", "領航，請更放心地指揮我們吧，不用顧慮雛鷹小隊實習生的身份。既然成了駕駛員，總有一天要和原罪戰鬥的。", "领航，请更放心地指挥我们吧，不用顾虑雏鹰小队实习生的身份。既然成了驾驶员，总有一天要和原罪战斗的。", "0", "cv_tenten_28", "0", "idle,idle"},
[4101900106] = {4101900106, 11019001, 92, 5, "15_1_0_0.8", "touch1", "If\u{0020}we\u{0020}had\u{0020}more\u{0020}ingredients,\u{0020}I\u{0020}could\u{0020}make\u{0020}something\u{0020}new\u{0020}for\u{0020}you\u{0020}every\u{0020}day!", "0", "0", "要是有更多的食材就好了，天天就可以給領航每天都做不同好吃的了！", "要是有更多的食材就好了，天天就可以给领航每天都做不同好吃的了！", "0", "cv_tenten_29", "0", "touch1,touch1"},
[4101900107] = {4101900107, 11019001, 92, 5, "15_1_0_0.8", "touch1", "Don't\u{0020}pat\u{0020}me\u{0020}on\u{0020}the\u{0020}head\u{0020}like\u{0020}a\u{0020}kid,\u{0020}or\u{0020}I'll\u{0020}bite\u{0020}you!", "0", "0", "不要把我當成小孩子一樣摸我的頭啦，咬你！", "不要把我当成小孩子一样摸我的头啦，咬你！", "0", "cv_tenten_5", "0", "touch1,touch1"},
[4101900108] = {4101900108, 11019001, 92, 5, "15_2_0_0.8", "touch2", "Hehe,\u{0020}mission\u{0020}accomplished\u{0020}perfectly\u{0020}again\u{0020}today,\u{0020}Navigator!\u{0020}Let's\u{0020}have\u{0020}a\u{0020}big\u{0020}dinner\u{0020}tonight!", "0", "0", "嘿嘿，天天今天也完美完成任務了呢，領航！晚上來做一頓大餐吧！", "嘿嘿，天天今天也完美完成任务了呢，领航！晚上来做一顿大餐吧！", "0", "cv_tenten_6", "0", "touch2,touch2"},
[4101900109] = {4101900109, 11019001, 92, 5, "15_2_0_0.8", "touch2", "My\u{0020}dad\u{0020}taught\u{0020}me\u{0020}how\u{0020}to\u{0020}cook.\u{0020}He\u{0020}used\u{0020}to\u{0020}say,\u{0020}\"The\u{0020}happiest\u{0020}chefs\u{0020}are\u{0020}the\u{0020}ones\u{0020}whose\u{0020}guests\u{0020}eat\u{0020}with\u{0020}a\u{0020}smile.\"\u{0020}I\u{0020}feel\u{0020}happy\u{0020}being\u{0020}with\u{0020}you,\u{0020}Navigator.", "0", "0", "我的料理都是我爸爸教我的，他曾經告訴我“只要食客吃得開心，就是廚師最大的幸福”，和領航在一起天天也感覺很幸福喔。", "我的料理都是我爸爸教我的，他曾经告诉我“只要食客吃得开心，就是厨师最大的幸福”，和领航在一起天天也感觉很幸福哦。", "0", "cv_tenten_7", "0", "touch2,touch2"},
[4101900110] = {4101900110, 11019001, 92, 5, "15_2_0_0.8", "touch2", "My\u{0020}dad\u{0020}taught\u{0020}me\u{0020}a\u{0020}special\u{0020}dish.\u{0020}My\u{0020}mom\u{0020}married\u{0020}him\u{0020}after\u{0020}she\u{0020}tasted\u{0020}it.\u{0020}Huh?\u{0020}You\u{0020}want\u{0020}to\u{0020}try\u{0020}it?\u{0020}No\u{0020}way!\u{0020}Wait...\u{0020}maybe...\u{0020}but\u{0020}you'll\u{0020}have\u{0020}to\u{0020}take\u{0020}responsibility!", "0", "0", "爸爸教過我一道特殊的料理，當年我的媽媽就是嘗了這道料理才和我爸爸結婚的。欸，領航你想嘗嘗這道料理？不行!不行!爸爸說過這料理只能做給……倒也不是不行啦，不過吃完領航可要負責喔！", "爸爸教过我一道特殊的料理，当年我的妈妈就是尝了这道料理才和我爸爸结婚的。诶，领航你想尝尝这道料理？不行!不行!爸爸说过这料理只能做给……倒也不是不行啦，不过吃完领航可要负责哦！", "0", "cv_tenten_8", "0", "touch2,touch2"},
[4101900111] = {4101900111, 11019001, 12, 6, "0", "0", "I\u{0020}think\u{0020}I've\u{0020}grown\u{0020}taller!", "0", "0", "感覺又長高了呢！", "感觉又长高了呢！", "0", "cv_tenten_9", "0", "0"},
