[4001700102] = {4001700102, 10017001, 3, 3, "0", "0", "Rosalind\u{0020}Rothschild,\u{0020}eldest\u{0020}daughter\u{0020}of\u{0020}the\u{0020}Rothschild\u{0020}family,\u{0020}at\u{0020}your\u{0020}service.\u{0020}So,\u{0020}you're\u{0020}the\u{0020}Navigator\u{0020}for\u{0020}this\u{0020}mission?", "0", "0", "0", "“羅斯柴德”家族長女——羅莎琳德覲見。您就是這次行動的領航嗎？", "0", "cv_sk_rosalind_1", "0", "0"},
[4001700103] = {4001700103, 10017001, 91, 4, "0", "idle", "I...\u{0020}I\u{0020}actually\u{0020}lost...?!", "0", "0", "0", "這裡的裝潢雖然不及家族內的裝飾，但是也算是別有風格。", "0", "cv_sk_rosalind_n01", "0", "0,idle"},
[4001700104] = {4001700104, 10017001, 94, 4, "0", "idle2", "N-Navigator,\u{0020}you're\u{0020}not\u{0020}interested\u{0020}in\u{0020}torn-up\u{0020}clothes,\u{0020}are\u{0020}you?!", "0", "0", "0", "不要因為本小姐是貴族就小瞧我的實力，下次任務本小姐來擔任前鋒。", "0", "cv_sk_rosalind_n02", "0", "0,idle2"},
[4001700105] = {4001700105, 10017001, 98, 4, "0", "idle3", "No,\u{0020}I\u{0020}can't\u{0020}take\u{0020}off\u{0020}any\u{0020}more!\u{0020}That's\u{0020}it!\u{0020}I'm\u{0020}done!\u{0020}I'm\u{0020}quitting\u{0020}for\u{0020}good!", "0", "0", "0", "與原罪戰鬥當然會害怕啦，但是本小姐的貴族血統可不允許害怕。作為前線小隊的成員每一次任務都是在用生命進行戰鬥，這點本小姐早就已經有覺悟了。", "0", "cv_sk_rosalind_n03", "0", "0,idle3"},
[4001700106] = {4001700106, 10017001, 92, 5, "14_1_0_0.8", "level1", "Ngh----!\u{0020}J-just\u{0020}kill\u{0020}me\u{0020}instead!", "0", "0", "0", "參加前線小隊完全是本小姐自己的意願，當然我家族那塊是必須瞞著的，要是被爸媽知道我在做這麼危險的事……所以，一定要保護好本小姐哦，領航！", "0", "cv_sk_rosalind_n04", "0", "0,level1"},
[4001700107] = {4001700107, 10017001, 95, 5, "14_1_0_0.8", "level2", "I-I\u{0020}accept\u{0020}my\u{0020}loss...\u{0020}a\u{0020}bet\u{0020}is\u{0020}a\u{0020}bet...", "0", "0", "0", "本小姐可是貴族，就算是領航也不可肆意輕薄。", "0", "cv_sk_rosalind_n05", "0", "0,level2"},
[4001700108] = {4001700108, 10017001, 99, 5, "14_1_0_0.8", "level3", "J-just\u{0020}you\u{0020}remember\u{0020}this...!\u{0020}You've\u{0020}disgraced\u{0020}a\u{0020}noble's\u{0020}dignity!\u{0020}I...I'll\u{0020}get\u{0020}my\u{0020}revenge!", "0", "0", "0", "本小姐的家族有著千年的歷史，是瑪雅地區老牌的貴族之一……嗯？網路上搜索不到？這…這是因為家族內有規矩，不會隨便出現在世人面前。", "0", "cv_sk_rosalind_n06", "0", "0,level3"},
[4001700109] = {4001700109, 10017001, 93, 5, "14_2_0_0.8", "livel1-2", "Ngh...\u{0020}keep\u{0020}going...!\u{0020}I\u{0020}refuse\u{0020}to\u{0020}believe\u{0020}it!", "0", "0", "0", "話說駕駛員巨大化後穿著的裝甲值不少錢吧，如果拿去賣了——呃啊啊，領航你怎麼在這？本小姐剛才什麼都沒說！你也什麼都沒聽到！", "0", "cv_sk_rosalind_n07", "0", "0,livel1-2"},
[4001700110] = {4001700110, 10017001, 96, 5, "14_2_0_0.8", "livel2-3", "I\u{0020}lost\u{0020}again?!\u{0020}...Do\u{0020}I\u{0020}still\u{0020}have\u{0020}to\u{0020}keep\u{0020}taking\u{0020}things\u{0020}off...?!", "0", "0", "0", "領航，雖然你與本小姐之間身份懸殊，但是…也並非沒有機會。如果說你願意的話，我回去請示一下父母……誒？領航……怎麼偏偏這時候睡著了啊。", "0", "cv_sk_rosalind_n08", "0", "0,livel2-3"},
