[4001700137] = {4001700137, 10017001, 39, 31, "0", "0", "Nice\u{0020}equipment,\u{0020}but\u{0020}it's\u{0020}still\u{0020}no\u{0020}match\u{0020}for\u{0020}mine.", "0", "0", "0", "今天的特惠是……咳，隨便挑吧。", "0", "cv_sk_rosalind_37", "0", "0"},
[4001700138] = {4001700138, 10017001, 40, 32, "0", "0", "Today's\u{0020}special\u{0020}offer\u{0020}is...\u{0020}Cough,\u{0020}just\u{0020}pick\u{0020}whatever\u{0020}you\u{0020}want.", "0", "0", "0", "領航來自多瑙……啊！你不會是真正的貴族吧？", "0", "cv_sk_rosalind_38", "0", "0"},
