[4201500123] = {4201500123, 12015001, 22, 38, "0", "0", "Not\u{0020}yet.", "0", "0", "0", "還不是時候。", "0", "cv_vicepearl_18", "0", "0"},
[4201500124] = {4201500124, 12015001, 26, 19, "0", "0", "Ah...\u{0020}I\u{0020}think\u{0020}I\u{0020}can\u{0020}hear\u{0020}the\u{0020}waves\u{0020}of\u{0020}Danube.", "0", "0", "0", "啊…我似乎聽到了……多瑙的浪聲。", "0", "cv_vicepearl_21", "0", "0"},
[4201500125] = {4201500125, 12015001, 27, 20, "0", "0", "Even\u{0020}a\u{0020}great\u{0020}Navigator\u{0020}serves\u{0020}others\u{0020}sometimes,\u{0020}huh?\u{0020}Just\u{0020}kidding,\u{0020}I'm\u{0020}not\u{0020}one\u{0020}to\u{0020}say\u{0020}that.", "0", "0", "0", "堂堂領航也有侍奉他人的時候嗎？嘿嘿嘿，開玩笑的，我可沒資格說這話呢。", "0", "cv_vicepearl_23", "0", "0"},
[4201500126] = {4201500126, 12015001, 28, 21, "0", "0", "Compared\u{0020}to\u{0020}the\u{0020}bath\u{0020}at\u{0020}home,\u{0020}this\u{0020}place\u{0020}feels\u{0020}a\u{0020}bit\u{0020}small.", "0", "0", "0", "和家裏的浴池相比，這裏果然還是太過狹小了啊。", "0", "cv_vicepearl_24", "0", "0"},
[4201500127] = {4201500127, 12015001, 29, 21, "0", "0", "Looks\u{0020}like\u{0020}I'll\u{0020}need\u{0020}to\u{0020}ask\u{0020}my\u{0020}father\u{0020}to\u{0020}renovate\u{0020}this\u{0020}place.", "0", "0", "0", "看來得讓父親把這裏再修繕一番了。", "0", "cv_vicepearl_25", "0", "0"},
