[415200] = {415200, 11052, 1, 1, "0", "0", "Haze\u{0020}Reverb", "苍雾残响", "0", "0", "0", "0", "cv_sps_001", "0", "0"},
[415201] = {415201, 11052, 2, 2, "0", "0", "After\u{0020}all,\u{0020}I\u{0020}am\u{0020}the\u{0020}hero.\u{0020}It\u{0020}is\u{0020}only\u{0020}natural\u{0020}for\u{0020}people\u{0020}to\u{0020}rely\u{0020}on\u{0020}me,\u{0020}so\u{0020}leave\u{0020}the\u{0020}escort\u{0020}work\u{0020}to\u{0020}me.", "毕竟我是勇者，被人依靠是当然的，护卫工作就交给我吧。", "0", "0", "0", "0", "cv_sps_002", "0", "0"},
[415202] = {415202, 11052, 3, 3, "0", "0", "I\u{0020}am\u{0020}Spes,\u{0020}the\u{0020}savior\u{0020}of\u{0020}the\u{0020}future,\u{0020}humanity's\u{0020}last\u{0020}hope,\u{0020}and\u{0020}the\u{0020}hero\u{0020}destined\u{0020}to\u{0020}save\u{0020}the\u{0020}world.\u{0020}Got\u{0020}that\u{0020}memorized?", "我是斯珀丝，未来的救世主，人类最后的希望，注定要拯救世界的勇者，记清楚了吗？", "0", "0", "0", "0", "cv_sps_003", "0", "0"},
[415203] = {415203, 11052, 4, 4, "0", "idle", "After\u{0020}I\u{0020}save\u{0020}the\u{0020}world,\u{0020}the\u{0020}name\u{0020}\"Spes\"\u{0020}will\u{0020}definitely\u{0020}spread\u{0020}across\u{0020}the\u{0020}entire\u{0020}world.\u{0020}When\u{0020}that\u{0020}time\u{0020}comes,\u{0020}everyone\u{0020}will\u{0020}praise\u{0020}me,\u{0020}worship\u{0020}me,\u{0020}and\u{0020}remember\u{0020}me\u{0020}forever.\u{0020}Hehe.", "等我拯救世界之后，“斯珀丝”这个名字一定会传遍全世界，到时候人人都会赞颂我，崇拜我，永远记得我，嘿嘿。", "0", "0", "0", "0", "cv_sps_004", "0", "0"},
[415204] = {415204, 11052, 5, 4, "0", "idle", "The\u{0020}length\u{0020}of\u{0020}life\u{0020}is\u{0020}already\u{0020}decided\u{0020}at\u{0020}birth,\u{0020}so\u{0020}I\u{0020}will\u{0020}extend\u{0020}its\u{0020}width\u{0020}and\u{0020}height\u{0020}in\u{0020}my\u{0020}own\u{0020}way.", "生命的长度在出生之时就已经被定好，所以，我会在用自己的方式去延伸自己的宽度与高度。", "0", "0", "0", "0", "cv_sps_005", "0", "0"},
[415205] = {415205, 11052, 6, 4, "0", "idle", "No\u{0020}one\u{0020}ever\u{0020}decided\u{0020}how\u{0020}many\u{0020}members\u{0020}a\u{0020}hero's\u{0020}party\u{0020}needs,\u{0020}so\u{0020}a\u{0020}hero's\u{0020}party\u{0020}with\u{0020}only\u{0020}you\u{0020}and\u{0020}me\u{0020}is\u{0020}perfectly\u{0020}valid.\u{0020}After\u{0020}all,\u{0020}with\u{0020}just\u{0020}you\u{0020}and\u{0020}me,\u{0020}saving\u{0020}the\u{0020}world\u{0020}will\u{0020}be\u{0020}more\u{0020}than\u{0020}easy\u{0020}enough.", "没人规定过勇者小队的成员数量，所以仅有你和我的勇者小队也是成立的——毕竟，光靠我和你，拯救世界也绰绰有馀了。", "0", "0", "0", "0", "cv_sps_006", "0", "0"},
[415206] = {415206, 11052, 7, 5, "1_》_0_0.8", "level1", "In\u{0020}my\u{0020}memory,\u{0020}this\u{0020}world\u{0020}has\u{0020}always\u{0020}been\u{0020}like\u{0020}this,\u{0020}broken\u{0020}and\u{0020}falling\u{0020}apart,\u{0020}and\u{0020}it\u{0020}would\u{0020}not\u{0020}be\u{0020}strange\u{0020}if\u{0020}it\u{0020}were\u{0020}destroyed\u{0020}at\u{0020}any\u{0020}moment.\u{0020}I\u{0020}know\u{0020}it\u{0020}must\u{0020}be\u{0020}waiting\u{0020}for\u{0020}a\u{0020}hero\u{0020}to\u{0020}appear\u{0020}and\u{0020}restore\u{0020}it\u{0020}to\u{0020}the\u{0020}way\u{0020}it\u{0020}used\u{0020}to\u{0020}be.\u{0020}Without\u{0020}a\u{0020}doubt,\u{0020}that\u{0020}person\u{0020}is\u{0020}me.", "在我的印象里，这个世界一直都是这样，破破烂烂的，什么时候毁灭也不奇怪。我知道，它一定是在等待一个勇者出现，将它恢复成以前的模样——毫无疑问，那个人就是我。", "0", "0", "0", "0", "cv_sps_007", "0", "0"},
[415207] = {415207, 11052, 8, 5, "1_》_0_0.8", "level1", "How\u{0020}many\u{0020}people\u{0020}used\u{0020}to\u{0020}live\u{0020}on\u{0020}this\u{0020}planet?\u{0020}Billions?\u{0020}Seriously?\u{0020}You\u{0020}are\u{0020}not\u{0020}just\u{0020}trying\u{0020}to\u{0020}humor\u{0020}me,\u{0020}are\u{0020}you?\u{0020}That\u{0020}number...\u{0020}Just\u{0020}hearing\u{0020}it\u{0020}is\u{0020}enough\u{0020}to\u{0020}make\u{0020}me\u{0020}feel\u{0020}suffocated.", "这颗星球以前有多少人啊？几十亿？真的假的，你不会在哄我吧？这个数字……光是听著就要窒息了。", "0", "0", "0", "0", "cv_sps_008", "0", "0"},
[415208] = {415208, 11052, 9, 5, "1_》_100_1.5", "level2", "You\u{0020}must\u{0020}have\u{0020}been\u{0020}a\u{0020}womanizing\u{0020}bad\u{0020}man\u{0020}in\u{0020}the\u{0020}past.\u{0020}Otherwise,\u{0020}why\u{0020}would\u{0020}so\u{0020}many\u{0020}people\u{0020}be\u{0020}staring\u{0020}at\u{0020}you...?\u{0020}No\u{0020}matter\u{0020}what\u{0020}kind\u{0020}of\u{0020}relationship\u{0020}you\u{0020}had\u{0020}with\u{0020}them\u{0020}before,\u{0020}you\u{0020}are\u{0020}my\u{0020}Companion\u{0020}No.\u{0020}1\u{0020}now.\u{0020}You\u{0020}belong\u{0020}to\u{0020}me.\u{0020}Is\u{0020}that\u{0020}clear?", "你以前一定是个拈花惹草的坏男人，不然怎么会有那么多人盯著你……不管你以前和她们什么关系，现在都是我的一号同伴，你是我的人，清楚了吗？", "0", "0", "0", "0", "cv_sps_009", "0", "0"},
[415209] = {415209, 11052, 10, 5, "1_》_500_2", "level3", "Humanity's\u{0020}greatest\u{0020}fear\u{0020}is\u{0020}death,\u{0020}but\u{0020}what\u{0020}is\u{0020}even\u{0020}more\u{0020}terrifying\u{0020}than\u{0020}death\u{0020}is\u{0020}being\u{0020}forgotten...\u{0020}I\u{0020}will\u{0020}make\u{0020}sure\u{0020}everyone\u{0020}I\u{0020}meet\u{0020}on\u{0020}my\u{0020}journey\u{0020}remembers\u{0020}me.\u{0020}That\u{0020}is\u{0020}also\u{0020}the\u{0020}meaning\u{0020}of\u{0020}traveling.", "人最大的恐惧是死亡，但比死亡更让人恐惧的是被遗忘……我会让旅途中遇到的每个人都记住我，这也是旅行的意义。", "0", "0", "0", "0", "cv_sps_010", "0", "0"},
[415210] = {415210, 11052, 11, 5, "1_》_1000_2.5", "level4", "I\u{0020}cannot\u{0020}decide\u{0020}why\u{0020}I\u{0020}was\u{0020}born,\u{0020}nor\u{0020}can\u{0020}I\u{0020}decide\u{0020}why\u{0020}I\u{0020}will\u{0020}die.\u{0020}So,\u{0020}consider\u{0020}this\u{0020}my\u{0020}revenge\u{0020}against\u{0020}fate.\u{0020}I\u{0020}will\u{0020}make\u{0020}you\u{0020}remember\u{0020}me\u{0020}for\u{0020}the\u{0020}rest\u{0020}of\u{0020}your\u{0020}life,\u{0020}so\u{0020}deeply\u{0020}that\u{0020}you\u{0020}could\u{0020}never\u{0020}forget\u{0020}me\u{0020}even\u{0020}if\u{0020}you\u{0020}tried.\u{0020}This\u{0020}is\u{0020}the\u{0020}curse\u{0020}I\u{0020}place\u{0020}on\u{0020}you,\u{0020}Navigator.", "我不能决定自己为什么而生，也无法决定自己为什么而死——所以，就当是我对命运的报复吧，我会让你一辈子都记住我，想忘也忘不掉我的。这是我对你下的诅咒，领航。", "0", "0", "0", "0", "cv_sps_011", "0", "0"},
[415211] = {415211, 11052, 12, 6, "0", "0", "It\u{0020}would\u{0020}be\u{0020}nice\u{0020}if\u{0020}I\u{0020}could\u{0020}level\u{0020}up\u{0020}with\u{0020}a\u{0020}command.", "要是能用指令升级就好了。", "0", "0", "0", "0", "cv_sps_012", "0", "0"},
[415212] = {415212, 11052, 13, 7, "0", "0", "Have\u{0020}I\u{0020}already\u{0020}reached\u{0020}the\u{0020}limit?", "已经到上限了吗？", "0", "0", "0", "0", "cv_sps_013", "0", "0"},
[415213] = {415213, 11052, 14, 8, "0", "0", "A\u{0020}growth-type\u{0020}hero\u{0020}has\u{0020}no\u{0020}limits.", "成长系的勇者是没有极限的。", "0", "0", "0", "0", "cv_sps_014", "0", "0"},
[415214] = {415214, 11052, 15, 9, "0", "0", "Raise\u{0020}me\u{0020}to\u{0020}max\u{0020}level.", "升到满级吧。", "0", "0", "0", "0", "cv_sps_015", "0", "0"},
[415215] = {415215, 11052, 16, 10, "0", "0", "Do\u{0020}not\u{0020}worry.\u{0020}I\u{0020}am\u{0020}here.", "别担心，有我在呢。", "0", "0", "0", "0", "cv_sps_016", "0", "0"},
[415216] = {415216, 11052, 17, 11, "0", "0", "How\u{0020}could\u{0020}I\u{0020}save\u{0020}the\u{0020}world\u{0020}if\u{0020}I\u{0020}could\u{0020}not\u{0020}do\u{0020}at\u{0020}least\u{0020}this\u{0020}much?", "不做到这种程度，怎么拯救世界？", "0", "0", "0", "0", "cv_sps_017", "0", "0"},
[415217] = {415217, 11052, 18, 12, "0", "0", "I\u{0020}simply\u{0020}have\u{0020}not\u{0020}used\u{0020}my\u{0020}full\u{0020}strength.", "我只是没有拿出全部实力。", "0", "0", "0", "0", "cv_sps_018", "0", "0"},
[415218] = {415218, 11052, 19, 13, "0", "0", "I\u{0020}was\u{0020}only\u{0020}warming\u{0020}up.", "只是在热身。", "0", "0", "0", "0", "cv_sps_019", "0", "0"},
[415219] = {415219, 11052, 20, 14, "0", "0", "This\u{0020}is\u{0020}so\u{0020}embarrassing.\u{0020}I\u{0020}want\u{0020}to\u{0020}die.", "太丢人了，好想去死。", "0", "0", "0", "0", "cv_sps_020", "0", "0"},
[415220] = {415220, 11052, 21, 15, "0", "0", "Become\u{0020}my\u{0020}EXP.", "成为经验值吧。", "0", "0", "0", "0", "cv_sps_021", "0", "0"},
