[415222] = {415222, 11052, 24, 17, "0", "0", "Still\u{0020}not\u{0020}dead?", "还没有死吗？", "0", "0", "0", "0", "cv_sps_023", "0", "0"},
[415223] = {415223, 11052, 25, 18, "0", "0", "Then\u{0020}let\u{0020}me\u{0020}show\u{0020}you\u{0020}how\u{0020}strong\u{0020}a\u{0020}hero\u{0020}in\u{0020}her\u{0020}prime\u{0020}can\u{0020}be.", "就让你们见识一下，全盛期的勇者有多强吧。", "0", "0", "0", "0", "cv_sps_025", "0", "0"},
[415224] = {415224, 11052, 26, 19, "0", "0", "I...\u{0020}will\u{0020}not\u{0020}die.", "我……是不会死的。", "0", "0", "0", "0", "cv_sps_026", "0", "0"},
