[415226] = {415226, 11052, 28, 21, "0", "0", "When\u{0020}I\u{0020}was\u{0020}little,\u{0020}Mother\u{0020}used\u{0020}to\u{0020}help\u{0020}me\u{0020}bathe...\u{0020}Later,\u{0020}she\u{0020}found\u{0020}it\u{0020}too\u{0020}troublesome\u{0020}and\u{0020}never\u{0020}helped\u{0020}again.", "小的时候，妈妈还会帮我洗澡……后来她嫌麻烦，就再也没帮过了。", "0", "0", "0", "0", "cv_sps_028", "0", "0"},
[415227] = {415227, 11052, 29, 21, "0", "0", "I\u{0020}cannot\u{0020}keep\u{0020}relaxing\u{0020}like\u{0020}this...\u{0020}Negligence\u{0020}is\u{0020}a\u{0020}hero's\u{0020}greatest\u{0020}enemy.", "不能再这么放松了……懈怠是勇者的头号大敌。", "0", "0", "0", "0", "cv_sps_029", "0", "0"},
