[4003500103] = {4003500103, 10035001, 91, 4, "0", "idle", "I\u{0020}used\u{0020}to\u{0020}admire\u{0020}AEGIS,\u{0020}but\u{0020}after\u{0020}getting\u{0020}here,\u{0020}I\u{0020}realized\u{0020}it's\u{0020}full\u{0020}of\u{0020}weirdos.\u{0020}Only\u{0020}the\u{0020}strongest\u{0020}survive.\u{0020}Chesterton's\u{0020}the\u{0020}same...\u{0020}Maybe\u{0020}it's\u{0020}like\u{0020}this\u{0020}everywhere.", "0", "0", "0", "0", "0", "cv_heli_4", "0", "idle,idle"},
[4003500104] = {4003500104, 10035001, 91, 4, "0", "idle", "Drivers\u{0020}get\u{0020}way\u{0020}more\u{0020}vacation\u{0020}than\u{0020}I\u{0020}thought.\u{0020}Now\u{0020}I\u{0020}can\u{0020}go\u{0020}back\u{0020}and\u{0020}mock\u{0020}my\u{0020}old\u{0020}boss\u{0020}who\u{0020}looked\u{0020}down\u{0020}on\u{0020}me.", "0", "0", "0", "0", "0", "cv_heli_5", "0", "idle,idle"},
