[4302000201] = {4302000201, 13020002, 2, 2, "0", "0", "Are\u{0020}you\u{0020}sure\u{0020}it's\u{0020}up\u{0020}to\u{0020}me?\u{0020}Just\u{0020}a\u{0020}heads-up,\u{0020}I\u{0020}can't\u{0020}promise\u{0020}I'll\u{0020}be\u{0020}much\u{0020}help.", "私に任せるの？あんまり、期待しないでね。", "0", "0", "0", "0", "cv_mayball_2", "0", "0"},
[4302000202] = {4302000202, 13020002, 3, 3, "0", "0", "This\u{0020}is\u{0020}Maybelle\u{0020}Ise,\u{0020}philosophy\u{0020}teacher\u{0020}at\u{0020}Sahara\u{0020}Azure\u{0020}Academy,\u{0020}part\u{0020}of\u{0020}the\u{0020}Honeymakers.\u{0020}Um,\u{0020}that's\u{0020}probably\u{0020}all\u{0020}you\u{0020}need\u{0020}to\u{0020}know...", "私はメイベル・イース。サハラの「ファーマメントアカデミー」で哲学の授业担当。ハニーメイカーに所属。これぐらいかな……。", "0", "0", "0", "0", "cv_mayball_3", "0", "0"},
[4302000203] = {4302000203, 13020002, 91, 4, "0", "idle", "Let's\u{0020}unwind\u{0020}after\u{0020}work.\u{0020}Coffee\u{0020}shop,\u{0020}friends,\u{0020}good\u{0020}vibes...\u{0020}hahuu...\u{0020}the\u{0020}clash\u{0020}of\u{0020}ideas\u{0020}and\u{0020}peace\u{0020}of\u{0020}mind\u{0020}all\u{0020}in\u{0020}one.", "仕事が终わったら、友达とカフェで会って、リラックスして、静かな时间と良い香り、そして…ふぁ～、思想のぶつかり合いを楽しむの。", "0", "0", "0", "0", "cv_mayball_4", "0", "0,idle"},
[4302000204] = {4302000204, 13020002, 94, 4, "0", "idle2", "I'm\u{0020}not\u{0020}exactly\u{0020}popular\u{0020}with\u{0020}the\u{0020}students,\u{0020}laid-back\u{0020}and\u{0020}all\u{0020}that.\u{0020}Still,\u{0020}even\u{0020}a\u{0020}bad\u{0020}example\u{0020}can\u{0020}be\u{0020}a\u{0020}lesson,\u{0020}right?", "のんびりしてる私は、一部の生徒からあまり良く思われてないみたい。でも教师としては成功かな…反面教师としてだけど。", "0", "0", "0", "0", "cv_mayball_5", "0", "0,idle2"},
[4302000205] = {4302000205, 13020002, 98, 4, "0", "idle3", "Precio\u{0020}and\u{0020}Mojun\u{0020}are\u{0020}workhorses.\u{0020}I'm\u{0020}lucky\u{0020}to\u{0020}have\u{0020}them\u{0020}around.\u{0020}Stella's\u{0020}like\u{0020}a\u{0020}walking\u{0020}balm.\u{0020}Want\u{0020}to\u{0020}give\u{0020}her\u{0020}style\u{0020}a\u{0020}try,\u{0020}Navigator?", "プレシオと墨君（ぼくくん）は仕事狂いだから、彼女たちがいるとチームはかなり楽になる。ステラは……柔らかくて愈されるの、ナビゲーターくんも试してみない？", "0", "0", "0", "0", "cv_mayball_6", "0", "0,idle3"},
[4302000206] = {4302000206, 13020002, 93, 5, "1_》_0_0.8", "switch1", "Existence\u{0020}is\u{0020}emptiness,\u{0020}right?\u{0020}So,\u{0020}what's\u{0020}it\u{0020}all\u{0020}about?\u{0020}Can\u{0020}nothingness\u{0020}ever\u{0020}be\u{0020}filled?", "存在は虚无であるが故に、意味を探し続ける。虚无を埋めることは出来るのかな？", "0", "0", "0", "0", "cv_mayball_7", "0", "0,switch1"},
[4302000207] = {4302000207, 13020002, 102, 5, "1_》_0_0.8", "switch2", "Do\u{0020}I\u{0020}seem\u{0020}sleepy?\u{0020}It's\u{0020}cool.\u{0020}Even\u{0020}if\u{0020}I\u{0020}nod\u{0020}off,\u{0020}this\u{0020}book\u{0020}doubles\u{0020}as\u{0020}a\u{0020}great\u{0020}pillow.", "少し疲れているように见える？心配しないで。うっかり寝てしまっても、この本がちょうど枕代わりになるから。", "0", "0", "0", "0", "cv_mayball_8", "0", "0,switch2"},
[4302000208] = {4302000208, 13020002, 96, 5, "1_》_0_0.8", "switch3", "Existence\u{0020}is\u{0020}emptiness;\u{0020}that\u{0020}is\u{0020}precisely\u{0020}why\u{0020}it\u{0020}continues\u{0020}to\u{0020}search\u{0020}for\u{0020}meaning...\u{0020}But\u{0020}can\u{0020}emptiness\u{0020}ever\u{0020}truly\u{0020}be\u{0020}filled?", "存在は虚无であるが故に、意味を探し続ける。虚无を埋めることは出来るのかな？", "0", "0", "0", "0", "cv_mayball_7", "0", "0,switch3"},
[4302000209] = {4302000209, 13020002, 92, 5, "1_》_0_0.8", "level1", "Philosophy\u{0020}books...\u{0020}Some\u{0020}keep\u{0020}you\u{0020}thinking\u{0020}all\u{0020}night,\u{0020}others\u{0020}put\u{0020}you\u{0020}right\u{0020}to\u{0020}sleep.\u{0020}Which\u{0020}type\u{0020}do\u{0020}you\u{0020}go\u{0020}for,\u{0020}Navigator?", "哲学の本は难解で深远。眠気が飞ぶものもあれば、眠りへ诱うものもある。ナビゲーターくんはどちらがお好み？", "0", "0", "0", "0", "cv_mayball_9", "0", "0,level1"},
[4302000210] = {4302000210, 13020002, 95, 5, "1_》_0_0.8", "level2", "Feeling\u{0020}lost?\u{0020}That's\u{0020}just\u{0020}proof\u{0020}of\u{0020}life.\u{0020}\"Existence\u{0020}precedes\u{0020}essence,\"\u{0020}and\u{0020}that's\u{0020}not\u{0020}something\u{0020}to\u{0020}sweat.", "たまに迷いを感じることはある？心配しないで。迷いを感じることこそ「実存は本质に先立つ」ということの证明。悪いことではないよ。", "0", "0", "0", "0", "cv_mayball_10", "0", "0,level2"},
[4302000211] = {4302000211, 13020002, 106, 5, "1_》_0_0.8", "level3", "Navigator,\u{0020}think\u{0020}I\u{0020}could\u{0020}lean\u{0020}on\u{0020}you\u{0020}a\u{0020}little\u{0020}more?\u{0020}Like...\u{0020}when\u{0020}my\u{0020}narcolepsy\u{0020}kicks\u{0020}in,\u{0020}you'll\u{0020}be\u{0020}there,\u{0020}yeah?\u{0020}That\u{0020}kind\u{0020}of\u{0020}vibe.", "ナビゲーターくん、もっと君に頼ってもいいかな？…もし过眠症の発作が起きたとき、君が侧にいてくれたらいいなって思って。", "0", "0", "0", "0", "cv_mayball_11", "0", "0,level3"},
[4302000212] = {4302000212, 13020002, 106, 5, "1_》_0_0.8", "level4", "Navigator,\u{0020}think\u{0020}I\u{0020}could\u{0020}lean\u{0020}on\u{0020}you\u{0020}a\u{0020}little\u{0020}more?\u{0020}Like...\u{0020}when\u{0020}my\u{0020}narcolepsy\u{0020}kicks\u{0020}in,\u{0020}you'll\u{0020}be\u{0020}there,\u{0020}yeah?\u{0020}That\u{0020}kind\u{0020}of\u{0020}vibe.", "ナビゲーターくん、もっと君に頼ってもいいかな？…もし过眠症の発作が起きたとき、君が侧にいてくれたらいいなって思って。", "0", "0", "0", "0", "cv_mayball_11", "0", "0,level4"},
