[4302000218] = {4302000218, 13020002, 17, 11, "0", "0", "Oops,\u{0020}I\u{0020}accidentally\u{0020}did\u{0020}a\u{0020}great\u{0020}job.", "おっと、やりすぎちゃったかな。", "0", "0", "0", "0", "cv_mayball_17", "0", "0"},
