[4302000226] = {4302000226, 13020002, 28, 21, "0", "0", "Hahuu...\u{0020}It's\u{0020}way\u{0020}easier\u{0020}to\u{0020}get\u{0020}sleepy\u{0020}in\u{0020}here\u{0020}than\u{0020}out\u{0020}there.\u{0020}Navigator,\u{0020}don't\u{0020}fall\u{0020}asleep\u{0020}before\u{0020}me.", "ふぁ～、ここは外よりも寝やすいね。ナビゲーターくんは先に寝ちゃだめだよ。", "0", "0", "0", "0", "cv_mayball_25", "0", "0"},
[4302000227] = {4302000227, 13020002, 29, 21, "0", "0", "In\u{0020}Sahara,\u{0020}philosophers\u{0020}have\u{0020}always\u{0020}debated\u{0020}in\u{0020}bathhouses.\u{0020}Got\u{0020}any\u{0020}questions\u{0020}you\u{0020}want\u{0020}to\u{0020}ask\u{0020}me\u{0020}right\u{0020}now?", "昔からサハラの哲学者たちはお风吕で议论するのが大好きだったの。ナビゲーターくんは何か话したいことはある？", "0", "0", "0", "0", "cv_mayball_26", "0", "0"},
