[412701] = {412701, 11027, 2, 2, "0", "0", "Since\u{0020}you\u{0020}chose\u{0020}me,\u{0020}then\u{0020}don't\u{0020}complain\u{0020}if\u{0020}I\u{0020}talk\u{0020}too\u{0020}much.", "あなたが選んだのだから、私がおしゃべりだとは思わないでね。", "0", "0", "0", "0", "cv_qishi_2", "0", "0"},
[412702] = {412702, 11027, 3, 3, "0", "0", "I\u{0020}thought\u{0020}you\u{0020}never\u{0020}wanted\u{0020}to\u{0020}see\u{0020}me\u{0020}again.\u{0020}Is\u{0020}my\u{0020}charm\u{0020}really\u{0020}just\u{0020}that\u{0020}irresistible?\u{0020}Fine\u{0020}then.\u{0020}In\u{0020}the\u{0020}time\u{0020}we\u{0020}spend\u{0020}together\u{0020}from\u{0020}here\u{0020}on,\u{0020}I'll\u{0020}make\u{0020}sure\u{0020}you\u{0020}fully\u{0020}experience\u{0020}my\u{0020}fatal\u{0020}allure,\u{0020}little\u{0020}Navigator.", "もう会いたくないのかと思ったわ。やっぱり私の魅力が強すぎるのかしら？まあいいわ、これからの付き合いで、私の魅力的な誘惑を存分に味わせてあげるわね、ナビゲーターくん。", "0", "0", "0", "0", "cv_qishi_3", "0", "0"},
[412703] = {412703, 11027, 4, 4, "0", "idle", "People\u{0020}who\u{0020}like\u{0020}sweets\u{0020}and\u{0020}people\u{0020}who\u{0020}prefer\u{0020}savory\u{0020}food\u{0020}are\u{0020}no\u{0020}different\u{0020}at\u{0020}heart.\u{0020}The\u{0020}same\u{0020}goes\u{0020}for\u{0020}me:\u{0020}those\u{0020}who\u{0020}worship\u{0020}hope\u{0020}and\u{0020}beauty\u{0020}are\u{0020}the\u{0020}same\u{0020}kind\u{0020}as\u{0020}people\u{0020}like\u{0020}me,\u{0020}who\u{0020}treat\u{0020}others'\u{0020}misfortune\u{0020}as\u{0020}drinking\u{0020}accompaniment.", "甘いものが好きな人と塩辛いものが好きな人は本質的に変わらないわ。それは私にも言えることよ。希望や美しさを尊ぶ人も、他人の不幸を酒の肴にする私みたいな人も、結局同じなの。", "0", "0", "0", "0", "cv_qishi_4", "0", "0"},
[412704] = {412704, 11027, 5, 4, "0", "idle", "Don't\u{0020}have\u{0020}unrealistic\u{0020}expectations\u{0020}of\u{0020}your\u{0020}own\u{0020}abilities.\u{0020}Don't\u{0020}fantasize\u{0020}that\u{0020}your\u{0020}life\u{0020}will\u{0020}unfold\u{0020}like\u{0020}some\u{0020}dream.\u{0020}Always\u{0020}prepare\u{0020}for\u{0020}the\u{0020}worst-case\u{0020}scenario.\u{0020}For\u{0020}people\u{0020}like\u{0020}us,\u{0020}that's\u{0020}the\u{0020}only\u{0020}way\u{0020}to\u{0020}grasp\u{0020}a\u{0020}happy\u{0020}life.", "自分の能力に過度な期待をしないで。人生が夢のように展開するなんて幻想を抱かないで。全てを最悪の状況で考えること、それが私たちのような人間が幸せをつかむ唯一の方法よ。", "0", "0", "0", "0", "cv_qishi_5", "0", "0"},
[412705] = {412705, 11027, 6, 4, "0", "idle", "The\u{0020}power\u{0020}of\u{0020}words\u{0020}is\u{0020}limited.\u{0020}No\u{0020}matter\u{0020}how\u{0020}silver-tongued\u{0020}I\u{0020}may\u{0020}be,\u{0020}I\u{0020}could\u{0020}never\u{0020}compete\u{0020}with\u{0020}absolute\u{0020}violence.\u{0020}That\u{0020}violent\u{0020}brat\u{0020}who\u{0020}only\u{0020}ever\u{0020}wants\u{0020}to\u{0020}solve\u{0020}everything\u{0020}with\u{0020}scissors\u{0020}is\u{0020}truly\u{0020}my\u{0020}natural\u{0020}enemy.", "言葉の力は限られているの。どんなに私が巧みに話しても、極度の暴力には勝てないわ。何でもハサミで解決しようとするあの暴力おちびちゃん、彼女はまさに私の「天敵」ね。", "0", "0", "0", "0", "cv_qishi_6", "0", "0"},
[412706] = {412706, 11027, 7, 5, "1_》_0_0.8", "level1", "Call\u{0020}it\u{0020}sophistry\u{0020}if\u{0020}you\u{0020}like,\u{0020}little\u{0020}Navigator,\u{0020}there\u{0020}are\u{0020}people\u{0020}in\u{0020}this\u{0020}world\u{0020}who\u{0020}take\u{0020}joy\u{0020}in\u{0020}helping\u{0020}others,\u{0020}so\u{0020}naturally\u{0020}there\u{0020}should\u{0020}also\u{0020}be\u{0020}people\u{0020}like\u{0020}me\u{0020}who\u{0020}long\u{0020}to\u{0020}see\u{0020}others\u{0020}fall\u{0020}into\u{0020}the\u{0020}abyss.\u{0020}People\u{0020}ought\u{0020}to\u{0020}respect\u{0020}even\u{0020}such\u{0020}a\u{0020}vile\u{0020}hobby\u{0020}of\u{0020}mine.", "これを私の詭弁だと思ってもいいわ——ナビゲーターくん。この世には助けを求める人がいる一方で、当然のことながら、他人が奈落の底に落ちるのを楽しみにしている私のような人間もいるの。私の悪趣味は尊重されるべきよ。", "0", "0", "0", "0", "cv_qishi_7", "0", "0"},
[412707] = {412707, 11027, 8, 5, "1_》_0_0.8", "level1", "I\u{0020}never\u{0020}harm\u{0020}people.\u{0020}All\u{0020}I\u{0020}do\u{0020}is\u{0020}push\u{0020}them\u{0020}toward\u{0020}making\u{0020}a\u{0020}choice.\u{0020}Even\u{0020}if\u{0020}they\u{0020}choose\u{0020}the\u{0020}wrong\u{0020}side,\u{0020}that\u{0020}choice\u{0020}was\u{0020}still\u{0020}made\u{0020}by\u{0020}their\u{0020}own\u{0020}will.", "私は決して人を害することはないわ。私のすることはただ、人を選択へと促すだけ——たとえそれが間違った選択であっても、それは彼らが自分の意志で決めたことよ。", "0", "0", "0", "0", "cv_qishi_8", "0", "0"},
[412708] = {412708, 11027, 9, 5, "1_》_100_1.5", "level2", "When\u{0020}someone\u{0020}stands\u{0020}at\u{0020}the\u{0020}crossroads\u{0020}of\u{0020}uncertainty,\u{0020}even\u{0020}words\u{0020}as\u{0020}light\u{0020}as\u{0020}a\u{0020}breeze\u{0020}can\u{0020}tilt\u{0020}their\u{0020}frozen\u{0020}body\u{0020}in\u{0020}one\u{0020}direction.\u{0020}Little\u{0020}Navigator,\u{0020}you\u{0020}should\u{0020}be\u{0020}wary\u{0020}of\u{0020}people\u{0020}who\u{0020}try\u{0020}to\u{0020}teach\u{0020}you\u{0020}what\u{0020}is\u{0020}\"right.\"", "人が迷いの十字路に立たされるとき、そよ風のような言葉でもその体をどこかに傾かせる力になるの。ナビゲーターくん、「正しい」ことを教えようとする人には注意しなさいね。", "0", "0", "0", "0", "cv_qishi_9", "0", "0"},
[412709] = {412709, 11027, 10, 5, "1_》_500_2", "level3", "Little\u{0020}Navigator,\u{0020}I'm\u{0020}an\u{0020}instigator,\u{0020}not\u{0020}a\u{0020}con\u{0020}artist.\u{0020}Lies\u{0020}are\u{0020}a\u{0020}cheap\u{0020}method\u{0020}beneath\u{0020}me.\u{0020}My\u{0020}words\u{0020}are\u{0020}always\u{0020}sincere.\u{0020}For\u{0020}example,\u{0020}this\u{0020}one,\u{0020}little\u{0020}Navigator,\u{0020}your\u{0020}scent\u{0020}is\u{0020}inciting\u{0020}me\u{0020}to\u{0020}commit\u{0020}a\u{0020}crime\u{0020}against\u{0020}you~", "ナビゲーターくん、私は教唆犯であって、詐欺師ではないわ。嘘なんて卑劣な手段は使わない。私の言葉はすべて本心よ。例えば——あなたの香りが私を犯罪に駆り立てるのよ、ナビゲーターくん。", "0", "0", "0", "0", "cv_qishi_10", "0", "0"},
[412710] = {412710, 11027, 11, 5, "1_》_1000_2.5", "level4", "I\u{0020}cannot\u{0020}be\u{0020}saved,\u{0020}nor\u{0020}do\u{0020}I\u{0020}deserve\u{0020}to\u{0020}be.\u{0020}My\u{0020}whole\u{0020}life\u{0020}has\u{0020}been\u{0020}one\u{0020}of\u{0020}committing\u{0020}sins\u{0020}and\u{0020}atoning\u{0020}for\u{0020}them.\u{0020}No\u{0020}matter\u{0020}how\u{0020}much\u{0020}time\u{0020}passes,\u{0020}I\u{0020}will\u{0020}never\u{0020}change.\u{0020}Now\u{0020}that\u{0020}little\u{0020}Navigator\u{0020}knows\u{0020}what\u{0020}kind\u{0020}of\u{0020}person\u{0020}I\u{0020}am...\u{0020}would\u{0020}you\u{0020}be\u{0020}willing\u{0020}to\u{0020}be\u{0020}my\u{0020}accomplice\u{0020}for\u{0020}life?", "私は救われることも、救われる価値もないわ。私の一生は犯罪と贖罪の連続よ。どんなに時間が経っても、私は変わらない。さあ、ナビゲーターくんは私がどんな人間か分かったでしょう……あなた、一生私の共犯者になってくれる？", "0", "0", "0", "0", "cv_qishi_11", "0", "0"},
[412711] = {412711, 11027, 12, 6, "0", "0", "Even\u{0020}if\u{0020}you\u{0020}invest\u{0020}in\u{0020}me,\u{0020}there's\u{0020}no\u{0020}guarantee\u{0020}you'll\u{0020}get\u{0020}anything\u{0020}in\u{0020}return.", "私に投資しても、何の利益も得られないかもしれないわよ。", "0", "0", "0", "0", "cv_qishi_12", "0", "0"},
