[4102700101] = {4102700101, 11027001, 2, 2, "0", "0", "Since\u{0020}you\u{0020}chose\u{0020}me,\u{0020}then\u{0020}don't\u{0020}complain\u{0020}if\u{0020}I\u{0020}talk\u{0020}too\u{0020}much.", "あなたが選んだのだから、私がおしゃべりだとは思わないでね。", "0", "0", "0", "0", "cv_sk_qishi_2", "0", "0"},
[4102700102] = {4102700102, 11027001, 3, 3, "0", "0", "I\u{0020}thought\u{0020}you\u{0020}never\u{0020}wanted\u{0020}to\u{0020}see\u{0020}me\u{0020}again.\u{0020}Is\u{0020}my\u{0020}charm\u{0020}really\u{0020}just\u{0020}that\u{0020}irresistible?\u{0020}Fine\u{0020}then.\u{0020}In\u{0020}the\u{0020}time\u{0020}we\u{0020}spend\u{0020}together\u{0020}from\u{0020}here\u{0020}on,\u{0020}I'll\u{0020}make\u{0020}sure\u{0020}you\u{0020}fully\u{0020}experience\u{0020}my\u{0020}fatal\u{0020}allure,\u{0020}little\u{0020}Navigator.", "もう会いたくないのかと思ったわ。やっぱり私の魅力が強すぎるのかしら？まあいいわ、これからの付き合いで、私の魅力的な誘惑を存分に味わせてあげるわね、ナビゲーターくん。", "0", "0", "0", "0", "cv_sk_qishi_3", "0", "0"},
[4102700103] = {4102700103, 11027001, 91, 4, "0", "idle", "Did\u{0020}Stephanie\u{0020}make\u{0020}you\u{0020}do\u{0020}this,\u{0020}little\u{0020}Navigator?\u{0020}Tsk,\u{0020}tsk...\u{0020}that\u{0020}person\u{0020}really\u{0020}has\u{0020}a\u{0020}disgusting\u{0020}personality\u{0020}that\u{0020}doesn't\u{0020}match\u{0020}her\u{0020}appearance...\u{0020}I'm\u{0020}not\u{0020}the\u{0020}only\u{0020}one\u{0020}who\u{0020}thinks\u{0020}so,\u{0020}am\u{0020}I?", "ステファニーがナビゲーターくんにそうさせたの？チッチッチ、あの人は見た目と違って本当に嫌な性格してるわね……私だけがそう思っているわけじゃないでしょう？", "0", "0", "0", "0", "cv_sk_qishi_7", "0", "0"},
[4102700104] = {4102700104, 11027001, 91, 4, "0", "idle", "I'm\u{0020}looking\u{0020}forward\u{0020}to\u{0020}it,\u{0020}little\u{0020}Navigator,\u{0020}what\u{0020}kind\u{0020}of\u{0020}methods\u{0020}will\u{0020}you\u{0020}use\u{0020}to\u{0020}make\u{0020}me\u{0020}submit?", "私は楽しみにしているわ、ナビゲーターくんがどんな手段で私を屈服させるのか。", "0", "0", "0", "0", "cv_sk_qishi_8", "0", "0"},
[4102700105] = {4102700105, 11027001, 91, 4, "0", "idle", "Right\u{0020}now,\u{0020}I\u{0020}can't\u{0020}do\u{0020}anything.\u{0020}Other\u{0020}than\u{0020}words,\u{0020}I\u{0020}have\u{0020}no\u{0020}way\u{0020}to\u{0020}resist\u{0020}you...\u{0020}You're\u{0020}excited,\u{0020}aren't\u{0020}you?\u{0020}Aren't\u{0020}you?", "今の私は何もできないわ。言葉以外では何も君に逆らう手段がないの……君は興奮しているんでしょう？そうでしょう？", "0", "0", "0", "0", "cv_sk_qishi_9", "0", "0"},
[4102700106] = {4102700106, 11027001, 94, 4, "0", "idle2", "I\u{0020}can\u{0020}feel\u{0020}it\u{0020}all,\u{0020}you\u{0020}know...\u{0020}your\u{0020}quickened\u{0020}breathing,\u{0020}your\u{0020}rising\u{0020}body\u{0020}heat,\u{0020}your\u{0020}uncontrollable\u{0020}heartbeat.\u{0020}I\u{0020}can\u{0020}feel\u{0020}every\u{0020}bit\u{0020}of\u{0020}it.", "感じるわよ——君の荒い息遣い、上がる体温、抑えきれない心臓の鼓動、全部感じるわ。", "0", "0", "0", "0", "cv_sk_qishi_13", "0", "0"},
[4102700107] = {4102700107, 11027001, 94, 4, "0", "idle2", "You're\u{0020}about\u{0020}to\u{0020}lose\u{0020}control,\u{0020}aren't\u{0020}you,\u{0020}little\u{0020}Navigator?\u{0020}Here's\u{0020}a\u{0020}little\u{0020}hint,\u{0020}what\u{0020}happened\u{0020}in\u{0020}this\u{0020}room,\u{0020}and\u{0020}what\u{0020}is\u{0020}going\u{0020}to\u{0020}happen\u{0020}here,\u{0020}is\u{0020}something\u{0020}only\u{0020}you\u{0020}and\u{0020}I\u{0020}know.", "もう抑えきれないでしょう？ナビゲーターくん、一つ教えてあげる——この部屋で何が起こったか、これから何が起こるか、知っているのは君と私だけよ。", "0", "0", "0", "0", "cv_sk_qishi_14", "0", "0"},
[4102700108] = {4102700108, 11027001, 94, 4, "0", "idle2", "That\u{0020}burning\u{0020}gaze\u{0020}of\u{0020}yours\u{0020}can't\u{0020}be\u{0020}hidden\u{0020}no\u{0020}matter\u{0020}how\u{0020}hard\u{0020}you\u{0020}try.\u{0020}You\u{0020}may\u{0020}be\u{0020}able\u{0020}to\u{0020}deceive\u{0020}yourself,\u{0020}but\u{0020}you\u{0020}can't\u{0020}deceive\u{0020}me,\u{0020}little\u{0020}Navigator.", "君の熱い視線は隠しきれないわ。君は自分を騙せても、私を騙すことはできない、ナビゲーターくん。", "0", "0", "0", "0", "cv_sk_qishi_15", "0", "0"},
[4102700109] = {4102700109, 11027001, 92, 5, "14_1_0_0.8", "touch1", "Do\u{0020}you\u{0020}want\u{0020}to\u{0020}correct\u{0020}my\u{0020}twisted\u{0020}way\u{0020}of\u{0020}thinking?\u{0020}That\u{0020}won't\u{0020}be\u{0020}easy.\u{0020}Can\u{0020}you\u{0020}really\u{0020}do\u{0020}it,\u{0020}little\u{0020}Navigator~", "私の歪んだ考えを直したいの？そんな簡単なことじゃないわよ、ナビゲーターくんにできるかしら？", "0", "0", "0", "0", "cv_sk_qishi_5", "0", "0"},
[4102700110] = {4102700110, 11027001, 92, 5, "14_1_0_0.8", "touch1", "If\u{0020}it's\u{0020}only\u{0020}some\u{0020}harmless\u{0020}little\u{0020}punishment,\u{0020}it'll\u{0020}just\u{0020}make\u{0020}me\u{0020}happy...\u{0020}little\u{0020}Navigator,\u{0020}surely\u{0020}that's\u{0020}not\u{0020}all\u{0020}you've\u{0020}got?", "もしそれが痛くも痒くもない罰なら、私は嬉しいだけよ……ナビゲーターくん、あなたはそんな程度じゃないわよね？", "0", "0", "0", "0", "cv_sk_qishi_6", "0", "0"},
