[414901] = {414901, 11049, 2, 2, "0", "0", "I\u{0020}really\u{0020}don't\u{0020}want\u{0020}to\u{0020}be\u{0020}on\u{0020}duty...\u{0020}I\u{0020}want\u{0020}to\u{0020}sleep,\u{0020}I\u{0020}want\u{0020}to\u{0020}watch\u{0020}anime...", "当直したくない……寝たい、アニメ観たい……", "0", "0", "0", "0", "cv_aertaiya_2", "0", "0"},
[414902] = {414902, 11049, 3, 3, "0", "0", "You\u{0020}didn't\u{0020}expect\u{0020}to\u{0020}see\u{0020}me\u{0020}here,\u{0020}did\u{0020}you,\u{0020}Mr.\u{0020}Lizard!\u{0020}Hehe,\u{0020}didn't\u{0020}someone\u{0020}once\u{0020}say\u{0020}that\u{0020}every\u{0020}reunion\u{0020}in\u{0020}this\u{0020}world\u{0020}is\u{0020}a\u{0020}long-planned\u{0020}encounter?\u{0020}I\u{0020}remembered\u{0020}that\u{0020}right,\u{0020}didn't\u{0020}I?", "驚いたでしょ、トカゲさん！ふふ、誰かが言ってたよね、世の中の再会はすべて仕組まれた出会いだって——間違ってないよね？", "0", "0", "0", "0", "cv_aertaiya_3", "0", "0"},
[414903] = {414903, 11049, 4, 4, "0", "idle", "People\u{0020}lose\u{0020}themselves\u{0020}in\u{0020}fantasy\u{0020}not\u{0020}because\u{0020}fantasy\u{0020}is\u{0020}so\u{0020}wonderful,\u{0020}but\u{0020}because\u{0020}reality\u{0020}is\u{0020}too\u{0020}cruel.\u{0020}I\u{0020}used\u{0020}to\u{0020}want\u{0020}to\u{0020}run\u{0020}from\u{0020}it,\u{0020}but\u{0020}now\u{0020}I\u{0020}understand.\u{0020}I\u{0020}want\u{0020}to\u{0020}face\u{0020}it\u{0020}and\u{0020}overcome\u{0020}it,\u{0020}so\u{0020}that\u{0020}my\u{0020}fantasy\u{0020}can\u{0020}become\u{0020}reality.", "人々が幻想に浸るのは、幻想がどれほど美しいかではなく、現実があまりにも残酷だからなんだ。昔は逃げたかったけど、今はわかったよ、向き合って、乗り越えなきゃ。そうすれば、私の幻想を現実にできる。", "0", "0", "0", "0", "cv_aertaiya_4", "0", "0"},
[414904] = {414904, 11049, 5, 4, "0", "idle2", "To\u{0020}think\u{0020}you\u{0020}were\u{0020}willing\u{0020}to\u{0020}pay\u{0020}with\u{0020}your\u{0020}freedom\u{0020}just\u{0020}to\u{0020}stay\u{0020}by\u{0020}my\u{0020}side...\u{0020}you're\u{0020}really\u{0020}something,\u{0020}Na--vi--ga--tor.", "自由を代償にしてまであなたのそばに居たいなんて、あなたって本当にすごいよ、ナビゲーター。", "0", "0", "0", "0", "cv_aertaiya_5", "0", "0"},
[414905] = {414905, 11049, 6, 4, "0", "idle3", "The\u{0020}Sin\u{0020}I\u{0020}drove\u{0020}off\u{0020}was\u{0020}called\u{0020}Hydra,\u{0020}the\u{0020}squad\u{0020}I'm\u{0020}in\u{0020}now\u{0020}is\u{0020}also\u{0020}called\u{0020}Hydra,\u{0020}and\u{0020}my\u{0020}teammates\u{0020}even\u{0020}seem\u{0020}to\u{0020}be\u{0020}like\u{0020}Sin...\u{0020}whoa,\u{0020}can\u{0020}that\u{0020}really\u{0020}be\u{0020}a\u{0020}coincidence...?\u{0020}Wait,\u{0020}does\u{0020}that\u{0020}mean\u{0020}I'm\u{0020}a\u{0020}Sin\u{0020}too?", "私が追い払った原罪の名前はハイドラ、今のチームの名前もハイドラ、そして仲間も原罪みたい……うわ、これって本当に偶然？……待って、もしかして私も原罪？", "0", "0", "0", "0", "cv_aertaiya_6", "0", "0"},
[414906] = {414906, 11049, 7, 5, "1_》_0_0.8", "level1", "If\u{0020}life\u{0020}really\u{0020}is\u{0020}like\u{0020}a\u{0020}box\u{0020}of\u{0020}chocolates,\u{0020}as\u{0020}people\u{0020}say,\u{0020}then\u{0020}mine\u{0020}must\u{0020}be\u{0020}filled\u{0020}with\u{0020}dark\u{0020}chocolate...\u{0020}bitter?\u{0020}No,\u{0020}I\u{0020}mean\u{0020}mature!\u{0020}Sexy!", "もし他の人が言うように人生が一箱のチョコレートだとしたら、私の箱はきっとダークチョコでいっぱい——苦い？いや、私が言いたいのは成熟だ！セクシーさだ！", "0", "0", "0", "0", "cv_aertaiya_7", "0", "0"},
[414907] = {414907, 11049, 8, 5, "1_》_0_0.8", "level1", "That\u{0020}feels\u{0020}more\u{0020}like\u{0020}a\u{0020}tickle.\u{0020}It's\u{0020}actually\u{0020}kind\u{0020}of\u{0020}nice.", "なんだかくすぐったいけど、結構気持ちいい。", "0", "0", "0", "0", "cv_aertaiya_8", "0", "0"},
[414908] = {414908, 11049, 9, 5, "1_》_100_1.5", "level2", "I'm\u{0020}at\u{0020}the\u{0020}age\u{0020}where\u{0020}I'm\u{0020}supposed\u{0020}to\u{0020}be\u{0020}enjoying\u{0020}my\u{0020}youth,\u{0020}but\u{0020}what\u{0020}does\u{0020}that\u{0020}even\u{0020}mean?\u{0020}Does\u{0020}it\u{0020}mean\u{0020}having\u{0020}a\u{0020}passionate\u{0020}romance?\u{0020}...What\u{0020}is\u{0020}real\u{0020}romance\u{0020}even\u{0020}like?", "私は今、青春を謳歌する年齢だけど、どうすれば青春を謳歌してるって言えるんだろう？破天荒な恋愛をすればいいのかな？……現実の恋愛ってどんな感じなんだろう？", "0", "0", "0", "0", "cv_aertaiya_9", "0", "0"},
[414909] = {414909, 11049, 10, 5, "1_》_500_2", "level3", "Come\u{0020}to\u{0020}think\u{0020}of\u{0020}it...\u{0020}I've\u{0020}never\u{0020}been\u{0020}in\u{0020}love,\u{0020}so\u{0020}I\u{0020}don't\u{0020}really\u{0020}know\u{0020}what\u{0020}liking\u{0020}someone\u{0020}is\u{0020}supposed\u{0020}to\u{0020}feel\u{0020}like.\u{0020}But\u{0020}one\u{0020}thing\u{0020}I\u{0020}am\u{0020}sure\u{0020}of\u{0020}is\u{0020}that\u{0020}when\u{0020}I'm\u{0020}by\u{0020}your\u{0020}side,\u{0020}I\u{0020}feel\u{0020}happy,\u{0020}and\u{0020}I\u{0020}feel\u{0020}at\u{0020}ease.", "そういえば……恋愛したことないから、好きってどんな感情かわからない。でも、あなたのそばにいるとき、私はとても幸せで安心してるよ。", "0", "0", "0", "0", "cv_aertaiya_10", "0", "0"},
[414910] = {414910, 11049, 11, 5, "1_》_1000_2.5", "level4", "Before\u{0020}I\u{0020}knew\u{0020}it,\u{0020}I'd\u{0020}already\u{0020}gotten\u{0020}used\u{0020}to\u{0020}being\u{0020}by\u{0020}your\u{0020}side...\u{0020}You\u{0020}know,\u{0020}I\u{0020}can't\u{0020}imagine\u{0020}waking\u{0020}up\u{0020}one\u{0020}day\u{0020}and\u{0020}not\u{0020}finding\u{0020}you\u{0020}beside\u{0020}me,\u{0020}or\u{0020}not\u{0020}being\u{0020}by\u{0020}your\u{0020}side.", "いつの間にか、あなたのそばにいるのが当たり前になってた……わかる？朝目覚めて、あなたがそばにいないとか、そんなこと想像できないんだ。", "0", "0", "0", "0", "cv_aertaiya_11", "0", "0"},
