[422501] = {422501, 12025, 2, 2, "0", "0", "Do\u{0020}I\u{0020}have\u{0020}to\u{0020}become\u{0020}your\u{0020}personal\u{0020}bodyguard,\u{0020}Navigator?\u{0020}Me?\u{0020}Deep\u{0020}breaths,\u{0020}I\u{0020}need\u{0020}deep\u{0020}breaths\u{0020}-\u{0020}hss\u{0020}-\u{0020}hoo\u{0020}-\u{0020}that\u{0020}was\u{0020}close,\u{0020}I\u{0020}almost\u{0020}suffocated\u{0020}from\u{0020}lack\u{0020}of\u{0020}oxygen...\u{0020}I'll\u{0020}do\u{0020}my\u{0020}best!", "ナビゲーターさんのボディガードを務めるのは私ですか？深呼吸、深呼吸しなければ——すぅ——はぁ——危なかった、息が切れそうになった……頑張ります！", "0", "0", "0", "0", "cv_feilin_2", "0", "0"},
[422502] = {422502, 12025, 3, 3, "0", "0", "Whenever\u{0020}I\u{0020}start\u{0020}wondering\u{0020}whether\u{0020}I'm\u{0020}still\u{0020}suited\u{0020}to\u{0020}be\u{0020}a\u{0020}driver,\u{0020}I\u{0020}somehow\u{0020}end\u{0020}up\u{0020}here.\u{0020}Please\u{0020}allow\u{0020}me\u{0020}to\u{0020}introduce\u{0020}myself\u{0020}again,\u{0020}Navigator.\u{0020}My\u{0020}name\u{0020}is\u{0020}Felin\u{0020}Branny,\u{0020}and\u{0020}I\u{0020}am\u{0020}a\u{0020}driver.", "自分がまだドライバーに向いているかどうか考えていたら、いつの間にかここに来てしまいました。もう一度自己紹介させてください、ナビゲーターさん。私はフェリン・ブリトニー、ドライバーです。", "0", "0", "0", "0", "cv_feilin_3", "0", "0"},
[422503] = {422503, 12025, 4, 4, "0", "idle", "Whether\u{0020}they're\u{0020}support\u{0020}staff\u{0020}handling\u{0020}logistics\u{0020}or\u{0020}drivers\u{0020}fighting\u{0020}on\u{0020}the\u{0020}front\u{0020}line,\u{0020}everyone\u{0020}is\u{0020}indispensable\u{0020}to\u{0020}Aegis.\u{0020}I\u{0020}think\u{0020}that's\u{0020}the\u{0020}most\u{0020}precious\u{0020}thing\u{0020}I've\u{0020}learned\u{0020}over\u{0020}these\u{0020}past\u{0020}six\u{0020}months.", "後方支援のスタッフも、前線で戦うドライバーも、アイギスには欠かせない存在です。これがこの半年で学んだ最も貴重なことです。", "0", "0", "0", "0", "cv_feilin_4", "0", "0"},
[422504] = {422504, 12025, 5, 4, "0", "idle", "I\u{0020}dreamed\u{0020}about\u{0020}the\u{0020}captain\u{0020}and\u{0020}the\u{0020}others\u{0020}again\u{0020}recently,\u{0020}and\u{0020}they\u{0020}praised\u{0020}me\u{0020}for\u{0020}how\u{0020}much\u{0020}I've\u{0020}grown.\u{0020}They\u{0020}said\u{0020}I've\u{0020}really\u{0020}worked\u{0020}hard,\u{0020}that\u{0020}I've\u{0020}done\u{0020}well...\u{0020}Actually,\u{0020}that's\u{0020}probably\u{0020}just\u{0020}what\u{0020}I\u{0020}want\u{0020}to\u{0020}hear\u{0020}deep\u{0020}down,\u{0020}isn't\u{0020}it?\u{0020}I\u{0020}really\u{0020}am...\u{0020}so\u{0020}full\u{0020}of\u{0020}myself.", "最近、また隊長たちの夢を見ました。彼女たちに成長したと褒められて、本当に努力してるねと言われました……実はこれ、私の独りよがりですよね？私って本当に……ナルシズムですね。", "0", "0", "0", "0", "cv_feilin_5", "0", "0"},
[422505] = {422505, 12025, 6, 4, "0", "idle", "Whenever\u{0020}I\u{0020}run\u{0020}into\u{0020}former\u{0020}coworkers\u{0020}from\u{0020}the\u{0020}Department\u{0020}of\u{0020}Social\u{0020}Restoration\u{0020}here\u{0020}on\u{0020}the\u{0020}Ark,\u{0020}I\u{0020}always\u{0020}pray\u{0020}they\u{0020}won't\u{0020}see\u{0020}me...\u{0020}Why?\u{0020}Because\u{0020}I\u{0020}have\u{0020}no\u{0020}idea\u{0020}what\u{0020}I'd\u{0020}even\u{0020}say...", "方舟で一緒に働いていた社会復興部の同僚に出会いそうなときは、いつも見つからないように祈っています……なぜって？何を話せばいいかわからないからです……", "0", "0", "0", "0", "cv_feilin_6", "0", "0"},
[422506] = {422506, 12025, 7, 5, "1_》_0_0.8", "level1", "This\u{0020}is\u{0020}something\u{0020}I\u{0020}only\u{0020}learned\u{0020}recently...\u{0020}It\u{0020}seems\u{0020}a\u{0020}lot\u{0020}of\u{0020}people\u{0020}now\u{0020}see\u{0020}\"driver\"\u{0020}as\u{0020}a\u{0020}dream,\u{0020}the\u{0020}way\u{0020}people\u{0020}once\u{0020}dreamed\u{0020}of\u{0020}becoming\u{0020}scientists.\u{0020}Is\u{0020}that\u{0020}a\u{0020}good\u{0020}thing?\u{0020}It\u{0020}feels\u{0020}a\u{0020}little\u{0020}complicated...", "最近知ったことですが……多くの人が「ドライバー」を夢見ているようです。かつての科学者のように。これは良いことなのでしょうか……？", "0", "0", "0", "0", "cv_feilin_7", "0", "0"},
[422507] = {422507, 12025, 8, 5, "1_》_0_0.8", "level1", "You\u{0020}don't\u{0020}look\u{0020}so\u{0020}well,\u{0020}Navigator.\u{0020}Are\u{0020}you\u{0020}too\u{0020}tired\u{0020}from\u{0020}work?\u{0020}I\u{0020}know\u{0020}a\u{0020}pretty\u{0020}good\u{0020}place.\u{0020}Their\u{0020}drinks\u{0020}and\u{0020}grilled\u{0020}meat\u{0020}are\u{0020}great.\u{0020}Want\u{0020}to\u{0020}go\u{0020}together\u{0020}after\u{0020}work?", "ナビゲーターさん、顔色が悪いですね。仕事が大変なのでしょうか？いいお店を知っていますよ。そこのお酒と焼肉は最高です。仕事が終わったら一緒に行きませんか？", "0", "0", "0", "0", "cv_feilin_8", "0", "0"},
[422508] = {422508, 12025, 9, 5, "1_》_100_1.5", "level2", "Can\u{0020}someone\u{0020}like\u{0020}me\u{0020}really\u{0020}be\u{0020}a\u{0020}capable\u{0020}captain?\u{0020}Navigator,\u{0020}do\u{0020}you\u{0020}know\u{0020}Miss\u{0020}Dolores?\u{0020}There's\u{0020}something\u{0020}I'd\u{0020}like\u{0020}to\u{0020}ask\u{0020}her\u{0020}about\u{0020}-\u{0020}how\u{0020}to\u{0020}be\u{0020}a\u{0020}good\u{0020}captain.", "私のような人間が本当に有能な隊長になれるのでしょうか？ナビゲーターさん、ドロリィスさんをご存知ですか？彼女に相談したいことがあります——どうやったら良い隊長になれるかについてです。", "0", "0", "0", "0", "cv_feilin_9", "0", "0"},
[422509] = {422509, 12025, 10, 5, "1_》_500_2", "level3", "Navigator,\u{0020}have\u{0020}you\u{0020}been\u{0020}free\u{0020}lately?\u{0020}N-no,\u{0020}it's\u{0020}nothing\u{0020}especially\u{0020}important.\u{0020}Driver\u{0020}counseling...\u{0020}you're\u{0020}good\u{0020}at\u{0020}that,\u{0020}aren't\u{0020}you?", "ナビゲーターさん、近々お時間ありますか？いえ、特に重要なことではありません。ドライバーの心理カウンセリング……ナビゲーターさんはお得意ですよね？", "0", "0", "0", "0", "cv_feilin_10", "0", "0"},
[422510] = {422510, 12025, 11, 5, "1_》_1000_2.5", "level4", "Navigator,\u{0020}could\u{0020}you\u{0020}cancel\u{0020}your\u{0020}plans\u{0020}for\u{0020}tonight?\u{0020}Yes,\u{0020}I\u{0020}know\u{0020}you\u{0020}already\u{0020}had\u{0020}plans\u{0020}with\u{0020}another\u{0020}driver,\u{0020}but\u{0020}there's\u{0020}something\u{0020}very\u{0020}important\u{0020}I\u{0020}need\u{0020}to\u{0020}talk\u{0020}to\u{0020}you\u{0020}about\u{0020}-\u{0020}it's\u{0020}about\u{0020}love,\u{0020}about\u{0020}drivers\u{0020}and\u{0020}Navigators...\u{0020}about\u{0020}ordinary\u{0020}people\u{0020}and\u{0020}empathic\u{0020}resonators...\u{0020}I\u{0020}need\u{0020}romantic\u{0020}advice.", "ナビゲーターさん、今晩の予定をキャンセルできますか？はい、他のドライバーとの約束があるのは知っていますが、重要なお話があります——恋愛についてです。ドライバーとナビゲーターのこと……一般人と通感覚者のことについての……恋愛相談です。", "0", "0", "0", "0", "cv_feilin_11", "0", "0"},
[422511] = {422511, 12025, 12, 6, "0", "0", "I've\u{0020}gotten\u{0020}stronger.", "私、強くなりました。", "0", "0", "0", "0", "cv_feilin_12", "0", "0"},
