[422516] = {422516, 12025, 17, 11, "0", "0", "I\u{0020}did\u{0020}it,\u{0020}Navigator!\u{0020}That's\u{0020}wonderful!\u{0020}From\u{0020}now\u{0020}on,\u{0020}every\u{0020}battle\u{0020}has\u{0020}to\u{0020}go\u{0020}like\u{0020}this\u{0020}one\u{0020}did!", "良かった、ナビゲーターさん、私やりました！次の戦闘も今回のように頑張ります！", "0", "0", "0", "0", "cv_feilin_17", "0", "0"},
[422517] = {422517, 12025, 18, 12, "0", "0", "We\u{0020}can\u{0020}still\u{0020}do\u{0020}better.\u{0020}We\u{0020}can\u{0020}do\u{0020}even\u{0020}better,\u{0020}Navigator.", "もっと上手くできるはずです、私たちならはもっと上手くやれます、ナビゲーターさん。", "0", "0", "0", "0", "cv_feilin_18", "0", "0"},
