[422526] = {422526, 12025, 28, 21, "0", "0", "I'm\u{0020}only\u{0020}here\u{0020}because\u{0020}empathic\u{0020}resonance\u{0020}helps\u{0020}relieve\u{0020}a\u{0020}driver's\u{0020}fatigue\u{0020}-\u{0020}that\u{0020}excuse\u{0020}sounds\u{0020}way\u{0020}too\u{0020}suspicious.\u{0020}No\u{0020}one's\u{0020}going\u{0020}to\u{0020}believe\u{0020}that.", "「通感覚を使ってドライバーの疲れを癒すためにここにいる」という説明は、怪しすぎます。誰も信じませんよ。", "0", "0", "0", "0", "cv_feilin_28", "0", "0"},
[422527] = {422527, 12025, 29, 21, "0", "0", "I'm\u{0020}not\u{0020}embarrassed.\u{0020}This\u{0020}body\u{0020}is\u{0020}just\u{0020}a\u{0020}manifested\u{0020}form\u{0020}anyway,\u{0020}so\u{0020}even\u{0020}if\u{0020}you\u{0020}touch\u{0020}me,\u{0020}it\u{0020}won't\u{0020}really\u{0020}matter...\u{0020}Ugh,\u{0020}don't\u{0020}actually\u{0020}start\u{0020}touching\u{0020}me\u{0020}all\u{0020}over\u{0020}the\u{0020}place!\u{0020}That's\u{0020}bullying!", "恥ずかしくないですよ。今は幻化の体ですから、ナビゲーターさんが触っても大丈夫です……うぅ、本当にあちこち触らないでください、それは意地悪です！", "0", "0", "0", "0", "cv_feilin_29", "0", "0"},
[422528] = {422528, 12025, 30, 22, "0", "0", "What\u{0020}happened!?", "何が起きましたか！？", "0", "0", "0", "0", "cv_feilin_30", "0", "0"},
[422529] = {422529, 12025, 31, 23, "0", "0", "Want\u{0020}to\u{0020}guess?\u{0020}Can\u{0020}I\u{0020}give\u{0020}you\u{0020}a\u{0020}hint?\u{0020}Hmm...\u{0020}\"glasses\".\u{0020}How\u{0020}about\u{0020}that\u{0020}hint?\u{0020}Can\u{0020}you\u{0020}guess\u{0020}now?", "当ててみますか？ヒントをあげましょうか？うーん……「眼鏡」、このヒントでどうですか？当てられますか？", "0", "0", "0", "0", "cv_feilin_31", "0", "0"},
[422530] = {422530, 12025, 32, 24, "0", "0", "Phew...\u{0020}that's\u{0020}a\u{0020}relief.\u{0020}I\u{0020}was\u{0020}worried\u{0020}you\u{0020}might\u{0020}forget\u{0020}about\u{0020}me,\u{0020}Navigator.", "ふぅ……ほっとしました。ナビゲーターさんが私を忘れたのかと思いました。", "0", "0", "0", "0", "cv_feilin_32", "0", "0"},
