[422532] = {422532, 12025, 34, 26, "0", "0", "Welcome\u{0020}back!\u{0020}Would\u{0020}you\u{0020}like\u{0020}to\u{0020}take\u{0020}a\u{0020}short\u{0020}break\u{0020}before\u{0020}getting\u{0020}back\u{0020}to\u{0020}work?", "お帰りなさい！少し休憩してから仕事を始めますか？", "0", "0", "0", "0", "cv_feilin_34", "0", "0"},
