[422601] = {422601, 12026, 2, 2, "0", "0", "Please\u{0020}leave\u{0020}it\u{0020}to\u{0020}me.\u{0020}Protecting\u{0020}the\u{0020}boss\u{0020}is\u{0020}my\u{0020}duty\u{0020}as\u{0020}your\u{0020}subordinate!", "安心して私にお任せください、親分の身の安全を確保することこそ、私の義務ですから。", "0", "0", "0", "0", "cv_lyfa2_2", "0", "0"},
[422602] = {422602, 12026, 3, 3, "0", "0", "Miss\u{0020}Lyfa\u{0020}of\u{0020}Valkyrie\u{0020}-\u{0020}that's\u{0020}me\u{0020}-\u{0020}has\u{0020}come\u{0020}to\u{0020}bother\u{0020}you\u{0020}again!\u{0020}Is\u{0020}our\u{0020}target\u{0020}this\u{0020}time\u{0020}to\u{0020}take\u{0020}down\u{0020}Aegis?", "ワルキューレのリーファさん――つまり私――この度もお邪魔することになりました！今回の目標は打倒アイギスでしょうか？", "0", "0", "0", "0", "cv_lyfa2_3", "0", "0"},
[422603] = {422603, 12026, 4, 4, "0", "idle", "Navigator!\u{0020}Do\u{0020}you\u{0020}know\u{0020}what\u{0020}works\u{0020}I\u{0020}should\u{0020}read\u{0020}if\u{0020}I\u{0020}want\u{0020}to\u{0020}learn\u{0020}more\u{0020}about\u{0020}biker\u{0020}culture?\u{0020}Even\u{0020}if\u{0020}this\u{0020}is\u{0020}only\u{0020}temporary,\u{0020}I\u{0020}still\u{0020}think\u{0020}it's\u{0020}necessary\u{0020}to\u{0020}understand\u{0020}it\u{0020}a\u{0020}little.", "ナビゲーターさん、バイクの文化について知りたいなら、どんな作品を読めばいいですか？一時的な興味でも、ちゃんと理解しておくのは大事ですからね。", "0", "0", "0", "0", "cv_lyfa2_4", "0", "0"},
[422604] = {422604, 12026, 5, 4, "0", "idle", "Navigator,\u{0020}is\u{0020}there\u{0020}anywhere\u{0020}you'd\u{0020}like\u{0020}to\u{0020}go\u{0020}this\u{0020}weekend?\u{0020}I\u{0020}can\u{0020}give\u{0020}you\u{0020}a\u{0020}ride!\u{0020}Don't\u{0020}worry,\u{0020}I\u{0020}won't\u{0020}speed!", "ナビゲーターさん、週末に行きたい場所はありますか？私がお連れしますよ！安心してください、スピードは出しすぎませんから。", "0", "0", "0", "0", "cv_lyfa2_5", "0", "0"},
[422605] = {422605, 12026, 6, 4, "0", "idle", "I\u{0020}designed\u{0020}this\u{0020}gear\u{0020}myself.\u{0020}When\u{0020}Captain\u{0020}Alvitr\u{0020}found\u{0020}out,\u{0020}she\u{0020}gave\u{0020}me\u{0020}a\u{0020}harsh\u{0020}scolding,\u{0020}saying\u{0020}that\u{0020}shoddy\u{0020}equipment\u{0020}would\u{0020}only\u{0020}disgrace\u{0020}Valkyrie...\u{0020}Seriously,\u{0020}couldn't\u{0020}she\u{0020}at\u{0020}least\u{0020}encourage\u{0020}me\u{0020}a\u{0020}little?", "この装備、実は私がデザインしたんです。アルヴィト隊長に見せたら、そんな無様な装備じゃ、ワルキューレの名に泥を塗るだけだって、すごく叱られちゃいました……。もう、少しは励ましてくれてもいいのに。", "0", "0", "0", "0", "cv_lyfa2_6", "0", "0"},
[422606] = {422606, 12026, 7, 5, "1_》_0_0.8", "level1", "Becoming\u{0020}a\u{0020}proper\u{0020}maid\u{0020}is\u{0020}my\u{0020}dream...\u{0020}it\u{0020}always\u{0020}has\u{0020}been,\u{0020}and\u{0020}it\u{0020}still\u{0020}is\u{0020}now.\u{0020}But\u{0020}while\u{0020}pursuing\u{0020}that\u{0020}dream,\u{0020}it's\u{0020}not\u{0020}a\u{0020}bad\u{0020}thing\u{0020}to\u{0020}occasionally\u{0020}stop\u{0020}and\u{0020}look\u{0020}at\u{0020}other\u{0020}scenery\u{0020}too.", "プロのメイドになるのが私の夢なんです……ずっと前から、今でも。それでも、夢を追う途中で違う景色を眺めるのも悪くないですね。", "0", "0", "0", "0", "cv_lyfa2_7", "0", "0"},
[422607] = {422607, 12026, 8, 5, "1_》_0_0.8", "level1", "Doesn't\u{0020}it\u{0020}feel\u{0020}nice\u{0020}to\u{0020}the\u{0020}touch?\u{0020}This\u{0020}outfit\u{0020}was\u{0020}made\u{0020}with\u{0020}special\u{0020}materials\u{0020}I\u{0020}chose\u{0020}myself,\u{0020}so\u{0020}it\u{0020}feels\u{0020}amazing!", "この服、触ってみてください。特別な素材で作ったから、触り心地は最高ですよ！", "0", "0", "0", "0", "cv_lyfa2_8", "0", "0"},
[422608] = {422608, 12026, 9, 5, "1_》_100_1.5", "level2", "What\u{0020}is\u{0020}Valkyrie's\u{0020}mission?\u{0020}Why\u{0020}are\u{0020}you\u{0020}suddenly\u{0020}curious\u{0020}about\u{0020}that,\u{0020}Navigator?\u{0020}It's\u{0020}not\u{0020}really\u{0020}a\u{0020}secret,\u{0020}but\u{0020}saying\u{0020}it\u{0020}out\u{0020}loud\u{0020}is\u{0020}embarrassing.\u{0020}Simply,\u{0020}we\u{0020}eliminate\u{0020}all\u{0020}threats\u{0020}that\u{0020}might\u{0020}endanger\u{0020}human\u{0020}society\u{0020}while\u{0020}they're\u{0020}still\u{0020}in\u{0020}the\u{0020}cradle...\u{0020}just\u{0020}like\u{0020}superheroes.", "ワルキューレの任務、ですか？いきなりですね。秘密ってほどでもないんですけど……簡単に言うと、人類社会に脅威を与える可能性のある危機を未然に防ぐことです……まるでスーパーヒーローみたいでしょ。", "0", "0", "0", "0", "cv_lyfa2_9", "0", "0"},
[422609] = {422609, 12026, 10, 5, "1_》_500_2", "level3", "About\u{0020}what\u{0020}happened\u{0020}in\u{0020}Plait\u{0020}City...\u{0020}it\u{0020}might\u{0020}not\u{0020}be\u{0020}good\u{0020}for\u{0020}Miss\u{0020}Althea\u{0020}if\u{0020}I\u{0020}said\u{0020}it\u{0020}out\u{0020}loud,\u{0020}but\u{0020}in\u{0020}my\u{0020}heart,\u{0020}I\u{0020}thought\u{0020}it\u{0020}was\u{0020}really\u{0020}interesting.\u{0020}I\u{0020}hope\u{0020}next\u{0020}time,\u{0020}and\u{0020}the\u{0020}time\u{0020}after\u{0020}that,\u{0020}I\u{0020}can\u{0020}run\u{0020}into\u{0020}stories\u{0020}that\u{0020}interesting\u{0020}with\u{0020}you\u{0020}again,\u{0020}Navigator...\u{0020}It'd\u{0020}be\u{0020}nice\u{0020}if\u{0020}someone\u{0020}could\u{0020}write\u{0020}them\u{0020}into\u{0020}a\u{0020}book.", "プレート市の件……アルテアさんには悪いけど、私は楽しかったですよ。次も、その次も、ナビゲーターさんと一緒にそんな楽しい物語に出会えたら……誰かが本にしてくれたらいいのにね。", "0", "0", "0", "0", "cv_lyfa2_10", "0", "0"},
[422610] = {422610, 12026, 11, 5, "1_》_1000_2.5", "level4", "Navigator,\u{0020}you\u{0020}probably\u{0020}have\u{0020}no\u{0020}idea\u{0020}just\u{0020}how\u{0020}outstanding\u{0020}you\u{0020}are.\u{0020}No\u{0020}one\u{0020}truly\u{0020}knows\u{0020}the\u{0020}extent\u{0020}of\u{0020}your\u{0020}achievements\u{0020}or\u{0020}your\u{0020}efforts...\u{0020}So\u{0020}only\u{0020}when\u{0020}I've\u{0020}become\u{0020}someone\u{0020}worthy\u{0020}of\u{0020}standing\u{0020}beside\u{0020}you\u{0020}will\u{0020}I\u{0020}tell\u{0020}you\u{0020}everything\u{0020}that's\u{0020}in\u{0020}my\u{0020}heart...\u{0020}all\u{0020}of\u{0020}it.", "ナビゲーターさん、ご自分がどれだけ素晴らしいか、きっとご存じないでしょう。あなたの功績と努力を誰も知らない……だから、私もあなたにふさわしい存在になったら、心の中の想いを全部伝えたいと思います。", "0", "0", "0", "0", "cv_lyfa2_11", "0", "0"},
[422611] = {422611, 12026, 12, 6, "0", "0", "Thank\u{0020}you~", "ありがとうございます～", "0", "0", "0", "0", "cv_lyfa2_12", "0", "0"},
