[4202600101] = {4202600101, 12026001, 2, 2, "0", "0", "Please\u{0020}leave\u{0020}it\u{0020}to\u{0020}me.\u{0020}Protecting\u{0020}the\u{0020}boss\u{0020}is\u{0020}my\u{0020}duty\u{0020}as\u{0020}your\u{0020}subordinate!", "安心して私にお任せください、親分の身の安全を確保することこそ、私の義務ですから。", "0", "0", "0", "0", "cv_sk_lyfa2_2", "0", "0"},
[4202600102] = {4202600102, 12026001, 3, 3, "0", "0", "Miss\u{0020}Lyfa\u{0020}of\u{0020}Valkyrie\u{0020}-\u{0020}that's\u{0020}me\u{0020}-\u{0020}has\u{0020}come\u{0020}to\u{0020}bother\u{0020}you\u{0020}again!\u{0020}Is\u{0020}our\u{0020}target\u{0020}this\u{0020}time\u{0020}to\u{0020}take\u{0020}down\u{0020}Aegis?", "ワルキューレのリーファさん――つまり私――この度もお邪魔することになりました！今回の目標は打倒アイギスでしょうか？", "0", "0", "0", "0", "cv_sk_lyfa2_3", "0", "0"},
[4202600103] = {4202600103, 12026001, 91, 4, "0", "touch1", "How\u{0020}strange...\u{0020}where\u{0020}did\u{0020}things\u{0020}go\u{0020}wrong?\u{0020}Did\u{0020}I\u{0020}go\u{0020}a\u{0020}little\u{0020}overboard\u{0020}last\u{0020}time\u{0020}I\u{0020}rode?", "おかしいなあ……どこが問題だったんでしょう？もしかして、前回飛ばしすぎたせいかな？", "0", "0", "0", "0", "cv_sk_lyfa2_7", "0", "0,touch1"},
[4202600104] = {4202600104, 12026001, 91, 4, "0", "touch1", "Once\u{0020}the\u{0020}bike\u{0020}is\u{0020}fixed,\u{0020}let's\u{0020}go\u{0020}for\u{0020}a\u{0020}ride\u{0020}together.\u{0020}That\u{0020}feeling\u{0020}of\u{0020}leaving\u{0020}the\u{0020}wind\u{0020}behind\u{0020}and\u{0020}letting\u{0020}your\u{0020}mind\u{0020}go\u{0020}completely\u{0020}blank\u{0020}is\u{0020}addictive,\u{0020}I\u{0020}promise!", "バイクが直ったら、一緒にドライブに行きましょう！風を追い越して、頭を空っぽにする感覚、病みつきになりますよ、私が保証します！", "0", "0", "0", "0", "cv_sk_lyfa2_8", "0", "0,touch1"},
[4202600105] = {4202600105, 12026001, 91, 4, "0", "idle", "I\u{0020}often\u{0020}help\u{0020}out\u{0020}in\u{0020}the\u{0020}lab...\u{0020}but\u{0020}mechanical\u{0020}repairs\u{0020}really\u{0020}aren't\u{0020}my\u{0020}strong\u{0020}suit.\u{0020}Would\u{0020}it\u{0020}be\u{0020}better\u{0020}to\u{0020}ask\u{0020}the\u{0020}captain?", "私はよく研究室で手伝っていますけど、機械の修理はあまり得意じゃないんです。隊長にお願いするのがいいかもしれませんね。", "0", "0", "0", "0", "cv_sk_lyfa2_9", "0", "0,idle"},
[4202600106] = {4202600106, 12026001, 94, 4, "0", "touch2", "Wahhh,\u{0020}it's\u{0020}so\u{0020}chilly...\u{0020}what\u{0020}a\u{0020}strange\u{0020}feeling...", "あわわ、ひんやりして、変な感じです……", "0", "0", "0", "0", "cv_sk_lyfa2_13", "0", "0,touch2"},
[4202600107] = {4202600107, 12026001, 94, 4, "0", "touch2", "Huh?\u{0020}Navigator,\u{0020}you\u{0020}aren't\u{0020}planning\u{0020}to\u{0020}do\u{0020}anything...?\u{0020}No,\u{0020}it's\u{0020}not\u{0020}that\u{0020}I'm\u{0020}hoping\u{0020}you'll\u{0020}do\u{0020}something,\u{0020}but...\u{0020}isn't\u{0020}the\u{0020}mood\u{0020}kind\u{0020}of\u{0020}already\u{0020}there...?", "え、ナビゲーターさん、何もするつもりないんですか……いや、別に何かしてほしいわけじゃないんですけど……この雰囲気なら何かが起こるかと思ったのに……", "0", "0", "0", "0", "cv_sk_lyfa2_14", "0", "0,touch2"},
[4202600108] = {4202600108, 12026001, 94, 4, "0", "idle2", "Teasing\u{0020}someone\u{0020}and\u{0020}then\u{0020}just\u{0020}leaving\u{0020}them\u{0020}hanging...\u{0020}that's\u{0020}some\u{0020}kind\u{0020}of\u{0020}wicked\u{0020}hobby,\u{0020}right?\u{0020}I\u{0020}get\u{0020}it.", "人をからかった後に放置するのは、ちょっと悪趣味なやり方ですね。わかってます。", "0", "0", "0", "0", "cv_sk_lyfa2_15", "0", "0,idle2"},
[4202600109] = {4202600109, 12026001, 94, 5, "0", "touch3", "As\u{0020}long\u{0020}as\u{0020}I\u{0020}ride\u{0020}my\u{0020}motorcycle,\u{0020}I\u{0020}can\u{0020}go\u{0020}anywhere.\u{0020}I'm\u{0020}sure\u{0020}I\u{0020}can\u{0020}even\u{0020}reach\u{0020}your\u{0020}heart,\u{0020}Navigator.", "バイクに乗れば、例えナビゲーターさんの心の奥底でもひとっ走りで着きますね。", "0", "0", "0", "0", "cv_sk_lyfa2_5", "0", "0,touch3"},
[4202600110] = {4202600110, 12026001, 94, 5, "0", "idle3", "Close\u{0020}skin-to-skin\u{0020}contact\u{0020}can\u{0020}help\u{0020}people\u{0020}understand\u{0020}each\u{0020}other's\u{0020}thoughts\u{0020}more\u{0020}deeply.\u{0020}Do\u{0020}you\u{0020}think\u{0020}that\u{0020}would\u{0020}work\u{0020}with\u{0020}motorcycles\u{0020}too?\u{0020}Oh,\u{0020}Navigator,\u{0020}want\u{0020}to\u{0020}try\u{0020}it?\u{0020}No,\u{0020}not\u{0020}the\u{0020}motorcycle—I\u{0020}mean\u{0020}with\u{0020}me~", "スキンシップによってお互いの考えをもっと深く理解できるんです。これバイクにも通用するでしょうか？そうだ、ナビゲーターさんも試してみますか？む～、バイクじゃなくて、私とですけど～", "0", "0", "0", "0", "cv_sk_lyfa2_6", "0", "0,idle3"},
[4202600111] = {4202600111, 12026001, 94, 5, "0", "touch3", "Uuuh—it's\u{0020}not\u{0020}that\u{0020}I\u{0020}dislike\u{0020}it,\u{0020}it's\u{0020}just\u{0020}a\u{0020}little\u{0020}ticklish...\u{0020}If\u{0020}I\u{0020}had\u{0020}to\u{0020}say,\u{0020}it\u{0020}even\u{0020}feels\u{0020}kind\u{0020}of\u{0020}nice?\u{0020}The\u{0020}timing\u{0020}just\u{0020}isn't\u{0020}quite\u{0020}right...", "ううん、嫌じゃないんですけど、ちょっとくすぐったいです……どちらかというと、少し気持ちいいかも？でも何事にも節度というものが……", "0", "0", "0", "0", "cv_sk_lyfa2_12", "0", "0,touch3"},
