[4202600130] = {4202600130, 12026001, 27, 20, "0", "0", "To\u{0020}think\u{0020}I've\u{0020}troubled\u{0020}Navigator\u{0020}into\u{0020}hosting\u{0020}me\u{0020}again...\u{0020}I'll\u{0020}just\u{0020}have\u{0020}to\u{0020}kneel\u{0020}and\u{0020}apologize\u{0020}later!", "またナビゲーターさんに迷惑をかけちゃって……これはもう土下座してお詫びするしか！", "0", "0", "0", "0", "cv_sk_lyfa2_31", "0", "0"},
[4202600131] = {4202600131, 12026001, 28, 21, "0", "0", "I'll\u{0020}gladly\u{0020}enjoy\u{0020}your\u{0020}hospitality\u{0020}with\u{0020}a\u{0020}grateful\u{0020}heart,\u{0020}Navigator.\u{0020}Thank\u{0020}you!", "ナビゲーターさんのサービスに感謝しながら、楽しませていただきますね、ありがとうございます！", "0", "0", "0", "0", "cv_sk_lyfa2_32", "0", "0"},
