[4001100200] = {4001100200, 10011002, 1, 1, "0", "0", "Haze\u{0020}reverb.", "苍雾残响（ハツリバーブ）。", "0", "0", "苍雾残响。", "0", "cv_ruoshui_32", "0", "0"},
[4001100201] = {4001100201, 10011002, 2, 2, "0", "0", "Yes,\u{0020}I'll\u{0020}always\u{0020}be\u{0020}here,\u{0020}waiting\u{0020}for\u{0020}your\u{0020}next\u{0020}order,\u{0020}Navigator.", "はい、次の命令までここで待ってますね。ナビゲーターのお兄さん。", "0", "0", "是，我会一直站在这等待您下一个命令的，领航哥哥。", "0", "cv_ruoshui_2", "0", "0"},
[4001100202] = {4001100202, 10011002, 3, 3, "0", "0", "My\u{0020}name\u{0020}is\u{0020}Jacksui...\u{0020}My\u{0020}eyes?\u{0020}It\u{0020}doesn't\u{0020}matter.\u{0020}As\u{0020}long\u{0020}as\u{0020}I\u{0020}can\u{0020}see\u{0020}you,\u{0020}Brother\u{0020}Navigator.", "私の名前は弱水です。……私の目ですか？大丈夫です。ちゃんと见えてますよ、ナビゲーターのお兄さん。", "0", "0", "我的名字是弱水…眼睛？没关系，我能看见您的，领航哥哥。", "0", "cv_ruoshui_1", "0", "0"},
[4001100203] = {4001100203, 10011002, 91, 4, "0", "idle", "My\u{0020}eyes...\u{0020}even\u{0020}though\u{0020}I\u{0020}can\u{0020}see,\u{0020}it\u{0020}feels\u{0020}like\u{0020}the\u{0020}\"world\"\u{0020}I\u{0020}see\u{0020}is\u{0020}different\u{0020}from\u{0020}everyone\u{0020}else’s…\u{0020}But\u{0020}I\u{0020}guess\u{0020}there's\u{0020}nothing\u{0020}I\u{0020}can\u{0020}do\u{0020}about\u{0020}that.", "见えてはいるのですが、皆さんが见ている世界とは违うのだそうです。……まあ、それも仕方ないですね。", "0", "0", "我的眼睛…虽然看得见，但是好像和大家看到的“世界”不一样…不过这也是没办法的事吧？", "0", "cv_ruoshui_3", "0", "idle,idle"},
[4001100204] = {4001100204, 10011002, 94, 4, "0", "idle2", "Brother\u{0020}Navigator,\u{0020}did\u{0020}you\u{0020}catch\u{0020}that\u{0020}TV\u{0020}drama\u{0020}yesterday?\u{0020}It\u{0020}wasn’t\u{0020}the\u{0020}best,\u{0020}but\u{0020}their\u{0020}passion\u{0020}to\u{0020}make\u{0020}something\u{0020}good\u{0020}really\u{0020}moved\u{0020}me!\u{0020}Huh?\u{0020}You\u{0020}didn’t\u{0020}watch\u{0020}it?", "ナビゲーターのお兄さん、昨日のテレビドラマは见ましたか？色々な意味で最悪なドラマでしたが、良い作品を作ろうという姿势にすごく感动したんです！えぇ？见てないんですか！？", "0", "0", "领航哥哥，昨天的电视剧你看了吗？那部电视剧虽然各种地方都很烂，但他们想要拍好一部作品的决心却让我超感动的！诶？没看吗？", "0", "cv_ruoshui_4", "0", "idle2,idle2"},
[4001100205] = {4001100205, 10011002, 94, 4, "0", "idle2", "Meika!\u{0020}Meika!\u{0020}Hmm?\u{0020}She's\u{0020}not\u{0020}here...\u{0020}Whenever\u{0020}she\u{0020}doesn’t\u{0020}have\u{0020}a\u{0020}mission,\u{0020}it’s\u{0020}like\u{0020}she\u{0020}vanishes.\u{0020}So\u{0020}mysterious…\u{0020}I\u{0020}wanted\u{0020}to\u{0020}hang\u{0020}out\u{0020}with\u{0020}her!", "冥火ー？冥火ー？あれ？いない……任务がないとすぐいなくなっちゃうんだから。……一绪に游ぼうって思ってたのに！", "0", "0", "冥火！冥火！嗯？她不在这里吗…诶，她只要没有任务的时候，感觉就跟消失了一样，真神秘呢…我还想找她玩呢！", "0", "cv_ruoshui_29", "0", "idle2,idle2"},
[4001100206] = {4001100206, 10011002, 92, 5, "1_》_0_0.8", "touch1", "In\u{0020}the\u{0020}past...\u{0020}I\u{0020}lost\u{0020}my\u{0020}sight,\u{0020}along\u{0020}with\u{0020}my\u{0020}friends\u{0020}and\u{0020}family.\u{0020}But\u{0020}that’s\u{0020}all\u{0020}behind\u{0020}me\u{0020}now.\u{0020}Now,\u{0020}I\u{0020}just\u{0020}want\u{0020}to\u{0020}do\u{0020}my\u{0020}best\u{0020}to\u{0020}help\u{0020}everyone!", "ここに来る前に……视力も、友达も、家族も失いました。……でも、それはもう过ぎたことです。今はただ、出来る限りみんなの助けになりたいんです！", "0", "0", "以前…因为一些原因，我失去了视力，也因此失去了自己的朋友和家人…不过，一切都过去了，现在的我，只想尽自己所能地帮助大家！", "0", "cv_ruoshui_30", "0", "touch1,touch1"},
[4001100207] = {4001100207, 10011002, 92, 5, "1_》_0_0.8", "touch2", "My\u{0020}eye\u{0020}patch\u{0020}is\u{0020}not\u{0020}a\u{0020}play\u{0020}toy,\u{0020}Brother\u{0020}Navigator!", "ちょっと、眼帯に…胜手に触らないでください！", "0", "0", "领航哥哥，眼罩…您别乱碰它呀！", "0", "cv_ruoshui_5", "0", "touch2,touch2"},
[4001100208] = {4001100208, 10011002, 95, 5, "1_》_0_0.8", "touch3", "Brother\u{0020}Navigator!\u{0020}Let's\u{0020}go\u{0020}out\u{0020}and\u{0020}have\u{0020}some\u{0020}fun.\u{0020}I\u{0020}want\u{0020}to\u{0020}go\u{0020}to\u{0020}the\u{0020}amusement\u{0020}park!", "お兄さんお兄さん、一绪に出かけましょう。游园地がいいです！", "0", "0", "哥哥，哥哥，我们一起出去玩吧，我想去游乐场玩！", "0", "cv_ruoshui_6", "0", "touch3,touch3"},
[4001100209] = {4001100209, 10011002, 95, 5, "1_》_0_0.8", "touch4", "Hey,\u{0020}Brother\u{0020}Navigator,\u{0020}let's\u{0020}go\u{0020}to\u{0020}the\u{0020}movies.\u{0020}First,\u{0020}we'll\u{0020}need\u{0020}to\u{0020}get\u{0020}drinks\u{0020}and\u{0020}popcorn...\u{0020}Eh,\u{0020}like\u{0020}a\u{0020}date?\u{0020}A\u{0020}date,\u{0020}huh...\u{0020}that\u{0020}wouldn't\u{0020}be\u{0020}impossible.", "お兄さん、一绪に映画を见に行きましょう。まず饮み物とポップコーンを买って……え、デートみたい？……デ、デートはダメ……じゃないですけど……", "0", "0", "哥哥，我们一起去看电影吧，首先要做的是去买饮料、爆米花…诶，像约会一样？……约、约会的话，也不是不行啦。", "0", "cv_ruoshui_7", "0", "touch4,touch4"},
[4001100210] = {4001100210, 10011002, 93, 5, "1_》_0_0.8", "switch1", "Whenever\u{0020}I'm\u{0020}with\u{0020}you,\u{0020}it's\u{0020}like\u{0020}I\u{0020}don’t\u{0020}have\u{0020}to\u{0020}worry\u{0020}about\u{0020}being\u{0020}betrayed\u{0020}or\u{0020}you\u{0020}suddenly\u{0020}disappearing...\u{0020}and\u{0020}that’s\u{0020}enough\u{0020}for\u{0020}me.\u{0020}Please\u{0020}stay\u{0020}with\u{0020}me\u{0020}from\u{0020}forever,\u{0020}I\u{0020}can't\u{0020}stand\u{0020}a\u{0020}moment\u{0020}apart\u{0020}from\u{0020}you.", "お兄さんがナビゲーターなら、私を里切ったり、ある日突然消えちゃうこともないですよね。……それで十分です。これからもずっと私のそばに居てください。私……お兄さんと离れるのは嫌なんです。", "0", "0", "是领航您的话，我不用担心被背叛，也不用担心你会突然消失吧…这样就足够了。领航，之后也请您一直陪着我吧，我…不想和您分开。", "0", "cv_ruoshui_8", "0", "switch1,switch1"},
[4001100211] = {4001100211, 10011002, 96, 5, "1_》_0_0.8", "switch2", "Whenever\u{0020}I'm\u{0020}with\u{0020}you,\u{0020}it's\u{0020}like\u{0020}I\u{0020}don’t\u{0020}have\u{0020}to\u{0020}worry\u{0020}about\u{0020}being\u{0020}betrayed\u{0020}or\u{0020}you\u{0020}suddenly\u{0020}disappearing...\u{0020}and\u{0020}that’s\u{0020}enough\u{0020}for\u{0020}me.\u{0020}Please\u{0020}stay\u{0020}with\u{0020}me\u{0020}from\u{0020}forever,\u{0020}I\u{0020}can't\u{0020}stand\u{0020}a\u{0020}moment\u{0020}apart\u{0020}from\u{0020}you.", "お兄さんがナビゲーターなら、私を里切ったり、ある日突然消えちゃうこともないですよね。……それで十分です。これからもずっと私のそばに居てください。私……お兄さんと离れるのは嫌なんです。", "0", "0", "是领航您的话，我不用担心被背叛，也不用担心你会突然消失吧…这样就足够了。领航，之后也请您一直陪着我吧，我…不想和您分开。", "0", "cv_ruoshui_8", "0", "switch2,switch2"},
[4001100212] = {4001100212, 10011002, 12, 6, "0", "0", "I\u{0020}leveled\u{0020}up!", "レベルアップしましたよ！", "0", "0", "我升级了诶！", "0", "cv_ruoshui_9", "0", "0"},
[4001100213] = {4001100213, 10011002, 13, 7, "0", "0", "The\u{0020}weapon's\u{0020}sharper!", "武器が鋭くなりました！", "0", "0", "武器变锋利了！", "0", "cv_ruoshui_10", "0", "0"},
[4001100214] = {4001100214, 10011002, 14, 8, "0", "0", "This\u{0020}is\u{0020}amazing...\u{0020}Power\u{0020}just\u{0020}keeps\u{0020}surging\u{0020}through\u{0020}me.\u{0020}Hmm,\u{0020}I've\u{0020}decided—this\u{0020}strength\u{0020}is\u{0020}for\u{0020}you,\u{0020}Navigator.\u{0020}From\u{0020}now\u{0020}on,\u{0020}no\u{0020}matter\u{0020}who\u{0020}the\u{0020}enemy\u{0020}is,\u{0020}\"Jacksui\"\u{0020}will\u{0020}take\u{0020}them\u{0020}down\u{0020}for\u{0020}you!", "不思议……力がどんどん涌いてきます。うん、决めました。この力、この强さはお兄さんだけのものです。これからどんな敌が现れようとも、お兄さんのために弱水が倒して见せます！", "0", "0", "真是不可思议呢…力量在源源不断地涌出。嗯，决定了，这份力量，这份强大，只为领航您而存在。今后，不管是什么样的敌人，“弱水”都会为了您，将他击溃！", "0", "cv_ruoshui_11", "0", "0"},
[4001100215] = {4001100215, 10011002, 15, 9, "0", "0", "I'm\u{0020}faster\u{0020}now!", "もっと速くなりました！", "0", "0", "速度变快了！", "0", "cv_ruoshui_12", "0", "0"},
[4001100216] = {4001100216, 10011002, 16, 10, "0", "0", "Got\u{0020}it.\u{0020}Let's\u{0020}start\u{0020}the\u{0020}operation.", "了解、作戦开始。", "0", "0", "了解，作战开始。", "0", "cv_ruoshui_13", "0", "0"},
[4001100217] = {4001100217, 10011002, 17, 11, "0", "0", "Mission\u{0020}complete—Navigator,\u{0020}let's\u{0020}head\u{0020}back.", "任务完了。……帰りましょう、お兄さん。", "0", "0", "任务完成——领航，我们回去吧。", "0", "cv_ruoshui_14", "0", "0"},
[4001100218] = {4001100218, 10011002, 18, 12, "0", "0", "I'm\u{0020}fine...\u{0020}But\u{0020}there\u{0020}are\u{0020}others\u{0020}who\u{0020}need\u{0020}medical\u{0020}attention,\u{0020}Navigator.", "大丈夫です……私より、负伤者の方を……お兄さん……", "0", "0", "我没事…但是有伤员需要治疗，领航。", "0", "cv_ruoshui_15", "0", "0"},
[4001100219] = {4001100219, 10011002, 19, 13, "0", "0", "Everyone...\u{0020}Are\u{0020}you\u{0020}all\u{0020}okay?", "みなさん…无事ですか？", "0", "0", "大家…还好吗？", "0", "cv_ruoshui_16", "0", "0"},
