[4102900201] = {4102900201, 11029002, 2, 2, "0", "0", "Even\u{0020}the\u{0020}president\u{0020}of\u{0020}the\u{0020}student\u{0020}council\u{0020}can't\u{0020}escape\u{0020}being\u{0020}on\u{0020}duty.", "生徒会长も例外なく、日直を担当します。", "0", "0", "0", "0", "cv_qianmo_2", "0", "0"},
[4102900202] = {4102900202, 11029002, 3, 3, "0", "0", "Good\u{0020}morning,\u{0020}Mr.\u{0020}Navigator.\u{0020}Senhaku\u{0020}of\u{0020}the\u{0020}Fledgeling\u{0020}Eagle\u{0020}reporting\u{0020}for\u{0020}duty.\u{0020}I'll\u{0020}be\u{0020}relying\u{0020}on\u{0020}you\u{0020}from\u{0020}now\u{0020}on.", "おはようございます、先生。雏鹰（ひなたか）所属の、千陌（せんはく）です。これからよろしくお愿いします。", "0", "0", "0", "0", "cv_qianmo_3", "0", "0"},
[4102900203] = {4102900203, 11029002, 91, 4, "0", "idle", "Is\u{0020}it\u{0020}within\u{0020}the\u{0020}regulations\u{0020}to\u{0020}give\u{0020}such\u{0020}advanced\u{0020}equipment\u{0020}to\u{0020}an\u{0020}intern?", "インターン生にこのような高性能の装备を与えて、问题はないのでしょうか？", "0", "0", "0", "0", "cv_qianmo_4", "0", "idle,idle"},
[4102900204] = {4102900204, 11029002, 94, 4, "0", "idle2", "According\u{0020}to\u{0020}the\u{0020}break\u{0020}schedule,\u{0020}it's\u{0020}almost\u{0020}break\u{0020}time.", "スケジュールによると、もうすぐ休憩时间です。", "0", "0", "0", "0", "cv_qianmo_5", "0", "idle2,idle2"},
[4102900205] = {4102900205, 11029002, 98, 4, "0", "idle3", "Honestly,\u{0020}I've\u{0020}always\u{0020}opposed\u{0020}the\u{0020}\"Fledgeling\u{0020}Eagle\u{0020}Project.\"\u{0020}Sending\u{0020}inexperienced\u{0020}students\u{0020}into\u{0020}battle\u{0020}is\u{0020}just\u{0020}rushing\u{0020}things.\u{0020}As\u{0020}it\u{0020}stands,\u{0020}only\u{0020}I\u{0020}and\u{0020}Karen\u{0020}at\u{0020}the\u{0020}academy\u{0020}are\u{0020}capable\u{0020}of\u{0020}performing\u{0020}real\u{0020}combat\u{0020}missions.", "私は「雏鹰プロジェクト」には反対です。戦闘経験のない学生を戦场に送るなど、助长抜苗（じょちょうばつびょう）でしかありません。现时点で実戦任务を遂行できるのは、私とカリンだけです。", "0", "0", "0", "0", "cv_qianmo_6", "0", "idle3,idle3"},
[4102900206] = {4102900206, 11029002, 92, 5, "1_》_0_0.8", "touch1", "Survival\u{0020}of\u{0020}the\u{0020}fittest\u{0020}may\u{0020}be\u{0020}the\u{0020}law\u{0020}of\u{0020}nature,\u{0020}but\u{0020}it's\u{0020}not\u{0020}the\u{0020}law\u{0020}of\u{0020}human\u{0020}development.\u{0020}So,\u{0020}even\u{0020}if\u{0020}Sin\u{0020}is\u{0020}a\u{0020}thousand\u{0020}times\u{0020}stronger\u{0020}than\u{0020}us,\u{0020}I\u{0020}will\u{0020}never\u{0020}bow\u{0020}my\u{0020}head.", "自然界においては弱肉强食が正しいのかもしれませんが、人类が発展したのは、それだけが理由ではないはずです。だからこそ、原罪が私たちの百倍、いえ、千倍强くとも屈することはありません。", "0", "0", "0", "0", "cv_qianmo_7", "0", "touch1,touch1"},
[4102900207] = {4102900207, 11029002, 95, 5, "1_》_0_0.8", "touch2", "Harassing\u{0020}students\u{0020}is\u{0020}a\u{0020}serious\u{0020}crime.\u{0020}Please\u{0020}think\u{0020}twice,\u{0020}sir.", "学生への迷惑行为は重大な犯罪です。慎重に考えてください。", "0", "0", "0", "0", "cv_qianmo_8", "0", "touch2,touch2"},
[4102900208] = {4102900208, 11029002, 106, 5, "1_》_0_0.8", "touch3", "It's\u{0020}work\u{0020}hours...\u{0020}if\u{0020}you\u{0020}want\u{0020}to\u{0020}complain,\u{0020}you\u{0020}can\u{0020}do\u{0020}it\u{0020}after\u{0020}we're\u{0020}done\u{0020}working,\u{0020}sir.", "仕事中です。愚痴を言いたければ、仕事が终わってからお闻きしましょう。", "0", "0", "0", "0", "cv_qianmo_9", "0", "touch3,touch3"},
[4102900209] = {4102900209, 11029002, 106, 5, "1_》_0_0.8", "touch4", "It's\u{0020}work\u{0020}hours...\u{0020}if\u{0020}you\u{0020}want\u{0020}to\u{0020}complain,\u{0020}you\u{0020}can\u{0020}do\u{0020}it\u{0020}after\u{0020}we're\u{0020}done\u{0020}working,\u{0020}sir.", "仕事中です。愚痴を言いたければ、仕事が终わってからお闻きしましょう。", "0", "0", "0", "0", "cv_qianmo_9", "0", "touch4,touch4"},
[4102900210] = {4102900210, 11029002, 93, 5, "1_》_0_0.8", "switch1", "What\u{0020}you\u{0020}said\u{0020}last\u{0020}time\u{0020}about\u{0020}Sin's\u{0020}movement\u{0020}patterns\u{0020}differs\u{0020}from\u{0020}what\u{0020}we\u{0020}learned\u{0020}in\u{0020}school.\u{0020}If\u{0020}we\u{0020}go\u{0020}by\u{0020}the\u{0020}textbook\u{0020}in\u{0020}combat,\u{0020}we'd\u{0020}likely\u{0020}suffer\u{0020}a\u{0020}major\u{0020}defeat.", "先生から教わった原罪の行动パターンは、学校で闻いたものとずいぶん违いますね……もし実戦で教科书通りに动いたら、あっさりと败北してしまうかもしれません……", "0", "0", "0", "0", "cv_qianmo_10", "0", "switch1,switch1"},
[4102900211] = {4102900211, 11029002, 102, 5, "1_》_0_0.8", "switch2", "Your\u{0020}knowledge\u{0020}and\u{0020}experience\u{0020}far\u{0020}surpass\u{0020}mine.\u{0020}Unfortunately,\u{0020}as\u{0020}an\u{0020}intern,\u{0020}I\u{0020}can't\u{0020}study\u{0020}under\u{0020}you\u{0020}for\u{0020}long.\u{0020}I\u{0020}hope\u{0020}that\u{0020}after\u{0020}I\u{0020}become\u{0020}a\u{0020}full\u{0020}Driver,\u{0020}we\u{0020}can\u{0020}continue\u{0020}to\u{0020}work\u{0020}together.", "先生の知识と経験は想象以上でした。もっと先生の元で学びたいのですが……インターン生ですから、残された时间は多くありません。将来、一人前のドライバーになって、先生と一绪に仕事をすることが私の目标です。", "0", "0", "0", "0", "cv_qianmo_11", "0", "switch2,switch2"},
[4102900212] = {4102900212, 11029002, 96, 5, "1_》_0_0.8", "switch3", "Your\u{0020}knowledge\u{0020}and\u{0020}experience\u{0020}far\u{0020}surpass\u{0020}mine.\u{0020}Unfortunately,\u{0020}as\u{0020}an\u{0020}intern,\u{0020}I\u{0020}can't\u{0020}study\u{0020}under\u{0020}you\u{0020}for\u{0020}long.\u{0020}I\u{0020}hope\u{0020}that\u{0020}after\u{0020}I\u{0020}become\u{0020}a\u{0020}full\u{0020}Driver,\u{0020}we\u{0020}can\u{0020}continue\u{0020}to\u{0020}work\u{0020}together.", "先生の知识と経験は想象以上でした。もっと先生の元で学びたいのですが……インターン生ですから、残された时间は多くありません。将来、一人前のドライバーになって、先生と一绪に仕事をすることが私の目标です。", "0", "0", "0", "0", "cv_qianmo_11", "0", "switch3,switch3"},
[4102900213] = {4102900213, 11029002, 12, 6, "0", "0", "Thank\u{0020}you\u{0020}for\u{0020}your\u{0020}guidance.", "教えに感谢します。", "0", "0", "0", "0", "cv_qianmo_12", "0", "0"},
[4102900214] = {4102900214, 11029002, 13, 7, "0", "0", "Talking\u{0020}with\u{0020}you,\u{0020}sir,\u{0020}really\u{0020}opens\u{0020}up\u{0020}my\u{0020}mind.", "先生との会话は、本当に得ることが多いです。", "0", "0", "0", "0", "cv_qianmo_13", "0", "0"},
[4102900215] = {4102900215, 11029002, 14, 8, "0", "0", "By\u{0020}the\u{0020}rules,\u{0020}this\u{0020}kind\u{0020}of\u{0020}power\u{0020}shouldn't\u{0020}be\u{0020}given\u{0020}to\u{0020}an\u{0020}intern\u{0020}driver.\u{0020}Does\u{0020}this\u{0020}mean,\u{0020}sir,\u{0020}that\u{0020}you\u{0020}already\u{0020}see\u{0020}me\u{0020}as\u{0020}a\u{0020}full-fledged\u{0020}driver?", "规定では、これはインターン生が持つべき力ではありません。先生の心の中では、私を一人前のドライバーと认めてくださったのですか？", "0", "0", "0", "0", "cv_qianmo_14", "0", "0"},
[4102900216] = {4102900216, 11029002, 15, 9, "0", "0", "Such\u{0020}a\u{0020}valuable\u{0020}gift,\u{0020}sir,\u{0020}you\u{0020}really\u{0020}didn't\u{0020}need\u{0020}to\u{0020}go\u{0020}all\u{0020}out.", "このように贵重なもの、いただけません。", "0", "0", "0", "0", "cv_qianmo_15", "0", "0"},
