[4102900218] = {4102900218, 11029002, 17, 11, "0", "0", "If\u{0020}we\u{0020}follow\u{0020}orders\u{0020}properly,\u{0020}winning\u{0020}will\u{0020}be\u{0020}as\u{0020}easy\u{0020}as\u{0020}flipping\u{0020}a\u{0020}coin.", "优れた指挥で、こうも简単に胜利できるとは。", "0", "0", "0", "0", "cv_qianmo_17", "0", "0"},
