[4001300200] = {4001300200, 10013002, 1, 1, "0", "0", "Haze\u{0020}reverb.", "苍雾残响（ハツリバーブ）。", "0", "0", "苍雾残响。", "0", "cv_lilith_31", "0", "0"},
[4001300201] = {4001300201, 10013002, 2, 2, "0", "0", "Why\u{0020}do\u{0020}you\u{0020}care\u{0020}so\u{0020}much\u{0020}about\u{0020}me?", "何故そんなに私のことが気になるの？", "0", "0", "为什么要这么在意我？", "0", "cv_lilith_2", "0", "0"},
[4001300202] = {4001300202, 10013002, 3, 3, "0", "0", "Ah,\u{0020}that\u{0020}familiar\u{0020}smell.\u{0020}You\u{0020}must\u{0020}be\u{0020}that\u{0020}real\u{0020}Synesthete.\u{0020}Let\u{0020}me\u{0020}make\u{0020}it\u{0020}clear,\u{0020}I\u{0020}hate\u{0020}all\u{0020}Synesthetes,\u{0020}including\u{0020}myself.", "ああ、懐かしい匂い…...あなたが真の通感覚者なのね。先に言っておくけど、私、通感覚者のことが嫌いなの。もちろん、私自身も含めて。", "0", "0", "啊，熟悉的味道啊。你就是那个真正的通感者吧。话先说在前面，我讨厌所有的通感者，当然也包括我自己。", "0", "cv_lilith_1", "0", "0"},
[4001300203] = {4001300203, 10013002, 91, 4, "0", "idle", "As\u{0020}a\u{0020}true\u{0020}Synesthete,\u{0020}you\u{0020}should\u{0020}be\u{0020}able\u{0020}to\u{0020}hear\u{0020}it\u{0020}too,\u{0020}right?\u{0020}Everyone's\u{0020}fear,\u{0020}hatred,\u{0020}and...\u{0020}despair.", "真の通感覚者のあなたなら、闻こえるんじゃない？みんなの恐怖、憎悪、そして……絶望。", "0", "0", "身为真正的通感者，你应该也能听得到吧？大家的恐惧，憎恨以及……绝望。", "0", "cv_lilith_3", "0", "0,idle"},
[4001300204] = {4001300204, 10013002, 94, 4, "0", "idle2", "Wasting\u{0020}time\u{0020}here\u{0020}is\u{0020}pointless.\u{0020}You\u{0020}know\u{0020}I'm\u{0020}your\u{0020}subordinate,\u{0020}just\u{0020}assign\u{0020}me\u{0020}a\u{0020}task\u{0020}already.", "ここで时间を费やしても意味がない。ここでは私はあなたの部下なのだから、早く指示を出してちょうだい。", "0", "0", "在这里浪费时间毫无意义，既然我是你的属下，就赶快给我布置任务吧。", "0", "cv_lilith_4", "0", "0,idle2"},
[4001300205] = {4001300205, 10013002, 98, 4, "0", "idle3", "Blueberry\u{0020}cake...\u{0020}Skadi,\u{0020}you\u{0020}secretly\u{0020}ate\u{0020}my\u{0020}blueberry\u{0020}cake\u{0020}again,\u{0020}didn't\u{0020}you?\u{0020}Don't\u{0020}pretend,\u{0020}I\u{0020}know\u{0020}exactly\u{0020}what's\u{0020}on\u{0020}your\u{0020}mind.", "スカディ、また私のブルーベリーケーキをこっそりつまみ食いしたでしょ？知らないふりをしたって无駄よ。何を考えてるのか、私には分かる。", "0", "0", "蓝莓蛋糕……斯卡蒂，你又偷偷吃了我的蓝莓蛋糕了吧？不要再装了，你心里想的我全都知道了。", "0", "cv_lilith_28", "0", "0,idle3"},
[4001300206] = {4001300206, 10013002, 92, 5, "1_》_0_0.8", "level1", "What's\u{0020}wrong?\u{0020}Is\u{0020}it\u{0020}strange\u{0020}that\u{0020}I\u{0020}like\u{0020}eating\u{0020}sweets?", "どうしたの？私がスイーツ好きなのが、そんなに惊くこと？", "0", "0", "怎么了？我喜欢吃甜食很奇怪吗？", "0", "cv_lilith_29", "0", "0,level1"},
[4001300207] = {4001300207, 10013002, 95, 5, "1_》_0_0.8", "level2", "If\u{0020}possible,\u{0020}just\u{0020}treat\u{0020}me\u{0020}as\u{0020}a\u{0020}tool.", "私を道具として使っていいよ。", "0", "0", "如果可以的话，将我当作是工具就好了。", "0", "cv_lilith_5", "0", "0,level2"},
[4001300208] = {4001300208, 10013002, 106, 5, "1_》_0_0.8", "level3", "Since\u{0020}you\u{0020}can\u{0020}also\u{0020}receive\u{0020}others'\u{0020}negative\u{0020}emotions,\u{0020}I\u{0020}suppose\u{0020}that\u{0020}makes\u{0020}us\u{0020}the\u{0020}same\u{0020}kind\u{0020}of\u{0020}Synesthete.", "もし、あなたも他人の负の感情を感じられると言うのなら、私たちは、通感覚者の中でも同类であると言えるね。", "0", "0", "既然你也能接受到他人的负面情感的话，那么我们姑且也能算作是通感者中的同类了吧。", "0", "cv_lilith_6", "0", "0,level3"},
[4001300209] = {4001300209, 10013002, 106, 5, "1_》_0_0.8", "level4", "Since\u{0020}you\u{0020}can\u{0020}also\u{0020}receive\u{0020}others'\u{0020}negative\u{0020}emotions,\u{0020}I\u{0020}suppose\u{0020}that\u{0020}makes\u{0020}us\u{0020}the\u{0020}same\u{0020}kind\u{0020}of\u{0020}Synesthete.", "もし、あなたも他人の负の感情を感じられると言うのなら、私たちは、通感覚者の中でも同类であると言えるね。", "0", "0", "既然你也能接受到他人的负面情感的话，那么我们姑且也能算作是通感者中的同类了吧。", "0", "cv_lilith_6", "0", "0,level4"},
[4001300210] = {4001300210, 10013002, 93, 5, "1_》_0_0.8", "switch1", "It\u{0020}must\u{0020}have\u{0020}been\u{0020}tough\u{0020}for\u{0020}you\u{0020}all\u{0020}this\u{0020}time.\u{0020}Even\u{0020}though\u{0020}I\u{0020}don’t\u{0020}understand\u{0020}why\u{0020}you\u{0020}still\u{0020}act\u{0020}indifferent\u{0020}about\u{0020}it.\u{0020}But\u{0020}I\u{0020}do\u{0020}know\u{0020}your\u{0020}pain,\u{0020}your\u{0020}guilt...", "辛いでしょ？あなたが何故そのようにどうでもいいみたいな态度をとってるのかは知らないけど。でも、私は知ってる。あなたの苦しみと自责の念……", "0", "0", "一直以来都很辛苦吧，虽然不清楚为什么你对此还是一副无所谓的态度。但是我很清楚，你的痛楚，你的自责……", "0", "cv_lilith_7", "0", "0,switch1"},
[4001300211] = {4001300211, 10013002, 102, 5, "1_》_0_0.8", "switch2", "We're...\u{0020}companions?\u{0020}Say\u{0020}whatever\u{0020}you\u{0020}want.\u{0020}I'm\u{0020}just\u{0020}your\u{0020}tool.\u{0020}But\u{0020}during\u{0020}battles,\u{0020}please\u{0020}stop\u{0020}using\u{0020}Synesthesia\u{0020}on\u{0020}me,\u{0020}I\u{0020}don't\u{0020}want\u{0020}your\u{0020}pain\u{0020}to\u{0020}double.", "同类じゃなくて仲间、か……胜手にすれば。私はただの道具だわ。あなたの道具。でも、戦ってる时は私に対して通感覚をしないで。あなたの苦しみを増やしたくないから。", "0", "0", "是同伴而不是同类吗……随便你怎么说吧，我只是你的工具而已。不过在战斗的时候还请不要再对我使用通感了，我可不希望你的痛苦翻倍。", "0", "cv_lilith_8", "0", "0,switch2"},
[4001300212] = {4001300212, 10013002, 96, 5, "1_》_0_0.8", "switch3", "We're...\u{0020}companions?\u{0020}Say\u{0020}whatever\u{0020}you\u{0020}want.\u{0020}I'm\u{0020}just\u{0020}your\u{0020}tool.\u{0020}But\u{0020}during\u{0020}battles,\u{0020}please\u{0020}stop\u{0020}using\u{0020}Synesthesia\u{0020}on\u{0020}me,\u{0020}I\u{0020}don't\u{0020}want\u{0020}your\u{0020}pain\u{0020}to\u{0020}double.", "同类じゃなくて仲间、か……胜手にすれば。私はただの道具だわ。あなたの道具。でも、戦ってる时は私に対して通感覚をしないで。あなたの苦しみを増やしたくないから。", "0", "0", "是同伴而不是同类吗……随便你怎么说吧，我只是你的工具而已。不过在战斗的时候还请不要再对我使用通感了，我可不希望你的痛苦翻倍。", "0", "cv_lilith_8", "0", "0,switch3"},
[4001300213] = {4001300213, 10013002, 12, 6, "0", "0", "That's\u{0020}right,\u{0020}just\u{0020}keep\u{0020}going\u{0020}like\u{0020}this.", "そう、こうやって続けて。", "0", "0", "没错，就这样继续下去吧。", "0", "cv_lilith_9", "0", "0"},
[4001300214] = {4001300214, 10013002, 13, 7, "0", "0", "Very\u{0020}good...\u{0020}So\u{0020}my\u{0020}illness\u{0020}can\u{0020}be\u{0020}cured\u{0020}this\u{0020}way,\u{0020}right?", "良いわね…...これなら私の病もきっと治るわ……", "0", "0", "很好……这么一来我的病就能痊愈了吧……", "0", "cv_lilith_10", "0", "0"},
[4001300215] = {4001300215, 10013002, 14, 8, "0", "0", "No\u{0020}matter\u{0020}how\u{0020}hard\u{0020}I\u{0020}try,\u{0020}I\u{0020}can't\u{0020}escape\u{0020}my\u{0020}identity\u{0020}as\u{0020}a\u{0020}Synesthete.\u{0020}But\u{0020}those\u{0020}annoying\u{0020}voices\u{0020}seem\u{0020}to\u{0020}have\u{0020}softened...\u{0020}I\u{0020}can\u{0020}hear\u{0020}other\u{0020}sounds\u{0020}now,\u{0020}the\u{0020}blessings,\u{0020}the\u{0020}thanks,\u{0020}and\u{0020}the\u{0020}prayers\u{0020}sung\u{0020}by\u{0020}the\u{0020}children.", "やっぱり、何をやっても通感覚者という身分から逃れられないのね……でも、最近あの嫌な声が柔らかくなった気がする……私、他の声が闻こえるようになったみたいだわ。子供たちの祝福、感谢、そして……祈りの歌声。", "0", "0", "果然，无论怎么样都无法摆脱通感者的身份吗……只是，那些让人讨厌的声音好像变得柔和了……我好像能听到其他的声音了。孩子们的祝福，感谢以及……祈祷的歌声。", "0", "cv_lilith_11", "0", "0"},
[4001300216] = {4001300216, 10013002, 15, 9, "0", "0", "The\u{0020}electric\u{0020}current\u{0020}has\u{0020}increased.", "电流の量が上がったわ。", "0", "0", "电流量提升了呢。", "0", "cv_lilith_12", "0", "0"},
[4001300217] = {4001300217, 10013002, 16, 10, "0", "0", "So\u{0020}annoying.", "嫌だわ。", "0", "0", "真讨厌啊。", "0", "cv_lilith_13", "0", "0"},
[4001300218] = {4001300218, 10013002, 17, 11, "0", "0", "Don't\u{0020}rush\u{0020}to\u{0020}thank\u{0020}me.", "感谢など、要らないわ。", "0", "0", "不用急着感谢我。", "0", "cv_lilith_14", "0", "0"},
[4001300219] = {4001300219, 10013002, 18, 12, "0", "0", "I've\u{0020}already\u{0020}told\u{0020}you,\u{0020}there's\u{0020}no\u{0020}problem.", "だから言ったでしょ？大丈夫だって。", "0", "0", "都和你说过了，没问题的。", "0", "cv_lilith_15", "0", "0"},
[4001300220] = {4001300220, 10013002, 19, 13, "0", "0", "Um,\u{0020}how\u{0020}should\u{0020}I\u{0020}put\u{0020}this?\u{0020}It\u{0020}was\u{0020}a\u{0020}narrow\u{0020}escape.", "…うん、なんていうか、ギリギリだったのね。", "0", "0", "嗯，怎么说呢，有惊无险吧。", "0", "cv_lilith_16", "0", "0"},
[4001300221] = {4001300221, 10013002, 20, 14, "0", "0", "Ah...\u{0020}those\u{0020}hateful\u{0020}voices...\u{0020}are\u{0020}they\u{0020}back\u{0020}again?", "ああ……例の嫌な声がまた……", "0", "0", "啊……那些讨厌的声音…又出现了吗。", "0", "cv_lilith_17", "0", "0"},
[4001300222] = {4001300222, 10013002, 21, 15, "0", "0", "Resent\u{0020}me.", "私を恨みなさい。", "0", "0", "怨恨我吧。", "0", "cv_lilith_18", "0", "0"},
[4001300223] = {4001300223, 10013002, 23, 16, "0", "0", "I'll\u{0020}kill\u{0020}you.", "あなたを、杀す。", "0", "0", "杀了你。", "0", "cv_lilith_19", "0", "0"},
[4001300224] = {4001300224, 10013002, 26, 19, "0", "0", "Energy\u{0020}reserves\u{0020}depleted...\u{0020}Is\u{0020}it\u{0020}finally\u{0020}over?\u{0020}Someone\u{0020}save\u{0020}me...\u{0020}Where\u{0020}are\u{0020}you...", "エネルギーがもうすぐ切れてしまう……やっと终わるのね……谁か、私を助けて……あなたはどこ……", "0", "0", "能量储备即将归零……终于可以结束了吗……谁来救救我……你在哪里啊……", "0", "cv_lilith_20", "0", "0"},
[4001300225] = {4001300225, 10013002, 27, 20, "0", "0", "Ah,\u{0020}it's\u{0020}that\u{0020}familiar\u{0020}smell\u{0020}again...\u{0020}it's\u{0020}you,\u{0020}isn't\u{0020}it?", "あっ、またあの懐かしい匂いが……あなたよね？", "0", "0", "啊，又是那股熟悉的味道呢，是你吧。", "0", "cv_lilith_21", "0", "0"},
[4001300226] = {4001300226, 10013002, 28, 21, "0", "0", "Being\u{0020}so\u{0020}close\u{0020}to\u{0020}you\u{0020}is\u{0020}irritating...", "あなたがこんな近い所にいるなんて、嫌だわ……", "0", "0", "和你贴得这么近，真讨厌啊……", "0", "cv_lilith_22", "0", "0"},
[4001300227] = {4001300227, 10013002, 29, 21, "0", "0", "Be\u{0020}careful.\u{0020}I\u{0020}don't\u{0020}want\u{0020}to\u{0020}hear\u{0020}your\u{0020}wailing\u{0020}when\u{0020}you\u{0020}fall.", "あなた、気を付けてね。落ちる时の叫び声は闻きたくないわ。", "0", "0", "要小心点哦，我可不想听到你摔下去时发出的哀嚎。", "0", "cv_lilith_23", "0", "0"},
[4001300228] = {4001300228, 10013002, 30, 22, "0", "0", "Go\u{0020}ahead\u{0020}with\u{0020}confidence.", "安心して行きなさい。", "0", "0", "放心地上吧。", "0", "cv_lilith_24", "0", "0"},
[4001300229] = {4001300229, 10013002, 31, 23, "0", "0", "If\u{0020}you\u{0020}dare\u{0020}to\u{0020}cheat\u{0020}using\u{0020}Synesthesia,\u{0020}I'll\u{0020}kill\u{0020}you.", "通感覚でカンニングしたら杀すわよ。", "0", "0", "如果敢使用通感作弊就杀了你哦。", "0", "cv_lilith_25", "0", "0"},
