[4149000101] = {4149000101, 11049001, 2, 2, "0", "0", "I\u{0020}really\u{0020}don't\u{0020}want\u{0020}to\u{0020}be\u{0020}on\u{0020}duty...\u{0020}I\u{0020}want\u{0020}to\u{0020}sleep,\u{0020}I\u{0020}want\u{0020}to\u{0020}watch\u{0020}anime...", "当直したくない……寝たい、アニメ観たい……", "0", "0", "0", "0", "cv_sk_aertaiya_2", "0", "0"},
[4149000102] = {4149000102, 11049001, 3, 3, "0", "0", "You\u{0020}didn't\u{0020}expect\u{0020}to\u{0020}see\u{0020}me\u{0020}here,\u{0020}did\u{0020}you,\u{0020}Mr.\u{0020}Lizard!\u{0020}Hehe,\u{0020}didn't\u{0020}someone\u{0020}once\u{0020}say\u{0020}that\u{0020}every\u{0020}reunion\u{0020}in\u{0020}this\u{0020}world\u{0020}is\u{0020}a\u{0020}long-planned\u{0020}encounter?\u{0020}I\u{0020}remembered\u{0020}that\u{0020}right,\u{0020}didn't\u{0020}I?", "驚いたでしょ、トカゲさん！ふふ、誰かが言ってたよね、世の中の再会はすべて仕組まれた出会いだって——間違ってないよね？", "0", "0", "0", "0", "cv_sk_aertaiya_3", "0", "0"},
[4149000103] = {4149000103, 11049001, 4, 4, "0", "idle", "I'm\u{0020}so\u{0020}sleepy...\u{0020}What\u{0020}time\u{0020}is\u{0020}it...?\u{0020}Oh,\u{0020}right...\u{0020}I\u{0020}don't\u{0020}have\u{0020}school\u{0020}today...", "ふあ、眠い……今何時だろう……あ、今日は学校行かなくていいんだっけ……", "0", "0", "0", "0", "cv_sk_aertaiya_4", "0", "0"},
[4149000104] = {4149000104, 11049001, 5, 4, "0", "idle", "Oh\u{0020}no...\u{0020}I\u{0020}accidentally\u{0020}fell\u{0020}asleep...\u{0020}I\u{0020}wasn't\u{0020}drooling,\u{0020}was\u{0020}I...?\u{0020}Ugh...\u{0020}I'll\u{0020}wipe\u{0020}it\u{0020}off\u{0020}first.\u{0020}Then\u{0020}no\u{0020}one\u{0020}will\u{0020}notice...!", "やばい……うっかり寝ちゃった……よだれ、垂れてないよね……うぅ……きれいに拭かなきゃ、これでバレないよね……！", "0", "0", "0", "0", "cv_sk_aertaiya_5", "0", "0"},
[4149000105] = {4149000105, 11049001, 6, 4, "0", "idle", "When\u{0020}he\u{0020}comes\u{0020}in\u{0020}later...\u{0020}I'm\u{0020}sure\u{0020}I'll\u{0020}give\u{0020}him\u{0020}a\u{0020}big\u{0020}surprise...\u{0020}He'd\u{0020}never\u{0020}expect\u{0020}me\u{0020}to\u{0020}have\u{0020}such\u{0020}a\u{0020}feminine\u{0020}side,\u{0020}right?\u{0020}Hehe...\u{0020}Hehehe...\u{0020}Mr.\u{0020}Lizard?\u{0020}When\u{0020}did\u{0020}you\u{0020}get\u{0020}here!?", "あとで彼が入ってきたら……きっとびっくりするだろうな……こんな女らしい一面があるなんてって…、ふふ……ふふふ……トカゲさん？いつからそこにいたの！？", "0", "0", "0", "0", "cv_sk_aertaiya_6", "0", "0"},
[4149000106] = {4149000106, 11049001, 7, 5, "15_1_0_0.8", "touch1", "Sob...\u{0020}To\u{0020}buy\u{0020}this\u{0020}outfit,\u{0020}I\u{0020}spent\u{0020}all\u{0020}the\u{0020}money\u{0020}I\u{0020}worked\u{0020}so\u{0020}hard\u{0020}to\u{0020}save...\u{0020}I\u{0020}have\u{0020}to\u{0020}make\u{0020}Mr.\u{0020}Lizard\u{0020}see\u{0020}me\u{0020}in\u{0020}a\u{0020}new\u{0020}light.\u{0020}I'm\u{0020}not\u{0020}a\u{0020}kid\u{0020}anymore.", "うぅぅ……この服を買うために、頑張って貯めたお金全部使っちゃったんだ……絶対トカゲさんに見直してもらわなきゃ、私はもう子供じゃないんだから。", "0", "0", "0", "0", "cv_sk_aertaiya_7", "0", "0"},
[4149000107] = {4149000107, 11049001, 8, 5, "15_2_0_0.8", "touch2", "...\u{0020}You\u{0020}heard\u{0020}that?\u{0020}You\u{0020}heard\u{0020}everything\u{0020}I\u{0020}just\u{0020}said!?\u{0020}Forget\u{0020}it!\u{0020}Pretend\u{0020}you\u{0020}didn't\u{0020}hear\u{0020}anything,\u{0020}please!", "……全部聞いてたの？今言ったこと、全部聞こえてたの！？忘れて！聞いてなかったことにして、お願いだから！", "0", "0", "0", "0", "cv_sk_aertaiya_8", "0", "0"},
[4149000108] = {4149000108, 11049001, 9, 5, "15_1_0_0.8", "touch1", "You\u{0020}kept\u{0020}me\u{0020}waiting\u{0020}for\u{0020}so\u{0020}long...\u{0020}Were\u{0020}you\u{0020}working\u{0020}until\u{0020}now...?\u{0020}Ah...\u{0020}Good\u{0020}work.\u{0020}Sorry...", "ずっと待ってたんだからね——この時間まで仕事だったの？あ……お疲れ様、ごめんね……", "0", "0", "0", "0", "cv_sk_aertaiya_9", "0", "0"},
[4149000109] = {4149000109, 11049001, 10, 5, "15_2_0_0.8", "touch2", "Since\u{0020}you've\u{0020}already\u{0020}seen\u{0020}it...\u{0020}I\u{0020}can't\u{0020}exactly\u{0020}act\u{0020}like\u{0020}a\u{0020}game\u{0020}heroine\u{0020}and\u{0020}use\u{0020}electric\u{0020}shocks\u{0020}to\u{0020}stimulate\u{0020}your\u{0020}hippocampus\u{0020}and\u{0020}make\u{0020}you\u{0020}lose\u{0020}your\u{0020}memory...\u{0020}So,\u{0020}don't\u{0020}you\u{0020}have\u{0020}anything\u{0020}you\u{0020}want\u{0020}to\u{0020}say\u{0020}to\u{0020}me?\u{0020}Not\u{0020}even\u{0020}one\u{0020}sentence?\u{0020}Hey!", "見られちゃった以上……ゲームの女主人公みたいに、電撃で君の海馬体を刺激して記憶を消すことなんて造作もないから……何か言いたいことはないの？一言もないの？ねえ！", "0", "0", "0", "0", "cv_sk_aertaiya_10", "0", "0"},
[4149000110] = {4149000110, 11049001, 11, 5, "15_1_0_0.8", "touch1", "Does\u{0020}it\u{0020}look\u{0020}good...?\u{0020}Ah,\u{0020}thank\u{0020}you.\u{0020}That\u{0020}means\u{0020}my\u{0020}efforts\u{0020}weren't\u{0020}wasted...\u{0020}But\u{0020}is\u{0020}that\u{0020}all\u{0020}you\u{0020}want\u{0020}to\u{0020}say?\u{0020}Isn't\u{0020}there\u{0020}something...\u{0020}more\u{0020}heart-fluttering?\u{0020}Something\u{0020}like...\u{0020}that\u{0020}line\u{0020}from\u{0020}anime,\u{0020}\"The\u{0020}moon\u{0020}is\u{0020}beautiful\u{0020}tonight\"...\u{0020}or\u{0020}something.", "どう？……あ、ありがとう、これで私の努力も無駄じゃなかったってことだね……でも、言いたいのはそれだけ？もっと……胸がときめくような言葉はないの？アニメみたいに……「月が綺麗」とか……さ。", "0", "0", "0", "0", "cv_sk_aertaiya_11", "0", "0"},
[4149000111] = {4149000111, 11049001, 12, 6, "0", "0", "Level\u{0020}up!", "レベルアップ！ ", "0", "0", "0", "0", "cv_sk_aertaiya_12", "0", "0"},
