[4149000124] = {4149000124, 11049001, 27, 20, "0", "0", "I\u{0020}won't\u{0020}scream\u{0020}like\u{0020}girls\u{0020}do\u{0020}in\u{0020}anime.\u{0020}Anyway,\u{0020}you\u{0020}must\u{0020}have\u{0020}had\u{0020}some\u{0020}reason\u{0020}for\u{0020}this...\u{0020}You\u{0020}couldn't\u{0020}really\u{0020}have\u{0020}just\u{0020}wandered\u{0020}into\u{0020}the\u{0020}wrong\u{0020}place,\u{0020}right?", "アニメの女の子みたいに叫んだりしないからね——どうせ理由があるんでしょ……まさか本当に間違って来たわけじゃないよね？", "0", "0", "0", "0", "cv_sk_aertaiya_27", "0", "0"},
[4149000125] = {4149000125, 11049001, 28, 21, "0", "0", "You've\u{0020}already\u{0020}seen\u{0020}everything\u{0020}you\u{0020}weren't\u{0020}supposed\u{0020}to\u{0020}see,\u{0020}haven't\u{0020}you?\u{0020}\"Take\u{0020}responsibility\u{0020}for\u{0020}it\"...\u{0020}would\u{0020}saying\u{0020}that\u{0020}sound\u{0020}too\u{0020}cliché?", "見ちゃいけないとこ全部見ちゃったでしょ、「責任取ってよ」……ちょっと古くさいかな？", "0", "0", "0", "0", "cv_sk_aertaiya_28", "0", "0"},
[4149000126] = {4149000126, 11049001, 29, 21, "0", "0", "Oh,\u{0020}right\u{0020}-\u{0020}next\u{0020}time,\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}go\u{0020}to\u{0020}a\u{0020}real\u{0020}hot\u{0020}spring\u{0020}together?\u{0020}I've\u{0020}always\u{0020}been\u{0020}interested\u{0020}in\u{0020}the\u{0020}hot\u{0020}spring\u{0020}inns\u{0020}that\u{0020}show\u{0020}up\u{0020}in\u{0020}anime!", "そうだ、今度本物の温泉に一緒に行かない？アニメの温泉旅館にずっと興味があったんだ！", "0", "0", "0", "0", "cv_sk_aertaiya_29", "0", "0"},
