[4202500101] = {4202500101, 12025001, 2, 2, "0", "0", "Do\u{0020}I\u{0020}have\u{0020}to\u{0020}become\u{0020}your\u{0020}personal\u{0020}bodyguard,\u{0020}Navigator?\u{0020}Me?\u{0020}Deep\u{0020}breaths,\u{0020}I\u{0020}need\u{0020}deep\u{0020}breaths\u{0020}-\u{0020}hss\u{0020}-\u{0020}hoo\u{0020}-\u{0020}that\u{0020}was\u{0020}close,\u{0020}I\u{0020}almost\u{0020}suffocated\u{0020}from\u{0020}lack\u{0020}of\u{0020}oxygen...\u{0020}I'll\u{0020}do\u{0020}my\u{0020}best!", "ナビゲーターさんのボディガードを务めるのは私ですか？深呼吸、深呼吸しなければ——すぅ——はぁ——危なかった、息が切れそうになった……顽张ります！", "0", "0", "0", "0", "cv_feilin_2", "0", "0"},
[4202500102] = {4202500102, 12025001, 3, 3, "0", "0", "Whenever\u{0020}I\u{0020}start\u{0020}wondering\u{0020}whether\u{0020}I'm\u{0020}still\u{0020}suited\u{0020}to\u{0020}be\u{0020}a\u{0020}driver,\u{0020}I\u{0020}somehow\u{0020}end\u{0020}up\u{0020}here.\u{0020}Please\u{0020}allow\u{0020}me\u{0020}to\u{0020}introduce\u{0020}myself\u{0020}again,\u{0020}Navigator.\u{0020}My\u{0020}name\u{0020}is\u{0020}Felin\u{0020}Branny,\u{0020}and\u{0020}I\u{0020}am\u{0020}a\u{0020}driver.", "自分がまだドライバーに向いているかどうか考えていたら、いつの间にかここに来てしまいました。もう一度自己绍介させてください、ナビゲーターさん。私はフェリン・ブリトニー、ドライバーです。", "0", "0", "0", "0", "cv_feilin_3", "0", "0"},
[4202500103] = {4202500103, 12025001, 91, 4, "0", "idle", "Whether\u{0020}they're\u{0020}support\u{0020}staff\u{0020}handling\u{0020}logistics\u{0020}or\u{0020}drivers\u{0020}fighting\u{0020}on\u{0020}the\u{0020}front\u{0020}line,\u{0020}everyone\u{0020}is\u{0020}indispensable\u{0020}to\u{0020}Aegis.\u{0020}I\u{0020}think\u{0020}that's\u{0020}the\u{0020}most\u{0020}precious\u{0020}thing\u{0020}I've\u{0020}learned\u{0020}over\u{0020}these\u{0020}past\u{0020}six\u{0020}months.", "后方支持のスタッフも、前线で戦うドライバーも、アイギスには欠かせない存在です。これがこの半年で学んだ最も贵重なことです。", "0", "0", "0", "0", "cv_feilin_4", "0", "idle,idle"},
[4202500104] = {4202500104, 12025001, 91, 4, "0", "idle", "I\u{0020}dreamed\u{0020}about\u{0020}the\u{0020}captain\u{0020}and\u{0020}the\u{0020}others\u{0020}again\u{0020}recently,\u{0020}and\u{0020}they\u{0020}praised\u{0020}me\u{0020}for\u{0020}how\u{0020}much\u{0020}I've\u{0020}grown.\u{0020}They\u{0020}said\u{0020}I've\u{0020}really\u{0020}worked\u{0020}hard,\u{0020}that\u{0020}I've\u{0020}done\u{0020}well...\u{0020}Actually,\u{0020}that's\u{0020}probably\u{0020}just\u{0020}what\u{0020}I\u{0020}want\u{0020}to\u{0020}hear\u{0020}deep\u{0020}down,\u{0020}isn't\u{0020}it?\u{0020}I\u{0020}really\u{0020}am...\u{0020}so\u{0020}full\u{0020}of\u{0020}myself.", "最近、また队长たちの梦を见ました。彼女たちに成长したと褒められて、本当に努力してるねと言われました……実はこれ、私の独りよがりですよね？私って本当に……ナルシズムですね。", "0", "0", "0", "0", "cv_feilin_5", "0", "idle,idle"},
[4202500105] = {4202500105, 12025001, 91, 4, "0", "idle", "Whenever\u{0020}I\u{0020}run\u{0020}into\u{0020}former\u{0020}coworkers\u{0020}from\u{0020}the\u{0020}Department\u{0020}of\u{0020}Social\u{0020}Restoration\u{0020}here\u{0020}on\u{0020}the\u{0020}Ark,\u{0020}I\u{0020}always\u{0020}pray\u{0020}they\u{0020}won't\u{0020}see\u{0020}me...\u{0020}Why?\u{0020}Because\u{0020}I\u{0020}have\u{0020}no\u{0020}idea\u{0020}what\u{0020}I'd\u{0020}even\u{0020}say...", "方舟で一绪に働いていた社会复兴部の同僚に出会いそうなときは、いつも见つからないように祈っています……なぜって？何を话せばいいかわからないからです……", "0", "0", "0", "0", "cv_feilin_6", "0", "idle,idle"},
[4202500106] = {4202500106, 12025001, 92, 5, "15_1_0_0.8", "level1", "This\u{0020}is\u{0020}something\u{0020}I\u{0020}only\u{0020}learned\u{0020}recently...\u{0020}It\u{0020}seems\u{0020}a\u{0020}lot\u{0020}of\u{0020}people\u{0020}now\u{0020}see\u{0020}\"driver\"\u{0020}as\u{0020}a\u{0020}dream,\u{0020}the\u{0020}way\u{0020}people\u{0020}once\u{0020}dreamed\u{0020}of\u{0020}becoming\u{0020}scientists.\u{0020}Is\u{0020}that\u{0020}a\u{0020}good\u{0020}thing?\u{0020}It\u{0020}feels\u{0020}a\u{0020}little\u{0020}complicated...", "最近知ったことですが……多くの人が「ドライバー」を梦见ているようです。かつての科学者のように。これは良いことなのでしょうか……？", "0", "0", "0", "0", "cv_feilin_7", "0", "level1,level1"},
[4202500107] = {4202500107, 12025001, 92, 5, "15_1_0_0.8", "level1", "You\u{0020}don't\u{0020}look\u{0020}so\u{0020}well,\u{0020}Navigator.\u{0020}Are\u{0020}you\u{0020}too\u{0020}tired\u{0020}from\u{0020}work?\u{0020}I\u{0020}know\u{0020}a\u{0020}pretty\u{0020}good\u{0020}place.\u{0020}Their\u{0020}drinks\u{0020}and\u{0020}grilled\u{0020}meat\u{0020}are\u{0020}great.\u{0020}Want\u{0020}to\u{0020}go\u{0020}together\u{0020}after\u{0020}work?", "ナビゲーターさん、颜色が悪いですね。仕事が大変なのでしょうか？いいお店を知っていますよ。そこのお酒と焼肉は最高です。仕事が终わったら一绪に行きませんか？", "0", "0", "0", "0", "cv_feilin_8", "0", "level1,level1"},
[4202500108] = {4202500108, 12025001, 92, 5, "15_2_0_0.8", "level2", "Can\u{0020}someone\u{0020}like\u{0020}me\u{0020}really\u{0020}be\u{0020}a\u{0020}capable\u{0020}captain?\u{0020}Navigator,\u{0020}do\u{0020}you\u{0020}know\u{0020}Miss\u{0020}Dolores?\u{0020}There's\u{0020}something\u{0020}I'd\u{0020}like\u{0020}to\u{0020}ask\u{0020}her\u{0020}about\u{0020}-\u{0020}how\u{0020}to\u{0020}be\u{0020}a\u{0020}good\u{0020}captain.", "私のような人间が本当に有能な队长になれるのでしょうか？ナビゲーターさん、ドロリィスさんをご存知ですか？彼女に相谈したいことがあります——どうやったら良い队长になれるかについてです。", "0", "0", "0", "0", "cv_feilin_9", "0", "level2,level2"},
[4202500109] = {4202500109, 12025001, 92, 5, "15_2_0_0.8", "level2", "Navigator,\u{0020}have\u{0020}you\u{0020}been\u{0020}free\u{0020}lately?\u{0020}N-no,\u{0020}it's\u{0020}nothing\u{0020}especially\u{0020}important.\u{0020}Driver\u{0020}counseling...\u{0020}you're\u{0020}good\u{0020}at\u{0020}that,\u{0020}aren't\u{0020}you?", "ナビゲーターさん、近々お时间ありますか？いえ、特に重要なことではありません。ドライバーの心理カウンセリング……ナビゲーターさんはお得意ですよね？", "0", "0", "0", "0", "cv_feilin_10", "0", "level2,level2"},
[4202500110] = {4202500110, 12025001, 92, 5, "15_2_0_0.8", "level2", "Navigator,\u{0020}could\u{0020}you\u{0020}cancel\u{0020}your\u{0020}plans\u{0020}for\u{0020}tonight?\u{0020}Yes,\u{0020}I\u{0020}know\u{0020}you\u{0020}already\u{0020}had\u{0020}plans\u{0020}with\u{0020}another\u{0020}driver,\u{0020}but\u{0020}there's\u{0020}something\u{0020}very\u{0020}important\u{0020}I\u{0020}need\u{0020}to\u{0020}talk\u{0020}to\u{0020}you\u{0020}about\u{0020}-\u{0020}it's\u{0020}about\u{0020}love,\u{0020}about\u{0020}drivers\u{0020}and\u{0020}Navigators...\u{0020}about\u{0020}ordinary\u{0020}people\u{0020}and\u{0020}empathic\u{0020}resonators...\u{0020}I\u{0020}need\u{0020}romantic\u{0020}advice.", "ナビゲーターさん、今晩の予定をキャンセルできますか？はい、他のドライバーとの约束があるのは知っていますが、重要なお话があります——恋爱についてです。ドライバーとナビゲーターのこと……一般人と通感覚者のことについての……恋爱相谈です。", "0", "0", "0", "0", "cv_feilin_11", "0", "level2,level2"},
