[404004] = {404004, 10040, 5, 4, "0", "idle", "The\u{0020}silicon-based\u{0020}arrow\u{0020}is\u{0020}ultrasonic\u{0020}sound,\u{0020}the\u{0020}silicon-based\u{0020}ear\u{0020}is\u{0020}a\u{0020}detector,\u{0020}the\u{0020}silicon-based\u{0020}wings\u{0020}soar\u{0020}through\u{0020}the\u{0020}sky,\u{0020}and\u{0020}the\u{0020}mechanical\u{0020}ray\u{0020}is\u{0020}a\u{0020}heat\u{0020}ray.\u{0020}Having\u{0020}learned\u{0020}of\u{0020}human\u{0020}love\u{0020}for\u{0020}the\u{0020}first\u{0020}time,\u{0020}the\u{0020}awakened,\u{0020}gentle,\u{0020}artificial\u{0020}Sin\u{0020}is\u{0020}none\u{0020}other\u{0020}than\u{0020}me,\u{0020}the\u{0020}hero\u{0020}of\u{0020}justice,\u{0020}red-chan,\u{0020}red-chan!", "0", "0", "0", "0", "0", "cv_megazlws_005", "0", "0"},
[404005] = {404005, 10040, 6, 4, "0", "idle", "You\u{0020}mean\u{0020}Dr.\u{0020}Red?\u{0020}She\u{0020}is\u{0020}the\u{0020}kind\u{0020}of\u{0020}person\u{0020}who\u{0020}ruins\u{0020}everything\u{0020}she\u{0020}touches.\u{0020}Working\u{0020}with\u{0020}her\u{0020}is\u{0020}one\u{0020}of\u{0020}the\u{0020}biggest\u{0020}mistakes\u{0020}of\u{0020}my\u{0020}life.\n(red)\u{0020}I\u{0020}am\u{0020}still\u{0020}your\u{0020}creator,\u{0020}you\u{0020}know!\n(Dr.\u{0020}Red)\u{0020}That\u{0020}is\u{0020}another\u{0020}major\u{0020}mistake\u{0020}of\u{0020}my\u{0020}life.\u{0020}(red)", "0", "0", "0", "0", "0", "cv_megazlws_006", "0", "0"},
[404006] = {404006, 10040, 7, 5, "1_》_0_0.8", "level1", "Listen\u{0020}carefully.\u{0020}red,\u{0020}today\u{0020}we\u{0020}begin\u{0020}Operation\u{0020}Flattery.\u{0020}Our\u{0020}goal\u{0020}is\u{0020}to\u{0020}obtain\u{0020}more\u{0020}of\u{0020}that\u{0020}Navigator's\u{0020}genes.\u{0020}(Dr.\u{0020}Red)\nDoctor,\u{0020}you\u{0020}are\u{0020}speaking\u{0020}on\u{0020}the\u{0020}public\u{0020}channel\u{0020}right\u{0020}now.\u{0020}Everyone\u{0020}has\u{0020}heard\u{0020}our\u{0020}conspiracy.\u{0020}(red)", "0", "0", "0", "0", "0", "cv_megazlws_007", "0", "0"},
[404007] = {404007, 10040, 8, 5, "1_》_0_0.8", "level2", "Dr.\u{0020}Red,\u{0020}please\u{0020}do\u{0020}not\u{0020}come\u{0020}near\u{0020}me\u{0020}anymore.\u{0020}I\u{0020}am\u{0020}afraid\u{0020}Navigator\u{0020}will\u{0020}misunderstand\u{0020}our\u{0020}relationship.\u{0020}(red)\nHuh?\u{0020}Hmm?\u{0020}What\u{0020}is\u{0020}that\u{0020}supposed\u{0020}to\u{0020}mean...?\u{0020}Could\u{0020}it\u{0020}be...\u{0020}you\u{0020}have\u{0020}fallen\u{0020}in\u{0020}love\u{0020}with\u{0020}him?\u{0020}No\u{0020}way.\u{0020}That\u{0020}is\u{0020}hilarious.\u{0020}(Dr.\u{0020}Red)", "0", "0", "0", "0", "0", "cv_megazlws_008", "0", "0"},
