[4300000102] = {4300000102, 13000001, 3, 3, "0", "0", "Whooooaaa--who\u{0020}are\u{0020}you?\u{0020}Oh,\u{0020}it's\u{0020}you,\u{0020}Navigator!\u{0020}I'm\u{0020}Odora.\u{0020}Nice\u{0020}to\u{0020}meet\u{0020}you!\u{0020}Yawn--", "ふぁ――あなた、誰？ナビゲーターだったのね。初めまして。あたしはオードラ。ふぁ――", "0", "0", "哇呼——你是誰？原來是領航，你好，我是歐朵啦。呼——", "0", "cv_sk_odora_1", "0", "0"},
[4300000103] = {4300000103, 13000001, 4, 4, "0", "idle", "I\u{0020}sleep\u{0020}enough,\u{0020}but\u{0020}why\u{0020}am\u{0020}I\u{0020}not\u{0020}getting\u{0020}taller?\u{0020}Navigator,\u{0020}do\u{0020}you\u{0020}have\u{0020}any\u{0020}tips?\u{0020}Milk?\u{0020}That's\u{0020}what\u{0020}Lulula\u{0020}said\u{0020}too...\u{0020}Alright,\u{0020}I'll\u{0020}trust\u{0020}you\u{0020}both.", "たっぷり寢てるのに、背が伸びないんだよね。何でだろう……ナビゲーターって、背を伸ばす秘訣とか何か知らない？ミルクか……ルルラもそう言ってたなあ……よし、あなたたちの言うことを信じようっと……", "0", "0", "明明睡眠很充足，為什麼長不高呢……領航有什麼長高的秘訣嗎？牛奶……露露啦也是這麼說的……好吧，相信你們……", "0", "cv_sk_odora_3", "0", "0,idle"},
[4300000104] = {4300000104, 13000001, 5, 4, "0", "idle", "Humming~\u{0020}The\u{0020}sun's\u{0020}out--Navigator,\u{0020}come\u{0020}play\u{0020}with\u{0020}me!\u{0020}Lulula\u{0020}said\u{0020}the\u{0020}more\u{0020}sun\u{0020}I\u{0020}get,\u{0020}the\u{0020}taller\u{0020}I'll\u{0020}grow!", "ふふふん～ふんふん～♪お日様が出てきたよ、あたしと出かけて遊ぼ、ね、ナビゲーター。背を伸ばすにはひなたぼっこを沢山しないといけないってルルラも言ってたの。", "0", "0", "哼哼——哼哼——太陽出來啦～領航和我出去玩吧～露露啦說多曬太陽才能長高哇～", "0", "cv_sk_odora_4", "0", "0,idle"},
[4300000105] = {4300000105, 13000001, 6, 4, "0", "idle", "I'm\u{0020}hungry...\u{0020}Lulula,\u{0020}where\u{0020}are\u{0020}you?\u{0020}I'm\u{0020}starving!", "お腹空いた……ルルラ！どこにいるの、お腹空いたよ～……", "0", "0", "肚子餓了……露露啦，你在哪~我肚子餓了~~~", "0", "cv_sk_odora_27", "0", "0,idle"},
