[4203100111] = {4203100111, 12031001, 95, 5, "1_》_0_0.8", "level4", "Oh,\u{0020}right.\u{0020}I\u{0020}still\u{0020}have\u{0020}not\u{0020}settled\u{0020}things\u{0020}with\u{0020}you\u{0020}over\u{0020}what\u{0020}happened\u{0020}last\u{0020}time.\u{0020}Listen\u{0020}carefully.\u{0020}If\u{0020}you\u{0020}run\u{0020}into\u{0020}any\u{0020}trouble\u{0020}in\u{0020}the\u{0020}future,\u{0020}remember\u{0020}to\u{0020}tell\u{0020}me.\u{0020}I\u{0020}may\u{0020}not\u{0020}always\u{0020}have\u{0020}time\u{0020}to\u{0020}help\u{0020}you,\u{0020}but\u{0020}if\u{0020}you\u{0020}tell\u{0020}me\u{0020}nothing\u{0020}at\u{0020}all,\u{0020}that\u{0020}is\u{0020}your\u{0020}problem!", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n12", "0", "level4,level4"},
[4203100112] = {4203100112, 12031001, 95, 5, "1_》_0_0.8", "level4", "Also,\u{0020}did\u{0020}I\u{0020}not\u{0020}tell\u{0020}you\u{0020}before?\u{0020}Stop\u{0020}going\u{0020}out\u{0020}of\u{0020}your\u{0020}way\u{0020}to\u{0020}make\u{0020}trouble\u{0020}for\u{0020}yourself.\u{0020}It\u{0020}is\u{0020}because\u{0020}you\u{0020}are\u{0020}so\u{0020}easily\u{0020}deceived\u{0020}by\u{0020}women\u{0020}that\u{0020}you\u{0020}keep\u{0020}getting\u{0020}dragged\u{0020}into\u{0020}undeserved\u{0020}disasters.\u{0020}You\u{0020}should\u{0020}learn\u{0020}your\u{0020}lesson!", "0", "0", "0", "0", "0", "cv_sk_qianqiu_se_n13", "0", "level4,level4"},
