[4000200101] = {4000200101, 10002001, 2, 2, "0", "0", "Eh?\u{0020}Is\u{0020}this\u{0020}a\u{0020}good\u{0020}idea?\u{0020}I\u{0020}don't\u{0020}know\u{0020}how\u{0020}to\u{0020}handle\u{0020}this\u{0020}kind\u{0020}of\u{0020}situation\u{0020}at\u{0020}all.", "え？本当にいいのか？こういうとき、どうすればいいのか全然わからないんだが。", "0", "0", "哎？这样真的好吗，我这种人完全不知道该怎么处理这种情况哎。", "0", "cv_hank_2", "0", "0"},
[4000200102] = {4000200102, 10002001, 3, 3, "0", "0", "Yo,\u{0020}you're\u{0020}the\u{0020}navigator?\u{0020}Just\u{0020}to\u{0020}be\u{0020}clear,\u{0020}I'm\u{0020}just\u{0020}a\u{0020}mercenary.", "よぉ！あんたがナビゲーターか？言っておくが、私はただの佣兵だ。", "0", "0", "哟，你就是领航吗？话先说好，我只是个佣兵哦。", "0", "cv_hank_1", "0", "0"},
[4000200103] = {4000200103, 10002001, 91, 4, "0", "idle", "It's\u{0020}not\u{0020}just\u{0020}for\u{0020}my\u{0020}benefit,\u{0020}it's\u{0020}for\u{0020}the\u{0020}benefit\u{0020}of\u{0020}my\u{0020}employer,\u{0020}too.", "私は报酬に応じた仕事をする。自分にとっても雇用主にとっても良いことだと思うんだがな。", "0", "0", "给多少钱办多少事，不光光是为了我好也是为了雇主好哦。", "0", "cv_hank_3", "0", "0,idle"},
[4000200104] = {4000200104, 10002001, 91, 4, "0", "idle", "Kill,\u{0020}Kill,\u{0020}Kill...\u{0020}This\u{0020}is\u{0020}what\u{0020}I've\u{0020}been\u{0020}doing\u{0020}...\u{0020}Long\u{0020}before\u{0020}I\u{0020}became\u{0020}a\u{0020}driver,\u{0020}I\u{0020}was\u{0020}doing\u{0020}similar\u{0020}things.", "杀戮、杀戮、杀戮、杀戮……これが私の仕事だ……ドライバーになる前もずっと似たような事をやっていた。", "0", "0", "杀戮，杀戮，杀戮，杀戮……这就是我一直以来在做的工作……早在成为驾驶员之前，我就在干类似的事情了。", "0", "cv_hank_4", "0", "0,idle"},
[4000200105] = {4000200105, 10002001, 91, 4, "0", "idle", "Tina\u{0020}is\u{0020}hard\u{0020}to\u{0020}get\u{0020}along\u{0020}with,\u{0020}but\u{0020}to\u{0020}be\u{0020}honest,\u{0020}I\u{0020}prefer\u{0020}someone\u{0020}who\u{0020}means\u{0020}what\u{0020}they\u{0020}say.", "确かにティナは扱いにくいやつだけど、でも正直なところ、口が悪いけど心根が优しいっていう女の子より、彼女みたいな言行一致のやつの方がいい。", "0", "0", "虽然蒂娜是个蛮难相处的家伙，不过说实话，比起刀子嘴豆腐心的人，我更喜欢像她一样言行一致的家伙。", "0", "cv_hank_28", "0", "0,idle"},
[4000200106] = {4000200106, 10002001, 92, 5, "15_1_0_0.8", "level1", "The\u{0020}reason\u{0020}for\u{0020}joining\u{0020}AEGIS...\u{0020}Of\u{0020}course\u{0020}it's\u{0020}the\u{0020}fat\u{0020}paycheck.\u{0020}And\u{0020}also\u{0020}those\u{0020}two\u{0020}girls\u{0020}that\u{0020}I\u{0020}care\u{0020}about.\u{0020}I\u{0020}didn't\u{0020}have\u{0020}a\u{0020}good\u{0020}relationship\u{0020}with\u{0020}my\u{0020}sister\u{0020}in\u{0020}the\u{0020}past.", "アイギスに入った理由……うーん……それはもちろん、报酬がいいからに决まってるだろ。まぁ、あの二人の女の子のことが気になるからっていうのもなくはないが……昔、私も姉さんとは仲が悪かったからな。", "0", "0", "加入艾吉斯的理由…嗯……当然是因为雇主给的钱足够多啊。还有部分原因是因为我很在意那两个女孩，在过去，我和姐姐的关系也不太好呢。", "0", "cv_hank_29", "0", "0,level1"},
[4000200107] = {4000200107, 10002001, 92, 5, "15_1_0_0.8", "level1", "What's\u{0020}going\u{0020}on\u{0020}here?", "ん？どういうことだ？", "0", "0", "哎？这是什么情况啊？", "0", "cv_hank_5", "0", "0,level1"},
[4000200108] = {4000200108, 10002001, 92, 5, "15_2_0_0.8", "level2", "Well...\u{0020}Weird\u{0020}but,\u{0020}you\u{0020}mean\u{0020}no\u{0020}harm,\u{0020}right?", "うーん……なんかよくわからないけど、悪意はないってことだろ？", "0", "0", "嗯……虽然还有些奇怪，但是你应该是没有恶意的吧。", "0", "cv_hank_6", "0", "0,level2"},
[4000200109] = {4000200109, 10002001, 92, 5, "15_2_0_0.8", "level2", "It's\u{0020}rare\u{0020}that\u{0020}someone\u{0020}other\u{0020}than\u{0020}enemy\u{0020}would\u{0020}approach\u{0020}me.\u{0020}You\u{0020}don't\u{0020}hate\u{0020}me,\u{0020}do\u{0020}you?", "珍しい。敌以外に自分から私に近づいてくるやつがいただなんて。ひょっとして、私のこと、嫌じゃないのか？", "0", "0", "还真是少见，除了敌人外，居然还会有主动靠近我的家伙啊。难道说，你并没有讨厌我吗？", "0", "cv_hank_7", "0", "0,level2"},
[4000200110] = {4000200110, 10002001, 92, 5, "15_2_0_0.8", "level2", "Although\u{0020}I'm\u{0020}just\u{0020}a\u{0020}mercenary\u{0020}who\u{0020}gets\u{0020}paid\u{0020}to\u{0020}do\u{0020}things,\u{0020}I\u{0020}don't\u{0020}really\u{0020}know\u{0020}how\u{0020}to\u{0020}express\u{0020}my\u{0020}thoughts.\u{0020}But\u{0020}I\u{0020}can't\u{0020}tell\u{0020}you\u{0020}how\u{0020}happy\u{0020}I\u{0020}am\u{0020}to\u{0020}work\u{0020}with\u{0020}you!\u{0020}I'd\u{0020}like\u{0020}to\u{0020}work\u{0020}with\u{0020}you\u{0020}all\u{0020}the\u{0020}time\u{0020}if\u{0020}I\u{0020}could!", "私は报酬に応じた仕事をするだけの佣兵、だから、自分の考えをどうやって伝えればいいのかもよくわからない。でも、なんというか……だから、あれだ――あんたと一绪に仕事をすることができて、本当に嬉しいんだ！出来るなら、あんたとはずっと一绪に仕事をしたい！", "0", "0", "虽然我只是一个拿钱办事的佣兵，也不是很懂该怎么表达自己的想法。但是，该怎么说呢……哈！就是那个啊——能和你一起工作，真的非常开心！如果有机会的话想要一直和你一起工作！", "0", "cv_hank_8", "0", "0,level2"},
[4000200111] = {4000200111, 10002001, 12, 6, "0", "0", "Is\u{0020}that\u{0020}all?\u{0020}Ha,\u{0020}just\u{0020}kidding.", "これしかないのか？あはは、冗谈だ。", "0", "0", "就只有这点吗？哈，开玩笑的。", "0", "cv_hank_9", "0", "0"},
[4000200112] = {4000200112, 10002001, 13, 7, "0", "0", "As\u{0020}long\u{0020}as\u{0020}I\u{0020}get\u{0020}paid.\u{0020}Who\u{0020}are\u{0020}we\u{0020}killing\u{0020}today?", "报酬に応じた仕事をするんだ、さて、今日は谁を斩ろうか？", "0", "0", "拿钱办事～拿钱办事～今天要去砍谁呢？", "0", "cv_hank_10", "0", "0"},
[4000200113] = {4000200113, 10002001, 14, 8, "0", "0", "Great\u{0020}deal\u{0020}indeed...\u{0020}just\u{0020}watch,\u{0020}I\u{0020}won't\u{0020}let\u{0020}my\u{0020}employer\u{0020}down!", "へぇー、これはうまい话だ。任せとけ！雇用主をがっかりさせるようなことは絶対しない。", "0", "0", "呼啊——真是一笔好买卖呢～你就好好看着吧，我绝对不会让雇主失望的！", "0", "cv_hank_11", "0", "0"},
[4000200114] = {4000200114, 10002001, 15, 9, "0", "0", "Whoaaaa!\u{0020}I\u{0020}feel\u{0020}more\u{0020}energetic\u{0020}when\u{0020}I\u{0020}swing\u{0020}my\u{0020}sword!", "おおお――刀捌きが上手くなった気がするぞ！", "0", "0", "噢噢噢噢——挥刀的时候感觉更加有干劲了啊！", "0", "cv_hank_12", "0", "0"},
