[4000200132] = {4000200132, 10002001, 36, 28, "0", "0", "No\u{0020}matter\u{0020}what\u{0020}kind\u{0020}of\u{0020}enemy\u{0020}it\u{0020}is,\u{0020}in\u{0020}the\u{0020}end,\u{0020}it\u{0020}will\u{0020}become\u{0020}part\u{0020}of\u{0020}my\u{0020}paycheck.", "どんな敌であっても、最终的には报酬になるからな。", "0", "0", "无论是什么样的敌人，最后都会变成酬金。", "0", "cv_hank_33", "0", "0"},
[4000200133] = {4000200133, 10002001, 37, 29, "0", "0", "Managing\u{0020}a\u{0020}lot\u{0020}of\u{0020}people\u{0020}must\u{0020}be\u{0020}exhausting.", "沢山の人を管理するのって、大変だろ。", "0", "0", "管理很多人一定很累吧。", "0", "cv_hank_34", "0", "0"},
[4000200134] = {4000200134, 10002001, 38, 30, "0", "0", "That's\u{0020}good.\u{0020}I'm\u{0020}a\u{0020}fan\u{0020}of\u{0020}the\u{0020}hustle\u{0020}and\u{0020}bustle.", "いいね。赈やかなのは好きだ。", "0", "0", "不错，不错，我是个喜欢热闹的人～", "0", "cv_hank_35", "0", "0"},
