[4001000200] = {4001000200, 10010002, 1, 1, "0", "0", "Haze\u{0020}reverb.", "苍雾残响（ハツリバーブ）。", "0", "0", "苍雾残响。", "0", "cv_alaita_32", "0", "0"},
[4001000201] = {4001000201, 10010002, 2, 2, "0", "0", "Don't\u{0020}get\u{0020}too\u{0020}captivated\u{0020}by\u{0020}me—we've\u{0020}still\u{0020}got\u{0020}work\u{0020}to\u{0020}do.", "あまり见惚れないで。仕事に支障を来すわよ。", "0", "0", "可不要看我看入迷了哦，那样会耽误工作的。", "0", "cv_alaita_2", "0", "0"},
[4001000202] = {4001000202, 10010002, 3, 3, "0", "0", "Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad,\u{0020}Alaita.\u{0020}Captain\u{0020}Dolores\u{0020}of\u{0020}my\u{0020}family\u{0020}has\u{0020}been\u{0020}taken\u{0020}good\u{0020}care\u{0020}of\u{0020}by\u{0020}you.\u{0020}Thank\u{0020}you~", "第三研究室防卫班、アライタ。うちのドロリィス队长が世话になったようね。礼を言うわ。", "0", "0", "第三研究室防卫班，阿莱塔。我家的多洛雷斯队长受你照顾了，谢谢~", "0", "cv_alaita_1", "0", "0"},
[4001000203] = {4001000203, 10010002, 91, 4, "0", "idle", "\"Siren\"?\u{0020}Some\u{0020}people\u{0020}do\u{0020}call\u{0020}me\u{0020}that...\u{0020}But,\u{0020}my\u{0020}singing\u{0020}isn't\u{0020}that\u{0020}good,\u{0020}you\u{0020}know?", "セイレーン？私をそう呼ぶ者もいるけど……私の歌はそんなに上手くないわよ？", "0", "0", "“海妖”？的确有人这么叫我啦…不过，我唱歌并没有那么好听噢？", "0", "cv_alaita_3", "0", "idle,idle"},
[4001000204] = {4001000204, 10010002, 94, 4, "0", "idle2", "Don't\u{0020}you\u{0020}think\u{0020}those\u{0020}fleeting\u{0020}beauties\u{0020}are\u{0020}always\u{0020}fascinating?\u{0020}Of\u{0020}course,\u{0020}this\u{0020}includes\u{0020}myself.", "一瞬の美しさには、目を夺われてしまうものよ。勿论、私のことも、ね。", "0", "0", "你不觉得那些转瞬即逝的美丽总是让人着迷吗？当然，这其中也包括我自己。", "0", "cv_alaita_4", "0", "idle2,idle2"},
[4001000205] = {4001000205, 10010002, 92, 5, "1_》_0_0.8", "touch1", "Captain\u{0020}Dolores~\u{0020}Captain\u{0020}Dolores~\u{0020}Ah...\u{0020}She's\u{0020}not\u{0020}here.\u{0020}Then\u{0020}I'll\u{0020}give\u{0020}these\u{0020}documents\u{0020}to\u{0020}her\u{0020}next\u{0020}time.\u{0020}Slacking\u{0020}off?\u{0020}No\u{0020}no\u{0020}no,\u{0020}there's\u{0020}nothing\u{0020}I\u{0020}can\u{0020}do\u{0020}about\u{0020}it.", "ドロリィス队长？……ドロリィス队长？……あら、いないの。じゃあこのファイルを渡すのは今度ね。……サボり？いいえ、これは仕方のないことよ。", "0", "0", "多洛雷斯队长~多洛雷斯队长~啊…不在啊，那下次再把这些档交给她吧。偷懒？不不不，这是没办法的事吧。", "0", "cv_alaita_29", "0", "touch1,touch1"},
[4001000206] = {4001000206, 10010002, 92, 5, "1_》_0_0.8", "touch2", "Heya,\u{0020}I\u{0020}was\u{0020}just\u{0020}looking\u{0020}for\u{0020}you\u{0020}too.\u{0020}I\u{0020}have\u{0020}a\u{0020}show\u{0020}tomorrow\u{0020}morning.\u{0020}Will\u{0020}you\u{0020}come\u{0020}to\u{0020}watch?\u{0020}After\u{0020}the\u{0020}performance,\u{0020}we\u{0020}can\u{0020}go\u{0020}have\u{0020}a\u{0020}cup\u{0020}of\u{0020}tea\u{0020}together.", "あら、ちょうど探していたのよ。明日、私の舞台があるの。见に来ない？それで终わったら、一绪にお茶でもどうかしら。", "0", "0", "哎呀，我正好也在找您呢。明天早上有我的演出，要来看看吗？等演出结束之后，我们正好可以一起去喝杯茶。", "0", "cv_alaita_30", "0", "touch2,touch2"},
[4001000207] = {4001000207, 10010002, 95, 5, "1_》_0_0.8", "touch3", "It's\u{0020}bad\u{0020}to\u{0020}flirt\u{0020}with\u{0020}someone\u{0020}you\u{0020}just\u{0020}met.", "知り合ったばかりの女性に手を出すのは感心しないわ。", "0", "0", "对认识不久的异性出手，可不太好噢。", "0", "cv_alaita_5", "0", "touch3,touch3"},
[4001000208] = {4001000208, 10010002, 95, 5, "1_》_0_0.8", "touch4", "It\u{0020}is\u{0020}said\u{0020}that\u{0020}\"sirens\"\u{0020}can\u{0020}bring\u{0020}misfortune\u{0020}on\u{0020}the\u{0020}sea.\u{0020}Then\u{0020}you'd\u{0020}better\u{0020}not\u{0020}be\u{0020}too\u{0020}close\u{0020}to\u{0020}me...\u{0020}You\u{0020}don't\u{0020}care?\u{0020}So\u{0020}be\u{0020}it...\u{0020}Hehe.", "伝说のセイレーンは海で不幸をもたらすもの。あまり私に近づかない方がいいわよ。……そんなの気にしないって？そう……フフ。", "0", "0", "据说，“海妖”在大海上可是会招来不幸的。那你最好不要和我太亲近了……你不在乎吗？是这样啊…呵呵。", "0", "cv_alaita_6", "0", "touch4,touch4"},
[4001000209] = {4001000209, 10010002, 93, 5, "1_》_0_0.8", "switch1", "Heh,\u{0020}even\u{0020}you,\u{0020}Navigator,\u{0020}are\u{0020}charmed\u{0020}by\u{0020}my\u{0020}beauty?\u{0020}Then,\u{0020}please\u{0020}protect\u{0020}me\u{0020}well,\u{0020}Navigator~\u{0020}I\u{0020}will\u{0020}also\u{0020}protect\u{0020}you~", "あら。ナビゲーターも私の美しさの虏になったのかしら。それじゃあ、ちゃんと私を守ってちょうだい。私もあなたを守るから。", "0", "0", "呵，连领航你也被我的美色迷惑了吗？那么，就请好好守护我吧，领航~我也会保护你的~", "0", "cv_alaita_7", "0", "switch1,switch1"},
[4001000210] = {4001000210, 10010002, 96, 5, "1_》_0_0.8", "switch2", "My\u{0020}life\u{0020}only\u{0020}needs\u{0020}to\u{0020}be\u{0020}like\u{0020}an\u{0020}epiphyllum.\u{0020}After\u{0020}all,\u{0020}eternity\u{0020}will\u{0020}only\u{0020}fade\u{0020}the\u{0020}beauty.\u{0020}Navigator,\u{0020}now,\u{0020}enjoy\u{0020}this\u{0020}short\u{0020}beauty\u{0020}with\u{0020}me.", "私の人生は、花や朝露のように一瞬でいいの。美しさなんて色褪せるだけだもの。さぁナビゲーター。この束の间の美しさを、私と一绪に楽しんでちょうだい。", "0", "0", "我的人生只需如昙花与朝露那样便好，毕竟，永恒只会让美丽褪色。领航，现在，就与我一起享受这份短暂的美好吧。", "0", "cv_alaita_8", "0", "switch2,switch2"},
[4001000211] = {4001000211, 10010002, 12, 6, "0", "0", "Nice\u{0020}feeling.", "いい感じね。", "0", "0", "不错的感觉。", "0", "cv_alaita_9", "0", "0"},
[4001000212] = {4001000212, 10010002, 13, 7, "0", "0", "Do\u{0020}you\u{0020}want\u{0020}to\u{0020}see\u{0020}an\u{0020}even\u{0020}grander\u{0020}show?", "もっと煌びやかにしてもいいんじゃない？", "0", "0", "想看更华丽的演出吗？", "0", "cv_alaita_10", "0", "0"},
[4001000213] = {4001000213, 10010002, 14, 8, "0", "0", "Hehe...\u{0020}Can\u{0020}you\u{0020}hear\u{0020}it?\u{0020}My\u{0020}sword\u{0020}sings\u{0020}not\u{0020}of\u{0020}my\u{0020}beauty\u{0020}but\u{0020}of\u{0020}its\u{0020}excitement—it's\u{0020}thrilled\u{0020}to\u{0020}defend\u{0020}Danube\u{0020}and\u{0020}Saar\u{0020}again.", "ふふ……この剣の喜びが闻こえるかしら？私の美しさはもとより、再びダニューブやサールを守ることができる喜びに违いないわ。", "0", "0", "呵呵……你能感受到吗，这把剑正在发出喜悦的鸣声呢。不，并不是在称赞我的美丽。它一定是因为能够再一次保护多瑙，保护萨尔而高兴吧。", "0", "cv_alaita_11", "0", "0"},
[4001000214] = {4001000214, 10010002, 15, 9, "0", "0", "Make\u{0020}me\u{0020}even\u{0020}more\u{0020}dazzling.", "もっと美しくしてちょうだい。", "0", "0", "让我变得更加美丽吧。", "0", "cv_alaita_12", "0", "0"},
[4001000215] = {4001000215, 10010002, 16, 10, "0", "0", "I'll\u{0020}handle\u{0020}the\u{0020}show;\u{0020}you\u{0020}handle\u{0020}the\u{0020}applause!", "私は舞台に。あなたは喝采を！", "0", "0", "我负责表演，你负责喝彩！", "0", "cv_alaita_13", "0", "0"},
[4001000216] = {4001000216, 10010002, 17, 11, "0", "0", "Shower\u{0020}me\u{0020}with\u{0020}praise,\u{0020}adoration—and\u{0020}then\u{0020}let\u{0020}yourself\u{0020}fall\u{0020}for\u{0020}me.", "讃えよ、讃えよ。そして私の虏になるのよ。", "0", "0", "夸赞我吧，称赞我吧，然后迷恋上我吧。", "0", "cv_alaita_14", "0", "0"},
[4001000217] = {4001000217, 10010002, 18, 12, "0", "0", "Well,\u{0020}Navigator,\u{0020}enough\u{0020}daydreaming.\u{0020}Let's\u{0020}get\u{0020}back\u{0020}to\u{0020}reality.", "まあまあね。……ナビゲーター、ボーッとしてないで帰るわよ。", "0", "0", "马马虎虎…领航，别发呆了，回去了。", "0", "cv_alaita_15", "0", "0"},
[4001000218] = {4001000218, 10010002, 19, 13, "0", "0", "...\u{0020}Hmm,\u{0020}well,\u{0020}I\u{0020}guess\u{0020}that\u{0020}counts\u{0020}as\u{0020}getting\u{0020}the\u{0020}job\u{0020}done,\u{0020}right?", "……まあ、とりあえず良しとするわ。", "0", "0", "…嗯，这也算是完成工作了吧？", "0", "cv_alaita_16", "0", "0"},
