[432802] = {432802, 13028, 3, 3, "0", "0", "Ah~\u{0020}It\u{0020}is\u{0020}Mr.\u{0020}Tiramisu~\u{0020}Would\u{0020}you\u{0020}like\u{0020}to\u{0020}come\u{0020}sit\u{0020}in\u{0020}my\u{0020}shop\u{0020}for\u{0020}a\u{0020}while?", "啊~是提拉米蘇先生~要不要到我的店裏坐一坐？", "0", "0", "0", "0", "cv_choco_03", "0", "0"},
[432803] = {432803, 13028, 4, 4, "0", "idle", "I\u{0020}wonder\u{0020}if\u{0020}there\u{0020}is\u{0020}any\u{0020}candy\u{0020}in\u{0020}this\u{0020}world\u{0020}that\u{0020}will\u{0020}not\u{0020}cause\u{0020}cavities\u{0020}after\u{0020}you\u{0020}eat\u{0020}it...\u{0020}or\u{0020}maybe\u{0020}even\u{0020}be\u{0020}good\u{0020}for\u{0020}your\u{0020}teeth...", "這個世界上有沒有吃了之後不會蛀牙……甚至對牙齒有益的糖果呢……", "0", "0", "0", "0", "cv_choco_04", "0", "0"},
[432804] = {432804, 13028, 5, 4, "0", "idle2", "Ta-da~\u{0020}This\u{0020}is\u{0020}candy\u{0020}that\u{0020}can\u{0020}ease\u{0020}stiff\u{0020}shoulders.\u{0020}After\u{0020}Mr.\u{0020}Tiramisu\u{0020}eats\u{0020}it,\u{0020}sit\u{0020}still\u{0020}for\u{0020}me.\u{0020}I\u{0020}am\u{0020}going\u{0020}to\u{0020}start\u{0020}giving\u{0020}you\u{0020}a\u{0020}back\u{0020}massage.", "鏘鏘~這是能緩解肩部僵硬的糖果，提拉米蘇先生吃下之後乖乖坐好，我要開始給你捶背了。", "0", "0", "0", "0", "cv_choco_05", "0", "0"},
[432805] = {432805, 13028, 6, 4, "0", "idle3", "Actually,\u{0020}I\u{0020}also\u{0020}have\u{0020}cookies\u{0020}that\u{0020}can\u{0020}ease\u{0020}lower\u{0020}back\u{0020}stiffness,\u{0020}but\u{0020}if\u{0020}I\u{0020}stepped\u{0020}onto\u{0020}Mr.\u{0020}Tiramisu's\u{0020}back\u{0020}while\u{0020}I\u{0020}am\u{0020}this\u{0020}huge...\u{0020}Mr.\u{0020}Tiramisu\u{0020}would\u{0020}turn\u{0020}into\u{0020}a\u{0020}tiramisu\u{0020}cookie...", "其實我還有緩解腰部僵硬的餅乾，不過在變得這麼大的情況下我要是踩到提拉米蘇先生背上……提拉米蘇先生就要變成提拉米蘇餅乾了……", "0", "0", "0", "0", "cv_choco_06", "0", "0"},
[432806] = {432806, 13028, 7, 5, "1_》_0_0.8", "level1", "Selling\u{0020}sweetness,\u{0020}collecting\u{0020}happiness~\u{0020}Choco\u{0020}House,\u{0020}where\u{0020}you\u{0020}can\u{0020}get\u{0020}something\u{0020}sweet\u{0020}anytime!\u{0020}That\u{0020}is\u{0020}an\u{0020}advertising\u{0020}slogan\u{0020}I\u{0020}thought\u{0020}about\u{0020}for\u{0020}a\u{0020}long\u{0020}time~\u{0020}One\u{0020}day,\u{0020}I\u{0020}have\u{0020}to\u{0020}make\u{0020}it\u{0020}into\u{0020}a\u{0020}commercial\u{0020}and\u{0020}put\u{0020}it\u{0020}on\u{0020}TV~", "販賣甜蜜，收藏快樂~甜心巧克屋，任何時候都能得到甜頭！這可是我想了很久的廣告詞~以後一定要拍成廣告視頻放到電視上去~", "0", "0", "0", "0", "cv_choco_07", "0", "0"},
[432807] = {432807, 13028, 8, 5, "1_》_0_0.8", "level2", "Grandpa\u{0020}said\u{0020}that\u{0020}only\u{0020}by\u{0020}constantly\u{0020}eating,\u{0020}eating,\u{0020}eating,\u{0020}and\u{0020}eating\u{0020}can\u{0020}you\u{0020}keep\u{0020}finding\u{0020}good\u{0020}snacks.", "爺爺說過，只有不斷地一直吃、吃、吃、吃下去才能不斷地找到好零食呢。", "0", "0", "0", "0", "cv_choco_08", "0", "0"},
[432808] = {432808, 13028, 9, 5, "1_》_100_1.5", "level3", "If\u{0020}only\u{0020}I\u{0020}could\u{0020}eat\u{0020}snacks\u{0020}as\u{0020}meals...\u{0020}Two\u{0020}Christmases\u{0020}ago,\u{0020}I\u{0020}made\u{0020}that\u{0020}wish\u{0020}to\u{0020}Santa\u{0020}Claus.\u{0020}I\u{0020}do\u{0020}not\u{0020}know\u{0020}why,\u{0020}but\u{0020}Santa\u{0020}Claus\u{0020}has\u{0020}not\u{0020}come\u{0020}since\u{0020}then.", "如果能把零食當飯吃就好了……兩年的聖誕節我向聖誕老爺爺許下了這個願望，不知道爲什麼從那以後聖誕老爺爺就沒來過了。", "0", "0", "0", "0", "cv_choco_09", "0", "0"},
[432809] = {432809, 13028, 10, 5, "1_》_500_2", "level4", "I\u{0020}have\u{0020}to\u{0020}sell\u{0020}all\u{0020}the\u{0020}snacks\u{0020}before\u{0020}they\u{0020}expire.\u{0020}How\u{0020}pitiful\u{0020}it\u{0020}would\u{0020}be\u{0020}if\u{0020}snacks\u{0020}that\u{0020}can\u{0020}bring\u{0020}smiles\u{0020}to\u{0020}people's\u{0020}faces\u{0020}were\u{0020}abandoned\u{0020}like\u{0020}this...\u{0020}Ah,\u{0020}I\u{0020}can\u{0020}just\u{0020}give\u{0020}them\u{0020}to\u{0020}everyone\u{0020}for\u{0020}free...!", "得在零食過期之前把大家賣出去才行，讓人們臉上誕生笑容的零食就這樣被遺棄了多可憐啊……啊，免費送給大家吃不就好了……！", "0", "0", "0", "0", "cv_choco_10", "0", "0"},
[432810] = {432810, 13028, 11, 5, "1_》_1000_2.5", "level5", "When\u{0020}I\u{0020}receive\u{0020}my\u{0020}first\u{0020}paycheck,\u{0020}I\u{0020}plan\u{0020}to\u{0020}add\u{0020}a\u{0020}cabinet\u{0020}to\u{0020}the\u{0020}shop\u{0020}that\u{0020}can\u{0020}store\u{0020}ice\u{0020}cream.\u{0020}What\u{0020}does\u{0020}Mr.\u{0020}Tiramisu\u{0020}think\u{0020}of\u{0020}this\u{0020}idea?\u{0020}A\u{0020}genius\u{0020}idea?\u{0020}Hehe,\u{0020}as\u{0020}expected,\u{0020}Mr.\u{0020}Tiramisu\u{0020}really\u{0020}understands.", "我打算在領到第一筆薪水的時候給店裏加上能存放冰淇淋的櫃子，提拉米蘇先生覺得這個主意怎麼樣？天才的想法？嘿嘿，提拉米蘇先生果然也很懂。", "0", "0", "0", "0", "cv_choco_11", "0", "0"},
[432811] = {432811, 13028, 12, 6, "0", "0", "As\u{0020}a\u{0020}Driver,\u{0020}I\u{0020}still\u{0020}do\u{0020}not\u{0020}know\u{0020}anything,\u{0020}so\u{0020}please\u{0020}teach\u{0020}me,\u{0020}Mr.\u{0020}Tiramisu.", "作爲駕駛員我還什麼都不知道，所以教教我吧提拉米蘇先生。", "0", "0", "0", "0", "cv_choco_12", "0", "0"},
[432812] = {432812, 13028, 13, 7, "0", "0", "You\u{0020}have\u{0020}to\u{0020}eat\u{0020}more\u{0020}so\u{0020}you\u{0020}can\u{0020}grow\u{0020}up\u{0020}quickly.", "多吃一點才能快快長大。", "0", "0", "0", "0", "cv_choco_13", "0", "0"},
[432813] = {432813, 13028, 14, 8, "0", "0", "Listen,\u{0020}listen~\u{0020}Mr.\u{0020}Tiramisu~\u{0020}I\u{0020}ate\u{0020}a\u{0020}really,\u{0020}really\u{0020}sweet\u{0020}candy.\u{0020}How\u{0020}can\u{0020}there\u{0020}be\u{0020}candy\u{0020}this\u{0020}sweet?\u{0020}My\u{0020}teeth\u{0020}are\u{0020}going\u{0020}to\u{0020}fall\u{0020}onto\u{0020}the\u{0020}floor\u{0020}with\u{0020}a\u{0020}\"clack.\"\u{0020}I\u{0020}am\u{0020}melting.\u{0020}This\u{0020}is\u{0020}bad.", "聽我說聽我說~提拉米蘇先生~我吃到了好~甜~的糖果，怎麼會有這麼甜的糖果，我的牙齒都要“叭噶”一聲掉到地上了，要融化了，大事不妙了。", "0", "0", "0", "0", "cv_choco_14", "0", "0"},
