[440909] = {440909, 14009, 10, 5, "1_》_500_2", "level4", "The\u{0020}other\u{0020}\"me\"\u{0020}is\u{0020}a\u{0020}complete\u{0020}idiot.\u{0020}She\u{0020}acts\u{0020}like\u{0020}she\u{0020}has\u{0020}some\u{0020}grand\u{0020}ambition,\u{0020}but\u{0020}I\u{0020}doubt\u{0020}she\u{0020}even\u{0020}knows\u{0020}how\u{0020}she's\u{0020}supposed\u{0020}to\u{0020}stay\u{0020}alive\u{0020}long\u{0020}enough\u{0020}to\u{0020}achieve\u{0020}it...\u{0020}Seriously,\u{0020}why\u{0020}do\u{0020}I\u{0020}keep\u{0020}running\u{0020}into\u{0020}people\u{0020}like\u{0020}that?", "0", "0", "0", "0", "0", "cv_teberda_sw_10", "0", "0"},
