[4102200201] = {4102200201, 11022002, 2, 2, "0", "0", "Pfft...\u{0020}From\u{0020}this\u{0020}angle,\u{0020}Navigator\u{0020}looks\u{0020}like\u{0020}a\u{0020}little\u{0020}bug!\u{0020}So\u{0020}adorable.", "おっかし～。こっから見るとナビくん、蟲みたいで可愛いじゃん。", "0", "0", "0", "0", "cv_wangnv_2", "0", "0"},
[4102200202] = {4102200202, 11022002, 3, 3, "0", "0", "Oh\u{0020}hey.\u{0020}Long\u{0020}time\u{0020}no\u{0020}see.\u{0020}I'm\u{0020}Her\u{0020}Majesty.\u{0020}What?\u{0020}Why\u{0020}am\u{0020}I\u{0020}here?\u{0020}Don't\u{0020}sweat\u{0020}the\u{0020}small\u{0020}details!", "おっひさー、王女だよー。え……？　なんでここにいるのかって？　細かいことはどうでもいいじゃん！", "0", "0", "0", "0", "cv_wangnv_3", "0", "0"},
[4102200203] = {4102200203, 11022002, 91, 4, "0", "idle", "Mmm...\u{0020}I'm\u{0020}like\u{0020}a\u{0020}difficult\u{0020}squatter\u{0020}living\u{0020}in\u{0020}Navigator's\u{0020}life.\u{0020}Sounds\u{0020}kinda\u{0020}intimate,\u{0020}doesn't\u{0020}it?", "ふむふむ……追い出せない同居人みたいにナビくんから離れない……って聞くとちょっとエッチじゃない？", "0", "0", "0", "0", "cv_wangnv_4", "0", "idle,idle"},
[4102200204] = {4102200204, 11022002, 91, 4, "0", "idle", "So\u{0020}many\u{0020}familiar\u{0020}faces...\u{0020}Wait,\u{0020}was\u{0020}that\u{0020}Skadi-chan\u{0020}just\u{0020}now?\u{0020}\u{0020}Aww!\u{0020}Too\u{0020}bad!\u{0020}I\u{0020}really\u{0020}wanted\u{0020}to\u{0020}say\u{0020}hi!", "ちらほらと見覚えのある顔が……あっ今通り過ぎたのってすかきちじゃん！　やばー！　挨拶しとけば良かったぁ！", "0", "0", "0", "0", "cv_wangnv_5", "0", "idle,idle"},
[4102200205] = {4102200205, 11022002, 91, 4, "0", "idle", "Wow...\u{0020}you\u{0020}deal\u{0020}with\u{0020}this\u{0020}much\u{0020}paperwork\u{0020}daily?\u{0020}That's\u{0020}a\u{0020}headache.\u{0020}\u{0020}Just\u{0020}looking\u{0020}at\u{0020}these\u{0020}files\u{0020}makes\u{0020}me\u{0020}sleepy.\u{0020}So\u{0020}boring!", "えぇ……普段からこんなに書類仕事があるのー？　大変だねー。同情しちゃうよ。あーしなら白目剝いちゃうね。だってマジ面白くなさそうだしー！", "0", "0", "0", "0", "cv_wangnv_6", "0", "idle,idle"},
[4102200206] = {4102200206, 11022002, 92, 5, "15_1_0_0.8", "touch1", "So\u{0020}this\u{0020}is\u{0020}AEGIS...\u{0020}Alright!\u{0020}I've\u{0020}made\u{0020}up\u{0020}my\u{0020}mind!\u{0020}My\u{0020}new\u{0020}goal\u{0020}is\u{0020}to\u{0020}be\u{0020}AEGIS'\u{0020}number\u{0020}one!", "ここがアイギスかぁ……よし決めた！　あーしの次の目標はアイギスのトップになること！", "0", "0", "0", "0", "cv_wangnv_7", "0", "touch1,touch1"},
[4102200207] = {4102200207, 11022002, 92, 5, "15_1_0_0.8", "touch1", "When\u{0020}are\u{0020}you\u{0020}taking\u{0020}me\u{0020}to\u{0020}fight\u{0020}giant\u{0020}monsters?\u{0020}My\u{0020}heart's\u{0020}bursting\u{0020}with\u{0020}the\u{0020}desire\u{0020}to\u{0020}protect\u{0020}everyone!\u{0020}...What\u{0020}do\u{0020}you\u{0020}mean\u{0020}I\u{0020}just\u{0020}want\u{0020}to\u{0020}play?\u{0020}\u{0020}Well,\u{0020}as\u{0020}long\u{0020}as\u{0020}the\u{0020}enemy\u{0020}is\u{0020}down.", "そろそろあーしも巨大怪獣と戦うのに連れてってよー。みんなを守りたいっていう気持ちが抑えられなくてさぁ……暴れたいだけだろって？結果オーライならいいっしょ～", "0", "0", "0", "0", "cv_wangnv_8", "0", "touch1,touch1"},
[4102200208] = {4102200208, 11022002, 92, 5, "15_2_0_0.8", "touch2", "Psst...\u{0020}when\u{0020}nobody's\u{0020}around,\u{0020}you\u{0020}can\u{0020}call\u{0020}me\u{0020}Skadi.\u{0020}Gives\u{0020}you\u{0020}that\u{0020}forbidden\u{0020}thrill,\u{0020}right?\u{0020}Hehe,\u{0020}kinda\u{0020}addicting.", "……誰もいないとこでなら、あーしのことこっそりスカディって呼んでいいよ？　へへ……なんかイケないことしてるみたいでクセになるかもね。", "0", "0", "0", "0", "cv_wangnv_9", "0", "touch2,touch2"},
[4102200209] = {4102200209, 11022002, 92, 5, "15_2_0_0.8", "touch2", "Navigator...\u{0020}which\u{0020}Skadi\u{0020}do\u{0020}you\u{0020}prefer?\u{0020}The\u{0020}one\u{0020}still\u{0020}growing,\u{0020}the\u{0020}dignified\u{0020}one,\u{0020}or...\u{0020}me?", "ナビくんは……どのスカディの方が好き？　成長途中のか、威厳に満ちてるのか、それとも……あーしが好き？", "0", "0", "0", "0", "cv_wangnv_10", "0", "touch2,touch2"},
[4102200210] = {4102200210, 11022002, 92, 5, "15_2_0_0.8", "touch2", "Let's\u{0020}be\u{0020}honest...\u{0020}you\u{0020}should\u{0020}like\u{0020}me\u{0020}best.", "知ってるよ……ナビくんはあーしのことが好きなんだってこと！", "0", "0", "0", "0", "cv_wangnv_11", "0", "touch2,touch2"},
