[4102200229] = {4102200229, 11022002, 32, 24, "0", "0", "Great!\u{0020}Correct!\u{0020}Your\u{0020}reward\u{0020}is\u{0020}some\u{0020}quality\u{0020}one-on-one\u{0020}time\u{0020}with\u{0020}me\u{0020}on\u{0020}the\u{0020}battlefield.", "はい、良くできましたー！　ご褒美に二人きりの時間をあげるね……さ、二人で戦場に行くよー！", "0", "0", "0", "0", "cv_wangnv_32", "0", "0"},
[4102200230] = {4102200230, 11022002, 33, 25, "0", "0", "Okay!\u{0020}Your\u{0020}punishment\u{0020}is\u{0020}going\u{0020}back\u{0020}into\u{0020}battle\u{0020}with\u{0020}me.\u{0020}Our\u{0020}special\u{0020}alone\u{0020}time!", "オッケー、罰としてもう一回戦場に付き合って貰うよー。ここからはあーしとナビくん、二人の時間だからね。", "0", "0", "0", "0", "cv_wangnv_33", "0", "0"},
