[4102200235] = {4102200235, 11022002, 38, 30, "0", "0", "Whoa,\u{0020}you\u{0020}can\u{0020}just\u{0020}call\u{0020}in\u{0020}other\u{0020}Drivers\u{0020}like\u{0020}it's\u{0020}nothing?\u{0020}Must\u{0020}be\u{0020}nice\u{0020}having\u{0020}that\u{0020}kinda\u{0020}pull.", "ナビくんって結構偉いんだねー。他のドライバーを自由に募集できるなんて。", "0", "0", "0", "0", "cv_wangnv_38", "0", "0"},
