[423826] = {423826, 12038, 27, 20, "0", "0", "As\u{0020}the\u{0020}district\u{0020}manager,\u{0020}I\u{0020}must\u{0020}pay\u{0020}proper\u{0020}attention\u{0020}to\u{0020}my\u{0020}image.", "身為城區管理人，必須注重形象管理才行。", "0", "0", "0", "0", "cv_rosalind_sw_27", "0", "0"},
[423827] = {423827, 12038, 28, 21, "0", "0", "It\u{0020}isn't\u{0020}proper\u{0020}etiquette\u{0020}to\u{0020}keep\u{0020}a\u{0020}noble\u{0020}lady\u{0020}waiting\u{0020}for\u{0020}too\u{0020}long,\u{0020}you\u{0020}know?", "讓一位貴族淑女等太久可不符合禮儀哦？", "0", "0", "0", "0", "cv_rosalind_sw_28", "0", "0"},
[423828] = {423828, 12038, 29, 21, "0", "0", "I\u{0020}specially\u{0020}grant\u{0020}you...\u{0020}the\u{0020}privilege\u{0020}of\u{0020}being\u{0020}alone\u{0020}with\u{0020}this\u{0020}young\u{0020}lady\u{0020}on\u{0020}an\u{0020}occasion\u{0020}like\u{0020}this.", "特別賜予你……在這種場合與本小姐獨處的權利。", "0", "0", "0", "0", "cv_rosalind_sw_29", "0", "0"},
