[423830] = {423830, 12038, 31, 23, "0", "0", "Even\u{0020}after\u{0020}all\u{0020}this\u{0020}time,\u{0020}this\u{0020}young\u{0020}lady's\u{0020}refinement\u{0020}is\u{0020}still\u{0020}obvious\u{0020}at\u{0020}a\u{0020}glance,\u{0020}isn't\u{0020}it?", "就算時過境遷，本小姐的氣質還是一目了然吧？", "0", "0", "0", "0", "cv_rosalind_sw_31", "0", "0"},
[423831] = {423831, 12038, 32, 24, "0", "0", "Mm,\u{0020}just\u{0020}as\u{0020}expected\u{0020}of\u{0020}the\u{0020}Navigator\u{0020}this\u{0020}young\u{0020}lady\u{0020}recognizes.", "嗯，不愧是本小姐認可的領航。", "0", "0", "0", "0", "cv_rosalind_sw_32", "0", "0"},
[423832] = {423832, 12038, 33, 25, "0", "0", "This\u{0020}young\u{0020}lady\u{0020}has\u{0020}always\u{0020}been\u{0020}generous!\u{0020}...I'm\u{0020}just\u{0020}a\u{0020}tiny\u{0020}bit\u{0020}disappointed,\u{0020}that's\u{0020}all.\u{0020}Just\u{0020}a\u{0020}tiny\u{0020}bit.", "本小姐一向寬宏大量！……只是，稍微有一點點失落哦，稍微有一點。", "0", "0", "0", "0", "cv_rosalind_sw_33", "0", "0"},
[423833] = {423833, 12038, 34, 26, "0", "0", "You're\u{0020}here,\u{0020}Navigator.\u{0020}Let's\u{0020}plan\u{0020}the\u{0020}perfect\u{0020}vacation\u{0020}together.", "你來了，領航。一起規劃出一個完美的假期吧。", "0", "0", "0", "0", "cv_rosalind_sw_34", "0", "0"},
[423834] = {423834, 12038, 35, 27, "0", "0", "It's\u{0020}merely\u{0020}an\u{0020}ordinary\u{0020}battlefield.\u{0020}Leave\u{0020}it\u{0020}to\u{0020}me.", "尋常的戰場而已，交給我吧。", "0", "0", "0", "0", "cv_rosalind_sw_35", "0", "0"},
[423835] = {423835, 12038, 36, 28, "0", "0", "Allow\u{0020}this\u{0020}young\u{0020}lady\u{0020}to\u{0020}show\u{0020}them\u{0020}what\u{0020}it\u{0020}means\u{0020}to\u{0020}set\u{0020}an\u{0020}example.", "讓本小姐教她們何為表率吧。", "0", "0", "0", "0", "cv_rosalind_sw_36", "0", "0"},
[423836] = {423836, 12038, 37, 29, "0", "0", "What\u{0020}a\u{0020}splendid\u{0020}roster.", "真是華麗的人員名冊。", "0", "0", "0", "0", "cv_rosalind_sw_37", "0", "0"},
[423837] = {423837, 12038, 38, 30, "0", "0", "Let\u{0020}this\u{0020}young\u{0020}lady\u{0020}see\u{0020}how\u{0020}good\u{0020}your\u{0020}eye\u{0020}for\u{0020}personnel\u{0020}really\u{0020}is.", "讓本小姐看看你用人的眼光吧。", "0", "0", "0", "0", "cv_rosalind_sw_38", "0", "0"},
[423838] = {423838, 12038, 39, 31, "0", "0", "The\u{0020}right\u{0020}facilities\u{0020}and\u{0020}equipment\u{0020}are\u{0020}both\u{0020}important.\u{0020}This\u{0020}young\u{0020}lady\u{0020}can\u{0020}help\u{0020}you\u{0020}check\u{0020}them.", "合適的設施與裝備都是很重要的，本小姐可以替你把關。", "0", "0", "0", "0", "cv_rosalind_sw_39", "0", "0"},
[423839] = {423839, 12038, 40, 32, "0", "0", "If\u{0020}we\u{0020}draw\u{0020}on\u{0020}the\u{0020}funds\u{0020}in\u{0020}moderation...", "如果有限度地調用一下資金的話……", "0", "0", "0", "0", "cv_rosalind_sw_40", "0", "0"},
[423840] = {423840, 12038, 41, 33, "0", "0", "Hehe,\u{0020}what\u{0020}a\u{0020}nostalgic\u{0020}face.", "呵呵，真是一張令人懷念的臉。", "0", "0", "0", "0", "cv_rosalind_sw_41", "0", "0"},
[423841] = {423841, 12038, 42, 34, "0", "0", "One\u{0020}must\u{0020}pay\u{0020}attention\u{0020}even\u{0020}to\u{0020}the\u{0020}smallest\u{0020}details.", "細節之處也要注意好。", "0", "0", "0", "0", "cv_rosalind_sw_42", "0", "0"},
[423842] = {423842, 12038, 43, 35, "0", "0", "Any\u{0020}message\u{0020}could\u{0020}be\u{0020}important,\u{0020}so\u{0020}none\u{0020}can\u{0020}be\u{0020}neglected...\u{0020}especially\u{0020}those\u{0020}from\u{0020}colleagues\u{0020}and\u{0020}subordinates!", "任何一封聯絡都可能很重要，不能怠慢……尤其是那些來自同僚下屬的！", "0", "0", "0", "0", "cv_rosalind_sw_43", "0", "0"},
